-- Service-only enrichment after the existing manager channel has established
-- its exact workflow/generation/approval/manifest. No cross-auth fetch exists.
create or replace function public.timesheet_correction_manager_summary_v1(
  p_workflow_id uuid,p_workflow_generation integer,p_approval_request_id uuid,p_manifest_sha256 text
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_workflow public.candidate_submission_workflows%rowtype;
  v_approval public.candidate_approval_requests%rowtype; v_hours public.candidate_submission_components%rowtype;
  v_render_input jsonb; v_schedule jsonb;
begin
  select w.* into v_workflow from public.candidate_submission_workflows w
    where w.id=p_workflow_id and w.generation=p_workflow_generation;
  select request.* into v_request from private.timesheet_correction_requests request
    where request.origin in('SIGNED_TIMESHEET_CORRECTION','AGENCY_INVOICE_CORRECTION') and request.state='WAITING'
      and request.replacement_timesheet_id=v_workflow.target_timesheet_id
      and request.candidate_id=v_workflow.candidate_id;
  if not found then return null; end if;
  select a.* into v_approval from public.candidate_approval_requests a
    where a.id=p_approval_request_id and a.workflow_id=p_workflow_id and a.workflow_generation=p_workflow_generation
      and a.state in('PENDING','APPROVED') and a.review_manifest_sha256=v_workflow.review_manifest_sha256
      and encode(a.review_manifest_sha256,'hex')=p_manifest_sha256;
  select c.* into v_hours from public.candidate_submission_components c
    where c.id=v_approval.manager_review_timesheet_component_id and c.workflow_id=p_workflow_id
      and c.workflow_generation=p_workflow_generation and c.component_kind='HOURS_TIMESHEET'
      and c.required and c.state='IMMUTABLE' and c.review_render_state='READY'
      and c.review_content_sha256=v_approval.manager_review_timesheet_sha256;
  if v_approval.id is null or v_hours.id is null
    or v_workflow.review_manifest_sha256 is null or v_workflow.immutable_submission_sha256 is null
    or private._candidate_sha256_jsonb_v1(v_workflow.immutable_submission_json) is distinct from v_workflow.immutable_submission_sha256 then
    raise exception 'CORRECTION_MANAGER_REVIEW_WITNESS_CHANGED' using errcode='40001';
  end if;
  v_render_input:=private._candidate_component_render_input_v1(p_workflow_id,p_workflow_generation,v_hours.id);
  if v_render_input->>'render_input_sha256' is distinct from encode(v_hours.review_render_input_sha256,'hex') then
    raise exception 'CORRECTION_MANAGER_REVIEW_INPUT_CHANGED' using errcode='40001';
  end if;
  v_schedule:=coalesce(v_workflow.immutable_submission_json#>'{timesheet_patch_json,actual_schedule_json}',
    v_workflow.immutable_submission_json#>'{hours_submission,timesheet_patch_json,actual_schedule_json}');
  if jsonb_typeof(v_schedule) is distinct from 'array' then
    raise exception 'CORRECTION_MANAGER_REVIEW_PROPOSAL_UNPROVED' using errcode='55000';
  end if;
  return jsonb_build_object('schema_version',1,'request_id',v_request.id,'correction_id',v_request.correction_id,
    'reason',v_request.reason,'original_schedule',v_request.frozen_original_json->'schedule',
    'reviewed_schedule',v_schedule,'review_witness',jsonb_build_object('workflow_id',p_workflow_id,
      'workflow_generation',p_workflow_generation,'approval_request_id',p_approval_request_id,
      'manifest_sha256',p_manifest_sha256,'hours_component_id',v_hours.id,
      'review_render_input_sha256',encode(v_hours.review_render_input_sha256,'hex'),
      'review_content_sha256',encode(v_hours.review_content_sha256,'hex')));
end;
$function$;

-- Adjacent request authority; no widening of the import correction classifier.
create or replace function private.timesheet_correction_whole_transition_v1(
  p_timesheet_id uuid,p_action text,p_actor_user_id uuid,p_expected_chain_fingerprint text,p_lock_rows boolean,p_max_members integer
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_request private.timesheet_correction_requests%rowtype; v_chain jsonb; v_ids uuid[];
  v_rows jsonb; v_items jsonb; v_authorised integer; v_unauthorised integer; v_ready integer; v_paid integer; v_invoiced integer;
  v_action text:=upper(btrim(p_action)); v_errors jsonb:='[]'::jsonb; v_include_original boolean:=false; v_count integer;
begin
  select request.* into v_request from private.timesheet_correction_requests request
    where p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
      and request.correction_id=(select t.correction_id from public.timesheets t where t.timesheet_id=p_timesheet_id);
  if not found then return null; end if;
  if private.timesheet_correction_actor_allowed_v1(p_actor_user_id) is distinct from true then
    raise exception 'CORRECTION_ACTOR_NOT_ALLOWED' using errcode='42501';
  end if;
  if v_action not in('AUTHORISE','UNAUTHORISE','PROCESS','UNPROCESS') then
    raise exception 'CORRECTION_TRANSITION_ACTION_INVALID' using errcode='22023';
  end if;
  if p_lock_rows then
    perform 1 from public.invoices i where i.id in(v_request.original_invoice_id,v_request.return_invoice_id) order by i.id for update;
    perform pg_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_request.root_timesheet_id::text,21072026));
    select request.* into v_request from private.timesheet_correction_requests request where request.id=v_request.id for update;
  end if;
  if v_request.state<>'APPLIED' then
    return jsonb_build_object('ok',true,'valid',false,'action_ready',false,'correction_id',v_request.correction_id,
      'expected_member_count',2,'errors',jsonb_build_array(jsonb_build_object('code','CORRECTION_REQUEST_NOT_APPLIED')));
  end if;
  v_include_original:=v_action='AUTHORISE'
    and coalesce((v_request.terminal_receipt_json->>'original_authorisation_required')::boolean,false)
    and exists(select 1 from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id
      and t.authorised_at_server is null);
  v_ids:=array[v_request.reversal_timesheet_id,v_request.replacement_timesheet_id];
  if v_include_original then v_ids:=array_append(v_ids,v_request.reversed_timesheet_id); end if;
  v_count:=cardinality(v_ids);
  if v_count>p_max_members then raise exception 'CORRECTION_TRANSITION_MEMBER_LIMIT_INVALID' using errcode='22023'; end if;
  if p_lock_rows then
    perform 1 from public.candidate_submission_workflows w where w.id in(select t.candidate_workflow_id from public.timesheets t
      where t.timesheet_id=any(v_ids)) order by w.id for update;
    perform 1 from public.timesheets t where t.timesheet_id=any(v_ids) order by t.timesheet_id for update;
    perform 1 from public.timesheets_financials tf where tf.timesheet_id=any(v_ids) and tf.is_current
      order by tf.timesheet_id,tf.id for update;
  end if;
  v_chain:=public.timesheet_correction_chain_scope_v1(p_timesheet_id,false,32,p_max_members);
  if (v_chain->>'valid')::boolean is distinct from true
    or (p_expected_chain_fingerprint is not null and p_expected_chain_fingerprint is distinct from v_chain->>'chain_fingerprint') then
    raise exception 'CORRECTION_TRANSITION_CHAIN_STALE' using errcode='40001';
  end if;
  select count(*) filter(where t.authorised_at_server is not null and tf.authorised_at_utc is not null),
    count(*) filter(where t.authorised_at_server is null and tf.authorised_at_utc is null),
    count(*) filter(where tf.id is not null and not coalesce(tf.is_stale,true) and tf.candidate_id=v_request.candidate_id
      and tf.client_id=v_request.client_id and nullif(btrim(tf.pay_method),'') is not null
      and not coalesce(tf.has_rate_issue,true) and not coalesce(tf.has_pay_channel_issue,true)),
    count(*) filter(where tf.paid_at_utc is not null),
    count(*) filter(where tf.locked_by_invoice_id is not null or exists(select 1 from public.invoice_lines l where l.timesheet_id=t.timesheet_id)
      or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
        then tf.invoice_breakdown_json->'segments' else '[]'::jsonb end) s where nullif(s->>'invoice_locked_invoice_id','') is not null)),
    jsonb_agg(jsonb_build_object('timesheet_id',t.timesheet_id,'correction_kind',t.correction_kind,
      'timesheet_authorised',t.authorised_at_server is not null,'tsfin_authorised',tf.authorised_at_utc is not null,
      'tsfin_id',tf.id,'processing_status',tf.processing_status,'policy_ready',not coalesce(tf.is_stale,true)) order by t.timesheet_id),
    jsonb_agg(jsonb_build_object('timesheet_id',t.timesheet_id,'expected_timesheet_id',t.timesheet_id,
      'expected_version',t.version) order by t.timesheet_id)
    into v_authorised,v_unauthorised,v_ready,v_paid,v_invoiced,v_rows,v_items
  from public.timesheets t left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
    where t.timesheet_id=any(v_ids) and t.is_current and t.archived_at_utc is null;
  if jsonb_array_length(coalesce(v_rows,'[]'::jsonb))<>v_count or v_paid<>0 or v_invoiced<>0
    or (v_action='AUTHORISE' and not(v_authorised=v_count or (v_unauthorised=v_count and v_ready=v_count)))
    or (v_action='UNAUTHORISE' and not(v_authorised=v_count or v_unauthorised=v_count)) then
    v_errors:=jsonb_build_array(jsonb_build_object('code','CORRECTION_UNIT_ACTION_STATE_INVALID'));
  end if;
  if v_action in('PROCESS','UNPROCESS') then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','WHOLE_CORRECTION_FINANCE_FROZEN'));
  end if;
  return jsonb_build_object('ok',true,'valid',jsonb_array_length(v_errors)=0,'action',v_action,
    'action_ready',jsonb_array_length(v_errors)=0,'root_timesheet_id',v_request.root_timesheet_id,
    'correction_id',v_request.correction_id,'request_id',v_request.id,'correction_shape','WHOLE_REVERSAL_REPLACEMENT',
    'expected_member_count',v_count,'pair_timesheet_ids',to_jsonb(v_ids),'pair_rows',coalesce(v_rows,'[]'::jsonb),
    'transition_items',coalesce(v_items,'[]'::jsonb),'chain_fingerprint',v_chain->>'chain_fingerprint',
    'authorised_count',v_authorised,'unauthorised_count',v_unauthorised,'ready_count',v_ready,
    'paid_count',v_paid,'invoice_lined_count',v_invoiced,'errors',v_errors,
    'correction_financials_policy_envelope',null,'correction_financials_policy_envelope_fingerprint',null,
    'required_backend_rpc',case when v_action='AUTHORISE' then 'timesheet_authorise_bulk_atomic' else 'timesheet_unauthorise_bulk_atomic' end);
end;
$function$;

create or replace function public.timesheet_correction_chain_scope_v1(
  p_timesheet_id uuid,
  p_lock_rows boolean default false,
  p_max_depth integer default 32,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'extensions', 'pg_temp'
as $function$
declare
  v_root_id uuid;
  v_member_ids uuid[] := array[]::uuid[];
  v_member_count integer := 0;
  v_cycle boolean := false;
  v_truncated boolean := false;
  v_units jsonb := '[]'::jsonb;
  v_members jsonb := '[]'::jsonb;
  v_errors jsonb := '[]'::jsonb;
  v_latest_positive uuid;
  v_fingerprint_payload jsonb;
  v_chain_fingerprint text;
  v_requested_unit jsonb;
  v_requested_operation_id text;
begin
  if p_timesheet_id is null then
    raise exception 'CORRECTION_CHAIN_TIMESHEET_ID_REQUIRED' using errcode='22023';
  end if;
  if p_max_depth < 1 or p_max_depth > 32 then
    raise exception 'CORRECTION_CHAIN_MAX_DEPTH_OUT_OF_RANGE' using errcode='22023';
  end if;
  if p_max_members < 1 or p_max_members > 100 then
    raise exception 'CORRECTION_CHAIN_MAX_MEMBERS_OUT_OF_RANGE' using errcode='22023';
  end if;
  if not exists (select 1 from public.timesheets where timesheet_id=p_timesheet_id) then
    raise exception 'CORRECTION_CHAIN_TIMESHEET_NOT_FOUND' using errcode='P0002';
  end if;

  with recursive ancestors as (
    select ts.timesheet_id, ts.parent_timesheet_id, 0 depth,
           array[ts.timesheet_id]::uuid[] path, false cycle
    from public.timesheets ts where ts.timesheet_id=p_timesheet_id
    union all
    select p.timesheet_id, p.parent_timesheet_id, a.depth+1,
           a.path||p.timesheet_id, p.timesheet_id=any(a.path)
    from ancestors a
    join public.timesheets p on p.timesheet_id=a.parent_timesheet_id
    where a.parent_timesheet_id is not null and not a.cycle and a.depth<p_max_depth
  )
  select a.timesheet_id,
         coalesce(bool_or(a.cycle) over (),false)
  into v_root_id, v_cycle
  from ancestors a
  order by a.depth desc
  limit 1;

  with recursive descendants as (
    select ts.timesheet_id, ts.parent_timesheet_id, 0 depth,
           array[ts.timesheet_id]::uuid[] path, false cycle
    from public.timesheets ts where ts.timesheet_id=v_root_id
    union all
    select c.timesheet_id, c.parent_timesheet_id, d.depth+1,
           d.path||c.timesheet_id, c.timesheet_id=any(d.path)
    from descendants d
    join public.timesheets c on c.parent_timesheet_id=d.timesheet_id
    where not d.cycle and d.depth<p_max_depth
  ), picked as (
    select distinct d.timesheet_id from descendants d where not d.cycle
  )
  select coalesce(array_agg(p.timesheet_id order by p.timesheet_id),array[]::uuid[]),
         count(*)::integer,
         exists(select 1 from descendants where cycle),
         exists(
           select 1 from public.timesheets child
           join descendants edge on edge.timesheet_id=child.parent_timesheet_id
           where edge.depth=p_max_depth
         )
  into v_member_ids,v_member_count,v_cycle,v_truncated
  from picked p;

  if v_member_count>p_max_members then
    raise exception 'CORRECTION_CHAIN_MEMBER_LIMIT_EXCEEDED'
      using errcode='22023', detail=jsonb_build_object('count',v_member_count,'max',p_max_members)::text;
  end if;
  if p_lock_rows then
    if not pg_try_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_root_id::text,21072026)) then
      raise exception 'CORRECTION_CHAIN_LOCK_BUSY' using errcode='55P03';
    end if;
    perform 1 from public.timesheets ts
    where ts.timesheet_id=any(v_member_ids) order by ts.timesheet_id for update;
  end if;

  with member_rows as (
    select ts.*,
      public._ctms_import_correction_classify_v1(ts.timesheet_id) as class_json,
      case when upper(btrim(coalesce(ts.adjustment_origin,''))) in ('IMPORT_CORRECTION','IMPORT_CANCELLATION')
        then public._ctms_correction_policy_envelope_read_v1(ts.timesheet_id) else null end as envelope
    from public.timesheets ts where ts.timesheet_id=any(v_member_ids)
  ), unit_members as (
    select mr.*,
      mr.envelope#>>'{operation,operation_id}' operation_id,
      mr.envelope->>'correction_chain_id' correction_chain_id,
      case
        when upper(btrim(coalesce(mr.correction_kind,''))) in
          ('CHANGED_HOURS_REVERSAL','CANCELLATION_REVERSAL') then 'REVERSAL'
        when upper(btrim(coalesce(mr.correction_kind,''))) in
          ('CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT') then 'REPLACEMENT'
        else 'INVALID'
      end member_role
    from member_rows mr
    where coalesce((mr.class_json->>'is_import_authoritative_correction')::boolean,false)=true
  ), unit_rows as (
    select operation_id,correction_chain_id,
      min(correction_id) correction_id,
      count(distinct correction_id)::integer correction_id_count,
      count(*) filter (where member_role='REVERSAL')::integer reversal_count,
      count(*) filter (where member_role='REPLACEMENT')::integer replacement_count,
      count(*)::integer actual_member_count,
      jsonb_agg(member_role order by case member_role when 'REVERSAL' then 1 when 'REPLACEMENT' then 2 else 3 end) actual_member_roles,
      array_agg(timesheet_id order by timesheet_id) member_ids,
      count(distinct envelope->>'envelope_fingerprint')::integer envelope_count,
      count(distinct envelope->>'root_timesheet_id')::integer envelope_root_count,
      min(envelope->>'envelope_fingerprint') envelope_fingerprint,
      min(envelope::text)::jsonb envelope
    from unit_members
    where nullif(btrim(coalesce(operation_id,'')),'') is not null
      and nullif(btrim(coalesce(correction_chain_id,'')),'') is not null
    group by operation_id,correction_chain_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'correction_id',u.correction_id,
    'correction_operation_id',u.operation_id,
    'correction_chain_id',u.correction_chain_id,
    'correction_shape',u.envelope->>'correction_shape',
    'expected_member_count',(u.envelope->>'expected_member_count')::integer,
    'expected_member_roles',u.envelope->'expected_member_roles',
    'actual_member_count',u.actual_member_count,
    'actual_member_roles',u.actual_member_roles,
    'member_ids',to_jsonb(u.member_ids),
    'reversal_count',u.reversal_count,
    'replacement_count',u.replacement_count,
    'envelope_fingerprint',u.envelope_fingerprint,
    'policy_envelope',u.envelope,
    'valid',u.operation_id is not null
      and u.correction_chain_id is not null
      and u.correction_id_count=1
      and u.envelope_count=1
      and u.envelope_root_count=1
      and u.envelope->>'root_timesheet_id' is not distinct from v_root_id::text
      and u.envelope->>'correction_shape' in ('REVERSAL_ONLY','REVERSAL_REPLACEMENT')
      and u.actual_member_count=(u.envelope->>'expected_member_count')::integer
      and u.actual_member_roles=u.envelope->'expected_member_roles'
      and u.reversal_count=1
      and u.replacement_count=case when u.envelope->>'correction_shape'='REVERSAL_ONLY' then 0 else 1 end
  ) order by u.operation_id),'[]'::jsonb)
  into v_units
  from unit_rows u;

  -- WHOLE requests are adjacent units; immutable request ownership replaces
  -- import policy envelopes only for this exact purpose.
  select v_units||coalesce(jsonb_agg(jsonb_build_object(
    'correction_id',request.correction_id,'correction_operation_id',request.id,
    'correction_chain_id',request.root_timesheet_id,'request_id',request.id,
    'correction_shape','WHOLE_REVERSAL_REPLACEMENT','expected_member_count',2,
    'expected_member_roles',jsonb_build_array('REVERSAL','REPLACEMENT'),
    'actual_member_count',(select count(*) from public.timesheets member where member.timesheet_id
      in(request.reversal_timesheet_id,request.replacement_timesheet_id) and member.is_current
      and member.correction_id=request.correction_id and member.parent_timesheet_id=request.root_timesheet_id),
    'member_ids',jsonb_build_array(request.reversal_timesheet_id,request.replacement_timesheet_id),
    'valid',exists(select 1 from public.timesheets r join public.timesheets p on p.timesheet_id=request.replacement_timesheet_id
      where r.timesheet_id=request.reversal_timesheet_id and r.correction_kind='WHOLE_TIMESHEET_REVERSAL'
      and p.correction_kind='WHOLE_TIMESHEET_REPLACEMENT' and r.correction_id=request.correction_id
      and p.correction_id=request.correction_id and r.parent_timesheet_id=request.root_timesheet_id
      and p.parent_timesheet_id=request.root_timesheet_id and r.is_current and p.is_current)
  ) order by request.created_at_utc,request.id),'[]'::jsonb) into v_units
  from private.timesheet_correction_requests request where request.root_timesheet_id=v_root_id and request.state='APPLIED';

  select coalesce(jsonb_agg(jsonb_build_object(
    'timesheet_id',ts.timesheet_id,
    'parent_timesheet_id',ts.parent_timesheet_id,
    'booking_id',ts.booking_id,
    'is_current',ts.is_current,
    'status',ts.status,
    'correction_id',ts.correction_id,
    'correction_kind',ts.correction_kind,
    'adjustment_origin',ts.adjustment_origin,
    'policy_envelope_fingerprint',coalesce(
      ts.candidate_hint_text#>>'{correction_financials_policy_envelope,envelope_fingerprint}',
      tf.policy_snapshot_json#>>'{correction_financials_policy_envelope,envelope_fingerprint}'
    ),
    'current_tsfin_id',tf.id,
    'processing_status',tf.processing_status,
    'paid_at_utc',tf.paid_at_utc,
    'locked_by_invoice_id',tf.locked_by_invoice_id
  ) order by ts.created_at,ts.timesheet_id),'[]'::jsonb)
  into v_members
  from public.timesheets ts
  left join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
  where ts.timesheet_id=any(v_member_ids);

  if v_cycle then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_CHAIN_CYCLE')); end if;
  if v_truncated then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_CHAIN_DEPTH_EXCEEDED')); end if;
  if exists(select 1 from jsonb_array_elements(v_units) u where coalesce((u->>'valid')::boolean,false)=false) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_UNIT_INVALID'));
  end if;
  if exists (
    select 1
    from public.timesheets ts
    where ts.timesheet_id=any(v_member_ids)
      and upper(btrim(coalesce(ts.adjustment_origin,''))) in ('IMPORT_CORRECTION','IMPORT_CANCELLATION')
      and not coalesce((public._ctms_import_correction_classify_v1(ts.timesheet_id)->>'is_import_authoritative_correction')::boolean,false)
  ) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_MEMBER_CONTRACT_INVALID'));
  end if;

  select ts.timesheet_id into v_latest_positive
  from public.timesheets ts
  where ts.timesheet_id=any(v_member_ids)
    and (
      ts.timesheet_id=v_root_id
      or upper(btrim(coalesce(ts.correction_kind,''))) in ('CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
      or (ts.correction_kind='WHOLE_TIMESHEET_REPLACEMENT' and exists(select 1 from private.timesheet_correction_requests request
        where request.replacement_timesheet_id=ts.timesheet_id and request.state='APPLIED'))
    )
  order by ts.created_at desc,ts.timesheet_id desc limit 1;

  if coalesce((public._ctms_import_correction_classify_v1(p_timesheet_id)->>'is_import_authoritative_correction')::boolean,false) then
    v_requested_operation_id:=public._ctms_correction_policy_envelope_read_v1(p_timesheet_id)#>>'{operation,operation_id}';
    select u into v_requested_unit
    from jsonb_array_elements(v_units) u
    where u->>'correction_operation_id'=v_requested_operation_id
    limit 1;
  end if;

  if exists(select 1 from private.timesheet_correction_requests request
    where request.state='APPLIED' and p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)) then
    select u into v_requested_unit from jsonb_array_elements(v_units) u
      where u->>'request_id'=(select request.id::text from private.timesheet_correction_requests request
        where request.state='APPLIED' and p_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id));
  end if;

  v_fingerprint_payload:=jsonb_build_object(
    'root_timesheet_id',v_root_id,'member_ids',to_jsonb(v_member_ids),
    'correction_units',v_units,'latest_positive_timesheet_id',v_latest_positive
  );
  v_chain_fingerprint:=encode(extensions.digest(convert_to(v_fingerprint_payload::text,'UTF8'),'sha256'::text),'hex');

  return jsonb_build_object(
    'ok',jsonb_array_length(v_errors)=0,
    'valid',jsonb_array_length(v_errors)=0,
    'requested_timesheet_id',p_timesheet_id,
    'root_timesheet_id',v_root_id,
    'latest_positive_timesheet_id',v_latest_positive,
    'member_count',v_member_count,'member_ids',to_jsonb(v_member_ids),
    'member_timesheet_ids',to_jsonb(v_member_ids),'members',v_members,
    'correction_units',v_units,'pairs',v_units,'requested_correction_unit',v_requested_unit,
    'correction_shape',v_requested_unit->>'correction_shape',
    'correction_financials_policy_required',v_requested_unit->'policy_envelope' is not null,
    'correction_financials_policy_envelope_required',v_requested_unit->'policy_envelope' is not null,
    'correction_financials_policy_envelope',v_requested_unit->'policy_envelope',
    'correction_financials_policy_envelope_fingerprint',v_requested_unit->>'envelope_fingerprint',
    'chain_fingerprint',v_chain_fingerprint,'errors',v_errors
  );
end;
$function$;

create or replace function public.timesheet_correction_pair_transition_v1(
  p_timesheet_id uuid,
  p_action text,
  p_actor_user_id uuid,
  p_operation_id uuid default null,
  p_expected_chain_fingerprint text default null,
  p_lock_rows boolean default true,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_action text:=upper(btrim(coalesce(p_action,'')));
  v_chain jsonb;
  v_unit jsonb;
  v_envelope jsonb;
  v_ids uuid[]:=array[]::uuid[];
  v_expected_count integer;
  v_rows jsonb:='[]'::jsonb;
  v_items jsonb:='[]'::jsonb;
  v_errors jsonb:='[]'::jsonb;
  v_authorised integer:=0;
  v_unauthorised integer:=0;
  v_ready integer:=0;
  v_processed integer:=0;
  v_unprocessed integer:=0;
  v_paid integer:=0;
  v_invoiced integer:=0;
  v_action_ready boolean:=false;
  v_idempotent boolean:=false;
  v_required_rpc text;
  r record;
  v_leg jsonb;
  v_actual_envelope_fingerprint text;
  v_actual_leg_fingerprint text;
  v_values_match boolean;
begin
  v_unit:=private.timesheet_correction_whole_transition_v1(p_timesheet_id,p_action,p_actor_user_id,
    p_expected_chain_fingerprint,p_lock_rows,p_max_members);
  if v_unit is not null then
    if p_operation_id is not null then raise exception 'WHOLE_CORRECTION_IMPORT_OPERATION_FORBIDDEN' using errcode='22023'; end if;
    return v_unit;
  end if;
  if p_timesheet_id is null or p_actor_user_id is null then
    raise exception 'CORRECTION_TRANSITION_REQUIRED_ARGUMENT_MISSING' using errcode='22023';
  end if;
  if v_action not in ('AUTHORISE','UNAUTHORISE','PROCESS','UNPROCESS') then
    raise exception 'CORRECTION_TRANSITION_ACTION_INVALID' using errcode='22023';
  end if;
  if p_max_members<1 or p_max_members>100 then
    raise exception 'CORRECTION_TRANSITION_MEMBER_LIMIT_INVALID' using errcode='22023';
  end if;
  perform 1 from public.tms_users u where u.id=p_actor_user_id and coalesce(u.is_active,false);
  if not found then raise exception 'CORRECTION_TRANSITION_ACTOR_INVALID' using errcode='42501'; end if;

  if p_operation_id is not null then
    perform 1 from public.import_apply_operations o
    where o.id=p_operation_id and o.actor_user_id=p_actor_user_id
      and o.state in ('PREPARED','SOURCE_COMMITTED_TSFIN_PENDING','FINANCIALISED_PENDING_FINALISATION')
    for update;
    if not found then raise exception 'CORRECTION_TRANSITION_OPERATION_INVALID' using errcode='P0001'; end if;
  end if;

  v_chain:=public.timesheet_correction_chain_scope_v1(p_timesheet_id,p_lock_rows,32,p_max_members);
  if coalesce((v_chain->>'valid')::boolean,false) is not true then
    raise exception 'CORRECTION_TRANSITION_CHAIN_INVALID' using errcode='P0001',detail=v_chain::text;
  end if;
  if nullif(btrim(coalesce(p_expected_chain_fingerprint,'')),'') is not null
     and p_expected_chain_fingerprint is distinct from v_chain->>'chain_fingerprint' then
    raise exception 'CORRECTION_TRANSITION_CHAIN_STALE' using errcode='40001';
  end if;
  v_unit:=v_chain->'requested_correction_unit';
  if jsonb_typeof(v_unit)<>'object' then
    raise exception 'CORRECTION_TRANSITION_UNIT_NOT_FOUND' using errcode='22023';
  end if;
  if coalesce((v_unit->>'valid')::boolean,false) is not true then
    raise exception 'CORRECTION_TRANSITION_UNIT_INVALID' using errcode='P0001',detail=v_unit::text;
  end if;
  v_envelope:=v_unit->'policy_envelope';
  v_expected_count:=(v_unit->>'expected_member_count')::integer;
  select coalesce(array_agg(value::uuid order by value::text),array[]::uuid[])
  into v_ids from jsonb_array_elements_text(v_unit->'member_ids');
  if cardinality(v_ids)<>v_expected_count then
    raise exception 'CORRECTION_TRANSITION_MEMBER_COUNT_MISMATCH' using errcode='P0001';
  end if;

  if p_lock_rows then
    perform 1 from public.timesheets ts where ts.timesheet_id=any(v_ids)
    order by ts.timesheet_id for update;
    perform 1 from public.timesheets_financials tf
    where tf.timesheet_id=any(v_ids) and tf.is_current=true
    order by tf.timesheet_id,tf.id for update;
  end if;

  for r in
    select ts.*,tf.id tsfin_id,tf.processing_status,tf.processed_at_utc,
      tf.authorised_at_utc,tf.is_stale,tf.paid_at_utc,tf.locked_by_invoice_id,
      tf.candidate_id,tf.client_id,tf.pay_method,tf.has_rate_issue,tf.has_pay_channel_issue,
      tf.policy_snapshot_json,tf.rate_source_refs_json,tf.pay_vat_rate_pct_snapshot,
      exists(select 1 from public.invoice_lines il where il.timesheet_id=ts.timesheet_id) invoice_lined
    from public.timesheets ts
    left join public.timesheets_financials tf on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
    where ts.timesheet_id=any(v_ids)
    order by ts.timesheet_id
  loop
    v_leg:=public._ctms_correction_policy_leg_read_v1(r.timesheet_id);
    v_actual_envelope_fingerprint:=coalesce(
      r.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint',
      r.policy_snapshot_json#>>'{correction_financials_policy_envelope,envelope_fingerprint}',
      r.rate_source_refs_json->>'correction_financials_policy_envelope_fingerprint'
    );
    v_actual_leg_fingerprint:=coalesce(
      r.policy_snapshot_json->>'correction_leg_fingerprint',
      r.rate_source_refs_json->>'correction_leg_fingerprint'
    );
    v_values_match:=
      v_actual_envelope_fingerprint is not distinct from v_envelope->>'envelope_fingerprint'
      and v_actual_leg_fingerprint is not distinct from v_leg->>'leg_fingerprint'
      and case when coalesce(r.policy_snapshot_json->>'erni_pct','')~'^-?[0-9]+([.][0-9]+)?$'
        then (r.policy_snapshot_json->>'erni_pct')::numeric is not distinct from (v_leg#>>'{tsfin_policy,erni_pct}')::numeric else false end
      and upper(btrim(coalesce(r.policy_snapshot_json->>'apply_erni_to','')))=upper(btrim(coalesce(v_leg#>>'{tsfin_policy,apply_erni_to}','')))
      and coalesce(r.pay_vat_rate_pct_snapshot,
        case when coalesce(r.policy_snapshot_json->>'pay_vat_rate_pct','')~'^-?[0-9]+([.][0-9]+)?$'
          then (r.policy_snapshot_json->>'pay_vat_rate_pct')::numeric else null end)
        is not distinct from (v_leg#>>'{tsfin_policy,applied_pay_vat_rate_pct}')::numeric
      and coalesce(r.policy_snapshot_json->>'correction_tsfin_policy_fingerprint','')
        is not distinct from v_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
      and coalesce(r.policy_snapshot_json->>'correction_invoice_policy_fingerprint','')
        is not distinct from v_leg#>>'{invoice_policy,invoice_policy_fingerprint}';

    if r.authorised_at_server is not null and r.authorised_at_utc is not null then v_authorised:=v_authorised+1; end if;
    if r.authorised_at_server is null and r.authorised_at_utc is null then v_unauthorised:=v_unauthorised+1; end if;
    if r.tsfin_id is not null and not coalesce(r.is_stale,false)
       and r.candidate_id is not null and r.client_id is not null
       and nullif(btrim(coalesce(r.pay_method,'')),'') is not null
       and not coalesce(r.has_rate_issue,false) and not coalesce(r.has_pay_channel_issue,false)
       and v_values_match then v_ready:=v_ready+1; end if;
    if r.processed_at_utc is not null or r.processing_status in (
      'READY_FOR_HR'::public.ts_fin_processing_status_enum,
      'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum,
      'PENDING_AUTH'::public.ts_fin_processing_status_enum) then v_processed:=v_processed+1; end if;
    if r.processed_at_utc is null and r.processing_status='UNPROCESSED'::public.ts_fin_processing_status_enum then v_unprocessed:=v_unprocessed+1; end if;
    if r.paid_at_utc is not null then v_paid:=v_paid+1; end if;
    if r.invoice_lined or r.locked_by_invoice_id is not null then v_invoiced:=v_invoiced+1; end if;
    if not v_values_match then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_LEG_POLICY_NOT_FROZEN','timesheet_id',r.timesheet_id));
    end if;
    v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
      'timesheet_id',r.timesheet_id,'correction_kind',r.correction_kind,
      'timesheet_authorised',r.authorised_at_server is not null,
      'tsfin_authorised',r.authorised_at_utc is not null,'tsfin_id',r.tsfin_id,
      'processing_status',r.processing_status,'policy_ready',v_values_match,
      'leg_fingerprint',v_leg->>'leg_fingerprint'));
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'timesheet_id',r.timesheet_id,'expected_timesheet_id',r.timesheet_id,
      'expected_version',r.version,
      'expected_policy_envelope_fingerprint',v_envelope->>'envelope_fingerprint',
      'expected_leg_fingerprint',v_leg->>'leg_fingerprint'));
  end loop;

  case v_action
    when 'AUTHORISE' then
      v_idempotent:=v_authorised=v_expected_count;
      v_action_ready:=v_idempotent or (v_unauthorised=v_expected_count and v_ready=v_expected_count);
      v_required_rpc:=case when v_idempotent then null else 'timesheet_authorise_bulk_atomic' end;
    when 'UNAUTHORISE' then
      v_idempotent:=v_unauthorised=v_expected_count;
      v_action_ready:=v_idempotent or v_authorised=v_expected_count;
      v_required_rpc:=case when v_idempotent then null else 'timesheet_unauthorise_bulk_atomic' end;
    when 'PROCESS' then
      v_idempotent:=v_processed=v_expected_count;
      v_action_ready:=v_idempotent or v_unprocessed=v_expected_count;
      v_required_rpc:=case when v_idempotent then null else 'contract_week_manual_upsert_bulk_process_atomic' end;
    when 'UNPROCESS' then
      v_idempotent:=v_unprocessed=v_expected_count;
      v_action_ready:=v_idempotent or v_processed=v_expected_count;
      v_required_rpc:=case when v_idempotent then null else 'contract_week_manual_unprocess_atomic' end;
  end case;
  if not v_action_ready then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','CORRECTION_UNIT_ACTION_STATE_INVALID')); end if;

  return jsonb_build_object(
    'ok',true,'valid',jsonb_array_length(v_errors)=0,'action',v_action,
    'action_ready',v_action_ready and jsonb_array_length(v_errors)=0,'idempotent_state',v_idempotent,
    'operation_id',p_operation_id,'root_timesheet_id',v_chain->>'root_timesheet_id',
    'correction_id',v_unit->>'correction_id','correction_shape',v_unit->>'correction_shape',
    'expected_member_count',v_expected_count,'pair_timesheet_ids',to_jsonb(v_ids),
    'correction_financials_policy_envelope',v_envelope,
    'correction_financials_policy_envelope_fingerprint',v_envelope->>'envelope_fingerprint',
    'chain_fingerprint',v_chain->>'chain_fingerprint','pair_rows',v_rows,
    'transition_items',v_items,'required_backend_rpc',v_required_rpc,
    'authorised_count',v_authorised,'unauthorised_count',v_unauthorised,
    'ready_count',v_ready,'processed_count',v_processed,'unprocessed_count',v_unprocessed,
    'paid_count',v_paid,'invoice_lined_count',v_invoiced,'errors',v_errors);
end;
$function$;

create or replace function public.timesheet_correction_pair_lifecycle_preview_v1(
  p_items jsonb,
  p_action text,
  p_actor_user_id uuid,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','extensions','pg_temp'
as $function$
declare
  v_action text:=upper(btrim(coalesce(p_action,'')));
  v_item jsonb;
  v_id_text text;
  v_id uuid;
  v_class jsonb;
  v_transition jsonb;
  v_group jsonb;
  v_groups jsonb:='[]'::jsonb;
  v_seen text[]:=array[]::text[];
  v_selected_count integer:=0;
  v_affected_count integer:=0;
  v_ordinary_count integer:=0;
  v_valid boolean:=true;
  v_repairable_mixed boolean:=false;
  v_already_target_state boolean:=false;
  v_group_ready boolean:=false;
  v_group_fingerprint text;
  v_members jsonb;
  v_errors jsonb;
begin
  if v_action not in ('AUTHORISE','UNAUTHORISE') then
    raise exception 'CORRECTION_LIFECYCLE_ACTION_INVALID' using errcode='22023';
  end if;
  if p_actor_user_id is null then
    raise exception 'CORRECTION_LIFECYCLE_ACTOR_REQUIRED' using errcode='22023';
  end if;
  if p_max_members<1 or p_max_members>100
     or jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array'
     or jsonb_array_length(coalesce(p_items,'[]'::jsonb))>p_max_members then
    raise exception 'CORRECTION_LIFECYCLE_ITEMS_INVALID' using errcode='22023';
  end if;

  v_selected_count:=jsonb_array_length(coalesce(p_items,'[]'::jsonb));
  for v_item in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb))
  loop
    v_id_text:=nullif(btrim(coalesce(
      v_item->>'timesheet_id',v_item->>'timesheetId',
      v_item->>'current_timesheet_id',v_item->>'currentTimesheetId',
      v_item->>'requested_timesheet_id',v_item->>'requestedTimesheetId',
      case when coalesce(v_item->>'row_key','') like 'timesheet:%'
        then substring(v_item->>'row_key' from 11) end,'')), '');
    if v_id_text is null or v_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_valid:=false;
      v_groups:=v_groups||jsonb_build_array(jsonb_build_object(
        'valid',false,'action_ready',false,'errors',jsonb_build_array(
          jsonb_build_object('code','TIMESHEET_ID_REQUIRED'))));
      continue;
    end if;

    v_id:=v_id_text::uuid;
    v_class:=public._ctms_import_correction_classify_v1(v_id);
    if exists(select 1 from private.timesheet_correction_requests request
      where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
        and request.correction_id=(select t.correction_id from public.timesheets t where t.timesheet_id=v_id)) then
      select jsonb_build_object('is_import_authoritative_correction',true,'correction_id',request.correction_id)
        into v_class from private.timesheet_correction_requests request
        where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id);
    end if;
    if coalesce((v_class->>'is_import_authoritative_correction')::boolean,false) is not true then
      v_ordinary_count:=v_ordinary_count+1;
      continue;
    end if;
    if nullif(v_class->>'correction_id','')=any(v_seen) then continue; end if;
    v_seen:=array_append(v_seen,v_class->>'correction_id');

    v_transition:=public.timesheet_correction_pair_transition_v1(
      v_id,v_action,p_actor_user_id,null::uuid,null::text,false,p_max_members);
    v_errors:=coalesce(v_transition->'errors','[]'::jsonb);
    v_repairable_mixed:=
      coalesce((v_transition->>'expected_member_count')::integer,0)=2
      and coalesce((v_transition->>'authorised_count')::integer,0)>0
      and coalesce((v_transition->>'unauthorised_count')::integer,0)>0
      and coalesce((v_transition->>'authorised_count')::integer,0)
          +coalesce((v_transition->>'unauthorised_count')::integer,0)=2
      and coalesce((v_transition->>'paid_count')::integer,0)=0
      and coalesce((v_transition->>'invoice_lined_count')::integer,0)=0
      and (select count(*)=1 and bool_and(e->>'code'='CORRECTION_UNIT_ACTION_STATE_INVALID')
           from jsonb_array_elements(v_errors) e)
      and (v_action='UNAUTHORISE'
        or coalesce((v_transition->>'ready_count')::integer,0)=2);
    v_already_target_state:=coalesce((v_transition->>'expected_member_count')::integer,0)=2
      and coalesce((v_transition->>'paid_count')::integer,0)=0
      and coalesce((v_transition->>'invoice_lined_count')::integer,0)=0
      and ((v_action='AUTHORISE' and coalesce((v_transition->>'authorised_count')::integer,0)=2)
        or (v_action='UNAUTHORISE' and coalesce((v_transition->>'unauthorised_count')::integer,0)=2));
    v_group_ready:=coalesce((v_transition->>'action_ready')::boolean,false)
      or v_repairable_mixed or v_already_target_state;

    select coalesce(jsonb_agg(
      row_json||jsonb_build_object(
        'signed_hours',jsonb_build_object(
          'day',coalesce(tf.hours_day,0),'night',coalesce(tf.hours_night,0),
          'sat',coalesce(tf.hours_sat,0),'sun',coalesce(tf.hours_sun,0),
          'bh',coalesce(tf.hours_bh,0),
          'total',coalesce(tf.hours_day,0)+coalesce(tf.hours_night,0)+coalesce(tf.hours_sat,0)+coalesce(tf.hours_sun,0)+coalesce(tf.hours_bh,0)),
        'current_state',case when coalesce((row_json->>'timesheet_authorised')::boolean,false)
          and coalesce((row_json->>'tsfin_authorised')::boolean,false) then 'AUTHORISED' else 'UNAUTHORISED' end,
        'resulting_state',case when v_action='AUTHORISE' then 'AUTHORISED' else 'UNAUTHORISED' end)
      order by case row_json->>'correction_kind' when 'CHANGED_HOURS_REVERSAL' then 1 else 2 end),
      '[]'::jsonb)
    into v_members
    from jsonb_array_elements(coalesce(v_transition->'pair_rows','[]'::jsonb)) row_json
    left join public.timesheets_financials tf
      on tf.timesheet_id=nullif(row_json->>'timesheet_id','')::uuid and tf.is_current=true;

    v_group_fingerprint:=public._import_review_hash_v1(concat_ws('|',
      'correction-lifecycle-preview-v1',v_action,v_transition->>'chain_fingerprint',
      v_transition->>'correction_id',v_members::text,v_group_ready));
    v_group:=v_transition||jsonb_build_object(
      'valid',v_group_ready,'action_ready',v_group_ready,
      'repairing_legacy_mixed_state',v_repairable_mixed,
      'already_in_target_state',v_already_target_state,
      'source_system',case
        when exists(select 1 from jsonb_array_elements(v_members) m
          join public.timesheets t on t.timesheet_id=(m->>'timesheet_id')::uuid
          left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current
          where upper(coalesce(
            t.candidate_hint_text#>>'{correction_financials_policy_envelope,classification,source_system}',
            tf.policy_snapshot_json#>>'{correction_financials_policy_envelope,classification,source_system}',
            tf.rate_source_refs_json#>>'{correction_financials_policy_envelope,classification,source_system}',
            case when tf.basis in ('NHSP','NHSP_ADJUSTMENT') then 'NHSP' end,''))='NHSP')
        then 'NHSP' else 'HealthRoster' end,
      'members',v_members,'pair_fingerprint',v_group_fingerprint,
      'errors',case when v_repairable_mixed or v_already_target_state then '[]'::jsonb else v_errors end);
    v_groups:=v_groups||jsonb_build_array(v_group);
    v_affected_count:=v_affected_count+coalesce((v_transition->>'expected_member_count')::integer,0);
    if not v_group_ready then v_valid:=false; end if;
  end loop;

  return jsonb_build_object(
    'ok',true,'valid',v_valid,'action',v_action,
    'selected_count',v_selected_count,
    'ordinary_timesheet_count',v_ordinary_count,
    'correction_pair_count',jsonb_array_length(v_groups),
    'affected_timesheet_count',v_ordinary_count+v_affected_count,
    'groups',v_groups,
    'preview_fingerprint',public._import_review_hash_v1(concat_ws('|',
      'correction-lifecycle-batch-preview-v1',v_action,v_selected_count,v_groups::text)));
end;
$function$;

create or replace function public._ctms_expand_lifecycle_items_v1(
  p_items jsonb,
  p_action text,
  p_actor_user_id uuid,
  p_max_members integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path to 'public', 'extensions', 'pg_temp'
as $function$
declare
  v_action text := upper(btrim(coalesce(p_action, '')));
  v_result jsonb := '[]'::jsonb;
  v_seen_correction_ids text[] := array[]::text[];
  v_item jsonb;
  v_id_text text;
  v_id uuid;
  v_class jsonb;
  v_transition jsonb;
  v_preview jsonb;
  v_group jsonb;
  v_transition_item jsonb;
  v_expected_pair_fingerprint text;
  v_correction_id text;
begin
  if v_action not in ('AUTHORISE', 'UNAUTHORISE') then
    raise exception 'CORRECTION_LIFECYCLE_ACTION_INVALID' using errcode = '22023';
  end if;
  if p_actor_user_id is null then
    raise exception 'CORRECTION_LIFECYCLE_ACTOR_REQUIRED' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) > p_max_members then
    raise exception 'CORRECTION_LIFECYCLE_ITEMS_INVALID' using errcode = '22023';
  end if;

  for v_item in
    select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    v_id_text := nullif(btrim(coalesce(
      v_item ->> 'timesheet_id', v_item ->> 'timesheetId',
      v_item ->> 'current_timesheet_id', v_item ->> 'currentTimesheetId',
      v_item ->> 'requested_timesheet_id', v_item ->> 'requestedTimesheetId',
      case when coalesce(v_item ->> 'row_key', '') like 'timesheet:%'
        then substring(v_item ->> 'row_key' from 11) end,
      ''
    )), '');

    if v_id_text is null
       or v_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_result := v_result || jsonb_build_array(v_item);
      continue;
    end if;

    v_id := v_id_text::uuid;
    if exists(select 1 from private.timesheet_correction_requests request
      where request.state='APPLIED' and request.reversed_timesheet_id=v_id) then
      if v_action='AUTHORISE' and exists(select 1 from private.timesheet_correction_requests request
        where request.state='APPLIED' and request.reversed_timesheet_id=v_id
          and coalesce((request.terminal_receipt_json->>'original_authorisation_required')::boolean,false)
          and exists(select 1 from public.timesheets t where t.timesheet_id=v_id and t.authorised_at_server is null)
          and (request.replacement_timesheet_id=any(public._ctms_payload_timesheet_ids_v1(p_items,p_max_members))
            or request.reversal_timesheet_id=any(public._ctms_payload_timesheet_ids_v1(p_items,p_max_members)))) then
        -- The adjacent WHOLE arm adds this A0 member exactly once. T0-only
        -- ordinary Authorise remains available while the request is WAITING.
        continue;
      end if;
      raise exception 'AGENCY_INVOICE_SUPERSEDED' using errcode='55000';
    end if;
    v_class := public._ctms_import_correction_classify_v1(v_id);
    if exists(select 1 from private.timesheet_correction_requests request
      where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
        and request.correction_id=(select t.correction_id from public.timesheets t where t.timesheet_id=v_id)) then
      select jsonb_build_object('is_import_authoritative_correction',true,'correction_id',request.correction_id)
        into v_class from private.timesheet_correction_requests request
        where v_id in(request.replacement_timesheet_id,request.reversal_timesheet_id);
    end if;
    if coalesce((v_class ->> 'is_import_authoritative_correction')::boolean, false) is not true then
      v_result := v_result || jsonb_build_array(v_item);
      continue;
    end if;

    v_correction_id := nullif(v_class ->> 'correction_id', '');
    if v_correction_id = any(v_seen_correction_ids) then
      continue;
    end if;

    v_preview:=public.timesheet_correction_pair_lifecycle_preview_v1(
      jsonb_build_array(v_item),v_action,p_actor_user_id,p_max_members);
    v_group:=v_preview#>'{groups,0}';
    v_transition:=public.timesheet_correction_pair_transition_v1(
      v_id,v_action,p_actor_user_id,null::uuid,v_group->>'chain_fingerprint',true,p_max_members);
    v_expected_pair_fingerprint:=nullif(btrim(coalesce(
      v_item->>'expected_pair_fingerprint',v_item->>'pair_fingerprint','')),'');
    if v_expected_pair_fingerprint is not null
       and v_expected_pair_fingerprint is distinct from v_group->>'pair_fingerprint' then
      raise exception 'CORRECTION_UNIT_LIFECYCLE_PREVIEW_STALE'
        using errcode='40001',detail=v_group::text;
    end if;
    if coalesce((v_group->>'valid')::boolean,false) is not true
       or coalesce((v_group->>'action_ready')::boolean,false) is not true then
      raise exception 'CORRECTION_UNIT_LIFECYCLE_TRANSITION_BLOCKED'
        using errcode = 'P0001', detail = v_group::text;
    end if;

    v_seen_correction_ids := array_append(v_seen_correction_ids, v_correction_id);
    for v_transition_item in
      select value from jsonb_array_elements(coalesce(v_transition->'transition_items','[]'::jsonb))
    loop
      v_result:=v_result||jsonb_build_array(v_transition_item||jsonb_build_object(
        'lifecycle_group_id','correction:'||v_correction_id,
        'lifecycle_group_size',coalesce((v_transition->>'expected_member_count')::integer,2),
        'pair_fingerprint',v_group->>'pair_fingerprint',
        'selected_timesheet_id',v_id,
        'repairing_legacy_mixed_state',coalesce((v_group->>'repairing_legacy_mixed_state')::boolean,false)
      ));
    end loop;
  end loop;

  if jsonb_array_length(v_result) > p_max_members then
    raise exception 'CORRECTION_LIFECYCLE_EXPANSION_TOO_LARGE' using errcode = '22023';
  end if;
  return v_result;
end;
$function$;

create or replace function private._timesheet_cross_record_overlap_assert_v1(
  p_candidate_id uuid,
  p_submission_json jsonb,
  p_actual_schedule_json jsonb,
  p_worked_start_iso timestamptz,
  p_worked_end_iso timestamptz,
  p_exclude_workflow_id uuid,
  p_exclude_timesheet_id uuid,
  p_exclude_booking_id text
) returns void language plpgsql volatile security definer
set search_path='public','private','pg_temp' as $function$
declare
  v_new_count integer:=0;
  v_conflict_kind text;
  v_conflict_id uuid;
  v_conflict_start timestamptz;
  v_conflict_end timestamptz;
  v_exact_chain jsonb;
  v_exact_correction_member_ids uuid[]:=array[]::uuid[];
  v_exact_correction_member_count integer:=0;
begin
  if p_candidate_id is null then
    raise exception using errcode='PT409',message='TIMESHEET_CANDIDATE_IDENTITY_REQUIRED_FOR_OVERLAP_CHECK';
  end if;

  select count(*)::integer into v_new_count
  from private._timesheet_work_intervals_v1(
    COALESCE(p_submission_json,'{}'::jsonb),p_actual_schedule_json,
    p_worked_start_iso,p_worked_end_iso
  );
  if v_new_count=0 then return; end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'timesheet-cross-record-overlap:'||p_candidate_id::text,31082026
  ));

  -- The correction-chain authority is consulted only for a current row that it
  -- classifies as an authoritative import correction. The exclusion activates
  -- only when every member of the resolved chain is accounted for by the root
  -- plus valid correction units and the requested unit is itself exact. This
  -- prevents an ordinary child, incomplete/tampered pair, duplicate leg or
  -- unrelated overlapping Timesheet from entering the exclusion set.
  if p_exclude_timesheet_id is not null
     and COALESCE((
       public._ctms_import_correction_classify_v1(p_exclude_timesheet_id)
         ->>'is_import_authoritative_correction'
     )::boolean,false) then
    v_exact_chain:=public.timesheet_correction_chain_scope_v1(
      p_exclude_timesheet_id,false,32,100
    );

    if COALESCE((v_exact_chain->>'valid')::boolean,false)
       and jsonb_typeof(v_exact_chain->'requested_correction_unit')='object'
       and COALESCE((
         v_exact_chain->'requested_correction_unit'->>'valid'
       )::boolean,false)
       and not exists (
         select 1
         from jsonb_array_elements(
           COALESCE(v_exact_chain->'correction_units','[]'::jsonb)
         ) correction_unit(unit_json)
         where COALESCE((correction_unit.unit_json->>'valid')::boolean,false) is not true
       ) then
      select COALESCE(
               array_agg(distinct exact_member.member_id order by exact_member.member_id),
               array[]::uuid[]
             )
      into v_exact_correction_member_ids
      from (
        select nullif(v_exact_chain->>'root_timesheet_id','')::uuid as member_id
        union all
        select correction_member.member_id_text::uuid
        from jsonb_array_elements(
          COALESCE(v_exact_chain->'correction_units','[]'::jsonb)
        ) correction_unit(unit_json)
        cross join lateral jsonb_array_elements_text(
          COALESCE(correction_unit.unit_json->'member_ids','[]'::jsonb)
        ) correction_member(member_id_text)
        where COALESCE((correction_unit.unit_json->>'valid')::boolean,false)
      ) exact_member
      where exact_member.member_id is not null;

      v_exact_correction_member_count:=COALESCE(
        (v_exact_chain->>'member_count')::integer,0
      );
      if v_exact_correction_member_count<>cardinality(v_exact_correction_member_ids)
         or p_exclude_timesheet_id<>all(v_exact_correction_member_ids) then
        v_exact_correction_member_ids:=array[]::uuid[];
      end if;
    end if;
  end if;

  -- Exact request membership is available before the P0/R0 row insert.
  -- Include historic applied WHOLE members of this immutable root so repeated
  -- corrections do not conflict with their own original signed workflows.
  if exists(select 1 from private.timesheet_correction_requests request
    where request.candidate_id=p_candidate_id and request.state in('WAITING','APPLIED')
      and (p_exclude_timesheet_id in(request.replacement_timesheet_id,request.reversal_timesheet_id)
        or p_exclude_timesheet_id::text=request.frozen_original_json->>'planned_reversal_timesheet_id')
      and (p_exclude_booking_id is null or p_exclude_booking_id in(request.replacement_booking_id,request.reversal_booking_id)
        or p_exclude_timesheet_id::text=request.frozen_original_json->>'planned_reversal_timesheet_id')) then
    select coalesce(array_agg(distinct member order by member),array[]::uuid[]) into v_exact_correction_member_ids
      from private.timesheet_correction_requests owner
      join private.timesheet_correction_requests request on request.root_timesheet_id=owner.root_timesheet_id
        and request.candidate_id=owner.candidate_id and request.state in('WAITING','APPLIED')
      cross join lateral unnest(array[request.root_timesheet_id,request.reversed_timesheet_id,
        request.replacement_timesheet_id,request.reversal_timesheet_id,
        (request.frozen_original_json->>'planned_reversal_timesheet_id')::uuid]) member
      where owner.candidate_id=p_candidate_id and owner.state in('WAITING','APPLIED')
        and (p_exclude_timesheet_id in(owner.replacement_timesheet_id,owner.reversal_timesheet_id)
          or p_exclude_timesheet_id::text=owner.frozen_original_json->>'planned_reversal_timesheet_id') and member is not null;
  end if;

  with new_intervals as materialized (
    select * from private._timesheet_work_intervals_v1(
      COALESCE(p_submission_json,'{}'::jsonb),p_actual_schedule_json,
      p_worked_start_iso,p_worked_end_iso
    )
  )
  select 'WORKFLOW',w.id,existing.work_start_utc,existing.work_end_utc
  into v_conflict_kind,v_conflict_id,v_conflict_start,v_conflict_end
  from public.candidate_submission_workflows w
  cross join lateral private._timesheet_work_intervals_v1(
    COALESCE(w.immutable_submission_json,'{}'::jsonb),null,null,null
  ) existing
  join new_intervals proposed
    on proposed.work_start_utc<existing.work_end_utc
   and existing.work_start_utc<proposed.work_end_utc
  where w.candidate_id=p_candidate_id
    and w.id is distinct from p_exclude_workflow_id
    and not (coalesce(w.target_timesheet_id=any(v_exact_correction_member_ids),false) or coalesce(w.anchor_timesheet_id=any(v_exact_correction_member_ids),false))
    and w.worker_submitted_at_utc is not null
    and w.state in (
      'WORKER_SUBMITTED','WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',
      'READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL',
      'MANAGER_APPROVED','MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',
      'READY_TO_FINALISE','AWAITING_PAPER_RETURN','RECEIVED','FINALISED'
    )
    and not (
      p_exclude_booking_id is not null and exists(
        select 1 from public.timesheets linked
        where linked.timesheet_id in (w.target_timesheet_id,w.anchor_timesheet_id)
          and linked.booking_id=p_exclude_booking_id
      )
    )
  order by existing.work_start_utc,w.id
  limit 1;

  if v_conflict_id is null then
    with new_intervals as materialized (
      select * from private._timesheet_work_intervals_v1(
        COALESCE(p_submission_json,'{}'::jsonb),p_actual_schedule_json,
        p_worked_start_iso,p_worked_end_iso
      )
    ), accepted_timesheets as materialized (
      select t.timesheet_id,t.booking_id,t.actual_schedule_json,
        t.worked_start_iso,t.worked_end_iso
      from public.timesheets_financials f
      join public.timesheets t on t.timesheet_id=f.timesheet_id
      where f.candidate_id=p_candidate_id and f.is_current=true
        and t.is_current=true and t.revoked_at is null
        and (t.authorised_at_server is not null or f.authorised_at_utc is not null)
      union
      select t.timesheet_id,t.booking_id,t.actual_schedule_json,
        t.worked_start_iso,t.worked_end_iso
      from public.contracts c
      join public.timesheets t on t.contract_id=c.id
      where c.candidate_id=p_candidate_id and t.is_current=true
        and t.revoked_at is null and t.authorised_at_server is not null
      union
      select t.timesheet_id,t.booking_id,t.actual_schedule_json,
        t.worked_start_iso,t.worked_end_iso
      from public.candidates c
      join public.timesheets t on t.occupant_key_norm=c.key_norm
      where c.id=p_candidate_id and c.key_norm is not null
        and t.is_current=true and t.revoked_at is null
        and t.authorised_at_server is not null
    )
    select 'TIMESHEET',t.timesheet_id,existing.work_start_utc,existing.work_end_utc
    into v_conflict_kind,v_conflict_id,v_conflict_start,v_conflict_end
    from accepted_timesheets t
    cross join lateral private._timesheet_work_intervals_v1(
      '{}'::jsonb,t.actual_schedule_json,t.worked_start_iso,t.worked_end_iso
    ) existing
    join new_intervals proposed
      on proposed.work_start_utc<existing.work_end_utc
     and existing.work_start_utc<proposed.work_end_utc
    where t.timesheet_id is distinct from p_exclude_timesheet_id
      and not (t.timesheet_id=any(v_exact_correction_member_ids))
      and (p_exclude_booking_id is null or t.booking_id<>p_exclude_booking_id)
    order by existing.work_start_utc,t.timesheet_id
    limit 1;
  end if;

  if v_conflict_id is not null then
    raise exception using
      errcode='PT409',
      message='TIMESHEET_WORK_INTERVAL_OVERLAP',
      detail=jsonb_build_object(
        'error_code','TIMESHEET_WORK_INTERVAL_OVERLAP',
        'conflicting_record_kind',v_conflict_kind,
        'conflicting_record_id',v_conflict_id,
        'conflicting_start_utc',v_conflict_start,
        'conflicting_end_utc',v_conflict_end
      )::text;
  end if;
end;$function$;

-- Owner-created, transaction-bound capability. It is not a client flag or a
-- broad workflow retirement exemption and contains no durable business store.
create or replace function private.timesheet_correction_cancel_capability_v1(p_timesheet_id uuid,p_actor_user_id uuid default null)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_cap jsonb; v_request private.timesheet_correction_requests%rowtype; v_p public.timesheets%rowtype;
begin
  if to_regclass('pg_temp.timesheet_correction_cancel_capability_v1') is null
    or not exists(select 1 from pg_class c where c.oid=to_regclass('pg_temp.timesheet_correction_cancel_capability_v1')
      and c.relowner=(select p.proowner from pg_proc p where p.oid='private.timesheet_correction_cancel_capability_v1(uuid,uuid)'::regprocedure)) then
    return null;
  end if;
  execute 'select to_jsonb(cap) from pg_temp.timesheet_correction_cancel_capability_v1 cap where cap.timesheet_id=$1 and cap.backend_pid=pg_backend_pid() and cap.transaction_id=txid_current()'
    into v_cap using p_timesheet_id;
  if v_cap is null or (p_actor_user_id is not null and v_cap->>'actor_user_id' is distinct from p_actor_user_id::text) then return null; end if;
  select request.* into v_request from private.timesheet_correction_requests request where request.id=(v_cap->>'request_id')::uuid;
  select t.* into v_p from public.timesheets t where t.timesheet_id=p_timesheet_id;
  if v_request.state is distinct from 'WAITING' or v_request.state_revision::text is distinct from v_cap->>'state_revision'
    or v_request.replacement_timesheet_id is distinct from p_timesheet_id
    or v_p.timesheet_id is null or not v_p.is_current or v_p.authorised_at_server is not null
    or v_p.booking_id is distinct from v_request.replacement_booking_id
    or v_p.contract_id is distinct from v_request.contract_id
    or v_p.week_ending_date is distinct from v_request.week_ending_date
    or v_p.parent_timesheet_id is distinct from v_request.root_timesheet_id
    or v_p.correction_id is distinct from v_request.correction_id
    or v_p.correction_kind is distinct from 'WHOLE_TIMESHEET_REPLACEMENT'
    or v_p.candidate_workflow_id::text is distinct from v_cap->>'workflow_id'
    or v_p.candidate_workflow_generation::text is distinct from v_cap->>'workflow_generation'
    or exists(select 1 from public.invoice_lines l where l.timesheet_id=p_timesheet_id)
    or exists(select 1 from public.timesheets_financials tf where tf.timesheet_id=p_timesheet_id
      and (tf.authorised_at_utc is not null or tf.paid_at_utc is not null or tf.locked_by_invoice_id is not null
        or tf.unlocked_by_credit_note_id is not null or tf.processed_at_utc is not null
        or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
          then tf.invoice_breakdown_json->'segments' else '[]'::jsonb end) s
          where nullif(s->>'invoice_locked_invoice_id','') is not null or nullif(s->>'invoice_locked_at_utc','') is not null
            or s->>'pay_locked'='true' or nullif(s->>'pay_locked_at_utc','') is not null)))
    or private.timesheet_correction_actor_allowed_v1((v_cap->>'actor_user_id')::uuid) is distinct from true then return null; end if;
  return v_cap;
end;
$function$;

create or replace function public.timesheet_correction_cancel_atomic_v1(
  p_environment text,p_request_id uuid,p_expected_state_revision bigint,p_actor_user_id uuid,p_now_utc timestamptz default now()
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment); v_request private.timesheet_correction_requests%rowtype;
  v_p public.timesheets%rowtype; v_original_before jsonb; v_original_fin_before jsonb; v_preview jsonb; v_pending jsonb;
  v_signature jsonb; v_signature_text text; v_result jsonb; v_retirement jsonb; v_receipt jsonb;
  v_week_ids uuid[]; v_preserved_ts uuid[]; v_preserved_weeks uuid[]; v_kind text;
  v_component_audit jsonb; v_retained_assets text[];
  v_opened boolean:=false; v_delete_operation uuid:=gen_random_uuid(); v_now timestamptz:=coalesce(p_now_utc,now());
begin
  perform private.timesheet_correction_actor_assert_v1(p_actor_user_id);
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id;
  perform 1 from public.invoices i where i.id in(v_request.original_invoice_id,v_request.return_invoice_id) order by i.id for update;
  perform pg_advisory_xact_lock(hashtextextended('CORRECTION_CHAIN|'||v_request.root_timesheet_id::text,21072026));
  select request.* into strict v_request from private.timesheet_correction_requests request where request.id=p_request_id for update;
  if v_request.state<>'WAITING' then return v_request.terminal_receipt_json||jsonb_build_object('replayed',true); end if;
  if v_request.state_revision is distinct from p_expected_state_revision then
    raise exception 'CORRECTION_REQUEST_CAS_STALE' using errcode='40001';
  end if;
  -- No independent actor can retire a neighbouring workflow/week. Capture
  -- every related workflow first, then refuse anything outside exact P0.
  perform 1 from public.candidate_submission_workflows w where w.target_timesheet_id=v_request.replacement_timesheet_id
    or w.anchor_timesheet_id=v_request.replacement_timesheet_id or w.contract_week_id=v_request.replacement_week_id
    order by w.id for update;
  perform 1 from public.contract_weeks w where w.id=v_request.replacement_week_id for update;
  perform 1 from public.timesheets t where t.timesheet_id in(v_request.reversed_timesheet_id,v_request.replacement_timesheet_id)
    order by t.timesheet_id for update;
  perform 1 from public.timesheets_financials tf where tf.timesheet_id in(v_request.reversed_timesheet_id,v_request.replacement_timesheet_id)
    order by tf.timesheet_id,tf.id for update;
  select t.* into strict v_p from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
  if exists(select 1 from public.candidate_submission_workflows w
    where (w.target_timesheet_id=v_p.timesheet_id or w.anchor_timesheet_id=v_p.timesheet_id or w.contract_week_id=v_request.replacement_week_id)
      and (w.id is distinct from v_p.candidate_workflow_id or w.generation is distinct from v_p.candidate_workflow_generation)) then
    raise exception 'CORRECTION_CANCEL_WORKFLOW_SCOPE_UNPROVED' using errcode='55000';
  end if;
  if to_regclass('pg_temp.timesheet_correction_cancel_capability_v1') is not null then
    raise exception 'CORRECTION_CANCEL_CONTEXT_CONFLICT' using errcode='55000';
  end if;
  create temp table pg_temp.timesheet_correction_cancel_capability_v1(
    request_id uuid primary key,timesheet_id uuid unique not null,state_revision bigint not null,
    actor_user_id uuid not null,workflow_id uuid,workflow_generation integer,contract_week_id uuid,
    delete_operation_id uuid not null,backend_pid integer not null,transaction_id bigint not null
  ) on commit drop;
  revoke all on pg_temp.timesheet_correction_cancel_capability_v1 from public,anon,authenticated,service_role;
  insert into pg_temp.timesheet_correction_cancel_capability_v1 values(v_request.id,v_p.timesheet_id,v_request.state_revision,
    p_actor_user_id,v_p.candidate_workflow_id,v_p.candidate_workflow_generation,v_request.replacement_week_id,
    v_delete_operation,pg_backend_pid(),txid_current());
  v_opened:=true;
  if private.timesheet_correction_cancel_capability_v1(v_p.timesheet_id,p_actor_user_id) is null then
    raise exception 'CORRECTION_CANCEL_P0_AUTHORITY_INVALID' using errcode='55000';
  end if;
  select to_jsonb(t) into v_original_before from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id;
  select coalesce(jsonb_agg(to_jsonb(tf) order by tf.id),'[]'::jsonb) into v_original_fin_before
    from public.timesheets_financials tf where tf.timesheet_id=v_request.reversed_timesheet_id;
  -- Native deletion inventories TS signature keys for cleanup. Preserve the
  -- exact immutable P0 audit assets before retirement clears live TS links.
  perform 1 from public.candidate_submission_components c where c.workflow_id=v_p.candidate_workflow_id
    and c.workflow_generation=v_p.candidate_workflow_generation and c.state='IMMUTABLE' order by c.id for update;
  select coalesce(jsonb_agg(to_jsonb(c)-'timesheet_id' order by c.id),'[]'::jsonb) into v_component_audit
    from public.candidate_submission_components c where c.workflow_id=v_p.candidate_workflow_id
      and c.workflow_generation=v_p.candidate_workflow_generation and c.state='IMMUTABLE';
  select coalesce(array_agg(distinct asset_key order by asset_key),array[]::text[]) into v_retained_assets
    from public.candidate_submission_components c cross join lateral unnest(array[
      c.storage_key,c.review_storage_key,c.final_signed_storage_key,c.paper_return_page_key]) asset(asset_key)
    where c.workflow_id=v_p.candidate_workflow_id and c.workflow_generation=v_p.candidate_workflow_generation
      and c.state='IMMUTABLE' and nullif(btrim(asset_key),'') is not null;
  v_week_ids:=case when v_request.replacement_week_id is null then array[]::uuid[] else array[v_request.replacement_week_id] end;
  v_signature:=public.timesheet_lifecycle_guard_signature_v1(v_p.timesheet_id,v_request.replacement_week_id,false);
  v_signature_text:=coalesce(v_signature->>'backend_row_signature',v_signature->>'row_signature');
  v_kind:=case when v_p.sheet_scope::text='WEEKLY' then 'WEEKLY_MANUAL_ADJUSTMENT_DELETE' else 'STANDARD_DELETE' end;
  v_preview:=case when v_kind='WEEKLY_MANUAL_ADJUSTMENT_DELETE'
    then public.timesheet_weekly_manual_adjustment_delete_preview(v_p.timesheet_id,p_actor_user_id)
    else public.timesheet_standard_delete_preview_v1(v_p.timesheet_id,p_actor_user_id,v_p.timesheet_id,v_signature_text) end;
  if v_preview->'timesheet_ids' is distinct from jsonb_build_array(v_p.timesheet_id)
    or v_preview->'contract_week_ids' is distinct from to_jsonb(v_week_ids)
    or v_preview->>'decision' not in('PERMANENT_DELETE','ARCHIVE_REQUIRED') then
    raise exception 'CORRECTION_CANCEL_LAWFUL_REMOVAL_UNPROVED' using errcode='55000',detail=v_preview::text;
  end if;
  select coalesce(array_agg(id::uuid order by id),array[]::uuid[]) into v_preserved_ts
    from jsonb_array_elements_text(coalesce(v_preview->'preserved_source_timesheet_ids','[]'::jsonb)) item(id);
  select coalesce(array_agg(id::uuid order by id),array[]::uuid[]) into v_preserved_weeks
    from jsonb_array_elements_text(coalesce(v_preview->'preserved_source_contract_week_ids','[]'::jsonb)) item(id);
  v_pending:=private._timesheet_pending_expense_delete_context_v1(v_environment,array[v_p.timesheet_id],true);
  if coalesce((v_pending->>'cancellation_required')::boolean,false)
    or coalesce((v_pending->>'delete_blocked')::boolean,false) then
    raise exception 'CORRECTION_CANCEL_EXTERNAL_EXPENSE_SCOPE_UNPROVED' using errcode='55000',detail=v_pending::text;
  end if;
  if v_preview->>'decision'='ARCHIVE_REQUIRED' then
    v_retirement:=private._candidate_timesheet_delete_retire_workflows_v1(v_environment,array[v_p.timesheet_id],v_week_ids,
      array[]::uuid[],p_actor_user_id,v_delete_operation,v_now);
    v_signature:=public.timesheet_lifecycle_guard_signature_v1(v_p.timesheet_id,v_request.replacement_week_id,false);
    v_result:=public.timesheet_archive_transition_v1(v_p.timesheet_id,'ARCHIVE',v_kind,p_actor_user_id,v_p.timesheet_id,
      coalesce(v_signature->>'backend_row_signature',v_signature->>'row_signature'),v_now);
  else
    v_result:=public.timesheet_delete_with_candidate_submission_guard_apply_v1(v_environment,v_kind,v_p.timesheet_id,p_actor_user_id,
      v_p.timesheet_id,v_signature_text,array[v_p.timesheet_id],v_week_ids,array[]::uuid[],v_preserved_ts,v_preserved_weeks,
      v_pending->>'context_sha256',v_delete_operation,v_now);
  end if;
  if jsonb_typeof(v_result->'r2_cleanup_keys')='array' then
    v_result:=jsonb_set(v_result,'{r2_cleanup_keys}',coalesce((select jsonb_agg(key.value order by key.value)
      from jsonb_array_elements_text(v_result->'r2_cleanup_keys') key(value)
      where not (key.value=any(v_retained_assets))),'[]'::jsonb),true);
    if v_result?'r2_cleanup_required' then
      v_result:=jsonb_set(v_result,'{r2_cleanup_required}',to_jsonb(jsonb_array_length(v_result->'r2_cleanup_keys')>0),true);
    end if;
  end if;
  if v_result->>'ok'='false' or v_result->>'success'='false'
    or exists(select 1 from public.timesheets t where t.timesheet_id=v_p.timesheet_id and t.archived_at_utc is null)
    or exists(select 1 from public.timesheets t where t.booking_id=v_request.replacement_booking_id
      and t.timesheet_id<>v_request.replacement_timesheet_id and t.is_current and t.archived_at_utc is null)
    or (v_preview->>'decision'='PERMANENT_DELETE' and exists(select 1 from public.contract_weeks w where w.id=v_request.replacement_week_id))
    or (v_preview->>'decision'='ARCHIVE_REQUIRED' and v_request.replacement_week_id is not null
      and not exists(select 1 from public.contract_weeks w join public.timesheets t on t.timesheet_id=w.timesheet_id
        where w.id=v_request.replacement_week_id and w.timesheet_id=v_request.replacement_timesheet_id and t.archived_at_utc is not null))
    or exists(select 1 from public.candidate_submission_workflows w where w.id=v_p.candidate_workflow_id
      and (w.target_timesheet_id is not null or w.anchor_timesheet_id is not null or w.contract_week_id is not null or w.state<>'CANCELLED'))
    or exists(select 1 from public.candidate_approval_requests a where a.workflow_id=v_p.candidate_workflow_id and a.state='PENDING')
    or (select coalesce(jsonb_agg(to_jsonb(c)-'timesheet_id' order by c.id),'[]'::jsonb)
      from public.candidate_submission_components c where c.workflow_id=v_p.candidate_workflow_id
        and c.workflow_generation=v_p.candidate_workflow_generation and c.state='IMMUTABLE') is distinct from v_component_audit
    or (select to_jsonb(t) from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id) is distinct from v_original_before
    or (select coalesce(jsonb_agg(to_jsonb(tf) order by tf.id),'[]'::jsonb) from public.timesheets_financials tf
      where tf.timesheet_id=v_request.reversed_timesheet_id) is distinct from v_original_fin_before then
    raise exception 'CORRECTION_CANCEL_COMPLETE_UNIT_FAILED' using errcode='55000',detail=v_result::text;
  end if;
  v_receipt:=jsonb_build_object('ok',true,'state','CANCELLED','request_id',v_request.id,'state_revision',v_request.state_revision+1,
    'replacement_timesheet_id',v_p.timesheet_id,'delete_operation_id',v_delete_operation,'lawful_removal',v_result,
    'retained_immutable_component_asset_count',cardinality(v_retained_assets));
  update private.timesheet_correction_requests request set state='CANCELLED',state_revision=state_revision+1,
    cancelled_at_utc=v_now,updated_at_utc=v_now,terminal_receipt_json=v_receipt where request.id=v_request.id;
  drop table pg_temp.timesheet_correction_cancel_capability_v1;
  v_opened:=false;
  return v_receipt;
exception when others then
  if v_opened then drop table if exists pg_temp.timesheet_correction_cancel_capability_v1; end if;
  raise;
end;
$function$;

create or replace function private._timesheet_candidate_submission_delete_guard_v1(
  p_environment text,
  p_timesheet_ids uuid[],
  p_lock_workflows boolean default false
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_timesheet_ids uuid[];
  v_timesheet_id uuid;
  v_target_context jsonb;
  v_target jsonb;
  v_guard_items jsonb:='[]'::jsonb;
  v_all_workflow_ids uuid[]:=array[]::uuid[];
  v_linked_pending_expense_workflow_ids uuid[]:=array[]::uuid[];
  v_stage text;
  v_linked_pending_expense_count integer:=0;
begin
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_timesheet_ids
  from unnest(coalesce(p_timesheet_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;

  if cardinality(v_timesheet_ids)<1 or cardinality(v_timesheet_ids)>64 then
    raise exception 'CANDIDATE_SUBMISSION_DELETE_TARGET_SET_INVALID' using errcode='22023';
  end if;

  foreach v_timesheet_id in array v_timesheet_ids loop
    v_target_context:=private._candidate_office_rejection_targets_v2(
      v_environment,v_timesheet_id
    );
    for v_target in
      select value from jsonb_array_elements(coalesce(
        v_target_context->'target_workflows','[]'::jsonb
      )) target(value)
    loop
      if not ((v_target->>'workflow_id')::uuid=any(v_all_workflow_ids)) then
        v_all_workflow_ids:=array_append(
          v_all_workflow_ids,(v_target->>'workflow_id')::uuid
        );
      end if;
      if coalesce((v_target->>'delete_guard_applicable')::boolean,false)
         and coalesce((v_target->>'linked_pending_expense')::boolean,false)
         and not ((v_target->>'workflow_id')::uuid
           =any(v_linked_pending_expense_workflow_ids)) then
        v_linked_pending_expense_workflow_ids:=array_append(
          v_linked_pending_expense_workflow_ids,(v_target->>'workflow_id')::uuid
        );
      end if;
      if coalesce((v_target->>'delete_guard_applicable')::boolean,false)
         and not (private.timesheet_correction_cancel_capability_v1(v_timesheet_id,null) is not null
           and v_target->>'workflow_id'=private.timesheet_correction_cancel_capability_v1(v_timesheet_id,null)->>'workflow_id')
         and v_target->>'candidate_submission_stage'<>'DRAFT'
         and not exists(
           select 1 from jsonb_array_elements(v_guard_items) existing(item)
           where existing.item->>'workflow_id'=v_target->>'workflow_id'
         ) then
        v_guard_items:=v_guard_items||jsonb_build_array(
          v_target||jsonb_build_object('rejection_timesheet_id',v_timesheet_id)
        );
      end if;
    end loop;
  end loop;

  if p_lock_workflows and cardinality(v_all_workflow_ids)>0 then
    perform 1
    from public.candidate_submission_workflows workflow_row
    where workflow_row.id=any(v_all_workflow_ids)
    order by workflow_row.id
    for update;
    return private._timesheet_candidate_submission_delete_guard_v1(
      v_environment,v_timesheet_ids,false
    );
  end if;

  v_stage:=case
    when exists(
      select 1 from jsonb_array_elements(v_guard_items) item
      where item->>'candidate_submission_stage'='MANAGER_APPROVED'
    ) then 'MANAGER_APPROVED'
    when jsonb_array_length(v_guard_items)>0 then 'CANDIDATE_SUBMITTED'
    else null
  end;
  v_linked_pending_expense_count:=cardinality(
    v_linked_pending_expense_workflow_ids
  );

  return jsonb_build_object(
    'ok',true,
    'contract_version','TIMESHEET_CANDIDATE_SUBMISSION_DELETE_GUARD_V1',
    'environment',v_environment,
    'timesheet_ids',to_jsonb(v_timesheet_ids),
    'candidate_submission_rejection_required',jsonb_array_length(v_guard_items)>0,
    'candidate_submission_stage',v_stage,
    'guarded_workflow_count',jsonb_array_length(v_guard_items),
    'guarded_workflows',v_guard_items,
    'related_workflow_ids',to_jsonb(v_all_workflow_ids),
    'linked_pending_expense_claim_count',v_linked_pending_expense_count
  );
end;
$function$;

create or replace function private._candidate_timesheet_delete_retire_workflows_v1(
  p_environment text,
  p_timesheet_ids uuid[],
  p_contract_week_ids uuid[],
  p_excluded_workflow_ids uuid[],
  p_actor_user_id uuid,
  p_delete_operation_id uuid,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_timesheet_ids uuid[];
  v_contract_week_ids uuid[];
  v_excluded_workflow_ids uuid[];
  v_workflow public.candidate_submission_workflows%rowtype;
  v_expense_component public.candidate_expense_components%rowtype;
  v_expense_before jsonb;
  v_retired_workflow_ids uuid[]:=array[]::uuid[];
  v_previous_state text;
  v_correction_cap jsonb;
begin
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_timesheet_ids
  from unnest(coalesce(p_timesheet_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_contract_week_ids
  from unnest(coalesce(p_contract_week_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;
  select coalesce(array_agg(distinct supplied_id order by supplied_id),array[]::uuid[])
  into v_excluded_workflow_ids
  from unnest(coalesce(p_excluded_workflow_ids,array[]::uuid[])) supplied(supplied_id)
  where supplied_id is not null;

  if p_actor_user_id is null or p_delete_operation_id is null
     or cardinality(v_timesheet_ids)<1 or cardinality(v_timesheet_ids)>64
     or cardinality(v_contract_week_ids)>64
     or cardinality(v_excluded_workflow_ids)>20 then
    raise exception 'CANDIDATE_TIMESHEET_DELETE_RETIREMENT_INVALID'
      using errcode='22023';
  end if;

  for v_workflow in
    select workflow_row.*
    from public.candidate_submission_workflows workflow_row
    where workflow_row.environment=v_environment
      and workflow_row.workflow_kind in (
        'CONTRACT_HOURS','CONTRACT_EXPENSE','CONTRACT_COMBINED','DAILY'
      )
      and (workflow_row.workflow_kind<>'DAILY' or exists(select 1 from unnest(v_timesheet_ids) id
        where private.timesheet_correction_cancel_capability_v1(id,p_actor_user_id)->>'workflow_id'=workflow_row.id::text))
      and not (workflow_row.id=any(v_excluded_workflow_ids))
      and (
        workflow_row.target_timesheet_id=any(v_timesheet_ids)
        or workflow_row.anchor_timesheet_id=any(v_timesheet_ids)
        or workflow_row.contract_week_id=any(v_contract_week_ids)
      )
    order by workflow_row.id
    for update
  loop
    v_correction_cap:=null;
    select private.timesheet_correction_cancel_capability_v1(id,p_actor_user_id) into v_correction_cap
      from unnest(v_timesheet_ids) id where private.timesheet_correction_cancel_capability_v1(id,p_actor_user_id)->>'workflow_id'=v_workflow.id::text;
    if v_correction_cap is not null and (cardinality(v_timesheet_ids)<>1
      or v_correction_cap->>'delete_operation_id' is distinct from p_delete_operation_id::text
      or v_correction_cap->>'workflow_generation' is distinct from v_workflow.generation::text
      or to_jsonb(v_contract_week_ids) is distinct from case when v_correction_cap->>'contract_week_id' is null
        then '[]'::jsonb else jsonb_build_array((v_correction_cap->>'contract_week_id')::uuid) end) then
      raise exception 'CORRECTION_CANCEL_RETIREMENT_SCOPE_CHANGED' using errcode='40001';
    end if;
    if v_correction_cap is null and v_workflow.state not in (
      'CREATED','WORKER_DRAFT','REFUSED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED'
    ) then
      raise exception 'CANDIDATE_SUBMISSION_REJECTION_REQUIRED'
        using errcode='55000',detail=jsonb_build_object(
          'workflow_id',v_workflow.id,
          'workflow_state',v_workflow.state
        )::text;
    end if;
    v_previous_state:=v_workflow.state;

    update public.candidate_approval_requests approval
    set state='CANCELLED',
        cancelled_at_utc=coalesce(approval.cancelled_at_utc,p_now_utc),
        updated_at_utc=p_now_utc
    where approval.workflow_id=v_workflow.id
      and approval.state='PENDING';

    -- The stable category ledger must be retired before the owning Timesheet
    -- FK is released.  Otherwise a draft component can survive the generic
    -- Office delete with no owner and still project a Candidate Remove action.
    -- Only components proved to belong to this deletion unit (or an unowned
    -- component on the exact deleted workflow anchor) are affected.
    for v_expense_component in
      select component.*
      from public.candidate_expense_components component
      where component.workflow_id=v_workflow.id
        and component.lifecycle_state not in (
          'MANAGER_REFUSED','OFFICE_REJECTED','WITHDRAWN','CANCELLED','SUPERSEDED'
        )
        and (
          component.owning_timesheet_id=any(v_timesheet_ids)
          or (
            component.owning_timesheet_id is null
            and (
              v_workflow.target_timesheet_id=any(v_timesheet_ids)
              or v_workflow.anchor_timesheet_id=any(v_timesheet_ids)
            )
          )
        )
      order by component.expense_component_id
      for update
    loop
      v_expense_before:=to_jsonb(v_expense_component);
      update public.candidate_expense_components component set
        component_generation=component.component_generation+1,
        owning_timesheet_id=null,
        lifecycle_state='CANCELLED',
        manager_approval_state=case
          when component.manager_approval_state in ('APPROVED','REFUSED')
            then component.manager_approval_state
          else 'NOT_REQUESTED' end,
        approval_request_id=case
          when component.manager_approval_state in ('APPROVED','REFUSED')
            then component.approval_request_id
          else null end,
        removed_at_utc=coalesce(component.removed_at_utc,p_now_utc),
        updated_at_utc=p_now_utc
      where component.expense_component_id=v_expense_component.expense_component_id
      returning component.* into v_expense_component;
      insert into public.candidate_expense_component_events(
        expense_component_id,workflow_id,component_generation,event_type,
        actor_kind,actor_id,before_state_json,after_state_json,idempotency_key,
        occurred_at_utc
      ) values (
        v_expense_component.expense_component_id,v_workflow.id,
        v_expense_component.component_generation,'CANCELLED','OFFICE',
        p_actor_user_id,v_expense_before,to_jsonb(v_expense_component),
        'office-timesheet-delete:'||p_delete_operation_id::text||':'
          ||v_expense_component.expense_component_id::text,p_now_utc
      ) on conflict(expense_component_id,idempotency_key) do nothing;
    end loop;

    update public.candidate_submission_components component
    set timesheet_id=null,
        state=case
          when v_previous_state in ('CREATED','WORKER_DRAFT')
            and component.state not in ('SUPERSEDED','REJECTED','ABANDONED')
            then 'ABANDONED'
          else component.state
        end,
        superseded_at_utc=case
          when v_previous_state in ('CREATED','WORKER_DRAFT')
            then coalesce(component.superseded_at_utc,p_now_utc)
          else component.superseded_at_utc
        end
    where component.workflow_id=v_workflow.id
      and component.timesheet_id=any(v_timesheet_ids);

    update public.candidate_notifications notification
    set timesheet_id=null,
        deep_link_json=(coalesce(notification.deep_link_json,'{}'::jsonb)
          -'timesheet_id'-'contract_week_id')||jsonb_build_object(
            'type','workflow','workflow_id',v_workflow.id
          ),
        state='DISMISSED',
        dismissed_at_utc=coalesce(notification.dismissed_at_utc,p_now_utc),
        push_state=case
          when notification.push_state in ('PENDING','FAILED','CLAIMED') then 'SKIPPED'
          else notification.push_state end
    where notification.workflow_id=v_workflow.id;

    update public.candidate_submission_workflows workflow_row
    set state=case
          when v_correction_cap is not null or workflow_row.state in ('CREATED','WORKER_DRAFT')
            then 'CANCELLED'
          else workflow_row.state
        end,
        contract_week_id=null,
        anchor_timesheet_id=null,
        target_timesheet_id=null,
        cancelled_at_utc=case
          when v_correction_cap is not null or workflow_row.state in ('CREATED','WORKER_DRAFT')
            then coalesce(workflow_row.cancelled_at_utc,p_now_utc)
          else workflow_row.cancelled_at_utc
        end,
        input_snapshot_json=coalesce(workflow_row.input_snapshot_json,'{}'::jsonb)
          ||jsonb_build_object(
            'office_permanent_delete_tombstone',jsonb_build_object(
              'delete_operation_id',p_delete_operation_id,
              'deleted_timesheet_ids',to_jsonb(v_timesheet_ids),
              'deleted_contract_week_ids',to_jsonb(v_contract_week_ids),
              'previous_contract_week_id',v_workflow.contract_week_id,
              'previous_anchor_timesheet_id',v_workflow.anchor_timesheet_id,
              'previous_target_timesheet_id',v_workflow.target_timesheet_id,
              'retired_at_utc',p_now_utc
            )
          ),
        issue_codes=case
          when workflow_row.issue_codes
            @> '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
            then workflow_row.issue_codes
          else workflow_row.issue_codes
            ||'["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
        end,
        updated_at_utc=p_now_utc
    where workflow_row.id=v_workflow.id;

    insert into public.audit_events(
      actor_user_id,object_type,object_id_text,action,before_json,after_json,
      reason,correlation_id,ts_utc
    ) values (
      p_actor_user_id,'candidate_submission_workflows',v_workflow.id::text,
      'CANDIDATE_WORKFLOW_RETAINED_AFTER_TIMESHEET_DELETE',
      jsonb_build_object(
        'state',v_previous_state,
        'contract_week_id',v_workflow.contract_week_id,
        'anchor_timesheet_id',v_workflow.anchor_timesheet_id,
        'target_timesheet_id',v_workflow.target_timesheet_id
      ),
      jsonb_build_object(
        'state',case when v_correction_cap is not null or v_previous_state in ('CREATED','WORKER_DRAFT')
          then 'CANCELLED' else v_previous_state end,
        'live_timesheet_links_released',true,
        'terminal_audit_retained',true
      ),
      'OFFICE_PERMANENTLY_DELETED_TIMESHEET',p_delete_operation_id,p_now_utc
    );
    v_retired_workflow_ids:=array_append(
      v_retired_workflow_ids,v_workflow.id
    );
  end loop;

  return jsonb_build_object(
    'ok',true,
    'contract_version','CANDIDATE_TIMESHEET_DELETE_WORKFLOW_RETIREMENT_V1',
    'retired_workflow_count',cardinality(v_retired_workflow_ids),
    'retired_workflow_ids',to_jsonb(v_retired_workflow_ids)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.timesheet_weekly_manual_adjustment_delete_preview(p_timesheet_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_in_ts public.timesheets%rowtype;
  v_current_ts public.timesheets%rowtype;

  v_booking_id text := null;

  v_timesheet_ids uuid[] := array[]::uuid[];
  v_contract_week_ids uuid[] := array[]::uuid[];
  v_contract_week_id uuid := null;
  v_preserved_source_contract_week_ids uuid[] := array[]::uuid[];
  v_preserved_source_timesheet_ids uuid[] := array[]::uuid[];
  v_effective_manual_adjustment boolean := false;
  v_linked_adjustment_contract_week_exists boolean := false;
  v_has_base_contract_week_target boolean := false;

  v_blocked jsonb := '[]'::jsonb;

  v_history jsonb := '{}'::jsonb;
  v_decision text := 'BLOCKED';

  v_delete_items jsonb := '[]'::jsonb;
begin
  if p_timesheet_id is null then
    raise exception 'timesheet_weekly_manual_adjustment_delete_preview: timesheet_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception using message = 'ACTOR_USER_ID_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.tms_users as actor
    where actor.id = p_actor_user_id
      and actor.is_active = true
  ) then
    raise exception using message = 'ACTOR_NOT_FOUND_OR_INACTIVE';
  end if;

  select input_timesheet.*
  into v_in_ts
  from public.timesheets as input_timesheet
  where input_timesheet.timesheet_id = p_timesheet_id;

  if not found then
    raise exception 'timesheet_weekly_manual_adjustment_delete_preview: timesheet % not found', p_timesheet_id;
  end if;

  v_booking_id := v_in_ts.booking_id;

  select current_timesheet.*
  into v_current_ts
  from public.timesheets as current_timesheet
  where current_timesheet.booking_id = v_booking_id
  order by current_timesheet.is_current desc, current_timesheet.version desc, current_timesheet.updated_at desc nulls last, current_timesheet.created_at desc nulls last, current_timesheet.timesheet_id desc
  limit 1;

  if not found then
    raise exception 'timesheet_weekly_manual_adjustment_delete_preview: booking_id % not found', v_booking_id;
  end if;

  select coalesce(array_agg(all_versions.timesheet_id order by all_versions.version asc nulls last, all_versions.created_at asc nulls last, all_versions.timesheet_id asc), array[]::uuid[])
  into v_timesheet_ids
  from public.timesheets as all_versions
  where all_versions.booking_id = v_current_ts.booking_id;

  select
    coalesce(bool_or(coalesce(linked_contract_week.is_adjustment, false) = true or coalesce(linked_contract_week.additional_seq, 0) > 0), false),
    coalesce(bool_or(coalesce(linked_contract_week.is_adjustment, false) = false or coalesce(linked_contract_week.additional_seq, 0) <= 0), false)
  into v_linked_adjustment_contract_week_exists,
       v_has_base_contract_week_target
  from public.contract_weeks as linked_contract_week
  where linked_contract_week.timesheet_id = any(v_timesheet_ids);

  select coalesce(array_agg(distinct adjustment_contract_week.id order by adjustment_contract_week.id), array[]::uuid[])
  into v_contract_week_ids
  from public.contract_weeks as adjustment_contract_week
  where adjustment_contract_week.timesheet_id = any(v_timesheet_ids)
    and coalesce(adjustment_contract_week.is_adjustment, false) = true
    and coalesce(adjustment_contract_week.additional_seq, 0) > 0;

  v_effective_manual_adjustment :=
    coalesce(v_current_ts.is_adjustment, false) = true
    or coalesce(v_linked_adjustment_contract_week_exists, false) = true
    or v_current_ts.parent_timesheet_id is not null
    or v_current_ts.correction_id is not null
    or nullif(btrim(coalesce(v_current_ts.correction_kind, '')), '') is not null
    or upper(coalesce(v_current_ts.adjustment_origin, '')) in ('MANUAL_ADJUSTMENT', 'IMPORT_CORRECTION', 'IMPORT_CANCELLATION');

  if coalesce(array_length(v_contract_week_ids, 1), 0) > 0 then
    v_contract_week_id := v_contract_week_ids[1];
  end if;

  select coalesce(array_agg(distinct source_contract_week.id order by source_contract_week.id), array[]::uuid[])
  into v_preserved_source_contract_week_ids
  from public.contract_weeks as adjustment_contract_week_for_source
  join public.contract_weeks as source_contract_week
    on source_contract_week.contract_id = adjustment_contract_week_for_source.contract_id
   and source_contract_week.week_ending_date = adjustment_contract_week_for_source.week_ending_date
   and coalesce(source_contract_week.additional_seq, 0) = 0
   and coalesce(source_contract_week.is_adjustment, false) = false
  where adjustment_contract_week_for_source.id = any(v_contract_week_ids);

  select coalesce(array_agg(distinct preserved_timesheet_id order by preserved_timesheet_id), array[]::uuid[])
  into v_preserved_source_timesheet_ids
  from (
    select source_contract_week_for_ts.timesheet_id as preserved_timesheet_id
    from public.contract_weeks as source_contract_week_for_ts
    where source_contract_week_for_ts.id = any(v_preserved_source_contract_week_ids)
      and source_contract_week_for_ts.timesheet_id is not null
    union
    select v_current_ts.parent_timesheet_id as preserved_timesheet_id
    where v_current_ts.parent_timesheet_id is not null
  ) as preserved_source_timesheet_ids
  where preserved_source_timesheet_ids.preserved_timesheet_id is not null;

  if v_current_ts.sheet_scope <> 'WEEKLY'::public.timesheet_scope_enum then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','NOT_WEEKLY',
      'message','Manual adjustment delete applies only to WEEKLY adjustment timesheets.',
      'timesheet_id', v_current_ts.timesheet_id::text
    ));
  end if;

  if coalesce(v_effective_manual_adjustment, false) is not true then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','NOT_ADJUSTMENT',
      'message','Timesheet is not an adjustment/additional manual row; this preview is only for WEEKLY manual adjustment deletes.',
      'timesheet_id', v_current_ts.timesheet_id::text,
      'contract_week_ids', to_jsonb(coalesce(v_contract_week_ids, array[]::uuid[]))
    ));
  end if;

  if private.timesheet_correction_cancel_capability_v1(v_current_ts.timesheet_id,p_actor_user_id) is null and (
    upper(coalesce(v_current_ts.adjustment_origin,'')) in ('IMPORT_CORRECTION','IMPORT_CANCELLATION')
    or nullif(btrim(coalesce(v_current_ts.correction_kind,'')),'') is not null
    or v_current_ts.correction_id is not null
  ) then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','IMPORT_DERIVED_CHILD',
      'message','Import-derived adjustments cannot be deleted directly; they must be deleted via the WEEKLY parent-chain delete.',
      'timesheet_id', v_current_ts.timesheet_id::text,
      'adjustment_origin', v_current_ts.adjustment_origin,
      'correction_id', v_current_ts.correction_id,
      'correction_kind', v_current_ts.correction_kind
    ));
  end if;

  if coalesce(array_length(v_contract_week_ids,1),0) = 0 then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','MISSING_CONTRACT_WEEK',
      'message','No linked additional/manual adjustment contract_week found for this weekly manual adjustment; refusing delete to avoid orphan/corruption.',
      'timesheet_id', v_current_ts.timesheet_id::text
    ));
  end if;

  if coalesce(v_has_base_contract_week_target, false) = true then
    v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
      'code','BASE_CONTRACT_WEEK_TARGETED',
      'message','Delete preview resolved a base/source contract_week for a manual adjustment delete; refusing delete to protect the parent/source row.',
      'contract_week_ids', to_jsonb(coalesce(v_contract_week_ids, array[]::uuid[])),
      'preserved_source_contract_week_ids', to_jsonb(coalesce(v_preserved_source_contract_week_ids, array[]::uuid[]))
    ));
  end if;

  v_history := public.timesheet_removal_financial_history_v1(
    v_timesheet_ids,
    ARRAY[v_current_ts.booking_id],
    v_contract_week_ids
  );

  v_blocked := v_blocked || COALESCE(v_history -> 'blockers', '[]'::jsonb);

  IF jsonb_array_length(v_blocked) > 0 THEN
    v_decision := 'BLOCKED';
  ELSIF COALESCE((v_history ->> 'archive_required')::boolean, false) THEN
    v_decision := 'ARCHIVE_REQUIRED';
  ELSE
    v_decision := 'PERMANENT_DELETE';
  END IF;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'timesheet_id', v_current_ts.timesheet_id::text,
        'booking_id', v_current_ts.booking_id,
        'week_ending_date', v_current_ts.week_ending_date::text,
        'status', v_current_ts.status::text,
        'is_adjustment', coalesce(v_effective_manual_adjustment, false),
        'adjustment_origin', v_current_ts.adjustment_origin,
        'correction_id', v_current_ts.correction_id,
        'correction_kind', v_current_ts.correction_kind,
        'display_role', 'MANUAL_ADJUSTMENT',
        'total_hours', coalesce(selected_tsfin.total_hours, 0),
        'total_pay_ex_vat', coalesce(selected_tsfin.total_pay_ex_vat, 0),
        'total_charge_ex_vat', coalesce(selected_tsfin.total_charge_ex_vat, 0)
      )
      order by selected_tsfin.id
    ),
    '[]'::jsonb
  )
  into v_delete_items
  from public.timesheets_financials as selected_tsfin
  where selected_tsfin.timesheet_id = v_current_ts.timesheet_id
    and selected_tsfin.is_current is true;

  if jsonb_array_length(v_delete_items) = 0 then
    v_delete_items := jsonb_build_array(jsonb_build_object(
      'timesheet_id', v_current_ts.timesheet_id::text,
      'booking_id', v_current_ts.booking_id,
      'week_ending_date', v_current_ts.week_ending_date::text,
      'status', v_current_ts.status::text,
      'is_adjustment', coalesce(v_effective_manual_adjustment, false),
      'adjustment_origin', v_current_ts.adjustment_origin,
      'correction_id', v_current_ts.correction_id,
      'correction_kind', v_current_ts.correction_kind,
      'display_role', 'MANUAL_ADJUSTMENT',
      'total_hours', 0,
      'total_pay_ex_vat', 0,
      'total_charge_ex_vat', 0
    ));
  end if;

  return jsonb_build_object(
    'kind', 'WEEKLY_MANUAL_ADJUSTMENT_DELETE',
    'requested_timesheet_id', p_timesheet_id::text,
    'current_timesheet_id', v_current_ts.timesheet_id::text,
    'booking_id', v_current_ts.booking_id,
    'contract_week_id', case when v_contract_week_id is null then null else v_contract_week_id::text end,
    'contract_week_ids', to_jsonb(coalesce(v_contract_week_ids, array[]::uuid[])),
    'timesheet_ids', to_jsonb(coalesce(v_timesheet_ids, array[]::uuid[])),
    'preserved_source_timesheet_ids', to_jsonb(coalesce(v_preserved_source_timesheet_ids, array[]::uuid[])),
    'preserved_source_contract_week_ids', to_jsonb(coalesce(v_preserved_source_contract_week_ids, array[]::uuid[])),
    'delete_items', v_delete_items,
    'decision', v_decision,
    'eligible', (v_decision = 'PERMANENT_DELETE'),
    'blocked_reasons', v_blocked,
    'blockers', v_blocked,
    'retention_reasons', COALESCE(v_history -> 'retention_reasons', '[]'::jsonb),
    'advance', COALESCE(v_history -> 'advance', '{}'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.timesheet_standard_delete_preview_v1(p_timesheet_id uuid, p_actor_user_id uuid, p_expected_timesheet_id uuid DEFAULT NULL::uuid, p_expected_row_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_requested public.timesheets%ROWTYPE;
  v_current public.timesheets%ROWTYPE;
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_nhsp_shift_ids uuid[] := ARRAY[]::uuid[];
  v_preserved_source_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_preserved_source_contract_week_ids uuid[] := ARRAY[]::uuid[];
  v_primary_contract_week_id uuid := NULL;
  v_history jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_decision text := 'BLOCKED';
  v_signature_payload jsonb := '{}'::jsonb;
  v_current_signature text := NULL;
  v_class jsonb := '{}'::jsonb;
  v_chain jsonb := '{}'::jsonb;
  v_unit jsonb := '{}'::jsonb;
  v_is_correction_pair boolean := false;
  v_pair_fingerprint text := NULL;
  v_pair_members jsonb := '[]'::jsonb;
  v_pair_net_hours numeric := 0;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'TIMESHEET_ID_REQUIRED';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_USER_ID_REQUIRED';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.tms_users AS actor
    WHERE actor.id = p_actor_user_id
      AND actor.is_active = true
  ) THEN
    RAISE EXCEPTION USING MESSAGE = 'ACTOR_NOT_FOUND_OR_INACTIVE';
  END IF;

  SELECT t.*
    INTO v_requested
  FROM public.timesheets AS t
  WHERE t.timesheet_id = p_timesheet_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'kind', 'STANDARD_DELETE',
      'decision', 'BLOCKED',
      'eligible', false,
      'blockers', jsonb_build_array(jsonb_build_object('code', 'TARGET_NOT_FOUND')),
      'blocked_reasons', jsonb_build_array(jsonb_build_object('code', 'TARGET_NOT_FOUND')),
      'timesheet_ids', '[]'::jsonb,
      'contract_week_ids', '[]'::jsonb,
      'nhsp_shift_ids', '[]'::jsonb,
      'preserved_source_timesheet_ids', '[]'::jsonb,
      'preserved_source_contract_week_ids', '[]'::jsonb,
      'retention_reasons', '[]'::jsonb,
      'advance', jsonb_build_object(
        'active', false,
        'clearable', false,
        'consumed', false,
        'historical', false
      )
    );
  END IF;

  SELECT t.*
    INTO v_current
  FROM public.timesheets AS t
  WHERE t.booking_id = v_requested.booking_id
    AND t.is_current = true
  ORDER BY t.version DESC NULLS LAST,
           t.updated_at DESC NULLS LAST,
           t.created_at DESC NULLS LAST,
           t.timesheet_id DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'kind', 'STANDARD_DELETE',
      'decision', 'BLOCKED',
      'eligible', false,
      'requested_timesheet_id', p_timesheet_id,
      'blockers', jsonb_build_array(jsonb_build_object('code', 'CURRENT_TIMESHEET_NOT_FOUND')),
      'blocked_reasons', jsonb_build_array(jsonb_build_object('code', 'CURRENT_TIMESHEET_NOT_FOUND')),
      'timesheet_ids', '[]'::jsonb,
      'contract_week_ids', '[]'::jsonb,
      'nhsp_shift_ids', '[]'::jsonb,
      'preserved_source_timesheet_ids', '[]'::jsonb,
      'preserved_source_contract_week_ids', '[]'::jsonb,
      'retention_reasons', '[]'::jsonb,
      'advance', jsonb_build_object(
        'active', false,
        'clearable', false,
        'consumed', false,
        'historical', false
      )
    );
  END IF;

  -- Import-authoritative changed-hours members are one exact two-row removal
  -- unit.  Resolve the requested correction generation, never the wider Weekly
  -- parent chain or a neighbouring generation.
  v_class:=public._ctms_import_correction_classify_v1(v_current.timesheet_id);
  IF COALESCE((v_class->>'is_import_authoritative_correction')::boolean,false) THEN
    v_chain:=public.timesheet_correction_chain_scope_v1(v_current.timesheet_id,false,32,100);
    v_unit:=v_chain->'requested_correction_unit';
    IF COALESCE((v_chain->>'valid')::boolean,false) IS TRUE
       AND COALESCE((v_unit->>'valid')::boolean,false) IS TRUE
       AND v_unit->>'correction_shape'='REVERSAL_REPLACEMENT'
       AND COALESCE((v_unit->>'expected_member_count')::integer,0)=2 THEN
      SELECT COALESCE(array_agg(value::uuid ORDER BY value::uuid),ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM jsonb_array_elements_text(v_unit->'member_ids') member(value);
      v_is_correction_pair:=cardinality(v_timesheet_ids)=2;
      v_pair_fingerprint:=public._import_review_hash_v1(concat_ws('|',
        'correction-pair-removal-v1',v_chain->>'chain_fingerprint',v_unit->>'correction_id',
        array_to_string(v_timesheet_ids,',')));
    ELSE
      -- Archived pairs are intentionally excluded from some active-chain
      -- projections.  Their exact durable correction identity remains enough
      -- to support an atomic Unarchive preview, but never a guessed role.
      SELECT COALESCE(array_agg(t.timesheet_id ORDER BY t.timesheet_id),ARRAY[]::uuid[])
      INTO v_timesheet_ids
      FROM public.timesheets t
      WHERE t.correction_id=v_current.correction_id AND t.is_current
        AND t.correction_kind IN ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT');
      IF cardinality(v_timesheet_ids)=2
         AND (SELECT count(*) FROM public.timesheets t WHERE t.timesheet_id=ANY(v_timesheet_ids)
                AND t.correction_kind='CHANGED_HOURS_REVERSAL')=1
         AND (SELECT count(*) FROM public.timesheets t WHERE t.timesheet_id=ANY(v_timesheet_ids)
                AND t.correction_kind='CHANGED_HOURS_REPLACEMENT')=1 THEN
        v_is_correction_pair:=true;
        v_unit:=jsonb_build_object('valid',true,'correction_id',v_current.correction_id,
          'correction_shape','REVERSAL_REPLACEMENT','expected_member_count',2,
          'member_ids',to_jsonb(v_timesheet_ids));
        v_pair_fingerprint:=public._import_review_hash_v1(concat_ws('|',
          'correction-pair-removal-v1',v_current.correction_id,array_to_string(v_timesheet_ids,',')));
      ELSE
        v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object(
          'code','CORRECTION_PAIR_MALFORMED','detail',v_chain));
      END IF;
    END IF;
  END IF;
  IF NOT v_is_correction_pair THEN
    -- Ordinary and non-authoritative paths keep the installed single-row unit.
    v_timesheet_ids:=ARRAY[v_current.timesheet_id]::uuid[];
  END IF;

  SELECT COALESCE(array_agg(DISTINCT cw.id ORDER BY cw.id), ARRAY[]::uuid[])
    INTO v_contract_week_ids
  FROM public.contract_weeks AS cw
  WHERE cw.timesheet_id = ANY(v_timesheet_ids);

  SELECT cw.id INTO v_primary_contract_week_id
  FROM public.contract_weeks cw
  WHERE cw.timesheet_id=v_current.timesheet_id
  ORDER BY cw.id LIMIT 1;

  SELECT COALESCE(array_agg(DISTINCT nhsp_shift.id ORDER BY nhsp_shift.id), ARRAY[]::uuid[])
    INTO v_nhsp_shift_ids
  FROM public.nhsp_shifts AS nhsp_shift
  WHERE nhsp_shift.timesheet_id = ANY(v_timesheet_ids);

  SELECT COALESCE(array_agg(DISTINCT source_contract_week.id ORDER BY source_contract_week.id), ARRAY[]::uuid[])
    INTO v_preserved_source_contract_week_ids
  FROM public.contract_weeks AS target_contract_week
  JOIN public.contract_weeks AS source_contract_week
    ON source_contract_week.contract_id = target_contract_week.contract_id
   AND source_contract_week.week_ending_date = target_contract_week.week_ending_date
   AND COALESCE(source_contract_week.additional_seq, 0) = 0
   AND COALESCE(source_contract_week.is_adjustment, false) = false
  WHERE target_contract_week.id = ANY(v_contract_week_ids)
    AND source_contract_week.id <> ALL(v_contract_week_ids);

  SELECT COALESCE(array_agg(DISTINCT preserved_row.preserved_timesheet_id ORDER BY preserved_row.preserved_timesheet_id), ARRAY[]::uuid[])
    INTO v_preserved_source_timesheet_ids
  FROM (
    SELECT source_contract_week.timesheet_id AS preserved_timesheet_id
    FROM public.contract_weeks AS source_contract_week
    WHERE source_contract_week.id = ANY(v_preserved_source_contract_week_ids)
      AND source_contract_week.timesheet_id IS NOT NULL

    UNION

    SELECT target_timesheet.parent_timesheet_id AS preserved_timesheet_id
    FROM public.timesheets AS target_timesheet
    WHERE target_timesheet.timesheet_id = ANY(v_timesheet_ids)
      AND target_timesheet.parent_timesheet_id IS NOT NULL
  ) AS preserved_row
  WHERE preserved_row.preserved_timesheet_id IS NOT NULL
    AND preserved_row.preserved_timesheet_id <> ALL(v_timesheet_ids);

  IF p_expected_timesheet_id IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_TIMESHEET_ID_REQUIRED',
      'current_timesheet_id', v_current.timesheet_id,
      'message', 'The current Timesheet identity is required. Refresh before continuing.'
    ));
  ELSIF p_expected_timesheet_id IS DISTINCT FROM v_current.timesheet_id THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_TIMESHEET_MISMATCH',
      'expected_timesheet_id', p_expected_timesheet_id,
      'current_timesheet_id', v_current.timesheet_id
    ));
  END IF;

  v_signature_payload := public.timesheet_lifecycle_guard_signature_v1(
    v_current.timesheet_id,
    v_primary_contract_week_id,
    false
  );
  v_current_signature := NULLIF(BTRIM(COALESCE(
    v_signature_payload ->> 'backend_row_signature',
    v_signature_payload ->> 'row_signature',
    v_signature_payload ->> 'signature',
    ''
  )), '');

  IF NULLIF(BTRIM(COALESCE(p_expected_row_signature, '')), '') IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'EXPECTED_ROW_SIGNATURE_REQUIRED',
      'current_row_signature', v_current_signature,
      'message', 'The current Timesheet lifecycle signature is required. Refresh before continuing.'
    ));
  ELSIF v_current_signature IS DISTINCT FROM BTRIM(p_expected_row_signature) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'ROW_SIGNATURE_MISMATCH',
      'expected_row_signature', BTRIM(p_expected_row_signature),
      'current_row_signature', v_current_signature
    ));
  END IF;

  IF NOT v_is_correction_pair AND v_current.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum THEN
    IF COALESCE(v_current.is_adjustment, false)
       OR EXISTS (
         SELECT 1
         FROM public.contract_weeks AS cw
         WHERE cw.timesheet_id = v_current.timesheet_id
           AND (COALESCE(cw.is_adjustment, false) OR COALESCE(cw.additional_seq, 0) > 0)
       ) THEN
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'WEEKLY_MANUAL_ADJUSTMENT_PREVIEW_REQUIRED'
      ));
    ELSE
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'WEEKLY_CHAIN_PREVIEW_REQUIRED'
      ));
    END IF;
  END IF;

  IF NOT v_is_correction_pair AND private.timesheet_correction_cancel_capability_v1(v_current.timesheet_id,p_actor_user_id) is null AND (UPPER(COALESCE(v_current.adjustment_origin, '')) IN ('IMPORT_CORRECTION', 'IMPORT_CANCELLATION')
     OR NULLIF(BTRIM(COALESCE(v_current.correction_kind, '')), '') IS NOT NULL
     OR v_current.correction_id IS NOT NULL) THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'IMPORT_DERIVED_CHILD',
      'message', 'Import-derived children must be handled through the parent-chain removal path.'
    ));
  END IF;

  IF v_is_correction_pair THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'timesheet_id',t.timesheet_id,'correction_kind',t.correction_kind,
      'signed_hours',COALESCE(tf.hours_day,0)+COALESCE(tf.hours_night,0)+COALESCE(tf.hours_sat,0)+COALESCE(tf.hours_sun,0)+COALESCE(tf.hours_bh,0),
      'authorised',t.authorised_at_server IS NOT NULL OR tf.authorised_at_utc IS NOT NULL,
      'invoice_linked',EXISTS(SELECT 1 FROM public.invoice_lines il WHERE il.timesheet_id=t.timesheet_id),
      'paid',tf.paid_at_utc IS NOT NULL,'archived',t.archived_at_utc IS NOT NULL)
      ORDER BY CASE t.correction_kind WHEN 'CHANGED_HOURS_REVERSAL' THEN 1 ELSE 2 END),'[]'::jsonb),
      COALESCE(sum(COALESCE(tf.hours_day,0)+COALESCE(tf.hours_night,0)+COALESCE(tf.hours_sat,0)+COALESCE(tf.hours_sun,0)+COALESCE(tf.hours_bh,0)),0)
    INTO v_pair_members,v_pair_net_hours
    FROM public.timesheets t
    LEFT JOIN public.timesheets_financials tf ON tf.timesheet_id=t.timesheet_id AND tf.is_current=true
    WHERE t.timesheet_id=ANY(v_timesheet_ids);

    IF (SELECT count(*) FROM public.timesheets t WHERE t.timesheet_id=ANY(v_timesheet_ids)
          AND t.archived_at_utc IS NOT NULL)=1 THEN
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','CORRECTION_PAIR_PARTIAL_ARCHIVE'));
    END IF;
    IF EXISTS(SELECT 1 FROM public.timesheets t LEFT JOIN public.timesheets_financials tf
        ON tf.timesheet_id=t.timesheet_id AND tf.is_current=true
      WHERE t.timesheet_id=ANY(v_timesheet_ids)
        AND (t.authorised_at_server IS NOT NULL OR tf.authorised_at_utc IS NOT NULL)) THEN
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','CORRECTION_PAIR_MUST_BE_UNAUTHORISED'));
    END IF;
    IF EXISTS(
      SELECT 1 FROM public.timesheets later
      WHERE later.is_current AND later.archived_at_utc IS NULL
        AND later.adjustment_origin='IMPORT_CORRECTION'
        AND later.parent_timesheet_id=(
          SELECT replacement.timesheet_id FROM public.timesheets replacement
          WHERE replacement.timesheet_id=ANY(v_timesheet_ids)
            AND replacement.correction_kind='CHANGED_HOURS_REPLACEMENT' LIMIT 1)
        AND later.timesheet_id<>ALL(v_timesheet_ids)
    ) THEN
      v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','CORRECTION_PAIR_HAS_LATER_GENERATION'));
    END IF;
  END IF;

  v_history := public.timesheet_removal_financial_history_v1(
    v_timesheet_ids,
    ARRAY[v_current.booking_id]::text[],
    v_contract_week_ids
  );

  v_blockers := v_blockers || COALESCE(v_history -> 'blockers', '[]'::jsonb);

  IF jsonb_array_length(v_blockers) > 0 THEN
    v_decision := 'BLOCKED';
  ELSIF COALESCE((v_history ->> 'archive_required')::boolean, false) THEN
    v_decision := 'ARCHIVE_REQUIRED';
  ELSE
    v_decision := 'PERMANENT_DELETE';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'kind', 'STANDARD_DELETE',
    'decision', v_decision,
    'eligible', v_decision = 'PERMANENT_DELETE',
    'requested_timesheet_id', p_timesheet_id,
    'current_timesheet_id', v_current.timesheet_id,
    'was_stale', v_current.timesheet_id IS DISTINCT FROM p_timesheet_id,
    'booking_id', v_current.booking_id,
    'timesheet_ids', to_jsonb(v_timesheet_ids),
    'contract_week_ids', to_jsonb(v_contract_week_ids),
    'nhsp_shift_ids', to_jsonb(v_nhsp_shift_ids),
    'preserved_source_timesheet_ids', to_jsonb(v_preserved_source_timesheet_ids),
    'preserved_source_contract_week_ids', to_jsonb(v_preserved_source_contract_week_ids),
    'blockers', v_blockers,
    'blocked_reasons', v_blockers,
    'retention_reasons', COALESCE(v_history -> 'retention_reasons', '[]'::jsonb),
    'advance', COALESCE(v_history -> 'advance', '{}'::jsonb),
    'current_row_signature', v_current_signature,
    'correction_pair',v_is_correction_pair,
    'source_system',CASE WHEN v_is_correction_pair THEN CASE
      WHEN upper(coalesce(
        v_current.candidate_hint_text#>>'{correction_financials_policy_envelope,classification,source_system}',
        v_current.adjustment_origin,'')) like 'NHSP%' THEN 'NHSP'
      ELSE 'HEALTHROSTER' END END,
    'correction_id',CASE WHEN v_is_correction_pair THEN v_unit->>'correction_id' END,
    'pair_timesheet_ids',CASE WHEN v_is_correction_pair THEN to_jsonb(v_timesheet_ids) ELSE '[]'::jsonb END,
    'pair_fingerprint',v_pair_fingerprint,
    'members',CASE WHEN v_is_correction_pair THEN v_pair_members ELSE '[]'::jsonb END,
    'pair_net_position',CASE WHEN v_is_correction_pair THEN jsonb_build_object('hours',v_pair_net_hours) ELSE NULL END,
    'resulting_financial_position',CASE WHEN v_is_correction_pair THEN jsonb_build_object('pair_removed_hours',v_pair_net_hours) ELSE NULL END
  );
END;
$function$;

create or replace function public.timesheet_delete_with_pending_expense_apply_v1(
  p_environment text,
  p_delete_kind text,
  p_timesheet_id uuid,
  p_actor_user_id uuid,
  p_expected_timesheet_id uuid,
  p_expected_row_signature text,
  p_expected_timesheet_ids uuid[],
  p_expected_contract_week_ids uuid[],
  p_expected_nhsp_shift_ids uuid[],
  p_expected_preserved_source_timesheet_ids uuid[],
  p_expected_preserved_source_contract_week_ids uuid[],
  p_expected_pending_expense_context_sha256 text,
  p_delete_operation_id uuid,
  p_now_utc timestamptz default now()
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_environment text:=private._candidate_assert_environment(p_environment);
  v_kind text:=upper(btrim(coalesce(p_delete_kind,'')));
  v_context jsonb;
  v_claim jsonb;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_cancel_result jsonb;
  v_cancel_results jsonb:='[]'::jsonb;
  v_notification_id uuid;
  v_notification_ids uuid[]:=array[]::uuid[];
  v_settings jsonb;
  v_template jsonb;
  v_terminal_mail jsonb;
  v_apply_result jsonb;
  v_delete_candidate_ids uuid[]:=array[]::uuid[];
  v_delete_candidate_id uuid;
  v_candidate_lock_key bigint;
  v_banking_dirty_result jsonb:='{}'::jsonb;
begin
  if p_actor_user_id is null or p_timesheet_id is null or p_expected_timesheet_id is null
     or p_delete_operation_id is null or nullif(btrim(coalesce(p_expected_row_signature,'')),'') is null
     or coalesce(p_expected_pending_expense_context_sha256,'') !~ '^[0-9a-f]{64}$'
     or v_kind not in (
       'STANDARD_DELETE','DAILY_ABANDONED_RECEIPT_DELETE',
       'WEEKLY_CHAIN_DELETE_PARENT','WEEKLY_MANUAL_ADJUSTMENT_DELETE'
     ) then
    raise exception 'PENDING_EXPENSE_DELETE_APPLY_INVALID' using errcode='22023';
  end if;

  perform 1
  from public.timesheets delete_timesheet
  where delete_timesheet.timesheet_id=any(p_expected_timesheet_ids)
  order by delete_timesheet.timesheet_id
  for update;

  v_context:=private._timesheet_pending_expense_delete_context_v1(
    v_environment,p_expected_timesheet_ids,true
  );
  if lower(v_context->>'context_sha256') is distinct from
       lower(p_expected_pending_expense_context_sha256) then
    raise exception 'PENDING_EXPENSE_DELETE_CONTEXT_CHANGED'
      using errcode='40001',detail=v_context::text;
  end if;
  if coalesce((v_context->>'delete_blocked')::boolean,false) then
    raise exception 'PENDING_EXPENSE_DELETE_BLOCKED'
      using errcode='55000',detail=v_context::text;
  end if;

  -- Every supported removal unit belongs to one Candidate. Capture and lock
  -- that owner while the Timesheets still exist so deletion cannot leave a
  -- stale Banking Pay view or try to validate a Timesheet after it is gone.
  select coalesce(array_agg(distinct owner.candidate_id order by owner.candidate_id),array[]::uuid[])
  into v_delete_candidate_ids
  from (
    select contract_row.candidate_id
    from public.timesheets timesheet_row
    join public.contracts contract_row on contract_row.id=timesheet_row.contract_id
    where timesheet_row.timesheet_id=any(p_expected_timesheet_ids)
    union all
    select financial_row.candidate_id
    from public.timesheets_financials financial_row
    where financial_row.timesheet_id=any(p_expected_timesheet_ids)
      and financial_row.is_current
    union all
    select request.candidate_id from private.timesheet_correction_requests request
    where request.replacement_timesheet_id=any(p_expected_timesheet_ids)
      and private.timesheet_correction_cancel_capability_v1(request.replacement_timesheet_id,p_actor_user_id) is not null
  ) owner
  where owner.candidate_id is not null;
  if cardinality(v_delete_candidate_ids)<>1 then
    raise exception 'TIMESHEET_DELETE_CANDIDATE_OWNERSHIP_INVALID'
      using errcode='23514',detail=jsonb_build_object(
        'candidate_count',cardinality(v_delete_candidate_ids)
      )::text;
  end if;
  v_delete_candidate_id:=v_delete_candidate_ids[1];
  v_candidate_lock_key:=pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(v_delete_candidate_id),24062027
  );
  perform pg_catalog.pg_advisory_xact_lock(v_candidate_lock_key);

  if coalesce((v_context->>'cancellation_required')::boolean,false) then
    v_settings:=public.candidate_manager_email_settings_get_v1();
    v_template:=v_settings#>'{templates,EXPENSE_CLAIM,CANCELLATION}';
    v_terminal_mail:=jsonb_build_object(
      'subject',v_template->>'subject',
      'body_text',v_template->>'body_text',
      'body_html',v_template->>'body_html',
      'manager_template_version',v_settings->'version',
      'manager_template_sha256',v_settings->>'semantic_sha256_hex',
      'manager_submission_type','EXPENSE_CLAIM'
    );
  end if;

  for v_claim in
    select value from jsonb_array_elements(coalesce(
      v_context->'pending_expense_claims','[]'::jsonb
    )) items(value)
  loop
    select workflow_row.* into strict v_workflow
    from public.candidate_submission_workflows workflow_row
    where workflow_row.id=(v_claim->>'workflow_id')::uuid
      and workflow_row.generation=(v_claim->>'generation')::integer
      and workflow_row.environment=v_environment
      and workflow_row.workflow_kind='CONTRACT_EXPENSE'
      and workflow_row.target_timesheet_id is null
    for update;

    perform 1 from public.candidate_notifications notification
    where notification.workflow_id=v_workflow.id
       or notification.timesheet_id=any(p_expected_timesheet_ids)
    order by notification.id
    for update;

    perform private._candidate_office_service_context_open_v1(
      v_environment,p_actor_user_id,'delete_timesheet','CANCEL',p_now_utc
    );
    v_cancel_result:=public.candidate_workflow_cancel_atomic_v2(
      null,v_environment,v_workflow.id,v_workflow.generation,
      jsonb_build_object(
        'service_office_action',true,
        'actor_user_id',p_actor_user_id,
        'reason_note','Pending expense claim cancelled because its Timesheet was deleted.',
        'reason_code','TIMESHEET_DELETED',
        'manager_terminal_mail',v_terminal_mail
      ),
      'office-timesheet-delete:'||p_delete_operation_id::text||':'||v_workflow.id::text,
      p_now_utc
    );
    perform private._candidate_office_service_context_close_v1();

    update public.candidate_submission_components component
    set timesheet_id=null
    where component.workflow_id=v_workflow.id
      and component.timesheet_id=any(p_expected_timesheet_ids);

    update public.candidate_notifications notification
    set timesheet_id=null,
        deep_link_json=(coalesce(notification.deep_link_json,'{}'::jsonb)
          -'timesheet_id'-'contract_week_id')||jsonb_build_object(
            'type','workflow','workflow_id',v_workflow.id
          ),
        state='DISMISSED',
        dismissed_at_utc=coalesce(notification.dismissed_at_utc,p_now_utc),
        push_state=case
          when notification.push_state in ('PENDING','FAILED','CLAIMED') then 'SKIPPED'
          else notification.push_state
        end
    where notification.workflow_id=v_workflow.id;

    update public.candidate_submission_workflows workflow_row
    set contract_week_id=null,
        anchor_timesheet_id=null,
        target_timesheet_id=null,
        input_snapshot_json=coalesce(workflow_row.input_snapshot_json,'{}'::jsonb)
          ||jsonb_build_object(
            'office_permanent_delete_tombstone',jsonb_build_object(
              'delete_operation_id',p_delete_operation_id,
              'deleted_timesheet_ids',to_jsonb(p_expected_timesheet_ids),
              'deleted_contract_week_ids',to_jsonb(p_expected_contract_week_ids),
              'previous_contract_week_id',v_workflow.contract_week_id,
              'previous_anchor_timesheet_id',v_workflow.anchor_timesheet_id,
              'previous_target_timesheet_id',v_workflow.target_timesheet_id,
              'retired_at_utc',p_now_utc
            )
          ),
        issue_codes=(case
          when workflow_row.issue_codes @> '["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
            then workflow_row.issue_codes
          else workflow_row.issue_codes||'["OFFICE_TIMESHEET_DELETED_EXPENSE_CANCELLED"]'::jsonb
        end)||(case
          when workflow_row.issue_codes @> '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
            then '[]'::jsonb
          else '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb
        end),
        updated_at_utc=p_now_utc
    where workflow_row.id=v_workflow.id
      and workflow_row.state='CANCELLED'
      and workflow_row.target_timesheet_id is null;
    if not found then
      raise exception 'PENDING_EXPENSE_CANCELLATION_NOT_PROVEN' using errcode='40001';
    end if;

    insert into public.candidate_notifications(
      account_id,candidate_id,workflow_id,timesheet_id,event_type,preference_category,
      template_key,template_params,deep_link_json,state,push_state,dedupe_key,created_at_utc
    )
    select
      v_workflow.account_id,v_workflow.candidate_id,v_workflow.id,null,
      'EXPENSE_CLAIM_CANCELLED','timesheet_expense_attention',
      'candidate-expense-claim-cancelled-timesheet-delete-v1',
      jsonb_build_object(
        'workflow_id',v_workflow.id,
        'reason_code','TIMESHEET_DELETED'
      ),
      jsonb_build_object('type','workflow','workflow_id',v_workflow.id),
      'UNREAD',
      case
        when account.status='ACTIVE'
          and coalesce((account.notification_preferences_json->>'push')::boolean,true)
          and coalesce(
            (account.notification_preferences_json->>'timesheet_expense_attention')::boolean,
            (account.notification_preferences_json->>'office_rejection')::boolean,
            true
          )
          then 'PENDING'
        else 'SKIPPED'
      end,
      'CANDIDATE_EXPENSE_CLAIM_CANCELLED_TIMESHEET_DELETE_V1:'
        ||v_workflow.id::text||':'||v_workflow.generation::text,
      p_now_utc
    from public.candidate_app_accounts account
    where account.id=v_workflow.account_id
    on conflict(dedupe_key) do update set dedupe_key=excluded.dedupe_key
    returning id into v_notification_id;

    v_notification_ids:=array_append(v_notification_ids,v_notification_id);
    v_cancel_results:=v_cancel_results||jsonb_build_array(jsonb_build_object(
      'workflow_id',v_workflow.id,
      'previous_generation',v_workflow.generation,
      'state','CANCELLED',
      'notification_id',v_notification_id,
      'cancellation',v_cancel_result
    ));
  end loop;

  -- The established Timesheet delete removes financial rows before the
  -- Timesheet. Suppress only the duplicate row-level delete signals for this
  -- one locked Candidate, then issue one complete Candidate refresh after the
  -- authoritative delete has been proved. This uses the existing sealed
  -- Banking Pay suppression boundary and changes no financial truth.
  if pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1') is not null then
    raise exception 'PAY_WORKBENCH_CANDIDATE_DELETE_CONTEXT_CONFLICT' using errcode='23514';
  end if;
  create temp table pg_temp._bpay_candidate_delete_context_v1(
    candidate_id uuid primary key,
    delete_operation_id uuid unique not null,
    candidate_lock_key bigint not null,
    backend_pid integer not null,
    transaction_id bigint not null,
    created_at_utc timestamptz not null,
    suppress boolean not null check(suppress)
  ) on commit drop;
  insert into pg_temp._bpay_candidate_delete_context_v1 values(
    v_delete_candidate_id,p_delete_operation_id,v_candidate_lock_key,
    pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),p_now_utc,true
  );

  if v_kind='STANDARD_DELETE' then
    v_apply_result:=public.timesheet_standard_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='DAILY_ABANDONED_RECEIPT_DELETE' then
    v_apply_result:=public.timesheet_daily_abandoned_receipt_delete_apply_v1(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_id,p_expected_row_signature
    );
  elsif v_kind='WEEKLY_CHAIN_DELETE_PARENT' then
    v_apply_result:=public.timesheet_weekly_chain_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_nhsp_shift_ids,p_expected_row_signature
    );
  else
    v_apply_result:=public.timesheet_weekly_manual_adjustment_delete_apply(
      p_timesheet_id,p_actor_user_id,p_expected_timesheet_ids,
      p_expected_contract_week_ids,p_expected_preserved_source_timesheet_ids,
      p_expected_preserved_source_contract_week_ids,p_expected_row_signature
    );
  end if;

  if coalesce((v_apply_result->>'apply_performed')::boolean,false) is not true
     or upper(coalesce(v_apply_result->>'decision',''))<>'PERMANENT_DELETE' then
    raise exception 'TIMESHEET_DELETE_AFTER_EXPENSE_CANCELLATION_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_apply_result,'{}'::jsonb)::text;
  end if;

  drop table pg_temp._bpay_candidate_delete_context_v1;
  v_banking_dirty_result:=public.pay_workbench_dirty_event_enqueue(
    p_job_type=>'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    p_scope_kind=>'CANDIDATE',
    p_scope_id=>v_delete_candidate_id::text,
    p_candidate_id=>v_delete_candidate_id,
    p_targeted_timesheet_ids=>array[]::uuid[],
    p_linked_timesheet_ids=>array[]::uuid[],
    p_payload_json=>jsonb_build_object(
      'trigger_table','timesheets',
      'trigger_op','DELETE',
      'trigger_operation','DELETE',
      'delete_operation_id',p_delete_operation_id,
      'deleted_timesheet_ids',coalesce(v_apply_result->'deleted_timesheet_ids','[]'::jsonb),
      'scope_resolution','CANDIDATE_FULL_AFTER_TIMESHEET_DELETE',
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
      'economic_truth_mutation_allowed',false
    ),
    p_reason=>'DIRTY_TRIGGER:TIMESHEETS:DELETE',
    p_priority=>-1000,
    p_run_at_utc=>p_now_utc
  );
  if coalesce((v_banking_dirty_result->>'ok')::boolean,false) is not true then
    raise exception 'TIMESHEET_DELETE_BANKING_REFRESH_NOT_PROVEN'
      using errcode='40001',detail=coalesce(v_banking_dirty_result,'{}'::jsonb)::text;
  end if;

  return v_apply_result||jsonb_build_object(
    'pending_expense_context_sha256',v_context->>'context_sha256',
    'cancelled_pending_expense_claim_count',jsonb_array_length(v_cancel_results),
    'cancelled_pending_expense_claims',v_cancel_results,
    'candidate_notification_ids',to_jsonb(v_notification_ids),
    'banking_pay_candidate_refresh',v_banking_dirty_result
  );
exception when others then
  perform private._candidate_office_service_context_close_v1();
  raise;
end;
$function$;

-- Final closure ACL: preserve audited existing grants; new private helpers
-- are owner-only and new public RPCs are service-only. Never rely on defaults.
alter function private.timesheet_correction_component_negate_v1(jsonb,text[]) OWNER TO CURRENT_USER;
alter function private.timesheet_correction_native_original_reversal_v1(jsonb,uuid) OWNER TO CURRENT_USER;
alter function private._candidate_timesheet_delete_retire_workflows_v1(text,uuid[],uuid[],uuid[],uuid,uuid,timestamptz) OWNER TO CURRENT_USER;
alter function private._timesheet_candidate_submission_delete_guard_v1(text,uuid[],boolean) OWNER TO CURRENT_USER;
alter function private._timesheet_cross_record_overlap_assert_v1(uuid,jsonb,jsonb,timestamptz,timestamptz,uuid,uuid,text) OWNER TO CURRENT_USER;
alter function private.timesheet_correction_actor_allowed_v1(uuid) OWNER TO CURRENT_USER;
alter function private.timesheet_correction_actor_assert_v1(uuid) OWNER TO CURRENT_USER;
