-- A scoped credit is a read of the approved request and persisted issued lines.
-- No live rate, recalculation, invoice updated_at or new financial identity is used.
create or replace function private.invoice_credit_scope_context_v1(
  p_invoice_id uuid,p_reversal_timesheet_id uuid,p_operation_id uuid default null,
  p_planned_credit_id uuid default null,p_lock_rows boolean default false
) returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_invoice public.invoices%rowtype; v_request private.timesheet_correction_requests%rowtype;
  v_r public.timesheets%rowtype; v_p public.timesheets%rowtype; v_fin public.timesheets_financials%rowtype;
  v_document public.invoice_document_versions%rowtype; v_input public.invoice_operation_chunks%rowtype;
  v_source jsonb; v_line_models jsonb; v_witness jsonb; v_revision text; v_count integer;
  v_net numeric; v_vat numeric; v_gross numeric; v_pay numeric; v_resume uuid;
  v_attach_hr boolean; v_attach_ts boolean; v_blocker text; v_lines jsonb;
begin
  if p_invoice_id is null or p_reversal_timesheet_id is null then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_INVALID');
  end if;
  if p_lock_rows then perform 1 from public.invoices i where i.id=p_invoice_id for update; end if;
  select i.* into v_invoice from public.invoices i where i.id=p_invoice_id;
  if v_invoice.id is null then return jsonb_build_object('valid',false,'blocker','INVOICE_NOT_FOUND'); end if;
  if v_invoice.type<>'INVOICE' then return jsonb_build_object('valid',false,'blocker','CREDIT_SOURCE_NOT_INVOICE'); end if;
  if v_invoice.status not in('ISSUED','PAID') then return jsonb_build_object('valid',false,'blocker','CREDIT_SOURCE_NOT_ISSUED'); end if;
  if p_lock_rows then perform 1 from private.timesheet_correction_requests request
    where request.reversal_timesheet_id=p_reversal_timesheet_id for update; end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where request.reversal_timesheet_id=p_reversal_timesheet_id and request.state='APPLIED'
      and request.original_invoice_id=p_invoice_id;
  select t.* into v_r from public.timesheets t where t.timesheet_id=p_reversal_timesheet_id;
  select t.* into v_p from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
  if v_request.id is null or v_r.correction_kind is distinct from 'WHOLE_TIMESHEET_REVERSAL'
    or v_r.adjustment_origin is distinct from v_request.origin
    or v_request.origin not in('AGENCY_INVOICE_CORRECTION','SIGNED_TIMESHEET_CORRECTION')
    or v_r.parent_timesheet_id is distinct from v_request.root_timesheet_id
    or v_p.correction_id is distinct from v_request.correction_id
    or v_p.correction_kind is distinct from 'WHOLE_TIMESHEET_REPLACEMENT'
    or v_p.adjustment_origin is distinct from v_request.origin then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_NOT_PRESET');
  end if;
  if p_lock_rows then
    perform 1 from public.timesheets t where t.timesheet_id in(v_r.timesheet_id,v_p.timesheet_id)
      order by t.timesheet_id for update;
    perform 1 from public.timesheets_financials tf where tf.timesheet_id in(v_r.timesheet_id,v_p.timesheet_id)
      and tf.is_current order by tf.timesheet_id,tf.id for update;
    select t.* into v_r from public.timesheets t where t.timesheet_id=p_reversal_timesheet_id;
    select t.* into v_p from public.timesheets t where t.timesheet_id=v_request.replacement_timesheet_id;
  end if;
  if v_r.is_current is distinct from true or v_p.is_current is distinct from true
    or v_r.authorised_at_server is null or v_p.authorised_at_server is null
    or (select count(*) from public.timesheets_financials tf where tf.is_current
      and tf.timesheet_id in(v_r.timesheet_id,v_p.timesheet_id) and tf.authorised_at_utc is not null)<>2 then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_UNIT_NOT_AUTHORISED');
  end if;
  select count(*)::integer,sum(l.total_charge_ex_vat),sum(l.vat_amount),sum(l.total_inc_vat),sum(l.total_pay_ex_vat),
    jsonb_agg(jsonb_build_object('line_id',l.id,'timesheet_id',l.timesheet_id,'booking_id',l.booking_id,
      'source_key',l.source_key,'net',l.total_charge_ex_vat,'vat',l.vat_amount,'gross',l.total_inc_vat,'pay',l.total_pay_ex_vat)
      order by l.id) into v_count,v_net,v_vat,v_gross,v_pay,v_lines
    from public.invoice_lines l where l.invoice_id=p_invoice_id and l.timesheet_id=v_request.reversed_timesheet_id;
  if v_count=0 then return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_TIMESHEET_NOT_ON_INVOICE'); end if;
  v_revision:=encode(digest(jsonb_build_object('invoice_id',p_invoice_id,'status',v_invoice.status,
    'lines',v_lines,'reversal_id',v_r.timesheet_id,'reversal_authorised',v_r.authorised_at_server,
    'replacement_id',v_p.timesheet_id,'replacement_authorised',v_p.authorised_at_server,
    'request_id',v_request.id,'request_state',v_request.state)::text,'sha256'),'hex');
  select own.credit_note_id into v_resume from private._invoice_credit_resume_v1(
    p_invoice_id,p_operation_id,p_planned_credit_id,p_reversal_timesheet_id) own;
  if exists(select 1 from public.invoices cn where cn.original_invoice_id=p_invoice_id and cn.type='CREDIT_NOTE'
    and cn.status in('DRAFT','ISSUED','PAID') and not(cn.header_snapshot_json?'credit_scope')) then
    v_blocker:='CREDIT_ALREADY_EXISTS';
  elsif v_resume is null and exists(select 1 from public.invoices cn join public.invoice_lines l on l.invoice_id=cn.id
    where cn.original_invoice_id=p_invoice_id and cn.type='CREDIT_NOTE' and cn.status in('DRAFT','ISSUED','PAID')
      and l.meta_json->>'reversal_timesheet_id'=p_reversal_timesheet_id::text) then
    v_blocker:='CREDIT_SCOPE_ALREADY_CREDITED';
  end if;
  if v_blocker is not null then return jsonb_build_object('valid',false,'blocker',v_blocker,'revision',v_revision); end if;
  select tf.* into v_fin from public.timesheets_financials tf where tf.timesheet_id=v_r.timesheet_id and tf.is_current;
  if v_resume is null and (v_fin.locked_by_invoice_id is not null or exists(select 1 from jsonb_array_elements(
    case when jsonb_typeof(v_fin.invoice_breakdown_json->'segments')='array' then v_fin.invoice_breakdown_json->'segments'
    else '[]'::jsonb end) s where nullif(s->>'invoice_locked_invoice_id','') is not null)) then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ALREADY_CREDITED','revision',v_revision);
  end if;
  v_attach_hr:=coalesce((v_invoice.header_snapshot_json#>>'{attach_policy,hr_attach_to_invoice}')::boolean,
    (v_invoice.header_snapshot_json#>>'{attachment_policy,hr_attach_to_invoice}')::boolean,true);
  v_attach_ts:=v_request.origin='SIGNED_TIMESHEET_CORRECTION' and coalesce(
    (v_invoice.header_snapshot_json#>>'{attach_policy,ts_attach_to_invoice}')::boolean,
    (v_invoice.header_snapshot_json#>>'{attachment_policy,ts_attach_to_invoice}')::boolean,true);
  if v_attach_hr and not exists(select 1 from public.invoice_hr_source_rows support
    where support.invoice_id=p_invoice_id and upper(support.source_system)='HEALTHROSTER'
      and jsonb_typeof(support.member_rows_json->v_request.reversed_timesheet_id::text)='array'
      and jsonb_array_length(support.member_rows_json->v_request.reversed_timesheet_id::text)>0) then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_SUPPORT_UNPROVED','revision',v_revision);
  end if;
  select d.* into v_document from public.invoice_document_versions d where d.id=v_invoice.issued_document_version_id
    and d.entity_type='INVOICE' and d.entity_id=p_invoice_id and d.purpose='FINAL_ISSUE'
    and d.status='READY' and d.verified_at_utc is not null;
  if v_document.id is null then return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_DOCUMENT_UNPROVED','revision',v_revision); end if;
  select count(*)::integer,min(source.value::text)::jsonb into v_count,v_source
    from jsonb_array_elements(case when jsonb_typeof(v_document.snapshot_json->'timesheet_sources')='array'
      then v_document.snapshot_json->'timesheet_sources' else '[]'::jsonb end) source(value)
    where source.value->>'timesheet_id'=v_request.reversed_timesheet_id::text;
  if v_count<>1 then return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_DOCUMENT_UNPROVED','revision',v_revision); end if;
  select jsonb_agg(model.value order by model.ordinality) into v_line_models
    from jsonb_array_elements(case when jsonb_typeof(v_document.snapshot_json#>'{presentation_model,lines}')='array'
      then v_document.snapshot_json#>'{presentation_model,lines}' else '[]'::jsonb end) with ordinality model(value,ordinality)
    where exists(select 1 from public.invoice_lines l where l.invoice_id=p_invoice_id
      and l.timesheet_id=v_request.reversed_timesheet_id and model.value->>'source_invoice_line_id'=l.id::text);
  if v_line_models is null or exists(select 1 from public.invoice_lines l where l.invoice_id=p_invoice_id
    and l.timesheet_id=v_request.reversed_timesheet_id and not exists(select 1 from jsonb_array_elements(v_line_models) m
      where m->>'source_invoice_line_id'=l.id::text)) then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_REFERENCES_UNPROVED','revision',v_revision);
  end if;
  if exists(select 1 from jsonb_array_elements(v_line_models) model
    where not pg_input_is_valid(model->>'net_amount','numeric')
      or not pg_input_is_valid(model->>'vat_amount','numeric') or not pg_input_is_valid(model->>'gross_amount','numeric')) then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_DOCUMENT_PENCE_MISMATCH','revision',v_revision);
  end if;
  if exists(select 1 from public.invoice_lines original left join lateral (
      select sum((model->>'net_amount')::numeric) net,sum((model->>'vat_amount')::numeric) vat,
        sum((model->>'gross_amount')::numeric) gross from jsonb_array_elements(v_line_models) model
        where model->>'source_invoice_line_id'=original.id::text
    ) frozen on true where original.invoice_id=p_invoice_id and original.timesheet_id=v_request.reversed_timesheet_id
      and (frozen.net is distinct from original.total_charge_ex_vat or frozen.vat is distinct from original.vat_amount
        or frozen.gross is distinct from original.total_inc_vat)) then
    return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_DOCUMENT_PENCE_MISMATCH','revision',v_revision);
  end if;
  if v_attach_ts then
    if v_source->>'submission_mode' is distinct from 'ELECTRONIC' then
      return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_SIGNED_ASSET_UNPROVED','revision',v_revision);
    end if;
    -- The selected input is T0's completed PDF inside the verified I1 graph,
    -- never the whole I1 bundle or a current Timesheet document fallback.
    select count(*)::integer into v_count from public.invoice_operation_chunks input
      where input.document_version_id=v_document.id and input.chunk_type='DOCUMENT_INPUT'
        and input.entity_type='TIMESHEET' and input.entity_id=v_request.reversed_timesheet_id
        and input.payload_json->>'input_type'='ELECTRONIC_TIMESHEET' and input.status='COMPLETE'
        and nullif(input.result_json->>'r2_key','') is not null
        and input.result_json->>'sha256'~'^[0-9a-f]{64}$' and input.actual_page_count>0 and input.actual_byte_count>0;
    if v_count<>1 then return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_SIGNED_ASSET_UNPROVED','revision',v_revision); end if;
    select input.* into v_input from public.invoice_operation_chunks input
      where input.document_version_id=v_document.id and input.chunk_type='DOCUMENT_INPUT'
        and input.entity_type='TIMESHEET' and input.entity_id=v_request.reversed_timesheet_id
        and input.payload_json->>'input_type'='ELECTRONIC_TIMESHEET' and input.status='COMPLETE';
    select count(*)::integer,(jsonb_agg(jsonb_build_object('workflow_id',manager.workflow_id,'workflow_generation',manager.workflow_generation,
      'approval_request_id',manager.approval_request_id,'manager_component_id',manager.id,'candidate_component_id',candidate.id,
      'manager_sha256',encode(manager.source_content_sha256,'hex'),'candidate_sha256',encode(candidate.source_content_sha256,'hex')))->0)
      into v_count,v_witness from public.candidate_submission_components manager
      join public.candidate_approval_requests approval on approval.id=manager.approval_request_id and approval.state='APPROVED'
      join public.candidate_submission_components candidate on candidate.workflow_id=manager.workflow_id
        and candidate.workflow_generation=manager.workflow_generation and candidate.document_role='CANDIDATE_SIGNATURE'
        and candidate.state='IMMUTABLE'
      where manager.document_role='MANAGER_SIGNATURE' and manager.state='IMMUTABLE'
        and manager.storage_key=v_source#>>'{render_model,signatures,authoriser,r2_key}'
        and encode(manager.source_content_sha256,'hex')=v_source#>>'{render_model,signatures,authoriser,sha256}'
        and candidate.storage_key=v_source#>>'{render_model,signatures,candidate,r2_key}'
        and encode(candidate.source_content_sha256,'hex')=v_source#>>'{render_model,signatures,candidate,sha256}'
        and approval.workflow_id=manager.workflow_id and approval.workflow_generation=manager.workflow_generation;
    if v_count<>1 or v_witness is null then return jsonb_build_object('valid',false,'blocker','CREDIT_SCOPE_ORIGINAL_SIGNED_WITNESS_UNPROVED','revision',v_revision); end if;
    v_source:=v_source||jsonb_build_object('input_document_version_id',v_document.id,
      'original_document_input_id',v_input.id,'original_document_input_result',v_input.result_json,
      'original_document_source_revision',v_input.payload_json->>'source_revision',
      'original_document_input_pages',v_input.actual_page_count,'original_document_input_bytes',v_input.actual_byte_count,
      'manager_signed_witness',v_witness);
  end if;
  v_source:=v_source||jsonb_build_object('attach_timesheet',v_attach_ts,
    'no_timesheet_required',v_request.origin='AGENCY_INVOICE_CORRECTION');
  return jsonb_build_object('valid',true,'revision',v_revision,'request_id',v_request.id,'correction_id',v_request.correction_id,
    'origin',v_request.origin,'root_timesheet_id',v_request.root_timesheet_id,'reversal_timesheet_id',v_r.timesheet_id,
    'reversed_timesheet_id',v_request.reversed_timesheet_id,'replacement_timesheet_id',v_p.timesheet_id,
    'resume_invoice_id',v_resume,'source_count',jsonb_array_length(v_lines),
    'subtotal_ex_vat',-v_net,'vat_amount',-v_vat,'total_inc_vat',-v_gross,'total_pay_ex_vat',-v_pay,
    'attach_hr',v_attach_hr,'attach_ts',v_attach_ts,'original_document_version_id',v_document.id,
    'frozen_timesheet_source',v_source,'frozen_line_models',v_line_models);
end;
$function$;

-- Exact additional authority for the existing batch validator. All native
-- financial/state/lock/VAT/member checks still run on the selected T0.
create or replace function private.timesheet_correction_scoped_source_identity_v1(p_scope jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_context jsonb; v_operation uuid; v_planned uuid;
begin
  if upper(coalesce(p_scope->>'validation_purpose',''))<>'CREDIT_SOURCE'
    or not pg_input_is_valid(p_scope#>>'{credit_scope,reversal_timesheet_id}','uuid')
    or not pg_input_is_valid(p_scope->>'invoice_id','uuid')
    or not pg_input_is_valid(p_scope->>'request_id','uuid')
    or not pg_input_is_valid(p_scope->>'operation_id','uuid')
    or not pg_input_is_valid(p_scope->>'planned_credit_note_id','uuid') then return null; end if;
  select request.* into v_request from private.timesheet_correction_requests request
    where request.id=(p_scope->>'request_id')::uuid and request.state='APPLIED'
      and request.reversal_timesheet_id=(p_scope#>>'{credit_scope,reversal_timesheet_id}')::uuid
      and request.original_invoice_id=(p_scope->>'invoice_id')::uuid
      and request.target_revision=p_scope->>'target_revision';
  if not found then return null; end if;
  v_operation:=(p_scope->>'operation_id')::uuid; v_planned:=(p_scope->>'planned_credit_note_id')::uuid;
  if not exists(select 1 from public.invoice_operations operation where operation.id=v_operation
    and operation.operation_type='GENERATE_CREDIT_NOTE' and operation.entity_type='INVOICE'
    and operation.entity_id=v_request.original_invoice_id
    and exists(select 1 from public.tms_users actor where actor.id=operation.actor_user_id and actor.is_active and lower(actor.role)='admin')) then
    return null;
  end if;
  v_context:=private.invoice_credit_scope_context_v1(v_request.original_invoice_id,v_request.reversal_timesheet_id,v_operation,v_planned,false);
  if (v_context->>'valid')::boolean is distinct from true then return null; end if;
  perform private.timesheet_correction_applied_assert_v1(v_request.id);
  perform private.timesheet_correction_reversal_assert_v1(
    coalesce(nullif(v_request.frozen_original_json->'financial_snapshot','null'::jsonb),
      (select to_jsonb(tf) from public.timesheets_financials tf where tf.timesheet_id=v_request.reversed_timesheet_id and tf.is_current)),
    (select to_jsonb(tf) from public.timesheets_financials tf where tf.timesheet_id=v_request.reversal_timesheet_id and tf.is_current));
  return jsonb_build_object('request_id',v_request.id,'timesheet_id',v_request.reversed_timesheet_id,'origin',v_request.origin,
    'root_timesheet_id',v_request.root_timesheet_id,'contract_id',v_request.contract_id,
    'sheet_scope',(select t.sheet_scope::text from public.timesheets t where t.timesheet_id=v_request.reversed_timesheet_id));
exception when sqlstate '23514' or sqlstate '55000' then return null;
end;
$function$;

create or replace function private.timesheet_correction_nullable_daily_contract_v1(p_scope jsonb,p_timesheet_id uuid)
returns boolean language plpgsql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
declare v_request private.timesheet_correction_requests%rowtype; v_scope jsonb; v_witness jsonb;
begin
  if upper(coalesce(p_scope->>'validation_purpose',''))='CREDIT_SOURCE' then
    v_scope:=private.timesheet_correction_scoped_source_identity_v1(p_scope);
    return v_scope->>'timesheet_id'=p_timesheet_id::text and v_scope->>'origin'='SIGNED_TIMESHEET_CORRECTION'
      and v_scope->>'contract_id' is null and v_scope->>'sheet_scope'='DAILY';
  end if;
  -- The only ordinary null-Contract exception is the exact finalized P0 of an
  -- APPLIED signed Daily request, not an ordinary Daily or forged WHOLE row.
  select request.* into v_request from private.timesheet_correction_requests request
    where request.replacement_timesheet_id=p_timesheet_id and request.state='APPLIED'
      and request.origin='SIGNED_TIMESHEET_CORRECTION' and request.contract_id is null;
  if not found or not exists(select 1 from public.timesheets t where t.timesheet_id=p_timesheet_id
    and t.sheet_scope='DAILY' and t.contract_id is null and t.is_current and t.correction_id=v_request.correction_id
    and t.correction_kind='WHOLE_TIMESHEET_REPLACEMENT' and t.parent_timesheet_id=v_request.root_timesheet_id) then return false; end if;
  perform private.timesheet_correction_applied_assert_v1(v_request.id);
  v_witness:=private.timesheet_correction_signed_witness_v1(p_timesheet_id,false);
  return v_witness->>'workflow_id'=v_request.workflow_id::text
    and v_witness->>'workflow_generation'=v_request.workflow_generation::text;
exception when sqlstate '23514' or sqlstate '55000' then return false;
end;
$function$;

create or replace function private._invoice_correction_validate_batch(
  p_scopes jsonb,
  p_evaluation_date date
) returns table(
  request_key text,
  scope_key text,
  invoice_id uuid,
  timesheet_id uuid,
  correction_classification text,
  correction_id text,
  correction_ids text[],
  required_member_ids uuid[],
  missing_member_ids uuid[],
  conflicting_invoice_ids uuid[],
  balanced boolean,
  valid boolean,
  blocker_code text,
  blocker_codes text[],
  detail_json jsonb
)
language sql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
with recursive scope_input as materialized (
  select e.ordinality::integer input_ordinal,e.value scope_json
  from jsonb_array_elements(case when jsonb_typeof(p_scopes)='array'
    then p_scopes else '[]'::jsonb end) with ordinality e(value,ordinality)
),
scopes as materialized (
  select
    coalesce(nullif(btrim(scope_json->>'request_key'),''),
      'correction:'||input_ordinal::text) request_key,
    coalesce(nullif(btrim(scope_json->>'scope_key'),''),
      nullif(btrim(scope_json->>'request_key'),''),
      'scope:'||input_ordinal::text) external_scope_key,
    coalesce(nullif(btrim(scope_json->>'request_key'),''),
      'correction:'||input_ordinal::text)||E'\\x1f'||
    coalesce(nullif(btrim(scope_json->>'scope_key'),''),
      nullif(btrim(scope_json->>'request_key'),''),
      'scope:'||input_ordinal::text) scope_key,
    case when coalesce(scope_json->>'invoice_id',
      scope_json->>'target_invoice_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then coalesce(scope_json->>'invoice_id',
        scope_json->>'target_invoice_id')::uuid end invoice_id,
    upper(coalesce(nullif(btrim(scope_json->>'validation_purpose'),''),
      'VALIDATE')) validation_purpose,
    case when coalesce(scope_json->>'expected_client_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(scope_json->>'expected_client_id')::uuid end expected_client_id,
    case when coalesce(scope_json->>'expected_contract_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(scope_json->>'expected_contract_id')::uuid end expected_contract_id,
    case when coalesce(scope_json->>'natural_source_week','')
      ~'^\\d{4}-\\d{2}-\\d{2}$'
      then(scope_json->>'natural_source_week')::date end natural_source_week,
    case when coalesce(scope_json->>'target_invoice_week','')
      ~'^\\d{4}-\\d{2}-\\d{2}$'
      then(scope_json->>'target_invoice_week')::date end target_invoice_week,
    nullif(upper(btrim(scope_json->>'expected_invoice_stream')),'')
      expected_invoice_stream,
    case when coalesce(scope_json->>'expected_vat_rate_pct','')
      ~'^[+-]?[0-9]+([.][0-9]+)?$'
      then(scope_json->>'expected_vat_rate_pct')::numeric end
      expected_vat_rate_pct,
    case when jsonb_typeof(scope_json->'planned_members')='array'
      then scope_json->'planned_members' else '[]'::jsonb end planned_members,
    scope_json
  from scope_input
),
planned_lines as materialized (
  select distinct s.scope_key,s.invoice_id,
    case when coalesce(x.value->>'timesheet_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x.value->>'timesheet_id')::uuid end timesheet_id,
    case when coalesce(x.value->>'vat_rate_pct','')
      ~'^[+-]?[0-9]+([.][0-9]+)?$'
      then(x.value->>'vat_rate_pct')::numeric
      else s.expected_vat_rate_pct end vat_rate_pct,
    nullif(btrim(coalesce(x.value->>'segment_id',
      x.value->>'segment_key')),'') segment_id
  from scopes s
  cross join lateral jsonb_array_elements(s.planned_members) x(value)
  where coalesce(x.value->>'timesheet_id','')~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
),
targets as materialized (
  select distinct s.invoice_id,s.scope_key,l.timesheet_id
  from scopes s
  join public.invoice_lines l on l.invoice_id=s.invoice_id
  where s.invoice_id is not null and l.timesheet_id is not null
    and (not(s.scope_json?'credit_scope') or l.timesheet_id::text=
      private.timesheet_correction_scoped_source_identity_v1(s.scope_json)->>'timesheet_id')
  union
  select p.invoice_id,p.scope_key,p.timesheet_id
  from planned_lines p
  where p.timesheet_id is not null
),
seed_units as materialized (
  select distinct t.correction_id,
    coalesce(t.candidate_hint_text->'correction_financials_policy_envelope',
      f.policy_snapshot_json->'correction_financials_policy_envelope',
      f.rate_source_refs_json->'correction_financials_policy_envelope')
      #>>'{operation,operation_id}' correction_operation_id,
    coalesce(t.candidate_hint_text->'correction_financials_policy_envelope',
      f.policy_snapshot_json->'correction_financials_policy_envelope',
      f.rate_source_refs_json->'correction_financials_policy_envelope')
      ->>'correction_chain_id' correction_chain_id
  from targets q
  join public.timesheets t on t.timesheet_id=q.timesheet_id
  left join public.timesheets_financials f
    on f.timesheet_id=t.timesheet_id and f.is_current
),all_current as materialized (
  select t.timesheet_id,t.correction_id,
    upper(btrim(coalesce(t.correction_kind,''))) correction_kind,
    upper(btrim(coalesce(t.adjustment_origin,''))) adjustment_origin,
    t.parent_timesheet_id,t.is_current,t.status::text timesheet_status,
    t.contract_id,t.week_ending_date,
    coalesce(f.client_id,c.client_id) client_id,
    f.id financial_id,f.processing_status::text processing_status,
    f.basis::text basis,f.total_charge_ex_vat,f.is_stale,f.stale_reason,
    f.total_hours,f.hours_day,f.hours_night,f.hours_sat,f.hours_sun,f.hours_bh,
    f.additional_pay_ex_vat,f.additional_charge_ex_vat,
    f.expenses_pay_ex_vat,f.expenses_charge_ex_vat,
    f.mileage_pay_ex_vat,f.mileage_charge_ex_vat,
    f.travel_pay_ex_vat,f.travel_charge_ex_vat,
    f.accommodation_pay_ex_vat,f.accommodation_charge_ex_vat,
    f.other_pay_ex_vat,f.other_charge_ex_vat,
    f.locked_by_invoice_id,f.invoice_breakdown_json,
    f.policy_snapshot_json,f.rate_source_refs_json,
    coalesce(
      t.candidate_hint_text->'correction_financials_policy_envelope',
      f.policy_snapshot_json->'correction_financials_policy_envelope',
      f.rate_source_refs_json->'correction_financials_policy_envelope') envelope
  from public.timesheets t
  left join public.timesheets_financials f
    on f.timesheet_id=t.timesheet_id and f.is_current
  left join public.contracts c on c.id=t.contract_id
  where exists(select 1 from targets q where q.timesheet_id=t.timesheet_id)
     or(t.correction_id is not null and exists(
       select 1 from seed_units u where u.correction_id=t.correction_id))
     or exists(
       select 1 from seed_units u
       where u.correction_operation_id is not null
         and u.correction_chain_id is not null
         and u.correction_operation_id=coalesce(
           t.candidate_hint_text->'correction_financials_policy_envelope',
           f.policy_snapshot_json->'correction_financials_policy_envelope',
           f.rate_source_refs_json->'correction_financials_policy_envelope')
             #>>'{operation,operation_id}'
         and u.correction_chain_id=coalesce(
           t.candidate_hint_text->'correction_financials_policy_envelope',
           f.policy_snapshot_json->'correction_financials_policy_envelope',
           f.rate_source_refs_json->'correction_financials_policy_envelope')
             ->>'correction_chain_id')
),
classified as materialized (
  select a.*,
    case
      when jsonb_typeof(a.envelope)='object'
      then encode(digest(convert_to(
        (a.envelope-'envelope_fingerprint')::text,'UTF8'),
        'sha256'),'hex')
    end recomputed_fingerprint,
    coalesce((authority.settings_json#>>'{values,is_nhsp}')::boolean,false) is_nhsp,
    coalesce((authority.settings_json#>>'{values,autoprocess_hr}')::boolean,false) autoprocess_hr,
    coalesce((authority.settings_json#>>'{values,no_timesheet_required}')::boolean,false) no_timesheet_required,
    coalesce((authority.settings_json#>>'{values,self_bill}')::boolean,false) self_bill,
    (a.adjustment_origin in(
        'IMPORT_CORRECTION','IMPORT_CANCELLATION',
        'HEALTHROSTER_CHANGED_HOURS','NHSP_CHANGED_HOURS',
        'HEALTHROSTER_CANCELLATION','NHSP_CANCELLATION')
      or a.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT',
        'CANCELLATION_REVERSAL','CANCELLATION_REPLACEMENT'))
      import_declared,
    coalesce(
      a.adjustment_origin in(
        'IMPORT_CORRECTION','IMPORT_CANCELLATION',
        'HEALTHROSTER_CHANGED_HOURS','NHSP_CHANGED_HOURS',
        'HEALTHROSTER_CANCELLATION','NHSP_CANCELLATION')
      and a.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT',
        'CANCELLATION_REVERSAL','CANCELLATION_REPLACEMENT')
      and jsonb_typeof(a.envelope)='object'
      and a.envelope->>'policy_schema_version'=
        'IMPORT_CORRECTION_FINANCIALS_POLICY_V2'
      and a.envelope->>'route_family'='IMPORT_AUTHORITATIVE'
      and lower(coalesce(a.envelope#>>'{classification,canonical}','false'))
        in('true','t','1','yes')
      and nullif(a.envelope#>>'{operation,operation_id}','') is not null
      and nullif(a.envelope->>'correction_chain_id','') is not null
      and a.envelope->>'envelope_fingerprint'=
        case
          when jsonb_typeof(a.envelope)='object'
          then encode(digest(convert_to(
            (a.envelope-'envelope_fingerprint')::text,'UTF8'),
            'sha256'),'hex')
        end
      and(
        (a.correction_kind like 'CHANGED_HOURS_%'
          and a.envelope#>>'{operation,correction_action}'='CHANGED_HOURS')
        or
        (a.correction_kind like 'CANCELLATION_%'
          and a.envelope#>>'{operation,correction_action}'='CANCELLATION')),
      false) authoritative
  from all_current a
  cross join lateral (
    select private._timesheet_settings_authority_frozen_v1(a.timesheet_id)
      as settings_json
  ) authority
),
policy_checked as materialized (
  select c.*,
    c.envelope#>>'{operation,operation_id}' correction_operation_id,
    c.envelope->>'correction_chain_id' correction_chain_id,
    c.envelope->>'root_timesheet_id' frozen_root_timesheet_id,
    upper(btrim(coalesce(c.envelope->>'correction_shape','')))
      correction_shape,
    case when coalesce(c.envelope->>'expected_member_count','')~'^[0-9]+$'
      then(c.envelope->>'expected_member_count')::integer end
      expected_member_count,
    c.envelope->'expected_member_roles' expected_member_roles,
    case
      when c.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CANCELLATION_REVERSAL')
        then 'REVERSAL'
      when c.correction_kind in(
        'CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
        then 'REPLACEMENT'
      else 'INVALID'
    end correction_role,
    case
      when c.correction_kind in(
        'CHANGED_HOURS_REVERSAL','CANCELLATION_REVERSAL')
        then c.envelope->'reversal'
      when c.correction_kind in(
        'CHANGED_HOURS_REPLACEMENT','CANCELLATION_REPLACEMENT')
        then c.envelope->'replacement'
    end correction_leg
  from classified c
),
policy_validated as materialized (
  select p.*,
    case when jsonb_typeof(p.correction_leg)='object'
      then encode(digest(convert_to(
        (p.correction_leg-'leg_fingerprint')::text,'UTF8'),'sha256'),'hex')
    end recomputed_leg_fingerprint,
    case when jsonb_typeof(p.correction_leg->'tsfin_policy')='object'
      then encode(digest(convert_to(
        ((p.correction_leg->'tsfin_policy')-'tsfin_policy_fingerprint')::text,
        'UTF8'),'sha256'),'hex')
    end recomputed_tsfin_policy_fingerprint,
    case when jsonb_typeof(p.correction_leg->'invoice_policy')='object'
      then encode(digest(convert_to(
        ((p.correction_leg->'invoice_policy')-'invoice_policy_fingerprint')::text,
        'UTF8'),'sha256'),'hex')
    end recomputed_invoice_policy_fingerprint,
    case
      when private._candidate_feature_enabled_current_v1(
        'candidate_expense_invoice_routing_v1'
      )
      and (
        abs(coalesce(p.total_hours,0))
        +abs(coalesce(p.hours_day,0))+abs(coalesce(p.hours_night,0))
        +abs(coalesce(p.hours_sat,0))+abs(coalesce(p.hours_sun,0))
        +abs(coalesce(p.hours_bh,0))
        +abs(coalesce(p.additional_pay_ex_vat,0))
        +abs(coalesce(p.additional_charge_ex_vat,0))
      )=0
      and (
        abs(coalesce(p.expenses_pay_ex_vat,0))
        +abs(coalesce(p.expenses_charge_ex_vat,0))
        +abs(coalesce(p.mileage_pay_ex_vat,0))
        +abs(coalesce(p.mileage_charge_ex_vat,0))
        +abs(coalesce(p.travel_pay_ex_vat,0))
        +abs(coalesce(p.travel_charge_ex_vat,0))
        +abs(coalesce(p.accommodation_pay_ex_vat,0))
        +abs(coalesce(p.accommodation_charge_ex_vat,0))
        +abs(coalesce(p.other_pay_ex_vat,0))
        +abs(coalesce(p.other_charge_ex_vat,0))
      )>0 then 'EXPENSE'
      when upper(coalesce(p.basis,'')) in(
        'NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL',
        'HEALTHROSTER_ADJUSTMENT'
      ) then 'SELF_BILL'
      when p.self_bill then 'SELF_BILL'
      else 'NORMAL'
    end current_invoice_stream
  from policy_checked p
),
policy_final as materialized (
  select p.*,
    (
      not p.import_declared
      or(
        jsonb_typeof(p.envelope)='object'
        and nullif(p.envelope->>'envelope_fingerprint','') is not null
        and p.envelope->>'envelope_fingerprint'=p.recomputed_fingerprint
        and p.correction_shape in('REVERSAL_ONLY','REVERSAL_REPLACEMENT')
        and p.expected_member_count between 1 and 100
        and jsonb_typeof(p.expected_member_roles)='array'
        and jsonb_array_length(p.expected_member_roles)=p.expected_member_count
        and nullif(p.correction_operation_id,'') is not null
        and nullif(p.correction_chain_id,'') is not null
        and jsonb_typeof(p.correction_leg)='object'
        and p.correction_leg->>'leg_fingerprint'
          =p.recomputed_leg_fingerprint
        and p.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
          =p.recomputed_tsfin_policy_fingerprint
        and p.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}'
          =p.recomputed_invoice_policy_fingerprint
        and p.correction_leg#>>'{invoice_policy,invoice_stream}'
          =p.envelope->>'invoice_stream'
        and p.current_invoice_stream=p.envelope->>'invoice_stream'
        and coalesce(
          p.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint',
          p.policy_snapshot_json#>>
            '{correction_financials_policy_envelope,envelope_fingerprint}',
          p.rate_source_refs_json->>'correction_financials_policy_envelope_fingerprint')
          is not distinct from p.envelope->>'envelope_fingerprint'
        and coalesce(
          p.policy_snapshot_json->>'correction_leg_fingerprint',
          p.rate_source_refs_json->>'correction_leg_fingerprint')
          is not distinct from p.correction_leg->>'leg_fingerprint'
        and coalesce(
          p.policy_snapshot_json->>'correction_tsfin_policy_fingerprint',
          p.rate_source_refs_json->>'correction_tsfin_policy_fingerprint')
          is not distinct from
            p.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
        and coalesce(
          p.policy_snapshot_json->>'correction_invoice_policy_fingerprint',
          p.rate_source_refs_json->>'correction_invoice_policy_fingerprint')
          is not distinct from
            p.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}'
        and p.policy_snapshot_json->'correction_invoice_policy'
          is not distinct from p.correction_leg->'invoice_policy'
        and upper(btrim(coalesce(
          p.policy_snapshot_json->>'correction_invoice_stream','')))
          is not distinct from p.envelope->>'invoice_stream'
      )
    ) frozen_policy_valid
  from policy_validated p
),
target_classes as materialized (
  select t.invoice_id,t.scope_key,t.timesheet_id,c.correction_id,
    c.correction_kind,c.import_declared,c.authoritative,c.envelope,c.client_id,c.contract_id,
    c.week_ending_date,c.basis,c.correction_operation_id,
    c.correction_chain_id
  from targets t
  join policy_final c on c.timesheet_id=t.timesheet_id
),
members as materialized (
  select tc.invoice_id,tc.scope_key,tc.timesheet_id target_timesheet_id,
    tc.correction_id,tc.correction_kind target_kind,
    tc.envelope target_envelope,
    m.timesheet_id,m.correction_kind,m.client_id,m.contract_id,
    m.week_ending_date,m.basis,m.financial_id,m.processing_status,
    m.is_stale,m.stale_reason,m.locked_by_invoice_id,
    m.invoice_breakdown_json,
    m.envelope,m.recomputed_fingerprint,m.is_nhsp,m.autoprocess_hr,
    m.no_timesheet_required,m.import_declared,m.authoritative,
    m.frozen_policy_valid,m.adjustment_origin,m.timesheet_status,
    m.policy_snapshot_json,m.rate_source_refs_json,
    m.recomputed_leg_fingerprint,m.recomputed_tsfin_policy_fingerprint,
    m.recomputed_invoice_policy_fingerprint,m.correction_role,m.correction_shape,m.expected_member_count,
    m.expected_member_roles,m.correction_operation_id,
    m.correction_chain_id,m.frozen_root_timesheet_id,
    m.current_invoice_stream,m.correction_leg
  from target_classes tc
  join policy_final m
    on m.timesheet_id=tc.timesheet_id
      or(
        tc.authoritative
        and m.authoritative
        and m.correction_operation_id=tc.correction_operation_id
        and m.correction_chain_id=tc.correction_chain_id)
      or(
        not tc.authoritative
        and tc.correction_kind not in('WHOLE_TIMESHEET_REVERSAL','WHOLE_TIMESHEET_REPLACEMENT')
        and tc.correction_id is not null
        and m.correction_id=tc.correction_id)
),
member_ancestors as (
  select m.scope_key,m.target_timesheet_id,m.timesheet_id member_timesheet_id,
    t.timesheet_id ancestor_id,t.parent_timesheet_id,0 depth,
    array[t.timesheet_id]::uuid[] path,false cycle
  from members m
  join public.timesheets t on t.timesheet_id=m.timesheet_id
  union all
  select a.scope_key,a.target_timesheet_id,a.member_timesheet_id,
    p.timesheet_id,p.parent_timesheet_id,a.depth+1,
    a.path||p.timesheet_id,p.timesheet_id=any(a.path)
  from member_ancestors a
  join public.timesheets p on p.timesheet_id=a.parent_timesheet_id
  where a.parent_timesheet_id is not null
    and not a.cycle and a.depth<32
),
member_roots as materialized (
  select distinct on(
      a.scope_key,a.target_timesheet_id,a.member_timesheet_id)
    a.scope_key,a.target_timesheet_id,a.member_timesheet_id,
    a.ancestor_id root_timesheet_id,a.cycle,
    a.depth=32 and a.parent_timesheet_id is not null depth_exceeded
  from member_ancestors a
  order by a.scope_key,a.target_timesheet_id,a.member_timesheet_id,
    a.depth desc,a.ancestor_id
),
rollup as materialized (
  select m.invoice_id,m.scope_key,m.target_timesheet_id timesheet_id,
    m.correction_id,
    bool_or(m.import_declared) import_declared,
    bool_or(m.authoritative) authoritative,
    array_agg(distinct m.timesheet_id order by m.timesheet_id) required_ids,
    count(*) filter(where m.financial_id is not null
      and upper(coalesce(m.processing_status,''))='READY_FOR_INVOICE') ready_count,
    count(*) filter(where m.financial_id is null) missing_financial_count,
    count(*) filter(where coalesce(m.is_stale,false)) stale_financial_count,
    count(*) filter(where m.financial_id is not null
      and upper(coalesce(m.processing_status,''))<>'READY_FOR_INVOICE')
      not_ready_financial_count,
    count(*) filter(where m.locked_by_invoice_id is not null
      and(m.invoice_id is null
        or m.locked_by_invoice_id<>m.invoice_id)) whole_lock_conflict_count,
    count(*) filter(where exists(
      select 1
      from jsonb_array_elements(case
        when jsonb_typeof(m.invoice_breakdown_json->'segments')='array'
          then m.invoice_breakdown_json->'segments'
        else '[]'::jsonb end) seg(value)
      where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is not null
        and(m.invoice_id is null
          or seg.value->>'invoice_locked_invoice_id'<>m.invoice_id::text)
        and(
          not exists(
            select 1 from planned_lines selected
            where selected.scope_key=m.scope_key
              and selected.timesheet_id=m.timesheet_id
              and selected.segment_id is not null)
          or seg.value->>'segment_id' in(
            select selected.segment_id from planned_lines selected
            where selected.scope_key=m.scope_key
              and selected.timesheet_id=m.timesheet_id
              and selected.segment_id is not null)))
    )
      segment_lock_conflict_count,
    count(distinct m.timesheet_id) member_count,
    count(distinct m.client_id) client_count,
    (min(m.client_id::text))::uuid member_client_id,
    count(distinct m.contract_id) contract_count,
    (min(m.contract_id::text))::uuid member_contract_id,
    count(distinct m.week_ending_date) week_count,
    min(m.week_ending_date) member_week,
    count(distinct case when upper(coalesce(m.basis,'')) in(
      'NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL',
      'HEALTHROSTER_ADJUSTMENT') then 'SELF_BILL' else 'NORMAL' end)
      stream_count,
    min(case when m.import_declared then m.envelope->>'invoice_stream'
      else m.current_invoice_stream end) expected_invoice_stream,
    count(*) filter(where m.correction_kind like '%_REVERSAL') reversal_count,
    count(*) filter(where m.correction_kind like '%_REPLACEMENT')
      replacement_count,
    bool_or(m.correction_kind like 'CHANGED_HOURS_%') changed_hours,
    bool_or(m.correction_kind like 'CANCELLATION_%') cancellation,
    bool_and(m.frozen_policy_valid) envelope_valid,
    count(*) filter(where m.import_declared
      and jsonb_typeof(m.envelope) is distinct from 'object')
      missing_envelope_count,
    count(*) filter(where m.import_declared
      and coalesce(m.envelope->>'policy_schema_version','')<>
        'IMPORT_CORRECTION_FINANCIALS_POLICY_V2') invalid_schema_count,
    count(*) filter(where m.import_declared
      and coalesce(m.envelope->>'route_family','')<>'IMPORT_AUTHORITATIVE')
      invalid_route_count,
    count(*) filter(where m.import_declared and(
      lower(coalesce(m.envelope#>>'{classification,canonical}','false'))
        not in('true','t','1','yes')
      or lower(coalesce(
        m.envelope#>>'{classification,client_eligible_at_operation}',
        'false')) not in('true','t','1','yes')
      or nullif(btrim(m.envelope#>>'{classification,source_system}'),'')
        is null)) invalid_classification_count,
    count(*) filter(where m.import_declared
      and nullif(m.envelope#>>'{operation,operation_id}','') is null)
      missing_operation_count,
    count(*) filter(where m.import_declared
      and nullif(m.envelope->>'correction_chain_id','') is null)
      missing_chain_count,
    count(*) filter(where m.import_declared and(
      (m.correction_kind like 'CHANGED_HOURS_%'
        and coalesce(m.envelope#>>'{operation,correction_action}','')<>
          'CHANGED_HOURS')
      or(m.correction_kind like 'CANCELLATION_%'
        and coalesce(m.envelope#>>'{operation,correction_action}','')<>
          'CANCELLATION'))) invalid_action_count,
    count(*) filter(where m.import_declared and(
      nullif(m.envelope->>'envelope_fingerprint','') is null
      or m.envelope->>'envelope_fingerprint'
        is distinct from m.recomputed_fingerprint)) envelope_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared
      and jsonb_typeof(m.correction_leg) is distinct from 'object')
      missing_leg_count,
    count(*) filter(where m.import_declared and(
      nullif(m.correction_leg->>'leg_fingerprint','') is null
      or m.correction_leg->>'leg_fingerprint'
        is distinct from m.recomputed_leg_fingerprint))
      leg_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      jsonb_typeof(m.correction_leg->'tsfin_policy') is distinct from 'object'
      or m.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}'
        is distinct from m.recomputed_tsfin_policy_fingerprint))
      tsfin_policy_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      jsonb_typeof(m.correction_leg->'invoice_policy')
        is distinct from 'object'
      or m.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}'
        is distinct from m.recomputed_invoice_policy_fingerprint))
      invoice_policy_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      m.correction_leg#>>'{invoice_policy,invoice_stream}'
        is distinct from m.envelope->>'invoice_stream'
      or m.current_invoice_stream
        is distinct from m.envelope->>'invoice_stream'))
      policy_stream_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_financials_policy_envelope_fingerprint',
      m.policy_snapshot_json#>>
        '{correction_financials_policy_envelope,envelope_fingerprint}',
      m.rate_source_refs_json->>
        'correction_financials_policy_envelope_fingerprint')
      is distinct from m.envelope->>'envelope_fingerprint')
      current_envelope_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_leg_fingerprint',
      m.rate_source_refs_json->>'correction_leg_fingerprint')
      is distinct from m.correction_leg->>'leg_fingerprint')
      current_leg_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_tsfin_policy_fingerprint',
      m.rate_source_refs_json->>'correction_tsfin_policy_fingerprint')
      is distinct from
        m.correction_leg#>>'{tsfin_policy,tsfin_policy_fingerprint}')
      current_tsfin_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and coalesce(
      m.policy_snapshot_json->>'correction_invoice_policy_fingerprint',
      m.rate_source_refs_json->>'correction_invoice_policy_fingerprint')
      is distinct from
        m.correction_leg#>>'{invoice_policy,invoice_policy_fingerprint}')
      current_invoice_fingerprint_mismatch_count,
    count(*) filter(where m.import_declared and(
      m.policy_snapshot_json->'correction_tsfin_policy'
        is distinct from m.correction_leg->'tsfin_policy'
      or m.policy_snapshot_json->'correction_invoice_policy'
        is distinct from m.correction_leg->'invoice_policy'))
      frozen_subpolicy_drift_count,
    count(distinct m.correction_operation_id)
      filter(where m.import_declared) correction_operation_count,
    count(distinct m.correction_chain_id)
      filter(where m.import_declared) correction_chain_count,
    count(distinct m.frozen_root_timesheet_id)
      filter(where m.import_declared) frozen_root_count,
    count(distinct mr.root_timesheet_id)
      filter(where m.import_declared) actual_root_count,
    bool_or(coalesce(mr.cycle,false)) chain_cycle,
    bool_or(coalesce(mr.depth_exceeded,false)) chain_depth_exceeded,
    bool_and(not m.import_declared
      or m.frozen_root_timesheet_id=mr.root_timesheet_id::text)
      frozen_root_matches,
    count(distinct m.envelope->>'envelope_fingerprint')
      filter(where m.import_declared) envelope_count,
    max(m.expected_member_count)
      filter(where m.import_declared) expected_member_count,
    count(distinct m.expected_member_count)
      filter(where m.import_declared) expected_count_variants,
    count(distinct m.correction_shape)
      filter(where m.import_declared) shape_variants,
    min(m.correction_shape)
      filter(where m.import_declared) correction_shape,
    coalesce(jsonb_agg(m.correction_role order by
      case m.correction_role when 'REVERSAL' then 1
        when 'REPLACEMENT' then 2 else 3 end,m.timesheet_id)
      filter(where m.import_declared),'[]'::jsonb) actual_member_roles,
    (min(m.expected_member_roles::text)
      filter(where m.import_declared))::jsonb expected_member_roles
  from members m
  left join member_roots mr on mr.scope_key=m.scope_key
    and mr.target_timesheet_id=m.target_timesheet_id
    and mr.member_timesheet_id=m.timesheet_id
  group by m.invoice_id,m.scope_key,m.target_timesheet_id,m.correction_id
),
candidate_lines as materialized (
  select distinct r.scope_key,r.invoice_id target_invoice_id,
    l.invoice_id line_invoice_id,l.timesheet_id,l.vat_rate_pct,
    false planned
  from rollup r
  join members m on m.scope_key=r.scope_key
    and m.target_timesheet_id=r.timesheet_id
  join public.invoice_lines l on l.timesheet_id=m.timesheet_id
  union all
  select p.scope_key,p.invoice_id,p.invoice_id,p.timesheet_id,p.vat_rate_pct,
    true
  from planned_lines p
  where not exists(
    select 1 from public.invoice_lines l
    where l.invoice_id=p.invoice_id and l.timesheet_id=p.timesheet_id)
),
line_scope as materialized (
  select r.invoice_id,r.scope_key,r.timesheet_id,
    array_agg(distinct l.timesheet_id order by l.timesheet_id)
      filter(where l.timesheet_id is not null and(
        l.planned or(
          r.invoice_id is not null and l.line_invoice_id=r.invoice_id)))
      present_ids,
    array_agg(distinct l.line_invoice_id order by l.line_invoice_id)
      filter(where not l.planned and(
        r.invoice_id is null or l.line_invoice_id<>r.invoice_id))
      conflicting_ids,
    count(distinct l.timesheet_id) filter(where l.timesheet_id is not null and(
      l.planned or(
        r.invoice_id is not null and l.line_invoice_id=r.invoice_id)))
      present_count,
    count(*) filter(where l.timesheet_id is not null and(
        l.planned or(
          r.invoice_id is not null and l.line_invoice_id=r.invoice_id))
      and coalesce(l.vat_rate_pct,-999999) is distinct from
        case when coalesce(
          m.correction_leg#>>'{invoice_policy,applied_vat_rate_pct}','')
          ~'^[+-]?[0-9]+([.][0-9]+)?$'
          then (m.correction_leg#>>
            '{invoice_policy,applied_vat_rate_pct}')::numeric
          else coalesce(l.vat_rate_pct,-999999) end) vat_mismatch_count
  from rollup r
  join members m on m.scope_key=r.scope_key
    and m.target_timesheet_id=r.timesheet_id
  left join candidate_lines l on l.scope_key=r.scope_key
    and l.timesheet_id=m.timesheet_id
  group by r.invoice_id,r.scope_key,r.timesheet_id
),
final as materialized (
  select r.*,coalesce(ls.present_ids,array[]::uuid[]) present_ids,
    coalesce(ls.conflicting_ids,array[]::uuid[]) conflicting_ids,
    coalesce(ls.present_count,0) present_count,
    coalesce(ls.vat_mismatch_count,0) vat_mismatch_count,
    array(select x from unnest(r.required_ids) x
      where not x=any(coalesce(ls.present_ids,array[]::uuid[]))) missing_ids,
    ti.id is not null target_exists,
    ti.status::text target_status,
    ti.issued_at_utc target_issued_at_utc,
    ti.client_id target_client_id,
    case
      when lower(coalesce(
        ti.header_snapshot_json#>>'{meta,self_bill}','false'))
        in('true','t','1','yes') then 'SELF_BILL'
      when private._candidate_feature_enabled_current_v1(
        'candidate_expense_invoice_routing_v1'
      ) and upper(coalesce(
        nullif(btrim(ti.header_snapshot_json->>'invoice_stream'),''),
        nullif(btrim(ti.header_snapshot_json#>>'{meta,invoice_stream}'),''),
        'NORMAL'
      ))='EXPENSE' then 'EXPENSE'
      else 'NORMAL'
    end target_invoice_stream,
    coalesce(pair_scope.scope_json,'{}'::jsonb) pair_scope_json,
    (
      not r.import_declared
      or(
        r.correction_operation_count=1
        and r.correction_chain_count=1
        and r.frozen_root_count=1
        and r.actual_root_count=1
        and r.frozen_root_matches
        and not r.chain_cycle
        and not r.chain_depth_exceeded
        and r.envelope_count=1
        and r.expected_count_variants=1
        and r.shape_variants=1
        and r.expected_member_count=r.member_count
        and r.actual_member_roles=r.expected_member_roles
        and r.reversal_count=1
        and r.replacement_count=case
          when r.correction_shape='REVERSAL_ONLY' then 0 else 1 end
        and r.correction_shape in('REVERSAL_ONLY','REVERSAL_REPLACEMENT')
      )
    ) pair_balanced
  from rollup r
  left join line_scope ls
    on ls.invoice_id is not distinct from r.invoice_id
   and ls.scope_key=r.scope_key
   and ls.timesheet_id=r.timesheet_id
  left join public.invoices ti on ti.id=r.invoice_id
  left join lateral (
    select public.invoice_correction_pair_scope_v1(
      r.timesheet_id,null::uuid,null::uuid,false,100) scope_json
    where r.import_declared
  ) pair_scope on true
),
member_results as materialized (
  select f.*,s.request_key,s.external_scope_key,s.validation_purpose,
    s.expected_client_id,s.expected_contract_id,s.natural_source_week,
    s.target_invoice_week,s.expected_invoice_stream scope_expected_stream,
    s.expected_vat_rate_pct,
    case when f.import_declared then 'IMPORT_AUTHORITATIVE'
      when f.correction_id is not null then 'NON_AUTHORITATIVE_CORRECTION'
      else 'ORDINARY' end correction_classification,
    b.blocker_codes,
    jsonb_build_object(
      'actual_member_count',f.member_count,
      'existing_line_member_count',f.present_count,
      'ready_count',f.ready_count,
      'missing_financial_count',f.missing_financial_count,
      'stale_financial_count',f.stale_financial_count,
      'not_ready_financial_count',f.not_ready_financial_count,
      'whole_lock_conflict_count',f.whole_lock_conflict_count,
      'segment_lock_conflict_count',f.segment_lock_conflict_count,
      'reversal_count',f.reversal_count,
      'replacement_count',f.replacement_count,
      'correction_shape',f.correction_shape,
      'expected_member_count',f.expected_member_count,
      'expected_member_roles',f.expected_member_roles,
      'actual_member_roles',f.actual_member_roles,
      'correction_operation_count',f.correction_operation_count,
      'correction_chain_count',f.correction_chain_count,
      'frozen_root_count',f.frozen_root_count,
      'actual_root_count',f.actual_root_count,
      'frozen_root_matches',f.frozen_root_matches,
      'chain_cycle',f.chain_cycle,
      'chain_depth_exceeded',f.chain_depth_exceeded,
      'expected_invoice_stream',f.expected_invoice_stream,
      'target_invoice_stream',case when f.invoice_id is null
        then null else f.target_invoice_stream end,
      'member_client_id',f.member_client_id,
      'member_contract_id',f.member_contract_id,
      'member_week',f.member_week,
      'target_client_id',f.target_client_id,
      'target_status',f.target_status,
      'vat_mismatch_count',f.vat_mismatch_count,
      'policy_failure_counts',jsonb_build_object(
        'missing_envelope',f.missing_envelope_count,
        'invalid_schema',f.invalid_schema_count,
        'invalid_route',f.invalid_route_count,
        'invalid_classification',f.invalid_classification_count,
        'missing_operation',f.missing_operation_count,
        'missing_chain',f.missing_chain_count,
        'invalid_action',f.invalid_action_count,
        'envelope_fingerprint',f.envelope_fingerprint_mismatch_count,
        'missing_leg',f.missing_leg_count,
        'leg_fingerprint',f.leg_fingerprint_mismatch_count,
        'tsfin_policy_fingerprint',f.tsfin_policy_fingerprint_mismatch_count,
        'invoice_policy_fingerprint',f.invoice_policy_fingerprint_mismatch_count,
        'policy_stream',f.policy_stream_mismatch_count,
        'current_envelope_fingerprint',
          f.current_envelope_fingerprint_mismatch_count,
        'current_leg_fingerprint',f.current_leg_fingerprint_mismatch_count,
        'current_tsfin_fingerprint',f.current_tsfin_fingerprint_mismatch_count,
        'current_invoice_fingerprint',
          f.current_invoice_fingerprint_mismatch_count,
        'frozen_subpolicy_drift',f.frozen_subpolicy_drift_count)) detail_json
  from final f
  join scopes s on s.scope_key=f.scope_key
  cross join lateral (
    select coalesce(array_agg(code order by ordinal)
      filter(where code is not null),array[]::text[]) blocker_codes
    from unnest(array[
      case when p_evaluation_date is null
        then 'EVALUATION_DATE_REQUIRED' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and not f.target_exists
        then 'INVOICE_CORRECTION_TARGET_NOT_FOUND' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and(upper(coalesce(f.target_status,''))<>'DRAFT'
          or f.target_issued_at_utc is not null)
        then 'INVOICE_CORRECTION_TARGET_NOT_APPENDABLE' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and f.target_client_id is distinct from f.member_client_id
        then 'INVOICE_CORRECTION_TARGET_CLIENT_MISMATCH' end,
      case when s.expected_client_id is not null
        and s.expected_client_id is distinct from f.member_client_id
        then 'INVOICE_CORRECTION_CLIENT_MISMATCH' end,
      case when s.expected_contract_id is not null
        and s.expected_contract_id is distinct from f.member_contract_id
        then 'INVOICE_CORRECTION_CONTRACT_MISMATCH' end,
      case when s.natural_source_week is not null
        and s.natural_source_week is distinct from f.member_week
        then 'INVOICE_CORRECTION_WEEK_MISMATCH' end,
      case when s.expected_invoice_stream is not null
        and s.expected_invoice_stream is distinct from f.expected_invoice_stream
        then 'INVOICE_CORRECTION_STREAM_MISMATCH' end,
      case when f.invoice_id is not null
        and s.validation_purpose not in('CREDIT_SOURCE','RECONCILE')
        and f.target_invoice_stream is distinct from f.expected_invoice_stream
        then 'INVOICE_CORRECTION_TARGET_STREAM_MISMATCH' end,
      case when f.import_declared and f.missing_envelope_count>0
        then 'INVOICE_CORRECTION_ENVELOPE_MISSING' end,
      case when f.import_declared and f.invalid_schema_count>0
        then 'INVOICE_CORRECTION_ENVELOPE_SCHEMA_INVALID' end,
      case when f.import_declared and f.invalid_route_count>0
        then 'INVOICE_CORRECTION_ROUTE_FAMILY_INVALID' end,
      case when f.import_declared and f.invalid_classification_count>0
        then 'INVOICE_CORRECTION_CLASSIFICATION_INVALID' end,
      case when f.import_declared and f.missing_operation_count>0
        then 'INVOICE_CORRECTION_OPERATION_IDENTITY_INVALID' end,
      case when f.import_declared and f.missing_chain_count>0
        then 'INVOICE_CORRECTION_CHAIN_IDENTITY_INVALID' end,
      case when f.import_declared and f.invalid_action_count>0
        then 'INVOICE_CORRECTION_ACTION_INVALID' end,
      case when f.import_declared and f.envelope_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_ENVELOPE_FINGERPRINT_MISMATCH' end,
      case when f.import_declared and f.envelope_count<>1
        then 'INVOICE_CORRECTION_MEMBER_ENVELOPE_MISMATCH' end,
      case when f.import_declared and f.missing_leg_count>0
        then 'INVOICE_CORRECTION_LEG_MISSING' end,
      case when f.import_declared and f.leg_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_LEG_FINGERPRINT_MISMATCH' end,
      case when f.import_declared
        and f.tsfin_policy_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_TSFIN_POLICY_FINGERPRINT_MISMATCH' end,
      case when f.import_declared
        and f.invoice_policy_fingerprint_mismatch_count>0
        then 'INVOICE_CORRECTION_INVOICE_POLICY_FINGERPRINT_MISMATCH' end,
      case when f.import_declared and f.policy_stream_mismatch_count>0
        then 'INVOICE_CORRECTION_STREAM_MISMATCH' end,
      case when f.import_declared
        and(f.current_envelope_fingerprint_mismatch_count>0
          or f.current_leg_fingerprint_mismatch_count>0
          or f.current_tsfin_fingerprint_mismatch_count>0
          or f.current_invoice_fingerprint_mismatch_count>0)
        then 'INVOICE_CORRECTION_CURRENT_POLICY_FINGERPRINT_MISMATCH' end,
      case when f.import_declared and f.frozen_subpolicy_drift_count>0
        then 'INVOICE_CORRECTION_FROZEN_POLICY_DRIFT' end,
      case when f.chain_cycle then 'INVOICE_CORRECTION_CHAIN_CYCLE' end,
      case when f.chain_depth_exceeded
        then 'INVOICE_CORRECTION_CHAIN_DEPTH_EXCEEDED' end,
      case when f.member_count>100
        then 'INVOICE_CORRECTION_MEMBER_LIMIT_EXCEEDED' end,
      case when f.import_declared and not f.frozen_root_matches
        then 'INVOICE_CORRECTION_ENVELOPE_ROOT_MISMATCH' end,
      case when f.missing_financial_count>0
        then 'INVOICE_CORRECTION_TSFIN_MISSING' end,
      case when f.stale_financial_count>0
        then 'INVOICE_CORRECTION_TSFIN_STALE' end,
      case when f.not_ready_financial_count>0
        or f.ready_count<>f.member_count
        then 'INVOICE_CORRECTION_TSFIN_NOT_READY' end,
      case when f.client_count<>1
        then 'INVOICE_CORRECTION_CLIENT_MISMATCH' end,
      case when f.contract_count<>1 and not (f.contract_count=0 and f.member_count=1
        and private.timesheet_correction_nullable_daily_contract_v1(s.scope_json,f.timesheet_id) is true)
        then 'INVOICE_CORRECTION_CONTRACT_MISMATCH' end,
      case when f.week_count<>1
        then 'INVOICE_CORRECTION_WEEK_MISMATCH' end,
      case when f.stream_count<>1
        then 'INVOICE_CORRECTION_STREAM_MISMATCH' end,
      case when f.whole_lock_conflict_count>0
        then 'INVOICE_CORRECTION_SOURCE_LOCK_CONFLICT' end,
      case when f.segment_lock_conflict_count>0
        then 'INVOICE_CORRECTION_SEGMENT_LOCK_CONFLICT' end,
      case when f.pair_scope_json->>'placement_state'='INCOMPLETE_MOVE'
        then 'INVOICE_CORRECTION_PAIR_PLACEMENT_INCOMPLETE' end,
      case when cardinality(f.conflicting_ids)>0
        and not (
          coalesce((f.pair_scope_json->>'valid')::boolean,false)
          and f.pair_scope_json->>'placement_state' in ('COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE')
        )
        then 'INVOICE_CORRECTION_UNIT_SPLIT_ACROSS_INVOICES' end,
      case when (cardinality(f.missing_ids)>0
        and not (
          coalesce((f.pair_scope_json->>'valid')::boolean,false)
          and f.pair_scope_json->>'placement_state' in ('COMPLETE_SPLIT_INVOICES','INCOMPLETE_MOVE')
        ))
        or(f.import_declared
          and coalesce(f.expected_member_count,0)>f.member_count
          and f.pair_scope_json->>'placement_state'<>'INCOMPLETE_MOVE')
        then 'INVOICE_CORRECTION_MEMBER_MISSING' end,
      case when f.vat_mismatch_count>0
        then 'INVOICE_CORRECTION_VAT_POLICY_MISMATCH' end,
      case when f.import_declared and not f.pair_balanced
        then 'INVOICE_CORRECTION_UNIT_INVALID' end
    ]::text[]) with ordinality u(code,ordinal)
  ) b
),
scope_blockers as materialized (
  select s.scope_key,coalesce(array_agg(x.code order by x.first_ordinal)
      filter(where x.code is not null),array[]::text[]) blocker_codes
  from scopes s
  left join lateral (
    select u.code,min(u.ordinal)::integer first_ordinal
    from member_results m
    cross join lateral unnest(m.blocker_codes) with ordinality u(code,ordinal)
    where m.scope_key=s.scope_key
    group by u.code
  ) x on true
  group by s.scope_key
),
scope_summary as materialized (
  select s.request_key,s.external_scope_key scope_key,s.invoice_id,
    case when count(distinct m.timesheet_id)=1 then (min(m.timesheet_id::text))::uuid end
      timesheet_id,
    case when bool_or(coalesce(m.import_declared,false))
      then 'IMPORT_AUTHORITATIVE'
      when bool_or(m.correction_id is not null)
      then 'NON_AUTHORITATIVE_CORRECTION'
      else 'ORDINARY' end correction_classification,
    case when count(distinct m.correction_id)=1 then min(m.correction_id) end
      correction_id,
    coalesce(array_agg(distinct m.correction_id order by m.correction_id)
      filter(where m.correction_id is not null),array[]::text[])
      correction_ids,
    coalesce(array(select distinct x from member_results mr
      cross join lateral unnest(mr.required_ids) q(x)
      where mr.scope_key=s.scope_key order by x),array[]::uuid[])
      required_member_ids,
    coalesce(array(select distinct x from member_results mr
      cross join lateral unnest(mr.missing_ids) q(x)
      where mr.scope_key=s.scope_key order by x),array[]::uuid[])
      missing_member_ids,
    coalesce(array(select distinct x from member_results mr
      cross join lateral unnest(mr.conflicting_ids) q(x)
      where mr.scope_key=s.scope_key order by x),array[]::uuid[])
      conflicting_invoice_ids,
    coalesce(bool_and(m.pair_balanced),true) balanced,
    sb.blocker_codes||case when exists(select 1 from scopes invalid_scope
      where invalid_scope.scope_key=s.scope_key and invalid_scope.scope_json?'credit_scope'
        and private.timesheet_correction_scoped_source_identity_v1(invalid_scope.scope_json) is null)
      then array['CREDIT_SCOPE_AUTHORITY_UNPROVED']::text[] else array[]::text[] end blocker_codes,
    jsonb_build_object(
      'validation_purpose',s.validation_purpose,
      'evaluation_date',p_evaluation_date,
      'natural_source_week',s.natural_source_week,
      'target_invoice_week',s.target_invoice_week,
      'unit_count',count(distinct(m.correction_id,m.timesheet_id))
        filter(where m.correction_id is not null),
      'units',coalesce(jsonb_agg(jsonb_build_object(
        'timesheet_id',m.timesheet_id,
        'correction_id',m.correction_id,
        'classification',m.correction_classification,
        'required_member_ids',m.required_ids,
        'missing_member_ids',m.missing_ids,
        'conflicting_invoice_ids',m.conflicting_ids,
        'balanced',m.pair_balanced,
        'blocker_codes',m.blocker_codes,
        'detail',m.detail_json)
        order by m.correction_id nulls last,m.timesheet_id)
        filter(where m.timesheet_id is not null),'[]'::jsonb)) detail_json
  from scopes s
  left join member_results m on m.scope_key=s.scope_key
  join scope_blockers sb on sb.scope_key=s.scope_key
  group by s.request_key,s.external_scope_key,s.scope_key,s.invoice_id,
    s.validation_purpose,s.natural_source_week,s.target_invoice_week,
    sb.blocker_codes
)
select request_key,scope_key,invoice_id,timesheet_id,
  correction_classification,correction_id,correction_ids,
  required_member_ids,missing_member_ids,conflicting_invoice_ids,
  balanced,cardinality(blocker_codes)=0 valid,
  blocker_codes[1] blocker_code,blocker_codes,detail_json
from scope_summary
order by request_key,scope_key;
$function$;

-- Fulfil an existing DOCUMENT_INPUT only from its exact T0-only original
-- completed input inside a verified original FINAL_ISSUE graph.
create or replace function private.invoice_credit_original_input_receipt_v1(p_frozen_source jsonb)
returns table(result_json jsonb,page_count integer,size_bytes bigint)
language sql stable security definer
set search_path to 'pg_catalog','public','private','pg_temp'
as $function$
  select input.result_json,input.actual_page_count,input.actual_byte_count
  from public.invoice_operation_chunks input
  join public.invoice_document_versions original on original.id=input.document_version_id
  where input.id=case when pg_input_is_valid(p_frozen_source->>'original_document_input_id','uuid')
      then(p_frozen_source->>'original_document_input_id')::uuid end
    and original.id=case when pg_input_is_valid(p_frozen_source->>'input_document_version_id','uuid')
      then(p_frozen_source->>'input_document_version_id')::uuid end
    and original.entity_type='INVOICE' and original.purpose='FINAL_ISSUE'
    and original.status='READY' and original.verified_at_utc is not null
    and input.entity_type='TIMESHEET'
    and input.entity_id=case when pg_input_is_valid(p_frozen_source->>'timesheet_id','uuid')
      then(p_frozen_source->>'timesheet_id')::uuid end
    and input.chunk_type='DOCUMENT_INPUT' and input.payload_json->>'input_type'='ELECTRONIC_TIMESHEET'
    and input.status='COMPLETE' and input.actual_page_count>0 and input.actual_byte_count>0
    and input.result_json is not distinct from p_frozen_source->'original_document_input_result'
    and input.payload_json->>'source_revision' is not distinct from p_frozen_source->>'original_document_source_revision'
    and input.result_json->>'sha256'~'^[0-9a-f]{64}$'
    and nullif(input.result_json->>'r2_key','') is not null;
$function$;

create or replace function private.invoice_credit_scoped_advance_v1(p_claim jsonb,p_now_utc timestamptz)
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public','private','extensions','pg_temp'
as $function$
declare
  v_chunk public.invoice_operation_chunks%rowtype; v_operation public.invoice_operations%rowtype;
  v_original public.invoices%rowtype; v_scope jsonb; v_id uuid; v_r uuid; v_x uuid;
  v_now timestamptz:=coalesce(p_now_utc,now()); v_blocker text; v_phase text:=p_claim->>'phase';
begin
  select c.* into strict v_chunk from public.invoice_operation_chunks c where c.id=(p_claim->>'chunk_id')::uuid;
  select o.* into strict v_operation from public.invoice_operations o where o.id=v_chunk.operation_id;
  if v_chunk.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
    or jsonb_typeof(v_chunk.payload_json->'credit_scope')<>'object'
    or not pg_input_is_valid(v_chunk.payload_json#>>'{credit_scope,reversal_timesheet_id}','uuid')
    or v_phase not in('VALIDATE_SOURCES','PLAN','COMMIT') then
    raise exception 'CREDIT_SCOPE_CLAIM_INVALID' using errcode='22023';
  end if;
  v_r:=(v_chunk.payload_json#>>'{credit_scope,reversal_timesheet_id}')::uuid;
  v_id:=case when pg_input_is_valid(v_chunk.payload_json#>>'{plan,planned_invoice_id}','uuid')
    then(v_chunk.payload_json#>>'{plan,planned_invoice_id}')::uuid end;
  v_scope:=private.invoice_credit_scope_context_v1(v_chunk.entity_id,v_r,v_chunk.operation_id,v_id,v_phase='COMMIT');
  v_blocker:=case when (v_scope->>'valid')::boolean is distinct from true then v_scope->>'blocker' end;
  if v_phase='COMMIT' then
    perform 1 from public.tms_users u where u.id=v_operation.actor_user_id for share;
    if v_blocker is null then
      select validation.blocker_code into v_blocker from private._invoice_correction_validate_batch(
        jsonb_build_array(jsonb_build_object('request_key','credit-source:'||v_chunk.entity_id,
          'scope_key',v_chunk.entity_id,'invoice_id',v_chunk.entity_id,'validation_purpose','CREDIT_SOURCE',
          'credit_scope',jsonb_build_object('reversal_timesheet_id',v_r),'request_id',v_scope->>'request_id',
          'target_revision',(select request.target_revision from private.timesheet_correction_requests request
            where request.id=(v_scope->>'request_id')::uuid),'operation_id',v_chunk.operation_id,'planned_credit_note_id',v_id)),
        (v_now at time zone 'Europe/London')::date) validation
        where validation.valid is distinct from true order by validation.blocker_code limit 1;
    end if;
  end if;
  if not exists(select 1 from public.tms_users u where u.id=v_operation.actor_user_id
      and coalesce(u.is_active,false) and upper(u.role::text)='ADMIN') then
    v_blocker:='CREDIT_ACTOR_NOT_ALLOWED';
  end if;
  if v_blocker is not null then
    update public.invoice_operation_chunks c set status=case when v_phase='COMMIT' then 'SUPERSEDED' else 'BLOCKED' end,
      phase=case when v_phase='COMMIT' then 'SUPERSEDED' else 'BLOCKED' end,
      error_json=jsonb_build_object('code',v_blocker,'invoice_id',v_chunk.entity_id,'reversal_timesheet_id',v_r),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now where c.id=v_chunk.id;
  elsif v_phase='VALIDATE_SOURCES' then
    update public.invoice_operation_chunks c set status='QUEUED',phase='PLAN',
      payload_json=c.payload_json||jsonb_build_object('source_revision',v_scope->>'revision',
        'source_invoice_id',c.entity_id,'resume_invoice_id',v_scope->'resume_invoice_id'),
      error_json=null,lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now where c.id=v_chunk.id;
  elsif v_phase='PLAN' then
    v_id:=coalesce(v_id,nullif(v_scope->>'resume_invoice_id','')::uuid,gen_random_uuid());
    update public.invoice_operation_chunks c set status='QUEUED',phase='COMMIT',
      payload_json=c.payload_json||jsonb_build_object('plan',jsonb_build_object('planned_invoice_id',v_id,
        'intended_invoice_count',1,'source_count',v_scope->'source_count','source_revision',v_scope->>'revision',
        'expected_charge_ex_vat',v_scope->'subtotal_ex_vat','expected_pay_ex_vat',v_scope->'total_pay_ex_vat',
        'settings_snapshot',v_scope,'settings_hash',encode(digest(v_scope::text,'sha256'),'hex'))),
      error_json=null,lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now where c.id=v_chunk.id;
  elsif nullif(v_scope->>'resume_invoice_id','') is not null then
    -- Own result was validated against exact creating operation, persisted
    -- membership, negative money and original-line identity by resume helper.
    update public.invoice_operation_chunks c set status='QUEUED',phase='QUEUE_DOCUMENT',
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(v_id),'credit_note_id',v_id,
        'source_invoice_id',c.entity_id,'replayed',true),error_json=null,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now where c.id=v_chunk.id;
  elsif v_id is null or v_chunk.payload_json->>'source_revision' is distinct from v_scope->>'revision'
    or v_chunk.payload_json#>>'{plan,source_revision}' is distinct from v_scope->>'revision' then
    update public.invoice_operation_chunks c set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code','CREDIT_SOURCE_CHANGED_BEFORE_COMMIT'),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now where c.id=v_chunk.id;
  else
    v_x:=(v_scope->>'reversed_timesheet_id')::uuid;
    select i.* into strict v_original from public.invoices i where i.id=v_chunk.entity_id;
    begin
      insert into public.invoices(id,type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
        original_invoice_id,notes,header_snapshot_json,document_revision,document_state,created_at,updated_at)
      values(v_id,'CREDIT_NOTE',v_original.client_id,'DRAFT',v_now,(v_scope->>'subtotal_ex_vat')::numeric,
        (v_scope->>'vat_amount')::numeric,(v_scope->>'total_inc_vat')::numeric,v_original.id,
        v_chunk.payload_json->>'credit_reason',v_original.header_snapshot_json||jsonb_build_object(
          'credit_source_invoice_id',v_original.id,'credit_reason',v_chunk.payload_json->>'credit_reason',
          'credit_operation_id',v_chunk.operation_id,'credit_scope',v_scope||jsonb_build_object(
            'creating_operation_id',v_chunk.operation_id)),1,'STALE',v_now,v_now);
      insert into public.invoice_lines(invoice_id,timesheet_id,booking_id,description,
        hours_day,hours_night,hours_sat,hours_sun,hours_bh,pay_day,pay_night,pay_sat,pay_sun,pay_bh,
        charge_day,charge_night,charge_sat,charge_sun,charge_bh,total_pay_ex_vat,total_charge_ex_vat,
        margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,paper_ts_r2_key,meta_json,source_key)
      select v_id,l.timesheet_id,l.booking_id,'CREDIT NOTE – '||coalesce(l.description,''),
        l.hours_day,l.hours_night,l.hours_sat,l.hours_sun,l.hours_bh,l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
        l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,-l.total_pay_ex_vat,-l.total_charge_ex_vat,
        -l.margin_ex_vat,l.vat_rate_pct,-l.vat_amount,-l.total_inc_vat,l.paper_ts_r2_key,
        coalesce(l.meta_json,'{}'::jsonb)||jsonb_build_object('credit_note',true,'original_invoice_id',v_original.id,
          'original_invoice_line_id',l.id,'credit_of_line_id',l.id,'reversal_timesheet_id',v_r,
          'line_type','CREDIT_'||coalesce(l.meta_json->>'line_type','LINE')),
        'CN:'||v_id||':LINE:'||l.id
      from public.invoice_lines l where l.invoice_id=v_original.id and l.timesheet_id=v_x;
      update public.timesheets_financials tf set locked_by_invoice_id=v_id,locked_at_utc=v_now,
        invoice_breakdown_json=case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
          then jsonb_set(tf.invoice_breakdown_json,'{segments}',coalesce((select jsonb_agg(s.value||jsonb_build_object(
            'invoice_locked_invoice_id',v_id,'invoice_locked_at_utc',v_now) order by s.ordinality)
            from jsonb_array_elements(tf.invoice_breakdown_json->'segments') with ordinality s(value,ordinality)),'[]'::jsonb),true)
          else tf.invoice_breakdown_json end,updated_at=v_now
        where tf.timesheet_id=v_r and tf.is_current and tf.locked_by_invoice_id is null;
      if not found then raise exception 'CREDIT_SCOPE_ALREADY_CREDITED' using errcode='P0001'; end if;
      update public.contract_weeks w set status='INVOICED',updated_at=v_now where w.timesheet_id=v_r;
      if (v_scope->>'attach_hr')::boolean then
        insert into public.invoice_hr_source_rows(invoice_id,source_system,import_id,header_columns,rows_json,header_rows,member_rows_json)
        select v_id,s.source_system,s.import_id,s.header_columns,s.member_rows_json->v_x::text,s.header_rows,
          jsonb_build_object(v_x::text,s.member_rows_json->v_x::text)
        from public.invoice_hr_source_rows s where s.invoice_id=v_original.id and upper(s.source_system)='HEALTHROSTER'
          and jsonb_typeof(s.member_rows_json->v_x::text)='array' and jsonb_array_length(s.member_rows_json->v_x::text)>0;
      end if;
      insert into public.audit_events(ts_utc,actor_user_id,object_type,object_id_text,action,after_json,reason)
      values(v_now,v_operation.actor_user_id,'invoices',v_id::text,'CREDIT_NOTE_CREATED',
        jsonb_build_object('credit_note_id',v_id,'original_invoice_id',v_original.id,'reversal_timesheet_id',v_r,
          'reversed_timesheet_id',v_x,'creating_operation_id',v_chunk.operation_id,
          'subtotal_ex_vat',v_scope->'subtotal_ex_vat','vat_amount',v_scope->'vat_amount','total_inc_vat',v_scope->'total_inc_vat'),
        'HEALTHROSTER_SCOPED_CREDIT');
      -- I1, X/T0 and every unrelated TF/segment/evidence row are deliberately
      -- not financial writes in this arm. All native triggers remain enabled.
      update public.invoice_operation_chunks c set status='QUEUED',phase='QUEUE_DOCUMENT',
        result_json=jsonb_build_object('invoice_ids',jsonb_build_array(v_id),'credit_note_id',v_id,'source_invoice_id',v_original.id),
        error_json=null,lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now where c.id=v_chunk.id;
    exception when others then
      if sqlerrm<>'CREDIT_SCOPE_ALREADY_CREDITED' then raise; end if;
      -- The subtransaction rolled the header/lines back before the loser receipt.
      update public.invoice_operation_chunks c set status='SUPERSEDED',phase='SUPERSEDED',
        error_json=jsonb_build_object('code','CREDIT_SCOPE_ALREADY_CREDITED'),
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=v_now where c.id=v_chunk.id;
    end;
  end if;
  select c.* into strict v_chunk from public.invoice_operation_chunks c where c.id=v_chunk.id;
  return jsonb_build_object('chunk_id',v_chunk.id,'status',v_chunk.status,'phase',v_chunk.phase,
    'result',v_chunk.result_json,'error',v_chunk.error_json);
end;
$function$;

create or replace function private._invoice_operation_start_core_v8(
  p_commands jsonb,
  p_actor_user_id uuid,
  p_now_utc timestamptz default now()
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz:=coalesce(p_now_utc,now());
  v_jwt_role text:=coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    auth.jwt()->>'role','');
  v_auth_user uuid:=auth.uid();
  v_result jsonb;
begin
  if jsonb_typeof(p_commands)<>'array'
     or jsonb_array_length(p_commands)<1
     or jsonb_array_length(p_commands)>1000 then
    raise exception using errcode='22023',
      message='p_commands must be a JSON array containing 1..1000 commands';
  end if;

  if p_actor_user_id is null
     or not exists(select 1 from public.tms_users u
       where u.id=p_actor_user_id and u.is_active and lower(u.role)='admin')
     or(v_jwt_role<>'service_role' and v_auth_user is distinct from p_actor_user_id) then
    raise exception using errcode='42501',
      message='Active administrator actor and matching authenticated/service caller required';
  end if;

  with raw as materialized (
    select e.ordinality::integer command_no,e.value command_json,
      upper(btrim(coalesce(e.value->>'command_type',e.value->>'type',''))) command_type
    from jsonb_array_elements(p_commands) with ordinality e(value,ordinality)
  ),
  command_ids as materialized (
    select r.command_no,r.command_type,x.ordinality::integer item_no,x.value id_text,
      x.value ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        valid_uuid
    from raw r
    cross join lateral jsonb_array_elements_text(
      case
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
          then r.command_json->'nhsp_shift_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'source_ids')='array'
          then r.command_json->'source_ids'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_NHSP','GENERATE_AUTO')
          and jsonb_typeof(r.command_json->'timesheet_ids')='array'
          then r.command_json->'timesheet_ids'
        when r.command_type in('GENERATE_CREDIT_NOTE','ISSUE_INVOICES','DELIVER_INVOICES')
          and jsonb_typeof(r.command_json->'invoice_ids')='array'
          then r.command_json->'invoice_ids'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and coalesce(r.command_json->>'base_invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'base_invoice_id')
        when r.command_type in(
          'GENERATE_CREDIT_NOTE','VIEW_INVOICE_DOCUMENT','DELIVER_INVOICES')
          and coalesce(r.command_json->>'invoice_id','')<>'' then
          jsonb_build_array(r.command_json->>'invoice_id')
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and coalesce(r.command_json->>'timesheet_id','')<>'' then
          jsonb_build_array(r.command_json->>'timesheet_id')
        else '[]'::jsonb
      end
    ) with ordinality x(value,ordinality)
  ),
  canonical_ids as materialized (
    select command_no,array_agg(distinct id_text::uuid order by id_text::uuid) ids
    from command_ids where valid_uuid group by command_no
  ),
  generation_groups as materialized (
    select *
    from private._invoice_generation_resolve_command_groups(
      p_commands,p_actor_user_id,v_now)
  ),
  view_facts as materialized (
    select r.command_no,r.command_type,
      case when r.command_type='VIEW_INVOICE_DOCUMENT' then 'INVOICE' else 'TIMESHEET' end entity_type,
      (array_agg(ci.id_text::uuid order by ci.item_no))[1] entity_id,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then i.document_revision else t.document_revision end document_revision,
      case when r.command_type='VIEW_INVOICE_DOCUMENT'
        then 'DRAFT_PREVIEW' else 'TIMESHEET' end purpose,
      coalesce(nullif(r.command_json->>'template_version',''),
        case when r.command_type='VIEW_INVOICE_DOCUMENT'
          then 'invoice-professional-v2' else 'timesheet-professional-v1' end) template_version
    from raw r
    left join command_ids ci on ci.command_no=r.command_no and ci.valid_uuid
    left join public.invoices i
      on r.command_type='VIEW_INVOICE_DOCUMENT' and i.id=ci.id_text::uuid
    left join public.timesheets t
      on r.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=ci.id_text::uuid
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    group by r.command_no,r.command_type,i.document_revision,t.document_revision,r.command_json
  ),
  issue_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      encode(digest(string_agg(i.id||':'||i.document_revision,
        '|' order by i.id),'sha256'),'hex') invoice_revision_hash,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where r.command_type='ISSUE_INVOICES'
    group by r.command_no
  ),
  delivery_facts as materialized (
    select r.command_no,
      array_agg(i.id order by i.id) invoice_ids,
      array_agg(i.issued_document_version_id order by i.id) document_version_ids,
      encode(digest(string_agg(concat_ws(':',i.id::text,
        i.issued_document_version_id::text,v.sha256,v.size_bytes::text,v.page_count::text),
        '|' order by i.id),'sha256'),'hex') delivery_revision,
      count(*)::integer resolved_count
    from raw r join canonical_ids ci on ci.command_no=r.command_no
    cross join unnest(ci.ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join public.invoice_document_versions v
      on v.id=i.issued_document_version_id and v.status='READY'
      and v.purpose='FINAL_ISSUE' and v.entity_type='INVOICE' and v.entity_id=i.id
    where r.command_type='DELIVER_INVOICES' and i.status in('ISSUED','PAID')
    group by r.command_no
  ),
  recipient_sets as materialized (
    select r.command_no,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_recipients,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_cc,
      coalesce((select jsonb_agg(email order by email)
        from(
          select distinct lower(btrim(e.value)) email
          from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
        ) q),'[]'::jsonb) canonical_bcc,
      (select count(*)::integer
        from(
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'recipient_set')='array'
              then r.command_json->'recipient_set' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'cc')='array'
              then r.command_json->'cc' else '[]'::jsonb end)
          union all
          select value from jsonb_array_elements_text(
            case when jsonb_typeof(r.command_json->'bcc')='array'
              then r.command_json->'bcc' else '[]'::jsonb end)
        ) e
        where nullif(btrim(e.value),'') is not null
          and btrim(e.value)!~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
        invalid_count
    from raw r
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_route_requests as materialized (
    select r.command_no,i.invoice_id,jsonb_build_object(
      'request_key',r.command_no::text||':'||i.invoice_id::text,
      'invoice_id',i.invoice_id,
      'recipient_set',rs.canonical_recipients,
      'cc',rs.canonical_cc,
      'bcc',rs.canonical_bcc,
      'delivery_policy',upper(coalesce(
        nullif(r.command_json->>'delivery_policy',''),'ATTACH')),
      'template_version',coalesce(
        nullif(r.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1')) request_json
    from raw r
    join delivery_facts f on f.command_no=r.command_no
    join recipient_sets rs on rs.command_no=r.command_no
    cross join unnest(f.invoice_ids) i(invoice_id)
    where r.command_type='DELIVER_INVOICES'
  ),
  delivery_routes as materialized (
    select q.command_no,d.*
    from private._invoice_delivery_routes_batch(coalesce((
      select jsonb_agg(q.request_json order by q.command_no,q.invoice_id)
      from delivery_route_requests q),'[]'::jsonb),
      (v_now at time zone 'Europe/London')::date) d
    join delivery_route_requests q
      on q.request_json->>'request_key'=d.request_key
      and q.invoice_id=d.invoice_id
  ),
  delivery_route_groups as materialized (
    select command_no,
      encode(digest(string_agg(invoice_id::text||':'||route_policy_hash,
        '|' order by invoice_id),'sha256'),'hex') route_set_hash,
      jsonb_agg(jsonb_build_object(
        'invoice_id',invoice_id,'to',canonical_to,'cc',canonical_cc,
        'bcc',canonical_bcc,'recipient_set_hash',recipient_set_hash,
        'route_policy_hash',route_policy_hash,
        'route_source',route_source,'do_not_send',do_not_send,
        'warning_codes',warning_codes,'blocker_codes',blocker_codes,
        'evaluated_date',(v_now at time zone 'Europe/London')::date)
        order by invoice_id) frozen_routes
    from delivery_routes
    group by command_no
  ),
  issue_delivery_intents as materialized (
    select r.command_no,
      (intent.intent_json-'recipient_set'-'cc'-'bcc')
        ||jsonb_build_object(
          'recipient_set',recipients.canonical,
          'cc',cc.canonical,'bcc',bcc.canonical) canonical_intent,
      recipients.requested_count+cc.requested_count+bcc.requested_count requested_count,
      recipients.valid_count+cc.valid_count+bcc.valid_count valid_count
    from raw r
    cross join lateral(
      select case when jsonb_typeof(r.command_json->'delivery_intent')='object'
        then r.command_json->'delivery_intent' else '{}'::jsonb end intent_json
    ) intent
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
                then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'recipient_set')='array'
              then intent.intent_json->'recipient_set' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) recipients
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'cc')='array'
                then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'cc')='array'
              then intent.intent_json->'cc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) cc
    cross join lateral(
      select coalesce((select jsonb_agg(email order by email)
          from(
            select distinct lower(btrim(e.value)) email
            from jsonb_array_elements_text(
              case when jsonb_typeof(intent.intent_json->'bcc')='array'
                then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
            where nullif(btrim(e.value),'') is not null
              and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
          ) valid),'[]'::jsonb) canonical,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null) requested_count,
        (select count(*)::integer
          from jsonb_array_elements_text(
            case when jsonb_typeof(intent.intent_json->'bcc')='array'
              then intent.intent_json->'bcc' else '[]'::jsonb end) e(value)
          where nullif(btrim(e.value),'') is not null
            and btrim(e.value)~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$')
          valid_count
    ) bcc
    where r.command_type='ISSUE_INVOICES'
  ),
  asset_specs as materialized (
    select r.command_no,r.command_json,
      upper(btrim(coalesce(r.command_json->>'source_kind',''))) source_kind,
      case when coalesce(r.command_json->>'source_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(r.command_json->>'source_id')::uuid end source_id,
      nullif(btrim(r.command_json->>'source_revision'),'') source_revision,
      nullif(btrim(r.command_json->>'original_r2_key'),'') original_r2_key,
      nullif(btrim(r.command_json->>'original_filename'),'') original_filename,
      nullif(btrim(r.command_json->>'declared_media_type'),'') declared_media_type,
      case when coalesce(r.command_json->>'rotation_degrees','') ~ '^(0|90|180|270)$'
        then(r.command_json->>'rotation_degrees')::integer end rotation_degrees,
      r.command_json?'rotation_degrees' rotation_supplied
    from raw r where r.command_type='PREPARE_ASSET'
  ),
  issue_entity_locks as materialized (
    select pg_advisory_xact_lock(
      hashtextextended('ISSUE_INVOICE|'||ci.id_text,0))
    from command_ids ci join raw r on r.command_no=ci.command_no
    where r.command_type='ISSUE_INVOICES' and ci.valid_uuid
    order by ci.id_text
  ),
  command_validation as materialized (
    select r.command_no,r.command_type,
      case
        when jsonb_typeof(r.command_json)<>'object'
          then 'COMMAND_MUST_BE_OBJECT'
        when r.command_type not in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS','GENERATE_EXPENSES',
          'GENERATE_NHSP','GENERATE_CREDIT_NOTE','GENERATE_AUTO',
          'VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT','PREPARE_ASSET',
          'ISSUE_INVOICES','DELIVER_INVOICES','RECONCILE')
          then 'UNSUPPORTED_COMMAND_TYPE'
        when r.command_type in(
          'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS',
          'GENERATE_EXPENSES','GENERATE_AUTO')
          and not(
            jsonb_typeof(r.command_json->'source_ids')='array'
            or jsonb_typeof(r.command_json->'timesheet_ids')='array')
          then 'GENERATION_SOURCE_ARRAY_REQUIRED'
        when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')<>'array'
          then 'NHSP_SHIFT_ARRAY_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'consolidation_mode'
          and upper(coalesce(r.command_json->>'consolidation_mode','')) not in(
            'NONE','BY_WEEK','ANY_WEEK')
          then 'INVALID_CONSOLIDATION_MODE'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and r.command_json?'allow_early'
          and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
          then 'ALLOW_EARLY_MUST_BE_BOOLEAN'
        when r.command_type like 'GENERATE_%'
          and r.command_type<>'GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(
            r.command_json->>'target_invoice_week','')),'') is not null
          and not pg_input_is_valid(
            r.command_json->>'target_invoice_week','date')
          then 'INVALID_TARGET_INVOICE_WEEK'
        when r.command_type='GENERATE_CREDIT_NOTE' and r.command_json?'credit_scope'
          and (jsonb_typeof(r.command_json->'credit_scope') is distinct from 'object'
            or not pg_input_is_valid(r.command_json#>>'{credit_scope,reversal_timesheet_id}','uuid')
            or (select count(*) from jsonb_object_keys(case
              when jsonb_typeof(r.command_json->'credit_scope')='object' then r.command_json->'credit_scope'
              else '{}'::jsonb end))<>1)
          then 'CREDIT_SCOPE_INVALID'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'base_invoice_id','')),'') is null
          then 'BASE_INVOICE_ID_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and(select count(*) from command_ids x
            where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_BASE_INVOICE_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'credit_reason','')),'') is null
          then 'CREDIT_REASON_REQUIRED'
        when r.command_type='GENERATE_CREDIT_NOTE'
          and nullif(btrim(coalesce(r.command_json->>'command_token','')),'') is null
          then 'CREDIT_COMMAND_TOKEN_REQUIRED'
        when exists(select 1 from command_ids x
          where x.command_no=r.command_no and not x.valid_uuid)
          then 'MALFORMED_UUID'
        when r.command_type like 'GENERATE_%' and not exists(
          select 1 from generation_groups g where g.command_no=r.command_no)
          then 'GENERATION_SOURCES_REQUIRED'
        when r.command_type like 'GENERATE_%'
          and (select count(*) from generation_groups g
            where g.command_no=r.command_no)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and(select count(*) from command_ids x where x.command_no=r.command_no)<>1
          then 'EXACTLY_ONE_DOCUMENT_ENTITY_REQUIRED'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and nullif(btrim(coalesce(r.command_json->>'priority_reason','')),'') is null
          then 'DOCUMENT_PRIORITY_REASON_REQUIRED'
        when r.command_type='VIEW_INVOICE_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'DRAFT_PREVIEW'))<>'DRAFT_PREVIEW'
          then 'INVALID_INVOICE_DOCUMENT_PURPOSE'
        when r.command_type='VIEW_TIMESHEET_DOCUMENT'
          and upper(coalesce(nullif(r.command_json->>'purpose',''),
            'TIMESHEET'))<>'TIMESHEET'
          then 'INVALID_TIMESHEET_DOCUMENT_PURPOSE'
        when r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
          and not exists(select 1 from view_facts v
            where v.command_no=r.command_no and v.document_revision is not null)
          then 'DOCUMENT_ENTITY_NOT_FOUND'
        when r.command_type='PREPARE_ASSET' and not exists(
          select 1 from asset_specs a
          where a.command_no=r.command_no
            and a.source_kind in(
              'MANUAL_TIMESHEET','TIMESHEET_EVIDENCE','OTHER_EVIDENCE',
              'HR_REPORT','NHSP_REPORT','HIGHER_RATE_SUPPORT')
            and a.source_id is not null and a.source_revision is not null
            and a.original_r2_key is not null and a.original_filename is not null
            and a.declared_media_type is not null
            and(not a.rotation_supplied or a.rotation_degrees is not null))
          then 'INVALID_ASSET_SOURCE_METADATA'
        when r.command_type='PREPARE_ASSET'
          and r.command_json?'rotation_degrees'
          and coalesce(r.command_json->>'rotation_degrees','')!~'^(0|90|180|270)$'
          then 'INVALID_ASSET_ROTATION'
        when r.command_type='ISSUE_INVOICES'
          and(jsonb_typeof(r.command_json->'invoice_ids')<>'array'
            or coalesce(cardinality((select ids from canonical_ids x
              where x.command_no=r.command_no)),0)=0
            or coalesce((select resolved_count from issue_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUE_INVOICES_NOT_RESOLVED'
        when r.command_type='ISSUE_INVOICES'
          and (r.command_json?'allow_early'
            and jsonb_typeof(r.command_json->'allow_early')<>'boolean'
            or r.command_json?'deliver'
            and jsonb_typeof(r.command_json->'deliver')<>'boolean')
          then 'ISSUE_FLAGS_MUST_BE_BOOLEAN'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(nullif(r.command_json->>'command_token',''),'')=''
          then 'ISSUE_COMMAND_TOKEN_REQUIRED'
        when r.command_type='ISSUE_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='ISSUE_INVOICES'
          and r.command_json?'delivery_intent'
          and jsonb_typeof(r.command_json->'delivery_intent')<>'object'
          then 'ISSUE_DELIVERY_INTENT_MUST_BE_OBJECT'
        when r.command_type='ISSUE_INVOICES'
          and jsonb_typeof(r.command_json->'delivery_intent')='object'
          and (
            r.command_json->'delivery_intent'?'recipient_set'
              and jsonb_typeof(r.command_json->'delivery_intent'->'recipient_set')<>'array'
            or r.command_json->'delivery_intent'?'cc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'cc')<>'array'
            or r.command_json->'delivery_intent'?'bcc'
              and jsonb_typeof(r.command_json->'delivery_intent'->'bcc')<>'array')
          then 'ISSUE_DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='ISSUE_INVOICES'
          and exists(
            select 1 from issue_delivery_intents intent
            where intent.command_no=r.command_no
              and intent.requested_count<>intent.valid_count)
          then 'ISSUE_DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='ISSUE_INVOICES' and exists(
          select 1 from command_ids x
          join public.invoice_operation_chunks c
            on c.chunk_type='ISSUE_INVOICE' and c.entity_type='INVOICE'
            and c.entity_id=x.id_text::uuid
            and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
          where x.command_no=r.command_no and x.valid_uuid)
          and not exists(
            select 1
            from public.invoice_operations exact
            join issue_facts f on f.command_no=r.command_no
            join issue_delivery_intents intent on intent.command_no=r.command_no
            where exact.idempotency_key=encode(digest(concat_ws('|',
              'ISSUE_INVOICES',f.invoice_revision_hash,
              coalesce(r.command_json->>'allow_early','false'),
              coalesce(r.command_json->>'deliver','false'),
              coalesce(r.command_json->>'command_token',''),
              encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
              'sha256'),'hex')
              and exact.status in(
                'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED'))
          then 'ACTIVE_ISSUE_CONFLICT'
        when r.command_type='DELIVER_INVOICES'
          and not(
            jsonb_typeof(r.command_json->'invoice_ids')='array'
            or nullif(btrim(coalesce(r.command_json->>'invoice_id','')),'') is not null)
          then 'DELIVERY_INVOICE_IDS_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and nullif(btrim(coalesce(
            r.command_json->>'delivery_request_token','')),'') is null
          then 'DELIVERY_REQUEST_TOKEN_REQUIRED'
        when r.command_type='DELIVER_INVOICES'
          and coalesce(cardinality((select ids from canonical_ids x
            where x.command_no=r.command_no)),0)>500
          then 'OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'recipient_set'
          and jsonb_typeof(r.command_json->'recipient_set')<>'array'
          then 'DELIVERY_RECIPIENT_SET_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and ((r.command_json?'cc' and jsonb_typeof(r.command_json->'cc')<>'array')
            or(r.command_json?'bcc' and jsonb_typeof(r.command_json->'bcc')<>'array'))
          then 'DELIVERY_CC_BCC_MUST_BE_ARRAY'
        when r.command_type='DELIVER_INVOICES'
          and exists(select 1 from recipient_sets rs
            where rs.command_no=r.command_no and rs.invalid_count>0)
          then 'DELIVERY_RECIPIENT_SET_INVALID'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_part_number'
          and coalesce(r.command_json->>'delivery_part_number','') !~ '^[1-9][0-9]*$'
          then 'INVALID_DELIVERY_PART_NUMBER'
        when r.command_type='DELIVER_INVOICES'
          and r.command_json?'delivery_policy'
          and upper(coalesce(r.command_json->>'delivery_policy',''))
            not in('ATTACH','SPLIT','SECURE_LINK')
          then 'INVALID_DELIVERY_POLICY'
        when r.command_type='DELIVER_INVOICES'
          and(coalesce((select resolved_count from delivery_facts f
              where f.command_no=r.command_no),0)<>
              coalesce(cardinality((select ids from canonical_ids x
                where x.command_no=r.command_no)),0))
          then 'ISSUED_DOCUMENT_NOT_READY'
        when r.command_type='RECONCILE'
          and not(r.command_json?'operation_ids'
            or r.command_json?'older_than_seconds') then 'RECONCILE_SCOPE_REQUIRED'
        when r.command_type='RECONCILE'
          and r.command_json?'operation_ids'
          and jsonb_typeof(r.command_json->'operation_ids')<>'array'
          then 'RECONCILE_OPERATION_IDS_MUST_BE_ARRAY'
        when r.command_type='RECONCILE'
          and jsonb_typeof(r.command_json->'operation_ids')='array'
          and jsonb_array_length(r.command_json->'operation_ids')>500
          then 'RECONCILE_OPERATION_SCOPE_TOO_LARGE'
        when r.command_type='RECONCILE'
          and r.command_json?'older_than_seconds'
          and coalesce(r.command_json->>'older_than_seconds','') !~ '^[0-9]{1,6}$'
          then 'RECONCILE_AGE_MUST_BE_INTEGER_SECONDS'
      end error_code,
      case when r.command_type like 'GENERATE_%' then (
        select jsonb_agg(jsonb_build_object(
          'group_key',g.group_key,'code',g.blocker_code,'detail',g.blocker_detail)
          order by g.group_key)
        from generation_groups g
        where g.command_no=r.command_no and g.blocker_code is not null)
      end error_detail
    from raw r cross join(select count(*) from issue_entity_locks) lock_barrier
  ),
  valid_commands as materialized (
    select r.* from raw r join command_validation v using(command_no,command_type)
    where v.error_code is null
  ),
  inserted_assets as materialized (
    insert into public.invoice_document_assets(
      source_kind,source_id,source_revision,original_r2_key,original_filename,
      declared_media_type,orientation_degrees,status,normalised_manifest_json,
      created_at_utc,updated_at_utc)
    select a.source_kind,a.source_id,a.source_revision,a.original_r2_key,
      a.original_filename,a.declared_media_type,a.rotation_degrees,
      'DISCOVERED','[]'::jsonb,v_now,v_now
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    on conflict(source_kind,source_id,source_revision,original_r2_key) do nothing
    returning *
  ),
  assets as materialized (
    select a.command_no,inserted.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join inserted_assets inserted
      on inserted.source_kind=a.source_kind
      and inserted.source_id=a.source_id
      and inserted.source_revision=a.source_revision
      and inserted.original_r2_key=a.original_r2_key
    union all
    select a.command_no,registered.*
    from asset_specs a
    join valid_commands v on v.command_no=a.command_no
    join public.invoice_document_assets registered
      on registered.source_kind=a.source_kind
      and registered.source_id=a.source_id
      and registered.source_revision=a.source_revision
      and registered.original_r2_key=a.original_r2_key
    where not exists(
      select 1 from inserted_assets inserted
      where inserted.source_kind=a.source_kind
        and inserted.source_id=a.source_id
        and inserted.source_revision=a.source_revision
        and inserted.original_r2_key=a.original_r2_key)
  ),
  asset_workflow_state as materialized (
    select a.*,
      exists(
        select 1
        from public.invoice_operation_chunks c
        join public.invoice_operations o on o.id=c.operation_id
        where c.document_asset_id=a.id
          and c.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE')
          and c.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
          and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      ) has_active_work
    from assets a
  ),
  operation_specs as materialized (
    select v.command_no,v.command_type,v.command_json,
      'GENERATE_INVOICES'::text operation_type,
      case when v.command_type='GENERATE_CREDIT_NOTE' then 'INVOICE'
        when count(*)=1 then 'CLIENT' else 'INVOICE_BATCH' end entity_type,
      case when v.command_type='GENERATE_CREDIT_NOTE'
        then (v.command_json->>'base_invoice_id')::uuid
        when count(*)=1 then(array_agg(g.client_id order by g.client_id))[1]
        else null::uuid end entity_id,
      encode(digest(string_agg(g.source_revision_hash,'|' order by g.group_key),
        'sha256'),'hex') source_revision,
      null::text template_version,
      case when v.command_type='GENERATE_AUTO' then 200 else 600 end priority,
      count(*)::integer unit_count,
      jsonb_build_object('generation_groups',
        jsonb_agg(g.idempotency_components order by g.group_key)) canonical_input,
      encode(digest('GENERATE_INVOICES|'||
        string_agg(g.idempotency_components::text,'|' order by g.group_key),
        'sha256'),'hex') idempotency_key
    from valid_commands v join generation_groups g on g.command_no=v.command_no
    where v.command_type like 'GENERATE_%'
    group by v.command_no,v.command_type,v.command_json
    union all
    select v.command_no,v.command_type,v.command_json,'BUILD_DOCUMENT',
      f.entity_type,f.entity_id,f.document_revision::text,f.template_version,1000,1,
      jsonb_build_object('entity_type',f.entity_type,'entity_id',f.entity_id,
        'purpose',f.purpose,'document_revision',f.document_revision,
        'template_version',f.template_version),
      encode(digest(concat_ws('|','BUILD_DOCUMENT',f.entity_type,f.entity_id::text,
        f.purpose,f.document_revision::text,f.template_version),'sha256'),'hex')
    from valid_commands v join view_facts f on f.command_no=v.command_no
    where v.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and not exists(
        select 1 from public.invoice_document_versions ready
        where ready.entity_type=f.entity_type and ready.entity_id=f.entity_id
          and ready.purpose=f.purpose
          and ready.source_revision=f.document_revision::text
          and ready.template_version=f.template_version and ready.status='READY')
    union all
    select v.command_no,v.command_type,v.command_json,'PREPARE_ASSET',
      'DOCUMENT_ASSET',a.id,a.source_revision,null,550,1,
      jsonb_build_object('document_asset_id',a.id,'source_kind',a.source_kind,
        'source_id',a.source_id,'source_revision',a.source_revision,
        'original_r2_key',a.original_r2_key),
      encode(digest(concat_ws('|','PREPARE_ASSET',a.source_kind,a.source_id::text,
        a.source_revision,a.original_r2_key),'sha256'),'hex')
    from valid_commands v join asset_workflow_state a
      on a.command_no=v.command_no
    where v.command_type='PREPARE_ASSET'
      and a.status in('DISCOVERED','INSPECTING','NORMALISING')
      and not(a.status in('INSPECTING','NORMALISING')
        and not a.has_active_work)
    union all
    select v.command_no,v.command_type,v.command_json,'ISSUE_INVOICES',
      'INVOICE_BATCH',null,f.invoice_revision_hash,null,850,
      cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'invoice_revision_hash',f.invoice_revision_hash,
        'allow_early',coalesce(v.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(v.command_json->'deliver','false'::jsonb),
        'command_token',v.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(v.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      encode(digest(concat_ws('|','ISSUE_INVOICES',f.invoice_revision_hash,
        coalesce(v.command_json->>'allow_early','false'),
        coalesce(v.command_json->>'deliver','false'),
        coalesce(v.command_json->>'command_token',''),
        encode(digest(intent.canonical_intent::text,'sha256'),'hex')),
        'sha256'),'hex')
    from valid_commands v join issue_facts f on f.command_no=v.command_no
    join issue_delivery_intents intent on intent.command_no=v.command_no
    where v.command_type='ISSUE_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'DELIVER_INVOICES',
      'INVOICE_BATCH',null,f.delivery_revision,
      coalesce(nullif(v.command_json->>'delivery_template_version',''),
        'invoice-delivery-v1'),400,cardinality(f.invoice_ids),
      jsonb_build_object('invoice_ids',to_jsonb(f.invoice_ids),
        'issued_document_version_ids',to_jsonb(f.document_version_ids),
        'delivery_revision',f.delivery_revision,
        'recipient_set',rs.canonical_recipients,
        'recipient_set_hash',drg.route_set_hash,
        'frozen_delivery_routes',drg.frozen_routes,
        'template_version',coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_part_number',coalesce(v.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',v.command_json->>'delivery_request_token'),
      encode(digest(concat_ws('|','DELIVER_INVOICES',f.delivery_revision,
        drg.route_set_hash,
        coalesce(nullif(v.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(v.command_json->>'delivery_part_number','1'),
        v.command_json->>'delivery_request_token'),'sha256'),'hex')
    from valid_commands v join delivery_facts f on f.command_no=v.command_no
    join recipient_sets rs on rs.command_no=v.command_no
    join delivery_route_groups drg on drg.command_no=v.command_no
    where v.command_type='DELIVER_INVOICES'
    union all
    select v.command_no,v.command_type,v.command_json,'RECONCILE_INVOICE_WORK',
      'SYSTEM',null,
      encode(digest(coalesce(v.command_json->'operation_ids','[]')::text||'|'||
        coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex'),
      null,50,1,
      jsonb_build_object(
        'operation_ids',coalesce(v.command_json->'operation_ids','[]'::jsonb),
        'older_than_seconds',least(604800,greatest(30,case
          when coalesce(v.command_json->>'older_than_seconds','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'older_than_seconds')::integer else 300 end)),
        'max_rows',least(500,greatest(1,case
          when coalesce(v.command_json->>'max_rows','') ~ '^[0-9]{1,6}$'
            then(v.command_json->>'max_rows')::integer else 100 end))),
      encode(digest('RECONCILE|'||coalesce(v.command_json->'operation_ids','[]')::text||
        '|'||coalesce(v.command_json->>'older_than_seconds',''),'sha256'),'hex')
    from valid_commands v where v.command_type='RECONCILE'
  ),
  locks as materialized (
    select pg_advisory_xact_lock(hashtextextended(x.lock_key,0))
    from(
      select idempotency_key lock_key from operation_specs
      union
      select 'ISSUE_INVOICE|'||unnest(f.invoice_ids)::text
      from issue_facts f join valid_commands v on v.command_no=f.command_no
      where v.command_type='ISSUE_INVOICES'
    ) x order by x.lock_key
  ),
  existing_before as materialized (
    select s.command_no,o.*
    from operation_specs s
    join lateral (
      select candidate.*
      from public.invoice_operations candidate
      where candidate.idempotency_key=s.idempotency_key
        and candidate.status in(
          'QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED','COMPLETE')
      order by(candidate.status='COMPLETE') desc,candidate.created_at_utc desc
      limit 1
    ) o on true
  ),
  inserted_operations as materialized (
    insert into public.invoice_operations(
      operation_type,entity_type,entity_id,actor_user_id,idempotency_key,
      status,phase,priority,source_revision,template_version,input_json,
      config_json,progress_json,total_units,chunk_count,control_version,
      change_seq,manifest_generation,manifest_committed,release_complete,
      created_at_utc,updated_at_utc)
    select s.operation_type,s.entity_type,s.entity_id,p_actor_user_id,
      s.idempotency_key,'QUEUED','SUBMITTED',s.priority,s.source_revision,
      s.template_version,s.canonical_input,
      jsonb_build_object(
        'command_type',s.command_type,
        'processor_policy',private._invoice_processor_limits()),
      jsonb_build_object('status_message','Accepted','total_units',s.unit_count,
        'completed_units',0,'failed_units',0),
      s.unit_count,s.unit_count,1,nextval('public.invoice_operation_change_seq'),
      case when s.command_type in ('ISSUE_INVOICES','DELIVER_INVOICES')
        then 1 else 0 end,
      true,true,
      v_now,v_now
    from operation_specs s cross join(select count(*) from locks) lock_barrier
    where not exists(select 1 from existing_before e where e.command_no=s.command_no)
    on conflict do nothing
    returning *
  ),
  chosen as materialized (
    select s.*,coalesce(i.id,e.id) operation_id,
      coalesce(i.status,e.status) operation_status,
      coalesce(i.phase,e.phase) operation_phase,
      coalesce(i.control_version,e.control_version) control_version,
      coalesce(i.change_seq,e.change_seq) change_seq,
      coalesce(i.priority,e.priority,s.priority) current_priority,
      i.id is not null created,e.id is not null reused
    from operation_specs s
    left join inserted_operations i on i.idempotency_key=s.idempotency_key
    left join existing_before e on e.command_no=s.command_no
  ),
  raised as materialized (
    update public.invoice_operations o
    set priority=greatest(o.priority,c.priority),updated_at_utc=v_now,
        change_seq=case when o.priority<c.priority
          then nextval('public.invoice_operation_change_seq') else o.change_seq end
    from chosen c
    where c.reused and o.id=c.operation_id
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    returning o.id
  ),
  existing_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
      and v.status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
  ),
  document_versions as materialized (
    insert into public.invoice_document_versions(
      entity_type,entity_id,purpose,operation_id,source_revision,template_version,
      status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select f.entity_type,f.entity_id,f.purpose,c.operation_id,
      f.document_revision::text,f.template_version,'PLANNING','{}'::jsonb,
      encode(digest('{}','sha256'),'hex'),'[]'::jsonb,
      encode(digest('[]','sha256'),'hex'),v_now
    from chosen c join view_facts f on f.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE'
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET') and status in(
        'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning *
  ),
  all_document_versions as materialized (
    select c.command_no,c.operation_id,v.*
    from chosen c join view_facts f on f.command_no=c.command_no
    join document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select e.* from existing_document_versions e
  ),
  chunk_specs as materialized (
    select c.operation_id,'GENERATION_GROUP'::text chunk_type,
      'VALIDATE_SOURCES'::text phase,
      encode(digest(concat_ws('|','GENERATION_GROUP',g.group_key,
        g.source_revision_hash,c.command_type,
        coalesce(g.idempotency_components->>'consolidation_mode',''),
        coalesce(g.idempotency_components->>'invoice_stream',''),'1'),
        'sha256'),'hex') work_key,
      row_number() over(partition by c.operation_id order by g.group_key)::integer-1 sequence_no,
      case when c.command_type='GENERATE_CREDIT_NOTE' then 'INVOICE' else 'CLIENT' end entity_type,
      case when c.command_type='GENERATE_CREDIT_NOTE'
        then (c.command_json->>'base_invoice_id')::uuid else g.client_id end entity_id,
      null::uuid document_version_id,
      null::uuid document_asset_id,
      g.idempotency_components||jsonb_build_object(
        'canonical_source_ids',to_jsonb(g.canonical_source_ids),
        'canonical_source_members',g.canonical_source_members,
        'source_types',to_jsonb(g.source_types),
        'source_revision',g.source_revision_hash,
        'resolver_blocker_code',g.blocker_code,
        'resolver_blocker_detail',g.blocker_detail) payload_json,
      c.priority,c.control_version
    from chosen c join generation_groups g on g.command_no=c.command_no
    where c.command_type like 'GENERATE_%' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',v.id::text,
        f.document_revision::text,f.template_version,'1'),'sha256'),'hex'),
      0,f.entity_type,f.entity_id,
      v.id,null,jsonb_build_object('purpose',f.purpose,
        'source_revision',f.document_revision::text,
        'template_version',f.template_version),c.priority,c.control_version
    from chosen c join view_facts f on f.command_no=c.command_no
    join all_document_versions v on v.command_no=c.command_no
    where c.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
      and c.operation_status<>'COMPLETE' and v.status<>'READY'
    union all
    select c.operation_id,'ASSET_INSPECT','INSPECT',
      encode(digest(concat_ws('|','ASSET_INSPECT',a.id::text,a.source_revision,
        private._invoice_processor_limits()->>'policy_version'),'sha256'),'hex'),
      0,'DOCUMENT_ASSET',a.id,
      null,a.id,jsonb_build_object('source_revision',a.source_revision,
        'source_kind',a.source_kind,'source_id',a.source_id,
        'rotation_degrees',a.orientation_degrees),c.priority,c.control_version
    from chosen c join assets a on a.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and c.operation_status<>'COMPLETE'
      and a.status not in('READY','INSPECTING','NORMALISING')
    union all
    select c.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',i.id::text,
        i.document_revision::text,c.command_json->>'command_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,null,null,
      jsonb_build_object(
        'request_key',c.command_no::text||':'||i.id::text,
        'invoice_id',i.id,'source_revision',i.document_revision,
        'evaluation_date',(v_now at time zone 'Europe/London')::date,
        'frozen_issue_at_utc',v_now,
        'allow_early',coalesce(c.command_json->'allow_early','false'::jsonb),
        'deliver',coalesce(c.command_json->'deliver','false'::jsonb),
        'command_token',c.command_json->>'command_token',
        'delivery_request_token','ISSUE:'||(c.command_json->>'command_token'),
        'delivery_intent',intent.canonical_intent),
      c.priority,c.control_version
    from chosen c join issue_facts f on f.command_no=c.command_no
    join issue_delivery_intents intent on intent.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    where c.command_type='ISSUE_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'DELIVERY_PREPARE','PREPARE',
      encode(digest(concat_ws('|','DELIVERY_PREPARE',
        i.issued_document_version_id::text,dr.route_policy_hash,
        coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        coalesce(c.command_json->>'delivery_part_number','1'),
        c.command_json->>'delivery_request_token'),'sha256'),'hex'),
      row_number() over(partition by c.operation_id order by i.id)::integer-1,
      'INVOICE',i.id,i.issued_document_version_id,null,
      jsonb_build_object(
        'invoice_id',i.id,'issued_document_version_id',i.issued_document_version_id,
        'recipient_set',dr.canonical_to,'cc',dr.canonical_cc,
        'bcc',dr.canonical_bcc,
        'recipient_set_hash',dr.recipient_set_hash,
        'route_policy_hash',dr.route_policy_hash,
        'routing_request',jsonb_build_object(
          'request_key',dr.request_key,
          'invoice_id',i.id,
          'recipient_set',rs.canonical_recipients,
          'cc',dr.canonical_cc,
          'bcc',dr.canonical_bcc,
          'delivery_policy',upper(coalesce(
            nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
          'template_version',coalesce(
            nullif(c.command_json->>'delivery_template_version',''),
            'invoice-delivery-v1')),
        'frozen_delivery_route',jsonb_build_object(
          'request_key',dr.request_key,
          'to',dr.canonical_to,'cc',dr.canonical_cc,'bcc',dr.canonical_bcc,
          'recipient_set_hash',dr.recipient_set_hash,
          'route_policy_hash',dr.route_policy_hash,
          'route_source',dr.route_source,'do_not_send',dr.do_not_send,
          'delivery_suppressed',dr.delivery_suppressed,
          'suppression_reason',dr.suppression_reason,
          'self_bill',dr.self_bill,
          'template_version',coalesce(
            nullif(c.command_json->>'delivery_template_version',''),
            'invoice-delivery-v1'),
          'delivery_policy',upper(coalesce(
            nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
          'warning_codes',dr.warning_codes,'blocker_codes',dr.blocker_codes,
          'evaluated_date',(v_now at time zone 'Europe/London')::date),
        'template_version',coalesce(nullif(c.command_json->>'delivery_template_version',''),
          'invoice-delivery-v1'),
        'delivery_policy',upper(coalesce(
          nullif(c.command_json->>'delivery_policy',''),'ATTACH')),
        'delivery_part_number',coalesce(c.command_json->'delivery_part_number','1'::jsonb),
        'delivery_request_token',encode(digest(concat_ws('|',
          'DELIVERY_REQUEST',c.command_json->>'delivery_request_token',
          i.id::text,i.issued_document_version_id::text),'sha256'),'hex'),
        'user_command_token',c.command_json->>'delivery_request_token'),
      c.priority,c.control_version
    from chosen c join delivery_facts f on f.command_no=c.command_no
    join recipient_sets rs on rs.command_no=c.command_no
    cross join unnest(f.invoice_ids) invoice_id
    join public.invoices i on i.id=invoice_id
    join delivery_routes dr on dr.command_no=c.command_no
      and dr.request_key=c.command_no::text||':'||i.id::text
      and dr.invoice_id=i.id
    where c.command_type='DELIVER_INVOICES' and c.operation_status<>'COMPLETE'
    union all
    select c.operation_id,'RECONCILE','RECONCILE',
      encode(digest(concat_ws('|','RECONCILE',c.canonical_input::text,'1'),
        'sha256'),'hex'),
      0,'SYSTEM',null,null,null,
      c.canonical_input,c.priority,c.control_version
    from chosen c where c.command_type='RECONCILE' and c.operation_status<>'COMPLETE'
  ),
  inserted_chunks as materialized (
    insert into public.invoice_operation_chunks(
      id,operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,document_asset_id,status,priority,run_after_utc,
      payload_json,operation_control_version,manifest_generation,
      is_manifest_member,manifest_committed,result_visible,
      created_at_utc,updated_at_utc)
    select generated.id,c.operation_id,c.chunk_type,c.phase,c.work_key,c.sequence_no,
      c.entity_type,c.entity_id,
      c.document_version_id,c.document_asset_id,'QUEUED',c.priority,v_now,
      case when c.chunk_type='DELIVERY_PREPARE'
        then jsonb_set(
          jsonb_set(
            jsonb_set(
              coalesce(c.payload_json,'{}'::jsonb),
              '{request_key}',
              to_jsonb(generated.id::text),
              true),
            '{routing_request,request_key}',
            to_jsonb(generated.id::text),
            true),
          '{frozen_delivery_route,request_key}',
          to_jsonb(generated.id::text),
          true)
        else c.payload_json end,
      c.control_version,
      case when c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE')
        then 1 else 0 end,
      c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE'),
      c.chunk_type in ('ISSUE_INVOICE','DELIVERY_PREPARE'),
      false,
      v_now,v_now
    from chunk_specs c
    cross join lateral (
      select gen_random_uuid() id
      where c.operation_id is not null
    ) generated
    on conflict do nothing
    returning *
  ),
  asset_operation_links as (
    update public.invoice_document_assets a
    set operation_id=c.operation_id,
        status=case when a.status='DISCOVERED' then 'INSPECTING' else a.status end,
        updated_at_utc=v_now
    from chosen c join assets x on x.command_no=c.command_no
    where c.command_type='PREPARE_ASSET' and a.id=x.id and a.status<>'READY'
    returning a.id
  ),
  entity_pointers as (
    update public.invoices i
    set active_document_operation_id=case
          when c.command_type='VIEW_INVOICE_DOCUMENT' then c.operation_id
          else i.active_document_operation_id end,
        document_state=case when c.command_type='VIEW_INVOICE_DOCUMENT'
          then 'QUEUED' else i.document_state end,
        active_issue_operation_id=case when c.command_type='ISSUE_INVOICES'
          then c.operation_id else i.active_issue_operation_id end,
        issue_state=case when c.command_type='ISSUE_INVOICES'
          then 'VALIDATING' else i.issue_state end,
        updated_at=v_now
    from chosen c
    where(c.command_type='VIEW_INVOICE_DOCUMENT' and i.id=c.entity_id)
      or(c.command_type='ISSUE_INVOICES' and exists(
        select 1
        from issue_facts f
        where f.command_no=c.command_no
          and i.id=any(f.invoice_ids)))
    returning i.id
  ),
  timesheet_pointers as (
    update public.timesheets t
    set active_document_operation_id=c.operation_id,document_state='QUEUED',
        updated_at=v_now
    from chosen c
    where c.command_type='VIEW_TIMESHEET_DOCUMENT' and t.timesheet_id=c.entity_id
    returning t.timesheet_id
  ),
  refreshed_counts as (
    update public.invoice_operations o
    set total_units=greatest(o.total_units,q.n),
        chunk_count=greatest(o.chunk_count,q.n),
        progress_json=coalesce(o.progress_json,'{}'::jsonb)||jsonb_build_object(
          'status_message','Queued',
          'total_units',greatest(o.total_units,q.n)),
        updated_at_utc=v_now,
        change_seq=nextval('public.invoice_operation_change_seq')
    from(
      select intended.operation_id,count(*)::integer n
      from chunk_specs intended
      cross join(
        select count(*) from inserted_chunks
      ) ensure_chunk_insert
      group by intended.operation_id
    ) q
    where o.id=q.operation_id and o.status<>'COMPLETE'
    returning o.id,o.chunk_count n
  ),
  ready_results as (
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_version_id',v.id,'r2_key',v.r2_key,
      'created',false,'reused_active',false,'reused_ready',true,
      'priority_raised',false,'blocked',false,'terminal_error',null) result
    from raw r join view_facts f on f.command_no=r.command_no
    join public.invoice_document_versions v
      on v.entity_type=f.entity_type and v.entity_id=f.entity_id
      and v.purpose=f.purpose and v.source_revision=f.document_revision::text
      and v.template_version=f.template_version and v.status='READY'
    where r.command_type in('VIEW_INVOICE_DOCUMENT','VIEW_TIMESHEET_DOCUMENT')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',null,'status','READY',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',true,'priority_raised',false,'blocked',false,
      'terminal_error',null) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET' and a.status='READY'
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status',a.status,
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'terminal_error',coalesce(a.error_json,
        jsonb_build_object('code','ASSET_'||a.status))) result
    from raw r join assets a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED')
    union all
    select r.command_no,jsonb_build_object(
      'command_no',r.command_no,'command_type',r.command_type,
      'accepted',true,'operation_id',a.operation_id,'status','BLOCKED',
      'document_asset_id',a.id,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,'blocked',true,
      'retry_required',true,'reconcile_available',true,
      'terminal_error',jsonb_build_object(
        'code','ASSET_WORKFLOW_INCONSISTENT',
        'asset_status',a.status,'document_asset_id',a.id)) result
    from raw r join asset_workflow_state a on a.command_no=r.command_no
    where r.command_type='PREPARE_ASSET'
      and a.status in('INSPECTING','NORMALISING')
      and not a.has_active_work
  ),
  operation_results as (
    select c.command_no,jsonb_build_object(
      'command_no',c.command_no,'command_type',c.command_type,'accepted',true,
      'operation_id',c.operation_id,'operation_type',c.operation_type,
      'status',coalesce(o.status,c.operation_status),
      'phase',coalesce(o.phase,c.operation_phase),
      'source_revision',c.source_revision,
      'change_seq',coalesce(o.change_seq,c.change_seq),
      'created',c.created,
      'reused_active',c.reused and coalesce(o.status,c.operation_status)<>'COMPLETE',
      'reused_ready',c.reused and coalesce(o.status,c.operation_status)='COMPLETE',
      'priority_raised',c.reused and c.priority>c.current_priority,
      'blocked',coalesce(o.status,c.operation_status)='BLOCKED',
      'terminal_error',null,
      'chunk_count',greatest(c.unit_count,(select count(*)
        from chunk_specs intended
        where intended.operation_id=c.operation_id)))
      result
    from chosen c
    left join public.invoice_operations o on o.id=c.operation_id
    left join refreshed_counts rc on rc.id=c.operation_id
  ),
  error_results as (
    select v.command_no,jsonb_build_object(
      'command_no',v.command_no,'command_type',v.command_type,
      'accepted',false,'created',false,'reused_active',false,
      'reused_ready',false,'priority_raised',false,
      'blocked',false,
      'terminal_error',jsonb_build_object('code',v.error_code,
        'detail',v.error_detail),
      'error',jsonb_build_object('code',v.error_code,'detail',v.error_detail)) result
    from command_validation v where v.error_code is not null
  ),
  combined as (
    select * from ready_results
    union all
    select o.* from operation_results o
    where not exists(select 1 from ready_results r where r.command_no=o.command_no)
    union all
    select * from error_results
  )
  select coalesce(jsonb_agg(result order by command_no),'[]'::jsonb)
  into v_result from combined;

  return v_result;
end;
$function$;

create or replace function private._invoice_generation_resolve_command_groups(
  p_commands jsonb,
  p_actor_user_id uuid,
  p_effective_at_utc timestamptz
) returns table(
  command_no integer,
  command_type text,
  group_key text,
  canonical_source_ids uuid[],
  canonical_source_members jsonb,
  source_types text[],
  client_id uuid,
  contract_ids uuid[],
  target_invoice_week date,
  natural_source_weeks date[],
  consolidation_mode text,
  invoice_stream text,
  self_bill boolean,
  automatic boolean,
  source_origin text,
  allow_early boolean,
  effective_settings_date date,
  source_revision_hash text,
  idempotency_components jsonb,
  blocker_code text,
  blocker_detail jsonb
)
language sql
stable
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
with raw_commands as materialized (
  select e.ordinality::integer command_no,e.value command_json,
    upper(btrim(coalesce(e.value->>'command_type',e.value->>'type',''))) command_type
  from jsonb_array_elements(
    case when jsonb_typeof(p_commands)='array' then p_commands else '[]'::jsonb end
  ) with ordinality e(value,ordinality)
),
generation_commands as materialized (
  select r.*,
    case
      when r.command_type='GENERATE_NHSP'
        and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
        then r.command_json->'nhsp_shift_ids'
      when jsonb_typeof(r.command_json->'source_ids')='array'
        then r.command_json->'source_ids'
      when jsonb_typeof(r.command_json->'canonical_source_ids')='array'
        then r.command_json->'canonical_source_ids'
      when jsonb_typeof(r.command_json->'timesheet_ids')='array'
        then r.command_json->'timesheet_ids'
      when r.command_type='GENERATE_CREDIT_NOTE'
        and jsonb_typeof(r.command_json->'invoice_ids')='array'
        then r.command_json->'invoice_ids'
      when r.command_type='GENERATE_CREDIT_NOTE'
        and coalesce(r.command_json->>'base_invoice_id','')<>''
        then jsonb_build_array(r.command_json->>'base_invoice_id')
      when r.command_type='GENERATE_CREDIT_NOTE'
        and coalesce(r.command_json->>'invoice_id','')<>''
        then jsonb_build_array(r.command_json->>'invoice_id')
      else '[]'::jsonb
    end requested_ids,
    case when lower(coalesce(r.command_json->>'allow_early','false')) in('true','false')
      then(r.command_json->>'allow_early')::boolean else false end allow_early,
    r.command_type='GENERATE_AUTO' automatic
  from raw_commands r
  where r.command_type in(
    'GENERATE_SELECTED','GENERATE_BY_WEEK','GENERATE_HOURS','GENERATE_EXPENSES',
    'GENERATE_NHSP','GENERATE_CREDIT_NOTE','GENERATE_AUTO')
),
raw_ids as materialized (
  select c.command_no,c.command_type,c.command_json,c.allow_early,c.automatic,
    x.ordinality::integer source_ordinal,x.value source_id_text,
    x.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      valid_uuid
  from generation_commands c
  cross join lateral jsonb_array_elements_text(c.requested_ids)
    with ordinality x(value,ordinality)
),
command_shape as materialized (
  select c.command_no,c.command_type,c.command_json,c.allow_early,c.automatic,
    jsonb_array_length(c.requested_ids) requested_count,
    count(r.source_id_text) filter(where r.valid_uuid)::integer valid_uuid_count,
    count(r.source_id_text) filter(where not r.valid_uuid)::integer invalid_uuid_count,
    coalesce(jsonb_agg(r.source_id_text order by r.source_ordinal)
      filter(where not r.valid_uuid),'[]'::jsonb) invalid_values
  from generation_commands c left join raw_ids r on r.command_no=c.command_no
  group by c.command_no,c.command_type,c.command_json,c.allow_early,c.automatic,c.requested_ids
),
resolved_ids as materialized (
  select distinct r.command_no,r.command_type,r.command_json,r.allow_early,r.automatic,
    case when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      then s.timesheet_id else r.source_id_text::uuid end timesheet_id,
    case when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      then 'NHSP_SHIFT' else 'TIMESHEET' end requested_source_type,
    case when r.command_type='GENERATE_NHSP'
          and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      then r.source_id_text::uuid else r.source_id_text::uuid end requested_source_id
  from raw_ids r
  left join public.nhsp_shifts s
    on r.command_type='GENERATE_NHSP'
      and jsonb_typeof(r.command_json->'nhsp_shift_ids')='array'
      and s.id=r.source_id_text::uuid
  where r.valid_uuid
),
base_sources as materialized (
  select r.*,ts.week_ending_date::date natural_week_ending,
    (ts.week_ending_date::date-6) natural_week_start,
    ts.version timesheet_version,ts.updated_at timesheet_updated_at,
    ts.is_current timesheet_is_current,ts.revoked_at,ts.is_adjustment,ts.adjustment_origin,
    ts.parent_timesheet_id,ts.correction_id,ts.correction_kind::text correction_kind,
    private.timesheet_correction_invoice_route_v1(r.timesheet_id) correction_invoice_route,
    tf.id tsfin_id,tf.timesheet_version tsfin_timesheet_version,
    tf.updated_at tsfin_updated_at,tf.is_current tsfin_is_current,tf.is_stale,
    tf.processing_status::text processing_status,tf.locked_by_invoice_id,
    tf.client_id,tf.candidate_id,tf.basis::text basis,tf.total_hours,
    tf.hours_day,tf.hours_night,tf.hours_sat,tf.hours_sun,tf.hours_bh,
    tf.additional_pay_ex_vat,tf.additional_charge_ex_vat,
    tf.expenses_pay_ex_vat,tf.expenses_charge_ex_vat,
    tf.mileage_pay_ex_vat,tf.mileage_charge_ex_vat,
    tf.travel_pay_ex_vat,tf.travel_charge_ex_vat,
    tf.accommodation_pay_ex_vat,tf.accommodation_charge_ex_vat,
    tf.other_pay_ex_vat,tf.other_charge_ex_vat,
    tf.invoice_breakdown_json,
    tf.additional_units_json,
    coalesce(
      ts.candidate_hint_text->'correction_financials_policy_envelope',
      tf.policy_snapshot_json->'correction_financials_policy_envelope',
      tf.rate_source_refs_json->'correction_financials_policy_envelope'
    ) correction_envelope,
    coalesce(ts.contract_id,cw.contract_id) contract_id,
    coalesce(parent_ts.contract_id,parent_cw.contract_id) parent_contract_id,
    coalesce((a.authority_json#>>'{values,self_bill}')::boolean,false) self_bill,
    nullif(btrim(coalesce(
      a.authority_json#>>'{values,candidate_expense_invoice_email}','')),'')
      contract_expense_invoice_email,
    a.authority_json settings_authority_json,
    case
      when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
      and (
        abs(coalesce(tf.total_hours,0))
        +abs(coalesce(tf.hours_day,0))+abs(coalesce(tf.hours_night,0))
        +abs(coalesce(tf.hours_sat,0))+abs(coalesce(tf.hours_sun,0))
        +abs(coalesce(tf.hours_bh,0))
        +abs(coalesce(tf.additional_pay_ex_vat,0))
        +abs(coalesce(tf.additional_charge_ex_vat,0))
      )=0
      and (
        abs(coalesce(tf.expenses_pay_ex_vat,0))
        +abs(coalesce(tf.expenses_charge_ex_vat,0))
        +abs(coalesce(tf.mileage_pay_ex_vat,0))
        +abs(coalesce(tf.mileage_charge_ex_vat,0))
        +abs(coalesce(tf.travel_pay_ex_vat,0))
        +abs(coalesce(tf.travel_charge_ex_vat,0))
        +abs(coalesce(tf.accommodation_pay_ex_vat,0))
        +abs(coalesce(tf.accommodation_charge_ex_vat,0))
        +abs(coalesce(tf.other_pay_ex_vat,0))
        +abs(coalesce(tf.other_charge_ex_vat,0))
      )>0 then 'EXPENSE'
      when upper(coalesce(tf.basis::text,'')) in(
        'NHSP','NHSP_ADJUSTMENT','HEALTHROSTER_SELF_BILL',
        'HEALTHROSTER_ADJUSTMENT'
      ) then 'SELF_BILL'
      when coalesce((a.authority_json#>>'{values,self_bill}')::boolean,false)
        then 'SELF_BILL'
      else 'NORMAL'
    end invoice_stream,
    case
      when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
      and (
        abs(coalesce(tf.total_hours,0))
        +abs(coalesce(tf.hours_day,0))+abs(coalesce(tf.hours_night,0))
        +abs(coalesce(tf.hours_sat,0))+abs(coalesce(tf.hours_sun,0))
        +abs(coalesce(tf.hours_bh,0))
        +abs(coalesce(tf.additional_pay_ex_vat,0))
        +abs(coalesce(tf.additional_charge_ex_vat,0))
      )=0
      and (
        abs(coalesce(tf.expenses_pay_ex_vat,0))
        +abs(coalesce(tf.expenses_charge_ex_vat,0))
        +abs(coalesce(tf.mileage_pay_ex_vat,0))
        +abs(coalesce(tf.mileage_charge_ex_vat,0))
        +abs(coalesce(tf.travel_pay_ex_vat,0))
        +abs(coalesce(tf.travel_charge_ex_vat,0))
        +abs(coalesce(tf.accommodation_pay_ex_vat,0))
        +abs(coalesce(tf.accommodation_charge_ex_vat,0))
        +abs(coalesce(tf.other_pay_ex_vat,0))
        +abs(coalesce(tf.other_charge_ex_vat,0))
      )>0 then 'EXPENSE'
      when upper(coalesce(tf.basis::text,'')) like 'NHSP%' then 'NHSP'
      when upper(coalesce(tf.basis::text,'')) like 'HEALTHROSTER%' then 'HEALTHROSTER'
      when upper(coalesce(tf.basis::text,'')) like '%EXPENSE%' then 'EXPENSE'
      when coalesce(ts.is_adjustment,false) then 'ADJUSTMENT'
      else 'TIMESHEET'
    end resolved_source_type
  from resolved_ids r
  left join public.timesheets ts on ts.timesheet_id=r.timesheet_id
  left join lateral (
    select private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)
      authority_json
    where ts.timesheet_id is not null
  ) a on true
  left join public.timesheets_financials tf
    on tf.timesheet_id=r.timesheet_id and tf.is_current
  left join lateral (
    select w.contract_id from public.contract_weeks w
    where w.timesheet_id=r.timesheet_id
    order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc limit 1
  ) cw on true
  left join public.timesheets parent_ts
    on parent_ts.timesheet_id=ts.parent_timesheet_id and parent_ts.is_current
  left join lateral (
    select w.contract_id from public.contract_weeks w
    where w.timesheet_id=parent_ts.timesheet_id
    order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc limit 1
  ) parent_cw on true
),
expanded_sources as materialized (
  select b.*,
    case
      when seg.segment_json is not null
        and pg_input_is_valid(
          coalesce(seg.segment_json->>'invoice_target_week_start',''),'date')
        then(seg.segment_json->>'invoice_target_week_start')::date
      when pg_input_is_valid(
          coalesce(b.command_json->>'target_invoice_week',''),'date')
        then(b.command_json->>'target_invoice_week')::date
      else b.natural_week_start end economic_target_week,
    seg.segment_json,seg.segment_ordinal,
    seg.segment_json->>'segment_id' segment_id,
    case
      when b.requested_source_type='NHSP_SHIFT' and b.timesheet_id is null
        then 'NHSP_SHIFT_TIMESHEET_REQUIRED'
      when b.timesheet_id is null then 'SOURCE_NOT_RESOLVED'
      when b.correction_invoice_route->>'route'='BLOCKED' then b.correction_invoice_route->>'blocker_code'
      when b.correction_invoice_route->>'route'='TIMESHEET_CREDIT' then 'WHOLE_REVERSAL_REQUIRES_TIMESHEET_CREDIT'
      when b.correction_invoice_route->>'route'='NO_INVOICE_PLACEMENT' then 'WHOLE_CORRECTION_NO_INVOICE_PLACEMENT'
      when b.correction_invoice_route->>'route'='RETURN_TO_SAME_DRAFT' then 'AGENCY_INVOICE_RETURNING_TO_DRAFT'
      when b.tsfin_id is null then 'CURRENT_FINANCIALS_MISSING'
      when b.timesheet_is_current is not true or b.revoked_at is not null
        then 'TIMESHEET_NOT_CURRENT'
      when b.tsfin_is_current is not true then 'CURRENT_FINANCIALS_MISSING'
      when b.is_stale then 'FINANCIALS_STALE'
      when b.processing_status<>'READY_FOR_INVOICE' then 'NOT_READY_FOR_INVOICE'
      when b.client_id is null then 'CLIENT_UNRESOLVED'
      when b.locked_by_invoice_id is not null
        and coalesce(b.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
        then 'SOURCE_ALREADY_LOCKED'
      when seg.segment_json is not null
        and nullif(btrim(coalesce(
          seg.segment_json->>'invoice_target_week_start','')),'') is not null
        and not pg_input_is_valid(
          seg.segment_json->>'invoice_target_week_start','date')
        then 'MALFORMED_SEGMENT_TARGET_WEEK'
      when seg.segment_json is not null and exists(
        select 1
        from (values
          (seg.segment_json->>'hours_day'),(seg.segment_json->>'hours_night'),
          (seg.segment_json->>'hours_sat'),(seg.segment_json->>'hours_sun'),
          (seg.segment_json->>'hours_bh'),(seg.segment_json->>'pay_amount'),
          (seg.segment_json->>'pay_ex_vat'),
          (seg.segment_json->>'charge_amount'),
          (seg.segment_json->>'charge_ex_vat')) n(value)
        where nullif(btrim(n.value),'') is not null
          and n.value!~'^[+-]?[0-9]+([.][0-9]+)?$')
        then 'MALFORMED_SEGMENT_FINANCIAL'
      when jsonb_typeof(b.additional_units_json)='object' and exists(
        select 1
        from jsonb_each(b.additional_units_json) a(key,value)
        where jsonb_typeof(a.value)<>'object'
          or exists(
            select 1
            from (values
              (a.value->>'unit_count'),(a.value->>'pay_rate'),
              (a.value->>'charge_rate'),(a.value->>'pay_ex_vat'),
              (a.value->>'charge_ex_vat')) n(value)
            where nullif(btrim(n.value),'') is not null
              and not pg_input_is_valid(n.value,'numeric'))
          or exists(
            select 1
            from jsonb_each_text(case
              when jsonb_typeof(a.value->'days')='object'
                then a.value->'days' else '{}'::jsonb end) d(key,value)
            where nullif(btrim(d.value),'') is not null
              and not pg_input_is_valid(d.value,'numeric')))
        then 'MALFORMED_ADDITIONAL_RATE'
      when seg.segment_json is not null
        and nullif(seg.segment_json->>'invoice_locked_invoice_id','') is not null
        then 'SEGMENT_ALREADY_LOCKED'
    end source_blocker
  from base_sources b
  left join lateral (
    select x.value segment_json,x.ordinality::integer segment_ordinal
    from jsonb_array_elements(
      case when jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
        then b.invoice_breakdown_json->'segments' else '[]'::jsonb end
    ) with ordinality x(value,ordinality)
    where coalesce(b.invoice_breakdown_json->>'mode','')='SEGMENTS'
      and jsonb_typeof(x.value)='object'
    union all
    select null::jsonb,0
    where coalesce(b.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
      or jsonb_array_length(case
        when jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
          then b.invoice_breakdown_json->'segments' else '[]'::jsonb end)=0
  ) seg on true
  where case
    when coalesce(b.command_json->>'target_invoice_week','')='' then true
    when not pg_input_is_valid(
      b.command_json->>'target_invoice_week','date') then true
    else coalesce(
      case when seg.segment_json is not null
          and pg_input_is_valid(
            coalesce(seg.segment_json->>'invoice_target_week_start',''),'date')
        then(seg.segment_json->>'invoice_target_week_start')::date end,
      b.natural_week_start)=(b.command_json->>'target_invoice_week')::date
    end
),
settings_resolved as materialized (
  select e.*,
    upper(coalesce(nullif(e.command_json->>'consolidation_mode',''),
      e.settings_authority_json#>>'{values,invoice_consolidation_mode}','NONE'))
      consolidation_mode,
    case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
      and e.invoice_stream='EXPENSE' then lower(nullif(btrim(coalesce(
      e.contract_expense_invoice_email,'')),''))
      else null::text end expense_delivery_identity,
    coalesce(e.economic_target_week,e.natural_week_start,
      (p_effective_at_utc at time zone 'Europe/London')::date) settings_date
  from expanded_sources e
),
source_rows_base as materialized (
  select s.*,
    case
      when s.consolidation_mode='NONE'
        and coalesce(s.is_adjustment,false)
        and upper(btrim(coalesce(s.adjustment_origin,'')))='IMPORT_CORRECTION'
        and nullif(btrim(coalesce(s.correction_id,'')),'') is not null
        and upper(btrim(coalesce(s.correction_kind,''))) in(
          'CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
        and jsonb_typeof(s.correction_envelope)='object'
        and s.correction_envelope->>'policy_schema_version'=
          'IMPORT_CORRECTION_FINANCIALS_POLICY_V2'
        and s.correction_envelope->>'route_family'='IMPORT_AUTHORITATIVE'
        and lower(coalesce(
          s.correction_envelope#>>'{classification,canonical}','false'))
          in('true','t','1','yes')
        and s.correction_envelope->>'correction_shape'=
          'REVERSAL_REPLACEMENT'
        and s.correction_envelope->>'expected_member_count'='2'
        and nullif(
          s.correction_envelope#>>'{operation,operation_id}','') is not null
        and nullif(
          s.correction_envelope->>'correction_chain_id','') is not null
        and s.correction_envelope#>>'{operation,correction_action}'=
          'CHANGED_HOURS'
        and s.correction_envelope->>'envelope_fingerprint'=
          encode(digest(convert_to(
            (s.correction_envelope-'envelope_fingerprint')::text,'UTF8'),
            'sha256'),'hex')
      then 'IMPORT_AUTHORITATIVE_CORRECTION:'||s.correction_id
      else s.timesheet_id::text
    end atomic_grouping_value,
    encode(digest(concat_ws('|',
      s.resolved_source_type,s.timesheet_id::text,
      coalesce(s.segment_id,'WHOLE'),s.economic_target_week::text),
      'sha256'),'hex') source_member_key,
    encode(digest(concat_ws('|',
      s.timesheet_id::text,s.tsfin_id::text,s.tsfin_timesheet_version::text,
      s.tsfin_updated_at::text,s.timesheet_version::text,s.timesheet_updated_at::text,
      coalesce(s.invoice_breakdown_json::text,''),coalesce(s.segment_id,'WHOLE'),
      coalesce(s.segment_json::text,''),coalesce(s.segment_json->>'segment_id',''),
      coalesce(s.segment_json->>'invoice_target_week_start',''),
      coalesce(s.segment_json->>'invoice_locked_invoice_id',''),
      coalesce(s.segment_json->>'ref_num',''),
      coalesce(s.segment_json->>'charge_amount',''),
      coalesce(s.segment_json->>'pay_amount',''),
      coalesce(s.economic_target_week::text,''),s.invoice_stream,s.consolidation_mode,
      case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then coalesce(s.expense_delivery_identity,'NO_EXPENSE_RECIPIENT') end),
      'sha256'),'hex') row_revision
  from settings_resolved s
),
pre_reference_groups as materialized (
  select
    s.command_no,
    s.client_id,
    s.invoice_stream,
    s.expense_delivery_identity,
    s.consolidation_mode,
    case
      when s.consolidation_mode='NONE' then s.atomic_grouping_value
      when s.consolidation_mode='BY_WEEK'
        then s.economic_target_week::text
      else 'ANY_WEEK'
    end grouping_value,
    encode(digest(concat_ws(
      '|',
      s.command_type,
      s.client_id::text,
      s.invoice_stream,
      case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then coalesce(s.expense_delivery_identity,'NO_EXPENSE_RECIPIENT') end,
      s.consolidation_mode,
      case
        when s.consolidation_mode='NONE' then s.atomic_grouping_value
        when s.consolidation_mode='BY_WEEK'
          then s.economic_target_week::text
        else 'ANY_WEEK'
      end,
      encode(digest(string_agg(concat_ws(
        ':',
        s.timesheet_id::text,
        coalesce(s.segment_id,'WHOLE'),
        s.economic_target_week::text
      ),'|' order by
        s.timesheet_id,
        coalesce(s.segment_id,'WHOLE')
      ),'sha256'),'hex')
    ),'sha256'),'hex') group_key
  from source_rows_base s
  group by
    s.command_no,
    s.command_type,
    s.client_id,
    s.invoice_stream,
    s.expense_delivery_identity,
    s.consolidation_mode,
    case
      when s.consolidation_mode='NONE' then s.atomic_grouping_value
      when s.consolidation_mode='BY_WEEK'
        then s.economic_target_week::text
      else 'ANY_WEEK'
    end
),
source_rows_scoped as materialized (
  select source_row.*
  from source_rows_base source_row
  join pre_reference_groups candidate_group
    on candidate_group.command_no=source_row.command_no
   and candidate_group.client_id=source_row.client_id
   and candidate_group.invoice_stream=source_row.invoice_stream
   and candidate_group.expense_delivery_identity is not distinct from
       source_row.expense_delivery_identity
   and candidate_group.consolidation_mode=
       source_row.consolidation_mode
   and candidate_group.grouping_value is not distinct from case
     when source_row.consolidation_mode='NONE'
       then source_row.atomic_grouping_value
     when source_row.consolidation_mode='BY_WEEK'
       then source_row.economic_target_week::text
     else 'ANY_WEEK'
   end
  join generation_commands command
    on command.command_no=source_row.command_no
  where jsonb_typeof(command.command_json->'scope_keys')
          is distinct from 'array'
     or jsonb_array_length(
          case
            when jsonb_typeof(
              command.command_json->'scope_keys'
            )='array'
              then command.command_json->'scope_keys'
            else '[]'::jsonb
          end
        )=0
     or exists (
       select 1
       from jsonb_array_elements_text(
         case
           when jsonb_typeof(
             command.command_json->'scope_keys'
           )='array'
             then command.command_json->'scope_keys'
           else '[]'::jsonb
         end
       ) requested_scope(scope_key)
       where requested_scope.scope_key=candidate_group.group_key
     )
),
reference_results as materialized (
  select distinct on (r.source_member_key) r.*
  from private._invoice_source_reference_validate_batch(coalesce((
    select jsonb_agg(jsonb_build_object(
      'source_member_key',b.source_member_key,
      'source_type',b.resolved_source_type,
      'source_id',b.timesheet_id,
      'related_timesheet_id',b.timesheet_id,
      'segment_id',b.segment_id,
      'target_invoice_week',b.economic_target_week,
      'invoice_stream',b.invoice_stream,
      'consolidation_mode',b.consolidation_mode,
      'row_revision',b.row_revision)
      order by b.command_no,b.timesheet_id,b.segment_ordinal)
    from source_rows_scoped b
  ),'[]'::jsonb)) r
  order by r.source_member_key
),
source_rows as materialized (
  select b.*,
    case
      when b.source_blocker is not null then b.source_blocker
      when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
       and b.invoice_stream='EXPENSE'
       and b.expense_delivery_identity is null
        then 'EXPENSE_INVOICE_EMAIL_REQUIRED'
      when r.blocker_code='INVOICE_REFERENCE_REQUIRED'
       and not (
         coalesce(precheck.require_reference_to_invoice,false)
         and coalesce(b.total_hours,0)>0
       ) then null
      else r.blocker_code
    end canonical_blocker,
    r.reference_hash,r.current_revision canonical_row_revision,
    r.detail_json reference_detail
  from source_rows_scoped b
  left join reference_results r
    on r.source_member_key=b.source_member_key
  left join public.v_ts_invoice_precheck precheck
    on precheck.timesheet_id=b.timesheet_id
),
grouped as materialized (
  select s.command_no,s.command_type,
    encode(digest(concat_ws('|',s.command_type,s.client_id::text,s.invoice_stream,
      case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then coalesce(s.expense_delivery_identity,'NO_EXPENSE_RECIPIENT') end,
      s.consolidation_mode,
      case
        when s.consolidation_mode='NONE' then s.atomic_grouping_value
        when s.consolidation_mode='BY_WEEK' then s.economic_target_week::text
        else 'ANY_WEEK' end,
      encode(digest(string_agg(concat_ws(':',s.timesheet_id::text,
        coalesce(s.segment_id,'WHOLE'),s.economic_target_week::text)
        ,'|' order by s.timesheet_id,coalesce(s.segment_id,'WHOLE')),'sha256'),'hex')),
      'sha256'),'hex') group_key,
    array_agg(distinct s.timesheet_id order by s.timesheet_id)
      filter(where s.timesheet_id is not null) canonical_source_ids,
    jsonb_agg(jsonb_build_object(
      'source_member_key',s.source_member_key,
      'source_type',s.resolved_source_type,
      'source_id',s.timesheet_id,
      'related_timesheet_id',s.timesheet_id,
      'requested_source_type',s.requested_source_type,
      'requested_source_id',s.requested_source_id,
      'natural_week_start',s.natural_week_start,
      'target_invoice_week',s.economic_target_week,
      'segment_id',s.segment_id,
      'segment_ordinal',s.segment_ordinal,
      'row_revision',coalesce(s.canonical_row_revision,s.row_revision))
      order by s.economic_target_week,s.timesheet_id,s.segment_ordinal)
      canonical_source_members,
    array_agg(distinct s.resolved_source_type order by s.resolved_source_type)
      source_types,
    s.client_id,
    array_agg(distinct coalesce(s.parent_contract_id,s.contract_id)
      order by coalesce(s.parent_contract_id,s.contract_id))
      filter(where coalesce(s.parent_contract_id,s.contract_id) is not null) contract_ids,
    case when s.consolidation_mode='ANY_WEEK' then null::date
      else min(s.economic_target_week) end target_invoice_week,
    array_agg(distinct s.natural_week_start order by s.natural_week_start)
      filter(where s.natural_week_start is not null) natural_source_weeks,
    s.consolidation_mode,s.invoice_stream,bool_or(s.self_bill) self_bill,
    bool_or(s.automatic) automatic,
    case when bool_or(s.command_type='GENERATE_AUTO') then 'AUTOMATIC'
      when bool_or(s.requested_source_type='NHSP_SHIFT') then 'NHSP_SELECTION'
      else 'MANUAL_SELECTION' end source_origin,
    bool_and(s.allow_early) allow_early,
    min(s.settings_date) effective_settings_date,
    encode(digest(string_agg(s.timesheet_id::text||':'||
      coalesce(s.canonical_row_revision,s.row_revision),
      '|' order by s.timesheet_id,s.segment_ordinal),'sha256'),'hex') source_revision_hash,
    coalesce(min(s.canonical_blocker),null) blocker_code,
    coalesce(jsonb_agg(jsonb_build_object(
      'source_id',s.timesheet_id,'segment_id',s.segment_id,
      'code',s.canonical_blocker,
      'reference_hash',s.reference_hash,
      'reference_detail',s.reference_detail)
      order by s.timesheet_id,s.segment_ordinal)
      filter(where s.canonical_blocker is not null),'[]'::jsonb) blocker_sources
  from source_rows s
  group by s.command_no,s.command_type,s.client_id,s.consolidation_mode,s.invoice_stream,
    s.expense_delivery_identity,
    case
      when s.consolidation_mode='NONE' then s.atomic_grouping_value
      when s.consolidation_mode='BY_WEEK' then s.economic_target_week::text
      else 'ANY_WEEK' end
),
normal_results as (
  select g.command_no,g.command_type,g.group_key,g.canonical_source_ids,
    g.canonical_source_members,g.source_types,g.client_id,g.contract_ids,
    g.target_invoice_week,g.natural_source_weeks,g.consolidation_mode,
    g.invoice_stream,g.self_bill,g.automatic,g.source_origin,g.allow_early,
    g.effective_settings_date,g.source_revision_hash,
    jsonb_build_object(
      'command_type',g.command_type,'group_key',g.group_key,
      'canonical_source_ids',to_jsonb(g.canonical_source_ids),
      'canonical_source_members',g.canonical_source_members,
      'client_id',g.client_id,'contract_ids',to_jsonb(g.contract_ids),
      'target_invoice_week',g.target_invoice_week,
      'natural_source_weeks',to_jsonb(g.natural_source_weeks),
      'consolidation_mode',g.consolidation_mode,'invoice_stream',g.invoice_stream,
      'self_bill',g.self_bill,'automatic',g.automatic,
      'source_origin',g.source_origin,'allow_early',g.allow_early,
      'effective_settings_date',g.effective_settings_date,
      'source_revision_hash',g.source_revision_hash) idempotency_components,
    g.blocker_code,
    case when g.blocker_code is null then null
      else jsonb_build_object('code',g.blocker_code,'sources',g.blocker_sources) end blocker_detail
  from grouped g
),
shape_errors as (
  select s.command_no,s.command_type,
    encode(digest('INVALID|'||s.command_no||'|'||s.command_type,'sha256'),'hex') group_key,
    array[]::uuid[] canonical_source_ids,'[]'::jsonb canonical_source_members,
    array[]::text[] source_types,null::uuid client_id,array[]::uuid[] contract_ids,
    null::date target_invoice_week,array[]::date[] natural_source_weeks,
    upper(coalesce(nullif(s.command_json->>'consolidation_mode',''),'NONE')) consolidation_mode,
    'UNKNOWN'::text invoice_stream,false self_bill,s.automatic,
    case when s.automatic then 'AUTOMATIC' else 'MANUAL_SELECTION' end source_origin,
    s.allow_early,
    (p_effective_at_utc at time zone 'Europe/London')::date effective_settings_date,
    encode(digest('INVALID','sha256'),'hex') source_revision_hash,
    jsonb_build_object('command_type',s.command_type,'invalid',true) idempotency_components,
    case
      when s.requested_count=0 then 'SOURCE_IDS_REQUIRED'
      when s.invalid_uuid_count>0 then 'MALFORMED_SOURCE_ID'
      when s.valid_uuid_count<>s.requested_count then 'MIXED_VALID_INVALID_SOURCE_IDS'
      when not exists(select 1 from resolved_ids r where r.command_no=s.command_no
        and r.timesheet_id is not null) then 'SOURCE_NOT_RESOLVED'
      when exists(
        select 1 from resolved_ids r
        left join public.timesheets t on t.timesheet_id=r.timesheet_id
        where r.command_no=s.command_no
          and(r.timesheet_id is null or t.timesheet_id is null)
      ) then 'SOURCE_NOT_RESOLVED'
    end blocker_code,
    jsonb_build_object(
      'requested_count',s.requested_count,'valid_uuid_count',s.valid_uuid_count,
      'invalid_uuid_count',s.invalid_uuid_count,'invalid_values',s.invalid_values) blocker_detail
  from command_shape s
  where s.command_type<>'GENERATE_CREDIT_NOTE' and (s.requested_count=0 or s.invalid_uuid_count>0
    or s.valid_uuid_count<>s.requested_count
    or not exists(select 1 from resolved_ids r where r.command_no=s.command_no
      and r.timesheet_id is not null)
    or exists(
      select 1 from resolved_ids r
      left join public.timesheets t on t.timesheet_id=r.timesheet_id
      where r.command_no=s.command_no
        and(r.timesheet_id is null or t.timesheet_id is null)
    ))
),
credit_results as (
  select s.command_no,s.command_type,
    encode(digest('CREDIT|'||i.id||'|'||
      coalesce(s.command_json->>'credit_reason','')||'|'||
      coalesce(s.command_json->>'command_token','')||
      case when s.command_json?'credit_scope' then '|'||coalesce(s.command_json#>>'{credit_scope,reversal_timesheet_id}','')
        ||'|'||coalesce(rev.revision,'INVALID') else '' end,'sha256'),'hex') group_key,
    array[i.id] canonical_source_ids,
    jsonb_build_array(jsonb_build_object(
      'source_type','INVOICE','source_id',i.id,'source_revision',
      rev.revision)) canonical_source_members,
    array['INVOICE']::text[] source_types,i.client_id,array[]::uuid[] contract_ids,
    null::date target_invoice_week,array[]::date[] natural_source_weeks,
    'CREDIT_NOTE'::text consolidation_mode,'CREDIT_NOTE'::text invoice_stream,
    false self_bill,false automatic,'MANUAL_SELECTION'::text source_origin,
    true allow_early,(i.updated_at at time zone 'Europe/London')::date effective_settings_date,
    rev.revision source_revision_hash,
    jsonb_build_object('command_type',s.command_type,'source_invoice_id',i.id,
      'source_revision',rev.revision,
      'credit_reason',s.command_json->>'credit_reason',
      'command_token',s.command_json->>'command_token')||case
      when s.command_json?'credit_scope' then jsonb_build_object('credit_scope',s.command_json->'credit_scope')
      else '{}'::jsonb end idempotency_components,
    case
      when i.id is null then 'INVOICE_NOT_FOUND'
      when i.type::text<>'INVOICE' then 'CREDIT_SOURCE_NOT_INVOICE'
      when i.status::text not in('ISSUED','PAID') then 'CREDIT_SOURCE_NOT_ISSUED'
      when s.command_json?'credit_scope' and (scope.ctx->>'valid')::boolean is distinct from true
        then coalesce(scope.ctx->>'blocker','CREDIT_SCOPE_INVALID')
      when not(s.command_json?'credit_scope') and exists(select 1 from public.invoices c
        where c.original_invoice_id=i.id and c.type='CREDIT_NOTE'
          and c.status in('DRAFT','ISSUED','PAID')) then 'CREDIT_ALREADY_EXISTS'
    end blocker_code,
    null::jsonb blocker_detail
  from command_shape s
  join raw_ids r on r.command_no=s.command_no and r.valid_uuid
  left join public.invoices i on i.id=r.source_id_text::uuid
  left join lateral(select case when s.command_json?'credit_scope' then
    private.invoice_credit_scope_context_v1(i.id,case when pg_input_is_valid(
      s.command_json#>>'{credit_scope,reversal_timesheet_id}','uuid')
      then(s.command_json#>>'{credit_scope,reversal_timesheet_id}')::uuid end,null,null,false) end ctx) scope on true
  cross join lateral(select case when s.command_json?'credit_scope' then scope.ctx->>'revision' else
    encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
        'sha256'),'hex') end revision) rev
  where s.command_type='GENERATE_CREDIT_NOTE'
    and s.requested_count>0 and s.invalid_uuid_count=0
)
select * from normal_results
where command_type<>'GENERATE_CREDIT_NOTE'
  and not exists(select 1 from shape_errors e where e.command_no=normal_results.command_no)
union all
select * from shape_errors
union all
select * from credit_results
order by command_no,group_key;
$function$;

create or replace function private._invoice_generation_advance_core_v8(
  p_claims jsonb,
  p_now_utc timestamptz
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_now timestamptz := coalesce(p_now_utc,now());
  v_result jsonb := '[]'::jsonb;
  v_part jsonb;
  v_scope_claim jsonb;
begin
  -- The optional scoped arm remains in this pipeline. Ordinary and whole
  -- commands retain the existing owner; QUEUE_DOCUMENT/issue is shared below.
  for v_scope_claim in select x.value from jsonb_array_elements(p_claims) x(value)
    join public.invoice_operation_chunks c on c.id=(x.value->>'chunk_id')::uuid
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE' and c.payload_json?'credit_scope'
      and x.value->>'phase' in('VALIDATE_SOURCES','PLAN','COMMIT')
  loop
    v_result:=v_result||jsonb_build_array(private.invoice_credit_scoped_advance_v1(v_scope_claim,v_now));
  end loop;
  select coalesce(jsonb_agg(x.value order by x.ordinality),'[]'::jsonb) into p_claims
    from jsonb_array_elements(p_claims) with ordinality x(value,ordinality)
    join public.invoice_operation_chunks c on c.id=(x.value->>'chunk_id')::uuid
    where not(c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE' and c.payload_json?'credit_scope'
      and x.value->>'phase' in('VALIDATE_SOURCES','PLAN','COMMIT'));
  -- VALIDATE_SOURCES: no invoice/header/line writes are permitted in this block.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  member_values as materialized (
    select c.id chunk_id,c.operation_id,c.payload_json,
      m.value member,m.ordinality
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
          and jsonb_array_length(c.payload_json->'canonical_source_members')>0
        then c.payload_json->'canonical_source_members'
        else coalesce((
          select jsonb_agg(jsonb_build_object(
            'source_type','TIMESHEET','source_id',s.value,
            'related_timesheet_id',s.value) order by s.ordinality)
          from jsonb_array_elements_text(coalesce(
            c.payload_json->'canonical_source_ids',
            c.payload_json->'source_ids','[]'::jsonb))
            with ordinality s(value,ordinality)
        ),'[]'::jsonb) end) with ordinality m(value,ordinality)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select m.chunk_id,m.operation_id,m.payload_json,m.member,
      upper(coalesce(m.member->>'source_type','TIMESHEET')) source_type,
      case when coalesce(m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(m.member->>'source_id')::uuid end source_id,
      case when coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id','')~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then coalesce(m.member->>'related_timesheet_id',
          m.member->>'source_id')::uuid end timesheet_id,
      nullif(btrim(m.member->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(m.member->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(m.member->>'source_type','TIMESHEET')),
          coalesce(m.member->>'source_id',''),
          coalesce(m.member->>'related_timesheet_id',''),
          coalesce(m.member->>'segment_id','WHOLE'),
          coalesce(m.member->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key,
      nullif(btrim(coalesce(m.member->>'row_revision',
        m.member->>'source_revision','')),'') expected_revision,
      m.ordinality
    from member_values m
  ),
  reference_eval as materialized (
    select distinct on (r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.member->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode',
        'source_revision',m.expected_revision)
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  vat_eval as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.ordinality)
      from members m
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-validate:'||scope.chunk_id::text,
      'scope_key',scope.chunk_id::text,
      'validation_purpose','GENERATION_VALIDATE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.chunk_id),'[]'::jsonb) scopes
    from(
      select m.chunk_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.ordinality) planned_members
      from members m
      left join vat_eval v on v.source_member_key=m.source_member_key
      group by m.chunk_id
    ) scope
  ),
  correction_eval as materialized (
    select r.*
    from correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_eval as materialized (
    select m.chunk_id,m.operation_id,m.timesheet_id,m.segment_id,
      m.source_member_key,m.ordinality,
      tf.id tsfin_id,
      encode(digest(concat_ws('|',tf.id::text,tf.timesheet_version::text,
        tf.updated_at::text,ts.version::text,ts.updated_at::text,
        coalesce(tf.invoice_breakdown_json::text,'')),'sha256'),'hex') row_revision,
      array_remove(array[
        case when ts.timesheet_id is null then 'TIMESHEET_NOT_FOUND' end,
        case when ts.timesheet_id is not null and (not ts.is_current or ts.revoked_at is not null) then 'TIMESHEET_NOT_CURRENT' end,
        case when tf.id is null then 'CURRENT_FINANCIALS_MISSING' end,
        case when tf.id is not null and tf.is_stale then 'FINANCIALS_STALE' end,
        case when tf.id is not null and tf.processing_status::text<>'READY_FOR_INVOICE' then 'NOT_READY_FOR_INVOICE' end,
        case when tf.id is not null and tf.has_rate_issue then 'RATE_MISSING' end,
        case when tf.id is not null and tf.has_pay_channel_issue then 'PAY_CHANNEL_MISSING' end,
        case when tf.id is not null and tf.client_id is null then 'CLIENT_UNRESOLVED' end,
        case when tf.id is not null and tf.locked_by_invoice_id is not null then 'SOURCE_ALREADY_LOCKED' end,
        case when ts.authorised_at_server is null
          then 'TIMESHEET_NOT_AUTHORISED' end,
        case when upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null)
          then 'QR_TIMESHEET_UNSIGNED' end,
        case when pc.require_reference_to_invoice
          and coalesce(ref.reference_ready,false) is not true
          then coalesce(ref.blocker_code,'MISSING_REFERENCE') end,
        case when coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_MILEAGE_EVIDENCE' end end,
        case when(coalesce(tf.mileage_pay_ex_vat,0)<>0
            or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'MILEAGE_ASSET_NOT_REGISTERED' end,
        case when coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0
          then case when not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null)
            then 'MISSING_EXPENSE_EVIDENCE' end end,
        case when(
            coalesce(tf.expenses_pay_ex_vat,0)<>0
            or coalesce(tf.expenses_charge_ex_vat,0)<>0
            or coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0
            or coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null
              and e.document_asset_id is null)
          then 'EXPENSE_ASSET_NOT_REGISTERED' end,
        case when(coalesce(tf.travel_pay_ex_vat,0)<>0
            or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_TRAVEL_EVIDENCE' end,
        case when(coalesce(tf.accommodation_pay_ex_vat,0)<>0
            or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_ACCOMMODATION_EVIDENCE' end,
        case when(coalesce(tf.other_pay_ex_vat,0)<>0
            or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null)
          then 'MISSING_OTHER_EXPENSE_EVIDENCE' end,
        case when exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'MILEAGE','TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and a.status in(
                'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED'))
          then 'REQUIRED_ASSET_PERMANENT_FAILURE' end,
        case when coalesce(vat.valid,false) is not true
          then coalesce(vat.blocker_code,'VAT_POLICY_UNRESOLVED') end,
        case when corr.valid is false
          then coalesce(corr.blocker_code,'CORRECTION_VALIDATION_FAILED') end,
        case when coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED')
          then 'HEALTHROSTER_VALIDATION_REQUIRED' end,
        case when coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null)
          then 'NHSP_SOURCE_NOT_READY' end,
        case when exists(select 1 from public.invoice_lines l join public.invoices i on i.id=l.invoice_id
                         where l.timesheet_id=m.timesheet_id and i.status in ('DRAFT','ISSUED','ON_HOLD'))
             and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS' then 'SOURCE_ALREADY_INVOICED' end
      ],null)::text[] blockers
    from members m
    left join public.timesheets ts on ts.timesheet_id=m.timesheet_id
    left join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join reference_eval ref on ref.source_member_key=m.source_member_key
    left join vat_eval vat on vat.source_member_key=m.source_member_key
    left join correction_eval corr
      on corr.scope_key=m.chunk_id::text
  ),
  resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from claim_ids q
    join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  canonical_now as materialized (
    select ri.chunk_id,r.group_key,r.source_revision_hash,
      r.blocker_code,r.blocker_detail
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from resolver_inputs ri),null,v_now) r
    join resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  per_chunk as materialized (
    select c.id chunk_id,
      n.source_revision_hash current_revision,
      coalesce(jsonb_agg(jsonb_build_object('source_id',se.timesheet_id,
        'segment_id',se.segment_id,
        'codes',to_jsonb(se.blockers)) order by se.ordinality)
        filter(where cardinality(se.blockers)>0),'[]'::jsonb)
        ||case when n.blocker_code is null then '[]'::jsonb
          else jsonb_build_array(coalesce(n.blocker_detail,
            jsonb_build_object('code',n.blocker_code))) end blockers,
      count(se.timesheet_id)::integer source_count
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join source_eval se on se.chunk_id=c.id
    left join canonical_now n on n.chunk_id=c.id
    group by c.id,n.source_revision_hash,n.blocker_code,n.blocker_detail
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case
          when p.source_count=0 then 'BLOCKED'
          when jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'PLAN' end,
        status=case
          when p.source_count=0 or jsonb_array_length(p.blockers)>0 then 'BLOCKED'
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then 'SUPERSEDED'
          else 'QUEUED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',p.current_revision,'source_count',p.source_count),
        progress_json=jsonb_build_object('status_message',
          case when p.source_count=0 then 'No sources resolved'
               when jsonb_array_length(p.blockers)>0 then 'Source validation blocked'
               when nullif(c.payload_json->>'source_revision','') is not null
                and c.payload_json->>'source_revision'<>p.current_revision then 'Source changed'
               else 'Sources validated' end,'source_count',p.source_count),
        error_json=case
          when p.source_count=0 then jsonb_build_object('code','NO_SOURCES','sources','[]'::jsonb)
          when jsonb_array_length(p.blockers)>0 then jsonb_build_object('code','SOURCE_VALIDATION_BLOCKED','sources',p.blockers)
          when nullif(c.payload_json->>'source_revision','') is not null
           and c.payload_json->>'source_revision'<>p.current_revision then jsonb_build_object('code','SOURCE_CHANGED')
          else null end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from per_chunk p where c.id=p.chunk_id
    returning c.id,c.operation_id,c.status,c.phase,c.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note validation is deliberately separate from normal timesheet sources.
  with claim_ids as (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='VALIDATE_SOURCES'
  ),
  credit_eval as (
    select c.id chunk_id,i.id invoice_id,own.credit_note_id resume_invoice_id,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),'sha256'),'hex') revision,
      case when i.id is null then 'INVOICE_NOT_FOUND'
           when i.type::text<>'INVOICE' then 'CREDIT_SOURCE_NOT_INVOICE'
           when i.status::text not in ('ISSUED','PAID') then 'CREDIT_SOURCE_NOT_ISSUED'
           when own.credit_note_id is null and exists(select 1 from public.invoices cn where cn.original_invoice_id=i.id and cn.type='CREDIT_NOTE'
                       and cn.status in('DRAFT','ISSUED','PAID')) then 'CREDIT_ALREADY_EXISTS'
           else null end blocker
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    left join public.invoices i on i.id=c.entity_id
    left join lateral private._invoice_credit_resume_v1(i.id,c.operation_id,
      case when pg_input_is_valid(c.payload_json#>>'{plan,planned_invoice_id}','uuid')
        then(c.payload_json#>>'{plan,planned_invoice_id}')::uuid end,null) own on true
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
  ),
  updated as (
    update public.invoice_operation_chunks c
    set phase=case when e.blocker is null then 'PLAN' else 'BLOCKED' end,
        status=case when e.blocker is null then 'QUEUED' else 'BLOCKED' end,
        payload_json=c.payload_json||jsonb_build_object('source_revision',e.revision,'source_invoice_id',e.invoice_id,
          'resume_invoice_id',e.resume_invoice_id),
        progress_json=jsonb_build_object('status_message',case when e.blocker is null then 'Credit source validated' else 'Credit source blocked' end),
        error_json=case when e.blocker is null then null else jsonb_build_object('code',e.blocker,'invoice_id',c.entity_id) end,
        lease_owner=null,lease_token=null,lease_expires_at_utc=null,
        updated_at_utc=v_now
    from credit_eval e where c.id=e.chunk_id
    returning c.id,c.status,c.phase,c.error_json
  )
  select v_result||coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'error',error_json)),'[]'::jsonb)
  into v_result from updated;

  -- PLAN: compact financial/settings summary only; no complete line arrays.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='PLAN'
  ),
  members as materialized (
    select c.id chunk_id,c.payload_json,
      case when pg_input_is_valid(s.value,'uuid')
        then s.value::uuid end timesheet_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    cross join lateral jsonb_array_elements_text(coalesce(
      c.payload_json->'canonical_source_ids',c.payload_json->'source_ids','[]'::jsonb)) s(value)
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
      and pg_input_is_valid(s.value,'uuid')
  ),
  values_by_chunk as materialized (
    select m.chunk_id,count(*)::integer source_count,
      round(sum(coalesce(tf.total_pay_ex_vat,0)),2) expected_pay_ex_vat,
      round(sum(coalesce(tf.total_charge_ex_vat,0)),2) expected_charge_ex_vat,
      (array_agg(tf.client_id order by tf.client_id))[1] client_id,
      jsonb_build_object(
        'client_id',(array_agg(tf.client_id order by tf.client_id))[1],'consolidation_mode',max(c.payload_json->>'consolidation_mode'),
        'stream',max(c.payload_json->>'invoice_stream'),
        'invoice_week_start',max(c.payload_json->>'target_invoice_week'),
        'client',jsonb_build_object('name',max(cl.name),'vat_chargeable',bool_and(cl.vat_chargeable),
          'payment_terms_days',max(cl.payment_terms_days),'primary_invoice_email',max(cl.primary_invoice_email)),
        'attach_policy',jsonb_build_object(
          'hr_attach_to_invoice',coalesce(bool_or(
            (a.authority_json#>>'{values,hr_attach_to_invoice}')::boolean),true),
          'ts_attach_to_invoice',coalesce(bool_or(
            (a.authority_json#>>'{values,ts_attach_to_invoice}')::boolean),true),
          'requires_hr',coalesce(bool_or(
            (a.authority_json#>>'{values,requires_hr}')::boolean),false)),
        'settings_authority',jsonb_build_object(
          'version','CONTRACT_SETTINGS_AUTHORITY_V1',
          'fingerprints',jsonb_agg(distinct to_jsonb(
            a.authority_json->>'authority_fingerprint'
          ) order by to_jsonb(a.authority_json->>'authority_fingerprint')))
      ) settings_snapshot
    from members m join public.invoice_operation_chunks c on c.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)
        authority_json
    ) a
    join public.clients cl on cl.id=tf.client_id
    group by m.chunk_id
  ),
  plans as materialized (
    select c.id chunk_id,coalesce(
      case when pg_input_is_valid(
        nullif(c.payload_json->>'planned_invoice_id',''),'uuid')
        then(c.payload_json->>'planned_invoice_id')::uuid end,
      case when c.payload_json->>'consolidation_mode' in ('BY_WEEK','ANY_WEEK') then (
        select i.id from public.invoices i
        where i.client_id=v.client_id and i.status='DRAFT' and i.type='INVOICE'
          and coalesce(i.header_snapshot_json#>>'{meta,consolidation_mode}','NONE')=c.payload_json->>'consolidation_mode'
          and coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false')=
              case when c.payload_json->>'invoice_stream'='SELF_BILL' then 'true' else 'false' end
          and (not private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
            or upper(coalesce(
              nullif(i.header_snapshot_json#>>'{meta,invoice_stream}',''),
              nullif(i.header_snapshot_json->>'invoice_stream',''),
              case when lower(coalesce(i.header_snapshot_json#>>'{meta,self_bill}','false'))
                in('true','t','1','yes') then 'SELF_BILL' else 'NORMAL' end
            ))=upper(coalesce(c.payload_json->>'invoice_stream','NORMAL')))
          and (c.payload_json->>'consolidation_mode'='ANY_WEEK'
               or i.header_snapshot_json#>>'{meta,invoice_week_start}'=c.payload_json->>'target_invoice_week')
        order by i.created_at desc limit 1
      ) end,gen_random_uuid()) planned_invoice_id,
      v.source_count,v.expected_charge_ex_vat,v.expected_pay_ex_vat,v.client_id,
      v.settings_snapshot,encode(digest(v.settings_snapshot::text,'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join values_by_chunk v on v.chunk_id=c.id
  ),
  credit_plans as materialized (
    select c.id chunk_id,coalesce(
      case when pg_input_is_valid(c.payload_json#>>'{plan,planned_invoice_id}','uuid')
        then(c.payload_json#>>'{plan,planned_invoice_id}')::uuid end,
      case when pg_input_is_valid(c.payload_json->>'resume_invoice_id','uuid')
        then(c.payload_json->>'resume_invoice_id')::uuid end,
      gen_random_uuid()) planned_invoice_id,1 source_count,
      -i.subtotal_ex_vat expected_charge_ex_vat,-coalesce(sum(l.total_pay_ex_vat),0) expected_pay_ex_vat,
      i.client_id,jsonb_build_object('source_invoice_id',i.id,'source_invoice_no',i.invoice_no,
        'client_id',i.client_id,'credit_note',true) settings_snapshot,
      encode(digest(concat_ws('|',i.id::text,i.updated_at::text),'sha256'),'hex') settings_hash
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    left join public.invoice_lines l on l.invoice_id=i.id
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
    group by c.id,i.id
  ),
  all_plans as materialized (select * from plans union all select * from credit_plans),
  updated as (
    update public.invoice_operation_chunks c
    set phase='COMMIT',status='QUEUED',
      payload_json=c.payload_json||jsonb_build_object('plan',jsonb_build_object(
        'planned_invoice_id',p.planned_invoice_id,'intended_invoice_count',1,
        'source_count',p.source_count,'expected_pay_ex_vat',p.expected_pay_ex_vat,
        'expected_charge_ex_vat',p.expected_charge_ex_vat,'settings_snapshot',p.settings_snapshot,
        'settings_hash',p.settings_hash,'source_revision',c.payload_json->>'source_revision')),
      progress_json=jsonb_build_object('status_message','Generation plan ready','source_count',p.source_count),
      error_json=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=v_now
    from all_plans p where c.id=p.chunk_id
    returning c.id,c.status,c.phase,c.payload_json->'plan' plan
  )
  select coalesce(jsonb_agg(jsonb_build_object('chunk_id',id,'status',status,'phase',phase,'plan',plan)),'[]'::jsonb)
    into v_part from updated;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- COMMIT: revalidate immediately, then headers, lines, locks, documents and audit set-wise.
  with recursive claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='COMMIT'
  ),
  normal_chunks as materialized (
    select c.*,case when pg_input_is_valid(
        c.payload_json#>>'{plan,planned_invoice_id}','uuid')
      then(c.payload_json#>>'{plan,planned_invoice_id}')::uuid end planned_invoice_id
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE'
  ),
  members as materialized (
    select c.id chunk_id,c.operation_id,c.planned_invoice_id,c.payload_json,
      upper(coalesce(s.value->>'source_type','TIMESHEET')) source_type,
      case when pg_input_is_valid(s.value->>'source_id','uuid')
        then(s.value->>'source_id')::uuid end source_id,
      case when pg_input_is_valid(coalesce(
          s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
        then coalesce(s.value->>'related_timesheet_id',
          s.value->>'source_id')::uuid end timesheet_id,
      nullif(btrim(s.value->>'segment_id'),'') segment_id,
      coalesce(nullif(btrim(s.value->>'source_member_key'),''),
        encode(digest(concat_ws('|',
          upper(coalesce(s.value->>'source_type','TIMESHEET')),
          coalesce(s.value->>'source_id',''),
          coalesce(s.value->>'related_timesheet_id',''),
          coalesce(s.value->>'segment_id','WHOLE'),
          coalesce(s.value->>'target_invoice_week','')),'sha256'),'hex'))
        source_member_key
    from normal_chunks c
    cross join lateral jsonb_array_elements(case
      when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        and jsonb_array_length(c.payload_json->'canonical_source_members')>0
      then c.payload_json->'canonical_source_members'
      else coalesce((
        select jsonb_agg(jsonb_build_object(
          'source_type','TIMESHEET','source_id',ids.value,
          'related_timesheet_id',ids.value) order by ids.ordinality)
        from jsonb_array_elements_text(coalesce(
          c.payload_json->'canonical_source_ids',
          c.payload_json->'source_ids','[]'::jsonb))
          with ordinality ids(value,ordinality)
      ),'[]'::jsonb) end) s(value)
    where pg_input_is_valid(coalesce(
      s.value->>'related_timesheet_id',s.value->>'source_id'),'uuid')
  ),
  selected_segments as materialized (
    select c.id chunk_id,
      (m.value->>'source_id')::uuid timesheet_id,
      array_agg(distinct m.value->>'segment_id'
        order by m.value->>'segment_id')
        filter(where nullif(m.value->>'segment_id','') is not null) segment_ids
    from normal_chunks c
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(c.payload_json->'canonical_source_members')='array'
        then c.payload_json->'canonical_source_members' else '[]'::jsonb end)
      m(value)
    where coalesce(m.value->>'source_id','')~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    group by c.id,(m.value->>'source_id')::uuid
  ),
  commit_reference_eval as materialized (
    select distinct on(r.source_member_key) r.*
    from private._invoice_source_reference_validate_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'related_timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'target_invoice_week',m.payload_json->>'target_invoice_week',
        'invoice_stream',m.payload_json->>'invoice_stream',
        'consolidation_mode',m.payload_json->>'consolidation_mode')
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) r
    order by r.source_member_key
  ),
  commit_vat_eval as materialized (
    select distinct on(v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',m.source_member_key,
        'source_type',m.source_type,
        'source_id',m.source_id,
        'timesheet_id',m.timesheet_id,
        'segment_id',m.segment_id,
        'effective_date',coalesce(
          case when m.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                m.payload_json->>'effective_settings_date','date')
            then m.payload_json->>'effective_settings_date' end,
          (select ts_vat.week_ending_date::text
             from public.timesheets ts_vat
            where ts_vat.timesheet_id=m.timesheet_id
              and ts_vat.is_current
            limit 1)))
        order by m.chunk_id,m.source_member_key)
      from members m),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  commit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-commit:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_COMMIT',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select m.planned_invoice_id,min(m.payload_json::text)::jsonb payload_json,
        jsonb_agg(jsonb_build_object(
          'timesheet_id',m.timesheet_id,
          'source_type',m.source_type,
          'source_id',m.source_id,
          'source_member_key',m.source_member_key,
          'segment_id',m.segment_id,
          'target_invoice_week',m.payload_json->>'target_invoice_week',
          'vat_rate_pct',v.vat_rate)
          order by m.source_member_key) planned_members
      from members m
      left join commit_vat_eval v
        on v.source_member_key=m.source_member_key
      group by m.planned_invoice_id
    ) scope
  ),
  commit_correction_eval as materialized (
    select r.*
    from commit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),  source_still_valid as materialized (
    select m.chunk_id,
      bool_and(tf.processing_status='READY_FOR_INVOICE' and not tf.is_stale
        and (tf.locked_by_invoice_id is null
          or coalesce(tf.invoice_breakdown_json->>'mode','')='SEGMENTS')
        and ts.authorised_at_server is not null
        and not(upper(coalesce(ts.submission_mode::text,''))='QR'
          and(nullif(ts.qr_signed_hash,'') is null
            or ts.qr_signed_at_utc is null))
        and(not coalesce(pc.require_reference_to_invoice,false)
          or coalesce(ref.reference_ready,false))
        and coalesce(vat.valid,false)
        and coalesce(corr.valid,true)
        and not(coalesce(vs.hr_validation_required_for_invoice,false)
          and upper(coalesce(tf.hr_crosscheck_status,'')) not in(
            'OK','PASS','PASSED','MATCHED','NOT_REQUIRED'))
        and not(coalesce(vs.client_is_nhsp,false)
          and coalesce(vs.nhsp_shift_count,0)>0
          and not exists(
            select 1
            from public.nhsp_shifts ns_ready
            where ns_ready.timesheet_id=m.timesheet_id
              and ns_ready.invoice_status='PENDING'
              and ns_ready.invoice_id is null
              and ns_ready.cancelled_at_utc is null))
        and not((coalesce(tf.mileage_pay_ex_vat,0)<>0
              or coalesce(tf.mileage_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='MILEAGE'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.travel_pay_ex_vat,0)<>0
              or coalesce(tf.travel_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='TRAVEL'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.accommodation_pay_ex_vat,0)<>0
              or coalesce(tf.accommodation_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,''))='ACCOMMODATION'
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET')
              and nullif(e.storage_key,'') is not null))
        and not((((coalesce(tf.travel_pay_ex_vat,0)
                +coalesce(tf.accommodation_pay_ex_vat,0)
                +coalesce(tf.other_pay_ex_vat,0)=0)
              and coalesce(tf.expenses_pay_ex_vat,0)<>0)
            or ((coalesce(tf.travel_charge_ex_vat,0)
                +coalesce(tf.accommodation_charge_ex_vat,0)
                +coalesce(tf.other_charge_ex_vat,0)=0)
              and coalesce(tf.expenses_charge_ex_vat,0)<>0))
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null))
        and not((coalesce(tf.other_pay_ex_vat,0)<>0
              or coalesce(tf.other_charge_ex_vat,0)<>0)
          and not exists(
            select 1 from public.timesheet_evidence e
            join public.invoice_document_assets a
              on a.id=e.document_asset_id
             and a.status not in('UNSUPPORTED','CORRUPT','MISSING',
               'FAILED','SUPERSEDED')
            where e.timesheet_id=m.timesheet_id
              and upper(coalesce(e.kind,'')) in(
                'OTHER','EXPENSE','EXPENSES')
              and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
              and upper(coalesce(e.document_role,'')) not in(
                'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
                'SIGNED_TIMESHEET','EXPENSE_MILEAGE_APPROVAL_SUMMARY')
              and nullif(e.storage_key,'') is not null))
        and not exists(
          select 1
          from public.timesheet_evidence e
          left join public.invoice_document_assets a
            on a.id=e.document_asset_id
          where e.timesheet_id=m.timesheet_id
            and upper(coalesce(e.processing_state,''))<>'SUPERSEDED'
            and upper(coalesce(e.document_role,'')) not in(
              'CANDIDATE_SIGNATURE','MANAGER_SIGNATURE','ELECTRONIC_SIGNATURES',
              'SIGNED_TIMESHEET')
            and(
              (upper(coalesce(e.kind,''))='MILEAGE'
                and(coalesce(tf.mileage_pay_ex_vat,0)<>0
                  or coalesce(tf.mileage_charge_ex_vat,0)<>0))
              or(upper(coalesce(e.kind,'')) in(
                  'TRAVEL','ACCOMMODATION','OTHER','EXPENSE','EXPENSES')
                and(coalesce(tf.expenses_pay_ex_vat,0)<>0
                  or coalesce(tf.expenses_charge_ex_vat,0)<>0
                  or coalesce(tf.travel_pay_ex_vat,0)<>0
                  or coalesce(tf.travel_charge_ex_vat,0)<>0
                  or coalesce(tf.accommodation_pay_ex_vat,0)<>0
                  or coalesce(tf.accommodation_charge_ex_vat,0)<>0)))
            and(e.document_asset_id is null
              or a.status in('UNSUPPORTED','CORRUPT','MISSING',
                'FAILED','SUPERSEDED')))
        and not exists(
          select 1
          from public.invoice_lines l
          join public.invoices existing on existing.id=l.invoice_id
          where l.timesheet_id=m.timesheet_id
            and existing.id<>m.planned_invoice_id
            and existing.status in('DRAFT','ISSUED','ON_HOLD')
            and coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS')
      ) still_valid
    from members m join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current and ts.revoked_at is null
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=m.timesheet_id
    left join public.v_timesheets_summary_base vs
      on vs.timesheet_id=m.timesheet_id
    left join commit_reference_eval ref
      on ref.source_member_key=m.source_member_key
    left join commit_vat_eval vat
      on vat.source_member_key=m.source_member_key
    left join commit_correction_eval corr
      on corr.scope_key=m.planned_invoice_id::text
    group by m.chunk_id
  ),
  commit_resolver_inputs as materialized (
    select c.id chunk_id,c.payload_json,
      row_number() over(order by c.id)::integer command_no
    from normal_chunks c
  ),
  commit_resolver_results as materialized (
    select ri.chunk_id,r.source_revision_hash,r.blocker_code
    from private._invoice_generation_resolve_command_groups(
      (select coalesce(jsonb_agg(ri.payload_json order by ri.command_no),
        '[]'::jsonb) from commit_resolver_inputs ri),null,v_now) r
    join commit_resolver_inputs ri on ri.command_no=r.command_no
    where r.group_key=case
      when left(coalesce(ri.payload_json->>'selection_key',''),9)='generate:'
        then substr(ri.payload_json->>'selection_key',10)
      else ri.payload_json->>'group_key' end
  ),
  revision_check as materialized (
    select c.id chunk_id,r.source_revision_hash current_revision,
      s.still_valid and r.blocker_code is null still_valid
    from normal_chunks c
    join source_still_valid s on s.chunk_id=c.id
    join commit_resolver_results r on r.chunk_id=c.id
  ),
  rejected as (
    update public.invoice_operation_chunks c
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code','SOURCE_CHANGED_BEFORE_COMMIT'),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from revision_check r
    where c.id=r.chunk_id and (not r.still_valid or r.current_revision<>c.payload_json->>'source_revision')
    returning c.id
  ),
  valid_chunks as materialized (
    select c.* from normal_chunks c join revision_check r on r.chunk_id=c.id
    where r.still_valid and r.current_revision=c.payload_json->>'source_revision'
      and not exists(select 1 from rejected x where x.id=c.id)
  ),
  header_source as materialized (
    select vc.id chunk_id,vc.planned_invoice_id,(array_agg(tf.client_id order by tf.client_id))[1] client_id,
      max(cl.name) client_name,max(cl.invoice_address) client_invoice_address,
      max(a.authority_json#>>'{values,client_primary_invoice_email}') primary_invoice_email,
      bool_and(coalesce(
        (a.authority_json#>>'{values,client_vat_chargeable}')::boolean,true
      )) vat_chargeable,
      max((a.authority_json#>>'{values,client_payment_terms_days}')::integer)
        payment_terms_days,
      max(sd.agency_name) agency_name,max(sd.agency_logo) agency_logo,
      max(sd.registered_address) registered_address,max(sd.company_reg_number) company_reg_number,
      max(sd.bank_name) bank_name,max(sd.bank_sort_code) bank_sort_code,
      max(sd.bank_account_number) bank_account_number,max(sd.vat_registration_number) vat_registration_number,
      count(*)::integer source_count
    from valid_chunks vc join members m on m.chunk_id=vc.id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)
        authority_json
    ) a
    join public.clients cl on cl.id=tf.client_id cross join public.settings_defaults sd
    where sd.id=1 group by vc.id,vc.planned_invoice_id
  ),
  source_rows_base as materialized (
    select m.chunk_id,m.planned_invoice_id,m.payload_json,
      m.source_member_key,m.source_type,m.source_id,m.segment_id,tf.*,ts.booking_id,
      ts.week_ending_date,ts.reference_number,ts.sheet_scope,ts.submission_mode,ts.day_references_json,
      ts.actual_schedule_json,coalesce(ts.contract_id,cw.contract_id) contract_id,
      coalesce(cd.display_name,'Candidate '||left(coalesce(tf.candidate_id::text,m.timesheet_id::text),8)) candidate_display,
      coalesce((a.authority_json#>>'{values,daily_calc_of_invoices}')::boolean,false)
        daily_calc_of_invoices,
      coalesce(a.authority_json#>'{values,bucket_labels_json}',
        jsonb_build_object('day','Day','night','Night','sat','Sat','sun','Sun','bh','BH'))
        bucket_labels_json,
      ct.role contract_role,ct.display_site contract_display_site,
      ct.ward_hint contract_ward_hint,
      null::numeric ordinary_vat_rate,
      case when ts.sheet_scope::text='WEEKLY'
          and ts.submission_mode::text='MANUAL'
          and jsonb_typeof(ts.actual_schedule_json)='array'
        then coalesce((
          select jsonb_agg(jsonb_build_object(
            'date',e.value->>'date','start',e.value->>'start',
            'end',e.value->>'end','start_utc',e.value->>'start_utc',
            'end_utc',e.value->>'end_utc','ref_num',e.value->>'ref_num')
            order by e.ordinality)
          from jsonb_array_elements(ts.actual_schedule_json)
            with ordinality e(value,ordinality)
          where nullif(btrim(e.value->>'start'),'') is not null
            and nullif(btrim(e.value->>'end'),'') is not null
        ),'[]'::jsonb)
        else '[]'::jsonb end schedule_refs
    from members m join valid_chunks vc on vc.id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    join public.timesheets ts on ts.timesheet_id=m.timesheet_id and ts.is_current
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)
        authority_json
    ) a
    left join lateral (
      select w.contract_id
      from public.contract_weeks w
      where w.timesheet_id=m.timesheet_id
      order by w.updated_at desc nulls last,w.created_at desc nulls last,w.id desc
      limit 1
    ) cw on true
    left join public.contracts ct on ct.id=coalesce(ts.contract_id,cw.contract_id)
    left join public.candidates cd on cd.id=tf.candidate_id
  ),
  vat_policy as materialized (
    select distinct on (v.source_member_key) v.*
    from private._invoice_generation_vat_policy_batch(coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_member_key',s.source_member_key,
        'source_type',s.source_type,'source_id',s.source_id,
        'timesheet_id',s.timesheet_id,'segment_id',s.segment_id,
        'ordinary_rate',s.ordinary_vat_rate,
        'effective_date',coalesce(
          case when s.payload_json->>'effective_settings_date'
              ~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              and pg_input_is_valid(
                s.payload_json->>'effective_settings_date','date')
            then(s.payload_json->>'effective_settings_date')::date end,
          s.week_ending_date::date))
        order by s.chunk_id,s.timesheet_id)
      from source_rows_base s
    ),'[]'::jsonb)) v
    order by v.source_member_key
  ),
  source_rows as materialized (
    select s.*,v.vat_rate
    from source_rows_base s
    join vat_policy v on v.source_member_key=s.source_member_key and v.valid
  ),
  source_timesheet_ancestry(
    planned_invoice_id,
    root_timesheet_id,
    source_timesheet_id,
    ancestry_path,
    ancestry_depth
  ) as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id,s.timesheet_id,
      array[s.timesheet_id]::uuid[],0
    from source_rows s
    union all
    select a.planned_invoice_id,a.root_timesheet_id,t.parent_timesheet_id,
      a.ancestry_path||t.parent_timesheet_id,a.ancestry_depth+1
    from source_timesheet_ancestry a
    join public.timesheets t
      on t.timesheet_id=a.source_timesheet_id
     and t.is_current
    where t.parent_timesheet_id is not null
      and not(t.parent_timesheet_id=any(a.ancestry_path))
      and a.ancestry_depth<32
  ),
  adjustment_segment_refs as materialized (
    select distinct s.planned_invoice_id,s.timesheet_id root_timesheet_id,
      coalesce(
        (s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,
        true
      ) healthroster_attach_allowed,
      nullif(btrim(seg.value->>'ref_num'),'') ref_num,
      case when pg_input_is_valid(
          seg.value->>'start_utc','timestamp with time zone')
        then(seg.value->>'start_utc')::timestamptz end start_utc,
      case when pg_input_is_valid(
          seg.value->>'end_utc','timestamp with time zone')
        then(seg.value->>'end_utc')::timestamptz end end_utc,
      lower(coalesce(seg.value->>'is_reversal','false')) in(
        'true','t','1','yes') is_reversal
    from source_rows s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      seg(value)
    where s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
  ),
  segment_lock_targets_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'invoice_id',s.planned_invoice_id,
      'timesheet_id',s.timesheet_id,
      'segment_ids',to_jsonb(p.segment_ids),
      'expected_financial_revision',encode(digest(jsonb_build_object(
        'financial_id',s.id,
        'timesheet_version',s.timesheet_version,
        'updated_at',s.updated_at,
        'basis',s.basis,
        'invoice_breakdown_json',s.invoice_breakdown_json
      )::text,'sha256'),'hex'))
      order by s.planned_invoice_id,s.timesheet_id),'[]'::jsonb) targets
    from source_rows s
    join selected_segments p
      on p.chunk_id=s.chunk_id and p.timesheet_id=s.timesheet_id
    where cardinality(coalesce(p.segment_ids,array[]::text[]))>0
      and exists(
        select 1
        from public.invoices existing_header
        where existing_header.id=s.planned_invoice_id)
  ),
  segment_lock_authority_pre as materialized (
    select r.*
    from segment_lock_targets_pre t
    cross join lateral private._invoice_segment_lock_batch(t.targets,v_now) r
  ),
  segment_lock_failures_pre as materialized (
    select * from segment_lock_authority_pre where not success
  ),
  segment_entries as materialized (
    select s.*,seg.ordinality,
      coalesce(nullif(seg.value->>'segment_id',''),
        left(encode(digest(seg.value::text,'sha256'),'hex'),24)) segment_id,
      case when left(coalesce(seg.value->>'date',''),10)
        ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        then left(seg.value->>'date',10) end work_date,
      case when coalesce(seg.value->>'hours_day','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_day')::numeric
        else 0 end segment_hours_day,
      case when coalesce(seg.value->>'hours_night','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_night')::numeric
        else 0 end segment_hours_night,
      case when coalesce(seg.value->>'hours_sat','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sat')::numeric
        else 0 end segment_hours_sat,
      case when coalesce(seg.value->>'hours_sun','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_sun')::numeric
        else 0 end segment_hours_sun,
      case when coalesce(seg.value->>'hours_bh','')~
        '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'hours_bh')::numeric
        else 0 end segment_hours_bh,
      case
        when coalesce(seg.value->>'pay_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_amount')::numeric
        when coalesce(seg.value->>'pay_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'pay_ex_vat')::numeric
        else 0 end segment_pay_ex,
      case
        when coalesce(seg.value->>'charge_amount','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_amount')::numeric
        when coalesce(seg.value->>'charge_ex_vat','')~
          '^[+-]?[0-9]+([.][0-9]+)?$' then(seg.value->>'charge_ex_vat')::numeric
        else 0 end segment_charge_ex
    from (
      select distinct on (base.chunk_id,base.timesheet_id) base.*
      from source_rows base
      order by base.chunk_id,base.timesheet_id,base.source_member_key
    ) s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)
      with ordinality seg(value,ordinality)
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))='SEGMENTS'
      and nullif(seg.value->>'invoice_locked_invoice_id','') is null
      and exists(
        select 1 from selected_segments picked
        where picked.chunk_id=s.chunk_id
          and picked.timesheet_id=s.timesheet_id
          and coalesce(nullif(seg.value->>'segment_id',''),
            left(encode(digest(seg.value::text,'sha256'),'hex'),24))
            =any(coalesce(picked.segment_ids,array[]::text[])))
  ),
  segment_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where s.daily_calc_of_invoices and s.work_date is not null
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,s.work_date
  ),
  segment_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,
      sum(s.segment_hours_day) h_day,sum(s.segment_hours_night) h_night,
      sum(s.segment_hours_sat) h_sat,sum(s.segment_hours_sun) h_sun,
      sum(s.segment_hours_bh) h_bh,sum(s.segment_pay_ex) pay_ex,
      sum(s.segment_charge_ex) charge_ex,max(s.vat_rate) vat_rate,
      max(s.charge_day) charge_day,max(s.charge_night) charge_night,
      max(s.charge_sat) charge_sat,max(s.charge_sun) charge_sun,
      max(s.charge_bh) charge_bh,
      max(s.timesheet_version) timesheet_version,
      (array_agg(s.id order by s.id))[1] tsfin_id,
      max(s.contract_role) contract_role,
      max(s.contract_display_site) contract_display_site,
      max(s.contract_ward_hint) contract_ward_hint,
      (array_agg(s.bucket_labels_json order by s.ordinality))[1]
        bucket_labels_json
    from segment_entries s
    where not s.daily_calc_of_invoices
       or not exists(select 1 from segment_entries d
         where d.chunk_id=s.chunk_id and d.timesheet_id=s.timesheet_id
           and d.daily_calc_of_invoices and d.work_date is not null)
    group by s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date
  ),
  nonsegment_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      coalesce(s.hours_day,0) h_day,coalesce(s.hours_night,0) h_night,coalesce(s.hours_sat,0) h_sat,
      coalesce(s.hours_sun,0) h_sun,coalesce(s.hours_bh,0) h_bh,
      round(coalesce(s.total_pay_ex_vat,0)-coalesce(s.additional_pay_ex_vat,0)
        -coalesce(s.expenses_pay_ex_vat,0)-coalesce(s.mileage_pay_ex_vat,0),2) pay_ex,
      round(coalesce(s.total_charge_ex_vat,0)-coalesce(s.additional_charge_ex_vat,0)
        -coalesce(s.expenses_charge_ex_vat,0)-coalesce(s.mileage_charge_ex_vat,0),2) charge_ex,
      s.vat_rate,s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,
      s.charge_bh,s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    where upper(coalesce(s.invoice_breakdown_json->>'mode',''))<>'SEGMENTS'
       or jsonb_array_length(case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
                                  then s.invoice_breakdown_json->'segments' else '[]'::jsonb end)=0
  ),
  additional_daily_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,
      s.candidate_display,s.week_ending_date,upper(a.key) code,
      left(d.key,10) work_date,
      case when pg_input_is_valid(d.value,'numeric')
        then d.value::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'pay_rate','numeric')
          then(a.value->>'pay_rate')::numeric else 0 end),2) pay_ex,
      round((case when pg_input_is_valid(d.value,'numeric')
          then d.value::numeric else 0 end)*
        (case when pg_input_is_valid(a.value->>'charge_rate','numeric')
          then(a.value->>'charge_rate')::numeric else 0 end),2) charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    cross join lateral jsonb_each_text(
      case when jsonb_typeof(a.value->'days')='object'
        then a.value->'days' else '{}'::jsonb end) d
    where s.daily_calc_of_invoices
      and left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      and exists(select 1 from segment_entries se
        where se.chunk_id=s.chunk_id and se.timesheet_id=s.timesheet_id
          and se.work_date is not null)
  ),
  additional_weekly_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      upper(a.key) code,
      case when pg_input_is_valid(a.value->>'unit_count','numeric')
        then(a.value->>'unit_count')::numeric else 0 end units,
      case when pg_input_is_valid(a.value->>'pay_rate','numeric')
        then(a.value->>'pay_rate')::numeric else 0 end pay_rate,
      case when pg_input_is_valid(a.value->>'charge_rate','numeric')
        then(a.value->>'charge_rate')::numeric else 0 end charge_rate,
      case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
        then(a.value->>'pay_ex_vat')::numeric else 0 end pay_ex,
      case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
        then(a.value->>'charge_ex_vat')::numeric else 0 end charge_ex,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) bucket_name,
      coalesce(nullif(a.value->>'unit_name',''),'units') unit_name,
      a.value->'frequency' frequency,s.vat_rate,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s cross join lateral jsonb_each(
      case when jsonb_typeof(s.additional_units_json)='object'
        then s.additional_units_json else '{}'::jsonb end) a
    where jsonb_typeof(a.value)='object'
      and ((case when pg_input_is_valid(a.value->>'pay_ex_vat','numeric')
              then(a.value->>'pay_ex_vat')::numeric else 0 end)<>0
        or (case when pg_input_is_valid(a.value->>'charge_ex_vat','numeric')
              then(a.value->>'charge_ex_vat')::numeric else 0 end)<>0)
      and not(s.daily_calc_of_invoices
        and jsonb_typeof(a.value->'days')='object'
        and exists(select 1 from jsonb_each_text(
          case when jsonb_typeof(a.value->'days')='object'
            then a.value->'days' else '{}'::jsonb end) d
          where left(d.key,10) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
  ),
  expense_lines as materialized (
    select s.chunk_id,s.planned_invoice_id,s.timesheet_id,s.booking_id,s.candidate_display,s.week_ending_date,
      e.code,e.pay_ex,e.charge_ex,s.vat_rate,s.expenses_description,
      s.expenses_evidence_r2_key,s.expenses_evidence_manifest,
      s.mileage_units,s.mileage_pay_rate,s.mileage_charge_rate,
      s.mileage_evidence_r2_key,s.mileage_evidence_manifest,
      s.charge_day,s.charge_night,s.charge_sat,s.charge_sun,s.charge_bh,
      s.timesheet_version,s.id tsfin_id,s.contract_role,
      s.contract_display_site,s.contract_ward_hint,s.bucket_labels_json
    from source_rows s
    cross join lateral (
      values
       ('TRAVEL',coalesce(s.travel_pay_ex_vat,0),coalesce(s.travel_charge_ex_vat,0)),
       ('ACCOMMODATION',coalesce(s.accommodation_pay_ex_vat,0),coalesce(s.accommodation_charge_ex_vat,0)),
       ('OTHER',coalesce(s.other_pay_ex_vat,0),coalesce(s.other_charge_ex_vat,0)),
       ('EXPENSES_FALLBACK',
          case when coalesce(s.travel_pay_ex_vat,0)+coalesce(s.accommodation_pay_ex_vat,0)+coalesce(s.other_pay_ex_vat,0)=0 then coalesce(s.expenses_pay_ex_vat,0) else 0 end,
          case when coalesce(s.travel_charge_ex_vat,0)+coalesce(s.accommodation_charge_ex_vat,0)+coalesce(s.other_charge_ex_vat,0)=0 then coalesce(s.expenses_charge_ex_vat,0) else 0 end),
       ('MILEAGE',coalesce(s.mileage_pay_ex_vat,0),coalesce(s.mileage_charge_ex_vat,0))
    ) e(code,pay_ex,charge_ex)
    where e.pay_ex<>0 or e.charge_ex<>0
  ),
  line_union as materialized (
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||work_date description,h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric pay_day,null::numeric pay_night,null::numeric pay_sat,
      null::numeric pay_sun,null::numeric pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_DAILY' line_type,
      'TS:'||timesheet_id||':HOURS:'||work_date source_key,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json) detail
    from segment_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from segment_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - W/E '||week_ending_date, h_day,h_night,h_sat,h_sun,h_bh,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'HOURS_WEEKLY','TS:'||timesheet_id||':HOURS:WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json)
    from nonsegment_lines
    where pay_ex<>0 or charge_ex<>0 or h_day+h_night+h_sat+h_sun+h_bh<>0
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||work_date||' - '||
        units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE_DAILY',
      'TS:'||timesheet_id||':ADD:'||code||':'||work_date,
      jsonb_build_object('date',work_date,'timesheet_version',timesheet_version,
        'tsfin_id',tsfin_id,'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_daily_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      candidate_display||' - '||bucket_name||' - '||units||' '||unit_name,0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,'ADDITIONAL_RATE',
      'TS:'||timesheet_id||':ADD:'||code||':WEEK',
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'bucket',jsonb_build_object('code',code,'bucket_name',bucket_name,
          'unit_name',unit_name,'frequency',frequency),
        'units',jsonb_build_object('unit_count',units,'pay_rate',pay_rate,
          'charge_rate',charge_rate))
    from additional_weekly_lines
    union all
    select chunk_id,planned_invoice_id,timesheet_id,booking_id,
      case when code='MILEAGE' then 'Mileage - '||coalesce(mileage_units,0)||
          ' miles (W/E '||week_ending_date||')'
        else initcap(replace(code,'_',' '))||' (W/E '||week_ending_date||')' end,
      0,0,0,0,0,
      null::numeric,null::numeric,null::numeric,null::numeric,null::numeric,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      pay_ex,charge_ex,vat_rate,
      case when code='MILEAGE' then 'MILEAGE'
        when code='EXPENSES_FALLBACK' then 'EXPENSES_TOTAL'
        else 'EXPENSE_'||code end,
      case when code='MILEAGE' then 'TS:'||timesheet_id||':MILEAGE'
        when code='EXPENSES_FALLBACK' then 'TS:'||timesheet_id||':EXP:TOTAL'
        else 'TS:'||timesheet_id||':EXP:'||code end,
      jsonb_build_object('timesheet_version',timesheet_version,'tsfin_id',tsfin_id,
        'role',contract_role,'hospital',contract_display_site,
        'ward',contract_ward_hint,'bucket_labels',bucket_labels_json,
        'expense',case when code='MILEAGE' then jsonb_build_object(
          'category','MILEAGE','mileage_units',mileage_units,
          'pay_rate',mileage_pay_rate,'charge_rate',mileage_charge_rate,
          'evidence_r2_key',mileage_evidence_r2_key,
          'evidence_manifest',mileage_evidence_manifest)
        else jsonb_build_object('category',code,'note',expenses_description,
          'evidence_r2_key',expenses_evidence_r2_key,
          'evidence_manifest',expenses_evidence_manifest) end)
    from expense_lines
  ),
  correction_scopes_pre as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','generation-prewrite:'||scope.planned_invoice_id::text,
      'scope_key',scope.planned_invoice_id::text,
      'invoice_id',case when exists(select 1 from public.invoices existing
        where existing.id=scope.planned_invoice_id)
        then scope.planned_invoice_id end,
      'validation_purpose','GENERATION_PREWRITE',
      'expected_client_id',scope.payload_json->>'client_id',
      'target_invoice_week',scope.payload_json->>'target_invoice_week',
      'expected_invoice_stream',scope.payload_json->>'invoice_stream',
      'planned_members',scope.planned_members)
      order by scope.planned_invoice_id),'[]'::jsonb) scopes
    from(
      select l.planned_invoice_id,min(vc.payload_json::text)::jsonb payload_json,
        jsonb_agg(distinct jsonb_build_object(
          'timesheet_id',l.timesheet_id,
          'vat_rate_pct',l.vat_rate))
          filter(where l.timesheet_id is not null) planned_members
      from line_union l
      join valid_chunks vc on vc.id=l.chunk_id
      group by l.planned_invoice_id
    ) scope
  ),
  correction_validation_pre as materialized (
    select r.*
    from correction_scopes_pre s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,(v_now at time zone 'Europe/London')::date) r
  ),
  correction_failures_pre as materialized (
    select scope_key,blocker_code,detail_json detail
    from correction_validation_pre
    where not valid
  ),  write_eligible_chunks as materialized (
    select vc.*
    from valid_chunks vc
    where not exists(
      select 1 from correction_failures_pre f
      where f.scope_key=vc.planned_invoice_id::text)
  ),
  line_totals as materialized (
    select l.planned_invoice_id,
      round(sum(round(l.charge_ex,2)),2) subtotal_ex_vat,
      round(sum(round(l.charge_ex*l.vat_rate/100,2)),2) vat_amount,
      round(sum(round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)),2) total_inc_vat
    from line_union l
    join write_eligible_chunks w on w.id=l.chunk_id
    group by l.planned_invoice_id
  ),
  existing_target_headers as materialized (
    select vc.id chunk_id,i.id invoice_id
    from write_eligible_chunks vc
    join header_source h on h.chunk_id=vc.id
    join public.invoices i on i.id=vc.planned_invoice_id
      and i.client_id=h.client_id and i.type='INVOICE' and i.status='DRAFT'
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=vc.planned_invoice_id)
  ),
  inserted_headers as (
    insert into public.invoices(id,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select h.planned_invoice_id,h.client_id,'DRAFT',v_now,
      t.subtotal_ex_vat,t.vat_amount,t.total_inc_vat,
      jsonb_build_object('client_id',h.client_id,'client_name',h.client_name)
      ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
        then jsonb_build_object('invoice_stream',upper(coalesce(vc.payload_json->>'invoice_stream','NORMAL')))
        else '{}'::jsonb end
      ||jsonb_build_object(
        'client_invoice_address',h.client_invoice_address,'client_primary_invoice_email',h.primary_invoice_email,
        'agency_name',h.agency_name,'agency_logo',h.agency_logo,'registered_address',h.registered_address,
        'company_reg_number',h.company_reg_number,'company_registration_number',h.company_reg_number,
        'vat_chargeable',h.vat_chargeable,'payment_terms_days',h.payment_terms_days,
        'issued_at_utc',null,'due_at_utc',null,
        'totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,
          'vat_amount',t.vat_amount,'total_inc_vat',t.total_inc_vat),
        'bank',jsonb_build_object('name',h.bank_name,'sort_code',h.bank_sort_code,'account_number',h.bank_account_number),
        'vat_registration_number',h.vat_registration_number,
        'meta',jsonb_build_object('source','INVOICE_OPERATION_QUEUE',
          'invoice_week_start',vc.payload_json->>'target_invoice_week',
          'consolidation_mode',vc.payload_json->>'consolidation_mode',
          'self_bill',vc.payload_json->>'invoice_stream'='SELF_BILL','timesheet_count',h.source_count)
          ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
            then jsonb_build_object('invoice_stream',upper(coalesce(vc.payload_json->>'invoice_stream','NORMAL')))
            else '{}'::jsonb end,
        'attach_policy',vc.payload_json#>'{plan,settings_snapshot,attach_policy}'),
      1,'STALE',v_now,v_now
    from header_source h join write_eligible_chunks vc on vc.id=h.chunk_id
    join line_totals t on t.planned_invoice_id=h.planned_invoice_id
    where not exists(
      select 1 from segment_lock_failures_pre f
      where f.invoice_id=h.planned_invoice_id)
    on conflict(id) do nothing returning id
  ),
  target_headers as materialized (
    select e.chunk_id,e.invoice_id
    from existing_target_headers e
    where not exists(
      select 1
      from inserted_headers h
      where h.id=e.invoice_id)
  ),
  deferred_new_headers as (
    update public.invoice_operation_chunks c
    set status='QUEUED',
      phase='COMMIT',
      progress_json=coalesce(c.progress_json,'{}'::jsonb)
        ||jsonb_build_object('status_message',
          'Invoice header created; applying authoritative source ownership'),
      error_json=null,
      lease_owner=null,
      lease_token=null,
      lease_expires_at_utc=null,
      updated_at_utc=v_now
    from inserted_headers h
    join write_eligible_chunks vc on vc.planned_invoice_id=h.id
    where c.id=vc.id
    returning c.id
  ),
  inserted_lines as (
    insert into public.invoice_lines(
      invoice_id,timesheet_id,booking_id,description,hours_day,hours_night,hours_sat,hours_sun,hours_bh,
      pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,
      paper_ts_r2_key,meta_json,source_key
    )
    select l.planned_invoice_id,l.timesheet_id,l.booking_id,l.description,
      round(l.h_day,2),round(l.h_night,2),round(l.h_sat,2),round(l.h_sun,2),round(l.h_bh,2),
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      round(l.pay_ex,2),round(l.charge_ex,2),round(l.charge_ex-l.pay_ex,2),l.vat_rate,
      round(l.charge_ex*l.vat_rate/100,2),round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2),
      null,jsonb_build_object('line_type',l.line_type,'timesheet_id',l.timesheet_id,
        'candidate_display',l.description,'week_ending_date',
        (select s.week_ending_date from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'schedule_references',
        (select s.schedule_refs from source_rows s where s.timesheet_id=l.timesheet_id limit 1),
        'totals',jsonb_build_object('line_pay_ex_vat',round(l.pay_ex,2),
          'line_charge_ex_vat',round(l.charge_ex,2),'margin_ex_vat',round(l.charge_ex-l.pay_ex,2),
          'vat_rate_pct',l.vat_rate,'vat_amount',round(l.charge_ex*l.vat_rate/100,2),
          'total_inc_vat',round(l.charge_ex+(l.charge_ex*l.vat_rate/100),2)))||l.detail,l.source_key
    from line_union l join target_headers h on h.invoice_id=l.planned_invoice_id
    on conflict(invoice_id,source_key) do nothing
    returning invoice_id,timesheet_id,total_charge_ex_vat,vat_amount,total_inc_vat
  ),
  all_target_lines as materialized (
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from public.invoice_lines l
    where l.invoice_id in(select invoice_id from target_headers)
    union all
    select l.invoice_id,l.total_charge_ex_vat,l.vat_amount,l.total_inc_vat
    from inserted_lines l
  ),
  all_line_totals as materialized (
    select l.invoice_id,count(*)::integer line_count,
      round(sum(l.total_charge_ex_vat),2) subtotal_ex_vat,
      round(sum(l.vat_amount),2) vat_amount,
      round(sum(l.total_inc_vat),2) total_inc_vat
    from all_target_lines l
    group by l.invoice_id
  ),
  target_header_streams as materialized (
    select h.invoice_id,
      max(upper(coalesce(c.payload_json->>'invoice_stream','NORMAL'))) invoice_stream
    from target_headers h
    join public.invoice_operation_chunks c on c.id=h.chunk_id
    group by h.invoice_id
  ),
  updated_header_totals as (
    update public.invoices i
    set subtotal_ex_vat=t.subtotal_ex_vat,vat_amount=t.vat_amount,
      total_inc_vat=t.total_inc_vat,document_state='STALE',
      header_snapshot_json=coalesce(i.header_snapshot_json,'{}'::jsonb)
        ||jsonb_build_object('totals',jsonb_build_object(
          'subtotal_ex_vat',t.subtotal_ex_vat,'vat_amount',t.vat_amount,
          'total_inc_vat',t.total_inc_vat))
        ||case when private._candidate_feature_enabled_current_v1('candidate_expense_invoice_routing_v1')
          then jsonb_build_object(
            'invoice_stream',s.invoice_stream,
            'meta',coalesce(i.header_snapshot_json->'meta','{}'::jsonb)
              ||jsonb_build_object('invoice_stream',s.invoice_stream))
          else '{}'::jsonb end,
      updated_at=v_now
    from all_line_totals t
    join target_header_streams s on s.invoice_id=t.invoice_id
    where i.id=t.invoice_id
    returning i.id
  ),
  segment_lock_targets as materialized (
    select targets from segment_lock_targets_pre
  ),
  segment_lock_authority as materialized (
    select * from segment_lock_authority_pre
  ),
  segment_lock_failures as materialized (
    select * from segment_lock_authority where not success
  ),
  whole_lock as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=vc.planned_invoice_id,locked_at_utc=v_now,updated_at=v_now
    from members m join write_eligible_chunks vc on vc.id=m.chunk_id
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    where tf.timesheet_id=m.timesheet_id and tf.is_current
      and (coalesce(tf.invoice_breakdown_json->>'mode','')<>'SEGMENTS'
        or not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                      where nullif(e->>'invoice_locked_invoice_id','') is null))
    returning tf.timesheet_id
  ),
  week_lock as (
    update public.contract_weeks cw set status='INVOICED',updated_at=v_now
    where cw.timesheet_id in(
      select m.timesheet_id
      from members m
      join target_headers h on h.chunk_id=m.chunk_id)
      and exists(select 1 from public.timesheets_financials tf where tf.timesheet_id=cw.timesheet_id
        and tf.is_current and (tf.locked_by_invoice_id is not null or
          not exists(select 1 from jsonb_array_elements(coalesce(tf.invoice_breakdown_json->'segments','[]'::jsonb)) e
                     where nullif(e->>'invoice_locked_invoice_id','') is null)))
    returning cw.id
  ),
  nhsp_shift_inclusion as (
    update public.nhsp_shifts ns
    set invoice_status='INCLUDED',
      invoice_id=h.invoice_id,
      updated_at=v_now
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    where ns.timesheet_id=s.timesheet_id
      and ns.invoice_status='PENDING'
      and ns.invoice_id is null
      and ns.cancelled_at_utc is null
      and exists(
        select 1
        from jsonb_array_elements(
          case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
            then s.invoice_breakdown_json->'segments'
            else '[]'::jsonb end) segment(value)
        where coalesce(
            nullif(segment.value->>'nhsp_shift_id',''),
            nullif(segment.value->>'shift_id',''))=ns.id::text)
    returning ns.id
  ),
  hr_member_sources as materialized (
    select distinct h.invoice_id,m.timesheet_id,
      case when tf.basis::text in('NHSP','NHSP_ADJUSTMENT')
        then 'NHSP' else 'HEALTHROSTER' end source_system,
      tf.nhsp_import_id import_id,
      case when jsonb_typeof(tf.external_source_rows_json)='array'
        then tf.external_source_rows_json else '[]'::jsonb end member_rows
    from members m
    join target_headers h on h.chunk_id=m.chunk_id
    join public.timesheets_financials tf on tf.timesheet_id=m.timesheet_id and tf.is_current
    where tf.nhsp_import_id is not null
  ),
  hr_sources as (
    insert into public.invoice_hr_source_rows(
      invoice_id,source_system,import_id,header_columns,rows_json,header_rows,member_rows_json)
    select m.invoice_id,m.source_system,m.import_id,'[]'::jsonb,
      coalesce((select jsonb_agg(rows.value order by rows.value::text)
        from (select distinct r.value from hr_member_sources same_source
          cross join lateral jsonb_array_elements(same_source.member_rows) r(value)
          where same_source.invoice_id=m.invoice_id and same_source.source_system=m.source_system
            and same_source.import_id=m.import_id) rows),'[]'::jsonb),
      '[]'::jsonb,jsonb_object_agg(m.timesheet_id::text,m.member_rows order by m.timesheet_id)
    from hr_member_sources m group by m.invoice_id,m.source_system,m.import_id
    on conflict(invoice_id,source_system,import_id) do update
      set member_rows_json=invoice_hr_source_rows.member_rows_json||excluded.member_rows_json,
        rows_json=coalesce((select jsonb_agg(rows.value order by rows.value::text)
          from(select distinct r.value from jsonb_array_elements(
            invoice_hr_source_rows.rows_json||excluded.rows_json) r(value)) rows),'[]'::jsonb)
    returning invoice_id
  ),
  source_segments as materialized (
    select distinct h.invoice_id planned_invoice_id,
      coalesce(
        case when coalesce(x.value->>'nhsp_shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'nhsp_shift_id')::uuid end,
        case when coalesce(x.value->>'shift_id','')~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then(x.value->>'shift_id')::uuid end,
        case when substr(coalesce(x.value->>'segment_id',''),6)~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then substr(x.value->>'segment_id',6)::uuid end) shift_id,
      case
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
         and (
           lower(coalesce(x.value->>'is_reversal','false')) in(
             'true','t','1','yes')
           or coalesce(s.total_hours,0)<0
         ) then 'REVERSAL'
        when s.basis::text in('NHSP_ADJUSTMENT','HEALTHROSTER_ADJUSTMENT')
          then 'CORRECTED_HOURS'
        else 'SOURCE'
      end evidence_role_key
    from source_rows s
    join target_headers h
      on h.chunk_id=s.chunk_id and h.invoice_id=s.planned_invoice_id
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.invoice_breakdown_json->'segments')='array'
        then s.invoice_breakdown_json->'segments' else '[]'::jsonb end) x(value)
    where coalesce(
        nullif(x.value->>'nhsp_shift_id',''),
        nullif(x.value->>'shift_id',''),
        case when left(x.value->>'segment_id',5)='nhsp:'
          then substr(x.value->>'segment_id',6) end)~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      and (
        upper(coalesce(x.value->>'source_system',''))='NHSP'
        or (upper(coalesce(x.value->>'source_system',''))='HEALTHROSTER'
          and coalesce((s.payload_json#>>'{plan,settings_snapshot,attach_policy,hr_attach_to_invoice}')::boolean,true)))
    union
    select distinct r.planned_invoice_id,n.id shift_id,
      case when r.is_reversal then 'REVERSAL'
        else 'CORRECTED_HOURS' end evidence_role_key
    from adjustment_segment_refs r
    join source_timesheet_ancestry a
      on a.planned_invoice_id=r.planned_invoice_id
     and a.root_timesheet_id=r.root_timesheet_id
     and a.ancestry_depth>0
    join public.nhsp_shifts n
      on n.timesheet_id=a.source_timesheet_id
     and n.latest_import_id is not null
     and n.external_row_key is not null
     and (
       upper(coalesce(n.source_system::text,''))='NHSP'
       or (
         upper(coalesce(n.source_system::text,''))='HEALTHROSTER'
         and r.healthroster_attach_allowed
       )
     )
     and (
       (r.ref_num is not null
         and btrim(coalesce(n.ref_num,''))=r.ref_num)
       or (
         r.ref_num is null
         and r.start_utc is not null
         and r.end_utc is not null
         and n.start_utc=r.start_utc
         and n.end_utc=r.end_utc
       )
     )
  ),
  source_import_rows as materialized (
    select distinct s.planned_invoice_id,
      upper(coalesce(n.source_system::text,'UNKNOWN')) source_system,
      n.latest_import_id import_id,n.external_row_key,s.evidence_role_key
    from source_segments s
    join public.nhsp_shifts n on n.id=s.shift_id
    where n.latest_import_id is not null
      and n.external_row_key is not null
  ),
  source_imports as materialized (
    select s.planned_invoice_id,s.source_system,s.import_id,
      jsonb_agg(jsonb_build_object(
        'external_row_key',s.external_row_key,
        'evidence_role_key',s.evidence_role_key)
        order by s.external_row_key,s.evidence_role_key) row_occurrences
    from source_import_rows s
    group by s.planned_invoice_id,s.source_system,s.import_id
  ),
  authoritative_hr_sources as (
    insert into public.invoice_hr_source_rows(
      invoice_id,source_system,import_id,header_columns,rows_json)
    select g.planned_invoice_id,g.source_system,g.import_id,
      case when jsonb_typeof(i.parse_summary_json->'header_columns')='array'
        then i.parse_summary_json->'header_columns' else '[]'::jsonb end,
      coalesce((select jsonb_agg(
          r.payload_json
            ||jsonb_build_object(
              'evidence_role',case occurrence.value->>'evidence_role_key'
                when 'REVERSAL' then case when g.source_system='NHSP'
                  then 'NHSP Reversal' else 'HealthRoster Reversal' end
                when 'CORRECTED_HOURS' then case when g.source_system='NHSP'
                  then 'NHSP Corrected Hours' else 'HealthRoster Corrected Hours' end
                else case when g.source_system='NHSP'
                  then 'NHSP Shift' else 'HealthRoster Shift' end
              end)
            ||case when occurrence.value->>'evidence_role_key'='REVERSAL'
              then jsonb_build_object('reversal_state','REVERSED')
              else '{}'::jsonb end
          order by r.id,occurrence.value->>'evidence_role_key')
        from jsonb_array_elements(g.row_occurrences) occurrence(value)
        join public.hr_rows r
          on r.import_id=g.import_id
         and r.external_row_key=occurrence.value->>'external_row_key'),
        '[]'::jsonb)
    from source_imports g join public.hr_imports i on i.id=g.import_id
    on conflict(invoice_id,source_system,import_id) do update
      set header_columns=excluded.header_columns,rows_json=excluded.rows_json
    returning invoice_id
  ),
  audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,actor_role_at_time,
      object_type,object_id_text,action,after_json,reason)
    select v_now,o.actor_user_id,u.display_name,u.role,'invoices',vc.planned_invoice_id::text,
      case when exists(select 1 from inserted_headers h
        where h.id=vc.planned_invoice_id)
        then 'INVOICE_CREATED' else 'INVOICE_DRAFT_APPENDED' end,
      jsonb_build_object('invoice_id',vc.planned_invoice_id,
        'source_ids',coalesce(vc.payload_json->'canonical_source_ids',
          vc.payload_json->'source_ids','[]'::jsonb),
        'source_revision',vc.payload_json->>'source_revision',
        'operation_id',vc.operation_id),'INVOICE_OPERATION_QUEUE'
    from write_eligible_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    join public.invoice_operations o on o.id=vc.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    where c.resume_invoice_id is null
    returning id
  ),
  correction_failures as materialized (
    select scope_key::uuid invoice_id,blocker_code,detail
    from correction_failures_pre
    where scope_key~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  update public.invoice_operation_chunks c
    set status=case when exists(select 1 from all_line_totals l
                               where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      phase=case when exists(select 1 from all_line_totals l
                            where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then 'COMPLETE' else 'BLOCKED' end,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(vc.planned_invoice_id),
        'source_revision',vc.payload_json->>'source_revision'),
      error_json=case
        when not exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','NO_INVOICE_LINES_CREATED')
        when exists(select 1 from segment_lock_failures sf
          where sf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code','SEGMENT_LOCK_FAILED','detail',(
            select jsonb_agg(to_jsonb(sf))
            from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id))
        when exists(select 1 from correction_failures cf
          where cf.invoice_id=vc.planned_invoice_id)
          then jsonb_build_object('code',(
            select cf.blocker_code from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id))
        else null end,
      completed_at_utc=case
        when exists(select 1 from all_line_totals l
          where l.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from correction_failures cf
            where cf.invoice_id=vc.planned_invoice_id)
          and not exists(select 1 from segment_lock_failures sf
            where sf.invoice_id=vc.planned_invoice_id)
        then v_now else null end,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=v_now
    from valid_chunks vc
    join target_headers h
      on h.chunk_id=vc.id and h.invoice_id=vc.planned_invoice_id
    cross join (select count(*) applied_count from segment_lock_authority) segment_application
    cross join (select count(*) cached_count from authoritative_hr_sources) source_cache_application
    where c.id=vc.id
  ;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='COMMIT'
    and coalesce(c.payload_json->>'command_type','')<>'GENERATE_CREDIT_NOTE';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Credit-note COMMIT: exact negative line clone and source unlock; document creation stays asynchronous.
  -- All credit writers and Unissue serialize on the original invoice before coverage/TSFIN locks.
  perform i.id from public.invoices i
  where i.id in (select c.entity_id
    from jsonb_array_elements(p_claims) x
    join public.invoice_operation_chunks c on c.id=(x->>'chunk_id')::uuid
    where x->>'phase'='COMMIT' and c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE')
  order by i.id for update;

  execute $q$
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements($1) x where x->>'phase'='COMMIT'
  ),
  credit_revisions as materialized (
    select c.*,i.id source_invoice_id,(c.payload_json#>>'{plan,planned_invoice_id}')::uuid credit_note_id,
      own.credit_note_id resume_invoice_id,
      case when own.credit_note_id is null and exists(
        select 1 from public.invoices existing where existing.original_invoice_id=i.id
          and existing.type='CREDIT_NOTE' and existing.status in('DRAFT','ISSUED','PAID'))
        then 'CREDIT_ALREADY_EXISTS' end coverage_blocker
      ,encode(digest(concat_ws('|',i.id::text,i.updated_at::text,i.status::text,
        i.subtotal_ex_vat::text,i.vat_amount::text,i.total_inc_vat::text),
        'sha256'),'hex') current_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i on i.id=c.entity_id
    left join lateral private._invoice_credit_resume_v1(i.id,c.operation_id,
      (c.payload_json#>>'{plan,planned_invoice_id}')::uuid,null) own on true
    where c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
      and i.type='INVOICE' and i.status in ('ISSUED','PAID')
  ),
  credit_correction_scopes as materialized (
    select coalesce(jsonb_agg(jsonb_build_object(
      'request_key','credit-source:'||c.source_invoice_id::text,
      'scope_key',c.source_invoice_id::text,
      'invoice_id',c.source_invoice_id,
      'validation_purpose','CREDIT_SOURCE')
      order by c.source_invoice_id),'[]'::jsonb) scopes
    from(select distinct source_invoice_id from credit_revisions) c
  ),
  credit_correction_failures as materialized (
    select r.invoice_id source_invoice_id,r.blocker_code,r.detail_json
    from credit_correction_scopes s
    cross join lateral private._invoice_correction_validate_batch(
      s.scopes,($2 at time zone 'Europe/London')::date) r
    where not r.valid
  ),
  credit_rejected as (
    update public.invoice_operation_chunks q
    set status='SUPERSEDED',phase='SUPERSEDED',
      error_json=jsonb_build_object('code',case
        when c.coverage_blocker is not null then c.coverage_blocker
        when c.resume_invoice_id is null and c.current_revision<>c.payload_json->>'source_revision'
          then 'CREDIT_SOURCE_CHANGED_BEFORE_COMMIT'
        else coalesce((select f.blocker_code
          from credit_correction_failures f
          where f.source_invoice_id=c.source_invoice_id
          order by f.blocker_code limit 1),'CREDIT_CORRECTION_VALIDATION_FAILED')
        end),
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      updated_at_utc=$2
    from credit_revisions c
    where q.id=c.id and(
      c.coverage_blocker is not null
      or (c.resume_invoice_id is null and c.current_revision<>c.payload_json->>'source_revision')
      or (c.resume_invoice_id is null and exists(select 1 from credit_correction_failures f
        where f.source_invoice_id=c.source_invoice_id)))
    returning q.id
  ),
  credits as materialized (
    select c.* from credit_revisions c
    where (c.resume_invoice_id is not null or c.current_revision=c.payload_json->>'source_revision')
      and c.coverage_blocker is null and not exists(select 1 from credit_rejected r where r.id=c.id)
  ),
  inserted_credit as (
    insert into public.invoices(id,type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
      original_invoice_id,notes,header_snapshot_json,document_revision,document_state,created_at,updated_at)
    select c.credit_note_id,'CREDIT_NOTE',i.client_id,'DRAFT',$2,
      -i.subtotal_ex_vat,-i.vat_amount,-i.total_inc_vat,i.id,
      c.payload_json->>'credit_reason',
      i.header_snapshot_json||jsonb_build_object(
        'credit_source_invoice_id',i.id,'credit_operation_id',c.operation_id,
        'credit_reason',c.payload_json->>'credit_reason'),1,'STALE',$2,$2
    from credits c join public.invoices i on i.id=c.source_invoice_id
    where c.resume_invoice_id is null
    on conflict(id) do nothing returning id
  ),
  cloned_lines as (
    insert into public.invoice_lines(invoice_id,timesheet_id,booking_id,description,
      hours_day,hours_night,hours_sat,hours_sun,hours_bh,pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,total_pay_ex_vat,total_charge_ex_vat,
      margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,paper_ts_r2_key,meta_json,source_key)
    select c.credit_note_id,l.timesheet_id,l.booking_id,
      'CREDIT NOTE – '||coalesce(l.description,''),
      l.hours_day,l.hours_night,l.hours_sat,l.hours_sun,l.hours_bh,
      l.pay_day,l.pay_night,l.pay_sat,l.pay_sun,l.pay_bh,
      l.charge_day,l.charge_night,l.charge_sat,l.charge_sun,l.charge_bh,
      -l.total_pay_ex_vat,-l.total_charge_ex_vat,-l.margin_ex_vat,l.vat_rate_pct,
      -l.vat_amount,-l.total_inc_vat,l.paper_ts_r2_key,
      coalesce(l.meta_json,'{}'::jsonb)||jsonb_build_object(
        'credit_note',true,'original_invoice_id',c.source_invoice_id,
        'original_invoice_line_id',l.id,'credit_of_line_id',l.id,'line_type',
        'CREDIT_'||coalesce(l.meta_json->>'line_type','LINE')),
      'CN:'||c.credit_note_id||':LINE:'||l.id
    from credits c join public.invoice_lines l on l.invoice_id=c.source_invoice_id
    where c.resume_invoice_id is null
    on conflict(invoice_id,source_key) do nothing returning invoice_id
  ),
  source_mark as (
    update public.invoices i set credit_note_created_at_utc=$2,updated_at=$2
    where i.id in(select source_invoice_id from credits where resume_invoice_id is null) returning i.id
  ),
  -- One UPDATE per financial row: whole and segment unlocks cannot collide in one CTE statement.
  unlocks as (
    update public.timesheets_financials tf
    set locked_by_invoice_id=case when tf.locked_by_invoice_id=c.source_invoice_id
          then null else tf.locked_by_invoice_id end,
      locked_at_utc=case when tf.locked_by_invoice_id=c.source_invoice_id
          then null else tf.locked_at_utc end,
      invoice_breakdown_json=case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
        then jsonb_set(tf.invoice_breakdown_json,'{segments}',coalesce((
          select jsonb_agg(case when e.value->>'invoice_locked_invoice_id'=c.source_invoice_id::text
            then(e.value-'invoice_locked_invoice_id'-'invoice_locked_at_utc') else e.value end order by e.ordinality)
          from jsonb_array_elements(tf.invoice_breakdown_json->'segments') with ordinality e(value,ordinality)
        ),'[]'::jsonb),true) else tf.invoice_breakdown_json end,
      unlocked_by_credit_note_id=c.credit_note_id,is_stale=true,
      stale_reason='UNLOCKED_BY_CREDIT',updated_at=$2
    from credits c
    where c.resume_invoice_id is null and tf.is_current and (
      tf.locked_by_invoice_id=c.source_invoice_id
      or exists(select 1 from jsonb_array_elements(case
        when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
        then tf.invoice_breakdown_json->'segments' else '[]'::jsonb end) e
        where e->>'invoice_locked_invoice_id'=c.source_invoice_id::text))
    returning tf.timesheet_id
  ),
  segment_unlocks as materialized (select timesheet_id from unlocks),
  recompute_outbox as (
    insert into public.ts_financials_outbox(
      timesheet_id,reason,attempt_count,next_attempt_at,last_error,created_at)
    select distinct u.timesheet_id,'VERSION_ROTATED'::public.ts_fin_reason_enum,
      0,$2,null,$2
    from (
      select timesheet_id from unlocks
      union all select timesheet_id from segment_unlocks
    ) u
    on conflict on constraint uq_tsfin_outbox do nothing
    returning timesheet_id
  ),
  credit_audits as (
    insert into public.audit_events(ts_utc,actor_user_id,actor_display,
      actor_role_at_time,object_type,object_id_text,action,after_json,reason)
    select $2,o.actor_user_id,u.display_name,u.role,'invoices',
      c.credit_note_id::text,'CREDIT_NOTE_CREATED',
      jsonb_build_object('credit_note_id',c.credit_note_id,
        'original_invoice_id',c.source_invoice_id,
        'credit_reason',c.payload_json->>'credit_reason',
        'command_token',c.payload_json->>'command_token',
        'subtotal_ex_vat',-i.subtotal_ex_vat,'vat_amount',-i.vat_amount,
        'total_inc_vat',-i.total_inc_vat,
        'financial_recompute_enqueued',true),
      'INVOICE_OPERATION_QUEUE'
    from credits c join public.invoices i on i.id=c.source_invoice_id
    join public.invoice_operations o on o.id=c.operation_id
    left join public.tms_users u on u.id=o.actor_user_id
    returning id
  ),
  completed as (
    update public.invoice_operation_chunks q
    set status='QUEUED',
      phase='QUEUE_DOCUMENT',
      error_json=null,
      completed_at_utc=null,lease_owner=null,lease_token=null,
      lease_expires_at_utc=null,updated_at_utc=$2,
      result_json=jsonb_build_object('invoice_ids',jsonb_build_array(c.credit_note_id),
        'credit_note_id',c.credit_note_id,'source_invoice_id',c.source_invoice_id)
    from credits c
    cross join (select count(*) outbox_count from recompute_outbox) outbox_application
    cross join (select count(*) audit_count from credit_audits) audit_application
    where q.id=c.id
    returning q.id,q.status,q.phase,q.result_json,q.error_json
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'chunk_id',id,'status',status,'phase',phase,
    'result',result_json,'error',error_json)),'[]'::jsonb)
  from completed
  $q$
  into v_part using p_claims,v_now;
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  -- Document work is queued in a separate SQL statement so source-invalidation
  -- statement triggers cannot supersede the freshly-created document operation.
  with claim_ids as materialized (
    select (x->>'chunk_id')::uuid chunk_id
    from jsonb_array_elements(p_claims) x where x->>'phase'='QUEUE_DOCUMENT'
  ),
  queued_sources as materialized (
    select c.id chunk_id,c.operation_id parent_operation_id,
      (c.payload_json#>>'{plan,planned_invoice_id}')::uuid planned_invoice_id,
      c.payload_json->>'source_revision' source_revision,
      c.payload_json->>'command_type' command_type,
      c.payload_json->>'command_token' command_token,
      c.payload_json->>'credit_reason' credit_reason,
      i.document_revision::text document_revision
    from claim_ids q join public.invoice_operation_chunks c on c.id=q.chunk_id
    join public.invoices i
      on i.id=(c.payload_json#>>'{plan,planned_invoice_id}')::uuid
    where c.payload_json->>'command_type'<>'GENERATE_CREDIT_NOTE' or i.status='DRAFT'
  ),
  existing_doc_versions as materialized (
    select distinct on(q.chunk_id) q.chunk_id,v.id document_version_id,
      v.operation_id,v.status
    from queued_sources q
    join public.invoice_document_versions v
      on v.entity_type='INVOICE'
     and v.entity_id=q.planned_invoice_id
     and v.purpose='DRAFT_PREVIEW'
     and v.source_revision=q.document_revision
     and v.template_version='invoice-professional-v2'
     and v.status in(
       'PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING',
       'VERIFYING','READY')
    where q.command_type<>'GENERATE_CREDIT_NOTE'
    order by q.chunk_id,case when v.status='READY' then 0 else 1 end,
      v.created_at_utc desc,v.id desc
  ),
  doc_ops as materialized (
    insert into public.invoice_operations(parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,input_json,config_json,progress_json,
      total_units,chunk_count,control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'BUILD_DOCUMENT','INVOICE',q.planned_invoice_id,o.actor_user_id,
      encode(digest('DRAFT_PREVIEW|'||q.planned_invoice_id||'|'||q.document_revision||
        '|invoice-professional-v2','sha256'),'hex'),
      'QUEUED','BUILD_MANIFEST',550,q.document_revision,'invoice-professional-v2',
      jsonb_build_object('invoice_id',q.planned_invoice_id,'purpose','DRAFT_PREVIEW'),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,
      nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type<>'GENERATE_CREDIT_NOTE'
      and not exists(
        select 1 from existing_doc_versions e where e.chunk_id=q.chunk_id)
    on conflict(idempotency_key) where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),updated_at_utc=v_now
    returning *
  ),
  selected_doc_ops as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision source_revision,
      d.id operation_id,d.control_version,null::uuid existing_version_id,
      null::text existing_status
    from queued_sources q join doc_ops d on d.entity_id=q.planned_invoice_id
    union all
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      e.operation_id,o.control_version,e.document_version_id,e.status
    from queued_sources q
    join existing_doc_versions e on e.chunk_id=q.chunk_id
    join public.invoice_operations o on o.id=e.operation_id
  ),
  doc_versions as materialized (
    insert into public.invoice_document_versions(entity_type,entity_id,purpose,operation_id,source_revision,
      template_version,status,snapshot_json,snapshot_hash,manifest_json,manifest_hash,created_at_utc)
    select 'INVOICE',d.planned_invoice_id,'DRAFT_PREVIEW',d.operation_id,d.source_revision,
      'invoice-professional-v2','PLANNING','{}',encode(digest('{}','sha256'),'hex'),
      '[]',encode(digest('[]','sha256'),'hex'),v_now
    from selected_doc_ops d
    where d.existing_version_id is null
    on conflict(entity_type,entity_id,purpose,source_revision,template_version)
      where purpose in('DRAFT_PREVIEW','TIMESHEET')
        and status in ('PLANNING','WAITING_FOR_INPUTS','RENDERING','ASSEMBLING','VERIFYING','READY')
    do nothing
    returning id,entity_id,operation_id
  ),
  all_doc_versions as materialized (
    select d.chunk_id,d.planned_invoice_id,d.operation_id,d.control_version,
      d.source_revision,
      coalesce(d.existing_version_id,v.id) document_version_id,
      coalesce(d.existing_status,'PLANNING') document_status
    from selected_doc_ops d
    left join doc_versions v
      on v.entity_id=d.planned_invoice_id and v.operation_id=d.operation_id
    where d.existing_version_id is not null or v.id is not null
  ),
  doc_chunks as (
    insert into public.invoice_operation_chunks(operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_version_id,status,priority,run_after_utc,payload_json,operation_control_version,created_at_utc,updated_at_utc)
    select d.operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
      encode(digest(concat_ws('|','DOCUMENT_PLAN',d.document_version_id::text,
        d.source_revision,'invoice-professional-v2','1'),'sha256'),'hex'),
      0,'INVOICE',d.planned_invoice_id,d.document_version_id,
      'QUEUED',550,v_now,jsonb_build_object('purpose','DRAFT_PREVIEW'),d.control_version,v_now,v_now
    from all_doc_versions d
    where d.document_status<>'READY'
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing returning operation_id
  ),
  invoice_ptrs as (
    update public.invoices i set preview_document_version_id=d.document_version_id,
      active_document_operation_id=case when d.document_status='READY'
        then null else d.operation_id end,
      document_state=case when d.document_status='READY'
        then 'READY' else 'QUEUED' end,updated_at=v_now
    from all_doc_versions d where i.id=d.planned_invoice_id returning i.id
  ),
  credit_issue_ops as materialized (
    insert into public.invoice_operations(
      parent_operation_id,operation_type,entity_type,entity_id,actor_user_id,
      idempotency_key,status,phase,priority,source_revision,template_version,
      input_json,config_json,progress_json,total_units,chunk_count,
      control_version,change_seq,created_at_utc,updated_at_utc)
    select q.parent_operation_id,'ISSUE_INVOICES','INVOICE',q.planned_invoice_id,
      o.actor_user_id,
      encode(digest('CREDIT_ISSUE|'||q.planned_invoice_id||'|'||
        q.parent_operation_id||'|'||coalesce(q.command_token,''),'sha256'),'hex'),
      'QUEUED','VALIDATE',850,q.document_revision,'invoice-professional-v2',
      jsonb_build_object(
        'invoice_ids',jsonb_build_array(q.planned_invoice_id),
        'credit_note',true,'credit_reason',q.credit_reason,
        'command_token',q.command_token,'deliver',false),
      jsonb_build_object('processor_policy',o.config_json->'processor_policy'),
      '{}',1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
    from queued_sources q
    join public.invoice_operations o on o.id=q.parent_operation_id
    where q.command_type='GENERATE_CREDIT_NOTE'
    on conflict(idempotency_key)
      where status in('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
    do update set priority=greatest(invoice_operations.priority,excluded.priority),
      updated_at_utc=v_now
    returning *
  ),
  selected_credit_issue as materialized (
    select q.chunk_id,q.planned_invoice_id,q.document_revision,
      q.command_token,q.credit_reason,o.id operation_id,o.control_version
    from queued_sources q
    join credit_issue_ops o on o.parent_operation_id=q.parent_operation_id
      and o.operation_type='ISSUE_INVOICES'
    where q.command_type='GENERATE_CREDIT_NOTE'
  ),
  credit_issue_chunks as (
    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,status,
      priority,run_after_utc,payload_json,operation_control_version,
      created_at_utc,updated_at_utc)
    select s.operation_id,'ISSUE_INVOICE','VALIDATE',
      encode(digest(concat_ws('|','ISSUE_INVOICE',s.planned_invoice_id::text,
        s.document_revision,s.command_token),'sha256'),'hex'),
      0,'INVOICE',
      s.planned_invoice_id,'QUEUED',850,v_now,
      jsonb_build_object(
        'invoice_id',s.planned_invoice_id,
        'source_revision',s.document_revision,
        'allow_early',true,'deliver',false,
        'command_token',s.command_token,
        'credit_note',true,'credit_reason',s.credit_reason),
      s.control_version,v_now,v_now
    from selected_credit_issue s
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing
    returning operation_id
  ),
  credit_issue_ptrs as (
    update public.invoices i
    set active_issue_operation_id=s.operation_id,issue_state='VALIDATING',
      updated_at=v_now
    from selected_credit_issue s
    where i.id=s.planned_invoice_id
    returning i.id
  ),
  child_results as materialized (
    select d.chunk_id,d.operation_id document_operation_id,
      d.document_version_id,null::uuid issue_operation_id
    from all_doc_versions d
    union all
    select s.chunk_id,null::uuid,null::uuid,s.operation_id
    from selected_credit_issue s
  )
  update public.invoice_operation_chunks c
    set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
      lease_owner=null,lease_token=null,lease_expires_at_utc=null,
      result_json=coalesce(c.result_json,'{}'::jsonb)||jsonb_build_object(
        'document_operation_id',d.document_operation_id,
        'document_version_id',d.document_version_id,
        'issue_operation_id',d.issue_operation_id)
    from child_results d where c.id=d.chunk_id
  ;
  -- A retry after legal issue reuses its terminal child/document receipt.
  -- A parent completion or a queued/DRAFT document never qualifies.
  update public.invoice_operation_chunks c
  set status='COMPLETE',phase='COMPLETE',completed_at_utc=v_now,updated_at_utc=v_now,
    lease_owner=null,lease_token=null,lease_expires_at_utc=null,error_json=null,
    result_json=coalesce(c.result_json,'{}'::jsonb)||jsonb_build_object(
      'credit_note_id',i.id,'document_version_id',d.id,'credit_note_issued',true)
  from public.invoices i join public.invoice_document_versions d on d.id=i.issued_document_version_id
  where c.id in(select (x->>'chunk_id')::uuid from jsonb_array_elements(p_claims) x
      where x->>'phase'='QUEUE_DOCUMENT')
    and c.payload_json->>'command_type'='GENERATE_CREDIT_NOTE'
    and i.id=(c.payload_json#>>'{plan,planned_invoice_id}')::uuid
    and i.header_snapshot_json->>'credit_operation_id'=c.operation_id::text
    and i.type='CREDIT_NOTE' and i.status in('ISSUED','PAID')
    and d.entity_type='INVOICE' and d.entity_id=i.id and d.purpose='FINAL_ISSUE'
    and d.status='READY' and d.verified_at_utc is not null
    and d.r2_key is not null and d.sha256 is not null and d.size_bytes>0 and d.page_count>0;
  select coalesce(jsonb_agg(jsonb_build_object(
      'chunk_id',c.id,'status',c.status,'phase',c.phase,
      'result',c.result_json,'error',c.error_json)),'[]'::jsonb)
    into v_part
  from jsonb_array_elements(p_claims) x
  join public.invoice_operation_chunks c
    on c.id=case when coalesce(x->>'chunk_id','')~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then(x->>'chunk_id')::uuid end
  where x->>'phase'='QUEUE_DOCUMENT';
  v_result:=v_result||coalesce(v_part,'[]'::jsonb);

  return coalesce(v_result,'[]'::jsonb);
end;
$function$;

create or replace function public.invoice_create_credit_note_and_unlock(
  p_invoice_id uuid,
  p_actor_user_id uuid
)
returns table (
  credit_note_id uuid,
  unlocked_snapshots int
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();

  v_inv record;
  v_base_hdr jsonb := '{}'::jsonb;

  v_original_issued_at timestamptz;
  v_anchor_ymd date;

  v_stationery_key text;
  v_margins jsonb;
  v_hide_bank_footer boolean;

  v_bank jsonb;
  v_vat_reg text;

  v_client_name text;
  v_client_addr text;
  v_client_email text;
  v_vat_chargeable boolean;
  v_terms_days int;

  v_applied_vat numeric;
  v_global_vat numeric := 20;
  v_client_vat_override numeric;

  v_due_at timestamptz;

  v_credit_id uuid;

  v_ts_ids uuid[];

  v_cn_ex numeric := 0;
  v_cn_vat numeric := 0;
  v_cn_inc numeric := 0;
begin
  if p_invoice_id is null then
    raise exception 'invoice_id is required';
  end if;

  -- Load original invoice
  select *
  into v_inv
  from public.invoices
  where id = p_invoice_id for update;

  if not found then
    raise exception 'Invoice not found';
  end if;

  -- Final physical legacy writer shares the original-I1 lock with async credits and Unissue.
  if exists(select 1 from public.invoices cn where cn.original_invoice_id=p_invoice_id
    and cn.type='CREDIT_NOTE' and cn.status in('DRAFT','ISSUED','PAID')) then
    raise exception 'CREDIT_ALREADY_EXISTS' using errcode='P0001';
  end if;

  if exists(select 1 from public.invoice_lines line where line.invoice_id=p_invoice_id
    and line.timesheet_id is not null and private.timesheet_correction_origin_v1(line.timesheet_id) is not null)
    or exists(select 1 from private.timesheet_correction_requests request where request.original_invoice_id=p_invoice_id) then
    raise exception 'CREDIT_PROTECTED_ORIGIN_REQUIRES_SCOPED_PIPELINE' using errcode='55000';
  end if;

  if v_inv.type::text = 'CREDIT_NOTE' then
    raise exception 'Cannot credit a CREDIT_NOTE';
  end if;

  if jsonb_typeof(v_inv.header_snapshot_json) = 'object' then
    v_base_hdr := v_inv.header_snapshot_json;
  end if;

  -- Original issued time (prefer invoice.issued_at_utc, else snapshot.issued_at_utc, else now)
  v_original_issued_at := v_inv.issued_at_utc;
  if v_original_issued_at is null and (v_base_hdr ? 'issued_at_utc') then
    begin
      v_original_issued_at := (v_base_hdr->>'issued_at_utc')::timestamptz;
    exception when others then
      v_original_issued_at := null;
    end;
  end if;
  if v_original_issued_at is null then
    v_original_issued_at := v_now;
  end if;

  v_anchor_ymd := (v_original_issued_at at time zone 'Europe/London')::date;

  -- Stationery key
  v_stationery_key := nullif(btrim(coalesce(v_base_hdr->>'stationery_key','')), '');
  if v_stationery_key is null then
    v_stationery_key := 'Assets/Stationery/Letterhead/A4/Letterhead_v1@300dpi.png';
  end if;

  if right(lower(v_stationery_key), 4) = '.pdf' then
    v_stationery_key := left(v_stationery_key, length(v_stationery_key) - 4) || '@300dpi.png';
  end if;

  while left(v_stationery_key, 1) = '/' loop
    v_stationery_key := substr(v_stationery_key, 2);
  end loop;

  -- Margins
  v_margins := v_base_hdr->'stationery_margins_mm';
  if jsonb_typeof(v_margins) = 'array' and jsonb_array_length(v_margins) = 4 then
    v_margins := jsonb_build_object(
      'top',    coalesce((v_margins->>0)::numeric, 32),
      'right',  coalesce((v_margins->>1)::numeric, 12),
      'bottom', coalesce((v_margins->>2)::numeric, 20),
      'left',   coalesce((v_margins->>3)::numeric, 12)
    );
  elsif jsonb_typeof(v_margins) = 'object' then
    v_margins := jsonb_build_object(
      'top',    coalesce((v_margins->>'top')::numeric, 32),
      'right',  coalesce((v_margins->>'right')::numeric, 12),
      'bottom', coalesce((v_margins->>'bottom')::numeric, 20),
      'left',   coalesce((v_margins->>'left')::numeric, 12)
    );
  else
    v_margins := jsonb_build_object('top',32,'right',12,'bottom',20,'left',12);
  end if;

  -- hide_bank_footer default TRUE
  if jsonb_typeof(v_base_hdr->'hide_bank_footer') = 'boolean' then
    v_hide_bank_footer := (v_base_hdr->>'hide_bank_footer')::boolean;
  else
    v_hide_bank_footer := true;
  end if;

  -- Bank + VAT registration
  if jsonb_typeof(v_base_hdr->'bank') = 'object' then
    v_bank := v_base_hdr->'bank';
  else
    v_bank := null;
  end if;

  v_vat_reg := nullif(btrim(coalesce(v_base_hdr->>'vat_registration_number','')), '');

  if v_bank is null or v_vat_reg is null then
    declare
      v_def record;
    begin
      select bank_name, bank_sort_code, bank_account_number, vat_registration_number
      into v_def
      from public.settings_defaults
      where id = 1
      limit 1;

      if v_bank is null then
        v_bank := jsonb_build_object(
          'name', v_def.bank_name,
          'sort_code', v_def.bank_sort_code,
          'account_number', v_def.bank_account_number
        );
      end if;

      if v_vat_reg is null then
        v_vat_reg := v_def.vat_registration_number;
      end if;
    end;
  end if;

  -- Client info
  v_client_name  := nullif(btrim(coalesce(v_base_hdr->>'client_name','')), '');
  v_client_addr  := nullif(btrim(coalesce(v_base_hdr->>'client_invoice_address','')), '');
  v_client_email := nullif(btrim(coalesce(v_base_hdr->>'client_primary_invoice_email','')), '');

  if jsonb_typeof(v_base_hdr->'vat_chargeable') = 'boolean' then
    v_vat_chargeable := (v_base_hdr->>'vat_chargeable')::boolean;
  else
    v_vat_chargeable := null;
  end if;

  if (v_base_hdr ? 'payment_terms_days') then
    begin
      v_terms_days := (v_base_hdr->>'payment_terms_days')::int;
    exception when others then
      v_terms_days := null;
    end;
  else
    v_terms_days := null;
  end if;

  if v_client_name is null or v_client_addr is null or v_vat_chargeable is null or v_terms_days is null then
    declare
      v_cli record;
    begin
      select name, invoice_address, primary_invoice_email, vat_chargeable, payment_terms_days
      into v_cli
      from public.clients
      where id = v_inv.client_id
      limit 1;

      if v_client_name is null then v_client_name := v_cli.name; end if;
      if v_client_addr is null then v_client_addr := v_cli.invoice_address; end if;
      if v_client_email is null then v_client_email := v_cli.primary_invoice_email; end if;

      if v_vat_chargeable is null then
        v_vat_chargeable := coalesce(v_cli.vat_chargeable, true);
      end if;

      if v_terms_days is null then
        v_terms_days := coalesce(v_cli.payment_terms_days, 30);
      end if;
    end;
  end if;

  -- VAT % (prefer original snapshot applied_vat_rate_pct; else compute anchored)
  v_applied_vat := null;
  if (v_base_hdr ? 'applied_vat_rate_pct') then
    begin
      v_applied_vat := (v_base_hdr->>'applied_vat_rate_pct')::numeric;
    exception when others then
      v_applied_vat := null;
    end;
  end if;

  if v_applied_vat is null then
    select coalesce(sf.vat_rate_pct, 20)
    into v_global_vat
    from public.settings_finance_pick(v_anchor_ymd) sf
    limit 1;

    select cs.vat_rate_pct
    into v_client_vat_override
    from public.client_settings cs
    where cs.client_id = v_inv.client_id
      and cs.effective_from <= v_anchor_ymd
    order by cs.effective_from desc
    limit 1;

    v_applied_vat := case
      when v_vat_chargeable = false then 0
      else coalesce(v_client_vat_override, v_global_vat, 20)
    end;
  else
    if v_vat_chargeable = false then
      v_applied_vat := 0;
    end if;
  end if;

  v_due_at := v_now + make_interval(days => coalesce(v_terms_days, 30));

  -- Create the credit note invoice row
  insert into public.invoices (
    client_id,
    type,
    status,
    status_date_utc,
    issued_at_utc,
    due_at_utc,
    subtotal_ex_vat,
    vat_amount,
    total_inc_vat,
    original_invoice_id,
    header_snapshot_json
  )
  values (
    v_inv.client_id,
    'CREDIT_NOTE'::public.invoice_type_enum,
    'ISSUED'::public.invoice_status_enum,
    v_now,
    v_now,
    v_due_at,
    0,
    0,
    0,
    v_inv.id,
    jsonb_build_object(
      'client_id', v_inv.client_id::text,
      'client_name', v_client_name,
      'client_invoice_address', v_client_addr,
      'client_primary_invoice_email', v_client_email,
      'vat_chargeable', coalesce(v_vat_chargeable, true),
      'applied_vat_rate_pct', coalesce(v_applied_vat, 0),
      'payment_terms_days', coalesce(v_terms_days, 30),
      'issued_at_utc', public._inv_iso_utc(v_now),
      'due_at_utc', public._inv_iso_utc(v_due_at),
      'stationery_key', v_stationery_key,
      'stationery_margins_mm', v_margins,
      'hide_bank_footer', v_hide_bank_footer,
      'bank', v_bank,
      'vat_registration_number', v_vat_reg,
      'meta', jsonb_build_object(
        'source', 'CREDIT_NOTE',
        'original_invoice_id', v_inv.id::text,
        'vat_anchor_ymd', v_anchor_ymd::text,
        'original_invoice_issued_at_utc', public._inv_iso_utc(v_original_issued_at)
      )
    )
  )
  returning id into v_credit_id;

  -- ✅ Insert negative mirror lines (one-for-one from original invoice_lines)
  insert into public.invoice_lines(
    invoice_id, timesheet_id, booking_id, description,
    hours_day, hours_night, hours_sat, hours_sun, hours_bh,
    pay_day, pay_night, pay_sat, pay_sun, pay_bh,
    charge_day, charge_night, charge_sat, charge_sun, charge_bh,
    total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
    vat_rate_pct, vat_amount, total_inc_vat,
    paper_ts_r2_key, meta_json, source_key
  )
  select
    v_credit_id,
    l.timesheet_id,
    l.booking_id,
    ('CREDIT NOTE – ' || coalesce(l.description,'')),

    l.hours_day, l.hours_night, l.hours_sat, l.hours_sun, l.hours_bh,

    l.pay_day, l.pay_night, l.pay_sat, l.pay_sun, l.pay_bh,
    l.charge_day, l.charge_night, l.charge_sat, l.charge_sun, l.charge_bh,

    public._inv_round2(-1 * coalesce(l.total_pay_ex_vat,0)),
    public._inv_round2(-1 * coalesce(l.total_charge_ex_vat,0)),
    public._inv_round2(-1 * coalesce(l.margin_ex_vat,0)),

    l.vat_rate_pct,
    public._inv_round2(-1 * coalesce(l.vat_amount,0)),
    public._inv_round2(-1 * coalesce(l.total_inc_vat,0)),

    l.paper_ts_r2_key,

    (coalesce(l.meta_json,'{}'::jsonb) ||
      jsonb_build_object(
        'credit_note', true,
        'original_invoice_id', v_inv.id::text,
        'original_invoice_line_id', l.id::text
      )
    ),

    ('CN:' || v_credit_id::text || ':LINE:' || l.id::text)
  from public.invoice_lines l
  where l.invoice_id = p_invoice_id;

  -- Update credit note totals from its lines
  select
    coalesce(sum(l2.total_charge_ex_vat),0)::numeric,
    coalesce(sum(l2.vat_amount),0)::numeric,
    coalesce(sum(l2.total_inc_vat),0)::numeric
  into v_cn_ex, v_cn_vat, v_cn_inc
  from public.invoice_lines l2
  where l2.invoice_id = v_credit_id;

  update public.invoices
  set
    subtotal_ex_vat = public._inv_round2(v_cn_ex),
    vat_amount      = public._inv_round2(v_cn_vat),
    total_inc_vat   = public._inv_round2(v_cn_inc),
    updated_at      = v_now
  where id = v_credit_id;

  -- Audit credit note creation (includes totals)
  perform public._audit_insert(
    'invoice',
    v_credit_id::text,
    'CREDIT_NOTE_CREATED',
    null,
    jsonb_build_object(
      'credit_note_id', v_credit_id::text,
      'original_invoice_id', v_inv.id::text,
      'subtotal_ex_vat', public._inv_round2(v_cn_ex),
      'vat_amount', public._inv_round2(v_cn_vat),
      'total_inc_vat', public._inv_round2(v_cn_inc)
    ),
    null,
    p_actor_user_id
  );

  -- Unlock snapshots locked by the original invoice
  select array_agg(distinct tf.timesheet_id)
  into v_ts_ids
  from public.timesheets_financials tf
  where tf.is_current = true
    and tf.locked_by_invoice_id = p_invoice_id
    and tf.timesheet_id is not null;

  unlocked_snapshots := coalesce(array_length(v_ts_ids, 1), 0);

  if unlocked_snapshots > 0 then
    update public.timesheets_financials tf
    set locked_by_invoice_id = null,
        locked_at_utc = null,
        unlocked_by_credit_note_id = v_credit_id,
        is_stale = true,
        stale_reason = 'UNLOCKED_BY_CREDIT',
        updated_at = v_now
    where tf.is_current = true
      and tf.locked_by_invoice_id = p_invoice_id;

    -- Enqueue recompute (batch, idempotent)
    insert into public.ts_financials_outbox(timesheet_id, reason, attempt_count, next_attempt_at, last_error, created_at)
    select
      x.timesheet_id,
      'VERSION_ROTATED'::public.ts_fin_reason_enum,
      0,
      v_now,
      null,
      v_now
    from (select unnest(v_ts_ids) as timesheet_id) x
    on conflict on constraint uq_tsfin_outbox do nothing;

    perform public._audit_insert(
      'invoice',
      v_credit_id::text,
      'CREDIT_NOTE_UNLOCKED_SNAPSHOTS',
      null,
      jsonb_build_object(
        'credit_note_id', v_credit_id::text,
        'original_invoice_id', v_inv.id::text,
        'timesheet_ids', to_jsonb(coalesce(v_ts_ids, array[]::uuid[])),
        'unlocked_count', unlocked_snapshots
      ),
      null,
      p_actor_user_id
    );
  end if;

  credit_note_id := v_credit_id;
  return next;
end;
$$;

create or replace function private._invoice_presentation_snapshot_batch(
    p_requests jsonb,
    p_now_utc timestamptz default null
)
returns table (
    request_key text,
    snapshot_schema_version text,
    presentation_model jsonb,
    timesheet_sources jsonb,
    supporting_sources jsonb,
    higher_rate_support jsonb,
    snapshot_json jsonb,
    snapshot_hash text,
    valid boolean,
    error_code text,
    error_detail jsonb
)
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
#variable_conflict use_column
declare
  v_now timestamptz := coalesce(p_now_utc, now());
begin
  if p_requests is null or jsonb_typeof(p_requests) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  if jsonb_array_length(p_requests) < 1
     or jsonb_array_length(p_requests) > 100 then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  return query
  with recursive raw_requests as materialized (
    select x.ordinality::integer request_no,
           x.value raw_request,
           nullif(btrim(coalesce(x.value->>'request_key','')),'') req_key,
           upper(nullif(btrim(coalesce(x.value->>'entity_type','')),'')) entity_type,
           case when coalesce(x.value->>'entity_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             then (x.value->>'entity_id')::uuid end entity_id,
           upper(nullif(btrim(coalesce(x.value->>'purpose','')),'')) purpose,
           coalesce(nullif(btrim(x.value->>'template_version'),''),'invoice-professional-v2') template_version,
           case when pg_input_is_valid(nullif(x.value->>'issue_at_utc',''),'timestamptz') then (x.value->>'issue_at_utc')::timestamptz end issue_at_utc,
           case when pg_input_is_valid(nullif(x.value->>'tax_point_utc',''),'timestamptz') then (x.value->>'tax_point_utc')::timestamptz end tax_point_utc,
           case when pg_input_is_valid(nullif(x.value->>'due_at_utc',''),'timestamptz') then (x.value->>'due_at_utc')::timestamptz end due_at_utc
    from jsonb_array_elements(p_requests) with ordinality x(value,ordinality)
  ),
  key_stats as materialized (
    select req_key,count(*)::integer key_count,min(request_no) first_request_no
    from raw_requests
    where req_key is not null
    group by req_key
  ),
  duplicate_key_results as materialized (
    select r.request_no,
           r.req_key request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           'DUPLICATE_REQUEST_KEY'::text error_code,
           jsonb_build_object('request_no',r.request_no,'request_key',r.req_key,'duplicate_count',ks.key_count,'first_request_no',ks.first_request_no) error_detail
    from raw_requests r
    join key_stats ks on ks.req_key=r.req_key
    where ks.key_count > 1
  ),
  processable as materialized (
    select r.*
    from raw_requests r
    left join key_stats ks on ks.req_key=r.req_key
    where coalesce(ks.key_count,0) <= 1
  ),
  invalid_request_results as materialized (
    select p.request_no,
           coalesce(p.req_key,'__request_'||p.request_no::text) request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           case
             when p.req_key is null then 'REQUEST_KEY_REQUIRED'
             when length(p.req_key) > 256 then 'REQUEST_KEY_TOO_LONG'
             when p.entity_type not in('INVOICE','TIMESHEET') then 'ENTITY_TYPE_UNSUPPORTED'
             when p.entity_id is null then 'ENTITY_ID_INVALID'
             when p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET') then 'PURPOSE_UNSUPPORTED'
             when p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null) then 'FINAL_ISSUE_DATES_REQUIRED'
             else 'PRESENTATION_REQUEST_INVALID' end error_code,
           jsonb_build_object('request_no',p.request_no,'entity_type',p.entity_type,'purpose',p.purpose) error_detail
    from processable p
    where p.req_key is null
       or length(p.req_key) > 256
       or p.entity_type not in('INVOICE','TIMESHEET')
       or p.entity_id is null
       or p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
       or (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  valid_requests as materialized (
    select p.*
    from processable p
    where p.req_key is not null and length(p.req_key) <= 256
      and p.entity_type in('INVOICE','TIMESHEET')
      and p.entity_id is not null
      and p.purpose in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
      and not (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  requested_invoices as materialized (
    select entity_id invoice_id from valid_requests where entity_type='INVOICE'
  ),
  reference_scope as materialized (
    select r.*
    from private._invoice_reference_rows_batch(
      coalesce((select array_agg(distinct invoice_id) from requested_invoices), array[]::uuid[])
    ) r
  ),
  invoice_line_base as materialized (
    select il.*,
           coalesce(nullif(btrim(vs.candidate_name),''),nullif(btrim(t.occupant_key_norm),'')) worker_name,
           coalesce(t.week_ending_date,
             case when pg_input_is_valid(nullif(il.meta_json->>'week_ending_date',''),'date')
               then (il.meta_json->>'week_ending_date')::date end)
             timesheet_week_ending_date,
           row_number() over(partition by il.invoice_id order by il.created_at,il.id)::integer base_display_order,
           case when pg_input_is_valid(nullif(il.meta_json->>'quantity',''),'numeric') then nullif(il.meta_json->>'quantity','')::numeric end meta_quantity,
           case when pg_input_is_valid(nullif(il.meta_json->>'units',''),'numeric') then nullif(il.meta_json->>'units','')::numeric end meta_units,
           case when il.timesheet_id is null
             then coalesce(nullif(btrim(il.meta_json->>'reference'),''),
               nullif(btrim(il.meta_json->>'po_number'),''))
             else refs.reference end canonical_reference,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_source,'NONE') end reference_source,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_scope,'TIMESHEET') end reference_scope,
           coalesce(refs.reference_source_row_keys,'[]'::jsonb)
             reference_source_row_keys,
           coalesce(refs.reference_required,false) reference_required
    from public.invoice_lines il
    left join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=il.timesheet_id
    left join lateral (
      select
        string_agg(x.current_reference,', ' order by x.first_row_key) reference,
        case when count(*)=1 then min(x.reference_source)
          else 'AGGREGATED_CANONICAL' end reference_source,
        case when count(*)=1 then min(x.reference_scope)
          else 'AGGREGATED_TIMESHEET' end reference_scope,
        jsonb_agg(x.row_key order by x.first_row_key) reference_source_row_keys,
        bool_or(x.is_required) reference_required
      from (
        select r.current_reference,min(r.row_key) first_row_key,
          min(r.row_key) row_key,
          min(case
            when r.ref_target='SEGMENT' then 'SEGMENT'
            when r.day_ymd is not null then 'DAY'
            else 'TIMESHEET' end) reference_source,
          min(case
            when r.ref_target='SEGMENT' then 'EXACT_SEGMENT'
            when r.day_ymd is not null then 'EXACT_DAY'
            else 'WHOLE_TIMESHEET' end) reference_scope,
          bool_or(r.is_required) is_required
        from reference_scope r
        where r.invoice_id=il.invoice_id and r.timesheet_id=il.timesheet_id
          and nullif(btrim(r.current_reference),'') is not null
        group by r.current_reference
      ) x
    ) refs on true
    where il.invoice_id in(select invoice_id from requested_invoices)
  ),
  invoice_line_component_raw as materialized (
    select b.invoice_id,b.id,b.created_at,
           (b.base_display_order*100+v.display_suffix)::integer base_display_order,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||v.bucket row_key,
           v.label description,
           b.canonical_reference reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           'hours'::text unit,
           round(coalesce(v.hours,0),4) quantity_raw,
           round(coalesce(v.hours,0)*coalesce(v.rate,0),4) net_raw,
           round(coalesce(b.total_charge_ex_vat,0),2) line_net,
           round(coalesce(b.vat_amount,0),2) line_vat,
           coalesce(b.vat_rate_pct,0) vat_rate,
           b.source_key,b.id source_invoice_line_id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    cross join lateral (values
      ('DAY','Day',1,coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
      ('NIGHT','Night',2,coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
      ('SATURDAY','Saturday',3,coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
      ('SUNDAY','Sunday',4,coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
      ('BANK_HOLIDAY','Bank holiday',5,coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
    ) v(bucket,label,display_suffix,hours,rate)
    where coalesce(v.hours,0)<>0
    union all
    select b.invoice_id,b.id,b.created_at,(b.base_display_order*100+90)::integer,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||lower(coalesce(nullif(b.meta_json->>'line_type',''),'residual')),
           case
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'Mileage'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%TRAVEL%' then 'Travel'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ACCOMMODATION%' then 'Accommodation'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%HIGHER%' then 'Higher rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADDITIONAL%' then 'Additional rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%REVERS%' then 'Reversal'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%CREDIT%' then 'Credit'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADJUST%' then 'Adjustment'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%EXPENSE%' then 'Other expenses'
             else coalesce(nullif(b.description,''),'Invoice line') end,
           b.canonical_reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           case when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'miles' else 'item' end,
           round(coalesce(b.meta_quantity,b.meta_units,1),4),
           round(coalesce(b.total_charge_ex_vat,0) - (
             coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
             + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
             + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
             + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
             + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
           ),4),
           round(coalesce(b.total_charge_ex_vat,0),2),round(coalesce(b.vat_amount,0),2),coalesce(b.vat_rate_pct,0),b.source_key,b.id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    where abs(coalesce(b.total_charge_ex_vat,0) - (
      coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
      + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
      + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
      + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
      + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
    )) > 0.004
       or not exists (
         select 1 from (values
           (coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
           (coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
           (coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
           (coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
           (coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
         ) nonzero(h,a) where coalesce(h,0)<>0 or coalesce(a,0)<>0)
  ),
  invoice_line_component_ranked as materialized (
    select r.*,
      row_number() over(partition by r.id order by r.base_display_order,r.row_key)::integer component_no,
      count(*) over(partition by r.id)::integer component_count,
      case when coalesce(r.line_net,0)<>0 then r.line_vat * r.net_raw / r.line_net
           else r.line_vat / nullif(count(*) over(partition by r.id),0) end raw_vat
    from invoice_line_component_raw r
  ),
  invoice_line_components as materialized (
    select q.invoice_id,q.id,q.created_at,q.base_display_order,q.row_key,q.description,
           q.reference,q.reference_required,q.reference_scope,q.reference_source,
           q.reference_source_row_keys,q.unit,
           q.quantity_raw quantity,
           case when q.quantity_raw<>0 then round(q.net_amount/q.quantity_raw,4) else q.net_amount end unit_price,
           q.net_amount,q.vat_rate,q.vat_amount,round(q.net_amount+q.vat_amount,2) gross_amount,
           q.source_key,q.source_invoice_line_id,q.worker_name,
           q.timesheet_week_ending_date
    from (
      select r.*,
        case when r.component_no=r.component_count
          then round(r.line_net - coalesce(sum(round(r.net_raw,2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(r.net_raw,2) end net_amount,
        case when r.component_no=r.component_count
          then round(r.line_vat - coalesce(sum(round(coalesce(r.raw_vat,0),2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(coalesce(r.raw_vat,0),2) end vat_amount
      from invoice_line_component_ranked r
    ) q
  ),
  invoice_line_rows as materialized (
    select c.invoice_id,
           jsonb_agg(jsonb_build_object(
             'row_key',c.row_key,
             'source_invoice_line_id',c.source_invoice_line_id,
             'source_key',coalesce(c.source_key,c.source_invoice_line_id::text),
             'description',c.description,
             'worker',c.worker_name,
             'week_ending_date',c.timesheet_week_ending_date,
             'reference',c.reference,
             'reference_required',c.reference_required,
             'reference_scope',c.reference_scope,
             'reference_source',c.reference_source,
             'reference_source_row_keys',c.reference_source_row_keys,
             'unit',c.unit,
             'quantity',c.quantity::text,
             'unit_price',c.unit_price::text,
             'net_amount',c.net_amount::text,
             'vat_rate',c.vat_rate::text,
             'vat_amount',c.vat_amount::text,
             'gross_amount',c.gross_amount::text,
             'display_order',c.base_display_order
           ) order by c.created_at,c.id,c.base_display_order) lines,
           round(sum(c.net_amount),2) line_net,
           round(sum(c.vat_amount),2) line_vat,
           round(sum(c.gross_amount),2) line_gross
    from invoice_line_components c
    group by c.invoice_id
  ),
  scoped_credit_line_rows as materialized (
    select cn.id invoice_id,jsonb_agg(model.value||jsonb_build_object(
      'row_key','CN:'||line.id||':'||(model.value->>'row_key'),
      'source_invoice_line_id',line.id,'source_key',line.source_key,
      'description','CREDIT NOTE – '||coalesce(model.value->>'description',''),
      'unit_price',(-(model.value->>'unit_price')::numeric)::text,
      'net_amount',(-(model.value->>'net_amount')::numeric)::text,
      'vat_amount',(-(model.value->>'vat_amount')::numeric)::text,
      'gross_amount',(-(model.value->>'gross_amount')::numeric)::text
    ) order by model.ordinality) lines
    from requested_invoices requested join public.invoices cn on cn.id=requested.invoice_id
    cross join lateral jsonb_array_elements(cn.header_snapshot_json#>'{credit_scope,frozen_line_models}')
      with ordinality model(value,ordinality)
    join public.invoice_lines line on line.invoice_id=cn.id
      and line.meta_json->>'original_invoice_line_id'=model.value->>'source_invoice_line_id'
    where cn.type='CREDIT_NOTE' and cn.header_snapshot_json?'credit_scope'
    group by cn.id
  ),
  timesheet_targets as materialized (
    select distinct il.invoice_id,t.timesheet_id
    from requested_invoices ri
    join public.invoice_lines il on il.invoice_id=ri.invoice_id
      and il.timesheet_id is not null
    join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    union
    select null::uuid,vr.entity_id
    from valid_requests vr
    where vr.entity_type='TIMESHEET'
  ),
  timesheet_base as materialized (
    select target.invoice_id,t.timesheet_id,t.document_revision,
      upper(coalesce(t.sheet_scope::text,'')) sheet_scope,
      upper(coalesce(t.submission_mode::text,'')) submission_mode,
      t.contract_id,t.week_ending_date,
      t.worked_start_iso,t.worked_end_iso,t.break_start_iso,t.break_end_iso,
      coalesce(t.break_minutes,0) break_minutes,t.actual_schedule_json,
      t.day_references_json,t.reference_number,t.additional_units_week,
      t.additional_units_per_day,t.authorised_at_server,t.auth_name,
      t.auth_job_title,t.r2_nurse_key,t.r2_auth_key,t.img_sha256_nurse,
      t.img_sha256_auth,t.qr_status::text qr_status,t.qr_token,
      t.qr_payload_json,t.qr_signed_hash,t.qr_signed_at_utc,
      coalesce(vs.candidate_id,tf.candidate_id,ct.candidate_id) candidate_id,
      coalesce(vs.client_id,tf.client_id,ct.client_id) client_id,
      coalesce(nullif(btrim(cand.first_name),''),
        split_part(coalesce(vs.candidate_name,t.occupant_key_norm,''),' ',1))
        candidate_first_name,
      coalesce(nullif(btrim(cand.last_name),''),
        nullif(btrim(regexp_replace(
          coalesce(vs.candidate_name,t.occupant_key_norm,''),
          '^[^ ]+[ ]*','','g')),'')) candidate_surname,
      coalesce(nullif(btrim(tf.role),''),nullif(btrim(t.job_title_norm),''),
        nullif(btrim(ct.role),'')) job_profile_title,
      coalesce(nullif(btrim(cl.name),''),nullif(btrim(vs.client_name),''),
        nullif(btrim(t.hospital_norm),'')) client_name,
      nullif(lower(btrim(t.hospital_norm)),'') hospital_norm,
      nullif(lower(btrim(t.ward_norm)),'') ward_norm,
      coalesce(
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        nullif(btrim(cl.name),''),
        nullif(btrim(vs.client_name),'')) hospital,
      regexp_replace(
        regexp_replace(
          initcap(lower(nullif(btrim(t.ward_norm),''))),
          '\mNhs\M','NHS','g'),
        '\mIcu\M','ICU','g') ward_display,
      concat_ws(' - ',
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.ward_norm),''))),
            '\mNhs\M','NHS','g'),
          '\mIcu\M','ICU','g')) site_ward,
      coalesce(nullif(btrim(tf.band),''),nullif(btrim(t.band),'')) band,
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb) invoice_breakdown_json,
      coalesce(tf.additional_units_json,
        tf.invoice_breakdown_json#>'{additional,units}',
        '{}'::jsonb) additional_units_json,
      coalesce((authority.settings_json#>>'{values,week_ending_weekday}')::integer,0)
        configured_week_ending_weekday,
      coalesce(pc.require_reference_to_invoice,false)
        or coalesce(pc.reference_number_required_to_issue_invoice,false)
        reference_required,
      sd.agency_name,
      case
        when nullif(coalesce(
          sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
          sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),'') is null
          then '{}'::jsonb
        else jsonb_build_object(
          'r2_key',coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),
          'sha256',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,sha256}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,sha256}')),
          'size_bytes',case when coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}',
            '')~'^[1-9][0-9]{0,18}$' then coalesce(
              sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
              sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}')::bigint end,
          'media_type',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,media_type}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,media_type}')))
      end logo_identity,
      coalesce(sd.timesheet_header_json,'{}'::jsonb) header_wording,
      coalesce(sd.timesheet_footer_json,'{}'::jsonb) footer_wording,
      coalesce(sd.temporary_worker_declaration_json,'{}'::jsonb)
        temporary_worker_declaration,
      coalesce(sd.client_declaration_json,'{}'::jsonb) client_declaration
    from timesheet_targets target
    join public.timesheets t on t.timesheet_id=target.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join public.contracts ct on ct.id=t.contract_id
    left join public.candidates cand on cand.id=coalesce(vs.candidate_id,ct.candidate_id)
    left join public.clients cl on cl.id=coalesce(vs.client_id,ct.client_id)
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
    left join lateral (
      select tf0.*
      from public.timesheets_financials tf0
      where tf0.timesheet_id=t.timesheet_id and tf0.is_current
      order by tf0.computed_at_utc desc nulls last,tf0.created_at desc nulls last,
        tf0.updated_at desc nulls last,tf0.id desc
      limit 1
    ) tf on true
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(t.timesheet_id)
        as settings_json
    ) authority
    cross join public.settings_defaults sd
    where sd.id=1
  ),
  timesheet_number_fnv(
    invoice_id,timesheet_id,source_text,character_no,fnv_hash
  ) as (
    select b.invoice_id,b.timesheet_id,b.timesheet_id::text,1::integer,
      2166136261::bigint
    from timesheet_base b
    union all
    select h.invoice_id,h.timesheet_id,h.source_text,h.character_no+1,
      mod(
        ((h.fnv_hash # ascii(substr(
          h.source_text,h.character_no,1))::bigint)*16777619::bigint),
        4294967296::bigint)
    from timesheet_number_fnv h
    where h.character_no<=length(h.source_text)
  ),
  timesheet_week_context as materialized (
    select b.*,
      coalesce(b.week_ending_date,
        (b.worked_start_iso at time zone 'Europe/London')::date+
          ((b.configured_week_ending_weekday-
            extract(dow from (b.worked_start_iso at time zone
              'Europe/London')::date)::integer+7)%7)) resolved_week_ending_date
    from timesheet_base b
  ),
  timesheet_schedule_source as materialized (
    select b.invoice_id,b.timesheet_id,s.ordinality::integer source_order,s.value row_json
    from timesheet_week_context b
    cross join lateral jsonb_array_elements(
      case
        when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
          then b.invoice_breakdown_json->'segments'
        when jsonb_typeof(b.actual_schedule_json)='array'
          then b.actual_schedule_json
        else '[]'::jsonb
      end) with ordinality s(value,ordinality)
    union all
    select b.invoice_id,b.timesheet_id,1,jsonb_build_object(
      'date',(b.worked_start_iso at time zone 'Europe/London')::date,
      'start_utc',b.worked_start_iso,'end_utc',b.worked_end_iso,
      'break_start',case when b.break_start_iso is not null
        then to_char(b.break_start_iso at time zone 'Europe/London','HH24:MI') end,
      'break_end',case when b.break_end_iso is not null
        then to_char(b.break_end_iso at time zone 'Europe/London','HH24:MI') end,
      'break_minutes',b.break_minutes,'ref_num',b.reference_number)
    from timesheet_week_context b
    where b.sheet_scope='DAILY'
      and not exists(
        select 1 from jsonb_array_elements(
          case
            when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
              and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
              then b.invoice_breakdown_json->'segments'
            when jsonb_typeof(b.actual_schedule_json)='array'
              then b.actual_schedule_json
            else '[]'::jsonb
          end) existing)
  ),
  timesheet_schedule_normalised as materialized (
    select s.*,b.resolved_week_ending_date,b.reference_required,
      coalesce(nullif(btrim(s.row_json->>'segment_id'),''),
        case when nullif(btrim(s.row_json->>'start_utc'),'') is not null
          and nullif(btrim(s.row_json->>'end_utc'),'') is not null
          then 'SE:'||(s.row_json->>'start_utc')||'|'||
            (s.row_json->>'end_utc') end,
        'ts:'||s.timesheet_id::text||':'||(s.source_order-1)::text) segment_id,
      coalesce(nullif(btrim(s.row_json->>'date'),''),
        nullif(btrim(s.row_json->>'day'),''),
        case when pg_input_is_valid(nullif(coalesce(
            s.row_json->>'worked_start',s.row_json->>'start_utc'),''),
            'timestamptz')
          then (coalesce(s.row_json->>'worked_start',
            s.row_json->>'start_utc')::timestamptz at time zone
              'Europe/London')::date::text end,
        case when b.sheet_scope='DAILY'
          then (b.worked_start_iso at time zone 'Europe/London')::date::text end)
        work_date,
      coalesce(nullif(btrim(s.row_json->>'worked_start'),''),
        nullif(btrim(s.row_json->>'start_utc'),''),
        nullif(btrim(s.row_json->>'start'),'')) worked_start,
      coalesce(nullif(btrim(s.row_json->>'worked_end'),''),
        nullif(btrim(s.row_json->>'end_utc'),''),
        nullif(btrim(s.row_json->>'end'),'')) worked_end,
      case
        when nullif(btrim(s.row_json->>'break_start'),'') is not null
          and nullif(btrim(s.row_json->>'break_end'),'') is not null
          then 'EXPLICIT_INTERVAL'
        when coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
          and coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins')::integer>0
          then 'MINUTES_ONLY'
        else 'NONE' end break_display_mode,
      case when coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
        then coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins')::integer else 0 end break_minutes,
      coalesce(nullif(btrim(s.row_json->>'ref_num'),''),
        nullif(btrim(s.row_json->>'reference'),'')) source_reference
    from timesheet_schedule_source s
    join timesheet_week_context b
      on b.invoice_id is not distinct from s.invoice_id
     and b.timesheet_id=s.timesheet_id
  ),
  timesheet_schedule_rows as materialized (
    select s.invoice_id,s.timesheet_id,s.source_order,s.segment_id,s.work_date,
      jsonb_build_object(
        'row_key',s.timesheet_id::text||'|SEGMENT|'||s.segment_id||'|'||
          coalesce(s.work_date,''),
        'display_order',row_number() over(
          partition by s.invoice_id,s.timesheet_id,s.work_date
          order by
            case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              then s.worked_start::timestamptz end nulls last,
            s.worked_start,s.segment_id,s.source_order),
        'segment_id',s.segment_id,
        'date',s.work_date,
        'worked_start_utc',case when pg_input_is_valid(
          nullif(s.worked_start,''),'timestamptz')
          then s.worked_start::timestamptz end,
        'worked_end_utc',case when pg_input_is_valid(
          nullif(s.worked_end,''),'timestamptz')
          then s.worked_end::timestamptz end,
        'display_start_local',case
          when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
            then to_char(s.worked_start::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_start~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_start,5)
          end,
        'display_end_local',case
          when pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then to_char(s.worked_end::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_end~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_end,5)
          end,
        'break_start_local',nullif(btrim(s.row_json->>'break_start'),''),
        'break_end_local',nullif(btrim(s.row_json->>'break_end'),''),
        'break_minutes',s.break_minutes,
        'break_display_mode',s.break_display_mode,
        'bucket_hours',jsonb_build_object(
          'DAY',coalesce(s.row_json->'hours_day','0'::jsonb),
          'NIGHT',coalesce(s.row_json->'hours_night','0'::jsonb),
          'SATURDAY',coalesce(s.row_json->'hours_sat','0'::jsonb),
          'SUNDAY',coalesce(s.row_json->'hours_sun','0'::jsonb),
          'BANK_HOLIDAY',coalesce(s.row_json->'hours_bh','0'::jsonb)),
        'paid_minutes',coalesce(
          case when (select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
            from(values(s.row_json->>'hours_day'),
              (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
              (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v))>0
            then round(60*(select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
              from(values(s.row_json->>'hours_day'),
                (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
                (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v)))::integer
          end,
          case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              and pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then greatest(0,round(extract(epoch from(
              s.worked_end::timestamptz-s.worked_start::timestamptz))/60)
                -s.break_minutes)::integer end,
          case when coalesce(s.row_json->>'hours',
              s.row_json->>'units','')~
                '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
            then round(coalesce(s.row_json->>'hours',
              s.row_json->>'units')::numeric*60)::integer end),
        'band',b.band,
        'booking_reference',coalesce(
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          s.source_reference,
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.day_ymd=s.work_date
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          case when jsonb_typeof(b.day_references_json)='object'
