-- One authority for accepted WAIT receipt qualification. Mechanically extracted
-- from the complete native V3 facts reader; transport helpers are unchanged.
create or replace function private.weekly_source_protected_wait_receipt_v1(
  p_root_timesheet_id uuid,p_family_event_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_scope jsonb; v_latest public.weekly_exceptional_pay_family_events%rowtype;
  v_generation uuid; v_count integer; v_approval_run uuid; v_invalid_wait_audit boolean;
  v_local_count integer; v_c1_count integer; v_next_count integer; v_audit_count integer;
  v_local jsonb; v_c1 jsonb; v_next jsonb; v_receipt jsonb; v_exception jsonb; v_unavailable boolean:=false;
begin
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null or v_scope->>'target_family_id' is null then return null; end if;
  select event.* into v_latest from public.weekly_exceptional_pay_family_events event
  where event.id=p_family_event_id and event.family_id=(v_scope->>'target_family_id')::uuid
    and event.state='WAIT' and not exists(select 1 from public.weekly_exceptional_pay_family_events newer
      where newer.family_id=event.family_id and newer.durable_work_event_id=event.durable_work_event_id
        and newer.event_sequence>event.event_sequence);
  if not found then return null; end if;
      -- Choose the actual approval's UNIQUE financial target-generation link.
      -- The Wait owner also appends generation-less, money-neutral audit rows
      -- for that same approval. They are not second payment publications, but
      -- must be genuine unchanged-vector WAIT evidence, never arbitrary nulls.
      -- A sibling publication may supersede the original financial generation;
      -- today's current_generation is not the immutable approval's pin.
      select count(*) filter (where t.financial_generation_id is not null),
        (array_agg(t.financial_generation_id) filter (where t.financial_generation_id is not null))[1],
        coalesce(bool_or(t.financial_generation_id is null and (
          t.reason is distinct from 'WAIT'
          or t.resulting_lifecycle_state is distinct from 'WAITING_SOURCE'
          or t.actor_user_id is null
          or t.complete_prior_family_vector_fingerprint is distinct from t.complete_next_family_vector_fingerprint
          or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
            t.fixed_target_component_snapshot) is distinct from t.complete_next_family_vector_fingerprint
          or jsonb_typeof(t.current_source_proposal_snapshot) is distinct from 'object'
          or t.event_hash is distinct from private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_TARGET_EVENT_V1',jsonb_build_object(
              'family_id',t.family_id,'event_sequence',t.event_sequence,
              'approval_id',t.approval_id,'generation_id',null,
              'prior_vector_hash',encode(t.complete_prior_family_vector_fingerprint,'hex'),
              'next_vector_hash',encode(t.complete_next_family_vector_fingerprint,'hex'),
              'reason','WAIT','actor_user_id',t.actor_user_id))
        )),false)
        into v_count,v_generation,v_invalid_wait_audit
        from public.weekly_exceptional_pay_target_events t
        where t.family_id=v_latest.family_id and t.approval_id=v_latest.evidence_approval_id;
      if v_latest.evidence_approval_id is null or v_count<>1 or v_generation is null or v_invalid_wait_audit then
        v_unavailable:=true;
      else
        v_local:=private.weekly_source_pay_query_local_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_c1:=private.weekly_source_pay_query_c1_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_next:=private.weekly_source_pay_query_next_receipt_v1(p_root_timesheet_id,
          v_latest.evidence_approval_id,v_generation);
        v_count:=(v_local is not null)::integer+(v_c1 is not null)::integer+(v_next is not null)::integer;
        select a.creation_orchestration_run_id into v_approval_run
          from public.weekly_exceptional_payment_approvals a where a.id=v_latest.evidence_approval_id;
        -- Count partial evidence too. A local RETIRED request is its audit row,
        -- not a second transport lane; unrelated sibling/history stays excluded.
        select count(*) into v_local_count
          from private.weekly_source_local_protected_decision_receipts l
          join public.weekly_exceptional_c1_publication_requests r on r.id=l.publication_request_id
          where l.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*),count(*) filter (where
          (v_local is not null and r.id::text=v_local->>'publication_request_id' and r.state='RETIRED')
          or (v_c1 is not null and r.id::text=v_c1->>'publication_request_id' and r.state='PUBLISHED'))
          into v_c1_count,v_audit_count
          from public.weekly_exceptional_c1_publication_requests r
          where r.generation_id=v_generation or r.orchestration_run_id=v_approval_run;
        select count(*) into v_next_count from private.bpay_next_protected_source_receipt r
          where r.approval_id=v_latest.evidence_approval_id or r.generation_id=v_generation
            or r.orchestration_run_id=v_approval_run;
        if v_count<>1 or v_approval_run is null
           or (v_local is not null and (v_local_count<>1 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_c1 is not null and (v_local_count<>0 or v_c1_count<>1 or v_audit_count<>1 or v_next_count<>0))
           or (v_next is not null and (v_local_count<>0 or v_c1_count<>0 or v_next_count<>1)) then v_unavailable:=true;
        else
          v_receipt:=coalesce(v_local,v_c1,v_next);
          v_exception:=jsonb_build_object('family_id',v_latest.family_id,
            'bound_version',v_scope->>'family_bound_version','event_sequence',v_latest.event_sequence::text,
            'state','WAIT','evidence_approval_id',v_latest.evidence_approval_id,'accepted_receipt',v_receipt);
        end if;
      end if;

  if v_unavailable then return null; end if;
  return v_exception;
end;
$function$;
alter function private.weekly_source_protected_wait_receipt_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_protected_wait_receipt_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Read-only event witness for report membership and projection placement.
-- A target-family flag or saved/pending decision is never accepted authority.
create or replace function private.weekly_source_protected_wait_witness_v1(
  p_work_event_id uuid,p_source_cycle_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_work public.weekly_work_events%rowtype; v_cycle public.weekly_source_cycles%rowtype;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_event public.weekly_exceptional_pay_family_events%rowtype;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_count integer; v_event_id uuid; v_scope jsonb; v_receipt jsonb; v_clocks jsonb;
  v_result jsonb; v_schedule jsonb;
begin
  if p_work_event_id is null or p_source_cycle_id is null then
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_SCOPE_REQUIRED' using errcode='22023'; end if;
  select * into strict v_work from public.weekly_work_events where id=p_work_event_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=p_source_cycle_id;
  if v_work.first_source_group_id is distinct from v_cycle.source_group_id
    or (v_cycle.scope_client_id is not null and v_cycle.scope_client_id is distinct from v_work.client_id) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_SCOPE_INVALID' using errcode='55000'; end if;
  select count(*),min(event.id::text)::uuid into v_count,v_event_id
  from public.weekly_exceptional_pay_family_events event
  join public.weekly_exceptional_pay_target_families family on family.id=event.family_id
    and family.candidate_id=v_work.candidate_id and v_work.work_date between family.week_start_date and family.week_ending_date
  join public.contracts contract on contract.id=family.contract_id and contract.client_id=v_work.client_id
  where event.durable_work_event_id=v_work.id and event.state='WAIT'
    and not exists(select 1 from public.weekly_exceptional_pay_family_events newer
      where newer.family_id=event.family_id and newer.durable_work_event_id=event.durable_work_event_id
        and newer.event_sequence>event.event_sequence);
  if v_count=0 then
    -- An unaccepted RECONCILE stage can append ACCEPTED_SOURCE before native
    -- completion. It must not erase a WAIT still present in the genuinely
    -- published complete vector. This is contradictory authority, not a
    -- cleared position; only an exact accepted native receipt can clear it.
    if exists(select 1
      from public.weekly_exceptional_pay_target_families family
      join public.contracts contract on contract.id=family.contract_id and contract.client_id=v_work.client_id
      join public.weekly_exceptional_pay_generations generation
        on generation.id=family.current_generation_id and generation.family_id=family.id
      where family.candidate_id=v_work.candidate_id
        and v_work.work_date between family.week_start_date and family.week_ending_date
        and generation.lifecycle_state='PUBLISHED'
        and ((generation.complete_next_vector_json->>'schema_version'='WEEKLY_PROTECTED_TARGET_VECTOR_V1'
          and exists(select 1 from jsonb_array_elements(case
            when jsonb_typeof(generation.complete_next_vector_json#>'{target_snapshot,actual_schedule_json}')='array'
            then generation.complete_next_vector_json#>'{target_snapshot,actual_schedule_json}' else '[]'::jsonb end) item
            where item->>'work_event_id'=v_work.id::text and item->>'protected_target_state'='WAIT'))
          or (generation.complete_next_vector_json->>'schema_version'='WEEKLY_PROTECTED_NEXT_TARGET_V1'
          and exists(select 1 from jsonb_array_elements(case
            when jsonb_typeof(generation.complete_next_vector_json->'components')='array'
            then generation.complete_next_vector_json->'components' else '[]'::jsonb end) item
            where item->>'kind'='WORK' and item->>'work_event_id'=v_work.id::text and item->'protected'='true'::jsonb)))
    ) then raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
    return null;
  end if;
  if v_count<>1 then raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  select * into strict v_event from public.weekly_exceptional_pay_family_events where id=v_event_id;
  select * into strict v_family from public.weekly_exceptional_pay_target_families where id=v_event.family_id;
  v_scope:=private.weekly_source_pay_query_scope_v1(v_family.root_timesheet_id);
  if v_scope is null or v_scope->>'target_family_id' is distinct from v_family.id::text
    or v_scope->>'candidate_id' is distinct from v_work.candidate_id::text
    or v_scope->>'client_id' is distinct from v_work.client_id::text
    or v_scope->>'contract_id' is distinct from v_family.contract_id::text
    or v_family.ownership_state is distinct from 'TARGET_MANAGED' then
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  select * into strict v_approval from public.weekly_exceptional_payment_approvals where id=v_event.evidence_approval_id;
  if v_approval.withdrawn_at_utc is not null or v_approval.pay_target_family_id<>v_family.id
    or v_approval.work_event_id<>v_work.id or v_approval.candidate_id<>v_work.candidate_id
    or v_approval.client_id<>v_work.client_id or v_approval.contract_id<>v_family.contract_id
    or v_approval.protected_work_date<>v_work.work_date or v_approval.week_ending<>v_family.week_ending_date
    or not exists(select 1 from public.weekly_source_cycles origin
      where origin.id=v_approval.source_cycle_id and origin.source_group_id=v_cycle.source_group_id) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  v_receipt:=private.weekly_source_protected_wait_receipt_v1(v_family.root_timesheet_id,v_event.id);
  if v_receipt is null or v_receipt#>>'{accepted_receipt,receipt_state}' is null
    or v_receipt#>>'{accepted_receipt,receipt_state}' not in ('COMPLETE','PUBLISHED') then
    -- PENDING_FREEZE is a saved decision; it never qualifies a new S25 position.
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  select * into strict v_generation from public.weekly_exceptional_pay_generations
    where id=v_family.current_generation_id and family_id=v_family.id;
  if v_generation.lifecycle_state is distinct from 'PUBLISHED' or v_generation.published_at_utc is null
    or not isfinite(v_generation.published_at_utc) or v_generation.result_hash is null
    or v_generation.generation_number is distinct from v_family.current_generation_number
    or v_generation.complete_next_vector_hash is distinct from v_family.current_complete_target_vector_hash
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',
      v_generation.complete_next_vector_json) is distinct from v_generation.complete_next_vector_hash then
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  if v_receipt#>>'{accepted_receipt,generation_id}' is null
    or v_family.bound_version is null or v_generation.generation_number is null
    or v_approval.protected_start_at_local is null or v_approval.protected_end_at_local is null
    or not isfinite(v_approval.protected_start_at_local) or not isfinite(v_approval.protected_end_at_local)
    or v_approval.protected_break_minutes is null or v_approval.protected_break_minutes<0
    or v_approval.protected_end_at_local<=v_approval.protected_start_at_local
    or extract(epoch from (v_approval.protected_end_at_local-v_approval.protected_start_at_local))/60
      <=v_approval.protected_break_minutes then
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  -- Current complete-vector membership is exact durable identity, never only
  -- same date/duration. A sibling can supersede the accepted approval generation.
  if v_generation.complete_next_vector_json->>'schema_version'='WEEKLY_PROTECTED_NEXT_TARGET_V1' then
    v_schedule:=v_generation.complete_next_vector_json->'components';
    if jsonb_typeof(v_schedule) is distinct from 'array' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
    select count(*),jsonb_agg(item)->0 into v_count,v_clocks from jsonb_array_elements(v_schedule) item
      where item->>'kind'='WORK' and item->>'work_event_id'=v_work.id::text and item->'protected'='true'::jsonb;
  elsif v_generation.complete_next_vector_json->>'schema_version'='WEEKLY_PROTECTED_TARGET_VECTOR_V1' then
    v_schedule:=v_generation.complete_next_vector_json#>'{target_snapshot,actual_schedule_json}';
    if jsonb_typeof(v_schedule) is distinct from 'array' then
      raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
    select count(*),jsonb_agg(item)->0 into v_count,v_clocks from jsonb_array_elements(v_schedule) item
      where item->>'work_event_id'=v_work.id::text and item->>'protected_target_state'='WAIT';
  else raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  if v_count<>1 or coalesce(v_clocks->>'date',v_clocks->>'work_date') is distinct from v_work.work_date::text
    or v_clocks->>'start' is distinct from to_char(v_approval.protected_start_at_local,'HH24:MI')
    or v_clocks->>'end' is distinct from to_char(v_approval.protected_end_at_local,'HH24:MI')
    or coalesce(v_clocks->>'break_mins',v_clocks->>'break_minutes')::integer is distinct from v_approval.protected_break_minutes
    or (v_event.start_at_local,v_event.end_at_local,v_event.break_minutes)
      is distinct from (v_approval.protected_start_at_local,v_approval.protected_end_at_local,v_approval.protected_break_minutes)
    or v_event.fixed_office_target_hash is distinct from v_approval.signed_schedule_fact_hash
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_SCHEDULE_V1',
      v_event.fixed_office_target_snapshot_json) is distinct from v_approval.signed_schedule_fact_hash then
    raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000'; end if;
  v_result:=jsonb_build_object('schema_version','WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_V1','state','QUALIFIED_WAIT',
    'work_event_id',v_work.id,'source_cycle_id',v_cycle.id,'source_group_id',v_cycle.source_group_id,
    'candidate_id',v_work.candidate_id,'client_id',v_work.client_id,'contract_id',v_family.contract_id,
    'root_timesheet_id',v_family.root_timesheet_id,'family_id',v_family.id,'family_bound_version',v_family.bound_version::text,
    'event_id',v_event.id,'event_sequence',v_event.event_sequence::text,'approval_id',v_approval.id,
    'approval_source_cycle_id',v_approval.source_cycle_id,
    'accepted_generation_id',v_receipt#>'{accepted_receipt,generation_id}',
    'current_generation_id',v_generation.id,'current_generation_number',v_generation.generation_number,
    'protected_work_date',v_approval.protected_work_date,'protected_start_at_local',v_approval.protected_start_at_local,
    'protected_end_at_local',v_approval.protected_end_at_local,'protected_break_minutes',v_approval.protected_break_minutes,
    'protected_net_minutes',(extract(epoch from (v_approval.protected_end_at_local-v_approval.protected_start_at_local))/60)::integer-v_approval.protected_break_minutes,
    'accepted_receipt',v_receipt->'accepted_receipt');
  return v_result||jsonb_build_object('qualification_sha256',encode(
    private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_V1',v_result),'hex'));
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range then
  raise exception 'WEEKLY_SOURCE_PROTECTED_WAIT_WITNESS_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_protected_wait_witness_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_protected_wait_witness_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Canonical transaction-neutral qualified-coverage definitions.
-- Included inside each owning repeatable's atomic transaction, before SQL
-- readers are parsed. One body authority; no financial/release transitions.

-- Factual admission only. No reader locks, monetary hold, zero entitlement,
-- financial write, invoice change or present-day recheck of a retained Draft.
create or replace function private.weekly_source_pay_query_facts_v1(p_root_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_scope jsonb; v_manual jsonb; v_hours jsonb:='[]'::jsonb;
  v_blocked boolean:=false; v_unavailable boolean:=false;
  v_row record; v_latest public.weekly_exceptional_pay_family_events%rowtype;
  v_generation uuid; v_count integer; v_approval_run uuid;
  v_invalid_wait_audit boolean;
  v_local_count integer; v_c1_count integer; v_next_count integer; v_audit_count integer;
  v_local jsonb; v_c1 jsonb; v_next jsonb; v_receipt jsonb; v_exception jsonb;
  v_state jsonb; v_digest bytea;
begin
  if p_root_timesheet_id is null then
    raise exception 'WEEKLY_SOURCE_PAY_QUERY_ROOT_REQUIRED' using errcode='22023'; end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  if v_scope is null then
    return jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_PAY_QUERY_SCOPE_UNAVAILABLE',
      'scope',null,'blocked',null,'query_state_sha256',null); end if;

  -- Work membership is the actual configured root week, across every owning
  -- report cutoff. Never substitute a Sunday or the report's cutoff period.
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'source_group_id',r.source_group_id,
    'source_cycle_id',r.source_cycle_id,'work_event_id',r.work_event_id,
    'candidate_id',r.candidate_id,'client_id',r.client_id,'contract_id',r.contract_id,
    'work_date',to_char(r.work_date,'YYYY-MM-DD'),'state',r.state) order by r.id),'[]'::jsonb),
    coalesce(bool_or(e.id is null or e.candidate_id is distinct from r.candidate_id
      or e.client_id is distinct from r.client_id or e.work_date is distinct from r.work_date
      or c.source_group_id is distinct from r.source_group_id),false)
  into v_manual,v_unavailable
  from private.weekly_source_manual_reviews r
  left join public.weekly_work_events e on e.id=r.work_event_id
  left join public.weekly_source_cycles c on c.id=r.source_cycle_id
  where r.state='OPEN' and r.candidate_id=(v_scope->>'candidate_id')::uuid
    and r.client_id=(v_scope->>'client_id')::uuid and r.contract_id=(v_scope->>'contract_id')::uuid
    and r.work_date between (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date;
  v_blocked:=jsonb_array_length(v_manual)>0;

  for v_row in
    select i.*,e.work_date,e.candidate_id as event_candidate_id,e.client_id as event_client_id,
      x.id as comparison_id,x.incident_id as comparison_incident_id,x.contract_id as comparison_contract_id,
      owning.id as owning_comparison_id,owning.contract_id as owning_contract_id,
      tail.id as tail_comparison_id,
      x.issue_family,encode(x.material_comparison_fingerprint,'hex') as material_fingerprint,
      c.source_group_id as cycle_group_id
    from public.weekly_discrepancy_incidents i
    left join public.weekly_work_events e on e.id=i.work_event_id
    -- These immutable incident-owned revisions establish relevance independently
    -- of the suspect current pointer. The unique incident/revision index bounds
    -- both the first-owner point read and the actual backward-tail probe.
    left join public.weekly_issue_comparison_revisions owning
      on owning.incident_id=i.id and owning.revision_number=1
    left join lateral (select r.id from public.weekly_issue_comparison_revisions r
      where r.incident_id=i.id order by r.revision_number desc limit 1) tail on true
    left join public.weekly_issue_comparison_revisions x on x.id=i.current_comparison_revision_id
    left join public.weekly_source_cycles c on c.id=i.source_cycle_id
    where i.state='OPEN' and i.candidate_id=(v_scope->>'candidate_id')::uuid
      and i.client_id=(v_scope->>'client_id')::uuid
      and (e.work_date is null or e.work_date between
        (v_scope->>'week_ending_date')::date-6 and (v_scope->>'week_ending_date')::date)
      and (owning.contract_id is null or owning.contract_id=(v_scope->>'contract_id')::uuid)
    order by i.id
  loop
    if v_row.work_date is null or v_row.event_candidate_id is distinct from v_row.candidate_id
       or v_row.event_client_id is distinct from v_row.client_id
       or v_row.cycle_group_id is distinct from v_row.source_group_id
       or v_row.owning_comparison_id is null
       or v_row.owning_contract_id is distinct from (v_scope->>'contract_id')::uuid
       or v_row.comparison_id is null or v_row.comparison_incident_id is distinct from v_row.id
       or v_row.comparison_id is distinct from v_row.tail_comparison_id
       or v_row.comparison_contract_id is distinct from (v_scope->>'contract_id')::uuid
       or v_row.issue_family is null or v_row.material_fingerprint is null then
      v_unavailable:=true;
    end if;
    v_exception:=null;
    v_latest:=null;
    if v_scope->>'target_family_id' is not null then
      select e.* into v_latest from public.weekly_exceptional_pay_family_events e
        where e.family_id=(v_scope->>'target_family_id')::uuid
          and e.durable_work_event_id=v_row.work_event_id
        order by e.event_sequence desc limit 1;
    end if;
    if v_latest.id is not null and v_latest.state='WAIT' then
      v_exception:=private.weekly_source_protected_wait_receipt_v1(p_root_timesheet_id,v_latest.id);
      if v_exception is null then v_unavailable:=true; end if;
    end if;
    if v_row.issue_family is distinct from 'CANDIDATE_TIMESHEET_MISSING'
      and not (v_row.issue_family in ('HEALTHROSTER_NOT_FINALISED','SOURCE_MISSING_OR_NOT_AUTHORISED')
        and private.weekly_source_is_import_authoritative_v1(v_row.client_id,v_row.comparison_contract_id,v_row.work_date))
      and v_exception is null then
      v_blocked:=true;
    end if;
    v_hours:=v_hours||jsonb_build_array(jsonb_build_object('id',v_row.id,
      'source_group_id',v_row.source_group_id,'source_cycle_id',v_row.source_cycle_id,
      'work_event_id',v_row.work_event_id,'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,
      'state',v_row.state,'work_date',to_char(v_row.work_date,'YYYY-MM-DD'),
      'current_comparison_revision_id',v_row.comparison_id,'comparison_contract_id',v_row.comparison_contract_id,
      'issue_family',v_row.issue_family,'material_comparison_fingerprint',v_row.material_fingerprint,
      'latest_qualified_exception',v_exception));
  end loop;
  if v_unavailable then
    return jsonb_build_object('ok',false,'code','WEEKLY_SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE',
      'scope',v_scope,'blocked',null,'query_state_sha256',null); end if;
  v_state:=jsonb_build_object('schema_version','PAY_QUERY_STATE_V3','scope',v_scope,
    'manual_reviews',v_manual,'hours_incidents',v_hours);
  v_digest:=extensions.digest(convert_to(v_state::text,'UTF8'),'sha256');
  return jsonb_build_object('ok',true,'code','OK','scope',v_scope,'blocked',v_blocked,
    'query_state_sha256',encode(v_digest,'hex'),'hours_incidents',v_hours,'manual_reviews',v_manual);
end;
$function$;
alter function private.weekly_source_pay_query_facts_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_pay_query_facts_v1(uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_covered_hours_incident_v1(p_incident_id uuid)
returns boolean language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_root uuid; v_count integer; v_facts jsonb;
begin
  select count(*),(array_agg(family.root_timesheet_id))[1] into v_count,v_root
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work on work.id=incident.work_event_id
  join public.weekly_exceptional_pay_target_families family
    on family.candidate_id=incident.candidate_id and family.contract_id=comparison.contract_id
    and work.work_date between family.week_start_date and family.week_ending_date
  join public.contracts contract on contract.id=family.contract_id and contract.client_id=incident.client_id
  where incident.id=p_incident_id and incident.state='OPEN'
    and exists(select 1 from public.weekly_exceptional_pay_family_events event
      where event.family_id=family.id and event.durable_work_event_id=work.id);
  if v_count<>1 or v_root is null then return false; end if;
  v_facts:=private.weekly_source_pay_query_facts_v1(v_root);
  if v_facts->'ok' is distinct from 'true'::jsonb then return false; end if;
  return exists(select 1 from jsonb_array_elements(v_facts->'hours_incidents') item
    where item->>'id'=p_incident_id::text and jsonb_typeof(item->'latest_qualified_exception')='object');
end;
$function$;
alter function private.weekly_source_covered_hours_incident_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_covered_hours_incident_v1(uuid) from public,anon,authenticated,service_role;

-- One incident contact lifecycle owner; no mail creation or financial action.
create or replace function private.weekly_source_incident_contact_retire_v1(p_incident_id uuid)
returns void language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_episode integer; v_completed_generations uuid[];
begin
  select episode_number into strict v_episode from public.weekly_discrepancy_incidents
    where id=p_incident_id for update;
    update public.weekly_candidate_outreach_memberships membership set state='RESOLVED'
      from public.weekly_candidate_outreach_generations generation
      where membership.incident_id=p_incident_id and membership.state in ('ACTIONABLE','ANSWERED')
        and generation.id=membership.candidate_generation_id
        and generation.request_kind='CHECK_HOURS';
    -- Reuse the existing answered-hours completion rule. Keep a mixed cohort
    -- active while another question needs an answer; never finish the separate
    -- missing-Timesheet request or rewrite accepted delivery history.
    with completed as (
      update public.weekly_candidate_outreach_generations generation set state='COMPLETE'
      where generation.state='ACTIVE' and generation.request_kind='CHECK_HOURS'
        and exists(select 1 from public.weekly_candidate_outreach_memberships membership
          where membership.candidate_generation_id=generation.id
            and membership.incident_id=p_incident_id and membership.state='RESOLVED')
        and not exists(select 1 from public.weekly_candidate_outreach_memberships membership
          where membership.candidate_generation_id=generation.id and membership.state='ACTIONABLE')
      returning generation.id
    ) select array_agg(id) into v_completed_generations from completed;
    update public.weekly_message_intents set state='RETIRED'
      where candidate_generation_id=any(v_completed_generations) and state in ('DUE','RENDERED');
    update public.weekly_manager_review_items set response_state='FILTERED_RESOLVED'
      where incident_id=p_incident_id and incident_episode=v_episode
        and response_state='UNANSWERED';
    update public.office_action_notifications set operational_state='RESOLVED',
      resolved_at_utc=transaction_timestamp()
      where issue_id=p_incident_id and operational_state='OPEN';
end;
$function$;
alter function private.weekly_source_incident_contact_retire_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_incident_contact_retire_v1(uuid)
  from public,anon,authenticated,service_role;

-- Contact lifecycle only. A successfully qualified protected decision moves
-- its Office work to Protected shifts, without resolving the retained hours
-- incident used by the pay gate, changing money, or retiring sibling questions.
-- Completion owners call this AFTER their positive accepted receipt exists.
create or replace function private.weekly_source_protected_contact_retire_v1(
  p_family_id uuid, p_work_event_id uuid
) returns integer
language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_count integer:=0;
begin
  if p_family_id is null or p_work_event_id is null or not exists (
    select 1 from public.weekly_exceptional_pay_target_families family
    join public.weekly_work_events work on work.id=p_work_event_id
      and work.candidate_id=family.candidate_id
      and work.work_date between family.week_start_date and family.week_ending_date
    join public.contracts contract on contract.id=family.contract_id
      and contract.client_id=work.client_id
    where family.id=p_family_id and exists (
      select 1 from public.weekly_exceptional_pay_family_events event
      where event.family_id=family.id and event.durable_work_event_id=work.id
    )
  ) then
    raise exception 'WEEKLY_SOURCE_PROTECTED_CONTACT_SCOPE_INVALID' using errcode='55000';
  end if;
  for v_incident in
    select incident.* from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_exceptional_pay_target_families family
      on family.id=p_family_id and family.candidate_id=incident.candidate_id
      and family.contract_id=comparison.contract_id
    where incident.work_event_id=p_work_event_id and incident.state='OPEN'
    order by incident.id for update of incident
  loop
    -- A WAIT label, an unconfirmed Save, or an incomplete transport request is
    -- insufficient. Use the same evidence that actually removes the pay hold.
    if not private.weekly_source_covered_hours_incident_v1(v_incident.id) then continue; end if;
    perform private.weekly_source_incident_contact_retire_v1(v_incident.id);
    v_count:=v_count+1;
  end loop;
  return v_count;
end;
$function$;
alter function private.weekly_source_protected_contact_retire_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_protected_contact_retire_v1(uuid,uuid)
  from public,anon,authenticated,service_role;

-- Called only by the real finalisation owners after their exact selection is
-- established. Four-fact producer and report arm must precede this consumer.
create or replace function private.weekly_source_unprotected_not_finalised_close_v1(
  p_cycle_id uuid,p_report_scope_id uuid
) returns integer language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_cycle public.weekly_source_cycles%rowtype; v_report public.weekly_source_report_scopes%rowtype; v_row record;
  v_selection jsonb; v_wait jsonb; v_count integer:=0;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_cycle from public.weekly_source_cycles where id=p_cycle_id;
  if p_report_scope_id is not null then
    select * into strict v_report from public.weekly_source_report_scopes
      where id=p_report_scope_id and source_cycle_id=v_cycle.id and self_bill_report_id is not null;
    if v_report.source_group_id is distinct from v_cycle.source_group_id
      or v_report.client_id is null
      or (v_cycle.scope_client_id is not null and v_cycle.scope_client_id is distinct from v_report.client_id) then
      raise exception 'WEEKLY_SOURCE_UNPROTECTED_CLOSE_SCOPE_INVALID' using errcode='55000'; end if;
    perform private.weekly_source_current_publication_guard_v1(v_cycle.id,'SELF_BILL_REPORT_SCOPE',
      v_report.id,v_report.current_complete_upload_id,v_report.current_projection_publication_id,v_report.version);
    perform private.weekly_source_self_bill_report_rules_assert_v1(v_report.client_id,v_cycle.id);
  end if;
  for v_row in
    select incident.*,comparison.contract_id,comparison.material_comparison_fingerprint,
      work.work_date,work.first_source_group_id,work.candidate_id as event_candidate_id,
      work.client_id as event_client_id
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id
    where incident.source_cycle_id=v_cycle.id and incident.state='OPEN'
      and comparison.issue_family='HEALTHROSTER_NOT_FINALISED'
      and (p_report_scope_id is null or incident.client_id=v_report.client_id)
    order by incident.id for update of incident
  loop
    if v_row.source_group_id is distinct from v_cycle.source_group_id
      or v_row.first_source_group_id is distinct from v_cycle.source_group_id
      or v_row.event_candidate_id is distinct from v_row.candidate_id
      or v_row.event_client_id is distinct from v_row.client_id
      or (v_cycle.scope_client_id is not null and v_cycle.scope_client_id is distinct from v_row.client_id)
      or v_row.contract_id is null then
      raise exception 'WEEKLY_SOURCE_UNPROTECTED_CLOSE_SCOPE_INVALID' using errcode='55000'; end if;
    -- Mode A, non-authoritative roster and NHSP retain their existing owners.
    if not private.weekly_source_is_import_authoritative_v1(v_row.client_id,v_row.contract_id,v_row.work_date) then continue; end if;
    v_wait:=private.weekly_source_protected_wait_witness_v1(v_row.work_event_id,v_cycle.id);
    if v_wait is not null then continue; end if;
    v_selection:=private.weekly_source_shift_on_self_bill_v1(v_row.work_event_id,coalesce(p_report_scope_id,v_cycle.id));
    if jsonb_typeof(v_selection) is distinct from 'object'
      or (select count(*) from jsonb_object_keys(v_selection))<>4
      or jsonb_typeof(v_selection->'on_accepted_report') is distinct from 'boolean'
      or jsonb_typeof(v_selection->'bound_to_finalised_export') is distinct from 'boolean'
      or jsonb_typeof(v_selection->'invoice_ready') is distinct from 'boolean'
      or jsonb_typeof(v_selection->'s25_pay_selected') is distinct from 'boolean' then
      raise exception 'WEEKLY_SOURCE_UNPROTECTED_CLOSE_SELECTION_UNAVAILABLE' using errcode='55000'; end if;
    if (v_selection->>'s25_pay_selected')::boolean or (v_selection->>'on_accepted_report')::boolean then continue; end if;
    update public.weekly_discrepancy_incidents
      set state='CANCELLED',resolved_at_utc=null,resolution_kind=null,
        candidate_action_state='NOT_REQUIRED',manager_potential_state='NOT_REQUIRED',manager_action_state='NOT_REQUIRED'
      where id=v_row.id and state='OPEN';
    if not found then continue; end if;
    perform private.weekly_source_incident_contact_retire_v1(v_row.id);
    insert into public.weekly_discrepancy_events(incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,idempotency_key)
    values(v_row.id,v_row.episode_number,v_cycle.current_projection_publication_id,
      v_row.material_comparison_fingerprint,'SOURCE_RECHECKED','SYSTEM',
      jsonb_build_object('state','CANCELLED','reason','UNPROTECTED_NOT_ON_FINAL_SELF_BILL',
        'source_cycle_id',v_cycle.id,'report_scope_id',p_report_scope_id),
      'UNPROTECTED_NOT_FINALISED_CANCELLED:'||v_row.id::text||':'||v_row.episode_number::text)
    on conflict(event_kind,idempotency_key) do nothing;
    v_count:=v_count+1;
  end loop;
  return v_count;
end;
$function$;
alter function private.weekly_source_unprotected_not_finalised_close_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_unprotected_not_finalised_close_v1(uuid,uuid)
  from public,anon,authenticated,service_role;

-- Complete current global owners; absent optional key preserves configured actor.
create or replace function public.weekly_source_global_settings_get_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_agency uuid;
  v_settings public.weekly_source_global_settings%rowtype;
begin
  perform private._weekly_source_settings_assert_request_v1(
    p_request,array['actor_user_id','agency_id','environment'],
    'WEEKLY_SOURCE_GLOBAL_SETTINGS_GET_REQUEST_INVALID'
  );
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_agency:=(p_request->>'agency_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_GET_REQUEST_INVALID' using errcode='22023';
  end;
  perform private._weekly_source_settings_require_admin_v1(v_actor);
  perform private._weekly_source_settings_deployment_v1(v_agency,p_request->>'environment');
  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  return pg_catalog.jsonb_build_object(
    'ok',true,'settings_version',v_settings.version,
    'settings',pg_catalog.jsonb_build_object(
      'candidate_reminder_minutes',extract(epoch from v_settings.candidate_reminder_after)::bigint/60,
      'candidate_response_deadline_minutes',extract(epoch from v_settings.candidate_response_deadline_after)::bigint/60,
      'manager_digest_minutes',extract(epoch from v_settings.manager_partial_digest_after)::bigint/60,
      'manager_manual_resend_cooldown_minutes',extract(epoch from v_settings.manager_manual_send_cooldown)::bigint/60,
      'candidate_manual_reminder_cooldown_minutes',extract(epoch from v_settings.candidate_manual_reminder_cooldown)::bigint/60,
      'manager_secure_link_days',extract(epoch from v_settings.manager_secure_link_lifetime)::bigint/86400,
      'automatic_reconcile_actor_user_id',v_settings.automatic_reconcile_actor_user_id
    )
  );
end;
$function$;

create or replace function public.weekly_source_global_settings_save_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_agency uuid;
  v_expected bigint;
  v_settings_json jsonb;
  v_settings public.weekly_source_global_settings%rowtype;
  v_candidate_reminder integer;
  v_candidate_deadline integer;
  v_manager_digest integer;
  v_manager_cooldown integer;
  v_candidate_cooldown integer;
  v_link_days integer;
  v_automatic_actor uuid;
begin
  perform private._weekly_source_settings_assert_request_v1(
    p_request,array['actor_user_id','agency_id','environment','expected_settings_version','settings'],
    'WEEKLY_SOURCE_GLOBAL_SETTINGS_SAVE_REQUEST_INVALID'
  );
  v_settings_json:=p_request->'settings';
  perform private._weekly_source_settings_assert_request_v1(
    v_settings_json,array[
      'candidate_reminder_minutes','candidate_response_deadline_minutes',
      'manager_digest_minutes','manager_manual_resend_cooldown_minutes',
      'candidate_manual_reminder_cooldown_minutes','manager_secure_link_days','automatic_reconcile_actor_user_id'
    ],'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID'
  );
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_agency:=(p_request->>'agency_id')::uuid;
    v_expected:=(p_request->>'expected_settings_version')::bigint;
    v_candidate_reminder:=(v_settings_json->>'candidate_reminder_minutes')::integer;
    v_candidate_deadline:=(v_settings_json->>'candidate_response_deadline_minutes')::integer;
    v_manager_digest:=(v_settings_json->>'manager_digest_minutes')::integer;
    v_manager_cooldown:=(v_settings_json->>'manager_manual_resend_cooldown_minutes')::integer;
    v_candidate_cooldown:=(v_settings_json->>'candidate_manual_reminder_cooldown_minutes')::integer;
    v_link_days:=(v_settings_json->>'manager_secure_link_days')::integer;
    if v_settings_json ? 'automatic_reconcile_actor_user_id' then
      if jsonb_typeof(v_settings_json->'automatic_reconcile_actor_user_id') not in ('string','null') then
        raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID' using errcode='22023'; end if;
      v_automatic_actor:=nullif(v_settings_json->>'automatic_reconcile_actor_user_id','')::uuid;
      if v_automatic_actor is not null and not exists(select 1 from public.tms_users where id=v_automatic_actor) then
        raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID' using errcode='22023'; end if;
    end if;
  exception when others then
    raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_SAVE_REQUEST_INVALID' using errcode='22023';
  end;
  perform private._weekly_source_settings_require_admin_v1(v_actor);
  perform private._weekly_source_settings_deployment_v1(v_agency,p_request->>'environment');
  if v_candidate_reminder<1 or v_candidate_reminder>=720
     or v_candidate_deadline<=v_candidate_reminder or v_candidate_deadline>10080
     or v_manager_digest<1 or v_manager_digest>10080
     or v_manager_cooldown<5 or v_manager_cooldown>1440
     or v_candidate_cooldown<60 or v_candidate_cooldown>10080
     or v_link_days<1 or v_link_days>30 then
    raise exception 'WEEKLY_SOURCE_GLOBAL_SETTINGS_VALUES_INVALID' using errcode='22023';
  end if;
  select * into strict v_settings
  from public.weekly_source_global_settings where singleton for update;
  if v_settings.version<>v_expected then
    raise exception 'WEEKLY_SOURCE_SETTINGS_STALE' using errcode='40001';
  end if;
  update public.weekly_source_global_settings
  set candidate_reminder_after=pg_catalog.make_interval(mins=>v_candidate_reminder),
      candidate_response_deadline_after=pg_catalog.make_interval(mins=>v_candidate_deadline),
      manager_partial_digest_after=pg_catalog.make_interval(mins=>v_manager_digest),
      manager_manual_send_cooldown=pg_catalog.make_interval(mins=>v_manager_cooldown),
      candidate_manual_reminder_cooldown=pg_catalog.make_interval(mins=>v_candidate_cooldown),
      manager_secure_link_lifetime=pg_catalog.make_interval(days=>v_link_days),
      automatic_reconcile_actor_user_id=case when v_settings_json ? 'automatic_reconcile_actor_user_id'
        then v_automatic_actor else automatic_reconcile_actor_user_id end,
      version=version+1,updated_by_user_id=v_actor,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where singleton;
  return public.weekly_source_global_settings_get_v1(pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor,'agency_id',v_agency,'environment',p_request->>'environment'
  ));
end;
$function$;

