revoke all on function public.weekly_source_global_settings_get_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_global_settings_get_v1(jsonb) to service_role;
alter function public.weekly_source_global_settings_save_atomic_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_global_settings_save_atomic_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_global_settings_save_atomic_v1(jsonb) to service_role;

-- Native current row set, with scoped confirmed-date narrowing and actual projection generation.
create or replace function private.weekly_source_candidate_current_rows_v1(
  p_projection_publication_id uuid,
  p_candidate_id uuid,
  p_client_id uuid,
  p_contract_id uuid,
  p_week_ending date
) returns table(
  source_row_id uuid,
  source_link_id uuid,
  work_event_id uuid,
  work_date date,
  start_at_local timestamp without time zone,
  end_at_local timestamp without time zone,
  break_minutes integer,
  row_finalisation_state text
)
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  select source_row.id,source_link.id,work_event.id,source_row.work_date,
    source_row.start_at_local,source_row.end_at_local,source_row.break_minutes,
    source_row.row_finalisation_state
  from public.weekly_source_projection_publications publication
  join public.weekly_source_upload_rows source_row
    on source_row.upload_id=publication.upload_id
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id
   and resolution.generation=coalesce(publication.projection_generation,publication.authority_scope_version)
   and resolution.mapping_state='RESOLVED'
   and resolution.candidate_id=p_candidate_id
   and resolution.client_id=p_client_id
   and resolution.contract_id=p_contract_id
  join public.weekly_work_event_source_links source_link
    on source_link.upload_row_id=source_row.id
   and source_link.row_resolution_id=resolution.id
   and source_link.work_event_id=resolution.work_event_id
  join public.weekly_work_events work_event
    on work_event.id=resolution.work_event_id
   and work_event.candidate_id=p_candidate_id
   and work_event.client_id=p_client_id
  where publication.id=p_projection_publication_id
    and publication.state='CURRENT'
    and source_row.work_date between p_week_ending-6 and p_week_ending
    and (not private.weekly_source_is_import_authoritative_v1(p_client_id,p_contract_id,source_row.work_date)
      or exists(select 1 from public.weekly_source_uploads upload where upload.id=publication.upload_id
        and source_row.work_date between upload.confirmed_coverage_start_local_date and upload.confirmed_coverage_end_local_date))
  order by source_row.work_date,source_row.start_at_local,
    source_row.end_at_local,source_row.id;
$function$;
alter function private.weekly_source_candidate_current_rows_v1(uuid,uuid,uuid,uuid,date) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_candidate_current_rows_v1(uuid,uuid,uuid,uuid,date) from public,anon,authenticated,service_role;

-- Complete comparator; scoped coverage and manager-only not-finalised behavior.
create or replace function private.weekly_source_candidate_submission_compare_sync_v1(
  p_candidate_generation_id uuid,
  p_projection_publication_id uuid,
  p_membership_id uuid,
  p_timesheet_id uuid,
  p_timesheet_hash bytea,
  p_now_utc timestamptz default pg_catalog.transaction_timestamp()
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_generation public.weekly_candidate_outreach_generations%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile_code text;
  v_submission public.weekly_timesheet_submission_requests%rowtype;
  v_membership public.weekly_timesheet_submission_request_memberships%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_candidate_row jsonb;
  v_source_json jsonb;
  v_source record;
  v_candidate_start timestamp without time zone;
  v_candidate_end timestamp without time zone;
  v_candidate_break integer;
  v_candidate_shift_hash bytea;
  v_durable_identity_hash bytea;
  v_prior_work_event_id uuid;
  v_work_event public.weekly_work_events%rowtype;
  v_issue jsonb;
  v_issues jsonb:='[]'::jsonb;
  v_used_source_rows uuid[]:='{}'::uuid[];
  v_seen_work_events uuid[]:='{}'::uuid[];
  v_tie_count integer;
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_policy jsonb;
  v_episode integer;
  v_revision integer;
  v_fingerprint bytea;
  v_is_new boolean;
  v_issue_family text;
  v_presence text;
  v_new_count integer:=0;
  v_changed_count integer:=0;
  v_unchanged_count integer:=0;
  v_resolved_count integer:=0;
  v_open_count integer:=0;
  v_import_authoritative boolean:=false;
  v_scope_client_id uuid;
  v_source_question_changed boolean:=false;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_projection_publication_id is null or p_timesheet_id is null
     or p_timesheet_hash is null or pg_catalog.octet_length(p_timesheet_hash)<>32 then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_REQUEST_INVALID' using errcode='22023';
  end if;

  if p_candidate_generation_id is null then
    -- A newly published checking source must recompare already-signed weekly
    -- evidence even when no submission request was needed or remains active.
    if p_membership_id is not null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_REQUEST_INVALID' using errcode='22023';
    end if;
    select * into strict v_publication
    from public.weekly_source_projection_publications
    where id=p_projection_publication_id and state='CURRENT';
    select * into strict v_cycle from public.weekly_source_cycles
    where id=v_publication.source_cycle_id for update;
    select * into strict v_timesheet from public.timesheets
    where timesheet_id=p_timesheet_id and is_current
      and revoked_at is null and archived_at_utc is null
      and sheet_scope='WEEKLY' and line_type='HOURS'
      and authorised_at_server is null
      and r2_nurse_key is not null and img_sha256_nurse is not null
    for update;
    select * into strict v_contract from public.contracts
    where id=v_timesheet.contract_id;
    v_generation.candidate_id:=v_contract.candidate_id;
    v_membership.contract_id:=v_contract.id;
    v_membership.client_id:=v_contract.client_id;
    v_membership.week_ending:=v_timesheet.week_ending_date;
  else
    if p_membership_id is null then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_REQUEST_INVALID' using errcode='22023';
    end if;
    select * into strict v_generation
    from public.weekly_candidate_outreach_generations
    where id=p_candidate_generation_id and request_kind='SUBMIT_TIMESHEET'
      and state='ACTIVE'
    for update;
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_generation.source_cycle_id
    for update;
  end if;
  perform private.weekly_source_query_current_publication_v1(
    v_cycle.id,p_projection_publication_id
  );
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=p_projection_publication_id
    and source_cycle_id=v_cycle.id and state='CURRENT';
  select * into strict v_upload from public.weekly_source_uploads
  where id=v_publication.upload_id and source_cycle_id=v_cycle.id;
  select profile.profile_code into strict v_profile_code
  from public.weekly_source_format_profiles profile
  where profile.id=v_upload.source_format_profile_id;
  if v_profile_code='NHSP_PREFINAL_RELEASED_V1'
     and (v_upload.confirmed_coverage_start_local_date is null
       or v_upload.confirmed_coverage_end_local_date is null) then
    raise exception 'WEEKLY_SOURCE_PREFINAL_COVERAGE_INVALID' using errcode='55000';
  end if;
  if p_candidate_generation_id is not null then
    select * into strict v_submission
    from public.weekly_timesheet_submission_requests
    where candidate_cohort_id=v_generation.candidate_cohort_id
      and candidate_id=v_generation.candidate_id
      and source_cycle_id=v_cycle.id
      and current_projection_publication_id=v_publication.id
      and state in ('ACTIVE','OVERDUE','PARTLY_SUBMITTED')
    for update;
    select * into strict v_membership
    from public.weekly_timesheet_submission_request_memberships
    where id=p_membership_id and submission_request_id=v_submission.id
      and state='WAITING'
    for update;
    select * into strict v_contract from public.contracts
    where id=v_membership.contract_id
      and candidate_id=v_generation.candidate_id
      and client_id=v_membership.client_id;
    select * into strict v_timesheet from public.timesheets
    where timesheet_id=p_timesheet_id and contract_id=v_membership.contract_id
      and week_ending_date=v_membership.week_ending
      and is_current and revoked_at is null and archived_at_utc is null
      and sheet_scope='WEEKLY' and line_type='HOURS'
      and authorised_at_server is null
      and r2_nurse_key is not null and img_sha256_nurse is not null
    for update;
  end if;
  v_scope_client_id:=private.weekly_source_checking_client_scope_v1(v_publication.id);
  if v_scope_client_id is not null and v_scope_client_id is distinct from v_contract.client_id then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_timesheet.version<1
     or private.weekly_source_query_candidate_timesheet_hash_v1(v_timesheet.timesheet_id)
          is distinct from p_timesheet_hash then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_TIMESHEET_STALE' using errcode='40001';
  end if;
  v_import_authoritative:=private.weekly_source_is_import_authoritative_v1(
    v_contract.client_id,v_contract.id,v_membership.week_ending);
  if v_import_authoritative and (v_upload.confirmed_coverage_start_local_date is null
    or v_upload.confirmed_coverage_end_local_date is null) then
    raise exception 'WEEKLY_SOURCE_PREFINAL_COVERAGE_INVALID' using errcode='55000'; end if;
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_membership.week_ending
  );
  if v_policy->>'source_group_id' is distinct from v_group.id::text
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or v_policy->>'document_mode'<>'CHECK_ONLY' then
    raise exception 'WEEKLY_SOURCE_SECURE_QUERY_NOT_APPLICABLE' using errcode='55000';
  end if;
  if exists(
    select 1
    from private.weekly_source_candidate_current_rows_v1(
      v_publication.id,v_generation.candidate_id,v_membership.client_id,
      v_membership.contract_id,v_membership.week_ending
    ) source_row
    where source_row.row_finalisation_state in (
      'BLOCK_FINALISATION_DISAGREEMENT','BLOCK_ACTUAL_TUPLE'
    )
  ) then
    raise exception 'WEEKLY_SOURCE_CANDIDATE_SOURCE_SCOPE_BLOCKED' using errcode='55000';
  end if;

  for v_candidate_row in
    select value
    from pg_catalog.jsonb_array_elements(
      private.weekly_source_candidate_app_schedule_v1(
        v_timesheet.actual_schedule_json,v_timesheet.additional_units_per_day
      )
    ) candidate_row
    where (v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' and not v_import_authoritative)
      or (candidate_row.value->>'date')::date between
        v_upload.confirmed_coverage_start_local_date
        and v_upload.confirmed_coverage_end_local_date
    order by value->>'date',value->>'start',value->>'end',
      coalesce(value->>'row_key','') collate "C"
  loop
    v_candidate_start:=(v_candidate_row->>'date')::date+
      (v_candidate_row->>'start')::time;
    v_candidate_end:=(v_candidate_row->>'date')::date+
      (v_candidate_row->>'end')::time;
    if v_candidate_end<=v_candidate_start then
      v_candidate_end:=v_candidate_end+interval '1 day';
    end if;
    v_candidate_break:=coalesce(
      nullif(v_candidate_row#>>'{break_entry,break_minutes}','')::integer,
      nullif(v_candidate_row#>>'{break_entry,calculated_break_minutes}','')::integer,0
    );
    v_candidate_shift_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CANDIDATE_SHIFT_V1',
      pg_catalog.jsonb_build_object(
        'timesheet_id',v_timesheet.timesheet_id,'timesheet_revision',v_timesheet.version,
        'row_key',v_candidate_row->>'row_key','work_date',v_candidate_row->>'date',
        'start_at_local',v_candidate_start,'end_at_local',v_candidate_end,
        'break_minutes',v_candidate_break,
        'additional_units',coalesce(v_candidate_row->'additional_units','[]'::jsonb)
      )
    );

    select pg_catalog.jsonb_build_object(
      'source_row_id',source_row.source_row_id,'source_link_id',source_row.source_link_id,
      'source_link_kind',(select link.link_kind
        from public.weekly_work_event_source_links link
        where link.id=source_row.source_link_id),
      'work_event_id',source_row.work_event_id,'work_date',source_row.work_date,
      'start_at_local',source_row.start_at_local,'end_at_local',source_row.end_at_local,
      'break_minutes',source_row.break_minutes,
      'row_finalisation_state',source_row.row_finalisation_state
    ) into v_source_json
    from private.weekly_source_candidate_current_rows_v1(
      v_publication.id,v_generation.candidate_id,v_membership.client_id,
      v_membership.contract_id,v_membership.week_ending
    ) source_row
    where not (source_row.source_row_id=any(v_used_source_rows))
      and source_row.row_finalisation_state in (
        'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_UNFINALISED'
      )
      and (select link.link_kind from public.weekly_work_event_source_links link
           where link.id=source_row.source_link_id)
            not in ('FULL_NEGATIVE_SOURCE','ZERO_SOURCE')
      and source_row.work_date=(v_candidate_row->>'date')::date
      and source_row.start_at_local=v_candidate_start
      and source_row.end_at_local=v_candidate_end
      and coalesce(source_row.break_minutes,0)=v_candidate_break
    order by source_row.source_row_id limit 1;

    if v_source_json is null then
      with possible as (
        select source_row.*,
          (select link.link_kind from public.weekly_work_event_source_links link
           where link.id=source_row.source_link_id) as source_link_kind,
          case
            when source_row.start_at_local is null or source_row.end_at_local is null
              then 1000000000::numeric
            else
              pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.start_at_local-v_candidate_start)/60)
              +pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.end_at_local-v_candidate_end)/60)
              +pg_catalog.abs(coalesce(source_row.break_minutes,0)-v_candidate_break)
          end as distance
        from private.weekly_source_candidate_current_rows_v1(
          v_publication.id,v_generation.candidate_id,v_membership.client_id,
          v_membership.contract_id,v_membership.week_ending
        ) source_row
        where not (source_row.source_row_id=any(v_used_source_rows))
          and source_row.work_date=(v_candidate_row->>'date')::date
          and source_row.row_finalisation_state in (
            'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO','SOURCE_UNFINALISED'
          )
      ),minimum as (select pg_catalog.min(distance) distance from possible)
      select pg_catalog.count(*)::integer into v_tie_count
      from possible,minimum where possible.distance=minimum.distance;
      if v_tie_count>1 then
        raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_AMBIGUOUS' using errcode='55000';
      elsif v_tie_count=1 then
        with possible as (
          select source_row.*,
            (select link.link_kind from public.weekly_work_event_source_links link
             where link.id=source_row.source_link_id) as source_link_kind,
            case
              when source_row.start_at_local is null or source_row.end_at_local is null
                then 1000000000::numeric
              else
                pg_catalog.abs(pg_catalog.date_part('epoch',
                  source_row.start_at_local-v_candidate_start)/60)
                +pg_catalog.abs(pg_catalog.date_part('epoch',
                  source_row.end_at_local-v_candidate_end)/60)
                +pg_catalog.abs(coalesce(source_row.break_minutes,0)-v_candidate_break)
            end as distance
          from private.weekly_source_candidate_current_rows_v1(
            v_publication.id,v_generation.candidate_id,v_membership.client_id,
            v_membership.contract_id,v_membership.week_ending
          ) source_row
          where not (source_row.source_row_id=any(v_used_source_rows))
            and source_row.work_date=(v_candidate_row->>'date')::date
            and source_row.row_finalisation_state in (
              'NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO','SOURCE_UNFINALISED'
            )
        )
        select pg_catalog.jsonb_build_object(
          'source_row_id',source_row_id,'source_link_id',source_link_id,
          'source_link_kind',source_link_kind,
          'work_event_id',work_event_id,'work_date',work_date,
          'start_at_local',start_at_local,'end_at_local',end_at_local,
          'break_minutes',break_minutes,'row_finalisation_state',row_finalisation_state
        ) into v_source_json
        from possible order by distance,source_row_id limit 1;
      end if;
    end if;

    if v_source_json is null then
      -- A replacement NHSP file may omit a previously linked shift. Reuse
      -- that durable event instead of inventing a new issue/notification clock.
      v_prior_work_event_id:=null;
      if p_candidate_generation_id is null then
        with prior_events as (
          select link.work_event_id,
            pg_catalog.min(
              pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.start_at_local-v_candidate_start)/60)
              +pg_catalog.abs(pg_catalog.date_part('epoch',
                source_row.end_at_local-v_candidate_end)/60)
              +pg_catalog.abs(coalesce(source_row.break_minutes,0)-v_candidate_break)
            ) as distance
          from public.weekly_source_uploads historical_upload
          join public.weekly_source_upload_rows source_row
            on source_row.upload_id=historical_upload.id
          join public.weekly_source_row_resolutions resolution
            on resolution.upload_row_id=source_row.id
           and resolution.mapping_state='RESOLVED'
          join public.weekly_work_event_source_links link
            on link.upload_row_id=source_row.id
           and link.row_resolution_id=resolution.id
           and link.work_event_id=resolution.work_event_id
          join public.weekly_work_events work_event
            on work_event.id=link.work_event_id
          where historical_upload.source_cycle_id=v_cycle.id
            and historical_upload.id<>v_upload.id
            -- A provisional check must not choose a final backing-report
            -- event as the identity of a missing provisional shift.
            and historical_upload.source_format_profile_id=v_upload.source_format_profile_id
            and source_row.work_date=(v_candidate_row->>'date')::date
            and source_row.start_at_local is not null
            and source_row.end_at_local is not null
            and resolution.candidate_id=v_generation.candidate_id
            and resolution.client_id=v_membership.client_id
            and resolution.contract_id=v_membership.contract_id
            and work_event.first_source_group_id=v_group.id
          group by link.work_event_id
        ), nearest as (
          select work_event_id,distance,
            pg_catalog.count(*) over (partition by distance) as tie_count
          from prior_events
        )
        select work_event_id,tie_count
        into v_prior_work_event_id,v_tie_count
        from nearest order by distance,work_event_id limit 1;
        if v_tie_count>1 then
          raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_AMBIGUOUS' using errcode='55000';
        end if;
      end if;
      if v_prior_work_event_id is null then
        v_durable_identity_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_WORK_EVENT_SCHEDULE_TUPLE_V1',
        pg_catalog.jsonb_build_object(
          'source_group_id',v_group.id,
          'source_format_profile_id',v_upload.source_format_profile_id,
          'candidate_id',v_generation.candidate_id,
          'client_id',v_membership.client_id,
          'work_date',(v_candidate_row->>'date')::date,
          'start_at_local',v_candidate_start,'end_at_local',v_candidate_end
        )
      );
        insert into public.weekly_work_events(
        candidate_id,client_id,work_date,identity_kind,profile_external_key,
        durable_identity_hash,first_source_group_id,source_format_profile_id
      ) values (
        v_generation.candidate_id,v_membership.client_id,
        (v_candidate_row->>'date')::date,'SCHEDULE_TUPLE',null,
        v_durable_identity_hash,v_group.id,v_upload.source_format_profile_id
      ) on conflict (durable_identity_hash) do nothing;
        select * into strict v_work_event from public.weekly_work_events
        where durable_identity_hash=v_durable_identity_hash;
        if v_work_event.candidate_id is distinct from v_generation.candidate_id
           or v_work_event.client_id is distinct from v_membership.client_id
           or v_work_event.work_date is distinct from (v_candidate_row->>'date')::date
           or v_work_event.first_source_group_id is distinct from v_group.id then
          raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_COLLISION' using errcode='55000';
        end if;
      else
        select * into strict v_work_event from public.weekly_work_events
        where id=v_prior_work_event_id;
      end if;
      v_issue:=pg_catalog.jsonb_build_object(
        'work_event_id',v_work_event.id,
        'candidate_timesheet_id',v_timesheet.timesheet_id,
        'candidate_timesheet_revision',v_timesheet.version,
        'candidate_shift_fingerprint',pg_catalog.encode(v_candidate_shift_hash,'hex'),
        'source_row_id',null,'source_work_event_link_id',null,
        'contract_id',v_membership.contract_id,
        'issue_family','SOURCE_MISSING_OR_NOT_AUTHORISED','source_presence','ABSENT',
        'candidate_start_at_local',v_candidate_start,
        'candidate_end_at_local',v_candidate_end,
        'candidate_break_minutes',v_candidate_break,
        'system_start_at_local',null,'system_end_at_local',null,
        'system_break_minutes',null
      );
      v_issues:=v_issues||pg_catalog.jsonb_build_array(v_issue);
    else
      v_used_source_rows:=pg_catalog.array_append(
        v_used_source_rows,(v_source_json->>'source_row_id')::uuid
      );
      if v_source_json->>'source_link_kind' in ('FULL_NEGATIVE_SOURCE','ZERO_SOURCE')
         or v_source_json->>'row_finalisation_state'='SOURCE_ABSENT_ZERO' then
        v_issue_family:='SOURCE_MISSING_OR_NOT_AUTHORISED';
        v_presence:='ABSENT';
      elsif v_source_json->>'row_finalisation_state'='SOURCE_UNFINALISED' then
        v_issue_family:='HEALTHROSTER_NOT_FINALISED';
        v_presence:='UNFINALISED';
      elsif nullif(v_source_json->>'start_at_local','')::timestamp=v_candidate_start
         and nullif(v_source_json->>'end_at_local','')::timestamp=v_candidate_end
         and coalesce(nullif(v_source_json->>'break_minutes','')::integer,0)=v_candidate_break then
        v_issue_family:=null;
        v_presence:='PRESENT';
      else
        v_issue_family:='SOURCE_HOURS_DIFFER';
        v_presence:='PRESENT';
      end if;
      if v_issue_family is not null then
        v_issue:=pg_catalog.jsonb_build_object(
          'work_event_id',(v_source_json->>'work_event_id')::uuid,
          'candidate_timesheet_id',v_timesheet.timesheet_id,
          'candidate_timesheet_revision',v_timesheet.version,
          'candidate_shift_fingerprint',pg_catalog.encode(v_candidate_shift_hash,'hex'),
          'source_row_id',(v_source_json->>'source_row_id')::uuid,
          'source_work_event_link_id',(v_source_json->>'source_link_id')::uuid,
          'contract_id',v_membership.contract_id,
          'issue_family',v_issue_family,'source_presence',v_presence,
          'candidate_start_at_local',v_candidate_start,
          'candidate_end_at_local',v_candidate_end,
          'candidate_break_minutes',v_candidate_break,
          'system_start_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
            then nullif(v_source_json->>'start_at_local','')::timestamp end,
          'system_end_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
            then nullif(v_source_json->>'end_at_local','')::timestamp end,
          'system_break_minutes',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
            then nullif(v_source_json->>'break_minutes','')::integer end
        );
        v_issues:=v_issues||pg_catalog.jsonb_build_array(v_issue);
      end if;
    end if;
  end loop;

  for v_source in
    select *
    from private.weekly_source_candidate_current_rows_v1(
      v_publication.id,v_generation.candidate_id,v_membership.client_id,
      v_membership.contract_id,v_membership.week_ending
    ) source_row
    where not (source_row.source_row_id=any(v_used_source_rows))
      and source_row.row_finalisation_state<>'SOURCE_ABSENT_ZERO'
      and (not v_import_authoritative or source_row.work_date between
        v_upload.confirmed_coverage_start_local_date and v_upload.confirmed_coverage_end_local_date)
      and (select link.link_kind from public.weekly_work_event_source_links link
           where link.id=source_row.source_link_id)
            not in ('FULL_NEGATIVE_SOURCE','ZERO_SOURCE')
    order by source_row.work_date,source_row.start_at_local,
      source_row.end_at_local,source_row.source_row_id
  loop
    v_candidate_shift_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CANDIDATE_SHIFT_V1',
      pg_catalog.jsonb_build_object(
        'timesheet_id',v_timesheet.timesheet_id,
        'timesheet_revision',v_timesheet.version,
        'work_event_id',v_source.work_event_id,'worked',false
      )
    );
    if v_source.row_finalisation_state='SOURCE_UNFINALISED' then
      if v_import_authoritative and not exists(select 1 from public.contract_weeks expected
        where expected.contract_id=v_contract.id and expected.additional_seq=0
          and not coalesce(expected.is_adjustment,false) and expected.status<>'CANCELLED'
          and v_source.work_date between expected.week_ending_date-6 and expected.week_ending_date) then continue; end if;
      v_issue_family:='HEALTHROSTER_NOT_FINALISED';
      v_presence:='UNFINALISED';
    elsif v_source.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED') then
      v_issue_family:='SOURCE_HOURS_DIFFER';
      v_presence:='PRESENT';
    else
      raise exception 'WEEKLY_SOURCE_CANDIDATE_SOURCE_SCOPE_BLOCKED' using errcode='55000';
    end if;
    v_issue:=pg_catalog.jsonb_build_object(
      'work_event_id',v_source.work_event_id,
      'candidate_timesheet_id',v_timesheet.timesheet_id,
      'candidate_timesheet_revision',v_timesheet.version,
      'candidate_shift_fingerprint',pg_catalog.encode(v_candidate_shift_hash,'hex'),
      'source_row_id',v_source.source_row_id,
      'source_work_event_link_id',v_source.source_link_id,
      'contract_id',v_membership.contract_id,
      'issue_family',v_issue_family,'source_presence',v_presence,
      'candidate_start_at_local',null,'candidate_end_at_local',null,
      'candidate_break_minutes',null,
      'system_start_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
        then v_source.start_at_local end,
      'system_end_at_local',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
        then v_source.end_at_local end,
      'system_break_minutes',case when v_presence='PRESENT' or (v_import_authoritative and v_presence='UNFINALISED')
        then v_source.break_minutes end
    );
    v_issues:=v_issues||pg_catalog.jsonb_build_array(v_issue);
  end loop;

  for v_issue in
    select value from pg_catalog.jsonb_array_elements(v_issues)
    order by value->>'work_event_id'
  loop
    select * into strict v_work_event from public.weekly_work_events
    where id=(v_issue->>'work_event_id')::uuid
      and candidate_id=v_generation.candidate_id
      and client_id=v_membership.client_id
      and first_source_group_id=v_group.id;
    if v_work_event.id=any(v_seen_work_events) then
      raise exception 'WEEKLY_SOURCE_QUERY_DUPLICATE_WORK_EVENT' using errcode='22023';
    end if;
    v_seen_work_events:=pg_catalog.array_append(v_seen_work_events,v_work_event.id);
    v_issue_family:=v_issue->>'issue_family';
    v_presence:=v_issue->>'source_presence';
    v_policy:=private._weekly_source_effective_policy_v1(
      v_membership.client_id,v_membership.contract_id,v_work_event.work_date
    );
    if v_policy->>'source_group_id' is distinct from v_group.id::text
       or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
       or v_policy->>'document_mode'<>'CHECK_ONLY' then
      raise exception 'WEEKLY_SOURCE_SECURE_QUERY_NOT_APPLICABLE' using errcode='55000';
    end if;

    perform 1 from public.weekly_work_events where id=v_work_event.id for update;
    if private.weekly_source_query_resolved_decision_matches_v1(v_group.id,v_work_event.id,v_issue) then
      v_unchanged_count:=v_unchanged_count+1;
      continue;
    end if;
    select * into v_incident
    from public.weekly_discrepancy_incidents
    where source_group_id=v_group.id and work_event_id=v_work_event.id
      and state='OPEN'
    for update;
    v_is_new:=not found;
    if v_is_new then
      select coalesce(pg_catalog.max(episode_number),0)+1 into v_episode
      from public.weekly_discrepancy_incidents
      where source_group_id=v_group.id and work_event_id=v_work_event.id;
      insert into public.weekly_discrepancy_incidents(
        source_group_id,work_event_id,episode_number,candidate_id,client_id,
        source_cycle_id,state,reconciliation_state,candidate_action_state,
        manager_potential_state,manager_action_state,waiting_source_state
      ) values (
        v_group.id,v_work_event.id,v_episode,v_generation.candidate_id,
        v_membership.client_id,v_cycle.id,'OPEN','UNRESOLVED',
        case when v_issue_family='HEALTHROSTER_NOT_FINALISED' and v_import_authoritative then 'NOT_REQUIRED'
          when p_candidate_generation_id is null
          and coalesce((v_policy->>'candidate_queries_enabled')::boolean,false)
          then 'NOT_ASKED' else 'NOT_REQUIRED' end,
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                   and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'AVAILABLE' else 'NOT_AVAILABLE' end,
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false)
                   and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'NOT_SENT' else 'NOT_REQUIRED' end,
        'NOT_WAITING'
      ) returning * into v_incident;
      v_comparison.id:=null;
      v_new_count:=v_new_count+1;
    else
      if v_incident.candidate_id is distinct from v_generation.candidate_id
         or v_incident.client_id is distinct from v_membership.client_id
         or v_incident.source_cycle_id is distinct from v_cycle.id
         or v_incident.current_comparison_revision_id is null then
        raise exception 'WEEKLY_SOURCE_CANDIDATE_INCIDENT_SCOPE_CONFLICT' using errcode='55000';
      end if;
      select * into strict v_comparison from public.weekly_issue_comparison_revisions
      where id=v_incident.current_comparison_revision_id;
      if v_comparison.contract_id is distinct from v_membership.contract_id then
        raise exception 'WEEKLY_SOURCE_CANDIDATE_INCIDENT_SCOPE_CONFLICT' using errcode='55000';
      end if;
      v_episode:=v_incident.episode_number;
    end if;

    v_source_question_changed:=v_import_authoritative and v_comparison.id is not null
      and (v_comparison.issue_family,v_comparison.source_presence,v_comparison.system_start_at_local,
        v_comparison.system_end_at_local,v_comparison.system_break_minutes)
      is distinct from (v_issue_family,v_presence,nullif(v_issue->>'system_start_at_local','')::timestamp,
        nullif(v_issue->>'system_end_at_local','')::timestamp,nullif(v_issue->>'system_break_minutes','')::integer);
    v_fingerprint:=private.weekly_source_query_comparison_fingerprint_v1(
      v_incident.id,v_episode,v_work_event.id,v_issue
    );
    if not v_is_new and v_comparison.material_comparison_fingerprint<>v_fingerprint then
      -- A re-signed candidate week changes the current comparison but not the
      -- identity or outreach clock of an already-open work-event incident.
      v_changed_count:=v_changed_count+1;
    end if;
    if v_comparison.id is not null
       and v_comparison.material_comparison_fingerprint=v_fingerprint then
      v_unchanged_count:=v_unchanged_count+1;
    else
      select coalesce(pg_catalog.max(revision_number),0)+1 into v_revision
      from public.weekly_issue_comparison_revisions
      where incident_id=v_incident.id;
      insert into public.weekly_issue_comparison_revisions(
        incident_id,revision_number,projection_publication_id,comparison_upload_id,
        final_revision_id,candidate_timesheet_id,candidate_timesheet_revision,
        candidate_shift_fingerprint,source_row_id,source_work_event_link_id,
        contract_id,issue_family,source_presence,candidate_start_at_local,
        candidate_end_at_local,candidate_break_minutes,system_start_at_local,
        system_end_at_local,system_break_minutes,material_comparison_fingerprint
      ) values (
        v_incident.id,v_revision,v_publication.id,v_upload.id,null,
        v_timesheet.timesheet_id,v_timesheet.version,
        private.weekly_source_query_hex32_v1(
          v_issue->>'candidate_shift_fingerprint',
          'WEEKLY_SOURCE_CANDIDATE_SHIFT_HASH_INVALID'
        ),nullif(v_issue->>'source_row_id','')::uuid,
        nullif(v_issue->>'source_work_event_link_id','')::uuid,
        v_membership.contract_id,v_issue_family,v_presence,
        nullif(v_issue->>'candidate_start_at_local','')::timestamp,
        nullif(v_issue->>'candidate_end_at_local','')::timestamp,
        nullif(v_issue->>'candidate_break_minutes','')::integer,
        nullif(v_issue->>'system_start_at_local','')::timestamp,
        nullif(v_issue->>'system_end_at_local','')::timestamp,
        nullif(v_issue->>'system_break_minutes','')::integer,v_fingerprint
      ) returning * into v_comparison;
      update public.weekly_discrepancy_incidents
      set current_comparison_revision_id=v_comparison.id,
        candidate_action_state=case when v_issue_family='HEALTHROSTER_NOT_FINALISED' and v_import_authoritative
          then 'NOT_REQUIRED' else candidate_action_state end,
        manager_action_state=case when v_source_question_changed and manager_potential_state='AVAILABLE'
          then 'NOT_SENT' else manager_action_state end,
        waiting_source_state=case when v_source_question_changed then 'NOT_WAITING' else waiting_source_state end,
        reconciliation_state=case when v_source_question_changed then 'UNRESOLVED' else reconciliation_state end
      where id=v_incident.id;
      insert into public.weekly_discrepancy_events(
        incident_id,issue_episode,projection_publication_id,
        expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
        idempotency_key
      ) values (
        v_incident.id,v_incident.episode_number,v_publication.id,v_fingerprint,
        'SOURCE_RECHECKED','SYSTEM',
        pg_catalog.jsonb_build_object(
          'issue_family',v_issue_family,'source_presence',v_presence,
          'comparison_revision_id',v_comparison.id,
          'origin','CANDIDATE_TIMESHEET_SUBMISSION'
        ),
        'SOURCE_RECHECKED:'||v_incident.id::text||':'||pg_catalog.encode(v_fingerprint,'hex')
      ) on conflict (event_kind,idempotency_key) do nothing;
    end if;
  end loop;

  for v_incident in
    select incident.*
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    where incident.source_group_id=v_group.id
      and incident.source_cycle_id=v_cycle.id
      and incident.candidate_id=v_generation.candidate_id
      and incident.client_id=v_membership.client_id
      and comparison.contract_id=v_membership.contract_id
      and work_event.work_date between v_membership.week_ending-6 and v_membership.week_ending
      and ((v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' and not v_import_authoritative)
        or work_event.work_date between v_upload.confirmed_coverage_start_local_date
          and v_upload.confirmed_coverage_end_local_date)
      and incident.state='OPEN'
      and not (incident.work_event_id=any(v_seen_work_events))
    order by incident.id for update of incident
  loop
    update public.weekly_discrepancy_incidents
    set state='RESOLVED',reconciliation_state='RECONCILED',
      candidate_action_state='NOT_REQUIRED',manager_potential_state='NOT_REQUIRED',
      manager_action_state='NOT_REQUIRED',waiting_source_state='SOURCE_MATCHED',
      resolved_at_utc=p_now_utc,resolution_kind='SOURCE_MATCHED'
    where id=v_incident.id;
    update public.weekly_candidate_outreach_memberships set state='RESOLVED'
    where incident_id=v_incident.id and state in ('ACTIONABLE','ANSWERED');
    update public.weekly_manager_review_items set response_state='FILTERED_RESOLVED'
    where incident_id=v_incident.id and response_state='UNANSWERED';
    update public.office_action_notifications
    set operational_state='RESOLVED',resolved_at_utc=p_now_utc
    where issue_id=v_incident.id and operational_state='OPEN';
    insert into public.weekly_discrepancy_events(
      incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,
      idempotency_key
    ) values (
      v_incident.id,v_incident.episode_number,v_publication.id,null,
      'RESOLVED','SYSTEM',
      pg_catalog.jsonb_build_object(
        'resolution','SOURCE_MATCHED','origin','CANDIDATE_TIMESHEET_SUBMISSION'
      ),
      'SOURCE_MATCHED:'||v_incident.id::text||':'||v_publication.id::text
    ) on conflict (event_kind,idempotency_key) do nothing;
    v_resolved_count:=v_resolved_count+1;
  end loop;

  select pg_catalog.count(*)::integer into v_open_count
  from public.weekly_discrepancy_incidents incident
  join public.weekly_issue_comparison_revisions comparison
    on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  where incident.source_cycle_id=v_cycle.id
    and incident.candidate_id=v_generation.candidate_id
    and incident.client_id=v_membership.client_id
    and comparison.contract_id=v_membership.contract_id
    and work_event.work_date between v_membership.week_ending-6 and v_membership.week_ending
    and incident.state='OPEN';

  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome',case when v_open_count=0 then 'MATCHED' else 'ISSUES' end,
    'open_issue_count',v_open_count,'new_incidents',v_new_count,
    'changed_comparisons',v_changed_count,'unchanged_incidents',v_unchanged_count,
    'resolved_incidents',v_resolved_count
  );
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_CANDIDATE_COMPARISON_STALE' using errcode='40001';
end;
$function$;
alter function private.weekly_source_candidate_submission_compare_sync_v1(uuid,uuid,uuid,uuid,bytea,timestamptz) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_candidate_submission_compare_sync_v1(uuid,uuid,uuid,uuid,bytea,timestamptz) from public,anon,authenticated,service_role;

-- Reuse the native append-only audit owner; no second comparison/status store.
create or replace function private.weekly_source_publication_comparison_record_v1(
  p_publication_id uuid,p_timesheet_id uuid,p_state text,p_refusal_code text
) returns void language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_sheet public.timesheets%rowtype; v_publication public.weekly_source_projection_publications%rowtype;
  v_contract public.contracts%rowtype; v_hash bytea; v_key text; v_payload jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_state is null or p_state not in ('COMPARED','NOT_COMPARED')
    or (p_state='NOT_COMPARED') is distinct from (p_refusal_code is not null)
    or (p_refusal_code is not null and p_refusal_code !~ '^[A-Z][A-Z0-9_]{0,119}$') then
    raise exception 'WEEKLY_SOURCE_COMPARISON_AUDIT_INVALID' using errcode='22023'; end if;
  select * into strict v_publication from public.weekly_source_projection_publications where id=p_publication_id and state='CURRENT';
  perform private.weekly_source_query_current_publication_v1(v_publication.source_cycle_id,v_publication.id);
  -- Same native cycle mutex used by the comparator and publication writer.
  perform 1 from public.weekly_source_cycles where id=v_publication.source_cycle_id for update;
  select * into strict v_sheet from public.timesheets where timesheet_id=p_timesheet_id and is_current
    and revoked_at is null and archived_at_utc is null and sheet_scope='WEEKLY' and line_type='HOURS';
  select * into strict v_contract from public.contracts where id=v_sheet.contract_id;
  v_hash:=private.weekly_source_query_candidate_timesheet_hash_v1(v_sheet.timesheet_id);
  if v_hash is null then raise exception 'WEEKLY_SOURCE_COMPARISON_AUDIT_EVIDENCE_UNAVAILABLE' using errcode='55000'; end if;
  v_key:='PUBLICATION_COMPARISON:'||v_publication.id::text||':'||v_sheet.timesheet_id::text||':'||encode(v_hash,'hex')||':'||p_state;
  v_payload:=jsonb_build_object('idempotency_key',v_key,'state',p_state,'refusal_code',p_refusal_code,
    'projection_publication_id',v_publication.id,'source_cycle_id',v_publication.source_cycle_id,
    'upload_id',v_publication.upload_id,'candidate_id',v_contract.candidate_id,'client_id',v_contract.client_id,
    'contract_id',v_contract.id,'week_ending_date',v_sheet.week_ending_date,
    'timesheet_id',v_sheet.timesheet_id,'timesheet_revision',v_sheet.version,'timesheet_hash',encode(v_hash,'hex'));
  if exists(select 1 from public.audit_events audit where audit.object_type='timesheets'
    and audit.object_id_text=v_sheet.timesheet_id::text and audit.action='WEEKLY_SOURCE_PUBLICATION_COMPARISON'
    and audit.after_json->>'idempotency_key'=v_key and audit.event_sequence_is_authoritative) then return; end if;
  perform public._audit_insert('timesheets',v_sheet.timesheet_id::text,'WEEKLY_SOURCE_PUBLICATION_COMPARISON',
    null,v_payload,case p_state when 'COMPARED' then 'Hours checked against the current client file'
      else 'Hours not compared; check this Timesheet before continuing' end,null);
end;
$function$;
alter function private.weekly_source_publication_comparison_record_v1(uuid,uuid,text,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_publication_comparison_record_v1(uuid,uuid,text,text)
  from public,anon,authenticated,service_role;

-- Existing inputs retain identical hash domain and JSON. New unsigned materialiser adds its exact Contract Week witness only.
create or replace function private.weekly_source_query_comparison_fingerprint_v1(
  p_incident_id uuid,
  p_episode integer,
  p_work_event_id uuid,
  p_issue jsonb
) returns bytea
language sql
stable
security definer
set search_path to 'private','pg_catalog','pg_temp'
as $function$
  select private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_MATERIAL_COMPARISON_V1',
    pg_catalog.jsonb_build_object(
      'incident_id',p_incident_id,
      'episode_number',p_episode,
      'work_event_id',p_work_event_id,
      'candidate_timesheet_id',nullif(p_issue->>'candidate_timesheet_id','')::uuid,
      'candidate_timesheet_revision',nullif(p_issue->>'candidate_timesheet_revision','')::integer,
      'candidate_shift_fingerprint',pg_catalog.lower(nullif(p_issue->>'candidate_shift_fingerprint','')),
      'contract_id',nullif(p_issue->>'contract_id','')::uuid,
      'issue_family',pg_catalog.upper(pg_catalog.btrim(coalesce(p_issue->>'issue_family',''))),
      'source_presence',pg_catalog.upper(pg_catalog.btrim(coalesce(p_issue->>'source_presence',''))),
      'candidate_start_at_local',nullif(p_issue->>'candidate_start_at_local','')::timestamp,
      'candidate_end_at_local',nullif(p_issue->>'candidate_end_at_local','')::timestamp,
      'candidate_break_minutes',nullif(p_issue->>'candidate_break_minutes','')::integer,
      'system_start_at_local',nullif(p_issue->>'system_start_at_local','')::timestamp,
      'system_end_at_local',nullif(p_issue->>'system_end_at_local','')::timestamp,
      'system_break_minutes',nullif(p_issue->>'system_break_minutes','')::integer
    )||case when p_issue ? 'contract_week_id' then jsonb_build_object(
      'contract_week_id',nullif(p_issue->>'contract_week_id','')::uuid) else '{}'::jsonb end
  );
$function$;
alter function private.weekly_source_query_comparison_fingerprint_v1(uuid,integer,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_query_comparison_fingerprint_v1(uuid,integer,uuid,jsonb) from public,anon,authenticated,service_role;

-- Unsigned expected weeks use the existing incident/revision/event stores.
-- No candidate schedule, signature, lineage or money is fabricated.
create or replace function private.weekly_source_expected_week_unsigned_materialise_v1(p_publication_id uuid)
returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype; v_cycle public.weekly_source_cycles%rowtype;
  v_incident public.weekly_discrepancy_incidents%rowtype;
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_row record; v_week public.contract_weeks%rowtype; v_policy jsonb; v_issue jsonb;
  v_fingerprint bytea; v_revision integer; v_episode integer; v_count integer;
  v_issue_family text; v_presence text;
  v_new integer:=0; v_changed integer:=0; v_unchanged integer:=0; v_resolved integer:=0;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=p_publication_id and state='CURRENT' and authority_scope_kind='CYCLE';
  select * into strict v_cycle from public.weekly_source_cycles where id=v_publication.source_cycle_id for update;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication.id);
  select * into strict v_upload from public.weekly_source_uploads where id=v_publication.upload_id and source_cycle_id=v_cycle.id;
  if v_upload.confirmed_coverage_start_local_date is null or v_upload.confirmed_coverage_end_local_date is null then
    raise exception 'WEEKLY_SOURCE_PREFINAL_COVERAGE_INVALID' using errcode='55000'; end if;
  for v_row in
    select source.*,resolution.id as resolution_id,resolution.contract_id,resolution.candidate_id,resolution.client_id,
      resolution.work_event_id,work.first_source_group_id,contract.candidate_id as contract_candidate_id,
      contract.client_id as contract_client_id,work.candidate_id as event_candidate_id,work.client_id as event_client_id,
      work.work_date as event_work_date
    from public.weekly_source_upload_rows source
    join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source.id
      and resolution.generation=coalesce(v_publication.projection_generation,v_publication.authority_scope_version)
      and resolution.mapping_state='RESOLVED'
    join public.weekly_work_events work on work.id=resolution.work_event_id
    join public.contracts contract on contract.id=resolution.contract_id
    where source.upload_id=v_upload.id and source.work_date between
      v_upload.confirmed_coverage_start_local_date and v_upload.confirmed_coverage_end_local_date
      and source.row_finalisation_state in ('SOURCE_UNFINALISED','SOURCE_WORKED')
      and private.weekly_source_is_import_authoritative_v1(resolution.client_id,resolution.contract_id,source.work_date)
      and (private.weekly_source_checking_client_scope_v1(v_publication.id) is null
        or resolution.client_id=private.weekly_source_checking_client_scope_v1(v_publication.id))
    order by source.work_date,resolution.work_event_id,source.id
  loop
    if (v_row.candidate_id,v_row.client_id,v_row.work_date,v_cycle.source_group_id)
      is distinct from (v_row.event_candidate_id,v_row.event_client_id,v_row.event_work_date,v_row.first_source_group_id)
      or (v_row.candidate_id,v_row.client_id) is distinct from (v_row.contract_candidate_id,v_row.contract_client_id) then
      raise exception 'WEEKLY_SOURCE_EXPECTED_WEEK_SCOPE_INVALID' using errcode='55000'; end if;
    select count(*) into v_count from public.contract_weeks expected
      where expected.contract_id=v_row.contract_id and expected.additional_seq=0 and not coalesce(expected.is_adjustment,false)
        and expected.status in ('PLANNED','OPEN','SUBMITTED')
        and v_row.work_date between expected.week_ending_date-6 and expected.week_ending_date;
    if v_count=0 then continue; end if;
    if v_count<>1 then raise exception 'WEEKLY_SOURCE_EXPECTED_WEEK_AMBIGUOUS' using errcode='55000'; end if;
    select * into strict v_week from public.contract_weeks expected
      where expected.contract_id=v_row.contract_id and expected.additional_seq=0 and not coalesce(expected.is_adjustment,false)
        and expected.status in ('PLANNED','OPEN','SUBMITTED')
        and v_row.work_date between expected.week_ending_date-6 and expected.week_ending_date;
    if exists(select 1 from public.timesheets signed where signed.contract_id=v_row.contract_id
      and signed.week_ending_date=v_week.week_ending_date and signed.is_current and signed.revoked_at is null
      and signed.archived_at_utc is null and signed.sheet_scope='WEEKLY' and signed.line_type='HOURS'
      and signed.r2_nurse_key is not null and signed.img_sha256_nurse is not null) then continue; end if;
    if (select count(*) from public.weekly_source_row_resolutions resolution
      where resolution.upload_row_id in(select source.id from public.weekly_source_upload_rows source where source.upload_id=v_upload.id)
        and resolution.generation=coalesce(v_publication.projection_generation,v_publication.authority_scope_version)
        and resolution.mapping_state='RESOLVED' and resolution.work_event_id=v_row.work_event_id)<>1 then
      raise exception 'WEEKLY_SOURCE_EXPECTED_WEEK_EVENT_AMBIGUOUS' using errcode='55000'; end if;
    perform 1 from public.weekly_work_events where id=v_row.work_event_id for update;
    select * into v_incident from public.weekly_discrepancy_incidents
      where source_group_id=v_cycle.source_group_id and work_event_id=v_row.work_event_id and state='OPEN' for update;
    if found then
      select * into strict v_comparison from public.weekly_issue_comparison_revisions
        where id=v_incident.current_comparison_revision_id and incident_id=v_incident.id;
      if v_incident.source_cycle_id is distinct from v_cycle.id or v_comparison.contract_id is distinct from v_row.contract_id
        or v_incident.candidate_id is distinct from v_row.candidate_id or v_incident.client_id is distinct from v_row.client_id then
        raise exception 'WEEKLY_SOURCE_EXPECTED_WEEK_SCOPE_INVALID' using errcode='55000'; end if;
      if v_comparison.candidate_timesheet_id is not null then continue; end if;
    else v_comparison.id:=null; end if;
    v_issue_family:='HEALTHROSTER_NOT_FINALISED'; v_presence:='UNFINALISED';
    if v_row.row_finalisation_state='SOURCE_WORKED' then
      if v_incident.id is null then continue; end if;
      if v_incident.id is not null and v_comparison.issue_family='HEALTHROSTER_NOT_FINALISED'
        and (v_comparison.system_start_at_local,v_comparison.system_end_at_local,v_comparison.system_break_minutes)
          is not distinct from (v_row.start_at_local,v_row.end_at_local,v_row.break_minutes) then
        update public.weekly_discrepancy_incidents set state='RESOLVED',reconciliation_state='RECONCILED',
          candidate_action_state='NOT_REQUIRED',manager_action_state='NOT_REQUIRED',manager_potential_state='NOT_REQUIRED',
          waiting_source_state='SOURCE_MATCHED',resolved_at_utc=transaction_timestamp(),resolution_kind='SOURCE_MATCHED'
          where id=v_incident.id;
        perform private.weekly_source_incident_contact_retire_v1(v_incident.id);
        insert into public.weekly_discrepancy_events(incident_id,issue_episode,projection_publication_id,
          event_kind,actor_kind,bounded_payload_json,idempotency_key)
        values(v_incident.id,v_incident.episode_number,v_publication.id,'RESOLVED','SYSTEM',
          jsonb_build_object('resolution','SOURCE_MATCHED','origin','EXPECTED_CONTRACT_WEEK'),
          'SOURCE_MATCHED:'||v_incident.id::text||':'||v_publication.id::text)
        on conflict(event_kind,idempotency_key) do nothing;
        v_resolved:=v_resolved+1;
        continue;
      end if;
      -- The manager question changes; Candidate evidence remains absent.
      v_issue_family:='SOURCE_HOURS_DIFFER'; v_presence:='PRESENT';
    end if;
    v_policy:=private._weekly_source_effective_policy_v1(v_row.client_id,v_row.contract_id,v_row.work_date);
    v_issue:=jsonb_build_object('work_event_id',v_row.work_event_id,'contract_week_id',v_week.id,
      'candidate_timesheet_id',null,'candidate_timesheet_revision',null,'candidate_shift_fingerprint',null,
      'contract_id',v_row.contract_id,'issue_family',v_issue_family,'source_presence',v_presence,
      'candidate_start_at_local',null,'candidate_end_at_local',null,'candidate_break_minutes',null,
      'system_start_at_local',v_row.start_at_local,'system_end_at_local',v_row.end_at_local,'system_break_minutes',v_row.break_minutes);
    if v_incident.id is null then
      select coalesce(max(episode_number),0)+1 into v_episode from public.weekly_discrepancy_incidents
        where source_group_id=v_cycle.source_group_id and work_event_id=v_row.work_event_id;
      insert into public.weekly_discrepancy_incidents(source_group_id,work_event_id,episode_number,candidate_id,client_id,
        source_cycle_id,state,reconciliation_state,candidate_action_state,manager_potential_state,manager_action_state,waiting_source_state)
      values(v_cycle.source_group_id,v_row.work_event_id,v_episode,v_row.candidate_id,v_row.client_id,v_cycle.id,'OPEN','UNRESOLVED','NOT_REQUIRED',
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false) and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'AVAILABLE' else 'NOT_AVAILABLE' end,
        case when coalesce((v_policy->>'manager_queries_enabled')::boolean,false) and nullif(v_policy->>'manager_query_recipient','') is not null
          then 'NOT_SENT' else 'NOT_REQUIRED' end,'NOT_WAITING') returning * into v_incident;
      v_new:=v_new+1;
    end if;
    v_fingerprint:=private.weekly_source_query_comparison_fingerprint_v1(v_incident.id,v_incident.episode_number,v_row.work_event_id,v_issue);
    if v_comparison.id is not null and v_comparison.material_comparison_fingerprint=v_fingerprint then
      v_unchanged:=v_unchanged+1; continue; end if;
    select coalesce(max(revision_number),0)+1 into v_revision from public.weekly_issue_comparison_revisions where incident_id=v_incident.id;
    insert into public.weekly_issue_comparison_revisions(incident_id,revision_number,projection_publication_id,comparison_upload_id,
      source_row_id,source_work_event_link_id,contract_id,issue_family,source_presence,
      system_start_at_local,system_end_at_local,system_break_minutes,material_comparison_fingerprint)
    values(v_incident.id,v_revision,v_publication.id,v_upload.id,v_row.id,
      (select link.id from public.weekly_work_event_source_links link where link.upload_row_id=v_row.id
        and link.row_resolution_id=v_row.resolution_id and link.work_event_id=v_row.work_event_id),
      v_row.contract_id,v_issue_family,v_presence,v_row.start_at_local,v_row.end_at_local,v_row.break_minutes,v_fingerprint)
    returning * into v_comparison;
    update public.weekly_discrepancy_incidents set current_comparison_revision_id=v_comparison.id,candidate_action_state='NOT_REQUIRED',
      manager_action_state=case when manager_potential_state='AVAILABLE' then 'NOT_SENT' else 'NOT_REQUIRED' end,
      waiting_source_state='NOT_WAITING',reconciliation_state='UNRESOLVED' where id=v_incident.id;
    insert into public.weekly_discrepancy_events(incident_id,issue_episode,projection_publication_id,
      expected_comparison_fingerprint,event_kind,actor_kind,bounded_payload_json,idempotency_key)
    values(v_incident.id,v_incident.episode_number,v_publication.id,v_fingerprint,'SOURCE_RECHECKED','SYSTEM',
      jsonb_build_object('issue_family',v_issue_family,'comparison_revision_id',v_comparison.id,
        'contract_week_id',v_week.id,'origin','EXPECTED_CONTRACT_WEEK'),
      'SOURCE_RECHECKED:'||v_incident.id::text||':'||encode(v_fingerprint,'hex'))
    on conflict(event_kind,idempotency_key) do nothing;
    if v_revision>1 then v_changed:=v_changed+1; end if;
  end loop;
  return jsonb_build_object('ok',true,'new_incidents',v_new,'changed_comparisons',v_changed,
    'unchanged_incidents',v_unchanged,'resolved_incidents',v_resolved);
end;
$function$;
alter function private.weekly_source_expected_week_unsigned_materialise_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_expected_week_unsigned_materialise_v1(uuid) from public,anon,authenticated,service_role;

-- Complete current recheck owner; native signed comparison plus unsigned expected-week materialiser.
create or replace function private.weekly_source_candidate_prefinal_publish_recheck_v1(
  p_actor_user_id uuid,
  p_projection_publication_id uuid
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_profile_code text;
  v_profile_id uuid;
  v_upload public.weekly_source_uploads%rowtype;
  v_signed record;
  v_result jsonb;
  v_checked integer:=0;
  v_new integer:=0;
  v_changed integer:=0;
  v_resolved integer:=0;
  v_restart_keys text[]:='{}'::text[];
  v_restart_key text;
  v_not_compared integer:=0; v_refusal text; v_unsigned jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=p_projection_publication_id and state='CURRENT';
  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_publication.source_cycle_id;
  select profile.profile_code,profile.id into strict v_profile_code,v_profile_id
  from public.weekly_source_uploads upload
  join public.weekly_source_format_profiles profile
    on profile.id=upload.source_format_profile_id
  where upload.id=v_publication.upload_id;
  if (v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' and not exists(select 1 from public.weekly_source_groups g
       where g.id=v_cycle.source_group_id and g.source_family='ROSTER'))
     or v_publication.authority_scope_kind<>'CYCLE'
     or v_cycle.current_projection_publication_id is distinct from v_publication.id then
    raise exception 'WEEKLY_SOURCE_PREFINAL_RECHECK_SCOPE_INVALID' using errcode='55000';
  end if;
  select * into strict v_upload from public.weekly_source_uploads
  where id=v_publication.upload_id and source_cycle_id=v_cycle.id;
  if v_upload.confirmed_coverage_start_local_date is null
     or v_upload.confirmed_coverage_end_local_date is null then
    raise exception 'WEEKLY_SOURCE_PREFINAL_COVERAGE_INVALID' using errcode='55000';
  end if;
  perform private.weekly_source_office_authority_v1(
    p_actor_user_id,'RECHECK_SOURCE',v_cycle.source_group_id,null,
    v_cycle.finalisation_week_ending
  );

  -- Recheck signed weeks only for days in this upload's confirmed export
  -- period. A week may straddle that period; compare_sync applies the same
  -- day boundary to candidate rows and incident resolution.
  for v_signed in
    select distinct sheet.timesheet_id,contract.candidate_id,contract.client_id,
      contract.id as contract_id
    from public.timesheets sheet
    join public.contracts contract
      on contract.id=sheet.contract_id
    where sheet.is_current and sheet.revoked_at is null
      and sheet.archived_at_utc is null and sheet.sheet_scope='WEEKLY'
      and sheet.line_type='HOURS' and sheet.authorised_at_server is null
      and sheet.r2_nurse_key is not null and sheet.img_sha256_nurse is not null
      and (private.weekly_source_checking_client_scope_v1(v_publication.id) is null
        or contract.client_id=private.weekly_source_checking_client_scope_v1(v_publication.id))
      and (v_profile_code='NHSP_PREFINAL_RELEASED_V1' or private.weekly_source_is_import_authoritative_v1(
        contract.client_id,contract.id,sheet.week_ending_date))
      and sheet.week_ending_date>=v_upload.confirmed_coverage_start_local_date
      and sheet.week_ending_date-6<=v_upload.confirmed_coverage_end_local_date
      and (exists (
        select 1
        from public.weekly_source_uploads historical_upload
        join public.weekly_source_upload_rows source_row
          on source_row.upload_id=historical_upload.id
        join public.weekly_source_row_resolutions resolution
          on resolution.upload_row_id=source_row.id
         and resolution.mapping_state='RESOLVED'
        where historical_upload.source_cycle_id=v_cycle.id
          and historical_upload.source_format_profile_id=v_profile_id
          and source_row.work_date between sheet.week_ending_date-6
            and sheet.week_ending_date
          and source_row.work_date between
            v_upload.confirmed_coverage_start_local_date
            and v_upload.confirmed_coverage_end_local_date
          and resolution.candidate_id=contract.candidate_id
          and resolution.client_id=contract.client_id
          and resolution.contract_id=contract.id
      ) or exists (
        select 1
        from pg_catalog.jsonb_array_elements(
          private.weekly_source_candidate_app_schedule_v1(
            sheet.actual_schedule_json,sheet.additional_units_per_day
          )
        ) candidate_shift
        where (candidate_shift.value->>'date')::date between
          v_upload.confirmed_coverage_start_local_date
          and v_upload.confirmed_coverage_end_local_date
          and private._weekly_source_effective_policy_v1(
            contract.client_id,contract.id,(candidate_shift.value->>'date')::date
          )->>'source_group_id'=v_cycle.source_group_id::text
      ))
    order by sheet.timesheet_id
  loop
    -- Each sheet is one native subtransaction. A refusal rolls back only its
    -- comparison effects; the native append-only audit records NOT_COMPARED.
    begin
      v_result:=private.weekly_source_candidate_submission_compare_sync_v1(
        null,v_publication.id,null,v_signed.timesheet_id,
        private.weekly_source_query_candidate_timesheet_hash_v1(v_signed.timesheet_id));
      perform private.weekly_source_publication_comparison_record_v1(v_publication.id,v_signed.timesheet_id,'COMPARED',null);
    exception when others then
      v_refusal:=coalesce(substring(sqlerrm from '^[A-Z][A-Z0-9_]{0,119}$'),'WEEKLY_SOURCE_COMPARISON_REFUSED');
      perform private.weekly_source_publication_comparison_record_v1(v_publication.id,v_signed.timesheet_id,'NOT_COMPARED',v_refusal);
      v_not_compared:=v_not_compared+1;
      continue;
    end;
    v_checked:=v_checked+1;
    v_new:=v_new+(v_result->>'new_incidents')::integer;
    v_changed:=v_changed+(v_result->>'changed_comparisons')::integer;
    v_resolved:=v_resolved+(v_result->>'resolved_incidents')::integer;
    if (v_result->>'new_incidents')::integer+(v_result->>'changed_comparisons')::integer>0 then
      v_restart_keys:=pg_catalog.array_append(
        v_restart_keys,v_signed.candidate_id::text||':'||v_signed.client_id::text
      );
    end if;
  end loop;
  for v_restart_key in
    select distinct key_value collate "C"
    from pg_catalog.unnest(v_restart_keys) key_value
    order by key_value
  loop
    perform private.weekly_source_query_restart_activated_cohort_v1(
      v_cycle.id,pg_catalog.split_part(v_restart_key,':',1)::uuid,
      pg_catalog.split_part(v_restart_key,':',2)::uuid,v_publication.id
    );
  end loop;
  if v_profile_code<>'NHSP_PREFINAL_RELEASED_V1' then
    v_unsigned:=private.weekly_source_expected_week_unsigned_materialise_v1(v_publication.id);
    v_new:=v_new+(v_unsigned->>'new_incidents')::integer;
    v_changed:=v_changed+(v_unsigned->>'changed_comparisons')::integer;
    v_resolved:=v_resolved+(v_unsigned->>'resolved_incidents')::integer;
    perform private.weekly_source_not_finalised_dispatch_v1(v_publication.id);
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'not_compared',v_not_compared,'signed_weeks_checked',v_checked,'new_incidents',v_new,
    'changed_comparisons',v_changed,'resolved_incidents',v_resolved
  );
end;
$function$;
alter function private.weekly_source_candidate_prefinal_publish_recheck_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_candidate_prefinal_publish_recheck_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- A later unsigned hours-change belongs to the existing (a) episode only
-- when its first native comparison proves the expected-week materialiser kind.
create or replace function private.weekly_source_expected_week_question_v1(p_incident_id uuid)
returns boolean language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select exists(select 1 from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions original on original.incident_id=incident.id and original.revision_number=1
    join public.weekly_issue_comparison_revisions current_question on current_question.id=incident.current_comparison_revision_id
    join public.weekly_work_events work on work.id=incident.work_event_id
    where incident.id=p_incident_id and original.issue_family='HEALTHROSTER_NOT_FINALISED'
      and original.source_presence='UNFINALISED' and original.candidate_timesheet_id is null
      and current_question.candidate_timesheet_id is null and current_question.issue_family in ('HEALTHROSTER_NOT_FINALISED','SOURCE_HOURS_DIFFER')
      and original.contract_id=current_question.contract_id
      and exists(select 1 from public.weekly_discrepancy_events original_event
        where original_event.incident_id=incident.id and original_event.event_kind='SOURCE_RECHECKED'
          and original_event.expected_comparison_fingerprint=original.material_comparison_fingerprint
          and original_event.bounded_payload_json->>'origin'='EXPECTED_CONTRACT_WEEK'
          and original_event.bounded_payload_json->>'comparison_revision_id'=original.id::text)
      and private.weekly_source_is_import_authoritative_v1(incident.client_id,current_question.contract_id,work.work_date));
$function$;
alter function private.weekly_source_expected_week_question_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_expected_week_question_v1(uuid) from public,anon,authenticated,service_role;

-- Complete native scope predicate; exact (a) revision does not broaden a cohort.
create or replace function private.weekly_source_manager_due_event_covers_v1(p_event_id uuid,p_incident_id uuid)
returns boolean language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select exists(
    select 1 from public.weekly_manager_cohort_due_events event
    join public.weekly_candidate_cohorts cohort on cohort.id=event.candidate_cohort_id
    join public.weekly_discrepancy_incidents incident
      on incident.id=p_incident_id and incident.candidate_id=cohort.candidate_id
      and incident.source_cycle_id=cohort.source_cycle_id
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    left join public.weekly_timesheet_submission_request_memberships requested on requested.id=event.requested_week_membership_id
    where event.id=p_event_id and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and (case when event.not_finalised_comparison_revision_id is not null then
        event.not_finalised_comparison_revision_id=comparison.id
        and (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' or private.weekly_source_expected_week_question_v1(incident.id))
        and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work_event.work_date)
        else not ((comparison.issue_family='HEALTHROSTER_NOT_FINALISED' or private.weekly_source_expected_week_question_v1(incident.id))
          and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work_event.work_date)) end)
      and (event.requested_week_membership_id is null
      or (requested.state='SUBMITTED_WITH_ISSUES' and requested.client_id=incident.client_id
        and requested.contract_id=comparison.contract_id
        and work_event.work_date>requested.week_ending-7 and work_event.work_date<=requested.week_ending
        and incident.candidate_action_state='NOT_REQUIRED'))
  );
$function$;
alter function private.weekly_source_manager_due_event_covers_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_manager_due_event_covers_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Existing accepted batch stays the authority for unchanged business facts.
create or replace function private.weekly_source_query_manager_row_owned_v1(
  p_recipient_route_id uuid,
  p_incident_id uuid,
  p_incident_episode integer
) returns boolean
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  select case
    when p_recipient_route_id is null or p_incident_id is null
      or p_incident_episode is null
    then true
    else exists(
      select 1
      from public.weekly_manager_review_items owning_item
      join public.weekly_manager_review_batches owning_batch
        on owning_batch.id=owning_item.review_batch_id
      join public.weekly_manager_recipient_generations owning_generation
        on owning_generation.id=owning_batch.recipient_generation_id
      join public.weekly_message_renders owning_render
        on owning_render.id=owning_batch.message_render_id
      join public.weekly_discrepancy_incidents current_incident on current_incident.id=owning_item.incident_id
      join public.weekly_issue_comparison_revisions current_comparison on current_comparison.id=current_incident.current_comparison_revision_id
      join public.weekly_issue_comparison_revisions sent_comparison on sent_comparison.id=owning_item.sent_comparison_revision_id
      join public.weekly_work_events actual_work on actual_work.id=current_incident.work_event_id
      where owning_item.incident_id=p_incident_id
        and (not private.weekly_source_is_import_authoritative_v1(current_incident.client_id,current_comparison.contract_id,actual_work.work_date)
          or (current_comparison.contract_id,current_comparison.issue_family,current_comparison.source_presence,
            current_comparison.candidate_start_at_local,current_comparison.candidate_end_at_local,current_comparison.candidate_break_minutes,
            current_comparison.system_start_at_local,current_comparison.system_end_at_local,current_comparison.system_break_minutes)
          is not distinct from (sent_comparison.contract_id,sent_comparison.issue_family,sent_comparison.source_presence,
            sent_comparison.candidate_start_at_local,sent_comparison.candidate_end_at_local,sent_comparison.candidate_break_minutes,
            sent_comparison.system_start_at_local,sent_comparison.system_end_at_local,sent_comparison.system_break_minutes))
        and owning_item.incident_episode=p_incident_episode
        and owning_generation.recipient_route_id=p_recipient_route_id
        and owning_batch.state in ('ACTIVE','COMPLETE')
        and owning_render.state in ('SUBMISSION_STARTED','ACCEPTED','AMBIGUOUS')
        and owning_item.response_state in ('UNANSWERED','ANSWERED')
    )
  end;
$function$;
alter function private.weekly_source_query_manager_row_owned_v1(uuid,uuid,integer) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_query_manager_row_owned_v1(uuid,uuid,integer) from public,anon,authenticated,service_role;

-- Complete native generation owner; only unsigned import-authoritative (a) joins the existing secure manager path.
create or replace function private.weekly_source_query_manager_generation_v1(
  p_recipient_route_id uuid,
  p_trigger_kind text,
  p_started_at_utc timestamptz,
  p_force_new boolean default false
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_route public.weekly_manager_recipient_routes%rowtype;
  v_old public.weekly_manager_recipient_generations%rowtype;
  v_new public.weekly_manager_recipient_generations%rowtype;
  v_membership jsonb;
  v_hash bytea;
  v_generation integer;
  v_ordinal integer:=0;
  v_row record;
  v_candidate_generation public.weekly_candidate_outreach_generations%rowtype;
  v_settings public.weekly_source_global_settings%rowtype;
  v_event_kind text;
  v_due timestamptz;
  v_trigger_hash bytea;
begin
  if p_trigger_kind not in (
    'OFFICE_DIRECT','EARLY_ALL','T6_RESPONDED','T12_REMAINDER','NEW_INCIDENT','MANUAL_RESEND'
  ) or p_started_at_utc is null then
    raise exception 'WEEKLY_SOURCE_MANAGER_TRIGGER_INVALID' using errcode='22023';
  end if;
  select * into strict v_route
  from public.weekly_manager_recipient_routes
  where id=p_recipient_route_id for update;
  select * into v_old
  from public.weekly_manager_recipient_generations
  where id=v_route.current_generation_id and state='ACTIVE'
  for update;
  v_membership:=coalesce((
    select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'activation_id',activation.id,
        'candidate_cohort_id',cohort.id,
        'candidate_generation_id',cohort.current_generation_id,
        'incident_id',incident.id,
        'comparison_revision_id',incident.current_comparison_revision_id
      ) order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",
                 client.id::text collate "C",
                 private.weekly_source_query_ascii_fold_v1(coalesce(
                   nullif(candidate.display_name,''),
                   pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)
                 )) collate "C",
                 candidate.id::text collate "C",work_event.work_date,
                 comparison.system_start_at_local,incident.id
    )
    from public.weekly_candidate_cohorts cohort
    join public.weekly_route_activations activation
      on activation.source_cycle_id=cohort.source_cycle_id
     and activation.candidate_id=cohort.candidate_id
     and activation.client_id=cohort.client_id
     and activation.audience_route='MANAGER'
     and activation.route_mode in ('CANDIDATE_FIRST','MANAGER_DIRECT')
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
     and incident.state='OPEN'
     and incident.manager_potential_state='AVAILABLE'
      -- 04A section 6: "Resolved and manager-answered/waiting-source items are
      -- not reintroduced", and section 1: an item "already answered by the
      -- manager but waiting for a later source remains visible to Office and is
      -- never included again".  A genuinely new EPISODE of the same incident is
      -- different work, and the recheck owner already resets manager_action_state
      -- when it raises the episode; nothing else may resurrect an answer.
      and incident.manager_action_state in ('NOT_SENT','DUE','SENT')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and (comparison.candidate_timesheet_id is not null
       or private.weekly_source_expected_week_question_v1(incident.id)
       or (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' and private.weekly_source_is_import_authoritative_v1(
         incident.client_id,comparison.contract_id,(select work.work_date from public.weekly_work_events work where work.id=incident.work_event_id))))
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    join public.clients client on client.id=incident.client_id
    join public.candidates candidate on candidate.id=incident.candidate_id
    where cohort.source_cycle_id=v_route.source_cycle_id
      and cohort.manager_recipient_route_key=v_route.normalised_recipient_hash
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
  ),'[]'::jsonb);
  if pg_catalog.jsonb_array_length(v_membership)=0 then
    return pg_catalog.jsonb_build_object('ok',true,'status','NO_MANAGER_ACTIONABLE_INCIDENTS');
  end if;
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_MANAGER_MEMBERSHIP_V1',v_membership);
  if v_old.id is not null and v_old.membership_hash=v_hash and not p_force_new then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','UNCHANGED','recipient_generation_id',v_old.id,
      'recipient_route_id',v_route.id,'membership_hash',pg_catalog.encode(v_hash,'hex')
    );
  end if;
  if v_old.id is not null then
    update public.weekly_manager_recipient_routes set current_generation_id=null where id=v_route.id;
    update public.weekly_manager_recipient_generations
    set state='SUPERSEDED',superseded_at_utc=pg_catalog.transaction_timestamp()
    where id=v_old.id;
    -- 04A section 8: "A later cohort merely becoming due is not a revocation
    -- event for an earlier accepted batch", and section 1: a later generation
    -- "cannot broaden, alter, supersede or revoke an already accepted earlier
    -- batch merely by becoming due".  The only express revocation the pack names
    -- is correcting a final source.  So an ACCEPTED batch and its live secure
    -- link survive this rotation untouched, and section 8's promise -- the
    -- manager "may answer some items, close the page and return later" -- keeps
    -- holding.
    --
    -- A batch whose render never reached provider submission (section 9) was
    -- never accepted: nothing was sent, its command and intent are retired just
    -- below, and the delivery start guard would refuse it anyway.  That batch is
    -- revoked here so its rows return to the unsent pool rather than being
    -- silently owned by an email nobody received.
    update public.weekly_manager_review_batches batch
    set state='REVOKED'
    from public.weekly_message_renders render
    where render.id=batch.message_render_id
      and batch.recipient_generation_id=v_old.id and batch.state='ACTIVE'
      and render.state not in ('SUBMISSION_STARTED','ACCEPTED','AMBIGUOUS');
    update public.weekly_manager_route_receipts receipt
    set state='REVOKED',revoked_at_utc=pg_catalog.transaction_timestamp()
    from public.weekly_manager_review_batches batch
    where batch.id=receipt.review_batch_id
      and receipt.recipient_generation_id=v_old.id and receipt.state='ACTIVE'
      and batch.state='REVOKED';
    update public.weekly_manager_review_items item
    set response_state='OBSOLETE'
    from public.weekly_manager_review_batches batch
    where batch.id=item.review_batch_id
      and batch.recipient_generation_id=v_old.id and batch.state='REVOKED'
      and item.response_state='UNANSWERED';
    update public.weekly_manager_cohort_due_events
    set state='RETIRED' where recipient_generation_id=v_old.id and state='PENDING';
    update public.weekly_message_intents
    set state='RETIRED'
    where recipient_generation_id=v_old.id and state in ('DUE','RENDERED');
    update public.weekly_message_dispatch_commands command
    set state='RETIRED'
    from public.weekly_message_intents intent
    where command.message_intent_id=intent.id
      and intent.recipient_generation_id=v_old.id
      and command.state in ('READY','LEASED');
    update public.weekly_message_renders render
    set state='STALE'
    from public.weekly_message_intents intent
    where render.message_intent_id=intent.id and intent.recipient_generation_id=v_old.id
      and render.state='CURRENT';
  end if;
  select coalesce(pg_catalog.max(generation_number),0)+1 into v_generation
  from public.weekly_manager_recipient_generations where recipient_route_id=v_route.id;
  insert into public.weekly_manager_recipient_generations(
    recipient_route_id,generation_number,trigger_kind,state,membership_hash
  ) values (v_route.id,v_generation,p_trigger_kind,'ACTIVE',v_hash)
  returning * into v_new;
  for v_row in
    select
      activation.id as activation_id,cohort.id as cohort_id,
      cohort.current_generation_id as candidate_generation_id,
      incident.id as incident_id,incident.current_comparison_revision_id
    from public.weekly_candidate_cohorts cohort
    join public.weekly_route_activations activation
      on activation.source_cycle_id=cohort.source_cycle_id
     and activation.candidate_id=cohort.candidate_id
     and activation.client_id=cohort.client_id
     and activation.audience_route='MANAGER'
     and activation.route_mode in ('CANDIDATE_FIRST','MANAGER_DIRECT')
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
      and incident.state='OPEN' and incident.manager_potential_state='AVAILABLE'
      -- 04A section 6: "Resolved and manager-answered/waiting-source items are
      -- not reintroduced", and section 1: an item "already answered by the
      -- manager but waiting for a later source remains visible to Office and is
      -- never included again".  A genuinely new EPISODE of the same incident is
      -- different work, and the recheck owner already resets manager_action_state
      -- when it raises the episode; nothing else may resurrect an answer.
      and incident.manager_action_state in ('NOT_SENT','DUE','SENT')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and (comparison.candidate_timesheet_id is not null
       or private.weekly_source_expected_week_question_v1(incident.id)
       or (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' and private.weekly_source_is_import_authoritative_v1(
         incident.client_id,comparison.contract_id,(select work.work_date from public.weekly_work_events work where work.id=incident.work_event_id))))
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    join public.clients client on client.id=incident.client_id
    join public.candidates candidate on candidate.id=incident.candidate_id
    where cohort.source_cycle_id=v_route.source_cycle_id
      and cohort.manager_recipient_route_key=v_route.normalised_recipient_hash
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
    order by private.weekly_source_query_ascii_fold_v1(client.name) collate "C",
             client.id::text collate "C",
             private.weekly_source_query_ascii_fold_v1(coalesce(
               nullif(candidate.display_name,''),
               pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)
             )) collate "C",
             candidate.id::text collate "C",work_event.work_date,
             comparison.system_start_at_local,incident.id
  loop
    -- A due-but-unsent row returns to the unsent pool, because the intent,
    -- command and render that made it due are retired above and this generation
    -- must be able to drive it again.  A SENT row stays SENT and a RESPONDED row
    -- keeps its answer: 04A section 1 forbids a later generation from altering
    -- an already accepted batch, and section 6 forbids reintroducing a
    -- manager-answered or waiting-source item.
    if p_trigger_kind='NEW_INCIDENT' then
      update public.weekly_discrepancy_incidents
      set manager_action_state='NOT_SENT',waiting_source_state='NOT_WAITING',
          reconciliation_state='UNRESOLVED'
      where id=v_row.incident_id
        and manager_action_state='DUE'
        and not private.weekly_source_query_manager_row_owned_v1(
          v_route.id,id,episode_number
        );
    end if;
    v_ordinal:=v_ordinal+1;
    insert into public.weekly_manager_recipient_memberships(
      recipient_generation_id,route_activation_id,candidate_outreach_generation_id,
      candidate_cohort_id,incident_id,comparison_revision_id,membership_role,ordinal
    ) values (
      v_new.id,v_row.activation_id,v_row.candidate_generation_id,v_row.cohort_id,
      v_row.incident_id,v_row.current_comparison_revision_id,'MANAGER_ACTIONABLE',v_ordinal
    );
  end loop;
  update public.weekly_manager_recipient_routes
  set current_generation_id=v_new.id where id=v_route.id;

  select * into strict v_settings from public.weekly_source_global_settings where singleton;
  for v_row in
    select distinct membership.candidate_cohort_id,activation.route_mode
    from public.weekly_manager_recipient_memberships membership
    join public.weekly_route_activations activation on activation.id=membership.route_activation_id
    where membership.recipient_generation_id=v_new.id
    order by membership.candidate_cohort_id
  loop
    v_candidate_generation.id:=null;
    v_candidate_generation.started_at_utc:=null;
    v_candidate_generation.deadline_at_utc:=null;
    if v_row.route_mode='MANAGER_DIRECT' then
      v_event_kind:='EARLY_ALL';
      v_due:=p_started_at_utc;
    else
      select * into v_candidate_generation
      from public.weekly_candidate_outreach_generations
      where id=(select current_generation_id from public.weekly_candidate_cohorts where id=v_row.candidate_cohort_id);
      if not found then
        continue;
      end if;
      v_event_kind:='T6_RESPONDED';
      v_due:=v_candidate_generation.started_at_utc+v_settings.manager_partial_digest_after;
    end if;
    v_trigger_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_MANAGER_COHORT_DUE_V1',
      pg_catalog.jsonb_build_object(
        'recipient_generation_id',v_new.id,'candidate_cohort_id',v_row.candidate_cohort_id,
        'event_kind',v_event_kind,'due_at_utc',v_due
      )
    );
    insert into public.weekly_manager_cohort_due_events(
      recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
      due_at_utc,state,trigger_hash
    ) values (
      v_new.id,v_row.candidate_cohort_id,v_event_kind,
      coalesce(v_candidate_generation.started_at_utc,p_started_at_utc),v_due,'PENDING',v_trigger_hash
    ) on conflict (recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    if v_row.route_mode='CANDIDATE_FIRST' then
      v_event_kind:='T12_REMAINDER';
      v_due:=v_candidate_generation.deadline_at_utc;
      v_trigger_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_MANAGER_COHORT_DUE_V1',
        pg_catalog.jsonb_build_object(
          'recipient_generation_id',v_new.id,'candidate_cohort_id',v_row.candidate_cohort_id,
          'event_kind',v_event_kind,'due_at_utc',v_due
        )
      );
      insert into public.weekly_manager_cohort_due_events(
        recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
        due_at_utc,state,trigger_hash
      ) values (
        v_new.id,v_row.candidate_cohort_id,v_event_kind,
        v_candidate_generation.started_at_utc,v_due,'PENDING',v_trigger_hash
      ) on conflict (recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    end if;
  end loop;
  -- A requested signed week is a bounded exception, not a persistent route
  -- override. Recreate its exact due scope on generation rotation without
  -- changing its original completion time or touching Office choices.
  insert into public.weekly_manager_cohort_due_events(
    recipient_generation_id,candidate_cohort_id,event_kind,cohort_started_at_utc,
    due_at_utc,state,trigger_hash,requested_week_membership_id
  )
  select distinct v_new.id,membership.candidate_cohort_id,'EARLY_ALL',requested.completed_at_utc,
    requested.completed_at_utc,'PENDING',private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_REQUESTED_WEEK_MANAGER_DUE_V1',pg_catalog.jsonb_build_object(
        'recipient_generation_id',v_new.id,'requested_week_membership_id',requested.id)),requested.id
  from public.weekly_manager_recipient_memberships membership
  join public.weekly_discrepancy_incidents incident on incident.id=membership.incident_id
  join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
  join public.weekly_work_events work_event on work_event.id=incident.work_event_id
  join public.weekly_timesheet_submission_requests request
    on request.source_cycle_id=incident.source_cycle_id and request.candidate_id=incident.candidate_id
  join public.weekly_timesheet_submission_request_memberships requested
    on requested.submission_request_id=request.id and requested.client_id=incident.client_id
    and requested.contract_id=comparison.contract_id and work_event.work_date>requested.week_ending-7
    and work_event.work_date<=requested.week_ending and requested.state='SUBMITTED_WITH_ISSUES'
  where membership.recipient_generation_id=v_new.id and incident.state='OPEN'
    and incident.candidate_action_state='NOT_REQUIRED'
    and not private.weekly_source_query_manager_row_owned_v1(v_route.id,incident.id,incident.episode_number)
  on conflict(recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','CREATED','recipient_route_id',v_route.id,
    'recipient_generation_id',v_new.id,
    'membership_hash',pg_catalog.encode(v_new.membership_hash,'hex')
  );
end;
$function$;
alter function private.weekly_source_query_manager_generation_v1(uuid,text,timestamptz,boolean) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_query_manager_generation_v1(uuid,text,timestamptz,boolean) from public,anon,authenticated,service_role;

-- Publication-time manager-only dispatch on the existing secure QD queue.
-- Deferred questions create audit evidence only; no future-due mail is staged.
create or replace function private.weekly_source_not_finalised_dispatch_v1(p_publication_id uuid)
returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_cycle public.weekly_source_cycles%rowtype; v_row record; v_context jsonb; v_generation jsonb;
  v_week date; v_count integer; v_monday timestamptz; v_key text; v_trigger bytea;
  v_route uuid; v_generation_id uuid; v_due_id uuid; v_intent uuid;
  v_deferred integer:=0; v_queued integer:=0; v_no_route integer:=0;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=p_publication_id and state='CURRENT' and authority_scope_kind='CYCLE' and correction_session_id is null;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_publication.source_cycle_id for update;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication.id);
  if v_publication.published_at_utc is null or not isfinite(v_publication.published_at_utc) then
    raise exception 'WEEKLY_SOURCE_NOT_FINALISED_PUBLICATION_CLOCK_INVALID' using errcode='55000'; end if;
  for v_row in
    select incident.*,comparison.id as comparison_id,comparison.contract_id,comparison.candidate_timesheet_id,
      comparison.material_comparison_fingerprint,work.work_date,sheet.week_ending_date as signed_week_ending
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
      and (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' or private.weekly_source_expected_week_question_v1(incident.id))
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=incident.source_group_id
    left join public.timesheets sheet on sheet.timesheet_id=comparison.candidate_timesheet_id
      and sheet.contract_id=comparison.contract_id and work.work_date between sheet.week_ending_date-6 and sheet.week_ending_date
    where incident.source_cycle_id=v_cycle.id and incident.state='OPEN'
      and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work.work_date)
      and (private.weekly_source_checking_client_scope_v1(v_publication.id) is null
        or incident.client_id=private.weekly_source_checking_client_scope_v1(v_publication.id))
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
    order by incident.id for update of incident
  loop
    update public.weekly_discrepancy_incidents set candidate_action_state='NOT_REQUIRED' where id=v_row.id;
    v_week:=v_row.signed_week_ending;
    if v_row.candidate_timesheet_id is not null and v_week is null then
      raise exception 'WEEKLY_SOURCE_NOT_FINALISED_WEEK_UNAVAILABLE' using errcode='55000'; end if;
    if v_week is null then
      select count(*),min(expected.week_ending_date) into v_count,v_week from public.contract_weeks expected
        where expected.contract_id=v_row.contract_id and expected.additional_seq=0 and not coalesce(expected.is_adjustment,false)
          and expected.status in ('PLANNED','OPEN','SUBMITTED')
          and v_row.work_date between expected.week_ending_date-6 and expected.week_ending_date;
      if v_count<>1 then raise exception 'WEEKLY_SOURCE_NOT_FINALISED_WEEK_UNAVAILABLE' using errcode='55000'; end if;
    end if;
    v_monday:=((v_week+(8-extract(isodow from v_week)::integer))::timestamp at time zone 'Europe/London');
    v_key:='NOT_FINALISED_DISPATCH:'||v_row.id::text||':'||v_row.comparison_id::text;
    if v_publication.published_at_utc<v_monday then
      if not exists(select 1 from public.audit_events audit where audit.action='WEEKLY_SOURCE_NOT_FINALISED_DISPATCH_DEFERRED'
        and audit.object_type='weekly_discrepancy_incident' and audit.object_id_text=v_row.id::text
        and audit.after_json->>'idempotency_key'=v_key and audit.event_sequence_is_authoritative) then
        perform public._audit_insert('weekly_discrepancy_incident',v_row.id::text,'WEEKLY_SOURCE_NOT_FINALISED_DISPATCH_DEFERRED',
          null,jsonb_build_object('idempotency_key',v_key,'comparison_revision_id',v_row.comparison_id,
            'projection_publication_id',v_publication.id,'week_ending_date',v_week,'first_monday_at_utc',v_monday),
          'Manager question waits for the first checking file on or after Monday',null);
      end if;
      v_deferred:=v_deferred+1; continue;
    end if;
    v_context:=private.weekly_source_query_cohort_ensure_v1(v_cycle.id,v_row.candidate_id,v_row.client_id,v_row.contract_id,v_row.work_date);
    if not coalesce((v_context->>'manager_queries_enabled')::boolean,false) or nullif(v_context->>'manager_route_id','') is null then
      v_no_route:=v_no_route+1; continue; end if;
    v_route:=(v_context->>'manager_route_id')::uuid;
    if private.weekly_source_query_manager_row_owned_v1(v_route,v_row.id,v_row.episode_number) then continue; end if;
    if exists(select 1 from public.weekly_route_activations activation where activation.source_cycle_id=v_cycle.id
      and activation.candidate_id=v_row.candidate_id and activation.client_id=v_row.client_id
      and activation.audience_route='MANAGER' and activation.route_mode in ('DISABLED','MANUAL_ONLY')) then
      v_no_route:=v_no_route+1; continue; end if;
    insert into public.weekly_route_activations(source_cycle_id,candidate_id,client_id,audience_route,route_mode,activated_at_utc,updated_at_utc)
    values(v_cycle.id,v_row.candidate_id,v_row.client_id,'MANAGER','CANDIDATE_FIRST',transaction_timestamp(),transaction_timestamp())
    on conflict(source_cycle_id,candidate_id,client_id,audience_route) do nothing;
    v_generation:=private.weekly_source_query_manager_generation_v1(v_route,'EARLY_ALL',v_publication.published_at_utc,false);
    v_generation_id:=nullif(v_generation->>'recipient_generation_id','')::uuid;
    if v_generation_id is null then raise exception 'WEEKLY_SOURCE_NOT_FINALISED_GENERATION_UNAVAILABLE' using errcode='55000'; end if;
    v_trigger:=private.weekly_source_sha256_jsonb_v1('WEEKLY_NOT_FINALISED_MANAGER_DUE_V1',
      jsonb_build_object('incident_id',v_row.id,'comparison_revision_id',v_row.comparison_id,
        'week_ending_date',v_week,'first_monday_at_utc',v_monday));
    insert into public.weekly_manager_cohort_due_events(recipient_generation_id,candidate_cohort_id,event_kind,
      cohort_started_at_utc,due_at_utc,state,trigger_hash,not_finalised_comparison_revision_id)
    values(v_generation_id,(v_context->>'cohort_id')::uuid,'EARLY_ALL',v_publication.published_at_utc,
      v_publication.published_at_utc,'PENDING',v_trigger,v_row.comparison_id)
    on conflict(recipient_generation_id,candidate_cohort_id,event_kind,trigger_hash) do nothing;
    select id into strict v_due_id from public.weekly_manager_cohort_due_events where recipient_generation_id=v_generation_id
      and candidate_cohort_id=(v_context->>'cohort_id')::uuid and event_kind='EARLY_ALL' and trigger_hash=v_trigger;
    if exists(select 1 from public.weekly_manager_cohort_due_events where id=v_due_id and state='CONSUMED') then continue; end if;
    if not private.weekly_source_manager_due_event_covers_v1(v_due_id,v_row.id) then
      raise exception 'WEEKLY_SOURCE_NOT_FINALISED_DUE_SCOPE_INVALID' using errcode='55000'; end if;
    v_intent:=private.weekly_source_query_manager_intent_v1(v_route,v_generation_id,array[v_due_id],
      'MANAGER_EARLY_ALL',1,v_publication.published_at_utc);
    update public.weekly_manager_cohort_due_events set state='CONSUMED' where id=v_due_id;
    update public.weekly_discrepancy_incidents set manager_action_state='DUE' where id=v_row.id and manager_action_state<>'RESPONDED';
    v_queued:=v_queued+1;
  end loop;
  return jsonb_build_object('ok',true,'deferred',v_deferred,'manager_intents_queued',v_queued,'manager_route_unavailable',v_no_route);
end;
$function$;
alter function private.weekly_source_not_finalised_dispatch_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_not_finalised_dispatch_v1(uuid) from public,anon,authenticated,service_role;

-- Complete native outreach owner; (a) and its unsigned expected-week lifecycle are manager-only.
create or replace function private.weekly_source_import_outreach_v1(
  p_projection_publication_id uuid
) returns void
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_candidate record;
  v_pair record;
  v_scopes jsonb;
  v_context jsonb;
  v_result jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  select publication.* into strict v_publication
  from public.weekly_source_projection_publications publication
  where publication.id=p_projection_publication_id and publication.state='CURRENT';
  if v_publication.correction_session_id is not null then return; end if;
  perform private.weekly_source_query_current_publication_v1(
    v_publication.source_cycle_id,v_publication.id);

  for v_candidate in
    select distinct groups.candidate_id
    from private.weekly_source_office_query_groups_v1(
      v_publication.source_cycle_id,v_publication.id,'{}'::jsonb) groups
    where groups.candidate_app_available
      and (select count(*) from public.candidate_app_global_membership_links membership
        join public.candidate_app_accounts account on account.id=membership.account_id
        where membership.candidate_id=groups.candidate_id
          and membership.state='ACTIVE' and account.status='ACTIVE')=1
    order by groups.candidate_id
  loop
    -- One candidate/cycle request owner. Serialize import/recheck attempts
    -- before inspecting memberships so concurrent imports cannot duplicate it.
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'weekly-source-import-outreach:'||v_publication.source_cycle_id::text||':'||v_candidate.candidate_id::text,0));
    select coalesce(pg_catalog.jsonb_agg(scope.value order by scope.value::text),'[]'::jsonb)
    into v_scopes
    from (
      select distinct membership.value
      from private.weekly_source_office_query_groups_v1(
        v_publication.source_cycle_id,v_publication.id,'{}'::jsonb) groups
      cross join lateral pg_catalog.jsonb_array_elements(groups.missing_scopes) membership
      where groups.candidate_id=v_candidate.candidate_id
        and coalesce((private._weekly_source_effective_policy_v1(
          (membership.value->>'client_id')::uuid,(membership.value->>'contract_id')::uuid,
          (membership.value->>'week_ending')::date)->>'candidate_queries_enabled')::boolean,false)
        and not exists (
          select 1 from public.timesheets sheet
          where sheet.contract_id=(membership.value->>'contract_id')::uuid
            and sheet.week_ending_date=(membership.value->>'week_ending')::date
            and sheet.is_current and sheet.revoked_at is null and sheet.archived_at_utc is null
            and sheet.sheet_scope='WEEKLY' and sheet.line_type='HOURS'
            and sheet.r2_nurse_key is not null and sheet.img_sha256_nurse is not null
        )
        and not exists (
          select 1 from public.weekly_route_activations activation
          where activation.source_cycle_id=v_publication.source_cycle_id
            and activation.candidate_id=v_candidate.candidate_id
            and activation.client_id=groups.client_id and activation.route_mode='MANAGER_DIRECT'
        )
    ) scope;
    if pg_catalog.jsonb_array_length(v_scopes)>0 then
      v_result:=private.weekly_source_submission_request_start_v1(
        pg_catalog.jsonb_build_object('source_cycle_id',v_publication.source_cycle_id,
          'projection_publication_id',v_publication.id,'candidate_id',v_candidate.candidate_id,
          'scopes',v_scopes),true);
    end if;

    for v_pair in
      select distinct on (incident.client_id) incident.client_id,comparison.contract_id,event.work_date
      from public.weekly_discrepancy_incidents incident
      join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      join public.weekly_work_events event on event.id=incident.work_event_id
      where incident.source_cycle_id=v_publication.source_cycle_id
        and incident.candidate_id=v_candidate.candidate_id and incident.state='OPEN'
        and comparison.projection_publication_id=v_publication.id
        and incident.candidate_action_state='NOT_ASKED'
        and not (comparison.issue_family='HEALTHROSTER_NOT_FINALISED'
          and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,event.work_date))
        and not private.weekly_source_expected_week_question_v1(incident.id)
        and not private.weekly_source_waiting_requested_week_v1(incident.source_cycle_id,
          incident.candidate_id,incident.client_id,comparison.contract_id,event.work_date)
        and not exists (
          select 1 from public.weekly_route_activations activation
          where activation.source_cycle_id=incident.source_cycle_id
            and activation.candidate_id=incident.candidate_id
            and activation.client_id=incident.client_id and activation.route_mode='MANAGER_DIRECT'
        )
      order by incident.client_id,event.work_date,incident.id
    loop
      v_context:=private.weekly_source_query_cohort_ensure_v1(v_publication.source_cycle_id,
        v_candidate.candidate_id,v_pair.client_id,v_pair.contract_id,v_pair.work_date);
      if not coalesce((v_context->>'candidate_queries_enabled')::boolean,false) then continue; end if;
      if coalesce((v_context->>'manager_queries_enabled')::boolean,false)
         and nullif(v_context->>'manager_route_id','') is not null then
        insert into public.weekly_route_activations(
          source_cycle_id,candidate_id,client_id,audience_route,route_mode,
          activated_at_utc,updated_at_utc
        ) values (v_publication.source_cycle_id,v_candidate.candidate_id,v_pair.client_id,
          'MANAGER','CANDIDATE_FIRST',pg_catalog.transaction_timestamp(),pg_catalog.transaction_timestamp())
        on conflict (source_cycle_id,candidate_id,client_id,audience_route) do nothing;
      end if;
      v_result:=private.weekly_source_query_candidate_generation_v1(
        v_publication.source_cycle_id,v_candidate.candidate_id,v_pair.client_id,
        v_publication.id,'NEW_INCIDENT',null,pg_catalog.transaction_timestamp());
      if v_result->>'status'='CREATED' and nullif(v_context->>'manager_route_id','') is not null then
        perform private.weekly_source_query_manager_generation_v1(
          (v_context->>'manager_route_id')::uuid,'T6_RESPONDED',pg_catalog.transaction_timestamp(),false);
      end if;
    end loop;
  end loop;
end;
$function$;
alter function private.weekly_source_import_outreach_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_import_outreach_v1(uuid) from public,anon,authenticated,service_role;

-- Key discovery is plain. The unchanged native I-1 owner locks the complete
-- physical booking family before any target/run/group/cycle row lock.
create or replace function private.weekly_source_protected_family_lock_v1(p_family_id uuid)
returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_before public.weekly_exceptional_pay_target_families%rowtype;
  v_after public.weekly_exceptional_pay_target_families%rowtype; v_lock jsonb;
begin
  select * into strict v_before from public.weekly_exceptional_pay_target_families where id=p_family_id;
  perform private.weekly_source_pay_query_admit_v2();
  v_lock:=private.weekly_source_lock_family_rows_v1(array[v_before.root_timesheet_id],v_before.candidate_id);
  if v_lock->>'ok' is distinct from 'true' then
    raise exception '%',coalesce(v_lock->>'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE') using errcode='55000'; end if;
  select * into strict v_after from public.weekly_exceptional_pay_target_families where id=p_family_id;
  if (v_after.root_timesheet_id,v_after.candidate_id,v_after.contract_id,v_after.week_ending_date)
    is distinct from (v_before.root_timesheet_id,v_before.candidate_id,v_before.contract_id,v_before.week_ending_date)
    or v_lock#>>'{families,0,canonical_timesheet_id}' is distinct from v_before.root_timesheet_id::text then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  return jsonb_build_object('root_timesheet_id',v_before.root_timesheet_id,'candidate_id',v_before.candidate_id,
    'contract_id',v_before.contract_id,'week_ending_date',v_before.week_ending_date);
end;
$function$;
alter function private.weekly_source_protected_family_lock_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_protected_family_lock_v1(uuid) from public,anon,authenticated,service_role;

-- Callers already hold I-1. This returns the exact discovered group key and
-- the caller rechecks it immediately after its original cycle row lock.
create or replace function private.weekly_source_protected_group_lock_v1(p_cycle_id uuid)
returns uuid language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_group_id uuid;
begin
  select source_group_id into strict v_group_id from public.weekly_source_cycles where id=p_cycle_id;
  perform 1 from public.weekly_source_groups where id=v_group_id and active for share;
  if not found then raise no_data_found; end if;
  return v_group_id;
end;
$function$;
alter function private.weekly_source_protected_group_lock_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_protected_group_lock_v1(uuid) from public,anon,authenticated,service_role;

-- Complete native owner: existing I-1/run locks, then group before cycle.
create or replace function public.weekly_exceptional_pay_prepare_family_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','source_cycle_id','candidate_id','client_id','contract_id',
    'week_ending_date','work_event_id','work_date','start_at_local',
    'end_at_local','break_minutes','evidence_timesheet_id','reason',
    'idempotency_key'
  ];
  v_actor_user_id uuid;
  v_source_cycle_id uuid;
  v_candidate_id uuid;
  v_client_id uuid;
  v_contract_id uuid;
  v_week_ending_date date;
  v_week_start_date date;
  v_work_event_id uuid;
  v_work_date date;
  v_start_at_local timestamp without time zone;
  v_end_at_local timestamp without time zone;
  v_break_minutes integer;
  v_evidence_timesheet_id uuid;
  v_reason text;
  v_idempotency_key text;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_contract_week public.contract_weeks%rowtype;
  v_root public.timesheets%rowtype;
  v_evidence public.timesheets%rowtype;
  v_signed_evidence jsonb;
  v_candidate public.candidates%rowtype;
  v_client public.clients%rowtype;
  v_policy jsonb;
  v_source_mode text;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_occupant_norm text;
  v_hospital_norm text;
  v_ward_norm text;
  v_role_norm text;
  v_booking_material text;
  v_booking_id text;
  v_work_event_hash bytea;
  v_first_evidence_hash bytea;
  v_request_hash bytea;
  v_before_hash bytea;
  v_created_root boolean:=false;
  v_created_family boolean:=false;
  v_created_event boolean:=false;
  v_replay boolean:=false;
  v_request_kind text:='APPROVE';
  v_lock_result jsonb;
  v_family_identity jsonb;
  v_known_root_timesheet_id uuid;
  v_saved_route jsonb;
  v_lock_group uuid;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,v_allowed_keys)
     or not (p_request ?& array[
       'actor_user_id','source_cycle_id','candidate_id','client_id','contract_id',
       'week_ending_date','work_date','start_at_local','end_at_local',
       'break_minutes','reason','idempotency_key'
     ]) then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end if;

  begin
    v_actor_user_id:=(p_request->>'actor_user_id')::uuid;
    v_source_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_candidate_id:=(p_request->>'candidate_id')::uuid;
    v_client_id:=(p_request->>'client_id')::uuid;
    v_contract_id:=(p_request->>'contract_id')::uuid;
    v_week_ending_date:=(p_request->>'week_ending_date')::date;
    v_work_event_id:=nullif(p_request->>'work_event_id','')::uuid;
    v_work_date:=(p_request->>'work_date')::date;
    v_start_at_local:=(p_request->>'start_at_local')::timestamp without time zone;
    v_end_at_local:=(p_request->>'end_at_local')::timestamp without time zone;
    v_break_minutes:=(p_request->>'break_minutes')::integer;
    v_evidence_timesheet_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_week_start_date:=v_week_ending_date-6;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1',p_request
  );

  if v_break_minutes is null or v_break_minutes<0
     or v_end_at_local<=v_start_at_local
     or v_break_minutes>=extract(epoch from (v_end_at_local-v_start_at_local))/60
     or v_work_date<>v_start_at_local::date
     or v_work_date>(pg_catalog.clock_timestamp() at time zone 'Europe/London')::date
     or v_work_date not between v_week_start_date and v_week_ending_date
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_idempotency_key) not between 16 and 200 then
    raise exception 'WEEKLY_PROTECTED_FAMILY_REQUEST_INVALID' using errcode='22023';
  end if;

  v_saved_route:=private.weekly_source_protected_saved_prepare_route_v1(p_request,
    'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1','APPROVE');
  if v_saved_route is not null then return v_saved_route; end if;
  perform private.weekly_source_pay_query_admit_v2();
  -- Review F1 and F4. After query admission, the I-1 lock set precedes the
  -- existing business locks this owner
  -- takes: no row lock, no FOR UPDATE and no other advisory key before it,
  -- because every installed rotation owner takes the family advisory key and
  -- the family rows before anything else (core 08082026_2035_...:126-131,
  -- legacy 16122025_...:844-849, confirmed route :2374-2376).  This owner
  -- previously locked the orchestration run, the cycle, the Contract and the
  -- Contract Week first and asked for the family keys afterwards, which is a
  -- proven deadlock (reproductions D1b and D2).  The root is discovered with a
  -- PLAIN read from the request's Contract and week.
  select contract_week.timesheet_id into v_known_root_timesheet_id
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0;

  if v_known_root_timesheet_id is not null then
    v_lock_result:=private.weekly_source_lock_family_rows_v1(
      array[v_known_root_timesheet_id]::uuid[],v_candidate_id
    );
    if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_lock_result->>'code'
        using errcode='55000',detail=v_lock_result::text;
    end if;
  end if;

  -- Serialize the global idempotency namespace before looking up the run.
  -- Without this lock, two first attempts can both observe no row and the
  -- loser receives a raw unique violation rather than an exact replay.  It is
  -- a Weekly-Source-private key that no rotation owner takes, and it is now
  -- requested after the family keys.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-exceptional-orchestration|'||v_idempotency_key,0
  ));

  -- A replay is recognized before any mutable work, but every immutable scope
  -- fact is still compared below.  A reused key can never name another family.
  select run.* into v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.idempotency_key=v_idempotency_key
  for update;
  if found then
    v_replay:=true;
  end if;

  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_source_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle
  where cycle.id=v_source_cycle_id
  for update;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id
    and source_group.active
  for share;

  perform private.weekly_source_office_authority_v1(
    v_actor_user_id,'APPROVE_PROTECTED_PAY',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  -- The source cycle records when Office discovered or is reconciling the
  -- protected item.  It is deliberately not required to be the work week:
  -- a missing or queried historic shift can remain protected for later cycles.
  if not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_client_id
         and v_cycle.finalisation_week_ending between membership.valid_from
           and coalesce(membership.valid_to,'infinity'::date)
     ) then
    raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
  end if;

  select contract.* into strict v_contract
  from public.contracts contract
  where contract.id=v_contract_id
  for update;
  if v_contract.candidate_id is distinct from v_candidate_id
     or v_contract.client_id is distinct from v_client_id
     or v_work_date not between v_contract.start_date and v_contract.end_date
     or v_contract.week_ending_weekday_snapshot not between 0 and 6
     or v_week_ending_date<>v_work_date+
       ((v_contract.week_ending_weekday_snapshot-
         extract(dow from v_work_date)::integer+7)%7) then
    raise exception 'WEEKLY_PROTECTED_CONTRACT_SCOPE_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_client_id,v_contract_id,v_work_date
  );
  v_source_mode:=v_policy->>'c1_source_mode';
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_POLICY_INVALID' using errcode='55000';
  end if;

  select candidate.* into strict v_candidate
  from public.candidates candidate where candidate.id=v_candidate_id;
  select client.* into strict v_client
  from public.clients client where client.id=v_client_id;

  -- G6-9 / WB-016.  Note on the Candidate serial gate (proof/32 section 6
  -- step 1): preparing the protected-pay family is not one of the four pinned
  -- Weekly Source job types, so this owner does not take the gate; the
  -- first-authorisation, publication and release owners do, through interface
  -- I-1.  It does take the full rotation lock set below (proof/34 rules 1, 6
  -- and 11), and adds no lock of its own on any Banking Pay table.

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_BASE_WEEK|'||v_contract_id::text||'|'||v_week_ending_date::text,0
  ));
  insert into public.contract_weeks(
    contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id,is_adjustment,created_at,updated_at
  ) values (
    v_contract_id,v_week_ending_date,0,'SUBMITTED'::public.contract_week_status_enum,
    'MANUAL'::public.submission_mode_enum,null,false,
    pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
  ) on conflict (contract_id,week_ending_date,additional_seq) do nothing;
  select contract_week.* into strict v_contract_week
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_contract_id
    and contract_week.week_ending_date=v_week_ending_date
    and contract_week.additional_seq=0
  for update;
  if v_contract_week.is_adjustment
     or v_contract_week.status='CANCELLED'::public.contract_week_status_enum then
    raise exception 'WEEKLY_PROTECTED_BASE_WEEK_INVALID' using errcode='55000';
  end if;

  -- Review G1.  Under the locks the Contract Week must still name the root
  -- whose family this transaction locked FIRST - including the null to non-null
  -- case, where the week gained a root between the plain read and here.  The
  -- earlier form guarded this with "v_known_root_timesheet_id is not null", so
  -- that case fell through to "select timesheet ... for update" before the
  -- family advisory keys, which is the reverse of every installed rotation
  -- owner and a proven deadlock.  This is the ensure owner's own unconditional
  -- check, in the same place relative to the locked read.
  if v_contract_week.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'expected_root_timesheet_id',v_known_root_timesheet_id,
          'observed_root_timesheet_id',v_contract_week.timesheet_id
        )::text;
  end if;

  if v_contract_week.timesheet_id is null then
    if v_contract_week.status in (
      'AUTHORISED'::public.contract_week_status_enum,
      'INVOICED'::public.contract_week_status_enum,
      'CANCELLED'::public.contract_week_status_enum
    ) then
      raise exception 'WEEKLY_PROTECTED_FINAL_WEEK_TIMESHEET_MISSING' using errcode='55000';
    end if;
    v_occupant_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_candidate.tms_ref),''),
      nullif(pg_catalog.btrim(v_candidate.display_name),''),v_candidate.id::text
    ));
    v_hospital_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.display_site),''),
      nullif(pg_catalog.btrim(v_client.name),''),v_client.id::text
    ));
    v_ward_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.ward_hint),''),'contract'
    ));
    v_role_norm:=pg_catalog.lower(coalesce(
      nullif(pg_catalog.btrim(v_contract.role),''),'weekly'
    ));
    v_booking_material:='weekly-source|'||v_contract_id::text||'|'||v_week_ending_date::text;
    v_booking_id:='bk_'||pg_catalog.substr(pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_booking_material,'UTF8'),'sha256'),'hex'
    ),1,24);
    -- A minted booking id must not collide with an existing family, and must
    -- not differ from an existing one by surrounding whitespace only: the
    -- confirmed rotation route serialises on the trimmed key while family
    -- membership is by the raw value, so such a pair is an ambiguous family.
    if exists(
      select 1 from public.timesheets existing
      where (existing.booking_id=v_booking_id and existing.is_current)
         or pg_catalog.btrim(existing.booking_id)=v_booking_id
    ) then
      raise exception 'WEEKLY_SOURCE_BOOKING_ID_COLLISION' using errcode='55000';
    end if;
    insert into public.timesheets(
      booking_id,version,is_current,status,sheet_scope,submission_mode,line_type,
      occupant_key_norm,hospital_norm,ward_norm,job_title_norm,shift_label_norm,
      week_ending_date,contract_id,actual_schedule_json,qr_payload_json,
      is_adjustment,created_at,updated_at
    ) values (
      v_booking_id,1,true,'RECEIVED'::public.timesheet_status_enum,
      'WEEKLY'::public.timesheet_scope_enum,'MANUAL'::public.submission_mode_enum,
      'HOURS'::public.timesheet_line_type_enum,v_occupant_norm,v_hospital_norm,
      v_ward_norm,v_role_norm,'weekly-0',v_week_ending_date,v_contract_id,
      '[]'::jsonb,'{}'::jsonb,false,
      pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()
    ) returning * into v_root;
    v_created_root:=true;
    update public.contract_weeks
    set timesheet_id=v_root.timesheet_id,
        status='SUBMITTED'::public.contract_week_status_enum,
        updated_at=pg_catalog.statement_timestamp()
    where id=v_contract_week.id
    returning * into v_contract_week;
  else
    select timesheet.* into strict v_root
    from public.timesheets timesheet
    where timesheet.timesheet_id=v_contract_week.timesheet_id
    for update;
  end if;

  -- G6-9 / proof/34 section 5 step 2 and rule 6.  A stored contract-week
  -- Timesheet id, or a freshly minted one, is only a lookup key: take the
  -- deadlock-free rotation lock set (trimmed key, raw key when different, raw
  -- booking family rows FOR UPDATE) and re-resolve the canonical current
  -- version through the installed Workbench authority before trusting it.
  -- For an existing root the lock set was already taken, before every other
  -- lock, so this call is re-entrant and re-resolves under the locks.  For a
  -- root this transaction has just minted, no other session can know the
  -- booking id yet, so taking the family keys here cannot join a cycle.
  v_lock_result:=private.weekly_source_lock_family_rows_v1(
    array[v_root.timesheet_id]::uuid[],v_candidate_id
  );
  if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
    raise exception '%',v_lock_result->>'code'
      using errcode='55000',detail=v_lock_result::text;
  end if;
  v_family_identity:=v_lock_result->'families'->0;

  -- The root this owner ends up holding must still be the one whose family was
  -- locked first, unless this transaction minted it itself.
  if not v_created_root
     and v_root.timesheet_id is distinct from v_known_root_timesheet_id then
    raise exception 'WEEKLY_SOURCE_BASE_WEEK_ROOT_CHANGED_DURING_LOCK'
      using errcode='40001';
  end if;

  -- proof/34 section 5 step 3: a changed current id makes the request stale.
  -- The older id is never used and nothing is written.
  if coalesce((v_family_identity->>'requested_is_canonical')::boolean,false) is not true
     or coalesce((v_family_identity->>'family_is_current')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION'
      using errcode='55000',detail=v_family_identity::text;
  end if;

  -- Re-read the root under the lock before any fact derived from it is frozen.
  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_root.timesheet_id;
  if v_root.booking_id is distinct from (v_family_identity->>'family_booking_id')
     or v_root.version is distinct from (v_family_identity->>'canonical_version')::integer then
    raise exception 'WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE'
      using errcode='55000',detail=v_family_identity::text;
  end if;

  if v_root.contract_id is distinct from v_contract_id
     or v_root.week_ending_date is distinct from v_week_ending_date
     or v_root.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
     or v_root.line_type<>'HOURS'::public.timesheet_line_type_enum
     or v_root.is_adjustment
     or not v_root.is_current
     or v_root.revoked_at is not null
     or v_root.archived_at_utc is not null then
    raise exception 'WEEKLY_PROTECTED_ROOT_INVALID' using errcode='55000';
  end if;

  if v_evidence_timesheet_id is not null then
    v_signed_evidence:=private.weekly_exceptional_candidate_signed_evidence_v1(
      v_evidence_timesheet_id
    );
    if (v_signed_evidence->>'contract_id')::uuid is distinct from v_contract_id
       or (v_signed_evidence->>'week_ending_date')::date is distinct from v_week_ending_date then
      raise exception 'WEEKLY_PROTECTED_EVIDENCE_INVALID' using errcode='55000';
    end if;
  end if;

  if v_work_event_id is not null then
    select event.id into strict v_work_event_id
    from public.weekly_work_events event
    where event.id=v_work_event_id
      and event.candidate_id=v_candidate_id
      and event.client_id=v_client_id
      and event.work_date=v_work_date
    for share;
  else
    v_work_event_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_OFFICE_PROTECTED_WORK_EVENT_V1',
      pg_catalog.jsonb_build_object(
        'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
        'client_id',v_client_id,'work_date',v_work_date,
        'start_at_local',v_start_at_local,'end_at_local',v_end_at_local,
        'break_minutes',v_break_minutes
      )
    );
    -- The new-shift editor cannot silently create another payable identity for
    -- work already recorded on this day. Exact replay keeps its original hash;
    -- changed hours must name the existing shift and use its protected owner.
    if not v_replay and exists(
      select 1 from public.weekly_work_events existing
      where existing.candidate_id=v_candidate_id
        and existing.work_date between v_work_date-1 and v_work_date+1
        and existing.durable_identity_hash<>v_work_event_hash
        and (
          (existing.work_date=v_work_date and existing.client_id=v_client_id
            and existing.first_source_group_id=v_group.id
            and existing.identity_kind='OFFICE_PROTECTED_SHIFT'
            and not exists(select 1 from public.weekly_exceptional_pay_family_events recorded
              where recorded.durable_work_event_id=existing.id))
          or
          private.weekly_source_work_event_schedule_compatible_v1(existing.id,v_start_at_local,v_end_at_local)
          or exists(select 1 from public.weekly_exceptional_pay_family_events protected
            where protected.durable_work_event_id=existing.id
              and protected.start_at_local<v_end_at_local and v_start_at_local<protected.end_at_local)
          or exists(select 1 from public.weekly_discrepancy_incidents incident
            join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
            where incident.work_event_id=existing.id
              and comparison.candidate_start_at_local<v_end_at_local
              and v_start_at_local<comparison.candidate_end_at_local)
        )
    ) then
      raise exception 'WEEKLY_PROTECTED_EXISTING_SHIFT_SELECTION_REQUIRED' using errcode='55000';
    end if;
    insert into public.weekly_work_events(
      candidate_id,client_id,work_date,identity_kind,profile_external_key,
      durable_identity_hash,first_source_group_id,source_format_profile_id
    ) values (
      v_candidate_id,v_client_id,v_work_date,'OFFICE_PROTECTED_SHIFT',null,
      v_work_event_hash,v_group.id,null
    ) on conflict (durable_identity_hash) do nothing
    returning id into v_work_event_id;
    if found then
      v_created_event:=true;
    else
      select event.id into strict v_work_event_id
      from public.weekly_work_events event
      where event.durable_identity_hash=v_work_event_hash
        and event.candidate_id=v_candidate_id
        and event.client_id=v_client_id
        and event.work_date=v_work_date
        and event.identity_kind='OFFICE_PROTECTED_SHIFT';
    end if;
  end if;

  v_first_evidence_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FIRST_EVIDENCE_V1',
    pg_catalog.jsonb_build_object(
      'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
      'client_id',v_client_id,'contract_id',v_contract_id,
      'week_ending_date',v_week_ending_date,'root_timesheet_id',v_root.timesheet_id,
      'evidence_timesheet_id',v_evidence_timesheet_id,'work_event_id',v_work_event_id,
      'work_date',v_work_date,'start_at_local',v_start_at_local,
      'end_at_local',v_end_at_local,'break_minutes',v_break_minutes
    )
  );

  select family.* into v_family
  from public.weekly_exceptional_pay_target_families family
  where family.agency_id=v_group.agency_id
    and family.candidate_id=v_candidate_id
    and family.contract_id=v_contract_id
    and family.week_ending_date=v_week_ending_date
  for update;
  if found then
    if v_family.root_timesheet_id is distinct from v_root.timesheet_id
       or v_family.week_start_date is distinct from v_week_start_date
       or v_family.agency_id is distinct from v_group.agency_id
       or v_family.candidate_id is distinct from v_candidate_id
       or v_family.contract_id is distinct from v_contract_id
       or (v_replay and v_run.family_id is distinct from v_family.id) then
      raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
    end if;
    -- One family is the complete Candidate + Contract + week entitlement.
    -- A later protected shift or an amended protected schedule is another
    -- immutable orchestration run against that same family, never a second
    -- public Timesheet and never a duplicate family.
    if v_replay then
      if v_run.request_kind not in ('APPROVE','AMEND') then
        raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
      end if;
      v_request_kind:=v_run.request_kind;
    else
      if v_family.c1_publication_state in ('PENDING','PUBLISHING') then
        raise exception 'WEEKLY_PROTECTED_PUBLICATION_BUSY' using errcode='55000';
      end if;
      -- Preparing a family is not a published pay decision. A failed first
      -- attempt can leave this identity present with no generation to amend.
      v_request_kind:=case when v_family.current_generation_id is null
        then 'APPROVE' else 'AMEND' end;
    end if;
  else
    if v_replay then
      raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
    end if;
    insert into public.weekly_exceptional_pay_target_families(
      agency_id,candidate_id,contract_id,week_start_date,week_ending_date,
      root_timesheet_id,ownership_state,first_signed_evidence_fingerprint,
      current_lifecycle_state,c1_publication_state,creation_idempotency_key
    ) values (
      v_group.agency_id,v_candidate_id,v_contract_id,v_week_start_date,
      v_week_ending_date,v_root.timesheet_id,'TARGET_MANAGED',v_first_evidence_hash,
      'PENDING_APPROVAL','NONE',v_idempotency_key
    ) returning * into v_family;
    v_created_family:=true;
    v_request_kind:='APPROVE';
  end if;

  v_before_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_BEFORE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'bound_version',v_family.bound_version,
      'root_timesheet_id',v_root.timesheet_id,
      'root_version',v_root.version,'contract_week_id',v_contract_week.id,
      'current_generation_id',v_family.current_generation_id,
      'current_generation_number',v_family.current_generation_number,
      'family_bound_version',v_family.bound_version,
      'work_event_id',v_work_event_id,
      'work_date',v_work_date,'start_at_local',v_start_at_local,
      'end_at_local',v_end_at_local,'break_minutes',v_break_minutes,
      'evidence_timesheet_id',v_evidence_timesheet_id,
      'request_kind',v_request_kind
    )
  );
  if not v_replay then
    insert into public.weekly_exceptional_orchestration_runs(
      family_id,request_kind,idempotency_key,requested_by_user_id,state,
      request_fingerprint,before_state_fingerprint
    ) values (
      v_family.id,v_request_kind,v_idempotency_key,v_actor_user_id,'RUNNING',
      v_request_hash,v_before_hash
    ) returning * into v_run;
  elsif v_run.request_kind<>v_request_kind
     or v_run.requested_by_user_id is distinct from v_actor_user_id
     or v_run.request_fingerprint is distinct from v_request_hash then
    raise exception 'WEEKLY_PROTECTED_REPLAY_SCOPE_INVALID' using errcode='55000';
  end if;

  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=v_root.timesheet_id
    and financial.is_current
  for share;

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,
    object_type,object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor_user_id,actor.display_name,actor.role,
    'weekly_exceptional_pay_target_families',v_family.id::text,
    case when v_created_family then 'WEEKLY_PROTECTED_FAMILY_PREPARED'
      else 'WEEKLY_PROTECTED_FAMILY_PREPARE_REPLAY' end,
    null,pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'source_cycle_id',v_source_cycle_id,
      'work_event_id',v_work_event_id,'root_timesheet_id',v_root.timesheet_id,
      'contract_week_id',v_contract_week.id,'candidate_id',v_candidate_id,
      'client_id',v_client_id,'contract_id',v_contract_id,
      'week_ending_date',v_week_ending_date,'source_mode',v_source_mode,
      'request_kind',v_request_kind,
      'created_root',v_created_root,'created_work_event',v_created_event,
      'requires_zero_financial',v_fin.id is null
    ),v_reason
  from public.tms_users actor where actor.id=v_actor_user_id;

  return pg_catalog.jsonb_build_object(
    'family_id',v_family.id,'orchestration_run_id',v_run.id,
    'source_cycle_id',v_source_cycle_id,'source_group_id',v_group.id,
    'agency_id',v_group.agency_id,'candidate_id',v_candidate_id,
    'client_id',v_client_id,'contract_id',v_contract_id,
    'contract_week_id',v_contract_week.id,'root_timesheet_id',v_root.timesheet_id,
    'work_event_id',v_work_event_id,'week_start_date',v_week_start_date,
    'week_ending_date',v_week_ending_date,'source_mode',v_source_mode,
    'root_version',v_root.version,'financial_row_id',v_fin.id,
    'requires_zero_financial',v_fin.id is null,
    'created_root',v_created_root,'created_family',v_created_family,
    'created_work_event',v_created_event,'idempotent_replay',v_replay,
    'family_bound_version',v_family.bound_version,'request_kind',v_request_kind,
    'run_state',v_run.state
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_FAMILY_SCOPE_INVALID' using errcode='55000';
end;
$function$;
alter function public.weekly_exceptional_pay_prepare_family_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_exceptional_pay_prepare_family_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_exceptional_pay_prepare_family_v1(jsonb) to service_role;

-- Complete native owner: immutable replay preserved; I-1 precedes Source locks; group precedes cycle.
create or replace function public.weekly_exceptional_pay_prepare_action_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','source_cycle_id','work_event_id',
    'action','expected_family_bound_version','protected_schedule','reason',
    'idempotency_key'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor uuid;
  v_family_id uuid;
  v_cycle_id uuid;
  v_event_id uuid;
  v_expected_version bigint;
  v_action text;
  v_reason text;
  v_key text;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_latest_event public.weekly_exceptional_pay_family_events%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_request_hash bytea;
  v_before bytea;
  v_source_mode text;
  v_policy jsonb;
  v_schedule jsonb;
  v_work_date date;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_break integer;
  v_replay boolean:=false;
  v_review_source jsonb;
  v_saved_route jsonb;
begin
  if pg_catalog.jsonb_typeof(p_request)<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(p_request,
       v_keys||array['expected_source_hash','expected_source_revision'])
     or not (p_request ?& v_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_ACTION_PREPARE_V1' then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_event_id:=(p_request->>'work_event_id')::uuid;
    v_expected_version:=(p_request->>'expected_family_bound_version')::bigint;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end;
  v_action:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'action','')));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PREPARE_ACTION_REQUEST_V1',p_request
  );
  if v_action not in ('AMEND','WITHDRAW','WAIT','RECONCILE','RECORD_NOT_WORKED')
     or v_expected_version<1
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_key) not between 16 and 200 then
    raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
  end if;

  v_saved_route:=private.weekly_source_protected_saved_prepare_route_v1(p_request,
    'WEEKLY_PROTECTED_PREPARE_ACTION_REQUEST_V1',v_action);
  if v_saved_route is not null then return v_saved_route; end if;
  perform private.weekly_source_pay_query_admit_v2();
  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  -- Share the same global idempotency lock as first approval.  Concurrent
  -- first attempts for one key therefore become one write plus one exact
  -- replay instead of leaking the ledger's unique constraint.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-exceptional-orchestration|'||v_key,0
  ));

  select run.* into v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.idempotency_key=v_key for update;
  v_replay:=found;

  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id for update;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_cycle_id for share;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active for share;
  select contract.* into strict v_contract
  from public.contracts contract where contract.id=v_family.contract_id for share;
  select work_event.* into strict v_event
  from public.weekly_work_events work_event
  where work_event.id=v_event_id
    and work_event.candidate_id=v_family.candidate_id
    and work_event.client_id=v_contract.client_id
    and work_event.work_date between v_family.week_start_date and v_family.week_ending_date
  for share;
  select family_event.* into strict v_latest_event
  from public.weekly_exceptional_pay_family_events family_event
  where family_event.family_id=v_family.id
    and family_event.durable_work_event_id=v_event.id
  order by family_event.event_sequence desc
  limit 1
  for share;

  if v_action='AMEND' then
    if pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
       or not private.weekly_exceptional_json_keys_exact_v1(
         p_request->'protected_schedule',v_schedule_keys
       )
       or not ((p_request->'protected_schedule') ?& v_schedule_keys) then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end if;
    v_schedule:=p_request->'protected_schedule';
    begin
      v_work_date:=(v_schedule->>'work_date')::date;
      v_start:=(v_schedule->>'start_at_local')::timestamp without time zone;
      v_end:=(v_schedule->>'end_at_local')::timestamp without time zone;
      v_break:=(v_schedule->>'break_minutes')::integer;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end;
    if v_work_date<>v_event.work_date or v_start::date<>v_work_date
       or v_end<=v_start or v_break<0
       or v_break>=extract(epoch from (v_end-v_start))/60 then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_INVALID' using errcode='22023';
    end if;
  else
    if p_request->'protected_schedule'<>'null'::jsonb then
      raise exception 'WEEKLY_PROTECTED_ACTION_SCHEDULE_FORBIDDEN' using errcode='22023';
    end if;
    v_schedule:=pg_catalog.jsonb_build_object(
      'work_date',v_latest_event.work_date,
      'start_at_local',v_latest_event.start_at_local,
      'end_at_local',v_latest_event.end_at_local,
      'break_minutes',v_latest_event.break_minutes
    );
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'APPROVE_PROTECTED_PAY',v_group.id,v_contract.client_id,v_cycle.finalisation_week_ending
  );
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_event.work_date
  );
  v_source_mode:=v_policy->>'c1_source_mode';
  if v_family.agency_id is distinct from v_group.agency_id
     or v_family.root_timesheet_id is null
     or v_family.ownership_state<>'TARGET_MANAGED'
     or v_contract.candidate_id is distinct from v_family.candidate_id
     or not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_contract.client_id
         and v_cycle.finalisation_week_ending between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
     )
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY')
     or v_latest_event.id is null then
    raise exception 'WEEKLY_PROTECTED_ACTION_SCOPE_INVALID' using errcode='55000';
  end if;

  if v_replay then
    if v_run.family_id is distinct from v_family.id
       or v_run.request_kind is distinct from v_action
       or v_run.requested_by_user_id is distinct from v_actor
       or v_run.request_fingerprint is distinct from v_request_hash then
      raise exception 'WEEKLY_PROTECTED_ACTION_IDEMPOTENCY_COLLISION' using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','PREPARED','family_id',v_family.id,
      'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
      'source_group_id',v_group.id,'agency_id',v_group.agency_id,
      'candidate_id',v_family.candidate_id,'client_id',v_contract.client_id,
      'contract_id',v_family.contract_id,'root_timesheet_id',v_family.root_timesheet_id,
      'work_event_id',v_event.id,'week_start_date',v_family.week_start_date,
      'week_ending_date',v_family.week_ending_date,'source_mode',v_source_mode,
      'family_bound_version',v_expected_version,'request_kind',v_action,
      'protected_schedule',v_schedule,'run_state',v_run.state,
      'idempotent_replay',true
    );
  end if;

  if v_family.current_generation_id is null
     or v_family.current_lifecycle_state not in (
       'PROTECTED','WAITING_SOURCE','READY_TO_RECONCILE','RECONCILED','NOT_WORKED','ACTION_REQUIRED'
     )
     or v_family.c1_publication_state in ('PENDING','PUBLISHING')
     or v_family.bound_version<>v_expected_version then
    -- A business-version refusal is not a retryable PostgreSQL serialization
    -- failure. PostgREST 14 retries 40001, so return the same refusal as HTTP
    -- conflict without repeating the request or creating an orchestration run.
    raise exception 'WEEKLY_PROTECTED_ACTION_STALE' using errcode='PT409';
  end if;

  -- A new Office review is bound to the exact final-source observation shown.
  -- Refuse before creating a run; old callers and exact saved replays retain
  -- their original request shape and fingerprint.
  if p_request ? 'expected_source_hash' or p_request ? 'expected_source_revision' then
    if v_action<>'RECONCILE'
      or coalesce(p_request->>'expected_source_hash','') !~ '^[0-9a-f]{64}$'
      or coalesce(p_request->>'expected_source_revision','') !~ '^[0-9a-f-]{36}$' then
      raise exception 'WEEKLY_PROTECTED_ACTION_REQUEST_INVALID' using errcode='22023';
    end if;
    v_review_source:=private.weekly_source_protected_final_source_context_v1(v_family.id,v_cycle.id,v_event.id);
    if not coalesce((v_review_source->>'source_observed')::boolean,false)
      or v_review_source#>>'{source_proposal,source_hash}' is distinct from p_request->>'expected_source_hash'
      or v_review_source#>>'{source_proposal,source_revision}' is distinct from p_request->>'expected_source_revision' then
      raise exception 'WEEKLY_PROTECTED_REVIEW_SOURCE_CHANGED' using errcode='40001';
    end if;
  end if;

  v_before:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_ACTION_PREPARE_BEFORE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'family_bound_version',v_family.bound_version,
      'current_generation_id',v_family.current_generation_id,
      'current_generation_number',v_family.current_generation_number,
      'current_target_vector_hash',pg_catalog.encode(v_family.current_complete_target_vector_hash,'hex'),
      'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
      'work_event_id',v_event.id,'action',v_action,'actor_user_id',v_actor,
      'protected_schedule',v_schedule,'reason',v_reason
    )
  );
  insert into public.weekly_exceptional_orchestration_runs(
    family_id,request_kind,idempotency_key,requested_by_user_id,state,
    request_fingerprint,before_state_fingerprint
  ) values (
    v_family.id,v_action,v_key,v_actor,'RUNNING',v_request_hash,v_before
  ) returning * into v_run;
  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome','PREPARED','family_id',v_family.id,
    'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
    'source_group_id',v_group.id,'agency_id',v_group.agency_id,
    'candidate_id',v_family.candidate_id,'client_id',v_contract.client_id,
    'contract_id',v_family.contract_id,'root_timesheet_id',v_family.root_timesheet_id,
    'work_event_id',v_event.id,'week_start_date',v_family.week_start_date,
    'week_ending_date',v_family.week_ending_date,'source_mode',v_source_mode,
    'family_bound_version',v_family.bound_version,'request_kind',v_action,
    'protected_schedule',v_schedule,'run_state',v_run.state,
    'idempotent_replay',v_replay
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_ACTION_SCOPE_INVALID' using errcode='55000';
end;
$function$;
alter function public.weekly_exceptional_pay_prepare_action_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_exceptional_pay_prepare_action_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_exceptional_pay_prepare_action_v1(jsonb) to service_role;

-- Complete native owner: immutable replay preserved; I-1 precedes Source locks; group precedes cycle.
create or replace function public.weekly_exceptional_pay_action_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','orchestration_run_id',
    'source_cycle_id','work_event_id','protected_schedule','evidence_timesheet_id'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor uuid;
  v_family_id uuid;
  v_run_id uuid;
  v_cycle_id uuid;
  v_event_id uuid;
  v_evidence_id uuid;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_contract_week public.contract_weeks%rowtype;
  v_root public.timesheets%rowtype;
  -- WP-30 (WP-27 sweep finding N4), standing rule 3.  The expense-authority
  -- selection below decides which SOURCE_EXPENSE authorities belong to this
  -- protected root through the source-row lineage binding, which is a fact
  -- about the Timesheet FAMILY.  Keyed on the physical root id a rotated
  -- family's authorities were SILENTLY DROPPED from the projection rather than
  -- refused — fail open by omission.  EXECUTED on a rotated family: 0
  -- authorities selected by the physical id against 4 by the family.
  v_root_family uuid[];
  v_fin public.timesheets_financials%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_schedule jsonb;
  v_work_date date;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_break integer;
  v_policy jsonb;
  v_root_policy jsonb;
  v_settings jsonb;
  v_source_mode text;
  v_source_segments jsonb:='[]'::jsonb;
  v_client_sources jsonb:='[]'::jsonb;
  v_decisions jsonb:='[]'::jsonb;
  v_source_expenses jsonb:='[]'::jsonb;
  v_current_final uuid;
  v_comparison uuid;
  v_signed jsonb;
  v_candidate_submission jsonb;
  v_selected_source_present boolean:=false;
  v_selected_source_minutes integer:=0;
  v_selected_source_revision text;
  v_selected_source_hash text;
  v_source_head_revision uuid;
  v_source_head_count integer:=0;
  v_ambiguous_event_count integer:=0;
  v_fin_hash text;
  v_provider_hash text;
  v_rate_refs jsonb;
  v_component_identity_inventory jsonb;
  v_component_identity_components jsonb;
  v_final_source jsonb;
  v_next_context boolean:=false;
begin
  if pg_catalog.jsonb_typeof(p_request)<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(p_request,v_keys)
     or not (p_request ?& v_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_ACTION_CONTEXT_V1'
     or pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
     or not private.weekly_exceptional_json_keys_exact_v1(
       p_request->'protected_schedule',v_schedule_keys
     )
     or not ((p_request->'protected_schedule') ?& v_schedule_keys) then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_run_id:=(p_request->>'orchestration_run_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_event_id:=(p_request->>'work_event_id')::uuid;
    v_evidence_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
    v_schedule:=p_request->'protected_schedule';
    v_work_date:=(v_schedule->>'work_date')::date;
    v_start:=(v_schedule->>'start_at_local')::timestamp without time zone;
    v_end:=(v_schedule->>'end_at_local')::timestamp without time zone;
    v_break:=(v_schedule->>'break_minutes')::integer;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end;
  if v_end<=v_start or v_start::date<>v_work_date or v_break<0
     or v_break>=extract(epoch from (v_end-v_start))/60 then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_INVALID' using errcode='22023';
  end if;

  -- Fresh context has no immutable decision receipt exemption. Admission
  -- precedes its first family/business lock and is reentrant for an owner.
  perform private.weekly_source_pay_query_admit_v2();

  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id for share;
  select run.* into strict v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.id=v_run_id and run.family_id=v_family.id for share;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_cycle_id);
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_cycle_id for share;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active for share;
  select contract.* into strict v_contract
  from public.contracts contract where contract.id=v_family.contract_id for share;
  select contract_week.* into strict v_contract_week
  from public.contract_weeks contract_week
  where contract_week.contract_id=v_family.contract_id
    and contract_week.week_ending_date=v_family.week_ending_date
    and contract_week.additional_seq=0 for share;
  -- WP-30, standing rule 3.  The family is resolved and its rows are locked
  -- BEFORE the family-scoped state below is read, in the SAME mode and the same
  -- timesheet_id order the installed code here already uses (`for share`), and
  -- before the root's own `for share` so no new lock ordering is introduced.
  v_next_context:=(select active_owner from private.bpay_next_module_control where id=1)='NEXT'
    and private.bpay_next_protected_owner_route_v1(v_family.id)='NEXT';
  if v_next_context then
    v_root_family:=array[v_family.root_timesheet_id];
  else
    v_root_family:=private.weekly_source_invoice_family_timesheet_ids_v1(v_family.root_timesheet_id);
  end if;
  -- Standing rule 3's fail-closed branch: an explicit cardinality test, never a
  -- `limit`.  This owner already refuses on every other unprovable scope fact.
  if v_root_family is null or pg_catalog.cardinality(v_root_family)=0 then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_FAMILY_UNRESOLVED'
      using errcode='55000';
  end if;
  perform 1 from public.timesheets lock_row
  where lock_row.timesheet_id=any(v_root_family)
  order by lock_row.timesheet_id for share;
  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_family.root_timesheet_id for share;
  select financial.* into v_fin
  from public.timesheets_financials financial
  where financial.timesheet_id=v_root.timesheet_id and financial.is_current
  order by financial.computed_at_utc desc nulls last,
           financial.updated_at desc nulls last,financial.id desc limit 1;
  select work_event.* into strict v_event
  from public.weekly_work_events work_event
  where work_event.id=v_event_id
    and work_event.candidate_id=v_family.candidate_id
    and work_event.client_id=v_contract.client_id for share;

  perform private.weekly_source_office_authority_v1(
    v_actor,'APPROVE_PROTECTED_PAY',v_group.id,v_contract.client_id,v_event.work_date
  );
  v_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_event.work_date
  );
  -- The selected shift uses its work-date policy, but the zero-value root
  -- financial is a weekly Timesheet. Its rate-source fingerprint must match
  -- the root prepare owner's week-ending policy exactly.
  v_root_policy:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_family.week_ending_date
  );
  v_settings:=(private._timesheet_settings_authority_frozen_v1(v_root.timesheet_id)->'values')
    -'resolved_at_utc';
  v_source_mode:=v_policy->>'c1_source_mode';
  if v_run.requested_by_user_id is distinct from v_actor
     or v_run.state not in ('RUNNING','COMPLETE')
     or v_run.request_kind not in ('APPROVE','AMEND','WITHDRAW','WAIT','RECONCILE','RECORD_NOT_WORKED')
     or v_family.agency_id is distinct from v_group.agency_id
     or v_contract.candidate_id is distinct from v_family.candidate_id
     or v_contract_week.timesheet_id is distinct from v_root.timesheet_id
     or v_root.contract_id is distinct from v_contract.id
     or (v_next_context and v_root.booking_id is distinct from v_family.root_family_booking_id)
     or v_root.week_ending_date is distinct from v_family.week_ending_date
     or not v_root.is_current or v_root.is_adjustment
     or v_root.revoked_at is not null or v_root.archived_at_utc is not null
     or v_event.work_date<>v_work_date
     or v_work_date not between v_family.week_start_date and v_family.week_ending_date
     or v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
  end if;

  -- Read the same final-source authority shown in the Office review.
  v_final_source:=private.weekly_source_protected_final_source_context_v1(v_family.id,v_cycle.id,v_event.id);
  v_source_segments:=v_final_source->'source_segments';
  v_client_sources:=v_final_source->'client_sources';
  v_current_final:=(v_final_source->>'current_final_revision_id')::uuid;
  v_selected_source_present:=(v_final_source#>>'{source_proposal,source_present}')::boolean;
  v_selected_source_minutes:=(v_final_source#>>'{source_proposal,source_minutes}')::integer;
  v_selected_source_revision:=v_final_source#>>'{source_proposal,source_revision}';
  v_selected_source_hash:=v_final_source#>>'{source_proposal,source_hash}';

  with latest as (
    select family_event.*,
      pg_catalog.row_number() over (
        partition by family_event.durable_work_event_id
        order by family_event.event_sequence desc
      ) as event_rank
    from public.weekly_exceptional_pay_family_events family_event
    where family_event.family_id=v_family.id
  ), decisions as (
    select latest.durable_work_event_id as work_event_id,
      case when latest.durable_work_event_id=v_event.id then case
        when v_run.request_kind in ('APPROVE','AMEND','WAIT') then 'WAIT'
        when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
        else 'NOT_WORKED' end
      else latest.state end as decision_state,
      case when latest.durable_work_event_id=v_event.id
             and v_run.request_kind in ('APPROVE','AMEND','WAIT')
        then v_schedule
        else pg_catalog.jsonb_build_object(
          'work_date',latest.work_date,'start_at_local',latest.start_at_local,
          'end_at_local',latest.end_at_local,'break_minutes',latest.break_minutes
        ) end as fixed_schedule
    from latest where latest.event_rank=1
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'work_event_id',decision.work_event_id,'state',decision.decision_state,
    'fixed_schedule',case when decision.decision_state='WAIT' then pg_catalog.jsonb_build_object(
      'date',decision.fixed_schedule->>'work_date',
      'start',pg_catalog.to_char((decision.fixed_schedule->>'start_at_local')::timestamp,'HH24:MI'),
      'end',pg_catalog.to_char((decision.fixed_schedule->>'end_at_local')::timestamp,'HH24:MI'),
      'break_mins',(decision.fixed_schedule->>'break_minutes')::integer
    ) else null end
  ) order by decision.work_event_id),'[]'::jsonb)
  into v_decisions from decisions decision;
  if not exists(
    select 1 from pg_catalog.jsonb_array_elements(v_decisions) d(value)
    where (d.value->>'work_event_id')::uuid=v_event.id
  ) then
    v_decisions:=v_decisions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'work_event_id',v_event.id,
      'state',case when v_run.request_kind in ('APPROVE','AMEND','WAIT') then 'WAIT'
        when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
        else 'NOT_WORKED' end,
      'fixed_schedule',case when v_run.request_kind in ('APPROVE','AMEND','WAIT')
        then pg_catalog.jsonb_build_object(
          'date',v_work_date,'start',pg_catalog.to_char(v_start,'HH24:MI'),
          'end',pg_catalog.to_char(v_end,'HH24:MI'),'break_mins',v_break
        ) else null end
    ));
  end if;

  if v_run.request_kind='RECORD_NOT_WORKED' and v_selected_source_present then
    raise exception 'WEEKLY_PROTECTED_NOT_WORKED_SOURCE_PRESENT' using errcode='55000';
  end if;

  select comparison.id into v_comparison
  from public.weekly_issue_comparison_revisions comparison
  join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
  where incident.work_event_id=v_event.id and incident.candidate_id=v_family.candidate_id
    and incident.client_id=v_contract.client_id
  order by comparison.created_at_utc desc,comparison.id desc limit 1;

  if v_evidence_id is null then
    select approval.evidence_timesheet_id into v_evidence_id
    from public.weekly_exceptional_payment_approvals approval
    where approval.pay_target_family_id=v_family.id
      and approval.work_event_id=v_event.id
    order by approval.approved_at_utc desc,approval.id desc limit 1;
  end if;
  if v_evidence_id is not null then
    v_signed:=private.weekly_exceptional_candidate_signed_evidence_v1(v_evidence_id);
    v_candidate_submission:=pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_CANDIDATE_TIMESHEET',
      'external_identity',v_evidence_id::text,
      'external_revision',v_signed->>'timesheet_version',
      'document_sha256',v_signed->>'signature_sha256',
      'work_date',v_event.work_date,'submitted_by_candidate_id',v_family.candidate_id,
      'submission_id',v_evidence_id,'submitted_at_utc',v_signed->>'signed_at_utc',
      'submitted_minutes',extract(epoch from (v_end-v_start))::integer/60-v_break
    );
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'expense_code','SOURCE_SUPPLIED:'||authority.work_event_id::text,
    'authority_kind','SOURCE_EXPENSE','source_expense_id',authority.id,
    'document_sha256',pg_catalog.encode(authority.authority_hash,'hex'),
    'pay_ex_vat',authority.candidate_reimbursement_ex_vat::text,
    'charge_ex_vat',authority.client_charge_ex_vat::text
  )||case when v_final_source ? 'next_source_segments'
    then pg_catalog.jsonb_build_object('work_event_id',authority.work_event_id,
      'final_revision_id',authority.final_revision_id,
      'source_observation_kind',authority.source_observation_kind) else '{}'::jsonb end
   order by authority.work_event_id),'[]'::jsonb)
  into v_source_expenses
  from (
    select authority.*,
      pg_catalog.row_number() over (
        partition by authority.work_event_id order by source_cycle.finalisation_week_ending desc,
          revision.finalised_at_utc desc,authority.generation desc,authority.id desc
      ) as event_rank
    from public.weekly_expense_authority_generations authority
    join public.weekly_source_final_revisions revision
      on revision.id=authority.final_revision_id and revision.state='CURRENT'
    join public.weekly_source_cycles source_cycle on source_cycle.id=revision.source_cycle_id
    where authority.contract_id=v_family.contract_id and authority.state='CURRENT'
      and source_cycle.source_group_id=v_group.id
      and ((not v_next_context and authority.source_expense_pence>0 and exists(
          select 1 from public.weekly_source_row_timesheet_lineages lineage
          where lineage.work_event_id=authority.work_event_id and lineage.contract_id=authority.contract_id
            and lineage.timesheet_id=any(v_root_family)))
        or (v_next_context and exists(
          select 1 from public.weekly_work_events event where event.id=authority.work_event_id
            and event.candidate_id=v_family.candidate_id and event.client_id=v_contract.client_id
            and event.work_date between v_family.week_start_date and v_family.week_ending_date
        ) and ((authority.source_observation_kind='OMITTED_IN_COMPLETE_COVERAGE' and authority.source_expense_pence=0)
          or exists(
            select 1 from public.weekly_source_row_expense_policy_snapshots expense_snapshot
            join public.weekly_source_row_timesheet_lineages lineage on lineage.row_resolution_id=expense_snapshot.row_resolution_id
            where expense_snapshot.id=authority.row_expense_policy_snapshot_id
              and lineage.family_booking_id=v_family.root_family_booking_id
              and lineage.work_event_id=authority.work_event_id and lineage.candidate_id=v_family.candidate_id
              and lineage.client_id=v_contract.client_id and lineage.contract_id=v_family.contract_id
              and lineage.week_ending_date=v_family.week_ending_date))))
  ) authority where authority.event_rank=1 and authority.source_expense_pence>0;

  v_fin_hash:=case when v_fin.id is null then null else pg_catalog.encode(
    private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_PROTECTED_ROOT_FINANCIAL_V1',pg_catalog.to_jsonb(v_fin)
    ),'hex') end;
  v_provider_hash:=pg_catalog.encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_PROVIDER_V1',
    pg_catalog.jsonb_build_object(
      'contract_id',v_contract.id,'pay_method',v_contract.pay_method_snapshot,
      'umbrella_id',pg_catalog.to_jsonb(v_contract)->>'umbrella_id',
      'candidate_id',v_contract.candidate_id
    )
  ),'hex');
  v_rate_refs:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_TARGET_MANAGED_ZERO_RATE_SOURCE_V1',
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'source_family',v_group.source_family,'source_mode',v_source_mode,
    'source_profile_domain',case when v_source_mode='NHSP_WEEKLY'
      then 'NHSP_TRUST_BACKING_REPORT' else 'ROSTER_FINAL_AUTHORITY' end,
    'target_family_id',v_family.id,'root_timesheet_id',v_root.timesheet_id,
    'effective_policy_sha256',v_root_policy->>'policy_sha256'
  );

  -- Local/common identity admission is independent of Banking work completion.
  -- An already authorised root requires its genuine complete current I1 basis;
  -- an actual unauthorised first Save must not invent that approved basis.
  if v_family.target_domain_version='C1_V1' then
    if v_root.authorised_at_server is not null then
      v_component_identity_inventory:=private.weekly_source_effective_inventory_v1(v_root.timesheet_id);
      if v_component_identity_inventory->>'ok' is distinct from 'true'
         or v_component_identity_inventory#>>'{approval_basis,coverage_complete}' is distinct from 'true'
         or v_component_identity_inventory#>>'{approval_basis,scope,root_timesheet_id}'
              is distinct from v_root.timesheet_id::text
         or jsonb_typeof(v_component_identity_inventory->'components') is distinct from 'array' then
        raise exception 'WEEKLY_PROTECTED_COMPONENT_APPROVED_BASIS_UNAVAILABLE' using errcode='55000'; end if;
      v_component_identity_components:=v_component_identity_inventory->'components';
    else
      if exists(select 1 from public.weekly_source_root_authorisations a
          where a.family_booking_id=v_root.booking_id)
         or exists(select 1 from public.weekly_source_entitlement_heads h
          where h.root_family_booking_id=v_root.booking_id and h.state='COMMITTED_CURRENT') then
        raise exception 'WEEKLY_PROTECTED_COMPONENT_APPROVED_BASIS_UNAVAILABLE' using errcode='55000'; end if;
      v_component_identity_components:='[]'::jsonb;
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'contract','WEEKLY_PROTECTED_ACTION_CONTEXT_V1',
    'action',v_run.request_kind,'family_id',v_family.id,
    'orchestration_run_id',v_run.id,'family_bound_version',v_family.bound_version,
    'current_target_vector_sha256',case
      when v_family.current_complete_target_vector_hash is null then null
      else pg_catalog.encode(v_family.current_complete_target_vector_hash,'hex') end,
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'agency_id',v_group.agency_id,'candidate_id',v_family.candidate_id,
    'client_id',v_contract.client_id,'contract_id',v_contract.id,
    'contract_week_id',v_contract_week.id,'root_timesheet_id',v_root.timesheet_id,
    'work_event_id',v_event.id,'week_ending_date',v_family.week_ending_date,
    'source_mode',v_source_mode,'policy',v_settings,
    'timesheet',pg_catalog.to_jsonb(v_root),'contract_week',pg_catalog.to_jsonb(v_contract_week),
    'contract_record',pg_catalog.to_jsonb(v_contract),
    'current_financial',case when v_fin.id is null then null else pg_catalog.to_jsonb(v_fin) end,
    'approved_component_identity_components',v_component_identity_components,
    'requires_zero_financial',v_fin.id is null,
    'protected_schedule',v_schedule,'source_segments',v_source_segments,
    'protected_decisions',v_decisions,'source_proposal',pg_catalog.jsonb_build_object(
      'selected_work_event_id',v_event.id,'source_present',v_selected_source_present,
      'source_minutes',v_selected_source_minutes,'source_revision',v_selected_source_revision,
      'source_hash',v_selected_source_hash,'source_segments',v_source_segments
    ),
    'client_sources',v_client_sources,'source_expenses',v_source_expenses,
    'candidate_submission',v_candidate_submission,
    'current_comparison_revision_id',v_comparison,
    'current_final_revision_id',v_current_final,
    'root_financial',case when v_fin.id is null then null else pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_TIMESHEET_FINANCIAL','external_identity',v_fin.id::text,
      'external_revision',v_fin.timesheet_version::text,'document_sha256',v_fin_hash,
      'financial_row_id',v_fin.id,'root_version',v_root.version,
      'financial_timesheet_version',v_fin.timesheet_version,
      'financial_revision_digest',v_fin_hash
    ) end,
    'provider',pg_catalog.jsonb_build_object(
      'source_system','CLOUDTMS_CONTRACT_PROVIDER','external_identity',v_contract.id::text,
      'external_revision',v_root.version::text,'document_sha256',v_provider_hash,
      'source_pay_method',v_contract.pay_method_snapshot,
      'umbrella_id',nullif(pg_catalog.to_jsonb(v_contract)->>'umbrella_id','')::uuid,
      'provider_authority_sha256',v_provider_hash,
      'target_pay_method',v_contract.pay_method_snapshot,
      'target_umbrella_id',nullif(pg_catalog.to_jsonb(v_contract)->>'umbrella_id','')::uuid,
      'target_enabled',true,'target_vat_chargeable',null
    ),
    'expected_head_revision',coalesce((
      select generation.generation_number::bigint
      from private.weekly_source_local_protected_decision_receipts receipt
      join public.weekly_exceptional_pay_generations generation on generation.id=receipt.generation_id
      where receipt.family_id=v_family.id and receipt.state='COMPLETE'
        and generation.id=v_family.current_generation_id
    ),(
      select request.c1_head_revision
      from public.weekly_exceptional_c1_publication_requests request
      where request.family_id=v_family.id and request.state='PUBLISHED'
      order by request.request_sequence desc limit 1
    ),0)::text,
    'request_sequence',(v_family.current_generation_number+1)::text,
    'zero_rate_source_refs',v_rate_refs
  )||case when v_final_source ? 'next_source_segments'
    then pg_catalog.jsonb_build_object('next_source_segments',v_final_source->'next_source_segments',
      'family_bound_version',v_family.bound_version::text) else '{}'::jsonb end;
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
end;
$function$;
alter function public.weekly_exceptional_pay_action_context_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_exceptional_pay_action_context_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_exceptional_pay_action_context_v1(jsonb) to service_role;

-- Complete native owner: immutable replay preserved; I-1 precedes Source locks; group precedes cycle.
create or replace function public.weekly_exceptional_pay_stage_c1_request_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_top_keys constant text[]:=array[
    'schema_version','actor_user_id','family_id','orchestration_run_id',
    'source_cycle_id','client_id','work_event_id','evidence_timesheet_id',
    'expected_family_bound_version','protected_schedule','rate_classification',
    'source_proposal','target_snapshot','current_comparison_revision_id',
    'current_final_revision_id','c1_request','c1_sources','c1_components',
    'reason','idempotency_key'
  ];
  v_c1_keys constant text[]:=array[
    'request_id','request_sequence','actor_user_id','candidate_id','contract_id',
    'root_timesheet_id','week_ending_date','source_mode',
    'expected_head_revision','expected_source_count','expected_component_count',
    'expected_payload_bytes','source_manifest_sha256','entitlement_sha256',
    'approval_sha256','is_zero_entitlement','financial_row_id','request_sha256'
  ];
  v_source_keys constant text[]:=array[
    'source_ordinal','source_id','authority_kind','source_system',
    'external_identity','external_revision','source_document_sha256',
    'payload_bytes','part_count','work_date','root_timesheet_id','candidate_id',
    'contract_id','source_row_sha256','record_type','parts'
  ];
  v_part_keys constant text[]:=array[
    'source_ordinal','part_ordinal','payload_utf8','fragment_sha256','record_type'
  ];
  v_component_keys constant text[]:=array[
    'component_ordinal','component_id','source_ordinal','source_key',
    'component_kind','economic_key_type','economic_key_value',
    'component_member_identity','segment_id','segment_key','segment_stable_key',
    'work_date','reference_number','hours_day','hours_night','hours_sat',
    'hours_sun','hours_bh','additional_code_raw','unit_count','unit_pay_rate',
    -- S7 (WB-007, WB-013, 24 section 5): `adjustment_id` is deliberately absent
    -- from this exact-key allowlist and from the C1 component relation.  An
    -- adjustment is never copied into a head, because an adjustment created
    -- later would make the snapshot stale and create a second owner.  A caller
    -- that still sends the key now fails closed here.
    'unit_charge_rate','expense_code','pay_ex_vat',
    'charge_ex_vat','exclude_from_pay','origin','component_sha256','record_type'
  ];
  v_schedule_keys constant text[]:=array[
    'work_date','start_at_local','end_at_local','break_minutes'
  ];
  v_actor_user_id uuid;
  v_family_id uuid;
  v_run_id uuid;
  v_source_cycle_id uuid;
  v_client_id uuid;
  v_work_event_id uuid;
  v_evidence_timesheet_id uuid;
  v_expected_bound_version bigint;
  v_comparison_revision_id uuid;
  v_final_revision_id uuid;
  v_reason text;
  v_idempotency_key text;
  v_schedule jsonb;
  v_rate_classification jsonb;
  v_source_proposal jsonb;
  v_selected_source_witness jsonb;
  v_target_snapshot jsonb;
  v_component_identity_context jsonb;
  v_component_identity_basis jsonb;
  v_bulk_signed_proof jsonb;
  v_automatic_reconcile_proof jsonb;
  v_start jsonb;
  v_sources jsonb;
  v_components jsonb;
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_lock_family jsonb; v_lock_group uuid;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_root public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_evidence public.timesheets%rowtype;
  v_signed_evidence jsonb;
  v_event public.weekly_work_events%rowtype;
  v_prior_generation public.weekly_exceptional_pay_generations%rowtype;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_publication public.weekly_exceptional_c1_publication_requests%rowtype;
  v_policy jsonb;
  v_source_mode text;
  v_work_date date;
  v_start_at timestamp without time zone;
  v_end_at timestamp without time zone;
  v_break_minutes integer;
  v_expected_source_count integer;
  v_expected_component_count integer;
  v_expected_payload_bytes integer;
  v_request_sequence bigint;
  v_expected_head_revision bigint;
  v_financial_row_id uuid;
  v_request_id uuid;
  v_source_manifest_hash bytea;
  v_entitlement_hash bytea;
  v_outer_approval_hash bytea;
  v_c1_request_hash bytea;
  v_rate_policy_hash bytea;
  v_schedule_hash bytea;
  v_source_proposal_hash bytea;
  v_prior_vector jsonb;
  v_prior_vector_hash bytea;
  v_next_vector jsonb;
  v_next_vector_hash bytea;
  v_fixed_source_hash bytea;
  v_local_approval_hash bytea;
  v_family_event_hash bytea;
  v_target_event_hash bytea;
  v_prior_family_event_hash bytea;
  v_prior_target_event_hash bytea;
  v_issue_ids uuid[]:='{}'::uuid[];
  v_issue_ids_hash bytea;
  v_signed_revision integer;
  v_signed_hash bytea;
  v_signed_at timestamptz;
  v_generation_number integer;
  v_generation_reason text;
  v_family_event_state text;
  v_resulting_lifecycle_state text;
  v_pending_outcome text;
  v_payment_event_kind text;
  v_other_wait_count integer:=0;
  v_family_event_sequence bigint;
  v_family_event_id uuid;
  v_target_event_sequence bigint;
  v_total_pay numeric(12,2):=0;
  v_payload_total bigint:=0;
  v_previous_source_key text:=null;
  v_source_entry jsonb;
  v_part_entry jsonb;
  v_component_entry jsonb;
  v_source_id uuid;
  v_source_ordinal integer;
  v_source_counter integer:=0;
  v_part_ordinal integer;
  v_component_ordinal integer;
  v_part_payload bytea;
  v_part_concat bytea;
  v_source_part_count integer;
  v_source_payload_bytes integer;
  v_source_kind text;
  v_source_document jsonb;
  v_count_client integer:=0;
  v_count_candidate integer:=0;
  v_count_root integer:=0;
  v_count_provider integer:=0;
  v_count_office integer:=0;
  v_step_sequence integer;
  v_request_body_hash bytea;
  v_before_hash bytea;
  v_after_hash bytea;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,v_top_keys||array['bulk_signed_selection_proof','automatic_reconcile_selection_sha256'])
     or not (p_request ?& v_top_keys)
     or p_request->>'schema_version'<>'WEEKLY_PROTECTED_C1_STAGE_REQUEST_V1'
     or pg_catalog.jsonb_typeof(p_request->'protected_schedule')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'rate_classification')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'source_proposal')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'target_snapshot')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'c1_request')<>'object'
     or pg_catalog.jsonb_typeof(p_request->'c1_sources')<>'array'
     or pg_catalog.jsonb_typeof(p_request->'c1_components')<>'array' then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end if;
  if pg_catalog.octet_length(pg_catalog.convert_to(p_request::text,'UTF8'))>4194304 then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_TOO_LARGE' using errcode='54000';
  end if;
  begin
    v_actor_user_id:=(p_request->>'actor_user_id')::uuid;
    v_family_id:=(p_request->>'family_id')::uuid;
    v_run_id:=(p_request->>'orchestration_run_id')::uuid;
    v_source_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_client_id:=(p_request->>'client_id')::uuid;
    v_work_event_id:=(p_request->>'work_event_id')::uuid;
    v_evidence_timesheet_id:=nullif(p_request->>'evidence_timesheet_id','')::uuid;
    v_expected_bound_version:=(p_request->>'expected_family_bound_version')::bigint;
    v_comparison_revision_id:=nullif(p_request->>'current_comparison_revision_id','')::uuid;
    v_final_revision_id:=nullif(p_request->>'current_final_revision_id','')::uuid;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  if pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_idempotency_key) not between 16 and 240 then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_REQUEST_INVALID' using errcode='22023';
  end if;

  v_schedule:=p_request->'protected_schedule';
  if not private.weekly_exceptional_json_keys_exact_v1(v_schedule,v_schedule_keys)
     or not (v_schedule ?& v_schedule_keys) then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end if;
  begin
    v_work_date:=(v_schedule->>'work_date')::date;
    v_start_at:=(v_schedule->>'start_at_local')::timestamp without time zone;
    v_end_at:=(v_schedule->>'end_at_local')::timestamp without time zone;
    v_break_minutes:=(v_schedule->>'break_minutes')::integer;
  exception when others then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end;
  if v_end_at<=v_start_at or v_start_at::date<>v_work_date
     or v_break_minutes<0
     or v_break_minutes>=extract(epoch from (v_end_at-v_start_at))/60 then
    raise exception 'WEEKLY_PROTECTED_SCHEDULE_INVALID' using errcode='22023';
  end if;
  v_rate_classification:=p_request->'rate_classification';
  v_source_proposal:=p_request->'source_proposal';
  v_target_snapshot:=p_request->'target_snapshot';
  if pg_catalog.octet_length(pg_catalog.convert_to(v_rate_classification::text,'UTF8'))>65536
     or pg_catalog.octet_length(pg_catalog.convert_to(v_source_proposal::text,'UTF8'))>65536
     or pg_catalog.octet_length(pg_catalog.convert_to(v_target_snapshot::text,'UTF8'))>1048576 then
    raise exception 'WEEKLY_PROTECTED_TARGET_TOO_LARGE' using errcode='54000';
  end if;

  v_start:=p_request->'c1_request';
  v_sources:=p_request->'c1_sources';
  v_components:=p_request->'c1_components';
  if not private.weekly_exceptional_json_keys_exact_v1(v_start,v_c1_keys)
     or not (v_start ?& v_c1_keys)
     or pg_catalog.jsonb_array_length(v_sources) not between 1 and 65536
     or pg_catalog.jsonb_array_length(v_components)>65536 then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_INVALID' using errcode='22023';
  end if;
  begin
    v_request_id:=(v_start->>'request_id')::uuid;
    v_request_sequence:=(v_start->>'request_sequence')::bigint;
    v_expected_head_revision:=(v_start->>'expected_head_revision')::bigint;
    v_expected_source_count:=(v_start->>'expected_source_count')::integer;
    v_expected_component_count:=(v_start->>'expected_component_count')::integer;
    v_expected_payload_bytes:=(v_start->>'expected_payload_bytes')::integer;
    v_financial_row_id:=(v_start->>'financial_row_id')::uuid;
    v_source_manifest_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'source_manifest_sha256');
    v_entitlement_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'entitlement_sha256');
    v_outer_approval_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'approval_sha256');
    v_c1_request_hash:=private.weekly_exceptional_hex_sha256_v1(v_start->>'request_sha256');
  exception when others then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_INVALID' using errcode='22023';
  end;
  if v_request_sequence<1 or v_expected_head_revision<0
     or v_expected_source_count<>pg_catalog.jsonb_array_length(v_sources)
     or v_expected_component_count<>pg_catalog.jsonb_array_length(v_components)
     or v_expected_payload_bytes<1
     or ((v_start->>'is_zero_entitlement')::boolean is distinct from
         (v_expected_component_count=0)) then
    raise exception 'WEEKLY_PROTECTED_C1_STREAM_COUNT_INVALID' using errcode='22023';
  end if;

  -- An exact staged request is the idempotency authority even after the family
  -- version advances.  A UUID collision with different bytes always refuses.
  select request.* into v_publication
  from public.weekly_exceptional_c1_publication_requests request
  where request.id=v_request_id;
  if found then
    if v_publication.family_id is distinct from v_family_id
       or v_publication.orchestration_run_id is distinct from v_run_id
       or v_publication.request_sha256 is distinct from v_c1_request_hash then
      raise exception 'WEEKLY_PROTECTED_C1_REQUEST_ID_COLLISION' using errcode='23505';
    end if;
    perform private.weekly_source_bulk_stage_replay_assert_v1(v_publication.id,p_request);
    perform private.weekly_source_automatic_reconcile_stage_replay_assert_v1(v_publication.id,p_request);
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','STAGED','idempotent_replay',true,
      'family_id',v_publication.family_id,'generation_id',v_publication.generation_id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_publication.request_sha256,'hex'),
      'state',v_publication.state
    );
  end if;

  v_lock_family:=private.weekly_source_protected_family_lock_v1(v_family_id);
  -- An exact staged request is the idempotency authority even after the family
  -- version advances.  A UUID collision with different bytes always refuses.
  select request.* into v_publication
  from public.weekly_exceptional_c1_publication_requests request
  where request.id=v_request_id
  for update;
  if found then
    if v_publication.family_id is distinct from v_family_id
       or v_publication.orchestration_run_id is distinct from v_run_id
       or v_publication.request_sha256 is distinct from v_c1_request_hash then
      raise exception 'WEEKLY_PROTECTED_C1_REQUEST_ID_COLLISION' using errcode='23505';
    end if;
    perform private.weekly_source_bulk_stage_replay_assert_v1(v_publication.id,p_request);
    perform private.weekly_source_automatic_reconcile_stage_replay_assert_v1(v_publication.id,p_request);
    return pg_catalog.jsonb_build_object(
      'ok',true,'outcome','STAGED','idempotent_replay',true,
      'family_id',v_publication.family_id,'generation_id',v_publication.generation_id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_publication.request_sha256,'hex'),
      'state',v_publication.state
    );
  end if;

  select family.* into strict v_family
  from public.weekly_exceptional_pay_target_families family
  where family.id=v_family_id
  for update;
  select run.* into strict v_run
  from public.weekly_exceptional_orchestration_runs run
  where run.id=v_run_id and run.family_id=v_family.id
  for update;
  if (v_family.root_timesheet_id::text,v_family.candidate_id::text,v_family.contract_id::text,v_family.week_ending_date::text)
    is distinct from (v_lock_family->>'root_timesheet_id',v_lock_family->>'candidate_id',
      v_lock_family->>'contract_id',v_lock_family->>'week_ending_date') then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  v_lock_group:=private.weekly_source_protected_group_lock_v1(v_source_cycle_id);
  if p_request ? 'bulk_signed_selection_proof' or p_request ? 'automatic_reconcile_selection_sha256' then
    -- The new one-shift round seals one pending proof at a time using the
    -- existing cycle mutex; the individual path retains its native SHARE.
    select cycle.* into strict v_cycle from public.weekly_source_cycles cycle
      where cycle.id=v_source_cycle_id for update;
  else
  select cycle.* into strict v_cycle
  from public.weekly_source_cycles cycle
  where cycle.id=v_source_cycle_id
  for share;
  end if;
  if v_cycle.source_group_id is distinct from v_lock_group then
    raise exception 'WEEKLY_SOURCE_PROTECTED_LOCK_SCOPE_CHANGED' using errcode='40001'; end if;
  select source_group.* into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id and source_group.active
  for share;
  perform private.weekly_source_office_authority_v1(
    v_actor_user_id,'APPROVE_PROTECTED_PAY',v_group.id,v_client_id,v_work_date
  );

  if v_run.requested_by_user_id is distinct from v_actor_user_id
     or v_run.state<>'RUNNING'
     or v_run.request_kind not in (
       'APPROVE','AMEND','WITHDRAW','RECONCILE','RECORD_NOT_WORKED'
     )
     or v_family.bound_version<>v_expected_bound_version
     or v_family.c1_publication_state in ('PENDING','PUBLISHING')
     or v_family.agency_id is distinct from v_group.agency_id
     or v_family.root_timesheet_id is null
     or v_work_date not between v_family.week_start_date and v_family.week_ending_date
     or not exists(
       select 1 from public.weekly_source_group_clients membership
       where membership.source_group_id=v_group.id
         and membership.client_id=v_client_id
         and v_work_date between membership.valid_from
           and coalesce(membership.valid_to,'infinity'::date)
     ) then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_SCOPE_INVALID' using errcode='55000';
  end if;

  select timesheet.* into strict v_root
  from public.timesheets timesheet
  where timesheet.timesheet_id=v_family.root_timesheet_id
  for share;
  select financial.* into strict v_fin
  from public.timesheets_financials financial
  where financial.id=v_financial_row_id
    and financial.timesheet_id=v_root.timesheet_id
    and financial.is_current
  for share;
  select event.* into strict v_event
  from public.weekly_work_events event
  where event.id=v_work_event_id
    and event.candidate_id=v_family.candidate_id
    and event.client_id=v_client_id
    and event.work_date=v_work_date
  for share;
  if v_root.contract_id is distinct from v_family.contract_id
     or v_root.week_ending_date is distinct from v_family.week_ending_date
     or v_root.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
     or v_root.line_type<>'HOURS'::public.timesheet_line_type_enum
     or v_root.is_adjustment or not v_root.is_current
     or v_root.revoked_at is not null or v_root.archived_at_utc is not null then
    raise exception 'WEEKLY_PROTECTED_C1_ROOT_INVALID' using errcode='55000';
  end if;

  v_policy:=private._weekly_source_effective_policy_v1(
    v_client_id,v_family.contract_id,v_work_date
  );
  v_source_mode:=v_policy->>'c1_source_mode';
  if v_policy->>'authority_mode'<>'SOURCE_AUTHORITY'
     or coalesce((v_policy->>'self_bill_enabled')::boolean,false) is not true
     or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
     or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_PROTECTED_C1_POLICY_INVALID' using errcode='55000';
  end if;

  -- Existing WITHDRAW/RECONCILE actions accept actual Source, including
  -- certified absence; this does not define any other removal action. A
  -- Final-only synthetic zero proposal is not proof that Source is absent.
  -- Keep replay above this fresh admission check; do not reinterpret a saved
  -- decision after subsequent imports or change the Banking publication owner.
  if v_run.request_kind in ('WITHDRAW','RECONCILE') then
    v_selected_source_witness:=private.weekly_source_selected_source_witness_v1(
      v_family.id,v_cycle.id,v_event.id
    );
    if v_selected_source_witness is null
       or v_selected_source_witness->'source_proposal' is distinct from v_source_proposal
       or (v_selected_source_witness->>'kind'='CURRENT_ROW' and (
         v_selected_source_witness#>>'{basis,final_revision_id}' is null
         or v_selected_source_witness#>>'{basis,final_revision_id}' is distinct from v_source_proposal->>'source_revision'
         or v_source_proposal->'source_present' is distinct from 'true'::jsonb
       ))
       or (v_selected_source_witness->>'kind'='CERTIFIED_ABSENCE' and (
         v_source_proposal->'source_present' is distinct from 'false'::jsonb
         or v_source_proposal->>'source_minutes' is distinct from '0'
       ))
       or coalesce(v_selected_source_witness->>'kind' not in ('CURRENT_ROW','CERTIFIED_ABSENCE'),true) then
      raise exception 'WEEKLY_PROTECTED_C1_SELECTED_SOURCE_UNAVAILABLE' using errcode='55000';
    end if;
  end if;

  if (v_start->>'actor_user_id')::uuid is distinct from v_actor_user_id
     or (v_start->>'candidate_id')::uuid is distinct from v_family.candidate_id
     or (v_start->>'contract_id')::uuid is distinct from v_family.contract_id
     or (v_start->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
     or (v_start->>'week_ending_date')::date is distinct from v_family.week_ending_date
     or v_start->>'source_mode'<>v_source_mode
     or v_financial_row_id is distinct from v_fin.id
     or v_request_sequence<>v_family.current_generation_number+1 then
    raise exception 'WEEKLY_PROTECTED_C1_START_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_family.current_generation_id is null then
    if v_expected_head_revision<>0 then
      raise exception 'WEEKLY_PROTECTED_C1_HEAD_INVALID' using errcode='55000';
    end if;
  else
    select generation.* into strict v_prior_generation
    from public.weekly_exceptional_pay_generations generation
    where generation.id=v_family.current_generation_id
      and generation.family_id=v_family.id
      and generation.lifecycle_state='PUBLISHED'
    for share;
    select request.* into strict v_publication
    from public.weekly_exceptional_c1_publication_requests request
    where request.generation_id=v_prior_generation.id
      and request.family_id=v_family.id
      and (request.state='PUBLISHED' or (request.state='RETIRED' and exists(
        select 1 from private.weekly_source_local_protected_decision_receipts receipt
        where receipt.publication_request_id=request.id and receipt.generation_id=v_prior_generation.id
          and receipt.state='COMPLETE')));
    if (case when v_publication.state='RETIRED' then v_prior_generation.generation_number::bigint
             else v_publication.c1_head_revision end) is distinct from v_expected_head_revision then
      raise exception 'WEEKLY_PROTECTED_C1_HEAD_INVALID' using errcode='55000';
    end if;
    v_publication.id:=null;
  end if;

  if v_evidence_timesheet_id is not null then
    select evidence.* into strict v_evidence
    from public.timesheets evidence
    where evidence.timesheet_id=v_evidence_timesheet_id
      and evidence.contract_id=v_family.contract_id
      and evidence.week_ending_date=v_family.week_ending_date
      and evidence.sheet_scope='WEEKLY'::public.timesheet_scope_enum
      and evidence.is_current and evidence.revoked_at is null
      and evidence.archived_at_utc is null;
    v_signed_evidence:=private.weekly_exceptional_candidate_signed_evidence_v1(
      v_evidence_timesheet_id
    );
    v_signed_at:=(v_signed_evidence->>'signed_at_utc')::timestamptz;
    v_signed_revision:=(v_signed_evidence->>'timesheet_version')::integer;
    v_signed_hash:=private.weekly_exceptional_hex_sha256_v1(
      v_signed_evidence->>'signature_sha256'
    );
  end if;

  select coalesce(pg_catalog.array_agg(incident.id order by incident.id),'{}'::uuid[])
    into v_issue_ids
  from public.weekly_discrepancy_incidents incident
  where incident.source_group_id=v_group.id
    and incident.work_event_id=v_work_event_id
    and incident.candidate_id=v_family.candidate_id
    and incident.client_id=v_client_id;
  v_issue_ids_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_ISSUE_SET_V1',pg_catalog.to_jsonb(v_issue_ids)
  );
  v_schedule_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_SCHEDULE_V1',v_schedule
  );
  v_rate_policy_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_RATE_POLICY_V1',
    pg_catalog.jsonb_build_object(
      'contract_id',v_family.contract_id,
      'rates_json',(select contract.rates_json from public.contracts contract where contract.id=v_family.contract_id),
      'policy',v_policy,'classification',v_rate_classification
    )
  );
  v_source_proposal_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_SOURCE_PROPOSAL_V1',v_source_proposal
  );

  if v_comparison_revision_id is not null and not exists(
    select 1
    from public.weekly_issue_comparison_revisions comparison
    join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
    where comparison.id=v_comparison_revision_id
      and comparison.contract_id=v_family.contract_id
      and incident.source_group_id=v_group.id
      and incident.work_event_id=v_work_event_id
      and incident.candidate_id=v_family.candidate_id
      and incident.client_id=v_client_id
  ) then
    raise exception 'WEEKLY_PROTECTED_COMPARISON_SCOPE_INVALID' using errcode='55000';
  end if;
  if v_final_revision_id is not null and not exists(
    select 1 from public.weekly_source_final_revisions final_revision
    where final_revision.id=v_final_revision_id
      and final_revision.source_cycle_id=v_source_cycle_id
      and final_revision.state='CURRENT'
  ) then
    raise exception 'WEEKLY_PROTECTED_FINAL_SCOPE_INVALID' using errcode='55000';
  end if;

  -- Validate and persist the complete normalized C1 source stream.  The C1
  -- owner independently replays its TLV hashes before certification; these
  -- local checks prevent truncation, reordering or cross-root substitution.
  for v_source_entry in
    select value from pg_catalog.jsonb_array_elements(v_sources)
  loop
    v_source_counter:=v_source_counter+1;
    if not private.weekly_exceptional_json_keys_exact_v1(v_source_entry,v_source_keys)
       or not (v_source_entry ?& v_source_keys)
       or v_source_entry->>'record_type'<>'SOURCE'
       or pg_catalog.jsonb_typeof(v_source_entry->'parts')<>'array' then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_INVALID' using errcode='22023';
    end if;
    begin
      v_source_ordinal:=(v_source_entry->>'source_ordinal')::integer;
      v_source_id:=(v_source_entry->>'source_id')::uuid;
      v_source_payload_bytes:=(v_source_entry->>'payload_bytes')::integer;
      v_source_part_count:=(v_source_entry->>'part_count')::integer;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_INVALID' using errcode='22023';
    end;
    if v_source_ordinal<>v_source_counter
       or v_source_ordinal not between 1 and v_expected_source_count
       or (v_source_entry->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
       or (v_source_entry->>'candidate_id')::uuid is distinct from v_family.candidate_id
       or (v_source_entry->>'contract_id')::uuid is distinct from v_family.contract_id
       or v_source_payload_bytes not between 1 and 16384
       or v_source_part_count<>pg_catalog.jsonb_array_length(v_source_entry->'parts')
       or v_source_part_count not between 1 and 6 then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_SCOPE_INVALID' using errcode='55000';
    end if;
    v_source_kind:=v_source_entry->>'authority_kind';
    if v_source_kind not in (
      'CANDIDATE_SUBMISSION','CLIENT_SOURCE','OFFICE_APPROVAL','ROOT_FINANCIAL',
      'PROVIDER','SOURCE_EXPENSE','ORDINARY_EXPENSE','APPROVED_COMPONENT'
    ) then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_KIND_INVALID' using errcode='22023';
    end if;
    v_count_client:=v_count_client+(v_source_kind='CLIENT_SOURCE')::integer;
    v_count_candidate:=v_count_candidate+(v_source_kind='CANDIDATE_SUBMISSION')::integer;
    v_count_root:=v_count_root+(v_source_kind='ROOT_FINANCIAL')::integer;
    v_count_provider:=v_count_provider+(v_source_kind='PROVIDER')::integer;
    v_count_office:=v_count_office+(v_source_kind='OFFICE_APPROVAL')::integer;
    v_part_concat:=''::bytea;
    v_part_ordinal:=0;
    for v_part_entry in
      select value from pg_catalog.jsonb_array_elements(v_source_entry->'parts')
    loop
      v_part_ordinal:=v_part_ordinal+1;
      if not private.weekly_exceptional_json_keys_exact_v1(v_part_entry,v_part_keys)
         or not (v_part_entry ?& v_part_keys)
         or v_part_entry->>'record_type'<>'PART'
         or (v_part_entry->>'source_ordinal')::integer<>v_source_ordinal
         or (v_part_entry->>'part_ordinal')::integer<>v_part_ordinal
         or coalesce(v_part_entry->>'payload_utf8','')!~'^(?:[0-9a-f]{2})+$' then
        raise exception 'WEEKLY_PROTECTED_C1_PART_INVALID' using errcode='22023';
      end if;
      v_part_payload:=pg_catalog.decode(v_part_entry->>'payload_utf8','hex');
      if pg_catalog.octet_length(v_part_payload) not between 1 and 3072
         or extensions.digest(v_part_payload,'sha256') is distinct from
            private.weekly_exceptional_hex_sha256_v1(v_part_entry->>'fragment_sha256') then
        raise exception 'WEEKLY_PROTECTED_C1_PART_HASH_INVALID' using errcode='22023';
      end if;
      v_part_concat:=v_part_concat||v_part_payload;
    end loop;
    if v_part_ordinal<>v_source_part_count
       or pg_catalog.octet_length(v_part_concat)<>v_source_payload_bytes then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_PAYLOAD_INVALID' using errcode='22023';
    end if;
    begin
      v_source_document:=pg_catalog.convert_from(v_part_concat,'UTF8')::jsonb;
    exception when others then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_DOCUMENT_INVALID' using errcode='22023';
    end;
    if pg_catalog.jsonb_typeof(v_source_document)<>'object'
       or (v_source_document->>'root_timesheet_id')::uuid is distinct from v_root.timesheet_id
       or (v_source_document->>'candidate_id')::uuid is distinct from v_family.candidate_id
       or (v_source_document->>'contract_id')::uuid is distinct from v_family.contract_id
       or (v_source_document->>'week_ending_date')::date is distinct from v_family.week_ending_date
       or v_source_document->>'document_sha256' is distinct from
          v_source_entry->>'source_document_sha256' then
      raise exception 'WEEKLY_PROTECTED_C1_SOURCE_DOCUMENT_SCOPE_INVALID' using errcode='55000';
    end if;
    if v_source_kind='CLIENT_SOURCE'
       and coalesce((v_source_document->>'source_complete')::boolean,false) is not true then
      raise exception 'WEEKLY_PROTECTED_C1_CLIENT_SOURCE_INCOMPLETE' using errcode='55000';
    elsif v_source_kind='ROOT_FINANCIAL'
       and (v_source_document->>'financial_row_id')::uuid is distinct from v_fin.id then
      raise exception 'WEEKLY_PROTECTED_C1_ROOT_FINANCIAL_INVALID' using errcode='55000';
    elsif v_source_kind='OFFICE_APPROVAL'
       and (
         (v_source_document->>'actor_user_id')::uuid is distinct from v_actor_user_id
         or (v_source_document->>'request_id')::uuid is distinct from v_request_id
         or v_source_document->>'entitlement_sha256' is distinct from
            v_start->>'entitlement_sha256'
         or v_source_document->>'decision'<>'APPROVE_ENTITLEMENT'
       ) then
      raise exception 'WEEKLY_PROTECTED_C1_OFFICE_SOURCE_INVALID' using errcode='55000';
    end if;
    v_payload_total:=v_payload_total+v_source_payload_bytes;
  end loop;
  if v_source_counter<>v_expected_source_count
     or v_count_client<1 or v_count_root<>1 or v_count_provider<>1 or v_count_office<>1
     or (v_evidence_timesheet_id is null and v_count_candidate<>0)
     or (v_evidence_timesheet_id is not null and v_count_candidate<>1)
     or v_payload_total<>v_expected_payload_bytes then
    raise exception 'WEEKLY_PROTECTED_C1_SOURCE_CARDINALITY_INVALID' using errcode='55000';
  end if;

  v_component_ordinal:=0;
  for v_component_entry in
    select value from pg_catalog.jsonb_array_elements(v_components)
  loop
    v_component_ordinal:=v_component_ordinal+1;
    if not private.weekly_exceptional_json_keys_exact_v1(v_component_entry,v_component_keys)
       or not (v_component_entry ?& v_component_keys)
       or v_component_entry->>'record_type'<>'COMPONENT'
       or (v_component_entry->>'component_ordinal')::integer<>v_component_ordinal
       or (v_component_entry->>'source_ordinal')::integer not between 1 and v_expected_source_count
       or coalesce(v_component_entry->>'source_key','')=''
       or (v_previous_source_key is not null and v_component_entry->>'source_key'<=v_previous_source_key) then
      raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_INVALID' using errcode='22023';
    end if;
    if nullif(v_component_entry->>'work_date','') is not null
       and (v_component_entry->>'work_date')::date not between
           v_family.week_start_date and v_family.week_ending_date then
      raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_WEEK_INVALID' using errcode='55000';
    end if;
    v_total_pay:=v_total_pay+(v_component_entry->>'pay_ex_vat')::numeric;
    perform private.weekly_exceptional_hex_sha256_v1(v_component_entry->>'component_sha256');
    v_previous_source_key:=v_component_entry->>'source_key';
  end loop;
  if v_component_ordinal<>v_expected_component_count then
    raise exception 'WEEKLY_PROTECTED_C1_COMPONENT_COUNT_INVALID' using errcode='22023';
  end if;
  v_total_pay:=pg_catalog.round(v_total_pay,2);

  if v_family.current_generation_id is null then
    -- Before the prepare owner distinguished empty from published families,
    -- a retry could be recorded as AMEND even though nothing was published.
    -- Preserve that immutable request and permit only its first generation;
    -- never treat an existing staged/published entitlement as an initial one.
    if v_run.request_kind not in ('APPROVE','AMEND')
       or v_family.current_generation_number<>0
       or v_family.current_lifecycle_state<>'PENDING_APPROVAL'
       or exists(select 1 from public.weekly_exceptional_pay_generations existing
         where existing.family_id=v_family.id) then
      raise exception 'WEEKLY_PROTECTED_C1_INITIAL_ACTION_INVALID' using errcode='55000';
    end if;
    v_prior_vector:=pg_catalog.jsonb_build_object(
      'schema_version','WEEKLY_PROTECTED_TARGET_VECTOR_V1',
      'components',pg_catalog.jsonb_build_array(),
      'component_count',0,'is_zero_entitlement',true
    );
    v_generation_number:=1;
    v_generation_reason:='INITIAL_APPROVAL';
  else
    v_prior_vector:=v_prior_generation.complete_next_vector_json;
    v_generation_number:=v_prior_generation.generation_number+1;
    v_generation_reason:=case v_run.request_kind
      when 'AMEND' then 'OFFICE_AMENDMENT'
      when 'WITHDRAW' then 'WITHDRAW'
      when 'RECONCILE' then 'RECONCILE'
      when 'RECORD_NOT_WORKED' then 'RECORD_NOT_WORKED'
      else null end;
    if v_generation_reason is null then
      raise exception 'WEEKLY_PROTECTED_C1_ACTION_INVALID' using errcode='55000';
    end if;
  end if;
  v_family_event_state:=case
    when v_run.request_kind in ('APPROVE','AMEND') then 'WAIT'
    when v_run.request_kind in ('WITHDRAW','RECONCILE') then 'ACCEPTED_SOURCE'
    else 'NOT_WORKED' end;
  if v_run.request_kind='RECORD_NOT_WORKED'
     and coalesce((v_source_proposal->>'source_present')::boolean,true) then
    raise exception 'WEEKLY_PROTECTED_NOT_WORKED_SOURCE_PRESENT' using errcode='55000';
  end if;
  with latest as (
    select family_event.durable_work_event_id,family_event.state,
      pg_catalog.row_number() over (
        partition by family_event.durable_work_event_id
        order by family_event.event_sequence desc
      ) as event_rank
    from public.weekly_exceptional_pay_family_events family_event
    where family_event.family_id=v_family.id
      and family_event.durable_work_event_id<>v_work_event_id
  )
  select pg_catalog.count(*)::integer into v_other_wait_count
  from latest where event_rank=1 and state='WAIT';
  v_resulting_lifecycle_state:=case
    when v_family_event_state='WAIT' or v_other_wait_count>0 then 'WAITING_SOURCE'
    when v_run.request_kind='RECORD_NOT_WORKED' then 'NOT_WORKED'
    else 'RECONCILED' end;
  v_pending_outcome:=case v_family_event_state
    when 'WAIT' then 'WAIT'
    when 'ACCEPTED_SOURCE' then 'ACCEPT_SOURCE'
    else 'RECORD_NOT_WORKED' end;
  v_payment_event_kind:=case v_run.request_kind
    when 'APPROVE' then 'APPROVED'
    when 'AMEND' then 'APPROVED'
    when 'RECORD_NOT_WORKED' then 'RECORDED_NOT_WORKED'
    else 'MATCH_ACCEPTED' end;
  v_prior_vector_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_prior_vector
  );
  v_next_vector:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_PROTECTED_TARGET_VECTOR_V1',
    'target_snapshot',v_target_snapshot,
    'components',v_components,
    'component_count',v_expected_component_count,
    'is_zero_entitlement',(v_expected_component_count=0),
    'entitlement_sha256',v_start->>'entitlement_sha256',
    'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00')
  );
  -- Identity metadata is admitted only against this fresh, actual server
  -- context under the established stage locks, never the caller's manifest.
  -- Matching clocks are not a historical identity-derivation fallback.
  v_component_identity_context:=public.weekly_exceptional_pay_action_context_v1(
    jsonb_build_object('schema_version','WEEKLY_PROTECTED_ACTION_CONTEXT_V1',
      'actor_user_id',v_actor_user_id,'family_id',v_family.id,
      'orchestration_run_id',v_run.id,'source_cycle_id',v_cycle.id,
      'work_event_id',v_event.id,'protected_schedule',v_schedule,
      'evidence_timesheet_id',v_evidence_timesheet_id));
  if v_component_identity_context->>'root_timesheet_id' is distinct from v_root.timesheet_id::text
     or v_component_identity_context#>>'{current_financial,id}' is distinct from v_fin.id::text
     or v_component_identity_context->>'family_bound_version' is distinct from v_expected_bound_version::text
     or v_component_identity_context->'source_proposal' is distinct from v_source_proposal then
    raise exception 'WEEKLY_PROTECTED_COMPONENT_MANIFEST_UNAVAILABLE' using errcode='55000'; end if;
  v_component_identity_basis:=private.weekly_source_protected_component_manifest_v1(
    v_component_identity_context,v_target_snapshot);
  v_next_vector:=v_next_vector||jsonb_build_object(
    'protected_component_identity_basis',v_component_identity_basis);
  -- Seal the common before-position at approval. A later authorised amendment
  -- must not silently replace an entitlement published after this calculation.
  if v_root.authorised_at_server is not null then
    v_next_vector:=v_next_vector||pg_catalog.jsonb_build_object(
      'prior_effective_inventory',private.weekly_source_effective_inventory_v1(v_root.timesheet_id));
  end if;
  if p_request ? 'bulk_signed_selection_proof' then
    v_bulk_signed_proof:=private.weekly_source_bulk_stage_proof_v1(p_request,v_fin.id);
    v_next_vector:=v_next_vector||jsonb_build_object('bulk_signed_selection_proof',v_bulk_signed_proof);
  end if;
  if p_request ? 'automatic_reconcile_selection_sha256' then
    v_automatic_reconcile_proof:=private.weekly_source_automatic_reconcile_stage_proof_v1(p_request);
    v_next_vector:=v_next_vector||jsonb_build_object('automatic_reconcile_proof',v_automatic_reconcile_proof);
  end if;
  v_next_vector_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_next_vector
  );
  v_fixed_source_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FIXED_SOURCE_STATE_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_source_cycle_id,
      'comparison_revision_id',v_comparison_revision_id,
      'final_revision_id',v_final_revision_id,
      'source_proposal_hash',pg_catalog.encode(v_source_proposal_hash,'hex'),
      'financial_row_id',v_fin.id,'financial_timesheet_version',v_fin.timesheet_version
    )
  );
  v_local_approval_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_APPROVAL_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'work_event_id',v_work_event_id,
      'candidate_id',v_family.candidate_id,'client_id',v_client_id,
      'contract_id',v_family.contract_id,'week_ending_date',v_family.week_ending_date,
      'schedule_hash',pg_catalog.encode(v_schedule_hash,'hex'),
      'evidence_timesheet_id',v_evidence_timesheet_id,
      'signed_hash',case when v_signed_hash is null then null else pg_catalog.encode(v_signed_hash,'hex') end,
      'issue_ids_hash',pg_catalog.encode(v_issue_ids_hash,'hex'),
      'rate_policy_hash',pg_catalog.encode(v_rate_policy_hash,'hex'),
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'actor_user_id',v_actor_user_id,'reason',v_reason
    )
  );

  insert into public.weekly_exceptional_payment_approvals(
    pay_target_family_id,work_event_id,evidence_timesheet_id,candidate_id,
    client_id,contract_id,week_ending,protected_work_date,
    protected_start_at_local,protected_end_at_local,protected_break_minutes,
    signed_submission_timesheet_id,signed_submission_revision,
    signed_submission_hash,signed_at_utc,contributing_issue_episode_ids,
    contributing_issue_episode_ids_hash,signed_schedule_fact_hash,
    contract_rate_policy_source_fingerprint,approved_by_user_id,
    approval_reason,source_cycle_id,comparison_revision_id,final_revision_id,
    approved_target_pay_components_json,approved_target_gross,
    creation_orchestration_run_id,approval_hash,creation_idempotency_key
  ) values (
    v_family.id,v_work_event_id,v_evidence_timesheet_id,v_family.candidate_id,
    v_client_id,v_family.contract_id,v_family.week_ending_date,v_work_date,
    v_start_at,v_end_at,v_break_minutes,
    v_evidence_timesheet_id,v_signed_revision,v_signed_hash,v_signed_at,v_issue_ids,
    v_issue_ids_hash,v_schedule_hash,v_rate_policy_hash,v_actor_user_id,
    v_reason,v_source_cycle_id,v_comparison_revision_id,v_final_revision_id,
    v_target_snapshot,v_total_pay,v_run.id,v_local_approval_hash,
    v_idempotency_key||':approval'
  ) returning * into v_approval;

  insert into public.weekly_exceptional_pay_generations(
    family_id,generation_number,prior_generation_id,prior_generation_hash,
    request_idempotency_key,reason,complete_prior_vector_json,
    complete_prior_vector_hash,complete_next_vector_json,complete_next_vector_hash,
    fixed_target_source_state_fingerprint,lifecycle_state
  ) values (
    v_family.id,v_generation_number,v_family.current_generation_id,
    case when v_family.current_generation_id is null then null else v_prior_vector_hash end,
    v_idempotency_key||':generation',v_generation_reason,v_prior_vector,
    v_prior_vector_hash,v_next_vector,v_next_vector_hash,v_fixed_source_hash,'PENDING_C1'
  ) returning * into v_generation;

  select coalesce(max(event_sequence),0)+1,
         (array_agg(event_hash order by event_sequence desc))[1]
    into v_family_event_sequence,v_prior_family_event_hash
  from public.weekly_exceptional_pay_family_events
  where family_id=v_family.id;
  v_family_event_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_FAMILY_EVENT_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'event_sequence',v_family_event_sequence,
      'work_event_id',v_work_event_id,'approval_id',v_approval.id,
      'schedule',v_schedule,'source_proposal_hash',pg_catalog.encode(v_source_proposal_hash,'hex'),
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'prior_event_hash',case when v_prior_family_event_hash is null then null
        else pg_catalog.encode(v_prior_family_event_hash,'hex') end
    )
  );
  insert into public.weekly_exceptional_pay_family_events(
    family_id,event_sequence,durable_work_event_id,evidence_approval_id,
    work_date,start_at_local,end_at_local,break_minutes,rate_classification_json,
    source_proposal_snapshot_json,source_proposal_hash,
    fixed_office_target_snapshot_json,fixed_office_target_hash,state,
    current_comparison_revision_id,current_final_revision_id,office_actor_user_id,
    office_reason,prior_event_hash,event_hash
  ) values (
    v_family.id,v_family_event_sequence,v_work_event_id,v_approval.id,
    v_work_date,v_start_at,v_end_at,v_break_minutes,v_rate_classification,
    v_source_proposal,v_source_proposal_hash,v_schedule,v_schedule_hash,v_family_event_state,
    v_comparison_revision_id,v_final_revision_id,v_actor_user_id,v_reason,
    v_prior_family_event_hash,v_family_event_hash
  ) returning id into v_family_event_id;
  if (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    perform private.bpay_next_protected_current_decision_capture_v1(v_family_event_id);
  end if;

  select coalesce(max(event_sequence),0)+1,
         (array_agg(event_hash order by event_sequence desc))[1]
    into v_target_event_sequence,v_prior_target_event_hash
  from public.weekly_exceptional_pay_target_events
  where family_id=v_family.id;
  v_target_event_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_TARGET_EVENT_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'event_sequence',v_target_event_sequence,
      'approval_id',v_approval.id,'generation_id',v_generation.id,
      'prior_vector_hash',pg_catalog.encode(v_prior_vector_hash,'hex'),
      'next_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'reason',v_generation_reason,'actor_user_id',v_actor_user_id
    )
  );
  insert into public.weekly_exceptional_pay_target_events(
    family_id,approval_id,event_sequence,triggering_comparison_revision_id,
    triggering_final_revision_id,prior_event_fingerprint,
    fixed_target_component_snapshot,current_source_proposal_snapshot,
    complete_prior_family_vector_fingerprint,
    complete_next_family_vector_fingerprint,reason,resulting_lifecycle_state,
    financial_generation_id,actor_user_id,event_hash,idempotency_key
  ) values (
    v_family.id,v_approval.id,v_target_event_sequence,v_comparison_revision_id,
    v_final_revision_id,v_prior_target_event_hash,v_target_snapshot,v_source_proposal,
    v_prior_vector_hash,v_next_vector_hash,v_generation_reason,v_resulting_lifecycle_state,
    v_generation.id,v_actor_user_id,v_target_event_hash,v_idempotency_key||':target-event'
  );
  update public.weekly_exceptional_pending_reconciliation_targets target
  set state=case when v_run.request_kind='WITHDRAW' then 'WITHDRAWN' else 'CONSUMED' end,
      completed_at_utc=pg_catalog.statement_timestamp()
  where target.family_id=v_family.id
    and target.durable_work_event_id=v_work_event_id
    and target.state='ACTIVE';
  if v_family_event_state='WAIT' then
    insert into public.weekly_exceptional_pending_reconciliation_targets(
      family_id,approval_id,durable_work_event_id,incident_id,current_final_revision_id,
      intended_outcome,source_action_policy_target_fingerprint,state
    ) values (
      v_family.id,v_approval.id,v_work_event_id,
      (select incident.id from public.weekly_discrepancy_incidents incident
       where incident.source_group_id=v_group.id and incident.work_event_id=v_work_event_id
       order by incident.episode_number desc limit 1),
      v_final_revision_id,v_pending_outcome,v_fixed_source_hash,'ACTIVE'
    );
  end if;
  insert into public.weekly_exceptional_payment_events(
    family_id,approval_id,event_kind,lifecycle_view,bounded_payload_json,
    idempotency_key
  ) values (
    v_family.id,v_approval.id,v_payment_event_kind,'PENDING_C1',
    pg_catalog.jsonb_build_object(
      'work_event_id',v_work_event_id,'generation_id',v_generation.id,
      'target_vector_hash',pg_catalog.encode(v_next_vector_hash,'hex'),
      'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00')
    ),v_idempotency_key||':payment-event'
  );

  insert into public.weekly_exceptional_c1_publication_requests(
    id,family_id,generation_id,orchestration_run_id,agency_id,candidate_id,
    contract_id,root_timesheet_id,week_ending_date,source_mode,request_sequence,
    expected_head_revision,expected_source_count,expected_component_count,
    expected_payload_bytes,source_manifest_sha256,entitlement_sha256,
    approval_sha256,is_zero_entitlement,financial_row_id,request_sha256,state
  ) values (
    v_request_id,v_family.id,v_generation.id,v_run.id,v_family.agency_id,
    v_family.candidate_id,v_family.contract_id,v_root.timesheet_id,
    v_family.week_ending_date,v_source_mode,v_request_sequence,
    v_expected_head_revision,v_expected_source_count,v_expected_component_count,
    v_expected_payload_bytes,v_source_manifest_hash,v_entitlement_hash,
    v_outer_approval_hash,(v_expected_component_count=0),v_fin.id,
    v_c1_request_hash,'READY'
  ) returning * into v_publication;

  for v_source_entry in select value from pg_catalog.jsonb_array_elements(v_sources)
  loop
    v_source_ordinal:=(v_source_entry->>'source_ordinal')::integer;
    v_source_id:=(v_source_entry->>'source_id')::uuid;
    insert into public.weekly_exceptional_c1_source_records(
      id,publication_request_id,source_ordinal,authority_kind,source_system,
      external_identity,external_revision,source_document_sha256,payload_bytes,
      part_count,work_date,root_timesheet_id,candidate_id,contract_id,
      source_row_sha256
    ) values (
      v_source_id,v_publication.id,v_source_ordinal,v_source_entry->>'authority_kind',
      v_source_entry->>'source_system',v_source_entry->>'external_identity',
      v_source_entry->>'external_revision',
      private.weekly_exceptional_hex_sha256_v1(v_source_entry->>'source_document_sha256'),
      (v_source_entry->>'payload_bytes')::integer,
      (v_source_entry->>'part_count')::integer,
      nullif(v_source_entry->>'work_date','')::date,v_root.timesheet_id,
      v_family.candidate_id,v_family.contract_id,
      private.weekly_exceptional_hex_sha256_v1(v_source_entry->>'source_row_sha256')
    );
    for v_part_entry in select value from pg_catalog.jsonb_array_elements(v_source_entry->'parts')
    loop
      insert into public.weekly_exceptional_c1_source_parts(
        publication_request_id,source_record_id,source_ordinal,part_ordinal,
        payload_utf8,fragment_sha256
      ) values (
        v_publication.id,v_source_id,v_source_ordinal,
        (v_part_entry->>'part_ordinal')::integer,
        pg_catalog.decode(v_part_entry->>'payload_utf8','hex'),
        private.weekly_exceptional_hex_sha256_v1(v_part_entry->>'fragment_sha256')
      );
    end loop;
  end loop;

  for v_component_entry in select value from pg_catalog.jsonb_array_elements(v_components)
  loop
    insert into public.weekly_exceptional_c1_component_records(
      publication_request_id,component_ordinal,component_id,source_ordinal,
      source_key,component_kind,economic_key_type,economic_key_value,
      component_member_identity,segment_id,segment_key,segment_stable_key,
      work_date,reference_number,hours_day,hours_night,hours_sat,hours_sun,
      hours_bh,additional_code_raw,unit_count,unit_pay_rate,unit_charge_rate,
      expense_code,pay_ex_vat,charge_ex_vat,exclude_from_pay,
      origin,component_sha256
    ) values (
      v_publication.id,(v_component_entry->>'component_ordinal')::integer,
      (v_component_entry->>'component_id')::uuid,
      (v_component_entry->>'source_ordinal')::integer,
      v_component_entry->>'source_key',v_component_entry->>'component_kind',
      v_component_entry->>'economic_key_type',v_component_entry->>'economic_key_value',
      v_component_entry->>'component_member_identity',nullif(v_component_entry->>'segment_id',''),
      nullif(v_component_entry->>'segment_key',''),nullif(v_component_entry->>'segment_stable_key',''),
      nullif(v_component_entry->>'work_date','')::date,nullif(v_component_entry->>'reference_number',''),
      nullif(v_component_entry->>'hours_day','')::numeric,
      nullif(v_component_entry->>'hours_night','')::numeric,
      nullif(v_component_entry->>'hours_sat','')::numeric,
      nullif(v_component_entry->>'hours_sun','')::numeric,
      nullif(v_component_entry->>'hours_bh','')::numeric,
      nullif(v_component_entry->>'additional_code_raw',''),
      nullif(v_component_entry->>'unit_count','')::numeric,
      nullif(v_component_entry->>'unit_pay_rate','')::numeric,
      nullif(v_component_entry->>'unit_charge_rate','')::numeric,
      nullif(v_component_entry->>'expense_code',''),
      (v_component_entry->>'pay_ex_vat')::numeric,
      nullif(v_component_entry->>'charge_ex_vat','')::numeric,
      (v_component_entry->>'exclude_from_pay')::boolean,
      v_component_entry->>'origin',
      private.weekly_exceptional_hex_sha256_v1(v_component_entry->>'component_sha256')
    );
  end loop;

  update public.weekly_exceptional_pay_target_families
  set c1_publication_state='PENDING',bound_version=bound_version+1
  where id=v_family.id;

  v_request_body_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_C1_STAGE_REQUEST_BODY_V1',p_request
  );
  v_before_hash:=v_run.before_state_fingerprint;
  v_after_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_PROTECTED_C1_STAGED_STATE_V1',
    pg_catalog.jsonb_build_object(
      'family_id',v_family.id,'generation_id',v_generation.id,
      'publication_request_id',v_publication.id,'request_sha256',
      pg_catalog.encode(v_c1_request_hash,'hex'),'new_bound_version',v_family.bound_version+1
    )
  );
  select coalesce(max(sequence),0)+1 into v_step_sequence
  from public.weekly_exceptional_orchestration_steps where orchestration_run_id=v_run.id;
  insert into public.weekly_exceptional_orchestration_steps(
    orchestration_run_id,sequence,step_kind,idempotency_key,
    allowlisted_owner_name,allowlisted_owner_signature,bounded_request_hash,
    before_state_fingerprint,bounded_owner_response_json,owner_response_hash,
    after_state_fingerprint,outcome,completed_at_utc
  ) values (
    v_run.id,v_step_sequence,'STAGE_C1_REQUEST',v_idempotency_key,
    'public.weekly_exceptional_pay_stage_c1_request_v1','jsonb->jsonb',
    v_request_body_hash,v_before_hash,
    pg_catalog.jsonb_build_object(
      'publication_request_id',v_publication.id,'generation_id',v_generation.id,
      'request_sha256',pg_catalog.encode(v_c1_request_hash,'hex')
    ),v_after_hash,v_after_hash,'COMPLETE',pg_catalog.statement_timestamp()
  );

  if p_request ? 'automatic_reconcile_selection_sha256' then
    -- The assertion reads the actual sealed complete vector and native rows.
    -- Any refusal rolls back this entire stage, including its unaccepted event.
    perform private.weekly_source_automatic_reconcile_certificate_v1(v_publication.id,v_actor_user_id,v_cycle.id);
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'outcome','STAGED','idempotent_replay',false,
    'family_id',v_family.id,'generation_id',v_generation.id,
    'approval_id',v_approval.id,'publication_request_id',v_publication.id,
    'request_sha256',pg_catalog.encode(v_publication.request_sha256,'hex'),
    'source_count',v_expected_source_count,
    'component_count',v_expected_component_count,
    'approved_pay_ex_vat',pg_catalog.to_char(v_total_pay,'FM9999999990.00'),
    'new_family_bound_version',v_family.bound_version+1,'state','READY'
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_PROTECTED_C1_STAGE_SCOPE_INVALID' using errcode='55000';
end;
$function$;
alter function public.weekly_exceptional_pay_stage_c1_request_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_exceptional_pay_stage_c1_request_v1(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.weekly_exceptional_pay_stage_c1_request_v1(jsonb) to service_role;

-- Exact complete signed-week discovery for the checking publication owner.
-- Malformed schedule JSON is not parsed here: per-sheet comparison isolation
-- owns that refusal after its physical family is protected.
create or replace function private.weekly_source_publication_signed_roots_v1(p_publication_id uuid)
returns uuid[] language sql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
  select coalesce(array_agg(distinct sheet.timesheet_id order by sheet.timesheet_id),'{}'::uuid[])
  from public.weekly_source_projection_publications publication
  join public.weekly_source_uploads upload on upload.id=publication.upload_id and upload.source_cycle_id=publication.source_cycle_id
  join public.weekly_source_cycles cycle on cycle.id=publication.source_cycle_id
  join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
  join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
  join public.timesheets sheet on sheet.week_ending_date>=upload.confirmed_coverage_start_local_date
    and sheet.week_ending_date-6<=upload.confirmed_coverage_end_local_date
  join public.contracts contract on contract.id=sheet.contract_id
  where publication.id=p_publication_id and publication.authority_scope_kind='CYCLE'
    and publication.correction_session_id is null
    and sheet.is_current and sheet.revoked_at is null and sheet.archived_at_utc is null
    and sheet.sheet_scope='WEEKLY' and sheet.line_type='HOURS' and sheet.authorised_at_server is null
    and sheet.r2_nurse_key is not null and sheet.img_sha256_nurse is not null
    and (private.weekly_source_checking_client_scope_v1(publication.id) is null
      or contract.client_id=private.weekly_source_checking_client_scope_v1(publication.id))
    and exists(select 1 from public.weekly_source_group_clients member where member.source_group_id=source_group.id
      and member.client_id=contract.client_id
      and member.valid_from<=sheet.week_ending_date and coalesce(member.valid_to,'infinity'::date)>=sheet.week_ending_date-6)
    and (profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
      or (profile.profile_code in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1','ROSTER_WEEKLY_SUMMARY_ACTUAL_V1')
        and private.weekly_source_is_import_authoritative_v1(contract.client_id,contract.id,sheet.week_ending_date)));
$function$;
alter function private.weekly_source_publication_signed_roots_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_publication_signed_roots_v1(uuid) from public,anon,authenticated,service_role;

-- First call before any outer business lock captures and locks I-1 once.
-- Second call after the original owner locks/re-reads its publication/cycle
-- must match all captured selectors and the complete discovery set exactly.
create or replace function private.weekly_source_publication_signed_family_fence_v1(
  p_publication_id uuid,p_before jsonb default null
) returns jsonb language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype; v_cycle public.weekly_source_cycles%rowtype;
  v_roots uuid[]; v_lock jsonb; v_proof jsonb;
begin
  select * into strict v_publication from public.weekly_source_projection_publications where id=p_publication_id;
  select * into strict v_upload from public.weekly_source_uploads where id=v_publication.upload_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_publication.source_cycle_id;
  if v_upload.source_cycle_id is distinct from v_cycle.id then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000'; end if;
  v_roots:=private.weekly_source_publication_signed_roots_v1(v_publication.id);
  v_proof:=jsonb_build_object('publication_id',v_publication.id,'source_cycle_id',v_cycle.id,
    'source_group_id',v_cycle.source_group_id,'upload_id',v_upload.id,'report_scope_id',v_publication.report_scope_id,
    'authority_scope_kind',v_publication.authority_scope_kind,'authority_scope_version',v_publication.authority_scope_version,
    'projection_generation',v_publication.projection_generation,'correction_session_id',v_publication.correction_session_id,
    'source_format_profile_id',v_upload.source_format_profile_id,'coverage_start',v_upload.confirmed_coverage_start_local_date,
    'coverage_end',v_upload.confirmed_coverage_end_local_date,
    'client_id',private.weekly_source_checking_client_scope_v1(v_publication.id),'signed_root_ids',to_jsonb(v_roots));
  if p_before is not null then
    if p_before is distinct from v_proof then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_SIGNED_ROOT_SET_CHANGED' using errcode='40001'; end if;
    return v_proof;
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  if cardinality(v_roots)>0 then
    v_lock:=private.weekly_source_lock_family_rows_v1(v_roots,null);
    if v_lock->>'ok' is distinct from 'true' then
      raise exception '%',coalesce(v_lock->>'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE') using errcode='55000'; end if;
  end if;
  return v_proof;
end;
$function$;
alter function private.weekly_source_publication_signed_family_fence_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_publication_signed_family_fence_v1(uuid,jsonb) from public,anon,authenticated,service_role;

-- Complete existing row reader: carry OPEN questions for dated import-authoritative CYCLE scopes.
-- Native qualified coverage remains the one protection exclusion; immutable comparisons are not rewritten.
create or replace function private.weekly_source_office_query_groups_v1(
  p_source_cycle_id uuid,
  p_projection_publication_id uuid,
  p_filters jsonb default '{}'::jsonb
) returns table(
  group_key text,
  candidate_id uuid,
  client_id uuid,
  manager_recipient_route_key bytea,
  candidate_name text,
  client_name text,
  incident_ids uuid[],
  accept_incident_ids uuid[],
  missing_scopes jsonb,
  children jsonb,
  issue_count integer,
  candidate_asked boolean,
  manager_informed boolean,
  outreach_eligible boolean,
  manager_eligible boolean,
  candidate_app_available boolean,
  first_seen_at_utc timestamptz,
  status_text text,
  status_tone text,
  issue_summary text
)
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  with cycle_context as (
    select cycle.id,cycle.source_group_id,cycle.finalisation_week_ending,
      source_group.environment,source_group.agency_id,source_group.source_family,
      publication.upload_id,
      current_upload.source_format_profile_id,
      current_profile.profile_code,publication.authority_scope_kind,
      private.weekly_source_checking_client_scope_v1(publication.id) checking_client_id
    from public.weekly_source_cycles cycle
    join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
    join public.weekly_source_projection_publications publication
      on publication.id=p_projection_publication_id
     and publication.source_cycle_id=cycle.id
     and publication.state='CURRENT'
    join public.weekly_source_uploads current_upload
      on current_upload.id=publication.upload_id
    join public.weekly_source_format_profiles current_profile
      on current_profile.id=current_upload.source_format_profile_id
    where cycle.id=p_source_cycle_id
  ), incident_facts as (
    select incident.id incident_id,incident.candidate_id,incident.client_id,
      incident.work_event_id,cycle_context.source_group_id,
      incident.candidate_action_state,incident.manager_action_state,
      incident.manager_potential_state,incident.created_at_utc,
      comparison.issue_family,comparison.contract_id,
      comparison.candidate_timesheet_id,comparison.source_presence,comparison.source_row_id,
      comparison.candidate_start_at_local,comparison.candidate_end_at_local,
      comparison.candidate_break_minutes,comparison.system_start_at_local,
      comparison.system_end_at_local,comparison.system_break_minutes,
      work_event.work_date,contract.role job_role,route_context.value route_context,
      candidate_reply.bounded_payload_json->>'choice' candidate_reply_choice,
      candidate_reply.occurred_at_utc candidate_replied_at,
      candidate_delivery.contacted_at_utc candidate_contacted_at,
      manager_reply.bounded_payload_json->>'response_kind' manager_reply_kind,
      manager_reply.occurred_at_utc manager_replied_at,
      manager_delivery.contacted_at_utc manager_contacted_at,
      manager_item.intended_start_at_local,manager_item.intended_end_at_local,
      manager_item.intended_break_minutes
    from cycle_context
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cycle_context.id and incident.state='OPEN'
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_source_uploads comparison_upload
      on comparison_upload.id=comparison.comparison_upload_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    left join public.contracts contract on contract.id=comparison.contract_id
    -- Replies belong to the current incident episode. A prior question's answer
    -- must never be presented as the answer to materially changed hours.
    left join lateral (
      select event.bounded_payload_json,event.occurred_at_utc
      from public.weekly_discrepancy_events event
      where event.incident_id=incident.id and event.issue_episode=incident.episode_number
        and event.event_kind='CANDIDATE_RESPONDED'
        and incident.candidate_action_state='RESPONDED'
      order by event.occurred_at_utc desc,event.id desc limit 1
    ) candidate_reply on true
    left join lateral (
      select min(command.provider_accepted_at_utc) contacted_at_utc
      from public.weekly_candidate_outreach_memberships membership
      join public.weekly_message_dispatch_commands command
        on command.candidate_generation_id=membership.candidate_generation_id
        and command.state='ACCEPTED'
      where membership.incident_id=incident.id
        and membership.comparison_revision_id=incident.current_comparison_revision_id
    ) candidate_delivery on true
    left join lateral (
      select event.bounded_payload_json,event.occurred_at_utc
      from public.weekly_discrepancy_events event
      where event.incident_id=incident.id and event.issue_episode=incident.episode_number
        and event.event_kind='MANAGER_RESPONDED'
        and incident.manager_action_state='RESPONDED'
      order by event.occurred_at_utc desc,event.id desc limit 1
    ) manager_reply on true
    left join lateral (
      select min(command.provider_accepted_at_utc) contacted_at_utc
      from public.weekly_manager_review_items review_item
      join public.weekly_manager_review_batches review_batch on review_batch.id=review_item.review_batch_id
      join public.weekly_message_dispatch_commands command
        on command.message_render_id=review_batch.message_render_id
        and command.state='ACCEPTED'
      where review_item.incident_id=incident.id
        and review_item.incident_episode=incident.episode_number
    ) manager_delivery on true
    left join public.weekly_manager_review_items manager_item
      on manager_item.id=nullif(manager_reply.bounded_payload_json->>'review_item_id','')::uuid
      and manager_item.incident_id=incident.id
      and manager_item.incident_episode=incident.episode_number
    cross join lateral (
      select private.weekly_source_office_route_key_v1(
        incident.source_cycle_id,incident.candidate_id,incident.client_id,
        comparison.contract_id,work_event.work_date
      ) value
    ) route_context
    -- A provisional comparison can remain byte-for-byte unchanged when a new
    -- file covers its date. Its immutable revision still names the prior
    -- publication; visibility is based on the OPEN incident, not a rewrite of
    -- that revision or a second notification clock.
    where comparison.issue_family<>'CANDIDATE_TIMESHEET_MISSING'
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and (cycle_context.checking_client_id is null or incident.client_id=cycle_context.checking_client_id)
      and (comparison.projection_publication_id=p_projection_publication_id
        or (cycle_context.profile_code='NHSP_PREFINAL_RELEASED_V1'
          and comparison_upload.source_cycle_id=cycle_context.id
          and comparison_upload.source_format_profile_id=cycle_context.source_format_profile_id)
        or (cycle_context.authority_scope_kind='CYCLE'
          and comparison_upload.source_cycle_id=cycle_context.id
          and comparison_upload.source_format_profile_id=cycle_context.source_format_profile_id
          and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work_event.work_date)))
  ), manual_facts as (
    select review.*,current_row.id current_source_row_id,
      current_row.normalised_row_hash current_source_row_hash,
      current_row.start_at_local,current_row.end_at_local,
      current_row.break_minutes,contract.role job_role,
      coalesce(nullif(office_user.display_name,''),'Office user') opened_by_name,
      route_context.value route_context
    from cycle_context
    join private.weekly_source_manual_reviews review
      on review.source_cycle_id=cycle_context.id and review.state='OPEN'
    join public.weekly_source_upload_rows source_row on source_row.id=review.upload_row_id
    join public.contracts contract on contract.id=review.contract_id
    left join public.tms_users office_user on office_user.id=review.opened_by_user_id
    left join lateral (
      select candidate_row.*
      from public.weekly_source_upload_rows candidate_row
      join public.weekly_source_uploads candidate_upload on candidate_upload.id=candidate_row.upload_id
      join lateral (
        select mapping.work_event_id,mapping.mapping_state
        from public.weekly_source_row_resolutions mapping
        where mapping.upload_row_id=candidate_row.id
        order by mapping.generation desc,mapping.id desc limit 1
      ) current_mapping on current_mapping.work_event_id=review.work_event_id
        and current_mapping.mapping_state='RESOLVED'
      where candidate_upload.source_cycle_id=review.source_cycle_id
        and candidate_row.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED')
        and (
          exists(select 1 from public.weekly_source_client_manifests manifest
            join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
            where manifest.source_cycle_id=review.source_cycle_id
              and manifest.client_id=review.client_id
              and revision.state='CURRENT' and revision.upload_id=candidate_upload.id)
          or (not exists(select 1 from public.weekly_source_client_manifests manifest
              join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
              where manifest.source_cycle_id=review.source_cycle_id
                and manifest.client_id=review.client_id and revision.state='CURRENT')
            and exists(select 1 from public.weekly_source_projection_publications publication
              where publication.source_cycle_id=review.source_cycle_id
                and publication.upload_id=candidate_upload.id and publication.state='CURRENT'))
        )
      order by candidate_row.created_at_utc desc,candidate_row.id desc limit 1
    ) current_row on true
    cross join lateral (select private.weekly_source_office_route_key_v1(
      review.source_cycle_id,review.candidate_id,review.client_id,
      review.contract_id,review.work_date) value) route_context
    where cycle_context.checking_client_id is null or review.client_id=cycle_context.checking_client_id
  ), missing_rows as (
    select cycle_context.id source_cycle_id,
      resolution.candidate_id,resolution.client_id,resolution.contract_id,
      row.id source_row_id,row.normalised_row_hash,row.work_date,
      row.start_at_local,row.end_at_local,row.break_minutes,row.actual_net_minutes,
      row.row_finalisation_state,row.created_at_utc,resolution.id row_resolution_id,
      resolution.work_event_id,resolution.source_row_fingerprint,
      resolution.contract_and_rate_fingerprint,resolution.effective_policy_fingerprint,
      (date_trunc('week',row.work_date)::date+6) week_ending,
      coalesce(lineage.timesheet_id,root_contract_week.timesheet_id) timesheet_id,
      route_context.value route_context
    from cycle_context
    join public.weekly_source_upload_rows row on row.upload_id=cycle_context.upload_id
    join lateral (
      select candidate.* from public.weekly_source_row_resolutions candidate
      where candidate.upload_row_id=row.id
      order by candidate.generation desc,candidate.id desc limit 1
    ) resolution on resolution.mapping_state='RESOLVED'
    left join public.weekly_source_row_timesheet_lineages lineage
      on lineage.row_resolution_id=resolution.id
    left join lateral (
      select contract_week.timesheet_id
      from public.contract_weeks contract_week
      where contract_week.contract_id=resolution.contract_id
        and contract_week.week_ending_date=(date_trunc('week',row.work_date)::date+6)
        and contract_week.additional_seq=0
        and not contract_week.is_adjustment
        and contract_week.status<>'CANCELLED'::public.contract_week_status_enum
      order by contract_week.created_at desc,contract_week.id desc
      limit 1
    ) root_contract_week on true
    left join public.timesheets timesheet
      on timesheet.timesheet_id=coalesce(lineage.timesheet_id,root_contract_week.timesheet_id)
     and timesheet.is_current and timesheet.revoked_at is null
     and timesheet.archived_at_utc is null
     and timesheet.sheet_scope='WEEKLY' and timesheet.line_type='HOURS'
    cross join lateral (
      select private.weekly_source_office_route_key_v1(
        cycle_context.id,resolution.candidate_id,resolution.client_id,
        resolution.contract_id,row.work_date
      ) value
    ) route_context
    where row.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED')
      and (cycle_context.checking_client_id is null or resolution.client_id=cycle_context.checking_client_id)
      and row.actual_net_minutes>0
      and not exists (
        select 1 from public.weekly_source_client_manifests manifest
        join public.weekly_source_final_revisions final_revision
          on final_revision.id=manifest.final_revision_id
        where manifest.source_cycle_id=cycle_context.id
          and manifest.client_id=resolution.client_id
          and final_revision.state='CURRENT'
      )
      and route_context.value->>'authority_mode'='SOURCE_AUTHORITY'
      and route_context.value->>'document_mode'='CHECK_ONLY'
      and (timesheet.timesheet_id is null
        or timesheet.r2_nurse_key is null or timesheet.img_sha256_nurse is null)
  ), missing_scopes as (
    select missing_rows.source_cycle_id,missing_rows.candidate_id,
      missing_rows.client_id,missing_rows.contract_id,missing_rows.week_ending,
      min(missing_rows.work_date) first_work_date,
      (pg_catalog.array_agg(missing_rows.source_row_id order by
        missing_rows.work_date,missing_rows.start_at_local,
        missing_rows.end_at_local,missing_rows.source_row_id))[1] first_source_row_id,
      min(missing_rows.created_at_utc) first_seen_at_utc,
      (min(missing_rows.route_context->>'route_key'))::text route_key_hex,
      bool_and(coalesce((missing_rows.route_context->>'candidate_queries_enabled')::boolean,false))
        candidate_queries_enabled,
      private.weekly_source_office_missing_scope_fingerprint_v1(
        p_projection_publication_id,missing_rows.candidate_id,missing_rows.client_id,
        missing_rows.contract_id,missing_rows.week_ending
      ) expected_source_fingerprint,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'incident_id',null,'row_key','missing-'||missing_rows.source_row_id::text,
        'day_date',to_char(missing_rows.work_date,'Dy FMDD Mon YYYY'),
        'job_role',coalesce(contract.role,''),
        'candidate_hours','Timesheet not submitted',
        'system_hours',case when missing_rows.start_at_local is null then pg_catalog.chr(8212)
          else to_char(missing_rows.start_at_local,'HH24:MI')||'-'||to_char(missing_rows.end_at_local,'HH24:MI') end,
        'issue','Timesheet missing',
        'status',pg_catalog.jsonb_build_object('text','Waiting for Timesheet','tone','warning'),
        'accept_eligible',false,'actions',pg_catalog.jsonb_build_array('View details')
      ) order by missing_rows.work_date,missing_rows.start_at_local,
        missing_rows.end_at_local,missing_rows.source_row_id) children
    from missing_rows
    join public.contracts contract on contract.id=missing_rows.contract_id
    group by missing_rows.source_cycle_id,missing_rows.candidate_id,
      missing_rows.client_id,missing_rows.contract_id,missing_rows.week_ending
  ), incident_grouped as (
    select (incident_facts.route_context->>'group_key')::text group_key,
      incident_facts.candidate_id,incident_facts.client_id,
      pg_catalog.decode(incident_facts.route_context->>'route_key','hex') manager_recipient_route_key,
      pg_catalog.array_agg(incident_facts.incident_id order by incident_facts.incident_id) incident_ids,
      coalesce(pg_catalog.array_agg(incident_facts.incident_id order by incident_facts.incident_id)
        filter (where incident_facts.route_context->>'authority_mode'='SOURCE_AUTHORITY'),'{}'::uuid[])
        accept_incident_ids,
      min(incident_facts.created_at_utc) first_seen_at_utc,
      bool_or(incident_facts.candidate_action_state in ('ASKED','RESPONDED')) candidate_asked,
      bool_or(incident_facts.manager_action_state in ('SENT','RESPONDED')) manager_informed,
      bool_and(coalesce((incident_facts.route_context->>'candidate_queries_enabled')::boolean,false))
        and bool_or(incident_facts.candidate_action_state<>'NOT_REQUIRED') candidate_queries_enabled,
      bool_and(coalesce((incident_facts.route_context->>'manager_queries_enabled')::boolean,false)
        and coalesce((incident_facts.route_context->>'manager_recipient_present')::boolean,false))
        manager_queries_enabled,
      bool_and((incident_facts.candidate_timesheet_id is not null
        or (private.weekly_source_is_import_authoritative_v1(incident_facts.client_id,incident_facts.contract_id,incident_facts.work_date)
          and (incident_facts.issue_family='HEALTHROSTER_NOT_FINALISED'
            or private.weekly_source_expected_week_question_v1(incident_facts.incident_id))))
        and incident_facts.manager_potential_state='AVAILABLE'
        and incident_facts.manager_action_state not in ('RESPONDED','NOT_REQUIRED')) manager_eligible,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'incident_id',incident_facts.incident_id,
        'candidate_shift_absent_from_import',incident_facts.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED'
          and incident_facts.source_presence='ABSENT' and incident_facts.source_row_id is null
          and incident_facts.candidate_timesheet_id is not null
          and incident_facts.candidate_start_at_local is not null
          and incident_facts.candidate_end_at_local>incident_facts.candidate_start_at_local,
        'candidate_response',case incident_facts.candidate_reply_choice
          when 'CANDIDATE_CORRECT' then 'My hours are correct'
          when 'CANDIDATE_WRONG' then 'Accepted system hours'
          when 'NEITHER_CORRECT' then 'Submitted corrected hours'
          else null end,
        'candidate_responded_at',to_char(incident_facts.candidate_replied_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'candidate_contacted_at',to_char(incident_facts.candidate_contacted_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'manager_response',case incident_facts.manager_reply_kind
          when 'SYSTEM_CORRECT' then 'System hours are correct'
          when 'CANDIDATE_DID_NOT_WORK' then 'Candidate did not work'
          when 'MANAGER_CORRECTED_SOURCE' then 'Reported a source correction'
          else null end,
        'manager_responded_at',to_char(incident_facts.manager_replied_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'manager_contacted_at',to_char(incident_facts.manager_contacted_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'manager_intended_hours',case when incident_facts.manager_reply_kind='MANAGER_CORRECTED_SOURCE'
          then to_char(incident_facts.intended_start_at_local,'HH24:MI')||'-'||to_char(incident_facts.intended_end_at_local,'HH24:MI')
            ||' ('||incident_facts.intended_break_minutes||' min break)' else null end,
        'protected_pay_seed',case when incident_facts.route_context->>'authority_mode'='SOURCE_AUTHORITY'
          then pg_catalog.jsonb_build_object('source_group_id',incident_facts.source_group_id,
            'client_id',incident_facts.client_id,'candidate_id',incident_facts.candidate_id,
            'work_event_id',incident_facts.work_event_id,'contract_id',incident_facts.contract_id,
            'work_date',incident_facts.work_date,
            'start',to_char(coalesce(incident_facts.candidate_start_at_local,incident_facts.system_start_at_local),'HH24:MI'),
            'end',to_char(coalesce(incident_facts.candidate_end_at_local,incident_facts.system_end_at_local),'HH24:MI'),
            'break_minutes',coalesce(incident_facts.candidate_break_minutes,incident_facts.system_break_minutes)) end,
        'row_key','incident-'||incident_facts.incident_id::text,
        'day_date',to_char(incident_facts.work_date,'Dy FMDD Mon YYYY'),
        'job_role',coalesce(incident_facts.job_role,''),
        'candidate_hours',case when incident_facts.candidate_start_at_local is null then 'Timesheet not submitted'
          else to_char(incident_facts.candidate_start_at_local,'HH24:MI')||'-'||to_char(incident_facts.candidate_end_at_local,'HH24:MI')
            ||case when incident_facts.candidate_break_minutes is null then '' else ' ('||incident_facts.candidate_break_minutes||' min break)' end end,
        'system_hours',case when incident_facts.source_presence<>'PRESENT'
          and not (incident_facts.source_presence='UNFINALISED'
            and private.weekly_source_is_import_authoritative_v1(incident_facts.client_id,incident_facts.contract_id,incident_facts.work_date)
            and incident_facts.system_start_at_local is not null
            and incident_facts.system_end_at_local>incident_facts.system_start_at_local) then 'Not included'
          else to_char(incident_facts.system_start_at_local,'HH24:MI')||'-'||to_char(incident_facts.system_end_at_local,'HH24:MI')
            ||case when incident_facts.system_break_minutes is null then '' else ' ('||incident_facts.system_break_minutes||' min break)' end end,
        'issue',case incident_facts.issue_family
          when 'SOURCE_HOURS_DIFFER' then 'Hours differ'
          when 'SOURCE_MISSING_OR_NOT_AUTHORISED' then 'Missing or not yet authorised'
          when 'REFERENCE_MISSING' then 'Reference missing'
          when 'HEALTHROSTER_NOT_FINALISED' then 'Not finalised'
          else 'Needs review' end,
        'status',pg_catalog.jsonb_build_object(
          'text',case when incident_facts.manager_action_state='RESPONDED' then 'Manager responded'
            when incident_facts.manager_action_state='SENT' then 'Manager informed'
            when incident_facts.candidate_action_state='RESPONDED' then 'Candidate responded'
            when incident_facts.candidate_action_state='ASKED' then 'Candidate asked' else 'Needs action' end,
          'tone',case when incident_facts.candidate_action_state='NOT_ASKED' then 'warning' else 'info' end
        ),'accept_eligible',incident_facts.route_context->>'authority_mode'='SOURCE_AUTHORITY',
        'actions',pg_catalog.jsonb_build_array('View details')
      ) order by incident_facts.work_date,
        coalesce(incident_facts.system_start_at_local,incident_facts.candidate_start_at_local),
        incident_facts.incident_id) children,
      pg_catalog.string_agg(distinct case incident_facts.issue_family
        when 'SOURCE_HOURS_DIFFER' then 'Hours differ'
        when 'SOURCE_MISSING_OR_NOT_AUTHORISED' then 'Missing or not yet authorised'
        when 'REFERENCE_MISSING' then 'Reference missing'
        when 'HEALTHROSTER_NOT_FINALISED' then 'Not finalised'
        else 'Needs review' end,', ' order by case incident_facts.issue_family
        when 'SOURCE_HOURS_DIFFER' then 'Hours differ'
        when 'SOURCE_MISSING_OR_NOT_AUTHORISED' then 'Missing or not yet authorised'
        when 'REFERENCE_MISSING' then 'Reference missing'
        when 'HEALTHROSTER_NOT_FINALISED' then 'Not finalised'
        else 'Needs review' end) issue_summary
    from incident_facts
    group by incident_facts.route_context->>'group_key',incident_facts.candidate_id,
      incident_facts.client_id,incident_facts.route_context->>'route_key'
  ), manual_grouped as (
    select (manual.route_context->>'group_key')::text group_key,
      manual.candidate_id,manual.client_id,
      pg_catalog.decode(manual.route_context->>'route_key','hex') manager_recipient_route_key,
      count(*)::integer review_count,min(manual.opened_at_utc) first_seen_at_utc,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'manual_review_id',manual.id,'incident_id',null,
        'source_row_id',manual.current_source_row_id,
        'current_source_row_hash',pg_catalog.encode(manual.current_source_row_hash,'hex'),
        'row_key','manual-'||manual.id::text,
        'day_date',to_char(manual.work_date,'Dy FMDD Mon YYYY'),
        'job_role',manual.job_role,
        'candidate_hours','See candidate Timesheet',
        'system_hours',case when manual.current_source_row_id is null then 'Not in current import'
          else to_char(manual.start_at_local,'HH24:MI')||'-'||
            to_char(manual.end_at_local,'HH24:MI')||' ('||manual.break_minutes||' min break)' end,
        'issue','Manually queried',
        'manual_query',pg_catalog.jsonb_build_object(
          'opened_by',manual.opened_by_name,
          'opened_at_uk',to_char(manual.opened_at_utc at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
          'reason',manual.office_reason),
        'status',pg_catalog.jsonb_build_object('text','Office review','tone','danger'),
        'accept_eligible',false,
        'protected_pay_seed',pg_catalog.jsonb_build_object(
          'source_group_id',manual.source_group_id,
          'client_id',manual.client_id,'candidate_id',manual.candidate_id,
          'work_event_id',manual.work_event_id,'contract_id',manual.contract_id,
          'manual_review_id',manual.id,
          'work_date',manual.work_date,'start',to_char(manual.start_at_local,'HH24:MI'),
          'end',to_char(manual.end_at_local,'HH24:MI'),
          'break_minutes',manual.break_minutes),
        'actions','[]'::jsonb
      ) order by manual.work_date,manual.start_at_local,manual.id) children
    from manual_facts manual
    group by manual.route_context->>'group_key',manual.candidate_id,
      manual.client_id,manual.route_context->>'route_key'
  ), missing_grouped as (
    select private.weekly_source_office_group_key_v1(
        scope.source_cycle_id,scope.candidate_id,scope.client_id,
        pg_catalog.decode(scope.route_key_hex,'hex')
      ) group_key,
      scope.candidate_id,scope.client_id,
      pg_catalog.decode(scope.route_key_hex,'hex') manager_recipient_route_key,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'week_ending',scope.week_ending,'client_id',scope.client_id,
        'contract_id',scope.contract_id,
        'expected_source_fingerprint',pg_catalog.encode(scope.expected_source_fingerprint,'hex')
      ) order by scope.week_ending,scope.client_id,scope.contract_id) scopes,
      min(scope.first_seen_at_utc) first_seen_at_utc,
      bool_and(scope.candidate_queries_enabled) candidate_queries_enabled,
      pg_catalog.jsonb_agg(child.value order by scope.week_ending,scope.contract_id,child.ordinality) children
    from missing_scopes scope
    cross join lateral pg_catalog.jsonb_array_elements(scope.children) with ordinality child(value,ordinality)
    group by scope.source_cycle_id,scope.candidate_id,scope.client_id,scope.route_key_hex
  ), combined as (
    select coalesce(incident.group_key,missing.group_key,manual.group_key) group_key,
      coalesce(incident.candidate_id,missing.candidate_id,manual.candidate_id) candidate_id,
      coalesce(incident.client_id,missing.client_id,manual.client_id) client_id,
      coalesce(incident.manager_recipient_route_key,missing.manager_recipient_route_key,
        manual.manager_recipient_route_key)
        manager_recipient_route_key,
      coalesce(incident.incident_ids,'{}'::uuid[]) incident_ids,
      coalesce(incident.accept_incident_ids,'{}'::uuid[]) accept_incident_ids,
      coalesce(missing.scopes,'[]'::jsonb) missing_scopes,
      coalesce(incident.children,'[]'::jsonb)||coalesce(missing.children,'[]'::jsonb)
        ||coalesce(manual.children,'[]'::jsonb) children,
      coalesce(pg_catalog.array_length(incident.incident_ids,1),0)
        +coalesce(pg_catalog.jsonb_array_length(missing.scopes),0)
        +coalesce(manual.review_count,0) issue_count,
      coalesce(incident.candidate_asked,false) candidate_asked,
      coalesce(incident.manager_informed,false) manager_informed,
      coalesce(incident.candidate_queries_enabled,true)
        and coalesce(missing.candidate_queries_enabled,true) candidate_queries_enabled,
      coalesce(incident.manager_eligible,false)
        and pg_catalog.jsonb_array_length(coalesce(missing.scopes,'[]'::jsonb))=0 manager_eligible,
      least(incident.first_seen_at_utc,missing.first_seen_at_utc,
        manual.first_seen_at_utc) first_seen_at_utc,
      case when manual.review_count>0 and (incident.group_key is not null or missing.group_key is not null)
        then 'Multiple' when manual.review_count>0 then 'Manually queried'
        else coalesce(incident.issue_summary,'Timesheet missing') end issue_summary
    from incident_grouped incident
    full join missing_grouped missing on missing.group_key=incident.group_key
    full join manual_grouped manual on manual.group_key=coalesce(incident.group_key,missing.group_key)
  ), named as (
    select combined.*,coalesce(nullif(candidate.display_name,''),
        nullif(pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name),''),
        candidate.tms_ref,'Candidate') candidate_name,
      client.name client_name,context.environment,
      (select count(*)=1
       from public.candidate_app_global_membership_links membership
       join public.candidate_app_accounts account on account.id=membership.account_id
       where membership.candidate_id=combined.candidate_id
         and membership.state='ACTIVE' and account.status='ACTIVE') candidate_app_available
    from combined
    join public.candidates candidate on candidate.id=combined.candidate_id
    join public.clients client on client.id=combined.client_id
    cross join cycle_context context
  )
  select named.group_key,named.candidate_id,named.client_id,
    named.manager_recipient_route_key,named.candidate_name,named.client_name,
    named.incident_ids,named.accept_incident_ids,named.missing_scopes,named.children,named.issue_count,
    named.candidate_asked,named.manager_informed,
    named.candidate_queries_enabled and named.candidate_app_available
      and (pg_catalog.cardinality(named.incident_ids)>0
        or pg_catalog.jsonb_array_length(named.missing_scopes)>0) outreach_eligible,
    named.manager_eligible,named.candidate_app_available,named.first_seen_at_utc,
    case when not named.candidate_app_available then 'Candidate app unavailable'
      when pg_catalog.jsonb_array_length(named.missing_scopes)>0 then 'Waiting for Timesheet'
      when named.manager_informed then 'Manager informed'
      when named.candidate_asked then 'Candidate asked' else 'Needs action' end status_text,
    case when not named.candidate_app_available then 'warning'
      when named.manager_informed or named.candidate_asked then 'info' else 'warning' end status_tone,
    named.issue_summary
  from named
  where coalesce(p_filters->>'status','UNRESOLVED') in ('UNRESOLVED','ALL')
    and (nullif(pg_catalog.btrim(coalesce(p_filters->>'candidate','')),'') is null
      or private.weekly_source_query_ascii_fold_v1(named.candidate_name)
        like '%'||private.weekly_source_query_ascii_fold_v1(p_filters->>'candidate')||'%')
    and (coalesce(p_filters->>'issue','ALL')='ALL'
      or (p_filters->>'issue'='TIMESHEET_MISSING' and pg_catalog.jsonb_array_length(named.missing_scopes)>0)
      or (p_filters->>'issue'='HOURS_DIFFER' and named.issue_summary like '%Hours differ%')
      or (p_filters->>'issue'='MISSING_SHIFT' and named.issue_summary like '%Missing%'));
$function$;

alter function private.weekly_source_office_query_groups_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_office_query_groups_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;

-- Purpose-bound bulk preview. Claim identity and hours come from the immutable
-- MyTMS submission and its exact comparison fingerprint, never booked/current Rota.
create or replace function private.weekly_source_bulk_signed_claim_v1(p_comparison_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_comparison public.weekly_issue_comparison_revisions%rowtype;
  v_sheet public.timesheets%rowtype; v_workflow public.candidate_submission_workflows%rowtype;
  v_evidence jsonb; v_input jsonb; v_units jsonb; v_schedule jsonb; v_row jsonb;
  v_candidate_start timestamp; v_candidate_end timestamp; v_break integer; v_fingerprint bytea;
  v_matches integer:=0; v_claim jsonb;
begin
  select * into strict v_comparison from public.weekly_issue_comparison_revisions where id=p_comparison_id;
  if v_comparison.candidate_timesheet_id is null then
    raise exception 'WEEKLY_PROTECTED_EVIDENCE_UNSIGNED' using errcode='55000'; end if;
  v_evidence:=private.weekly_exceptional_candidate_signed_evidence_v1(v_comparison.candidate_timesheet_id);
  if v_evidence->>'signature_kind' is distinct from 'CANDIDATE_WORKFLOW' then
    return jsonb_build_object('eligible',false,'code','SIGNED_PAPER_OR_QR','reason','Signed on paper/QR - protect individually'); end if;
  select * into strict v_sheet from public.timesheets where timesheet_id=v_comparison.candidate_timesheet_id;
  select * into strict v_workflow from public.candidate_submission_workflows
    where id=v_sheet.candidate_workflow_id and generation=v_sheet.candidate_workflow_generation;
  if v_comparison.candidate_timesheet_revision is distinct from v_sheet.version
    or v_comparison.contract_id is distinct from v_sheet.contract_id
    or v_workflow.immutable_submission_sha256 is null
    or private._candidate_sha256_jsonb_v1(v_workflow.immutable_submission_json)
      is distinct from v_workflow.immutable_submission_sha256 then
    raise exception 'WEEKLY_PROTECTED_EVIDENCE_INVALID' using errcode='55000'; end if;
  v_input:=v_workflow.immutable_submission_json;
  v_units:=coalesce(v_input->'additional_units_per_day',v_input#>'{timesheet_patch_json,additional_units_per_day}',
    v_input#>'{hours_submission,additional_units_per_day}',v_input#>'{hours_submission,timesheet_patch_json,additional_units_per_day}','{}'::jsonb);
  v_schedule:=private.weekly_source_candidate_app_schedule_v1(coalesce(
    v_input->'actual_schedule_json',v_input->'schedule_json',v_input#>'{timesheet_patch_json,actual_schedule_json}',
    v_input#>'{timesheet_patch_json,schedule_json}',v_input#>'{hours_submission,actual_schedule_json}',
    v_input#>'{hours_submission,schedule_json}',v_input#>'{hours_submission,timesheet_patch_json,actual_schedule_json}',
    v_input#>'{hours_submission,timesheet_patch_json,schedule_json}'),v_units);
  for v_row in select value from jsonb_array_elements(v_schedule) loop
    v_candidate_start:=(v_row->>'date')::date+(v_row->>'start')::time;
    v_candidate_end:=(v_row->>'date')::date+(v_row->>'end')::time;
    if v_candidate_end<=v_candidate_start then v_candidate_end:=v_candidate_end+interval '1 day'; end if;
    v_break:=coalesce(nullif(v_row#>>'{break_entry,break_minutes}','')::integer,
      nullif(v_row#>>'{break_entry,calculated_break_minutes}','')::integer,0);
    v_fingerprint:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_CANDIDATE_SHIFT_V1',jsonb_build_object(
      'timesheet_id',v_sheet.timesheet_id,'timesheet_revision',v_sheet.version,'row_key',v_row->>'row_key',
      'work_date',v_row->>'date','start_at_local',v_candidate_start,'end_at_local',v_candidate_end,
      'break_minutes',v_break,'additional_units',coalesce(v_row->'additional_units','[]'::jsonb)));
    if v_fingerprint=v_comparison.candidate_shift_fingerprint
      and (v_candidate_start,v_candidate_end,v_break) is not distinct from
        (v_comparison.candidate_start_at_local,v_comparison.candidate_end_at_local,v_comparison.candidate_break_minutes) then
      v_matches:=v_matches+1;
      v_claim:=jsonb_build_object('eligible',true,'evidence_timesheet_id',v_sheet.timesheet_id,
        'timesheet_revision',v_sheet.version,'workflow_id',v_workflow.id,'workflow_generation',v_workflow.generation,
        'immutable_submission_sha256',encode(v_workflow.immutable_submission_sha256,'hex'),
        'signature_kind',v_evidence->>'signature_kind','signature_sha256',v_evidence->>'signature_sha256',
        'signed_at_utc',v_evidence->'signed_at_utc','candidate_shift_fingerprint',encode(v_fingerprint,'hex'),
        'week_ending_date',v_sheet.week_ending_date,'work_date',(v_row->>'date')::date,
        'start',v_row->>'start','end',v_row->>'end','break_minutes',v_break,
        'start_at_local',v_candidate_start,'end_at_local',v_candidate_end);
    end if;
  end loop;
  if v_matches<>1 then raise exception 'WEEKLY_PROTECTED_EVIDENCE_INVALID' using errcode='55000'; end if;
  return v_claim;
exception when no_data_found or too_many_rows or invalid_text_representation or datetime_field_overflow
  or numeric_value_out_of_range or invalid_parameter_value then
  raise exception 'WEEKLY_PROTECTED_EVIDENCE_INVALID' using errcode='55000';
end;
$function$;
alter function private.weekly_source_bulk_signed_claim_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_bulk_signed_claim_v1(uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_protect_all_signed_selection_v1(p_source_cycle_id uuid,p_actor_user_id uuid,p_own_stage_context jsonb default null)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_cycle public.weekly_source_cycles%rowtype; v_publication public.weekly_source_projection_publications%rowtype;
  v_row record; v_claim jsonb; v_facts jsonb; v_witness jsonb; v_selection jsonb; v_key text;
  v_eligible jsonb:='[]'::jsonb; v_skipped jsonb:='[]'::jsonb; v_reason text; v_code text; v_count integer; v_clients uuid[]:='{}'::uuid[]; v_cas jsonb; v_own_stage boolean;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_cycle from public.weekly_source_cycles where id=p_source_cycle_id;
  perform private.weekly_source_office_authority_v1(p_actor_user_id,'APPROVE_PROTECTED_PAY',v_cycle.source_group_id,null,v_cycle.finalisation_week_ending);
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=v_cycle.current_projection_publication_id and source_cycle_id=v_cycle.id and state='CURRENT'
      and authority_scope_kind='CYCLE' and correction_session_id is null;
  perform private.weekly_source_query_current_publication_v1(v_cycle.id,v_publication.id);
  for v_row in select incident.id as incident_id,incident.episode_number,incident.candidate_id,incident.client_id,
      incident.work_event_id,comparison.id as comparison_id,comparison.contract_id,comparison.issue_family,
      comparison.material_comparison_fingerprint,work.work_date
    from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
      and comparison.incident_id=incident.id
    join public.weekly_work_events work on work.id=incident.work_event_id and work.candidate_id=incident.candidate_id
      and work.client_id=incident.client_id and work.first_source_group_id=v_cycle.source_group_id
    join public.contracts contract on contract.id=comparison.contract_id and contract.candidate_id=incident.candidate_id
      and contract.client_id=incident.client_id
    where incident.source_cycle_id=v_cycle.id and incident.state='OPEN'
      and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work.work_date)
      and (private.weekly_source_checking_client_scope_v1(v_publication.id) is null
        or incident.client_id=private.weekly_source_checking_client_scope_v1(v_publication.id))
    order by incident.candidate_id,work.id,incident.id
  loop
    v_code:=null; v_reason:=null; v_claim:=null;
    if not (v_row.client_id=any(v_clients)) then v_clients:=array_append(v_clients,v_row.client_id); end if;
    if v_row.issue_family not in ('HEALTHROSTER_NOT_FINALISED','SOURCE_MISSING_OR_NOT_AUTHORISED') then
      v_code:='DECIDE_INDIVIDUALLY'; v_reason:=case v_row.issue_family when 'SOURCE_HOURS_DIFFER'
        then 'Hours differ - decide individually' else 'Review this shift individually' end;
    elsif private.weekly_source_covered_hours_incident_v1(v_row.incident_id) then
      v_code:='ALREADY_PROTECTED'; v_reason:='Already protected';
    else
      -- A bare or partial WAIT is unknown, never treated as unprotected.
      v_own_stage:=exists(select 1 from jsonb_array_elements(p_own_stage_context->'exclusions') exclusion
        where exclusion->>'work_event_id'=v_row.work_event_id::text);
      v_witness:=case when v_own_stage then null else private.weekly_source_protected_wait_witness_v1(v_row.work_event_id,v_cycle.id) end;
      if v_witness is not null then v_code:='ALREADY_PROTECTED'; v_reason:='Already protected'; end if;
      if v_code is null then
        if p_own_stage_context is null then
          v_facts:=private.weekly_source_shift_on_self_bill_v1(v_row.work_event_id,v_cycle.id);
        else
          if to_regprocedure('private.weekly_source_shift_on_self_bill_context_v1(uuid,uuid,jsonb)') is null then
            raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000'; end if;
          execute 'select private.weekly_source_shift_on_self_bill_context_v1($1,$2,$3)' into v_facts
            using v_row.work_event_id,v_cycle.id,p_own_stage_context;
        end if;
        if jsonb_typeof(v_facts) is distinct from 'object' or not (v_facts ?& array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected'])
          or exists(select 1 from unnest(array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected']) field
            where jsonb_typeof(v_facts->field) is distinct from 'boolean') then
          raise exception 'WEEKLY_SOURCE_SELF_BILL_FACTS_UNAVAILABLE' using errcode='55000'; end if;
        if (v_facts->>'s25_pay_selected')::boolean or (v_facts->>'on_accepted_report')::boolean then
          v_code:='ON_SELF_BILL'; v_reason:='Already on the client self-bill';
        end if;
      end if;
      if v_code is null then
        begin
          v_claim:=private.weekly_source_bulk_signed_claim_v1(v_row.comparison_id);
          if v_claim->>'eligible' is distinct from 'true' then v_code:=v_claim->>'code'; v_reason:=v_claim->>'reason'; end if;
        exception when others then
          if sqlerrm='WEEKLY_PROTECTED_EVIDENCE_UNSIGNED' then v_code:='NO_SIGNED_SUBMISSION'; v_reason:='No signed submission';
          elsif sqlerrm='WEEKLY_PROTECTED_EVIDENCE_INVALID' then v_code:='SIGNED_SUBMISSION_UNAVAILABLE'; v_reason:='Signed submission changed - protect individually';
          else raise; end if;
        end;
      end if;
    end if;
    if v_code is not null then
      v_skipped:=v_skipped||jsonb_build_array(jsonb_build_object('incident_id',v_row.incident_id,'work_event_id',v_row.work_event_id,
        'work_date',v_row.work_date,'code',v_code,'reason',v_reason));
    else
      v_eligible:=v_eligible||jsonb_build_array(jsonb_build_object('incident_id',v_row.incident_id,'issue_episode',v_row.episode_number,
        'comparison_revision_id',v_row.comparison_id,'comparison_fingerprint',encode(v_row.material_comparison_fingerprint,'hex'),
        'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,'contract_id',v_row.contract_id,
        'work_event_id',v_row.work_event_id,'claim',v_claim,'self_bill_facts',v_facts));
    end if;
  end loop;
  -- Protected/skipped questions retain their Client in the Source CAS census.
  -- Completing a round must not shrink its original relevant Client authority.
  select coalesce(array_agg(item order by item),'{}'::uuid[]) into v_clients from unnest(v_clients) item;
  v_cas:=private.weekly_source_bulk_source_cas_assert_v1(v_cycle.id,v_clients);
  v_count:=jsonb_array_length(v_eligible);
  v_selection:=jsonb_build_object('contract','WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1','source_cycle_id',v_cycle.id,
    'source_cycle_version',v_cycle.version,'projection_publication_id',v_publication.id,
    'source_cas',v_cas,'eligible',v_eligible,'skipped',v_skipped);
  return v_selection||jsonb_build_object('selection_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_BULK_SIGNED_SELECTION_V1',v_selection),'hex'),'eligible_count',v_count,
    'skipped_count',jsonb_array_length(v_skipped));
end;
$function$;
alter function private.weekly_source_protect_all_signed_selection_v1(uuid,uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_protect_all_signed_selection_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;

-- Nullable legacy rows keep native behavior. A new (a) scope is captured once
-- against the actual generation membership and cannot be repointed on consume.
create or replace function private.weekly_source_not_finalised_due_scope_guard_v1()
returns trigger language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_week date; v_count integer; v_clock timestamptz; v_incident uuid;
begin
  if TG_OP='UPDATE' then
    if OLD.not_finalised_comparison_revision_id is distinct from NEW.not_finalised_comparison_revision_id
      or (OLD.not_finalised_comparison_revision_id is not null and
        (OLD.recipient_generation_id,OLD.candidate_cohort_id,OLD.event_kind,OLD.cohort_started_at_utc,
          OLD.due_at_utc,OLD.trigger_hash,OLD.requested_week_membership_id)
        is distinct from (NEW.recipient_generation_id,NEW.candidate_cohort_id,NEW.event_kind,NEW.cohort_started_at_utc,
          NEW.due_at_utc,NEW.trigger_hash,NEW.requested_week_membership_id)) then
      raise exception 'WEEKLY_SOURCE_NOT_FINALISED_DUE_SCOPE_IMMUTABLE' using errcode='55000'; end if;
    return NEW;
  end if;
  if NEW.not_finalised_comparison_revision_id is null then return NEW; end if;
  select comparison.incident_id,sheet.week_ending_date into strict v_incident,v_week
    from public.weekly_issue_comparison_revisions comparison
    join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
      and incident.current_comparison_revision_id=comparison.id and incident.state='OPEN'
    join public.weekly_candidate_cohorts cohort on cohort.id=NEW.candidate_cohort_id
      and cohort.candidate_id=incident.candidate_id and cohort.source_cycle_id=incident.source_cycle_id
    join public.weekly_manager_recipient_memberships membership on membership.recipient_generation_id=NEW.recipient_generation_id
      and membership.candidate_cohort_id=cohort.id and membership.incident_id=incident.id
      and membership.comparison_revision_id=comparison.id
    join public.weekly_work_events work on work.id=incident.work_event_id
    left join public.timesheets sheet on sheet.timesheet_id=comparison.candidate_timesheet_id
      and sheet.contract_id=comparison.contract_id and work.work_date between sheet.week_ending_date-6 and sheet.week_ending_date
    where comparison.id=NEW.not_finalised_comparison_revision_id
      and (comparison.issue_family='HEALTHROSTER_NOT_FINALISED' or private.weekly_source_expected_week_question_v1(incident.id))
      and private.weekly_source_is_import_authoritative_v1(incident.client_id,comparison.contract_id,work.work_date);
  if v_week is null then
    select count(*),min(expected.week_ending_date) into v_count,v_week
      from public.weekly_issue_comparison_revisions comparison
      join public.weekly_discrepancy_incidents incident on incident.id=comparison.incident_id
      join public.weekly_work_events work on work.id=incident.work_event_id
      join public.contract_weeks expected on expected.contract_id=comparison.contract_id
        and expected.additional_seq=0 and not coalesce(expected.is_adjustment,false)
        and expected.status in ('PLANNED','OPEN','SUBMITTED')
        and work.work_date between expected.week_ending_date-6 and expected.week_ending_date
      where comparison.id=NEW.not_finalised_comparison_revision_id;
    if v_count<>1 then raise exception 'WEEKLY_SOURCE_NOT_FINALISED_DUE_SCOPE_INVALID' using errcode='55000'; end if;
  end if;
  v_clock:=((v_week+(8-extract(isodow from v_week)::integer))::timestamp at time zone 'Europe/London');
  if NEW.event_kind is distinct from 'EARLY_ALL' or NEW.requested_week_membership_id is not null
    or NEW.due_at_utc is null or not isfinite(NEW.due_at_utc) or NEW.due_at_utc<v_clock then
    raise exception 'WEEKLY_SOURCE_NOT_FINALISED_DUE_SCOPE_INVALID' using errcode='55000'; end if;
  return NEW;
exception when no_data_found or too_many_rows then
  raise exception 'WEEKLY_SOURCE_NOT_FINALISED_DUE_SCOPE_INVALID' using errcode='55000';
end;
$function$;
