  for each row execute function private.weekly_source_not_finalised_due_scope_guard_v1();

-- Root owns both readiness and the actual shared Source/Report CAS census.
-- Presence is not qualification. No fake readiness or CAS implementation here.
create or replace function private.weekly_source_bulk_source_cas_assert_v1(p_cycle_id uuid,p_client_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ready boolean; v_cas jsonb; v_clients uuid[];
begin
  if p_client_ids is null or array_position(p_client_ids,null::uuid) is not null then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='22023'; end if;
  select coalesce(array_agg(distinct item order by item),'{}'::uuid[]) into v_clients from unnest(p_client_ids) item;
  if to_regprocedure('private.weekly_source_bulk_producer_ready_v1(uuid)') is null
    or to_regprocedure('private.weekly_source_bulk_source_cas_v1(uuid,uuid[])') is null then
    raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_bulk_producer_ready_v1($1)' into v_ready using p_cycle_id;
  if v_ready is distinct from true then raise exception 'WEEKLY_SOURCE_BULK_PRODUCER_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_bulk_source_cas_v1($1,$2)' into v_cas using p_cycle_id,v_clients;
  if not private.weekly_exceptional_json_keys_exact_v1(v_cas,array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or not(v_cas ?& array['schema_version','source_cycle_id','client_ids','source_cas_sha256'])
    or v_cas->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_SOURCE_CAS_V1'
    or v_cas->>'source_cycle_id' is distinct from p_cycle_id::text
    or v_cas->'client_ids' is distinct from to_jsonb(v_clients)
    or coalesce(v_cas->>'source_cas_sha256','') !~ '^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CAS_INVALID' using errcode='55000'; end if;
  return v_cas;
end;
$function$;
alter function private.weekly_source_bulk_source_cas_assert_v1(uuid,uuid[]) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_bulk_source_cas_assert_v1(uuid,uuid[]) from public,anon,authenticated,service_role;

-- Exact immutable staged generation only. Never accepts a receipt, flags or
-- claimed booleans from a browser, and never excludes another pending WAIT.
create or replace function private.weekly_source_bulk_stage_replay_assert_v1(p_request_id uuid,p_stage_request jsonb)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_vector jsonb; v_hash bytea; v_proof jsonb; v_input jsonb;
begin
  select generation.complete_next_vector_json,generation.complete_next_vector_hash into strict v_vector,v_hash
    from public.weekly_exceptional_c1_publication_requests request
    join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id and generation.family_id=request.family_id
    where request.id=p_request_id;
  v_proof:=v_vector->'bulk_signed_selection_proof'; v_input:=p_stage_request->'bulk_signed_selection_proof';
  if not (p_stage_request ? 'bulk_signed_selection_proof') and not (v_vector ? 'bulk_signed_selection_proof') then return; end if;
  if not (p_stage_request ? 'bulk_signed_selection_proof') or not (v_vector ? 'bulk_signed_selection_proof')
    or not private.weekly_exceptional_json_keys_exact_v1(v_input,array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or not(v_input ?& array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or v_proof->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_STAGED_PROOF_V1'
    or v_proof->>'actor_user_id' is distinct from p_stage_request->>'actor_user_id'
    or v_proof->>'source_cycle_id' is distinct from p_stage_request->>'source_cycle_id'
    or v_input->>'expected_selection_sha256' is distinct from v_proof->>'selection_sha256'
    or v_input->>'expected_source_cas_sha256' is distinct from v_proof#>>'{source_cas,source_cas_sha256}'
    or v_input->>'incident_id' is distinct from v_proof#>>'{eligible_claim,incident_id}'
    or v_input->>'bulk_request_key' is distinct from v_proof->>'bulk_request_key'
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_STAGED_PROOF_V1',v_proof-'proof_sha256')
      is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'proof_sha256')
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_vector) is distinct from v_hash then
    raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505'; end if;
exception when no_data_found or too_many_rows or invalid_text_representation then
  raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505';
end;
$function$;
alter function private.weekly_source_bulk_stage_replay_assert_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_bulk_stage_replay_assert_v1(uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_bulk_own_stage_v1(
  p_request_id uuid,p_actor_id uuid,p_cycle_id uuid,p_bulk_key text,p_selection_sha256 text,p_source_cas_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare r public.weekly_exceptional_c1_publication_requests%rowtype;
  g public.weekly_exceptional_pay_generations%rowtype; a public.weekly_exceptional_payment_approvals%rowtype;
  run public.weekly_exceptional_orchestration_runs%rowtype; family public.weekly_exceptional_pay_target_families%rowtype;
  v_proof jsonb; v_claim jsonb; v_cas jsonb; v_clients uuid[]; v_event uuid; v_count integer;
begin
  select * into strict r from public.weekly_exceptional_c1_publication_requests where id=p_request_id;
  select * into strict g from public.weekly_exceptional_pay_generations where id=r.generation_id and family_id=r.family_id;
  select * into strict run from public.weekly_exceptional_orchestration_runs where id=r.orchestration_run_id and family_id=r.family_id;
  select * into strict family from public.weekly_exceptional_pay_target_families where id=r.family_id;
  select * into strict a from public.weekly_exceptional_payment_approvals
    where creation_orchestration_run_id=run.id and pay_target_family_id=family.id;
  v_proof:=g.complete_next_vector_json->'bulk_signed_selection_proof';
  v_claim:=v_proof->'eligible_claim';
  if v_proof->>'schema_version' is distinct from 'WEEKLY_SOURCE_BULK_STAGED_PROOF_V1'
    or v_proof->>'actor_user_id' is distinct from p_actor_id::text
    or v_proof->>'source_cycle_id' is distinct from p_cycle_id::text
    or v_proof->>'bulk_request_key' is distinct from p_bulk_key
    or v_proof->>'selection_sha256' is distinct from p_selection_sha256
    or v_proof#>>'{source_cas,source_cas_sha256}' is distinct from p_source_cas_sha256
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_STAGED_PROOF_V1',v_proof-'proof_sha256')
      is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'proof_sha256')
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',g.complete_next_vector_json)
      is distinct from g.complete_next_vector_hash
    or r.state is distinct from 'READY' or g.lifecycle_state is distinct from 'PENDING_C1'
    or run.state is distinct from 'RUNNING' or run.request_kind not in ('APPROVE','AMEND')
    or run.requested_by_user_id is distinct from p_actor_id or a.approved_by_user_id is distinct from p_actor_id
    or a.source_cycle_id is distinct from p_cycle_id or a.withdrawn_at_utc is not null
    or r.candidate_id is distinct from a.candidate_id or r.contract_id is distinct from a.contract_id
    or r.root_timesheet_id is distinct from family.root_timesheet_id
    or r.request_sha256 is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'request_sha256')
    or r.financial_row_id::text is distinct from v_proof->>'financial_row_id'
    or a.work_event_id::text is distinct from v_claim->>'work_event_id'
    or a.comparison_revision_id::text is distinct from v_claim->>'comparison_revision_id'
    or a.signed_submission_timesheet_id::text is distinct from v_claim#>>'{claim,evidence_timesheet_id}'
    or a.signed_submission_revision::text is distinct from v_claim#>>'{claim,timesheet_revision}'
    or encode(a.signed_submission_hash,'hex') is distinct from v_claim#>>'{claim,signature_sha256}'
    or v_claim#>>'{claim,signature_kind}' is distinct from 'CANDIDATE_WORKFLOW'
    or a.approved_target_pay_components_json is distinct from g.complete_next_vector_json->'target_snapshot'
    or encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_TARGET_SNAPSHOT_V1',a.approved_target_pay_components_json),'hex')
      is distinct from v_proof->>'target_snapshot_sha256'
    or family.current_generation_id is distinct from g.prior_generation_id
    or family.current_generation_number+1 is distinct from g.generation_number
    or exists(select 1 from private.weekly_source_local_protected_decision_receipts receipt where receipt.publication_request_id=r.id)
    or exists(select 1 from public.weekly_exceptional_c1_publication_checkpoints checkpoint where checkpoint.publication_request_id=r.id)
    or exists(select 1 from public.weekly_exceptional_c1_unknown_outcomes outcome where outcome.publication_request_id=r.id and outcome.state='RECOVERY_REQUIRED') then
    raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
  select count(*),min(event.id::text)::uuid into v_count,v_event from public.weekly_exceptional_pay_family_events event
    where event.family_id=family.id and event.evidence_approval_id=a.id and event.durable_work_event_id=a.work_event_id and event.state='WAIT'
      and not exists(select 1 from public.weekly_exceptional_pay_family_events newer where newer.family_id=family.id
        and newer.durable_work_event_id=a.work_event_id and newer.event_sequence>event.event_sequence);
  if v_count<>1 or (a.protected_work_date,a.protected_start_at_local,a.protected_end_at_local,a.protected_break_minutes)
    is distinct from ((v_claim#>>'{claim,work_date}')::date,(v_claim#>>'{claim,start_at_local}')::timestamp,
      (v_claim#>>'{claim,end_at_local}')::timestamp,(v_claim#>>'{claim,break_minutes}')::integer) then
    raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
  if private.weekly_source_bulk_signed_claim_v1(a.comparison_revision_id) is distinct from v_claim->'claim' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  select array_agg(value::uuid order by value::uuid) into v_clients from jsonb_array_elements_text(v_proof#>'{source_cas,client_ids}') value;
  v_cas:=private.weekly_source_bulk_source_cas_assert_v1(p_cycle_id,v_clients);
  if v_cas is distinct from v_proof->'source_cas' then
    raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
  return jsonb_build_object('work_event_id',a.work_event_id,'publication_request_id',r.id,'generation_id',g.id,
    'approval_id',a.id,'family_id',family.id,'proof_sha256',v_proof->>'proof_sha256');
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range then
  raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_bulk_own_stage_v1(uuid,uuid,uuid,text,text,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_bulk_own_stage_v1(uuid,uuid,uuid,text,text,text) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_bulk_own_stage_context_v1(
  p_cycle_id uuid,p_actor_id uuid,p_bulk_key text,p_selection_sha256 text,p_source_cas_sha256 text
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_row record; v_exclusions jsonb:='[]'::jsonb; v_clients jsonb;
begin
  for v_row in select request.id,generation.complete_next_vector_json->'bulk_signed_selection_proof' as proof
    from public.weekly_exceptional_c1_publication_requests request
    join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
    where generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,bulk_request_key}'=p_bulk_key
      and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,actor_user_id}'=p_actor_id::text
      and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,source_cycle_id}'=p_cycle_id::text
      and request.state='READY' and generation.lifecycle_state='PENDING_C1'
    order by request.id
  loop
    if v_clients is null then v_clients:=v_row.proof#>'{source_cas,client_ids}';
    elsif v_clients is distinct from v_row.proof#>'{source_cas,client_ids}' then
      raise exception 'WEEKLY_SOURCE_BULK_OWN_STAGE_UNAVAILABLE' using errcode='55000'; end if;
    v_exclusions:=v_exclusions||jsonb_build_array(private.weekly_source_bulk_own_stage_v1(v_row.id,p_actor_id,p_cycle_id,
      p_bulk_key,p_selection_sha256,p_source_cas_sha256));
  end loop;
  if jsonb_array_length(v_exclusions)=0 then return null; end if;
  return jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_OWN_STAGE_CONTEXT_V1','source_cycle_id',p_cycle_id,
    'actor_user_id',p_actor_id,'bulk_request_key',p_bulk_key,'selection_sha256',p_selection_sha256,
    'source_cas_sha256',p_source_cas_sha256,'client_ids',v_clients,'exclusions',v_exclusions);
end;
$function$;
alter function private.weekly_source_bulk_own_stage_context_v1(uuid,uuid,text,text,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_bulk_own_stage_context_v1(uuid,uuid,text,text,text) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_bulk_stage_proof_v1(p_stage jsonb,p_financial_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_request jsonb:=p_stage->'bulk_signed_selection_proof'; v_context jsonb; v_selection jsonb; v_item jsonb; v_proof jsonb;
  v_count integer; v_run public.weekly_exceptional_orchestration_runs%rowtype;
begin
  if not private.weekly_exceptional_json_keys_exact_v1(v_request,array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or not(v_request ?& array['expected_selection_sha256','expected_source_cas_sha256','incident_id','bulk_request_key'])
    or coalesce(v_request->>'expected_selection_sha256','') !~ '^[0-9a-f]{64}$'
    or coalesce(v_request->>'expected_source_cas_sha256','') !~ '^[0-9a-f]{64}$'
    or coalesce(v_request->>'bulk_request_key','') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='22023'; end if;
  select * into strict v_run from public.weekly_exceptional_orchestration_runs where id=(p_stage->>'orchestration_run_id')::uuid;
  if v_run.request_kind not in ('APPROVE','AMEND') or v_run.state is distinct from 'RUNNING'
    or v_run.requested_by_user_id::text is distinct from p_stage->>'actor_user_id' then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='55000'; end if;
  v_context:=private.weekly_source_bulk_own_stage_context_v1((p_stage->>'source_cycle_id')::uuid,(p_stage->>'actor_user_id')::uuid,
    v_request->>'bulk_request_key',v_request->>'expected_selection_sha256',v_request->>'expected_source_cas_sha256');
  if v_context is not null then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_ALREADY_STAGED' using errcode='55000'; end if;
  v_selection:=private.weekly_source_protect_all_signed_selection_v1((p_stage->>'source_cycle_id')::uuid,(p_stage->>'actor_user_id')::uuid,v_context);
  if v_selection->>'selection_sha256' is distinct from v_request->>'expected_selection_sha256'
    or v_selection#>>'{source_cas,source_cas_sha256}' is distinct from v_request->>'expected_source_cas_sha256' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  select count(*),jsonb_agg(value)->0 into v_count,v_item from jsonb_array_elements(v_selection->'eligible') value
    where value->>'incident_id'=v_request->>'incident_id';
  if v_count<>1 or v_item->>'work_event_id' is distinct from p_stage->>'work_event_id'
    or v_item->>'client_id' is distinct from p_stage->>'client_id'
    or v_item#>>'{claim,evidence_timesheet_id}' is distinct from p_stage->>'evidence_timesheet_id'
    or v_item->>'comparison_revision_id' is distinct from p_stage->>'current_comparison_revision_id'
    or (v_item#>>'{claim,work_date}')::date is distinct from (p_stage#>>'{protected_schedule,work_date}')::date
    or (v_item#>>'{claim,start_at_local}')::timestamp is distinct from (p_stage#>>'{protected_schedule,start_at_local}')::timestamp
    or (v_item#>>'{claim,end_at_local}')::timestamp is distinct from (p_stage#>>'{protected_schedule,end_at_local}')::timestamp
    or (v_item#>>'{claim,break_minutes}')::integer is distinct from (p_stage#>>'{protected_schedule,break_minutes}')::integer then
    raise exception 'WEEKLY_SOURCE_BULK_STAGE_PROOF_INVALID' using errcode='55000'; end if;
  v_proof:=jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_STAGED_PROOF_V1','actor_user_id',p_stage->>'actor_user_id',
    'source_cycle_id',p_stage->>'source_cycle_id','bulk_request_key',v_request->>'bulk_request_key',
    'selection_sha256',v_selection->>'selection_sha256','source_cas',v_selection->'source_cas',
    'eligible_claim',v_item,'financial_row_id',p_financial_id,
    'request_sha256',p_stage#>>'{c1_request,request_sha256}','target_snapshot_sha256',
    encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_TARGET_SNAPSHOT_V1',p_stage->'target_snapshot'),'hex'));
  return v_proof||jsonb_build_object('proof_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BULK_STAGED_PROOF_V1',v_proof),'hex'));
end;
$function$;
alter function private.weekly_source_bulk_stage_proof_v1(jsonb,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_bulk_stage_proof_v1(jsonb,uuid) from public,anon,authenticated,service_role;

-- One shift per bounded round. Initial claims and round results reuse native
-- append-only audit_events; no command/receipt table or financial calculation.
create or replace function public.weekly_source_protect_all_signed_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_cycle_id uuid; v_mode text; v_phase text; v_key text; v_object text; v_initial jsonb;
  v_cycle public.weekly_source_cycles%rowtype; v_group uuid; v_selection jsonb; v_context jsonb; v_stage jsonb;
  v_request public.weekly_exceptional_c1_publication_requests%rowtype; v_generation public.weekly_exceptional_pay_generations%rowtype;
  v_proof jsonb; v_own jsonb; v_lock jsonb; v_gate jsonb; v_result jsonb; v_response jsonb; v_refusal text;
  v_claim jsonb; v_remaining jsonb:='[]'::jsonb; v_done jsonb:='[]'::jsonb; v_current jsonb; v_count integer;
  v_round_key text; v_source_cas text; v_selection_sha text; v_completed boolean; v_initial_claim jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,array['actor_user_id','source_cycle_id','mode','phase',
    'bulk_request_key','expected_selection_sha256','staged'])
    or jsonb_typeof(p_request) is distinct from 'object' or octet_length(convert_to(p_request::text,'UTF8'))>262144 then
    raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
  begin v_actor:=(p_request->>'actor_user_id')::uuid; v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
  exception when invalid_text_representation then raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end;
  v_mode:=p_request->>'mode'; v_phase:=coalesce(p_request->>'phase','ADMIT'); v_key:=p_request->>'bulk_request_key';
  select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY',v_cycle.source_group_id,null,v_cycle.finalisation_week_ending);
  if v_mode='PREVIEW' then
    if p_request ? 'staged' or p_request ? 'phase' then raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
    return jsonb_build_object('ok',true,'mode','PREVIEW')||private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,null);
  end if;
  if v_mode is distinct from 'COMMIT' or v_phase not in ('ADMIT','ROUND','APPLY')
    or coalesce(v_key,'') !~ '^[A-Za-z0-9:_-]{16,120}$' then
    raise exception 'WEEKLY_SOURCE_BULK_REQUEST_INVALID' using errcode='22023'; end if;
  v_object:=v_cycle_id::text||':'||v_actor::text||':'||v_key;
  select audit.after_json into v_initial from public.audit_events audit
    where audit.object_type='weekly_source_bulk_signed_command' and audit.object_id_text=v_object
      and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  if v_phase='ADMIT' then
    -- No family/gate call is made in this phase. The original cycle mutex owns
    -- admission idempotence, and is released before Worker preparation starts.
    perform 1 from public.weekly_source_groups where id=v_cycle.source_group_id for share;
    v_group:=v_cycle.source_group_id;
    select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id for update;
    if v_cycle.source_group_id is distinct from v_group then
      raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
    select audit.after_json into v_initial from public.audit_events audit
      where audit.object_type='weekly_source_bulk_signed_command' and audit.object_id_text=v_object
        and audit.action='WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED' and audit.event_sequence_is_authoritative
      order by audit.event_sequence desc limit 1;
    if v_initial is not null then
      if v_initial#>>'{initial_selection,selection_sha256}' is distinct from p_request->>'expected_selection_sha256' then
        raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505'; end if;
      return jsonb_build_object('ok',true,'phase','ADMITTED','idempotent_replay',true,'initial_selection',v_initial->'initial_selection');
    end if;
    v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,null);
    if v_selection->>'selection_sha256' is distinct from p_request->>'expected_selection_sha256' then
      raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
    v_initial:=jsonb_build_object('schema_version','WEEKLY_SOURCE_BULK_COMMAND_V1','actor_user_id',v_actor,
      'source_cycle_id',v_cycle_id,'bulk_request_key',v_key,'initial_selection',v_selection);
    perform public._audit_insert('weekly_source_bulk_signed_command',v_object,'WEEKLY_SOURCE_BULK_SIGNED_COMMAND_ADMITTED',
      null,v_initial,'Protect signed MyTMS submissions',v_actor);
    return jsonb_build_object('ok',true,'phase','ADMITTED','idempotent_replay',false,'initial_selection',v_selection);
  end if;
  if v_initial is null then raise exception 'WEEKLY_SOURCE_BULK_COMMAND_NOT_ADMITTED' using errcode='55000'; end if;
  if v_phase='ROUND' then
    -- Resume the exact pending generation before deriving another round.
    select generation.complete_next_vector_json->'bulk_signed_selection_proof' into v_proof
      from public.weekly_exceptional_c1_publication_requests request
      join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
      where generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,bulk_request_key}'=v_key
        and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,actor_user_id}'=v_actor::text
        and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,source_cycle_id}'=v_cycle_id::text
        and request.state='READY' and generation.lifecycle_state='PENDING_C1'
      order by request.id limit 1;
    if v_proof is not null then
      v_context:=private.weekly_source_bulk_own_stage_context_v1(v_cycle_id,v_actor,v_key,
        v_proof->>'selection_sha256',v_proof#>>'{source_cas,source_cas_sha256}');
    end if;
    v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,v_context);
    if v_selection#>>'{source_cas,source_cas_sha256}' is distinct from v_initial#>>'{initial_selection,source_cas,source_cas_sha256}' then
      raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
    for v_initial_claim in select value from jsonb_array_elements(v_initial#>'{initial_selection,eligible}') loop
      -- A completed disposition is accepted only from this command's actual
      -- immutable native stage proof and local completion receipt.
      select exists(select 1 from public.weekly_exceptional_c1_publication_requests request
        join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
        join private.weekly_source_local_protected_decision_receipts receipt on receipt.publication_request_id=request.id
          and receipt.actor_user_id=v_actor and receipt.request_sha256=request.request_sha256 and receipt.state in ('COMPLETE','PENDING_FREEZE')
        where generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,bulk_request_key}'=v_key
          and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,actor_user_id}'=v_actor::text
          and generation.complete_next_vector_json#>>'{bulk_signed_selection_proof,source_cycle_id}'=v_cycle_id::text
          and generation.complete_next_vector_json#>'{bulk_signed_selection_proof,eligible_claim}'=v_initial_claim
          and private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',generation.complete_next_vector_json)=generation.complete_next_vector_hash
          and receipt.result_json->>'ok'='true') into v_completed;
      if v_completed then v_done:=v_done||jsonb_build_array(v_initial_claim->'work_event_id'); continue; end if;
      select count(*),jsonb_agg(value)->0 into v_count,v_current from jsonb_array_elements(v_selection->'eligible') value
        where value->>'work_event_id'=v_initial_claim->>'work_event_id';
      if v_count<>1 or v_current is distinct from v_initial_claim then
        raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLAIM_CHANGED' using errcode='40001'; end if;
      v_remaining:=v_remaining||jsonb_build_array(v_current);
    end loop;
    return jsonb_build_object('ok',true,'phase','ROUND','selection',v_selection,'remaining',v_remaining,'completed_work_event_ids',v_done,
      'pending_stages',coalesce(v_context->'exclusions','[]'::jsonb),'max_stages_per_round',1);
  end if;
  if jsonb_typeof(p_request->'staged') is distinct from 'array' or jsonb_array_length(p_request->'staged')<>1 then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='22023'; end if;
  v_stage:=p_request#>'{staged,0}';
  if not private.weekly_exceptional_json_keys_exact_v1(v_stage,array['publication_request_id','request_sha256'])
    or not(v_stage ?& array['publication_request_id','request_sha256']) then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='22023'; end if;
  select * into strict v_request from public.weekly_exceptional_c1_publication_requests where id=(v_stage->>'publication_request_id')::uuid;
  select * into strict v_generation from public.weekly_exceptional_pay_generations where id=v_request.generation_id;
  v_proof:=v_generation.complete_next_vector_json->'bulk_signed_selection_proof';
  v_selection_sha:=v_proof->>'selection_sha256'; v_source_cas:=v_proof#>>'{source_cas,source_cas_sha256}';
  v_round_key:=v_request.id::text;
  -- Exact audit replay precedes mutable freshness checks and locks.
  select audit.after_json into v_response from public.audit_events audit where audit.object_type='weekly_source_bulk_signed_command'
    and audit.object_id_text=v_object and audit.action='WEEKLY_SOURCE_BULK_SIGNED_ROUND_COMPLETED'
    and audit.after_json->>'publication_request_id'=v_round_key and audit.event_sequence_is_authoritative
    order by audit.event_sequence desc limit 1;
  if v_response is not null then
    if v_response->>'request_sha256' is distinct from v_stage->>'request_sha256' then
      raise exception 'WEEKLY_SOURCE_BULK_REPLAY_CONFLICT' using errcode='23505'; end if;
    return v_response||jsonb_build_object('idempotent_replay',true);
  end if;
  -- Complete round has one real family. Every Candidate gate comes first;
  -- native I-1 still receives the complete round set and owns its raw order.
  perform private.weekly_source_pay_query_admit_v2();
  v_gate:=private.weekly_source_candidate_serial_gate_v1(v_request.candidate_id,'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',
    v_request.id,'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if v_gate->>'ok' is distinct from 'true' then return v_gate||jsonb_build_object('phase','BLOCKED','accepted',false); end if;
  if not exists(select 1 from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
    where sheet.timesheet_id=v_request.root_timesheet_id and contract.candidate_id=v_request.candidate_id) then
    raise exception 'WEEKLY_SOURCE_BULK_ROOT_CANDIDATE_MISMATCH' using errcode='55000'; end if;
  v_lock:=private.weekly_source_lock_family_rows_v1(array[v_request.root_timesheet_id],null);
  if v_lock->>'ok' is distinct from 'true' then return v_lock||jsonb_build_object('phase','BLOCKED','accepted',false); end if;
  v_group:=v_cycle.source_group_id;
  perform 1 from public.weekly_source_groups where id=v_group and active for update;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_cycle_id for update;
  if v_cycle.source_group_id is distinct from v_group then raise exception 'WEEKLY_SOURCE_BULK_SOURCE_CHANGED' using errcode='40001'; end if;
  v_own:=private.weekly_source_bulk_own_stage_v1(v_request.id,v_actor,v_cycle_id,v_key,v_selection_sha,v_source_cas);
  if v_request.request_sha256 is distinct from private.weekly_exceptional_hex_sha256_v1(v_stage->>'request_sha256')
    or not exists(select 1 from jsonb_array_elements(v_initial#>'{initial_selection,eligible}') original
      where original=v_proof->'eligible_claim') then
    raise exception 'WEEKLY_SOURCE_BULK_ORIGINAL_CLAIM_CHANGED' using errcode='40001'; end if;
  v_context:=private.weekly_source_bulk_own_stage_context_v1(v_cycle_id,v_actor,v_key,v_selection_sha,v_source_cas);
  if jsonb_array_length(v_context->'exclusions') is distinct from 1
    or v_context#>>'{exclusions,0,publication_request_id}' is distinct from v_request.id::text then
    raise exception 'WEEKLY_SOURCE_BULK_ROUND_INVALID' using errcode='55000'; end if;
  v_selection:=private.weekly_source_protect_all_signed_selection_v1(v_cycle_id,v_actor,v_context);
  if v_selection->>'selection_sha256' is distinct from v_selection_sha
    or v_source_cas is distinct from v_initial#>>'{initial_selection,source_cas,source_cas_sha256}' then
    raise exception 'WEEKLY_SOURCE_BULK_SELECTION_CHANGED' using errcode='40001'; end if;
  begin
    v_result:=public.weekly_exceptional_pay_complete_local_v1(jsonb_build_object('schema_version','WEEKLY_PROTECTED_LOCAL_COMPLETE_V1',
      'actor_user_id',v_actor,'publication_request_id',v_request.id,'expected_request_sha256',v_stage->>'request_sha256',
      'idempotency_key',(select idempotency_key from public.weekly_exceptional_orchestration_runs where id=v_request.orchestration_run_id)||':local-complete'));
    if v_result->>'ok' is distinct from 'true' or v_result->>'outcome' not in ('PUBLISHED','SAVED_PENDING_FREEZE') then
      raise exception 'WEEKLY_SOURCE_BULK_NATIVE_COMPLETE_REFUSED' using errcode='55000'; end if;
  exception when others then
    v_refusal:=coalesce(substring(sqlerrm from '^[A-Z][A-Z0-9_]{0,119}$'),'PROTECTION_REFUSED');
    return jsonb_build_object('ok',false,'phase','PARTIAL','publication_request_id',v_request.id,
      'work_event_id',v_proof#>'{eligible_claim,work_event_id}','code',v_refusal,'completed',false,'retryable',true);
  end;
  v_response:=jsonb_build_object('ok',true,'phase','ROUND_COMPLETED','publication_request_id',v_request.id,
    'request_sha256',v_stage->>'request_sha256','work_event_id',v_proof#>'{eligible_claim,work_event_id}',
    'native_result',v_result,'whole_command_atomic',false);
  perform public._audit_insert('weekly_source_bulk_signed_command',v_object,'WEEKLY_SOURCE_BULK_SIGNED_ROUND_COMPLETED',
    null,v_response,'Protected from the signed MyTMS submission',v_actor);
  return v_response;
end;
$function$;
alter function public.weekly_source_protect_all_signed_atomic_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_protect_all_signed_atomic_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_protect_all_signed_atomic_v1(jsonb) to service_role;

-- S18b uses native approved vectors. Root supplies the qualified capability
-- and full-component delta assertion; their mere presence never certifies £0.
create or replace function private.weekly_source_automatic_reconcile_capability_assert_v1(p_cycle_id uuid)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_ready boolean;
begin
  if to_regprocedure('private.weekly_source_automatic_reconcile_producer_ready_v1(uuid)') is null
    or to_regprocedure('private.weekly_source_automatic_reconcile_delta_assert_v1(uuid,uuid)') is null then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_automatic_reconcile_producer_ready_v1($1)' into v_ready using p_cycle_id;
  if v_ready is distinct from true then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
end;
$function$;
alter function private.weekly_source_automatic_reconcile_capability_assert_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_automatic_reconcile_capability_assert_v1(uuid) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_automatic_reconcile_selection_v1(p_cycle_id uuid,p_event_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_cycle public.weekly_source_cycles%rowtype; v_work public.weekly_work_events%rowtype;
  v_wait jsonb; v_rules jsonb; v_facts jsonb; v_source jsonb; v_segment jsonb; v_count integer;
  v_start timestamp; v_end timestamp; v_selection jsonb; v_cas jsonb; v_inventory jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  select * into strict v_cycle from public.weekly_source_cycles where id=p_cycle_id;
  select * into strict v_work from public.weekly_work_events where id=p_event_id and first_source_group_id=v_cycle.source_group_id;
  v_wait:=private.weekly_source_protected_wait_witness_v1(v_work.id,v_cycle.id);
  if v_wait is null then return jsonb_build_object('eligible',false,'code','NO_QUALIFIED_WAIT'); end if;
  if not private.weekly_source_is_import_authoritative_v1(v_work.client_id,(v_wait->>'contract_id')::uuid,v_work.work_date) then
    return jsonb_build_object('eligible',false,'code','OUTSIDE_IMPORT_AUTHORITY'); end if;
  v_rules:=private.weekly_source_effective_rule_set_v1(v_work.client_id,v_cycle.id);
  if v_rules#>>'{values,invoice_sender}' is distinct from 'CLIENT_SELF_BILL'
    or v_rules#>>'{values,equal_protected_hours}' is distinct from 'CLEAR_AUTOMATICALLY' then
    return jsonb_build_object('eligible',false,'code','AUTOMATIC_CLEAR_NOT_ENABLED'); end if;
  v_facts:=private.weekly_source_shift_on_self_bill_v1(v_work.id,v_cycle.id);
  if jsonb_typeof(v_facts) is distinct from 'object'
    or not(v_facts ?& array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected'])
    or exists(select 1 from unnest(array['on_accepted_report','bound_to_finalised_export','invoice_ready','s25_pay_selected']) k
      where jsonb_typeof(v_facts->k) is distinct from 'boolean') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_FACTS_UNAVAILABLE' using errcode='55000'; end if;
  if not (v_facts->>'bound_to_finalised_export')::boolean
    or not coalesce(((v_rules#>>'{values,self_bill_source}'='SAME_FILE' and (v_facts->>'s25_pay_selected')::boolean)
      or (v_rules#>>'{values,self_bill_source}'='SEPARATE_FINAL_REPORT' and (v_facts->>'on_accepted_report')::boolean)),false) then
    return jsonb_build_object('eligible',false,'code','SELF_BILL_NOT_BOUND_TO_FINAL_SOURCE'); end if;
  v_source:=private.weekly_source_protected_final_source_context_v1((v_wait->>'family_id')::uuid,v_cycle.id,v_work.id);
  if v_source#>>'{source_proposal,source_present}' is distinct from 'true'
    or coalesce(v_source#>>'{source_proposal,source_hash}','') !~ '^[0-9a-f]{64}$'
    or nullif(v_source#>>'{source_proposal,source_revision}','') is null
    or jsonb_typeof(v_source->'source_segments') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
  select count(*),jsonb_agg(item)->0 into v_count,v_segment from jsonb_array_elements(v_source->'source_segments') item
    where item->>'work_event_id'=v_work.id::text;
  if v_count<>1 or v_segment->>'date' is distinct from v_work.work_date::text
    or coalesce(v_segment->>'start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or coalesce(v_segment->>'end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or coalesce(v_segment->>'break_mins','') !~ '^[0-9]+$' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SOURCE_UNAVAILABLE' using errcode='55000'; end if;
  v_start:=v_work.work_date+(v_segment->>'start')::time;
  v_end:=v_work.work_date+(v_segment->>'end')::time;
  if v_end<=v_start then v_end:=v_end+interval '1 day'; end if;
  if (v_start,v_end,(v_segment->>'break_mins')::integer,(v_source#>>'{source_proposal,source_minutes}')::integer)
    is distinct from ((v_wait->>'protected_start_at_local')::timestamp,(v_wait->>'protected_end_at_local')::timestamp,
      (v_wait->>'protected_break_minutes')::integer,(v_wait->>'protected_net_minutes')::integer) then
    return jsonb_build_object('eligible',false,'code','PROTECTED_SOURCE_HOURS_DIFFER',
      'reason','Hours differ — decide individually'); end if;
  select automatic_reconcile_actor_user_id into strict v_actor from public.weekly_source_global_settings where singleton;
  if v_actor is null or not private.weekly_source_pay_actor_allowed_v1(v_actor) then
    return jsonb_build_object('eligible',false,'code','AUTOMATIC_ACTOR_UNAVAILABLE',
      'reason','Hours match — Accept source hours and reconcile'); end if;
  perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY',v_cycle.source_group_id,v_work.client_id,v_work.work_date);
  v_inventory:=private.weekly_source_effective_inventory_v1((v_wait->>'root_timesheet_id')::uuid);
  if v_inventory->>'ok' is distinct from 'true' or v_inventory#>>'{approval_basis,coverage_complete}' is distinct from 'true'
    or v_inventory#>>'{approval_basis,scope,root_timesheet_id}' is distinct from v_wait->>'root_timesheet_id'
    or v_inventory#>>'{approval_basis,scope,target_family_id}' is distinct from v_wait->>'family_id'
    or v_inventory#>>'{approval_basis,scope,candidate_id}' is distinct from v_work.candidate_id::text
    or v_inventory#>>'{approval_basis,scope,client_id}' is distinct from v_work.client_id::text then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  v_cas:=private.weekly_source_bulk_source_cas_assert_v1(v_cycle.id,array[v_work.client_id]);
  v_selection:=jsonb_build_object('schema_version','WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SELECTION_V1','eligible',true,
    'actor_user_id',v_actor,'source_cycle_id',v_cycle.id,'work_event_id',v_work.id,'qualified_wait',v_wait,
    'rule_set_version_id',v_rules->'rule_set_version_id','rule_values_sha256',v_rules->'values_sha256',
    'source_proposal',v_source->'source_proposal','self_bill_facts',v_facts,'source_cas',v_cas,
    'approved_inventory_basis',v_inventory->'approval_basis');
  return v_selection||jsonb_build_object('selection_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SELECTION_V1',v_selection),'hex'));
exception when no_data_found or too_many_rows or invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SOURCE_UNAVAILABLE' using errcode='55000';
end;
$function$;
alter function private.weekly_source_automatic_reconcile_selection_v1(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_automatic_reconcile_selection_v1(uuid,uuid) from public,anon,authenticated,service_role;

-- Called before the stage appends its unaccepted ACCEPTED_SOURCE event.
create or replace function private.weekly_source_automatic_reconcile_stage_replay_assert_v1(p_request_id uuid,p_stage_request jsonb)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_vector jsonb; v_hash bytea; v_proof jsonb;
begin
  select generation.complete_next_vector_json,generation.complete_next_vector_hash into strict v_vector,v_hash
    from public.weekly_exceptional_c1_publication_requests request
    join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id and generation.family_id=request.family_id
    where request.id=p_request_id;
  v_proof:=v_vector->'automatic_reconcile_proof';
  if not(p_stage_request ? 'automatic_reconcile_selection_sha256') and not(v_vector ? 'automatic_reconcile_proof') then return; end if;
  if not(p_stage_request ? 'automatic_reconcile_selection_sha256') or not(v_vector ? 'automatic_reconcile_proof')
    or v_proof->>'selection_sha256' is distinct from p_stage_request->>'automatic_reconcile_selection_sha256'
    or v_proof->>'actor_user_id' is distinct from p_stage_request->>'actor_user_id'
    or v_proof->>'source_cycle_id' is distinct from p_stage_request->>'source_cycle_id'
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SELECTION_V1',v_proof-'selection_sha256')
      is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'selection_sha256')
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_vector) is distinct from v_hash then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_REPLAY_CONFLICT' using errcode='23505'; end if;
end;
$function$;
alter function private.weekly_source_automatic_reconcile_stage_replay_assert_v1(uuid,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_automatic_reconcile_stage_replay_assert_v1(uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_automatic_reconcile_stage_proof_v1(p_stage_request jsonb)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_selection jsonb; v_run public.weekly_exceptional_orchestration_runs%rowtype;
begin
  perform private.weekly_source_automatic_reconcile_capability_assert_v1((p_stage_request->>'source_cycle_id')::uuid);
  select * into strict v_run from public.weekly_exceptional_orchestration_runs where id=(p_stage_request->>'orchestration_run_id')::uuid;
  v_selection:=private.weekly_source_automatic_reconcile_selection_v1((p_stage_request->>'source_cycle_id')::uuid,(p_stage_request->>'work_event_id')::uuid);
  if v_selection->>'eligible' is distinct from 'true' or v_run.request_kind is distinct from 'RECONCILE'
    or v_run.state is distinct from 'RUNNING' or v_run.requested_by_user_id::text is distinct from v_selection->>'actor_user_id'
    or p_stage_request->>'actor_user_id' is distinct from v_selection->>'actor_user_id'
    or p_stage_request->>'family_id' is distinct from v_selection#>>'{qualified_wait,family_id}'
    or p_stage_request->>'expected_family_bound_version' is distinct from v_selection#>>'{qualified_wait,family_bound_version}'
    or p_stage_request->'source_proposal' is distinct from v_selection->'source_proposal'
    or p_stage_request->>'automatic_reconcile_selection_sha256' is distinct from v_selection->>'selection_sha256'
    or p_stage_request ? 'bulk_signed_selection_proof' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SELECTION_CHANGED' using errcode='40001'; end if;
  return v_selection;
end;
$function$;
alter function private.weekly_source_automatic_reconcile_stage_proof_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_automatic_reconcile_stage_proof_v1(jsonb) from public,anon,authenticated,service_role;

create or replace function private.weekly_source_automatic_reconcile_certificate_v1(p_request_id uuid,p_actor_id uuid,p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_certificate jsonb; v_generation public.weekly_exceptional_pay_generations%rowtype; v_proof jsonb;
begin
  perform private.weekly_source_automatic_reconcile_capability_assert_v1(p_cycle_id);
  select generation.* into strict v_generation from public.weekly_exceptional_c1_publication_requests request
    join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id and generation.family_id=request.family_id
    where request.id=p_request_id;
  v_proof:=v_generation.complete_next_vector_json->'automatic_reconcile_proof';
  if v_proof->>'actor_user_id' is distinct from p_actor_id::text or v_proof->>'source_cycle_id' is distinct from p_cycle_id::text
    or v_proof->>'eligible' is distinct from 'true'
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SELECTION_V1',v_proof-'selection_sha256')
      is distinct from private.weekly_exceptional_hex_sha256_v1(v_proof->>'selection_sha256')
    or private.weekly_source_sha256_jsonb_v1('WEEKLY_PROTECTED_COMPLETE_VECTOR_V1',v_generation.complete_next_vector_json)
      is distinct from v_generation.complete_next_vector_hash then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  execute 'select private.weekly_source_automatic_reconcile_delta_assert_v1($1,$2)' into v_certificate using p_request_id,p_actor_id;
  if not private.weekly_exceptional_json_keys_exact_v1(v_certificate,array['schema_version','publication_request_id','actor_user_id',
      'prior_inventory_digest','complete_next_vector_sha256','delta_pay_ex_vat','qualification_sha256'])
    or not(v_certificate ?& array['schema_version','publication_request_id','actor_user_id','prior_inventory_digest',
      'complete_next_vector_sha256','delta_pay_ex_vat','qualification_sha256'])
    or v_certificate->>'schema_version' is distinct from 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_V1'
    or v_certificate->>'publication_request_id' is distinct from p_request_id::text
    or v_certificate->>'actor_user_id' is distinct from p_actor_id::text
    or v_certificate->>'prior_inventory_digest' is distinct from v_generation.complete_next_vector_json#>>'{prior_effective_inventory,inventory_digest}'
    or v_certificate->>'complete_next_vector_sha256' is distinct from encode(v_generation.complete_next_vector_hash,'hex')
    or v_certificate->>'delta_pay_ex_vat' is distinct from '0.00'
    or coalesce(v_certificate->>'qualification_sha256','') !~ '^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  return v_certificate;
end;
$function$;
alter function private.weekly_source_automatic_reconcile_certificate_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_automatic_reconcile_certificate_v1(uuid,uuid,uuid) from public,anon,authenticated,service_role;

-- No route/dispatcher is mounted by this package. Trusted Worker preflight
-- runs before preparation. Only a native PUBLISHED completion claims clearing.
create or replace function public.weekly_source_automatic_reconcile_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_cycle uuid; v_event uuid; v_actor uuid; v_selection jsonb; v_mode text; v_count integer;
  r public.weekly_exceptional_c1_publication_requests%rowtype; g public.weekly_exceptional_pay_generations%rowtype;
  run public.weekly_exceptional_orchestration_runs%rowtype; v_proof jsonb; v_gate jsonb; v_lock jsonb;
  v_source_group uuid; v_certificate jsonb; v_result jsonb; v_replay jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if jsonb_typeof(p_request) is distinct from 'object' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_REQUEST_INVALID' using errcode='22023'; end if;
  if not private.weekly_exceptional_json_keys_exact_v1(p_request,array['source_cycle_id','work_event_id','mode','publication_request_id','request_sha256'])
    or not(p_request ?& array['source_cycle_id','work_event_id','mode']) then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_REQUEST_INVALID' using errcode='22023'; end if;
  v_cycle:=(p_request->>'source_cycle_id')::uuid; v_event:=(p_request->>'work_event_id')::uuid; v_mode:=p_request->>'mode';
  if v_cycle is null or v_event is null or v_mode is null or v_mode not in ('PREVIEW','COMPLETE') then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_REQUEST_INVALID' using errcode='22023'; end if;
  perform private.weekly_source_automatic_reconcile_capability_assert_v1(v_cycle);
  select automatic_reconcile_actor_user_id into strict v_actor from public.weekly_source_global_settings where singleton;
  if v_actor is null or not private.weekly_source_pay_actor_allowed_v1(v_actor) then
    return jsonb_build_object('ok',false,'eligible',false,'code','AUTOMATIC_ACTOR_UNAVAILABLE',
      'reason','Hours match — Accept source hours and reconcile'); end if;
  if v_mode='PREVIEW' then
    if p_request ? 'publication_request_id' or p_request ? 'request_sha256' then
      raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_REQUEST_INVALID' using errcode='22023'; end if;
    select count(*) into v_count from public.weekly_exceptional_c1_publication_requests request
      join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
      where request.state='READY' and generation.lifecycle_state='PENDING_C1'
        and generation.complete_next_vector_json#>>'{automatic_reconcile_proof,actor_user_id}'=v_actor::text
        and generation.complete_next_vector_json#>>'{automatic_reconcile_proof,source_cycle_id}'=v_cycle::text
        and generation.complete_next_vector_json#>>'{automatic_reconcile_proof,work_event_id}'=v_event::text;
    if v_count>1 then raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
    if v_count=1 then
      select request.* into strict r from public.weekly_exceptional_c1_publication_requests request
        join public.weekly_exceptional_pay_generations generation on generation.id=request.generation_id
        where request.state='READY' and generation.lifecycle_state='PENDING_C1'
          and generation.complete_next_vector_json#>>'{automatic_reconcile_proof,actor_user_id}'=v_actor::text
          and generation.complete_next_vector_json#>>'{automatic_reconcile_proof,source_cycle_id}'=v_cycle::text
          and generation.complete_next_vector_json#>>'{automatic_reconcile_proof,work_event_id}'=v_event::text;
      return jsonb_build_object('ok',true,'pending_stage',jsonb_build_object('publication_request_id',r.id,'request_sha256',encode(r.request_sha256,'hex')));
    end if;
    return jsonb_build_object('ok',true,'selection',private.weekly_source_automatic_reconcile_selection_v1(v_cycle,v_event));
  end if;
  select * into strict r from public.weekly_exceptional_c1_publication_requests where id=(p_request->>'publication_request_id')::uuid;
  select * into strict g from public.weekly_exceptional_pay_generations where id=r.generation_id and family_id=r.family_id;
  v_proof:=g.complete_next_vector_json->'automatic_reconcile_proof';
  if r.request_sha256 is distinct from private.weekly_exceptional_hex_sha256_v1(p_request->>'request_sha256')
    or v_proof->>'work_event_id' is distinct from v_event::text or v_proof->>'source_cycle_id' is distinct from v_cycle::text
    or v_proof->>'actor_user_id' is distinct from v_actor::text then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_REQUEST_INVALID' using errcode='22023'; end if;
  select audit.after_json into v_replay from public.audit_events audit
    where audit.object_type='weekly_source_automatic_reconcile' and audit.object_id_text=r.id::text
      and audit.action='WEEKLY_SOURCE_AUTOMATIC_RECONCILE_CLEARED' and audit.event_sequence_is_authoritative
      and audit.after_json->>'source_cycle_id'=v_cycle::text and audit.after_json->>'work_event_id'=v_event::text
      and audit.after_json->>'request_sha256'=p_request->>'request_sha256'
      and audit.after_json#>>'{delta_certificate,actor_user_id}'=v_actor::text
    order by audit.event_sequence desc limit 1;
  if v_replay is not null then return jsonb_build_object('ok',true,'cleared',true,'idempotent_replay',true,
    'native_result',v_replay->'native_result','delta_certificate',v_replay->'delta_certificate'); end if;
  perform private.weekly_source_pay_query_admit_v2();
  v_gate:=private.weekly_source_candidate_serial_gate_v1(r.candidate_id,'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',r.id,'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if v_gate->>'ok' is distinct from 'true' then return v_gate; end if;
  if not exists(select 1 from public.timesheets sheet join public.contracts contract on contract.id=sheet.contract_id
    where sheet.timesheet_id=r.root_timesheet_id and contract.candidate_id=r.candidate_id) then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  v_lock:=private.weekly_source_lock_family_rows_v1(array[r.root_timesheet_id],null);
  if v_lock->>'ok' is distinct from 'true' then return v_lock; end if;
  select source_group_id into strict v_source_group from public.weekly_source_cycles where id=v_cycle;
  perform 1 from public.weekly_source_groups where id=v_source_group and active for update;
  perform 1 from public.weekly_source_cycles where id=v_cycle and source_group_id=v_source_group for update;
  if not found then raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_SOURCE_CHANGED' using errcode='40001'; end if;
  select * into strict run from public.weekly_exceptional_orchestration_runs where id=r.orchestration_run_id and family_id=r.family_id;
  if run.request_kind is distinct from 'RECONCILE' or run.requested_by_user_id is distinct from v_actor then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_DELTA_UNAVAILABLE' using errcode='55000'; end if;
  v_certificate:=private.weekly_source_automatic_reconcile_certificate_v1(r.id,v_actor,v_cycle);
  v_result:=public.weekly_exceptional_pay_complete_local_v1(jsonb_build_object('schema_version','WEEKLY_PROTECTED_LOCAL_COMPLETE_V1',
    'actor_user_id',v_actor,'publication_request_id',r.id,'expected_request_sha256',p_request->>'request_sha256',
    'idempotency_key',run.idempotency_key||':local-complete'));
  if v_result->>'ok' is distinct from 'true' or v_result->>'outcome' is distinct from 'PUBLISHED' then
    raise exception 'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_NOT_PUBLISHED' using errcode='55000'; end if;
  perform public._audit_insert('weekly_source_automatic_reconcile',r.id::text,'WEEKLY_SOURCE_AUTOMATIC_RECONCILE_CLEARED',null,
    jsonb_build_object('work_event_id',v_event,'source_cycle_id',v_cycle,'publication_request_id',r.id,
      'request_sha256',p_request->>'request_sha256','native_result',v_result,'delta_certificate',v_certificate),'Cleared automatically · hours matched',v_actor);
  return jsonb_build_object('ok',true,'cleared',true,'native_result',v_result,'delta_certificate',v_certificate);
end;
$function$;
alter function public.weekly_source_automatic_reconcile_atomic_v1(jsonb) OWNER TO CURRENT_USER;
revoke all on function public.weekly_source_automatic_reconcile_atomic_v1(jsonb) from public,anon,authenticated;
grant execute on function public.weekly_source_automatic_reconcile_atomic_v1(jsonb) to service_role;

notify pgrst, 'reload schema';

-- Repeatable CloudTMS function/view authority: weekly_source_self_bill_report_scope_v1
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.





-- Sixth active parser profile; report times are factual invoice evidence,
-- never worked duration or pay authority. The existing five profiles stay exact.
do $seed_acacium_report_profile$
declare
  v_profile public.weekly_source_format_profiles%rowtype;
  v_json jsonb:='{"source_family":"ROSTER","purpose":"SELF_BILL_REPORT","sheet":"Allocate","header_row":1,"layouts":["A","B"],"report_number_required":true,"single_client_required":true,"invoice_only":true,"report_times_are_pay_hours":false,"fee_columns_read":false}'::jsonb;
  v_hash bytea;
begin
  v_hash:=extensions.digest(pg_catalog.convert_to(v_json::text,'UTF8'),'sha256');
  insert into public.weekly_source_format_profiles(id,profile_code,version,final_authority_kind,container_kind,omission_meaning,
    row_finalisation_capability,worked_duration_authority,scheduled_hours_fallback,physical_negative_meaning,
    report_number_required,single_client_required,fmc_must_equal_zero,profile_json,profile_sha256,active)
  values('36666666-6666-4666-8666-666666666666','ACACIUM_SELF_BILL_REPORT_V1',1,'SELF_BILL_REPORT','XLSX','NO_INFERENCE',
    'INVOICE_ONLY_REPORT_LINES','NO_PAY_HOURS',false,'INVOICE_ONLY_TRUST_CREDIT',true,true,false,v_json,v_hash,true)
    on conflict(profile_code,version) do nothing;
  select profile.* into strict v_profile from public.weekly_source_format_profiles profile
    where profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' and profile.version=1;
  if v_profile.id is distinct from '36666666-6666-4666-8666-666666666666'::uuid
    or v_profile.final_authority_kind is distinct from 'SELF_BILL_REPORT' or v_profile.container_kind is distinct from 'XLSX'
    or v_profile.omission_meaning is distinct from 'NO_INFERENCE'
    or v_profile.row_finalisation_capability is distinct from 'INVOICE_ONLY_REPORT_LINES'
    or v_profile.worked_duration_authority is distinct from 'NO_PAY_HOURS' or v_profile.scheduled_hours_fallback is distinct from false
    or v_profile.physical_negative_meaning is distinct from 'INVOICE_ONLY_TRUST_CREDIT'
    or v_profile.report_number_required is distinct from true or v_profile.single_client_required is distinct from true
    or v_profile.fmc_must_equal_zero is distinct from false or v_profile.profile_json is distinct from v_json
    or v_profile.profile_sha256 is distinct from v_hash or v_profile.active is distinct from true then
    raise exception 'WEEKLY_SOURCE_PROFILE_VERSION_CONFLICT' using errcode='55000';
  end if;
end;
$seed_acacium_report_profile$;

