-- Native NHSP owner: only partial-index inference and scope discriminator differ.
create or replace function public.weekly_source_nhsp_report_scope_resolve_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_allowed constant text[]:=array[
    'actor_user_id','source_group_id','source_cycle_id','trust_name'
  ]::text[];
  v_actor uuid;
  v_group_id uuid;
  v_cycle_id uuid;
  v_trust_name text;
  v_unknown text;
  v_group public.weekly_source_groups%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_client_id uuid;
  v_client_name text;
  v_match_count integer;
  v_inserted_count integer:=0;
  v_scope public.weekly_source_report_scopes%rowtype;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown
  from pg_catalog.jsonb_object_keys(p_request) key
  where not key=any(v_allowed)
  order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown;
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_group_id:=(p_request->>'source_group_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_trust_name:=nullif(pg_catalog.btrim(p_request->>'trust_name'),'');
  exception when others then
    raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_group_id is null or v_cycle_id is null
     or v_trust_name is null or pg_catalog.char_length(v_trust_name)>200 then
    raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_REQUEST_INVALID' using errcode='22023';
  end if;

  select * into v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_group_id
  for update;
  if not found or not v_group.active or v_group.source_family<>'NHSP' then
    raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_GROUP_INVALID' using errcode='22023';
  end if;
  select * into v_cycle
  from public.weekly_source_cycles cycle
  where cycle.id=v_cycle_id
    and cycle.source_group_id=v_group.id
  for update;
  if not found or v_cycle.state not in ('OPEN','FINALISABLE') then
    raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_CYCLE_INVALID' using errcode='55000';
  end if;

  select pg_catalog.count(*),pg_catalog.min(client.id::text)::uuid,
         pg_catalog.min(client.name)
    into v_match_count,v_client_id,v_client_name
  from public.weekly_source_group_clients membership
  join public.clients client on client.id=membership.client_id
  where membership.source_group_id=v_group.id
    and v_cycle.finalisation_week_ending between membership.valid_from
      and coalesce(membership.valid_to,'infinity'::date)
    and pg_catalog.lower(pg_catalog.btrim(client.name))=
      pg_catalog.lower(v_trust_name);
  if v_match_count=0 then
    raise exception 'WEEKLY_SOURCE_NHSP_TRUST_NOT_CONFIGURED' using errcode='22023';
  elsif v_match_count>1 then
    raise exception 'WEEKLY_SOURCE_NHSP_TRUST_AMBIGUOUS' using errcode='55000';
  end if;

  perform private.weekly_source_office_authority_v1(
    v_actor,'UPLOAD_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-source-nhsp-report-scope:'||v_cycle.id::text||':'||v_client_id::text,0
  ));
  insert into public.weekly_source_report_scopes(
    source_cycle_id,environment,agency_id,source_group_id,client_id,cutoff_at_utc
  ) values (
    v_cycle.id,v_group.environment,v_group.agency_id,v_group.id,v_client_id,v_cycle.cutoff_at_utc
  ) on conflict (environment,agency_id,source_group_id,client_id,cutoff_at_utc) where self_bill_report_id is null
    do nothing;
  get diagnostics v_inserted_count=row_count;
  select * into strict v_scope
  from public.weekly_source_report_scopes report_scope
  where report_scope.environment=v_group.environment
    and report_scope.agency_id=v_group.agency_id
    and report_scope.source_group_id=v_group.id
    and report_scope.client_id=v_client_id
    and report_scope.cutoff_at_utc=v_cycle.cutoff_at_utc
    and report_scope.self_bill_report_id is null;
  if v_scope.source_cycle_id is distinct from v_cycle.id then
    raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_CYCLE_MISMATCH' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,
    'report_scope_id',v_scope.id,
    'source_group_id',v_group.id,
    'source_cycle_id',v_cycle.id,
    'client_id',v_client_id,
    'client_name',v_client_name,
    'cutoff_at_utc',v_scope.cutoff_at_utc,
    'authority_scope_version',v_scope.version,
    'idempotent',v_inserted_count=0
  );
end;
$function$;


-- One closed DTO is used before report registration, during staging and again
-- from persisted rows at seal. Money is literal evidence; arithmetic is not
-- corrected here. Start/end are source facts and never pay duration authority.
create or replace function private.weekly_source_self_bill_report_row_dto_v1(p_row jsonb)
returns jsonb language plpgsql immutable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_row public.weekly_source_upload_rows%rowtype; v_raw jsonb; v_component jsonb;
  v_kind text; v_expected bigint; v_start timestamp; v_end timestamp;
begin
  if p_row is null or jsonb_typeof(p_row)<>'object' or exists(
    select 1 from jsonb_object_keys(p_row) k where k not in (
      'source_row_ordinal','external_source_key','source_candidate_identity','source_client_identity',
      'work_date','start_at_local','end_at_local','source_shift_charge_pence','source_vat_pence',
      'source_gross_pence','bounded_raw_columns_json')) then
    raise exception 'WEEKLY_SOURCE_REPORT_ROW_UNKNOWN_OR_MISSING_FIELD' using errcode='22023';
  end if;
  begin v_row:=jsonb_populate_record(null::public.weekly_source_upload_rows,p_row);
  exception when others then raise exception 'WEEKLY_SOURCE_REPORT_ROW_TYPE_INVALID' using errcode='22023'; end;
  v_raw:=v_row.bounded_raw_columns_json;
  if v_row.source_row_ordinal is null or v_row.source_row_ordinal<1
    or char_length(coalesce(v_row.external_source_key,'')) not between 1 and 160
    or v_row.external_source_key<>btrim(v_row.external_source_key)
    or char_length(coalesce(v_row.source_candidate_identity,'')) not between 1 and 200
    or char_length(coalesce(v_row.source_client_identity,'')) not between 1 and 200
    or v_row.work_date is null or v_row.start_at_local is null or v_row.end_at_local is null
    or v_row.source_shift_charge_pence is null or v_row.source_vat_pence is null or v_row.source_gross_pence is null
    or greatest(abs(v_row.source_shift_charge_pence::numeric),abs(v_row.source_vat_pence::numeric),abs(v_row.source_gross_pence::numeric))>999999999999
    or jsonb_typeof(v_raw) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(v_raw) k where k not in ('reportTimes','requestedOn','components'))
    or jsonb_typeof(v_raw->'reportTimes') is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(v_raw->'reportTimes') k where k not in ('start','end','overnight'))
    or coalesce(v_raw#>>'{reportTimes,start}','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or coalesce(v_raw#>>'{reportTimes,end}','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or jsonb_typeof(v_raw#>'{reportTimes,overnight}') is distinct from 'boolean'
    or coalesce(v_raw->>'requestedOn','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
    or jsonb_typeof(v_raw->'components') is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(v_raw->'components') k where k not in ('net','vat','gross')) then
    raise exception 'WEEKLY_SOURCE_REPORT_ROW_FACTS_INVALID' using errcode='22023';
  end if;
  perform (v_raw->>'requestedOn')::timestamp;
  v_start:=v_row.work_date+(v_raw#>>'{reportTimes,start}')::time;
  v_end:=v_row.work_date+(v_raw#>>'{reportTimes,end}')::time;
  if v_end<=v_start then v_end:=v_end+interval '1 day'; end if;
  if v_row.start_at_local is distinct from v_start or v_row.end_at_local is distinct from v_end
    or (v_raw#>>'{reportTimes,overnight}')::boolean is distinct from (v_end::date>v_start::date) then
    raise exception 'WEEKLY_SOURCE_REPORT_TIMES_INVALID' using errcode='22023';
  end if;
  foreach v_kind in array array['net','vat','gross'] loop
    v_component:=v_raw->'components'->v_kind;
    v_expected:=case v_kind when 'net' then v_row.source_shift_charge_pence when 'vat' then v_row.source_vat_pence else v_row.source_gross_pence end;
    if jsonb_typeof(v_component) is distinct from 'object' or exists(
      select 1 from jsonb_object_keys(v_component) k where k not in (
        'coordinate','sourceKind','cellKind','formulaPresent','originalToken','decodedToken','tokenTruncated',
        'parseState','parsedPence','normalisation','rounding'))
      or coalesce(v_component->>'coordinate','') !~ '^[A-Z]{1,3}[1-9][0-9]{0,6}$'
      or coalesce(v_component->>'sourceKind','') not in ('XLSX_NUMERIC_TOKEN','XLSX_STRING_TOKEN')
      or coalesce(v_component->>'cellKind','') not in ('NUMBER','STRING')
      or v_component->'formulaPresent' is distinct from 'false'::jsonb
      or jsonb_typeof(v_component->'tokenTruncated') is distinct from 'boolean'
      or jsonb_typeof(v_component->'originalToken') is distinct from 'string'
      or jsonb_typeof(v_component->'decodedToken') is distinct from 'string'
      or char_length(v_component->>'originalToken')>128 or char_length(v_component->>'decodedToken')>128
      or v_component->>'parseState' is distinct from 'PARSED'
      or coalesce(v_component->>'parsedPence','') !~ '^-?[0-9]{1,12}$'
      or (v_component->>'parsedPence')::bigint is distinct from v_expected
      or (v_component ? 'normalisation' and (jsonb_typeof(v_component->'normalisation')<>'string' or char_length(v_component->>'normalisation')>200))
      or (v_component ? 'rounding' and (jsonb_typeof(v_component->'rounding')<>'string' or char_length(v_component->>'rounding')>200)) then
      raise exception 'WEEKLY_SOURCE_REPORT_COMPONENT_EVIDENCE_INVALID' using errcode='22023',detail=v_kind;
    end if;
  end loop;
  return jsonb_build_object('source_row_ordinal',v_row.source_row_ordinal,'external_source_key',v_row.external_source_key,
    'source_candidate_identity',v_row.source_candidate_identity,'source_client_identity',v_row.source_client_identity,
    'work_date',to_char(v_row.work_date,'YYYY-MM-DD'),'start_at_local',to_char(v_start,'YYYY-MM-DD"T"HH24:MI:SS'),
    'end_at_local',to_char(v_end,'YYYY-MM-DD"T"HH24:MI:SS'),'source_shift_charge_pence',v_row.source_shift_charge_pence,
    'source_vat_pence',v_row.source_vat_pence,'source_gross_pence',v_row.source_gross_pence,'bounded_raw_columns_json',v_raw);
end;
$function$;

create or replace function private.weekly_source_self_bill_report_row_hash_v1(p_row jsonb)
returns bytea language sql immutable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_SELF_BILL_REPORT_ROW_V1',
    private.weekly_source_self_bill_report_row_dto_v1(p_row))
$function$;

create or replace function private.weekly_source_self_bill_report_manifest_v1(p_rows jsonb)
returns jsonb language plpgsql immutable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_rows jsonb; v_count integer; v_net numeric; v_vat numeric; v_gross numeric;
begin
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 100000 then
    raise exception 'WEEKLY_SOURCE_REPORT_LINE_COUNT_INVALID' using errcode='22023'; end if;
  select jsonb_agg(private.weekly_source_self_bill_report_row_dto_v1(x) order by (x->>'source_row_ordinal')::integer),
    count(*),sum((x->>'source_shift_charge_pence')::numeric),sum((x->>'source_vat_pence')::numeric),sum((x->>'source_gross_pence')::numeric)
    into v_rows,v_count,v_net,v_vat,v_gross from jsonb_array_elements(p_rows) x;
  if exists(select 1 from jsonb_array_elements(v_rows) x group by x->>'external_source_key' having count(*)<>1)
    or exists(select 1 from jsonb_array_elements(v_rows) x group by x->>'source_row_ordinal' having count(*)<>1)
    or greatest(abs(v_net),abs(v_vat),abs(v_gross))>999999999999 then
    raise exception 'WEEKLY_SOURCE_REPORT_DUPLICATE_OR_TOTAL_OVERFLOW' using errcode='22023'; end if;
  return jsonb_build_object('line_count',v_count,'net_pence',v_net::bigint,'vat_pence',v_vat::bigint,'gross_pence',v_gross::bigint,
    'row_manifest_hash',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_SELF_BILL_REPORT_MANIFEST_V1',v_rows),'hex'));
end;
$function$;

create or replace function private.weekly_source_self_bill_report_stored_rows_v1(p_upload_id uuid)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select coalesce(jsonb_agg(jsonb_build_object('source_row_ordinal',r.source_row_ordinal,'external_source_key',r.external_source_key,
    'source_candidate_identity',r.source_candidate_identity,'source_client_identity',r.source_client_identity,
    'work_date',r.work_date,'start_at_local',r.start_at_local,'end_at_local',r.end_at_local,
    'source_shift_charge_pence',r.source_shift_charge_pence,'source_vat_pence',r.source_vat_pence,
    'source_gross_pence',r.source_gross_pence,'bounded_raw_columns_json',r.bounded_raw_columns_json) order by r.source_row_ordinal),'[]'::jsonb)
  from public.weekly_source_upload_rows r where r.upload_id=p_upload_id
$function$;

create or replace function private.weekly_source_self_bill_report_rules_assert_v1(p_client_id uuid,p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_rules jsonb;
begin
  -- This helper resolves actual dated membership and enabled immutable F1
  -- assignment; saved disabled settings can never authorize a report.
  v_rules:=private.weekly_source_effective_rule_set_v1(p_client_id,p_cycle_id);
  if v_rules is null or v_rules->>'contract' is distinct from 'WEEKLY_SOURCE_EFFECTIVE_RULE_SET_V1'
    or v_rules->>'rule_set_version_id' is null
    or v_rules#>>'{values,self_bill_source}' is distinct from 'SEPARATE_FINAL_REPORT'
    or v_rules#>>'{values,final_report_profile_kind}' is distinct from 'ACACIUM_SELF_BILL_REPORT_V1'
    or v_rules#>>'{values,invoice_membership}' is distinct from 'FOLLOW_FINAL_REPORT_LINES'
    or v_rules#>>'{values,invoice_amount_basis}' is distinct from 'SOURCE_AMOUNT'
    or v_rules#>>'{values,source_amount_basis}' is distinct from 'REPORT_LINE_NET'
    or v_rules#>>'{values,line_vat_method}' is distinct from 'LINE_VAT_FROM_REPORT'
    or v_rules#>>'{values,pay_membership}' is distinct from 'ON_ACCEPTED_REPORT_OR_PROTECTED' then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_RULES_NOT_ENABLED' using errcode='55000';
  end if;
  return v_rules;
end;
$function$;

create or replace function public.weekly_source_self_bill_report_scope_resolve_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_group_id uuid; v_cycle_id uuid; v_client_id uuid;
  v_group public.weekly_source_groups%rowtype; v_cycle public.weekly_source_cycles%rowtype;
  v_report public.weekly_source_self_bill_reports%rowtype; v_scope public.weekly_source_report_scopes%rowtype;
  v_number text; v_date date; v_content bytea; v_manifest jsonb; v_client_name text;
  v_net bigint; v_vat bigint; v_gross bigint; v_count integer; v_created boolean:=false;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_request is null or jsonb_typeof(p_request)<>'object' or exists(select 1 from jsonb_object_keys(p_request) k
    where k not in ('actor_user_id','source_group_id','source_cycle_id','client_id','report_number','invoice_date','layout',
      'content_sha256','line_count','net_pence','vat_pence','gross_pence','rows')) then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_SCOPE_REQUEST_INVALID' using errcode='22023'; end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid; v_group_id:=(p_request->>'source_group_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid; v_client_id:=(p_request->>'client_id')::uuid;
    v_number:=p_request->>'report_number'; v_date:=(p_request->>'invoice_date')::date;
    v_net:=(p_request->>'net_pence')::bigint; v_vat:=(p_request->>'vat_pence')::bigint;
    v_gross:=(p_request->>'gross_pence')::bigint; v_count:=(p_request->>'line_count')::integer;
    v_content:=private.weekly_source_hex32_v1(p_request->>'content_sha256','WEEKLY_SOURCE_CONTENT_HASH_INVALID');
  exception when others then raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_SCOPE_TYPE_INVALID' using errcode='22023'; end;
  if v_actor is null or v_group_id is null or v_cycle_id is null or v_client_id is null
    or coalesce(v_number,'') !~ '^XYOXLR[0-9]{6}$' or v_date is null
    or substring(v_number from 7)<>to_char(v_date,'DDMMYY') or v_date not between date '2000-01-01' and date '2099-12-31'
    or coalesce(p_request->>'layout','') not in ('A','B') or v_count is null or v_net is null or v_vat is null or v_gross is null then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_IDENTITY_INVALID' using errcode='22023'; end if;
  -- G1: always group before cycle, including replay and post-pay report upload.
  select * into v_group from public.weekly_source_groups where id=v_group_id for update;
  if not found or not v_group.active or v_group.source_family<>'ROSTER' then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_GROUP_INVALID' using errcode='22023'; end if;
  select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id and source_group_id=v_group_id for update;
  if not found or v_cycle.state not in ('OPEN','FINALISABLE','FINALISED')
    or (v_cycle.scope_client_id is not null and v_cycle.scope_client_id<>v_client_id) then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CYCLE_INVALID' using errcode='55000'; end if;
  select c.name into v_client_name from public.clients c join public.weekly_source_group_clients gc on gc.client_id=c.id
    where c.id=v_client_id and gc.source_group_id=v_group_id
      and v_cycle.finalisation_week_ending between gc.valid_from and coalesce(gc.valid_to,'infinity'::date);
  if not found then raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CLIENT_INVALID' using errcode='22023'; end if;
  perform private.weekly_source_office_authority_v1(v_actor,'UPLOAD_SOURCE',v_group_id,v_client_id,v_cycle.finalisation_week_ending);
  perform private.weekly_source_self_bill_report_rules_assert_v1(v_client_id,v_cycle_id);
  if (p_request->>'layout'='A' and private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle_id)#>>'{values,invoice_vat_method}'='ONCE_ON_TOTAL_TRUNCATE')
    or (p_request->>'layout'='B' and private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle_id)#>>'{values,invoice_vat_method}'='ONCE_ON_TOTAL_HALF_UP') then
    raise exception 'WEEKLY_SOURCE_REPORT_LAYOUT_VAT_METHOD_MISMATCH' using errcode='22023'; end if;
  v_manifest:=private.weekly_source_self_bill_report_manifest_v1(p_request->'rows');
  if (v_manifest->>'line_count')::integer is distinct from v_count or (v_manifest->>'net_pence')::bigint is distinct from v_net
    or (v_manifest->>'vat_pence')::bigint is distinct from v_vat or (v_manifest->>'gross_pence')::bigint is distinct from v_gross
    or exists(select 1 from jsonb_array_elements(p_request->'rows') r
      where r->>'source_client_identity' is distinct from v_client_name) then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_MANIFEST_MISMATCH' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('weekly-source-self-bill-report-content:'||encode(v_content,'hex'),0));
  select * into v_report from public.weekly_source_self_bill_reports where content_sha256=v_content;
  if not found then
    if exists(select 1 from public.weekly_source_self_bill_reports where source_group_id=v_group_id and client_id=v_client_id and report_number=v_number) then
      raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_NUMBER_REUSED' using errcode='55000'; end if;
    insert into public.weekly_source_self_bill_reports(source_group_id,client_id,source_cycle_id,report_number,invoice_date,
      content_sha256,line_count,net_pence,vat_pence,gross_pence,row_manifest_hash,layout,created_by_user_id)
    values(v_group_id,v_client_id,v_cycle_id,v_number,v_date,v_content,v_count,v_net,v_vat,v_gross,
      decode(v_manifest->>'row_manifest_hash','hex'),p_request->>'layout',v_actor) returning * into v_report;
    v_created:=true;
  elsif v_report.source_group_id is distinct from v_group_id or v_report.client_id is distinct from v_client_id
    or v_report.source_cycle_id is distinct from v_cycle_id or v_report.report_number is distinct from v_number
    or v_report.invoice_date is distinct from v_date or v_report.layout is distinct from p_request->>'layout'
    or v_report.line_count is distinct from v_count or v_report.net_pence is distinct from v_net
    or v_report.vat_pence is distinct from v_vat or v_report.gross_pence is distinct from v_gross
    or v_report.row_manifest_hash is distinct from decode(v_manifest->>'row_manifest_hash','hex') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CONTENT_SCOPE_CONFLICT' using errcode='55000';
  end if;
  insert into public.weekly_source_report_scopes(source_cycle_id,environment,agency_id,source_group_id,client_id,cutoff_at_utc,self_bill_report_id)
    values(v_cycle_id,v_group.environment,v_group.agency_id,v_group_id,v_client_id,v_cycle.cutoff_at_utc,v_report.id)
    on conflict(source_group_id,client_id,self_bill_report_id) where self_bill_report_id is not null do nothing;
  select * into strict v_scope from public.weekly_source_report_scopes where self_bill_report_id=v_report.id;
  if v_scope.source_cycle_id is distinct from v_cycle_id or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_SCOPE_CHANGED' using errcode='55000'; end if;
  return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_SELF_BILL_REPORT_SCOPE_V1','report_scope_id',v_scope.id,
    'self_bill_report_id',v_report.id,'source_group_id',v_group_id,'source_cycle_id',v_cycle_id,'client_id',v_client_id,
    'client_name',v_client_name,'authority_scope_version',v_scope.version,'cutoff_at_utc',v_scope.cutoff_at_utc,
    'row_manifest_hash',encode(v_report.row_manifest_hash,'hex'),'idempotent',not v_created);
end;
$function$;

create or replace function private.weekly_source_self_bill_report_seal_assert_v1(p_upload_id uuid)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_upload public.weekly_source_uploads%rowtype; v_scope public.weekly_source_report_scopes%rowtype;
  v_report public.weekly_source_self_bill_reports%rowtype; v_manifest jsonb; v_row record; v_kind text; v_component jsonb;
begin
  select * into strict v_upload from public.weekly_source_uploads where id=p_upload_id;
  select * into strict v_scope from public.weekly_source_report_scopes where id=v_upload.report_scope_id;
  select * into strict v_report from public.weekly_source_self_bill_reports where id=v_scope.self_bill_report_id;
  perform private.weekly_source_self_bill_report_rules_assert_v1(v_scope.client_id,v_scope.source_cycle_id);
  v_manifest:=private.weekly_source_self_bill_report_manifest_v1(private.weekly_source_self_bill_report_stored_rows_v1(p_upload_id));
  if v_upload.content_sha256 is distinct from v_report.content_sha256 or v_upload.accepted_count<>v_report.line_count
    or v_report.row_manifest_hash is distinct from decode(v_manifest->>'row_manifest_hash','hex')
    or v_report.net_pence is distinct from (v_manifest->>'net_pence')::bigint
    or v_report.vat_pence is distinct from (v_manifest->>'vat_pence')::bigint
    or v_report.gross_pence is distinct from (v_manifest->>'gross_pence')::bigint
    or v_upload.coverage_proof_kind<>'SELF_BILL_REPORT_SCOPE' or v_upload.purpose<>'ORDINARY'
    or v_upload.confirmed_coverage_start_local_date is not null or v_upload.confirmed_coverage_end_local_date is not null
    or exists(select 1 from public.weekly_source_row_resolutions x join public.weekly_source_upload_rows r on r.id=x.upload_row_id where r.upload_id=p_upload_id)
    or exists(select 1 from public.weekly_source_expense_cell_evidence where upload_id=p_upload_id)
    or (select count(*) from public.weekly_source_money_cell_evidence where upload_id=p_upload_id)<>v_report.line_count*3
    or exists(select 1 from public.weekly_source_upload_rows r where r.upload_id=p_upload_id and (
      r.row_finalisation_state<>'SOURCE_REPORT_LINE' or r.break_minutes is not null or r.actual_net_minutes is not null
      or r.finalised_by is not null or r.role_band_source is not null or r.source_expense_pence is not null
      or r.source_expense_parse_state<>'NOT_APPLICABLE' or r.source_money_parse_state<>'VALID'
      or r.source_commission_pence is not null or r.source_total_cost_pence is not null
      or r.source_qualification_profile_version is distinct from 'SOURCE_INVOICE_MONEY_PENCE_V1'
      or r.normalised_row_hash is distinct from private.weekly_source_self_bill_report_row_hash_v1(
        jsonb_build_object('source_row_ordinal',r.source_row_ordinal,'external_source_key',r.external_source_key,
          'source_candidate_identity',r.source_candidate_identity,'source_client_identity',r.source_client_identity,
          'work_date',r.work_date,'start_at_local',r.start_at_local,'end_at_local',r.end_at_local,
          'source_shift_charge_pence',r.source_shift_charge_pence,'source_vat_pence',r.source_vat_pence,
          'source_gross_pence',r.source_gross_pence,'bounded_raw_columns_json',r.bounded_raw_columns_json))
    )) then raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_SEAL_AUTHORITY_INVALID' using errcode='55000'; end if;
  for v_row in select * from public.weekly_source_upload_rows where upload_id=p_upload_id loop
    foreach v_kind in array array['net','vat','gross'] loop
      v_component:=v_row.bounded_raw_columns_json->'components'->v_kind;
      if not exists(select 1 from public.weekly_source_money_cell_evidence e where e.upload_id=p_upload_id
        and e.source_row_ordinal=v_row.source_row_ordinal and e.money_field_kind='SOURCE_'||upper(v_kind)
        and e.source_file_sha256=v_upload.content_sha256 and e.parse_state='VALID' and not e.formula_present
        and e.parsed_pence=(v_component->>'parsedPence')::bigint and e.cell_coordinate=v_component->>'coordinate'
        and e.source_kind=v_component->>'sourceKind' and e.original_token=v_component->>'originalToken'
        and e.decoded_token=v_component->>'decodedToken' and e.cell_type_marker=v_component->>'cellKind') then
        raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_MONEY_WITNESS_INVALID' using errcode='55000',detail=v_kind;
      end if;
    end loop;
  end loop;
  -- net+VAT vs gross differences remain accepted forensic warnings here.
end;
$function$;

-- Complete F8 facts/gate with purpose-bound report timing and coverage exemption.
create or replace function private.weekly_source_final_upload_facts_v1(
  p_profile text,p_week_ending date,p_cutoff_at_utc timestamptz,p_uploaded_at_utc timestamptz,
  p_coverage_state text,p_coverage_start date,p_coverage_end date,p_rules jsonb,p_coverage_floor date
) returns jsonb language plpgsql immutable security invoker
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_code text; v_message text; v_earliest timestamptz;
  v_weekday integer; v_clock time; v_local timestamp; v_required_start date;
  v_days constant text[]:=array['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
begin
  -- Legacy/off/unassigned, NHSP and Mode A retain their existing owners.
  if (p_rules is null and p_profile<>'ACACIUM_SELF_BILL_REPORT_V1') or p_profile in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1') then
    return jsonb_build_object('contract','WEEKLY_SOURCE_FINAL_UPLOAD_GATE_V1','allowed',true,
      'code',null,'message',null,'earliest_upload_at_utc',null,'coverage_floor_local_date',null);
  end if;
  if p_profile not in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
      'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1','ACACIUM_SELF_BILL_REPORT_V1') or jsonb_typeof(p_rules) is distinct from 'object'
      or p_week_ending is null or p_cutoff_at_utc is null or p_uploaded_at_utc is null
      or (p_profile<>'ACACIUM_SELF_BILL_REPORT_V1' and (p_coverage_floor is null or p_rules->>'checking_profile_kind' is distinct from p_profile))
      or (p_profile='ACACIUM_SELF_BILL_REPORT_V1' and (p_rules->>'self_bill_source' is distinct from 'SEPARATE_FINAL_REPORT'
        or p_rules->>'final_report_profile_kind' is distinct from 'ACACIUM_SELF_BILL_REPORT_V1')) then
    v_code:='WEEKLY_SOURCE_FINAL_UPLOAD_CONTEXT_INVALID';
    v_message:='The final file could not be checked. Refresh the import before trying again.';
  elsif p_rules->'earliest_final_weekday'='null'::jsonb
      and p_rules->'earliest_final_local_time'='null'::jsonb then
    v_earliest:=p_cutoff_at_utc;
  elsif jsonb_typeof(p_rules->'earliest_final_weekday')='number'
      and coalesce(p_rules->>'earliest_final_weekday','') ~ '^[0-6]$'
      and coalesce(p_rules->>'earliest_final_local_time','') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
    v_weekday:=(p_rules->>'earliest_final_weekday')::integer;
    v_clock:=(p_rules->>'earliest_final_local_time')::time;
    -- A source cycle's Sunday is the completed work week. Its cutoff/S12
    -- occurrence is the following configured weekday, as the cycle owner does.
    v_earliest:=((p_week_ending+v_weekday)+v_clock) at time zone 'Europe/London';
    if v_earliest<p_cutoff_at_utc then
      v_code:='WEEKLY_SOURCE_FINAL_UPLOAD_CONTEXT_INVALID';
      v_message:='The final file could not be checked. Refresh the import before trying again.';
    end if;
  else
    v_code:='WEEKLY_SOURCE_FINAL_UPLOAD_CONTEXT_INVALID';
    v_message:='The final file could not be checked. Refresh the import before trying again.';
  end if;
  if v_code is null and p_uploaded_at_utc<v_earliest then
    v_local:=v_earliest at time zone 'Europe/London';
    v_code:='WEEKLY_SOURCE_FINAL_FILE_UPLOADED_TOO_EARLY';
    v_message:='The final file can be uploaded from '
      ||v_days[extract(dow from v_local)::integer+1]||' '||to_char(v_local,'HH24:MI')
      ||' ('||to_char(v_local,'DD/MM/YYYY')||').';
  end if;
  if p_profile<>'ACACIUM_SELF_BILL_REPORT_V1' then
  v_required_start:=greatest(p_week_ending-6,p_coverage_floor);
  if v_code is null and (p_coverage_state is distinct from 'COMPLETE' or p_coverage_start is null
      or p_coverage_end is null or p_coverage_start>p_coverage_end) then
    v_code:='WEEKLY_SOURCE_FINAL_FILE_COVERAGE_INCOMPLETE';
    v_message:='Upload an export covering the whole week.';
  elsif v_code is null and p_coverage_start<p_coverage_floor then
    v_code:='WEEKLY_SOURCE_COVERAGE_BEFORE_RULE_SET';
    v_message:='Import coverage starts from '||to_char(p_coverage_floor,'DD/MM/YYYY')
      ||', the first week using these settings.';
  elsif v_code is null and (p_coverage_start>v_required_start or p_coverage_end<p_week_ending) then
    v_code:='WEEKLY_SOURCE_FINAL_FILE_COVERAGE_INCOMPLETE';
    v_message:='The current file covers '||to_char(p_coverage_start,'DD/MM/YYYY')||'–'
      ||to_char(p_coverage_end,'DD/MM/YYYY')||' only. Upload an export covering the whole week.';
  end if;
  end if;
  return jsonb_build_object('contract','WEEKLY_SOURCE_FINAL_UPLOAD_GATE_V1','allowed',v_code is null,
    'code',v_code,'message',v_message,'earliest_upload_at_utc',v_earliest,
    'coverage_floor_local_date',p_coverage_floor);
end;
$function$;

create or replace function private.weekly_source_final_upload_gate_v1(p_upload_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_upload public.weekly_source_uploads%rowtype; v_cycle public.weekly_source_cycles%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype; v_rules jsonb; v_floor date; v_client uuid;
begin
  select * into strict v_upload from public.weekly_source_uploads where id=p_upload_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_upload.source_cycle_id;
  select * into strict v_profile from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
  v_client:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
  v_rules:=private.weekly_source_effective_rule_set_v1(v_client,v_cycle.id);
  if v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' then
    v_rules:=private.weekly_source_self_bill_report_rules_assert_v1(v_client,v_cycle.id);
    if not exists(select 1 from public.weekly_source_report_scopes s join public.weekly_source_self_bill_reports r on r.id=s.self_bill_report_id
      where s.id=v_upload.report_scope_id and s.source_cycle_id=v_cycle.id and s.client_id=v_client
        and r.content_sha256=v_upload.content_sha256) then
      raise exception 'WEEKLY_SOURCE_REPORT_TIMING_SCOPE_INVALID' using errcode='55000'; end if;
  elsif v_rules is not null then
    -- Retained activation receipts and frozen revisions prove this client's
    -- first applicable rule week, including historical disabled assignments.
    v_floor:=private.weekly_source_rule_coverage_floor_v1(v_client,v_cycle.id);
  end if;
  return private.weekly_source_final_upload_facts_v1(v_profile.profile_code,v_cycle.finalisation_week_ending,
    v_cycle.cutoff_at_utc,v_upload.uploaded_at_utc,v_upload.coverage_state,
    v_upload.confirmed_coverage_start_local_date,v_upload.confirmed_coverage_end_local_date,v_rules->'values',v_floor);
end;
$function$;

create or replace function private.weekly_source_self_bill_report_prior_binding_v1(p_report_row_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare row_fact public.weekly_source_upload_rows%rowtype; s public.weekly_source_report_scopes%rowtype;
  report public.weekly_source_self_bill_reports%rowtype; v_date date; v_count integer; result jsonb;
begin
  select * into strict row_fact from public.weekly_source_upload_rows where id=p_report_row_id;
  if row_fact.row_finalisation_state<>'SOURCE_REPORT_LINE' or row_fact.source_shift_charge_pence>=0 then return null; end if;
  select rs.* into strict s from public.weekly_source_report_scopes rs join public.weekly_source_uploads u on u.report_scope_id=rs.id where u.id=row_fact.upload_id;
  select * into strict report from public.weekly_source_self_bill_reports where id=s.self_bill_report_id;
  select max(pr.invoice_date) into v_date from public.weekly_source_billing_movements m
    join public.weekly_source_upload_rows rr on rr.id=m.self_bill_report_row_id
    join public.weekly_source_final_revisions fr on fr.id=m.final_revision_id and fr.state='CURRENT'
    join public.weekly_source_report_scopes ps on ps.id=fr.report_scope_id and ps.current_final_revision_id=fr.id
    join public.weekly_source_self_bill_reports pr on pr.id=ps.self_bill_report_id
    where m.source_line_kind='SELF_BILL_REPORT_LINE' and m.movement_role='POSITIVE' and m.actual_client_id=s.client_id
      and ps.source_group_id=s.source_group_id and rr.external_source_key=row_fact.external_source_key and pr.invoice_date<report.invoice_date;
  if v_date is null then return null; end if;
  select count(*),jsonb_agg(jsonb_build_object('prior_movement_id',m.id,'row_id',b.export_upload_row_id,
    'resolution_id',b.bound_row_resolution_id,'publication_id',b.export_projection_publication_id,'work_event_id',b.work_event_id))->0
    into v_count,result from public.weekly_source_billing_movements m
    join public.weekly_source_upload_rows rr on rr.id=m.self_bill_report_row_id
    join public.weekly_source_final_revisions fr on fr.id=m.final_revision_id and fr.state='CURRENT'
    join public.weekly_source_report_scopes ps on ps.id=fr.report_scope_id and ps.current_final_revision_id=fr.id
    join public.weekly_source_self_bill_reports pr on pr.id=ps.self_bill_report_id
    join public.weekly_source_self_bill_report_line_bindings b on b.id=(m.source_facts_json->>'report_line_binding_id')::uuid
      and b.report_row_id=rr.id and b.self_bill_report_id=pr.id and b.work_event_id=m.work_event_id
    where m.source_line_kind='SELF_BILL_REPORT_LINE' and m.movement_role='POSITIVE' and m.actual_client_id=s.client_id
      and ps.source_group_id=s.source_group_id and rr.external_source_key=row_fact.external_source_key and pr.invoice_date=v_date;
  if v_count<>1 then raise exception 'WEEKLY_SOURCE_REPORT_PRIOR_BINDING_UNPROVED' using errcode='55000'; end if;
  return result;
end;
$function$;

-- Native immutable pay-finalisation proof for the exact export binding.
-- Retired/current flags alone never fabricate proof or erase a retained receipt.
-- Root adds joined PROPOSED/NEXT/protected effective-position alternatives here.
create or replace function private.weekly_source_self_bill_report_pay_witness_v1(p_binding_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_count integer; v_witness jsonb;
begin
  select count(*),jsonb_agg(jsonb_build_object('bound_pay_snapshot_line_id',fs.id,
    'bound_pay_final_revision_id',fr.id,'bound_pay_projection_receipt_id',receipt.id,
    'published_timesheet_financial_id',financial.id,'invoice_timesheet_id',lineage.timesheet_id,
    'candidate_id',rr.candidate_id,'client_id',rr.client_id,'contract_id',rr.contract_id,'work_event_id',rr.work_event_id))->0
    into v_count,v_witness
    from public.weekly_source_self_bill_report_line_bindings b
    join public.weekly_source_upload_rows er on er.id=b.export_upload_row_id and er.row_finalisation_state='SOURCE_WORKED'
      and nullif(btrim(er.finalised_by),'') is not null
    join public.weekly_source_row_resolutions rr on rr.id=b.bound_row_resolution_id and rr.upload_row_id=er.id
      and rr.work_event_id=b.work_event_id and rr.mapping_state='RESOLVED'
    join public.weekly_source_projection_publications ep on ep.id=b.export_projection_publication_id and ep.upload_id=er.upload_id
      and ep.authority_scope_kind='CYCLE' and rr.generation=coalesce(ep.projection_generation,ep.authority_scope_version)
    join public.weekly_source_cycles ec on ec.id=ep.source_cycle_id
    join public.weekly_source_final_revisions fr on fr.id=ec.current_final_revision_id and fr.source_cycle_id=ec.id
      and fr.authority_scope_kind='CYCLE' and fr.state='CURRENT'
    join public.weekly_source_final_snapshot_lines fs on fs.final_revision_id=fr.id and fs.row_resolution_id=rr.id
      and fs.work_event_id=rr.work_event_id and fs.client_id=rr.client_id and fs.contract_id=rr.contract_id
    join public.weekly_source_row_timesheet_lineages lineage on lineage.row_resolution_id=rr.id
      and lineage.work_event_id=rr.work_event_id and lineage.client_id=rr.client_id and lineage.contract_id=rr.contract_id
    join public.weekly_source_ordinary_pay_projection_receipts receipt on receipt.final_revision_id=fr.id
      and receipt.root_timesheet_id=lineage.timesheet_id and receipt.client_id=rr.client_id
      and receipt.outcome='PREPARED_FOR_AUTHORISATION'
    join public.timesheets_financials financial on financial.id=receipt.published_timesheet_financial_id
      and financial.timesheet_id=lineage.timesheet_id and financial.client_id=rr.client_id
    where b.id=p_binding_id;
  if v_count=0 then return null; end if;
  if v_count<>1 then raise exception 'WEEKLY_SOURCE_REPORT_PAY_WITNESS_AMBIGUOUS' using errcode='55000'; end if;
  return v_witness;
end;
$function$;

create or replace function private.weekly_source_self_bill_report_projection_rows_v1(p_actor_user_id uuid,p_publication_id uuid,p_rows jsonb)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_projection_publications%rowtype; s public.weekly_source_report_scopes%rowtype; c public.weekly_source_cycles%rowtype;
begin
  if p_actor_user_id is null or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)<>0 then
    raise exception 'WEEKLY_SOURCE_REPORT_PAY_RESOLUTIONS_FORBIDDEN' using errcode='22023'; end if;
  select * into strict p from public.weekly_source_projection_publications where id=p_publication_id;
  perform 1 from public.weekly_source_groups where id=(select source_group_id from public.weekly_source_cycles where id=p.source_cycle_id) for update;
  select * into strict c from public.weekly_source_cycles where id=p.source_cycle_id for update;
  select * into strict s from public.weekly_source_report_scopes where id=p.report_scope_id for update;
  select * into strict p from public.weekly_source_projection_publications where id=p_publication_id for update;
  if p.authority_scope_kind<>'SELF_BILL_REPORT_SCOPE' or s.self_bill_report_id is null or p.state<>'BUILDING'
    or p.correction_session_id is not null or s.current_complete_upload_id is distinct from p.upload_id
    or s.version<>p.authority_scope_version or s.projection_state<>'REBUILDING' then
    raise exception 'WEEKLY_SOURCE_REPORT_PROJECTION_STALE' using errcode='40001'; end if;
  perform private.weekly_source_office_authority_v1(p_actor_user_id,'RECHECK_SOURCE',c.source_group_id,s.client_id,c.finalisation_week_ending);
  perform private.weekly_source_self_bill_report_seal_assert_v1(p.upload_id);
  return jsonb_build_object('ok',true,'status','APPLIED','publication_id',p.id,'rows_applied',0,'expected_rows',0,'invoice_only',true);
end;
$function$;

create or replace function private.weekly_source_self_bill_report_bind_v1(p_publication_id uuid)
returns integer language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_projection_publications%rowtype; c public.weekly_source_cycles%rowtype;
  line record; target record; old public.weekly_source_self_bill_report_line_bindings%rowtype;
  v_count integer; v_event_count integer; v_latest timestamptz; v_added integer:=0; v_prior jsonb;
begin
  select * into strict p from public.weekly_source_projection_publications where id=p_publication_id;
  select * into strict c from public.weekly_source_cycles where id=p.source_cycle_id;
  perform 1 from public.weekly_source_groups where id=c.source_group_id for update;
  if p.state<>'CURRENT' or p.correction_session_id is not null then
    raise exception 'WEEKLY_SOURCE_REPORT_BIND_PUBLICATION_NOT_ACCEPTED' using errcode='55000'; end if;
  -- Accepted is a CURRENT publication under its exact scope head. Metadata
  -- registration, staging and sealed uploads are never membership witnesses.
  for line in select r.*,s.self_bill_report_id,s.client_id from public.weekly_source_report_scopes s
    join public.weekly_source_projection_publications rp on rp.id=s.current_projection_publication_id
      and rp.report_scope_id=s.id and rp.upload_id=s.current_complete_upload_id and rp.state='CURRENT'
      and rp.authority_scope_kind='SELF_BILL_REPORT_SCOPE' and rp.authority_scope_version=s.version
    join public.weekly_source_uploads u on u.id=rp.upload_id and u.state='CURRENT'
    join public.weekly_source_upload_rows r on r.upload_id=u.id and r.row_finalisation_state='SOURCE_REPORT_LINE'
    where s.source_group_id=c.source_group_id and s.self_bill_report_id is not null
      and (p.authority_scope_kind='CYCLE' or rp.id=p.id) order by r.id
  loop
    v_prior:=private.weekly_source_self_bill_report_prior_binding_v1(line.id);
    if v_prior is not null then
      select (v_prior->>'row_id')::uuid as row_id,(v_prior->>'resolution_id')::uuid as resolution_id,
        (v_prior->>'work_event_id')::uuid as work_event_id,(v_prior->>'publication_id')::uuid as publication_id into target;
    else
    select count(distinct rr.work_event_id),max(ep.published_at_utc) into v_event_count,v_latest
      from public.weekly_source_projection_publications ep join public.weekly_source_cycles ec on ec.id=ep.source_cycle_id
      join public.weekly_source_uploads eu on eu.id=ep.upload_id and eu.state='CURRENT'
      join public.weekly_source_upload_rows er on er.upload_id=eu.id and er.external_source_key=line.external_source_key
      join public.weekly_source_row_resolutions rr on rr.upload_row_id=er.id and rr.mapping_state='RESOLVED'
        and rr.generation=coalesce(ep.projection_generation,ep.authority_scope_version)
      where ec.source_group_id=c.source_group_id and ep.authority_scope_kind='CYCLE' and ep.state='CURRENT'
        and ec.current_projection_publication_id=ep.id and ec.current_complete_upload_id=eu.id
        and rr.client_id=line.client_id
        and (p.authority_scope_kind<>'CYCLE' or ep.id=p.id);
    if v_event_count>1 then raise exception 'WEEKLY_SOURCE_REPORT_BIND_IDENTITY_AMBIGUOUS' using errcode='55000'; end if;
    if v_event_count=0 then continue; end if; -- Omission preserves any earlier current binding.
    select count(*) into v_count from public.weekly_source_projection_publications ep
      join public.weekly_source_cycles ec on ec.id=ep.source_cycle_id
      join public.weekly_source_upload_rows er on er.upload_id=ep.upload_id and er.external_source_key=line.external_source_key
      join public.weekly_source_row_resolutions rr on rr.upload_row_id=er.id and rr.mapping_state='RESOLVED'
        and rr.generation=coalesce(ep.projection_generation,ep.authority_scope_version)
      where ec.source_group_id=c.source_group_id and ep.authority_scope_kind='CYCLE' and ep.state='CURRENT'
        and ec.current_projection_publication_id=ep.id and ec.current_complete_upload_id=ep.upload_id
        and rr.client_id=line.client_id and ep.published_at_utc=v_latest
        and (p.authority_scope_kind<>'CYCLE' or ep.id=p.id);
    if v_count<>1 then raise exception 'WEEKLY_SOURCE_REPORT_BIND_GENERATION_AMBIGUOUS' using errcode='55000'; end if;
    select er.id as row_id,rr.id as resolution_id,rr.work_event_id,ep.id as publication_id into strict target
      from public.weekly_source_projection_publications ep join public.weekly_source_cycles ec on ec.id=ep.source_cycle_id
      join public.weekly_source_upload_rows er on er.upload_id=ep.upload_id and er.external_source_key=line.external_source_key
      join public.weekly_source_row_resolutions rr on rr.upload_row_id=er.id and rr.mapping_state='RESOLVED'
        and rr.generation=coalesce(ep.projection_generation,ep.authority_scope_version)
      where ec.source_group_id=c.source_group_id and ep.authority_scope_kind='CYCLE' and ep.state='CURRENT'
        and ec.current_projection_publication_id=ep.id and ec.current_complete_upload_id=ep.upload_id
        and rr.client_id=line.client_id and ep.published_at_utc=v_latest
        and (p.authority_scope_kind<>'CYCLE' or ep.id=p.id);
    end if;
    select * into old from public.weekly_source_self_bill_report_line_bindings where report_row_id=line.id and state='CURRENT' for update;
    if found and old.export_upload_row_id=target.row_id and old.bound_row_resolution_id=target.resolution_id
      and old.export_projection_publication_id=target.publication_id then continue; end if;
    if old.id is not null then
      if old.work_event_id<>target.work_event_id then raise exception 'WEEKLY_SOURCE_REPORT_BIND_IDENTITY_CHANGED' using errcode='55000'; end if;
      update public.weekly_source_self_bill_report_line_bindings set state='SUPERSEDED',superseded_at_utc=transaction_timestamp() where id=old.id;
    end if;
    insert into public.weekly_source_self_bill_report_line_bindings(report_row_id,export_upload_row_id,bound_row_resolution_id,
      export_projection_publication_id,work_event_id,self_bill_report_id,state)
      values(line.id,target.row_id,target.resolution_id,target.publication_id,target.work_event_id,line.self_bill_report_id,'CURRENT');
    v_added:=v_added+1;
  end loop;
  return v_added;
end;
$function$;

create or replace function private.weekly_source_report_shift_facts_v1(p_work_event_id uuid,p_cycle_or_report uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare e public.weekly_work_events%rowtype; c public.weekly_source_cycles%rowtype; s public.weekly_source_report_scopes%rowtype;
  v_on boolean:=false; v_bound boolean:=false; v_ready boolean:=false; v_protected boolean:=false; v_wait jsonb;
  v_pay_export_worked boolean:=false;
begin
  select * into e from public.weekly_work_events where id=p_work_event_id;
  if not found then raise exception 'WEEKLY_SOURCE_SELF_BILL_EVENT_NOT_FOUND' using errcode='22023'; end if;
  select * into c from public.weekly_source_cycles where id=p_cycle_or_report;
  if not found then
    select * into s from public.weekly_source_report_scopes where id=p_cycle_or_report and self_bill_report_id is not null;
    if not found then raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_NOT_FOUND' using errcode='22023'; end if;
    if s.client_id is distinct from e.client_id then
      raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_MISMATCH' using errcode='22023'; end if;
    select * into strict c from public.weekly_source_cycles where id=s.source_cycle_id;
  end if;
  if e.first_source_group_id is distinct from c.source_group_id
    or (c.scope_client_id is not null and c.scope_client_id is distinct from e.client_id)
    or (s.id is not null and (s.source_group_id is distinct from c.source_group_id
      or not exists(select 1 from public.weekly_source_groups source_group where source_group.id=c.source_group_id
        and source_group.agency_id=s.agency_id and source_group.environment=s.environment))) then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_SCOPE_MISMATCH' using errcode='22023'; end if;
  -- The actual event's client is the F1 helper's first parameter.
  if private.weekly_source_effective_rule_set_v1(e.client_id,c.id)#>>'{values,self_bill_source}' is distinct from 'SEPARATE_FINAL_REPORT' then
    return jsonb_build_object('on_accepted_report',false,'bound_to_finalised_export',false,'invoice_ready',false,'s25_pay_selected',false); end if;
  select coalesce(bool_or(true),false),coalesce(bool_or(b.id is not null and er.row_finalisation_state='SOURCE_WORKED'
      and nullif(btrim(er.finalised_by),'') is not null),false),
    coalesce(bool_or(b.id is not null and er.row_finalisation_state='SOURCE_WORKED' and nullif(btrim(er.finalised_by),'') is not null
      and private.weekly_source_self_bill_report_pay_witness_v1(b.id) is not null),false)
    into v_on,v_bound,v_ready
    from public.weekly_source_report_scopes rs
    join public.weekly_source_projection_publications rp on rp.id=rs.current_projection_publication_id
      and rp.upload_id=rs.current_complete_upload_id and rp.report_scope_id=rs.id and rp.state='CURRENT'
      and rp.authority_scope_kind='SELF_BILL_REPORT_SCOPE' and rp.authority_scope_version=rs.version
    join public.weekly_source_uploads ru on ru.id=rp.upload_id and ru.state='CURRENT'
    join public.weekly_source_upload_rows rr on rr.upload_id=ru.id and rr.row_finalisation_state='SOURCE_REPORT_LINE'
    left join public.weekly_source_self_bill_report_line_bindings b on b.report_row_id=rr.id and b.state='CURRENT'
    left join public.weekly_source_upload_rows er on er.id=b.export_upload_row_id
    where rs.source_group_id=c.source_group_id and rs.client_id=e.client_id
      and (s.id is null or rs.id=s.id) and (b.work_event_id=e.id
        or (e.profile_external_key is not null and rr.external_source_key=e.profile_external_key));
  v_wait:=private.weekly_source_protected_wait_witness_v1(e.id,c.id);
  v_protected:=v_wait is not null and v_wait->>'state'='QUALIFIED_WAIT';
  select exists(select 1 from public.weekly_source_projection_publications ep
    join public.weekly_source_uploads eu on eu.id=ep.upload_id and eu.state='CURRENT'
    join public.weekly_source_upload_rows er on er.upload_id=eu.id and er.row_finalisation_state='SOURCE_WORKED'
      and nullif(btrim(er.finalised_by),'') is not null and er.work_date<=c.finalisation_week_ending
    join public.weekly_source_row_resolutions rr on rr.upload_row_id=er.id and rr.mapping_state='RESOLVED'
      and rr.work_event_id=e.id and rr.client_id=e.client_id and rr.generation=coalesce(ep.projection_generation,ep.authority_scope_version)
    where ep.id=c.current_projection_publication_id and ep.upload_id=c.current_complete_upload_id
      and ep.authority_scope_kind='CYCLE' and ep.state='CURRENT') into v_pay_export_worked;
  return jsonb_build_object('on_accepted_report',v_on,'bound_to_finalised_export',v_bound,
    'invoice_ready',v_bound and v_ready,'s25_pay_selected',v_protected or (v_bound and v_pay_export_worked));
end;
$function$;

-- Complete F8/NHSP released-client owner plus exact report branch.
create or replace function public.weekly_source_upload_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_allowed constant text[]:=array[
    'operation','actor_user_id','source_group_id','source_cycle_id',
    'report_scope_id','client_id','upload_id'
  ]::text[];
  v_operation text;
  v_actor uuid;
  v_group_id uuid;
  v_cycle_id uuid;
  v_report_scope_id uuid;
  v_client_id uuid;
  v_row_client_id uuid;
  v_upload_id uuid;
  v_group public.weekly_source_groups%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_office_choice private.weekly_source_office_row_choices%rowtype;
  v_source_name text;
  v_source_id text;
  v_source_id_2 text;
  v_source_id_3 text;
  v_source_client text;
  v_norm_name text;
  v_norm_compact text;
  v_candidate_ids uuid[];
  v_candidate_id uuid;
  v_candidate_matches jsonb;
  v_contracts jsonb;
  v_prior_contract_id uuid;
  v_prior_work_event_id uuid;
  -- WP-37: the `24 §9` step-2 compatible-schedule set, counted explicitly.
  v_prior_candidate_count integer;
  v_rows jsonb:='[]'::jsonb;
  v_client_name text;
  v_client_choices jsonb:='[]'::jsonb;
  v_client_choice_count integer:=0;
  v_unknown text;
  v_coverage_context jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown
  from pg_catalog.jsonb_object_keys(p_request) key
  where not key=any(v_allowed)
  order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_CONTEXT_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown;
  end if;
  begin
    v_operation:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'operation','')));
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_group_id:=nullif(p_request->>'source_group_id','')::uuid;
    v_cycle_id:=nullif(p_request->>'source_cycle_id','')::uuid;
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_client_id:=nullif(p_request->>'client_id','')::uuid;
    v_upload_id:=nullif(p_request->>'upload_id','')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_operation not in ('DISCOVER_SCOPE','BUILD_PROJECTION') then
    raise exception 'WEEKLY_SOURCE_CONTEXT_REQUEST_INVALID' using errcode='22023';
  end if;

  if v_operation='BUILD_PROJECTION' then
    if v_upload_id is null then
      raise exception 'WEEKLY_SOURCE_CONTEXT_UPLOAD_REQUIRED' using errcode='22023';
    end if;
    select * into v_upload from public.weekly_source_uploads where id=v_upload_id;
    if not found or v_upload.state not in ('CURRENT','CORRECTION_READY')
       or v_upload.row_manifest_hash is null then
      raise exception 'WEEKLY_SOURCE_CONTEXT_UPLOAD_NOT_SEALED' using errcode='55000';
    end if;
    v_cycle_id:=v_upload.source_cycle_id;
    v_report_scope_id:=v_upload.report_scope_id;
  elsif v_cycle_id is null then
    raise exception 'WEEKLY_SOURCE_CONTEXT_SCOPE_REQUIRED' using errcode='22023';
  end if;

  select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CONTEXT_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  if not found or not v_group.active
     or (v_group_id is not null and v_group.id is distinct from v_group_id) then
    raise exception 'WEEKLY_SOURCE_CONTEXT_GROUP_MISMATCH' using errcode='22023';
  end if;
  v_group_id:=v_group.id;

  if v_report_scope_id is not null then
    select * into v_scope
    from public.weekly_source_report_scopes where id=v_report_scope_id;
    if not found or not ((v_group.source_family='NHSP' and v_scope.self_bill_report_id is null)
      or (v_group.source_family='ROSTER' and v_scope.self_bill_report_id is not null))
       or v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc
       or (v_client_id is not null and v_scope.client_id is distinct from v_client_id) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_REPORT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    v_client_id:=v_scope.client_id;
    if v_scope.self_bill_report_id is not null then
      perform private.weekly_source_self_bill_report_rules_assert_v1(v_client_id,v_cycle.id);
    end if;
  else
    if v_group.source_family='NHSP' and v_operation='BUILD_PROJECTION'
       and exists(
         select 1 from public.weekly_source_format_profiles profile
         where profile.id=v_upload.source_format_profile_id
           and profile.profile_code='NHSP_FINAL_BACKING_V1'
       ) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_REPORT_SCOPE_REQUIRED' using errcode='22023';
    end if;
    if v_operation='BUILD_PROJECTION' then
      begin
        v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
      exception when invalid_text_representation then
        raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_INVALID' using errcode='55000';
      end;
    end if;
    if v_client_id is not null and not exists(
      select 1 from public.weekly_source_group_clients membership
      where membership.source_group_id=v_group.id
        and membership.client_id=v_client_id
        and v_cycle.finalisation_week_ending between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
    ) then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_SCOPE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if v_client_id is not null then
    if v_operation='BUILD_PROJECTION' and v_cycle.scope_client_id is not null and v_cycle.scope_client_id<>v_client_id then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    select client.name into strict v_client_name
    from public.clients client where client.id=v_client_id;
  elsif v_group.source_family='ROSTER' then
    select pg_catalog.count(*),coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('client_id',client.id,'client_name',client.name)
      order by client.name,client.id
    ),'[]'::jsonb)
      into v_client_choice_count,v_client_choices
    from public.weekly_source_group_clients membership
    join public.clients client on client.id=membership.client_id
    where membership.source_group_id=v_group.id
      and v_cycle.finalisation_week_ending between membership.valid_from
        and coalesce(membership.valid_to,'infinity'::date);
    if v_client_choice_count=1 then
      v_client_id:=(v_client_choices->0->>'client_id')::uuid;
      v_client_name:=v_client_choices->0->>'client_name';
    elsif v_client_choice_count=0 then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_NOT_FOUND' using errcode='22023';
    end if;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,
    case when v_operation='DISCOVER_SCOPE' then 'UPLOAD_SOURCE' else 'RECHECK_SOURCE' end,
    v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  if v_operation='BUILD_PROJECTION' and v_scope.self_bill_report_id is not null then
    perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
    return jsonb_build_object('ok',true,'context_version','WEEKLY_SOURCE_UPLOAD_CONTEXT_V1',
      'source_group_id',v_group.id,'source_cycle_id',v_cycle.id,'report_scope_id',v_scope.id,
      'client_id',v_client_id,'client_name',v_client_name,'upload_id',v_upload.id,
      'self_bill_report_id',v_scope.self_bill_report_id,'invoice_only',true,'rows','[]'::jsonb);
  end if;
  if v_operation='DISCOVER_SCOPE' then
    if v_scope.self_bill_report_id is null then
      v_coverage_context:=private.weekly_source_upload_coverage_context_v1(v_client_id,v_cycle.id);
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'context_version','WEEKLY_SOURCE_UPLOAD_CONTEXT_V1',
      'environment',v_group.environment,'agency_id',v_group.agency_id,
      'source_group_id',v_group.id,'source_group_code',v_group.code,
      'source_group_name',v_group.display_name,'source_family',v_group.source_family,
      'source_cycle_id',v_cycle.id,'finalisation_week_ending',v_cycle.finalisation_week_ending,
      'cutoff_at_utc',v_cycle.cutoff_at_utc,'cycle_state',v_cycle.state,
      'previous_coverage',(
        select pg_catalog.jsonb_build_object(
          'start_local_date',prior.confirmed_coverage_start_local_date,
          'end_local_date',prior.confirmed_coverage_end_local_date
        )
        from public.weekly_source_uploads prior
        where prior.id=case when v_report_scope_id is null then v_cycle.current_complete_upload_id else v_scope.current_complete_upload_id end
          and prior.state='CURRENT'
      ),
      'report_scope_id',v_report_scope_id,'client_id',v_client_id,
      'client_name',v_client_name,'nhsp_report_heading_name',v_group.nhsp_report_heading_name,
      'effective_rule_set',private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id),
      'client_selection_required',v_group.source_family='ROSTER' and v_client_id is null,
      'client_choices',v_client_choices,
      'authority_scope_version',case when v_report_scope_id is null then v_cycle.version else v_scope.version end,
      'authority_scope_kind',case when v_report_scope_id is null then 'CYCLE'
        when v_scope.self_bill_report_id is null then 'NHSP_REPORT_SCOPE' else 'SELF_BILL_REPORT_SCOPE' end
    )||case when v_coverage_context is null then '{}'::jsonb
      else jsonb_build_object('coverage_context',v_coverage_context) end;
  end if;

  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;

  for v_source_row in
    select source_row.*
    from public.weekly_source_upload_rows source_row
    where source_row.upload_id=v_upload.id
    order by source_row.source_row_ordinal,source_row.id
  loop
    -- Released reports identify the client on each row. A legacy upload-level
    -- client hint must not silently assign every row to that one client.
    v_row_client_id:=case when v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
      then null else v_client_id end;
    select * into v_office_choice from private.weekly_source_office_row_choices
      where upload_row_id=v_source_row.id order by id desc limit 1;
    v_source_name:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'worker_name',
      v_source_row.bounded_raw_columns_json->>'candidate',
      v_source_row.source_candidate_identity
    )), '');
    v_source_id:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'worker_unique_id',
      v_source_row.bounded_raw_columns_json->>'candidate_id',''
    )), '');
    v_source_id_2:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'candidate_uid',''
    )), '');
    v_source_id_3:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'payroll_number',''
    )), '');
    v_source_client:=nullif(pg_catalog.btrim(coalesce(
      v_source_row.bounded_raw_columns_json->>'trust',
      v_source_row.source_client_identity
    )), '');
    if v_row_client_id is null and v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1' then
      select case when pg_catalog.count(*)=1 then pg_catalog.min(client.id::text)::uuid end
        into v_row_client_id
      from public.clients client
      where private.weekly_source_upload_client_eligible_v1(
          v_upload.id,client.id,v_source_row.work_date)
        and pg_catalog.lower(pg_catalog.btrim(client.name))=
          pg_catalog.lower(pg_catalog.btrim(coalesce(v_source_client,'')));
    end if;
    if v_office_choice.client_id is not null then
      select client.id into v_row_client_id
      from public.clients client
      where client.id=v_office_choice.client_id
        and private.weekly_source_upload_client_eligible_v1(
          v_upload.id,client.id,v_source_row.work_date);
    end if;
    v_norm_name:=pg_catalog.lower(pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(v_source_name,'')),'[[:space:]]+',' ','g'
    ));
    v_norm_compact:=pg_catalog.regexp_replace(v_norm_name,'[^a-z0-9]+','','g');

    select coalesce(pg_catalog.array_agg(candidate_id order by candidate_id),'{}'::uuid[])
      into v_candidate_ids
    from (
      select distinct candidate.id as candidate_id
      from public.candidates candidate
      where candidate.active
        and (
          (v_source_id is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id))
          or (v_source_id_2 is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id_2))
          or (v_source_id_3 is not null and pg_catalog.lower(pg_catalog.btrim(candidate.tms_ref))=
             pg_catalog.lower(v_source_id_3))
          or exists(
            select 1
            from pg_catalog.jsonb_array_elements_text(
              case when pg_catalog.jsonb_typeof(candidate.nhsp_hr_name_aliases)='array'
                then candidate.nhsp_hr_name_aliases else '[]'::jsonb end
            ) alias(value)
            where pg_catalog.lower(pg_catalog.btrim(alias.value))=v_norm_name
               or pg_catalog.regexp_replace(pg_catalog.lower(alias.value),'[^a-z0-9]+','','g')=v_norm_compact
          )
          or exists(
            select 1 from public.hr_name_mappings mapping
            where mapping.active and mapping.candidate_id=candidate.id
              and (
                pg_catalog.lower(pg_catalog.btrim(mapping.hr_name_norm))=v_norm_name
                or pg_catalog.regexp_replace(pg_catalog.lower(mapping.hr_name_norm),'[^a-z0-9]+','','g')=v_norm_compact
              )
              and (nullif(pg_catalog.btrim(coalesce(mapping.hospital_or_trust,'')),'') is null
                or pg_catalog.lower(pg_catalog.btrim(mapping.hospital_or_trust))=
                   pg_catalog.lower(pg_catalog.btrim(coalesce(v_source_client,''))))
          )
        )
    ) exact_saved;
    if v_office_choice.candidate_id is not null then
      select coalesce(pg_catalog.array_agg(id),'{}'::uuid[]) into v_candidate_ids
        from public.candidates where id=v_office_choice.candidate_id and active;
    end if;
    v_candidate_id:=case when pg_catalog.cardinality(v_candidate_ids)=1 then v_candidate_ids[1] end;
    select coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'candidate_id',candidate.id,'display_name',coalesce(nullif(candidate.display_name,''),
          pg_catalog.btrim(coalesce(candidate.first_name,'')||' '||coalesce(candidate.last_name,''))),
        'tms_ref',candidate.tms_ref
      ) order by candidate.id
    ),'[]'::jsonb) into v_candidate_matches
    from public.candidates candidate where candidate.id=any(v_candidate_ids);

    v_contracts:='[]'::jsonb;
    v_prior_contract_id:=null;
    v_prior_work_event_id:=null;
    v_prior_candidate_count:=0;
    if v_candidate_id is not null and v_row_client_id is not null then
      select coalesce(pg_catalog.jsonb_agg(contract_item order by contract_item->>'contract_id'),'[]'::jsonb)
        into v_contracts
      from (
        select pg_catalog.jsonb_build_object(
          'contract_id',contract.id,
          'candidate_id',contract.candidate_id,
          'client_id',contract.client_id,
          'valid_from',contract.start_date,
          'valid_to',contract.end_date,
          'display_label',pg_catalog.concat_ws(' · ',nullif(contract.role,''),nullif(contract.band,''),nullif(contract.display_site,'')),
          'role',contract.role,'band',contract.band,
          'pay_type',contract.pay_method_snapshot,
          'rates_json',contract.rates_json,
          'contract_updated_at',contract.updated_at,
          'weekly_source_applicable',true,
          'schedule_compatible',private.weekly_source_schedule_compatible_v1(
            contract.std_schedule_json,v_source_row.work_date
          ),
          'verified_role_band_match',private.weekly_source_verified_role_band_match_v1(
            case when v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1')
              then 'NHSP' else 'HR_WEEKLY' end,
            v_source_row.role_band_source,v_candidate_id,v_row_client_id,
            contract.id,contract.band,v_source_row.work_date
          ),
          'effective_policy',private._weekly_source_effective_policy_v1(
            v_row_client_id,contract.id,v_source_row.work_date
          ),
          'effective_rule_set',private.weekly_source_effective_rule_set_v1(v_row_client_id,v_cycle.id),
          'settings_authority',private._contract_settings_effective_core_v1(
            v_row_client_id,contract.id,v_source_row.work_date,'IMPORT',null
          )
        ) contract_item
        from public.contracts contract
        where contract.candidate_id=v_candidate_id
          and contract.client_id=v_row_client_id
          and v_source_row.work_date between contract.start_date and coalesce(contract.end_date,'infinity'::date)
      ) eligible;

      -- G6-13 / XSG-010.  Only the three roster profiles use the source
      -- system's own line identity as the durable work-event key.  An NHSP
      -- Reference Number is evidence, never sole durable identity
      -- (`24 §9`; `25 §7` Removed), so NHSP lineage resolves through the
      -- schedule tuple below, exactly as the publication owner now keys it.
      if v_profile.profile_code in (
        'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
        'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
        'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
      ) and nullif(pg_catalog.btrim(coalesce(v_source_row.external_source_key,'')),'') is not null then
        select event.id,resolution.contract_id
          into v_prior_work_event_id,v_prior_contract_id
        from public.weekly_work_events event
        left join lateral (
          select saved.contract_id
          from public.weekly_source_row_resolutions saved
          where saved.work_event_id=event.id and saved.mapping_state='RESOLVED'
          order by saved.created_at_utc desc,saved.id desc limit 1
        ) resolution on true
        where event.first_source_group_id=v_group.id
          and event.source_format_profile_id=v_profile.id
          and event.identity_kind='PROFILE_EXTERNAL_KEY'
          and event.profile_external_key=v_source_row.external_source_key
          and event.candidate_id=v_candidate_id and event.client_id=v_row_client_id
        order by event.created_at_utc,event.id limit 1;
      else
        -- WP-37, against `24 §9` step 2.  The pack keys identity on "exact
        -- Candidate, actual Client, worked date and **compatible** schedule",
        -- so lineage must NOT demand exact Actual start and end: `24 §6.2`
        -- ("Paid eight hours becomes nine") is a later source change on ONE
        -- root, and an NHSP correction routinely moves the times.  The
        -- cardinality is checked explicitly: none means new work, and more than
        -- one is `24 §9` step 4 (Office confirmation), where nothing is
        -- suggested and the server refuses to guess.
        select pg_catalog.count(*)::integer,
               pg_catalog.min(event.id::text)::uuid
          into v_prior_candidate_count,v_prior_work_event_id
        from public.weekly_work_events event
        where event.first_source_group_id=v_group.id
          and event.source_format_profile_id=v_profile.id
          and event.identity_kind='SCHEDULE_TUPLE'
          and event.candidate_id=v_candidate_id and event.client_id=v_row_client_id
          and event.work_date=v_source_row.work_date
          and private.weekly_source_work_event_schedule_compatible_v1(
                event.id,v_source_row.start_at_local,v_source_row.end_at_local
              );
        if v_prior_candidate_count<>1 then
          v_prior_work_event_id:=null;
        else
          -- The Contract is a SUGGESTION only: `weekly_source_projection_build_v1`
          -- re-proves DURABLE_LINEAGE against a prior RESOLVED resolution for
          -- this same work event before it will accept the selection method.
          select saved.contract_id into v_prior_contract_id
          from public.weekly_source_row_resolutions saved
          where saved.work_event_id=v_prior_work_event_id
            and saved.mapping_state='RESOLVED'
          order by saved.created_at_utc desc,saved.id desc limit 1;
        end if;
      end if;
    end if;

    v_rows:=v_rows||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'upload_row_id',v_source_row.id,
      'source_row_ordinal',v_source_row.source_row_ordinal,
      'external_source_key',v_source_row.external_source_key,
      'source_candidate_identity',v_source_row.source_candidate_identity,
      'source_client_identity',v_source_row.source_client_identity,
      'work_date',v_source_row.work_date,
      'start_at_local',v_source_row.start_at_local,
      'end_at_local',v_source_row.end_at_local,
      'break_minutes',v_source_row.break_minutes,
      'actual_net_minutes',v_source_row.actual_net_minutes,
      'row_finalisation_state',v_source_row.row_finalisation_state,
      'role_band_source',v_source_row.role_band_source,
      'source_commission_pence',v_source_row.source_commission_pence,
      'source_total_cost_pence',v_source_row.source_total_cost_pence,
      'source_shift_charge_pence',v_source_row.source_shift_charge_pence,
      'source_gross_pence',v_source_row.source_gross_pence,'source_vat_pence',v_source_row.source_vat_pence,
      'finalised_at_utc',v_source_row.finalised_at_utc,
      'source_money_parse_state',v_source_row.source_money_parse_state,
      'source_expense_pence',v_source_row.source_expense_pence,
      'source_expense_parse_state',v_source_row.source_expense_parse_state,
      'candidate_match_count',pg_catalog.cardinality(v_candidate_ids),
      'candidate_matches',v_candidate_matches,
      'candidate_id',v_candidate_id,
      'office_selected_contract_id',v_office_choice.contract_id,
      'office_selected_work_event_id',v_office_choice.work_event_id,
      'office_separate_shift',coalesce(v_office_choice.separate_shift,false),
      'protected_matches',private.weekly_source_protected_match_candidates_v1(v_source_row.id,v_candidate_id,v_row_client_id),
      'client_id',v_row_client_id,
      'contracts',v_contracts,
      'prior_accepted_contract_id',v_prior_contract_id,
      'prior_work_event_id',v_prior_work_event_id,
      -- `24 §9` step 4.  True means more than one plausible existing work
      -- record remains, so Office must confirm the relationship; the server
      -- refuses to publish the row until it does.
      'prior_work_event_ambiguous',v_prior_candidate_count>1
    ));
  end loop;

  if v_upload.correction_session_id is not null then
    select publication.* into v_publication
    from public.weekly_final_source_correction_sessions correction
    join public.weekly_source_projection_publications publication
      on publication.id=correction.replacement_projection_publication_id
    where correction.id=v_upload.correction_session_id
      and correction.replacement_correction_upload_id=v_upload.id
      and publication.upload_id=v_upload.id
      and publication.correction_session_id=correction.id
      and publication.state='CORRECTION_READY';
  else
    select publication.* into v_publication
    from public.weekly_source_projection_publications publication
    where publication.upload_id=v_upload.id
      and publication.state='CURRENT'
    order by publication.published_at_utc desc nulls last,publication.id desc
    limit 1;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'context_version','WEEKLY_SOURCE_PROJECTION_CONTEXT_V1',
    'environment',v_group.environment,'agency_id',v_group.agency_id,
    'source_group_id',v_group.id,'source_family',v_group.source_family,
    'source_cycle_id',v_cycle.id,'report_scope_id',v_report_scope_id,
    'client_id',v_client_id,'client_name',v_client_name,
    'profile_id',v_profile.profile_code,'profile_version',v_profile.version,
    'upload_id',v_upload.id,
    'row_manifest_hash',case when v_upload.row_manifest_hash is null then null
      else pg_catalog.encode(v_upload.row_manifest_hash,'hex') end,
    'projection_publication_id',v_publication.id,
    'projection_state',v_publication.state,
    'comparison_manifest_hash',case when v_publication.comparison_manifest_hash is null then null
      else pg_catalog.encode(v_publication.comparison_manifest_hash,'hex') end,
    'issue_set_hash',case when v_publication.issue_set_hash is null then null
      else pg_catalog.encode(v_publication.issue_set_hash,'hex') end,
    'correction_session_id',v_upload.correction_session_id,
    'correction_session_version',case when v_upload.correction_session_id is null then null else (
      select correction.version
      from public.weekly_final_source_correction_sessions correction
      where correction.id=v_upload.correction_session_id
    ) end,
    'authority_scope_kind',case when v_report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end,
    'authority_scope_version',coalesce(v_scope.version,v_cycle.version),
    'rows',v_rows
  );
end;
$function$;

-- Complete native successor; bounded report arm only. Root composes later shared owner hunks.
create or replace function public.weekly_source_upload_stage_begin_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','environment','agency_id','source_group_id','source_cycle_id',
    'report_scope_id','client_id','original_filename','content_sha256','byte_count',
    'profile_code','profile_version','parser_version','normaliser_version',
    'workbook_part_and_sheet_fingerprint','header_coordinate_map_json',
    'header_coordinate_map_hash','money_lexical_authority_version','purpose',
    'correction_session_id','expected_correction_session_version','declared_scope_fingerprint',
    'suggested_coverage_start_local_date','suggested_coverage_end_local_date',
    'confirmed_coverage_start_local_date','confirmed_coverage_end_local_date',
    'coverage_timezone','coverage_confirmation_version','coverage_confirmed_at_utc',
    'coverage_shrink_acknowledged','coverage_state','coverage_proof_kind',
    'physical_row_count','header_count','trailer_count','continuation_count',
    'accepted_count','blocking_economic_duplicate_count','malformed_count',
    'blocked_count','file_metadata_json','parser_summary_json'
  ]::text[];
  v_actor uuid;
  v_environment text;
  v_agency uuid;
  v_group_id uuid;
  v_cycle_id uuid;
  v_report_scope_id uuid;
  v_client_id uuid;
  v_group public.weekly_source_groups%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_purpose text;
  v_content bytea;
  v_workbook_fingerprint bytea;
  v_header_map jsonb;
  v_header_hash bytea;
  v_declared bytea;
  v_computed_scope bytea;
  v_metadata jsonb;
  v_summary jsonb;
  v_report_number text;
  v_existing public.weekly_source_uploads%rowtype;
  v_upload_id uuid;
  v_attempt_id uuid;
  v_unknown_key text;
  v_profile_version integer;
  v_physical integer;
  v_header integer;
  v_trailer integer;
  v_continuation integer;
  v_accepted integer;
  v_duplicate integer;
  v_malformed integer;
  v_blocked integer;
  v_byte_count bigint;
  v_suggested_start date;
  v_suggested_end date;
  v_confirmed_start date;
  v_confirmed_end date;
  v_coverage_timezone text;
  v_confirmation_version text;
  v_coverage_state text;
  v_proof_kind text;
  v_profile_identity text;
  v_expected_correction_version bigint;
  v_report public.weekly_source_self_bill_reports%rowtype;
begin
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_UPLOAD_REQUEST_INVALID' using errcode='22023';
  end if;

  select key into v_unknown_key
  from pg_catalog.jsonb_object_keys(p_request) key
  where not (key=any(v_allowed_keys))
  order by key
  limit 1;
  if v_unknown_key is not null then
    raise exception 'WEEKLY_SOURCE_UPLOAD_REQUEST_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown_key;
  end if;

  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_environment:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'environment','')));
    v_agency:=(p_request->>'agency_id')::uuid;
    v_group_id:=(p_request->>'source_group_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_client_id:=nullif(p_request->>'client_id','')::uuid;
    v_profile_version:=(p_request->>'profile_version')::integer;
    v_byte_count:=(p_request->>'byte_count')::bigint;
    v_physical:=(p_request->>'physical_row_count')::integer;
    v_header:=coalesce((p_request->>'header_count')::integer,0);
    v_trailer:=coalesce((p_request->>'trailer_count')::integer,0);
    v_continuation:=coalesce((p_request->>'continuation_count')::integer,0);
    v_accepted:=coalesce((p_request->>'accepted_count')::integer,0);
    v_duplicate:=coalesce((p_request->>'blocking_economic_duplicate_count')::integer,0);
    v_malformed:=coalesce((p_request->>'malformed_count')::integer,0);
    v_blocked:=coalesce((p_request->>'blocked_count')::integer,0);
    v_suggested_start:=nullif(p_request->>'suggested_coverage_start_local_date','')::date;
    v_suggested_end:=nullif(p_request->>'suggested_coverage_end_local_date','')::date;
    v_confirmed_start:=nullif(p_request->>'confirmed_coverage_start_local_date','')::date;
    v_confirmed_end:=nullif(p_request->>'confirmed_coverage_end_local_date','')::date;
    v_expected_correction_version:=nullif(p_request->>'expected_correction_session_version','')::bigint;
  exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
    raise exception 'WEEKLY_SOURCE_UPLOAD_REQUEST_TYPE_INVALID' using errcode='22023';
  end;

  if v_environment not in ('TEST','LIVE') or v_agency is null
     or v_group_id is null or v_cycle_id is null or v_actor is null then
    raise exception 'WEEKLY_SOURCE_UPLOAD_SCOPE_REQUIRED' using errcode='22023';
  end if;
  if nullif(pg_catalog.btrim(coalesce(p_request->>'original_filename','')),'') is null
     or pg_catalog.char_length(p_request->>'original_filename')>255 then
    raise exception 'WEEKLY_SOURCE_FILENAME_INVALID' using errcode='22023';
  end if;
  if v_byte_count is null or v_byte_count<=0
     or v_physical is null or least(v_physical,v_header,v_trailer,v_continuation,
       v_accepted,v_duplicate,v_malformed,v_blocked)<0 then
    raise exception 'WEEKLY_SOURCE_DECLARED_COUNTS_INVALID' using errcode='22023';
  end if;

  v_content:=private.weekly_source_hex32_v1(
    p_request->>'content_sha256','WEEKLY_SOURCE_CONTENT_HASH_INVALID'
  );
  v_header_map:=coalesce(p_request->'header_coordinate_map_json','{}'::jsonb);
  v_metadata:=coalesce(p_request->'file_metadata_json','{}'::jsonb);
  v_summary:=coalesce(p_request->'parser_summary_json','{}'::jsonb);
  if pg_catalog.jsonb_typeof(v_header_map)<>'object'
     or pg_catalog.jsonb_typeof(v_metadata)<>'object'
     or pg_catalog.jsonb_typeof(v_summary)<>'object' then
    raise exception 'WEEKLY_SOURCE_UPLOAD_OBJECT_INVALID' using errcode='22023';
  end if;
  v_header_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_HEADER_COORDINATE_MAP_V1',v_header_map
  );
  if nullif(p_request->>'header_coordinate_map_hash','') is not null
     and private.weekly_source_hex32_v1(
       p_request->>'header_coordinate_map_hash','WEEKLY_SOURCE_HEADER_MAP_HASH_INVALID'
     ) is distinct from v_header_hash then
    raise exception 'WEEKLY_SOURCE_HEADER_MAP_HASH_MISMATCH' using errcode='22023';
  end if;
  v_workbook_fingerprint:=case
    when nullif(p_request->>'workbook_part_and_sheet_fingerprint','') is null then null
    else private.weekly_source_hex32_v1(
      p_request->>'workbook_part_and_sheet_fingerprint',
      'WEEKLY_SOURCE_WORKBOOK_FINGERPRINT_INVALID'
    ) end;

  select * into v_group from public.weekly_source_groups where id=v_group_id;
  if not found or not v_group.active
     or v_group.environment is distinct from v_environment
     or v_group.agency_id is distinct from v_agency then
    raise exception 'WEEKLY_SOURCE_GROUP_SCOPE_MISMATCH' using errcode='22023';
  end if;
  select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  if not found or v_cycle.source_group_id is distinct from v_group_id then
    raise exception 'WEEKLY_SOURCE_CYCLE_SCOPE_MISMATCH' using errcode='22023';
  end if;
  select * into v_profile
  from public.weekly_source_format_profiles
  where profile_code=pg_catalog.btrim(coalesce(p_request->>'profile_code',''))
    and version=v_profile_version;
  if not found or not v_profile.active or v_profile.scheduled_hours_fallback then
    raise exception 'WEEKLY_SOURCE_PROFILE_NOT_RELEASED' using errcode='22023';
  end if;
  if v_profile.profile_code not in (
    'NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1',
    'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
    'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
    'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1','ACACIUM_SELF_BILL_REPORT_V1'
  ) or v_profile.version<>1 then
    raise exception 'WEEKLY_SOURCE_PROFILE_NOT_ADMITTED' using errcode='22023';
  end if;
  -- An approved workbook profile may also arrive as one self-contained
  -- data-bearing HTML table (including NHSP's Excel-exported .xls). Only
  -- the server parser identifies that container; HTML has no OOXML part to
  -- fingerprint, while an actual XLSX must retain its selected-part proof.
  if v_profile.container_kind='XLSX' then
    if pg_catalog.upper(pg_catalog.btrim(coalesce(v_summary->>'source_kind','XLSX')))
       not in ('XLSX','HTML')
       or (pg_catalog.upper(pg_catalog.btrim(coalesce(v_summary->>'source_kind','XLSX')))='XLSX')
          is distinct from (v_workbook_fingerprint is not null) then
      raise exception 'WEEKLY_SOURCE_WORKBOOK_FINGERPRINT_REQUIRED' using errcode='22023';
    end if;
  elsif v_workbook_fingerprint is not null then
    raise exception 'WEEKLY_SOURCE_WORKBOOK_FINGERPRINT_REQUIRED' using errcode='22023';
  end if;
  if v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1') then
    if nullif(p_request->>'money_lexical_authority_version','') is distinct from
       'XLSX_BINARY64_SAME_VALUE_PENCE_V1' then
      raise exception 'WEEKLY_SOURCE_NHSP_MONEY_AUTHORITY_INVALID' using errcode='22023';
    end if;
  elsif v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' then
    if p_request->>'money_lexical_authority_version' is distinct from 'SOURCE_INVOICE_MONEY_PENCE_V1' then
      raise exception 'WEEKLY_SOURCE_REPORT_MONEY_AUTHORITY_INVALID' using errcode='22023'; end if;
  elsif nullif(p_request->>'money_lexical_authority_version','') is not null then
    raise exception 'WEEKLY_SOURCE_MONEY_AUTHORITY_NOT_ALLOWED' using errcode='22023';
  end if;

  v_purpose:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'purpose','ORDINARY')));
  if v_purpose not in ('ORDINARY','FINAL_SOURCE_CORRECTION') then
    raise exception 'WEEKLY_SOURCE_UPLOAD_PURPOSE_INVALID' using errcode='22023';
  end if;
  if nullif(pg_catalog.btrim(coalesce(p_request->>'parser_version','')),'') is null
     or nullif(pg_catalog.btrim(coalesce(p_request->>'normaliser_version','')),'') is null then
    raise exception 'WEEKLY_SOURCE_PARSER_VERSION_REQUIRED' using errcode='22023';
  end if;
  v_coverage_timezone:=nullif(pg_catalog.btrim(coalesce(p_request->>'coverage_timezone','')),'');
  v_confirmation_version:=nullif(pg_catalog.btrim(coalesce(p_request->>'coverage_confirmation_version','')),'');
  v_coverage_state:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'coverage_state','')));
  v_proof_kind:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'coverage_proof_kind','')));

  if v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' then
    if v_group.source_family<>'ROSTER' or v_report_scope_id is null or v_purpose<>'ORDINARY'
      or v_proof_kind<>'SELF_BILL_REPORT_SCOPE' or v_confirmed_start is not null or v_confirmed_end is not null
      or v_suggested_start is not null or v_suggested_end is not null
      or v_profile.final_authority_kind<>'SELF_BILL_REPORT' or v_profile.omission_meaning<>'NO_INFERENCE'
      or not v_profile.single_client_required or not v_profile.report_number_required then
      raise exception 'WEEKLY_SOURCE_REPORT_PROFILE_SCOPE_INVALID' using errcode='22023'; end if;
    select * into v_scope from public.weekly_source_report_scopes where id=v_report_scope_id;
    if not found or v_scope.self_bill_report_id is null or v_scope.source_cycle_id is distinct from v_cycle_id
      or v_scope.source_group_id is distinct from v_group_id or v_scope.environment is distinct from v_environment
      or v_scope.agency_id is distinct from v_agency or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc
      or v_scope.client_id is distinct from v_client_id then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_MISMATCH' using errcode='22023'; end if;
    select * into strict v_report from public.weekly_source_self_bill_reports where id=v_scope.self_bill_report_id;
    perform private.weekly_source_self_bill_report_rules_assert_v1(v_client_id,v_cycle_id);
    if v_report.content_sha256 is distinct from v_content or v_report.line_count is distinct from v_accepted
      or v_metadata->>'self_bill_report_id' is distinct from v_report.id::text
      or v_metadata->>'report_number' is distinct from v_report.report_number
      or v_metadata->>'invoice_date' is distinct from v_report.invoice_date::text
      or v_metadata->>'report_layout' is distinct from v_report.layout then
      raise exception 'WEEKLY_SOURCE_REPORT_REGISTERED_IDENTITY_MISMATCH' using errcode='22023'; end if;
    v_metadata:=v_metadata||jsonb_build_object('client_id',v_client_id);
  elsif v_profile.profile_code='NHSP_FINAL_BACKING_V1' then
    if v_group.source_family<>'NHSP' or v_report_scope_id is null
       or v_profile.final_authority_kind<>'NHSP_TRUST_BACKING_REPORT'
       or v_profile.omission_meaning<>'NO_INFERENCE'
       or not v_profile.report_number_required
       or not v_profile.fmc_must_equal_zero then
      raise exception 'WEEKLY_SOURCE_NHSP_FINAL_PROFILE_INVALID' using errcode='22023';
    end if;
    select * into v_scope
    from public.weekly_source_report_scopes
    where id=v_report_scope_id;
    if not found or v_scope.source_cycle_id is distinct from v_cycle_id
       or v_scope.environment is distinct from v_environment
       or v_scope.agency_id is distinct from v_agency
       or v_scope.source_group_id is distinct from v_group_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_NHSP_REPORT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    v_client_id:=v_scope.client_id;
    if nullif(p_request->>'client_id','') is not null
       and (p_request->>'client_id')::uuid is distinct from v_client_id then
      raise exception 'WEEKLY_SOURCE_NHSP_CLIENT_MISMATCH' using errcode='22023';
    end if;
    v_report_number:=private.weekly_source_canonical_report_number_v1(
      v_metadata->>'nhsp_report_number'
    );
    if v_report_number is null
       or nullif(pg_catalog.btrim(coalesce(v_metadata->>'nhsp_report_heading_name','')),'')
          is distinct from pg_catalog.btrim(v_group.nhsp_report_heading_name)
       or v_proof_kind<>'NHSP_TRUST_REPORT_SCOPE'
       or v_confirmed_start is not null or v_confirmed_end is not null then
      raise exception 'WEEKLY_SOURCE_NHSP_REPORT_IDENTITY_INVALID' using errcode='22023';
    end if;
    v_metadata:=v_metadata||pg_catalog.jsonb_build_object(
      'nhsp_report_number',v_report_number,'client_id',v_client_id
    );
  elsif v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1' then
    if v_group.source_family<>'NHSP' or v_report_scope_id is not null
       or v_profile.profile_json->>'purpose'<>'PREFINAL_CHECKING'
       or v_profile.row_finalisation_capability<>'CHECKING_ONLY' then
      raise exception 'WEEKLY_SOURCE_NHSP_PREFINAL_SCOPE_INVALID' using errcode='22023';
    end if;
  else
    if v_group.source_family<>'ROSTER' or v_report_scope_id is not null then
      raise exception 'WEEKLY_SOURCE_ROSTER_SCOPE_INVALID' using errcode='22023';
    end if;
    if v_cycle.scope_client_id is not null and v_cycle.scope_client_id is distinct from v_client_id then
      raise exception 'WEEKLY_SOURCE_CONTEXT_CLIENT_SCOPE_MISMATCH' using errcode='22023';
    end if;
    if v_profile.single_client_required and v_client_id is null then
      raise exception 'WEEKLY_SOURCE_CLIENT_SCOPE_REQUIRED' using errcode='22023';
    end if;
    if v_client_id is not null then
      if not exists(
        select 1 from public.weekly_source_group_clients membership
        where membership.source_group_id=v_group_id
          and membership.client_id=v_client_id
          and v_cycle.finalisation_week_ending between membership.valid_from
            and coalesce(membership.valid_to,'infinity'::date)
      ) then
        raise exception 'WEEKLY_SOURCE_CLIENT_SCOPE_MISMATCH' using errcode='22023';
      end if;
      v_metadata:=v_metadata||pg_catalog.jsonb_build_object('client_id',v_client_id);
    end if;
    if v_profile.final_authority_kind='HEALTHROSTER_ACTUAL_ROWS'
       and (pg_catalog.jsonb_typeof(v_metadata->'saved_finalisation_profile_map') is distinct from 'object'
            or v_metadata->'saved_finalisation_profile_map'='{}'::jsonb) then
      raise exception 'WEEKLY_SOURCE_HEALTHROSTER_FINALISATION_MAP_REQUIRED' using errcode='22023';
    end if;
  end if;

  if v_profile.profile_code not in ('NHSP_FINAL_BACKING_V1','ACACIUM_SELF_BILL_REPORT_V1') then
    if v_coverage_state<>'COMPLETE'
       or v_confirmed_start is null or v_confirmed_end is null
       or v_confirmed_start>v_confirmed_end
       or v_coverage_timezone<>'Europe/London'
       or v_confirmation_version is null
       or v_proof_kind not in (
         'FORMAT_MANIFEST','OFFICE_COMPLETE_EXPORT_ATTESTATION',
         'EXPLICIT_EMPTY_CONFIRMATION','HEALTHROSTER_COMPLETE_EXPORT_ATTESTATION'
       ) then
      raise exception 'WEEKLY_SOURCE_COMPLETE_COVERAGE_REQUIRED' using errcode='22023';
    end if;
  end if;
  if (v_suggested_start is null)<>(v_suggested_end is null)
     or (v_confirmed_start is null)<>(v_confirmed_end is null)
     or (v_suggested_start is not null and v_suggested_start>v_suggested_end) then
    raise exception 'WEEKLY_SOURCE_COVERAGE_RANGE_INVALID' using errcode='22023';
  end if;
  -- 14 section 5.4.3.  The service SUGGESTS inclusive coverage from the file's
  -- own earliest and latest valid work Date; Office then CONFIRMS the range for
  -- which the export is complete.  Confirmation is therefore NOT the same fact
  -- as the evidence and must not be forced to equal it: 5.4.5 bullet 4 makes a
  -- Request Id that is "absent inside confirmed coverage" a full cancellation
  -- reversal, so a shift the Trust withdraws at the edge of the week can only
  -- ever be noticed by a confirmed range WIDER than the rows that arrived.  The
  -- same section already contemplates a confirmation with no rows at all ("a
  -- genuinely empty complete export requires explicit start/end dates and
  -- attestation"), which is the same freedom at its limit.
  --
  -- A confirmed range NARROWER than the evidence is refused here: every
  -- accepted row must stay inside the final scope, and the finaliser admits
  -- nothing outside confirmed coverage
  -- (WEEKLY_SOURCE_RESOLUTION_OUTSIDE_FINAL_SCOPE), so a narrower confirmation
  -- could only produce an upload that can never be finalised.  The suggestion
  -- itself is still evidence and is re-checked against the real rows at the
  -- seal.
  if v_profile.profile_code not in ('NHSP_FINAL_BACKING_V1','ACACIUM_SELF_BILL_REPORT_V1') then
    if v_accepted>0 and v_suggested_start is null then
      raise exception 'WEEKLY_SOURCE_COVERAGE_CONFIRMATION_MISMATCH' using errcode='22023';
    end if;
    if v_accepted>0 and (
         v_confirmed_start>v_suggested_start
         or v_confirmed_end<v_suggested_end
       ) then
      raise exception 'WEEKLY_SOURCE_COVERAGE_CONFIRMATION_NARROWER_THAN_EVIDENCE'
        using errcode='22023';
    end if;
    if v_accepted=0 and (v_suggested_start is not null or v_suggested_end is not null) then
      raise exception 'WEEKLY_SOURCE_EMPTY_COVERAGE_SUGGESTION_INVALID' using errcode='22023';
    end if;
  end if;

  v_computed_scope:=private.weekly_source_scope_fingerprint_v1(
    v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_client_id
  );
  if nullif(p_request->>'declared_scope_fingerprint','') is not null then
    v_declared:=private.weekly_source_hex32_v1(
      p_request->>'declared_scope_fingerprint','WEEKLY_SOURCE_DECLARED_SCOPE_HASH_INVALID'
    );
    if v_declared is distinct from v_computed_scope then
      raise exception 'WEEKLY_SOURCE_DECLARED_SCOPE_MISMATCH' using errcode='22023';
    end if;
  end if;
  v_declared:=v_computed_scope;

  if v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' then
    perform 1 from public.weekly_source_groups where id=v_group_id for update;
    perform 1 from public.weekly_source_cycles where id=v_cycle_id for update;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.encode(v_declared,'hex'),73241837)
  );
  if v_report_scope_id is null then
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_cycle_id for update;
  else
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_cycle_id;
  end if;
  if v_cycle.source_group_id is distinct from v_group_id then
    raise exception 'WEEKLY_SOURCE_CYCLE_SCOPE_MISMATCH' using errcode='22023';
  end if;
  if v_report_scope_id is not null then
    select * into strict v_scope
    from public.weekly_source_report_scopes where id=v_report_scope_id for update;
    if v_scope.source_cycle_id is distinct from v_cycle_id
       or v_scope.environment is distinct from v_environment
       or v_scope.agency_id is distinct from v_agency
       or v_scope.source_group_id is distinct from v_group_id
       or v_scope.client_id is distinct from v_client_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_CHANGED' using errcode='55000';
    end if;
  end if;
  if private.weekly_source_scope_fingerprint_v1(
       v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_client_id
     ) is distinct from v_declared then
    raise exception 'WEEKLY_SOURCE_SCOPE_CHANGED' using errcode='55000';
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'UPLOAD_SOURCE',v_group_id,v_client_id,v_cycle.finalisation_week_ending
  );

  if v_profile.profile_code<>'ACACIUM_SELF_BILL_REPORT_V1' then
  perform private.weekly_source_upload_coverage_floor_assert_v1(
    v_client_id,v_cycle.id,v_profile.profile_code,v_confirmed_start);

  if v_purpose='FINAL_SOURCE_CORRECTION' then
    if nullif(p_request->>'correction_session_id','') is null then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_REQUIRED' using errcode='22023';
    end if;
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=(p_request->>'correction_session_id')::uuid for update;
    if not found or v_correction.source_cycle_id is distinct from v_cycle_id
       or v_correction.authority_scope_kind is distinct from
          (case when v_report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end)
       or v_correction.report_scope_id is distinct from v_report_scope_id
       or v_correction.actor_user_id is distinct from v_actor
       or (v_expected_correction_version is not null
           and v_correction.version is distinct from v_expected_correction_version)
       or v_correction.state not in ('DRAFT','STAGING','READY')
       or (v_correction.state='DRAFT' and v_correction.replacement_correction_upload_id is not null)
       or (v_correction.state in ('STAGING','READY') and v_correction.replacement_correction_upload_id is null) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_INVALID' using errcode='22023';
    end if;
    if v_correction.replacement_correction_upload_id is not null then
      select * into strict v_existing
      from public.weekly_source_uploads
      where id=v_correction.replacement_correction_upload_id;
      if v_existing.content_sha256=v_content
         and v_existing.byte_count=v_byte_count
         and v_existing.source_format_profile_id=v_profile.id
         and (v_profile.profile_code='NHSP_FINAL_BACKING_V1'
              or (v_existing.parser_version=p_request->>'parser_version'
                  and v_existing.normaliser_version=p_request->>'normaliser_version'
                  and v_existing.workbook_part_and_sheet_fingerprint is not distinct from v_workbook_fingerprint
                  and v_existing.header_coordinate_map_hash=v_header_hash
                  and v_existing.confirmed_coverage_start_local_date is not distinct from v_confirmed_start
                  and v_existing.confirmed_coverage_end_local_date is not distinct from v_confirmed_end
                  and v_existing.coverage_confirmation_version is not distinct from v_confirmation_version)) then
        v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
          v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
          v_declared,v_correction.id,v_actor,p_request->>'original_filename',v_byte_count,
          v_content,p_request->>'parser_version',
          v_profile.profile_code||':'||v_profile.version::text,
          p_request->>'normaliser_version','DUPLICATE',
          'CORRECTION_UPLOAD_EXACT_REPLAY',v_existing.id
        );
        return pg_catalog.jsonb_build_object(
          'ok',true,'status','DUPLICATE','logical_upload_id',v_existing.id,
          'attempt_id',v_attempt_id,'current_pointer_moved',false
        );
      end if;
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,v_correction.id,v_actor,p_request->>'original_filename',v_byte_count,
        v_content,p_request->>'parser_version',
        v_profile.profile_code||':'||v_profile.version::text,
        p_request->>'normaliser_version','CONFLICT',
        'CORRECTION_SESSION_REPLACEMENT_CONFLICT',v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',false,'status','CONFLICT',
        'reason_code','CORRECTION_SESSION_REPLACEMENT_CONFLICT',
        'logical_upload_id',v_existing.id,'attempt_id',v_attempt_id,
        'current_pointer_moved',false
      );
    end if;
  elsif nullif(p_request->>'correction_session_id','') is not null
        or v_expected_correction_version is not null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_ALLOWED' using errcode='22023';
  end if;

  -- Validate even duplicate attempts; a reused byte stream is not authority
  -- to change a checking-only profile's use.
  if coalesce(v_metadata->>'import_use','CHECKING') not in ('CHECKING','PREPARE_FINALISATION')
    or (v_profile.row_finalisation_capability='CHECKING_ONLY'
      and v_metadata->>'import_use'='PREPARE_FINALISATION') then
    raise exception 'WEEKLY_SOURCE_IMPORT_USE_INVALID' using errcode='22023';
  end if;
  if v_metadata->>'import_use'='PREPARE_FINALISATION' then
    perform private.weekly_source_office_authority_v1(v_actor,'FINALISE_WEEK',v_group_id,
      v_client_id,v_cycle.finalisation_week_ending);
  end if;

  if v_profile.profile_code='NHSP_FINAL_BACKING_V1' and v_purpose='ORDINARY' then
    select upload.* into v_existing
    from public.weekly_source_uploads upload
    join public.weekly_source_format_profiles profile
      on profile.id=upload.source_format_profile_id
    where upload.source_cycle_id=v_cycle_id
      and upload.report_scope_id=v_report_scope_id
      and profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT'
      and private.weekly_source_canonical_report_number_v1(
        upload.file_metadata_json->>'nhsp_report_number'
      )=v_report_number
      and upload.content_sha256=v_content
      and upload.byte_count=v_byte_count
      and upload.state<>'REJECTED'
    order by (upload.state='CURRENT') desc,upload.uploaded_at_utc desc,upload.id desc
    limit 1;
    if found then
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,null,v_actor,p_request->>'original_filename',v_byte_count,v_content,
        p_request->>'parser_version',v_profile.profile_code||':'||v_profile.version::text,
        p_request->>'normaliser_version','DUPLICATE','NHSP_REPORT_IDENTICAL_REPLAY',
        v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','DUPLICATE','logical_upload_id',v_existing.id,
        'attempt_id',v_attempt_id,'current_pointer_moved',false
      );
    end if;

    select upload.* into v_existing
    from public.weekly_source_uploads upload
    join public.weekly_source_format_profiles profile
      on profile.id=upload.source_format_profile_id
    where upload.source_cycle_id=v_cycle_id
      and upload.report_scope_id=v_report_scope_id
      and profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT'
      and private.weekly_source_canonical_report_number_v1(
        upload.file_metadata_json->>'nhsp_report_number'
      )=v_report_number
      and upload.state<>'REJECTED'
    order by upload.uploaded_at_utc,upload.id
    limit 1;

    if found then
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,null,v_actor,p_request->>'original_filename',v_byte_count,v_content,
        p_request->>'parser_version',v_profile.profile_code||':'||v_profile.version::text,
        p_request->>'normaliser_version','CONFLICT','NHSP_REPORT_IDENTITY_BYTES_CONFLICT',
        v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',false,'status','CONFLICT','reason_code','NHSP_REPORT_IDENTITY_BYTES_CONFLICT',
        'logical_upload_id',v_existing.id,'attempt_id',v_attempt_id,
        'current_pointer_moved',false
      );
    end if;
  elsif v_profile.profile_code<>'NHSP_FINAL_BACKING_V1' then
    v_profile_identity:=v_profile.profile_code||':'||v_profile.version::text;
    select upload.* into v_existing
    from public.weekly_source_uploads upload
    where upload.source_cycle_id=v_cycle_id
      and upload.report_scope_id is not distinct from v_report_scope_id
      and upload.purpose=v_purpose
      and upload.content_sha256=v_content
      and upload.byte_count=v_byte_count
      and upload.source_format_profile_id=v_profile.id
      and upload.parser_version=coalesce(nullif(p_request->>'parser_version',''),'')
      and upload.normaliser_version=coalesce(nullif(p_request->>'normaliser_version',''),'')
      and upload.workbook_part_and_sheet_fingerprint is not distinct from v_workbook_fingerprint
      and upload.header_coordinate_map_hash=v_header_hash
      and upload.money_lexical_authority_version is not distinct from
          nullif(p_request->>'money_lexical_authority_version','')
      and upload.correction_session_id is not distinct from
          nullif(p_request->>'correction_session_id','')::uuid
      and upload.declared_scope_fingerprint=v_declared
      and upload.confirmed_coverage_start_local_date is not distinct from v_confirmed_start
      and upload.confirmed_coverage_end_local_date is not distinct from v_confirmed_end
      and upload.coverage_confirmation_version is not distinct from v_confirmation_version
      and coalesce(upload.file_metadata_json->'saved_finalisation_profile_map','null'::jsonb)
          =coalesce(v_metadata->'saved_finalisation_profile_map','null'::jsonb)
      and coalesce(upload.file_metadata_json->>'import_use','CHECKING')
          =coalesce(v_metadata->>'import_use','CHECKING')
      and upload.state<>'REJECTED'
    order by upload.uploaded_at_utc,upload.id
    limit 1;
    if found then
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,nullif(p_request->>'correction_session_id','')::uuid,v_actor,
        p_request->>'original_filename',v_byte_count,v_content,p_request->>'parser_version',
        v_profile_identity,p_request->>'normaliser_version','DUPLICATE',
        'WEEKLY_SOURCE_EXACT_DUPLICATE',v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','DUPLICATE','logical_upload_id',v_existing.id,
        'attempt_id',v_attempt_id,'current_pointer_moved',false
      );
    end if;
  end if;

  insert into public.weekly_source_uploads(
    source_cycle_id,report_scope_id,original_filename,content_sha256,byte_count,
    source_format_profile_id,parser_version,normaliser_version,
    workbook_part_and_sheet_fingerprint,header_coordinate_map_json,
    header_coordinate_map_hash,money_lexical_authority_version,purpose,
    correction_session_id,declared_scope_fingerprint,
    suggested_coverage_start_local_date,suggested_coverage_end_local_date,
    confirmed_coverage_start_local_date,confirmed_coverage_end_local_date,
    coverage_timezone,coverage_confirmation_version,coverage_confirmed_by_user_id,
    coverage_confirmed_at_utc,coverage_shrink_acknowledged,coverage_state,
    coverage_proof_kind,physical_row_count,header_count,trailer_count,
    continuation_count,accepted_count,blocking_economic_duplicate_count,
    malformed_count,blocked_count,state,uploaded_by_user_id,file_metadata_json,
    parser_summary_json
  ) values (
    v_cycle_id,v_report_scope_id,p_request->>'original_filename',v_content,v_byte_count,
    v_profile.id,p_request->>'parser_version',p_request->>'normaliser_version',
    v_workbook_fingerprint,v_header_map,v_header_hash,
    nullif(p_request->>'money_lexical_authority_version',''),v_purpose,
    nullif(p_request->>'correction_session_id','')::uuid,v_declared,
    v_suggested_start,v_suggested_end,v_confirmed_start,v_confirmed_end,
    case when v_confirmed_start is null then null else v_coverage_timezone end,
    case when v_confirmed_start is null then null else v_confirmation_version end,
    case when v_confirmed_start is null then null else v_actor end,
    case when v_confirmed_start is null then null
      else coalesce(nullif(p_request->>'coverage_confirmed_at_utc','')::timestamptz,
        pg_catalog.transaction_timestamp()) end,
    case when p_request?'coverage_shrink_acknowledged'
      then (p_request->>'coverage_shrink_acknowledged')::boolean else null end,
    nullif(v_coverage_state,''),v_proof_kind,v_physical,v_header,v_trailer,
    v_continuation,v_accepted,v_duplicate,v_malformed,v_blocked,'STAGING',v_actor,
    v_metadata,v_summary
  ) returning id into v_upload_id;

  if v_purpose='FINAL_SOURCE_CORRECTION' then
    update public.weekly_final_source_correction_sessions
    set state='STAGING',replacement_correction_upload_id=v_upload_id,
        version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_correction.id;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','STAGING','logical_upload_id',v_upload_id,
    'declared_scope_fingerprint',pg_catalog.encode(v_declared,'hex'),
    'header_coordinate_map_hash',pg_catalog.encode(v_header_hash,'hex'),
    'current_pointer_moved',false
  );
  end if;

  if v_purpose='FINAL_SOURCE_CORRECTION' then
    if nullif(p_request->>'correction_session_id','') is null then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_REQUIRED' using errcode='22023';
    end if;
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=(p_request->>'correction_session_id')::uuid for update;
    if not found or v_correction.source_cycle_id is distinct from v_cycle_id
       or v_correction.authority_scope_kind is distinct from
          (case when v_report_scope_id is null then 'CYCLE' else 'NHSP_REPORT_SCOPE' end)
       or v_correction.report_scope_id is distinct from v_report_scope_id
       or v_correction.actor_user_id is distinct from v_actor
       or (v_expected_correction_version is not null
           and v_correction.version is distinct from v_expected_correction_version)
       or v_correction.state not in ('DRAFT','STAGING','READY')
       or (v_correction.state='DRAFT' and v_correction.replacement_correction_upload_id is not null)
       or (v_correction.state in ('STAGING','READY') and v_correction.replacement_correction_upload_id is null) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_INVALID' using errcode='22023';
    end if;
    if v_correction.replacement_correction_upload_id is not null then
      select * into strict v_existing
      from public.weekly_source_uploads
      where id=v_correction.replacement_correction_upload_id;
      if v_existing.content_sha256=v_content
         and v_existing.byte_count=v_byte_count
         and v_existing.source_format_profile_id=v_profile.id
         and (v_profile.profile_code='NHSP_FINAL_BACKING_V1'
              or (v_existing.parser_version=p_request->>'parser_version'
                  and v_existing.normaliser_version=p_request->>'normaliser_version'
                  and v_existing.workbook_part_and_sheet_fingerprint is not distinct from v_workbook_fingerprint
                  and v_existing.header_coordinate_map_hash=v_header_hash
                  and v_existing.confirmed_coverage_start_local_date is not distinct from v_confirmed_start
                  and v_existing.confirmed_coverage_end_local_date is not distinct from v_confirmed_end
                  and v_existing.coverage_confirmation_version is not distinct from v_confirmation_version)) then
        v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
          v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
          v_declared,v_correction.id,v_actor,p_request->>'original_filename',v_byte_count,
          v_content,p_request->>'parser_version',
          v_profile.profile_code||':'||v_profile.version::text,
          p_request->>'normaliser_version','DUPLICATE',
          'CORRECTION_UPLOAD_EXACT_REPLAY',v_existing.id
        );
        return pg_catalog.jsonb_build_object(
          'ok',true,'status','DUPLICATE','logical_upload_id',v_existing.id,
          'attempt_id',v_attempt_id,'current_pointer_moved',false
        );
      end if;
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,v_correction.id,v_actor,p_request->>'original_filename',v_byte_count,
        v_content,p_request->>'parser_version',
        v_profile.profile_code||':'||v_profile.version::text,
        p_request->>'normaliser_version','CONFLICT',
        'CORRECTION_SESSION_REPLACEMENT_CONFLICT',v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',false,'status','CONFLICT',
        'reason_code','CORRECTION_SESSION_REPLACEMENT_CONFLICT',
        'logical_upload_id',v_existing.id,'attempt_id',v_attempt_id,
        'current_pointer_moved',false
      );
    end if;
  elsif nullif(p_request->>'correction_session_id','') is not null
        or v_expected_correction_version is not null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_ALLOWED' using errcode='22023';
  end if;

  -- Validate even duplicate attempts; a reused byte stream is not authority
  -- to change a checking-only profile's use.
  if coalesce(v_metadata->>'import_use','CHECKING') not in ('CHECKING','PREPARE_FINALISATION')
    or (v_profile.row_finalisation_capability='CHECKING_ONLY'
      and v_metadata->>'import_use'='PREPARE_FINALISATION') then
    raise exception 'WEEKLY_SOURCE_IMPORT_USE_INVALID' using errcode='22023';
  end if;
  if v_metadata->>'import_use'='PREPARE_FINALISATION' then
    perform private.weekly_source_office_authority_v1(v_actor,'FINALISE_WEEK',v_group_id,
      v_client_id,v_cycle.finalisation_week_ending);
  end if;

  if v_profile.profile_code='NHSP_FINAL_BACKING_V1' and v_purpose='ORDINARY' then
    select upload.* into v_existing
    from public.weekly_source_uploads upload
    join public.weekly_source_format_profiles profile
      on profile.id=upload.source_format_profile_id
    where upload.source_cycle_id=v_cycle_id
      and upload.report_scope_id=v_report_scope_id
      and profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT'
      and private.weekly_source_canonical_report_number_v1(
        upload.file_metadata_json->>'nhsp_report_number'
      )=v_report_number
      and upload.content_sha256=v_content
      and upload.byte_count=v_byte_count
      and upload.state<>'REJECTED'
    order by (upload.state='CURRENT') desc,upload.uploaded_at_utc desc,upload.id desc
    limit 1;
    if found then
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,null,v_actor,p_request->>'original_filename',v_byte_count,v_content,
        p_request->>'parser_version',v_profile.profile_code||':'||v_profile.version::text,
        p_request->>'normaliser_version','DUPLICATE','NHSP_REPORT_IDENTICAL_REPLAY',
        v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','DUPLICATE','logical_upload_id',v_existing.id,
        'attempt_id',v_attempt_id,'current_pointer_moved',false
      );
    end if;

    select upload.* into v_existing
    from public.weekly_source_uploads upload
    join public.weekly_source_format_profiles profile
      on profile.id=upload.source_format_profile_id
    where upload.source_cycle_id=v_cycle_id
      and upload.report_scope_id=v_report_scope_id
      and profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT'
      and private.weekly_source_canonical_report_number_v1(
        upload.file_metadata_json->>'nhsp_report_number'
      )=v_report_number
      and upload.state<>'REJECTED'
    order by upload.uploaded_at_utc,upload.id
    limit 1;

    if found then
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,null,v_actor,p_request->>'original_filename',v_byte_count,v_content,
        p_request->>'parser_version',v_profile.profile_code||':'||v_profile.version::text,
        p_request->>'normaliser_version','CONFLICT','NHSP_REPORT_IDENTITY_BYTES_CONFLICT',
        v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',false,'status','CONFLICT','reason_code','NHSP_REPORT_IDENTITY_BYTES_CONFLICT',
        'logical_upload_id',v_existing.id,'attempt_id',v_attempt_id,
        'current_pointer_moved',false
      );
    end if;
  elsif v_profile.profile_code<>'NHSP_FINAL_BACKING_V1' then
    v_profile_identity:=v_profile.profile_code||':'||v_profile.version::text;
    select upload.* into v_existing
    from public.weekly_source_uploads upload
    where upload.source_cycle_id=v_cycle_id
      and upload.report_scope_id is not distinct from v_report_scope_id
      and upload.purpose=v_purpose
      and upload.content_sha256=v_content
      and upload.byte_count=v_byte_count
      and upload.source_format_profile_id=v_profile.id
      and upload.parser_version=coalesce(nullif(p_request->>'parser_version',''),'')
      and upload.normaliser_version=coalesce(nullif(p_request->>'normaliser_version',''),'')
      and upload.workbook_part_and_sheet_fingerprint is not distinct from v_workbook_fingerprint
      and upload.header_coordinate_map_hash=v_header_hash
      and upload.money_lexical_authority_version is not distinct from
          nullif(p_request->>'money_lexical_authority_version','')
      and upload.correction_session_id is not distinct from
          nullif(p_request->>'correction_session_id','')::uuid
      and upload.declared_scope_fingerprint=v_declared
      and upload.confirmed_coverage_start_local_date is not distinct from v_confirmed_start
      and upload.confirmed_coverage_end_local_date is not distinct from v_confirmed_end
      and upload.coverage_confirmation_version is not distinct from v_confirmation_version
      and coalesce(upload.file_metadata_json->'saved_finalisation_profile_map','null'::jsonb)
          =coalesce(v_metadata->'saved_finalisation_profile_map','null'::jsonb)
      and coalesce(upload.file_metadata_json->>'import_use','CHECKING')
          =coalesce(v_metadata->>'import_use','CHECKING')
      and upload.state<>'REJECTED'
    order by upload.uploaded_at_utc,upload.id
    limit 1;
    if found then
      v_attempt_id:=private.weekly_source_attempt_append_without_upload_v1(
        v_environment,v_agency,v_group_id,v_cycle_id,v_report_scope_id,v_purpose,
        v_declared,nullif(p_request->>'correction_session_id','')::uuid,v_actor,
        p_request->>'original_filename',v_byte_count,v_content,p_request->>'parser_version',
        v_profile_identity,p_request->>'normaliser_version','DUPLICATE',
        'WEEKLY_SOURCE_EXACT_DUPLICATE',v_existing.id
      );
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','DUPLICATE','logical_upload_id',v_existing.id,
        'attempt_id',v_attempt_id,'current_pointer_moved',false
      );
    end if;
  end if;

  insert into public.weekly_source_uploads(
    source_cycle_id,report_scope_id,original_filename,content_sha256,byte_count,
    source_format_profile_id,parser_version,normaliser_version,
    workbook_part_and_sheet_fingerprint,header_coordinate_map_json,
    header_coordinate_map_hash,money_lexical_authority_version,purpose,
    correction_session_id,declared_scope_fingerprint,
    suggested_coverage_start_local_date,suggested_coverage_end_local_date,
    confirmed_coverage_start_local_date,confirmed_coverage_end_local_date,
    coverage_timezone,coverage_confirmation_version,coverage_confirmed_by_user_id,
    coverage_confirmed_at_utc,coverage_shrink_acknowledged,coverage_state,
    coverage_proof_kind,physical_row_count,header_count,trailer_count,
    continuation_count,accepted_count,blocking_economic_duplicate_count,
    malformed_count,blocked_count,state,uploaded_by_user_id,file_metadata_json,
    parser_summary_json
  ) values (
    v_cycle_id,v_report_scope_id,p_request->>'original_filename',v_content,v_byte_count,
    v_profile.id,p_request->>'parser_version',p_request->>'normaliser_version',
    v_workbook_fingerprint,v_header_map,v_header_hash,
    nullif(p_request->>'money_lexical_authority_version',''),v_purpose,
    nullif(p_request->>'correction_session_id','')::uuid,v_declared,
    v_suggested_start,v_suggested_end,v_confirmed_start,v_confirmed_end,
    case when v_confirmed_start is null then null else v_coverage_timezone end,
    case when v_confirmed_start is null then null else v_confirmation_version end,
    case when v_confirmed_start is null then null else v_actor end,
    case when v_confirmed_start is null then null
      else coalesce(nullif(p_request->>'coverage_confirmed_at_utc','')::timestamptz,
        pg_catalog.transaction_timestamp()) end,
    case when p_request?'coverage_shrink_acknowledged'
      then (p_request->>'coverage_shrink_acknowledged')::boolean else null end,
    nullif(v_coverage_state,''),v_proof_kind,v_physical,v_header,v_trailer,
    v_continuation,v_accepted,v_duplicate,v_malformed,v_blocked,'STAGING',v_actor,
    v_metadata,v_summary
  ) returning id into v_upload_id;

  if v_purpose='FINAL_SOURCE_CORRECTION' then
    update public.weekly_final_source_correction_sessions
    set state='STAGING',replacement_correction_upload_id=v_upload_id,
        version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_correction.id;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','STAGING','logical_upload_id',v_upload_id,
    'declared_scope_fingerprint',pg_catalog.encode(v_declared,'hex'),
    'header_coordinate_map_hash',pg_catalog.encode(v_header_hash,'hex'),
    'current_pointer_moved',false
  );
end;
$function$;

-- Complete native successor; bounded report arm only. Root composes later shared owner hunks.
create or replace function public.weekly_source_upload_stage_rows_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_upload_id uuid;
  v_upload public.weekly_source_uploads%rowtype;
  v_group_id uuid;
  v_cycle_date date;
  v_client_id uuid;
  v_item jsonb;
  v_key text;
  v_ordinal integer;
  v_hash bytea;
  v_existing_physical public.weekly_source_physical_rows%rowtype;
  v_existing_row public.weekly_source_upload_rows%rowtype;
  v_existing_money public.weekly_source_money_cell_evidence%rowtype;
  v_existing_expense public.weekly_source_expense_cell_evidence%rowtype;
  v_row public.weekly_source_upload_rows%rowtype;
  v_money public.weekly_source_money_cell_evidence%rowtype;
  v_expense public.weekly_source_expense_cell_evidence%rowtype;
  v_payload jsonb;
  v_physical_added integer:=0;
  v_rows_added integer:=0;
  v_money_added integer:=0;
  v_expenses_added integer:=0;
  v_report boolean:=false;
begin
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(
       select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in ('actor_user_id','upload_id','physical_rows','normalised_rows',
         'money_evidence','expense_evidence')
     ) then
    raise exception 'WEEKLY_SOURCE_STAGE_ROWS_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_upload_id:=(p_request->>'upload_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_STAGE_ROWS_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_upload_id is null
     or pg_catalog.jsonb_typeof(coalesce(p_request->'physical_rows','[]'::jsonb))<>'array'
     or pg_catalog.jsonb_typeof(coalesce(p_request->'normalised_rows','[]'::jsonb))<>'array'
     or pg_catalog.jsonb_typeof(coalesce(p_request->'money_evidence','[]'::jsonb))<>'array'
     or pg_catalog.jsonb_typeof(coalesce(p_request->'expense_evidence','[]'::jsonb))<>'array' then
    raise exception 'WEEKLY_SOURCE_STAGE_ROWS_REQUEST_INVALID' using errcode='22023';
  end if;
  if pg_catalog.jsonb_array_length(coalesce(p_request->'physical_rows','[]'::jsonb))>10000
     or pg_catalog.jsonb_array_length(coalesce(p_request->'normalised_rows','[]'::jsonb))>10000
     or pg_catalog.jsonb_array_length(coalesce(p_request->'money_evidence','[]'::jsonb))>40001
     or pg_catalog.jsonb_array_length(coalesce(p_request->'expense_evidence','[]'::jsonb))>10000 then
    raise exception 'WEEKLY_SOURCE_STAGE_ROWS_BATCH_TOO_LARGE' using errcode='22023';
  end if;

  select * into v_upload
  from public.weekly_source_uploads where id=v_upload_id for update;
  if not found or v_upload.state<>'STAGING' then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_STAGING' using errcode='55000';
  end if;
  if v_upload.uploaded_by_user_id is distinct from v_actor then
    raise exception 'WEEKLY_SOURCE_UPLOAD_ACTOR_MISMATCH' using errcode='42501';
  end if;
  select cycle.source_group_id,cycle.finalisation_week_ending
    into strict v_group_id,v_cycle_date
  from public.weekly_source_cycles cycle where cycle.id=v_upload.source_cycle_id;
  if v_upload.report_scope_id is null then
    begin
      v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
    exception when invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_CLIENT_SCOPE_INVALID' using errcode='55000';
    end;
  else
    select scope.client_id into strict v_client_id
    from public.weekly_source_report_scopes scope
    where scope.id=v_upload.report_scope_id
      and scope.source_cycle_id=v_upload.source_cycle_id;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'UPLOAD_SOURCE',v_group_id,v_client_id,v_cycle_date
  );

  v_report:=exists(select 1 from public.weekly_source_format_profiles p where p.id=v_upload.source_format_profile_id
    and p.profile_code='ACACIUM_SELF_BILL_REPORT_V1');
  if v_report and jsonb_array_length(coalesce(p_request->'expense_evidence','[]'::jsonb))<>0 then
    raise exception 'WEEKLY_SOURCE_REPORT_EXPENSES_FORBIDDEN' using errcode='22023'; end if;

  for v_item in
    select value from pg_catalog.jsonb_array_elements(
      coalesce(p_request->'physical_rows','[]'::jsonb)
    )
  loop
    if pg_catalog.jsonb_typeof(v_item)<>'object' then
      raise exception 'WEEKLY_SOURCE_PHYSICAL_ROW_INVALID' using errcode='22023';
    end if;
    select key into v_key from pg_catalog.jsonb_object_keys(v_item) key
    where key not in ('source_row_ordinal','bounded_raw_cells_json','classification','row_sha256')
    order by key limit 1;
    if v_key is not null then
      raise exception 'WEEKLY_SOURCE_PHYSICAL_ROW_UNKNOWN_FIELD'
        using errcode='22023',detail=v_key;
    end if;
    begin
      v_ordinal:=(v_item->>'source_row_ordinal')::integer;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'WEEKLY_SOURCE_PHYSICAL_ROW_ORDINAL_INVALID' using errcode='22023';
    end;
    if v_ordinal is null or v_ordinal<1 or v_ordinal>v_upload.physical_row_count
       or pg_catalog.jsonb_typeof(v_item->'bounded_raw_cells_json')<>'object'
       or coalesce(v_item->>'classification','') not in (
         'HEADER','TRAILER','PROFILE_PROVED_NON_ECONOMIC_CONTINUATION',
         'ACCEPTED_SHIFT','BLOCKING_ECONOMIC_DUPLICATE','BLOCKING_MALFORMED'
       ) then
      raise exception 'WEEKLY_SOURCE_PHYSICAL_ROW_INVALID' using errcode='22023';
    end if;
    v_payload:=pg_catalog.jsonb_build_object(
      'source_row_ordinal',v_ordinal,
      'classification',v_item->>'classification',
      'bounded_raw_cells_json',v_item->'bounded_raw_cells_json'
    );
    v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_PHYSICAL_ROW_V1',v_payload);
    if nullif(v_item->>'row_sha256','') is not null
       and private.weekly_source_hex32_v1(
         v_item->>'row_sha256','WEEKLY_SOURCE_PHYSICAL_ROW_HASH_INVALID'
       ) is distinct from v_hash then
      raise exception 'WEEKLY_SOURCE_PHYSICAL_ROW_HASH_MISMATCH' using errcode='22023';
    end if;
    select * into v_existing_physical
    from public.weekly_source_physical_rows
    where upload_id=v_upload_id and source_row_ordinal=v_ordinal;
    if found then
      if v_existing_physical.classification is distinct from v_item->>'classification'
         or v_existing_physical.bounded_raw_cells_json is distinct from v_item->'bounded_raw_cells_json'
         or v_existing_physical.row_sha256 is distinct from v_hash then
        raise exception 'WEEKLY_SOURCE_PHYSICAL_ROW_REPLAY_CONFLICT' using errcode='55000';
      end if;
    else
      insert into public.weekly_source_physical_rows(
        upload_id,source_row_ordinal,bounded_raw_cells_json,row_sha256,classification
      ) values (
        v_upload_id,v_ordinal,v_item->'bounded_raw_cells_json',v_hash,v_item->>'classification'
      );
      v_physical_added:=v_physical_added+1;
    end if;
  end loop;

  for v_item in
    select value from pg_catalog.jsonb_array_elements(
      coalesce(p_request->'normalised_rows','[]'::jsonb)
    )
  loop
    if pg_catalog.jsonb_typeof(v_item)<>'object' then
      raise exception 'WEEKLY_SOURCE_NORMALISED_ROW_INVALID' using errcode='22023';
    end if;
    select key into v_key from pg_catalog.jsonb_object_keys(v_item) key
    where key not in (
      'source_row_ordinal','external_source_key','source_candidate_identity',
      'source_client_identity','work_date','start_at_local','end_at_local',
      'break_minutes','actual_net_minutes','row_finalisation_state','finalised_by',
      'role_band_source','source_commission_pence','source_total_cost_pence',
      'source_shift_charge_pence','source_money_parse_state','source_gross_pence','source_vat_pence','finalised_at_utc',
      'source_qualification_profile_version','source_expense_pence',
      'source_expense_parse_state','bounded_raw_columns_json','normalised_row_hash'
    ) order by key limit 1;
    if v_key is not null then
      raise exception 'WEEKLY_SOURCE_NORMALISED_ROW_UNKNOWN_FIELD'
        using errcode='22023',detail=v_key;
    end if;
    begin
      v_row:=pg_catalog.jsonb_populate_record(null::public.weekly_source_upload_rows,v_item);
    exception when others then
      raise exception 'WEEKLY_SOURCE_NORMALISED_ROW_TYPE_INVALID' using errcode='22023';
    end;
    v_row.row_finalisation_state:=coalesce(v_row.row_finalisation_state,'NOT_APPLICABLE');
    v_row.source_money_parse_state:=coalesce(v_row.source_money_parse_state,'NOT_APPLICABLE');
    v_row.source_expense_parse_state:=coalesce(v_row.source_expense_parse_state,'NOT_APPLICABLE');
    v_row.bounded_raw_columns_json:=coalesce(v_row.bounded_raw_columns_json,'{}'::jsonb);
    if v_row.source_row_ordinal is null or v_row.source_row_ordinal<1
       or v_row.source_row_ordinal>v_upload.physical_row_count
       or nullif(pg_catalog.btrim(coalesce(v_row.source_candidate_identity,'')),'') is null
       or nullif(pg_catalog.btrim(coalesce(v_row.source_client_identity,'')),'') is null
       or v_row.work_date is null
       or pg_catalog.jsonb_typeof(v_row.bounded_raw_columns_json)<>'object'
       or not exists(
         select 1 from public.weekly_source_physical_rows physical
         where physical.upload_id=v_upload_id
           and physical.source_row_ordinal=v_row.source_row_ordinal
           and physical.classification='ACCEPTED_SHIFT'
       ) then
      raise exception 'WEEKLY_SOURCE_NORMALISED_ROW_INVALID' using errcode='22023';
    end if;
    v_payload:=pg_catalog.jsonb_build_object(
      'source_row_ordinal',v_row.source_row_ordinal,
      'external_source_key',v_row.external_source_key,
      'source_candidate_identity',v_row.source_candidate_identity,
      'source_client_identity',v_row.source_client_identity,
      'work_date',v_row.work_date,
      'start_at_local',v_row.start_at_local,
      'end_at_local',v_row.end_at_local,
      'break_minutes',v_row.break_minutes,
      'actual_net_minutes',v_row.actual_net_minutes,
      'row_finalisation_state',v_row.row_finalisation_state,
      'finalised_by',v_row.finalised_by,
      'role_band_source',v_row.role_band_source,
      'source_commission_pence',v_row.source_commission_pence,
      'source_total_cost_pence',v_row.source_total_cost_pence,
      'source_shift_charge_pence',v_row.source_shift_charge_pence,
      'source_money_parse_state',v_row.source_money_parse_state,
      'source_qualification_profile_version',v_row.source_qualification_profile_version,
      'source_expense_pence',v_row.source_expense_pence,
      'source_expense_parse_state',v_row.source_expense_parse_state,
      'bounded_raw_columns_json',v_row.bounded_raw_columns_json
    )||case when not v_report and (v_row.source_gross_pence is not null or v_row.source_vat_pence is not null or v_row.finalised_at_utc is not null)
      then jsonb_build_object('source_gross_pence',v_row.source_gross_pence,'source_vat_pence',v_row.source_vat_pence,'finalised_at_utc',v_row.finalised_at_utc) else '{}'::jsonb end;
    if v_report then
      if v_row.row_finalisation_state<>'SOURCE_REPORT_LINE' or v_row.break_minutes is not null
        or v_row.actual_net_minutes is not null or v_row.finalised_at_utc is not null or v_row.finalised_by is not null or v_row.role_band_source is not null
        or v_row.source_commission_pence is not null or v_row.source_total_cost_pence is not null
        or v_row.source_expense_pence is not null or v_row.source_expense_parse_state<>'NOT_APPLICABLE'
        or v_row.source_money_parse_state<>'VALID'
        or v_row.source_qualification_profile_version is distinct from 'SOURCE_INVOICE_MONEY_PENCE_V1' then
        raise exception 'WEEKLY_SOURCE_REPORT_PAY_FACTS_FORBIDDEN' using errcode='22023'; end if;
      v_hash:=private.weekly_source_self_bill_report_row_hash_v1(v_item-array[
        'break_minutes','actual_net_minutes','row_finalisation_state','finalised_by','role_band_source',
        'source_commission_pence','source_total_cost_pence','source_money_parse_state','source_qualification_profile_version',
        'source_expense_pence','source_expense_parse_state','normalised_row_hash']);
    else
      if v_row.row_finalisation_state='SOURCE_REPORT_LINE' then
        raise exception 'WEEKLY_SOURCE_REPORT_ROW_PROFILE_INVALID' using errcode='22023'; end if;
      v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_NORMALISED_ROW_V1',v_payload);
    end if;
    if nullif(v_item->>'normalised_row_hash','') is not null
       and private.weekly_source_hex32_v1(
         v_item->>'normalised_row_hash','WEEKLY_SOURCE_NORMALISED_ROW_HASH_INVALID'
       ) is distinct from v_hash then
      raise exception 'WEEKLY_SOURCE_NORMALISED_ROW_HASH_MISMATCH' using errcode='22023';
    end if;
    select * into v_existing_row
    from public.weekly_source_upload_rows
    where upload_id=v_upload_id and source_row_ordinal=v_row.source_row_ordinal;
    if found then
      if v_existing_row.normalised_row_hash is distinct from v_hash then
        raise exception 'WEEKLY_SOURCE_NORMALISED_ROW_REPLAY_CONFLICT' using errcode='55000';
      end if;
    else
      -- Two accepted economic rows of one upload may not share an external
      -- source key.  For HealthRoster the key is the `Request Id`, which the
      -- profile uses as durable work identity, so a repeat is a duplicate
      -- economic row (14 s4.2.8).  For NHSP the broker stages the Reference
      -- Number, which 24 s9 says is evidence and never identity; a report that
      -- repeats one is a source shape this build cannot account for, and 14
      -- s4.2.8 blocks it.
      --
      -- Either way the refusal must be STATED.  Until this guard existed the
      -- only thing that stopped it was the unique index
      -- weekly_source_upload_rows_external_key_uq, which reached the caller as
      -- a bare 23505 from a constraint name - an unhandled error, not a
      -- refusal, and the exact shape a positive and its same-Reference full
      -- negative produce.  A unique index must never be the statement of a
      -- rule (standing rule 5); it stays as the backstop behind this one.
      if v_row.external_source_key is not null
         and exists(
           select 1
           from public.weekly_source_upload_rows existing_key
           where existing_key.upload_id=v_upload_id
             and existing_key.external_source_key=v_row.external_source_key
             and existing_key.source_row_ordinal is distinct from v_row.source_row_ordinal
         ) then
        raise exception 'WEEKLY_SOURCE_UPLOAD_DUPLICATE_EXTERNAL_KEY'
          using errcode='55000',
                detail=pg_catalog.jsonb_build_object(
                  'upload_id',v_upload_id,
                  'source_row_ordinal',v_row.source_row_ordinal,
                  'external_source_key',v_row.external_source_key
                )::text;
      end if;
      insert into public.weekly_source_upload_rows(
        upload_id,source_row_ordinal,external_source_key,source_candidate_identity,
        source_client_identity,work_date,start_at_local,end_at_local,break_minutes,
        actual_net_minutes,row_finalisation_state,finalised_by,role_band_source,source_gross_pence,source_vat_pence,finalised_at_utc,
        source_commission_pence,source_total_cost_pence,source_shift_charge_pence,
        source_money_parse_state,source_qualification_profile_version,
        source_expense_pence,source_expense_parse_state,normalised_row_hash,
        bounded_raw_columns_json
      ) values (
        v_upload_id,v_row.source_row_ordinal,v_row.external_source_key,
        v_row.source_candidate_identity,v_row.source_client_identity,v_row.work_date,
        v_row.start_at_local,v_row.end_at_local,v_row.break_minutes,v_row.actual_net_minutes,
        v_row.row_finalisation_state,v_row.finalised_by,v_row.role_band_source,v_row.source_gross_pence,v_row.source_vat_pence,v_row.finalised_at_utc,
        v_row.source_commission_pence,v_row.source_total_cost_pence,
        v_row.source_shift_charge_pence,v_row.source_money_parse_state,
        v_row.source_qualification_profile_version,v_row.source_expense_pence,
        v_row.source_expense_parse_state,v_hash,v_row.bounded_raw_columns_json
      );
      v_rows_added:=v_rows_added+1;
    end if;
  end loop;

  for v_item in
    select value from pg_catalog.jsonb_array_elements(
      coalesce(p_request->'money_evidence','[]'::jsonb)
    )
  loop
    if pg_catalog.jsonb_typeof(v_item)<>'object' then
      raise exception 'WEEKLY_SOURCE_MONEY_EVIDENCE_INVALID' using errcode='22023';
    end if;
    select key into v_key from pg_catalog.jsonb_object_keys(v_item) key
    where key not in (
      'source_row_ordinal','money_field_kind','source_column_index','cell_coordinate',
      'source_kind','original_token','decoded_token','cell_type_marker',
      'formula_present','parse_state','parsed_pence','source_file_sha256','token_sha256'
    ) order by key limit 1;
    if v_key is not null then
      raise exception 'WEEKLY_SOURCE_MONEY_EVIDENCE_UNKNOWN_FIELD'
        using errcode='22023',detail=v_key;
    end if;
    begin
      v_money:=pg_catalog.jsonb_populate_record(null::public.weekly_source_money_cell_evidence,v_item);
    exception when others then
      raise exception 'WEEKLY_SOURCE_MONEY_EVIDENCE_TYPE_INVALID' using errcode='22023';
    end;
    v_money.formula_present:=coalesce(v_money.formula_present,false);
    if v_money.source_row_ordinal is null or v_money.source_row_ordinal<1
       or v_money.source_row_ordinal>v_upload.physical_row_count
       or not ((not v_report and v_money.money_field_kind in ('COMMISSION','TOTAL_COST','FMC','BOTTOM_TOTAL_COST','SOURCE_NET','SOURCE_GROSS','SOURCE_VAT'))
          or (v_report and v_money.money_field_kind in ('SOURCE_NET','SOURCE_VAT','SOURCE_GROSS')))
       or v_money.source_column_index is null or v_money.source_column_index<0
       or v_money.source_kind not in (
         'XLSX_NUMERIC_TOKEN','XLSX_STRING_TOKEN','HTML_DECODED_TEXT','CSV_DECODED_TEXT'
       )
       or v_money.original_token is null or v_money.decoded_token is null
       or v_money.parse_state not in (
         'VALID','MISSING','INVALID','EXCESS_PRECISION','FORMULA',
         'UNSUPPORTED_CELL_TYPE','OVERFLOW'
       ) then
      raise exception 'WEEKLY_SOURCE_MONEY_EVIDENCE_INVALID' using errcode='22023';
    end if;
    if nullif(v_item->>'source_file_sha256','') is not null
       and private.weekly_source_hex32_v1(
         v_item->>'source_file_sha256','WEEKLY_SOURCE_EVIDENCE_FILE_HASH_INVALID'
       ) is distinct from v_upload.content_sha256 then
      raise exception 'WEEKLY_SOURCE_EVIDENCE_FILE_HASH_MISMATCH' using errcode='22023';
    end if;
    v_payload:=pg_catalog.jsonb_build_object(
      'source_row_ordinal',v_money.source_row_ordinal,
      'money_field_kind',v_money.money_field_kind,
      'source_column_index',v_money.source_column_index,
      'cell_coordinate',v_money.cell_coordinate,
      'source_kind',v_money.source_kind,
      'original_token',v_money.original_token,
      'decoded_token',v_money.decoded_token,
      'cell_type_marker',v_money.cell_type_marker,
      'formula_present',v_money.formula_present,
      'parse_state',v_money.parse_state,
      'parsed_pence',v_money.parsed_pence
    );
    v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_MONEY_TOKEN_V1',v_payload);
    if nullif(v_item->>'token_sha256','') is not null
       and private.weekly_source_hex32_v1(
         v_item->>'token_sha256','WEEKLY_SOURCE_MONEY_TOKEN_HASH_INVALID'
       ) is distinct from v_hash then
      raise exception 'WEEKLY_SOURCE_MONEY_TOKEN_HASH_MISMATCH' using errcode='22023';
    end if;
    select * into v_existing_money
    from public.weekly_source_money_cell_evidence
    where upload_id=v_upload_id and source_row_ordinal=v_money.source_row_ordinal
      and money_field_kind=v_money.money_field_kind;
    if found then
      if v_existing_money.token_sha256 is distinct from v_hash
         or v_existing_money.source_file_sha256 is distinct from v_upload.content_sha256 then
        raise exception 'WEEKLY_SOURCE_MONEY_EVIDENCE_REPLAY_CONFLICT' using errcode='55000';
      end if;
    else
      insert into public.weekly_source_money_cell_evidence(
        upload_id,source_row_ordinal,money_field_kind,source_column_index,
        cell_coordinate,source_kind,original_token,decoded_token,cell_type_marker,
        formula_present,parse_state,parsed_pence,source_file_sha256,token_sha256
      ) values (
        v_upload_id,v_money.source_row_ordinal,v_money.money_field_kind,
        v_money.source_column_index,v_money.cell_coordinate,v_money.source_kind,
        v_money.original_token,v_money.decoded_token,v_money.cell_type_marker,
        v_money.formula_present,v_money.parse_state,v_money.parsed_pence,
        v_upload.content_sha256,v_hash
      );
      v_money_added:=v_money_added+1;
    end if;
  end loop;

  for v_item in
    select value from pg_catalog.jsonb_array_elements(
      coalesce(p_request->'expense_evidence','[]'::jsonb)
    )
  loop
    if pg_catalog.jsonb_typeof(v_item)<>'object' then
      raise exception 'WEEKLY_SOURCE_EXPENSE_EVIDENCE_INVALID' using errcode='22023';
    end if;
    select key into v_key from pg_catalog.jsonb_object_keys(v_item) key
    where key not in (
      'source_row_ordinal','source_column_index','cell_coordinate','source_kind',
      'original_token','decoded_token','cell_type_marker','formula_present',
      'lexical_profile_version','parse_state','parsed_pence',
      'source_file_sha256','token_sha256'
    ) order by key limit 1;
    if v_key is not null then
      raise exception 'WEEKLY_SOURCE_EXPENSE_EVIDENCE_UNKNOWN_FIELD'
        using errcode='22023',detail=v_key;
    end if;
    begin
      v_expense:=pg_catalog.jsonb_populate_record(null::public.weekly_source_expense_cell_evidence,v_item);
    exception when others then
      raise exception 'WEEKLY_SOURCE_EXPENSE_EVIDENCE_TYPE_INVALID' using errcode='22023';
    end;
    v_expense.formula_present:=coalesce(v_expense.formula_present,false);
    v_expense.lexical_profile_version:=coalesce(
      v_expense.lexical_profile_version,'SOURCE_FIXED_EXPENSE_PENCE_V1'
    );
    if v_expense.source_row_ordinal is null or v_expense.source_row_ordinal<1
       or v_expense.source_row_ordinal>v_upload.physical_row_count
       or v_expense.source_column_index is null or v_expense.source_column_index<0
       or v_expense.source_kind not in (
         'XLSX_NUMERIC_TOKEN','XLSX_STRING_TOKEN','HTML_DECODED_TEXT','CSV_DECODED_TEXT'
       )
       or v_expense.original_token is null or v_expense.decoded_token is null
       or v_expense.lexical_profile_version<>'SOURCE_FIXED_EXPENSE_PENCE_V1'
       or v_expense.parse_state not in (
         'VALID','OMITTED_ZERO','INVALID','EXCESS_PRECISION','FORMULA',
         'UNSUPPORTED_CELL_TYPE','OVERFLOW'
       ) then
      raise exception 'WEEKLY_SOURCE_EXPENSE_EVIDENCE_INVALID' using errcode='22023';
    end if;
    if nullif(v_item->>'source_file_sha256','') is not null
       and private.weekly_source_hex32_v1(
         v_item->>'source_file_sha256','WEEKLY_SOURCE_EVIDENCE_FILE_HASH_INVALID'
       ) is distinct from v_upload.content_sha256 then
      raise exception 'WEEKLY_SOURCE_EVIDENCE_FILE_HASH_MISMATCH' using errcode='22023';
    end if;
    v_payload:=pg_catalog.jsonb_build_object(
      'source_row_ordinal',v_expense.source_row_ordinal,
      'source_column_index',v_expense.source_column_index,
      'cell_coordinate',v_expense.cell_coordinate,
      'source_kind',v_expense.source_kind,
      'original_token',v_expense.original_token,
      'decoded_token',v_expense.decoded_token,
      'cell_type_marker',v_expense.cell_type_marker,
      'formula_present',v_expense.formula_present,
      'lexical_profile_version',v_expense.lexical_profile_version,
      'parse_state',v_expense.parse_state,
      'parsed_pence',v_expense.parsed_pence
    );
    v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_EXPENSE_TOKEN_V1',v_payload);
    if nullif(v_item->>'token_sha256','') is not null
       and private.weekly_source_hex32_v1(
         v_item->>'token_sha256','WEEKLY_SOURCE_EXPENSE_TOKEN_HASH_INVALID'
       ) is distinct from v_hash then
      raise exception 'WEEKLY_SOURCE_EXPENSE_TOKEN_HASH_MISMATCH' using errcode='22023';
    end if;
    select * into v_existing_expense
    from public.weekly_source_expense_cell_evidence
    where upload_id=v_upload_id and source_row_ordinal=v_expense.source_row_ordinal;
    if found then
      if v_existing_expense.token_sha256 is distinct from v_hash
         or v_existing_expense.source_file_sha256 is distinct from v_upload.content_sha256 then
        raise exception 'WEEKLY_SOURCE_EXPENSE_EVIDENCE_REPLAY_CONFLICT' using errcode='55000';
      end if;
    else
      insert into public.weekly_source_expense_cell_evidence(
        upload_id,source_row_ordinal,source_column_index,cell_coordinate,source_kind,
        original_token,decoded_token,cell_type_marker,formula_present,
        lexical_profile_version,parse_state,parsed_pence,source_file_sha256,token_sha256
      ) values (
        v_upload_id,v_expense.source_row_ordinal,v_expense.source_column_index,
        v_expense.cell_coordinate,v_expense.source_kind,v_expense.original_token,
        v_expense.decoded_token,v_expense.cell_type_marker,v_expense.formula_present,
        v_expense.lexical_profile_version,v_expense.parse_state,v_expense.parsed_pence,
        v_upload.content_sha256,v_hash
      );
      v_expenses_added:=v_expenses_added+1;
    end if;
  end loop;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','STAGING','upload_id',v_upload_id,
    'inserted',pg_catalog.jsonb_build_object(
      'physical_rows',v_physical_added,'normalised_rows',v_rows_added,
      'money_evidence',v_money_added,'expense_evidence',v_expenses_added
    ),
    'stored',pg_catalog.jsonb_build_object(
      'physical_rows',(select count(*) from public.weekly_source_physical_rows where upload_id=v_upload_id),
      'normalised_rows',(select count(*) from public.weekly_source_upload_rows where upload_id=v_upload_id),
      'money_evidence',(select count(*) from public.weekly_source_money_cell_evidence where upload_id=v_upload_id),
      'expense_evidence',(select count(*) from public.weekly_source_expense_cell_evidence where upload_id=v_upload_id)
    )
  );
end;
$function$;

-- Complete native successor; bounded report arm only. Root composes later shared owner hunks.
create or replace function private.weekly_source_upload_seal_core_v1(
  p_upload_id uuid,
  p_actor_user_id uuid
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_client_id uuid;
  v_expected_scope bytea;
  v_manifest_hash bytea;
  v_version_before bigint;
  v_version_after bigint;
  v_attempt_id uuid;
  v_actual_physical integer;
  v_actual_header integer;
  v_actual_trailer integer;
  v_actual_continuation integer;
  v_actual_accepted integer;
  v_actual_duplicate integer;
  v_actual_malformed integer;
  v_actual_blocked integer;
  v_normalised_count integer;
  v_money_count integer;
  v_expense_count integer;
  v_actual_coverage_start date;
  v_actual_coverage_end date;
begin
  if p_upload_id is null or p_actor_user_id is null then
    raise exception 'WEEKLY_SOURCE_SEAL_INPUT_INVALID' using errcode='22023';
  end if;
  select * into v_upload
  from public.weekly_source_uploads where id=p_upload_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_FOUND' using errcode='22023';
  end if;
  if v_upload.uploaded_by_user_id is distinct from p_actor_user_id then
    raise exception 'WEEKLY_SOURCE_UPLOAD_ACTOR_MISMATCH' using errcode='42501';
  end if;
  if v_upload.state in ('CURRENT','SUPERSEDED','CORRECTION_READY') then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',v_upload.state,'logical_upload_id',v_upload.id,
      'row_manifest_hash',pg_catalog.encode(v_upload.row_manifest_hash,'hex'),
      'current_pointer_moved',false,'idempotent',true
    );
  end if;
  if v_upload.state<>'STAGING' then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_STAGING' using errcode='55000';
  end if;

  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_upload.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
  if not v_group.active or not v_profile.active
     or v_profile.profile_code not in (
       'NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1',
       'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
       'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
       'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1','ACACIUM_SELF_BILL_REPORT_V1'
     ) or v_profile.version<>1 then
    raise exception 'WEEKLY_SOURCE_RELEASE_PROFILE_STALE' using errcode='55000';
  end if;
  if v_upload.header_coordinate_map_hash is distinct from
     private.weekly_source_sha256_jsonb_v1(
       'WEEKLY_SOURCE_HEADER_COORDINATE_MAP_V1',v_upload.header_coordinate_map_json
     ) then
    raise exception 'WEEKLY_SOURCE_HEADER_MAP_HASH_MISMATCH' using errcode='55000';
  end if;

  if v_upload.report_scope_id is not null then
    if v_profile.profile_code not in ('NHSP_FINAL_BACKING_V1','ACACIUM_SELF_BILL_REPORT_V1') then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_PROFILE_INVALID' using errcode='55000';
    end if;
    select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_upload.report_scope_id;
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_MISMATCH' using errcode='55000';
    end if;
    v_client_id:=v_scope.client_id;
  else
    begin
      v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
    exception when invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_CLIENT_SCOPE_INVALID' using errcode='55000';
    end;
  end if;
  v_expected_scope:=private.weekly_source_scope_fingerprint_v1(
    v_group.environment,v_group.agency_id,v_group.id,v_cycle.id,
    v_upload.report_scope_id,v_client_id
  );
  if v_upload.declared_scope_fingerprint is distinct from v_expected_scope then
    raise exception 'WEEKLY_SOURCE_DECLARED_SCOPE_STALE' using errcode='55000';
  end if;
  if v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' then
    perform 1 from public.weekly_source_groups where id=v_group.id for update;
    perform 1 from public.weekly_source_cycles where id=v_cycle.id for update;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.encode(v_expected_scope,'hex'),73241837)
  );
  select * into strict v_upload
  from public.weekly_source_uploads where id=p_upload_id for update;
  if v_upload.uploaded_by_user_id is distinct from p_actor_user_id then
    raise exception 'WEEKLY_SOURCE_UPLOAD_ACTOR_MISMATCH' using errcode='42501';
  end if;
  if v_upload.state in ('CURRENT','SUPERSEDED','CORRECTION_READY') then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',v_upload.state,'logical_upload_id',v_upload.id,
      'row_manifest_hash',pg_catalog.encode(v_upload.row_manifest_hash,'hex'),
      'current_pointer_moved',false,'idempotent',true
    );
  end if;
  if v_upload.state<>'STAGING'
     or v_upload.declared_scope_fingerprint is distinct from v_expected_scope then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_STAGING' using errcode='55000';
  end if;
  if v_upload.report_scope_id is null then
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_upload.source_cycle_id for update;
  else
    -- NHSP authority is per Trust.  Do not serialize independent Trusts by
    -- taking the shared cycle row lock; the exact report-scope row is its head.
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_upload.source_cycle_id;
    select * into strict v_scope
    from public.weekly_source_report_scopes where id=v_upload.report_scope_id for update;
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.client_id is distinct from v_client_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_CHANGED' using errcode='55000';
    end if;
  end if;
  if private.weekly_source_scope_fingerprint_v1(
       v_group.environment,v_group.agency_id,v_group.id,v_cycle.id,
       v_upload.report_scope_id,v_client_id
     ) is distinct from v_expected_scope then
    raise exception 'WEEKLY_SOURCE_SCOPE_CHANGED' using errcode='55000';
  end if;
  perform private.weekly_source_office_authority_v1(
    p_actor_user_id,'SEAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  select
    count(*)::integer,
    count(*) filter(where classification='HEADER')::integer,
    count(*) filter(where classification='TRAILER')::integer,
    count(*) filter(where classification='PROFILE_PROVED_NON_ECONOMIC_CONTINUATION')::integer,
    count(*) filter(where classification='ACCEPTED_SHIFT')::integer,
    count(*) filter(where classification='BLOCKING_ECONOMIC_DUPLICATE')::integer,
    count(*) filter(where classification='BLOCKING_MALFORMED')::integer
  into v_actual_physical,v_actual_header,v_actual_trailer,v_actual_continuation,
       v_actual_accepted,v_actual_duplicate,v_actual_malformed
  from public.weekly_source_physical_rows where upload_id=v_upload.id;
  select count(*)::integer,
         count(*) filter(where row_finalisation_state in (
           'BLOCK_FINALISATION_DISAGREEMENT','BLOCK_ACTUAL_TUPLE'
         ))::integer
    into v_normalised_count,v_actual_blocked
  from public.weekly_source_upload_rows where upload_id=v_upload.id;
  v_actual_blocked:=v_actual_blocked+v_actual_duplicate+v_actual_malformed;

  if v_actual_physical<>v_upload.physical_row_count
     or v_actual_header<>v_upload.header_count
     or v_actual_trailer<>v_upload.trailer_count
     or v_actual_continuation<>v_upload.continuation_count
     or v_actual_accepted<>v_upload.accepted_count
     or v_actual_duplicate<>v_upload.blocking_economic_duplicate_count
     or v_actual_malformed<>v_upload.malformed_count
     or v_actual_blocked<>v_upload.blocked_count
     or v_actual_physical<>v_actual_header+v_actual_trailer+v_actual_continuation+
       v_actual_accepted+v_actual_duplicate+v_actual_malformed
     or v_normalised_count<>v_actual_accepted then
    raise exception 'WEEKLY_SOURCE_ROW_COUNTS_MISMATCH' using errcode='55000';
  end if;
  if exists(
    select 1 from public.weekly_source_upload_rows normalised
    left join public.weekly_source_physical_rows physical
      on physical.upload_id=normalised.upload_id
     and physical.source_row_ordinal=normalised.source_row_ordinal
    where normalised.upload_id=v_upload.id
      and (physical.id is null or physical.classification<>'ACCEPTED_SHIFT')
  ) or exists(
    select 1 from public.weekly_source_physical_rows physical
    left join public.weekly_source_upload_rows normalised
      on normalised.upload_id=physical.upload_id
     and normalised.source_row_ordinal=physical.source_row_ordinal
    where physical.upload_id=v_upload.id
      and physical.classification='ACCEPTED_SHIFT'
      and normalised.id is null
  ) then
    raise exception 'WEEKLY_SOURCE_ACCEPTED_ROW_EVIDENCE_MISMATCH' using errcode='55000';
  end if;
  if v_actual_duplicate<>0 or v_actual_malformed<>0 or v_actual_blocked<>0 then
    raise exception 'WEEKLY_SOURCE_UPLOAD_HAS_BLOCKERS' using errcode='55000';
  end if;

  -- The sealed row state is profile authority, not a caller-selected label.
  -- A source-zero row is retained as evidence only by the one released
  -- no-finalisation-column profile which proves that zero means source absence.
  if exists(
    select 1
    from public.weekly_source_upload_rows source_row
    where source_row.upload_id=v_upload.id
      and (
        (v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' and source_row.row_finalisation_state<>'SOURCE_REPORT_LINE')
        or (v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1')
          and source_row.row_finalisation_state<>'SOURCE_WORKED')
        or (v_profile.profile_code in (
              'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
              'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1'
            ) and source_row.row_finalisation_state not in ('SOURCE_WORKED','SOURCE_UNFINALISED'))
        or (v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
            and source_row.row_finalisation_state not in ('SOURCE_WORKED','SOURCE_ABSENT_ZERO'))
        or (source_row.row_finalisation_state='SOURCE_WORKED' and (
              source_row.start_at_local is null
              or source_row.end_at_local is null
              or source_row.break_minutes is null
              or source_row.actual_net_minutes is null
              or source_row.actual_net_minutes<=0
              or pg_catalog.mod(
                   extract(epoch from (source_row.end_at_local-source_row.start_at_local))::numeric,
                   60::numeric
                 )<>0
              or source_row.actual_net_minutes<>
                 (extract(epoch from (source_row.end_at_local-source_row.start_at_local))/60)::integer
                 - source_row.break_minutes
            ))
        or (source_row.row_finalisation_state='SOURCE_ABSENT_ZERO'
            and source_row.actual_net_minutes is distinct from 0)
      )
  ) then
    raise exception 'WEEKLY_SOURCE_ROW_FINALISATION_STATE_INVALID' using errcode='55000';
  end if;

  -- WP-54.  Two source-row admission rules the pack states and that nothing
  -- enforced.  They are placed HERE, after the state validation immediately
  -- above, because that validation is what guarantees every SOURCE_WORKED row
  -- has a complete, internally consistent Actual tuple; a guard that reads
  -- start and end before that check could silently skip a row whose times were
  -- absent.  Both raise, and public.weekly_source_upload_seal_atomic_v1 turns
  -- the raise into a typed REJECTED attempt with the code as its reason, so a
  -- refused report is refused as a whole -- pack 14 section 4.1.7, "Finalisation
  -- is all or nothing.  A blocker cannot be removed, unticked or ignored".
  --
  -- NHSP-BR-006 (pack 14 section 4.1.3): the confirmed cutoff occurrence may
  -- not predate any row's real Actual finish, overnight finishes included.  The
  -- cutoff handed over is v_cycle.cutoff_at_utc, which for a report scope this
  -- function has already proved equal to v_scope.cutoff_at_utc under the scope
  -- row lock above.
  if v_profile.profile_code<>'ACACIUM_SELF_BILL_REPORT_V1' then
  perform private.weekly_source_cutoff_admission_assert_v1(
    v_upload.id,v_profile.profile_code,v_cycle.cutoff_at_utc
  );
  -- Pack 03 section 7 with pack 14 section 4.2.8: one person cannot work two
  -- intersecting intervals, and two overlapping records are not made valid by
  -- differing references.
  perform private.weekly_source_overlap_admission_assert_v1(v_upload.id);
  end if;

  if v_actual_accepted=0
     and v_upload.coverage_proof_kind<>'EXPLICIT_EMPTY_CONFIRMATION'
     and coalesce((v_upload.file_metadata_json->>'explicit_empty_attestation')::boolean,false)=false then
    raise exception 'WEEKLY_SOURCE_EMPTY_ATTESTATION_REQUIRED' using errcode='55000';
  end if;

  if v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' then
    perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
  elsif v_profile.profile_code='NHSP_FINAL_BACKING_V1' then
    if v_upload.coverage_proof_kind<>'NHSP_TRUST_REPORT_SCOPE'
       or v_upload.confirmed_coverage_start_local_date is not null
       or v_upload.confirmed_coverage_end_local_date is not null
       or private.weekly_source_canonical_report_number_v1(
         v_upload.file_metadata_json->>'nhsp_report_number'
       ) is null
       or v_upload.money_lexical_authority_version<>
          'XLSX_BINARY64_SAME_VALUE_PENCE_V1' then
      raise exception 'WEEKLY_SOURCE_NHSP_FINAL_EVIDENCE_INVALID' using errcode='55000';
    end if;
    select count(*)::integer into v_money_count
    from public.weekly_source_money_cell_evidence where upload_id=v_upload.id;
    if v_money_count not in (v_actual_accepted*3,v_actual_accepted*3+1)
       or (v_money_count=v_actual_accepted*3+1 and not exists(
         select 1 from public.weekly_source_money_cell_evidence money
         join public.weekly_source_physical_rows physical
           on physical.upload_id=money.upload_id
          and physical.source_row_ordinal=money.source_row_ordinal
         where money.upload_id=v_upload.id and money.money_field_kind='BOTTOM_TOTAL_COST'
           and physical.classification='TRAILER'
       ))
       or exists(
         select 1
         from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (
             source_row.source_money_parse_state<>'VALID'
             or source_row.source_commission_pence is null
             or source_row.source_total_cost_pence is null
             or source_row.source_shift_charge_pence is null
             or source_row.source_shift_charge_pence<>
                source_row.source_commission_pence+source_row.source_total_cost_pence
             or sign(source_row.source_commission_pence) not in (0,sign(source_row.source_shift_charge_pence))
             or sign(source_row.source_total_cost_pence) not in (0,sign(source_row.source_shift_charge_pence))
             or (select count(*) from public.weekly_source_money_cell_evidence money
                 where money.upload_id=source_row.upload_id
                   and money.source_row_ordinal=source_row.source_row_ordinal
                    and money.money_field_kind in ('COMMISSION','TOTAL_COST','FMC')
                    and money.parse_state='VALID'
                    and not money.formula_present
                    and (
                      (v_upload.parser_summary_json->>'source_kind'='HTML'
                       and money.source_kind='HTML_DECODED_TEXT')
                      or (coalesce(v_upload.parser_summary_json->>'source_kind','XLSX')='XLSX'
                          and money.source_kind in ('XLSX_NUMERIC_TOKEN','XLSX_STRING_TOKEN'))
                    )
                    and nullif(money.cell_coordinate,'') is not null)<>3
             or (select money.parsed_pence from public.weekly_source_money_cell_evidence money
                 where money.upload_id=source_row.upload_id
                   and money.source_row_ordinal=source_row.source_row_ordinal
                   and money.money_field_kind='COMMISSION')
                is distinct from source_row.source_commission_pence
             or (select money.parsed_pence from public.weekly_source_money_cell_evidence money
                 where money.upload_id=source_row.upload_id
                   and money.source_row_ordinal=source_row.source_row_ordinal
                   and money.money_field_kind='TOTAL_COST')
                is distinct from source_row.source_total_cost_pence
             or (select money.parsed_pence from public.weekly_source_money_cell_evidence money
                 where money.upload_id=source_row.upload_id
                   and money.source_row_ordinal=source_row.source_row_ordinal
                   and money.money_field_kind='FMC') is distinct from 0
           )
       )
       or exists(
          select 1 from public.weekly_source_money_cell_evidence money
          where money.upload_id=v_upload.id
            and (
              money.source_file_sha256 is distinct from v_upload.content_sha256
              or not (
                (v_upload.parser_summary_json->>'source_kind'='HTML'
                 and money.source_kind='HTML_DECODED_TEXT')
                or (coalesce(v_upload.parser_summary_json->>'source_kind','XLSX')='XLSX'
                    and money.source_kind in ('XLSX_NUMERIC_TOKEN','XLSX_STRING_TOKEN'))
              )
              or nullif(money.cell_coordinate,'') is null
              or (money.formula_present is distinct from (money.parse_state='FORMULA'))
              or (money.money_field_kind='BOTTOM_TOTAL_COST'
                  and (money.parse_state<>'VALID' or money.formula_present))
            )
        ) then
      raise exception 'WEEKLY_SOURCE_NHSP_MONEY_EVIDENCE_INVALID' using errcode='55000';
    end if;
  elsif v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1' then
    -- Pre-final NHSP money is checking evidence only.  It must be retained
    -- exactly, but an unparseable component remains a non-blocking pricing
    -- issue for the comparison owner rather than rejecting the hours upload.
    if v_upload.money_lexical_authority_version<>
         'XLSX_BINARY64_SAME_VALUE_PENCE_V1' then
      raise exception 'WEEKLY_SOURCE_NHSP_PREFINAL_EVIDENCE_INVALID' using errcode='55000';
    end if;
    select count(*)::integer into v_money_count
    from public.weekly_source_money_cell_evidence where upload_id=v_upload.id;
    if v_money_count<>v_actual_accepted*2
       or exists(
         select 1
         from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (
             (select count(*) from public.weekly_source_money_cell_evidence money
              where money.upload_id=source_row.upload_id
                and money.source_row_ordinal=source_row.source_row_ordinal
                and money.money_field_kind in ('COMMISSION','TOTAL_COST'))<>2
             or (
               source_row.source_money_parse_state='VALID'
               and (
                 source_row.source_commission_pence is null
                 or source_row.source_total_cost_pence is null
                 or source_row.source_shift_charge_pence is null
                 or source_row.source_shift_charge_pence<>
                    source_row.source_commission_pence+source_row.source_total_cost_pence
                 or sign(source_row.source_commission_pence) not in
                    (0,sign(source_row.source_shift_charge_pence))
                 or sign(source_row.source_total_cost_pence) not in
                    (0,sign(source_row.source_shift_charge_pence))
                 or (select count(*) from public.weekly_source_money_cell_evidence money
                     where money.upload_id=source_row.upload_id
                       and money.source_row_ordinal=source_row.source_row_ordinal
                       and money.money_field_kind in ('COMMISSION','TOTAL_COST')
                       and money.parse_state='VALID'
                       and not money.formula_present)<>2
                 or (select money.parsed_pence
                     from public.weekly_source_money_cell_evidence money
                     where money.upload_id=source_row.upload_id
                       and money.source_row_ordinal=source_row.source_row_ordinal
                       and money.money_field_kind='COMMISSION')
                    is distinct from source_row.source_commission_pence
                 or (select money.parsed_pence
                     from public.weekly_source_money_cell_evidence money
                     where money.upload_id=source_row.upload_id
                       and money.source_row_ordinal=source_row.source_row_ordinal
                       and money.money_field_kind='TOTAL_COST')
                    is distinct from source_row.source_total_cost_pence
               )
             )
             or (
               source_row.source_money_parse_state<>'VALID'
               and (
                 source_row.source_money_parse_state not in (
                   'MISSING','INVALID','EXCESS_PRECISION','FORMULA',
                   'UNSUPPORTED_CELL_TYPE','OVERFLOW'
                 )
                 or source_row.source_commission_pence is not null
                 or source_row.source_total_cost_pence is not null
                 or source_row.source_shift_charge_pence is not null
                 or not exists(
                   select 1 from public.weekly_source_money_cell_evidence money
                   where money.upload_id=source_row.upload_id
                     and money.source_row_ordinal=source_row.source_row_ordinal
                     and money.parse_state<>'VALID'
                 )
               )
             )
           )
       )
       or exists(
         select 1 from public.weekly_source_money_cell_evidence money
         where money.upload_id=v_upload.id
           and (
             money.money_field_kind not in ('COMMISSION','TOTAL_COST')
             or money.source_file_sha256 is distinct from v_upload.content_sha256
             or not (
               (v_upload.parser_summary_json->>'source_kind'='HTML'
                and money.source_kind='HTML_DECODED_TEXT')
               or (coalesce(v_upload.parser_summary_json->>'source_kind','XLSX')='XLSX'
                   and money.source_kind in ('XLSX_NUMERIC_TOKEN','XLSX_STRING_TOKEN'))
             )
             or nullif(money.cell_coordinate,'') is null
             or (money.formula_present is distinct from (money.parse_state='FORMULA'))
           )
       ) then
      raise exception 'WEEKLY_SOURCE_NHSP_PREFINAL_MONEY_EVIDENCE_INVALID'
        using errcode='55000';
    end if;
  elsif (private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id)#>>'{values,invoice_sender}')='CLIENT_SELF_BILL'
    and (private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id)#>>'{values,invoice_amount_basis}')='SOURCE_AMOUNT'
    and (private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id)#>>'{values,source_amount_basis}')='EXPORT_ACTUAL_COST_INC_VAT_NET_AGENCY_WORKER_PAY' then
    if v_profile.profile_code not in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1')
      or exists(select 1 from public.weekly_source_upload_rows s where s.upload_id=v_upload.id and (
        s.source_commission_pence is not null or s.source_total_cost_pence is not null
        or (s.row_finalisation_state='SOURCE_WORKED' and (s.source_money_parse_state<>'VALID'
          or s.source_qualification_profile_version is distinct from 'SOURCE_INVOICE_MONEY_PENCE_V1'
          or s.source_shift_charge_pence is null or s.source_gross_pence is null or s.source_vat_pence is null
          or s.source_shift_charge_pence<0 or s.source_gross_pence<0 or s.source_shift_charge_pence+s.source_vat_pence<>s.source_gross_pence
          or s.finalised_at_utc is null or nullif(btrim(s.finalised_by),'') is null
          or (select count(*) from public.weekly_source_money_cell_evidence e where e.upload_id=s.upload_id and e.source_row_ordinal=s.source_row_ordinal
            and e.money_field_kind in ('SOURCE_NET','SOURCE_GROSS') and e.parse_state='VALID' and not e.formula_present and e.source_file_sha256=v_upload.content_sha256
            and e.parsed_pence=case e.money_field_kind when 'SOURCE_NET' then s.source_shift_charge_pence else s.source_gross_pence end)<>2))
        or (s.row_finalisation_state<>'SOURCE_WORKED' and (s.source_money_parse_state<>'NOT_APPLICABLE' or s.source_shift_charge_pence is not null
          or s.source_gross_pence is not null or s.source_vat_pence is not null or s.finalised_at_utc is not null))))
      or exists(select 1 from public.weekly_source_money_cell_evidence e where e.upload_id=v_upload.id
        and e.money_field_kind not in ('SOURCE_NET','SOURCE_GROSS')) then
      raise exception 'WEEKLY_SOURCE_INVOICE_MONEY_EVIDENCE_INVALID' using errcode='55000'; end if;
  else
    if exists(select 1 from public.weekly_source_money_cell_evidence where upload_id=v_upload.id)
       or exists(select 1 from public.weekly_source_upload_rows source_row where source_row.upload_id=v_upload.id
         and (source_row.source_money_parse_state<>'NOT_APPLICABLE' or source_row.source_commission_pence is not null
           or source_row.source_total_cost_pence is not null or source_row.source_shift_charge_pence is not null
           or source_row.source_gross_pence is not null or source_row.source_vat_pence is not null)) then
      raise exception 'WEEKLY_SOURCE_MONEY_EVIDENCE_NOT_ALLOWED' using errcode='55000'; end if;
  end if;

  select count(*)::integer into v_expense_count
  from public.weekly_source_expense_cell_evidence where upload_id=v_upload.id;
  if v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1' then
    if v_expense_count<>v_actual_accepted
       or exists(
         select 1 from public.weekly_source_upload_rows source_row
         left join public.weekly_source_expense_cell_evidence expense
           on expense.upload_id=source_row.upload_id
          and expense.source_row_ordinal=source_row.source_row_ordinal
         where source_row.upload_id=v_upload.id
           and (
             expense.id is null
             or expense.source_file_sha256 is distinct from v_upload.content_sha256
             or source_row.source_expense_parse_state not in ('VALID','OMITTED_ZERO')
             or expense.parse_state is distinct from source_row.source_expense_parse_state
             or expense.parsed_pence is distinct from source_row.source_expense_pence
           )
       ) then
      raise exception 'WEEKLY_SOURCE_EXPENSE_EVIDENCE_INVALID' using errcode='55000';
    end if;
  elsif v_expense_count<>0 or exists(
    select 1 from public.weekly_source_upload_rows source_row
    where source_row.upload_id=v_upload.id
      and (source_row.source_expense_parse_state<>'NOT_APPLICABLE'
           or source_row.source_expense_pence is not null)
  ) then
    raise exception 'WEEKLY_SOURCE_EXPENSE_EVIDENCE_NOT_ALLOWED' using errcode='55000';
  end if;

  if v_profile.profile_code not in ('NHSP_FINAL_BACKING_V1','ACACIUM_SELF_BILL_REPORT_V1') then
    if v_upload.coverage_state<>'COMPLETE'
       or v_upload.confirmed_coverage_start_local_date is null
       or v_upload.confirmed_coverage_end_local_date is null
       or v_upload.confirmed_coverage_start_local_date>v_upload.confirmed_coverage_end_local_date
       or v_upload.coverage_timezone<>'Europe/London'
       or nullif(v_upload.coverage_confirmation_version,'') is null
       or v_upload.coverage_confirmed_by_user_id is null
       or v_upload.coverage_confirmed_at_utc is null then
      raise exception 'WEEKLY_SOURCE_COMPLETE_COVERAGE_INVALID' using errcode='55000';
    end if;
    if v_actual_accepted>0 then
      select pg_catalog.min(source_row.work_date),pg_catalog.max(source_row.work_date)
        into v_actual_coverage_start,v_actual_coverage_end
      from public.weekly_source_upload_rows source_row
      where source_row.upload_id=v_upload.id;
      -- 14 section 5.4.3, first sentence: the SUGGESTION is the file's own
      -- earliest and latest valid work Date, so it is evidence and is still
      -- checked exactly against the rows that were actually staged.  A caller
      -- may not widen the suggestion to manufacture coverage.
      if v_upload.suggested_coverage_start_local_date is distinct from v_actual_coverage_start
         or v_upload.suggested_coverage_end_local_date is distinct from v_actual_coverage_end then
        raise exception 'WEEKLY_SOURCE_COVERAGE_EVIDENCE_MISMATCH' using errcode='55000';
      end if;
      -- 14 section 5.4.3, second sentence: "Office must confirm that the export
      -- is complete for that date range."  The CONFIRMATION is Office's own
      -- attestation and is deliberately independent of the rows present, so
      -- that 5.4.5 bullet 4 -- "absent inside confirmed coverage: create one
      -- full cancellation reversal" -- can reach a shift the source has
      -- stopped sending.  Coverage derived from what arrived can never notice
      -- what stopped arriving.  It must still CONTAIN the evidence, because the
      -- finaliser admits no resolution outside confirmed coverage.
      if v_upload.confirmed_coverage_start_local_date>v_actual_coverage_start
         or v_upload.confirmed_coverage_end_local_date<v_actual_coverage_end then
        raise exception 'WEEKLY_SOURCE_COVERAGE_CONFIRMATION_NARROWER_THAN_EVIDENCE'
          using errcode='55000';
      end if;
    elsif v_upload.suggested_coverage_start_local_date is not null
       or v_upload.suggested_coverage_end_local_date is not null then
      raise exception 'WEEKLY_SOURCE_EMPTY_COVERAGE_SUGGESTION_INVALID' using errcode='55000';
    end if;
  end if;

  v_manifest_hash:=private.weekly_source_upload_manifest_hash_v1(v_upload.id);
  if v_upload.purpose='FINAL_SOURCE_CORRECTION' then
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=v_upload.correction_session_id for update;
    if not found or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.report_scope_id is distinct from v_upload.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.state<>'STAGING' then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='55000';
    end if;
    update public.weekly_source_uploads
    set row_manifest_hash=v_manifest_hash,state='CORRECTION_READY'
    where id=v_upload.id;
    update public.weekly_final_source_correction_sessions
    set state='READY',version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_correction.id;
    v_attempt_id:=private.weekly_source_upload_attempt_append_v1(
      v_upload.id,p_actor_user_id,'ACCEPTED','CORRECTION_UPLOAD_READY'
    );
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','CORRECTION_READY','logical_upload_id',v_upload.id,
      'row_manifest_hash',pg_catalog.encode(v_manifest_hash,'hex'),
      'attempt_id',v_attempt_id,'current_pointer_moved',false
    );
  end if;

  if v_upload.report_scope_id is null then
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_upload.source_cycle_id for update;
    if v_cycle.state not in ('OPEN','FINALISABLE') then
      raise exception 'WEEKLY_SOURCE_CYCLE_NOT_OPEN' using errcode='55000';
    end if;
    v_version_before:=v_cycle.version;
    if v_cycle.current_complete_upload_id is not null then
      select * into strict v_prior_upload
      from public.weekly_source_uploads
      where id=v_cycle.current_complete_upload_id for update;
      if v_prior_upload.source_cycle_id is distinct from v_cycle.id
         or v_prior_upload.report_scope_id is not null
         or v_prior_upload.state<>'CURRENT' then
        raise exception 'WEEKLY_SOURCE_CURRENT_POINTER_CORRUPT' using errcode='55000';
      end if;
      -- The longitudinal coverage/omission acknowledgement does not apply to
      -- NHSP previously released shifts. This is provisional checking evidence;
      -- omitted rows never cancel NHSP work or create a financial movement.
      if v_profile.profile_code<>'NHSP_PREFINAL_RELEASED_V1'
         and (v_upload.confirmed_coverage_start_local_date>
            v_prior_upload.confirmed_coverage_start_local_date
          or v_upload.confirmed_coverage_end_local_date<
            v_prior_upload.confirmed_coverage_end_local_date)
         and coalesce(v_upload.coverage_shrink_acknowledged,false)=false then
        raise exception 'WEEKLY_SOURCE_COVERAGE_SHRINK_ACKNOWLEDGEMENT_REQUIRED'
          using errcode='55000';
      end if;
      update public.weekly_source_uploads set state='SUPERSEDED'
      where id=v_prior_upload.id;
    end if;
    update public.weekly_source_projection_publications
    set state='STALE',failure_code='SUPERSEDED_BY_COMPLETE_UPLOAD'
    where source_cycle_id=v_cycle.id and authority_scope_kind='CYCLE'
      and report_scope_id is null and state in ('BUILDING','CURRENT');
    v_version_after:=v_version_before+1;
    update public.weekly_source_uploads
    set row_manifest_hash=v_manifest_hash,state='CURRENT' where id=v_upload.id;
    update public.weekly_source_cycles
    set current_complete_upload_id=v_upload.id,version=v_version_after,
        current_projection_publication_id=null,projection_state='REBUILDING'
    where id=v_cycle.id;
    insert into public.weekly_source_upload_supersessions(
      source_cycle_id,authority_scope_kind,report_scope_id,superseding_upload_id,
      superseded_upload_id,cycle_version_before,cycle_version_after
    ) values (
      v_cycle.id,'CYCLE',null,v_upload.id,v_prior_upload.id,
      v_version_before,v_version_after
    );
  else
    select * into strict v_scope
    from public.weekly_source_report_scopes where id=v_upload.report_scope_id for update;
    if v_scope.state not in ('OPEN','FINALISABLE') then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_NOT_OPEN' using errcode='55000';
    end if;
    v_version_before:=v_scope.version;
    if v_scope.current_complete_upload_id is not null then
      select * into strict v_prior_upload
      from public.weekly_source_uploads
      where id=v_scope.current_complete_upload_id for update;
      if v_prior_upload.source_cycle_id is distinct from v_cycle.id
         or v_prior_upload.report_scope_id is distinct from v_scope.id
         or v_prior_upload.state<>'CURRENT' then
        raise exception 'WEEKLY_SOURCE_CURRENT_POINTER_CORRUPT' using errcode='55000';
      end if;
      update public.weekly_source_uploads set state='SUPERSEDED'
      where id=v_prior_upload.id;
    end if;
    update public.weekly_source_projection_publications
    set state='STALE',failure_code='SUPERSEDED_BY_COMPLETE_UPLOAD'
    where source_cycle_id=v_cycle.id and authority_scope_kind=case when v_scope.self_bill_report_id is null then 'NHSP_REPORT_SCOPE' else 'SELF_BILL_REPORT_SCOPE' end
      and report_scope_id=v_scope.id and state in ('BUILDING','CURRENT');
    v_version_after:=v_version_before+1;
    update public.weekly_source_uploads
    set row_manifest_hash=v_manifest_hash,state='CURRENT' where id=v_upload.id;
    update public.weekly_source_report_scopes
    set current_complete_upload_id=v_upload.id,version=v_version_after,
        current_projection_publication_id=null,projection_state='REBUILDING',
        updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_scope.id;
    insert into public.weekly_source_upload_supersessions(
      source_cycle_id,authority_scope_kind,report_scope_id,superseding_upload_id,
      superseded_upload_id,cycle_version_before,cycle_version_after
    ) values (
      v_cycle.id,case when v_scope.self_bill_report_id is null then 'NHSP_REPORT_SCOPE' else 'SELF_BILL_REPORT_SCOPE' end,v_scope.id,v_upload.id,v_prior_upload.id,
      v_version_before,v_version_after
    );
  end if;

  v_attempt_id:=private.weekly_source_upload_attempt_append_v1(
    v_upload.id,p_actor_user_id,'ACCEPTED','NEW_COMPLETE_UPLOAD'
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','CURRENT','logical_upload_id',v_upload.id,
    'superseded_upload_id',v_prior_upload.id,
    'authority_scope_kind',case when v_upload.report_scope_id is null
      then 'CYCLE' when v_scope.self_bill_report_id is null then 'NHSP_REPORT_SCOPE' else 'SELF_BILL_REPORT_SCOPE' end,
    'authority_scope_version',v_version_after,
    'row_manifest_hash',pg_catalog.encode(v_manifest_hash,'hex'),
    'attempt_id',v_attempt_id,'current_pointer_moved',true,
    'projection_state','REBUILDING'
  );
end;
$function$;

-- Complete native successor; bounded report arm only. Root composes later shared owner hunks.
create or replace function public.weekly_source_projection_begin_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','upload_id','expected_authority_scope_version',
    'correction_session_id','expected_correction_session_version',
    'expected_projection_publication_id','expected_row_manifest_hash',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'rebuild_idempotency_key'
  ]::text[];
  v_rebuild_keys constant text[]:=array[
    'correction_session_id','expected_correction_session_version',
    'expected_projection_publication_id','expected_row_manifest_hash',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'rebuild_idempotency_key'
  ]::text[];
  v_unknown_key text;
  v_rebuild boolean;
  v_actor uuid;
  v_upload_id uuid;
  v_expected_version bigint;
  v_correction_id uuid;
  v_expected_session_version bigint;
  v_expected_publication_id uuid;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_rebuild_idempotency_key text;
  v_rebuild_request_hash bytea;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_scope_kind text;
  v_scope_version bigint;
  v_scope_current_upload uuid;
  v_client_id uuid;
  v_empty_comparison_hash bytea;
  v_empty_issue_hash bytea;
  v_projection_generation integer;
  v_resolution_count integer;
  v_rows_applied boolean:=false;
  v_rebuild_replay boolean:=false;
  v_correction_found boolean:=false;
begin
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_PROJECTION_BEGIN_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown_key
  from pg_catalog.jsonb_object_keys(p_request) key
  where not key=any(v_allowed_keys)
  order by key limit 1;
  if v_unknown_key is not null then
    raise exception 'WEEKLY_SOURCE_PROJECTION_BEGIN_REQUEST_INVALID'
      using errcode='22023',detail=v_unknown_key;
  end if;
  v_rebuild:=p_request ?| v_rebuild_keys;
  if v_rebuild and exists(
    select 1 from pg_catalog.unnest(v_rebuild_keys) key
    where not (p_request ? key)
  ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_REBUILD_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_upload_id:=(p_request->>'upload_id')::uuid;
    v_expected_version:=(p_request->>'expected_authority_scope_version')::bigint;
    if v_rebuild then
      v_correction_id:=(p_request->>'correction_session_id')::uuid;
      v_expected_session_version:=(p_request->>'expected_correction_session_version')::bigint;
      v_expected_publication_id:=(p_request->>'expected_projection_publication_id')::uuid;
      v_expected_row_hash:=private.weekly_source_hex32_v1(
        p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_INVALID'
      );
      v_expected_comparison_hash:=private.weekly_source_hex32_v1(
        p_request->>'expected_comparison_manifest_hash',
        'WEEKLY_SOURCE_COMPARISON_MANIFEST_HASH_INVALID'
      );
      v_expected_issue_hash:=private.weekly_source_hex32_v1(
        p_request->>'expected_issue_set_hash','WEEKLY_SOURCE_ISSUE_SET_HASH_INVALID'
      );
      v_rebuild_idempotency_key:=pg_catalog.btrim(
        coalesce(p_request->>'rebuild_idempotency_key','')
      );
    end if;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'WEEKLY_SOURCE_PROJECTION_BEGIN_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_upload_id is null or v_expected_version is null
     or v_expected_version<1
     or (v_rebuild and (
       v_correction_id is null or v_expected_session_version is null
       or v_expected_session_version<1 or v_expected_publication_id is null
       or pg_catalog.octet_length(v_expected_row_hash)<>32
       or pg_catalog.octet_length(v_expected_comparison_hash)<>32
       or pg_catalog.octet_length(v_expected_issue_hash)<>32
       or pg_catalog.char_length(v_rebuild_idempotency_key) not between 1 and 200
     )) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_BEGIN_REQUEST_INVALID' using errcode='22023';
  end if;
  if v_rebuild then
    v_rebuild_request_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PROJECTION_REBUILD_V1',p_request-'rebuild_idempotency_key'
    );
  end if;
  select * into v_upload
  from public.weekly_source_uploads where id=v_upload_id;
  if not found or v_upload.row_manifest_hash is null
     or (v_upload.purpose='ORDINARY' and v_upload.state<>'CURRENT')
     or (v_upload.purpose='FINAL_SOURCE_CORRECTION' and v_upload.state<>'CORRECTION_READY') then
    return pg_catalog.jsonb_build_object(
      'ok',false,'status','STALE','reason_code','WEEKLY_SOURCE_UPLOAD_NOT_CURRENT'
    );
  end if;
  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_upload.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  if v_upload.purpose<>'FINAL_SOURCE_CORRECTION' and v_upload.correction_session_id is not null then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
  end if;

  if v_upload.report_scope_id is null then
    v_scope_kind:='CYCLE';
    v_scope_version:=v_cycle.version;
    v_scope_current_upload:=v_cycle.current_complete_upload_id;
    begin
      v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
    exception when invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
    end;
  else
    select * into strict v_scope
    from public.weekly_source_report_scopes where id=v_upload.report_scope_id;
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
    end if;
    v_scope_kind:=case when v_scope.self_bill_report_id is null then 'NHSP_REPORT_SCOPE' else 'SELF_BILL_REPORT_SCOPE' end;
    if v_scope.self_bill_report_id is not null then
      if v_upload.purpose<>'ORDINARY' or v_rebuild then
        raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000'; end if;
      perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
      perform 1 from public.weekly_source_groups where id=v_group.id for update;
      perform 1 from public.weekly_source_cycles where id=v_cycle.id for update;
    end if;
    v_scope_version:=v_scope.version;
    v_scope_current_upload:=v_scope.current_complete_upload_id;
    v_client_id:=v_scope.client_id;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.encode(v_upload.declared_scope_fingerprint,'hex'),73241837)
  );
  if v_scope_kind='CYCLE' then
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_upload.source_cycle_id for update;
    v_scope_version:=v_cycle.version;
    v_scope_current_upload:=v_cycle.current_complete_upload_id;
  else
    -- Each NHSP Trust publishes independently under its report-scope head.
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_upload.source_cycle_id;
    select * into strict v_scope
    from public.weekly_source_report_scopes where id=v_upload.report_scope_id for update;
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.client_id is distinct from v_client_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000';
    end if;
    v_scope_version:=v_scope.version;
    v_scope_current_upload:=v_scope.current_complete_upload_id;
  end if;
  if v_upload.purpose='FINAL_SOURCE_CORRECTION' then
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=v_upload.correction_session_id for update;
    v_correction_found:=found;
    if v_correction_found and v_rebuild then
      select * into v_publication
      from public.weekly_source_projection_publications publication
      where publication.correction_session_id=v_correction.id
        and publication.rebuild_idempotency_key=v_rebuild_idempotency_key
      for update;
      if found then
        if v_publication.rebuild_request_hash is distinct from v_rebuild_request_hash then
          raise exception 'WEEKLY_SOURCE_PROJECTION_REBUILD_IDEMPOTENCY_COLLISION'
            using errcode='22023';
        end if;
        if v_publication.state='BUILDING' then
          if v_correction.state<>'REVIEWED'
             or v_correction.version<>v_expected_session_version
             or v_correction.replacement_projection_publication_id
                  is distinct from v_expected_publication_id then
            raise exception 'WEEKLY_SOURCE_CORRECTION_REBUILD_STALE' using errcode='40001';
          end if;
        elsif v_publication.state='CORRECTION_READY' then
          if v_correction.replacement_projection_publication_id
               is distinct from v_publication.id
             or v_publication.ready_session_version is null then
            raise exception 'WEEKLY_SOURCE_CORRECTION_REBUILD_STALE' using errcode='40001';
          end if;
        else
          raise exception 'WEEKLY_SOURCE_CORRECTION_REBUILD_STALE' using errcode='40001';
        end if;
        v_rebuild_replay:=true;
      end if;
    end if;
    if not v_correction_found
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_scope_kind
       or v_correction.report_scope_id is distinct from v_upload.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.actor_user_id is distinct from v_actor
       or (v_rebuild and not v_rebuild_replay and (
         v_correction.id is distinct from v_correction_id
         or v_correction.state<>'REVIEWED'
         or v_correction.version<>v_expected_session_version
         or v_correction.replacement_projection_publication_id
              is distinct from v_expected_publication_id
       ))
       or (not v_rebuild and v_correction.state<>'READY') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
    end if;
  elsif v_rebuild then
    raise exception 'WEEKLY_SOURCE_PROJECTION_REBUILD_REQUEST_INVALID' using errcode='22023';
  end if;
  if private.weekly_source_scope_fingerprint_v1(
       v_group.environment,v_group.agency_id,v_group.id,v_cycle.id,
       v_upload.report_scope_id,v_client_id
     ) is distinct from v_upload.declared_scope_fingerprint then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000';
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'RECHECK_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  if v_scope_version<>v_expected_version
     or (v_upload.purpose='ORDINARY' and v_scope_current_upload is distinct from v_upload.id)
     or (v_upload.purpose='FINAL_SOURCE_CORRECTION' and
       coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
         is distinct from v_correction.expected_current_final_revision_id) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'status','STALE','reason_code','WEEKLY_SOURCE_SCOPE_VERSION_STALE',
      'current_upload_id',v_scope_current_upload,'current_authority_scope_version',v_scope_version
    );
  end if;

  if v_rebuild then
    select * into v_publication
    from public.weekly_source_projection_publications publication
    where publication.correction_session_id=v_correction.id
      and publication.rebuild_idempotency_key=v_rebuild_idempotency_key
    for update;
    if found then
      if v_publication.state not in ('BUILDING','CORRECTION_READY')
         or v_publication.upload_id is distinct from v_upload.id
         or v_publication.authority_scope_version<>v_scope_version then
        return pg_catalog.jsonb_build_object(
          'ok',false,'status','STALE',
          'reason_code','WEEKLY_SOURCE_CORRECTION_REBUILD_STALE',
          'publication_id',v_publication.id
        );
      end if;
      if v_publication.state='CORRECTION_READY'
         and v_correction.replacement_projection_publication_id
               is distinct from v_publication.id then
        return pg_catalog.jsonb_build_object(
          'ok',false,'status','STALE',
          'reason_code','WEEKLY_SOURCE_CORRECTION_REBUILD_POINTER_STALE',
          'publication_id',v_publication.id
        );
      end if;
      select pg_catalog.count(*)::integer into v_resolution_count
      from public.weekly_source_row_resolutions resolution
      join public.weekly_source_upload_rows source_row
        on source_row.id=resolution.upload_row_id
      where source_row.upload_id=v_upload.id
        and resolution.generation=coalesce(
          v_publication.projection_generation,
          v_publication.authority_scope_version::integer
        );
      v_rows_applied:=v_resolution_count=v_upload.accepted_count;
      return pg_catalog.jsonb_build_object(
        'ok',true,'status',v_publication.state,
        'publication_id',v_publication.id,'upload_id',v_upload.id,
        'authority_scope_version',v_scope_version,
        'projection_generation',v_publication.projection_generation,
        'ready_session_version',v_publication.ready_session_version,
        'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
        'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex'),
        'rows_applied',v_rows_applied,'idempotent',true
      );
    end if;
    select * into v_prior_publication
    from public.weekly_source_projection_publications publication
    where publication.id=v_expected_publication_id for share;
    if not found or v_upload.row_manifest_hash is distinct from v_expected_row_hash
       or v_prior_publication.state<>'CORRECTION_READY'
       or v_prior_publication.correction_session_id is distinct from v_correction.id
       or v_prior_publication.upload_id is distinct from v_upload.id
       or v_prior_publication.source_cycle_id is distinct from v_cycle.id
       or v_prior_publication.authority_scope_kind is distinct from v_scope_kind
       or v_prior_publication.report_scope_id is distinct from v_upload.report_scope_id
       or v_prior_publication.authority_scope_version<>v_scope_version
       or v_prior_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
       or v_prior_publication.issue_set_hash is distinct from v_expected_issue_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REBUILD_STALE' using errcode='40001';
    end if;
  end if;

  select * into v_publication
  from public.weekly_source_projection_publications
  where source_cycle_id=v_cycle.id
    and authority_scope_kind=v_scope_kind
    and report_scope_id is not distinct from v_upload.report_scope_id
    and authority_scope_version=v_scope_version
    and upload_id=v_upload.id
    and projection_generation is null
    and rebuild_idempotency_key is null
  for update;
  if found and not v_rebuild then
    if v_publication.state in ('BUILDING','CURRENT','CORRECTION_READY') then
      return pg_catalog.jsonb_build_object(
        'ok',true,'status',v_publication.state,'publication_id',v_publication.id,
        'upload_id',v_upload.id,'authority_scope_version',v_scope_version,
        'idempotent',true
      );
    elsif v_publication.state='FAILED' then
      update public.weekly_source_projection_publications
      set state='BUILDING',failure_code=null,published_at_utc=null
      where id=v_publication.id;
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','BUILDING','publication_id',v_publication.id,
        'upload_id',v_upload.id,'authority_scope_version',v_scope_version,
        'retry',true
      );
    else
      return pg_catalog.jsonb_build_object(
        'ok',false,'status','STALE','reason_code','WEEKLY_SOURCE_PUBLICATION_STALE',
        'publication_id',v_publication.id
      );
    end if;
  end if;

  v_empty_comparison_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_COMPARISON_MANIFEST_V1',
    pg_catalog.jsonb_build_object(
      'manifest_version','WEEKLY_SOURCE_COMPARISON_MANIFEST_V1',
      'source_authority','[]'::jsonb,'timesheet_authority','[]'::jsonb
    )
  );
  v_empty_issue_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ISSUE_SET_V1',
    pg_catalog.jsonb_build_object('issue_set_version','WEEKLY_SOURCE_ISSUE_SET_V1','issues','[]'::jsonb)
  );
  if v_rebuild then
    if v_scope_version>2147483647 then
      raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003';
    end if;
    select pg_catalog.max(coalesce(
      publication.projection_generation,
      publication.authority_scope_version::integer
    )) into v_projection_generation
    from public.weekly_source_projection_publications publication
    where publication.upload_id=v_upload.id;
    if coalesce(v_projection_generation,0)>=2147483647 then
      raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003';
    end if;
    v_projection_generation:=coalesce(v_projection_generation,0)+1;
  else
    v_projection_generation:=null;
  end if;
  insert into public.weekly_source_projection_publications(
    source_cycle_id,authority_scope_kind,report_scope_id,upload_id,correction_session_id,
    authority_scope_version,projection_generation,rebuild_idempotency_key,
    rebuild_request_hash,ready_session_version,
    comparison_manifest_hash,issue_set_hash,state
  ) values (
    v_cycle.id,v_scope_kind,v_upload.report_scope_id,v_upload.id,v_upload.correction_session_id,
    v_scope_version,v_projection_generation,v_rebuild_idempotency_key,
    v_rebuild_request_hash,case when v_rebuild then v_expected_session_version end,
    v_empty_comparison_hash,v_empty_issue_hash,'BUILDING'
  ) returning * into v_publication;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','BUILDING','publication_id',v_publication.id,
    'upload_id',v_upload.id,'authority_scope_kind',v_scope_kind,
    'authority_scope_version',v_scope_version,
    'projection_generation',v_publication.projection_generation,
    'ready_session_version',v_publication.ready_session_version,
    'rows_applied',false,'idempotent',false
  );
end;
$function$;

-- Complete native successor; bounded report arm only. Root composes later shared owner hunks.
create or replace function public.weekly_source_projection_rows_apply_atomic_v1(
  p_actor_user_id uuid,
  p_publication_id uuid,
  p_rows jsonb
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
declare
  v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_row_json jsonb;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_contract public.contracts%rowtype;
  v_work_event public.weekly_work_events%rowtype;
  v_resolution_id uuid;
  v_work_event_id uuid;
  v_mapping_state text;
  v_selection_method text;
  v_candidate_id uuid;
  v_client_id uuid;
  v_contract_id uuid;
  v_prior_work_event_id uuid;
  v_identity_kind text;
  v_link_kind text;
  v_work_event_match_kind text;
  v_work_event_match_fingerprint bytea;
  v_work_event_was_present boolean;
  v_profile_external_key text;
  v_durable_identity_hash bytea;
  -- WP-37: the `24 §9` step-2 candidate set, counted explicitly.  Safety is
  -- never expressed through `limit`/`order by` here: anything other than
  -- exactly one compatible root takes a named branch.
  v_compatible_count integer;
  v_compatible_event_id uuid;
  v_protected_matches jsonb;
  v_protected_choice uuid;
  v_protected_count integer;
  v_protected_separate boolean;
  v_eligible_ids jsonb;
  v_eligible_hash bytea;
  v_generation integer;
  v_applied integer:=0;
  v_expected integer;
  v_existing integer;
  v_qualification jsonb;
  v_charge jsonb;
  v_economic jsonb;
  v_effective_policy jsonb;
  v_invoice_rules jsonb;
  v_source_amount boolean;
  v_contract_settings_authority jsonb;
  v_canonical_economic jsonb;
  v_contract_rate_fingerprint bytea;
  v_effective_policy_fingerprint bytea;
  v_invoice_vat_policy_fingerprint bytea;
  v_calculation_fingerprint bytea;
  v_expense_policy_snapshot_hash bytea;
  v_source_mode text;
  v_row_sign smallint;
  v_invoice_vat_chargeable boolean;
  v_invoice_vat_rate_pct numeric;
  v_source_expense_vat_enabled boolean;
  v_source_authority boolean;
  v_has_worked_tuple boolean;
  v_expected_pay_pence bigint;
  v_expected_charge_pence bigint;
  v_result text;
  v_passed boolean;
  v_charge_source_pence bigint;
  v_charge_calculated_pence bigint;
  v_charge_difference_pence bigint;
  v_charge_row_sign_kind text;
  v_charge_claimed_result text;
  v_charge_expected_result text;
  v_charge_expected_sign_kind text;
  v_mode_a_policy jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_actor_user_id is null or p_publication_id is null
     or pg_catalog.jsonb_typeof(p_rows)<>'array' then
    raise exception 'WEEKLY_SOURCE_PROJECTION_INPUT_INVALID' using errcode='22023';
  end if;

  -- Read immutable identity first, then enter the same scope lock order as
  -- begin/publish before taking any row lock. Exact retries can therefore race
  -- safely without forming a publication-to-scope lock cycle.
  select * into v_publication
  from public.weekly_source_projection_publications
  where id=p_publication_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_upload
  from public.weekly_source_uploads
  where id=v_publication.upload_id;
  select * into strict v_cycle
  from public.weekly_source_cycles
  where id=v_publication.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  perform private.weekly_source_pay_query_admit_v2();
  if v_publication.authority_scope_kind='SELF_BILL_REPORT_SCOPE' then
    return private.weekly_source_self_bill_report_projection_rows_v1(p_actor_user_id,p_publication_id,p_rows);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.encode(v_upload.declared_scope_fingerprint,'hex'),73241837
    )
  );

  if v_publication.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_cycle
    from public.weekly_source_cycles
    where id=v_publication.source_cycle_id;
    select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id
    for update;
  else
    select * into strict v_cycle
    from public.weekly_source_cycles
    where id=v_publication.source_cycle_id
    for update;
  end if;
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=p_publication_id
  for update;
  if v_publication.state not in ('BUILDING','CORRECTION_READY')
     or (v_publication.state='CORRECTION_READY'
         and v_publication.correction_session_id is null) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_NOT_BUILDING' using errcode='55000';
  end if;
  select * into strict v_upload
  from public.weekly_source_uploads
  where id=v_publication.upload_id
  for share;
  select * into strict v_profile
  from public.weekly_source_format_profiles profile
  where profile.id=v_upload.source_format_profile_id and profile.active;

  if v_publication.authority_scope_kind='NHSP_REPORT_SCOPE' then
    if v_scope.version is distinct from v_publication.authority_scope_version
       or (
         v_publication.correction_session_id is null
         and (v_scope.current_complete_upload_id is distinct from v_upload.id
              or v_scope.projection_state<>'REBUILDING')
       ) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_STALE' using errcode='40001';
    end if;
  elsif v_cycle.version is distinct from v_publication.authority_scope_version
        or (
          v_publication.correction_session_id is null
          and (v_cycle.current_complete_upload_id is distinct from v_upload.id
               or v_cycle.projection_state<>'REBUILDING')
        ) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_STALE' using errcode='40001';
  end if;

  if v_publication.correction_session_id is not null then
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=v_publication.correction_session_id for update;
    if not found
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_publication.authority_scope_kind
       or v_correction.report_scope_id is distinct from v_publication.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.actor_user_id is distinct from p_actor_user_id
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.state<>'CORRECTION_READY'
       or (v_publication.state='BUILDING'
         and v_publication.rebuild_idempotency_key is null and (
         v_correction.state<>'READY'
         or v_correction.replacement_projection_publication_id is not null
       ))
       or (v_publication.state='BUILDING'
         and v_publication.rebuild_idempotency_key is not null and (
         v_publication.projection_generation is null
         or v_publication.ready_session_version is null
         or v_correction.state<>'REVIEWED'
         or v_correction.version<>v_publication.ready_session_version
         or v_correction.replacement_projection_publication_id is null
         or v_correction.replacement_projection_publication_id=v_publication.id
       ))
       or (v_publication.state='CORRECTION_READY'
         and v_correction.replacement_projection_publication_id
               is distinct from v_publication.id)
       or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
            is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
    end if;
  elsif v_upload.purpose<>'ORDINARY' or v_upload.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_STALE' using errcode='40001';
  end if;

  perform private.weekly_source_office_authority_v1(
    p_actor_user_id,'RECHECK_SOURCE',v_group.id,
    case when v_publication.authority_scope_kind='NHSP_REPORT_SCOPE' then v_scope.client_id else null end,
    v_cycle.finalisation_week_ending
  );

  if v_publication.authority_scope_version>2147483647
     or coalesce(v_publication.projection_generation,0)>2147483647 then
    raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003';
  end if;
  v_generation:=coalesce(
    v_publication.projection_generation,
    v_publication.authority_scope_version::integer
  );

  select pg_catalog.count(*)::integer into v_expected
  from public.weekly_source_upload_rows source_row
  where source_row.upload_id=v_upload.id;
  if pg_catalog.jsonb_array_length(p_rows)<>v_expected then
    raise exception 'WEEKLY_SOURCE_PROJECTION_ROW_CENSUS_MISMATCH'
      using errcode='22023',detail=pg_catalog.jsonb_build_object(
        'expected',v_expected,'received',pg_catalog.jsonb_array_length(p_rows)
      )::text;
  end if;

  select pg_catalog.count(*)::integer into v_existing
  from public.weekly_source_row_resolutions resolution
  join public.weekly_source_upload_rows source_row
    on source_row.id=resolution.upload_row_id
  where source_row.upload_id=v_upload.id
    and resolution.generation=v_generation;
  if v_publication.state='CORRECTION_READY' or v_existing>0 then
    if v_existing<>v_expected or exists(
      select 1
      from public.weekly_source_upload_rows source_row
      where source_row.upload_id=v_upload.id
        and not exists(
          select 1
          from public.weekly_source_row_resolutions resolution
          where resolution.upload_row_id=source_row.id
            and resolution.generation=v_generation
            and resolution.source_row_fingerprint=source_row.normalised_row_hash
        )
    ) then
      raise exception 'WEEKLY_SOURCE_PROJECTION_RESOLUTION_CENSUS_INCOMPLETE'
        using errcode='55000';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'publication_id',v_publication.id,'upload_id',v_upload.id,
      'authority_scope_version',v_publication.authority_scope_version,
      'generation',v_generation,'applied_row_count',v_existing,'idempotent',true
    );
  end if;

  for v_row_json in select value from pg_catalog.jsonb_array_elements(p_rows)
  loop
    if pg_catalog.jsonb_typeof(v_row_json)<>'object' then
      raise exception 'WEEKLY_SOURCE_PROJECTION_ROW_INVALID' using errcode='22023';
    end if;
    select * into strict v_source_row
    from public.weekly_source_upload_rows source_row
    where source_row.id=(v_row_json->>'upload_row_id')::uuid
      and source_row.upload_id=v_upload.id
    for share;

    if exists(
      select 1 from public.weekly_source_row_resolutions resolution
      where resolution.upload_row_id=v_source_row.id and resolution.generation=v_generation
    ) then
      raise exception 'WEEKLY_SOURCE_PROJECTION_ROW_ALREADY_APPLIED' using errcode='23505';
    end if;

    v_mapping_state:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'mapping_state','')));
    if v_mapping_state not in (
      'RESOLVED','CANDIDATE_NOT_FOUND','CLIENT_NOT_FOUND','NO_ELIGIBLE_CONTRACT',
      'AMBIGUOUS_CONTRACT','CONTRACT_SELECTION_REQUIRED','SOURCE_ROW_BLOCKED'
    ) then
      raise exception 'WEEKLY_SOURCE_MAPPING_STATE_INVALID' using errcode='22023';
    end if;
    v_candidate_id:=nullif(v_row_json->>'candidate_id','')::uuid;
    v_client_id:=nullif(v_row_json->>'client_id','')::uuid;
    v_contract_id:=nullif(v_row_json->>'contract_id','')::uuid;
    v_prior_work_event_id:=nullif(v_row_json->>'prior_work_event_id','')::uuid;
    v_selection_method:=nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'contract_selection_method',''))),'');
    v_work_event_id:=null;
    v_link_kind:=null;
    v_work_event_match_kind:=null;
    v_work_event_match_fingerprint:=null;
    v_work_event_was_present:=false;
    v_compatible_count:=0;
    v_compatible_event_id:=null;
    v_economic:=v_row_json->'economic_snapshot';
    v_effective_policy:=null;
    v_invoice_rules:=null; v_source_amount:=false;
    v_contract_settings_authority:=null;
    v_canonical_economic:=null;
    v_contract_rate_fingerprint:=null;
    v_effective_policy_fingerprint:=null;
    v_invoice_vat_policy_fingerprint:=null;
    v_calculation_fingerprint:=null;
    v_expense_policy_snapshot_hash:=null;
    v_source_mode:=null;
    v_row_sign:=null;
    v_invoice_vat_chargeable:=null;
    v_invoice_vat_rate_pct:=null;
    v_source_expense_vat_enabled:=null;
    v_source_authority:=false;
    v_has_worked_tuple:=false;

    v_eligible_ids:=coalesce((
      select pg_catalog.jsonb_agg(contract_id order by contract_id)
      from (
        select distinct value as contract_id
        from pg_catalog.jsonb_array_elements_text(coalesce(v_row_json->'qualifying_contract_ids','[]'::jsonb))
      ) ordered
    ),'[]'::jsonb);
    v_eligible_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_QUALIFYING_CONTRACT_SET_V1',v_eligible_ids
    );

    if v_mapping_state='RESOLVED' then
      if v_candidate_id is null or v_client_id is null or v_contract_id is null
         or v_selection_method not in ('AUTO_UNIQUE','OFFICE_SELECTED','DURABLE_LINEAGE') then
        raise exception 'WEEKLY_SOURCE_RESOLVED_MAPPING_INCOMPLETE' using errcode='22023';
      end if;
      select * into strict v_contract
      from public.contracts contract
      where contract.id=v_contract_id
        and contract.candidate_id=v_candidate_id
        and contract.client_id=v_client_id
        and v_source_row.work_date between contract.start_date and coalesce(contract.end_date,'infinity'::date);
      if not (v_eligible_ids ? v_contract_id::text) then
        raise exception 'WEEKLY_SOURCE_SELECTED_CONTRACT_NOT_QUALIFIED' using errcode='22023';
      end if;
      -- G6-4: the selection method must be provable from server-derived
      -- facts, not asserted by the caller. Authority: 24 §8 ("If one Contract
      -- remains, the system selects it… The system must never offer a chooser
      -- when only one Contract is eligible"), 24 §9 (unique prior lineage),
      -- 25 §7, XSG-011, XSG-012.
      if v_selection_method='AUTO_UNIQUE'
         and pg_catalog.jsonb_array_length(v_eligible_ids)<>1 then
        raise exception 'WEEKLY_SOURCE_AUTO_UNIQUE_NOT_UNIQUE' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'qualifying_contract_count',pg_catalog.jsonb_array_length(v_eligible_ids)
          )::text;
      end if;
      if v_selection_method='OFFICE_SELECTED'
         and pg_catalog.jsonb_array_length(v_eligible_ids)<2 then
        raise exception 'WEEKLY_SOURCE_OFFICE_CHOICE_NOT_WARRANTED' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'qualifying_contract_count',pg_catalog.jsonb_array_length(v_eligible_ids)
          )::text;
      end if;
      if v_selection_method='DURABLE_LINEAGE' then
        if v_prior_work_event_id is null then
          raise exception 'WEEKLY_SOURCE_DURABLE_LINEAGE_UNPROVEN' using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'reason','PRIOR_WORK_EVENT_ABSENT'
            )::text;
        end if;
        perform 1
        from public.weekly_work_events prior_event
        join public.weekly_source_row_resolutions prior_resolution
          on prior_resolution.work_event_id=prior_event.id
        where prior_event.id=v_prior_work_event_id
          and prior_event.candidate_id=v_candidate_id
          and prior_event.client_id=v_client_id
          and prior_event.first_source_group_id=v_group.id
          and prior_resolution.mapping_state='RESOLVED'
          and prior_resolution.contract_id=v_contract_id
          and (prior_resolution.upload_row_id<>v_source_row.id
            or (prior_resolution.generation<v_generation
              and prior_resolution.source_row_fingerprint=v_source_row.normalised_row_hash
              and exists(select 1 from public.weekly_source_projection_publications prior_publication
                where prior_publication.upload_id=v_upload.id
                  and coalesce(prior_publication.projection_generation,prior_publication.authority_scope_version)=prior_resolution.generation
                  and prior_publication.published_at_utc is not null
                  and prior_publication.state in ('CURRENT','STALE'))));
        if not found then
          raise exception 'WEEKLY_SOURCE_DURABLE_LINEAGE_UNPROVEN' using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'reason','NO_PRIOR_RESOLVED_CONTRACT_FOR_WORK_EVENT'
            )::text;
        end if;
      end if;

      v_effective_policy:=private._weekly_source_effective_policy_v1(
        v_client_id,v_contract_id,v_source_row.work_date
      );
      v_effective_policy_fingerprint:=private.weekly_source_projection_hex32_v1(
        v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
      );
      if nullif(v_row_json->>'effective_policy_fingerprint','') is not null
         and private.weekly_source_projection_hex32_v1(
           v_row_json->>'effective_policy_fingerprint','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
         ) is distinct from v_effective_policy_fingerprint then
        raise exception 'WEEKLY_SOURCE_POLICY_STALE' using errcode='40001';
      end if;
      v_invoice_rules:=private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id)->'values';
      v_source_amount:=v_invoice_rules is not null and v_invoice_rules->>'invoice_sender'='CLIENT_SELF_BILL' and v_invoice_rules->>'invoice_amount_basis'='SOURCE_AMOUNT' and v_invoice_rules->>'source_amount_basis'='EXPORT_ACTUAL_COST_INC_VAT_NET_AGENCY_WORKER_PAY';
      v_source_authority:=coalesce(v_effective_policy->>'authority_mode','')='SOURCE_AUTHORITY';
      v_source_mode:=nullif(v_effective_policy->>'c1_source_mode','');
      if v_source_authority and (
           coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
           or v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
         ) then
        raise exception 'WEEKLY_SOURCE_C1_MODE_UNRESOLVED' using errcode='55000';
      end if;
      if not v_source_authority and v_source_mode is not null then
        raise exception 'WEEKLY_SOURCE_TIMESHEET_AUTHORITY_C1_MODE_FORBIDDEN' using errcode='55000';
      end if;
      if (v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1'))
           is distinct from (v_source_mode='NHSP_WEEKLY')
         and v_source_authority then
        raise exception 'WEEKLY_SOURCE_PROFILE_MODE_MISMATCH' using errcode='55000';
      end if;

      v_contract_settings_authority:=private._contract_settings_effective_core_v1(
        v_client_id,v_contract_id,v_source_row.work_date,'IMPORT',null
      );
      v_invoice_vat_chargeable:=coalesce(
        (v_contract_settings_authority#>>'{values,client_vat_chargeable}')::boolean,true
      );
      v_invoice_vat_rate_pct:=case when v_invoice_vat_chargeable then
        coalesce((v_contract_settings_authority#>>'{values,vat_rate_pct}')::numeric,20)
        else 0::numeric end;
      if v_invoice_vat_rate_pct<0 or v_invoice_vat_rate_pct>100 then
        raise exception 'WEEKLY_SOURCE_INVOICE_VAT_RATE_INVALID' using errcode='22023';
      end if;
      v_source_expense_vat_enabled:=coalesce(
        (v_effective_policy->>'source_expense_vat_enabled')::boolean,false
      );
      v_invoice_vat_policy_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_INVOICE_VAT_POLICY_V1',
        pg_catalog.jsonb_build_object(
          'client_id',v_client_id,'contract_id',v_contract_id,'work_date',v_source_row.work_date,
          'client_settings_id',v_contract_settings_authority->>'client_settings_id',
          'client_settings_effective_from',v_contract_settings_authority->>'client_settings_effective_from',
          'finance_settings_id',v_contract_settings_authority->>'finance_settings_id',
          'finance_settings_date_from',v_contract_settings_authority->>'finance_settings_date_from',
          'client_vat_chargeable',v_invoice_vat_chargeable,
          'vat_rate_pct',v_invoice_vat_rate_pct,
          'source_expense_vat_enabled',v_source_expense_vat_enabled,
          'settings_authority_fingerprint',v_contract_settings_authority->>'authority_fingerprint'
        )
      );

      -- G8-1/G8-2 (XSG-009).  `24 §14` and `25 §9`: a signed-Timesheet-authority
      -- row belongs to the established validation-only Mode A journey, never to
      -- source finalisation, and "merely labelling the row as Timesheet evidence
      -- is insufficient".  The unified upload owner therefore records the
      -- resolved Mode A authority as production data on the
      -- `weekly_timesheet_authority_resolutions` relation, which until now had
      -- no writer outside a verification fixture.
      -- `Reference required before pay` and `require_reference_to_invoice` come
      -- from the installed contract-settings authority and default to false;
      -- the auto-authorisation decision is taken from the established resolver
      -- `public.import_auto_authorise_policy_resolve_v2` in validation context,
      -- exactly as `public._import_review_auto_authorise_targets_core_v1` reads
      -- it, so no second policy engine is introduced.
      if not v_source_authority then
        if coalesce(v_effective_policy->>'document_mode','')<>'INVOICE_EVIDENCE_REQUIRED'
           or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) then
          raise exception 'WEEKLY_SOURCE_TIMESHEET_AUTHORITY_POLICY_INVALID' using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'document_mode',v_effective_policy->>'document_mode',
              'self_bill_enabled',v_effective_policy->>'self_bill_enabled'
            )::text;
        end if;
        v_mode_a_policy:=public.import_auto_authorise_policy_resolve_v2(
          case when v_profile.profile_code in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1')
            then 'NHSP'::public.hr_source_enum
            else 'HEALTHROSTER'::public.hr_source_enum end,
          v_client_id,v_contract_id,null,v_source_row.work_date,true
        );
        insert into public.weekly_timesheet_authority_resolutions(
          source_cycle_id,client_id,contract_id,work_date,authority_mode,document_mode,
          require_reference_to_pay,require_reference_to_invoice,auto_authorise_enabled,
          effective_policy_fingerprint
        ) values (
          v_cycle.id,v_client_id,v_contract_id,v_source_row.work_date,
          'TIMESHEET_AUTHORITY','INVOICE_EVIDENCE_REQUIRED',
          coalesce((v_contract_settings_authority#>>'{values,require_reference_to_pay}')::boolean,false),
          coalesce((v_contract_settings_authority#>>'{values,require_reference_to_invoice}')::boolean,false),
          coalesce((v_mode_a_policy->>'effective_value')::boolean,false),
          v_effective_policy_fingerprint
        ) on conflict (source_cycle_id,contract_id,work_date,effective_policy_fingerprint) do nothing;
      end if;

      v_has_worked_tuple:=v_source_row.start_at_local is not null
        and v_source_row.end_at_local is not null
        and v_source_row.break_minutes is not null
        and coalesce(v_source_row.actual_net_minutes,0)>0;

      v_identity_kind:=pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'identity_kind','')));
      if v_identity_kind not in ('PROFILE_EXTERNAL_KEY','SCHEDULE_TUPLE') then
        raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_INVALID' using errcode='22023';
      end if;
      if v_profile.profile_code in (
        'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
        'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1',
        'ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
      ) and v_identity_kind<>'PROFILE_EXTERNAL_KEY' then
        raise exception 'WEEKLY_SOURCE_PROFILE_EXTERNAL_EVENT_KEY_REQUIRED' using errcode='22023';
      end if;
      -- WP-58 / WP-50 finding F7, the mirror image of the guard above.
      -- Pack 24 section 1 supersedes "the NHSP Reference Number is the durable
      -- identity of the real shift", and 24 section 9 states the Reference
      -- Number is "not sole durable work identity": it, the ward and the
      -- location may all change during a correction. An NHSP shift is the same
      -- shift as another by the schedule tuple
      -- (private.weekly_source_work_event_schedule_compatible_v1), never by the
      -- reference. Reference-keyed identity on an NHSP row makes a reversal and
      -- its re-issue three separate work events for one corrected shift, which
      -- is what WP-50 executed. Until this guard existed, the only thing
      -- sending SCHEDULE_TUPLE for NHSP was one ternary in the broker
      -- (broker/src/weekly-source/upload-publication-owner.mjs), so the rule
      -- held on exactly one route. It is enforced here, where no caller can go
      -- round it.
      if v_profile.profile_code in (
        'NHSP_PREFINAL_RELEASED_V1',
        'NHSP_FINAL_BACKING_V1'
      ) and v_identity_kind<>'SCHEDULE_TUPLE' then
        raise exception 'WEEKLY_SOURCE_SCHEDULE_TUPLE_EVENT_KEY_REQUIRED' using errcode='22023';
      end if;
      v_profile_external_key:=case when v_identity_kind='PROFILE_EXTERNAL_KEY'
        then nullif(pg_catalog.btrim(coalesce(v_row_json->>'profile_external_key','')),'') end;
      if v_identity_kind='PROFILE_EXTERNAL_KEY'
         and (v_profile_external_key is null
              or v_profile_external_key is distinct from nullif(pg_catalog.btrim(v_source_row.external_source_key),'')) then
        raise exception 'WEEKLY_SOURCE_EXTERNAL_EVENT_KEY_REQUIRED' using errcode='22023';
      end if;

      if v_source_authority then
        v_protected_matches:=private.weekly_source_protected_match_candidates_v1(v_source_row.id,v_candidate_id,v_client_id);
        select choice.work_event_id,choice.separate_shift into v_protected_choice,v_protected_separate
          from private.weekly_source_office_row_choices choice
          where choice.upload_row_id=v_source_row.id and choice.candidate_id=v_candidate_id
            and choice.client_id=v_client_id and choice.contract_id=v_contract_id
          order by choice.id desc limit 1;
        if v_protected_choice is not null then
          if v_prior_work_event_id is distinct from v_protected_choice
            or not exists(select 1 from jsonb_array_elements(v_protected_matches) match
              where match->>'work_event_id'=v_protected_choice::text and match->>'contract_id'=v_contract_id::text) then
            raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_NOT_ELIGIBLE' using errcode='40001';
          end if;
        elsif not coalesce(v_protected_separate,false) then
          if exists(select 1 from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text and (match->>'retained_source_identity')::boolean) then
            select coalesce(jsonb_agg(match),'[]'::jsonb) into v_protected_matches
              from jsonb_array_elements(v_protected_matches) match
              where match->>'contract_id'=v_contract_id::text and (match->>'retained_source_identity')::boolean;
          elsif exists(select 1 from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text and (match->>'schedule_compatible')::boolean) then
            select coalesce(jsonb_agg(match),'[]'::jsonb) into v_protected_matches
              from jsonb_array_elements(v_protected_matches) match
              where match->>'contract_id'=v_contract_id::text and (match->>'schedule_compatible')::boolean;
          end if;
          select count(*) into v_protected_count from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text;
          if v_protected_count>0 and (v_protected_count<>1 or not exists(
            select 1 from jsonb_array_elements(v_protected_matches) match
            where match->>'contract_id'=v_contract_id::text
              and ((match->>'schedule_compatible')::boolean or (match->>'retained_source_identity')::boolean)
              and match->>'work_event_id'=v_prior_work_event_id::text)) then
            raise exception 'WEEKLY_SOURCE_PROTECTED_MATCH_REQUIRED' using errcode='55000';
          end if;
        end if;
      end if;
      if v_prior_work_event_id is not null then
        select * into strict v_work_event
        from public.weekly_work_events work_event
        where work_event.id=v_prior_work_event_id
          and work_event.candidate_id=v_candidate_id
          and work_event.client_id=v_client_id
          and work_event.first_source_group_id=v_group.id;
        if v_identity_kind='PROFILE_EXTERNAL_KEY'
           and exists(
             select 1
             from public.weekly_work_events other_event
             where other_event.first_source_group_id=v_group.id
               and other_event.source_format_profile_id=v_upload.source_format_profile_id
               and other_event.identity_kind='PROFILE_EXTERNAL_KEY'
               and other_event.profile_external_key=v_profile_external_key
               and other_event.id<>v_work_event.id
           ) then
          raise exception 'WEEKLY_SOURCE_PROFILE_EVENT_KEY_CONFLICT' using errcode='55000';
        end if;
        v_work_event_id:=v_work_event.id;
        v_work_event_match_kind:='EXACT_DURABLE_LINEAGE';
      else
        if v_identity_kind='PROFILE_EXTERNAL_KEY' then
          v_durable_identity_hash:=private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_WORK_EVENT_PROFILE_KEY_V1',
            pg_catalog.jsonb_build_object(
              'source_group_id',v_group.id,
              'source_format_profile_id',v_upload.source_format_profile_id,
              'profile_external_key',v_profile_external_key
            )
          );
        else
          -- WP-37 / `24 §9` step 2 and step 4.  The guarded set is read only
          -- after the family lock is held, so a concurrent publication cannot
          -- create a second root for the same work between this read and the
          -- insert below.
          perform pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(
              v_group.id::text||'|'||v_upload.source_format_profile_id::text||'|'
                ||v_candidate_id::text||'|'||v_client_id::text||'|'
                ||v_source_row.work_date::text,
              17092026
            )
          );
          select pg_catalog.count(*)::integer,
                 pg_catalog.min(work_event.id::text)::uuid
            into v_compatible_count,v_compatible_event_id
          from public.weekly_work_events work_event
          where work_event.first_source_group_id=v_group.id
            and work_event.source_format_profile_id=v_upload.source_format_profile_id
            and work_event.identity_kind='SCHEDULE_TUPLE'
            and work_event.candidate_id=v_candidate_id
            and work_event.client_id=v_client_id
            and work_event.work_date=v_source_row.work_date
            and private.weekly_source_work_event_schedule_compatible_v1(
                  work_event.id,v_source_row.start_at_local,v_source_row.end_at_local
                );
          if v_compatible_count>1 then
            -- `24 §9`: "Office confirmation when more than one plausible
            -- relationship remains.  It never guesses."  No root is chosen.
            raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_AMBIGUOUS' using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'source_row_ordinal',v_source_row.source_row_ordinal,
                'candidate_id',v_candidate_id,'client_id',v_client_id,
                'work_date',v_source_row.work_date,
                'compatible_work_event_count',v_compatible_count
              )::text;
          end if;
          -- The hash still carries this row's own schedule, so a genuinely
          -- different, non-overlapping shift on the same date gets its own
          -- durable identity.  It is a uniqueness token for a NEW root, not
          -- the identity rule: the rule is the compatible-schedule set above.
          v_durable_identity_hash:=private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_WORK_EVENT_SCHEDULE_TUPLE_V1',
            pg_catalog.jsonb_build_object(
              'source_group_id',v_group.id,'source_format_profile_id',v_upload.source_format_profile_id,
              'candidate_id',v_candidate_id,'client_id',v_client_id,'work_date',v_source_row.work_date,
              'start_at_local',v_source_row.start_at_local,'end_at_local',v_source_row.end_at_local
            )
          );
        end if;
        if v_identity_kind='SCHEDULE_TUPLE' and v_compatible_count=1 then
          select * into strict v_work_event
          from public.weekly_work_events work_event
          where work_event.id=v_compatible_event_id;
          v_work_event_was_present:=true;
        else
          select exists(
            select 1 from public.weekly_work_events work_event
            where work_event.durable_identity_hash=v_durable_identity_hash
          ) into v_work_event_was_present;
          insert into public.weekly_work_events(
            candidate_id,client_id,work_date,identity_kind,profile_external_key,
            durable_identity_hash,first_source_group_id,source_format_profile_id
          ) values (
            v_candidate_id,v_client_id,v_source_row.work_date,v_identity_kind,
            v_profile_external_key,v_durable_identity_hash,v_group.id,v_upload.source_format_profile_id
          ) on conflict (durable_identity_hash) do nothing;
          select * into strict v_work_event
          from public.weekly_work_events work_event
          where work_event.durable_identity_hash=v_durable_identity_hash;
        end if;
        if v_work_event.candidate_id is distinct from v_candidate_id
           or v_work_event.client_id is distinct from v_client_id
           or v_work_event.identity_kind is distinct from v_identity_kind
           or v_work_event.profile_external_key is distinct from v_profile_external_key
           or v_work_event.first_source_group_id is distinct from v_group.id
           or v_work_event.source_format_profile_id is distinct from v_upload.source_format_profile_id
           or (v_identity_kind='SCHEDULE_TUPLE' and v_work_event.work_date is distinct from v_source_row.work_date) then
          raise exception 'WEEKLY_SOURCE_WORK_EVENT_IDENTITY_COLLISION' using errcode='55000';
        end if;
        v_work_event_id:=v_work_event.id;
        v_work_event_match_kind:=case
          when v_identity_kind='PROFILE_EXTERNAL_KEY' and v_work_event_was_present then 'REUSED_PROFILE_KEY'
          when v_identity_kind='PROFILE_EXTERNAL_KEY' then 'NEW_PROFILE_KEY'
          when v_work_event_was_present then 'EXACT_DURABLE_LINEAGE'
          else 'NEW_SCHEDULE_TUPLE'
        end;
      end if;
      v_work_event_match_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_WORK_EVENT_MATCH_V1',
        pg_catalog.jsonb_build_object(
          'upload_row_id',v_source_row.id,'work_event_id',v_work_event_id,
          'match_kind',v_work_event_match_kind,'prior_work_event_id',v_prior_work_event_id,
          'source_row_fingerprint',pg_catalog.encode(v_source_row.normalised_row_hash,'hex')
        )
      );
    end if;

    -- Only a resolved, source-authoritative worked row owns a C1 economic
    -- snapshot.  Timesheet-authoritative validation rows, unfinished rows and
    -- explicit source-zero positions must never cross the pay boundary.
    if v_mapping_state='RESOLVED'
       and v_source_authority
       and v_source_row.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED') then
      if not v_has_worked_tuple then
        raise exception 'WEEKLY_SOURCE_WORKED_TUPLE_REQUIRED' using errcode='22023';
      end if;
      if pg_catalog.jsonb_typeof(v_economic)<>'object'
         or v_economic->>'schema_version' is distinct from 'WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1'
         or v_economic->>'calculator_version' is distinct from 'WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1'
         or pg_catalog.upper(coalesce(v_economic->>'source_mode','')) is distinct from v_source_mode
         or pg_catalog.upper(coalesce(v_economic->>'rate_method',''))
              is distinct from v_effective_policy->>'weekly_rate_classification_method'
         or pg_catalog.jsonb_typeof(v_economic->'bucket_minutes')<>'object'
         or pg_catalog.jsonb_typeof(v_economic->'hours')<>'object'
         or pg_catalog.jsonb_typeof(v_economic->'pay_rates')<>'object'
         or pg_catalog.jsonb_typeof(v_economic->'charge_rates')<>'object' then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_SNAPSHOT_INVALID' using errcode='22023';
      end if;

      -- A structurally valid NHSP £0 line is still a worked row.  Source money
      -- decides whether a physical row is a reversal only when it is negative;
      -- zero therefore keeps the positive worked-time/pay sign while the
      -- invoice movement retains the exact £0 source value.
      v_row_sign:=case when v_source_mode='NHSP_WEEKLY' then
        case when coalesce(v_source_row.source_shift_charge_pence,0)<0 then -1 else 1 end
        else 1 end;
      if v_row_sign not in (-1,1)
         or coalesce(v_economic->>'sign','')!~'^[-]?[0-9]+

         or (v_economic->>'sign')::smallint is distinct from v_row_sign
         or coalesce(v_economic->>'paid_minutes','')!~'^[0-9]+

         or (v_economic->>'paid_minutes')::integer is distinct from v_source_row.actual_net_minutes
         or coalesce(v_economic->>'break_minutes','')!~'^[0-9]+

         or (v_economic->>'break_minutes')::integer is distinct from v_source_row.break_minutes then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_SOURCE_TUPLE_MISMATCH' using errcode='22023';
      end if;

      if exists(
        select 1
        from (values ('day'),('night'),('sat'),('sun'),('bh')) bucket(name)
        where coalesce(v_economic#>>array['bucket_minutes',bucket.name],'')!~'^[0-9]+

           or coalesce(v_economic#>>array['hours',bucket.name],'')!~'^[+-]?[0-9]+([.][0-9]+)?

           or coalesce(v_economic#>>array['pay_rates',bucket.name],'')!~'^[+]?[0-9]+([.][0-9]+)?

           or coalesce(v_economic#>>array['charge_rates',bucket.name],'')!~'^[+]?[0-9]+([.][0-9]+)?

           or (v_economic#>>array['pay_rates',bucket.name])::numeric<=0
           or (v_economic#>>array['charge_rates',bucket.name])::numeric<=0
      ) then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_BUCKET_INVALID' using errcode='22023';
      end if;
      if (
        (v_economic#>>'{bucket_minutes,day}')::integer+
        (v_economic#>>'{bucket_minutes,night}')::integer+
        (v_economic#>>'{bucket_minutes,sat}')::integer+
        (v_economic#>>'{bucket_minutes,sun}')::integer+
        (v_economic#>>'{bucket_minutes,bh}')::integer
      ) is distinct from v_source_row.actual_net_minutes then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_MINUTES_MISMATCH' using errcode='22023';
      end if;
      if exists(
        select 1
        from (values ('day'),('night'),('sat'),('sun'),('bh')) bucket(name)
        where (v_economic#>>array['hours',bucket.name])::numeric is distinct from
          pg_catalog.round(
            ((v_economic#>>array['bucket_minutes',bucket.name])::numeric/60)*v_row_sign,2
          )
      ) then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_HOURS_MISMATCH' using errcode='22023';
      end if;
      if coalesce(v_economic->>'total_pay_pence','')!~'^[-]?[0-9]+

         or coalesce(v_economic->>'calculated_charge_pence','')!~'^[-]?[0-9]+
 then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_TOTAL_INVALID' using errcode='22023';
      end if;

      v_expected_pay_pence:=(pg_catalog.round(
        pg_catalog.round(
          pg_catalog.abs((v_economic#>>'{hours,day}')::numeric)*(v_economic#>>'{pay_rates,day}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,night}')::numeric)*(v_economic#>>'{pay_rates,night}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sat}')::numeric)*(v_economic#>>'{pay_rates,sat}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sun}')::numeric)*(v_economic#>>'{pay_rates,sun}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,bh}')::numeric)*(v_economic#>>'{pay_rates,bh}')::numeric,2
        )*100,0
      )::bigint)*v_row_sign;
      v_expected_charge_pence:=(pg_catalog.round(
        pg_catalog.round(
          pg_catalog.abs((v_economic#>>'{hours,day}')::numeric)*(v_economic#>>'{charge_rates,day}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,night}')::numeric)*(v_economic#>>'{charge_rates,night}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sat}')::numeric)*(v_economic#>>'{charge_rates,sat}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,sun}')::numeric)*(v_economic#>>'{charge_rates,sun}')::numeric+
          pg_catalog.abs((v_economic#>>'{hours,bh}')::numeric)*(v_economic#>>'{charge_rates,bh}')::numeric,2
        )*100,0
      )::bigint)*v_row_sign;
      if (v_economic->>'total_pay_pence')::bigint is distinct from v_expected_pay_pence
         or (v_economic->>'calculated_charge_pence')::bigint is distinct from v_expected_charge_pence then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_TOTAL_MISMATCH' using errcode='22023';
      end if;

      v_contract_rate_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_CONTRACT_RATE_AUTHORITY_V1',
        pg_catalog.jsonb_build_object(
          'contract_id',v_contract.id,'contract_updated_at',v_contract.updated_at,
          'rates_json',v_contract.rates_json,'additional_rates_json',v_contract.additional_rates_json,
          'rate_method',v_effective_policy->>'weekly_rate_classification_method',
          'duration_break_tie_rule',v_effective_policy->>'duration_break_tie_rule',
          'canonical_pay_rates',v_economic->'pay_rates',
          'canonical_charge_rates',v_economic->'charge_rates',
          'settings_authority_fingerprint',v_contract_settings_authority->>'authority_fingerprint'
        )
      );
      v_canonical_economic:=pg_catalog.jsonb_build_object(
        'schema_version','WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1',
        'calculator_version','WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1',
        'source_mode',v_source_mode,
        'rate_method',v_effective_policy->>'weekly_rate_classification_method',
        'sign',v_row_sign,
        'paid_minutes',v_source_row.actual_net_minutes,
        'break_minutes',v_source_row.break_minutes,
        'bucket_minutes',v_economic->'bucket_minutes',
        'hours',v_economic->'hours',
        'pay_rates',v_economic->'pay_rates',
        'charge_rates',v_economic->'charge_rates',
        'total_pay_pence',v_expected_pay_pence::text,
        'calculated_charge_pence',v_expected_charge_pence::text,
        'invoice_vat_chargeable',v_invoice_vat_chargeable,
        'invoice_vat_rate_pct',v_invoice_vat_rate_pct,
        'source_expense_vat_enabled',v_source_expense_vat_enabled,
        'contract_and_rate_fingerprint',pg_catalog.encode(v_contract_rate_fingerprint,'hex'),
        'effective_policy_fingerprint',pg_catalog.encode(v_effective_policy_fingerprint,'hex'),
        'invoice_vat_policy_fingerprint',pg_catalog.encode(v_invoice_vat_policy_fingerprint,'hex'),
        'break_allocation',v_economic->'break_allocation'
      );
      v_calculation_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1',v_canonical_economic
      );
    else
      if pg_catalog.jsonb_typeof(v_economic)='object' then
        raise exception 'WEEKLY_SOURCE_ECONOMIC_SNAPSHOT_NOT_APPLICABLE' using errcode='22023';
      end if;
      if v_mapping_state='RESOLVED' and v_source_authority
         and v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO'
         and coalesce(v_source_row.actual_net_minutes,-1)<>0 then
        raise exception 'WEEKLY_SOURCE_SOURCE_ZERO_INVALID' using errcode='22023';
      end if;
    end if;

    if v_mapping_state='RESOLVED' then
      v_link_kind:=case
        when not v_source_authority then 'TIMESHEET_EVIDENCE'
        when v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
          or v_source_row.row_finalisation_state='SOURCE_UNFINALISED' then 'PROVISIONAL_SOURCE'
        when v_source_row.row_finalisation_state='SOURCE_ABSENT_ZERO' then 'ZERO_SOURCE'
        when v_source_mode='NHSP_WEEKLY' and v_row_sign=-1 then 'FULL_NEGATIVE_SOURCE'
        else 'POSITIVE_SOURCE'
      end;
      if nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(v_row_json->>'link_kind',''))),'')
           is distinct from v_link_kind then
        raise exception 'WEEKLY_SOURCE_LINK_KIND_MISMATCH' using errcode='22023';
      end if;
    elsif nullif(pg_catalog.btrim(coalesce(v_row_json->>'link_kind','')),'') is not null then
      raise exception 'WEEKLY_SOURCE_LINK_NOT_APPLICABLE' using errcode='22023';
    end if;

    insert into public.weekly_source_row_resolutions(
      upload_row_id,generation,candidate_id,client_id,contract_id,work_event_id,
      paid_minutes,rate_classifications_json,mapping_state,blocker_code,
      contract_selection_method,work_event_match_kind,work_event_match_fingerprint,
      qualification_profile_fingerprint,
      qualifying_contract_count,qualifying_contract_set_hash,source_row_fingerprint,
      contract_and_rate_fingerprint,effective_policy_fingerprint
    ) values (
      v_source_row.id,v_generation,v_candidate_id,v_client_id,v_contract_id,v_work_event_id,
      v_source_row.actual_net_minutes,v_canonical_economic,
      v_mapping_state,nullif(v_row_json->>'blocker_code',''),v_selection_method,
      v_work_event_match_kind,v_work_event_match_fingerprint,
      private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_QUALIFICATION_PROFILE_V1',
        pg_catalog.jsonb_build_object(
          'upload_row_id',v_source_row.id,'generation',v_generation,
          'qualifying_contract_ids',v_eligible_ids,'mapping_state',v_mapping_state
        )
      ),
      pg_catalog.jsonb_array_length(v_eligible_ids),v_eligible_hash,
      v_source_row.normalised_row_hash,
      case when v_mapping_state='RESOLVED' then coalesce(
        v_contract_rate_fingerprint,
        private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_NON_ECONOMIC_CONTRACT_AUTHORITY_V1',
          pg_catalog.jsonb_build_object(
            'contract_id',v_contract.id,'contract_updated_at',v_contract.updated_at,
            'rates_json',v_contract.rates_json,'additional_rates_json',v_contract.additional_rates_json,
            'source_row_state',v_source_row.row_finalisation_state
          )
        )
      ) end,
      case when v_mapping_state='RESOLVED' then v_effective_policy_fingerprint end
    ) returning id into v_resolution_id;

    if v_canonical_economic is not null then
      insert into public.weekly_source_row_economic_snapshots(
        row_resolution_id,upload_row_id,generation,work_event_id,
        candidate_id,client_id,contract_id,calculator_version,source_mode,rate_method,row_sign,
        paid_minutes,break_minutes,minutes_day,minutes_night,minutes_sat,minutes_sun,minutes_bh,
        hours_day,hours_night,hours_sat,hours_sun,hours_bh,
        pay_day,pay_night,pay_sat,pay_sun,pay_bh,
        charge_day,charge_night,charge_sat,charge_sun,charge_bh,
        total_pay_pence,calculated_charge_pence,
        invoice_vat_chargeable,invoice_vat_rate_pct,source_expense_vat_enabled,
        canonical_result_json,contract_and_rate_fingerprint,effective_policy_fingerprint,
        invoice_vat_policy_fingerprint,calculation_fingerprint
      ) values (
        v_resolution_id,v_source_row.id,v_generation,v_work_event_id,
        v_candidate_id,v_client_id,v_contract_id,'WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1',
        v_source_mode,v_effective_policy->>'weekly_rate_classification_method',v_row_sign,
        v_source_row.actual_net_minutes,v_source_row.break_minutes,
        (v_economic#>>'{bucket_minutes,day}')::integer,
        (v_economic#>>'{bucket_minutes,night}')::integer,
        (v_economic#>>'{bucket_minutes,sat}')::integer,
        (v_economic#>>'{bucket_minutes,sun}')::integer,
        (v_economic#>>'{bucket_minutes,bh}')::integer,
        (v_economic#>>'{hours,day}')::numeric,
        (v_economic#>>'{hours,night}')::numeric,
        (v_economic#>>'{hours,sat}')::numeric,
        (v_economic#>>'{hours,sun}')::numeric,
        (v_economic#>>'{hours,bh}')::numeric,
        (v_economic#>>'{pay_rates,day}')::numeric,
        (v_economic#>>'{pay_rates,night}')::numeric,
        (v_economic#>>'{pay_rates,sat}')::numeric,
        (v_economic#>>'{pay_rates,sun}')::numeric,
        (v_economic#>>'{pay_rates,bh}')::numeric,
        (v_economic#>>'{charge_rates,day}')::numeric,
        (v_economic#>>'{charge_rates,night}')::numeric,
        (v_economic#>>'{charge_rates,sat}')::numeric,
        (v_economic#>>'{charge_rates,sun}')::numeric,
        (v_economic#>>'{charge_rates,bh}')::numeric,
        v_expected_pay_pence,v_expected_charge_pence,
        v_invoice_vat_chargeable,v_invoice_vat_rate_pct,v_source_expense_vat_enabled,
        v_canonical_economic,v_contract_rate_fingerprint,v_effective_policy_fingerprint,
        v_invoice_vat_policy_fingerprint,v_calculation_fingerprint
      );
    end if;

    if v_mapping_state='RESOLVED'
       and v_source_authority
       and v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1'
       and coalesce((v_effective_policy->>'source_fixed_expenses_enabled')::boolean,false) then
      if v_source_row.source_expense_pence is null
         or v_source_row.source_expense_parse_state not in ('VALID','OMITTED_ZERO')
         or (v_source_row.source_expense_parse_state='OMITTED_ZERO'
             and v_source_row.source_expense_pence<>0) then
        raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_INPUT_INVALID'
          using errcode='22023';
      end if;
      if v_source_row.source_expense_pence>0 and (
           v_source_row.start_at_local is null or v_source_row.end_at_local is null
           or v_source_row.end_at_local<=v_source_row.start_at_local
           or v_source_row.break_minutes is null
         ) then
        raise exception 'WEEKLY_SOURCE_EXPENSE_DISPLAY_TUPLE_REQUIRED'
          using errcode='22023';
      end if;
      v_expense_policy_snapshot_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_ROW_EXPENSE_POLICY_SNAPSHOT_V1',
        pg_catalog.jsonb_build_object(
          'row_resolution_id',v_resolution_id,'upload_row_id',v_source_row.id,
          'generation',v_generation,'work_event_id',v_work_event_id,
          'candidate_id',v_candidate_id,'client_id',v_client_id,
          'contract_id',v_contract_id,'row_finalisation_state',v_source_row.row_finalisation_state,
          'source_expense_pence',v_source_row.source_expense_pence,
          'source_expense_parse_state',v_source_row.source_expense_parse_state,
          'source_expense_vat_enabled',v_source_expense_vat_enabled,
          'invoice_vat_chargeable',v_invoice_vat_chargeable,
          'invoice_vat_rate_pct',v_invoice_vat_rate_pct,
          'correction_presentation',v_effective_policy->>'self_bill_correction_presentation',
          'effective_policy_fingerprint',pg_catalog.encode(v_effective_policy_fingerprint,'hex'),
          'invoice_vat_policy_fingerprint',pg_catalog.encode(v_invoice_vat_policy_fingerprint,'hex')
        )
      );
      insert into public.weekly_source_row_expense_policy_snapshots(
        row_resolution_id,upload_row_id,generation,work_event_id,
        candidate_id,client_id,contract_id,source_expense_pence,
        source_expense_parse_state,source_expense_vat_enabled,
        invoice_vat_chargeable,invoice_vat_rate_pct,correction_presentation,effective_policy_fingerprint,
        invoice_vat_policy_fingerprint,snapshot_hash
      ) values (
        v_resolution_id,v_source_row.id,v_generation,v_work_event_id,
        v_candidate_id,v_client_id,v_contract_id,v_source_row.source_expense_pence,
        v_source_row.source_expense_parse_state,v_source_expense_vat_enabled,
        v_invoice_vat_chargeable,v_invoice_vat_rate_pct,
        v_effective_policy->>'self_bill_correction_presentation',v_effective_policy_fingerprint,
        v_invoice_vat_policy_fingerprint,v_expense_policy_snapshot_hash
      );
    end if;

    if v_mapping_state='RESOLVED' then
      insert into public.weekly_work_event_source_links(
        work_event_id,upload_row_id,row_resolution_id,link_kind,link_hash
      ) values (
        v_work_event_id,v_source_row.id,v_resolution_id,
        v_link_kind,
        private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_WORK_EVENT_LINK_V1',
          pg_catalog.jsonb_build_object(
            'work_event_id',v_work_event_id,'upload_row_id',v_source_row.id,
            'resolution_id',v_resolution_id,'link_kind',v_link_kind
          )
        )
      );
    end if;

    for v_qualification in
      select value from pg_catalog.jsonb_array_elements(coalesce(v_row_json->'qualification_observations','[]'::jsonb))
    loop
      if v_profile.profile_code not in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1') then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_PROFILE_NOT_APPLICABLE' using errcode='22023';
      end if;
      v_result:=pg_catalog.upper(coalesce(v_qualification->>'comparison_result',''));
      -- G6-2/G6-4: a per-Contract qualification verdict is re-derived here
      -- from the immutable source pence and the caller's canonical pence for
      -- that Contract, using the same symmetric NHSP_TWO_COMPONENT_PENCE_V1
      -- rule (25 §6; 24 §8, §13; 14 §4.3 items 1 and 5; NHSP-BR-013). The
      -- eligible set that the selection method is proved against is therefore
      -- the set the server itself would admit. UNVERIFIABLE stays available
      -- as the fail-closed verdict and is never upgraded.
      v_charge_source_pence:=nullif(v_qualification->>'source_shift_charge_pence','')::bigint;
      v_charge_calculated_pence:=nullif(v_qualification->>'canonical_calculated_pence','')::bigint;
      if v_charge_source_pence is distinct from v_source_row.source_shift_charge_pence then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_SOURCE_PENCE_MISMATCH' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'contract_id',v_qualification->>'contract_id'
          )::text;
      end if;
      v_charge_difference_pence:=case
        when v_charge_source_pence is null or v_charge_calculated_pence is null then null
        else v_charge_source_pence-v_charge_calculated_pence end;
      v_charge_expected_result:=case
        when v_charge_source_pence is null or v_charge_calculated_pence is null then 'UNVERIFIABLE'
        when v_charge_source_pence=0 and v_charge_calculated_pence<>0 then 'ZERO_SOURCE_CHARGE'
        when v_charge_calculated_pence=0 then 'MISMATCH'
        when v_charge_difference_pence=0 then 'EXACT'
        when (v_charge_difference_pence=1 or v_charge_difference_pence=-1)
          and ((v_charge_source_pence>0 and v_charge_calculated_pence>0)
            or (v_charge_source_pence<0 and v_charge_calculated_pence<0))
          then 'SOURCE_ROUNDING_EQUIVALENT'
        else 'MISMATCH' end;
      if v_result<>'UNVERIFIABLE' and v_result is distinct from v_charge_expected_result then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_RESULT_NOT_REDERIVED' using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'source_row_ordinal',v_source_row.source_row_ordinal,
            'contract_id',v_qualification->>'contract_id',
            'claimed_result',v_result,'rederived_result',v_charge_expected_result,
            'signed_difference_pence',v_charge_difference_pence
          )::text;
      end if;
      -- Price does not decide Contract identity. Every safe canonical
      -- observation remains in the reliable base set; warning admission is a
      -- separate Office decision after Contract resolution.
      v_passed:=v_result in ('EXACT','SOURCE_ROUNDING_EQUIVALENT','MISMATCH','ZERO_SOURCE_CHARGE');
      perform 1
      from public.contracts contract
      where contract.id=(v_qualification->>'contract_id')::uuid
        and contract.candidate_id=v_candidate_id
        and contract.client_id=v_client_id
        and v_source_row.work_date between contract.start_date and coalesce(contract.end_date,'infinity'::date)
        and v_eligible_ids ? contract.id::text;
      if not found then
        raise exception 'WEEKLY_SOURCE_QUALIFICATION_CONTRACT_OUT_OF_SCOPE' using errcode='22023';
      end if;
      insert into public.weekly_source_contract_qualification_observations(
        upload_row_id,generation,candidate_id,client_id,contract_id,
        source_format_profile_id,qualification_profile_version,
        qualification_profile_fingerprint,contract_revision_fingerprint,
        source_shift_charge_pence,canonical_calculated_pence,
        source_charge_difference_pence,comparison_result,qualification_passed,
        ordered_reason_codes,evidence_fingerprint
      ) values (
        v_source_row.id,v_generation,v_candidate_id,v_client_id,
        (v_qualification->>'contract_id')::uuid,v_upload.source_format_profile_id,
        'NHSP_TWO_COMPONENT_PENCE_V1',
        private.weekly_source_sha256_jsonb_v1('NHSP_QUALIFICATION_PROFILE_V1',v_qualification),
        private.weekly_source_projection_hex32_v1(
          v_qualification->>'contract_revision_fingerprint','WEEKLY_SOURCE_CONTRACT_REVISION_FINGERPRINT_INVALID'
        ),
        v_charge_source_pence,
        v_charge_calculated_pence,
        v_charge_difference_pence,
        v_result,v_passed,
        coalesce(array(select pg_catalog.jsonb_array_elements_text(v_qualification->'reason_codes')),'{}'::text[]),
        private.weekly_source_sha256_jsonb_v1('NHSP_CONTRACT_QUALIFICATION_EVIDENCE_V1',v_qualification)
      );
    end loop;

    v_charge:=v_row_json->'charge_check';
    if v_source_amount and v_calculation_fingerprint is not null and jsonb_typeof(v_charge) is distinct from 'object' then
      raise exception 'WEEKLY_SOURCE_INVOICE_SOURCE_PRICE_MISSING' using errcode='55000'; end if;
    if v_charge is not null and pg_catalog.jsonb_typeof(v_charge)='object' then
      if (v_profile.profile_code not in ('NHSP_PREFINAL_RELEASED_V1','NHSP_FINAL_BACKING_V1') and not coalesce(v_source_amount,false))
         or v_mapping_state<>'RESOLVED' then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_NOT_APPLICABLE' using errcode='22023';
      end if;
      if v_calculation_fingerprint is null then
        raise exception 'WEEKLY_SOURCE_CHARGE_FINGERPRINT_MISSING' using errcode='55000';
      end if;
      if nullif(v_charge->>'charge_calculation_fingerprint','') is not null
         and private.weekly_source_projection_hex32_v1(
               v_charge->>'charge_calculation_fingerprint',
               'WEEKLY_SOURCE_CHARGE_FINGERPRINT_INVALID'
             ) is distinct from v_calculation_fingerprint then
        raise exception 'WEEKLY_SOURCE_CHARGE_FINGERPRINT_MISMATCH' using errcode='22023';
      end if;
      if nullif(v_charge->>'source_commission_pence','')::bigint
            is distinct from v_source_row.source_commission_pence
         or nullif(v_charge->>'source_total_cost_pence','')::bigint
            is distinct from v_source_row.source_total_cost_pence
         or nullif(v_charge->>'source_shift_charge_pence','')::bigint
            is distinct from v_source_row.source_shift_charge_pence
         or nullif(v_charge->>'calculated_segment_charge_pence','')::bigint
            is distinct from v_expected_charge_pence then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_ECONOMIC_MISMATCH' using errcode='22023';
      end if;
      -- G6-2: server-side re-derivation of the NHSP_TWO_COMPONENT_PENCE_V1
      -- verdict. Authority: 25 §6; 24 §13; 14 §4.3 items 1 and 5;
      -- NHSP-BR-013; PRC-006, PRC-007, PRC-020, NHSBR-019, NHSBR-020.
      -- The four inputs are already anchored above to the immutable upload
      -- row and to this server's own canonical calculation, so the verdict
      -- is recomputed here from those facts. A caller may never upgrade a
      -- verdict: anything other than the fail-closed UNVERIFIABLE must equal
      -- the re-derived result, and the sign kind must equal the re-derived
      -- sign kind. EXACT is a zero difference. SOURCE_ROUNDING_EQUIVALENT is
      -- the same non-zero sign on the source and calculated pence with an
      -- absolute difference of exactly one penny in either arithmetic
      -- direction; no directional constraint is permitted.
      v_charge_source_pence:=v_source_row.source_shift_charge_pence;
      v_charge_calculated_pence:=v_expected_charge_pence;
      v_charge_difference_pence:=case
        when v_charge_source_pence is null or v_charge_calculated_pence is null then null
        else v_charge_source_pence-v_charge_calculated_pence end;
      v_charge_expected_sign_kind:=case
        when v_charge_source_pence is null then null
        when v_charge_source_pence>0 then 'POSITIVE'
        when v_charge_source_pence<0 then 'FULL_NEGATIVE'
        when v_charge_calculated_pence>0 then 'POSITIVE'
        when v_charge_calculated_pence<0 then 'FULL_NEGATIVE' end;
      if v_source_amount then
        if v_source_row.source_money_parse_state<>'VALID' or v_charge_source_pence is null or v_charge_source_pence<0 or v_charge_calculated_pence is null or v_charge_calculated_pence<=0 then
          raise exception 'WEEKLY_SOURCE_INVOICE_SOURCE_PRICE_INVALID' using errcode='55000'; end if;
        v_charge_expected_result:=case when v_charge_difference_pence=0 then 'EXACT' when abs(v_charge_difference_pence)=1 then 'SOURCE_ROUNDING_EQUIVALENT' else 'SOURCE_AMOUNT_DIFFERS' end;
        v_charge_expected_sign_kind:='POSITIVE';
      else
      v_charge_expected_result:=case
        when v_source_row.source_commission_pence is null
          or v_source_row.source_total_cost_pence is null
          or v_charge_source_pence is null
          or v_charge_calculated_pence is null then 'UNVERIFIABLE'
        when v_charge_source_pence=0 and v_charge_calculated_pence<>0 then 'ZERO_SOURCE_CHARGE'
        when v_charge_calculated_pence=0 then 'MISMATCH'
        when v_charge_difference_pence=0 then 'EXACT'
        when (v_charge_difference_pence=1 or v_charge_difference_pence=-1)
          and ((v_charge_source_pence>0 and v_charge_calculated_pence>0)
            or (v_charge_source_pence<0 and v_charge_calculated_pence<0))
          then 'SOURCE_ROUNDING_EQUIVALENT'
        else 'MISMATCH' end;
      end if;
      v_charge_claimed_result:=pg_catalog.upper(pg_catalog.btrim(
        coalesce(v_charge->>'comparison_result','')));
      v_charge_row_sign_kind:=pg_catalog.upper(pg_catalog.btrim(
        coalesce(v_charge->>'row_sign_kind','')));
      if (v_source_amount or v_charge_claimed_result<>'UNVERIFIABLE')
         and v_charge_claimed_result is distinct from v_charge_expected_result then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_RESULT_NOT_REDERIVED'
          using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'claimed_result',v_charge_claimed_result,
              'rederived_result',v_charge_expected_result,
              'signed_difference_pence',v_charge_difference_pence
            )::text;
      end if;
      if v_charge_claimed_result<>'UNVERIFIABLE'
         and v_charge_row_sign_kind is distinct from v_charge_expected_sign_kind then
        raise exception 'WEEKLY_SOURCE_CHARGE_CHECK_SIGN_NOT_REDERIVED'
          using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'source_row_ordinal',v_source_row.source_row_ordinal,
              'claimed_row_sign_kind',v_charge_row_sign_kind,
              'rederived_row_sign_kind',v_charge_expected_sign_kind
            )::text;
      end if;
      insert into public.weekly_source_charge_checks(
        upload_row_id,row_resolution_id,generation,row_sign_kind,
        source_commission_pence,source_total_cost_pence,source_shift_charge_pence,
        calculated_segment_charge_pence,source_charge_difference_pence,
        comparison_profile_version,comparison_result,comparison_reason_code,
        phase_severity,blocker_code,charge_calculation_fingerprint
      ) values (
        v_source_row.id,v_resolution_id,v_generation,
        coalesce(v_charge_expected_sign_kind,v_charge_row_sign_kind),
        v_source_row.source_commission_pence,
        v_source_row.source_total_cost_pence,
        v_charge_source_pence,
        v_charge_calculated_pence,
        v_charge_difference_pence,
        case when v_source_amount then 'SOURCE_INVOICE_MONEY_PENCE_V1' else 'NHSP_TWO_COMPONENT_PENCE_V1' end,v_charge_claimed_result,
        coalesce(v_charge->>'comparison_reason_code',''),pg_catalog.upper(v_charge->>'phase_severity'),
        nullif(v_charge->>'blocker_code',''),
        v_calculation_fingerprint
      );
    end if;

    v_applied:=v_applied+1;
  end loop;

  if v_applied<>v_expected or exists(
    select 1 from public.weekly_source_upload_rows source_row
    where source_row.upload_id=v_upload.id
      and not exists(
        select 1 from public.weekly_source_row_resolutions resolution
        where resolution.upload_row_id=source_row.id and resolution.generation=v_generation
      )
  ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_RESOLUTION_CENSUS_INCOMPLETE' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'publication_id',v_publication.id,'upload_id',v_upload.id,
    'authority_scope_version',v_publication.authority_scope_version,
    'generation',v_generation,'applied_row_count',v_applied
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'WEEKLY_SOURCE_PROJECTION_VALUE_INVALID' using errcode='22023';
end;
$function$;

-- Complete native successor; bounded report arm only. Root composes later shared owner hunks.
create or replace function public.weekly_source_projection_publish_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_publication_id uuid;
  v_expected_comparison bytea;
  v_expected_issue bytea;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_scope_version bigint;
  v_scope_upload uuid;
  v_client_id uuid;
  v_comparison_hash bytea;
  v_issue_hash bytea;
  v_fingerprint bytea;
  v_resolution_count integer;
  v_generation integer;
  v_ready_session_version bigint;
begin
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(
       select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in ('actor_user_id','publication_id',
         'expected_comparison_manifest_hash','expected_issue_set_hash')
     ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_PUBLISH_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_publication_id:=(p_request->>'publication_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_PROJECTION_PUBLISH_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_publication_id is null then
    raise exception 'WEEKLY_SOURCE_PROJECTION_PUBLISH_REQUEST_INVALID' using errcode='22023';
  end if;
  v_expected_comparison:=case
    when nullif(p_request->>'expected_comparison_manifest_hash','') is null then null
    else private.weekly_source_hex32_v1(
      p_request->>'expected_comparison_manifest_hash',
      'WEEKLY_SOURCE_COMPARISON_MANIFEST_HASH_INVALID'
    ) end;
  v_expected_issue:=case
    when nullif(p_request->>'expected_issue_set_hash','') is null then null
    else private.weekly_source_hex32_v1(
      p_request->>'expected_issue_set_hash','WEEKLY_SOURCE_ISSUE_SET_HASH_INVALID'
    ) end;

  select * into v_publication
  from public.weekly_source_projection_publications
  where id=v_publication_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_upload
  from public.weekly_source_uploads where id=v_publication.upload_id;
  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_publication.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  if v_publication.authority_scope_kind='CYCLE' then
    v_scope_version:=v_cycle.version;
    v_scope_upload:=v_cycle.current_complete_upload_id;
    begin
      v_client_id:=nullif(v_upload.file_metadata_json->>'client_id','')::uuid;
    exception when invalid_text_representation then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_INVALID' using errcode='55000';
    end;
  else
    select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id;
    v_scope_version:=v_scope.version;
    v_scope_upload:=v_scope.current_complete_upload_id;
    v_client_id:=v_scope.client_id;
  end if;
  perform private.weekly_source_pay_query_admit_v2();
  if v_publication.authority_scope_kind='SELF_BILL_REPORT_SCOPE' then
    perform 1 from public.weekly_source_groups where id=v_group.id for update;
    perform 1 from public.weekly_source_cycles where id=v_cycle.id for update;
    perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(pg_catalog.encode(v_upload.declared_scope_fingerprint,'hex'),73241837)
  );
  if v_publication.authority_scope_kind='CYCLE' then
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_publication.source_cycle_id for update;
    v_scope_version:=v_cycle.version;
    v_scope_upload:=v_cycle.current_complete_upload_id;
  else
    -- Each NHSP Trust publishes independently under its report-scope head.
    select * into strict v_cycle
    from public.weekly_source_cycles where id=v_publication.source_cycle_id;
    select * into strict v_scope
    from public.weekly_source_report_scopes
    where id=v_publication.report_scope_id for update;
    if v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000';
    end if;
    v_scope_version:=v_scope.version;
    v_scope_upload:=v_scope.current_complete_upload_id;
    v_client_id:=v_scope.client_id;
  end if;
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=v_publication_id for update;
  select * into strict v_upload
  from public.weekly_source_uploads where id=v_publication.upload_id;
  if private.weekly_source_scope_fingerprint_v1(
       v_group.environment,v_group.agency_id,v_group.id,v_cycle.id,
       v_publication.report_scope_id,v_client_id
     ) is distinct from v_upload.declared_scope_fingerprint then
    raise exception 'WEEKLY_SOURCE_PROJECTION_SCOPE_CHANGED' using errcode='55000';
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'RECHECK_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  if v_publication.correction_session_id is not null then
    select * into v_correction
    from public.weekly_final_source_correction_sessions
    where id=v_publication.correction_session_id for update;
    if not found
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_publication.authority_scope_kind
       or v_correction.report_scope_id is distinct from v_publication.report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.actor_user_id is distinct from v_actor
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.state<>'CORRECTION_READY'
       or v_scope_version<>v_publication.authority_scope_version
       or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
            is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
    end if;
    if v_publication.state='CORRECTION_READY' then
      if v_correction.replacement_projection_publication_id is distinct from v_publication.id
         or (v_publication.rebuild_idempotency_key is not null
             and v_publication.ready_session_version is null) then
        raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
      end if;
      if (v_expected_comparison is not null
            and v_expected_comparison<>v_publication.comparison_manifest_hash)
         or (v_expected_issue is not null
            and v_expected_issue<>v_publication.issue_set_hash) then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_HASH_MISMATCH' using errcode='40001';
      end if;
      v_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_PUBLICATION_FINGERPRINT_V1',
        pg_catalog.jsonb_build_object(
          'publication_id',v_publication.id,'upload_id',v_publication.upload_id,
          'authority_scope_version',v_publication.authority_scope_version,
          'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
          'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex')
        )
      );
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','CORRECTION_READY','publication_id',v_publication.id,
        'upload_id',v_publication.upload_id,
        'authority_scope_version',v_publication.authority_scope_version,
        'projection_generation',v_publication.projection_generation,
        'ready_session_version',v_publication.ready_session_version,
        'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
        'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex'),
        'publication_fingerprint',pg_catalog.encode(v_fingerprint,'hex'),'idempotent',true
      );
    end if;
    if (v_publication.rebuild_idempotency_key is null and (
         v_correction.state<>'READY'
         or v_correction.replacement_projection_publication_id is not null
       ))
       or (v_publication.rebuild_idempotency_key is not null and (
         v_publication.projection_generation is null
         or v_publication.ready_session_version is null
         or v_correction.state<>'REVIEWED'
         or v_correction.version<>v_publication.ready_session_version
         or v_correction.replacement_projection_publication_id is null
         or v_correction.replacement_projection_publication_id=v_publication.id
       )) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_STALE' using errcode='40001';
    end if;
  end if;
  if v_publication.state='CURRENT'
      and v_publication.correction_session_id is null
      and v_scope_upload=v_publication.upload_id
      and v_scope_version=v_publication.authority_scope_version then
    if (v_expected_comparison is not null
          and v_expected_comparison<>v_publication.comparison_manifest_hash)
       or (v_expected_issue is not null
          and v_expected_issue<>v_publication.issue_set_hash) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_HASH_MISMATCH' using errcode='40001';
    end if;
    v_fingerprint:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_PUBLICATION_FINGERPRINT_V1',
      pg_catalog.jsonb_build_object(
        'publication_id',v_publication.id,'upload_id',v_publication.upload_id,
        'authority_scope_version',v_publication.authority_scope_version,
        'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
        'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex')
      )
    );
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',v_publication.state,'publication_id',v_publication.id,
      'upload_id',v_publication.upload_id,
      'authority_scope_version',v_publication.authority_scope_version,
      'projection_generation',v_publication.projection_generation,
      'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex'),
      'publication_fingerprint',pg_catalog.encode(v_fingerprint,'hex'),'idempotent',true
    );
  end if;
  if v_publication.state not in ('BUILDING','FAILED')
     or v_scope_version<>v_publication.authority_scope_version
     or (v_publication.correction_session_id is null and (
       v_scope_upload is distinct from v_publication.upload_id
       or v_upload.state<>'CURRENT'
     )) then
    if v_publication.state in ('BUILDING','FAILED') then
      update public.weekly_source_projection_publications
      set state='STALE',failure_code='AUTHORITY_SCOPE_CHANGED'
      where id=v_publication.id;
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',false,'status','STALE','reason_code','WEEKLY_SOURCE_PUBLICATION_CAS_STALE',
      'publication_id',v_publication.id,'current_upload_id',v_scope_upload,
      'current_authority_scope_version',v_scope_version
    );
  end if;

  if v_publication.authority_scope_version>2147483647
     or coalesce(v_publication.projection_generation,0)>2147483647 then
    raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003';
  end if;
  v_generation:=coalesce(
    v_publication.projection_generation,
    v_publication.authority_scope_version::integer
  );
  select pg_catalog.count(*)::integer into v_resolution_count
  from public.weekly_source_row_resolutions resolution
  join public.weekly_source_upload_rows source_row
    on source_row.id=resolution.upload_row_id
  where source_row.upload_id=v_upload.id
    and resolution.generation=v_generation;
  if v_resolution_count<>(select count(*) from public.weekly_source_upload_rows r
       where r.upload_id=v_upload.id and r.row_finalisation_state<>'SOURCE_REPORT_LINE')
     or exists(
       select 1
       from public.weekly_source_upload_rows source_row
       where source_row.upload_id=v_upload.id
         and source_row.row_finalisation_state<>'SOURCE_REPORT_LINE'
         and not exists(
           select 1
            from public.weekly_source_row_resolutions resolution
            where resolution.upload_row_id=source_row.id
              and resolution.generation=v_generation
              and resolution.source_row_fingerprint=source_row.normalised_row_hash
         )
     )
     or (v_publication.projection_generation is null and exists(
        select 1
        from public.weekly_source_row_resolutions resolution
       join public.weekly_source_upload_rows source_row
         on source_row.id=resolution.upload_row_id
        where source_row.upload_id=v_upload.id
          and resolution.generation<>v_generation
     )) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_RESOLUTION_CENSUS_INCOMPLETE'
      using errcode='55000';
  end if;

  v_comparison_hash:=private.weekly_source_projection_comparison_manifest_hash_v1(
    v_publication.id
  );
  v_issue_hash:=private.weekly_source_projection_issue_set_hash_v1(v_publication.id);
  if (v_expected_comparison is not null and v_expected_comparison<>v_comparison_hash)
     or (v_expected_issue is not null and v_expected_issue<>v_issue_hash) then
    update public.weekly_source_projection_publications
    set state='FAILED',failure_code='PUBLICATION_HASH_MISMATCH'
    where id=v_publication.id;
    if v_publication.correction_session_id is not null then
      update public.weekly_final_source_correction_sessions
      set updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_publication.correction_session_id;
    elsif v_publication.authority_scope_kind='CYCLE' then
      update public.weekly_source_cycles
      set projection_state='FAILED',current_projection_publication_id=null
      where id=v_cycle.id and current_complete_upload_id=v_publication.upload_id
        and version=v_publication.authority_scope_version;
    else
      update public.weekly_source_report_scopes
      set projection_state='FAILED',current_projection_publication_id=null,
          updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_scope.id and current_complete_upload_id=v_publication.upload_id
        and version=v_publication.authority_scope_version;
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',false,'status','FAILED','reason_code','WEEKLY_SOURCE_PUBLICATION_HASH_MISMATCH',
      'publication_id',v_publication.id
    );
  end if;

  v_ready_session_version:=case when v_publication.correction_session_id is null then null
    else v_correction.version+1 end;
  update public.weekly_source_projection_publications
  set comparison_manifest_hash=v_comparison_hash,issue_set_hash=v_issue_hash,
      state=case when v_publication.correction_session_id is null
        then 'CURRENT' else 'CORRECTION_READY' end,
      ready_session_version=v_ready_session_version,
      failure_code=null,published_at_utc=pg_catalog.transaction_timestamp()
  where id=v_publication.id;
  if v_publication.correction_session_id is not null then
    if v_publication.rebuild_idempotency_key is null then
      update public.weekly_final_source_correction_sessions
      set replacement_projection_publication_id=v_publication.id,
          version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_publication.correction_session_id and state='READY'
        and version=v_correction.version
        and replacement_correction_upload_id=v_publication.upload_id
        and replacement_projection_publication_id is null;
    else
      update public.weekly_final_source_correction_sessions
      set replacement_projection_publication_id=v_publication.id,
          state='READY',review_idempotency_key=null,review_request_hash=null,
          review_result_json=null,review_result_hash=null,
          version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_publication.correction_session_id and state='REVIEWED'
        and version=v_publication.ready_session_version
        and replacement_correction_upload_id=v_publication.upload_id
        and replacement_projection_publication_id is not null
        and replacement_projection_publication_id<>v_publication.id;
    end if;
    if not found then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PUBLICATION_CAS_LOST' using errcode='40001';
    end if;
  elsif v_publication.authority_scope_kind='CYCLE' then
    update public.weekly_source_cycles
    set projection_state='CURRENT',current_projection_publication_id=v_publication.id
    where id=v_cycle.id and current_complete_upload_id=v_publication.upload_id
      and version=v_publication.authority_scope_version;
  else
    update public.weekly_source_report_scopes
    set projection_state='CURRENT',current_projection_publication_id=v_publication.id,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_scope.id and current_complete_upload_id=v_publication.upload_id
      and version=v_publication.authority_scope_version;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_CAS_LOST' using errcode='40001';
  end if;
  if v_publication.correction_session_id is null and exists (
    select 1 from public.weekly_source_format_profiles profile
    where profile.id=v_upload.source_format_profile_id
      and profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
  ) then
    -- Recheck already-signed candidate evidence in the same publication
    -- transaction. This writes comparison/query evidence only: no source
    -- financial movement or Timesheet hours are created here.
    perform private.weekly_source_candidate_prefinal_publish_recheck_v1(
      v_actor,v_publication.id
    );
  end if;
  if v_publication.correction_session_id is null then
    perform private.weekly_source_self_bill_report_bind_v1(v_publication.id);
  end if;
  if v_publication.correction_session_id is null and v_publication.authority_scope_kind<>'SELF_BILL_REPORT_SCOPE' then
    perform private.weekly_source_import_outreach_v1(v_publication.id);
  end if;
  v_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_PUBLICATION_FINGERPRINT_V1',
    pg_catalog.jsonb_build_object(
      'publication_id',v_publication.id,'upload_id',v_publication.upload_id,
      'authority_scope_version',v_publication.authority_scope_version,
      'comparison_manifest_hash',pg_catalog.encode(v_comparison_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_issue_hash,'hex')
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok',true,'status',case when v_publication.correction_session_id is null
      then 'CURRENT' else 'CORRECTION_READY' end,
    'publication_id',v_publication.id,
    'upload_id',v_publication.upload_id,
    'authority_scope_version',v_publication.authority_scope_version,
    'projection_generation',v_publication.projection_generation,
    'ready_session_version',v_ready_session_version,
    'comparison_manifest_hash',pg_catalog.encode(v_comparison_hash,'hex'),
    'issue_set_hash',pg_catalog.encode(v_issue_hash,'hex'),
    'publication_fingerprint',pg_catalog.encode(v_fingerprint,'hex'),
    'idempotent',false
  );
end;
$function$;

-- Complete F8 Prepare owner plus report-only preparation; no pay orchestration.
create or replace function public.weekly_source_import_prepare_atomic_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_guard jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
    or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key where key not in
      ('actor_user_id','upload_id','projection_publication_id','expected_authority_scope_version','expected_row_manifest_hash')) then
    raise exception 'WEEKLY_SOURCE_PREPARATION_REQUEST_INVALID' using errcode='22023';
  end if;
  v_actor:=(p_request->>'actor_user_id')::uuid;
  select * into strict v_upload from public.weekly_source_uploads where id=(p_request->>'upload_id')::uuid;
  if exists(select 1 from public.weekly_source_report_scopes rs where rs.id=v_upload.report_scope_id and rs.self_bill_report_id is not null) then
    perform 1 from public.weekly_source_groups where id=(select source_group_id from public.weekly_source_cycles where id=v_upload.source_cycle_id) for update;
  end if;
  -- Same scope lock order as publication and finalisation; preparation cannot
  -- race a replacement into reviving a superseded file.
  select * into strict v_cycle from public.weekly_source_cycles where id=v_upload.source_cycle_id for update;
  select * into strict v_upload from public.weekly_source_uploads where id=v_upload.id for share;
  select * into strict v_profile from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
  select * into strict v_publication from public.weekly_source_projection_publications
    where id=(p_request->>'projection_publication_id')::uuid for share;
  perform private.weekly_source_office_authority_v1(v_actor,'FINALISE_WEEK',v_cycle.source_group_id,
    nullif(v_upload.file_metadata_json->>'client_id','')::uuid,v_cycle.finalisation_week_ending);
  if v_profile.profile_code='ACACIUM_SELF_BILL_REPORT_V1' then
    if v_upload.state<>'CURRENT' or v_upload.purpose<>'ORDINARY'
      or v_publication.authority_scope_kind<>'SELF_BILL_REPORT_SCOPE'
      or v_upload.row_manifest_hash is distinct from private.weekly_source_hex32_v1(
        p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_REQUIRED') then
      raise exception 'WEEKLY_SOURCE_REPORT_IMPORT_NOT_PREPARABLE' using errcode='55000'; end if;
    v_guard:=private.weekly_source_current_publication_guard_v1(v_cycle.id,
      v_publication.authority_scope_kind,v_publication.report_scope_id,v_upload.id,v_publication.id,
      (p_request->>'expected_authority_scope_version')::bigint);
    perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
    perform private.weekly_source_final_upload_assert_v1(v_upload.id);
    insert into private.weekly_source_import_preparations(upload_id,projection_publication_id,
      authority_scope_version,prepared_by_user_id,row_manifest_hash)
      values(v_upload.id,v_publication.id,v_publication.authority_scope_version,v_actor,v_upload.row_manifest_hash)
      on conflict(upload_id) do nothing;
    return jsonb_build_object('ok',true,'status','PREPARED','upload_id',v_upload.id,'invoice_only',true);
  end if;
  if v_upload.state<>'CURRENT' or v_upload.purpose<>'ORDINARY'
    or v_cycle.state in ('FINALISING','FINALISED')
    or v_profile.profile_code not in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1',
      'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1','ROSTER_WEEKLY_SUMMARY_ACTUAL_V1')
    or v_upload.coverage_state<>'COMPLETE'
    or v_upload.row_manifest_hash is distinct from private.weekly_source_hex32_v1(
      p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_REQUIRED') then
    raise exception 'WEEKLY_SOURCE_IMPORT_NOT_PREPARABLE' using errcode='55000';
  end if;
  v_guard:=private.weekly_source_current_publication_guard_v1(v_cycle.id,
    v_publication.authority_scope_kind,v_publication.report_scope_id,v_upload.id,v_publication.id,
    (p_request->>'expected_authority_scope_version')::bigint);
  perform private.weekly_source_final_upload_assert_v1(v_upload.id);
  insert into private.weekly_source_import_preparations(upload_id,projection_publication_id,
    authority_scope_version,prepared_by_user_id,row_manifest_hash)
  values(v_upload.id,v_publication.id,v_publication.authority_scope_version,v_actor,v_upload.row_manifest_hash)
  on conflict(upload_id) do nothing;
  return pg_catalog.jsonb_build_object('ok',true,'status','PREPARED','upload_id',v_upload.id);
end;
$function$;

create or replace function private.weekly_source_self_bill_report_duplicate_prior_v1(p_report_row_id uuid)
returns boolean language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select exists(select 1 from public.weekly_source_upload_rows r
    join public.weekly_source_uploads u on u.id=r.upload_id
    join public.weekly_source_report_scopes s on s.id=u.report_scope_id
    join public.weekly_source_self_bill_reports report on report.id=s.self_bill_report_id
    join public.weekly_source_billing_movements m on m.actual_client_id=s.client_id and m.source_line_kind='SELF_BILL_REPORT_LINE'
      and m.movement_role='POSITIVE' and m.placement_state='PLACED'
    join public.weekly_source_upload_rows prior on prior.id=m.self_bill_report_row_id and prior.external_source_key=r.external_source_key
    join public.weekly_source_final_revisions fr on fr.id=m.final_revision_id and fr.state='CURRENT'
    join public.weekly_source_report_scopes ps on ps.id=fr.report_scope_id and ps.source_group_id=s.source_group_id
    join public.weekly_source_self_bill_reports pr on pr.id=ps.self_bill_report_id and pr.invoice_date<report.invoice_date
    where r.id=p_report_row_id and r.row_finalisation_state='SOURCE_REPORT_LINE' and r.source_shift_charge_pence>=0)
$function$;

create or replace function private.weekly_source_self_bill_report_duplicate_hold_v1(p_report_row_id uuid)
returns boolean language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select private.weekly_source_self_bill_report_duplicate_prior_v1(p_report_row_id)
    and not exists(select 1 from public.weekly_source_upload_rows r
      join public.weekly_source_invoice_hold_releases receipt on receipt.upload_row_id=r.id
        and receipt.hold_kind='DUPLICATE_REQUEST_ID' and receipt.action='BILL_AS_FILE'
        and receipt.net_pence=r.source_shift_charge_pence and receipt.vat_pence=r.source_vat_pence and receipt.gross_pence=r.source_gross_pence
      where r.id=p_report_row_id)
$function$;

-- This invoice-only leaf is composed into the existing finalise engine by the
-- root integrator after NEXT/busy admission. It is never a new public route.
create or replace function private.weekly_source_self_bill_report_movement_insert_v1(p_report_row_id uuid,p_final_revision_id uuid)
returns uuid language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare row_fact public.weekly_source_upload_rows%rowtype; revision public.weekly_source_final_revisions%rowtype;
  scope public.weekly_source_report_scopes%rowtype; report public.weekly_source_self_bill_reports%rowtype;
  binding public.weekly_source_self_bill_report_line_bindings%rowtype; resolution public.weekly_source_row_resolutions%rowtype;
  prior public.weekly_source_billing_movements%rowtype; v_prior_count integer; v_id uuid; v_timesheet uuid;
  v_pay_witness jsonb; v_prior_binding jsonb; v_role text; v_facts jsonb; v_pay jsonb; v_charge jsonb; v_mapping bytea; v_hash bytea;
begin
  select * into strict revision from public.weekly_source_final_revisions where id=p_final_revision_id;
  select * into strict scope from public.weekly_source_report_scopes where id=revision.report_scope_id;
  select * into strict report from public.weekly_source_self_bill_reports where id=scope.self_bill_report_id;
  select * into strict row_fact from public.weekly_source_upload_rows where id=p_report_row_id;
  if revision.authority_scope_kind<>'SELF_BILL_REPORT_SCOPE' or revision.state<>'CURRENT'
    or revision.reason<>'INITIAL_FINALISATION' or row_fact.upload_id<>revision.upload_id
    or row_fact.row_finalisation_state<>'SOURCE_REPORT_LINE'
    or row_fact.source_gross_pence::numeric is distinct from row_fact.source_shift_charge_pence::numeric+row_fact.source_vat_pence::numeric then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_MOVEMENT_AUTHORITY_INVALID' using errcode='55000'; end if;
  select id into v_id from public.weekly_source_billing_movements where self_bill_report_row_id=row_fact.id;
  if found then raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_MOVEMENT_ALREADY_EXISTS' using errcode='55000'; end if;
  select * into binding from public.weekly_source_self_bill_report_line_bindings where report_row_id=row_fact.id and state='CURRENT' for share;
  if found then
    select * into strict resolution from public.weekly_source_row_resolutions where id=binding.bound_row_resolution_id;
    if resolution.upload_row_id<>binding.export_upload_row_id or resolution.work_event_id<>binding.work_event_id
      or resolution.client_id<>scope.client_id or resolution.mapping_state<>'RESOLVED' then
      raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_BOUND_IDENTITY_INVALID' using errcode='55000'; end if;
    v_pay_witness:=private.weekly_source_self_bill_report_pay_witness_v1(binding.id);
    v_timesheet:=nullif(v_pay_witness->>'invoice_timesheet_id','')::uuid;
  end if;
  v_role:='POSITIVE';
  if row_fact.source_shift_charge_pence<0 then
    v_prior_binding:=private.weekly_source_self_bill_report_prior_binding_v1(row_fact.id);
    if v_prior_binding is not null then
      select * into strict prior from public.weekly_source_billing_movements where id=(v_prior_binding->>'prior_movement_id')::uuid;
      -- Preserve the prior bound identity. A physical credit is not pay work.
      if binding.id is not null and binding.work_event_id is distinct from prior.work_event_id then
        raise exception 'WEEKLY_SOURCE_REPORT_PRIOR_BOUND_IDENTITY_CHANGED' using errcode='55000'; end if;
      resolution.candidate_id:=prior.candidate_id; resolution.contract_id:=prior.contract_id;
      resolution.work_event_id:=prior.work_event_id; v_timesheet:=prior.invoice_timesheet_id; v_role:='REVERSAL';
      v_pay_witness:=jsonb_build_object('bound_pay_snapshot_line_id',prior.source_facts_json->'bound_pay_snapshot_line_id',
        'bound_pay_final_revision_id',prior.source_facts_json->'bound_pay_final_revision_id',
        'bound_pay_projection_receipt_id',prior.source_facts_json->'bound_pay_projection_receipt_id',
        'published_timesheet_financial_id',prior.source_facts_json->'published_timesheet_financial_id',
        'invoice_timesheet_id',prior.invoice_timesheet_id,'candidate_id',prior.candidate_id,'client_id',prior.actual_client_id,
        'contract_id',prior.contract_id,'work_event_id',prior.work_event_id);
    else
      v_role:='STANDALONE_NEGATIVE';
      if binding.id is not null and v_timesheet is null then
        select timesheet_id into v_timesheet from public.weekly_source_row_timesheet_lineages where row_resolution_id=binding.bound_row_resolution_id;
      end if;
    end if;
  elsif binding.id is null or v_timesheet is null or
    private.weekly_source_report_shift_facts_v1(binding.work_event_id,scope.id)->'invoice_ready' is distinct from 'true'::jsonb then
    raise exception 'WEEKLY_SOURCE_REPORT_Q_NOPAY' using errcode='55000';
  end if;
  if v_role<>'STANDALONE_NEGATIVE' and (resolution.candidate_id is null or resolution.contract_id is null
    or resolution.work_event_id is null or v_timesheet is null) then
    raise exception 'WEEKLY_SOURCE_REPORT_INVOICE_IDENTITY_UNPROVED' using errcode='55000'; end if;
  if private.weekly_source_self_bill_report_duplicate_hold_v1(row_fact.id) then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_DUPLICATE_REQUEST_HOLD' using errcode='55000'; end if;
  v_pay:=private.weekly_source_invoice_only_vector_v1('PAY',0);
  v_charge:=private.weekly_source_invoice_only_vector_v1('CHARGE',row_fact.source_shift_charge_pence);
  v_facts:=jsonb_build_object('schema_version','WEEKLY_SOURCE_SELF_BILL_REPORT_FACTS_V1','self_bill_report_id',report.id,
    'report_scope_id',scope.id,'report_number',report.report_number,'invoice_date',report.invoice_date,
    'upload_row_id',row_fact.id,'source_row_ordinal',row_fact.source_row_ordinal,'request_id',row_fact.external_source_key,
    'worker_name',row_fact.source_candidate_identity,'work_date',row_fact.work_date,
    'start_at_local',row_fact.start_at_local,'end_at_local',row_fact.end_at_local,
    'source_net_pence',row_fact.source_shift_charge_pence,'source_vat_pence',row_fact.source_vat_pence,'source_gross_pence',row_fact.source_gross_pence,
    'report_line_binding_id',binding.id,'bound_row_resolution_id',binding.bound_row_resolution_id,
    'bound_export_projection_publication_id',binding.export_projection_publication_id,'prior_report_movement_id',prior.id,
    'rule_set_version_id',revision.rule_set_version_id)||coalesce(v_pay_witness,'{}'::jsonb);
  if v_facts ? 'row_resolution_id' then raise exception 'WEEKLY_SOURCE_REPORT_PAY_ORIGIN_FORBIDDEN' using errcode='55000'; end if;
  v_mapping:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_REPORT_BINDING_POLICY_V1',jsonb_build_object(
    'report_row_hash',encode(row_fact.normalised_row_hash,'hex'),'binding_id',binding.id,
    'bound_row_resolution_id',binding.bound_row_resolution_id,'prior_movement_id',prior.id,'rule_set_version_id',revision.rule_set_version_id));
  v_hash:=private.weekly_source_billing_movement_hash_v1(jsonb_build_object('self_bill_report_row_id',row_fact.id,
    'final_revision_id',revision.id,'finalisation_cycle_id',revision.source_cycle_id,'actual_client_id',scope.client_id,
    'candidate_id',resolution.candidate_id,'contract_id',resolution.contract_id,'work_event_id',resolution.work_event_id,
    'movement_role',v_role,'prior_movement_id',prior.id,'source_profile_kind','SELF_BILL_REPORT','source_line_kind','SELF_BILL_REPORT_LINE',
    'source_facts',v_facts,'pay_vector',v_pay,'charge_vector',v_charge,'total_pay_pence',0,
    'calculated_comparison_charge_pence',row_fact.source_shift_charge_pence,'source_validation_charge_pence',row_fact.source_shift_charge_pence,
    'invoice_presentation_charge_pence',row_fact.source_shift_charge_pence,'vat_rate_pct',20,'vat_amount',row_fact.source_vat_pence::numeric/100,
    'total_inc_vat',row_fact.source_gross_pence::numeric/100,'price_check_result','NOT_APPLICABLE','price_check_fingerprint',null,
    'charge_acceptance_id',null,'mapping_rate_policy_fingerprint',encode(v_mapping,'hex'),'invoice_timesheet_id',v_timesheet));
  insert into public.weekly_source_billing_movements(self_bill_report_row_id,final_revision_id,finalisation_cycle_id,actual_client_id,
    candidate_id,contract_id,work_event_id,movement_role,prior_movement_id,source_profile_kind,source_line_kind,source_facts_json,
    canonical_pay_vector_json,canonical_charge_vector_json,total_pay_ex_vat,calculated_comparison_charge_pence,
    source_validation_charge_pence,invoice_presentation_charge_pence,vat_rate_pct,vat_amount,total_inc_vat,price_check_result,
    mapping_rate_policy_fingerprint,invoice_timesheet_id,original_cycle_key,movement_economic_hash,placement_state)
    values(row_fact.id,revision.id,revision.source_cycle_id,scope.client_id,resolution.candidate_id,resolution.contract_id,resolution.work_event_id,
      v_role,prior.id,'SELF_BILL_REPORT','SELF_BILL_REPORT_LINE',v_facts,v_pay,v_charge,0,row_fact.source_shift_charge_pence,
      row_fact.source_shift_charge_pence,row_fact.source_shift_charge_pence,20,row_fact.source_vat_pence::numeric/100,
      row_fact.source_gross_pence::numeric/100,'NOT_APPLICABLE',v_mapping,v_timesheet,revision.source_cycle_id::text,v_hash,'UNPLACED') returning id into v_id;
  return v_id;
end;
$function$;

create or replace function private.weekly_source_self_bill_report_finalise_v1(p_request jsonb,p_vat_rounding_variant text)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_cycle public.weekly_source_cycles%rowtype; v_scope public.weekly_source_report_scopes%rowtype;
  v_report public.weekly_source_self_bill_reports%rowtype; v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype; v_rules jsonb; v_revision uuid; v_manifest uuid;
  v_policy bytea; v_hash bytea; v_row uuid; v_movement uuid; v_rounding uuid; v_count integer; v_client_hash bytea;
  v_rounding_pence bigint;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_vat_rounding_variant is null or p_vat_rounding_variant not in ('A','B') then
    raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_COMPOSITION_UNPROVED' using errcode='55000'; end if;
  if jsonb_typeof(p_request) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_request) k where k not in (
    'actor_user_id','source_cycle_id','authority_scope_kind','report_scope_id','upload_id','projection_publication_id',
    'expected_authority_scope_version','expected_row_manifest_hash','expected_comparison_manifest_hash','expected_issue_set_hash','exclude_unfinalised_acknowledged'))
    or p_request->>'authority_scope_kind' is distinct from 'SELF_BILL_REPORT_SCOPE' then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_FINALISE_REQUEST_INVALID' using errcode='22023'; end if;
  v_actor:=(p_request->>'actor_user_id')::uuid;
  if v_actor is null then raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_ACTOR_REQUIRED' using errcode='22023'; end if;
  perform 1 from public.weekly_source_groups where id=(select source_group_id from public.weekly_source_cycles where id=(p_request->>'source_cycle_id')::uuid) for update;
  select * into strict v_cycle from public.weekly_source_cycles where id=(p_request->>'source_cycle_id')::uuid for update;
  select * into strict v_scope from public.weekly_source_report_scopes where id=(p_request->>'report_scope_id')::uuid for update;
  select * into strict v_report from public.weekly_source_self_bill_reports where id=v_scope.self_bill_report_id;
  select * into strict v_upload from public.weekly_source_uploads where id=(p_request->>'upload_id')::uuid for share;
  select * into strict v_publication from public.weekly_source_projection_publications where id=(p_request->>'projection_publication_id')::uuid for share;
  perform private.weekly_source_office_authority_v1(v_actor,'FINALISE_WEEK',v_cycle.source_group_id,v_scope.client_id,v_cycle.finalisation_week_ending);
  v_rules:=private.weekly_source_self_bill_report_rules_assert_v1(v_scope.client_id,v_cycle.id);
  if v_scope.source_cycle_id<>v_cycle.id or v_scope.source_group_id<>v_cycle.source_group_id
    or v_scope.cutoff_at_utc<>v_cycle.cutoff_at_utc or v_report.source_cycle_id<>v_cycle.id
    or v_report.client_id<>v_scope.client_id or v_scope.version is distinct from (p_request->>'expected_authority_scope_version')::bigint
    or v_scope.current_complete_upload_id is distinct from v_upload.id or v_scope.current_projection_publication_id is distinct from v_publication.id
    or v_scope.projection_state<>'CURRENT' or v_upload.state<>'CURRENT' or v_upload.report_scope_id<>v_scope.id
    or v_publication.state<>'CURRENT' or v_publication.authority_scope_kind<>'SELF_BILL_REPORT_SCOPE'
    or v_publication.upload_id<>v_upload.id or v_publication.report_scope_id<>v_scope.id or v_publication.authority_scope_version<>v_scope.version
    or v_upload.row_manifest_hash is distinct from private.weekly_source_hex32_v1(p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_INVALID')
    or v_publication.comparison_manifest_hash is distinct from private.weekly_source_hex32_v1(p_request->>'expected_comparison_manifest_hash','WEEKLY_SOURCE_COMPARISON_MANIFEST_HASH_INVALID')
    or v_publication.issue_set_hash is distinct from private.weekly_source_hex32_v1(p_request->>'expected_issue_set_hash','WEEKLY_SOURCE_ISSUE_SET_HASH_INVALID') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_FINALISE_CAS_STALE' using errcode='40001'; end if;
  if v_scope.current_final_revision_id is not null then
    if not exists(select 1 from public.weekly_source_final_revisions fr where fr.id=v_scope.current_final_revision_id
      and fr.authority_scope_kind='SELF_BILL_REPORT_SCOPE' and fr.report_scope_id=v_scope.id and fr.upload_id=v_upload.id and fr.state='CURRENT') then
      raise exception 'WEEKLY_SOURCE_REPORT_FINAL_POINTER_CORRUPT' using errcode='55000'; end if;
    return jsonb_build_object('ok',true,'status','FINALISED','final_revision_id',v_scope.current_final_revision_id,
      'source_cycle_id',v_cycle.id,'report_scope_id',v_scope.id,'invoice_only',true,'idempotent',true);
  end if;
  if v_scope.state not in ('OPEN','FINALISABLE') then raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_NOT_OPEN' using errcode='55000'; end if;
  perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
  perform private.weekly_source_final_upload_assert_v1(v_upload.id);
  if not private.weekly_source_import_is_prepared_v1(v_upload.id) then
    raise exception 'WEEKLY_SOURCE_REPORT_IMPORT_NOT_PREPARED' using errcode='55000'; end if;
  if exists(select 1 from public.weekly_source_upload_rows r where r.upload_id=v_upload.id
    and r.source_shift_charge_pence::numeric+r.source_vat_pence::numeric is distinct from r.source_gross_pence::numeric) then
    raise exception 'WEEKLY_SOURCE_REPORT_LITERAL_GROSS_MISMATCH' using errcode='55000'; end if;
  v_policy:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_REPORT_FINAL_POLICY_V1',v_rules);
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_REPORT_FINAL_MANIFEST_V1',jsonb_build_object(
    'source_cycle_id',v_cycle.id,'report_scope_id',v_scope.id,'self_bill_report_id',v_report.id,'upload_id',v_upload.id,
    'publication_id',v_publication.id,'authority_scope_version',v_scope.version,'row_manifest_hash',encode(v_upload.row_manifest_hash,'hex'),
    'report_row_manifest_hash',encode(v_report.row_manifest_hash,'hex'),'policy_fingerprint',encode(v_policy,'hex')));
  insert into public.weekly_source_final_revisions(source_cycle_id,authority_scope_kind,report_scope_id,revision_number,upload_id,
    reason,finalised_by_user_id,manifest_hash,policy_fingerprint,state,rule_set_version_id)
    values(v_cycle.id,'SELF_BILL_REPORT_SCOPE',v_scope.id,1,v_upload.id,'INITIAL_FINALISATION',v_actor,v_hash,v_policy,'CURRENT',
      (v_rules->>'rule_set_version_id')::uuid) returning id into v_revision;
  for v_row in select id from public.weekly_source_upload_rows where upload_id=v_upload.id order by source_row_ordinal loop
    v_movement:=private.weekly_source_self_bill_report_movement_insert_v1(v_row,v_revision);
  end loop;
  select count(*) into v_count from public.weekly_source_billing_movements where final_revision_id=v_revision and source_line_kind='SELF_BILL_REPORT_LINE';
  if v_count<>v_report.line_count or not exists(select 1 from public.weekly_source_billing_movements where final_revision_id=v_revision
    having sum(invoice_presentation_charge_pence)=v_report.net_pence and sum(vat_amount*100)=v_report.vat_pence and sum(total_inc_vat*100)=v_report.gross_pence) then
    raise exception 'WEEKLY_SOURCE_REPORT_MOVEMENT_TOTALS_MISMATCH' using errcode='55000'; end if;
  -- A/B is selected solely by the root integration after real proof. No default.
  v_rounding:=private.weekly_source_vat_rounding_movement_insert_v1(v_revision,v_scope.client_id,
    case when p_vat_rounding_variant='B' then v_movement else null end);
  select coalesce(sum(vat_amount*100),0)::bigint into v_rounding_pence from public.weekly_source_billing_movements
    where id=v_rounding and vat_rounding_revision_id=v_revision and actual_client_id=v_scope.client_id and source_line_kind='INVOICE_VAT_ROUNDING';
  if not exists(select 1 from public.weekly_source_billing_movements where final_revision_id=v_revision
    having sum(invoice_presentation_charge_pence)=v_report.net_pence
      and sum(vat_amount*100)=v_report.vat_pence::numeric+v_rounding_pence
      and sum(total_inc_vat*100)=v_report.net_pence::numeric+v_report.vat_pence::numeric+v_rounding_pence) then
    raise exception 'WEEKLY_SOURCE_REPORT_INVOICE_TARGET_TOTALS_MISMATCH' using errcode='55000'; end if;
  select private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_CLIENT_MANIFEST_V1',jsonb_build_object(
    'final_revision_id',v_revision,'source_group_id',v_cycle.source_group_id,'source_cycle_id',v_cycle.id,'client_id',v_scope.client_id,
    'finalisation_week_ending',v_cycle.finalisation_week_ending,'backing_report_number',v_report.report_number,
    'movements',jsonb_agg(jsonb_build_object('movement_id',id,'movement_economic_hash',encode(movement_economic_hash,'hex')) order by encode(movement_economic_hash,'hex')),
    'expense_authorities','[]'::jsonb)) into v_client_hash from public.weekly_source_billing_movements where final_revision_id=v_revision;
  insert into public.weekly_source_client_manifests(final_revision_id,source_group_id,source_cycle_id,client_id,finalisation_week_ending,
    backing_report_number,manifest_hash,movement_count,unchanged_snapshot_count,expense_line_count,invoice_state)
    values(v_revision,v_cycle.source_group_id,v_cycle.id,v_scope.client_id,v_cycle.finalisation_week_ending,v_report.report_number,v_client_hash,
      v_count+(v_rounding is not null)::integer,0,0,'READY') returning id into v_manifest;
  insert into public.weekly_source_manifest_movements(client_manifest_id,billing_movement_id,manifest_ordinal,movement_hash)
    select v_manifest,id,row_number() over(order by encode(movement_economic_hash,'hex'))::integer,movement_economic_hash
    from public.weekly_source_billing_movements where final_revision_id=v_revision;
  update public.weekly_source_report_scopes set current_final_revision_id=v_revision,state='FINALISED',updated_at_utc=transaction_timestamp()
    where id=v_scope.id and current_final_revision_id is null and version=v_scope.version
      and current_complete_upload_id=v_upload.id and current_projection_publication_id=v_publication.id;
  if not found then raise exception 'WEEKLY_SOURCE_REPORT_FINALISE_CAS_LOST' using errcode='40001'; end if;
  return jsonb_build_object('ok',true,'status','FINALISED','idempotent',false,'final_revision_id',v_revision,
    'source_cycle_id',v_cycle.id,'authority_scope_kind','SELF_BILL_REPORT_SCOPE','report_scope_id',v_scope.id,
    'self_bill_report_id',v_report.id,'invoice_date',v_report.invoice_date,'movement_count',v_count+(v_rounding is not null)::integer,
    'snapshot_count',0,'transition_count',0,'expense_generation_count',0,'invoice_only',true);
end;
$function$;

-- Complete native correction owners: report-scoped Correct Final is explicitly unsupported.
create or replace function public.weekly_source_correct_final_open_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','authority_scope_kind','expected_current_final_revision_id',
    'expected_final_manifest_hash','idempotency_key','reason','report_scope_id',
    'schema_version','source_cycle_id'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_cycle_id uuid;
  v_scope_kind text;
  v_report_scope_id uuid;
  v_revision_id uuid;
  v_expected_manifest bytea;
  v_idempotency_key text;
  v_reason text;
  v_request_hash bytea;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_revision public.weekly_source_final_revisions%rowtype;
  v_existing public.weekly_final_source_correction_sessions%rowtype;
  v_existing_by_key public.weekly_final_source_correction_sessions%rowtype;
  v_existing_by_hash public.weekly_final_source_correction_sessions%rowtype;
  v_existing_key_count bigint;
  v_existing_hash_count bigint;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_guard jsonb;
  v_group_id uuid;
  v_client_id uuid;
  v_guard_fingerprint bytea;
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_OPEN_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_scope_kind:=pg_catalog.upper(pg_catalog.btrim(p_request->>'authority_scope_kind'));
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_revision_id:=(p_request->>'expected_current_final_revision_id')::uuid;
    v_expected_manifest:=pg_catalog.decode(p_request->>'expected_final_manifest_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_actor is null or v_cycle_id is null or v_revision_id is null
     or v_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE')
     or (v_scope_kind='NHSP_REPORT_SCOPE') is distinct from (v_report_scope_id is not null)
     or pg_catalog.octet_length(v_expected_manifest)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_OPEN_V1',p_request-'idempotency_key'
  );
  -- WP-59.  Two defects lived in this one replay lookup.
  --
  -- (1) It chose between an idempotency-key match and a request-hash match with
  --     `order by ... limit 1`.  That is a safety decision taken by an
  --     ordering, which this programme forbids.  Both candidates are now read
  --     explicitly, each with its own cardinality check, and a disagreement
  --     between them fails closed instead of being silently ranked away.
  --
  -- (2) It matched a session in ANY state.  Before WP-59 that was harmless
  --     because no session could ever leave the live set.  Now that
  --     public.weekly_source_correct_final_cancel_atomic_v1 exists, re-sending
  --     the request that opened a since-cancelled session would have returned
  --     that cancelled session as an idempotent replay -- telling Office it
  --     still has a correction session when it has none.  A terminal session is
  --     never replayed as if it were live; the caller is told so in a typed
  --     refusal and must open the new correction with its own key.
  select pg_catalog.count(*) into v_existing_key_count
  from public.weekly_final_source_correction_sessions correction
  where correction.actor_user_id=v_actor
    and correction.idempotency_key=v_idempotency_key;
  select pg_catalog.count(*) into v_existing_hash_count
  from public.weekly_final_source_correction_sessions correction
  where correction.request_hash=v_request_hash;
  if v_existing_key_count>1 or v_existing_hash_count>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_AMBIGUOUS'
      using errcode='55000',
        detail='key_matches='||v_existing_key_count::text
               ||' request_hash_matches='||v_existing_hash_count::text;
  end if;
  if v_existing_key_count=1 then
    select * into v_existing_by_key
    from public.weekly_final_source_correction_sessions correction
    where correction.actor_user_id=v_actor
      and correction.idempotency_key=v_idempotency_key;
  end if;
  if v_existing_hash_count=1 then
    select * into v_existing_by_hash
    from public.weekly_final_source_correction_sessions correction
    where correction.request_hash=v_request_hash;
  end if;
  if v_existing_key_count=1 and v_existing_hash_count=1
     and v_existing_by_key.id is distinct from v_existing_by_hash.id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_COLLISION'
      using errcode='22023';
  end if;
  if v_existing_key_count=1 then
    v_existing:=v_existing_by_key;
  elsif v_existing_hash_count=1 then
    v_existing:=v_existing_by_hash;
  end if;
  if v_existing_key_count=1 or v_existing_hash_count=1 then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    if v_existing.state in ('CANCELLED','FAILED') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_SESSION_TERMINAL'
        using errcode='22023',
          detail='correction session '||v_existing.id::text||' is '
                 ||v_existing.state||'. Open the new correction with its own '
                 'idempotency key and its own reason; a terminal session is '
                 'never replayed as a live one.';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',v_existing.state,'correction_session_id',v_existing.id,
      'version',v_existing.version,'idempotent_replay',true
    );
  end if;

  select * into v_cycle from public.weekly_source_cycles
  where id=v_cycle_id for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select source_group_id into v_group_id
  from public.weekly_source_cycles where id=v_cycle.id;
  if v_scope_kind='NHSP_REPORT_SCOPE' then
    select * into v_scope from public.weekly_source_report_scopes
    where id=v_report_scope_id for update;
    if not found or v_scope.source_cycle_id is distinct from v_cycle.id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SCOPE_INVALID' using errcode='22023';
    end if;
    v_client_id:=v_scope.client_id;
    if v_scope.current_final_revision_id is distinct from v_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
    end if;
  elsif v_cycle.current_final_revision_id is distinct from v_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;
  select * into v_revision from public.weekly_source_final_revisions
  where id=v_revision_id for update;
  if not found or v_revision.state<>'CURRENT'
     or v_revision.source_cycle_id is distinct from v_cycle.id
     or v_revision.authority_scope_kind is distinct from v_scope_kind
     or v_revision.report_scope_id is distinct from v_report_scope_id
     or v_revision.manifest_hash is distinct from v_expected_manifest then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;
  if v_client_id is null then
    select client_id into strict v_client_id
    from public.weekly_source_client_manifests where final_revision_id=v_revision.id;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group_id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_revision.id,v_actor,null::uuid,false
  );
  v_guard_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  insert into public.weekly_final_source_correction_sessions(
    source_cycle_id,authority_scope_kind,report_scope_id,
    expected_current_final_revision_id,expected_final_manifest_hash,state,version,
    actor_user_id,reason,idempotency_key,request_hash,guard_fingerprint
  ) values (
    v_cycle.id,v_scope_kind,v_report_scope_id,v_revision.id,v_revision.manifest_hash,
    'DRAFT',1,v_actor,v_reason,v_idempotency_key,v_request_hash,v_guard_fingerprint
  ) returning * into v_session;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_OPENED',
         pg_catalog.jsonb_build_object(
           'current_final_revision_id',v_revision.id,
           'current_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex')
         ),
         pg_catalog.jsonb_build_object(
           'state','DRAFT','source_cycle_id',v_cycle.id,
           'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_guard->'affected_roots'),
           'guard_fingerprint',pg_catalog.encode(v_guard_fingerprint,'hex')
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','DRAFT','correction_session_id',v_session.id,
    'version',v_session.version,'affected_root_count',
      pg_catalog.jsonb_array_length(v_guard->'affected_roots'),
    'guard_fingerprint',pg_catalog.encode(v_guard_fingerprint,'hex'),
    'idempotent_replay',false
  );
end;
$function$;

create or replace function public.weekly_source_correct_final_review_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_row_manifest_hash','expected_session_version','idempotency_key',
    'replacement_projection_publication_id','replacement_upload_id','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_idempotency_key text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_client_id uuid;
  v_office_preview jsonb;
  v_result jsonb;
  v_result_hash bytea;
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_V1',p_request-'idempotency_key'
  );

  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.review_idempotency_key=v_idempotency_key then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.review_request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.review_result_json||pg_catalog.jsonb_build_object(
      'idempotent_replay',true
    );
  end if;
  if v_session.state not in ('READY','REVIEWED') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state not in ('READY','REVIEWED')
     or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for share;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,
                    v_cycle.current_projection_publication_id)
  for share;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for share;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for share;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
      or v_replacement_publication.authority_scope_version<>v_scope_version
      or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
      or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;
  select client_id into strict v_client_id
  from public.weekly_source_client_manifests
  where final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,false
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  v_result:=pg_catalog.jsonb_build_object(
    'ok',true,
    'status',case when pg_catalog.jsonb_array_length(v_office_preview->'blockers')>0
      then 'BLOCKED' else 'READY_FOR_CONFIRMATION' end,
    'correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'upload_id',v_replacement_upload.id,
    'version',v_expected_session_version+1,
    'office_preview',v_office_preview,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='REVIEWED',review_idempotency_key=v_idempotency_key,
      review_request_hash=v_request_hash,review_result_json=v_result,
      review_result_hash=v_result_hash,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state in ('READY','REVIEWED')
    and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_REVIEWED',
         pg_catalog.jsonb_build_object('state',v_session.state,'version',v_expected_session_version),
         pg_catalog.jsonb_build_object(
           'state','REVIEWED','version',v_expected_session_version+1,
           'status',v_result->>'status',
           'change_count',pg_catalog.jsonb_array_length(v_office_preview->'changes'),
           'blocker_count',pg_catalog.jsonb_array_length(v_office_preview->'blockers'),
           'review_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_session.reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function public.weekly_source_correct_final_prepare_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_preview_hash','expected_row_manifest_hash','expected_session_version',
    'idempotency_key','reason','confirmation_text',
    'replacement_projection_publication_id','replacement_upload_id','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_expected_preview_hash bytea;
  v_idempotency_key text;
  v_reason text;
  v_confirmation_text text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_client_id uuid;
  v_core_result jsonb;
  v_context jsonb;
  v_result jsonb;
  v_result_hash bytea;
  v_prepared_revision_id uuid;
  v_prepared_session_version bigint;
  v_office_preview jsonb;
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
    v_expected_preview_hash:=pg_catalog.decode(p_request->>'expected_preview_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_confirmation_text:=pg_catalog.btrim(coalesce(p_request->>'confirmation_text',''));
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.octet_length(v_expected_preview_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_confirmation_text) not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_V1',p_request-'idempotency_key'
  );
  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.state in ('PREPARED','COMMITTING','APPLIED') then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.prepare_idempotency_key is distinct from v_idempotency_key
       or v_session.prepare_request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.prepare_result_json||pg_catalog.jsonb_build_object(
      'status','PREPARED','idempotent_replay',true
    );
  end if;

  -- Exact retained PREPARE replay above remains exempt. Fresh correction
  -- admission precedes the outer cycle lock and the nested Final engine.
  perform private.weekly_source_pay_query_admit_v2();

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state<>'REVIEWED' or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or v_session.review_result_json is null
     or v_session.review_result_hash is distinct from private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_RESULT_V1',v_session.review_result_json
        )
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for share;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,
                    v_cycle.current_projection_publication_id)
  for share;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for update;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for update;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_publication.authority_scope_version<>v_scope_version
     or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
     or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;
  select client_id into strict v_client_id
  from public.weekly_source_client_manifests
  where final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,true
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  if v_session.review_result_json->'office_preview' is distinct from v_office_preview
     or private.weekly_source_finalisation_hex32_v1(
          v_office_preview->>'preview_hash','WEEKLY_SOURCE_CORRECTION_PREVIEW_HASH_INVALID'
        ) is distinct from v_expected_preview_hash
     or v_confirmation_text is distinct from v_office_preview->>'confirmation_text'
     or pg_catalog.jsonb_array_length(v_office_preview->'blockers')<>0 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREVIEW_STALE' using errcode='40001';
  end if;
  update public.weekly_final_source_correction_sessions
  set state='PREPARING',prepare_idempotency_key=v_idempotency_key,
      prepare_request_hash=v_request_hash,reason=v_reason,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='REVIEWED' and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;

  v_core_result:=private.weekly_source_finalise_engine_v1(
    pg_catalog.jsonb_build_object(
      'actor_user_id',v_actor,'source_cycle_id',v_cycle.id,
      'authority_scope_kind',v_session.authority_scope_kind,
      'report_scope_id',v_session.report_scope_id,
      'upload_id',v_replacement_upload.id,
      'projection_publication_id',v_replacement_publication.id,
      'expected_authority_scope_version',v_scope_version,
      'expected_row_manifest_hash',pg_catalog.encode(v_expected_row_hash,'hex'),
      'expected_comparison_manifest_hash',pg_catalog.encode(v_expected_comparison_hash,'hex'),
      'expected_issue_set_hash',pg_catalog.encode(v_expected_issue_hash,'hex')
    ),v_session.id,true
  );
  if coalesce((v_core_result->>'ok')::boolean,false) is not true
     or v_core_result->>'status'<>'PREPARED' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_FAILED'
      using errcode='55000',detail=v_core_result::text;
  end if;
  v_prepared_revision_id:=(v_core_result->>'final_revision_id')::uuid;
  update public.weekly_final_source_correction_sessions
  set prepared_final_revision_id=v_prepared_revision_id
  where id=v_session.id and state='PREPARING'
    and prepare_request_hash=v_request_hash;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  v_context:=private.weekly_source_correct_final_prepared_context_v1(v_session.id);
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  v_prepared_session_version:=v_expected_session_version+2;
  v_result:=v_core_result||pg_catalog.jsonb_build_object(
    'correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'root_contexts',v_context->'root_contexts',
    'office_preview',v_office_preview,
    'version',v_prepared_session_version,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='PREPARED',prepare_result_json=v_result,prepare_result_hash=v_result_hash,
      version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='PREPARING'
    and prepared_final_revision_id=v_prepared_revision_id
    and prepare_request_hash=v_request_hash;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_PREPARED',
         pg_catalog.jsonb_build_object(
           'state','READY','current_final_revision_id',v_prior_revision.id
         ),
         pg_catalog.jsonb_build_object(
           'state','PREPARED','prepared_final_revision_id',v_prepared_revision_id,
           'replacement_upload_id',v_replacement_upload.id,
           'replacement_projection_publication_id',v_replacement_publication.id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_context->'root_contexts'),
           'prepare_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_session.reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function public.weekly_source_correct_final_apply_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
