-- Isolated complete source proposal. No installation/runtime acceptance.
-- REVIEW ONLY: requires proposed schema/helpers and root-composed consumers.
create or replace function private.weekly_source_billing_movement_hash_v1(p_state jsonb)
returns bytea language plpgsql immutable set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if jsonb_typeof(p_state) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_state) k
    where k not in ('transition_id','nhsp_upload_row_id','expense_authority_generation_id','self_bill_report_row_id','vat_rounding_revision_id','invoice_window_cycle_id',
      'final_revision_id','finalisation_cycle_id','actual_client_id','candidate_id','contract_id','work_event_id','movement_role',
      'correction_unit_id','prior_movement_id','source_profile_kind','source_line_kind','source_facts','pay_vector','charge_vector',
      'total_pay_pence','total_pay_ex_vat','calculated_comparison_charge_pence','source_validation_charge_pence',
      'invoice_presentation_charge_pence','vat_rate_pct','vat_amount','total_inc_vat','price_check_result','price_check_fingerprint',
      'charge_acceptance_id','mapping_rate_policy_fingerprint','invoice_timesheet_id','vector')) then
    raise exception 'WEEKLY_SOURCE_BILLING_HASH_INPUT_INVALID' using errcode='22023';
  end if;
  -- Keep the existing domain and each old producer's exact JSON field set.
  -- Newly present origins are added by their producer, never by NULL backfill.
  return private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_BILLING_MOVEMENT_V1',p_state);
end;
$function$;

create or replace function private.weekly_source_invoice_movement_window_id_v1(p_movement_id uuid)
returns uuid language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare m public.weekly_source_billing_movements%rowtype; target uuid;
begin
  select * into strict m from public.weekly_source_billing_movements where id=p_movement_id;
  target:=case when m.source_line_kind='INVOICE_VAT_ROUNDING' then coalesce(m.invoice_window_cycle_id,m.finalisation_cycle_id)
    when m.source_line_kind='SOURCE_INVOICE_CORRECTION' and m.movement_role in ('REVERSAL','REPLACEMENT')
      then nullif(m.source_facts_json->>'invoice_window_cycle_id','')::uuid else m.finalisation_cycle_id end;
  if target is null or not exists(select 1 from public.weekly_source_cycles actual join public.weekly_source_cycles original
    on original.id=m.finalisation_cycle_id and actual.source_group_id=original.source_group_id
    where actual.id=target and (actual.scope_client_id is null or actual.scope_client_id=m.actual_client_id)) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVEMENT_WINDOW_INVALID' using errcode='55000'; end if;
  return target;
end;
$function$;

create or replace function private.weekly_source_invoice_correction_insert_v1(p_transition_id uuid,p_work_event_id uuid,p_final_revision_id uuid)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare t public.weekly_source_state_transitions%rowtype; revision public.weekly_source_final_revisions%rowtype;
  current_line public.weekly_source_final_snapshot_lines%rowtype; prior_line public.weekly_source_final_snapshot_lines%rowtype;
  base public.weekly_source_billing_movements%rowtype; rules jsonb; amounts jsonb; cycle_id uuid; window_cycle uuid;
  adjustment_net bigint; adjustment_vat bigint; net bigint; vat bigint; gross bigint; v_role text; pair_id uuid:=gen_random_uuid(); base_money jsonb;
  facts jsonb; v_invoice_window_scope jsonb; pay_vector jsonb; charge_vector jsonb; h bytea; ids uuid[]:='{}'::uuid[]; id uuid; existing_count integer;
begin
  select * into strict t from public.weekly_source_state_transitions where weekly_source_state_transitions.id=p_transition_id;
  select * into strict revision from public.weekly_source_final_revisions where weekly_source_final_revisions.id=p_final_revision_id;
  if t.final_revision_id<>revision.id or t.work_event_id<>p_work_event_id or t.outcome<>'NO_CHANGE'
    or t.source_profile_kind<>'HEALTHROSTER_ACTUAL_ROWS' or revision.state not in ('CURRENT','PREPARED') then
    raise exception 'WEEKLY_SOURCE_INVOICE_CORRECTION_SCOPE_INVALID' using errcode='55000'; end if;
  rules:=private.weekly_source_frozen_rule_values_v1(revision.id);
  if rules is null or rules->>'invoice_sender'<>'CLIENT_SELF_BILL' or rules->>'invoice_amount_basis'<>'SOURCE_AMOUNT'
    or rules->>'invoice_membership'<>'FINALISED_IN_CYCLE_WINDOW' then return jsonb_build_object('movement_count',0); end if;
  select * into strict current_line from public.weekly_source_final_snapshot_lines where weekly_source_final_snapshot_lines.id=t.new_snapshot_line_id;
  select * into strict prior_line from public.weekly_source_final_snapshot_lines where weekly_source_final_snapshot_lines.id=t.previous_snapshot_line_id;
  if current_line.invoice_economics_sha256 is null or current_line.invoice_economics_sha256 is not distinct from prior_line.invoice_economics_sha256 then
    return jsonb_build_object('movement_count',0); end if;
  select array_agg(m.id order by m.movement_role),count(*) into ids,existing_count from public.weekly_source_billing_movements m
    where m.transition_id=t.id and m.source_line_kind='SOURCE_INVOICE_CORRECTION' and m.movement_role in ('REVERSAL','REPLACEMENT');
  if existing_count=2 then return jsonb_build_object('movement_count',0,'idempotent',true,'movement_ids',to_jsonb(ids));
  elsif existing_count<>0 then raise exception 'WEEKLY_SOURCE_INVOICE_CORRECTION_PARTIAL_PAIR' using errcode='55000'; end if;
  cycle_id:=revision.source_cycle_id;
  window_cycle:=private.weekly_source_invoice_window_cycle_v1(current_line.upload_row_id,
    (select source_group_id from public.weekly_source_cycles where weekly_source_cycles.id=cycle_id));
  if window_cycle is null then return jsonb_build_object('movement_count',0,'information_code','SOURCE_AMOUNT_CHANGED_OUTSIDE_SELF_BILL_WINDOW'); end if;
  -- The movement retains the actual Source revision/cycle. Only its immutable
  -- invoice membership witness identifies another real OPEN client window.
  v_invoice_window_scope:=private.weekly_source_invoice_window_scope_v1(
    cycle_id,current_line.client_id,current_line.upload_row_id,window_cycle);
  amounts:=private.weekly_source_invoice_line_amounts_v1(current_line.row_resolution_id,revision.id);
  select m.* into base from public.weekly_source_billing_movements m
    join public.weekly_source_final_revisions r on r.id=m.final_revision_id and r.state='CURRENT'
    join public.weekly_source_cycles c on c.id=m.finalisation_cycle_id
    where m.work_event_id=p_work_event_id and m.movement_role in ('POSITIVE','REPLACEMENT')
      and m.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT') and m.placement_state<>'VOIDED_BY_CORRECT_FINAL'
      and c.source_group_id=(select source_group_id from public.weekly_source_cycles where weekly_source_cycles.id=cycle_id)
      and m.actual_client_id=current_line.client_id
    order by c.finalisation_week_ending desc,r.finalised_at_utc desc,m.created_at_utc desc,m.id desc limit 1;
  if not found then raise exception 'WEEKLY_SOURCE_INVOICE_CORRECTION_BASE_MISSING' using errcode='55000'; end if;
  base_money:=private.weekly_source_invoice_movement_money_v1(base.id);
  select coalesce(sum(m.invoice_presentation_charge_pence),0)::bigint,coalesce(sum((private.weekly_source_invoice_movement_money_v1(m.id)->>'vat_pence')::numeric),0)::bigint into adjustment_net,adjustment_vat
    from public.weekly_source_billing_movements m join public.weekly_source_final_revisions r on r.id=m.final_revision_id and r.state='CURRENT'
    join public.weekly_source_cycles c on c.id=m.finalisation_cycle_id
    where m.work_event_id=p_work_event_id and m.source_line_kind='SOURCE_INVOICE_CORRECTION' and m.placement_state<>'VOIDED_BY_CORRECT_FINAL'
      and c.source_group_id=(select source_group_id from public.weekly_source_cycles where weekly_source_cycles.id=cycle_id) and m.actual_client_id=current_line.client_id;
  pay_vector:=private.weekly_source_invoice_only_vector_v1('PAY',0); ids:='{}'::uuid[];
  foreach v_role in array array['REVERSAL','REPLACEMENT'] loop
    net:=case when v_role='REVERSAL' then -(base.invoice_presentation_charge_pence+adjustment_net) else (amounts->>'net_pence')::bigint end;
    vat:=case when v_role='REVERSAL' then -((base_money->>'vat_pence')::bigint+adjustment_vat) else (amounts->>'vat_pence')::bigint end; gross:=net+vat;
    facts:=jsonb_build_object('schema_version','WEEKLY_SOURCE_INVOICE_CORRECTION_FACTS_V1','snapshot_line_id',current_line.id,
      'prior_snapshot_line_id',prior_line.id,'upload_row_id',current_line.upload_row_id,'bound_row_resolution_id',current_line.row_resolution_id,
      'rule_set_version_id',revision.rule_set_version_id,'invoice_economics_sha256',encode(current_line.invoice_economics_sha256,'hex'),
      'hold_release_id',case when v_role='REPLACEMENT' then amounts->'hold_release_id' else 'null'::jsonb end,
      'invoice_hold',case when v_role='REPLACEMENT' then amounts->'invoice_hold' else 'null'::jsonb end,'invoice_window_cycle_id',window_cycle,'invoice_window_scope',v_invoice_window_scope,
      'correction_presentation','FULL_REVERSAL_REPLACEMENT');
    charge_vector:=private.weekly_source_invoice_only_vector_v1('CHARGE',net);
    h:=private.weekly_source_billing_movement_hash_v1(jsonb_build_object('transition_id',t.id,'final_revision_id',revision.id,
      'finalisation_cycle_id',cycle_id,'actual_client_id',base.actual_client_id,'candidate_id',base.candidate_id,
      'contract_id',base.contract_id,'work_event_id',p_work_event_id,'movement_role',v_role,'correction_unit_id',pair_id,
      'prior_movement_id',base.id,'source_profile_kind',t.source_profile_kind,'source_line_kind','SOURCE_INVOICE_CORRECTION',
      'source_facts',facts,'pay_vector',pay_vector,'charge_vector',charge_vector,'total_pay_pence',0,
      'calculated_comparison_charge_pence',0,'source_validation_charge_pence',net,'invoice_presentation_charge_pence',net,
      'vat_rate_pct',(amounts->>'vat_rate_pct')::numeric,'vat_amount',vat::numeric/100,'total_inc_vat',gross::numeric/100,
      'price_check_result','NOT_APPLICABLE','price_check_fingerprint',null,'charge_acceptance_id',null,
      'mapping_rate_policy_fingerprint',encode(base.mapping_rate_policy_fingerprint,'hex'),'invoice_timesheet_id',base.invoice_timesheet_id));
    insert into public.weekly_source_billing_movements(transition_id,final_revision_id,finalisation_cycle_id,actual_client_id,candidate_id,contract_id,work_event_id,
      movement_role,correction_unit_id,prior_movement_id,source_profile_kind,source_line_kind,source_facts_json,canonical_pay_vector_json,canonical_charge_vector_json,
      total_pay_ex_vat,calculated_comparison_charge_pence,source_validation_charge_pence,invoice_presentation_charge_pence,vat_rate_pct,vat_amount,total_inc_vat,
      price_check_result,mapping_rate_policy_fingerprint,invoice_timesheet_id,original_cycle_key,movement_economic_hash)
    values(t.id,revision.id,cycle_id,base.actual_client_id,base.candidate_id,base.contract_id,p_work_event_id,v_role,pair_id,base.id,t.source_profile_kind,
      'SOURCE_INVOICE_CORRECTION',facts,pay_vector,charge_vector,0,0,net,net,(amounts->>'vat_rate_pct')::numeric,vat::numeric/100,gross::numeric/100,
      'NOT_APPLICABLE',base.mapping_rate_policy_fingerprint,base.invoice_timesheet_id,cycle_id::text,h) returning public.weekly_source_billing_movements.id into id;
    ids:=array_append(ids,id);
  end loop;
  return jsonb_build_object('movement_count',2,'movement_ids',to_jsonb(ids));
end;
$function$;

create or replace function private.weekly_source_vat_rounding_movement_insert_v1(p_final_revision_id uuid,p_client_id uuid,p_identity_movement_id uuid,p_invoice_window_cycle_id uuid)
returns uuid language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare revision public.weekly_source_final_revisions%rowtype; identity_row public.weekly_source_billing_movements%rowtype;
  rules jsonb; net numeric; vat numeric; rate numeric; target numeric; difference bigint; rate_count integer;
  id uuid; pending_hold_rows uuid[]; facts jsonb; pay jsonb; charge jsonb; mapping bytea; h bytea; profile text;
begin
  select * into strict revision from public.weekly_source_final_revisions where weekly_source_final_revisions.id=p_final_revision_id;
  rules:=private.weekly_source_frozen_rule_values_v1(revision.id);
  if rules is null or rules->>'invoice_sender'<>'CLIENT_SELF_BILL' or rules->>'invoice_vat_method'='SUM_OF_LINES' then return null; end if;
  if p_invoice_window_cycle_id is null or not exists(select 1 from public.weekly_source_cycles actual
    join public.weekly_source_cycles original on original.id=revision.source_cycle_id and actual.source_group_id=original.source_group_id
    where actual.id=p_invoice_window_cycle_id and (actual.scope_client_id is null or actual.scope_client_id=p_client_id)) then
    raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_WINDOW_INVALID' using errcode='55000'; end if;
  if revision.state not in ('CURRENT','PREPARED') or p_client_id is null then raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_SCOPE_INVALID' using errcode='55000'; end if;
  select m.id into id from public.weekly_source_billing_movements m where m.vat_rounding_revision_id=revision.id and m.actual_client_id=p_client_id
    and coalesce(m.invoice_window_cycle_id,m.finalisation_cycle_id)=p_invoice_window_cycle_id;
  if found then return id; end if;
  select coalesce(sum(m.invoice_presentation_charge_pence),0),coalesce(sum(m.vat_amount*100),0),min(m.vat_rate_pct),count(distinct m.vat_rate_pct),min(m.source_profile_kind)
    into net,vat,rate,rate_count,profile from public.weekly_source_billing_movements m
    where m.final_revision_id=revision.id and m.actual_client_id=p_client_id and m.source_line_kind<>'INVOICE_VAT_ROUNDING'
      and private.weekly_source_invoice_movement_window_id_v1(m.id)=p_invoice_window_cycle_id;
  if rate_count=0 then return null; end if;
  if rate_count<>1 or profile not in ('SELF_BILL_REPORT','HEALTHROSTER_ACTUAL_ROWS','GENERIC_COMPLETE_SNAPSHOT') then
    raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_RATE_AMBIGUOUS' using errcode='55000'; end if;
  target:=private.weekly_source_invoice_vat_target_pence_v1(net,vat,rules->>'invoice_vat_method',rate);
  if target is null then raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_METHOD_INVALID' using errcode='55000'; end if;
  select array_agg(distinct s.id order by s.id) into pending_hold_rows
    from public.weekly_source_billing_movements m join public.weekly_source_upload_rows s
      on s.id::text=m.source_facts_json->>'upload_row_id'
    where m.final_revision_id=revision.id and m.actual_client_id=p_client_id
      and private.weekly_source_invoice_movement_window_id_v1(m.id)=p_invoice_window_cycle_id
      and m.source_facts_json->>'invoice_hold'='VAT_FIT'
;
  difference:=(target-vat)::bigint;
  -- This proposed zero authority is restricted to unresolved actual VAT_FIT.
  -- D0 with no hold (including Report210825) retains no movement/visible line.
  if difference=0 and pending_hold_rows is null then return null; end if;
  if p_identity_movement_id is not null then
    select * into strict identity_row from public.weekly_source_billing_movements where weekly_source_billing_movements.id=p_identity_movement_id;
    if identity_row.final_revision_id<>revision.id or identity_row.actual_client_id<>p_client_id
      or identity_row.source_line_kind='INVOICE_VAT_ROUNDING' or identity_row.candidate_id is null
      or identity_row.contract_id is null or identity_row.work_event_id is null or identity_row.invoice_timesheet_id is null then
      raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_IDENTITY_INVALID' using errcode='55000'; end if;
  end if;
  -- The calling integration must select A(NULL) or B(real last line) only after
  -- hosted admission/render/pay-isolation proof. There is no UI/default choice.
  pay:=private.weekly_source_invoice_only_vector_v1('PAY',0); charge:=private.weekly_source_invoice_only_vector_v1('CHARGE',0);
  facts:=jsonb_build_object('schema_version','WEEKLY_SOURCE_VAT_ROUNDING_FACTS_V1','rule_set_version_id',revision.rule_set_version_id,
    'invoice_vat_method',rules->>'invoice_vat_method','membership_net_pence',net,
    'invoice_window_cycle_id',p_invoice_window_cycle_id,'pending_vat_fit_upload_row_ids',coalesce(to_jsonb(pending_hold_rows),'[]'::jsonb),'membership_vat_pence',vat,
    'target_vat_pence',target,'identity_movement_id',p_identity_movement_id,'description','VAT rounding (matches the client''s self-bill)');
  mapping:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_VAT_ROUNDING_V1',jsonb_build_object('rule_set_version_id',revision.rule_set_version_id));
  h:=private.weekly_source_billing_movement_hash_v1(jsonb_build_object('vat_rounding_revision_id',revision.id,'final_revision_id',revision.id,
    'finalisation_cycle_id',revision.source_cycle_id,'actual_client_id',p_client_id,'candidate_id',identity_row.candidate_id,'contract_id',identity_row.contract_id,
    'work_event_id',identity_row.work_event_id,'movement_role','POSITIVE','prior_movement_id',p_identity_movement_id,'source_profile_kind',profile,
    'source_line_kind','INVOICE_VAT_ROUNDING','source_facts',facts,'pay_vector',pay,'charge_vector',charge,'total_pay_pence',0,
    'calculated_comparison_charge_pence',0,'source_validation_charge_pence',null,'invoice_presentation_charge_pence',0,
    'vat_rate_pct',rate,'vat_amount',difference::numeric/100,'total_inc_vat',difference::numeric/100,'price_check_result','NOT_APPLICABLE',
    'price_check_fingerprint',null,'charge_acceptance_id',null,'mapping_rate_policy_fingerprint',encode(mapping,'hex'),'invoice_timesheet_id',identity_row.invoice_timesheet_id)
    ||case when p_invoice_window_cycle_id=revision.source_cycle_id then '{}'::jsonb else jsonb_build_object('invoice_window_cycle_id',p_invoice_window_cycle_id) end);
  insert into public.weekly_source_billing_movements(vat_rounding_revision_id,invoice_window_cycle_id,final_revision_id,finalisation_cycle_id,actual_client_id,candidate_id,contract_id,work_event_id,
    movement_role,prior_movement_id,source_profile_kind,source_line_kind,source_facts_json,canonical_pay_vector_json,canonical_charge_vector_json,
    total_pay_ex_vat,calculated_comparison_charge_pence,invoice_presentation_charge_pence,vat_rate_pct,vat_amount,total_inc_vat,
    price_check_result,mapping_rate_policy_fingerprint,invoice_timesheet_id,original_cycle_key,movement_economic_hash)
  values(revision.id,case when p_invoice_window_cycle_id=revision.source_cycle_id then null else p_invoice_window_cycle_id end,revision.id,revision.source_cycle_id,p_client_id,identity_row.candidate_id,identity_row.contract_id,identity_row.work_event_id,
    'POSITIVE',p_identity_movement_id,profile,'INVOICE_VAT_ROUNDING',facts,pay,charge,0,0,0,rate,difference::numeric/100,difference::numeric/100,
    'NOT_APPLICABLE',mapping,identity_row.invoice_timesheet_id,revision.source_cycle_id::text,h) returning public.weekly_source_billing_movements.id into id;
  return id;
end;
$function$;

create or replace function private.weekly_source_vat_rounding_movement_insert_v1(p_final_revision_id uuid,p_client_id uuid,p_identity_movement_id uuid)
returns uuid language sql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$ select private.weekly_source_vat_rounding_movement_insert_v1(p_final_revision_id,p_client_id,p_identity_movement_id,
  (select source_cycle_id from public.weekly_source_final_revisions where id=p_final_revision_id)); $function$;


-- Isolated complete source proposal. No installation/runtime acceptance.
-- REVIEW ONLY. Owner-private proposals; no service/browser grants or RPC mount.
-- Native rounding insert and receipt projection must share this one S09 target.
create or replace function private.weekly_source_invoice_vat_target_pence_v1(
  p_net_pence numeric,p_line_vat_pence numeric,p_method text,p_rate_pct numeric
) returns bigint language plpgsql immutable set search_path to 'pg_catalog','pg_temp'
as $function$
begin
  if p_net_pence is null or p_line_vat_pence is null or p_rate_pct is null
    or p_net_pence<>trunc(p_net_pence) or p_line_vat_pence<>trunc(p_line_vat_pence)
    or p_rate_pct<0 or p_rate_pct>100 then
    raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_MONEY_INVALID' using errcode='22023'; end if;
  return case p_method when 'SUM_OF_LINES' then p_line_vat_pence::bigint
    when 'ONCE_ON_TOTAL_HALF_UP' then round(p_net_pence*p_rate_pct/100)::bigint
    when 'ONCE_ON_TOTAL_TRUNCATE' then trunc(p_net_pence*p_rate_pct/100)::bigint
    else null end;
end;
$function$;

-- A production caller must lock the whole discovered actual cycle set after
-- I-1 and group, capture this witness BEFORE insertion, and use its immutable
-- fields for later admission/issue. Current state is initial admission only.
create or replace function private.weekly_source_invoice_window_scope_v1(
  p_source_cycle_id uuid,p_client_id uuid,p_upload_row_id uuid,p_window_cycle_id uuid
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare source_cycle public.weekly_source_cycles%rowtype; invoice_cycle public.weekly_source_cycles%rowtype;
  source_row public.weekly_source_upload_rows%rowtype; previous_cutoff timestamptz; result jsonb;
begin
  select * into strict source_cycle from public.weekly_source_cycles where id=p_source_cycle_id;
  select * into strict invoice_cycle from public.weekly_source_cycles where id=p_window_cycle_id;
  select * into strict source_row from public.weekly_source_upload_rows where id=p_upload_row_id;
  if p_client_id is null or invoice_cycle.source_group_id<>source_cycle.source_group_id
    or (invoice_cycle.scope_client_id is not null and invoice_cycle.scope_client_id<>p_client_id)
    or invoice_cycle.state not in ('OPEN','FINALISABLE','FINALISING')
    or not exists(select 1 from public.weekly_source_group_clients member
      where member.source_group_id=invoice_cycle.source_group_id and member.client_id=p_client_id
        and invoice_cycle.finalisation_week_ending between member.valid_from and coalesce(member.valid_to,'infinity'::date)) then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SCOPE_INVALID' using errcode='55000'; end if;
  if not exists(select 1 from public.weekly_source_uploads upload
    join public.weekly_source_projection_publications publication on publication.upload_id=upload.id
      and publication.source_cycle_id=source_cycle.id and publication.authority_scope_kind='CYCLE'
      and publication.report_scope_id is null and publication.state in ('CURRENT','CORRECTION_READY')
    join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source_row.id
      and resolution.generation=coalesce(publication.projection_generation,publication.authority_scope_version)
      and resolution.client_id=p_client_id and resolution.mapping_state='RESOLVED'
    join public.weekly_work_events event on event.id=resolution.work_event_id and event.client_id=p_client_id
      and event.first_source_group_id=source_cycle.source_group_id and event.work_date=source_row.work_date
    where upload.id=source_row.upload_id and upload.source_cycle_id=source_cycle.id and upload.report_scope_id is null
      and upload.state in ('CURRENT','CORRECTION_READY')) then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SOURCE_SCOPE_INVALID' using errcode='55000'; end if;
  select max(previous.cutoff_at_utc) into previous_cutoff from public.weekly_source_cycles previous
    where previous.source_group_id=invoice_cycle.source_group_id and previous.cutoff_at_utc<invoice_cycle.cutoff_at_utc;
  previous_cutoff:=coalesce(previous_cutoff,((invoice_cycle.cutoff_at_utc at time zone 'Europe/London')-interval '7 days') at time zone 'Europe/London');
  if source_row.finalised_at_utc is null or nullif(btrim(source_row.finalised_by),'') is null
    or source_row.work_date>invoice_cycle.finalisation_week_ending
    or source_row.finalised_at_utc<=previous_cutoff or source_row.finalised_at_utc>invoice_cycle.cutoff_at_utc then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_TIMESTAMP_INVALID' using errcode='55000'; end if;
  result:=jsonb_build_object('contract','WEEKLY_SOURCE_INVOICE_WINDOW_SCOPE_V1','source_cycle_id',source_cycle.id,
    'invoice_window_cycle_id',invoice_cycle.id,'invoice_window_version',invoice_cycle.version,
    'source_group_id',invoice_cycle.source_group_id,'actual_client_id',p_client_id,
    'invoice_week_ending',invoice_cycle.finalisation_week_ending,'window_previous_cutoff_at_utc',previous_cutoff,
    'window_cutoff_at_utc',invoice_cycle.cutoff_at_utc,'upload_row_id',source_row.id,
    'source_row_hash',encode(source_row.normalised_row_hash,'hex'),'finalised_at_utc',source_row.finalised_at_utc);
  return result||jsonb_build_object('scope_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_WINDOW_SCOPE_V1',result),'hex'));
end;
$function$;

-- Input is a complete closed UUID/null map, not caller money. ADMIT builds it
-- from actual immutable receipts under its existing locks; history passes the
-- exact map frozen in the admitted presentation, not a latest receipt lookup.
create or replace function private.weekly_source_invoice_rounding_receipt_set_v1(
  p_client_manifest_id uuid,p_receipt_set jsonb
) returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare manifest public.weekly_source_client_manifests%rowtype; rounding public.weekly_source_billing_movements%rowtype;
  member record; item jsonb; receipt_id uuid; money jsonb; rules jsonb; facts jsonb;
  witness jsonb:='[]'::jsonb; net numeric:=0; raw_vat numeric:=0; admitted_vat numeric:=0;
  target bigint; raw_target bigint; actual_count integer:=0; supplied_count integer; rate_count integer; rate numeric;
begin
  select * into strict manifest from public.weekly_source_client_manifests where id=p_client_manifest_id;
  rules:=private.weekly_source_frozen_rule_values_v1(manifest.final_revision_id);
  if rules is null or rules->>'invoice_sender' is distinct from 'CLIENT_SELF_BILL'
    or rules->>'invoice_vat_method'='SUM_OF_LINES' then return null; end if;
  if jsonb_typeof(p_receipt_set) is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_INVALID' using errcode='22023'; end if;
  supplied_count:=jsonb_array_length(p_receipt_set);
  if exists(select 1 from jsonb_array_elements(p_receipt_set) supplied where jsonb_typeof(supplied)<>'object'
      or not(supplied ?& array['billing_movement_id','invoice_hold_release_id'])
      or jsonb_typeof(supplied->'billing_movement_id') is distinct from 'string'
      or not pg_input_is_valid(coalesce(supplied->>'billing_movement_id',''),'uuid')
      or (supplied->'invoice_hold_release_id'<>'null'::jsonb and (jsonb_typeof(supplied->'invoice_hold_release_id') is distinct from 'string'
        or not pg_input_is_valid(coalesce(supplied->>'invoice_hold_release_id',''),'uuid')))
      or exists(select 1 from jsonb_object_keys(supplied) key where key not in ('billing_movement_id','invoice_hold_release_id')))
    or (select count(distinct supplied->>'billing_movement_id') from jsonb_array_elements(p_receipt_set) supplied)<>supplied_count then
    raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_INVALID' using errcode='22023'; end if;
  select m.* into rounding from public.weekly_source_manifest_movements mm
    join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    where mm.client_manifest_id=manifest.id and m.source_line_kind='INVOICE_VAT_ROUNDING';

  for member in select m.*,mm.movement_hash from public.weekly_source_manifest_movements mm
    join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    where mm.client_manifest_id=manifest.id and m.source_line_kind<>'INVOICE_VAT_ROUNDING' order by m.id
  loop
    actual_count:=actual_count+1;
    if member.final_revision_id<>manifest.final_revision_id or member.finalisation_cycle_id<>manifest.source_cycle_id
      or member.actual_client_id<>manifest.client_id or member.movement_hash<>member.movement_economic_hash
      or private.weekly_source_invoice_movement_window_id_v1(member.id)<>coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id) then
      raise exception 'WEEKLY_SOURCE_ROUNDING_MANIFEST_INVALID' using errcode='55000'; end if;
    select supplied into item from jsonb_array_elements(p_receipt_set) supplied where supplied->>'billing_movement_id'=member.id::text;
    if not found then raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_CENSUS_INVALID' using errcode='55000'; end if;
    receipt_id:=nullif(item->>'invoice_hold_release_id','')::uuid;
    if receipt_id is null then
      -- Explicit original money: never use the implicit CURRENT-presentation
      -- branch of movement_money_v1 for a null frozen receipt-map entry.
      money:=jsonb_build_object('net_pence',member.invoice_presentation_charge_pence,
        'vat_pence',(member.vat_amount*100)::bigint,'gross_pence',(member.total_inc_vat*100)::bigint,'release_authority',null);
    else money:=private.weekly_source_invoice_movement_money_v1(member.id,receipt_id); end if;
    if (money->>'net_pence')::bigint<>member.invoice_presentation_charge_pence
      or (money->>'gross_pence')::bigint<>(money->>'net_pence')::bigint+(money->>'vat_pence')::bigint then
      raise exception 'WEEKLY_SOURCE_ROUNDING_RELEASE_MONEY_INVALID' using errcode='55000'; end if;
    net:=net+member.invoice_presentation_charge_pence; raw_vat:=raw_vat+member.vat_amount*100;
    admitted_vat:=admitted_vat+(money->>'vat_pence')::numeric;
    witness:=witness||jsonb_build_array(jsonb_build_object('billing_movement_id',member.id,
      'movement_hash',encode(member.movement_economic_hash,'hex'),'invoice_hold_release_id',receipt_id,
      'release_authority',money->'release_authority','net_pence',member.invoice_presentation_charge_pence,
      'original_vat_pence',(member.vat_amount*100)::bigint,'admitted_vat_pence',(money->>'vat_pence')::bigint));
  end loop;
  if actual_count<>supplied_count then raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_SET_CENSUS_INVALID' using errcode='55000'; end if;
  select min(m.vat_rate_pct),count(distinct m.vat_rate_pct) into rate,rate_count
    from public.weekly_source_manifest_movements mm join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    where mm.client_manifest_id=manifest.id and m.source_line_kind<>'INVOICE_VAT_ROUNDING';
  if rate_count<>1 then raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_RATE_AMBIGUOUS' using errcode='55000'; end if;
  raw_target:=private.weekly_source_invoice_vat_target_pence_v1(net,raw_vat,rules->>'invoice_vat_method',rate);
  target:=private.weekly_source_invoice_vat_target_pence_v1(net,admitted_vat,rules->>'invoice_vat_method',rate);
  if rounding.id is null then
    if target is null or raw_target<>raw_vat or target<>admitted_vat
      or exists(select 1 from jsonb_array_elements(witness) w where (w->>'original_vat_pence')::bigint<>(w->>'admitted_vat_pence')::bigint) then
      raise exception 'WEEKLY_SOURCE_FROZEN_ROUNDING_AUTHORITY_REQUIRED' using errcode='55000'; end if;
    return null;
  end if;
  if target is null or (raw_target-raw_vat)::bigint<>(rounding.vat_amount*100)::bigint then
    raise exception 'WEEKLY_SOURCE_FROZEN_ROUNDING_AMOUNT_INVALID' using errcode='55000'; end if;
  facts:=jsonb_build_object('contract','WEEKLY_SOURCE_INVOICE_ROUNDING_AUTHORITY_V1','client_manifest_id',manifest.id,
    'manifest_hash',encode(manifest.manifest_hash,'hex'),'final_revision_id',manifest.final_revision_id,
    'actual_client_id',manifest.client_id,'invoice_window_cycle_id',coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id),
    'rounding_movement_id',rounding.id,'rounding_movement_hash',encode(rounding.movement_economic_hash,'hex'),
    'frozen_rule_set_version_id',(select r.rule_set_version_id from public.weekly_source_final_revisions r where r.id=manifest.final_revision_id),
    'frozen_rule_values_sha256',(select v.values_sha256 from public.weekly_source_final_revisions r
      join public.weekly_source_rule_set_versions v on v.id=r.rule_set_version_id where r.id=manifest.final_revision_id),
    'invoice_vat_method',rules->>'invoice_vat_method','vat_rate_pct',rate,'membership_net_pence',net,
    'original_rounding_vat_pence',(rounding.vat_amount*100)::bigint,'admitted_line_vat_pence',admitted_vat,
    'target_vat_pence',target,'admitted_rounding_vat_pence',target-admitted_vat,'member_witnesses',witness,
    'suppress_visible_rounding_line',target-admitted_vat=0);
  return facts||jsonb_build_object('authority_sha256',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_ROUNDING_AUTHORITY_V1',facts),'hex'));
end;
$function$;

-- Doc/model qualification runs after the accepted complete allocation successor.
-- Allocation uses receipt_set_v1 directly, never this helper (no recursion).
create or replace function private.weekly_source_invoice_rounding_suppression_witness_v1(p_invoice_line_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare line public.invoice_lines%rowtype; presentation public.weekly_source_invoice_presentation_lines%rowtype;
  movement public.weekly_source_billing_movements%rowtype; authority jsonb; rebuilt jsonb; receipt_map jsonb;
  binding_count integer; original_hash bytea; disposition text;
begin
  select * into strict line from public.invoice_lines where id=p_invoice_line_id;
  disposition:=line.meta_json->>'presentation_disposition';
  if disposition is distinct from 'SUPPRESS_ZERO_ROUNDING_AUTHORITY' then return null; end if;
  -- Full native invoice lineage, money, source-hash and cardinality validation
  -- must succeed before a document/model can suppress any source line.
  perform private.weekly_source_invoice_allocation_assert_v1(line.invoice_id);
  select count(*) into binding_count from public.weekly_source_invoice_line_bindings b
    where b.invoice_line_id=line.id and b.invoice_id=line.invoice_id and b.state='CURRENT';
  if binding_count<>1 then raise exception 'WEEKLY_SOURCE_ZERO_ROUNDING_SUPPRESSION_INVALID' using errcode='55000'; end if;
  select p.* into strict presentation from public.weekly_source_invoice_line_bindings b
    join public.weekly_source_invoice_presentation_lines p on p.id=b.presentation_line_id
    where b.invoice_line_id=line.id and b.state='CURRENT';
  select m.* into strict movement from public.weekly_source_invoice_line_bindings b
    join public.weekly_source_billing_movements m on m.id=b.billing_movement_id
    where b.invoice_line_id=line.id and b.state='CURRENT';
  authority:=presentation.invoice_rounding_authority_json;
  if movement.source_line_kind<>'INVOICE_VAT_ROUNDING' or movement.vat_rounding_revision_id<>movement.final_revision_id
    or presentation.line_kind<>'INVOICE_VAT_ROUNDING' or presentation.origin_kind<>'INVOICE_VAT_ROUNDING'
    or movement.total_pay_ex_vat<>0 or movement.invoice_presentation_charge_pence<>0
    or line.total_pay_ex_vat<>0 or line.total_charge_ex_vat<>0 or line.vat_amount<>0 or line.total_inc_vat<>0
    or presentation.total_pay_ex_vat<>0 or presentation.total_charge_ex_vat<>0 or presentation.vat_amount<>0 or presentation.total_inc_vat<>0
    or coalesce(line.hours_day,0)<>0 or coalesce(line.hours_night,0)<>0 or coalesce(line.hours_sat,0)<>0 or coalesce(line.hours_sun,0)<>0 or coalesce(line.hours_bh,0)<>0
    or coalesce(presentation.hours_day,0)<>0 or coalesce(presentation.hours_night,0)<>0 or coalesce(presentation.hours_sat,0)<>0 or coalesce(presentation.hours_sun,0)<>0 or coalesce(presentation.hours_bh,0)<>0
    or authority->>'contract' is distinct from 'WEEKLY_SOURCE_INVOICE_ROUNDING_AUTHORITY_V1'
    or authority->'suppress_visible_rounding_line' is distinct from 'true'::jsonb
    or line.meta_json->'weekly_source_rounding_authority' is distinct from authority then
    raise exception 'WEEKLY_SOURCE_ZERO_ROUNDING_SUPPRESSION_INVALID' using errcode='55000'; end if;
  select jsonb_agg(jsonb_build_object('billing_movement_id',member->'billing_movement_id',
    'invoice_hold_release_id',member->'invoice_hold_release_id') order by member->>'billing_movement_id') into receipt_map
    from jsonb_array_elements(authority->'member_witnesses') member;
  rebuilt:=private.weekly_source_invoice_rounding_receipt_set_v1(presentation.client_manifest_id,receipt_map);
  original_hash:=private.weekly_source_invoice_presentation_source_hash_v1(array[movement.id],null);
  if rebuilt is distinct from authority or presentation.source_hash is distinct from private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_INVOICE_ROUNDING_PRESENTATION_V1',jsonb_build_object('original_movement_source_hash',encode(original_hash,'hex'),
      'rounding_authority_sha256',authority->>'authority_sha256')) then
    raise exception 'WEEKLY_SOURCE_ZERO_ROUNDING_SUPPRESSION_INVALID' using errcode='55000'; end if;
  return jsonb_build_object('contract','WEEKLY_SOURCE_ZERO_ROUNDING_SUPPRESSION_V1','invoice_id',line.invoice_id,
    'invoice_line_id',line.id,'presentation_line_id',presentation.id,'presentation_hash',encode(presentation.presentation_hash,'hex'),
    'source_hash',encode(presentation.source_hash,'hex'),'rounding_authority_sha256',authority->>'authority_sha256',
    'total_pay_pence',0,'net_pence',0,'vat_pence',0,'gross_pence',0);
end;
$function$;

-- Root must compile all four, owner-map and revoke PUBLIC/anon/authenticated/
-- service_role after acceptance. These drafts deliberately mount no service RPC.


-- Owner-private complete proposed helpers. No caller money/config/activation.
create or replace function private.weekly_source_invoice_legacy_render_support_v1(p_invoice_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare suppressed jsonb; receipts jsonb;
begin
  select jsonb_agg(private.weekly_source_invoice_rounding_suppression_witness_v1(line.id) order by line.id)
    into suppressed from public.invoice_lines line where line.invoice_id=p_invoice_id
      and line.meta_json->>'presentation_disposition'='SUPPRESS_ZERO_ROUNDING_AUTHORITY';
  receipts:=private.weekly_source_invoice_receipt_support_v1(p_invoice_id);
  return case when suppressed is null then '{}'::jsonb else jsonb_build_object('source_rounding_suppressions',suppressed) end
    ||case when receipts is null then '{}'::jsonb else jsonb_build_object('source_invoice_receipt_support',receipts) end;
end;
$function$;

create or replace function private.weekly_source_invoice_window_lock_inventory_v1(
  p_upload_id uuid,p_generation bigint,p_source_cycle_id uuid,p_client_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare source_cycle public.weekly_source_cycles%rowtype; rules jsonb;
  v_record record; target uuid; ids uuid[]; windows jsonb; witnesses jsonb:='[]'::jsonb;
begin
  select * into strict source_cycle from public.weekly_source_cycles where id=p_source_cycle_id;
  if not exists(select 1 from public.weekly_source_uploads upload where upload.id=p_upload_id
    and upload.source_cycle_id=source_cycle.id) then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_UPLOAD_SCOPE_INVALID' using errcode='55000'; end if;
  ids:=array[source_cycle.id];
  rules:=private.weekly_source_effective_rule_set_v1(p_client_id,source_cycle.id)->'values';
  if rules is not null and rules->>'invoice_sender'='CLIENT_SELF_BILL'
    and rules->>'invoice_amount_basis'='SOURCE_AMOUNT'
    and rules->>'invoice_membership'='FINALISED_IN_CYCLE_WINDOW'
    and rules->>'self_bill_source'='SAME_FILE' then
    for v_record in select source_row.*,resolution.id resolution_id,resolution.work_event_id,
        resolution.client_id,resolution.contract_id from public.weekly_source_upload_rows source_row
      join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source_row.id
        and resolution.generation=p_generation where source_row.upload_id=p_upload_id
      order by source_row.id
    loop
      if v_record.client_id is distinct from p_client_id then
        raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_CLIENT_INVALID' using errcode='55000'; end if;
      target:=private.weekly_source_invoice_window_cycle_v1(v_record.id,source_cycle.source_group_id);
      if target is not null then
        if not(target=any(ids)) then ids:=array_append(ids,target); end if;
        witnesses:=witnesses||jsonb_build_array(jsonb_build_object('upload_row_id',v_record.id,
          'row_hash',encode(v_record.normalised_row_hash,'hex'),'resolution_id',v_record.resolution_id,
          'work_event_id',v_record.work_event_id,'client_id',v_record.client_id,'contract_id',v_record.contract_id,
          'invoice_window_scope',private.weekly_source_invoice_window_scope_v1(source_cycle.id,v_record.client_id,v_record.id,target)));
      end if;
    end loop;
  end if;
  select jsonb_object_agg(cycle.id::text,to_jsonb(cycle) order by cycle.id) into windows
    from public.weekly_source_cycles cycle where cycle.id=any(ids);
  if (select count(*) from jsonb_object_keys(windows))<>cardinality(ids) then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_INVALID' using errcode='55000'; end if;
  return jsonb_build_object('contract','WEEKLY_SOURCE_INVOICE_WINDOW_LOCK_INVENTORY_V1',
    'source_cycle_id',source_cycle.id,'upload_id',p_upload_id,'generation',p_generation,
    'client_id',p_client_id,'cycles',windows,'row_window_witnesses',witnesses);
end;
$function$;

create or replace function private.weekly_source_invoice_receipt_support_v1(p_invoice_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare witnesses jsonb;
begin
  if not exists(select 1 from public.weekly_source_invoice_line_bindings b
    join public.weekly_source_invoice_presentation_lines p on p.id=b.presentation_line_id
    where b.invoice_id=p_invoice_id and b.state='CURRENT'
      and (p.invoice_rounding_authority_json is not null or p.invoice_hold_release_id is not null)) then return null; end if;
  perform private.weekly_source_invoice_allocation_assert_v1(p_invoice_id);
  select jsonb_agg(witness order by presentation_id) into witnesses from (
    select p.id presentation_id,jsonb_build_object('presentation_line_id',p.id,
      'presentation_hash',encode(p.presentation_hash,'hex'),'source_hash',encode(p.source_hash,'hex'),
      'client_manifest_id',p.client_manifest_id,'rounding_authority',p.invoice_rounding_authority_json,
      'invoice_hold_release_authority',private.weekly_source_invoice_presentation_release_authority_v1(
        array_agg(b.billing_movement_id order by b.billing_movement_id),p.invoice_hold_release_id),
      'billing_movement_ids',jsonb_agg(b.billing_movement_id order by b.billing_movement_id)) witness
      from public.weekly_source_invoice_line_bindings b join public.weekly_source_invoice_presentation_lines p on p.id=b.presentation_line_id
      where b.invoice_id=p_invoice_id and b.state='CURRENT'
        and (p.invoice_rounding_authority_json is not null or p.invoice_hold_release_id is not null)
      group by p.id
  ) exact;
  return jsonb_build_object('contract','WEEKLY_SOURCE_INVOICE_RECEIPT_SUPPORT_V1','invoice_id',p_invoice_id,
    'presentation_witnesses',witnesses,'support_sha256',encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_RECEIPT_SUPPORT_V1',witnesses),'hex'));
end;
$function$;

create or replace function private.weekly_source_invoice_window_cycle_v1(p_upload_row_id uuid,p_source_group_id uuid)
returns uuid language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_record public.weekly_source_upload_rows%rowtype; actual_client uuid; ids uuid[];
begin
  select * into strict v_record from public.weekly_source_upload_rows where id=p_upload_row_id;
  if v_record.finalised_at_utc is null then return null; end if;
  -- The exact saved active publication owns the generation; no latest-v_record pick.
  select resolution.client_id into strict actual_client from public.weekly_source_uploads upload
    join public.weekly_source_projection_publications publication on publication.upload_id=upload.id
      and publication.source_cycle_id=upload.source_cycle_id and publication.report_scope_id is null
      and publication.authority_scope_kind='CYCLE' and publication.state in ('CURRENT','CORRECTION_READY')
    join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=v_record.id
      and resolution.generation=coalesce(publication.projection_generation,publication.authority_scope_version)
    where upload.id=v_record.upload_id and upload.state in ('CURRENT','CORRECTION_READY');
  select array_agg(cycle.id order by cycle.id) into ids from public.weekly_source_cycles cycle
    where cycle.source_group_id=p_source_group_id and cycle.state in ('OPEN','FINALISABLE','FINALISING')
      and (cycle.scope_client_id is null or cycle.scope_client_id=actual_client)
      and v_record.work_date<=cycle.finalisation_week_ending and cycle.cutoff_at_utc>=v_record.finalised_at_utc
      and v_record.finalised_at_utc>coalesce((select max(prior.cutoff_at_utc) from public.weekly_source_cycles prior
        where prior.source_group_id=cycle.source_group_id and prior.cutoff_at_utc<cycle.cutoff_at_utc),
        ((cycle.cutoff_at_utc at time zone 'Europe/London')-interval '7 days') at time zone 'Europe/London');
  if cardinality(ids)>1 then select array_agg(cycle.id order by cycle.id) into ids
    from public.weekly_source_cycles cycle where cycle.id=any(ids) and cycle.scope_client_id=actual_client; end if;
  if cardinality(ids)>1 then raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_AMBIGUOUS' using errcode='55000'; end if;
  return ids[1];
end;
$function$;

create or replace function private.weekly_source_invoice_admission_receipt_map_v1(p_client_manifest_id uuid)
returns jsonb language sql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
  select coalesce(jsonb_agg(jsonb_build_object('billing_movement_id',m.id,'invoice_hold_release_id',receipt.id)
    order by m.id),'[]'::jsonb) from public.weekly_source_manifest_movements mm
  join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
  left join public.weekly_source_invoice_hold_releases receipt
    on receipt.upload_row_id::text=m.source_facts_json->>'upload_row_id' and receipt.hold_kind='VAT_FIT'
    and m.movement_role in ('POSITIVE','REPLACEMENT')
    and m.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
  where mm.client_manifest_id=p_client_manifest_id and m.source_line_kind<>'INVOICE_VAT_ROUNDING';
$function$;

create or replace function private.weekly_source_invoice_manifest_admission_money_v1(p_client_manifest_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare member record; authority jsonb; receipt_map jsonb; money jsonb;
  net numeric:=0; vat numeric:=0; gross numeric:=0;
begin
  receipt_map:=private.weekly_source_invoice_admission_receipt_map_v1(p_client_manifest_id);
  authority:=private.weekly_source_invoice_rounding_receipt_set_v1(p_client_manifest_id,receipt_map);
  for member in select m.*,supplied->>'invoice_hold_release_id' receipt_id
    from public.weekly_source_manifest_movements mm join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    left join lateral (select supplied from jsonb_array_elements(receipt_map) supplied where supplied->>'billing_movement_id'=m.id::text) receipt on true
    where mm.client_manifest_id=p_client_manifest_id order by m.id
  loop
    if member.source_line_kind='INVOICE_VAT_ROUNDING' and authority is not null then
      money:=jsonb_build_object('net_pence',0,'vat_pence',authority->'admitted_rounding_vat_pence','gross_pence',authority->'admitted_rounding_vat_pence');
    elsif member.receipt_id is not null then
      money:=private.weekly_source_invoice_movement_money_v1(member.id,member.receipt_id::uuid);
    else money:=jsonb_build_object('net_pence',member.invoice_presentation_charge_pence,
      'vat_pence',(member.vat_amount*100)::bigint,'gross_pence',(member.total_inc_vat*100)::bigint); end if;
    net:=net+(money->>'net_pence')::numeric;vat:=vat+(money->>'vat_pence')::numeric;gross:=gross+(money->>'gross_pence')::numeric;
  end loop;
  return jsonb_build_object('net_pence',net,'vat_pence',vat,'gross_pence',gross);
end;
$function$;

create or replace function private.weekly_source_invoice_rounding_authority_rebuild_v1(p_presentation_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_invoice_presentation_lines%rowtype; receipt_map jsonb; result jsonb;
begin
  select * into strict p from public.weekly_source_invoice_presentation_lines where id=p_presentation_id;
  if p.invoice_rounding_authority_json is null then return null; end if;
  if p.line_kind<>'INVOICE_VAT_ROUNDING' or p.origin_kind<>'INVOICE_VAT_ROUNDING'
    or jsonb_typeof(p.invoice_rounding_authority_json->'member_witnesses') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_ROUNDING_PRESENTATION_AUTHORITY_INVALID' using errcode='55000'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('billing_movement_id',w->'billing_movement_id',
    'invoice_hold_release_id',w->'invoice_hold_release_id') order by w->>'billing_movement_id'),'[]'::jsonb)
    into receipt_map from jsonb_array_elements(p.invoice_rounding_authority_json->'member_witnesses') w;
  result:=private.weekly_source_invoice_rounding_receipt_set_v1(p.client_manifest_id,receipt_map);
  if result is distinct from p.invoice_rounding_authority_json then
    raise exception 'WEEKLY_SOURCE_ROUNDING_PRESENTATION_AUTHORITY_INVALID' using errcode='55000'; end if;
  -- Every admitted witness must be tied to the exact original presentation of
  -- the actual member, including an explicit NULL original-money decision.
  if exists(select 1 from jsonb_array_elements(result->'member_witnesses') w
    where not exists(select 1 from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines original on original.id=binding.presentation_line_id
      where binding.billing_movement_id=(w->>'billing_movement_id')::uuid and binding.state='CURRENT'
        and original.client_manifest_id=p.client_manifest_id
        and original.invoice_hold_release_id is not distinct from nullif(w->>'invoice_hold_release_id','')::uuid)) then
    raise exception 'WEEKLY_SOURCE_ROUNDING_RECEIPT_PRESENTATION_SET_INVALID' using errcode='55000'; end if;
  return result;
end;
$function$;

create or replace function private.weekly_source_invoice_presentation_expected_source_hash_v1(p_presentation_id uuid)
returns bytea language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_invoice_presentation_lines%rowtype; ids uuid[]; original bytea; authority jsonb;
begin
  select * into strict p from public.weekly_source_invoice_presentation_lines where id=p_presentation_id;
  select array_agg(binding.billing_movement_id order by binding.billing_movement_id) into ids
    from public.weekly_source_invoice_line_bindings binding where binding.presentation_line_id=p.id and binding.state='CURRENT';
  original:=private.weekly_source_invoice_presentation_source_hash_v1(ids,p.invoice_hold_release_id);
  authority:=private.weekly_source_invoice_rounding_authority_rebuild_v1(p.id);
  if authority is null then return original; end if;
  return private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_ROUNDING_PRESENTATION_V1',
    jsonb_build_object('original_movement_source_hash',encode(original,'hex'),
      'rounding_authority_sha256',authority->>'authority_sha256'));
end;
$function$;

create or replace function private.weekly_source_invoice_admitted_member_money_v1(p_presentation_id uuid,p_movement_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare p public.weekly_source_invoice_presentation_lines%rowtype; m public.weekly_source_billing_movements%rowtype;
  authority jsonb; receipt public.weekly_source_invoice_hold_releases%rowtype;
begin
  select * into strict p from public.weekly_source_invoice_presentation_lines where id=p_presentation_id;
  select * into strict m from public.weekly_source_billing_movements where id=p_movement_id;
  if not exists(select 1 from public.weekly_source_invoice_line_bindings b where b.presentation_line_id=p.id
    and b.billing_movement_id=m.id and b.state='CURRENT') then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADMITTED_MEMBER_INVALID' using errcode='55000'; end if;
  authority:=private.weekly_source_invoice_rounding_authority_rebuild_v1(p.id);
  if authority is not null then
    if authority->>'rounding_movement_id' is distinct from m.id::text then
      raise exception 'WEEKLY_SOURCE_INVOICE_ROUNDING_MEMBER_INVALID' using errcode='55000'; end if;
    return jsonb_build_object('net_pence',0,'vat_pence',authority->'admitted_rounding_vat_pence','gross_pence',authority->'admitted_rounding_vat_pence');
  end if;
  if p.invoice_hold_release_id is not null then
    select * into strict receipt from public.weekly_source_invoice_hold_releases where id=p.invoice_hold_release_id;
    if receipt.upload_row_id::text=m.source_facts_json->>'upload_row_id' and m.movement_role in ('POSITIVE','REPLACEMENT') then
      return private.weekly_source_invoice_movement_money_v1(m.id,receipt.id); end if;
  end if;
  -- NULL is the original immutable money at this exact historical identity.
  return jsonb_build_object('net_pence',m.invoice_presentation_charge_pence,
    'vat_pence',(m.vat_amount*100)::bigint,'gross_pence',(m.total_inc_vat*100)::bigint);
end;
$function$;

create or replace function private.weekly_source_invoice_receipt_projection_assert_v1(p_invoice_id uuid)
returns void language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_record record; authority jsonb; expected jsonb; expected_hash bytea; members uuid[];
begin
  for v_record in select distinct presentation.* from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_invoice_presentation_lines presentation on presentation.id=binding.presentation_line_id
    where binding.invoice_id=p_invoice_id and binding.state='CURRENT' order by presentation.id
  loop
    authority:=private.weekly_source_invoice_rounding_authority_rebuild_v1(v_record.id);
    expected_hash:=private.weekly_source_invoice_presentation_expected_source_hash_v1(v_record.id);
    if v_record.source_hash is distinct from expected_hash then
      raise exception 'WEEKLY_SOURCE_INVOICE_PRESENTATION_SOURCE_HASH_INVALID' using errcode='55000'; end if;
    select array_agg(b.billing_movement_id order by m.movement_role,m.id) into members
      from public.weekly_source_invoice_line_bindings b join public.weekly_source_billing_movements m on m.id=b.billing_movement_id
      where b.presentation_line_id=v_record.id and b.state='CURRENT';
    if authority is not null and v_record.presentation_hash is distinct from private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_PRESENTATION_V1',jsonb_build_object(
        'client_manifest_id',v_record.client_manifest_id,'movement_ids',to_jsonb(members),'line_kind',v_record.line_kind,
        'source_shift_group_id',v_record.source_shift_group_id,'work_date',v_record.work_date,
        'start_at_local',v_record.start_at_local,'end_at_local',v_record.end_at_local,'break_minutes',v_record.break_minutes,
        'hours',jsonb_build_array(v_record.hours_day,v_record.hours_night,v_record.hours_sat,v_record.hours_sun,v_record.hours_bh),
        'total_pay',v_record.total_pay_ex_vat,'total_charge',v_record.total_charge_ex_vat,
        'vat_rate',v_record.vat_rate_pct,'vat',v_record.vat_amount,'total',v_record.total_inc_vat,
        'charge_acceptance_id',v_record.charge_acceptance_id,'source_hash',encode(v_record.source_hash,'hex'))
        ||case when v_record.invoice_hold_release_id is null then '{}'::jsonb else jsonb_build_object(
          'invoice_hold_release_authority',private.weekly_source_invoice_presentation_release_authority_v1(members,v_record.invoice_hold_release_id)) end
        ||case when authority is null then '{}'::jsonb else jsonb_build_object('weekly_source_rounding_authority',authority) end) then
      raise exception 'WEEKLY_SOURCE_INVOICE_PRESENTATION_HASH_INVALID' using errcode='55000'; end if;
    select jsonb_build_object('net_pence',sum((money->>'net_pence')::numeric),
      'vat_pence',sum((money->>'vat_pence')::numeric),'gross_pence',sum((money->>'gross_pence')::numeric)) into expected
      from public.weekly_source_invoice_line_bindings binding
      cross join lateral (select private.weekly_source_invoice_admitted_member_money_v1(v_record.id,binding.billing_movement_id) money) actual
      where binding.presentation_line_id=v_record.id and binding.state='CURRENT';
    if v_record.invoice_presentation_charge_pence is distinct from (expected->>'net_pence')::bigint
      or v_record.vat_amount*100 is distinct from (expected->>'vat_pence')::numeric
      or v_record.total_inc_vat*100 is distinct from (expected->>'gross_pence')::numeric then
      raise exception 'WEEKLY_SOURCE_INVOICE_PRESENTATION_ADMITTED_MONEY_INVALID' using errcode='55000'; end if;
    if authority is not null and exists(select 1 from public.weekly_source_invoice_line_bindings b
      join public.invoice_lines line on line.id=b.invoice_line_id where b.presentation_line_id=v_record.id and b.state='CURRENT'
        and (line.meta_json->'weekly_source_rounding_authority' is distinct from authority
          or line.meta_json->>'presentation_disposition' is distinct from case when (authority->>'suppress_visible_rounding_line')::boolean
            then 'SUPPRESS_ZERO_ROUNDING_AUTHORITY' else 'VISIBLE' end)) then
      raise exception 'WEEKLY_SOURCE_INVOICE_ROUNDING_METADATA_INVALID' using errcode='55000'; end if;
  end loop;
end;
$function$;


-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function private.weekly_source_finalise_engine_v1(
  p_request jsonb,
  p_correction_session_id uuid,
  p_prepare_only boolean
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','source_cycle_id','authority_scope_kind','report_scope_id',
    'upload_id','projection_publication_id','expected_authority_scope_version',
    'expected_row_manifest_hash','expected_comparison_manifest_hash',
    'expected_issue_set_hash','exclude_unfinalised_acknowledged'
  ]::text[];
  v_unknown_key text;
  v_actor uuid;
  v_cycle_id uuid;
  v_scope_kind text;
  v_report_scope_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_existing_revision public.weekly_source_final_revisions%rowtype;
  v_correction public.weekly_final_source_correction_sessions%rowtype;
  v_guard jsonb;
  v_client_id uuid;
  v_resolved_client_id uuid;
  v_resolved_client_count integer;
  v_source_profile_kind text;
  v_source_mode text;
  v_generation integer;
  v_coverage_start date;
  v_coverage_end date;
  v_prior_revision_id uuid;
  v_revision_number integer;
  v_revision_id uuid;
  v_revision_manifest_hash bytea;
  v_policy_fingerprint bytea;
  v_finalised_at timestamptz:=pg_catalog.transaction_timestamp();
  v_row record;
  v_finalisation_root_ids uuid[];
  v_finalisation_root_recheck uuid[];
  v_finalisation_lock_result jsonb;
  v_lock_phase integer;
  v_lock_discovery jsonb;
  v_window_discovery jsonb; v_window_observed jsonb; v_window_lock record;
  v_invoice_window_ids uuid[]; v_round_scope record; v_round_id uuid;
  v_lock_observed jsonb;
  v_finalisation_lock_context boolean:=false;
  v_next_source_hooks boolean:=false;
  v_finalisation_lock_operation uuid;
  v_prior_finalisation_lock_operation text;
  v_prior_finalisation_root_set text;
  v_economic_id uuid;
  v_timesheet_id uuid;
  v_economic public.weekly_source_row_economic_snapshots%rowtype;
  v_snapshot_id uuid;
  v_snapshot_hash bytea;
  v_mapping_fingerprint bytea;
  v_pay_vector jsonb;
  v_charge_vector jsonb;
  v_transition record;
  v_prior_snapshot public.weekly_source_final_snapshot_lines%rowtype;
  v_current_snapshot public.weekly_source_final_snapshot_lines%rowtype;
  v_prior_state bytea;
  v_current_state bytea;
  v_outcome text;
  v_transition_id uuid;
  v_transition_fingerprint bytea;
  v_prior_movement public.weekly_source_billing_movements%rowtype;
  v_correction_unit_id uuid;
  v_charge_check public.weekly_source_charge_checks%rowtype;
  v_charge_acceptance public.weekly_source_charge_acceptances%rowtype;
  v_price_admission_result text;
  v_movement_id uuid;
  v_backing_report_number text;
  v_source_total_cost bigint;
  v_source_commission bigint;
  v_source_invoice_total bigint;
  v_line_count integer;
  v_manifest record;
  v_client_manifest_id uuid;
  v_client_manifest_hash bytea;
  v_completion_generation integer;
  v_completion_hash bytea;
  v_expense_observation record;
  v_target_expense_pence bigint;
  v_target_expense_vat boolean;
  v_target_expense_contract_id uuid;
  v_expense_observation_kind text;
  v_current_expense public.weekly_expense_authority_generations%rowtype;
  v_expense_policy public.weekly_source_row_expense_policy_snapshots%rowtype;
  v_expense_generation integer;
  v_expense_hash bytea;
  v_expense_authority_id uuid;
  v_prior_expense_authority_id uuid;
  v_expense_timesheet_id uuid;
  v_expense_policy_id uuid;
  v_expense_movement_result jsonb;
  v_rule_set jsonb;
  v_rule_values jsonb;
  v_rule_version uuid;
  v_invoice_amounts jsonb;
  v_invoice_correction jsonb;
  v_effective_policy jsonb;
  v_authority_subset jsonb;
  v_prior_authority_subset jsonb;
  v_current_authority_subset jsonb;
  v_comparison_current_authority jsonb;
  v_correction_presentation text;
  v_movement_count integer:=0;
  v_transition_count integer:=0;
  v_snapshot_count integer:=0;
  v_unchanged_count integer:=0;
  v_expense_generation_count integer:=0;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_prepare_only is null
     or (p_prepare_only and p_correction_session_id is null)
     or (not p_prepare_only and p_correction_session_id is not null) then
    raise exception 'WEEKLY_SOURCE_FINALISE_EXECUTION_MODE_INVALID' using errcode='22023';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_FINALISE_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown_key
  from pg_catalog.jsonb_object_keys(p_request) key
  where not (key=any(v_allowed_keys))
  order by key limit 1;
  if v_unknown_key is not null then
    raise exception 'WEEKLY_SOURCE_FINALISE_REQUEST_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown_key;
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_scope_kind:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_request->>'authority_scope_kind','')));
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_upload_id:=(p_request->>'upload_id')::uuid;
    v_publication_id:=(p_request->>'projection_publication_id')::uuid;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'WEEKLY_SOURCE_FINALISE_REQUEST_INVALID' using errcode='22023';
  end;
  if v_actor is null or v_cycle_id is null or v_upload_id is null
     or v_publication_id is null or v_scope_version is null or v_scope_version<1
     or v_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE')
     or (v_scope_kind='NHSP_REPORT_SCOPE') is distinct from (v_report_scope_id is not null) then
    raise exception 'WEEKLY_SOURCE_FINALISE_SCOPE_INVALID' using errcode='22023';
  end if;
  v_expected_row_hash:=private.weekly_source_finalisation_hex32_v1(
    p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_REQUIRED'
  );
  v_expected_comparison_hash:=private.weekly_source_finalisation_hex32_v1(
    p_request->>'expected_comparison_manifest_hash','WEEKLY_SOURCE_COMPARISON_HASH_REQUIRED'
  );
  v_expected_issue_hash:=private.weekly_source_finalisation_hex32_v1(
    p_request->>'expected_issue_set_hash','WEEKLY_SOURCE_ISSUE_HASH_REQUIRED'
  );

  -- Fresh Final admission precedes the first cycle/business lock. Recursive
  -- lineage/current-publication owners inherit this transaction's admission.
  perform private.weekly_source_pay_query_admit_v2();

  -- G1 plain scope discovery -> native complete I-1 -> group -> cycle.
  -- Repeat the same guards under locks; changed source/rules/roots retry before any mutation.
  for v_lock_phase in 1..2 loop
  if v_lock_phase=2 then
    -- Use the discovered exact group, never a fresh group chosen after I-1.
    select * into v_group from public.weekly_source_groups
    where id=(v_lock_discovery#>>'{group,id}')::uuid for update;
    if not found or to_jsonb(v_group) is distinct from v_lock_discovery->'group' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    -- Complete source + candidate invoice windows were discovered BEFORE I-1.
    -- Take every cycle in UUID order, then compare full original row witnesses.
    for v_window_lock in select cycle.* from public.weekly_source_cycles cycle
      where cycle.id=any(v_invoice_window_ids) order by cycle.id for update
    loop
      if to_jsonb(v_window_lock) is distinct from v_window_discovery->'cycles'->v_window_lock.id::text then
        raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    end loop;
    if (select count(*) from public.weekly_source_cycles cycle where cycle.id=any(v_invoice_window_ids))<>cardinality(v_invoice_window_ids) then
      raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
    if not found or to_jsonb(v_cycle) is distinct from v_lock_discovery->'cycle' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_cycle from public.weekly_source_cycles where id=v_cycle_id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  if v_scope_kind='NHSP_REPORT_SCOPE' then
  if v_lock_phase=2 then
    select * into v_scope from public.weekly_source_report_scopes where id=v_report_scope_id for update;
    if not found or to_jsonb(v_scope) is distinct from v_lock_discovery->'scope' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_scope from public.weekly_source_report_scopes where id=v_report_scope_id;
  end if;
    if not found or v_scope.source_cycle_id is distinct from v_cycle.id
       or v_scope.source_group_id is distinct from v_group.id
       or v_scope.environment is distinct from v_group.environment
       or v_scope.agency_id is distinct from v_group.agency_id
       or v_scope.cutoff_at_utc is distinct from v_cycle.cutoff_at_utc then
      raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if v_lock_phase=2 then
    select * into v_upload from public.weekly_source_uploads where id=v_upload_id for share;
    if not found or to_jsonb(v_upload) is distinct from v_lock_discovery->'upload' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_upload from public.weekly_source_uploads where id=v_upload_id;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_FOUND' using errcode='22023';
  end if;
  if v_lock_phase=2 then
    select * into v_publication from public.weekly_source_projection_publications where id=v_publication_id for share;
    if not found or to_jsonb(v_publication) is distinct from v_lock_discovery->'publication' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into strict v_publication from public.weekly_source_projection_publications where id=v_publication_id;
  end if;
  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
  if v_lock_phase=2 and to_jsonb(v_profile) is distinct from v_lock_discovery->'profile' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;

  if p_prepare_only then
  if v_lock_phase=2 then
    select * into v_correction from public.weekly_final_source_correction_sessions where id=p_correction_session_id for share;
    if not found or to_jsonb(v_correction) is distinct from v_lock_discovery->'correction' then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  else
    select * into v_correction from public.weekly_final_source_correction_sessions where id=p_correction_session_id;
  end if;
    if not found or v_correction.state<>'PREPARING'
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_scope_kind
       or v_correction.report_scope_id is distinct from v_report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.replacement_projection_publication_id is distinct from v_publication.id
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.correction_session_id is distinct from v_correction.id
       or v_upload.state<>'CORRECTION_READY'
       or v_publication.state<>'CORRECTION_READY'
       or v_publication.correction_session_id is distinct from v_correction.id
       or v_publication.upload_id is distinct from v_upload.id
       or v_publication.authority_scope_version is distinct from v_scope_version then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
    end if;
    v_guard:=pg_catalog.jsonb_build_object(
      'row_manifest_hash',pg_catalog.encode(v_upload.row_manifest_hash,'hex'),
      'comparison_manifest_hash',pg_catalog.encode(v_publication.comparison_manifest_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_publication.issue_set_hash,'hex')
    );
  else
    v_guard:=private.weekly_source_current_publication_guard_v1(
      v_cycle.id,v_scope_kind,v_report_scope_id,v_upload.id,v_publication.id,v_scope_version
    );
  end if;
  if private.weekly_source_finalisation_hex32_v1(
       v_guard->>'row_manifest_hash','WEEKLY_SOURCE_GUARD_ROW_HASH_INVALID'
     ) is distinct from v_expected_row_hash
     or private.weekly_source_finalisation_hex32_v1(
       v_guard->>'comparison_manifest_hash','WEEKLY_SOURCE_GUARD_COMPARISON_HASH_INVALID'
     ) is distinct from v_expected_comparison_hash
     or private.weekly_source_finalisation_hex32_v1(
       v_guard->>'issue_set_hash','WEEKLY_SOURCE_GUARD_ISSUE_HASH_INVALID'
     ) is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_FINALISE_PREVIEW_CHANGED' using errcode='40001';
  end if;

  v_client_id:=case when v_scope_kind='NHSP_REPORT_SCOPE' then v_scope.client_id
    else nullif(v_upload.file_metadata_json->>'client_id','')::uuid end;
  perform private.weekly_source_office_authority_v1(
    v_actor,case when p_prepare_only then 'CORRECT_FINAL_SOURCE' else 'FINALISE_WEEK' end,
    v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  if p_correction_session_id is null then
    if v_upload.purpose<>'ORDINARY' or v_upload.correction_session_id is not null then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REQUIRES_DEDICATED_OWNER' using errcode='55000';
    end if;
  else
    if v_correction.id is null or v_correction.state<>'PREPARING'
       or v_correction.source_cycle_id is distinct from v_cycle.id
       or v_correction.authority_scope_kind is distinct from v_scope_kind
       or v_correction.report_scope_id is distinct from v_report_scope_id
       or v_correction.replacement_correction_upload_id is distinct from v_upload.id
       or v_correction.replacement_projection_publication_id is distinct from v_publication.id
       or v_upload.purpose<>'FINAL_SOURCE_CORRECTION'
       or v_upload.correction_session_id is distinct from v_correction.id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
    end if;
  end if;
  perform private.weekly_source_final_upload_assert_v1(v_upload.id);
  if not private.weekly_source_import_is_prepared_v1(v_upload.id) then
    raise exception 'WEEKLY_SOURCE_CHECKING_FILE_NOT_FINALISABLE' using errcode='55000';
  end if;
  if v_profile.profile_code in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1')
    and exists(select 1 from public.weekly_source_upload_rows source_row
      where source_row.upload_id=v_upload.id and source_row.row_finalisation_state='SOURCE_UNFINALISED')
    and p_request->'exclude_unfinalised_acknowledged' is distinct from 'true'::jsonb then
    raise exception 'WEEKLY_SOURCE_UNFINALISED_EXCLUSION_ACKNOWLEDGEMENT_REQUIRED' using errcode='55000';
  end if;
  if v_finalised_at<coalesce(v_scope.cutoff_at_utc,v_cycle.cutoff_at_utc)
    and v_profile.profile_code not in ('HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1') then
    raise exception 'WEEKLY_SOURCE_CUTOFF_NOT_REACHED' using errcode='55000';
  end if;

  if v_upload.state<>(case when p_prepare_only then 'CORRECTION_READY' else 'CURRENT' end)
     or v_upload.row_manifest_hash is null
     or v_upload.blocked_count<>0 or v_upload.blocking_economic_duplicate_count<>0
     or v_upload.malformed_count<>0
     or v_upload.physical_row_count<>
       v_upload.header_count+v_upload.trailer_count+v_upload.continuation_count+
       v_upload.accepted_count+v_upload.blocking_economic_duplicate_count+v_upload.malformed_count
     or (select pg_catalog.count(*) from public.weekly_source_upload_rows
         where upload_id=v_upload.id)<>v_upload.accepted_count then
    raise exception 'WEEKLY_SOURCE_UPLOAD_NOT_FINALISABLE' using errcode='55000';
  end if;
  -- WP-54, pack 03 section 7: "Overlapping candidate work events are checked
  -- BEFORE FINALISATION.  The system does not assume two overlapping records
  -- are valid because their references differ."  The same guard runs at the
  -- seal, where a refused report never becomes CURRENT.  It runs again here
  -- because this is the owner the pack names and because the rows this engine
  -- is about to turn into movements are the rows that must satisfy it -- pack
  -- 14 section 8.1, the database decides source authority, never the browser.
  -- Deliberately NOT accompanied by a cutoff re-check: NHSP-BR-006 governs the
  -- cutoff occurrence Office confirms when the report is accepted, and the
  -- seal is where that confirmation is made authoritative.
  perform private.weekly_source_overlap_admission_assert_v1(v_upload.id);
  if v_scope_version>2147483647
     or coalesce(v_publication.projection_generation,0)>2147483647 then
    raise exception 'WEEKLY_SOURCE_GENERATION_OVERFLOW' using errcode='22003';
  end if;
  v_generation:=coalesce(
    v_publication.projection_generation,
    v_scope_version::integer
  );
  if (select pg_catalog.count(*)
      from public.weekly_source_row_resolutions resolution
      join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
      where source_row.upload_id=v_upload.id and resolution.generation=v_generation)
       <>v_upload.accepted_count
     or exists(
       select 1
       from public.weekly_source_upload_rows source_row
       left join public.weekly_source_row_resolutions resolution
         on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
       where source_row.upload_id=v_upload.id
         and (resolution.id is null or resolution.mapping_state<>'RESOLVED')
     )
     or (v_profile.final_authority_kind<>'NHSP_TRUST_BACKING_REPORT' and exists(
       select 1
       from public.weekly_source_row_resolutions resolution
       join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
       where source_row.upload_id=v_upload.id and resolution.generation=v_generation
       group by resolution.work_event_id having pg_catalog.count(*)<>1
     )) then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_CENSUS_NOT_FINALISABLE' using errcode='55000';
  end if;
  if v_scope_kind='CYCLE' then
    select pg_catalog.count(distinct resolution.client_id)::integer,
           pg_catalog.min(resolution.client_id::text)::uuid
    into v_resolved_client_count,v_resolved_client_id
    from public.weekly_source_row_resolutions resolution
    join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
    where source_row.upload_id=v_upload.id and resolution.generation=v_generation;
    if v_resolved_client_count>1 then
      raise exception 'WEEKLY_SOURCE_SINGLE_CLIENT_RESOLUTION_REQUIRED' using errcode='55000';
    end if;
    if v_resolved_client_count=1 and v_client_id is not null
       and v_client_id is distinct from v_resolved_client_id then
      raise exception 'WEEKLY_SOURCE_UPLOAD_CLIENT_MISMATCH' using errcode='55000';
    end if;
    v_client_id:=coalesce(v_resolved_client_id,v_client_id);
    if v_cycle.scope_client_id is not null and v_cycle.scope_client_id is distinct from v_client_id then
      raise exception 'WEEKLY_SOURCE_FINAL_CLIENT_SCOPE_REQUIRED' using errcode='55000';
    end if;
    if v_client_id is null or not exists(
      select 1
      from public.weekly_source_group_clients group_client
      where group_client.source_group_id=v_group.id
        and group_client.client_id=v_client_id
        and v_cycle.finalisation_week_ending between group_client.valid_from
          and coalesce(group_client.valid_to,'infinity'::date)
    ) then
      raise exception 'WEEKLY_SOURCE_FINAL_CLIENT_SCOPE_REQUIRED' using errcode='55000';
    end if;
    perform private.weekly_source_office_authority_v1(
      v_actor,case when p_prepare_only then 'CORRECT_FINAL_SOURCE' else 'FINALISE_WEEK' end,
      v_group.id,v_client_id,v_cycle.finalisation_week_ending
    );
  elsif not exists(
    select 1
    from public.weekly_source_group_clients group_client
    where group_client.source_group_id=v_group.id
      and group_client.client_id=v_client_id
      and v_cycle.finalisation_week_ending between group_client.valid_from
        and coalesce(group_client.valid_to,'infinity'::date)
  ) then
    raise exception 'WEEKLY_SOURCE_FINAL_CLIENT_SCOPE_REQUIRED' using errcode='55000';
  end if;

  v_rule_set:=private.weekly_source_effective_rule_set_v1(v_client_id,v_cycle.id);
  v_rule_values:=v_rule_set->'values'; v_rule_version:=nullif(v_rule_set->>'rule_set_version_id','')::uuid;
  v_source_profile_kind:=v_profile.final_authority_kind;
  if v_profile.profile_code='NHSP_FINAL_BACKING_V1' then
    if v_scope_kind<>'NHSP_REPORT_SCOPE' or v_group.source_family<>'NHSP'
       or v_source_profile_kind<>'NHSP_TRUST_BACKING_REPORT'
       or v_profile.omission_meaning<>'NO_INFERENCE'
       or not v_profile.report_number_required or not v_profile.fmc_must_equal_zero
       or v_client_id is null
       or exists(select 1 from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (source_row.row_finalisation_state not in ('NOT_APPLICABLE','SOURCE_WORKED')
              or source_row.source_money_parse_state<>'VALID'
              or source_row.source_shift_charge_pence is null
              or source_row.source_expense_parse_state<>'NOT_APPLICABLE'
             or source_row.source_expense_pence is not null)) then
      raise exception 'WEEKLY_SOURCE_NHSP_FINAL_NOT_FINALISABLE' using errcode='55000';
    end if;
    v_source_mode:='NHSP_WEEKLY';
    v_coverage_start:=null;
    v_coverage_end:=null;
    v_backing_report_number:=private.weekly_source_canonical_report_number_v1(
      v_upload.file_metadata_json->>'nhsp_report_number'
    );
    if v_backing_report_number is null then
      raise exception 'WEEKLY_SOURCE_NHSP_REPORT_NUMBER_REQUIRED' using errcode='55000';
    end if;
  elsif v_profile.profile_code in (
    'HEALTHROSTER_WEEKLY_FROM_TO_ACTUAL_V1','HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1'
  ) then
    if v_scope_kind<>'CYCLE' or v_group.source_family<>'ROSTER'
       or v_source_profile_kind<>'HEALTHROSTER_ACTUAL_ROWS'
       or v_profile.omission_meaning<>'CANCEL_INSIDE_CONFIRMED_COVERAGE'
       or v_client_id is null
       or exists(select 1 from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (source_row.row_finalisation_state not in ('SOURCE_WORKED','SOURCE_UNFINALISED')
             or source_row.source_expense_parse_state<>'NOT_APPLICABLE'
             or source_row.source_expense_pence is not null)) then
      raise exception 'WEEKLY_SOURCE_HEALTHROSTER_NOT_FINALISABLE' using errcode='55000';
    end if;
    v_source_mode:='HEALTHROSTER_WEEKLY';
    v_coverage_start:=v_upload.confirmed_coverage_start_local_date;
    v_coverage_end:=v_upload.confirmed_coverage_end_local_date;
  elsif v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1' then
    if v_scope_kind<>'CYCLE' or v_group.source_family<>'ROSTER'
       or v_source_profile_kind<>'GENERIC_COMPLETE_SNAPSHOT'
       or v_profile.omission_meaning<>'CANCEL_INSIDE_CONFIRMED_COVERAGE'
       or v_client_id is null
       or exists(select 1 from public.weekly_source_upload_rows source_row
         where source_row.upload_id=v_upload.id
           and (source_row.row_finalisation_state not in ('NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO')
             or source_row.source_expense_parse_state not in ('NOT_APPLICABLE','VALID','OMITTED_ZERO')
             or (source_row.source_expense_parse_state='NOT_APPLICABLE')
                  is distinct from (source_row.source_expense_pence is null)
             or (source_row.source_expense_parse_state='OMITTED_ZERO'
                 and source_row.source_expense_pence<>0))) then
      raise exception 'WEEKLY_SOURCE_ROSTER_COMPLETE_NOT_FINALISABLE' using errcode='55000';
    end if;
    v_source_mode:='HEALTHROSTER_WEEKLY';
    v_coverage_start:=v_upload.confirmed_coverage_start_local_date;
    v_coverage_end:=v_upload.confirmed_coverage_end_local_date;
  else
    raise exception 'WEEKLY_SOURCE_PROFILE_NOT_FINAL_AUTHORITY' using errcode='55000';
  end if;
  if v_scope_kind='CYCLE' and (
    v_upload.coverage_state<>'COMPLETE' or v_upload.coverage_timezone<>'Europe/London'
    or v_coverage_start is null or v_coverage_end is null or v_coverage_start>v_coverage_end
  ) then
    raise exception 'WEEKLY_SOURCE_CONFIRMED_COVERAGE_REQUIRED' using errcode='55000';
  end if;
  if exists(
    select 1
    from public.weekly_source_row_resolutions resolution
    join public.weekly_source_upload_rows source_row on source_row.id=resolution.upload_row_id
    where source_row.upload_id=v_upload.id and resolution.generation=v_generation
      and (resolution.client_id is distinct from v_client_id
        or source_row.work_date<coalesce(v_coverage_start,source_row.work_date)
        or source_row.work_date>coalesce(v_coverage_end,source_row.work_date))
  ) then
    raise exception 'WEEKLY_SOURCE_RESOLUTION_OUTSIDE_FINAL_SCOPE' using errcode='55000';
  end if;

  v_window_observed:=private.weekly_source_invoice_window_lock_inventory_v1(v_upload.id,v_generation,v_cycle.id,v_client_id);
  if v_lock_phase=1 then
    v_window_discovery:=v_window_observed;
    select array_agg(key::uuid order by key::uuid) into v_invoice_window_ids
      from jsonb_object_keys(v_window_discovery->'cycles') key;
  elsif v_window_observed is distinct from v_window_discovery then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_CHANGED_DURING_LOCK' using errcode='40001'; end if;
  v_lock_observed:=jsonb_build_object(
    'group',to_jsonb(v_group),'cycle',to_jsonb(v_cycle),'scope',to_jsonb(v_scope),
    'upload',to_jsonb(v_upload),'publication',to_jsonb(v_publication),
    'profile',to_jsonb(v_profile),'correction',to_jsonb(v_correction),
    'client_id',v_client_id,'generation',v_generation,'coverage_start',v_coverage_start,
    'coverage_end',v_coverage_end,'source_profile_kind',v_source_profile_kind,
    'rule_set',v_rule_set,'resolutions',coalesce((select jsonb_agg(to_jsonb(r) order by r.id)
      from public.weekly_source_row_resolutions r join public.weekly_source_upload_rows s on s.id=r.upload_row_id
      where s.upload_id=v_upload.id and r.generation=v_generation),'[]'::jsonb));
  if v_lock_phase=1 then
    v_lock_discovery:=v_lock_observed;
  -- Review F2.  Finalisation calls the lineage ensure owner once per source row
  -- inside ONE transaction, so without this it accumulates family lock sets in
  -- source_row_ordinal order rather than the (btrim(booking_id), booking_id)
  -- order proof/32 section 6 step 2 fixes.  That is an A-B / B-A cycle against
  -- any sorted I-1 caller -- a publication, a release tick or a first
  -- authorisation -- and the I-1 caller was the victim (reproduction D3).
  --
  -- The complete set of roots this cycle will touch is therefore locked ONCE,
  -- up front, through the same helper, which sorts them.  Every later per-row
  -- call then re-enters locks this transaction already holds.
  --
  -- The Candidate serial gate is deliberately NOT taken here.  proof/32
  -- section 6 step 1 makes the gate per Candidate and pins it to four job
  -- types: first authorisation, first-authorisation withdrawal, entitlement
  -- publication and pending release.  Finalisation is none of them -- it
  -- authorises nothing and publishes no entitlement -- and one finalisation
  -- spans many Candidates, so a single gate call cannot cover it and a gate per
  -- Candidate would invent a lock ladder the pack does not describe.
  -- proof/34 section 5 asks this path only for the family lock set and the
  -- resolver, which is exactly what it takes.
  v_prior_finalisation_lock_operation:=coalesce(pg_catalog.current_setting('cloudtms.weekly_source_finalisation_lock_operation',true),'');
  v_prior_finalisation_root_set:=coalesce(pg_catalog.current_setting('cloudtms.weekly_source_finalisation_root_set',true),'');
  v_finalisation_lock_context:=true;
  select active_owner='NEXT' into v_next_source_hooks
  from private.bpay_next_module_control where id=1 for share;
  if coalesce(v_next_source_hooks,false) then

  -- Include prior-only CURRENT HR cancellation and positive-expense omission
  -- roots BEFORE taking any booking key. Current partial indexes provide the
  -- coverage inventory; only this upload/exact corrected revision contributes
  -- immutable emitted roots. No historical chooser is added here.
  v_finalisation_lock_operation:=private.bpay_next_source_current_lock_inventory_v1(
    v_upload.id,v_generation,case when p_prepare_only then v_correction.expected_current_final_revision_id else null end,
    v_group.id,v_client_id,v_coverage_start,v_coverage_end
  );
  perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_finalisation_lock_operation::text,true);
  perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set','',true);
  else
  -- Retained default LEGACY / DISABLED Source path: no selector inventory,
  -- no assumption that pre-existing Source facts have been bootstrapped.
  select pg_catalog.array_agg(distinct contract_week.timesheet_id order by contract_week.timesheet_id)
  into v_finalisation_root_ids
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  join public.contract_weeks contract_week
    on contract_week.contract_id=resolution.contract_id
   and contract_week.additional_seq=0
   and contract_week.week_ending_date=source_row.work_date+
       ((coalesce((
          select contract.week_ending_weekday_snapshot
          from public.contracts contract where contract.id=resolution.contract_id
        ),0)-extract(dow from source_row.work_date)::integer+7)%7)
  where source_row.upload_id=v_upload.id
    and contract_week.timesheet_id is not null;

  if v_finalisation_root_ids is not null
     and pg_catalog.array_length(v_finalisation_root_ids,1) is not null then
    v_finalisation_lock_result:=private.weekly_source_lock_family_rows_v1(
      v_finalisation_root_ids,null
    );
    if coalesce((v_finalisation_lock_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_finalisation_lock_result->>'code'
        using errcode='55000',detail=v_finalisation_lock_result::text;
    end if;
  end if;

  -- Review G2.  The set above was computed from an UNLOCKED read filtered on a
  -- non-null Contract Week Timesheet id, so a root another owner commits between
  -- that read and the loop would be locked later, in source-row order, out of
  -- the sorted order proof/32 section 6 step 2 fixes.  Recompute it under the
  -- family locks now held; if it grew, refuse retryably (40001) rather than take
  -- a second lock set out of order.  A retry recomputes the larger set up front.
  select pg_catalog.array_agg(distinct contract_week.timesheet_id order by contract_week.timesheet_id)
  into v_finalisation_root_recheck
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  join public.contract_weeks contract_week
    on contract_week.contract_id=resolution.contract_id
   and contract_week.additional_seq=0
   and contract_week.week_ending_date=source_row.work_date+
       ((coalesce((
          select contract.week_ending_weekday_snapshot
          from public.contracts contract where contract.id=resolution.contract_id
        ),0)-extract(dow from source_row.work_date)::integer+7)%7)
  where source_row.upload_id=v_upload.id
    and contract_week.timesheet_id is not null;

  if coalesce(v_finalisation_root_recheck,array[]::uuid[])
     <>coalesce(v_finalisation_root_ids,array[]::uuid[]) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'locked_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_ids,1),0),
          'observed_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_recheck,1),0)
        )::text;
  end if;

  -- Publish the locked set for the per-row calls.  The lineage ensure owner
  -- refuses 40001 when it discovers a root this set does not contain, so a root
  -- that appears after the recheck can never be locked out of order either.
  -- This is a Weekly-Source-private setting, never a Workbench-owned one.
  perform pg_catalog.set_config(
    'cloudtms.weekly_source_finalisation_root_set',
    coalesce(pg_catalog.array_to_string(v_finalisation_root_ids,','),'EMPTY_LOCKED_SET'),
    true
  );
  perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation','',true);
  end if;


  else
    if v_lock_observed is distinct from v_lock_discovery then
      raise exception 'WEEKLY_SOURCE_FINALISATION_SCOPE_CHANGED_DURING_LOCK' using errcode='40001'; end if;
    if v_finalisation_lock_operation is not null then
      perform private.bpay_next_source_current_lock_recheck_v1(v_finalisation_lock_operation);
    else
  -- Review G2.  The set above was computed from an UNLOCKED read filtered on a
  -- non-null Contract Week Timesheet id, so a root another owner commits between
  -- that read and the loop would be locked later, in source-row order, out of
  -- the sorted order proof/32 section 6 step 2 fixes.  Recompute it under the
  -- family locks now held; if it grew, refuse retryably (40001) rather than take
  -- a second lock set out of order.  A retry recomputes the larger set up front.
  select pg_catalog.array_agg(distinct contract_week.timesheet_id order by contract_week.timesheet_id)
  into v_finalisation_root_recheck
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  join public.contract_weeks contract_week
    on contract_week.contract_id=resolution.contract_id
   and contract_week.additional_seq=0
   and contract_week.week_ending_date=source_row.work_date+
       ((coalesce((
          select contract.week_ending_weekday_snapshot
          from public.contracts contract where contract.id=resolution.contract_id
        ),0)-extract(dow from source_row.work_date)::integer+7)%7)
  where source_row.upload_id=v_upload.id
    and contract_week.timesheet_id is not null;

  if coalesce(v_finalisation_root_recheck,array[]::uuid[])
     <>coalesce(v_finalisation_root_ids,array[]::uuid[]) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_ROOT_SET_CHANGED_DURING_LOCK'
      using errcode='40001',
        detail=pg_catalog.jsonb_build_object(
          'locked_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_ids,1),0),
          'observed_root_count',
            coalesce(pg_catalog.array_length(v_finalisation_root_recheck,1),0)
        )::text;
  end if;


    end if;
  end if;
  end loop;

  -- One transaction at a time may decide the final order for a logical
  -- group/Client/source-authority history.  Both supported HealthRoster
  -- layouts share the same final_authority_kind and therefore the same lock.
  -- The lock is acquired only after the exact current publication and Client
  -- have been resolved; no other owner acquires this finaliser-only domain.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly_source_finalise_order:'||v_group.id::text||':'||v_client_id::text||':'||v_source_profile_kind,
    0
  ));

  if p_prepare_only then
    if coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
         is distinct from v_correction.expected_current_final_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
    end if;
  elsif coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id) is not null then
    select * into strict v_existing_revision
    from public.weekly_source_final_revisions
    where id=coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id);
    if v_existing_revision.upload_id=v_upload.id
       and v_existing_revision.authority_scope_kind=v_scope_kind
       and v_existing_revision.report_scope_id is not distinct from v_report_scope_id
       and v_existing_revision.state='CURRENT' then
      -- Native operation is transaction-local, including exact immutable replay.
      if v_finalisation_lock_operation is not null then
        perform private.bpay_next_source_current_lock_release_v1(v_finalisation_lock_operation);
      end if;
      if v_finalisation_lock_context then
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
      end if;
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','FINALISED','idempotent',true,
        'final_revision_id',v_existing_revision.id,'source_cycle_id',v_cycle.id,
        'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
        'upload_id',v_upload.id
      );
    end if;
    raise exception 'WEEKLY_SOURCE_SCOPE_ALREADY_FINALISED' using errcode='55000';
  end if;

  if v_scope_kind='CYCLE' and exists(
    select 1
    from public.weekly_source_final_revisions later_revision
    join public.weekly_source_cycles later_cycle
      on later_cycle.id=later_revision.source_cycle_id
    join public.weekly_source_client_manifests later_manifest
      on coalesce(later_manifest.invoice_window_cycle_id,later_manifest.source_cycle_id)=later_manifest.source_cycle_id and later_manifest.final_revision_id=later_revision.id
     and later_manifest.client_id=v_client_id
    join public.weekly_source_uploads later_upload
      on later_upload.id=later_revision.upload_id
    join public.weekly_source_format_profiles later_profile
      on later_profile.id=later_upload.source_format_profile_id
    where later_revision.authority_scope_kind='CYCLE'
      and later_revision.state='CURRENT'
      and later_cycle.source_group_id=v_group.id
      and later_cycle.finalisation_week_ending>v_cycle.finalisation_week_ending
      and later_profile.final_authority_kind=v_source_profile_kind
  ) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_OUT_OF_ORDER' using errcode='55000';
  end if;

  -- The source Timesheet owner is the only component permitted to create or
  -- reuse ordinary Timesheet lineage.  Finalisation calls it, then validates
  -- the resulting immutable binding; it never accepts a caller-owned id.
  for v_row in
    select resolution.id as resolution_id,source_row.row_finalisation_state
    from public.weekly_source_upload_rows source_row
    join public.weekly_source_row_resolutions resolution
      on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
    where source_row.upload_id=v_upload.id
      and (v_rule_values is null or v_rule_values->>'invoice_sender'<>'CLIENT_SELF_BILL' or v_rule_values->>'self_bill_source'<>'SAME_FILE'
          or coalesce((private.weekly_source_shift_on_self_bill_v1(resolution.work_event_id,v_cycle.id)->>'s25_pay_selected')::boolean,false))
      and (v_source_profile_kind='NHSP_TRUST_BACKING_REPORT'
        or source_row.row_finalisation_state='SOURCE_WORKED'
        or (v_source_profile_kind='GENERIC_COMPLETE_SNAPSHOT'
          and source_row.row_finalisation_state='NOT_APPLICABLE'))
    order by source_row.source_row_ordinal
  loop
    perform public.weekly_source_timesheet_lineage_ensure_atomic_v1(v_row.resolution_id,v_actor);
    v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
      v_row.resolution_id,v_cycle.id,v_source_mode
    );
    v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
      v_row.resolution_id,v_cycle.id
    );
  end loop;

  if v_scope_kind='CYCLE' then
    select revision.id into v_prior_revision_id
    from public.weekly_source_final_revisions revision
    join public.weekly_source_cycles prior_cycle on prior_cycle.id=revision.source_cycle_id
    join public.weekly_source_client_manifests prior_manifest
      on coalesce(prior_manifest.invoice_window_cycle_id,prior_manifest.source_cycle_id)=prior_manifest.source_cycle_id and prior_manifest.final_revision_id=revision.id and prior_manifest.client_id=v_client_id
    join public.weekly_source_uploads prior_upload on prior_upload.id=revision.upload_id
    join public.weekly_source_format_profiles prior_profile
      on prior_profile.id=prior_upload.source_format_profile_id
    where revision.authority_scope_kind='CYCLE' and revision.state='CURRENT'
      and prior_cycle.source_group_id=v_group.id and prior_cycle.id<>v_cycle.id
      and prior_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending
      and prior_profile.final_authority_kind=v_source_profile_kind
    order by prior_cycle.finalisation_week_ending desc,revision.finalised_at_utc desc,revision.id desc
    limit 1;
  end if;

  select coalesce(pg_catalog.max(revision.revision_number),0)+1 into v_revision_number
  from public.weekly_source_final_revisions revision
  where revision.source_cycle_id=v_cycle.id
    and revision.authority_scope_kind=v_scope_kind
    and revision.report_scope_id is not distinct from v_report_scope_id;
  select private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_FINAL_POLICY_SET_V1',
    pg_catalog.jsonb_build_object(
      'profile_code',v_profile.profile_code,'profile_version',v_profile.version,
      'source_profile_kind',v_source_profile_kind,'source_mode',v_source_mode,
      'economics',coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'row_resolution_id',resolution.id,
        'contract_and_rate_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.contract_and_rate_fingerprint,'hex') end,
        'effective_policy_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.effective_policy_fingerprint,'hex') end,
        'invoice_vat_policy_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.invoice_vat_policy_fingerprint,'hex') end,
        'calculation_fingerprint',case when economic.id is null then null
          else pg_catalog.encode(economic.calculation_fingerprint,'hex') end,
        'expense_policy_snapshot_id',expense_policy.id,
        'expense_policy_snapshot_hash',case when expense_policy.id is null then null
          else pg_catalog.encode(expense_policy.snapshot_hash,'hex') end
      ) order by source_row.source_row_ordinal),'[]'::jsonb)
    )
  ) into v_policy_fingerprint
  from public.weekly_source_upload_rows source_row
  join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
  left join public.weekly_source_row_economic_snapshots economic
    on economic.row_resolution_id=resolution.id
  left join public.weekly_source_row_expense_policy_snapshots expense_policy
    on expense_policy.row_resolution_id=resolution.id
  where source_row.upload_id=v_upload.id;
  v_revision_manifest_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_FINAL_REVISION_MANIFEST_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_cycle.id,'authority_scope_kind',v_scope_kind,
      'report_scope_id',v_report_scope_id,'revision_number',v_revision_number,
      'upload_id',v_upload.id,'authority_scope_version',v_scope_version,
      'row_manifest_hash',pg_catalog.encode(v_expected_row_hash,'hex'),
      'comparison_manifest_hash',pg_catalog.encode(v_expected_comparison_hash,'hex'),
      'issue_set_hash',pg_catalog.encode(v_expected_issue_hash,'hex'),
      'profile_code',v_profile.profile_code,'profile_version',v_profile.version,
      'coverage_start_local_date',v_coverage_start,'coverage_end_local_date',v_coverage_end,
      'reason',case when p_correction_session_id is null then 'INITIAL_FINALISATION'
        else 'CORRECT_FINAL_SOURCE' end,
      'predecessor_revision_id',case when p_correction_session_id is null then null
        else v_correction.expected_current_final_revision_id end,
      'prior_state_cutoff_revision_id',v_prior_revision_id,
      'policy_fingerprint',pg_catalog.encode(v_policy_fingerprint,'hex')
    )||case when v_rule_version is null then '{}'::jsonb else jsonb_build_object(
      'rule_set_version_id',v_rule_version,'rule_set_values_sha256',v_rule_set->>'values_sha256') end
  );
  insert into public.weekly_source_final_revisions(
    source_cycle_id,authority_scope_kind,report_scope_id,revision_number,upload_id,
    predecessor_revision_id,coverage_start_local_date,coverage_end_local_date,
    coverage_timezone,prior_state_cutoff_revision_id,reason,finalised_by_user_id,
    finalised_at_utc,manifest_hash,policy_fingerprint,state,rule_set_version_id
  ) values (
    v_cycle.id,v_scope_kind,v_report_scope_id,v_revision_number,v_upload.id,
    case when p_correction_session_id is null then null
      else v_correction.expected_current_final_revision_id end,
    v_coverage_start,v_coverage_end,
    case when v_scope_kind='CYCLE' then 'Europe/London' else null end,
    v_prior_revision_id,
    case when p_correction_session_id is null then 'INITIAL_FINALISATION'
      else 'CORRECT_FINAL_SOURCE' end,
    v_actor,v_finalised_at,
    v_revision_manifest_hash,v_policy_fingerprint,
    case when p_prepare_only then 'PREPARED' else 'CURRENT' end,v_rule_version
  ) returning id into v_revision_id;

  if v_source_profile_kind in ('GENERIC_COMPLETE_SNAPSHOT','HEALTHROSTER_ACTUAL_ROWS') then
    for v_row in
      select source_row.*,resolution.id as resolution_id,
             resolution.work_event_id,resolution.candidate_id,resolution.client_id,
             resolution.contract_id,resolution.work_event_match_kind,
             resolution.work_event_match_fingerprint
      from public.weekly_source_upload_rows source_row
      join public.weekly_source_row_resolutions resolution
        on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
      where source_row.upload_id=v_upload.id
        and (v_rule_values is null or v_rule_values->>'invoice_sender'<>'CLIENT_SELF_BILL' or v_rule_values->>'self_bill_source'<>'SAME_FILE'
          or coalesce((private.weekly_source_shift_on_self_bill_v1(resolution.work_event_id,v_cycle.id)->>'s25_pay_selected')::boolean,false))
        and (source_row.row_finalisation_state='SOURCE_WORKED'
          or (v_source_profile_kind='GENERIC_COMPLETE_SNAPSHOT'
            and source_row.row_finalisation_state='NOT_APPLICABLE'))
      order by source_row.source_row_ordinal
    loop
      v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
        v_row.resolution_id,v_cycle.id,'HEALTHROSTER_WEEKLY'
      );
      v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
        v_row.resolution_id,v_cycle.id
      );
      select * into strict v_economic
      from public.weekly_source_row_economic_snapshots where id=v_economic_id;
      v_pay_vector:=private.weekly_source_finalisation_vector_v1(v_economic.id,'PAY',1::smallint);
      v_charge_vector:=private.weekly_source_finalisation_vector_v1(v_economic.id,'CHARGE',1::smallint);
      v_mapping_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_FINAL_MAPPING_V1',
        pg_catalog.jsonb_build_object(
          'work_event_id',v_row.work_event_id,'candidate_id',v_row.candidate_id,
          'client_id',v_row.client_id,'contract_id',v_row.contract_id
        )
      );
      -- Freeze only the four authority fields for this exact new snapshot.
      -- The full economic/provenance hashes remain unchanged below.
      v_effective_policy:=private._weekly_source_effective_policy_v1(
        v_row.client_id,v_row.contract_id,v_row.work_date
      );
      if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
         or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
         or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id then
        raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
      end if;
      v_authority_subset:=private.weekly_source_authority_subset_v1(v_effective_policy);
      v_snapshot_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_FINAL_SNAPSHOT_LINE_V1',
        pg_catalog.jsonb_build_object(
          'final_revision_id',v_revision_id,'upload_row_id',v_row.id,
          'row_resolution_id',v_row.resolution_id,'work_event_id',v_row.work_event_id,
          'candidate_id',v_row.candidate_id,'client_id',v_row.client_id,
          'contract_id',v_row.contract_id,'work_date',v_row.work_date,
          'start_at_local',v_row.start_at_local,'end_at_local',v_row.end_at_local,
          'break_minutes',v_row.break_minutes,'actual_net_minutes',v_row.actual_net_minutes,
          'pay_vector',v_pay_vector,'charge_vector',v_charge_vector,
          'source_expense_pence',v_row.source_expense_pence,
          'source_fingerprint',pg_catalog.encode(v_row.normalised_row_hash,'hex'),
          'mapping_fingerprint',pg_catalog.encode(v_mapping_fingerprint,'hex'),
          'rate_fingerprint',pg_catalog.encode(v_economic.calculation_fingerprint,'hex'),
          'policy_fingerprint',pg_catalog.encode(v_economic.effective_policy_fingerprint,'hex')
        )
      );
      insert into public.weekly_source_final_snapshot_lines(
        final_revision_id,upload_row_id,row_resolution_id,charge_check_id,
        source_profile_kind,work_event_id,external_event_identity,candidate_id,
        client_id,contract_id,work_date,start_at_local,end_at_local,break_minutes,
        actual_net_minutes,source_classifications_json,pay_vector_json,charge_vector_json,
        source_expense_pence,source_fingerprint,mapping_fingerprint,rate_fingerprint,
        policy_fingerprint,snapshot_line_hash,authority_subset_json,authority_subset_sha256,invoice_economics_sha256
      ) values (
        v_revision_id,v_row.id,v_row.resolution_id,null,v_source_profile_kind,
        v_row.work_event_id,v_row.external_source_key,v_row.candidate_id,v_row.client_id,
        v_row.contract_id,v_row.work_date,v_row.start_at_local,v_row.end_at_local,
        v_row.break_minutes,v_row.actual_net_minutes,v_economic.canonical_result_json,
        v_pay_vector,v_charge_vector,v_row.source_expense_pence,v_row.normalised_row_hash,
        v_mapping_fingerprint,v_economic.calculation_fingerprint,
        v_economic.effective_policy_fingerprint,v_snapshot_hash,v_authority_subset,
        private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_AUTHORITY_SUBSET_V1',v_authority_subset),
        case when v_rule_values is not null and v_rule_values->>'invoice_sender'='CLIENT_SELF_BILL' and v_rule_values->>'invoice_amount_basis'='SOURCE_AMOUNT' and v_rule_values->>'source_amount_basis'='EXPORT_ACTUAL_COST_INC_VAT_NET_AGENCY_WORKER_PAY'
          then private.weekly_source_invoice_economics_fingerprint_v1(jsonb_build_object('source_shift_charge_pence',v_row.source_shift_charge_pence,
            'source_gross_pence',v_row.source_gross_pence,'source_vat_pence',v_row.source_vat_pence),v_rule_values->>'line_vat_method',
            case when v_economic.invoice_vat_chargeable then v_economic.invoice_vat_rate_pct else 0 end) else null end
      ) returning id into v_snapshot_id;
      v_snapshot_count:=v_snapshot_count+1;
    end loop;

    for v_transition in
      with prior_states as (
        select distinct on (prior_transition.work_event_id)
               prior_transition.work_event_id,
               prior_transition.new_snapshot_line_id
        from public.weekly_source_state_transitions prior_transition
        join public.weekly_source_final_revisions prior_revision
          on prior_revision.id=prior_transition.final_revision_id
         and prior_revision.state='CURRENT'
        join public.weekly_source_cycles prior_cycle
          on prior_cycle.id=prior_transition.finalisation_cycle_id
        join public.weekly_source_client_manifests prior_manifest
          on coalesce(prior_manifest.invoice_window_cycle_id,prior_manifest.source_cycle_id)=prior_manifest.source_cycle_id and prior_manifest.final_revision_id=prior_revision.id
         and prior_manifest.client_id=v_client_id
        where prior_transition.source_profile_kind=v_source_profile_kind
          and prior_cycle.source_group_id=v_group.id
          and prior_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending
        order by prior_transition.work_event_id,
                 prior_cycle.finalisation_week_ending desc,
                 prior_revision.finalised_at_utc desc,
                 prior_revision.revision_number desc,
                 prior_transition.created_at_utc desc,
                 prior_transition.id desc
      ), prior_lines as (
        select prior_line.id,prior_state.work_event_id
        from prior_states prior_state
        join public.weekly_source_final_snapshot_lines prior_line
          on prior_line.id=prior_state.new_snapshot_line_id
        where prior_line.client_id=v_client_id
          and not (v_rule_values is not null and v_rule_values->>'invoice_sender'='CLIENT_SELF_BILL' and v_rule_values->>'self_bill_source'='SAME_FILE'
            and coalesce((private.weekly_source_shift_on_self_bill_v1(prior_line.work_event_id,v_cycle.id)->>'bound_to_finalised_export')::boolean,false)
            and not coalesce((private.weekly_source_shift_on_self_bill_v1(prior_line.work_event_id,v_cycle.id)->>'s25_pay_selected')::boolean,false))
          and (
            prior_line.work_date between v_coverage_start and v_coverage_end
            or exists(
              select 1
              from public.weekly_source_row_resolutions current_resolution
              join public.weekly_source_upload_rows current_row
                on current_row.id=current_resolution.upload_row_id
              where current_row.upload_id=v_upload.id
                and current_resolution.generation=v_generation
                and current_resolution.work_event_id=prior_line.work_event_id
            )
          )
      ), current_lines as (
        select current_line.id,current_line.work_event_id
        from public.weekly_source_final_snapshot_lines current_line
        where current_line.final_revision_id=v_revision_id
      )
      select coalesce(prior_lines.work_event_id,current_lines.work_event_id) as work_event_id,
             prior_lines.id as prior_snapshot_id,current_lines.id as current_snapshot_id
      from prior_lines full join current_lines using(work_event_id)
      order by coalesce(prior_lines.work_event_id,current_lines.work_event_id)
    loop
      select * into v_prior_snapshot
      from public.weekly_source_final_snapshot_lines
      where id=v_transition.prior_snapshot_id;
      select * into v_current_snapshot
      from public.weekly_source_final_snapshot_lines
      where id=v_transition.current_snapshot_id;
      v_effective_policy:=private._weekly_source_effective_policy_v1(
        coalesce(v_current_snapshot.client_id,v_prior_snapshot.client_id),
        coalesce(v_current_snapshot.contract_id,v_prior_snapshot.contract_id),
        coalesce(v_current_snapshot.work_date,v_prior_snapshot.work_date)
      );
      if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
         or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
         or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id then
        raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
      end if;
      v_authority_subset:=private.weekly_source_authority_subset_v1(v_effective_policy);
      v_prior_authority_subset:=private.weekly_source_snapshot_authority_subset_v1(v_transition.prior_snapshot_id);
      v_current_authority_subset:=private.weekly_source_snapshot_authority_subset_v1(v_transition.current_snapshot_id);
      if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
         or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
         or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id
         or (coalesce(v_current_authority_subset,v_prior_authority_subset) is not null
           and v_authority_subset is distinct from coalesce(v_current_authority_subset,v_prior_authority_subset))
         or (coalesce(v_current_authority_subset,v_prior_authority_subset) is null
           and private.weekly_source_finalisation_hex32_v1(
              v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
            ) is distinct from coalesce(
              v_current_snapshot.policy_fingerprint,v_prior_snapshot.policy_fingerprint
            )) then
        raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
      end if;
      v_correction_presentation:=pg_catalog.upper(pg_catalog.btrim(coalesce(
        v_effective_policy->>'self_bill_correction_presentation',''
      )));
      if v_correction_presentation not in (
        'FULL_REVERSAL_REPLACEMENT','NET_DIFFERENCE_PRESENTATION'
      ) then
        raise exception 'WEEKLY_SOURCE_SELF_BILL_CORRECTION_POLICY_REQUIRED'
          using errcode='55000';
      end if;
      -- Unknown pre-upgrade authority keeps the whole-hash fence. Equality
      -- proves compatibility without inventing historical four-field JSON.
      v_comparison_current_authority:=v_current_authority_subset;
      if v_transition.prior_snapshot_id is not null and v_prior_authority_subset is null
         and v_transition.current_snapshot_id is not null then
        if private.weekly_source_finalisation_hex32_v1(
             v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
           ) is distinct from v_prior_snapshot.policy_fingerprint then
          raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
        end if;
        v_comparison_current_authority:=null;
      end if;
      v_prior_state:=private.weekly_source_snapshot_value_fingerprint_v1(
        v_transition.prior_snapshot_id,v_prior_authority_subset
      );
      v_current_state:=private.weekly_source_snapshot_value_fingerprint_v1(
        v_transition.current_snapshot_id,v_comparison_current_authority
      );
      v_outcome:=case
        when v_transition.prior_snapshot_id is null then 'ADD'
        when v_transition.current_snapshot_id is null then 'CANCEL'
        when v_prior_state=v_current_state then 'NO_CHANGE'
        else 'AMEND' end;
      v_transition_fingerprint:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_STATE_TRANSITION_V1',
        pg_catalog.jsonb_build_object(
          'final_revision_id',v_revision_id,'work_event_id',v_transition.work_event_id,
          'previous_snapshot_line_id',v_transition.prior_snapshot_id,
          'new_snapshot_line_id',v_transition.current_snapshot_id,
          'outcome',v_outcome,
          'prior_state_fingerprint',case when v_prior_state is null then null
            else pg_catalog.encode(v_prior_state,'hex') end,
          'new_state_fingerprint',case when v_current_state is null then null
            else pg_catalog.encode(v_current_state,'hex') end
        )
      );
      insert into public.weekly_source_state_transitions(
        final_revision_id,finalisation_cycle_id,source_profile_kind,work_event_id,
        previous_present,new_present,previous_snapshot_line_id,new_snapshot_line_id,
        outcome,identity_match_kind,match_confidence,prior_state_fingerprint,
        new_state_fingerprint,transition_fingerprint,
        ordinary_source_entitlement_projection_state
      ) values (
        v_revision_id,v_cycle.id,v_source_profile_kind,v_transition.work_event_id,
        v_transition.prior_snapshot_id is not null,v_transition.current_snapshot_id is not null,
        v_transition.prior_snapshot_id,v_transition.current_snapshot_id,v_outcome,
        (select event.identity_kind from public.weekly_work_events event
          where event.id=v_transition.work_event_id),
        case when (select event.identity_kind from public.weekly_work_events event
          where event.id=v_transition.work_event_id)='PROFILE_EXTERNAL_KEY'
          then 'EXACT_PROFILE_KEY' else 'EXACT_DURABLE_LINEAGE' end,
        v_prior_state,v_current_state,v_transition_fingerprint,
        case when v_outcome='NO_CHANGE' then 'NOT_APPLICABLE' else 'PENDING' end
      ) returning id into v_transition_id;
      v_transition_count:=v_transition_count+1;

      if v_outcome='NO_CHANGE' then
        v_unchanged_count:=v_unchanged_count+1;
        if v_transition.new_snapshot_line_id is not null and v_transition.previous_snapshot_line_id is not null and exists(select 1 from public.weekly_source_final_snapshot_lines current_line join public.weekly_source_final_snapshot_lines prior_line on prior_line.id=v_transition.previous_snapshot_line_id where current_line.id=v_transition.new_snapshot_line_id and current_line.external_event_identity is distinct from prior_line.external_event_identity) then
          if private.weekly_source_rebill_movement_insert_v1(v_transition_id,v_revision_id) is not null then v_movement_count:=v_movement_count+1; end if;
        else
          v_invoice_correction:=private.weekly_source_invoice_correction_insert_v1(v_transition_id,v_transition.work_event_id,v_revision_id);
          v_movement_count:=v_movement_count+coalesce((v_invoice_correction->>'movement_count')::integer,0);
        end if;
      else
        if v_outcome in ('AMEND','CANCEL') then
          select movement.* into v_prior_movement
          from public.weekly_source_billing_movements movement
          join public.weekly_source_final_revisions movement_revision
            on movement_revision.id=movement.final_revision_id
          join public.weekly_source_cycles movement_cycle
            on movement_cycle.id=movement.finalisation_cycle_id
          where movement.work_event_id=v_transition.work_event_id
            and movement.source_profile_kind=v_source_profile_kind
            and movement.movement_role in ('POSITIVE','REPLACEMENT')
            and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
            and movement.final_revision_id<>v_revision_id
            and movement_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending
          order by movement_cycle.finalisation_week_ending desc,
                   movement_revision.finalised_at_utc desc,movement.created_at_utc desc,movement.id desc
          limit 1;
          if not found then
            raise exception 'WEEKLY_SOURCE_PRIOR_MOVEMENT_MISSING' using errcode='55000';
          end if;
          v_correction_unit_id:=pg_catalog.gen_random_uuid();
          v_movement_id:=private.weekly_source_finalisation_insert_reversal_v1(
            v_transition_id,v_revision_id,v_cycle.id,v_prior_movement.id,
            v_correction_unit_id,v_source_profile_kind,
            pg_catalog.jsonb_build_object(
              'schema_version','WEEKLY_SOURCE_GENERATED_REVERSAL_FACTS_V1',
              'outcome',v_outcome,'prior_snapshot_line_id',v_transition.prior_snapshot_id,
              'prior_movement_id',v_prior_movement.id,
              'correction_presentation',v_correction_presentation
            )
          );
          v_movement_count:=v_movement_count+1;
          if private.weekly_source_invoice_correction_unwind_v1(v_transition_id,v_transition.work_event_id,v_revision_id) is not null then v_movement_count:=v_movement_count+1; end if;
        else
          v_correction_unit_id:=null;
          v_prior_movement.id:=null;
        end if;
        if v_outcome in ('ADD','AMEND') then
          select resolution.id as resolution_id into strict v_row
          from public.weekly_source_row_resolutions resolution
          where resolution.id=v_current_snapshot.row_resolution_id;
          v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
            v_row.resolution_id,v_cycle.id,'HEALTHROSTER_WEEKLY'
          );
          v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
            v_row.resolution_id,v_cycle.id
          );
          select * into strict v_economic
          from public.weekly_source_row_economic_snapshots where id=v_economic_id;
          v_invoice_amounts:=private.weekly_source_invoice_line_amounts_v1(v_row.resolution_id,v_revision_id);
          v_movement_id:=private.weekly_source_finalisation_insert_current_movement_v1(
            v_transition_id,null,v_revision_id,v_cycle.id,v_source_profile_kind,
            case when v_outcome='ADD' then 'POSITIVE' else 'REPLACEMENT' end,
            case when v_outcome='ADD' then 'SOURCE_ORDINARY' else 'SOURCE_REPLACEMENT' end,
            v_row.resolution_id,v_economic.id,v_timesheet_id,case when (v_invoice_amounts->>'source_amount')::boolean then (v_invoice_amounts->>'net_pence')::bigint else null end,
            (v_invoice_amounts->>'net_pence')::bigint,v_invoice_amounts->>'price_check_result',case when (v_invoice_amounts->>'source_amount')::boolean then v_economic.calculation_fingerprint else null end,
            nullif(v_invoice_amounts->>'charge_acceptance_id','')::uuid,
            pg_catalog.jsonb_build_object(
              'schema_version','WEEKLY_SOURCE_CURRENT_FACTS_V1','outcome',v_outcome,
              'snapshot_line_id',v_current_snapshot.id,
              'upload_row_id',v_current_snapshot.upload_row_id,
              'row_resolution_id',v_current_snapshot.row_resolution_id,
              'correction_presentation',v_correction_presentation
            ),v_correction_unit_id,
            case when v_outcome='AMEND' then v_prior_movement.id else null end
          );
          v_movement_count:=v_movement_count+1;
        end if;
      end if;

    end loop;

    if v_profile.profile_code='ROSTER_WEEKLY_SUMMARY_ACTUAL_V1' then
      -- The profile can serve Clients with or without source-fixed expenses.
      -- A snapshot is mandatory exactly where the sealed effective policy
      -- enables that route, and forbidden otherwise.  This prevents both a
      -- missing configured expense and accidental contamination of ordinary
      -- evidence-led expenses.
      for v_row in
        select source_row.work_date,resolution.id as resolution_id,
               resolution.client_id,resolution.contract_id,
               resolution.effective_policy_fingerprint,
               expense_policy.id as expense_policy_snapshot_id
        from public.weekly_source_upload_rows source_row
        join public.weekly_source_row_resolutions resolution
          on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
        left join public.weekly_source_row_expense_policy_snapshots expense_policy
          on expense_policy.row_resolution_id=resolution.id
        where source_row.upload_id=v_upload.id
        order by source_row.source_row_ordinal
      loop
        v_effective_policy:=private._weekly_source_effective_policy_v1(
          v_row.client_id,v_row.contract_id,v_row.work_date
        );
        if (v_effective_policy->>'authority_mode') is distinct from 'SOURCE_AUTHORITY'
           or coalesce((v_effective_policy->>'self_bill_enabled')::boolean,false) is not true
           or (v_effective_policy->>'source_group_id')::uuid is distinct from v_group.id
           or private.weekly_source_finalisation_hex32_v1(
                v_effective_policy->>'policy_sha256','WEEKLY_SOURCE_POLICY_FINGERPRINT_INVALID'
              ) is distinct from v_row.effective_policy_fingerprint then
          raise exception 'WEEKLY_SOURCE_FINALISATION_POLICY_STALE' using errcode='40001';
        end if;
        if coalesce((v_effective_policy->>'source_fixed_expenses_enabled')::boolean,false) then
          if v_row.expense_policy_snapshot_id is null
             or private.weekly_source_finalisation_expense_policy_assert_v1(
                  v_row.resolution_id,v_cycle.id
                ) is distinct from v_row.expense_policy_snapshot_id then
            raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_CARDINALITY'
              using errcode='55000';
          end if;
        elsif v_row.expense_policy_snapshot_id is not null then
          raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_NOT_ENABLED' using errcode='55000';
        end if;
      end loop;

      for v_expense_observation in
        with current_observation as (
          select expense_policy.id as expense_policy_snapshot_id,
                 expense_policy.row_resolution_id,expense_policy.work_event_id,
                 expense_policy.contract_id,expense_policy.source_expense_pence,
                 expense_policy.source_expense_vat_enabled,
                 expense_policy.correction_presentation
          from public.weekly_source_row_expense_policy_snapshots expense_policy
          join public.weekly_source_row_resolutions resolution
            on resolution.id=expense_policy.row_resolution_id
          join public.weekly_source_upload_rows source_row
            on source_row.id=resolution.upload_row_id
          where source_row.upload_id=v_upload.id and resolution.generation=v_generation
        ), prior_authority as (
          select
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.id else authority.id end as prior_authority_id,
                 authority.work_event_id,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.contract_id else authority.contract_id end as contract_id,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.source_expense_pence else authority.source_expense_pence end
                   as source_expense_pence,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.source_expense_vat_enabled
                        else authority.source_expense_vat_enabled end
                   as source_expense_vat_enabled,
                 case when p_prepare_only
                           and authority.final_revision_id=v_correction.expected_current_final_revision_id
                        then baseline.correction_presentation
                        else authority.correction_presentation end
                   as correction_presentation,
                 event.work_date
          from public.weekly_expense_authority_generations authority
          join public.weekly_work_events event on event.id=authority.work_event_id
          left join public.weekly_expense_authority_generations baseline
            on p_prepare_only
           and authority.final_revision_id=v_correction.expected_current_final_revision_id
           and baseline.id=authority.prior_expense_authority_generation_id
          where authority.state='CURRENT'
            and event.first_source_group_id=v_group.id
            and event.client_id=v_client_id
            and not (
              p_prepare_only
              and authority.final_revision_id=v_correction.expected_current_final_revision_id
              and baseline.id is null
            )
            and (
              event.work_date between v_coverage_start and v_coverage_end
              or exists(
                select 1 from current_observation current_match
                where current_match.work_event_id=authority.work_event_id
              )
            )
        )
        select coalesce(current_observation.work_event_id,prior_authority.work_event_id) as work_event_id,
               current_observation.expense_policy_snapshot_id,
               current_observation.row_resolution_id,
               current_observation.contract_id as current_contract_id,
               current_observation.source_expense_pence as current_expense_pence,
               current_observation.source_expense_vat_enabled as current_expense_vat_enabled,
               current_observation.correction_presentation as current_correction_presentation,
               prior_authority.prior_authority_id,
               prior_authority.contract_id as prior_contract_id,
               prior_authority.source_expense_pence as prior_expense_pence,
               prior_authority.source_expense_vat_enabled as prior_expense_vat_enabled,
               prior_authority.correction_presentation as prior_correction_presentation
        from current_observation
        full join prior_authority using(work_event_id)
        order by coalesce(current_observation.work_event_id,prior_authority.work_event_id)
      loop
        v_expense_policy_id:=v_expense_observation.expense_policy_snapshot_id;
        v_prior_expense_authority_id:=v_expense_observation.prior_authority_id;
        v_expense_authority_id:=null;
        v_expense_timesheet_id:=null;
        v_current_expense.id:=null;
        if v_expense_policy_id is not null then
          if private.weekly_source_finalisation_expense_policy_assert_v1(
               v_expense_observation.row_resolution_id,v_cycle.id
             ) is distinct from v_expense_policy_id then
            raise exception 'WEEKLY_SOURCE_EXPENSE_POLICY_SNAPSHOT_INVALID' using errcode='55000';
          end if;
          select * into strict v_expense_policy
          from public.weekly_source_row_expense_policy_snapshots
          where id=v_expense_policy_id;
          v_target_expense_pence:=v_expense_policy.source_expense_pence;
          v_target_expense_vat:=v_expense_policy.source_expense_vat_enabled;
          v_target_expense_contract_id:=v_expense_policy.contract_id;
          v_expense_observation_kind:='ROW_PRESENT';
          v_correction_presentation:=v_expense_policy.correction_presentation;
          if v_target_expense_pence>0 then
            perform public.weekly_source_timesheet_lineage_ensure_atomic_v1(
              v_expense_policy.row_resolution_id,v_actor
            );
            v_expense_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
              v_expense_policy.row_resolution_id,v_cycle.id
            );
          end if;
        else
          v_target_expense_pence:=0;
          v_target_expense_vat:=v_expense_observation.prior_expense_vat_enabled;
          v_target_expense_contract_id:=v_expense_observation.prior_contract_id;
          v_expense_observation_kind:='OMITTED_IN_COMPLETE_COVERAGE';
          v_correction_presentation:=v_expense_observation.prior_correction_presentation;
        end if;
        if v_prior_expense_authority_id is not null then
          select * into strict v_current_expense
          from public.weekly_expense_authority_generations expense
          where expense.id=v_prior_expense_authority_id
            and expense.state in ('CURRENT','SUPERSEDED')
            and expense.work_event_id=v_expense_observation.work_event_id
          for update;
        end if;
        if v_prior_expense_authority_id is null
           or v_current_expense.source_expense_pence is distinct from v_target_expense_pence
           or v_current_expense.source_expense_vat_enabled is distinct from v_target_expense_vat
           or v_current_expense.contract_id is distinct from v_target_expense_contract_id
           or v_current_expense.source_observation_kind is distinct from v_expense_observation_kind then
          if v_prior_expense_authority_id is not null then
            if not p_prepare_only then
              update public.weekly_expense_authority_generations
              set state='SUPERSEDED' where id=v_prior_expense_authority_id;
            end if;
          end if;
          select coalesce(pg_catalog.max(expense.generation),0)+1 into v_expense_generation
          from public.weekly_expense_authority_generations expense
          where expense.work_event_id=v_expense_observation.work_event_id;
          v_expense_hash:=private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_EXPENSE_AUTHORITY_GENERATION_V1',
            pg_catalog.jsonb_build_object(
              'final_revision_id',v_revision_id,
              'work_event_id',v_expense_observation.work_event_id,
              'contract_id',v_target_expense_contract_id,
              'row_expense_policy_snapshot_id',v_expense_policy_id,
              'prior_expense_authority_generation_id',v_prior_expense_authority_id,
              'generation',v_expense_generation,
              'source_observation_kind',v_expense_observation_kind,
              'correction_presentation',v_correction_presentation,
              'source_expense_pence',v_target_expense_pence,
              'source_expense_vat_enabled',v_target_expense_vat
            )
          );
          insert into public.weekly_expense_authority_generations(
            final_revision_id,work_event_id,contract_id,row_expense_policy_snapshot_id,
            prior_expense_authority_generation_id,generation,source_observation_kind,
            correction_presentation,source_expense_pence,source_expense_vat_enabled,
            candidate_reimbursement_ex_vat,client_charge_ex_vat,authority_hash,state
          ) values (
            v_revision_id,v_expense_observation.work_event_id,v_target_expense_contract_id,
            v_expense_policy_id,v_prior_expense_authority_id,v_expense_generation,
            v_expense_observation_kind,v_correction_presentation,v_target_expense_pence,
            v_target_expense_vat,v_target_expense_pence::numeric/100,
            v_target_expense_pence::numeric/100,v_expense_hash,
            case when p_prepare_only then 'PREPARED' else 'CURRENT' end
          ) returning id into v_expense_authority_id;
          v_expense_movement_result:=
            private.weekly_source_finalisation_materialise_expense_invoice_v1(
              v_revision_id,v_cycle.id,v_source_profile_kind,
              v_expense_authority_id,v_prior_expense_authority_id,
              v_expense_policy_id,v_expense_timesheet_id,
              v_correction_presentation
            );
          v_movement_count:=v_movement_count+
            coalesce((v_expense_movement_result->>'movement_count')::integer,0);
          v_expense_generation_count:=v_expense_generation_count+1;
        end if;
        v_current_expense.id:=null;
      end loop;
    end if;
  else
    v_source_total_cost:=0;
    v_source_commission:=0;
    v_source_invoice_total:=0;
    v_line_count:=0;
    for v_row in
      select source_row.*,resolution.id as resolution_id,
             resolution.work_event_id,resolution.candidate_id,resolution.client_id,
             resolution.contract_id
      from public.weekly_source_upload_rows source_row
      join public.weekly_source_row_resolutions resolution
        on resolution.upload_row_id=source_row.id and resolution.generation=v_generation
      where source_row.upload_id=v_upload.id
      order by source_row.source_row_ordinal
    loop
      v_economic_id:=private.weekly_source_finalisation_economic_assert_v1(
        v_row.resolution_id,v_cycle.id,'NHSP_WEEKLY'
      );
      v_timesheet_id:=private.weekly_source_finalisation_lineage_assert_v1(
        v_row.resolution_id,v_cycle.id
      );
      select * into strict v_economic
      from public.weekly_source_row_economic_snapshots where id=v_economic_id;
      select * into v_charge_check
      from public.weekly_source_charge_checks charge_check
      where charge_check.upload_row_id=v_row.id
        and charge_check.row_resolution_id=v_row.resolution_id
        and charge_check.generation=v_generation;
      v_charge_acceptance.id:=null;
      if found and v_charge_check.comparison_result in ('MISMATCH','ZERO_SOURCE_CHARGE') then
        select * into v_charge_acceptance
        from public.weekly_source_charge_acceptances acceptance
        where acceptance.charge_check_id=v_charge_check.id
          and acceptance.upload_row_id=v_row.id
          and acceptance.row_resolution_id=v_row.resolution_id
          and acceptance.source_upload_id=v_upload.id
          and acceptance.contract_id=v_row.contract_id
          and acceptance.acceptance_kind=case v_charge_check.comparison_result
            when 'ZERO_SOURCE_CHARGE' then 'ACCEPTED_ZERO' else 'ACCEPTED_DISPARITY' end
          and acceptance.source_upload_hash=v_upload.content_sha256
          and acceptance.source_row_fingerprint=(select resolution.source_row_fingerprint
            from public.weekly_source_row_resolutions resolution where resolution.id=v_row.resolution_id)
          and acceptance.contract_and_rate_fingerprint=v_economic.contract_and_rate_fingerprint
          and acceptance.effective_policy_fingerprint=v_economic.effective_policy_fingerprint
          and acceptance.charge_calculation_fingerprint=v_economic.calculation_fingerprint
          and acceptance.acceptance_policy_fingerprint=
            private.weekly_source_charge_acceptance_policy_fingerprint_v1();
      end if;
      v_price_admission_result:=case v_charge_check.comparison_result
        when 'ZERO_SOURCE_CHARGE' then 'ACCEPTED_ZERO'
        when 'MISMATCH' then 'ACCEPTED_DISPARITY'
        else v_charge_check.comparison_result end;
      if not found or (select pg_catalog.count(*)
          from public.weekly_source_charge_checks charge_check
          where charge_check.upload_row_id=v_row.id
            and charge_check.row_resolution_id=v_row.resolution_id
            and charge_check.generation=v_generation)<>1
         or v_charge_check.source_commission_pence is distinct from v_row.source_commission_pence
         or v_charge_check.source_total_cost_pence is distinct from v_row.source_total_cost_pence
         or v_charge_check.source_shift_charge_pence is distinct from v_row.source_shift_charge_pence
         or v_charge_check.calculated_segment_charge_pence is distinct from v_economic.calculated_charge_pence
         or v_charge_check.source_charge_difference_pence is distinct from
              (v_row.source_shift_charge_pence-v_economic.calculated_charge_pence)
         or v_charge_check.charge_calculation_fingerprint is distinct from
              v_economic.calculation_fingerprint
         or v_charge_check.comparison_profile_version<>'NHSP_TWO_COMPONENT_PENCE_V1'
         or v_charge_check.comparison_result not in (
              'EXACT','SOURCE_ROUNDING_EQUIVALENT','MISMATCH','ZERO_SOURCE_CHARGE'
            )
         or not (
           (v_charge_check.comparison_result='EXACT'
             and v_charge_check.source_charge_difference_pence=0)
           or (v_charge_check.comparison_result='SOURCE_ROUNDING_EQUIVALENT'
             and v_charge_check.row_sign_kind in ('POSITIVE','FULL_NEGATIVE')
             and (v_charge_check.source_charge_difference_pence=1
               or v_charge_check.source_charge_difference_pence=-1)
             and ((v_charge_check.source_shift_charge_pence>0
                   and v_charge_check.calculated_segment_charge_pence>0)
               or (v_charge_check.source_shift_charge_pence<0
                   and v_charge_check.calculated_segment_charge_pence<0)))
           or (v_charge_check.comparison_result='MISMATCH'
             and v_charge_acceptance.id is not null
             and v_charge_acceptance.acceptance_kind='ACCEPTED_DISPARITY')
           or (v_charge_check.comparison_result='ZERO_SOURCE_CHARGE'
             and v_charge_check.source_commission_pence=0
             and v_charge_check.source_total_cost_pence=0
             and v_charge_check.source_shift_charge_pence=0
             and v_charge_check.calculated_segment_charge_pence>0
             and v_charge_acceptance.id is not null
             and v_charge_acceptance.acceptance_kind='ACCEPTED_ZERO')
         )
         or v_charge_check.row_sign_kind is distinct from (case
              when v_economic.row_sign=1 then 'POSITIVE' else 'FULL_NEGATIVE' end)
         or v_charge_check.phase_severity='FINALISATION_BLOCKER'
         or v_charge_check.blocker_code is not null then
        raise exception 'WEEKLY_SOURCE_NHSP_PRICE_GATE_FAILED'
          using errcode='55000',detail=v_row.source_row_ordinal::text;
      end if;
      v_movement_id:=private.weekly_source_finalisation_insert_current_movement_v1(
        null,v_row.id,v_revision_id,v_cycle.id,'NHSP_TRUST_BACKING_REPORT',
        case when v_economic.row_sign=1 then 'POSITIVE' else 'REVERSAL' end,
        case when v_economic.row_sign=1
          then 'NHSP_PHYSICAL_POSITIVE' else 'NHSP_PHYSICAL_FULL_NEGATIVE' end,
        v_row.resolution_id,v_economic.id,v_timesheet_id,
        v_row.source_shift_charge_pence,v_row.source_shift_charge_pence,
        v_price_admission_result,v_charge_check.charge_calculation_fingerprint,
        v_charge_acceptance.id,
        pg_catalog.jsonb_build_object(
          'schema_version','WEEKLY_SOURCE_NHSP_PHYSICAL_FACTS_V1',
          'backing_report_number',v_backing_report_number,
          'report_scope_id',v_report_scope_id,'source_row_ordinal',v_row.source_row_ordinal,
          'upload_row_id',v_row.id,'row_resolution_id',v_row.resolution_id,
          'work_date',v_row.work_date,'start_at_local',v_row.start_at_local,
          'end_at_local',v_row.end_at_local,'break_minutes',v_row.break_minutes,
          'actual_net_minutes',v_row.actual_net_minutes,
          'source_commission_pence',v_row.source_commission_pence,
          'source_total_cost_pence',v_row.source_total_cost_pence,
          'source_shift_charge_pence',v_row.source_shift_charge_pence,
          'calculated_comparison_charge_pence',v_economic.calculated_charge_pence,
          'comparison_result',v_charge_check.comparison_result,
          'price_admission_result',v_price_admission_result,
          'charge_acceptance_id',v_charge_acceptance.id,
          'physical_sign',case when v_economic.row_sign=1
            then 'POSITIVE' else 'FULL_NEGATIVE' end
        ),null,null
      );
      v_source_total_cost:=v_source_total_cost+v_row.source_total_cost_pence;
      v_source_commission:=v_source_commission+v_row.source_commission_pence;
      v_source_invoice_total:=v_source_invoice_total+v_row.source_shift_charge_pence;
      v_line_count:=v_line_count+1;
      v_movement_count:=v_movement_count+1;
    end loop;
    if v_line_count<>v_upload.accepted_count
       or v_source_invoice_total<>v_source_total_cost+v_source_commission then
      raise exception 'WEEKLY_SOURCE_NHSP_REPORT_TOTAL_INVALID' using errcode='55000';
    end if;
    insert into public.weekly_source_nhsp_backing_reports(
      report_scope_id,final_revision_id,upload_id,client_id,backing_report_number,
      cutoff_at_utc,physical_line_count,source_total_cost_pence,
      source_commission_pence,source_invoice_total_pence,row_manifest_hash
    ) values (
      v_report_scope_id,v_revision_id,v_upload.id,v_client_id,v_backing_report_number,
      v_scope.cutoff_at_utc,v_line_count,v_source_total_cost,v_source_commission,
      v_source_invoice_total,v_upload.row_manifest_hash
    );
  end if;

  for v_round_scope in select distinct movement.actual_client_id client_id,
      private.weekly_source_invoice_movement_window_id_v1(movement.id) invoice_window_cycle_id
    from public.weekly_source_billing_movements movement where movement.final_revision_id=v_revision_id
      and movement.source_line_kind<>'INVOICE_VAT_ROUNDING'
    order by client_id,invoice_window_cycle_id
  loop
    if not(v_round_scope.invoice_window_cycle_id=any(v_invoice_window_ids)) then
      raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SET_GREW_AFTER_LOCK' using errcode='40001'; end if;
    v_round_id:=private.weekly_source_vat_rounding_movement_insert_v1(v_revision_id,v_round_scope.client_id,null,v_round_scope.invoice_window_cycle_id);
    if v_round_id is not null then v_movement_count:=v_movement_count+1; end if;
  end loop;
  for v_manifest in
    select scope.client_id,scope.invoice_window_cycle_id,actual.finalisation_week_ending as invoice_week_ending
    from (select movement.actual_client_id as client_id,
      private.weekly_source_invoice_movement_window_id_v1(movement.id) as invoice_window_cycle_id
      from public.weekly_source_billing_movements movement where movement.final_revision_id=v_revision_id
      union select v_client_id,v_cycle.id) scope
    join public.weekly_source_cycles actual on actual.id=scope.invoice_window_cycle_id
    where scope.client_id is not null order by scope.client_id,scope.invoice_window_cycle_id
  loop
    select private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CLIENT_MANIFEST_V1',
      pg_catalog.jsonb_build_object(
        'final_revision_id',v_revision_id,'source_group_id',v_group.id,
        'source_cycle_id',v_cycle.id,'client_id',v_manifest.client_id,
        'finalisation_week_ending',v_manifest.invoice_week_ending,
        'backing_report_number',v_backing_report_number,
        'movements',coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'movement_id',movement.id,
          'movement_economic_hash',pg_catalog.encode(movement.movement_economic_hash,'hex')
        ) order by pg_catalog.encode(movement.movement_economic_hash,'hex')),
        '[]'::jsonb),
        'expense_authorities',coalesce((
          select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'expense_authority_generation_id',expense.id,
            'authority_hash',pg_catalog.encode(expense.authority_hash,'hex')
          ) order by pg_catalog.encode(expense.authority_hash,'hex'))
          from public.weekly_expense_authority_generations expense
          join public.weekly_work_events event on event.id=expense.work_event_id
          where expense.final_revision_id=v_revision_id and event.client_id=v_manifest.client_id
            and v_manifest.invoice_window_cycle_id=v_cycle.id
        ),'[]'::jsonb)
      )||case when v_manifest.invoice_window_cycle_id=v_cycle.id then '{}'::jsonb else jsonb_build_object('invoice_window_cycle_id',v_manifest.invoice_window_cycle_id) end
      ||case when v_rule_version is null then '{}'::jsonb else jsonb_build_object('rule_set_version_id',v_rule_version,'rule_set_values_sha256',v_rule_set->>'values_sha256') end
    ) into v_client_manifest_hash
    from public.weekly_source_billing_movements movement
    where movement.final_revision_id=v_revision_id
      and movement.actual_client_id=v_manifest.client_id
      and private.weekly_source_invoice_movement_window_id_v1(movement.id)=v_manifest.invoice_window_cycle_id;
    insert into public.weekly_source_client_manifests(
      final_revision_id,source_group_id,source_cycle_id,invoice_window_cycle_id,client_id,
      finalisation_week_ending,backing_report_number,manifest_hash,movement_count,
      unchanged_snapshot_count,expense_line_count,invoice_state
    ) values (
      v_revision_id,v_group.id,v_cycle.id,case when v_manifest.invoice_window_cycle_id=v_cycle.id then null else v_manifest.invoice_window_cycle_id end,v_manifest.client_id,
      v_manifest.invoice_week_ending,v_backing_report_number,v_client_manifest_hash,
      (select pg_catalog.count(*)::integer
       from public.weekly_source_billing_movements movement
       where movement.final_revision_id=v_revision_id
         and movement.actual_client_id=v_manifest.client_id
         and private.weekly_source_invoice_movement_window_id_v1(movement.id)=v_manifest.invoice_window_cycle_id),
      (select pg_catalog.count(*)::integer
       from public.weekly_source_state_transitions transition_row
       join public.weekly_source_final_snapshot_lines snapshot_line
         on snapshot_line.id=transition_row.new_snapshot_line_id
       where transition_row.final_revision_id=v_revision_id
         and transition_row.outcome='NO_CHANGE'
         and snapshot_line.client_id=v_manifest.client_id
         and v_manifest.invoice_window_cycle_id=v_cycle.id),
      (select pg_catalog.count(*)::integer
       from public.weekly_expense_authority_generations expense
       join public.weekly_work_events event on event.id=expense.work_event_id
       where expense.final_revision_id=v_revision_id
         and event.client_id=v_manifest.client_id
         and v_manifest.invoice_window_cycle_id=v_cycle.id),
      'READY'
    ) returning id into v_client_manifest_id;
    insert into public.weekly_source_manifest_movements(
      client_manifest_id,billing_movement_id,manifest_ordinal,movement_hash
    )
    select v_client_manifest_id,movement.id,
           pg_catalog.row_number() over(
             order by pg_catalog.encode(movement.movement_economic_hash,'hex')
           )::integer,
           movement.movement_economic_hash
    from public.weekly_source_billing_movements movement
    where movement.final_revision_id=v_revision_id
      and movement.actual_client_id=v_manifest.client_id
      and private.weekly_source_invoice_movement_window_id_v1(movement.id)=v_manifest.invoice_window_cycle_id;
  end loop;


  if v_finalisation_lock_operation is not null then
    -- Includes the later positive-expense lineage calls. Advisory/row locks
    -- remain transaction-held; remove only this operation's working copies.
    perform private.bpay_next_source_current_lock_release_v1(v_finalisation_lock_operation);
  end if;
  if v_finalisation_lock_context then
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
    perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
  end if;

  if p_prepare_only then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','PREPARED','idempotent',false,
      'final_revision_id',v_revision_id,'source_cycle_id',v_cycle.id,
      'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
      'upload_id',v_upload.id,'profile_code',v_profile.profile_code,
      'client_id',v_client_id,'snapshot_count',v_snapshot_count,
      'transition_count',v_transition_count,'movement_count',v_movement_count,
      'unchanged_count',v_unchanged_count,
      'expense_generation_count',v_expense_generation_count
    );
  end if;

  update public.weekly_source_client_cycle_completions completion
  set state='SUPERSEDED',superseded_at_utc=v_finalised_at
  where completion.source_cycle_id=v_cycle.id
    and completion.client_id=v_client_id and completion.state='CURRENT';
  select coalesce(pg_catalog.max(completion.completion_generation),0)+1
  into v_completion_generation
  from public.weekly_source_client_cycle_completions completion
  where completion.source_cycle_id=v_cycle.id and completion.client_id=v_client_id;
  v_completion_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CLIENT_CYCLE_COMPLETION_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
      'client_id',v_client_id,'completion_generation',v_completion_generation,
      'completion_kind','FINAL_SOURCE','final_revision_id',v_revision_id,
      'actor_user_id',v_actor
    )
  );
  insert into public.weekly_source_client_cycle_completions(
    source_cycle_id,source_group_id,client_id,completion_generation,
    completion_kind,final_revision_id,attested_by_user_id,attested_at_utc,
    attestation_text,completion_hash,state
  ) values (
    v_cycle.id,v_group.id,v_client_id,v_completion_generation,
    'FINAL_SOURCE',v_revision_id,v_actor,v_finalised_at,null,v_completion_hash,'CURRENT'
  );

  if v_scope_kind='CYCLE' then
    update public.weekly_source_cycles
    set current_final_revision_id=v_revision_id,state='FINALISED',
        finalised_at_utc=v_finalised_at,finalised_by_user_id=v_actor
    where id=v_cycle.id and current_complete_upload_id=v_upload.id
      and current_projection_publication_id=v_publication.id
      and version=v_scope_version and current_final_revision_id is null;
    if not found then
      raise exception 'WEEKLY_SOURCE_FINALISE_CAS_LOST' using errcode='40001';
    end if;
  else
    update public.weekly_source_report_scopes
    set current_final_revision_id=v_revision_id,state='FINALISED',
        updated_at_utc=v_finalised_at
    where id=v_scope.id and current_complete_upload_id=v_upload.id
      and current_projection_publication_id=v_publication.id
      and version=v_scope_version and current_final_revision_id is null;
    if not found then
      raise exception 'WEEKLY_SOURCE_FINALISE_CAS_LOST' using errcode='40001';
    end if;
    if not exists(
      select 1
      from public.weekly_source_group_clients membership
      where membership.source_group_id=v_group.id
        and v_cycle.finalisation_week_ending between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
        and not exists(
          select 1
          from public.weekly_source_client_cycle_completions completion
          where completion.source_cycle_id=v_cycle.id
            and completion.client_id=membership.client_id
            and completion.state='CURRENT'
        )
    ) then
      update public.weekly_source_cycles
      set state='FINALISED',finalised_at_utc=v_finalised_at,
          finalised_by_user_id=v_actor
      where id=v_cycle.id;
    else
      update public.weekly_source_cycles
      set state='FINALISABLE'
      where id=v_cycle.id and state in ('OPEN','FINALISABLE');
    end if;
  end if;

  -- Only this genuine new CURRENT transition may resolve contained manual
  -- queries. PREPARED and retained Final replay returned earlier. Query-only
  -- resolution shares this transaction; it never changes frozen pay or money.
  perform private.weekly_source_manual_reviews_finalised_v1(v_revision_id,v_actor);

  -- PREPARED returned above and remains invisible. Capture only AFTER the
  -- real cycle/report CURRENT CAS; any failure rolls back Source and selector
  -- together. The same immutable economic/lineage facts remain authoritative.
  if coalesce(v_next_source_hooks,false) then
    perform private.bpay_next_source_current_publish_revision_v1(v_revision_id);
  end if;

  if p_correction_session_id is null and exists(
    select 1
    from public.weekly_source_cycles cycle
    where cycle.id=v_cycle.id and cycle.state='FINALISED'
  ) then
    perform private._weekly_source_settings_ensure_open_cycle_v1(
      v_group.id,v_finalised_at
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status',case when p_correction_session_id is null
      then 'FINALISED' else 'CORRECTED' end,'idempotent',false,
    'final_revision_id',v_revision_id,'source_cycle_id',v_cycle.id,
    'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
    'upload_id',v_upload.id,'profile_code',v_profile.profile_code,
    'client_id',v_client_id,'snapshot_count',v_snapshot_count,
    'transition_count',v_transition_count,'movement_count',v_movement_count,
    'unchanged_count',v_unchanged_count,
    'expense_generation_count',v_expense_generation_count
  );
exception
  when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
    -- The function subtransaction already rolled back Source/cache/control
    -- writes on entry to this handler. Restore only the caller's exact GUCs.
    if v_finalisation_lock_context then
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
    end if;
    raise exception 'WEEKLY_SOURCE_FINALISE_VALUE_INVALID' using errcode='22023';
  when others then
    if v_finalisation_lock_context then
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_lock_operation',v_prior_finalisation_lock_operation,true);
      perform pg_catalog.set_config('cloudtms.weekly_source_finalisation_root_set',v_prior_finalisation_root_set,true);
    end if;
    raise;
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function public.weekly_source_invoice_admit_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','client_manifest_id','expected_manifest_hash'
  ]::text[];
  v_unknown text;
  v_actor uuid;
  v_manifest_id uuid;
  v_expected_hash bytea;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_invoice_window public.weekly_source_cycles%rowtype;
  v_receipt_map jsonb; v_round_authority jsonb; v_round_presentation jsonb;
  v_revision public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_client public.clients%rowtype;
  v_defaults public.settings_defaults%rowtype;
  v_invoice_id uuid;
  v_header jsonb;
  v_group_row record;
  v_movement public.weekly_source_billing_movements%rowtype;
  v_snapshot public.weekly_source_final_snapshot_lines%rowtype;
  v_source_row public.weekly_source_upload_rows%rowtype;
  v_contract public.contracts%rowtype;
  v_candidate public.candidates%rowtype;
  v_ids uuid[];
  v_member_id uuid;
  v_member public.weekly_source_billing_movements%rowtype;
  v_presentation_id uuid;
  v_invoice_line_id uuid;
  v_binding_id uuid;
  v_line_kind text;
  v_origin_kind text;
  v_correction_role text;
  v_old_id uuid;
  v_new_id uuid;
  v_work_date date;
  v_start timestamp without time zone;
  v_end timestamp without time zone;
  v_break integer;
  v_reference text;
  v_description text;
  v_hours_day numeric;
  v_hours_night numeric;
  v_hours_sat numeric;
  v_hours_sun numeric;
  v_hours_bh numeric;
  v_pay_day numeric;
  v_pay_night numeric;
  v_pay_sat numeric;
  v_pay_sun numeric;
  v_pay_bh numeric;
  v_charge_day numeric;
  v_charge_night numeric;
  v_charge_sat numeric;
  v_charge_sun numeric;
  v_charge_bh numeric;
  v_total_pay numeric(12,2);
  v_total_charge numeric(12,2);
  v_calc_pence bigint;
  v_source_pence bigint;
  v_vat_rate numeric(5,2);
  v_vat numeric(12,2);
  v_total numeric(12,2);
  v_price_result text;
  v_price_fingerprint bytea;
  v_mapping_fingerprint bytea;
  v_source_hash bytea;
  v_presentation_hash bytea;
  v_materialised_hash bytea;
  v_placement_hash bytea;
  v_candidate_display text;
  v_client_display text;
  v_is_net boolean;
  v_is_expense boolean;
  v_is_rounding boolean;
  v_release_id uuid;
  v_release_authority jsonb;
  v_release_member uuid;
  v_release_money jsonb;
  v_identity_movement public.weekly_source_billing_movements%rowtype;
  v_count integer;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')
       <>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADMIT_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown from pg_catalog.jsonb_object_keys(p_request) key
  where not (key=any(v_allowed_keys)) order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADMIT_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown;
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_manifest_id:=(p_request->>'client_manifest_id')::uuid;
    v_expected_hash:=pg_catalog.decode(p_request->>'expected_manifest_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADMIT_VALUE_INVALID' using errcode='22023';
  end;
  if pg_catalog.octet_length(v_expected_hash)<>32 then
    raise exception 'WEEKLY_SOURCE_INVOICE_ADMIT_HASH_INVALID' using errcode='22023';
  end if;

  select * into v_manifest from public.weekly_source_client_manifests where id=v_manifest_id;
  if not found then raise exception 'WEEKLY_SOURCE_INVOICE_MANIFEST_CHANGED' using errcode='40001'; end if;
  perform 1 from public.weekly_source_groups where id=v_manifest.source_group_id for update;
  perform 1 from public.weekly_source_cycles where id in (v_manifest.source_cycle_id,coalesce(v_manifest.invoice_window_cycle_id,v_manifest.source_cycle_id)) order by id for update;
  select * into v_manifest from public.weekly_source_client_manifests where id=v_manifest_id for update;
  if not found or v_manifest.manifest_hash is distinct from v_expected_hash then
    raise exception 'WEEKLY_SOURCE_INVOICE_MANIFEST_CHANGED' using errcode='40001';
  end if;
  select * into strict v_revision from public.weekly_source_final_revisions
  where id=v_manifest.final_revision_id for share;
  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_manifest.source_cycle_id for share;
  if v_revision.state<>'CURRENT'
     or v_revision.source_cycle_id is distinct from v_cycle.id
     or v_cycle.source_group_id is distinct from v_manifest.source_group_id
     or not exists(
       select 1 from public.weekly_source_client_cycle_completions completion
       where completion.source_cycle_id=v_cycle.id
         and completion.client_id=v_manifest.client_id
         and completion.final_revision_id=v_revision.id
         and completion.completion_kind='FINAL_SOURCE' and completion.state='CURRENT'
     ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_FINAL_AUTHORITY_STALE' using errcode='40001';
  end if;
  select * into strict v_invoice_window from public.weekly_source_cycles
    where id=coalesce(v_manifest.invoice_window_cycle_id,v_manifest.source_cycle_id);
  if v_invoice_window.source_group_id<>v_manifest.source_group_id
    or v_invoice_window.finalisation_week_ending<>v_manifest.finalisation_week_ending
    or (v_invoice_window.scope_client_id is not null and v_invoice_window.scope_client_id<>v_manifest.client_id) then
    raise exception 'WEEKLY_SOURCE_INVOICE_WINDOW_SCOPE_INVALID' using errcode='55000'; end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'ADMIT_SOURCE_INVOICE',v_manifest.source_group_id,
    v_manifest.client_id,v_manifest.finalisation_week_ending
  );

  if (select pg_catalog.count(*) from public.weekly_source_manifest_movements mm
      where mm.client_manifest_id=v_manifest.id)<>v_manifest.movement_count
     or exists(
       select 1 from public.weekly_source_manifest_movements mm
       join public.weekly_source_billing_movements movement
         on movement.id=mm.billing_movement_id
       where mm.client_manifest_id=v_manifest.id
         and (mm.movement_hash is distinct from movement.movement_economic_hash
           or movement.final_revision_id is distinct from v_revision.id
           or movement.finalisation_cycle_id is distinct from v_cycle.id
           or movement.actual_client_id is distinct from v_manifest.client_id
           or private.weekly_source_invoice_movement_window_id_v1(movement.id)<>v_invoice_window.id
           or (v_invoice_window.id<>v_cycle.id and (movement.source_line_kind not in ('SOURCE_INVOICE_CORRECTION','INVOICE_VAT_ROUNDING')
             or movement.total_pay_ex_vat<>0 or exists(select 1 from jsonb_each_text(movement.canonical_pay_vector_json->'minutes') v where v.value::numeric<>0)
             or exists(select 1 from jsonb_each_text(movement.canonical_pay_vector_json->'hours') v where v.value::numeric<>0))))
     ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MANIFEST_INVALID' using errcode='55000';
  end if;

  if v_manifest.invoice_state='ADMITTED' then
    if exists(
      select 1 from public.weekly_source_manifest_movements mm
      where mm.client_manifest_id=v_manifest.id
        and not exists(
          select 1 from public.weekly_source_invoice_line_bindings binding
          where binding.billing_movement_id=mm.billing_movement_id
            and binding.state='CURRENT'
        )
    ) then
      raise exception 'WEEKLY_SOURCE_INVOICE_ADMITTED_INCOMPLETE' using errcode='55000';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',case when v_manifest.movement_count=0 then 'NO_MOVEMENTS' else 'ADMITTED' end,
      'idempotent',true,'client_manifest_id',v_manifest.id,
      'invoice_ids',coalesce((
        select pg_catalog.jsonb_agg(distinct binding.invoice_id)
        from public.weekly_source_manifest_movements mm
        join public.weekly_source_invoice_line_bindings binding
          on binding.billing_movement_id=mm.billing_movement_id and binding.state='CURRENT'
        where mm.client_manifest_id=v_manifest.id
      ),'[]'::jsonb)
    );
  end if;
  if v_manifest.invoice_state<>'READY' then
    raise exception 'WEEKLY_SOURCE_INVOICE_MANIFEST_NOT_READY' using errcode='55000';
  end if;
  if v_manifest.movement_count=0 then
    update public.weekly_source_client_manifests set invoice_state='ADMITTED'
    where id=v_manifest.id and invoice_state='READY';
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','NO_MOVEMENTS','idempotent',false,
      'client_manifest_id',v_manifest.id,'invoice_ids','[]'::jsonb
    );
  end if;
  if exists(
    select 1 from public.weekly_source_manifest_movements mm
    join public.weekly_source_billing_movements movement on movement.id=mm.billing_movement_id
    where mm.client_manifest_id=v_manifest.id
      and (movement.placement_state<>'UNPLACED'
        or exists(select 1 from public.weekly_source_invoice_line_bindings binding
                  where binding.billing_movement_id=movement.id and binding.state='CURRENT'))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVEMENT_ALREADY_ADMITTED' using errcode='55000';
  end if;

  if exists(select 1 from public.weekly_source_manifest_movements mm join public.weekly_source_billing_movements m on m.id=mm.billing_movement_id
    where mm.client_manifest_id=v_manifest.id and m.source_facts_json->>'invoice_hold'='VAT_FIT'
      and not exists(select 1 from public.weekly_source_invoice_hold_releases receipt where receipt.upload_row_id::text=m.source_facts_json->>'upload_row_id' and receipt.hold_kind='VAT_FIT')) then
    raise exception 'WEEKLY_SOURCE_INVOICE_VAT_FIT_HELD' using errcode='55000'; end if;
  v_receipt_map:=private.weekly_source_invoice_admission_receipt_map_v1(v_manifest.id);
  v_round_authority:=private.weekly_source_invoice_rounding_receipt_set_v1(v_manifest.id,v_receipt_map);
  select * into strict v_client from public.clients where id=v_manifest.client_id for share;
  select * into strict v_defaults from public.settings_defaults where id=1 for share;
  v_header:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_SELF_BILL_INVOICE_V1',
    'client_id',v_client.id,'client_name',v_client.name,
    'client_invoice_address',v_client.invoice_address,
    'client_primary_invoice_email',v_client.primary_invoice_email,
    'payment_terms_days',coalesce(v_client.payment_terms_days,0),
    'agency_name',v_defaults.agency_name,'registered_address',v_defaults.registered_address,
    'company_reg_number',v_defaults.company_reg_number,
    'vat_registration_number',v_defaults.vat_registration_number,
    'meta',pg_catalog.jsonb_build_object(
      'source','WEEKLY_FINAL_SOURCE','self_bill',true,
      'source_group_id',v_manifest.source_group_id,
      'source_cycle_id',v_manifest.source_cycle_id,
      'final_revision_id',v_manifest.final_revision_id,
      'client_manifest_id',v_manifest.id,
      'finalisation_week_ending',v_manifest.finalisation_week_ending,
      'backing_report_numbers',case when v_manifest.backing_report_number is null
        then '[]'::jsonb else pg_catalog.jsonb_build_array(v_manifest.backing_report_number) end,
      'automatic_consolidation','ONE_CLIENT_ONE_FINALISED_CYCLE'
    )||case when v_manifest.invoice_window_cycle_id is null then '{}'::jsonb else jsonb_build_object(
      'invoice_window_cycle_id',v_invoice_window.id,'source_finalisation_week_ending',v_cycle.finalisation_week_ending
    ) end
  );
  insert into public.invoices(
    type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
    notes,header_snapshot_json,do_not_send,document_revision,document_state,issue_state
  ) values (
    'INVOICE',v_manifest.client_id,'DRAFT',pg_catalog.transaction_timestamp(),0,0,0,
    case when v_manifest.backing_report_number is null then null
      else 'Backing report '||v_manifest.backing_report_number end,
    v_header,false,1,'STALE','NOT_STARTED'
  ) returning id into v_invoice_id;

  perform pg_catalog.set_config(
    'cloudtms.weekly_source_invoice_owner','ADMIT_SOURCE_INVOICE',true
  );

  for v_group_row in
    with member as (
      select movement.*,
             movement.source_facts_json->>'correction_presentation' as presentation_policy,
             case
               when movement.source_profile_kind<>'NHSP_TRUST_BACKING_REPORT'
                and movement.correction_unit_id is not null
                and movement.source_facts_json->>'correction_presentation'='NET_DIFFERENCE_PRESENTATION'
               then movement.correction_unit_id else movement.id
             end as presentation_group
      from public.weekly_source_manifest_movements mm
      join public.weekly_source_billing_movements movement
        on movement.id=mm.billing_movement_id
      where mm.client_manifest_id=v_manifest.id
    )
    select presentation_group,
           pg_catalog.array_agg(id order by movement_role,id) as movement_ids,
           pg_catalog.count(*)::integer as member_count,
           pg_catalog.bool_and(source_line_kind='SOURCE_FIXED_EXPENSE') as is_expense,
           pg_catalog.bool_and(presentation_policy='NET_DIFFERENCE_PRESENTATION') as requested_net
    from member
    group by presentation_group
    -- 24 section 12 requires a source-fixed expense presentation to declare the
    -- shift presentation it follows.  weekly_source_invoice_presentation_lines
    -- is IMMUTABLE_APPEND_ONLY, so that declaration has to be written at birth;
    -- every non-expense group is therefore materialised first and the expense
    -- group can then name its companion.  Within each of the two blocks the
    -- established creation order is unchanged.
    order by pg_catalog.bool_and(source_line_kind='SOURCE_FIXED_EXPENSE'),
             pg_catalog.min(created_at_utc),presentation_group
  loop
    v_ids:=v_group_row.movement_ids;
    v_count:=v_group_row.member_count;
    v_is_expense:=v_group_row.is_expense;
    v_is_net:=v_group_row.requested_net and v_count=2;
    if v_count>2
       or (v_count=2 and not v_is_net)
       or (v_is_net and exists(
         select 1 from public.weekly_source_billing_movements movement
         where movement.id=any(v_ids)
           and movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
       ))
       or (v_is_net and (
         select pg_catalog.array_agg(movement.movement_role order by movement.movement_role)
         from public.weekly_source_billing_movements movement where movement.id=any(v_ids)
       ) not in (
         array['REPLACEMENT','REVERSAL']::text[],
         array['EXPENSE_REPLACEMENT','EXPENSE_REVERSAL']::text[]
       ))
       or (v_count=2 and (select pg_catalog.count(distinct movement.correction_unit_id)
           from public.weekly_source_billing_movements movement where movement.id=any(v_ids))<>1)
       or (select pg_catalog.count(distinct movement.work_event_id)
           from public.weekly_source_billing_movements movement where movement.id=any(v_ids))<>1
       or (select pg_catalog.count(distinct movement.final_revision_id)
           from public.weekly_source_billing_movements movement where movement.id=any(v_ids))<>1
       or (select pg_catalog.count(distinct movement.actual_client_id)
           from public.weekly_source_billing_movements movement where movement.id=any(v_ids))<>1 then
      raise exception 'WEEKLY_SOURCE_INVOICE_PRESENTATION_GROUP_INVALID' using errcode='55000';
    end if;

    select * into strict v_movement
    from public.weekly_source_billing_movements movement
    where movement.id=case when v_is_net then (
      select candidate.id from public.weekly_source_billing_movements candidate
      where candidate.id=any(v_ids)
        and candidate.movement_role in ('REPLACEMENT','EXPENSE_REPLACEMENT')
      limit 1
    ) else v_ids[1] end;
    v_round_presentation:=null;
    v_is_rounding:=v_movement.source_line_kind='INVOICE_VAT_ROUNDING';
    v_release_id:=null; v_release_authority:=null; v_release_member:=null;
    if not (v_is_rounding and v_movement.candidate_id is null) then
    select * into strict v_contract from public.contracts
    where id=v_movement.contract_id and client_id=v_manifest.client_id
      and candidate_id=v_movement.candidate_id for share;
    select * into strict v_candidate from public.candidates
    where id=v_movement.candidate_id for share;
    v_candidate_display:=coalesce(nullif(pg_catalog.btrim(v_candidate.display_name),''),
      nullif(pg_catalog.btrim(pg_catalog.concat_ws(' ',v_candidate.first_name,v_candidate.last_name)),''),
      v_candidate.tms_ref,v_candidate.id::text);
    else v_contract:=null; v_candidate:=null; v_candidate_display:=null; end if;
    v_client_display:=coalesce(nullif(pg_catalog.btrim(v_client.name),''),v_client.id::text);

    if v_is_rounding then
      v_work_date:=null; v_start:=null; v_end:=null; v_break:=null; v_reference:=null;
      if v_movement.prior_movement_id is not null then
        select * into strict v_identity_movement from public.weekly_source_billing_movements where id=v_movement.prior_movement_id;
        select snapshot.* into strict v_snapshot from public.weekly_source_state_transitions transition_row
          join public.weekly_source_final_snapshot_lines snapshot on snapshot.id=coalesce(transition_row.new_snapshot_line_id,transition_row.previous_snapshot_line_id)
          where transition_row.id=v_identity_movement.transition_id;
        v_work_date:=v_snapshot.work_date; v_start:=v_snapshot.start_at_local; v_end:=v_snapshot.end_at_local;
        v_break:=v_snapshot.break_minutes; v_reference:=v_snapshot.external_event_identity;
      end if;
    elsif v_is_expense then
      select source_row.* into strict v_source_row
      from public.weekly_expense_authority_generations expense_authority
      join public.weekly_source_row_expense_policy_snapshots expense_policy
        on expense_policy.id=expense_authority.row_expense_policy_snapshot_id
      join public.weekly_source_upload_rows source_row
        on source_row.id=expense_policy.upload_row_id
      where expense_authority.id=case
        when v_movement.movement_role='EXPENSE_REVERSAL' then (
          select prior_movement.expense_authority_generation_id
          from public.weekly_source_billing_movements prior_movement
          where prior_movement.id=v_movement.prior_movement_id
        ) else v_movement.expense_authority_generation_id end;
      v_work_date:=v_source_row.work_date;
      v_start:=v_source_row.start_at_local;
      v_end:=v_source_row.end_at_local;
      v_break:=coalesce(v_source_row.break_minutes,0);
      v_reference:=v_source_row.external_source_key;
    elsif v_movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT' then
      select * into strict v_source_row from public.weekly_source_upload_rows
      where id=v_movement.nhsp_upload_row_id;
      v_work_date:=v_source_row.work_date;
      v_start:=v_source_row.start_at_local;
      v_end:=v_source_row.end_at_local;
      v_break:=v_source_row.break_minutes;
      v_reference:=v_source_row.external_source_key;
    else
      select snapshot.* into strict v_snapshot
      from public.weekly_source_state_transitions transition_row
      join public.weekly_source_final_snapshot_lines snapshot
        on snapshot.id=case
          when v_is_net or v_movement.movement_role in (
            'POSITIVE','REPLACEMENT','EXPENSE_POSITIVE','EXPENSE_REPLACEMENT'
          ) then transition_row.new_snapshot_line_id
          else transition_row.previous_snapshot_line_id end
      where transition_row.final_revision_id=v_manifest.final_revision_id
        and transition_row.work_event_id=v_movement.work_event_id;
      v_work_date:=v_snapshot.work_date;
      v_start:=v_snapshot.start_at_local;
      v_end:=v_snapshot.end_at_local;
      v_break:=v_snapshot.break_minutes;
      v_reference:=v_snapshot.external_event_identity;
    end if;

    v_mapping_fingerprint:=v_movement.mapping_rate_policy_fingerprint;
    v_price_fingerprint:=case when v_count=1 then v_movement.price_check_fingerprint end;

    select
      coalesce(pg_catalog.sum((movement.canonical_pay_vector_json#>>'{hours,day}')::numeric),0),
      coalesce(pg_catalog.sum((movement.canonical_pay_vector_json#>>'{hours,night}')::numeric),0),
      coalesce(pg_catalog.sum((movement.canonical_pay_vector_json#>>'{hours,sat}')::numeric),0),
      coalesce(pg_catalog.sum((movement.canonical_pay_vector_json#>>'{hours,sun}')::numeric),0),
      coalesce(pg_catalog.sum((movement.canonical_pay_vector_json#>>'{hours,bh}')::numeric),0),
      pg_catalog.sum(movement.total_pay_ex_vat),
      pg_catalog.sum(movement.invoice_presentation_charge_pence)::numeric/100,
      pg_catalog.sum(movement.calculated_comparison_charge_pence),
      case when pg_catalog.count(movement.source_validation_charge_pence)=pg_catalog.count(*)
        then pg_catalog.sum(movement.source_validation_charge_pence) end,
      pg_catalog.sum(movement.vat_amount),pg_catalog.sum(movement.total_inc_vat),
      pg_catalog.min(movement.vat_rate_pct),
      case when pg_catalog.count(distinct movement.price_check_result)=1
        then pg_catalog.min(movement.price_check_result) else 'NOT_APPLICABLE' end,
      private.weekly_source_invoice_presentation_source_hash_v1(v_ids,null)
    into v_hours_day,v_hours_night,v_hours_sat,v_hours_sun,v_hours_bh,
         v_total_pay,v_total_charge,v_calc_pence,v_source_pence,v_vat,v_total,
         v_vat_rate,v_price_result,v_source_hash
    from public.weekly_source_billing_movements movement where movement.id=any(v_ids);
    select receipt.id,m.id into v_release_id,v_release_member from public.weekly_source_billing_movements m
      join public.weekly_source_invoice_hold_releases receipt on receipt.upload_row_id::text=m.source_facts_json->>'upload_row_id' and receipt.hold_kind='VAT_FIT'
      where m.id=any(v_ids) and m.movement_role in ('POSITIVE','REPLACEMENT')
        and m.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION');
    if found then
      v_release_money:=private.weekly_source_invoice_movement_money_v1(v_release_member,v_release_id);
      v_release_authority:=v_release_money->'release_authority';
      select v_vat-m.vat_amount+(v_release_money->>'vat_pence')::numeric/100,
        v_total-m.total_inc_vat+(v_release_money->>'gross_pence')::numeric/100 into v_vat,v_total
        from public.weekly_source_billing_movements m where m.id=v_release_member;
      v_source_hash:=private.weekly_source_invoice_presentation_source_hash_v1(v_ids,v_release_id);
    end if;
    if v_is_rounding and v_round_authority is not null then
      if v_ids<>array[(v_round_authority->>'rounding_movement_id')::uuid] then
        raise exception 'WEEKLY_SOURCE_ROUNDING_PRESENTATION_MEMBER_INVALID' using errcode='55000'; end if;
      v_round_presentation:=v_round_authority;
      v_vat:=(v_round_authority->>'admitted_rounding_vat_pence')::numeric/100;
      v_total:=v_vat;
      v_source_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_INVOICE_ROUNDING_PRESENTATION_V1',
        jsonb_build_object('original_movement_source_hash',encode(v_source_hash,'hex'),
          'rounding_authority_sha256',v_round_authority->>'authority_sha256'));
      -- New authority hash is reproducible from exact stored native typmods.
      -- Retained ordinary/NULL-rule presentation hash inputs remain untouched.
      v_hours_day:=v_hours_day::numeric(7,2);v_hours_night:=v_hours_night::numeric(7,2);
      v_hours_sat:=v_hours_sat::numeric(7,2);v_hours_sun:=v_hours_sun::numeric(7,2);v_hours_bh:=v_hours_bh::numeric(7,2);
      v_total_pay:=v_total_pay::numeric(12,2);v_total_charge:=v_total_charge::numeric(12,2);
      v_vat_rate:=v_vat_rate::numeric(5,2);v_vat:=v_vat::numeric(12,2);v_total:=v_total::numeric(12,2);
    end if;
    if v_is_expense then
      v_hours_day:=0;v_hours_night:=0;v_hours_sat:=0;v_hours_sun:=0;v_hours_bh:=0;
      v_pay_day:=null;v_pay_night:=null;v_pay_sat:=null;v_pay_sun:=null;v_pay_bh:=null;
      v_charge_day:=null;v_charge_night:=null;v_charge_sat:=null;v_charge_sun:=null;v_charge_bh:=null;
    else
      v_pay_day:=(v_movement.canonical_pay_vector_json#>>'{rates,day}')::numeric;
      v_pay_night:=(v_movement.canonical_pay_vector_json#>>'{rates,night}')::numeric;
      v_pay_sat:=(v_movement.canonical_pay_vector_json#>>'{rates,sat}')::numeric;
      v_pay_sun:=(v_movement.canonical_pay_vector_json#>>'{rates,sun}')::numeric;
      v_pay_bh:=(v_movement.canonical_pay_vector_json#>>'{rates,bh}')::numeric;
      v_charge_day:=(v_movement.canonical_charge_vector_json#>>'{rates,day}')::numeric;
      v_charge_night:=(v_movement.canonical_charge_vector_json#>>'{rates,night}')::numeric;
      v_charge_sat:=(v_movement.canonical_charge_vector_json#>>'{rates,sat}')::numeric;
      v_charge_sun:=(v_movement.canonical_charge_vector_json#>>'{rates,sun}')::numeric;
      v_charge_bh:=(v_movement.canonical_charge_vector_json#>>'{rates,bh}')::numeric;
    end if;
    v_line_kind:=case
      when v_movement.source_line_kind in ('INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION') then v_movement.source_line_kind
      when v_is_expense then 'SOURCE_FIXED_EXPENSE'
      when v_is_net then 'NON_NHSP_DIFFERENCE'
      when v_movement.movement_role='REPLACEMENT' then 'SOURCE_REPLACEMENT'
      when v_movement.movement_role='REVERSAL' then 'GENERATED_HISTORICAL_REVERSAL'
      else 'SOURCE_ORDINARY' end;
    v_origin_kind:=case
      when v_is_rounding then 'INVOICE_VAT_ROUNDING'
      when v_is_expense then 'SOURCE_FIXED_EXPENSE'
      when v_movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT' then 'NHSP_PHYSICAL_ROW'
      when v_movement.source_profile_kind='HEALTHROSTER_ACTUAL_ROWS' then 'HEALTHROSTER_TRANSITION'
      else 'GENERIC_TRANSITION' end;
    v_correction_role:=case
      when v_is_net then 'NET_DIFFERENCE'
      when v_movement.movement_role in ('REVERSAL','EXPENSE_REVERSAL') then 'REVERSAL'
      when v_movement.movement_role in ('REPLACEMENT','EXPENSE_REPLACEMENT') then 'REPLACEMENT'
      else null end;
    v_old_id:=null;v_new_id:=null;
    select id into v_old_id from public.weekly_source_billing_movements
      where id=any(v_ids) and movement_role in ('REVERSAL','EXPENSE_REVERSAL') limit 1;
    select id into v_new_id from public.weekly_source_billing_movements
      where id=any(v_ids) and movement_role in ('REPLACEMENT','EXPENSE_REPLACEMENT') limit 1;
    v_description:=case when v_is_rounding then 'VAT rounding (matches the client''s self-bill)'
      when v_movement.source_line_kind='SOURCE_INVOICE_CORRECTION' then 'Source invoice correction'
      when v_is_expense then 'Source expense'
      else pg_catalog.concat_ws(' · ',coalesce(v_contract.role,'Shift'),
        pg_catalog.to_char(v_work_date,'Dy DD Mon YYYY'),
        pg_catalog.to_char(v_start,'HH24:MI')||'–'||pg_catalog.to_char(v_end,'HH24:MI'),
        case when v_break>0 then v_break::text||' min break' end) end;
    v_presentation_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_PRESENTATION_V1',
      pg_catalog.jsonb_build_object(
        'client_manifest_id',v_manifest.id,'movement_ids',pg_catalog.to_jsonb(v_ids),
        'line_kind',v_line_kind,'source_shift_group_id',v_movement.work_event_id,
        'work_date',v_work_date,'start_at_local',v_start,'end_at_local',v_end,
        'break_minutes',v_break,'hours',pg_catalog.jsonb_build_array(
          v_hours_day,v_hours_night,v_hours_sat,v_hours_sun,v_hours_bh),
        'total_pay',v_total_pay,'total_charge',v_total_charge,
        'vat_rate',v_vat_rate,'vat',v_vat,'total',v_total,
        'charge_acceptance_id',v_movement.charge_acceptance_id,
        'source_hash',pg_catalog.encode(v_source_hash,'hex')
      )||case when v_release_authority is null then '{}'::jsonb else jsonb_build_object('invoice_hold_release_authority',v_release_authority) end||case when v_round_presentation is null then '{}'::jsonb else jsonb_build_object('weekly_source_rounding_authority',v_round_presentation) end
    );
    insert into public.weekly_source_invoice_presentation_lines(
      billing_movement_id,client_manifest_id,final_revision_id,
      original_finalisation_cycle_id,line_kind,origin_kind,correction_root_id,
      correction_role,old_internal_movement_id,new_internal_movement_id,
      client_id,candidate_id,contract_id,work_event_id,source_shift_group_id,
      role_snapshot,band_snapshot,candidate_display_snapshot,client_display_snapshot,
      work_date,start_at_local,end_at_local,break_minutes,booking_reference_snapshot,
      description_snapshot,hours_day,hours_night,hours_sat,hours_sun,hours_bh,
      pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      total_pay_ex_vat,total_charge_ex_vat,calculated_comparison_charge_pence,
      source_validation_charge_pence,invoice_presentation_charge_pence,
      margin_ex_vat,vat_rate_pct,vat_amount,total_inc_vat,price_check_result,
      price_check_profile,charge_acceptance_id,mapping_rate_policy_fingerprint,source_hash,
      amount_authority,presentation_hash,invoice_hold_release_id,invoice_rounding_authority_json,companion_presentation_line_id
    ) values (
      v_movement.id,v_manifest.id,v_manifest.final_revision_id,v_manifest.source_cycle_id,
      v_line_kind,v_origin_kind,v_movement.correction_unit_id,v_correction_role,
      v_old_id,v_new_id,v_manifest.client_id,v_movement.candidate_id,v_movement.contract_id,
      v_movement.work_event_id,v_movement.work_event_id,v_contract.role,v_contract.band,
      v_candidate_display,v_client_display,v_work_date,v_start,v_end,v_break,v_reference,
      v_description,v_hours_day,v_hours_night,v_hours_sat,v_hours_sun,v_hours_bh,
      v_pay_day,v_pay_night,v_pay_sat,v_pay_sun,v_pay_bh,
      v_charge_day,v_charge_night,v_charge_sat,v_charge_sun,v_charge_bh,
      v_total_pay,v_total_charge,v_calc_pence,v_source_pence,(v_total_charge*100)::bigint,
      v_total_charge-v_total_pay,v_vat_rate,v_vat,v_total,v_price_result,
      case when v_movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
        then 'NHSP_TWO_COMPONENT_PENCE_V1' when private.weekly_source_invoice_source_amount_movement_valid_v1(v_movement.id) then 'SOURCE_INVOICE_MONEY_PENCE_V1' else null end,
      v_movement.charge_acceptance_id,
      v_mapping_fingerprint,v_source_hash,
      case when v_movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT' or v_is_expense
        or private.weekly_source_invoice_source_amount_movement_valid_v1(v_movement.id)
        then 'VALIDATED_SOURCE_PENCE' else 'CLOUDTMS_CALCULATION' end,
      v_presentation_hash,v_release_id,v_round_presentation,
      -- 24 section 12: "a source-fixed expense declared as part of the same
      -- source presentation follows its defined companion relationship; no
      -- unrelated expense or work-event line moves accidentally."  Declared
      -- only when exactly one shift presentation of the same work event and the
      -- same correction role exists in this manifest, so the relationship is
      -- never guessed; null otherwise and the expense then moves on its own.
      -- PostgreSQL has no min(uuid), so the text form is aggregated and cast
      -- back after the having clause has proved the single-value cardinality.
      case when v_is_expense then (
        select pg_catalog.min(shift_line.id::text)::uuid
        from public.weekly_source_invoice_presentation_lines shift_line
        where shift_line.client_manifest_id=v_manifest.id
          and shift_line.work_event_id=v_movement.work_event_id
          and shift_line.line_kind<>'SOURCE_FIXED_EXPENSE'
          and shift_line.correction_role is not distinct from v_correction_role
        having pg_catalog.count(*)=1
      ) end
    ) returning id into v_presentation_id;

    insert into public.invoice_lines(
      invoice_id,timesheet_id,booking_id,description,
      hours_day,hours_night,hours_sat,hours_sun,hours_bh,
      pay_day,pay_night,pay_sat,pay_sun,pay_bh,
      charge_day,charge_night,charge_sat,charge_sun,charge_bh,
      total_pay_ex_vat,total_charge_ex_vat,margin_ex_vat,vat_rate_pct,
      vat_amount,total_inc_vat,meta_json,source_key
    ) values (
      v_invoice_id,v_movement.invoice_timesheet_id,v_reference,v_description,
      v_hours_day,v_hours_night,v_hours_sat,v_hours_sun,v_hours_bh,
      v_pay_day,v_pay_night,v_pay_sat,v_pay_sun,v_pay_bh,
      v_charge_day,v_charge_night,v_charge_sat,v_charge_sun,v_charge_bh,
      v_total_pay,v_total_charge,v_total_charge-v_total_pay,v_vat_rate,v_vat,v_total,
      pg_catalog.jsonb_build_object(
        'line_type','WEEKLY_FINAL_SOURCE','presentation_line_id',v_presentation_id,
        'source_shift_group_id',v_movement.work_event_id,
        'client_manifest_id',v_manifest.id,'movement_ids',pg_catalog.to_jsonb(v_ids)
      )||case when v_release_authority is null then '{}'::jsonb else jsonb_build_object('invoice_hold_release_authority',v_release_authority) end||case when v_round_presentation is null then '{}'::jsonb else jsonb_build_object(
        'weekly_source_rounding_authority',v_round_presentation,
        'presentation_disposition',case when (v_round_presentation->>'suppress_visible_rounding_line')::boolean
          then 'SUPPRESS_ZERO_ROUNDING_AUTHORITY' else 'VISIBLE' end) end,'WEEKLY_SOURCE:'||v_presentation_id::text
    ) returning id into v_invoice_line_id;

    foreach v_member_id in array v_ids loop
      select * into strict v_member from public.weekly_source_billing_movements
      where id=v_member_id;
      v_materialised_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_INVOICE_BINDING_V1',pg_catalog.jsonb_build_object(
          'movement_id',v_member.id,'presentation_line_id',v_presentation_id,
          'invoice_line_id',v_invoice_line_id,'invoice_id',v_invoice_id,
          'manifest_hash',pg_catalog.encode(v_manifest.manifest_hash,'hex'),'binding_version',1
        )
      );
      insert into public.weekly_source_invoice_line_bindings(
        billing_movement_id,presentation_line_id,invoice_line_id,invoice_id,
        original_final_revision_id,original_cycle_id,client_id,correction_root_id,
        correction_role,manifest_hash,materialised_line_hash,binding_version,state
      ) values (
        v_member.id,v_presentation_id,v_invoice_line_id,v_invoice_id,
        v_manifest.final_revision_id,v_manifest.source_cycle_id,v_manifest.client_id,
        v_member.correction_unit_id,v_correction_role,v_manifest.manifest_hash,
        v_materialised_hash,1,'CURRENT'
      ) returning id into v_binding_id;
      v_placement_hash:=private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_INVOICE_PLACEMENT_V1',pg_catalog.jsonb_build_object(
          'movement_id',v_member.id,'invoice_id',v_invoice_id,
          'invoice_line_id',v_invoice_line_id,'placement_revision',1,
          'placement_reason','AUTOMATIC_SOURCE_BATCH'
        )
      );
      insert into public.weekly_source_invoice_placements(
        billing_movement_id,source_shift_group_id,invoice_id,invoice_line_id,
        placement_revision,placement_state,is_current,original_automatic_cycle_id,
        current_target_cycle_id,placement_reason,actor_user_id,placement_hash
      ) values (
        v_member.id,v_member.work_event_id,v_invoice_id,v_invoice_line_id,1,
        'PLACED',true,v_invoice_window.id,v_invoice_window.id,
        'AUTOMATIC_SOURCE_BATCH',v_actor,v_placement_hash
      );
      update public.weekly_source_billing_movements
      set placement_state='PLACED' where id=v_member.id and placement_state='UNPLACED';
      if not found then
        raise exception 'WEEKLY_SOURCE_INVOICE_MOVEMENT_CAS_LOST' using errcode='40001';
      end if;
    end loop;
  end loop;

  insert into public.weekly_source_expense_materialisations(
    expense_authority_generation_id,billing_movement_id,
    invoice_presentation_line_id,expense_lineage_hash,state
  )
  select movement.expense_authority_generation_id,
         (pg_catalog.array_agg(
           movement.id
           order by (movement.movement_role not in (
             'EXPENSE_POSITIVE','EXPENSE_REPLACEMENT'
           )),movement.id
         ))[1],
         (pg_catalog.array_agg(
           binding.presentation_line_id
           order by (movement.movement_role not in (
             'EXPENSE_POSITIVE','EXPENSE_REPLACEMENT'
           )),movement.id
         ))[1],
         private.weekly_source_sha256_jsonb_v1(
           'WEEKLY_SOURCE_EXPENSE_INVOICE_MATERIALISATION_V1',
           pg_catalog.jsonb_build_object(
             'expense_authority_generation_id',movement.expense_authority_generation_id,
             'movement_ids',pg_catalog.jsonb_agg(movement.id order by movement.id),
             'presentation_ids',pg_catalog.jsonb_agg(binding.presentation_line_id order by movement.id)
           )
         ),'MATERIALISED'
  from public.weekly_source_manifest_movements mm
  join public.weekly_source_billing_movements movement on movement.id=mm.billing_movement_id
  join public.weekly_source_invoice_line_bindings binding
    on binding.billing_movement_id=movement.id and binding.state='CURRENT'
  where mm.client_manifest_id=v_manifest.id
    and movement.expense_authority_generation_id is not null
  group by movement.expense_authority_generation_id;

  perform private.weekly_source_invoice_header_refresh_v1(v_invoice_id);
  perform public.invoice_recompute_totals(v_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(v_invoice_id);
  if exists(
    select 1 from public.weekly_source_manifest_movements mm
    where mm.client_manifest_id=v_manifest.id
      and not exists(
        select 1 from public.weekly_source_invoice_line_bindings binding
        where binding.billing_movement_id=mm.billing_movement_id and binding.state='CURRENT'
      )
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MANIFEST_NOT_FULLY_ADMITTED' using errcode='55000';
  end if;
  update public.weekly_source_client_manifests set invoice_state='ADMITTED'
  where id=v_manifest.id and invoice_state='READY';
  if not found then
    raise exception 'WEEKLY_SOURCE_INVOICE_MANIFEST_CAS_LOST' using errcode='40001';
  end if;
  perform pg_catalog.set_config('cloudtms.weekly_source_invoice_owner','',true);

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'invoices',v_invoice_id::text,'WEEKLY_SOURCE_INVOICE_ADMITTED',null,
         pg_catalog.jsonb_build_object(
           'client_manifest_id',v_manifest.id,'source_cycle_id',v_manifest.source_cycle_id,
           'client_id',v_manifest.client_id,'movement_count',v_manifest.movement_count,
           'backing_report_number',v_manifest.backing_report_number
         ),'FINAL_SOURCE_MANIFEST'
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','ADMITTED','idempotent',false,
    'client_manifest_id',v_manifest.id,'invoice_ids',pg_catalog.jsonb_build_array(v_invoice_id),
    'movement_count',v_manifest.movement_count
  );
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function private.weekly_source_invoice_allocation_assert_v1(
  p_invoice_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_invoice public.invoices%rowtype;
  v_line_count integer;
  v_binding_count integer;
  v_has_source_header boolean;
begin
  select * into v_invoice from public.invoices where id=p_invoice_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_INVOICE_NOT_FOUND' using errcode='22023';
  end if;
  select pg_catalog.count(*)::integer into v_binding_count
  from public.weekly_source_invoice_line_bindings binding
  where binding.invoice_id=p_invoice_id and binding.state='CURRENT';
  v_has_source_header:=coalesce(
    v_invoice.header_snapshot_json#>>'{meta,source}'='WEEKLY_FINAL_SOURCE'
    and v_invoice.header_snapshot_json#>>'{meta,self_bill}'='true',false
  );
  if v_binding_count=0 then
    if not v_has_source_header then
      return pg_catalog.jsonb_build_object(
        'ok',true,'is_source_invoice',false,'invoice_id',p_invoice_id
      );
    end if;
    select pg_catalog.count(*)::integer into v_line_count
    from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;
    if v_line_count<>0 then
      raise exception 'WEEKLY_SOURCE_INVOICE_EXTRA_LINE' using errcode='55000';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'is_source_invoice',true,'invoice_id',p_invoice_id,
      'line_count',0,'binding_count',0,'empty',true
    );
  end if;
  if not v_has_source_header then
    raise exception 'WEEKLY_SOURCE_INVOICE_HEADER_INVALID' using errcode='55000';
  end if;
  select pg_catalog.count(*)::integer into v_line_count
  from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;

  if exists(
    select 1 from public.invoice_lines invoice_line
    where invoice_line.invoice_id=p_invoice_id
      and not exists(
        select 1 from public.weekly_source_invoice_line_bindings binding
        where binding.invoice_line_id=invoice_line.id
          and binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      )
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EXTRA_LINE' using errcode='55000';
  end if;

  perform private.weekly_source_invoice_receipt_projection_assert_v1(p_invoice_id);
  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    join public.invoice_lines invoice_line on invoice_line.id=binding.invoice_line_id
    join public.weekly_source_invoice_placements placement
      on placement.billing_movement_id=movement.id and placement.is_current
    join public.weekly_source_manifest_movements manifest_movement
      on manifest_movement.billing_movement_id=movement.id
    join public.weekly_source_client_manifests manifest
      on manifest.id=manifest_movement.client_manifest_id
    where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      and (
        invoice_line.invoice_id is distinct from p_invoice_id
        or placement.invoice_id is distinct from p_invoice_id
        or placement.invoice_line_id is distinct from invoice_line.id
        or placement.placement_state<>'PLACED'
        or placement.original_automatic_cycle_id is distinct from coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)
        or private.weekly_source_invoice_movement_window_id_v1(movement.id) is distinct from coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)
        or binding.client_id is distinct from v_invoice.client_id
        or movement.actual_client_id is distinct from v_invoice.client_id
        or presentation.client_id is distinct from v_invoice.client_id
        or manifest.client_id is distinct from v_invoice.client_id
        or manifest_movement.movement_hash is distinct from movement.movement_economic_hash
        or binding.manifest_hash is distinct from manifest.manifest_hash
        or presentation.client_manifest_id is distinct from manifest.id
        or presentation.final_revision_id is distinct from movement.final_revision_id
        or presentation.original_finalisation_cycle_id is distinct from movement.finalisation_cycle_id
        or invoice_line.timesheet_id is distinct from movement.invoice_timesheet_id
        or invoice_line.total_pay_ex_vat is distinct from presentation.total_pay_ex_vat
        or invoice_line.total_charge_ex_vat is distinct from presentation.total_charge_ex_vat
        or invoice_line.vat_rate_pct is distinct from presentation.vat_rate_pct
        or invoice_line.vat_amount is distinct from presentation.vat_amount
        or invoice_line.total_inc_vat is distinct from presentation.total_inc_vat
        or (presentation.invoice_hold_release_id is not null and (presentation.source_hash is distinct from
          private.weekly_source_invoice_presentation_source_hash_v1((select array_agg(b.billing_movement_id order by b.billing_movement_id)
            from public.weekly_source_invoice_line_bindings b where b.presentation_line_id=presentation.id and b.state='CURRENT'),presentation.invoice_hold_release_id)
          or invoice_line.meta_json->'invoice_hold_release_authority' is distinct from private.weekly_source_invoice_presentation_release_authority_v1(
            (select array_agg(b.billing_movement_id order by b.billing_movement_id) from public.weekly_source_invoice_line_bindings b
              where b.presentation_line_id=presentation.id and b.state='CURRENT'),presentation.invoice_hold_release_id)))
      )
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_ALLOCATION_MISMATCH' using errcode='55000';
  end if;

  if exists(
    select 1
    from (
      select binding.invoice_line_id,
             pg_catalog.count(*)::integer as member_count,
             pg_catalog.count(distinct movement.correction_unit_id) as correction_count,
             pg_catalog.count(distinct movement.work_event_id) as event_count,
             pg_catalog.count(distinct movement.final_revision_id) as revision_count,
             pg_catalog.count(distinct movement.finalisation_cycle_id) as cycle_count,
             pg_catalog.count(distinct movement.actual_client_id) as client_count,
             pg_catalog.count(*) filter(where movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT') as nhsp_count,
             pg_catalog.array_agg(movement.movement_role order by movement.movement_role) as roles,
             pg_catalog.min(presentation.correction_role) as correction_role
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      group by binding.invoice_line_id
    ) grouped
    where grouped.member_count not in (1,2)
       or (grouped.member_count=2 and (
         grouped.correction_count<>1 or grouped.event_count<>1
         or grouped.revision_count<>1 or grouped.cycle_count<>1
         or grouped.client_count<>1 or grouped.nhsp_count<>0
         or grouped.correction_role is distinct from 'NET_DIFFERENCE'
         or grouped.roles not in (
           array['REPLACEMENT','REVERSAL']::text[],
           array['EXPENSE_REPLACEMENT','EXPENSE_REVERSAL']::text[]
         )
       ))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_NET_CARDINALITY_INVALID' using errcode='55000';
  end if;

  if v_invoice.subtotal_ex_vat is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.total_charge_ex_vat),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     )
     or v_invoice.vat_amount is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.vat_amount),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     )
     or v_invoice.total_inc_vat is distinct from (
       select pg_catalog.round(coalesce(pg_catalog.sum(line.total_inc_vat),0),2)
       from public.invoice_lines line where line.invoice_id=p_invoice_id
     ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_TOTAL_MISMATCH' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'is_source_invoice',true,'invoice_id',p_invoice_id,
    'line_count',v_line_count,'binding_count',v_binding_count
  );
end;
$function$;

create or replace function private.weekly_source_invoice_issue_validate_v1(
  p_invoice_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_invoice public.invoices%rowtype;
  v_has_source_header boolean;
  v_binding_count integer;
  v_line_count integer;
  v_codes text[]:=array[]::text[];
  v_detail jsonb:='{}'::jsonb;
  v_assert jsonb;
  v_assert_code text;
  -- The immutable header's source group, read ONCE and only when it really is a
  -- uuid.  A malformed value must fail this invoice closed, never abort the
  -- batch that this invoice happens to share with other invoices.
  v_header_source_group_id uuid;
  v_header_source_group_valid boolean;
  v_validator_error text;
  -- HANDOVER 2 round 5, Part E: the three financial-record states, recorded
  -- separately on the verdict this owner returns.
  v_tsfin jsonb;
  -- WP-28: the enforced and the withheld halves of that ruling, computed by
  -- private.weekly_source_invoice_tsfin_refusal_v1 from the state above.
  v_tsfin_refusal jsonb;
  -- WP-33: the R8A section 1 admission-predicate boundary, applied once, here.
  v_wholly_sealed boolean;
  v_tsfin_codes jsonb;
  v_tsfin_deferred jsonb;
  v_tsfin_disposition text;
begin
  if p_invoice_id is null then
    return pg_catalog.jsonb_build_object('is_source_invoice',false);
  end if;
  select * into v_invoice from public.invoices where id=p_invoice_id;
  if not found then
    -- The ordinary owner already has an exact "not found" behaviour; never
    -- pre-empt it and never claim the source branch for a missing invoice.
    return pg_catalog.jsonb_build_object('is_source_invoice',false);
  end if;

  v_has_source_header:=coalesce(
    v_invoice.header_snapshot_json#>>'{meta,source}'='WEEKLY_FINAL_SOURCE'
    and v_invoice.header_snapshot_json#>>'{meta,self_bill}'='true',false
  );
  select pg_catalog.count(*)::integer into v_binding_count
  from public.weekly_source_invoice_line_bindings binding
  where binding.invoice_id=p_invoice_id and binding.state='CURRENT';

  if not v_has_source_header and v_binding_count=0 then
    return pg_catalog.jsonb_build_object('is_source_invoice',false);
  end if;

  select pg_catalog.count(*)::integer into v_line_count
  from public.invoice_lines invoice_line where invoice_line.invoice_id=p_invoice_id;

  -- Everything from here to the aggregation below is wrapped in ONE handler.
  -- This function is called from inside private._invoice_issue_validate_batch,
  -- which evaluates EVERY invoice of a batch in one statement, so an
  -- unexpected error raised here would abort the verdict of every other
  -- invoice in that batch, including ordinary invoices that have nothing to do
  -- with this one.  An unexpected error is therefore converted into a blocking
  -- code on THIS invoice and nothing else.  It cannot mask an ordinary
  -- invoice: the two "is_source_invoice: false" returns above are outside the
  -- handler, so an ordinary invoice never enters it.
  begin

  -- 24 section 11 qualification list -------------------------------------
  -- "its immutable header says source = WEEKLY_FINAL_SOURCE and self_bill = true"
  if not v_has_source_header then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_HEADER_INVALID'::text;
  end if;
  v_header_source_group_valid:=pg_catalog.pg_input_is_valid(
    coalesce(v_invoice.header_snapshot_json#>>'{meta,source_group_id}',''),'uuid');
  if v_header_source_group_valid then
    v_header_source_group_id:=(v_invoice.header_snapshot_json#>>'{meta,source_group_id}')::uuid;
  else
    -- 24 section 11: the source group is part of the immutable header the
    -- source branch is entered on.  A missing or malformed value is this
    -- invoice's own explicit failure.
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_HEADER_INVALID'::text;
    v_detail:=v_detail||pg_catalog.jsonb_build_object(
      'header_source_group_id_invalid',true
    );
  end if;
  -- "it contains at least one source binding"
  if v_binding_count=0 then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_NO_SOURCE_BINDING'::text;
  end if;
  -- "no empty invoice"
  if v_line_count=0 then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_EMPTY_INVOICE'::text;
  end if;
  -- "no extra ordinary or unbound line is present"
  if exists(
    select 1 from public.invoice_lines invoice_line
    where invoice_line.invoice_id=p_invoice_id
      and not exists(
        select 1 from public.weekly_source_invoice_line_bindings binding
        where binding.invoice_line_id=invoice_line.id
          and binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      )
  ) then
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_UNBOUND_LINE'::text;
  end if;

  -- The established rule body.  weekly_source_invoice_allocation_assert_v1
  -- proves the header shape, extra/unbound lines, manifest hash, movement,
  -- presentation and placement binding, Contract and Client allocation, exact
  -- signed line amounts, VAT, header totals and the net-presentation
  -- cardinality.  It raises; here that becomes a blocker so the real entry
  -- points can report rather than abort.
  begin
    v_assert:=private.weekly_source_invoice_allocation_assert_v1(p_invoice_id);
    if coalesce((v_assert->>'empty')::boolean,false)
       and not (v_codes @> array['WEEKLY_SOURCE_ISSUE_EMPTY_INVOICE']) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_EMPTY_INVOICE'::text;
    end if;
  exception when others then
    get stacked diagnostics v_assert_code=message_text;
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_ALLOCATION_INVALID'::text;
    v_detail:=v_detail||pg_catalog.jsonb_build_object(
      'allocation_assert_error',pg_catalog.left(coalesce(v_assert_code,''),200)
    );
  end;

  if v_binding_count>0 then
    -- "current manifest and final source revision" -------------------------
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      join public.weekly_source_client_manifests manifest
        on manifest.id=manifest_movement.client_manifest_id
      join public.weekly_source_final_revisions revision
        on revision.id=manifest.final_revision_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and revision.state<>'CURRENT'
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_STALE_FINAL_REVISION'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      join public.weekly_source_client_manifests manifest
        on manifest.id=manifest_movement.client_manifest_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          binding.manifest_hash is distinct from manifest.manifest_hash
          or binding.original_final_revision_id is distinct from manifest.final_revision_id
          or binding.original_cycle_id is distinct from manifest.source_cycle_id
          or manifest.invoice_state not in ('PARTLY_ADMITTED','ADMITTED')
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_STALE_MANIFEST'::text;
    end if;

    -- "exact presentation, binding and placement hashes" --------------------
    -- Every hash below is rebuilt from immutable identity text only, so the
    -- comparison is exact.  The presentation source hash is the admission
    -- owner's WEEKLY_SOURCE_INVOICE_PRESENTATION_SOURCE_V1 digest over the
    -- movement set the presentation actually binds, which is also the proof
    -- that the allocation carries no missing or duplicate movement.
    if exists(
      select 1
      from (
        select presentation.id,presentation.source_hash,
          private.weekly_source_invoice_presentation_expected_source_hash_v1(presentation.id) rebuilt
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        group by presentation.id,presentation.source_hash,presentation.invoice_hold_release_id
      ) rebuilt_presentation
      where rebuilt_presentation.rebuilt is distinct from rebuilt_presentation.source_hash
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_PRESENTATION_HASH_INVALID'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and binding.materialised_line_hash is distinct from
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_INVOICE_BINDING_V1',
            case when binding.binding_version=1 then
              pg_catalog.jsonb_build_object(
                'movement_id',binding.billing_movement_id,
                'presentation_line_id',binding.presentation_line_id,
                'invoice_line_id',binding.invoice_line_id,
                'invoice_id',binding.invoice_id,
                'manifest_hash',pg_catalog.encode(binding.manifest_hash,'hex'),
                'binding_version',1
              )
            else
              pg_catalog.jsonb_build_object(
                'movement_id',binding.billing_movement_id,
                'presentation_line_id',binding.presentation_line_id,
                'invoice_line_id',binding.invoice_line_id,
                'invoice_id',binding.invoice_id,
                'manifest_hash',pg_catalog.encode(binding.manifest_hash,'hex'),
                'binding_version',binding.binding_version,
                'prior_binding_id',binding.prior_binding_id
              )
            end
          )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_BINDING_HASH_INVALID'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_placements placement
        on placement.billing_movement_id=binding.billing_movement_id
       and placement.is_current
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and placement.placement_hash is distinct from
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_INVOICE_PLACEMENT_V1',
            case when placement.placement_revision=1 then
              pg_catalog.jsonb_build_object(
                'movement_id',placement.billing_movement_id,
                'invoice_id',placement.invoice_id,
                'invoice_line_id',placement.invoice_line_id,
                'placement_revision',1,
                'placement_reason',placement.placement_reason
              )
            else
              pg_catalog.jsonb_build_object(
                'movement_id',placement.billing_movement_id,
                'invoice_id',placement.invoice_id,
                'invoice_line_id',placement.invoice_line_id,
                'placement_revision',placement.placement_revision,
                'placement_reason',placement.placement_reason,
                'prior_placement_id',placement.prior_placement_id,
                'source_invoice_version_fingerprint',
                  pg_catalog.encode(placement.source_invoice_version_fingerprint,'hex'),
                'destination_invoice_version_fingerprint',
                  pg_catalog.encode(placement.destination_invoice_version_fingerprint,'hex')
              )
            end
          )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_PLACEMENT_HASH_INVALID'::text;
    end if;

    -- "complete allocation with no missing or duplicate movement" ----------
    -- Every movement of every manifest this invoice draws on is either bound
    -- here or bound CURRENT somewhere else; none is bound twice; and the
    -- invoice never carries a movement its manifest does not contain.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
      group by binding.billing_movement_id
      having pg_catalog.count(*)>1
    ) or exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and not exists(
          select 1 from public.weekly_source_manifest_movements manifest_movement
          where manifest_movement.billing_movement_id=binding.billing_movement_id
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_DUPLICATE_MOVEMENT'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.weekly_source_invoice_line_bindings sibling
        on sibling.presentation_line_id=presentation.id
       and sibling.state='CURRENT'
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and sibling.invoice_id is distinct from p_invoice_id
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_MISSING_MOVEMENT'::text;
    end if;

    -- Every bound movement is still placed on this invoice and has not been
    -- voided by a later Correct Final Source.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      left join public.weekly_source_invoice_placements placement
        on placement.billing_movement_id=movement.id and placement.is_current
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          movement.placement_state not in ('PLACED','ISSUED')
          or placement.id is null
          or placement.placement_state<>'PLACED'
          or placement.invoice_id is distinct from p_invoice_id
          or placement.invoice_line_id is distinct from binding.invoice_line_id
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_MOVEMENT_NOT_PLACED'::text;
    end if;

    -- "Client, source group, cycle, currency and VAT consistency" -----------
    -- CloudTMS invoices carry no per-invoice currency column, so currency
    -- consistency is structural: one Client, one source group.  Cycle
    -- consistency is deliberately NOT one cycle per invoice: 24 section 12
    -- allows a confirmed cross-week move, and the header records every
    -- contained cycle.  What must hold is that the header's contained sets
    -- describe exactly the manifests the bindings actually reference.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      join public.weekly_source_client_manifests manifest
        on manifest.id=manifest_movement.client_manifest_id
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          manifest.client_id is distinct from v_invoice.client_id
          or movement.actual_client_id is distinct from v_invoice.client_id
          or presentation.client_id is distinct from v_invoice.client_id
          or binding.client_id is distinct from v_invoice.client_id
          or manifest.source_group_id is distinct from v_header_source_group_id
        )
    ) or exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_manifest_movements manifest_movement
        on manifest_movement.billing_movement_id=binding.billing_movement_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and not (
          coalesce(
            v_invoice.header_snapshot_json#>'{meta,contained_client_manifest_ids}',
            '[]'::jsonb
          ) @> pg_catalog.to_jsonb(manifest_movement.client_manifest_id)
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_SCOPE_INCONSISTENT'::text;
    end if;
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.invoice_lines invoice_line on invoice_line.id=binding.invoice_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and invoice_line.vat_rate_pct is distinct from presentation.vat_rate_pct
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_SCOPE_INCONSISTENT'::text;
    end if;

    -- Immutable automatic invoice windows remain distinct from original Source
    -- cycle witnesses. The header must describe the actual complete bound set.
    if coalesce(v_invoice.header_snapshot_json#>'{meta,contained_invoice_window_cycle_ids}',
        v_invoice.header_snapshot_json#>'{meta,contained_source_cycle_ids}','[]'::jsonb)
      is distinct from coalesce((select jsonb_agg(window_id order by window_id) from (
        select distinct coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id) window_id
          from public.weekly_source_invoice_line_bindings binding
          join public.weekly_source_manifest_movements mm on mm.billing_movement_id=binding.billing_movement_id
          join public.weekly_source_client_manifests manifest on manifest.id=mm.client_manifest_id
          where binding.invoice_id=p_invoice_id and binding.state='CURRENT') actual),'[]'::jsonb) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_WINDOW_SCOPE_INCONSISTENT'::text;
    end if;
    -- "NHSP physical negative and positive independence" (24 section 10) -----
    -- An NHSP physical row is one movement, one presentation, one visible line;
    -- it is never netted with another physical row.
    if exists(
      select 1
      from public.weekly_source_invoice_presentation_lines presentation
      join public.weekly_source_invoice_line_bindings binding
        on binding.presentation_line_id=presentation.id
       and binding.state='CURRENT'
      where binding.invoice_id=p_invoice_id
        and presentation.origin_kind='NHSP_PHYSICAL_ROW'
      group by presentation.id,binding.invoice_line_id
      having pg_catalog.count(*)<>1
    ) or exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          (presentation.origin_kind='NHSP_PHYSICAL_ROW')
            <>(movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT')
          or (presentation.origin_kind='NHSP_PHYSICAL_ROW'
              and presentation.correction_role='NET_DIFFERENCE')
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_NHSP_NETTING_DETECTED'::text;
    end if;

    -- "the configured non-NHSP correction shape" (24 section 10) ------------
    -- FULL pair: one movement per presentation, correction_role REVERSAL or
    -- REPLACEMENT.  NET: exactly the reversal/replacement pair of one
    -- correction unit on one visible line, correction_role NET_DIFFERENCE.
    if exists(
      select 1
      from (
        select presentation.id,presentation.correction_role,
          pg_catalog.count(*)::integer member_count,
          pg_catalog.count(distinct movement.correction_unit_id) correction_count,
          pg_catalog.array_agg(movement.movement_role order by movement.movement_role) roles
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        group by presentation.id,presentation.correction_role
      ) shaped
      where shaped.member_count not in (1,2)
        or (shaped.member_count=2 and (
          shaped.correction_role is distinct from 'NET_DIFFERENCE'
          or shaped.correction_count<>1
          or shaped.roles not in (
            array['REPLACEMENT','REVERSAL']::text[],
            array['EXPENSE_REPLACEMENT','EXPENSE_REVERSAL']::text[]
          )
        ))
        or (shaped.member_count=1 and shaped.correction_role='NET_DIFFERENCE')
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_CORRECTION_SHAPE_INVALID'::text;
    end if;

    -- "source price comparison success" (24 section 13) ---------------------
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_invoice_presentation_lines presentation
        on presentation.id=binding.presentation_line_id
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          (presentation.origin_kind='NHSP_PHYSICAL_ROW'
            and (presentation.price_check_result not in (
                'EXACT','SOURCE_ROUNDING_EQUIVALENT','ACCEPTED_DISPARITY','ACCEPTED_ZERO'
              )
              or presentation.amount_authority<>'VALIDATED_SOURCE_PENCE'
              or presentation.source_validation_charge_pence is null
              or presentation.invoice_presentation_charge_pence
                 is distinct from presentation.source_validation_charge_pence
              or presentation.charge_acceptance_id is distinct from movement.charge_acceptance_id
              or (presentation.price_check_result in ('ACCEPTED_DISPARITY','ACCEPTED_ZERO')
                and not exists(
                  select 1 from public.weekly_source_charge_acceptances acceptance
                  where acceptance.id=presentation.charge_acceptance_id
                    and acceptance.acceptance_kind=presentation.price_check_result
                    and acceptance.upload_row_id=movement.nhsp_upload_row_id
                    and acceptance.contract_id=movement.contract_id
                    and acceptance.charge_calculation_fingerprint=movement.price_check_fingerprint
                    and acceptance.acceptance_policy_fingerprint=
                      private.weekly_source_charge_acceptance_policy_fingerprint_v1()
                ))))
          or (presentation.origin_kind='SOURCE_FIXED_EXPENSE'
            and (presentation.price_check_result<>'NOT_APPLICABLE'
              or presentation.amount_authority<>'VALIDATED_SOURCE_PENCE'))
          or (presentation.amount_authority='VALIDATED_SOURCE_PENCE' and movement.source_line_kind in ('SOURCE_ORDINARY','SOURCE_REPLACEMENT','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION') and private.weekly_source_invoice_source_amount_movement_valid_v1(movement.id) is distinct from true)
          or (presentation.origin_kind not in ('NHSP_PHYSICAL_ROW','SOURCE_FIXED_EXPENSE')
            and not (private.weekly_source_invoice_source_amount_movement_valid_v1(movement.id)
              and presentation.amount_authority='VALIDATED_SOURCE_PENCE')
            and presentation.amount_authority<>'CLOUDTMS_CALCULATION')
          or (movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
            and movement.price_check_result
              not in ('EXACT','SOURCE_ROUNDING_EQUIVALENT','ACCEPTED_DISPARITY','ACCEPTED_ZERO'))
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_PRICE_CHECK_FAILED'::text;
    end if;

    -- "exact signed line amounts, VAT and header total" ---------------------
    -- The allocation assert already compares the visible line with its
    -- presentation and the header with the sum of its lines.  What it does not
    -- do is tie the presentation back to the immutable movements it binds.
    if exists(
      select 1
      from (
        select presentation.id,
          presentation.total_pay_ex_vat,presentation.total_charge_ex_vat,
          presentation.vat_amount,presentation.total_inc_vat,
          presentation.invoice_presentation_charge_pence,
          presentation.calculated_comparison_charge_pence,
          pg_catalog.sum(movement.total_pay_ex_vat) movement_pay,
          pg_catalog.sum((private.weekly_source_invoice_admitted_member_money_v1(presentation.id,movement.id)->>'vat_pence')::numeric/100) movement_vat,
          pg_catalog.sum((private.weekly_source_invoice_admitted_member_money_v1(presentation.id,movement.id)->>'gross_pence')::numeric/100) movement_total,
          pg_catalog.sum(movement.invoice_presentation_charge_pence) movement_pence,
          pg_catalog.sum(movement.calculated_comparison_charge_pence) movement_calc_pence
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        group by presentation.id,presentation.total_pay_ex_vat,
          presentation.total_charge_ex_vat,presentation.vat_amount,
          presentation.total_inc_vat,presentation.invoice_presentation_charge_pence,
          presentation.calculated_comparison_charge_pence
      ) amounts
      where amounts.total_pay_ex_vat is distinct from amounts.movement_pay
        or amounts.vat_amount is distinct from amounts.movement_vat
        or amounts.total_inc_vat is distinct from amounts.movement_total
        or amounts.invoice_presentation_charge_pence is distinct from amounts.movement_pence
        or amounts.calculated_comparison_charge_pence is distinct from amounts.movement_calc_pence
        or amounts.invoice_presentation_charge_pence
           is distinct from (amounts.total_charge_ex_vat*100)::bigint
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_AMOUNT_MISMATCH'::text;
    end if;
    if v_invoice.subtotal_ex_vat is distinct from (
         select pg_catalog.round(coalesce(pg_catalog.sum(line.total_charge_ex_vat),0),2)
         from public.invoice_lines line where line.invoice_id=p_invoice_id
       )
       or v_invoice.vat_amount is distinct from (
         select pg_catalog.round(coalesce(pg_catalog.sum(line.vat_amount),0),2)
         from public.invoice_lines line where line.invoice_id=p_invoice_id
       )
       or v_invoice.total_inc_vat is distinct from (
         select pg_catalog.round(coalesce(pg_catalog.sum(line.total_inc_vat),0),2)
         from public.invoice_lines line where line.invoice_id=p_invoice_id
       ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_TOTAL_MISMATCH'::text;
    end if;

    -- "Timesheet relationship where required for navigation, without treating
    -- Candidate evidence as invoice authority" (24 section 11; proof/34 section 9).
    -- The visible line keeps the immutable Timesheet identity the movement was
    -- written against.  Nothing here reads authorisation, signature, PDF or
    -- any other Candidate evidence, and nothing re-points a line.
    if exists(
      select 1
      from public.weekly_source_invoice_line_bindings binding
      join public.weekly_source_billing_movements movement
        on movement.id=binding.billing_movement_id
      join public.invoice_lines invoice_line on invoice_line.id=binding.invoice_line_id
      where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
        and (
          (invoice_line.timesheet_id is null and not (movement.invoice_timesheet_id is null and (movement.source_line_kind='INVOICE_VAT_ROUNDING'
            or (movement.source_line_kind='SELF_BILL_REPORT_LINE' and movement.movement_role='STANDALONE_NEGATIVE'))))
          or invoice_line.timesheet_id is distinct from movement.invoice_timesheet_id
          or invoice_line.invoice_id is distinct from p_invoice_id
        )
    ) then
      v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_TIMESHEET_LINK_INVALID'::text;
    end if;
  end if;

    -- HANDOVER 2 round 5, Part E "Invoice and TSFIN outcomes": the three
    -- financial-record states are RECORDED SEPARATELY on the verdict so a
    -- consumer of this owner can tell them apart without reading this body.
    v_tsfin:=private.weekly_source_invoice_tsfin_state_v1(p_invoice_id);
    v_detail:=v_detail||pg_catalog.jsonb_build_object('tsfin',v_tsfin);

  exception when others then
    get stacked diagnostics v_validator_error=message_text;
    v_codes:=v_codes||'WEEKLY_SOURCE_ISSUE_VALIDATOR_ERROR'::text;
    v_detail:=v_detail||pg_catalog.jsonb_build_object(
      'validator_error',pg_catalog.left(coalesce(v_validator_error,''),200)
    );
  end;

  select pg_catalog.array_agg(distinct code order by code)
    into v_codes from pg_catalog.unnest(v_codes) code;
  v_codes:=coalesce(v_codes,array[]::text[]);

  -- WP-28.  The financial-record refusal is computed OUTSIDE the handler above,
  -- so a validator that blew up leaves v_tsfin null and the predicate returns
  -- WEEKLY_SOURCE_ISSUE_TSFIN_STATE_UNDETERMINED rather than nothing.
  --
  -- WP-33, HANDOVER 2 round 8 Part 2.1.  The predicate now answers several
  -- separate questions from the one state document, and this verdict carries
  -- each of them on its own key because the ruling keeps them apart:
  --   tsfin_blocker_codes          what ACTUALLY stops the INVOICE today;
  --   tsfin_invoice_disposition    the explicit typed invoice outcome, which is
  --                                what both seams consume - an omission is not
  --                                an outcome, so a seam that cannot read this
  --                                key fails closed;
  --   tsfin_payment_blocker_codes  the RETAINED expected-but-missing fact, which
  --                                is non-empty for the exempt case too so that
  --                                payment and financial publication stay
  --                                fail-closed while the invoice issues;
  --   tsfin_deferred_blocker_codes the expected-but-missing INVOICE refusal that
  --                                round 8 Part 2.1 requires and sealed pack 02
  --                                section 15 forbids.  Computed, named, NOT
  --                                enforced, with a reason that is true today.
  --
  -- The WP-28 tsfin_withheld_* keys are RETIRED and deliberately not renamed
  -- back into use: their reason named the round-6 question, and the approver has
  -- answered that question.  Standing rule 12 forbids shipping a fail-closed
  -- reason that is no longer true, so the deferred keys above carry the reason
  -- that IS true - an outstanding admission-predicate boundary correction.
  --
  -- It is carried on its OWN key and is deliberately NOT folded into
  -- blocker_codes, so `ok` keeps its exact 24 section 11 meaning - "the exact
  -- source branch passes" - and an admitted source invoice still skips only the
  -- four irrelevant ordinary evidence categories.  Folding a Candidate
  -- financial-record refusal into `ok` would additionally (a) stop the direct
  -- owner skipping public._ctms_assert_invoice_correction_lines_v1, turning an
  -- ON_HOLD into a raised exception, and (b) re-impose every ordinary evidence
  -- requirement the pack says is irrelevant to source self-billing.  Both seams
  -- append this array unconditionally, in the ok and the not-ok branch alike.
  v_tsfin_refusal:=private.weekly_source_invoice_tsfin_refusal_v1(v_tsfin);

  -- =========================================================================
  -- WP-33, HANDOVER 2 CORRECTION ADDENDUM R8A section 1 - the ADMISSION
  -- PREDICATE BOUNDARY.  This is the one place the boundary is applied, and it
  -- is applied to a verdict whose source-side truth has ALREADY been decided
  -- immediately above.
  --
  -- R8A section 1 is LATER authority than round 8 and is accepted by the
  -- product owner.  It withdraws round 8 Part 2.2 and Part 6 item 6 for a
  -- wholly sealed source-backed self-bill, word for word:
  --
  --   "Candidate Timesheet authorisation, Candidate-pay TSFIN existence/
  --    currentness/status, READY_FOR_INVOICE, pay holds, advances, settlement
  --    and pay query/reconciliation state are never self-bill admission
  --    predicates."
  --   "A stale or missing Candidate-pay TSFIN likewise does not block an
  --    otherwise-valid immutable final-source invoice movement.  It blocks
  --    Candidate-pay publication, readiness or reconciliation wherever those
  --    owners require current pay evidence."
  --
  -- and restores 02 CONTROLLING POLICY section 15 and acceptance row ISS-013
  -- ("Source invoice while Candidate pay pending/protected/frozen" -> ISSUED).
  --
  -- WHOLLY SEALED IS A POSITIVE TEST, and R8A's first precision point says so:
  -- "This must be implemented as a positive test of sealed status, never
  -- inherited by anything partially sealed or merely source-adjacent."  The
  -- test is cardinality(v_codes)=0 - the exact 24 section 11 branch, every
  -- source-side limb proved: current manifest and final source revision, exact
  -- presentation/binding/placement hashes, complete allocation with no missing
  -- or duplicate movement, every line bound, no extra ordinary line, exact
  -- signed amounts, VAT and header total, Client/group/cycle/currency/VAT
  -- consistency, NHSP physical independence, the configured correction shape,
  -- source price comparison success and a non-empty invoice.  It is the SAME
  -- value returned as `ok`, computed here and not re-read, so the two can never
  -- drift apart.
  --
  -- IF IT IS NOT PROVED, THE OLD BEHAVIOUR STANDS: every Candidate-pay TSFIN
  -- code remains an invoice blocker exactly as WP-28 installed it.  A mixed,
  -- unbound, tampered or partly sealed invoice is already failing closed on its
  -- own source codes and gains nothing here.
  --
  -- WHAT MOVES, AND WHAT DOES NOT.  For a wholly sealed self-bill every
  -- Candidate-pay TSFIN code moves from tsfin_blocker_codes to
  -- tsfin_deferred_blocker_codes - stale, expected-but-missing and the
  -- undetermined/disagreement codes alike, because each of them is a judgement
  -- about the Candidate financial record and R8A names that whole class.
  -- tsfin_payment_blocker_codes is NOT touched by any of this: it already
  -- carries the same facts and it is what keeps Candidate-pay publication,
  -- readiness and reconciliation fail-closed.  The invoice moves; the payment
  -- does not.  Nothing in v_codes - the source-side truth - is touched either.
  -- =========================================================================
  v_wholly_sealed:=cardinality(v_codes)=0;
  v_tsfin_codes:=coalesce(v_tsfin_refusal->'blocker_codes','[]'::jsonb);
  v_tsfin_deferred:=coalesce(v_tsfin_refusal->'deferred_blocker_codes','[]'::jsonb);
  v_tsfin_disposition:=coalesce(v_tsfin_refusal->>'invoice_disposition','');
  if v_wholly_sealed and pg_catalog.jsonb_typeof(v_tsfin_codes)='array'
     and pg_catalog.jsonb_typeof(v_tsfin_deferred)='array' then
    if pg_catalog.jsonb_array_length(v_tsfin_codes)>0 then
      -- The sorted union of the two arrays, so the deferred record stays a set
      -- and its order can never carry meaning.
      select coalesce(pg_catalog.jsonb_agg(code order by code),'[]'::jsonb)
        into v_tsfin_deferred
      from (
        select distinct element.value code
        from pg_catalog.jsonb_array_elements_text(
          v_tsfin_codes||v_tsfin_deferred) as element(value)
      ) merged;
      v_tsfin_codes:='[]'::jsonb;
      -- The typed outcome.  The proved first-authorisation state keeps its own
      -- name, because R8A names it separately and round 8 Part 2.1 requires an
      -- explicit typed disposition for it; every other Candidate-pay condition
      -- on a wholly sealed self-bill gets the boundary's own name.
      if v_tsfin_disposition
           <>'WEEKLY_SOURCE_INVOICE_TSFIN_AWAITING_FIRST_AUTHORISATION_EXEMPT' then
        v_tsfin_disposition:=
          'WEEKLY_SOURCE_INVOICE_TSFIN_CANDIDATE_PAY_NOT_ADMISSION_PREDICATE';
      end if;
    elsif v_tsfin_disposition
            ='WEEKLY_SOURCE_INVOICE_TSFIN_EXPECTED_BUT_MISSING_NOT_ENFORCED' then
      v_tsfin_disposition:=
        'WEEKLY_SOURCE_INVOICE_TSFIN_CANDIDATE_PAY_NOT_ADMISSION_PREDICATE';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'is_source_invoice',true,
    'ok',cardinality(v_codes)=0,
    'invoice_id',p_invoice_id,
    'line_count',v_line_count,
    'binding_count',v_binding_count,
    'wholly_sealed_source_self_bill',v_wholly_sealed,
    'blocker_codes',pg_catalog.to_jsonb(v_codes),
    'tsfin_blocker_codes',v_tsfin_codes,
    'tsfin_invoice_disposition',v_tsfin_disposition,
    'tsfin_payment_blocker_codes',
      coalesce(v_tsfin_refusal->'payment_blocker_codes','[]'::jsonb),
    'tsfin_deferred_blocker_codes',v_tsfin_deferred,
    'tsfin_deferred_reason',
      case when pg_catalog.jsonb_array_length(v_tsfin_deferred)>0
        then case when v_wholly_sealed
          then 'WEEKLY_SOURCE_TSFIN_CANDIDATE_PAY_NOT_A_SELF_BILL_ADMISSION_PREDICATE'
          else v_tsfin_refusal->>'deferred_reason' end end,
    'tsfin_deferred_authority',
      case when pg_catalog.jsonb_array_length(v_tsfin_deferred)>0
        then case when v_wholly_sealed
          then 'HANDOVER 2 CORRECTION ADDENDUM R8A section 1, later authority than '
            ||'round 8 and accepted by the product owner; sealed pack '
            ||'02 CONTROLLING POLICY section 15, annex FTI-013 and acceptance row '
            ||'ISS-013. The fact is retained for Candidate-pay publication, '
            ||'readiness and reconciliation in tsfin_payment_blocker_codes'
          else v_tsfin_refusal->>'deferred_authority' end end,
    'detail',v_detail
  );
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function private.weekly_source_invoice_header_refresh_v1(
  p_invoice_id uuid
) returns void
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_manifest_ids jsonb;
  v_cycle_ids jsonb; v_invoice_window_ids jsonb;
  v_week_endings jsonb;
  v_backing_reports jsonb;
begin
  with facts as materialized (
    select distinct manifest.id as manifest_id,manifest.source_cycle_id,coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id) invoice_window_cycle_id,
           manifest.finalisation_week_ending,manifest.backing_report_number
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_manifest_movements manifest_movement
      on manifest_movement.billing_movement_id=binding.billing_movement_id
    join public.weekly_source_client_manifests manifest
      on manifest.id=manifest_movement.client_manifest_id
    where binding.invoice_id=p_invoice_id and binding.state='CURRENT'
  )
  select
    coalesce((select pg_catalog.jsonb_agg(f.manifest_id order by f.manifest_id)
              from facts f),'[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(c.source_cycle_id order by c.source_cycle_id)
              from (select distinct source_cycle_id from facts) c),'[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(w.finalisation_week_ending order by w.finalisation_week_ending)
              from (select distinct finalisation_week_ending from facts) w),'[]'::jsonb),
    coalesce((select pg_catalog.jsonb_agg(r.backing_report_number order by r.backing_report_number)
              from (select distinct backing_report_number from facts
                    where backing_report_number is not null) r),'[]'::jsonb)
    ,coalesce((select jsonb_agg(w.invoice_window_cycle_id order by w.invoice_window_cycle_id)
      from (select distinct invoice_window_cycle_id from facts) w),'[]'::jsonb)
  into v_manifest_ids,v_cycle_ids,v_week_endings,v_backing_reports,v_invoice_window_ids;

  update public.invoices invoice
  set header_snapshot_json=pg_catalog.jsonb_set(
        invoice.header_snapshot_json,'{meta}',
        (coalesce(invoice.header_snapshot_json->'meta','{}'::jsonb)-'contained_invoice_window_cycle_ids')
          ||pg_catalog.jsonb_build_object(
            'contained_client_manifest_ids',v_manifest_ids,
            'contained_source_cycle_ids',v_cycle_ids,
            'contained_finalisation_week_endings',v_week_endings,
            'backing_report_numbers',v_backing_reports
          )||case when v_invoice_window_ids=v_cycle_ids then '{}'::jsonb else jsonb_build_object(
            'contained_invoice_window_cycle_ids',v_invoice_window_ids
          ) end,true
      ),
      updated_at=pg_catalog.statement_timestamp()
  where invoice.id=p_invoice_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_INVOICE_NOT_FOUND' using errcode='22023';
  end if;
end;
$function$;

create or replace function public.weekly_source_invoice_move_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed_keys constant text[]:=array[
    'actor_user_id','source_invoice_id','destination_invoice_id',
    'presentation_line_id','invoice_line_id','expected_presentation_hash',
    'expected_source_document_revision',
    'expected_destination_document_revision','reason'
  ]::text[];
  v_required_keys constant text[]:=array[
    'actor_user_id','source_invoice_id','destination_invoice_id',
    'expected_presentation_hash','expected_source_document_revision',
    'expected_destination_document_revision','reason'
  ]::text[];
  v_unknown text;
  v_actor uuid;
  v_source_invoice_id uuid;
  v_destination_invoice_id uuid;
  v_presentation_line_id uuid;
  v_invoice_line_id uuid;
  v_expected_presentation_hash bytea;
  v_expected_source_revision bigint;
  v_expected_destination_revision bigint;
  v_reason text;
  v_selected public.weekly_source_invoice_presentation_lines%rowtype;
  v_presentation_ids uuid[];
  v_companion_count integer;
  v_source public.invoices%rowtype;
  v_destination public.invoices%rowtype;
  v_source_manifest public.weekly_source_client_manifests%rowtype;
  v_destination_manifest public.weekly_source_client_manifests%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_source_fingerprint bytea;
  v_destination_fingerprint bytea;
  v_line_ids uuid[];
  v_line_count integer;
  v_updated_line_count integer;
  v_movement_count integer;
  v_binding_invoice_ids uuid[];
  v_binding record;
  v_placement public.weekly_source_invoice_placements%rowtype;
  v_new_binding_version integer;
  v_new_placement_revision integer;
  v_binding_hash bytea;
  v_placement_hash bytea;
  v_replay_count integer;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')
       <>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown from pg_catalog.jsonb_object_keys(p_request) key
  where not (key=any(v_allowed_keys)) order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_UNKNOWN_FIELD'
      using errcode='22023',detail=v_unknown;
  end if;
  if not (p_request ?& v_required_keys) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_REQUEST_INVALID' using errcode='22023';
  end if;
  -- 24 section 12 is a contract over VALUES; ?& above proves only that a key
  -- EXISTS.  A key present with a JSON null passes ?&, and ->> on a JSON null
  -- yields SQL NULL, which no cast rejects, so a null would reach a predicate
  -- and be swallowed by three-valued logic.  Every required value is therefore
  -- type-gated here, before anything is parsed.  The two optional identity keys
  -- may be JSON null, which is how "not supplied" has always been expressed,
  -- but may not be any other non-string type.
  if pg_catalog.jsonb_typeof(p_request->'actor_user_id') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'source_invoice_id') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'destination_invoice_id') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'expected_presentation_hash') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'reason') is distinct from 'string'
     or pg_catalog.jsonb_typeof(p_request->'expected_source_document_revision')
          is distinct from 'number'
     or pg_catalog.jsonb_typeof(p_request->'expected_destination_document_revision')
          is distinct from 'number'
     or coalesce(pg_catalog.jsonb_typeof(p_request->'presentation_line_id'),'null')
          not in ('string','null')
     or coalesce(pg_catalog.jsonb_typeof(p_request->'invoice_line_id'),'null')
          not in ('string','null') then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VALUE_INVALID' using errcode='22023';
  end if;
  -- Exactly one of the two identities 24 section 12 allows.
  if ((nullif(p_request->>'presentation_line_id','') is not null)::integer
     +(nullif(p_request->>'invoice_line_id','') is not null)::integer)<>1 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_IDENTITY_REQUIRED' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_source_invoice_id:=(p_request->>'source_invoice_id')::uuid;
    v_destination_invoice_id:=(p_request->>'destination_invoice_id')::uuid;
    v_presentation_line_id:=nullif(p_request->>'presentation_line_id','')::uuid;
    v_invoice_line_id:=nullif(p_request->>'invoice_line_id','')::uuid;
    v_expected_source_revision:=(p_request->>'expected_source_document_revision')::bigint;
    v_expected_destination_revision:=(p_request->>'expected_destination_document_revision')::bigint;
    if coalesce(p_request->>'expected_presentation_hash','') !~ '^[0-9a-f]{64}$' then
      raise exception 'invalid presentation hash';
    end if;
    v_expected_presentation_hash:=pg_catalog.decode(
      p_request->>'expected_presentation_hash','hex'
    );
  exception when others then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VALUE_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_source_invoice_id=v_destination_invoice_id
     or coalesce(v_expected_source_revision,0)<1
     or coalesce(v_expected_destination_revision,0)<1
     or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VALUE_INVALID' using errcode='22023';
  end if;
  v_source_fingerprint:=private.weekly_source_invoice_expected_version_fingerprint_v1(
    v_source_invoice_id,v_expected_source_revision
  );
  v_destination_fingerprint:=private.weekly_source_invoice_expected_version_fingerprint_v1(
    v_destination_invoice_id,v_expected_destination_revision
  );

  -- Resolve the selected presentation line.  The invoice-line identity is the
  -- alternative 24 section 12 allows; it resolves to exactly one presentation,
  -- otherwise the selection is ambiguous and is refused.
  if v_presentation_line_id is null then
    select pg_catalog.count(distinct binding.presentation_line_id)::integer,
           pg_catalog.min(binding.presentation_line_id::text)::uuid
      into v_companion_count,v_presentation_line_id
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_line_id=v_invoice_line_id and binding.state='CURRENT';
    if coalesce(v_companion_count,0)<>1 then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
    end if;
  end if;
  select * into v_selected from public.weekly_source_invoice_presentation_lines
  where id=v_presentation_line_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;
  -- The expected presentation hash is the Office's proof that it is moving the
  -- immutable line it was shown.
  if v_selected.presentation_hash is distinct from v_expected_presentation_hash then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PRESENTATION_HASH_MISMATCH'
      using errcode='40001';
  end if;
  if v_invoice_line_id is not null and not exists(
    select 1 from public.weekly_source_invoice_line_bindings binding
    where binding.presentation_line_id=v_selected.id and binding.state='CURRENT'
      and binding.invoice_line_id=v_invoice_line_id
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;
  -- A source-fixed expense follows its companion; it is never the unit of
  -- selection while it has one.  The Office moves the shift presentation and
  -- the expense goes with it.
  if v_selected.companion_presentation_line_id is not null then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_COMPANION_REQUIRED'
      using errcode='55000',detail=v_selected.companion_presentation_line_id::text;
  end if;
  select pg_catalog.array_agg(distinct member.id)
    into v_presentation_ids
  from public.weekly_source_invoice_presentation_lines member
  where member.id=v_selected.id
     or member.companion_presentation_line_id=v_selected.id;
  -- Nothing unrelated: every member is the selected line or an expense that
  -- declared it as its companion, on the same work event.
  if exists(
    select 1 from public.weekly_source_invoice_presentation_lines member
    where member.id=any(v_presentation_ids)
      and (member.work_event_id is distinct from v_selected.work_event_id
        or member.client_manifest_id is distinct from v_selected.client_manifest_id
        or (member.id<>v_selected.id and member.line_kind<>'SOURCE_FIXED_EXPENSE'))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_COMPANION_INVALID' using errcode='55000';
  end if;

  perform 1 from public.invoices invoice
  where invoice.id=any(array[v_source_invoice_id,v_destination_invoice_id])
  order by invoice.id for update;
  if (select pg_catalog.count(*) from public.invoices invoice
      where invoice.id=any(array[v_source_invoice_id,v_destination_invoice_id]))<>2 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_INVOICE_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_source from public.invoices where id=v_source_invoice_id;
  select * into strict v_destination from public.invoices where id=v_destination_invoice_id;

  -- Gate 13 finding F6.  `->>` and `#>>` yield SQL NULL for an ABSENT key, and
  -- `NULL <> 'X'` is NULL, not true, so each of these four limbs evaluated to
  -- NULL and the whole `if` was not taken.  Executed on a build from empty
  -- before the change: with `schema_version` removed from either header the
  -- move was ACCEPTED and COMMITTED (`status=MOVED`); with `{meta,source}`
  -- removed it was refused only by the neighbouring G7-4 header trigger
  -- (`WEEKLY_SOURCE_INVOICE_HEADER_INVALID`), never by this guard.
  -- `is distinct from` is null-safe, so absent, JSON null and wrong value are
  -- all unsafe, exactly as the self_bill and manifest-id limbs beside them
  -- already treat them. PHD-003 intentionally has no cross-week confirmation
  -- gate: same Client plus two idle, unissued Draft invoices is the complete
  -- business compatibility rule.
  if v_source.header_snapshot_json->>'schema_version'
       is distinct from 'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
     or v_destination.header_snapshot_json->>'schema_version'
       is distinct from 'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
     or v_source.header_snapshot_json#>>'{meta,source}'
       is distinct from 'WEEKLY_FINAL_SOURCE'
     or v_destination.header_snapshot_json#>>'{meta,source}'
       is distinct from 'WEEKLY_FINAL_SOURCE'
     or v_source.header_snapshot_json#>>'{meta,self_bill}' is distinct from 'true'
     or v_destination.header_snapshot_json#>>'{meta,self_bill}' is distinct from 'true'
     or not pg_catalog.pg_input_is_valid(
          coalesce(v_source.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid')
     or not pg_catalog.pg_input_is_valid(
          coalesce(v_destination.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid') then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_SOURCE_INVOICE_REQUIRED' using errcode='55000';
  end if;
  select * into strict v_source_manifest
  from public.weekly_source_client_manifests
  where id=(v_source.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid;
  select * into strict v_destination_manifest
  from public.weekly_source_client_manifests
  where id=(v_destination.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid;
  select * into strict v_event from public.weekly_work_events
  where id=v_selected.work_event_id;
  if v_source.client_id is distinct from v_destination.client_id
     or v_source.client_id is distinct from v_source_manifest.client_id
     or v_destination.client_id is distinct from v_destination_manifest.client_id
     or v_source.client_id is distinct from v_event.client_id
     or v_source.client_id is distinct from v_selected.client_id
     or v_source.type::text<>'INVOICE' or v_destination.type::text<>'INVOICE' then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_SCOPE_INVALID' using errcode='55000';
  end if;

  perform private.weekly_source_office_authority_v1(
    v_actor,'MOVE_SOURCE_INVOICE',v_source_manifest.source_group_id,
    v_source.client_id,v_event.work_date
  );
  if exists(select 1 from public.weekly_source_invoice_line_bindings binding join public.weekly_source_billing_movements movement on movement.id=binding.billing_movement_id
    where binding.invoice_id in (v_source_invoice_id,v_destination_invoice_id) and binding.state='CURRENT'
      and private.weekly_source_frozen_rule_values_v1(movement.final_revision_id)->>'invoice_sender'='CLIENT_SELF_BILL'
      and private.weekly_source_frozen_rule_values_v1(movement.final_revision_id)->>'invoice_vat_method'<>'SUM_OF_LINES') then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_VAT_MEMBERSHIP_LOCKED' using errcode='55000'; end if;

  -- Where do the selected presentations currently live?  The presentation
  -- identity is immutable, so this answers the replay question without needing
  -- the bindings to still be on the source invoice.
  select pg_catalog.array_agg(distinct binding.invoice_id)
    into v_binding_invoice_ids
  from public.weekly_source_invoice_line_bindings binding
  where binding.presentation_line_id=any(v_presentation_ids)
    and binding.state='CURRENT';
  if v_binding_invoice_ids is null then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;

  if v_binding_invoice_ids=array[v_destination_invoice_id]::uuid[] then
    select pg_catalog.count(*)::integer into v_replay_count
    from public.weekly_source_invoice_placements placement
    join public.weekly_source_invoice_placements prior
      on prior.id=placement.prior_placement_id
    join public.weekly_source_invoice_line_bindings binding
      on binding.billing_movement_id=placement.billing_movement_id
     and binding.state='CURRENT'
    where placement.is_current
      and binding.presentation_line_id=any(v_presentation_ids)
      and placement.invoice_id=v_destination_invoice_id
      and prior.invoice_id=v_source_invoice_id
      and placement.source_invoice_version_fingerprint=v_source_fingerprint
      and placement.destination_invoice_version_fingerprint=v_destination_fingerprint
      and placement.placement_reason='OFFICE_MOVE_BETWEEN_UNISSUED_INVOICES';
    if v_replay_count>0 then
      return pg_catalog.jsonb_build_object(
        'ok',true,'status','MOVED','idempotent',true,
        'source_invoice_id',v_source_invoice_id,
        'destination_invoice_id',v_destination_invoice_id,
        'presentation_line_id',v_selected.id,
        'presentation_line_ids',pg_catalog.to_jsonb(v_presentation_ids),
        'movement_count',v_replay_count
      );
    end if;
  end if;
  if v_binding_invoice_ids<>array[v_source_invoice_id]::uuid[] then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_ON_SOURCE_INVOICE'
      using errcode='55000';
  end if;

  if v_source.document_revision is distinct from v_expected_source_revision
     or v_destination.document_revision is distinct from v_expected_destination_revision then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_STALE_REVISION' using errcode='40001';
  end if;
  if v_source.status::text<>'DRAFT' or v_destination.status::text<>'DRAFT'
     or v_source.issued_at_utc is not null or v_destination.issued_at_utc is not null
     or v_source.paid_at_utc is not null or v_destination.paid_at_utc is not null
     or v_source.active_document_operation_id is not null
     or v_destination.active_document_operation_id is not null
     or v_source.active_issue_operation_id is not null
     or v_destination.active_issue_operation_id is not null
     or pg_catalog.upper(coalesce(v_source.issue_state,'')) in (
       'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
     )
     or pg_catalog.upper(coalesce(v_destination.issue_state,'')) in (
       'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
     )
     or exists(
       select 1 from public.invoice_operation_chunks chunk
       where chunk.entity_type='INVOICE'
         and chunk.entity_id=any(array[v_source_invoice_id,v_destination_invoice_id])
         and chunk.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
     ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_REQUIRES_IDLE_DRAFTS' using errcode='55000';
  end if;
  -- PHD-003: same Client and both invoices unissued are the only business
  -- compatibility restrictions. Source group, cycle, week, report, profile
  -- and original batch remain immutable lineage on the presentation but never
  -- prevent its deliberate Office placement on another same-Client Draft.

  perform private.weekly_source_invoice_allocation_assert_v1(v_source_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(v_destination_invoice_id);

  perform 1
  from public.weekly_source_invoice_line_bindings binding
  join public.weekly_source_billing_movements movement
    on movement.id=binding.billing_movement_id
  where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
    and binding.presentation_line_id=any(v_presentation_ids)
  order by movement.id
  for update of binding,movement;
  select pg_catalog.count(*)::integer into v_movement_count
  from public.weekly_source_invoice_line_bindings binding
  join public.weekly_source_billing_movements movement
    on movement.id=binding.billing_movement_id
  where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
    and binding.presentation_line_id=any(v_presentation_ids)
    and movement.placement_state='PLACED';
  if v_movement_count=0 then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_NOT_FOUND' using errcode='22023';
  end if;
  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.presentation_line_id=any(v_presentation_ids)
      and movement.placement_state<>'PLACED'
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PLACEMENT_INVALID' using errcode='55000';
  end if;
  select pg_catalog.array_agg(lines.invoice_line_id order by lines.invoice_line_id),
         pg_catalog.count(*)::integer
    into v_line_ids,v_line_count
  from (
    select distinct binding.invoice_line_id
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.presentation_line_id=any(v_presentation_ids)
  ) lines;
  -- An indivisible presentation moves whole: no visible line in the move set
  -- may keep a CURRENT binding that is not part of the move set, and no member
  -- of the move set may sit on a line outside it.
  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_line_id=any(v_line_ids) and binding.state='CURRENT'
      and (binding.invoice_id<>v_source_invoice_id
        or not (binding.presentation_line_id=any(v_presentation_ids)))
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PARTIAL_LINE_REFUSED' using errcode='55000';
  end if;
  perform 1 from public.weekly_source_invoice_placements placement
  where placement.billing_movement_id in (
    select binding.billing_movement_id
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.invoice_line_id=any(v_line_ids)
  ) and placement.is_current
  order by placement.billing_movement_id for update;

  perform pg_catalog.set_config(
    'cloudtms.weekly_source_invoice_owner','MOVE_SOURCE_INVOICE',true
  );
  update public.invoice_lines
  set invoice_id=v_destination_invoice_id
  where id=any(v_line_ids) and invoice_id=v_source_invoice_id;
  get diagnostics v_updated_line_count=row_count;
  if v_updated_line_count is distinct from v_line_count then
    raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_LINE_CAS_LOST' using errcode='40001';
  end if;

  for v_binding in
    select binding.*,presentation.source_shift_group_id
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    where binding.invoice_id=v_source_invoice_id and binding.state='CURRENT'
      and binding.presentation_line_id=any(v_presentation_ids)
    order by binding.billing_movement_id
  loop
    update public.weekly_source_invoice_line_bindings
    set state='SUPERSEDED',superseded_at_utc=pg_catalog.statement_timestamp()
    where id=v_binding.id and state='CURRENT';
    if not found then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_BINDING_CAS_LOST' using errcode='40001';
    end if;
    v_new_binding_version:=v_binding.binding_version+1;
    v_binding_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_BINDING_V1',pg_catalog.jsonb_build_object(
        'movement_id',v_binding.billing_movement_id,
        'presentation_line_id',v_binding.presentation_line_id,
        'invoice_line_id',v_binding.invoice_line_id,
        'invoice_id',v_destination_invoice_id,
        'manifest_hash',pg_catalog.encode(v_binding.manifest_hash,'hex'),
        'binding_version',v_new_binding_version,
        'prior_binding_id',v_binding.id
      )
    );
    insert into public.weekly_source_invoice_line_bindings(
      billing_movement_id,presentation_line_id,invoice_line_id,invoice_id,
      original_final_revision_id,original_cycle_id,client_id,correction_root_id,
      correction_role,manifest_hash,materialised_line_hash,binding_version,
      prior_binding_id,state
    ) values (
      v_binding.billing_movement_id,v_binding.presentation_line_id,
      v_binding.invoice_line_id,v_destination_invoice_id,
      v_binding.original_final_revision_id,v_binding.original_cycle_id,
      v_binding.client_id,v_binding.correction_root_id,v_binding.correction_role,
      v_binding.manifest_hash,v_binding_hash,v_new_binding_version,v_binding.id,'CURRENT'
    );

    select * into strict v_placement
    from public.weekly_source_invoice_placements placement
    where placement.billing_movement_id=v_binding.billing_movement_id
      and placement.is_current;
    if v_placement.invoice_id is distinct from v_source_invoice_id
       or v_placement.invoice_line_id is distinct from v_binding.invoice_line_id
       or v_placement.placement_state<>'PLACED' then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PLACEMENT_INVALID' using errcode='55000';
    end if;
    update public.weekly_source_invoice_placements
    set is_current=false where id=v_placement.id and is_current;
    if not found then
      raise exception 'WEEKLY_SOURCE_INVOICE_MOVE_PLACEMENT_CAS_LOST' using errcode='40001';
    end if;
    v_new_placement_revision:=v_placement.placement_revision+1;
    v_placement_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_PLACEMENT_V1',pg_catalog.jsonb_build_object(
        'movement_id',v_binding.billing_movement_id,
        'invoice_id',v_destination_invoice_id,
        'invoice_line_id',v_binding.invoice_line_id,
        'placement_revision',v_new_placement_revision,
        'placement_reason','OFFICE_MOVE_BETWEEN_UNISSUED_INVOICES',
        'prior_placement_id',v_placement.id,
        'source_invoice_version_fingerprint',pg_catalog.encode(v_source_fingerprint,'hex'),
        'destination_invoice_version_fingerprint',pg_catalog.encode(v_destination_fingerprint,'hex')
      )
    );
    insert into public.weekly_source_invoice_placements(
      billing_movement_id,source_shift_group_id,invoice_id,invoice_line_id,
      placement_revision,placement_state,is_current,original_automatic_cycle_id,
      current_target_cycle_id,placement_reason,actor_user_id,prior_placement_id,
      source_invoice_version_fingerprint,destination_invoice_version_fingerprint,
      placement_hash
    ) values (
      v_binding.billing_movement_id,v_binding.source_shift_group_id,
      v_destination_invoice_id,v_binding.invoice_line_id,
      v_new_placement_revision,'PLACED',true,v_placement.original_automatic_cycle_id,
      coalesce(v_destination_manifest.invoice_window_cycle_id,v_destination_manifest.source_cycle_id),'OFFICE_MOVE_BETWEEN_UNISSUED_INVOICES',
      v_actor,v_placement.id,v_source_fingerprint,v_destination_fingerprint,
      v_placement_hash
    );
  end loop;

  perform private.weekly_source_invoice_header_refresh_v1(v_source_invoice_id);
  perform private.weekly_source_invoice_header_refresh_v1(v_destination_invoice_id);
  perform public.invoice_recompute_totals(v_source_invoice_id);
  perform public.invoice_recompute_totals(v_destination_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(v_source_invoice_id);
  perform private.weekly_source_invoice_allocation_assert_v1(v_destination_invoice_id);
  perform pg_catalog.set_config('cloudtms.weekly_source_invoice_owner','',true);

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_source_invoice_presentation_lines',v_selected.id::text,
         'WEEKLY_SOURCE_PRESENTATION_LINE_MOVED_BETWEEN_DRAFT_INVOICES',
         pg_catalog.jsonb_build_object(
           'source_invoice_id',v_source_invoice_id,
           'source_document_revision',v_expected_source_revision,
           'presentation_line_id',v_selected.id,
           'expected_presentation_hash',
             pg_catalog.encode(v_expected_presentation_hash,'hex')
         ),
         pg_catalog.jsonb_build_object(
           'destination_invoice_id',v_destination_invoice_id,
           'destination_document_revision',v_expected_destination_revision,
           'presentation_line_ids',pg_catalog.to_jsonb(v_presentation_ids),
           'work_event_id',v_selected.work_event_id,
           'line_count',v_line_count,'movement_count',v_movement_count,
           'different_finalised_week',
             v_source_manifest.source_cycle_id is distinct from coalesce(v_destination_manifest.invoice_window_cycle_id,v_destination_manifest.source_cycle_id)
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','MOVED','idempotent',false,
    'source_invoice_id',v_source_invoice_id,
    'destination_invoice_id',v_destination_invoice_id,
    'presentation_line_id',v_selected.id,
    'presentation_line_ids',pg_catalog.to_jsonb(v_presentation_ids),
    'line_count',v_line_count,'movement_count',v_movement_count
  );
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function private.weekly_source_invoice_batch_snapshot_v1()
returns text
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  select pg_catalog.encode(
    private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_INVOICE_BATCH_SNAPSHOT_V1',
      coalesce(pg_catalog.jsonb_agg(f.fact order by f.manifest_id),'[]'::jsonb)
    ),
    'hex'
  )
  from (
    select manifest.id manifest_id,
      pg_catalog.jsonb_build_object(
        'manifest_id',manifest.id,
        'manifest_hash',pg_catalog.encode(manifest.manifest_hash,'hex'),
        'invoice_state',manifest.invoice_state,
        'movement_count',manifest.movement_count,
        'revision_state',revision.state,
        'completion_id',completion.id,
        'invoice_window_cycle_id',coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id),
        'admission_receipts',private.weekly_source_invoice_admission_receipt_map_v1(manifest.id),
        'members',coalesce((
          select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'movement_id',movement.id,
            'movement_hash',pg_catalog.encode(movement.movement_economic_hash,'hex'),
            'placement_state',movement.placement_state,
            'binding_invoice_id',binding.invoice_id
          ) order by member.manifest_ordinal)
          from public.weekly_source_manifest_movements member
          join public.weekly_source_billing_movements movement
            on movement.id=member.billing_movement_id
          left join public.weekly_source_invoice_line_bindings binding
            on binding.billing_movement_id=movement.id and binding.state='CURRENT'
          where member.client_manifest_id=manifest.id
        ),'[]'::jsonb)
      ) fact
    from public.weekly_source_client_manifests manifest
    join public.weekly_source_final_revisions revision
      on revision.id=manifest.final_revision_id
    join public.weekly_source_client_cycle_completions completion
      on completion.source_cycle_id=manifest.source_cycle_id
     and completion.client_id=manifest.client_id
     and completion.final_revision_id=manifest.final_revision_id
     and completion.completion_kind='FINAL_SOURCE'
     and completion.state='CURRENT'
    where manifest.invoice_state='READY'
      and manifest.movement_count>0
      and revision.state='CURRENT'
  ) f;
$function$;

create or replace function private.weekly_source_invoice_batch_rows_v1(
  p_filters jsonb default '{}'::jsonb,
  p_selection jsonb default pg_catalog.jsonb_build_object(
    'contract_version','INVOICE_BATCH_SELECTION_V2',
    'mode','IMPLICIT_ALL','default_selected',true,'rules','[]'::jsonb
  )
) returns table(
  manifest_id uuid,
  selection_key text,
  source_revision text,
  source_group_id uuid,
  source_cycle_id uuid,
  client_id uuid,
  client_name text,
  finalisation_week_ending date,
  backing_report_number text,
  movement_count integer,
  candidate_ids uuid[],
  candidate_names text[],
  total_ex_vat numeric,
  vat_amount numeric,
  total_inc_vat numeric,
  released_after_dispute boolean,
  selectable boolean,
  blocker_codes text[],
  selected boolean
)
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  with rules as materialized (
    select * from private._invoice_batch_selection_rules_v2(p_selection)
  ),
  raw as materialized (
    select
      manifest.id manifest_id,
      'weekly-source-manifest:'||manifest.id::text selection_key,
      pg_catalog.encode(manifest.manifest_hash,'hex') source_revision,
      manifest.source_group_id,
      manifest.source_cycle_id,
      manifest.client_id,
      coalesce(nullif(pg_catalog.btrim(client.name),''),manifest.client_id::text) client_name,
      manifest.finalisation_week_ending,
      nullif(pg_catalog.btrim(manifest.backing_report_number),'') backing_report_number,
      manifest.movement_count,
      coalesce(pg_catalog.array_agg(distinct movement.candidate_id order by movement.candidate_id)
        filter(where movement.candidate_id is not null),'{}'::uuid[]) candidate_ids,
      coalesce(pg_catalog.array_agg(distinct coalesce(
        nullif(pg_catalog.btrim(candidate.display_name),''),
        nullif(pg_catalog.btrim(pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)),''),
        candidate.tms_ref,movement.candidate_id::text
      ) order by coalesce(
        nullif(pg_catalog.btrim(candidate.display_name),''),
        nullif(pg_catalog.btrim(pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name)),''),
        candidate.tms_ref,movement.candidate_id::text
      )) filter(where movement.candidate_id is not null),'{}'::text[]) candidate_names,
      coalesce(pg_catalog.sum(movement.invoice_presentation_charge_pence),0)::numeric/100 total_ex_vat,
      (private.weekly_source_invoice_manifest_admission_money_v1(manifest.id)->>'vat_pence')::numeric/100 vat_amount,
      (private.weekly_source_invoice_manifest_admission_money_v1(manifest.id)->>'gross_pence')::numeric/100 total_inc_vat,
      coalesce(pg_catalog.bool_or(exists(
        select 1 from public.weekly_discrepancy_incidents incident
        where incident.source_group_id=manifest.source_group_id
          and incident.work_event_id=movement.work_event_id
      )),false) released_after_dispute,
      (
        manifest.movement_count>0
        and pg_catalog.count(member.billing_movement_id)=manifest.movement_count
        and pg_catalog.bool_and(member.movement_hash=movement.movement_economic_hash)
        and pg_catalog.bool_and(movement.final_revision_id=manifest.final_revision_id)
        and pg_catalog.bool_and(movement.finalisation_cycle_id=manifest.source_cycle_id)
        and pg_catalog.bool_and(movement.actual_client_id=manifest.client_id)
        and pg_catalog.bool_and(movement.placement_state='UNPLACED')
        and pg_catalog.bool_and(binding.id is null)
        and not exists(select 1 from public.weekly_source_manifest_movements held
          join public.weekly_source_billing_movements hm on hm.id=held.billing_movement_id
          where held.client_manifest_id=manifest.id and hm.source_facts_json->>'invoice_hold'='VAT_FIT'
            and not exists(select 1 from public.weekly_source_invoice_hold_releases receipt
              where receipt.upload_row_id::text=hm.source_facts_json->>'upload_row_id' and receipt.hold_kind='VAT_FIT'))
      ) integrity_ok
    from public.weekly_source_client_manifests manifest
    join public.weekly_source_final_revisions revision
      on revision.id=manifest.final_revision_id and revision.state='CURRENT'
    join public.weekly_source_client_cycle_completions completion
      on completion.source_cycle_id=manifest.source_cycle_id
     and completion.client_id=manifest.client_id
     and completion.final_revision_id=manifest.final_revision_id
     and completion.completion_kind='FINAL_SOURCE' and completion.state='CURRENT'
    join public.clients client on client.id=manifest.client_id
    left join public.weekly_source_manifest_movements member
      on member.client_manifest_id=manifest.id
    left join public.weekly_source_billing_movements movement
      on movement.id=member.billing_movement_id
    left join public.candidates candidate on candidate.id=movement.candidate_id
    left join public.weekly_source_invoice_line_bindings binding
      on binding.billing_movement_id=movement.id and binding.state='CURRENT'
    where manifest.invoice_state='READY'
      and manifest.movement_count>0
    group by manifest.id,client.name
  ),
  filtered as materialized (
    select raw.*,
      case when raw.integrity_ok then '{}'::text[]
        else array['SOURCE_MANIFEST_INVALID']::text[] end blocker_codes
    from raw
    where
      (pg_catalog.jsonb_array_length(coalesce(p_filters->'client_ids','[]'::jsonb))=0
        or raw.client_id::text in (select pg_catalog.jsonb_array_elements_text(p_filters->'client_ids')))
      and (pg_catalog.jsonb_array_length(coalesce(p_filters->'candidate_ids','[]'::jsonb))=0
        or exists(select 1 from pg_catalog.unnest(raw.candidate_ids) candidate_id
          where candidate_id::text in (select pg_catalog.jsonb_array_elements_text(p_filters->'candidate_ids'))))
      and (pg_catalog.jsonb_array_length(coalesce(p_filters->'week_endings','[]'::jsonb))=0
        or raw.finalisation_week_ending::text in (select pg_catalog.jsonb_array_elements_text(p_filters->'week_endings')))
      and (nullif(p_filters->>'week_ending_from','') is null
        or raw.finalisation_week_ending>=nullif(p_filters->>'week_ending_from','')::date)
      and (nullif(p_filters->>'week_ending_to','') is null
        or raw.finalisation_week_ending<=nullif(p_filters->>'week_ending_to','')::date)
      and (pg_catalog.jsonb_array_length(coalesce(p_filters->'status_codes','[]'::jsonb))=0
        or case when raw.integrity_ok then 'READY' else 'BLOCKED' end
          in (select pg_catalog.upper(pg_catalog.jsonb_array_elements_text(p_filters->'status_codes'))))
      and (coalesce(pg_catalog.upper(nullif(p_filters->>'display_mode','')),'ALL')='ALL'
        or coalesce(pg_catalog.upper(nullif(p_filters->>'display_mode','')),'ALL')=
          case when raw.integrity_ok then 'READY' else 'BLOCKED' end)
      and (pg_catalog.jsonb_array_length(coalesce(p_filters->'blocker_codes','[]'::jsonb))=0
        or (not raw.integrity_ok and 'SOURCE_MANIFEST_INVALID'
          in (select pg_catalog.upper(pg_catalog.jsonb_array_elements_text(p_filters->'blocker_codes')))))
      and (nullif(pg_catalog.lower(pg_catalog.btrim(p_filters->>'search')),'') is null
        or pg_catalog.lower(raw.client_name||' '||coalesce(raw.backing_report_number,'')||' '
          ||pg_catalog.array_to_string(raw.candidate_names,' ')) like
          '%'||pg_catalog.lower(pg_catalog.btrim(p_filters->>'search'))||'%')
  ),
  decided as (
    select filtered.*,
      coalesce((
        select rule.action='INCLUDE'
        from rules rule
        where case rule.selector_type
          when 'ROW' then rule.selection_key=filtered.selection_key
          when 'WEEK' then rule.week_ending_date=filtered.finalisation_week_ending
          when 'CLIENT' then rule.client_id=filtered.client_id
          when 'CANDIDATE' then rule.candidate_id=any(filtered.candidate_ids)
          when 'STATUS' then rule.status_code=case when filtered.integrity_ok then 'READY' else 'BLOCKED' end
          when 'WEEK_CLIENT' then rule.week_ending_date=filtered.finalisation_week_ending and rule.client_id=filtered.client_id
          when 'WEEK_CLIENT_CANDIDATE' then rule.week_ending_date=filtered.finalisation_week_ending
            and rule.client_id=filtered.client_id and rule.candidate_id=any(filtered.candidate_ids)
          when 'STATUS_WEEK' then rule.status_code=case when filtered.integrity_ok then 'READY' else 'BLOCKED' end
            and rule.week_ending_date=filtered.finalisation_week_ending
          when 'STATUS_WEEK_CLIENT' then rule.status_code=case when filtered.integrity_ok then 'READY' else 'BLOCKED' end
            and rule.week_ending_date=filtered.finalisation_week_ending and rule.client_id=filtered.client_id
          when 'DIMENSION_GROUP' then (rule.week_ending_date is null or rule.week_ending_date=filtered.finalisation_week_ending)
            and (rule.client_id is null or rule.client_id=filtered.client_id)
            and (rule.candidate_id is null or rule.candidate_id=any(filtered.candidate_ids))
            and (rule.status_code is null or rule.status_code=case when filtered.integrity_ok then 'READY' else 'BLOCKED' end)
          else false end
        order by rule.rule_sequence desc limit 1
      ),true) and filtered.integrity_ok is_selected
    from filtered
  )
  select decided.manifest_id,decided.selection_key,decided.source_revision,
    decided.source_group_id,decided.source_cycle_id,decided.client_id,
    decided.client_name,decided.finalisation_week_ending,
    decided.backing_report_number,decided.movement_count,
    decided.candidate_ids,decided.candidate_names,decided.total_ex_vat,
    decided.vat_amount,decided.total_inc_vat,decided.released_after_dispute,
    decided.integrity_ok,decided.blocker_codes,decided.is_selected
  from decided;
$function$;

create or replace function public.weekly_source_invoice_batch_candidates_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_allowed constant text[]:=array[
    'mode','snapshot_hash','filters','sort','selection','page_size',
    'selection_keys','expected_source_revisions'
  ];
  v_unknown text;
  v_mode text;
  v_snapshot text;
  v_current_snapshot text;
  v_filters jsonb;
  v_selection jsonb;
  v_page_size integer;
  v_rows jsonb:='[]'::jsonb;
  v_total integer:=0;
  v_eligible integer:=0;
  v_selected integer:=0;
  v_blocked integer:=0;
  v_refs jsonb:='[]'::jsonb;
  v_selection_keys jsonb;
  v_expected jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_REQUEST_INVALID' using errcode='22023';
  end if;
  select key into v_unknown from pg_catalog.jsonb_object_keys(p_request) key
  where not key=any(v_allowed) order by key limit 1;
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_UNKNOWN_FIELD' using errcode='22023',detail=v_unknown;
  end if;
  v_mode:=pg_catalog.upper(coalesce(nullif(pg_catalog.btrim(p_request->>'mode'),''),'PAGE'));
  if v_mode not in ('PAGE','SUMMARY','FACETS','EXPLICIT_KEYS','CONFIRM') then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_MODE_INVALID' using errcode='22023';
  end if;
  v_filters:=coalesce(p_request->'filters','{}'::jsonb);
  v_selection:=coalesce(p_request->'selection',pg_catalog.jsonb_build_object(
    'contract_version','INVOICE_BATCH_SELECTION_V2','mode','IMPLICIT_ALL',
    'default_selected',true,'rules','[]'::jsonb));
  if pg_catalog.jsonb_typeof(v_filters)<>'object' or pg_catalog.jsonb_typeof(v_selection)<>'object' then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_REQUEST_INVALID' using errcode='22023';
  end if;
  perform 1 from private._invoice_batch_selection_rules_v2(v_selection) limit 1;
  v_page_size:=coalesce(nullif(p_request->>'page_size','')::integer,100);
  if v_page_size not between 1 and 5000 then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_PAGE_SIZE_INVALID' using errcode='22023';
  end if;
  v_current_snapshot:=private.weekly_source_invoice_batch_snapshot_v1();
  v_snapshot:=nullif(pg_catalog.lower(pg_catalog.btrim(p_request->>'snapshot_hash')),'');
  if v_snapshot is not null and (v_snapshot!~'^[0-9a-f]{64}$' or v_snapshot<>v_current_snapshot) then
    raise exception 'BATCH_SOURCE_CHANGED' using errcode='40001';
  end if;
  if v_mode<>'PAGE' and v_snapshot is null then
    raise exception 'BATCH_SNAPSHOT_REQUIRED' using errcode='22023';
  end if;

  v_selection_keys:=coalesce(p_request->'selection_keys','[]'::jsonb);
  v_expected:=coalesce(p_request->'expected_source_revisions','{}'::jsonb);
  if v_mode in ('EXPLICIT_KEYS','CONFIRM') and (
    pg_catalog.jsonb_typeof(v_selection_keys)<>'array'
    or pg_catalog.jsonb_typeof(v_expected)<>'object'
  ) then raise exception 'BATCH_EXPLICIT_KEYS_INVALID' using errcode='22023'; end if;
  if v_mode='EXPLICIT_KEYS' and pg_catalog.jsonb_array_length(v_selection_keys)<>1 then
    raise exception 'BATCH_EXPLICIT_KEYS_INVALID' using errcode='22023';
  end if;

  with candidate as materialized (
    select * from private.weekly_source_invoice_batch_rows_v1(v_filters,v_selection)
  ), scoped as materialized (
    select candidate.* from candidate
    where v_mode not in ('EXPLICIT_KEYS','CONFIRM')
      or (v_mode='CONFIRM' and pg_catalog.jsonb_array_length(v_selection_keys)=0)
      or candidate.selection_key in (select pg_catalog.jsonb_array_elements_text(v_selection_keys))
  )
  select pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter(where selectable)::integer,
    pg_catalog.count(*) filter(where selected)::integer,
    pg_catalog.count(*) filter(where not selectable)::integer
  into v_total,v_eligible,v_selected,v_blocked from scoped;

  if (v_mode='PAGE' and v_total>v_page_size)
     or (v_mode='CONFIRM' and v_selected>5000) then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_SCOPE_TOO_LARGE'
      using errcode='54000';
  end if;

  if v_mode='EXPLICIT_KEYS'
     or (v_mode='CONFIRM' and pg_catalog.jsonb_array_length(v_selection_keys)>0) then
    if (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements_text(v_selection_keys))<>v_total
       or exists(
         select 1 from private.weekly_source_invoice_batch_rows_v1(v_filters,v_selection) row_value
         where row_value.selection_key in (select pg_catalog.jsonb_array_elements_text(v_selection_keys))
           and coalesce(v_expected->>row_value.selection_key,'')<>row_value.source_revision
       ) then
      raise exception 'BATCH_SOURCE_CHANGED' using errcode='40001';
    end if;
  end if;

  if v_mode in ('PAGE','EXPLICIT_KEYS') then
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'selection_key',row_value.selection_key,
      'source_revision',row_value.source_revision,
      'source_kind','WEEKLY_FINAL_SOURCE',
      'invoice_stream','WEEKLY_FINAL_SOURCE',
      'selectable',row_value.selectable,
      'row_status',case when row_value.selectable then 'READY' else 'BLOCKED' end,
      'generation_state','NOT_GENERATED',
      'week_ending_date',row_value.finalisation_week_ending,
      'client_id',row_value.client_id,'client_name',row_value.client_name,
      'candidate_ids',pg_catalog.to_jsonb(row_value.candidate_ids),
      'candidate_names',pg_catalog.to_jsonb(row_value.candidate_names),
      'candidate_name',case pg_catalog.cardinality(row_value.candidate_ids)
        when 1 then row_value.candidate_names[1]
        else pg_catalog.cardinality(row_value.candidate_ids)::text||' workers' end,
      'report_number',row_value.backing_report_number,
      'movement_count',row_value.movement_count,
      'total_ex_vat',row_value.total_ex_vat,'vat_amount',row_value.vat_amount,
      'total_inc_vat',row_value.total_inc_vat,'currency','GBP',
      'action_blocker_codes',pg_catalog.to_jsonb(row_value.blocker_codes),
      'informational_codes',case when row_value.released_after_dispute
        then '["RELEASED_AFTER_DISPUTE"]'::jsonb else '[]'::jsonb end,
      'released_after_dispute',row_value.released_after_dispute,
      'client_manifest_id',row_value.manifest_id,
      'source_cycle_id',row_value.source_cycle_id,
      'command_payload',pg_catalog.jsonb_build_object(
        'command_type','ADMIT_WEEKLY_SOURCE_MANIFEST',
        'client_manifest_id',row_value.manifest_id,
        'expected_manifest_hash',row_value.source_revision
      )
    ) order by row_value.finalisation_week_ending desc,row_value.client_name,row_value.manifest_id),'[]'::jsonb)
    into v_rows
    from (
      select * from private.weekly_source_invoice_batch_rows_v1(v_filters,v_selection)
      where (v_mode<>'EXPLICIT_KEYS' or selection_key in (
        select pg_catalog.jsonb_array_elements_text(v_selection_keys)))
      order by finalisation_week_ending desc,client_name,manifest_id limit v_page_size
    ) row_value;
  end if;

  if v_mode='CONFIRM' then
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'client_manifest_id',row_value.manifest_id,
      'expected_manifest_hash',row_value.source_revision,
      'selection_key',row_value.selection_key,
      'client_id',row_value.client_id,
      'source_cycle_id',row_value.source_cycle_id,
      'finalisation_week_ending',row_value.finalisation_week_ending,
      'report_number',row_value.backing_report_number
    ) order by row_value.finalisation_week_ending,row_value.client_id,row_value.manifest_id),'[]'::jsonb)
    into v_refs
    from private.weekly_source_invoice_batch_rows_v1(v_filters,v_selection) row_value
    where row_value.selected
      and (pg_catalog.jsonb_array_length(v_selection_keys)=0
        or row_value.selection_key in (
          select pg_catalog.jsonb_array_elements_text(v_selection_keys)));
  end if;

  return pg_catalog.jsonb_build_object(
    'contract_version','WEEKLY_SOURCE_INVOICE_BATCH_CANDIDATES_V1',
    'mode',v_mode,'snapshot_hash',v_current_snapshot,'rows',v_rows,
    'page',pg_catalog.jsonb_build_object('total_count',v_total,'returned_count',pg_catalog.jsonb_array_length(v_rows)),
    'selection_summary',pg_catalog.jsonb_build_object(
      'exact',true,'eligible_total',v_eligible,'selected_total',v_selected,'blocked_total',v_blocked),
    'selected_manifest_refs',v_refs
  );
end;
$function$;

create or replace function public.weekly_source_invoice_batch_admit_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_snapshot text;
  v_current_snapshot text;
  v_token text;
  v_refs jsonb;
  v_ref jsonb;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_all_admitted boolean;
  v_result jsonb;
  v_results jsonb:='[]'::jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in ('actor_user_id','command_token','snapshot_hash','selected_manifests')) then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_ADMIT_REQUEST_INVALID' using errcode='22023';
  end if;
  begin v_actor:=(p_request->>'actor_user_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_ADMIT_REQUEST_INVALID' using errcode='22023';
  end;
  v_token:=nullif(pg_catalog.btrim(p_request->>'command_token'),'');
  v_snapshot:=nullif(pg_catalog.lower(pg_catalog.btrim(p_request->>'snapshot_hash')),'');
  v_refs:=coalesce(p_request->'selected_manifests','[]'::jsonb);
  if v_actor is null or v_token is null or pg_catalog.length(v_token)>256
     or v_snapshot!~'^[0-9a-f]{64}$'
     or pg_catalog.jsonb_typeof(v_refs)<>'array'
     or pg_catalog.jsonb_array_length(v_refs) not between 1 and 5000
     or exists(select 1 from pg_catalog.jsonb_array_elements(v_refs) item
       where pg_catalog.jsonb_typeof(item)<>'object'
         or exists(select 1 from pg_catalog.jsonb_object_keys(item) key
           where key not in ('client_manifest_id','expected_manifest_hash','selection_key',
             'client_id','source_cycle_id','finalisation_week_ending','report_number'))
         or not pg_catalog.pg_input_is_valid(coalesce(item->>'client_manifest_id',''),'uuid')
         or coalesce(item->>'selection_key','')<>
           'weekly-source-manifest:'||coalesce(item->>'client_manifest_id','')
         or coalesce(item->>'expected_manifest_hash','')!~'^[0-9a-f]{64}$')
     or (select pg_catalog.count(distinct item->>'client_manifest_id')
         from pg_catalog.jsonb_array_elements(v_refs) item)<>pg_catalog.jsonb_array_length(v_refs) then
    raise exception 'WEEKLY_SOURCE_INVOICE_BATCH_ADMIT_REQUEST_INVALID' using errcode='22023';
  end if;

  -- Whole batch group/cycle inventory precedes every nested manifest lock.
  perform 1 from public.weekly_source_groups g where g.id in (
    select manifest.source_group_id from public.weekly_source_client_manifests manifest
    join jsonb_array_elements(v_refs) item on manifest.id=(item->>'client_manifest_id')::uuid)
    order by g.id for update;
  perform 1 from public.weekly_source_cycles c where c.id in (
    select manifest.source_cycle_id from public.weekly_source_client_manifests manifest
    join jsonb_array_elements(v_refs) item on manifest.id=(item->>'client_manifest_id')::uuid
    union select coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)
      from public.weekly_source_client_manifests manifest
      join jsonb_array_elements(v_refs) item on manifest.id=(item->>'client_manifest_id')::uuid)
    order by c.id for update;
  select pg_catalog.bool_and(manifest.invoice_state='ADMITTED'
    and pg_catalog.encode(manifest.manifest_hash,'hex')=item->>'expected_manifest_hash')
  into v_all_admitted
  from pg_catalog.jsonb_array_elements(v_refs) item
  join public.weekly_source_client_manifests manifest
    on manifest.id=(item->>'client_manifest_id')::uuid;
  v_all_admitted:=coalesce(v_all_admitted,false);
  v_current_snapshot:=private.weekly_source_invoice_batch_snapshot_v1();
  if not v_all_admitted and v_current_snapshot<>v_snapshot then
    raise exception 'BATCH_SOURCE_CHANGED' using errcode='40001';
  end if;

  for v_ref in select item from pg_catalog.jsonb_array_elements(v_refs) item
    order by item->>'finalisation_week_ending',item->>'client_id',item->>'client_manifest_id'
  loop
    select * into v_manifest from public.weekly_source_client_manifests
    where id=(v_ref->>'client_manifest_id')::uuid for update;
    if not found or pg_catalog.encode(v_manifest.manifest_hash,'hex')<>v_ref->>'expected_manifest_hash'
       or v_manifest.invoice_state not in ('READY','ADMITTED') then
      raise exception 'BATCH_SOURCE_CHANGED' using errcode='40001';
    end if;
    v_result:=public.weekly_source_invoice_admit_atomic_v1(pg_catalog.jsonb_build_object(
      'actor_user_id',v_actor,'client_manifest_id',v_manifest.id,
      'expected_manifest_hash',v_ref->>'expected_manifest_hash'
    ));
    v_results:=v_results||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'selection_key',v_ref->>'selection_key',
        'client_manifest_id',v_manifest.id,
        'client_id',v_manifest.client_id,
        'source_cycle_id',v_manifest.source_cycle_id,'invoice_window_cycle_id',coalesce(v_manifest.invoice_window_cycle_id,v_manifest.source_cycle_id),
        'finalisation_week_ending',v_manifest.finalisation_week_ending,
        'report_number',v_manifest.backing_report_number,
        'status',v_result->>'status','idempotent',coalesce((v_result->>'idempotent')::boolean,false),
        'invoice_ids',coalesce(v_result->'invoice_ids','[]'::jsonb)
      )
    );
  end loop;

  if exists(
    select 1
    from pg_catalog.jsonb_array_elements(v_results) left_result
    join pg_catalog.jsonb_array_elements(v_results) right_result
      on left_result->>'client_manifest_id'<right_result->>'client_manifest_id'
     and left_result->>'client_id'=right_result->>'client_id'
     and left_result->>'invoice_window_cycle_id'<>right_result->>'invoice_window_cycle_id'
    where exists(
      select 1 from pg_catalog.jsonb_array_elements_text(left_result->'invoice_ids') left_invoice
      join pg_catalog.jsonb_array_elements_text(right_result->'invoice_ids') right_invoice
        on left_invoice=right_invoice
    )
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_CYCLE_CONSOLIDATION_REFUSED' using errcode='55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','WEEKLY_SOURCE_INVOICE_BATCH_ADMISSION_V1',
    'command_token',v_token,'atomic',true,
    'selected_count',pg_catalog.jsonb_array_length(v_results),
    'per_manifest_results',v_results
  );
end;
$function$;

create or replace function public.weekly_source_invoice_edit_context_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_invoice_id uuid;
  v_invoice public.invoices%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_result jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
       where key not in ('actor_user_id','invoice_id')) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_CONTEXT_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_invoice_id:=(p_request->>'invoice_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_CONTEXT_INVALID' using errcode='22023';
  end;
  select * into v_invoice from public.invoices where id=v_invoice_id;
  if not found or v_invoice.header_snapshot_json->>'schema_version'<>'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1' then
    return pg_catalog.jsonb_build_object('is_weekly_source_invoice',false);
  end if;
  if not pg_catalog.pg_input_is_valid(
    coalesce(v_invoice.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid'
  ) then
    raise exception 'WEEKLY_SOURCE_INVOICE_EDIT_CONTEXT_INVALID' using errcode='22023';
  end if;
  select * into strict v_manifest from public.weekly_source_client_manifests
  where id=(v_invoice.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid;
  perform private.weekly_source_office_authority_v1(
    v_actor,'VIEW_SOURCE_PROGRESS',v_manifest.source_group_id,
    v_manifest.client_id,v_manifest.finalisation_week_ending
  );

  select pg_catalog.jsonb_build_object(
    'is_weekly_source_invoice',true,
    'invoice_id',v_invoice.id,'invoice_number',v_invoice.invoice_no,
    'document_revision',v_invoice.document_revision,
    'source_cycle_id',v_manifest.source_cycle_id,
    'invoice_window_cycle_id',coalesce(v_manifest.invoice_window_cycle_id,v_manifest.source_cycle_id),
    'finalisation_week_ending',v_manifest.finalisation_week_ending,
    'report_number',v_manifest.backing_report_number,
    'report_numbers',coalesce(
      v_invoice.header_snapshot_json#>'{meta,backing_report_numbers}',
      case when v_manifest.backing_report_number is null then '[]'::jsonb
        else pg_catalog.jsonb_build_array(v_manifest.backing_report_number) end
    ),
    'editable',v_invoice.status='DRAFT'
      and v_invoice.issued_at_utc is null and v_invoice.paid_at_utc is null
      and v_invoice.active_document_operation_id is null
      and v_invoice.active_issue_operation_id is null
      and pg_catalog.upper(coalesce(v_invoice.issue_state,'')) not in (
        'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
      ),
    -- Gate 7 item G7-2 (24 section 12; 25 section 8 Removed).
    -- The unit of movement offered to the Office is ONE immutable source
    -- presentation line, never a work event: "Moving by whole work-event ID is
    -- prohibited because it can move more than the Office selected."  Each row
    -- carries the presentation-line id and the expected presentation hash the
    -- move owner demands, plus the facts the Office needs to understand what
    -- will travel with it: an NHSP physical row is independently movable, a
    -- non-NHSP net presentation is indivisible, and a source-fixed expense
    -- follows its declared companion rather than being selected on its own.
    'movable_lines',coalesce((
      select pg_catalog.jsonb_agg(movable.row_json order by movable.work_date,
        movable.start_at_local,movable.candidate_display,movable.presentation_line_id)
      from (
        select presentation.id presentation_line_id,presentation.work_date,
          presentation.start_at_local,
          presentation.candidate_display_snapshot candidate_display,
          pg_catalog.jsonb_build_object(
            'presentation_line_id',presentation.id,
            'presentation_hash',pg_catalog.encode(presentation.presentation_hash,'hex'),
            'invoice_line_id',pg_catalog.min(binding.invoice_line_id::text)::uuid,
            'line_kind',presentation.line_kind,
            'origin_kind',presentation.origin_kind,
            'correction_role',presentation.correction_role,
            'work_event_id',presentation.work_event_id,
            'candidate',presentation.candidate_display_snapshot,
            'work_date',presentation.work_date,
            'start_at_local',presentation.start_at_local,
            'end_at_local',presentation.end_at_local,
            'break_minutes',presentation.break_minutes,
            -- Display-only source facts. Never use reference, ward or band as
            -- a movement identity or as an invoice amount authority.
            'source_reference',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'reference_number')
              else presentation.booking_reference_snapshot end,
            'source_ward',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'ward') else null end,
            'source_trust',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'trust') else null end,
            'source_hospital',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.bounded_raw_columns_json->>'hospital') else null end,
            'source_band',case when pg_catalog.count(distinct source_row.id)=1
              then pg_catalog.min(source_row.role_band_source) else null end,
            'timesheet_id',case when pg_catalog.count(distinct movement.invoice_timesheet_id)=1
              then pg_catalog.min(movement.invoice_timesheet_id::text)::uuid else null end,
            'description',presentation.description_snapshot,
            'bound_movement_count',pg_catalog.count(*)::integer,
            -- A presentation that binds more than one movement is the narrowly
            -- supported non-NHSP net presentation: it moves as one.
            'indivisible_presentation',pg_catalog.count(*)>1,
            'independently_movable',
              presentation.companion_presentation_line_id is null,
            'follows_companion_presentation_line_id',
              presentation.companion_presentation_line_id,
            'companion_presentation_line_ids',coalesce((
              select pg_catalog.jsonb_agg(companion.id order by companion.id)
              from public.weekly_source_invoice_presentation_lines companion
              where companion.companion_presentation_line_id=presentation.id
            ),'[]'::jsonb),
            'released_after_dispute',exists(
              select 1 from public.weekly_discrepancy_incidents incident
              where incident.source_group_id=v_manifest.source_group_id
                and incident.work_event_id=presentation.work_event_id
            )
          ) row_json
        from public.weekly_source_invoice_line_bindings binding
        join public.weekly_source_invoice_presentation_lines presentation
          on presentation.id=binding.presentation_line_id
        join public.weekly_source_billing_movements movement
          on movement.id=binding.billing_movement_id
        left join public.weekly_source_upload_rows source_row
          on source_row.id=movement.nhsp_upload_row_id
        where binding.invoice_id=v_invoice.id and binding.state='CURRENT'
        group by presentation.id,presentation.presentation_hash,presentation.line_kind,
          presentation.origin_kind,presentation.correction_role,presentation.work_event_id,
          presentation.candidate_display_snapshot,presentation.work_date,
          presentation.start_at_local,presentation.end_at_local,
          presentation.break_minutes,presentation.description_snapshot,
          presentation.companion_presentation_line_id
      ) movable
    ),'[]'::jsonb),
    'compatible_destinations',coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'invoice_id',destination.id,'invoice_number',destination.invoice_no,
        'document_revision',destination.document_revision,
        'finalisation_week_ending',destination_manifest.finalisation_week_ending,
        'report_numbers',coalesce(destination.header_snapshot_json#>'{meta,backing_report_numbers}','[]'::jsonb),
        'total_inc_vat',destination.total_inc_vat
      ) order by destination_manifest.finalisation_week_ending desc,destination.invoice_no,destination.id)
      from public.invoices destination
      join public.weekly_source_client_manifests destination_manifest
        on destination_manifest.id=case
          when pg_catalog.pg_input_is_valid(
            coalesce(destination.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid'
          ) then (destination.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid
          else null
        end
      where destination.id<>v_invoice.id
        and destination.header_snapshot_json->>'schema_version'='WEEKLY_SOURCE_SELF_BILL_INVOICE_V1'
        and destination.client_id=v_invoice.client_id
        and destination.status='DRAFT'
        and destination.issued_at_utc is null and destination.paid_at_utc is null
        and destination.active_document_operation_id is null
        and destination.active_issue_operation_id is null
        and pg_catalog.upper(coalesce(destination.issue_state,'')) not in (
          'VALIDATING','PREPARING_DOCUMENT','READY_TO_FINALISE'
        )
    ),'[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function public.weekly_source_ordinary_pay_projection_apply_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_keys text[]:=array[
    'actor_user_id','final_revision_id','idempotency_key','root_timesheet_id',
    'schema_version','service_snapshot'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_final_revision_id uuid;
  v_root_timesheet_id uuid;
  v_idempotency_key text;
  v_service_snapshot jsonb;
  v_request_hash bytea;
  v_service_snapshot_hash bytea;
  v_source_unit_manifest_hash bytea;
  v_source_expense_manifest_hash bytea;
  v_active_segment_manifest_hash bytea;
  v_server_calculation_fingerprint bytea;
  v_root_before_hash bytea;
  v_root_after_hash bytea;
  v_revision public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_contract_week public.contract_weeks%rowtype;
  v_current_financial public.timesheets_financials%rowtype;
  v_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  v_correction_impact public.weekly_final_source_correction_root_impacts%rowtype;
  v_source_units jsonb;
  v_expected_source_expenses jsonb;
  v_expected_segments jsonb;
  v_expected_actual_schedule jsonb;
  v_expected_rate_source_refs jsonb;
  v_canonical_tsfin jsonb;
  v_source_mode text;
  v_source_profile_kind text;
  v_client_id uuid;
  v_client_count integer;
  v_profile_count integer;
  v_raw_unit_count integer;
  v_scope_movement_count integer;
  v_active_movement_count integer;
  v_ambiguous_event_count integer;
  v_first_negative_only boolean;
  v_target_state text;
  v_target_family public.weekly_exceptional_pay_target_families%rowtype;
  v_live_generation_count integer;
  v_outcome text;
  v_components jsonb;
  v_decision_bundle_id uuid;
  v_decision_id uuid;
  v_head_id uuid;
  v_proposal_request jsonb;
  v_proposal jsonb;
  v_preflight jsonb;
  v_required_path text;
  v_lifecycle_result jsonb;
  v_write_result jsonb;
  v_published_financial_id uuid;
  v_unit record;
  v_expense_unit record;
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_PROJECTION_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_keys
  from pg_catalog.unnest(v_keys) key;
  if v_actual_keys is distinct from v_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_ORDINARY_PAY_PROJECTION_REQUEST_V1'
     or pg_catalog.jsonb_typeof(p_request->'service_snapshot')<>'object' then
    raise exception 'WEEKLY_SOURCE_PROJECTION_REQUEST_CONTRACT_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_final_revision_id:=(p_request->>'final_revision_id')::uuid;
    v_root_timesheet_id:=(p_request->>'root_timesheet_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_PROJECTION_ID_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_service_snapshot:=p_request->'service_snapshot';
  if v_actor is null or v_final_revision_id is null or v_root_timesheet_id is null
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200 then
    raise exception 'WEEKLY_SOURCE_PROJECTION_REQUIRED_INPUT_MISSING' using errcode='22023';
  end if;
  perform 1 from public.tms_users actor
  where actor.id=v_actor and coalesce(actor.is_active,false);
  if not found then
    raise exception 'WEEKLY_SOURCE_PROJECTION_ACTOR_INVALID' using errcode='42501';
  end if;

  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_PAY_PROJECTION_REQUEST_V1',
    p_request-'idempotency_key'
  );
  select * into v_receipt
  from public.weekly_source_ordinary_pay_projection_receipts receipt
  where receipt.idempotency_key=v_idempotency_key
     or receipt.request_hash=v_request_hash
  order by case when receipt.idempotency_key=v_idempotency_key then 0 else 1 end,
           receipt.created_at_utc,receipt.id
  limit 1;
  if found then
    if v_receipt.request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_PROJECTION_IDEMPOTENCY_COLLISION' using errcode='22023';
    end if;
    return private.weekly_source_ordinary_projection_receipt_json_v1(v_receipt)
      ||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_ORDINARY_PROJECTION|'||v_final_revision_id::text||'|'||
    v_root_timesheet_id::text,0
  ));
  select * into v_receipt
  from public.weekly_source_ordinary_pay_projection_receipts receipt
  where receipt.idempotency_key=v_idempotency_key
     or receipt.request_hash=v_request_hash
  limit 1;
  if found then
    if v_receipt.request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_PROJECTION_IDEMPOTENCY_COLLISION' using errcode='22023';
    end if;
    return private.weekly_source_ordinary_projection_receipt_json_v1(v_receipt)
      ||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;

  select * into v_revision from public.weekly_source_final_revisions
  where id=v_final_revision_id for share;
  if not found or v_revision.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_FINAL_REVISION_NOT_CURRENT' using errcode='55000';
  end if;
  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_revision.source_cycle_id for share;
  select * into strict v_upload from public.weekly_source_uploads
  where id=v_revision.upload_id;
  select * into strict v_profile from public.weekly_source_format_profiles
  where id=v_upload.source_format_profile_id;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_revision.authority_scope_kind='CYCLE' then
    if v_cycle.current_final_revision_id is distinct from v_revision.id
       or v_upload.report_scope_id is not null then
      raise exception 'WEEKLY_SOURCE_FINAL_REVISION_POINTER_STALE' using errcode='40001';
    end if;
  else
    select * into v_scope from public.weekly_source_report_scopes
    where id=v_revision.report_scope_id for share;
    if not found or v_scope.current_final_revision_id is distinct from v_revision.id
       or v_scope.source_cycle_id is distinct from v_cycle.id
       or v_upload.report_scope_id is distinct from v_scope.id then
      raise exception 'WEEKLY_SOURCE_FINAL_REVISION_POINTER_STALE' using errcode='40001';
    end if;
  end if;
  v_source_profile_kind:=v_profile.final_authority_kind;
  v_source_mode:=case when v_source_profile_kind='NHSP_TRUST_BACKING_REPORT'
    then 'NHSP_WEEKLY' else 'HEALTHROSTER_WEEKLY' end;
  if v_source_profile_kind not in (
       'GENERIC_COMPLETE_SNAPSHOT','NHSP_TRUST_BACKING_REPORT','HEALTHROSTER_ACTUAL_ROWS'
     ) or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_SOURCE_FINAL_PROFILE_INVALID' using errcode='55000';
  end if;

  select pg_catalog.count(distinct movement.actual_client_id),
         pg_catalog.count(distinct movement.source_profile_kind),
         pg_catalog.count(*) filter (
           where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.expense_authority_generation_id is null
             and movement.source_line_kind<>'SOURCE_FIXED_EXPENSE'
         ),
         pg_catalog.count(*),
         (pg_catalog.array_agg(movement.actual_client_id order by movement.id))[1]
  into v_client_count,v_profile_count,v_raw_unit_count,v_scope_movement_count,v_client_id
  from public.weekly_source_billing_movements movement
  where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
    and movement.invoice_timesheet_id=v_root_timesheet_id;
  if v_scope_movement_count=0 then
    select * into v_correction_impact
    from public.weekly_final_source_correction_root_impacts impact
    where impact.replacement_final_revision_id=v_revision.id
      and impact.root_timesheet_id=v_root_timesheet_id;
    if not found or v_revision.reason<>'CORRECT_FINAL_SOURCE'
       or v_correction_impact.source_profile_kind is distinct from v_source_profile_kind
       or v_correction_impact.source_mode is distinct from v_source_mode then
      raise exception 'WEEKLY_SOURCE_PROJECTION_UNIT_SCOPE_INVALID' using errcode='55000';
    end if;
    v_client_id:=v_correction_impact.client_id;
  elsif v_client_count<>1 or v_profile_count<>1
     or exists(
       select 1 from public.weekly_source_billing_movements movement
       where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
         and movement.invoice_timesheet_id=v_root_timesheet_id
         and movement.source_profile_kind is distinct from v_source_profile_kind
     ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_UNIT_SCOPE_INVALID' using errcode='55000';
  end if;
  select * into v_manifest from public.weekly_source_client_manifests manifest where coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)=manifest.source_cycle_id and manifest.final_revision_id=v_revision.id and manifest.client_id=v_client_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CLIENT_MANIFEST_MISSING' using errcode='55000';
  end if;
  if v_scope_movement_count=0 and (
       v_manifest.client_id is distinct from v_correction_impact.client_id
       or v_correction_impact.prior_final_revision_id
            is distinct from v_revision.predecessor_revision_id
       or not exists(
         select 1
         from public.weekly_source_ordinary_pay_projection_receipts prior_receipt
         where prior_receipt.id=v_correction_impact.prior_projection_receipt_id
           and prior_receipt.final_revision_id=v_correction_impact.prior_final_revision_id
           and prior_receipt.root_timesheet_id=v_root_timesheet_id
           and prior_receipt.client_id=v_client_id
           and prior_receipt.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED')
       )
     ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_IMPACT_INVALID' using errcode='55000';
  end if;
  if exists(
    select 1
    from public.weekly_source_billing_movements predecessor_movement
    join public.weekly_source_final_revisions predecessor_revision
      on predecessor_revision.id=predecessor_movement.final_revision_id
     and predecessor_revision.state='CURRENT'
    join public.weekly_source_cycles predecessor_cycle
      on predecessor_cycle.id=predecessor_movement.finalisation_cycle_id
    where predecessor_movement.source_profile_kind<>'SELF_BILL_REPORT' and predecessor_movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and predecessor_movement.invoice_timesheet_id=v_root_timesheet_id
      and (
        predecessor_cycle.finalisation_week_ending<v_cycle.finalisation_week_ending
        or (
          predecessor_cycle.finalisation_week_ending=v_cycle.finalisation_week_ending
          and predecessor_revision.finalised_at_utc<v_revision.finalised_at_utc
        )
        or (
          predecessor_cycle.finalisation_week_ending=v_cycle.finalisation_week_ending
          and predecessor_revision.finalised_at_utc=v_revision.finalised_at_utc
          and predecessor_revision.revision_number<v_revision.revision_number
        )
        or (
          predecessor_cycle.finalisation_week_ending=v_cycle.finalisation_week_ending
          and predecessor_revision.finalised_at_utc=v_revision.finalised_at_utc
          and predecessor_revision.revision_number=v_revision.revision_number
          and predecessor_revision.id::text<v_revision.id::text
        )
      )
      and not exists(
        select 1
        from public.weekly_source_ordinary_pay_projection_receipts predecessor_receipt
        where predecessor_receipt.final_revision_id=predecessor_revision.id
          and predecessor_receipt.root_timesheet_id=v_root_timesheet_id
          and predecessor_receipt.outcome in (
            'PREPARED_FOR_AUTHORISATION','PROPOSED','NO_OP_FIRST_NEGATIVE',
            'TARGET_MANAGED_SUPPRESSED'
          )
      )
  ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_PREDECESSOR_REQUIRED'
      using errcode='55000';
  end if;
  if exists(
    select 1
    from public.weekly_source_ordinary_pay_projection_receipts later_receipt
    join public.weekly_source_final_revisions later_revision
      on later_revision.id=later_receipt.final_revision_id
    join public.weekly_source_cycles later_cycle
      on later_cycle.id=later_receipt.source_cycle_id
    where later_receipt.root_timesheet_id=v_root_timesheet_id
      and later_receipt.outcome in (
        'PREPARED_FOR_AUTHORISATION','PROPOSED','NO_OP_FIRST_NEGATIVE',
        'TARGET_MANAGED_SUPPRESSED'
      )
      and (
        later_cycle.finalisation_week_ending>v_cycle.finalisation_week_ending
        or (
          later_cycle.finalisation_week_ending=v_cycle.finalisation_week_ending
          and later_revision.finalised_at_utc>v_revision.finalised_at_utc
        )
        or (
          later_cycle.finalisation_week_ending=v_cycle.finalisation_week_ending
          and later_revision.finalised_at_utc=v_revision.finalised_at_utc
          and later_revision.revision_number>v_revision.revision_number
        )
        or (
          later_cycle.finalisation_week_ending=v_cycle.finalisation_week_ending
          and later_revision.finalised_at_utc=v_revision.finalised_at_utc
          and later_revision.revision_number=v_revision.revision_number
          and later_revision.id::text>v_revision.id::text
        )
      )
  ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_LEDGER_ORDER_INVALID'
      using errcode='55000';
  end if;
  v_source_units:=private.weekly_source_ordinary_projection_source_units_v1(
    v_revision.id,v_root_timesheet_id
  );
  if pg_catalog.jsonb_array_length(v_source_units)<>v_raw_unit_count then
    raise exception 'WEEKLY_SOURCE_PROJECTION_MANIFEST_INCOMPLETE' using errcode='55000';
  end if;

  select * into v_timesheet from public.timesheets
  where timesheet_id=v_root_timesheet_id for update;
  if not found or not v_timesheet.is_current
     or v_timesheet.contract_id is null
     or v_timesheet.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum
     or v_timesheet.line_type<>'HOURS'::public.timesheet_line_type_enum
     or v_timesheet.is_adjustment or v_timesheet.revoked_at is not null
     or v_timesheet.archived_at_utc is not null then
    raise exception 'WEEKLY_SOURCE_ROOT_TIMESHEET_INVALID' using errcode='55000';
  end if;
  select * into v_contract_week from public.contract_weeks
  where timesheet_id=v_root_timesheet_id
  order by additional_seq,updated_at desc,id desc limit 1 for update;
  if not found or v_contract_week.additional_seq<>0 or v_contract_week.is_adjustment
     or v_contract_week.contract_id is distinct from v_timesheet.contract_id
     or v_contract_week.week_ending_date is distinct from v_timesheet.week_ending_date
     or v_contract_week.status='CANCELLED'::public.contract_week_status_enum then
    raise exception 'WEEKLY_SOURCE_ROOT_CONTRACT_WEEK_INVALID' using errcode='55000';
  end if;
  if exists(
    select 1 from public.weekly_source_billing_movements movement
    where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
      and movement.invoice_timesheet_id=v_root_timesheet_id
      and (
        movement.actual_client_id is distinct from v_client_id
        or movement.contract_id is distinct from v_timesheet.contract_id
      )
  ) then
    raise exception 'WEEKLY_SOURCE_PROJECTION_ROOT_LINEAGE_MISMATCH' using errcode='55000';
  end if;

  for v_unit in
    select movement.*
    from public.weekly_source_billing_movements movement
    where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
      and movement.invoice_timesheet_id=v_root_timesheet_id
      and movement.expense_authority_generation_id is null
      and movement.source_line_kind<>'SOURCE_FIXED_EXPENSE'
    order by movement.created_at_utc,movement.id
  loop
    if v_unit.source_profile_kind is distinct from v_source_profile_kind
       or v_unit.finalisation_cycle_id is distinct from v_cycle.id
       or pg_catalog.jsonb_typeof(v_unit.canonical_pay_vector_json)<>'object'
       or pg_catalog.jsonb_typeof(v_unit.canonical_charge_vector_json)<>'object'
       or v_unit.canonical_pay_vector_json->>'source_mode' is distinct from v_source_mode
       or v_unit.canonical_charge_vector_json->>'source_mode' is distinct from v_source_mode
       or v_unit.canonical_pay_vector_json->>'kind'<>'PAY'
       or v_unit.canonical_charge_vector_json->>'kind'<>'CHARGE'
       or v_unit.canonical_pay_vector_json->>'calculation_fingerprint'
            is distinct from v_unit.canonical_charge_vector_json->>'calculation_fingerprint'
       or not exists(
         select 1 from public.weekly_source_manifest_movements manifest_movement
         where manifest_movement.client_manifest_id=v_manifest.id
           and manifest_movement.billing_movement_id=v_unit.id
           and manifest_movement.movement_hash=v_unit.movement_economic_hash
       ) then
      raise exception 'WEEKLY_SOURCE_PROJECTION_UNIT_INTEGRITY_FAILED' using errcode='55000';
    end if;
    if v_unit.source_line_kind='GENERATED_HISTORICAL_REVERSAL' then
      if v_unit.prior_movement_id is null or not exists(
        select 1 from public.weekly_source_billing_movements prior
        where prior.id=v_unit.prior_movement_id
          and prior.invoice_timesheet_id=v_root_timesheet_id
          and private.weekly_source_finalisation_negate_vector_v1(
                prior.canonical_pay_vector_json
              )=v_unit.canonical_pay_vector_json
          and private.weekly_source_finalisation_negate_vector_v1(
                prior.canonical_charge_vector_json
              )=v_unit.canonical_charge_vector_json
      ) then
        raise exception 'WEEKLY_SOURCE_PROJECTION_REVERSAL_INTEGRITY_FAILED' using errcode='55000';
      end if;
    elsif coalesce(v_unit.source_facts_json->>'row_resolution_id','')
          !~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or not exists(
         select 1
         from public.weekly_source_row_resolutions resolution
         join public.weekly_source_row_economic_snapshots economic
           on economic.row_resolution_id=resolution.id
         join public.weekly_source_row_timesheet_lineages lineage
           on lineage.row_resolution_id=resolution.id
         where resolution.id=(v_unit.source_facts_json->>'row_resolution_id')::uuid
           and resolution.work_event_id=v_unit.work_event_id
           and resolution.contract_id=v_unit.contract_id
           and resolution.client_id=v_unit.actual_client_id
           and lineage.timesheet_id=v_root_timesheet_id
           and pg_catalog.encode(economic.calculation_fingerprint,'hex')=
                 v_unit.canonical_pay_vector_json->>'calculation_fingerprint'
           and private.weekly_source_finalisation_vector_v1(
                 economic.id,'PAY',1::smallint
               )=
                 v_unit.canonical_pay_vector_json
           and private.weekly_source_finalisation_vector_v1(
                 economic.id,'CHARGE',1::smallint
               )=
                 v_unit.canonical_charge_vector_json
       ) then
      raise exception 'WEEKLY_SOURCE_PROJECTION_SOURCE_FACT_INTEGRITY_FAILED' using errcode='55000';
    end if;
  end loop;

  -- Source-fixed expenses are a third invoice origin but remain ordinary
  -- candidate pay on this same Weekly root.  Validate every immutable expense
  -- movement independently; an expense-only zero-hours row deliberately has
  -- no worked movement and no segment.
  for v_expense_unit in
    select movement.*
    from public.weekly_source_billing_movements movement
    where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
      and movement.invoice_timesheet_id=v_root_timesheet_id
      and movement.expense_authority_generation_id is not null
      and movement.source_line_kind='SOURCE_FIXED_EXPENSE'
    order by movement.created_at_utc,movement.id
  loop
    if not private.weekly_source_ordinary_projection_expense_movement_assert_v1(
      v_expense_unit.id,v_revision.id,v_cycle.id,v_manifest.id,v_root_timesheet_id
    ) then
      raise exception 'WEEKLY_SOURCE_EXPENSE_MOVEMENT_INTEGRITY_FAILED'
        using errcode='55000';
    end if;
  end loop;

  v_service_snapshot_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_SERVICE_SNAPSHOT_V1',v_service_snapshot
  );
  v_source_unit_manifest_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_UNIT_MANIFEST_V1',v_source_units
  );
  v_expected_segments:=private.weekly_source_ordinary_projection_current_segments_v1(
    v_root_timesheet_id,v_revision.id
  );
  v_expected_source_expenses:=
    private.weekly_source_ordinary_projection_current_expenses_v1(
      v_root_timesheet_id,v_revision.id
    );
  v_source_expense_manifest_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_SOURCE_EXPENSE_MANIFEST_V1',
    v_expected_source_expenses
  );
  -- The completeness check reads the SAME owner the segment composer reads,
  -- so the count and the composed manifest can never be derived from two
  -- different rules.  The block that used to stand here was a second copy of
  -- the row-order ranking and had to be kept in step with it by hand.
  select pg_catalog.count(*) into v_active_movement_count
  from private.weekly_source_ordinary_projection_active_movements_v1(
    v_root_timesheet_id,v_revision.id
  );
  if v_active_movement_count<>pg_catalog.jsonb_array_length(v_expected_segments) then
    raise exception 'WEEKLY_SOURCE_ACTIVE_SEGMENT_MANIFEST_INCOMPLETE'
      using errcode='55000';
  end if;

  -- One work event is one shift, so it has at most one current entitlement
  -- head (14 s6.2.1 to s6.2.3).  Two live source positions of DIFFERENT
  -- economics on one work event are two contradictory statements about the
  -- same shift - the source shape 14 s4.2.8 requires to block at finalisation.
  -- There is no order-free way to choose between them and no rule that says
  -- which is right, so the money fails closed here rather than being settled
  -- by whichever row the Trust happened to list last (standing rule 5).
  select pg_catalog.count(*) into v_ambiguous_event_count
  from (
    select active.work_event_id
    from private.weekly_source_ordinary_projection_active_movements_v1(
      v_root_timesheet_id,v_revision.id
    ) active
    group by active.work_event_id
    having pg_catalog.count(*)>1
  ) ambiguous;
  if v_ambiguous_event_count>0 then
    raise exception 'WEEKLY_SOURCE_ORDINARY_AMBIGUOUS_SOURCE_HEAD'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'root_timesheet_id',v_root_timesheet_id,
              'final_revision_id',v_revision.id,
              'ambiguous_work_event_count',v_ambiguous_event_count
            )::text;
  end if;
  v_expected_actual_schedule:=
    private.weekly_source_ordinary_projection_actual_schedule_v1(v_expected_segments);
  v_active_segment_manifest_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_ACTIVE_SEGMENTS_V1',v_expected_segments
  );
  v_expected_rate_source_refs:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_FINAL_AUTHORITY_RATE_SOURCE_V1',
    'source_mode',v_source_mode,'root_timesheet_id',v_root_timesheet_id,
    'final_revision_id',v_revision.id,
    'final_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex'),
    'final_policy_fingerprint',pg_catalog.encode(v_revision.policy_fingerprint,'hex'),
    'client_manifest_hash',pg_catalog.encode(v_manifest.manifest_hash,'hex'),
    'source_unit_manifest_hash',pg_catalog.encode(v_source_unit_manifest_hash,'hex'),
    'source_expense_manifest_hash',
      pg_catalog.encode(v_source_expense_manifest_hash,'hex'),
    'active_segment_manifest_hash',pg_catalog.encode(v_active_segment_manifest_hash,'hex')
  );
  v_server_calculation_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_SERVER_CALCULATION_V1',
    pg_catalog.jsonb_build_object(
      'final_revision_id',v_revision.id,'root_timesheet_id',v_root_timesheet_id,
      'source_mode',v_source_mode,'source_units',v_source_units,
      'source_expense_authorities',v_expected_source_expenses,
      'expected_segments',v_expected_segments,
      'expected_actual_schedule',v_expected_actual_schedule,
      'expected_rate_source_refs',v_expected_rate_source_refs,
      'service_snapshot_hash',pg_catalog.encode(v_service_snapshot_hash,'hex')
    )
  );
  v_root_before_hash:=
    private.weekly_source_ordinary_projection_root_hash_v1(v_root_timesheet_id);

  -- S8.  This read decides TARGET_MANAGED_SUPPRESSED on a pay receipt, so it
  -- must never be allowed to pick an arbitrary row once the family is keyed on
  -- the Timesheet family rather than on one physical id (WP-03_NEEDS.md N1.2).
  v_target_family:=private.weekly_source_target_family_for_root_v1(v_root_timesheet_id);
  v_target_state:=v_target_family.ownership_state;
  if v_target_family.id is not null and v_target_state='TARGET_MANAGED' then
    v_receipt:=private.weekly_source_ordinary_projection_receipt_insert_v1(
      v_revision.id,v_cycle.id,v_client_id,v_root_timesheet_id,null,
      v_source_profile_kind,v_source_mode,'TARGET_MANAGED_SUPPRESSED',v_source_units,
      v_source_unit_manifest_hash,v_expected_source_expenses,
      v_source_expense_manifest_hash,v_revision.manifest_hash,v_revision.policy_fingerprint,
      v_service_snapshot_hash,v_server_calculation_fingerprint,v_root_before_hash,
      v_root_before_hash,v_idempotency_key,v_request_hash,v_actor
    );
    perform pg_catalog.set_config(
      'cloudtms.weekly_source_projection_owner',
      'weekly_source_ordinary_pay_projection_apply_atomic_v1',true
    );
    update public.weekly_source_state_transitions transition_row
    set ordinary_source_entitlement_projection_state='PUBLISHED'
    where transition_row.final_revision_id=v_revision.id
      and transition_row.ordinary_source_entitlement_projection_state='PENDING'
      and exists(
        select 1 from public.weekly_source_billing_movements movement
        where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.transition_id=transition_row.id
          and movement.invoice_timesheet_id=v_root_timesheet_id
      );
    return private.weekly_source_ordinary_projection_receipt_json_v1(v_receipt)
      ||pg_catalog.jsonb_build_object('idempotent_replay',false);
  end if;
  if v_target_family.id is not null and v_target_state<>'ORDINARY_SOURCE' then
    raise exception 'WEEKLY_SOURCE_TARGET_FAMILY_STATE_INVALID' using errcode='55000';
  end if;

  select coalesce(pg_catalog.bool_and(
    coalesce((unit.value->>'first_plan6_negative')::boolean,false)
  ),false) into v_first_negative_only
  from pg_catalog.jsonb_array_elements(v_source_units) unit(value);
  if v_first_negative_only then
    v_receipt:=private.weekly_source_ordinary_projection_receipt_insert_v1(
      v_revision.id,v_cycle.id,v_client_id,v_root_timesheet_id,null,
      v_source_profile_kind,v_source_mode,'NO_OP_FIRST_NEGATIVE',v_source_units,
      v_source_unit_manifest_hash,v_expected_source_expenses,
      v_source_expense_manifest_hash,v_revision.manifest_hash,v_revision.policy_fingerprint,
      v_service_snapshot_hash,v_server_calculation_fingerprint,v_root_before_hash,
      v_root_before_hash,v_idempotency_key,v_request_hash,v_actor
    );
    return private.weekly_source_ordinary_projection_receipt_json_v1(v_receipt)
      ||pg_catalog.jsonb_build_object('idempotent_replay',false);
  end if;

  v_preflight:=public.import_timesheet_financial_preflight_v1(
    array[v_root_timesheet_id],'WEEKLY_SOURCE_ORDINARY_PROJECTION',v_actor,
    '{}'::jsonb,true,1
  );
  v_required_path:=v_preflight->>'required_path';

  v_canonical_tsfin:=private.weekly_source_ordinary_projection_snapshot_assert_v1(
    v_root_timesheet_id,v_source_mode,v_expected_segments,
    v_expected_actual_schedule,v_expected_rate_source_refs,
    v_expected_source_expenses,v_service_snapshot
  );

  -- Has this root ever been authorised?  Two independent signals, and the root
  -- counts as authorised if EITHER says so, because the consequence of getting
  -- this wrong in the permissive direction is the forbidden behaviour itself.
  --   1. a live (non-withdrawn) Weekly Source lineage generation, which is what
  --      proof/34 section 4 records at first authorisation;
  --   2. the installed preflight owner's own classification: it asks for
  --      UNAUTHORISE_AMEND_RECALCULATE_REAUTHORISE precisely when the root is
  --      authorised, and it refuses outright when the root is paid, invoiced or
  --      inside an active Draft.
  -- Decision D8: the authorisation record is per ROOT, in
  -- public.weekly_source_root_authorisations, NOT on the per-source-row lineage
  -- table (which is written before any authorisation exists).
  select pg_catalog.count(*)::integer into v_live_generation_count
  from public.weekly_source_root_authorisations root_authorisation
  where pg_catalog.btrim(root_authorisation.family_booking_id)=pg_catalog.btrim(v_timesheet.booking_id)
    and root_authorisation.withdrawn_at_utc is null;

  if v_live_generation_count=0
     and coalesce((v_preflight->>'allowed')::boolean,false) is true
     and v_required_path='DIRECT_AMEND_RECALCULATE' then

    -- =====================================================================
    -- Initial branch: a genuinely never-authorised root (24 section 4.1;
    -- 27 section 3).  Prepared through the established mutable, unauthorised
    -- Timesheet/TSFIN writers, and NOT authorised here (XSG-001 / G2-0).
    -- =====================================================================

    -- 24 section 4.1: "The Candidate's signed/submitted hours must already be
    -- retained as separate immutable evidence and must remain readable after
    -- preparation.  If the current schema cannot prove that separation,
    -- preparation must fail closed rather than overwrite the only copy of the
    -- Candidate submission."  actual_schedule_json IS the submitted-hours copy
    -- the Office read projection uses, so it may only be overwritten when the
    -- Candidate submission is provably retained elsewhere.
    if v_timesheet.candidate_workflow_id is not null
       and not exists(
         select 1 from public.candidate_submission_workflows workflow
         where workflow.id=v_timesheet.candidate_workflow_id
           and workflow.immutable_submission_json is not null
           and workflow.immutable_submission_sha256 is not null
       ) then
      raise exception 'WEEKLY_SOURCE_CANDIDATE_SUBMISSION_NOT_SEPARATELY_RETAINED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'root_timesheet_id',v_root_timesheet_id,
                'candidate_workflow_id',v_timesheet.candidate_workflow_id)::text;
    end if;

    perform pg_catalog.set_config(
      'cloudtms.lifecycle_mutation_context','manual_timesheet_save',true
    );
    update public.timesheets timesheet_row
    set actual_schedule_json=v_expected_actual_schedule,
        updated_at=pg_catalog.transaction_timestamp()
    where timesheet_row.timesheet_id=v_root_timesheet_id
      and timesheet_row.is_current=true;
    if not found then
      raise exception 'WEEKLY_SOURCE_ROOT_TIMESHEET_CHANGED' using errcode='40001';
    end if;

    v_write_result:=public.tsfin_write_current_snapshot_single_bounded(
      v_root_timesheet_id,v_timesheet.version,v_canonical_tsfin,v_actor,
      pg_catalog.transaction_timestamp()
    );
    if coalesce((v_write_result->>'ok')::boolean,false) is not true
       or coalesce(v_write_result->>'timesheet_financials_id','')
            !~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'WEEKLY_SOURCE_ORDINARY_TSFIN_WRITE_FAILED'
        using errcode='55000',detail=coalesce(v_write_result,'{}'::jsonb)::text;
    end if;
    v_published_financial_id:=(v_write_result->>'timesheet_financials_id')::uuid;
    perform private.weekly_source_ordinary_projection_expenses_materialise_v1(
      v_root_timesheet_id,v_published_financial_id,v_expected_source_expenses
    );

    -- Deliberately absent: public.timesheet_authorise_generic_atomic.
    -- Finalisation never authorises (XSG-001, G2-0; 24 section 4.1).
    v_outcome:='PREPARED_FOR_AUTHORISATION';
  else

    -- =====================================================================
    -- Later branch: the root is already authorised (24 section 4.2).  Compose
    -- one complete proposed entitlement and record it.  NOTHING on the root is
    -- touched: no unauthorise, no schedule overwrite, no TSFIN rotation, no
    -- reauthorise.  A frozen, paid or invoiced root takes exactly this path;
    -- there is no REFUSED_LOCKED any more.
    -- =====================================================================
    v_components:=private.weekly_source_entitlement_components_v1(
      v_expected_segments,v_expected_source_expenses
    );
    v_components:=private.weekly_source_retain_approved_additional_v2(
      v_root_timesheet_id,v_components
    );
    v_decision_bundle_id:=private.weekly_source_entitlement_derived_uuid_v1(
      'WEEKLY_SOURCE_DECISION_BUNDLE_V1',
      pg_catalog.btrim(v_timesheet.booking_id)||'|'||v_revision.id::text
    );
    v_decision_id:=private.weekly_source_entitlement_derived_uuid_v1(
      'WEEKLY_SOURCE_DECISION_V1',v_decision_bundle_id::text||'|1'
    );
    v_head_id:=private.weekly_source_entitlement_derived_uuid_v1(
      'WEEKLY_SOURCE_PROPOSED_HEAD_V1',
      v_decision_bundle_id::text||'|1|'||v_root_timesheet_id::text
    );
    v_proposal_request:=private.weekly_source_entitlement_proposal_request_v1(
      v_root_timesheet_id,v_revision.id,'LOCKED_FINAL_SOURCE',
      v_decision_bundle_id,1::bigint,v_head_id,v_decision_id,v_components
    );
    v_proposal:=private.weekly_source_entitlement_proposal_record_v1(
      v_proposal_request,v_group.agency_id,v_timesheet.contract_id,
      v_timesheet.week_ending_date,v_actor
    );
    v_outcome:='PROPOSED';
  end if;

  perform pg_catalog.set_config(
    'cloudtms.weekly_source_projection_owner',
    'weekly_source_ordinary_pay_projection_apply_atomic_v1',true
  );
  update public.weekly_source_state_transitions transition_row
  set ordinary_source_entitlement_projection_state='PUBLISHED'
  where transition_row.final_revision_id=v_revision.id
    and transition_row.ordinary_source_entitlement_projection_state='PENDING'
    and exists(
      select 1 from public.weekly_source_billing_movements movement
      where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.transition_id=transition_row.id
        and movement.invoice_timesheet_id=v_root_timesheet_id
    );

  v_root_after_hash:=
    private.weekly_source_ordinary_projection_root_hash_v1(v_root_timesheet_id);
  v_receipt:=private.weekly_source_ordinary_projection_receipt_insert_v1(
    v_revision.id,v_cycle.id,v_client_id,v_root_timesheet_id,v_published_financial_id,
    v_source_profile_kind,v_source_mode,v_outcome,v_source_units,
    v_source_unit_manifest_hash,v_expected_source_expenses,
    v_source_expense_manifest_hash,v_revision.manifest_hash,v_revision.policy_fingerprint,
    v_service_snapshot_hash,v_server_calculation_fingerprint,v_root_before_hash,
    v_root_after_hash,v_idempotency_key,v_request_hash,v_actor
  );
  return private.weekly_source_ordinary_projection_receipt_json_v1(v_receipt)
    ||pg_catalog.jsonb_build_object(
      'idempotent_replay',false,
      'required_path',v_required_path,
      'preflight_fingerprint',v_preflight->>'preflight_fingerprint',
      'proposal',coalesce(v_proposal,'null'::jsonb)
    );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_SOURCE_ORDINARY_PROJECTION_SCOPE_INVALID' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_ordinary_projection_source_units_v1(
  p_final_revision_id uuid,
  p_root_timesheet_id uuid
) returns jsonb
language sql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'manifest_ordinal',manifest_movement.manifest_ordinal,
      'movement_id',movement.id,
      'work_event_id',movement.work_event_id,
      'movement_role',movement.movement_role,
      'source_profile_kind',movement.source_profile_kind,
      'source_line_kind',movement.source_line_kind,
      'movement_economic_hash',pg_catalog.encode(movement.movement_economic_hash,'hex'),
      'mapping_rate_policy_fingerprint',
        pg_catalog.encode(movement.mapping_rate_policy_fingerprint,'hex'),
      'source_facts_hash',pg_catalog.encode(private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_ORDINARY_UNIT_FACTS_V1',movement.source_facts_json
      ),'hex'),
      'first_plan6_negative',(
        movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
        and movement.movement_role='REVERSAL'
        and not exists(
          select 1
          from public.weekly_source_billing_movements prior_movement
          join public.weekly_source_final_revisions prior_revision
            on prior_revision.id=prior_movement.final_revision_id
          join public.weekly_source_cycles prior_cycle
            on prior_cycle.id=prior_movement.finalisation_cycle_id
          -- WP-62 (executed on a rotated family): the outstanding positive may
          -- sit on ANOTHER physical member of the Timesheet family, because a
          -- movement keeps the member that was current when its report was
          -- finalised.  Keyed on the physical root alone, a reversal landing
          -- after a rotation was flagged as a first-activation negative, the
          -- projection returned NO_OP_FIRST_NEGATIVE and the Candidate stayed
          -- paid for a shift the Trust had withdrawn.  The search is therefore
          -- keyed on the FAMILY through the established adapter (standing
          -- rule 3); for an unrotated family the adapter returns exactly
          -- {invoice_timesheet_id}, so nothing changes there.
          where prior_movement.source_profile_kind<>'SELF_BILL_REPORT' and prior_movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and prior_movement.invoice_timesheet_id=any(
            private.weekly_source_invoice_family_timesheet_ids_v1(
              movement.invoice_timesheet_id))
            and prior_movement.work_event_id=movement.work_event_id
            and prior_movement.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
            and prior_movement.movement_role in ('POSITIVE','REPLACEMENT')
            and (
              revision.state<>'PREPARED'
              or prior_revision.id is distinct from revision.predecessor_revision_id
            )
            -- The positive must not stand LATER than this negative on the
            -- revision ladder.  A positive in the SAME revision counts,
            -- whatever physical row it occupied: 14 s4.2.5 says row order has
            -- no financial meaning, so this limb must not read
            -- `source_row_ordinal`, which is what it used to compare.
            and (
              prior_cycle.finalisation_week_ending<source_cycle.finalisation_week_ending
              or (
                prior_cycle.finalisation_week_ending=source_cycle.finalisation_week_ending
                and prior_revision.finalised_at_utc<=revision.finalised_at_utc
              )
            )
        )
      )
    ) order by manifest_movement.manifest_ordinal
  ),'[]'::jsonb)
  from public.weekly_source_billing_movements movement
  join public.weekly_source_manifest_movements manifest_movement
    on manifest_movement.billing_movement_id=movement.id
  join public.weekly_source_client_manifests client_manifest on coalesce(client_manifest.invoice_window_cycle_id,client_manifest.source_cycle_id)=client_manifest.source_cycle_id and client_manifest.id=manifest_movement.client_manifest_id
   and client_manifest.final_revision_id=movement.final_revision_id
   and client_manifest.client_id=movement.actual_client_id
  join public.weekly_source_final_revisions revision
    on revision.id=movement.final_revision_id
  join public.weekly_source_cycles source_cycle
    on source_cycle.id=movement.finalisation_cycle_id
  where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=p_final_revision_id
    and movement.invoice_timesheet_id=p_root_timesheet_id
    and movement.expense_authority_generation_id is null
    and movement.source_line_kind<>'SOURCE_FIXED_EXPENSE';
$function$;

create or replace function private.weekly_source_ordinary_projection_active_movements_v1(
  p_root_timesheet_id uuid,
  p_through_final_revision_id uuid
) returns setof public.weekly_source_billing_movements
language sql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  with root_scope as materialized (
    select ts.booking_id,ts.contract_id,ts.week_ending_date,c.candidate_id,c.client_id,
      coalesce(module.active_owner='NEXT' and exists(
        select 1 from public.weekly_exceptional_pay_target_families f
        where f.root_timesheet_id=ts.timesheet_id and f.root_family_booking_id=ts.booking_id
          and pg_catalog.btrim(f.root_family_booking_id)=pg_catalog.btrim(ts.booking_id)
          and private.bpay_next_protected_owner_route_v1(f.id)='NEXT'
      ),false) as use_next
    from public.timesheets ts join public.contracts c on c.id=ts.contract_id
    left join private.bpay_next_module_control module on module.id=1
    where ts.timesheet_id=p_root_timesheet_id
  ), family as materialized (
    -- WP-62 (WP-57 handoff N1, executed): a Timesheet family can carry more
    -- than one physical member after a rotation, and a movement keeps the
    -- member that was current when its report was finalised.  Pairing a full
    -- negative to its positive must therefore run over the WHOLE family, or a
    -- reversal landing after a rotation never meets the positive it reverses
    -- and the Candidate stays paid for a shift the Trust withdrew (executed:
    -- 8.00 h / GBP 80.00 paid against a GBP 0.00 invoice).  The family is
    -- resolved ONCE through the established adapter - the same one the
    -- protected proposal owner and the invoice owners use - never by a second
    -- resolver.  For an unrotated family it returns exactly
    -- {p_root_timesheet_id}, so every decision below is unchanged there, and
    -- the answer is the same whichever member of a family is asked.
    -- NEXT uses the exact immutable Source lineage's raw family key; only
    -- retained C1 invokes the old physical-family resolver. This changes
    -- membership, NOT the Source revision-ladder cancellation calculation
    -- below. It is not a maintained-current observation or bounded-history
    -- claim; a separate real producer-owned current factual binding is next.
    select root_scope.*,case when use_next then array[p_root_timesheet_id]
      else private.weekly_source_invoice_family_timesheet_ids_v1(p_root_timesheet_id) end as timesheet_ids
    from root_scope
  ), target as (
    select target_revision.finalised_at_utc,target_revision.revision_number,
           target_cycle.finalisation_week_ending,target_revision.id,
           target_revision.state,target_revision.predecessor_revision_id
    from public.weekly_source_final_revisions target_revision
    join public.weekly_source_cycles target_cycle
      on target_cycle.id=target_revision.source_cycle_id
    where target_revision.id=p_through_final_revision_id
  ), scoped as (
    select
      movement.id,
      movement.work_event_id,
      movement.movement_role,
      movement.source_line_kind,
      movement.prior_movement_id,
      movement.created_at_utc,
      revision.finalised_at_utc,
      revision.revision_number,
      source_cycle.finalisation_week_ending,
      pg_catalog.jsonb_build_object(
        'work_date',movement.source_facts_json->>'work_date',
        'start_at_local',movement.source_facts_json->>'start_at_local',
        'end_at_local',movement.source_facts_json->>'end_at_local',
        'break_minutes',movement.source_facts_json->>'break_minutes',
        'hours_day',pg_catalog.round(pg_catalog.abs(
          (movement.canonical_pay_vector_json#>>'{hours,day}')::numeric),2)::text,
        'hours_night',pg_catalog.round(pg_catalog.abs(
          (movement.canonical_pay_vector_json#>>'{hours,night}')::numeric),2)::text,
        'hours_sat',pg_catalog.round(pg_catalog.abs(
          (movement.canonical_pay_vector_json#>>'{hours,sat}')::numeric),2)::text,
        'hours_sun',pg_catalog.round(pg_catalog.abs(
          (movement.canonical_pay_vector_json#>>'{hours,sun}')::numeric),2)::text,
        'hours_bh',pg_catalog.round(pg_catalog.abs(
          (movement.canonical_pay_vector_json#>>'{hours,bh}')::numeric),2)::text,
        'pay_pence',pg_catalog.abs(
          (movement.canonical_pay_vector_json->>'total_pence')::bigint)::text,
        'charge_pence',pg_catalog.abs(
          (movement.canonical_charge_vector_json->>'total_pence')::bigint)::text
      ) as economic_magnitude
    from public.weekly_source_billing_movements movement
    join public.weekly_source_final_revisions revision
      on revision.id=movement.final_revision_id
    join public.weekly_source_cycles source_cycle
      on source_cycle.id=movement.finalisation_cycle_id
    cross join target
    cross join family
    where ((not family.use_next and movement.invoice_timesheet_id=any(family.timesheet_ids))
      or (family.use_next and exists(
        select 1 from public.weekly_source_row_timesheet_lineages lineage
        where lineage.row_resolution_id=case
          when coalesce(movement.source_facts_json->>'row_resolution_id','')
            ~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
            then (movement.source_facts_json->>'row_resolution_id')::uuid
          else (select (prior.source_facts_json->>'row_resolution_id')::uuid
            from public.weekly_source_billing_movements prior
            where prior.source_profile_kind<>'SELF_BILL_REPORT' and prior.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and prior.id=movement.prior_movement_id and prior.work_event_id=movement.work_event_id
              and prior.candidate_id=movement.candidate_id and prior.contract_id=movement.contract_id
              and prior.actual_client_id=movement.actual_client_id and prior.movement_role in ('POSITIVE','REPLACEMENT')
              and coalesce(prior.source_facts_json->>'row_resolution_id','')
                ~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') end
          and lineage.family_booking_id=family.booking_id and lineage.work_event_id=movement.work_event_id
          and lineage.candidate_id=family.candidate_id and lineage.client_id=family.client_id
          and lineage.contract_id=family.contract_id and lineage.week_ending_date=family.week_ending_date
          and movement.candidate_id=family.candidate_id and movement.actual_client_id=family.client_id
          and movement.contract_id=family.contract_id)))
      and movement.expense_authority_generation_id is null
      and movement.source_line_kind<>'SOURCE_FIXED_EXPENSE'
      and movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and (revision.state='CURRENT' or revision.id=target.id)
      and (
        target.state<>'PREPARED'
        or revision.id is distinct from target.predecessor_revision_id
      )
      and (
        source_cycle.finalisation_week_ending<target.finalisation_week_ending
        or (
          source_cycle.finalisation_week_ending=target.finalisation_week_ending
          and revision.finalised_at_utc<target.finalised_at_utc
        )
        or (
          source_cycle.finalisation_week_ending=target.finalisation_week_ending
          and revision.finalised_at_utc=target.finalised_at_utc
          and revision.revision_number<target.revision_number
        )
        or (
          source_cycle.finalisation_week_ending=target.finalisation_week_ending
          and revision.finalised_at_utc=target.finalised_at_utc
          and revision.revision_number=target.revision_number
          and revision.id::text<=target.id::text
        )
      )
  ), explicitly_superseded as (
    select distinct scoped.prior_movement_id as movement_id
    from scoped
    where scoped.prior_movement_id is not null
      and scoped.movement_role in ('REVERSAL','REPLACEMENT')
  ), nhsp_physical as (
    select scoped.*
    from scoped
    where scoped.source_line_kind in (
        'NHSP_PHYSICAL_POSITIVE','NHSP_PHYSICAL_FULL_NEGATIVE'
      )
      and scoped.prior_movement_id is null
  ), nhsp_cancelled as (
    -- A positive is bound by a full negative when, inside its own work event
    -- and economic magnitude, the number of reversals standing at or after it
    -- is at least the number of positives standing at or after it.  That is a
    -- pure counting statement over the revision ladder: it is unchanged by any
    -- permutation of the physical rows inside a report, and it is unchanged by
    -- which report a row arrived in as long as the ladder order is the same.
    select positive.id as movement_id
    from nhsp_physical positive
    where positive.movement_role in ('POSITIVE','REPLACEMENT')
      and (
        select pg_catalog.count(*)
        from nhsp_physical reversal
        where reversal.work_event_id=positive.work_event_id
          and reversal.economic_magnitude=positive.economic_magnitude
          and reversal.movement_role='REVERSAL'
          and (reversal.finalisation_week_ending,reversal.finalised_at_utc,
               reversal.revision_number)
              >=(positive.finalisation_week_ending,positive.finalised_at_utc,
                 positive.revision_number)
      )>=(
        select pg_catalog.count(*)
        from nhsp_physical peer
        where peer.work_event_id=positive.work_event_id
          and peer.economic_magnitude=positive.economic_magnitude
          and peer.movement_role in ('POSITIVE','REPLACEMENT')
          and (peer.finalisation_week_ending,peer.finalised_at_utc,
               peer.revision_number)
              >=(positive.finalisation_week_ending,positive.finalised_at_utc,
                 positive.revision_number)
      )
  ), live as (
    select scoped.*
    from scoped
    where scoped.movement_role in ('POSITIVE','REPLACEMENT')
      and not exists(
        select 1 from explicitly_superseded
        where explicitly_superseded.movement_id=scoped.id
      )
      and not exists(
        select 1 from nhsp_cancelled
        where nhsp_cancelled.movement_id=scoped.id
      )
  ), current_head as (
    -- 14 s6.2.2: where no protected version exists, "the latest final source
    -- position supplies the current entitlement".  Latest means latest on the
    -- REVISION ladder - which report, which revision - and nothing else.  A
    -- surviving position from an earlier report is history the later report
    -- has restated; it is not a second shift.  Stated as "no live peer on this
    -- work event stands later", so no `order by` decides it.
    select live.*
    from live
    where not exists(
      select 1
      from live peer
      where peer.work_event_id=live.work_event_id
        and (peer.finalisation_week_ending,peer.finalised_at_utc,
             peer.revision_number)
            >(live.finalisation_week_ending,live.finalised_at_utc,
              live.revision_number)
    )
  ), one_per_position as (
    -- Inside that one latest revision, several live rows of the SAME economic
    -- magnitude are one position stated more than once, so exactly one of them
    -- represents it and the money is identical whichever it is.  The
    -- comparison is a strict total order because id::text is unique, so
    -- exactly one member of each group satisfies "no peer in this group stands
    -- after me".  Rows of DIFFERENT magnitudes survive this step together and
    -- the projection owner refuses them: inside one revision there is no
    -- later-than relation to appeal to, and the only thing that could separate
    -- them is the physical row order, which carries no financial meaning.
    select current_head.id
    from current_head
    where not exists(
      select 1
      from current_head peer
      where peer.work_event_id=current_head.work_event_id
        and peer.economic_magnitude=current_head.economic_magnitude
        and (peer.created_at_utc,peer.id::text)
            >(current_head.created_at_utc,current_head.id::text)
    )
  )
  select movement.*
  from public.weekly_source_billing_movements movement
  join one_per_position on one_per_position.id=movement.id;
$function$;

create or replace function private.weekly_source_selected_source_witness_v1(
  p_family_id uuid,p_action_cycle_id uuid,p_work_event_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_contract public.contracts%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_protected public.weekly_exceptional_pay_family_events%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_mapping public.weekly_source_row_resolutions%rowtype;
  v_row public.weekly_source_upload_rows%rowtype;
  v_final public.weekly_source_final_revisions%rowtype;
  v_transition public.weekly_source_state_transitions%rowtype;
  v_snapshot public.weekly_source_final_snapshot_lines%rowtype;
  v_choice private.weekly_source_office_row_choices%rowtype;
  v_mode text; v_kind text; v_basis_kind text;
  v_source jsonb; v_selected jsonb; v_current_row jsonb;
  v_basis jsonb; v_scope jsonb; v_result jsonb; v_history jsonb;
  v_census jsonb:='[]'::jsonb;
  v_rows_checked jsonb;
  v_matches jsonb; v_root_ids uuid[];
  v_count integer; v_generation integer; v_has_positive boolean; v_has_negative boolean;
begin
  if p_family_id is null or p_action_cycle_id is null or p_work_event_id is null then
    raise exception 'WEEKLY_SOURCE_SELECTED_WITNESS_IDENTITY_REQUIRED' using errcode='22023'; end if;
  select * into strict v_family from public.weekly_exceptional_pay_target_families where id=p_family_id;
  select * into strict v_contract from public.contracts where id=v_family.contract_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=p_action_cycle_id;
  select * into strict v_event from public.weekly_work_events where id=p_work_event_id;
  if v_contract.candidate_id is distinct from v_family.candidate_id
     or v_event.candidate_id is distinct from v_family.candidate_id
     or v_event.client_id is distinct from v_contract.client_id
     or v_event.first_source_group_id is distinct from v_cycle.source_group_id
     or v_event.work_date not between v_family.week_start_date and v_family.week_ending_date
     or (v_cycle.scope_client_id is not null and v_cycle.scope_client_id<>v_contract.client_id)
     or v_family.agency_id is distinct from (select agency_id from public.weekly_source_groups where id=v_cycle.source_group_id)
     or v_contract.week_ending_weekday_snapshot not between 0 and 6
     or v_contract.week_ending_weekday_snapshot is null
     or v_event.work_date+((v_contract.week_ending_weekday_snapshot-extract(dow from v_event.work_date)::integer+7)%7)
          is distinct from v_family.week_ending_date then
    raise exception 'WEEKLY_SOURCE_SELECTED_WITNESS_SCOPE_INVALID' using errcode='55000'; end if;
  v_scope:=private.weekly_source_pay_query_scope_v1(v_family.root_timesheet_id);
  if v_scope is null or v_scope->>'target_family_id' is distinct from v_family.id::text then return null; end if;
  v_root_ids:=private.weekly_source_invoice_family_timesheet_ids_v1(v_family.root_timesheet_id);
  if cardinality(v_root_ids) is null or cardinality(v_root_ids)=0 then return null; end if;
  v_mode:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,v_event.work_date)->>'c1_source_mode';
  v_source:=private.weekly_source_protected_final_source_context_v1(v_family.id,v_cycle.id,v_event.id);
  select count(*),jsonb_agg(s.value)->0 into v_count,v_selected
    from jsonb_array_elements(v_source->'client_sources') s(value)
    where s.value->>'external_identity'=v_event.id::text;
  if v_count<>1 then return null; end if;

  -- Reuse the exact current-row reader, including Final precedence, original
  -- report scope, configured workweek and raw normalised-row hash domain.
  select count(*),jsonb_agg(s.source)->0 into v_count,v_current_row
    from public.weekly_source_row_resolutions r
    cross join lateral (select private.weekly_source_manual_review_source_v2(r.upload_row_id) source) s
    where r.work_event_id=v_event.id and r.candidate_id=v_family.candidate_id
      and r.client_id=v_contract.client_id and r.contract_id=v_contract.id
      and s.source is not null and s.source->>'row_resolution_id'=r.id::text
      and (v_source->'source_observed'='false'::jsonb
        or (v_mode='NHSP_WEEKLY' and exists(select 1 from public.weekly_source_billing_movements m
          where m.source_profile_kind<>'SELF_BILL_REPORT' and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and m.id::text=v_selected->>'client_source_id' and m.nhsp_upload_row_id=r.upload_row_id))
        or (v_mode='HEALTHROSTER_WEEKLY' and exists(select 1 from public.weekly_source_state_transitions t
          join public.weekly_source_final_snapshot_lines sn on sn.id=t.new_snapshot_line_id
          where t.id::text=v_selected->>'client_source_id' and sn.upload_row_id=r.upload_row_id)));
  if v_count>1 then return null; end if;
  if v_count=1 then
    if v_current_row->>'source_group_id' is distinct from v_cycle.source_group_id::text then return null; end if;
    v_kind:='CURRENT_ROW';
    v_basis_kind:=case when v_current_row->>'final_revision_id' is null
      then 'CURRENT_PROVISIONAL_ROW' else 'CURRENT_FINAL_ROW' end;
    v_basis:=v_current_row;
  else
    -- Latest selected clocks belong to the actual family event. Other duties
    -- in the same Timesheet are not a whole-family absence veto.
    select * into v_protected from public.weekly_exceptional_pay_family_events e
      where e.family_id=v_family.id and e.durable_work_event_id=v_event.id
      order by e.event_sequence desc limit 1;
    if not found then return null; end if;
    -- Failed/rebuilding authority can exist before a logical upload/row does.
    -- No work-date or nullable unparsed identity proves that it is unrelated.
    if exists(select 1 from public.weekly_source_cycles c
      where c.source_group_id=v_cycle.source_group_id
        and (c.scope_client_id is null or c.scope_client_id=v_contract.client_id)
        and c.projection_state in ('REBUILDING','FAILED'))
      or exists(select 1 from public.weekly_source_report_scopes s
        where s.source_group_id=v_cycle.source_group_id and s.client_id=v_contract.client_id
          and s.projection_state in ('REBUILDING','FAILED'))
      or exists(select 1 from public.weekly_source_upload_attempts a
        left join public.weekly_source_cycles c on c.id=a.source_cycle_id
        left join public.weekly_source_report_scopes rs on rs.id=a.report_scope_id
        where a.agency_id=v_family.agency_id
          and (a.source_group_id is null or a.source_group_id=v_cycle.source_group_id)
          and (c.scope_client_id is null or c.scope_client_id=v_contract.client_id)
          and (rs.client_id is null or rs.client_id=v_contract.client_id)
          and a.logical_upload_id is null and a.result in ('PARTIAL','CORRUPT','FAILED','CONFLICT','REJECTED')
          and not exists(select 1 from public.weekly_source_uploads repaired
            where a.content_sha256 is not null and repaired.content_sha256=a.content_sha256
              and repaired.source_cycle_id=a.source_cycle_id
              and repaired.report_scope_id is not distinct from a.report_scope_id
              and repaired.purpose=a.purpose and repaired.declared_scope_fingerprint=a.declared_scope_fingerprint
              and repaired.uploaded_at_utc>=a.attempted_at_utc and repaired.state='CURRENT'
              and (repaired.coverage_state='COMPLETE' or (
                repaired.coverage_proof_kind='NHSP_TRUST_REPORT_SCOPE' and repaired.report_scope_id is not null
                and exists(select 1 from public.weekly_source_format_profiles p
                  where p.id=repaired.source_format_profile_id and p.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
                and repaired.row_manifest_hash=private.weekly_source_upload_manifest_hash_v1(repaired.id)
              )))) then return null; end if;
    -- Census every potentially relevant non-superseded import across cutoffs.
    -- Nullable resolution identity is UNKNOWN, not evidence of another worker.
    for v_upload in select u.* from public.weekly_source_uploads u
      join public.weekly_source_cycles c on c.id=u.source_cycle_id
      left join public.weekly_source_report_scopes rs on rs.id=u.report_scope_id
      where c.source_group_id=v_cycle.source_group_id and u.state<>'SUPERSEDED'
        and (c.scope_client_id is null or c.scope_client_id=v_contract.client_id)
        and (rs.client_id is null or rs.client_id=v_contract.client_id)
        and (u.confirmed_coverage_start_local_date is null or u.confirmed_coverage_end_local_date is null
          or daterange(v_event.work_date-1,v_event.work_date+2,'[)') &&
            daterange(u.confirmed_coverage_start_local_date,u.confirmed_coverage_end_local_date+1,'[)')
          or exists(select 1 from public.weekly_source_upload_rows rr where rr.upload_id=u.id
            and (rr.work_date is null or rr.work_date between v_event.work_date-1 and v_event.work_date+1)))
      order by u.source_cycle_id,u.report_scope_id,u.id
    loop
      if v_upload.state in ('STAGING','SEALED','CORRECTION_READY','REJECTED') then return null; end if;
      if v_upload.state<>'CURRENT' or v_upload.row_manifest_hash is null then return null; end if;
      select count(*) into v_count from public.weekly_source_projection_publications p
        where p.upload_id=v_upload.id and p.source_cycle_id=v_upload.source_cycle_id
          and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT';
      if v_count<>1 then return null; end if;
      select * into strict v_publication from public.weekly_source_projection_publications p
        where p.upload_id=v_upload.id and p.source_cycle_id=v_upload.source_cycle_id
          and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT';
      if v_publication.published_at_utc is null or not isfinite(v_publication.published_at_utc)
         or (v_upload.report_scope_id is null and v_publication.authority_scope_kind is distinct from 'CYCLE')
         or (v_upload.report_scope_id is not null and (
           v_publication.authority_scope_kind is distinct from 'NHSP_REPORT_SCOPE'
           or not exists(select 1 from public.weekly_source_report_scopes rs
             join public.weekly_source_cycles c on c.id=rs.source_cycle_id
             where rs.id=v_upload.report_scope_id and rs.source_cycle_id=v_upload.source_cycle_id
               and rs.source_group_id=v_cycle.source_group_id and c.source_group_id=rs.source_group_id
               and rs.client_id=v_contract.client_id and rs.cutoff_at_utc=c.cutoff_at_utc)
         )) then return null; end if;
      if v_publication.authority_scope_version>2147483647
         or coalesce(v_publication.projection_generation,0)>2147483647 then
        raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003'; end if;
      v_generation:=coalesce(v_publication.projection_generation,v_publication.authority_scope_version::integer);
      if v_generation is null then return null; end if;
      -- Finalised authority deliberately uses its Final pointer, not equality
      -- with the provisional version that Finalisation legitimately advanced.
      if not exists(select 1 from public.weekly_source_final_revisions f
        join public.weekly_source_cycles c on c.id=f.source_cycle_id
        left join public.weekly_source_report_scopes rs on rs.id=f.report_scope_id
        where f.upload_id=v_upload.id and f.state='CURRENT'
          and f.source_cycle_id=v_upload.source_cycle_id
          and f.report_scope_id is not distinct from v_upload.report_scope_id
          and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)
          and ((f.authority_scope_kind='CYCLE' and f.report_scope_id is null and c.current_final_revision_id=f.id)
            or (f.authority_scope_kind='NHSP_REPORT_SCOPE' and rs.current_final_revision_id=f.id
              and rs.source_cycle_id=c.id and rs.source_group_id=c.source_group_id
              and rs.client_id=v_contract.client_id and rs.cutoff_at_utc=c.cutoff_at_utc))) then
        if not exists(select 1 from public.weekly_source_cycles c
          left join public.weekly_source_report_scopes rs on rs.id=v_upload.report_scope_id
          where c.id=v_upload.source_cycle_id and (
            (v_upload.report_scope_id is null and c.current_complete_upload_id=v_upload.id
              and c.current_projection_publication_id=v_publication.id and c.projection_state='CURRENT'
              and c.version=v_publication.authority_scope_version)
            or (rs.id is not null and rs.current_complete_upload_id=v_upload.id
              and rs.current_projection_publication_id=v_publication.id and rs.projection_state='CURRENT'
              and rs.version=v_publication.authority_scope_version))) then return null; end if;
      end if;
      v_rows_checked:='[]'::jsonb;
      for v_row in select * from public.weekly_source_upload_rows r where r.upload_id=v_upload.id
        and (r.work_date is null or r.work_date between v_event.work_date-1 and v_event.work_date+1)
        order by r.id
      loop
        select * into v_mapping from public.weekly_source_row_resolutions r
          where r.upload_row_id=v_row.id and r.generation=v_generation;
        if not found or v_mapping.mapping_state<>'RESOLVED' then return null; end if;
        v_rows_checked:=v_rows_checked||jsonb_build_array(jsonb_build_object(
          'upload_row_id',v_row.id,'source_row_hash',encode(v_row.normalised_row_hash,'hex'),
          'row_resolution_id',v_mapping.id,'generation',v_mapping.generation,
          'candidate_id',v_mapping.candidate_id,'client_id',v_mapping.client_id,
          'contract_id',v_mapping.contract_id,'work_event_id',v_mapping.work_event_id,
          'source_row_fingerprint',encode(v_mapping.source_row_fingerprint,'hex'),
          'work_event_match_fingerprint',encode(v_mapping.work_event_match_fingerprint,'hex'),
          'qualification_profile_fingerprint',encode(v_mapping.qualification_profile_fingerprint,'hex'),
          'qualifying_contract_set_hash',encode(v_mapping.qualifying_contract_set_hash,'hex'),
          'contract_and_rate_fingerprint',encode(v_mapping.contract_and_rate_fingerprint,'hex'),
          'effective_policy_fingerprint',encode(v_mapping.effective_policy_fingerprint,'hex')));
        if v_mapping.candidate_id<>v_family.candidate_id or v_mapping.client_id<>v_contract.client_id
           or v_mapping.contract_id<>v_contract.id then continue; end if;
        if v_mapping.candidate_id is null or v_mapping.client_id is null or v_mapping.contract_id is null
           or v_row.work_date is null then return null; end if;
        if v_mapping.work_event_id=v_event.id then
          -- Retained physical positive history is required for a genuine NHSP
          -- full reversal. It is not a surviving payable row: the active owner
          -- must already prove extinction, and the complete sealed physical
          -- history is qualified below. A provisional positive cannot pass.
          if not exists(select 1 from public.weekly_source_billing_movements m
            join public.weekly_source_final_revisions f on f.id=m.final_revision_id
              and f.upload_id=v_upload.id and f.source_cycle_id=v_upload.source_cycle_id
              and f.report_scope_id=v_upload.report_scope_id and f.state='CURRENT'
              and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)
            join public.weekly_source_report_scopes rs on rs.id=f.report_scope_id
              and rs.current_final_revision_id=f.id and rs.client_id=v_contract.client_id
            join public.weekly_source_client_manifests cm on coalesce(cm.invoice_window_cycle_id,cm.source_cycle_id)=cm.source_cycle_id and cm.final_revision_id=f.id
              and cm.client_id=v_contract.client_id and cm.source_group_id=v_cycle.source_group_id
              and cm.source_cycle_id=f.source_cycle_id
            join public.weekly_source_manifest_movements mm on mm.client_manifest_id=cm.id
              and mm.billing_movement_id=m.id and mm.movement_hash=m.movement_economic_hash
            where v_mode='NHSP_WEEKLY' and v_source->'source_observed'='true'::jsonb
              and v_source#>'{source_proposal,source_present}'='false'::jsonb
              and m.nhsp_upload_row_id=v_row.id and m.work_event_id=v_event.id
              and m.candidate_id=v_family.candidate_id and m.contract_id=v_contract.id
              and m.actual_client_id=v_contract.client_id and m.invoice_timesheet_id=any(v_root_ids)
              and m.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
              and m.source_line_kind in ('NHSP_PHYSICAL_POSITIVE','NHSP_PHYSICAL_FULL_NEGATIVE'))
            and not exists(select 1 from public.weekly_source_final_snapshot_lines sn
              join public.weekly_source_final_revisions old_final on old_final.id=sn.final_revision_id
                and old_final.upload_id=v_upload.id and old_final.source_cycle_id=v_upload.source_cycle_id
                and old_final.report_scope_id is null and old_final.state='CURRENT'
                and old_final.finalised_at_utc is not null and isfinite(old_final.finalised_at_utc)
              join public.weekly_source_cycles old_cycle on old_cycle.id=old_final.source_cycle_id
                and old_cycle.current_final_revision_id=old_final.id and old_cycle.source_group_id=v_cycle.source_group_id
              join public.weekly_source_client_manifests cm on coalesce(cm.invoice_window_cycle_id,cm.source_cycle_id)=cm.source_cycle_id and cm.final_revision_id=old_final.id
                and cm.source_cycle_id=old_cycle.id and cm.source_group_id=old_cycle.source_group_id
                and cm.client_id=v_contract.client_id
              where v_mode='HEALTHROSTER_WEEKLY' and v_source->'source_observed'='true'::jsonb
                and v_source#>'{source_proposal,source_present}'='false'::jsonb
                and sn.upload_row_id=v_row.id and sn.row_resolution_id=v_mapping.id
                and sn.work_event_id=v_event.id and sn.candidate_id=v_family.candidate_id
                and sn.client_id=v_contract.client_id and sn.contract_id=v_contract.id
                and sn.work_date=v_event.work_date
                and exists(select 1 from public.weekly_source_state_transitions cancelled
                  join public.weekly_source_final_revisions cancel_final on cancel_final.id=cancelled.final_revision_id
                    and cancel_final.source_cycle_id=cancelled.finalisation_cycle_id
                    and cancel_final.state='CURRENT' and cancel_final.authority_scope_kind='CYCLE'
                  join public.weekly_source_cycles cancel_cycle on cancel_cycle.id=cancel_final.source_cycle_id
                    and cancel_cycle.current_final_revision_id=cancel_final.id
                    and cancel_cycle.source_group_id=v_cycle.source_group_id
                  where cancelled.id::text=v_selected->>'client_source_id' and cancelled.work_event_id=v_event.id
                    and cancelled.outcome='CANCEL' and cancelled.previous_present and not cancelled.new_present
                    and cancelled.previous_snapshot_line_id is not null and cancelled.new_snapshot_line_id is null))
            and not exists(select 1 from public.weekly_source_final_revisions cancel_final
              join public.weekly_source_format_profiles zero_profile on zero_profile.id=v_upload.source_format_profile_id
                and zero_profile.final_authority_kind in ('GENERIC_COMPLETE_SNAPSHOT','HEALTHROSTER_ACTUAL_ROWS')
                and zero_profile.omission_meaning='CANCEL_INSIDE_CONFIRMED_COVERAGE'
              join public.weekly_source_uploads actual_upload on actual_upload.id=cancel_final.upload_id
                and cancel_final.upload_id=v_upload.id and cancel_final.state='CURRENT'
                and cancel_final.authority_scope_kind='CYCLE' and cancel_final.report_scope_id is null
                and cancel_final.finalised_at_utc is not null and isfinite(cancel_final.finalised_at_utc)
              join public.weekly_source_cycles cancel_cycle on cancel_cycle.id=cancel_final.source_cycle_id
                and cancel_cycle.current_final_revision_id=cancel_final.id
                and cancel_cycle.source_group_id=v_cycle.source_group_id
              join public.weekly_source_client_manifests cm on coalesce(cm.invoice_window_cycle_id,cm.source_cycle_id)=cm.source_cycle_id and cm.final_revision_id=cancel_final.id
                and cm.source_cycle_id=cancel_cycle.id and cm.source_group_id=cancel_cycle.source_group_id
                and cm.client_id=v_contract.client_id
              where v_mode='HEALTHROSTER_WEEKLY'
                and v_source#>'{source_proposal,source_present}'='false'::jsonb
                and v_row.row_finalisation_state='SOURCE_ABSENT_ZERO'
                and v_upload.coverage_state='COMPLETE' and v_upload.coverage_timezone='Europe/London'
                and v_upload.coverage_confirmed_at_utc is not null and isfinite(v_upload.coverage_confirmed_at_utc)
                and v_upload.coverage_confirmed_by_user_id is not null
                and v_upload.confirmed_coverage_start_local_date=cancel_final.coverage_start_local_date
                and v_upload.confirmed_coverage_end_local_date=cancel_final.coverage_end_local_date
                and v_event.work_date between cancel_final.coverage_start_local_date and cancel_final.coverage_end_local_date)
          then return null; end if;
          continue;
        end if;
        select * into v_choice from private.weekly_source_office_row_choices c
          where c.upload_row_id=v_row.id and c.candidate_id=v_family.candidate_id
            and c.client_id=v_contract.client_id and c.contract_id=v_contract.id order by c.id desc limit 1;
        if found and v_choice.separate_shift and v_choice.work_event_id is null then continue; end if;
        v_matches:=private.weekly_source_protected_match_candidates_v1(v_row.id,v_family.candidate_id,v_contract.client_id);
        if exists(select 1 from jsonb_array_elements(v_matches) m
          where m->>'work_event_id'=v_event.id::text and m->>'contract_id'=v_contract.id::text
            and (m->'schedule_compatible'='true'::jsonb or m->'retained_source_identity'='true'::jsonb)) then return null; end if;
        if v_row.start_at_local is null or v_row.end_at_local is null
           or v_protected.start_at_local is null or v_protected.end_at_local is null
           or (v_row.start_at_local<v_protected.end_at_local and v_protected.start_at_local<v_row.end_at_local)
        then return null; end if;
      end loop;
      if exists(select 1 from public.weekly_source_format_profiles p
        where p.id=v_upload.source_format_profile_id and p.final_authority_kind='NHSP_TRUST_BACKING_REPORT') then
        -- NHSP completeness is the report's actual row/count/scope seal. It
        -- deliberately has no roster date-coverage attestation or inference.
        if v_upload.coverage_proof_kind is distinct from 'NHSP_TRUST_REPORT_SCOPE'
           or v_upload.report_scope_id is null
           or v_upload.row_manifest_hash is distinct from private.weekly_source_upload_manifest_hash_v1(v_upload.id)
        then return null; end if;
      elsif v_upload.coverage_state is distinct from 'COMPLETE' then return null; end if;
      v_census:=v_census||jsonb_build_array(jsonb_build_object(
        'upload_id',v_upload.id,'source_cycle_id',v_upload.source_cycle_id,'report_scope_id',v_upload.report_scope_id,
        'source_cycle_cutoff_at_utc',(select c.cutoff_at_utc from public.weekly_source_cycles c where c.id=v_upload.source_cycle_id),
        'publication_at_utc',v_publication.published_at_utc,'authority_scope_kind',v_publication.authority_scope_kind,
        'row_manifest_hash',encode(v_upload.row_manifest_hash,'hex'),
        'declared_scope_fingerprint',encode(v_upload.declared_scope_fingerprint,'hex'),
        'publication_id',v_publication.id,'authority_scope_version',v_publication.authority_scope_version,
        'projection_generation',v_generation,'comparison_manifest_hash',encode(v_publication.comparison_manifest_hash,'hex'),
        'issue_set_hash',encode(v_publication.issue_set_hash,'hex'),'rows_checked',v_rows_checked,
        'current_final_revisions',(select coalesce(jsonb_agg(jsonb_build_object('id',f.id,
          'manifest_hash',encode(f.manifest_hash,'hex'),'policy_fingerprint',encode(f.policy_fingerprint,'hex'))
          order by f.id),'[]'::jsonb) from public.weekly_source_final_revisions f where f.upload_id=v_upload.id and f.state='CURRENT')));
    end loop;

    if v_source#>'{source_proposal,source_present}' is distinct from 'false'::jsonb
       or v_source#>>'{source_proposal,source_minutes}' is distinct from '0' then return null; end if;
    if v_mode='NHSP_WEEKLY' and v_source->'source_observed'='true'::jsonb then
      -- The active-position owner has already proved this event extinguished.
      -- Keep the REAL physical positive/negative history, not its synthetic
      -- selected-event absence proposal encoding, as the certificate basis.
      select coalesce(jsonb_agg(jsonb_build_object('movement_id',m.id,'final_revision_id',f.id,
          'movement_hash',encode(m.movement_economic_hash,'hex'),'source_row_id',u.id,
          'source_row_hash',encode(u.normalised_row_hash,'hex'),'row_resolution_id',r.id,
          'backing_report_id',br.id,'row_manifest_hash',encode(br.row_manifest_hash,'hex'),
          'final_manifest_hash',encode(f.manifest_hash,'hex'),'client_manifest_id',cm.id,
          'client_manifest_hash',encode(cm.manifest_hash,'hex'),'manifest_movement_hash',encode(mm.movement_hash,'hex'))
          order by f.finalised_at_utc,m.id),'[]'::jsonb),
        bool_or(m.source_line_kind='NHSP_PHYSICAL_POSITIVE'),bool_or(m.source_line_kind='NHSP_PHYSICAL_FULL_NEGATIVE')
        into v_history,v_has_positive,v_has_negative
        from public.weekly_source_billing_movements m
        join public.weekly_source_final_revisions f on f.id=m.final_revision_id and f.state='CURRENT'
        join public.weekly_source_cycles c on c.id=f.source_cycle_id and c.source_group_id=v_cycle.source_group_id
        join public.weekly_source_report_scopes rs on rs.id=f.report_scope_id and rs.current_final_revision_id=f.id
          and rs.client_id=v_contract.client_id and rs.cutoff_at_utc=c.cutoff_at_utc
        join public.weekly_source_upload_rows u on u.id=m.nhsp_upload_row_id and u.upload_id=f.upload_id and u.work_date=v_event.work_date
        join public.weekly_source_row_resolutions r on r.id=(m.source_facts_json->>'row_resolution_id')::uuid
          and r.upload_row_id=u.id and r.mapping_state='RESOLVED' and r.work_event_id=v_event.id
          and r.candidate_id=v_family.candidate_id and r.client_id=v_contract.client_id and r.contract_id=v_contract.id
        join public.weekly_source_uploads up on up.id=f.upload_id and up.report_scope_id=rs.id and up.source_cycle_id=c.id
        join public.weekly_source_nhsp_backing_reports br on br.final_revision_id=f.id and br.upload_id=up.id
          and br.client_id=v_contract.client_id and br.report_scope_id=rs.id and br.cutoff_at_utc=rs.cutoff_at_utc
          and br.row_manifest_hash=up.row_manifest_hash
        join public.weekly_source_client_manifests cm on coalesce(cm.invoice_window_cycle_id,cm.source_cycle_id)=cm.source_cycle_id and cm.final_revision_id=f.id and cm.client_id=v_contract.client_id
          and cm.source_cycle_id=c.id and cm.source_group_id=c.source_group_id
        join public.weekly_source_manifest_movements mm on mm.client_manifest_id=cm.id
          and mm.billing_movement_id=m.id and mm.movement_hash=m.movement_economic_hash
        where m.source_profile_kind<>'SELF_BILL_REPORT' and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and m.invoice_timesheet_id=any(v_root_ids) and m.work_event_id=v_event.id
          and m.candidate_id=v_family.candidate_id and m.contract_id=v_contract.id and m.actual_client_id=v_contract.client_id
          and m.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
          and m.source_line_kind in ('NHSP_PHYSICAL_POSITIVE','NHSP_PHYSICAL_FULL_NEGATIVE');
      if v_has_positive is distinct from true or v_has_negative is distinct from true then return null; end if;
      if exists(select 1 from public.weekly_source_billing_movements m
        where m.source_profile_kind<>'SELF_BILL_REPORT' and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and m.invoice_timesheet_id=any(v_root_ids) and m.work_event_id=v_event.id
          and m.source_profile_kind='NHSP_TRUST_BACKING_REPORT'
          and exists(select 1 from public.weekly_source_final_revisions f where f.id=m.final_revision_id and f.state='CURRENT')
          and not exists(select 1 from jsonb_array_elements(v_history) h where h->>'movement_id'=m.id::text)) then return null; end if;
      v_kind:='CERTIFIED_ABSENCE'; v_basis_kind:='NHSP_FULL_REVERSAL'; v_basis:=jsonb_build_object('physical_history',v_history);
    elsif v_mode='HEALTHROSTER_WEEKLY' then
      if v_source->'source_observed'='true'::jsonb then
        select * into v_transition from public.weekly_source_state_transitions t where t.id=(v_selected->>'client_source_id')::uuid
          and t.work_event_id=v_event.id and t.outcome='CANCEL' and t.previous_present and not t.new_present
          and t.previous_snapshot_line_id is not null and t.new_snapshot_line_id is null;
        if not found then return null; end if;
        select * into strict v_snapshot from public.weekly_source_final_snapshot_lines where id=v_transition.previous_snapshot_line_id;
        if v_snapshot.work_event_id is distinct from v_event.id or v_snapshot.candidate_id is distinct from v_family.candidate_id
           or v_snapshot.client_id is distinct from v_contract.client_id or v_snapshot.contract_id is distinct from v_contract.id
           or v_snapshot.work_date is distinct from v_event.work_date then return null; end if;
        if not exists(select 1 from public.weekly_source_upload_rows raw
          join public.weekly_source_row_resolutions resolution on resolution.id=v_snapshot.row_resolution_id
            and resolution.upload_row_id=raw.id and resolution.mapping_state='RESOLVED'
          join public.weekly_source_final_revisions previous_final on previous_final.id=v_snapshot.final_revision_id
            and previous_final.upload_id=raw.upload_id
          join public.weekly_source_cycles previous_cycle on previous_cycle.id=previous_final.source_cycle_id
            and previous_cycle.source_group_id=v_cycle.source_group_id
          where raw.id=v_snapshot.upload_row_id and raw.work_date=v_event.work_date
            and resolution.work_event_id=v_event.id and resolution.candidate_id=v_family.candidate_id
            and resolution.client_id=v_contract.client_id and resolution.contract_id=v_contract.id)
        then return null; end if;
        select * into v_final from public.weekly_source_final_revisions where id=v_transition.final_revision_id;
        if not found or v_transition.finalisation_cycle_id is distinct from v_final.source_cycle_id then return null; end if;
        v_basis_kind:='ROSTER_CANCEL';
      else
        select count(*),jsonb_agg(to_jsonb(f))->0 into v_count,v_basis
          from public.weekly_source_final_revisions f join public.weekly_source_cycles c on c.id=f.source_cycle_id
          join public.weekly_source_client_manifests m on coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=f.id and m.client_id=v_contract.client_id
          where c.source_group_id=v_cycle.source_group_id and f.state='CURRENT' and c.current_final_revision_id=f.id
            and f.authority_scope_kind='CYCLE' and v_event.work_date between f.coverage_start_local_date and f.coverage_end_local_date;
        if v_count>1 then return null; end if;
        if v_count=1 then
          select * into strict v_final from public.weekly_source_final_revisions where id=(v_basis->>'id')::uuid;
          v_basis_kind:='ROSTER_COVERAGE_OMISSION';
        end if;
      end if;
      if v_final.id is not null then
      select * into strict v_upload from public.weekly_source_uploads where id=v_final.upload_id;
      if v_final.state<>'CURRENT' or v_final.authority_scope_kind<>'CYCLE' or v_final.finalised_at_utc is null
         or not isfinite(v_final.finalised_at_utc) or v_final.coverage_timezone is distinct from 'Europe/London'
         or v_upload.coverage_timezone is distinct from 'Europe/London' or v_upload.coverage_state is distinct from 'COMPLETE'
         or v_upload.coverage_confirmed_at_utc is null or v_upload.coverage_confirmed_by_user_id is null
         or v_upload.confirmed_coverage_start_local_date is distinct from v_final.coverage_start_local_date
         or v_upload.confirmed_coverage_end_local_date is distinct from v_final.coverage_end_local_date
         or v_event.work_date not between v_final.coverage_start_local_date and v_final.coverage_end_local_date
         or not exists(select 1 from public.weekly_source_cycles c where c.id=v_final.source_cycle_id
           and c.source_group_id=v_cycle.source_group_id and c.current_final_revision_id=v_final.id)
         or not exists(select 1 from public.weekly_source_format_profiles p where p.id=v_upload.source_format_profile_id
           and p.final_authority_kind in ('GENERIC_COMPLETE_SNAPSHOT','HEALTHROSTER_ACTUAL_ROWS')
           and p.omission_meaning='CANCEL_INSIDE_CONFIRMED_COVERAGE')
         or not exists(select 1 from public.weekly_source_client_manifests m where coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=v_final.id
           and m.source_cycle_id=v_final.source_cycle_id and m.source_group_id=v_cycle.source_group_id and m.client_id=v_contract.client_id)
      then return null; end if;
      v_kind:='CERTIFIED_ABSENCE'; v_basis:=jsonb_build_object('final_revision_id',v_final.id,
        'manifest_hash',encode(v_final.manifest_hash,'hex'),'policy_fingerprint',encode(v_final.policy_fingerprint,'hex'),
        'upload_id',v_upload.id,'row_manifest_hash',encode(v_upload.row_manifest_hash,'hex'),
        'source_cycle_id',v_final.source_cycle_id,
        'source_cycle_cutoff_at_utc',(select c.cutoff_at_utc from public.weekly_source_cycles c where c.id=v_final.source_cycle_id),
        'declared_scope_fingerprint',encode(v_upload.declared_scope_fingerprint,'hex'),
        'client_manifests',(select jsonb_agg(jsonb_build_object('id',m.id,'manifest_hash',encode(m.manifest_hash,'hex'))
          order by m.id) from public.weekly_source_client_manifests m where coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=v_final.id
            and m.source_cycle_id=v_final.source_cycle_id and m.source_group_id=v_cycle.source_group_id and m.client_id=v_contract.client_id),
        'coverage_start',v_final.coverage_start_local_date,'coverage_end',v_final.coverage_end_local_date,
        'transition_id',v_transition.id,'transition_fingerprint',encode(v_transition.transition_fingerprint,'hex'),
        'previous_snapshot_id',v_snapshot.id,'previous_snapshot_hash',encode(v_snapshot.snapshot_line_hash,'hex'),
        'previous_upload_row_id',v_snapshot.upload_row_id,'previous_row_resolution_id',v_snapshot.row_resolution_id);
      end if;
    end if;
    if v_kind is null then
      if v_event.identity_kind<>'OFFICE_PROTECTED_SHIFT'
         or v_source->'source_observed' is distinct from 'false'::jsonb
         or exists(select 1 from public.weekly_source_row_resolutions r where r.work_event_id=v_event.id)
         or exists(select 1 from public.weekly_work_event_source_links l where l.work_event_id=v_event.id)
         or exists(select 1 from public.weekly_source_final_snapshot_lines s where s.work_event_id=v_event.id)
         or exists(select 1 from public.weekly_source_billing_movements m where m.source_profile_kind<>'SELF_BILL_REPORT' and m.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and m.work_event_id=v_event.id)
      then return null; end if;
      v_kind:='CERTIFIED_ABSENCE'; v_basis_kind:='NO_IMPORT_YET';
      v_basis:=jsonb_build_object('work_event_id',v_event.id,'durable_identity_hash',encode(v_event.durable_identity_hash,'hex'),
        'first_source_group_id',v_event.first_source_group_id,'family_event_id',v_protected.id,
        'family_event_sequence',v_protected.event_sequence,'action_cycle_id',v_cycle.id,
        'action_cycle_version',v_cycle.version,'action_cycle_projection_state',v_cycle.projection_state);
    end if;
    v_basis:=v_basis||jsonb_build_object('checked_current_imports',v_census);
  end if;
  v_result:=jsonb_build_object('schema_version','WEEKLY_SOURCE_SELECTED_SOURCE_WITNESS_V1',
    'scope',v_scope||jsonb_build_object('work_event_id',v_event.id,'work_date',v_event.work_date,
      'source_group_id',v_cycle.source_group_id,'action_cycle_id',v_cycle.id),
    'kind',v_kind,'basis_kind',v_basis_kind,'source_proposal',v_source->'source_proposal','basis',v_basis);
  return v_result||jsonb_build_object('basis_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_SELECTED_SOURCE_WITNESS_V1',v_result),'hex'));
end;
$function$;

create or replace function private.weekly_source_protected_final_source_context_v1(
  p_family_id uuid,p_cycle_id uuid,p_event_id uuid
) returns jsonb language plpgsql stable security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_family public.weekly_exceptional_pay_target_families%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_contract public.contracts%rowtype;
  v_event public.weekly_work_events%rowtype;
  v_event_id uuid:=p_event_id;
  v_root_family uuid[];
  v_source_mode text;
  v_source_segments jsonb:='[]'::jsonb;
  v_client_sources jsonb:='[]'::jsonb;
  v_current_final uuid;
  v_selected_source_present boolean:=false;
  v_selected_source_minutes integer:=0;
  v_selected_source_revision text;
  v_selected_source_hash text;
  v_source_head_revision uuid;
  v_source_head_count integer:=0;
  v_ambiguous_event_count integer:=0;
  v_source_observed boolean:=false;
  v_next_source_segments jsonb:='[]'::jsonb;
  v_retain_next_facts boolean:=false;
begin
  select family.* into strict v_family
    from public.weekly_exceptional_pay_target_families family where family.id=p_family_id;
  select cycle.* into strict v_cycle from public.weekly_source_cycles cycle where cycle.id=p_cycle_id;
  select source_group.* into strict v_group from public.weekly_source_groups source_group
    where source_group.id=v_cycle.source_group_id;
  select contract.* into strict v_contract from public.contracts contract where contract.id=v_family.contract_id;
  select event.* into strict v_event from public.weekly_work_events event where event.id=p_event_id
    and event.candidate_id=v_family.candidate_id and event.client_id=v_contract.client_id
    and event.first_source_group_id=v_group.id
    and event.work_date between v_family.week_start_date and v_family.week_ending_date;
  if v_family.agency_id is distinct from v_group.agency_id then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
  end if;
  v_source_mode:=private._weekly_source_effective_policy_v1(
    v_contract.client_id,v_contract.id,v_event.work_date)->>'c1_source_mode';
  if v_source_mode not in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY') or v_source_mode is null then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_SCOPE_INVALID' using errcode='55000';
  end if;
  v_retain_next_facts:=(select active_owner from private.bpay_next_module_control where id=1)='NEXT'
    and private.bpay_next_protected_owner_route_v1(v_family.id)='NEXT';
  if v_retain_next_facts then
    -- Actual exact current root/contract-week binding, not version discovery.
    perform 1 from public.timesheets root join public.contract_weeks cw on cw.timesheet_id=root.timesheet_id
      where root.timesheet_id=v_family.root_timesheet_id and root.booking_id=v_family.root_family_booking_id
        and root.is_current and not root.is_adjustment and root.revoked_at is null and root.archived_at_utc is null
        and root.contract_id=v_family.contract_id and root.week_ending_date=v_family.week_ending_date
        and cw.contract_id=v_family.contract_id and cw.week_ending_date=v_family.week_ending_date and cw.additional_seq=0;
    if not found then raise exception 'WEEKLY_PROTECTED_NEXT_CURRENT_ROOT_NOT_EXACT' using errcode='55000';end if;
    v_root_family:=array[v_family.root_timesheet_id];
  else
    v_root_family:=private.weekly_source_invoice_family_timesheet_ids_v1(v_family.root_timesheet_id);
  end if;
  if v_root_family is null or cardinality(v_root_family)=0 then
    raise exception 'WEEKLY_PROTECTED_ACTION_CONTEXT_FAMILY_UNRESOLVED' using errcode='55000';
  end if;
  if v_source_mode='HEALTHROSTER_WEEKLY' then
    with ranked as (
      select transition.*,source_cycle.finalisation_week_ending,
        revision.finalised_at_utc,revision.revision_number,
        coalesce(current_line.contract_id,prior_line.contract_id) as resolved_contract_id,
        coalesce(current_line.candidate_id,prior_line.candidate_id) as resolved_candidate_id,
        coalesce(current_line.work_date,prior_line.work_date) as resolved_work_date,
        pg_catalog.row_number() over (
          partition by transition.work_event_id
          order by source_cycle.finalisation_week_ending desc,
                   revision.finalised_at_utc desc,revision.revision_number desc,
                   transition.created_at_utc desc,transition.id desc
        ) as event_rank
      from public.weekly_source_state_transitions transition
      join public.weekly_source_final_revisions revision
        on revision.id=transition.final_revision_id and revision.state='CURRENT'
      join public.weekly_source_cycles source_cycle on source_cycle.id=revision.source_cycle_id
      left join public.weekly_source_final_snapshot_lines current_line
        on current_line.id=transition.new_snapshot_line_id
      left join public.weekly_source_final_snapshot_lines prior_line
        on prior_line.id=transition.previous_snapshot_line_id
      where transition.source_profile_kind in ('GENERIC_COMPLETE_SNAPSHOT','HEALTHROSTER_ACTUAL_ROWS')
        and source_cycle.source_group_id=v_group.id
    ), current_state as (
      select ranked.*,snapshot.start_at_local,snapshot.end_at_local,
             snapshot.break_minutes,snapshot.actual_net_minutes,
             snapshot.snapshot_line_hash
      from ranked
      left join public.weekly_source_final_snapshot_lines snapshot
        on snapshot.id=ranked.new_snapshot_line_id
      where ranked.event_rank=1
        and ranked.resolved_contract_id=v_family.contract_id
        and ranked.resolved_candidate_id=v_family.candidate_id
        and ranked.resolved_work_date between v_family.week_start_date and v_family.week_ending_date
    )
    select
      coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'work_event_id',state.work_event_id,'date',state.resolved_work_date,
        'start',pg_catalog.to_char(state.start_at_local,'HH24:MI'),
        'end',pg_catalog.to_char(state.end_at_local,'HH24:MI'),
        'break_mins',state.break_minutes
      ) order by state.resolved_work_date,state.start_at_local,state.work_event_id)
        filter (where state.new_present),'[]'::jsonb),
      coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'source_system','CLOUDTMS_WEEKLY_FINAL_SOURCE',
        'external_identity',state.work_event_id::text,
        'external_revision',state.final_revision_id::text,
        'document_sha256',pg_catalog.encode(coalesce(
          state.snapshot_line_hash,state.transition_fingerprint
        ),'hex'),
        'work_date',state.resolved_work_date,'client_source_id',state.id,
        'source_complete',true,'source_present',state.new_present,
        'approved_minutes',case when state.new_present then state.actual_net_minutes else 0 end
      ) order by state.resolved_work_date,state.work_event_id),'[]'::jsonb),
      (pg_catalog.array_agg(state.final_revision_id order by
        state.finalisation_week_ending desc,state.finalised_at_utc desc,
        state.revision_number desc,state.id desc)
        filter (where state.work_event_id=v_event_id))[1],
      coalesce(bool_or(state.work_event_id=v_event_id and state.new_present),false),
      coalesce(max(state.actual_net_minutes) filter (where state.work_event_id=v_event_id and state.new_present),0),
      (pg_catalog.array_agg(state.final_revision_id::text order by
        state.finalisation_week_ending desc,state.finalised_at_utc desc,
        state.revision_number desc,state.id desc)
        filter (where state.work_event_id=v_event_id))[1],
      max(pg_catalog.encode(coalesce(state.snapshot_line_hash,state.transition_fingerprint),'hex'))
        filter (where state.work_event_id=v_event_id)
    into v_source_segments,v_client_sources,v_current_final,
         v_selected_source_present,v_selected_source_minutes,
         v_selected_source_revision,v_selected_source_hash
    from current_state state;
  else
    -- WP-57 (WP-52 handoff N1).  WHICH SOURCE POSITION IS LIVE ON AN NHSP WORK
    -- EVENT IS DECIDED BY FACTS, NEVER BY WHICH PHYSICAL ROW THE TRUST LISTED
    -- FIRST.  The single owner of that decision is
    -- private.weekly_source_ordinary_projection_active_movements_v1, installed
    -- by WP-52 in
    -- supabase/repeatable/15092026_1534_weekly_source_ordinary_pay_projection_v1.sql:3413.
    -- This surface READS it and keeps no second copy of the rule, so the
    -- proposal Office is shown and the pay the Candidate receives cannot drift
    -- apart.  APPLY-ORDER DEPENDENCY: that repeatable must be installed before
    -- this one.  It is, under the release runner's DDMMYYYY -> YYYYMMDD re-key
    -- followed by filename order (`…_ordinary_pay_projection_v1` sorts before
    -- `…_protected_action_orchestration_v1`), and plpgsql resolves the call at
    -- run time in any case.
    --
    -- WHAT WAS HERE AND WHY IT WAS WRONG.  A
    -- `row_number() over (partition by movement.work_event_id
    --   order by …, movement.created_at_utc desc, movement.id desc)`
    -- kept rank 1 per work event and read `source_present` and
    -- `approved_minutes` off it.  Since WP-37 an NHSP reversal and its re-issue
    -- resolve to ONE work event, so inside one report that ranking fell through
    -- to `created_at_utc` - which is `transaction_timestamp()` (schema
    -- 15092026_1534_weekly_source_plan6_schema.sql:1093) and therefore
    -- IDENTICAL for every movement of one finalisation - and then to
    -- `movement.id`, a random UUID.  EXECUTED on a build from empty: the same
    -- corrected shift answered `source_present=true, 540 approved minutes` on
    -- one run and `source_present=false, 0` on the next, with the Client
    -- invoiced GBP 180.00 either way; and with `source_present=false` the
    -- RECORD_NOT_WORKED guard at the foot of this owner stopped guarding, so
    -- Office could record a worked, re-issued shift as not worked.  Split
    -- across reports it was deterministically wrong: a later reversal of the
    -- ORIGINAL 8 h line wiped a re-issued 9 h shift.
    --
    -- WP-30, standing rule 3: the movements are read over the whole Timesheet
    -- FAMILY (`v_root_family`), never the physical root id alone.
    --
    -- The revision-ladder head is stated as a fact - "no CURRENT peer carrying
    -- this family's movements stands later" - not as `order by … limit 1`, and
    -- an ambiguous head fails CLOSED.
    with ladder as (
      select revision.id,source_cycle.finalisation_week_ending,
             revision.finalised_at_utc,revision.revision_number
      from public.weekly_source_final_revisions revision
      join public.weekly_source_cycles source_cycle
        on source_cycle.id=revision.source_cycle_id
      where revision.state='CURRENT'
        and exists(
          select 1
          from public.weekly_source_billing_movements movement
          where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=revision.id
            and ((not v_retain_next_facts and movement.invoice_timesheet_id=any(v_root_family))
            or (v_retain_next_facts and exists(
              select 1 from public.weekly_source_row_timesheet_lineages lineage
              where lineage.row_resolution_id=case when coalesce(movement.source_facts_json->>'row_resolution_id','')
                ~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
                then (movement.source_facts_json->>'row_resolution_id')::uuid else null end
                and lineage.family_booking_id=v_family.root_family_booking_id
                and lineage.work_event_id=movement.work_event_id and lineage.candidate_id=v_family.candidate_id
                and lineage.client_id=v_contract.client_id and lineage.contract_id=v_family.contract_id
                and lineage.week_ending_date=v_family.week_ending_date)))
            and movement.source_line_kind in (
              'NHSP_PHYSICAL_POSITIVE','NHSP_PHYSICAL_FULL_NEGATIVE')
            and movement.candidate_id=v_family.candidate_id
            and movement.contract_id=v_family.contract_id
            and movement.actual_client_id=v_contract.client_id
        )
    )
    -- The UUID representative is taken as `min(...::text)::uuid` per AGENTS.md
    -- (PostgreSQL has no `min(uuid)`), and only after the exact cardinality
    -- proof on the next line.
    select pg_catalog.count(*)::integer,pg_catalog.min(head.id::text)::uuid
      into v_source_head_count,v_source_head_revision
    from ladder head
    where not exists(
      select 1 from ladder peer
      where (peer.finalisation_week_ending,peer.finalised_at_utc,peer.revision_number)
            >(head.finalisation_week_ending,head.finalised_at_utc,head.revision_number)
    );
    if v_source_head_count>1 then
      raise exception 'WEEKLY_PROTECTED_AMBIGUOUS_SOURCE_LADDER_HEAD'
        using errcode='55000',
        detail=pg_catalog.jsonb_build_object(
          'family_id',v_family.id,'work_event_id',v_event_id,
          'current_ladder_head_count',v_source_head_count)::text;
    end if;

    if v_source_head_revision is not null then
      with scope as (
        -- Which work events this family week has ANY NHSP source row for,
        -- positive or negative.  This is a scope question, not a money
        -- question: it fixes the rows that appear in the evidence, and it
        -- carries no ranking.
        select distinct movement.work_event_id,
               (movement.source_facts_json->>'work_date')::date as work_date
        from public.weekly_source_billing_movements movement
        join public.weekly_source_final_revisions revision
          on revision.id=movement.final_revision_id and revision.state='CURRENT'
        where ((not v_retain_next_facts and movement.invoice_timesheet_id=any(v_root_family))
            or (v_retain_next_facts and exists(
              select 1 from public.weekly_source_row_timesheet_lineages lineage
              where lineage.row_resolution_id=case when coalesce(movement.source_facts_json->>'row_resolution_id','')
                ~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
                then (movement.source_facts_json->>'row_resolution_id')::uuid else null end
                and lineage.family_booking_id=v_family.root_family_booking_id
                and lineage.work_event_id=movement.work_event_id and lineage.candidate_id=v_family.candidate_id
                and lineage.client_id=v_contract.client_id and lineage.contract_id=v_family.contract_id
                and lineage.week_ending_date=v_family.week_ending_date)))
          and movement.source_line_kind in (
            'NHSP_PHYSICAL_POSITIVE','NHSP_PHYSICAL_FULL_NEGATIVE')
          and movement.candidate_id=v_family.candidate_id
          and movement.contract_id=v_family.contract_id
          and movement.actual_client_id=v_contract.client_id
          and (movement.source_facts_json->>'work_date')::date
              between v_family.week_start_date and v_family.week_ending_date
      ), live as (
        -- The single owner's answer, over every physical member of the family.
        -- Nothing is re-filtered here that could change WHICH position is
        -- live; the predicates below are identity and week scope only.  A
        -- movement voided by Correct Final Source cannot appear: the only
        -- writer of `VOIDED_BY_CORRECT_FINAL` in the tree sets it in the same
        -- atomic block that moves its revision CURRENT -> SUPERSEDED
        -- (15092026_1534_weekly_source_correct_final_source_v1.sql:1864-1873),
        -- and the owner reads CURRENT revisions only.
        select live_movement.*
        from pg_catalog.unnest(v_root_family) as family_member(root_timesheet_id)
        cross join lateral
          private.weekly_source_ordinary_projection_active_movements_v1(
            family_member.root_timesheet_id,v_source_head_revision) live_movement
        where live_movement.source_profile_kind<>'SELF_BILL_REPORT' and live_movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and live_movement.source_line_kind in (
            'NHSP_PHYSICAL_POSITIVE','NHSP_PHYSICAL_FULL_NEGATIVE')
          and live_movement.candidate_id=v_family.candidate_id
          and live_movement.contract_id=v_family.contract_id
          and live_movement.actual_client_id=v_contract.client_id
          and (live_movement.source_facts_json->>'work_date')::date
              between v_family.week_start_date and v_family.week_ending_date
      ), row_state as (
        select scope.work_event_id,scope.work_date,
               live.id as movement_id,live.final_revision_id,
               live.movement_economic_hash,live.source_facts_json,
               (live.id is not null) as source_present,
               pg_catalog.count(live.id) over (
                 partition by scope.work_event_id) as live_count
        from scope
        left join live on live.work_event_id=scope.work_event_id
      )
      -- Every `order by` below is inside a `jsonb_agg` and fixes DISPLAY order
      -- only; no money value is selected by one.  The `max(...) filter (...)`
      -- expressions run over a group whose cardinality is one, proved by
      -- `v_ambiguous_event_count` immediately after this statement: when two
      -- contradictory live positions survive on one work event this owner
      -- REFUSES, and none of these values reaches the caller.
      select
        coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'work_event_id',row_state.work_event_id,'date',row_state.work_date,
          'start',pg_catalog.to_char(
            (row_state.source_facts_json->>'start_at_local')::timestamp,'HH24:MI'),
          'end',pg_catalog.to_char(
            (row_state.source_facts_json->>'end_at_local')::timestamp,'HH24:MI'),
          'break_mins',(row_state.source_facts_json->>'break_minutes')::integer
        ) order by row_state.work_date,row_state.work_event_id)
          filter (where row_state.source_present),'[]'::jsonb),
        coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'source_system','NHSP_BACKING_REPORT',
          'external_identity',row_state.work_event_id::text,
          'external_revision',coalesce(
            row_state.final_revision_id::text,v_cycle.id::text),
          'document_sha256',case when row_state.source_present
            then pg_catalog.encode(row_state.movement_economic_hash,'hex')
            -- A work event the Trust has fully reversed has no live position.
            -- Its evidence is the same server-derived absence statement this
            -- owner already builds for a work event the source never mentioned
            -- (below), so nothing has to choose between several negatives.
            else pg_catalog.encode(private.weekly_source_sha256_jsonb_v1(
              'WEEKLY_PROTECTED_SOURCE_ABSENCE_V1',
              pg_catalog.jsonb_build_object(
                'family_id',v_family.id,'source_cycle_id',v_cycle.id,
                'work_event_id',row_state.work_event_id,
                'source_mode',v_source_mode,'source_present',false
              )),'hex') end,
          'work_date',row_state.work_date,
          'client_source_id',coalesce(row_state.movement_id,row_state.work_event_id),
          'source_complete',true,'source_present',row_state.source_present,
          'approved_minutes',case when row_state.source_present
            then (row_state.source_facts_json->>'actual_net_minutes')::integer
            else 0 end
        ) order by row_state.work_date,row_state.work_event_id),'[]'::jsonb),
        (pg_catalog.max(row_state.final_revision_id::text)
          filter (where row_state.work_event_id=v_event_id
            and row_state.source_present))::uuid,
        coalesce(pg_catalog.bool_or(row_state.work_event_id=v_event_id
          and row_state.source_present),false),
        coalesce(pg_catalog.max(
          (row_state.source_facts_json->>'actual_net_minutes')::integer)
          filter (where row_state.work_event_id=v_event_id
            and row_state.source_present),0),
        pg_catalog.max(row_state.final_revision_id::text)
          filter (where row_state.work_event_id=v_event_id
            and row_state.source_present),
        pg_catalog.max(pg_catalog.encode(row_state.movement_economic_hash,'hex'))
          filter (where row_state.work_event_id=v_event_id
            and row_state.source_present),
        coalesce(pg_catalog.count(distinct row_state.work_event_id)
          filter (where row_state.live_count>1),0)::integer
      into v_source_segments,v_client_sources,v_current_final,
           v_selected_source_present,v_selected_source_minutes,
           v_selected_source_revision,v_selected_source_hash,
           v_ambiguous_event_count
      from row_state;
      if v_ambiguous_event_count>0 then
        -- 14 s4.2.8.  Two live positions of different economics on one shift
        -- are two contradictory statements about it.  Standing rule 5: an
        -- explicit cardinality check, and the unexpected case goes to the
        -- fail-closed branch with a stated reason - never to whichever row the
        -- Trust listed last.
        raise exception 'WEEKLY_PROTECTED_AMBIGUOUS_SOURCE_HEAD'
          using errcode='55000',
          detail=pg_catalog.jsonb_build_object(
            'family_id',v_family.id,'work_event_id',v_event_id,
            'ambiguous_work_event_count',v_ambiguous_event_count)::text;
      end if;
    end if;
  end if;

  v_source_observed:=exists(
    select 1 from pg_catalog.jsonb_array_elements(v_client_sources) source_row(value)
    where source_row.value->>'external_identity'=v_event.id::text
  );
  -- A fully reversed NHSP shift is an observed zero, not a missing proposal.
  -- Reuse its already-built canonical absence evidence; never select a negative
  -- movement by row order or change the zero-hour financial position.
  if v_source_observed and not v_selected_source_present then
    select source_row.value->>'external_revision',source_row.value->>'document_sha256'
      into strict v_selected_source_revision,v_selected_source_hash
    from pg_catalog.jsonb_array_elements(v_client_sources) source_row(value)
    where source_row.value->>'external_identity'=v_event.id::text;
  end if;
  if not exists(
    select 1 from pg_catalog.jsonb_array_elements(v_client_sources) source_row(value)
    where source_row.value->>'external_identity'=v_event.id::text
  ) then
    v_selected_source_hash:=pg_catalog.encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_PROTECTED_SOURCE_ABSENCE_V1',
      pg_catalog.jsonb_build_object(
        'family_id',v_family.id,'source_cycle_id',v_cycle.id,
        'work_event_id',v_event.id,'source_mode',v_source_mode,'source_present',false
      )
    ),'hex');
    v_selected_source_revision:=v_cycle.id::text;
    v_client_sources:=v_client_sources||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'source_system',case when v_source_mode='NHSP_WEEKLY'
          then 'NHSP_BACKING_REPORT' else 'CLOUDTMS_WEEKLY_FINAL_SOURCE' end,
        'external_identity',v_event.id::text,'external_revision',v_selected_source_revision,
        'document_sha256',v_selected_source_hash,'work_date',v_event.work_date,
        'client_source_id',v_event.id,'source_complete',true,
        'source_present',false,'approved_minutes',0
      )
    );
  end if;

  -- A selected source observation may legitimately come from an older cycle.
  -- The approval audit pointer is populated only when that CURRENT revision
  -- belongs to this action's cycle; stage validation must never be handed a
  -- cross-cycle revision identifier.
  if v_current_final is not null and not exists(
    select 1 from public.weekly_source_final_revisions revision
    where revision.id=v_current_final
      and revision.source_cycle_id=v_cycle.id
      and revision.state='CURRENT'
  ) then
    v_current_final:=null;
  end if;


  -- NEXT retains the genuine selected Source economics, not the contract-rate
  -- protected preview. The existing projection owner remains the sole chooser
  -- of active movements. A missing final approval legitimately has no Source
  -- vectors; present Source without exact immutable vectors fails closed.
  if v_retain_next_facts then
    if v_source_head_revision is null and pg_catalog.jsonb_array_length(v_source_segments)>0 then
      with selected as (
        select distinct revision.id,cycle.finalisation_week_ending,
               revision.finalised_at_utc,revision.revision_number
        from pg_catalog.jsonb_array_elements(v_client_sources) s(value)
        join public.weekly_source_final_revisions revision
          on revision.id=(s.value->>'external_revision')::uuid and revision.state='CURRENT'
        join public.weekly_source_cycles cycle on cycle.id=revision.source_cycle_id
        where (s.value->>'source_present')::boolean and cycle.source_group_id=v_group.id
      )
      select pg_catalog.count(*)::integer,pg_catalog.min(head.id::text)::uuid
        into v_source_head_count,v_source_head_revision
      from selected head where not exists(select 1 from selected peer
        where (peer.finalisation_week_ending,peer.finalised_at_utc,peer.revision_number)
          >(head.finalisation_week_ending,head.finalised_at_utc,head.revision_number));
      if v_source_head_count<>1 then
        raise exception 'WEEKLY_PROTECTED_NEXT_SOURCE_LADDER_NOT_EXACT' using errcode='55000';
      end if;
    end if;
    if v_source_head_revision is not null then
      v_next_source_segments:=private.weekly_source_ordinary_projection_current_segments_v1(
        v_family.root_timesheet_id,v_source_head_revision);
    end if;
    if pg_catalog.jsonb_array_length(v_next_source_segments)<>pg_catalog.jsonb_array_length(v_source_segments)
       or exists(select 1 from pg_catalog.jsonb_array_elements(v_source_segments) s(value)
         where (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_next_source_segments) n(value)
           where n.value#>>'{weekly_source,work_event_id}'=s.value->>'work_event_id'
             and n.value->>'date'=s.value->>'date' and n.value->>'start'=s.value->>'start'
             and n.value->>'end'=s.value->>'end'
             and n.value->>'break_mins'=s.value->>'break_mins')<>1) then
      raise exception 'WEEKLY_PROTECTED_NEXT_SOURCE_VECTOR_NOT_EXACT' using errcode='55000';
    end if;
    -- Numeric evidence leaves PostgreSQL as text; no JS Number round-trip.
    select coalesce(pg_catalog.jsonb_agg(n.value||pg_catalog.jsonb_build_object(
      'weekly_source',(n.value->'weekly_source')||pg_catalog.jsonb_build_object(
        'pay_vector',(n.value#>'{weekly_source,pay_vector}')||pg_catalog.jsonb_build_object(
          'total_pence',n.value#>>'{weekly_source,pay_vector,total_pence}',
          'hours',(select pg_catalog.jsonb_object_agg(k.key,k.value)
            from pg_catalog.jsonb_each_text(n.value#>'{weekly_source,pay_vector,hours}') k),
          'rates',(select pg_catalog.jsonb_object_agg(k.key,k.value)
            from pg_catalog.jsonb_each_text(n.value#>'{weekly_source,pay_vector,rates}') k)),
        'charge_vector',(n.value#>'{weekly_source,charge_vector}')||pg_catalog.jsonb_build_object(
          'total_pence',n.value#>>'{weekly_source,charge_vector,total_pence}',
          'rates',(select pg_catalog.jsonb_object_agg(k.key,k.value)
            from pg_catalog.jsonb_each_text(n.value#>'{weekly_source,charge_vector,rates}') k))
      )) order by n.ordinality),'[]'::jsonb) into v_next_source_segments
    from pg_catalog.jsonb_array_elements(v_next_source_segments) with ordinality n(value,ordinality);
    if pg_catalog.jsonb_array_length(v_next_source_segments)>100
       or pg_catalog.octet_length(v_next_source_segments::text)>120000 then
      raise exception 'WEEKLY_PROTECTED_NEXT_SOURCE_PAGE_BOUND' using errcode='54000';
    end if;
  end if;

  return jsonb_build_object('source_segments',v_source_segments,'client_sources',v_client_sources,
    'current_final_revision_id',v_current_final,'source_observed',v_source_observed,
    'source_proposal',jsonb_build_object(
      'selected_work_event_id',v_event.id,'source_present',v_selected_source_present,
      'source_minutes',v_selected_source_minutes,'source_revision',v_selected_source_revision,
      'source_hash',v_selected_source_hash,'source_segments',v_source_segments))
    ||case when v_retain_next_facts
      then pg_catalog.jsonb_build_object('next_source_segments',v_next_source_segments) else '{}'::jsonb end;
end;
$function$;

create or replace function private.weekly_source_finalisation_pay_context_v1(
  p_final_revision_id uuid,
  p_root_timesheet_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_revision public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_client_id uuid;
  v_client_count integer;
  v_profile_count integer;
  v_source_profile_kind text;
  v_source_mode text;
  v_source_units jsonb;
  v_segments jsonb;
  v_schedule jsonb;
  v_expenses jsonb;
  v_source_unit_hash bytea;
  v_source_expense_hash bytea;
  v_active_segment_hash bytea;
  v_rate_refs jsonb;
  v_context jsonb;
  v_context_hash bytea;
begin
  if p_final_revision_id is null or p_root_timesheet_id is null then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_CONTEXT_INVALID'
      using errcode='22023';
  end if;
  select * into v_revision
  from public.weekly_source_final_revisions revision
  where revision.id=p_final_revision_id;
  if not found or v_revision.state<>'CURRENT'
     or v_revision.reason<>'INITIAL_FINALISATION' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_REVISION_INVALID'
      using errcode='55000';
  end if;
  select * into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_revision.source_cycle_id;
  select * into strict v_upload
  from public.weekly_source_uploads upload where upload.id=v_revision.upload_id;
  select * into strict v_profile
  from public.weekly_source_format_profiles profile
  where profile.id=v_upload.source_format_profile_id;
  select * into strict v_group
  from public.weekly_source_groups source_group
  where source_group.id=v_cycle.source_group_id;
  if v_revision.authority_scope_kind='CYCLE' then
    if v_cycle.current_final_revision_id is distinct from v_revision.id
       or v_upload.report_scope_id is not null then
      raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_REVISION_STALE'
        using errcode='40001';
    end if;
  else
    select * into v_scope
    from public.weekly_source_report_scopes report_scope
    where report_scope.id=v_revision.report_scope_id;
    if not found or v_scope.current_final_revision_id is distinct from v_revision.id
       or v_scope.source_cycle_id is distinct from v_cycle.id
       or v_upload.report_scope_id is distinct from v_scope.id then
      raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_REVISION_STALE'
        using errcode='40001';
    end if;
  end if;

  v_source_profile_kind:=v_profile.final_authority_kind;
  v_source_mode:=case when v_source_profile_kind='NHSP_TRUST_BACKING_REPORT'
    then 'NHSP_WEEKLY' else 'HEALTHROSTER_WEEKLY' end;
  if v_source_profile_kind not in (
       'GENERIC_COMPLETE_SNAPSHOT','NHSP_TRUST_BACKING_REPORT','HEALTHROSTER_ACTUAL_ROWS'
     ) or (v_group.source_family='NHSP') is distinct from (v_source_mode='NHSP_WEEKLY') then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_PROFILE_INVALID'
      using errcode='55000';
  end if;

  select pg_catalog.count(distinct movement.actual_client_id),
         pg_catalog.count(distinct movement.source_profile_kind),
         (pg_catalog.array_agg(movement.actual_client_id order by movement.id))[1]
    into v_client_count,v_profile_count,v_client_id
  from public.weekly_source_billing_movements movement
  where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
    and movement.invoice_timesheet_id=p_root_timesheet_id;
  if v_client_count<>1 or v_profile_count<>1 or v_client_id is null
     or exists(
       select 1 from public.weekly_source_billing_movements movement
       where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
         and movement.invoice_timesheet_id=p_root_timesheet_id
         and movement.source_profile_kind is distinct from v_source_profile_kind
     ) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_ROOT_SCOPE_INVALID'
      using errcode='55000';
  end if;
  select * into v_manifest
  from public.weekly_source_client_manifests manifest where coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)=manifest.source_cycle_id and manifest.final_revision_id=v_revision.id and manifest.client_id=v_client_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_MANIFEST_MISSING'
      using errcode='55000';
  end if;
  if not exists(
    select 1 from public.timesheets timesheet_row
    where timesheet_row.timesheet_id=p_root_timesheet_id
      and timesheet_row.is_current
      and timesheet_row.sheet_scope='WEEKLY'::public.timesheet_scope_enum
      and timesheet_row.line_type='HOURS'::public.timesheet_line_type_enum
      and not timesheet_row.is_adjustment
      and timesheet_row.revoked_at is null
      and timesheet_row.archived_at_utc is null
  ) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_ROOT_INVALID'
      using errcode='55000';
  end if;

  v_source_units:=private.weekly_source_ordinary_projection_source_units_v1(
    v_revision.id,p_root_timesheet_id
  );
  v_segments:=private.weekly_source_ordinary_projection_current_segments_v1(
    p_root_timesheet_id,v_revision.id
  );
  v_schedule:=private.weekly_source_ordinary_projection_actual_schedule_v1(v_segments);
  v_expenses:=private.weekly_source_ordinary_projection_current_expenses_v1(
    p_root_timesheet_id,v_revision.id
  );
  v_source_unit_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_UNIT_MANIFEST_V1',v_source_units
  );
  v_source_expense_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_SOURCE_EXPENSE_MANIFEST_V1',v_expenses
  );
  v_active_segment_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_ORDINARY_ACTIVE_SEGMENTS_V1',v_segments
  );
  v_rate_refs:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_FINAL_AUTHORITY_RATE_SOURCE_V1',
    'source_mode',v_source_mode,'root_timesheet_id',p_root_timesheet_id,
    'final_revision_id',v_revision.id,
    'final_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex'),
    'final_policy_fingerprint',pg_catalog.encode(v_revision.policy_fingerprint,'hex'),
    'client_manifest_hash',pg_catalog.encode(v_manifest.manifest_hash,'hex'),
    'source_unit_manifest_hash',pg_catalog.encode(v_source_unit_hash,'hex'),
    'source_expense_manifest_hash',pg_catalog.encode(v_source_expense_hash,'hex'),
    'active_segment_manifest_hash',pg_catalog.encode(v_active_segment_hash,'hex')
  );
  v_context:=pg_catalog.jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_FINALISATION_PAY_ROOT_CONTEXT_V1',
    'final_revision_id',v_revision.id,
    'source_cycle_id',v_cycle.id,
    'client_manifest_id',v_manifest.id,
    'client_id',v_client_id,
    'root_timesheet_id',p_root_timesheet_id,
    'source_profile_kind',v_source_profile_kind,
    'source_mode',v_source_mode,
    'expected_segments',v_segments,
    'expected_actual_schedule',v_schedule,
    'expected_source_expenses',v_expenses,
    'expected_rate_source_refs',v_rate_refs
  );
  v_context_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_FINALISATION_PAY_ROOT_CONTEXT_V1',v_context
  );
  return v_context||pg_catalog.jsonb_build_object(
    'prepared_context_hash',pg_catalog.encode(v_context_hash,'hex')
  );
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_CONTEXT_SCOPE_INVALID'
      using errcode='55000';
end;
$function$;

create or replace function public.weekly_source_finalisation_pay_open_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array['actor_user_id','final_revision_id','schema_version'];
  v_actual_keys text[];
  v_actor uuid;
  v_revision_id uuid;
  v_revision public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_run public.weekly_source_finalisation_pay_runs%rowtype;
  v_contexts jsonb;
  v_task_manifest_hash bytea;
  v_run_hash bytea;
  v_task_count integer;
  v_context record;
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_OPEN_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_FINALISATION_PAY_OPEN_V1' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_OPEN_CONTRACT_INVALID'
      using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_revision_id:=(p_request->>'final_revision_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_OPEN_INVALID' using errcode='22023';
  end;
  perform 1 from public.tms_users actor
  where actor.id=v_actor and coalesce(actor.is_active,false);
  if v_actor is null or v_revision_id is null or not found then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_ACTOR_INVALID' using errcode='42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_FINALISATION_PAY_RUN|'||v_revision_id::text,0
  ));
  select * into v_revision
  from public.weekly_source_final_revisions revision
  where revision.id=v_revision_id for share;
  if not found or v_revision.state<>'CURRENT'
     or v_revision.reason<>'INITIAL_FINALISATION' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_REVISION_INVALID'
      using errcode='55000';
  end if;
  select * into strict v_cycle
  from public.weekly_source_cycles cycle where cycle.id=v_revision.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups source_group where source_group.id=v_cycle.source_group_id;
  for v_context in
    select distinct movement.actual_client_id as client_id
    from public.weekly_source_billing_movements movement
    where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
    order by movement.actual_client_id
  loop
    perform private.weekly_source_office_authority_v1(
      v_actor,'FINALISE_WEEK',v_group.id,v_context.client_id,
      v_cycle.finalisation_week_ending
    );
  end loop;

  select * into v_run
  from public.weekly_source_finalisation_pay_runs run_row
  where run_row.final_revision_id=v_revision.id;
  if found then
    if v_run.requested_by_user_id is distinct from v_actor
       or v_run.final_revision_manifest_hash is distinct from v_revision.manifest_hash then
      raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_RUN_IDENTITY_CHANGED'
        using errcode='40001';
    end if;
    v_run:=private.weekly_source_finalisation_pay_run_refresh_v1(v_run.id);
    return private.weekly_source_finalisation_pay_run_json_v1(v_run)
      ||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;

  select coalesce(pg_catalog.jsonb_agg(context_value order by root_timesheet_id),'[]'::jsonb)
    into v_contexts
  from (
    select roots.root_timesheet_id,
           private.weekly_source_finalisation_pay_context_v1(
             v_revision.id,roots.root_timesheet_id
           ) as context_value
    from (
      select distinct movement.invoice_timesheet_id as root_timesheet_id
      from public.weekly_source_billing_movements movement
      where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
        and movement.invoice_timesheet_id is not null
    ) roots
  ) prepared;
  v_task_count:=pg_catalog.jsonb_array_length(v_contexts);
  v_task_manifest_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_FINALISATION_PAY_TASK_MANIFEST_V1',v_contexts
  );
  v_run_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_FINALISATION_PAY_RUN_V1',
    pg_catalog.jsonb_build_object(
      'final_revision_id',v_revision.id,
      'source_cycle_id',v_cycle.id,
      'requested_by_user_id',v_actor,
      'final_revision_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex'),
      'task_manifest_hash',pg_catalog.encode(v_task_manifest_hash,'hex'),
      'task_count',v_task_count
    )
  );
  insert into public.weekly_source_finalisation_pay_runs(
    final_revision_id,source_cycle_id,requested_by_user_id,orchestration_key,
    final_revision_manifest_hash,task_manifest_hash,task_count,
    terminal_task_count,action_required_task_count,state,run_hash,completed_at_utc
  ) values (
    v_revision.id,v_cycle.id,v_actor,'weekly-source-finalisation-pay:'||v_revision.id::text,
    v_revision.manifest_hash,v_task_manifest_hash,v_task_count,0,0,
    case when v_task_count=0 then 'COMPLETE' else 'READY' end,v_run_hash,
    case when v_task_count=0 then pg_catalog.transaction_timestamp() else null end
  ) returning * into v_run;
  -- S9 / WB-016: every task carries the Timesheet FAMILY identity and the
  -- version it was opened against, so a retry, recovery or delayed release
  -- resolves through the family instead of trusting a stored physical id.  The
  -- run-level uniqueness is now on the family, not on root_timesheet_id.
  insert into public.weekly_source_finalisation_pay_tasks(
    run_id,task_ordinal,client_manifest_id,root_timesheet_id,
    root_family_booking_id,root_timesheet_version,
    projection_idempotency_key,prepared_context_json,prepared_context_hash,state
  )
  select v_run.id,entry.ordinality::integer,
         (entry.value->>'client_manifest_id')::uuid,
         (entry.value->>'root_timesheet_id')::uuid,
         root_timesheet.booking_id,
         root_timesheet.version,
         'weekly-source-finalisation-pay:'||v_revision.id::text||':'||
           (entry.value->>'root_timesheet_id'),
         entry.value-(array['prepared_context_hash']::text[]),
         pg_catalog.decode(entry.value->>'prepared_context_hash','hex'),'READY'
  from pg_catalog.jsonb_array_elements(v_contexts) with ordinality entry(value,ordinality)
  join public.timesheets root_timesheet
    on root_timesheet.timesheet_id=(entry.value->>'root_timesheet_id')::uuid;
  -- The join above would silently drop a context whose root Timesheet is not
  -- present, so the manifest count is asserted rather than assumed.
  if (select pg_catalog.count(*)::integer
      from public.weekly_source_finalisation_pay_tasks task
      where task.run_id=v_run.id)<>v_task_count then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_TASK_MANIFEST_CHANGED'
      using errcode='55000';
  end if;
  return private.weekly_source_finalisation_pay_run_json_v1(v_run)
    ||pg_catalog.jsonb_build_object('idempotent_replay',false);
exception
  when no_data_found or too_many_rows then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_OPEN_SCOPE_INVALID'
      using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_correct_final_prepared_context_v1(
  p_correction_session_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_revision public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  v_root record;
  v_source_mode text;
  v_source_units jsonb;
  v_segments jsonb;
  v_expenses jsonb;
  v_actual jsonb;
  v_rate_refs jsonb;
  v_context jsonb;
  v_contexts jsonb:='[]'::jsonb;
  v_source_unit_hash bytea;
  v_source_expense_hash bytea;
  v_active_segment_hash bytea;
begin
  select * into v_session
  from public.weekly_final_source_correction_sessions
  where id=p_correction_session_id;
  if not found or v_session.state not in ('PREPARING','PREPARED','COMMITTING')
     or v_session.prepared_final_revision_id is null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_CONTEXT_UNAVAILABLE'
      using errcode='55000';
  end if;
  select * into strict v_revision
  from public.weekly_source_final_revisions
  where id=v_session.prepared_final_revision_id;
  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_revision.source_cycle_id;
  select * into strict v_upload
  from public.weekly_source_uploads where id=v_revision.upload_id;
  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
  select * into v_manifest
  from public.weekly_source_client_manifests
  where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_revision.id;
  if not found or exists(
    select 1 from public.weekly_source_client_manifests other_manifest where coalesce(other_manifest.invoice_window_cycle_id,other_manifest.source_cycle_id)=other_manifest.source_cycle_id and other_manifest.final_revision_id=v_revision.id
      and other_manifest.id<>v_manifest.id
  ) or v_revision.state<>'PREPARED'
     or v_revision.reason<>'CORRECT_FINAL_SOURCE'
     or v_revision.predecessor_revision_id
          is distinct from v_session.expected_current_final_revision_id
     or v_upload.id is distinct from v_session.replacement_correction_upload_id
     or v_upload.state<>'CORRECTION_READY' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_CONTEXT_INVALID'
      using errcode='55000';
  end if;
  v_source_mode:=case when v_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT'
    then 'NHSP_WEEKLY' else 'HEALTHROSTER_WEEKLY' end;

  -- Rebuild the complete union, not merely roots published by the mistaken
  -- authority.  A valid complete replacement may add a root or remove the
  -- last movement from an old root; both need one exact ordinary projection.
  for v_root in
    with prior_roots as (
      select receipt.root_timesheet_id,receipt.id as prior_projection_receipt_id
      from public.weekly_source_ordinary_pay_projection_receipts receipt
      where receipt.final_revision_id=v_session.expected_current_final_revision_id
        and receipt.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED')
    ), replacement_roots as (
      select distinct movement.invoice_timesheet_id as root_timesheet_id
      from public.weekly_source_billing_movements movement
      where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.final_revision_id=v_revision.id
    )
    select coalesce(replacement.root_timesheet_id,prior.root_timesheet_id)
             as root_timesheet_id,
           prior.prior_projection_receipt_id
    from prior_roots prior
    full join replacement_roots replacement using(root_timesheet_id)
    order by coalesce(replacement.root_timesheet_id,prior.root_timesheet_id)
  loop
    v_source_units:=private.weekly_source_ordinary_projection_source_units_v1(
      v_revision.id,v_root.root_timesheet_id
    );
    v_segments:=private.weekly_source_ordinary_projection_current_segments_v1(
      v_root.root_timesheet_id,v_revision.id
    );
    v_expenses:=private.weekly_source_ordinary_projection_current_expenses_v1(
      v_root.root_timesheet_id,v_revision.id
    );
    v_actual:=private.weekly_source_ordinary_projection_actual_schedule_v1(v_segments);
    v_source_unit_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ORDINARY_UNIT_MANIFEST_V1',v_source_units
    );
    v_source_expense_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ORDINARY_SOURCE_EXPENSE_MANIFEST_V1',v_expenses
    );
    v_active_segment_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_ORDINARY_ACTIVE_SEGMENTS_V1',v_segments
    );
    v_rate_refs:=pg_catalog.jsonb_build_object(
      'schema_version','WEEKLY_SOURCE_FINAL_AUTHORITY_RATE_SOURCE_V1',
      'source_mode',v_source_mode,'root_timesheet_id',v_root.root_timesheet_id,
      'final_revision_id',v_revision.id,
      'final_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex'),
      'final_policy_fingerprint',pg_catalog.encode(v_revision.policy_fingerprint,'hex'),
      'client_manifest_hash',pg_catalog.encode(v_manifest.manifest_hash,'hex'),
      'source_unit_manifest_hash',pg_catalog.encode(v_source_unit_hash,'hex'),
      'source_expense_manifest_hash',pg_catalog.encode(v_source_expense_hash,'hex'),
      'active_segment_manifest_hash',pg_catalog.encode(v_active_segment_hash,'hex')
    );
    v_context:=pg_catalog.jsonb_build_object(
      'root_timesheet_id',v_root.root_timesheet_id,
      'prior_projection_receipt_id',v_root.prior_projection_receipt_id,
      'client_id',v_manifest.client_id,
      'source_profile_kind',v_profile.final_authority_kind,
      'source_mode',v_source_mode,
      'source_units',v_source_units,
      'expected_segments',v_segments,
      'expected_actual_schedule',v_actual,
      'expected_source_expenses',v_expenses,
      'expected_rate_source_refs',v_rate_refs,
      'root_state_hash',pg_catalog.encode(
         private.weekly_source_ordinary_projection_root_hash_v1(
          v_root.root_timesheet_id
        ),'hex'
      )
    );
    v_contexts:=v_contexts||pg_catalog.jsonb_build_array(
      v_context||pg_catalog.jsonb_build_object(
        'prepared_context_hash',pg_catalog.encode(
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_CORRECT_FINAL_PREPARED_ROOT_CONTEXT_V1',v_context
          ),'hex'
        )
      )
    );
  end loop;

  return pg_catalog.jsonb_build_object(
    'correction_session_id',v_session.id,
    'prepared_final_revision_id',v_revision.id,
    'prior_final_revision_id',v_session.expected_current_final_revision_id,
    'source_cycle_id',v_cycle.id,
    'client_id',v_manifest.client_id,
    'source_profile_kind',v_profile.final_authority_kind,
    'source_mode',v_source_mode,
    'root_contexts',v_contexts
  );
end;
$function$;

create or replace function public.weekly_source_finalisation_pay_task_finish_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','expected_task_version','projection_receipt_hash',
    'projection_receipt_id','run_id','schema_version','task_id'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_run_id uuid;
  v_task_id uuid;
  v_receipt_id uuid;
  v_version bigint;
  v_receipt_hash bytea;
  v_run public.weekly_source_finalisation_pay_runs%rowtype;
  v_task public.weekly_source_finalisation_pay_tasks%rowtype;
  v_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_TASK_FINISH_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_FINALISATION_PAY_TASK_FINISH_V1'
     or coalesce(p_request->>'projection_receipt_hash','')!~'^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_TASK_FINISH_CONTRACT_INVALID'
      using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_run_id:=(p_request->>'run_id')::uuid;
    v_task_id:=(p_request->>'task_id')::uuid;
    v_receipt_id:=(p_request->>'projection_receipt_id')::uuid;
    v_version:=(p_request->>'expected_task_version')::bigint;
    v_receipt_hash:=pg_catalog.decode(p_request->>'projection_receipt_hash','hex');
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_TASK_FINISH_INVALID' using errcode='22023';
  end;
  select * into v_run
  from public.weekly_source_finalisation_pay_runs run_row
  where run_row.id=v_run_id for update;
  select * into v_task
  from public.weekly_source_finalisation_pay_tasks task
  where task.id=v_task_id and task.run_id=v_run_id for update;
  if v_run.id is null or v_task.id is null
     or v_run.requested_by_user_id is distinct from v_actor then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_TASK_IDENTITY_CHANGED'
      using errcode='40001';
  end if;
  if v_task.state in (
    'PREPARED_FOR_AUTHORISATION','PROPOSED','NO_OP_FIRST_NEGATIVE','TARGET_MANAGED_SUPPRESSED','FAILED'
  ) then
    v_run:=private.weekly_source_finalisation_pay_run_refresh_v1(v_run.id);
    return private.weekly_source_finalisation_pay_run_json_v1(v_run)
      ||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;
  if v_task.state<>'SUBMISSION_STARTED' or v_task.version<>v_version then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_TASK_STALE'
      using errcode='40001';
  end if;
  select * into v_receipt
  from public.weekly_source_ordinary_pay_projection_receipts receipt
  where receipt.id=v_receipt_id
    and receipt.idempotency_key=v_task.projection_idempotency_key;
  if not found or v_receipt.final_revision_id is distinct from v_run.final_revision_id
     or v_receipt.root_timesheet_id is distinct from v_task.root_timesheet_id
     or v_receipt.receipt_hash is distinct from v_receipt_hash
     or v_receipt.outcome not in (
       'PREPARED_FOR_AUTHORISATION','PROPOSED','NO_OP_FIRST_NEGATIVE','TARGET_MANAGED_SUPPRESSED'
     ) then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_RECEIPT_INVALID'
      using errcode='55000';
  end if;
  perform pg_catalog.set_config(
    'cloudtms.weekly_source_projection_owner',
    'weekly_source_finalisation_pay_task_finish_atomic_v1',true
  );
  update public.weekly_source_state_transitions transition_row
  -- Gate 2: every reachable projection outcome is a success.  There is no
  -- REFUSED_LOCKED to map to FAILED any more.
  set ordinary_source_entitlement_projection_state='PUBLISHED'
  where transition_row.final_revision_id=v_run.final_revision_id
    and transition_row.ordinary_source_entitlement_projection_state='PENDING'
    and exists(
      select 1 from public.weekly_source_billing_movements movement
      where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.transition_id=transition_row.id
        and movement.invoice_timesheet_id=v_task.root_timesheet_id
    );
  update public.weekly_source_finalisation_pay_tasks task
  set state=v_receipt.outcome,projection_receipt_id=v_receipt.id,
      bounded_error_json=null,
      completed_at_utc=pg_catalog.transaction_timestamp(),version=task.version+1
  where task.id=v_task.id;
  v_run:=private.weekly_source_finalisation_pay_run_refresh_v1(v_run.id);
  return private.weekly_source_finalisation_pay_run_json_v1(v_run)
    ||pg_catalog.jsonb_build_object('idempotent_replay',false);
end;
$function$;

create or replace function public.weekly_source_finalisation_pay_task_recover_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','confirm_retry','expected_task_version','run_id',
    'schema_version','task_id'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_run_id uuid;
  v_task_id uuid;
  v_version bigint;
  v_confirm boolean;
  v_run public.weekly_source_finalisation_pay_runs%rowtype;
  v_task public.weekly_source_finalisation_pay_tasks%rowtype;
  v_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  v_terminal_state text;
begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_RECOVER_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_FINALISATION_PAY_RECOVER_V1'
     or pg_catalog.jsonb_typeof(p_request->'confirm_retry')<>'boolean' then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_RECOVER_CONTRACT_INVALID'
      using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_run_id:=(p_request->>'run_id')::uuid;
    v_task_id:=(p_request->>'task_id')::uuid;
    v_version:=(p_request->>'expected_task_version')::bigint;
    v_confirm:=(p_request->>'confirm_retry')::boolean;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_RECOVER_INVALID' using errcode='22023';
  end;
  select * into v_run from public.weekly_source_finalisation_pay_runs run_row
  where run_row.id=v_run_id for update;
  select * into v_task from public.weekly_source_finalisation_pay_tasks task
  where task.id=v_task_id and task.run_id=v_run_id for update;
  if v_run.id is null or v_task.id is null
     or v_run.requested_by_user_id is distinct from v_actor
     or v_task.version<>v_version then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_TASK_STALE'
      using errcode='40001';
  end if;
  if v_task.state in (
    'PREPARED_FOR_AUTHORISATION','PROPOSED','NO_OP_FIRST_NEGATIVE','TARGET_MANAGED_SUPPRESSED','FAILED'
  ) then
    v_run:=private.weekly_source_finalisation_pay_run_refresh_v1(v_run.id);
    return private.weekly_source_finalisation_pay_run_json_v1(v_run)
      ||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;
  if v_task.state not in ('SUBMISSION_STARTED','RECOVERY_REQUIRED') then
    raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_RECOVERY_NOT_REQUIRED'
      using errcode='55000';
  end if;
  select * into v_receipt
  from public.weekly_source_ordinary_pay_projection_receipts receipt
  where receipt.idempotency_key=v_task.projection_idempotency_key;
  if found then
    if v_receipt.final_revision_id is distinct from v_run.final_revision_id
       or v_receipt.root_timesheet_id is distinct from v_task.root_timesheet_id
       or v_receipt.outcome not in (
         'PREPARED_FOR_AUTHORISATION','PROPOSED','NO_OP_FIRST_NEGATIVE','TARGET_MANAGED_SUPPRESSED'
       ) then
      raise exception 'WEEKLY_SOURCE_FINALISATION_PAY_RECEIPT_INVALID'
        using errcode='55000';
    end if;
    v_terminal_state:=v_receipt.outcome;
    perform pg_catalog.set_config(
      'cloudtms.weekly_source_projection_owner',
      'weekly_source_finalisation_pay_task_recover_atomic_v1',true
    );
    update public.weekly_source_state_transitions transition_row
    set ordinary_source_entitlement_projection_state='PUBLISHED'
    where transition_row.final_revision_id=v_run.final_revision_id
      and transition_row.ordinary_source_entitlement_projection_state='PENDING'
      and exists(
        select 1 from public.weekly_source_billing_movements movement
        where movement.source_profile_kind<>'SELF_BILL_REPORT' and movement.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement.transition_id=transition_row.id
          and movement.invoice_timesheet_id=v_task.root_timesheet_id
      );
    update public.weekly_source_finalisation_pay_tasks task
    set state=v_terminal_state,projection_receipt_id=v_receipt.id,
        bounded_error_json=null,
        completed_at_utc=pg_catalog.transaction_timestamp(),version=task.version+1
    where task.id=v_task.id;
    v_run:=private.weekly_source_finalisation_pay_run_refresh_v1(v_run.id);
    return private.weekly_source_finalisation_pay_run_json_v1(v_run)
      ||pg_catalog.jsonb_build_object('recovered_receipt',true);
  end if;
  if not v_confirm then
    if v_task.state='SUBMISSION_STARTED' then
      update public.weekly_source_finalisation_pay_tasks task
      set state='RECOVERY_REQUIRED',bounded_error_json=coalesce(
        task.bounded_error_json,
        pg_catalog.jsonb_build_object(
          'error_code','WEEKLY_SOURCE_FINALISATION_PAY_RESULT_UNKNOWN',
          'outcome','UNKNOWN'
        )
      ),version=task.version+1
      where task.id=v_task.id;
    end if;
    v_run:=private.weekly_source_finalisation_pay_run_refresh_v1(v_run.id);
    return private.weekly_source_finalisation_pay_run_json_v1(v_run)
      ||pg_catalog.jsonb_build_object('retry_permitted',false);
  end if;
  update public.weekly_source_finalisation_pay_tasks task
  set state='READY',bounded_error_json=null,completed_at_utc=null,
      version=task.version+1
  where task.id=v_task.id returning * into v_task;
  update public.weekly_source_finalisation_pay_runs run_row
  set state='READY',completed_at_utc=null where run_row.id=v_run.id;
  v_run:=private.weekly_source_finalisation_pay_run_refresh_v1(v_run.id);
  return private.weekly_source_finalisation_pay_run_json_v1(v_run)
    ||pg_catalog.jsonb_build_object(
      'retry_permitted',true,
      'task',private.weekly_source_finalisation_pay_task_json_v1(v_task)
    );
end;
$function$;

create or replace function private.weekly_source_office_proposal_revision_v1(
  p_member_timesheet_ids uuid[],
  p_source_revision_digest bytea
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_candidates integer:=0;
  v_matches uuid[];
begin
  if p_member_timesheet_ids is null
     or pg_catalog.cardinality(p_member_timesheet_ids)=0
     or p_source_revision_digest is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','PROPOSAL_REVISION_INPUT_INVALID','final_revision_id',null,
      'candidate_count',0,'match_count',0);
  end if;

  with candidate_revision as (
    select distinct revision_row.*
    from public.weekly_source_final_revisions as revision_row
    where revision_row.id in (
      select movement_row.final_revision_id
      from public.weekly_source_billing_movements as movement_row
      where movement_row.source_profile_kind<>'SELF_BILL_REPORT' and movement_row.source_line_kind not in ('SELF_BILL_REPORT_LINE','INVOICE_VAT_ROUNDING','SOURCE_REBILL_LINE','SOURCE_INVOICE_CORRECTION')
      and movement_row.invoice_timesheet_id=any(p_member_timesheet_ids)
      union
      select receipt_row.final_revision_id
      from public.weekly_source_ordinary_pay_projection_receipts as receipt_row
      where receipt_row.root_timesheet_id=any(p_member_timesheet_ids)
    )
  )
  -- The ONE canonical encoder, not a second hash of the same fact (WP-06c
  -- handoff N1).  The recorder used to write this digest with a
  -- domain-separated sha256 while both installed consumers -- the publication
  -- coordinator and the save-pending owner -- recompute it with
  -- `weekly_source_publication_request_digest_v1` and refuse on any difference,
  -- so nothing could publish at all.  The recorder moved onto the canonical
  -- encoder; this resolver was the last reader of the old form.
  --
  -- The two uuids are cast to `text` on purpose: the canonicaliser emits every
  -- uuid as a lower-case JSON string and `revision_number` as a bare integer,
  -- and the encoder refuses a non-integral number, so the object has to be
  -- built in exactly that form to reproduce the stored value.
  select pg_catalog.count(*)::integer,
         pg_catalog.array_agg(candidate_revision.id) filter (
           where private.weekly_source_publication_request_digest_v1(
             pg_catalog.jsonb_build_object(
               'final_revision_id',candidate_revision.id::text,
               'source_cycle_id',candidate_revision.source_cycle_id::text,
               'revision_number',candidate_revision.revision_number,
               'manifest_hash',pg_catalog.encode(candidate_revision.manifest_hash,'hex'),
               'policy_fingerprint',pg_catalog.encode(candidate_revision.policy_fingerprint,'hex')
             ))=p_source_revision_digest)
    into v_candidates,v_matches
  from candidate_revision;

  if v_candidates>200 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','PROPOSAL_REVISION_CANDIDATES_EXCEED_BOUND',
      'final_revision_id',null,'candidate_count',v_candidates,'match_count',0);
  end if;
  if v_matches is null or pg_catalog.cardinality(v_matches)=0 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','PROPOSAL_REVISION_NOT_IDENTIFIED',
      'final_revision_id',null,'candidate_count',v_candidates,'match_count',0);
  end if;
  if pg_catalog.cardinality(v_matches)>1 then
    return pg_catalog.jsonb_build_object(
      'ok',false,'reason','PROPOSAL_REVISION_AMBIGUOUS',
      'final_revision_id',null,'candidate_count',v_candidates,
      'match_count',pg_catalog.cardinality(v_matches));
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,'reason',null,'final_revision_id',v_matches[1],
    'candidate_count',v_candidates,'match_count',1);
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function private.weekly_source_correct_final_preconditions_v1(
  p_prior_final_revision_id uuid,
  p_actor_user_id uuid,
  p_excluding_correction_session_id uuid,
  p_lock_roots boolean
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_revision public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  v_root record;
  v_preflight jsonb;
  v_roots jsonb;
  v_family uuid[];
  v_family_after_lock uuid[];
  v_current_lock_upload public.weekly_source_uploads%rowtype;
  v_current_lock_publication public.weekly_source_projection_publications%rowtype;
  v_current_lock_generation integer;
  v_current_lock_operation uuid;
begin
  if p_prior_final_revision_id is null or p_actor_user_id is null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PRECONDITION_INPUT_INVALID'
      using errcode='22023';
  end if;

  select * into v_revision
  from public.weekly_source_final_revisions
  where id=p_prior_final_revision_id;
  if not found or v_revision.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE'
      using errcode='40001';
  end if;
  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_revision.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  select * into strict v_upload
  from public.weekly_source_uploads where id=v_revision.upload_id;
  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;

  select * into v_manifest
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_revision.id;
  if not found or exists(
    select 1 from public.weekly_source_client_manifests other_manifest
    where coalesce(other_manifest.invoice_window_cycle_id,other_manifest.source_cycle_id)=other_manifest.source_cycle_id and other_manifest.final_revision_id=v_revision.id
      and other_manifest.id<>v_manifest.id
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CLIENT_SCOPE_INVALID'
      using errcode='55000';
  end if;

  if exists(
    select 1
    from public.weekly_source_final_revisions later_revision
    join public.weekly_source_cycles later_cycle
      on later_cycle.id=later_revision.source_cycle_id
    join public.weekly_source_client_manifests later_manifest
      on later_manifest.final_revision_id=later_revision.id
     and later_manifest.client_id=v_manifest.client_id
    join public.weekly_source_uploads later_upload on later_upload.id=later_revision.upload_id
    join public.weekly_source_format_profiles later_profile
      on later_profile.id=later_upload.source_format_profile_id
    where later_revision.state='CURRENT'
      and later_cycle.source_group_id=v_group.id
      and later_cycle.finalisation_week_ending>v_cycle.finalisation_week_ending
      and later_profile.final_authority_kind=v_profile.final_authority_kind
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_LATER_FINAL_CYCLE_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1 from public.weekly_source_final_revisions descendant
    where descendant.predecessor_revision_id=v_revision.id
      and not exists(
        select 1
        from public.weekly_final_source_correction_sessions own_correction
        where own_correction.id=p_excluding_correction_session_id
          and own_correction.expected_current_final_revision_id=v_revision.id
          and own_correction.prepared_final_revision_id=descendant.id
          and descendant.state='PREPARED'
      )
  ) or exists(
    select 1 from public.weekly_final_source_correction_sessions correction
    where correction.expected_current_final_revision_id=v_revision.id
      and correction.id is distinct from p_excluding_correction_session_id
      and correction.state not in ('CANCELLED','FAILED')
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_DESCENDANT_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1
    from public.weekly_exceptional_pay_target_events target_event
    where target_event.triggering_final_revision_id=v_revision.id
  ) or exists(
    select 1
    from public.weekly_exceptional_pending_reconciliation_targets pending_target
    where pending_target.current_final_revision_id=v_revision.id
      and pending_target.state='ACTIVE'
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_DESCENDANT_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    where movement.final_revision_id=v_revision.id
  ) or exists(
    select 1
    from public.weekly_source_invoice_placements placement
    join public.weekly_source_billing_movements movement
      on movement.id=placement.billing_movement_id
    where movement.final_revision_id=v_revision.id
      and placement.placement_state='PLACED'
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1 from public.invoice_operations operation
    where operation.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and operation.operation_type in ('GENERATE_INVOICES','BUILD_DOCUMENT','ISSUE_INVOICES')
      and (
        (operation.entity_type='CLIENT' and operation.entity_id=v_manifest.client_id)
        or operation.input_json->>'client_id'=v_manifest.client_id::text
        or operation.input_json->'client_ids' @> pg_catalog.jsonb_build_array(v_manifest.client_id::text)
      )
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_INVOICE_OPERATION'
      using errcode='55000';
  end if;

  -- Establish the complete sorted booking inventory BEFORE this owner's
  -- first old-family row lock. PREPARE/APPLY also include actual replacement
  -- upload roots and maintained prior-only CURRENT HR/expense coverage roots;
  -- OPEN has no replacement and locks only genuine exact prior membership.
  if coalesce(p_lock_roots,true) and (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    if p_excluding_correction_session_id is not null then
      select u.* into v_current_lock_upload from public.weekly_final_source_correction_sessions s
        join public.weekly_source_uploads u on u.id=s.replacement_correction_upload_id
        where s.id=p_excluding_correction_session_id;
      if found then
        select p.* into strict v_current_lock_publication from public.weekly_final_source_correction_sessions s
          join public.weekly_source_projection_publications p on p.id=s.replacement_projection_publication_id
          where s.id=p_excluding_correction_session_id and p.upload_id=v_current_lock_upload.id;
        if v_current_lock_publication.authority_scope_version>2147483647 then
          raise exception 'WEEKLY_SOURCE_GENERATION_OVERFLOW' using errcode='22003';end if;
        v_current_lock_generation:=coalesce(v_current_lock_publication.projection_generation,v_current_lock_publication.authority_scope_version::integer);
      end if;
    end if;
    v_current_lock_operation:=private.bpay_next_source_current_lock_inventory_v1(
      v_current_lock_upload.id,v_current_lock_generation,v_revision.id,v_group.id,v_manifest.client_id,
      v_current_lock_upload.confirmed_coverage_start_local_date,v_current_lock_upload.confirmed_coverage_end_local_date
    );
  end if;

  for v_receipt in
    select receipt.*
    from public.weekly_source_ordinary_pay_projection_receipts receipt
    where receipt.final_revision_id=v_revision.id
      and receipt.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED')
    order by receipt.root_timesheet_id
  loop
    -- Gate 13 hostile review F5 / standing rule 3.  These preconditions guard
    -- one ordinary Weekly root against protected-pay ownership and against an
    -- existing invoice line.  After S8 the physical root id is not a family
    -- identity, so a protected family or an invoice line recorded against a
    -- rotated sibling was invisible here and the correction proceeded.
    --
    -- The lock is taken BEFORE the guarded state is read.  The family has to be
    -- named before its rows can be locked, so the identity is resolved, its
    -- rows are locked in a deterministic order, and the identity is then
    -- re-resolved and required to be unchanged (the same shape as the
    -- lock-and-resolve helper's post-lock re-read).  A membership change across
    -- the lock fails closed.
    v_family:=private.weekly_source_invoice_family_timesheet_ids_v1(
      v_receipt.root_timesheet_id
    );
    if v_family is null or pg_catalog.cardinality(v_family)=0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
        using errcode='55000';
    end if;
    if coalesce(p_lock_roots,true) then
      perform 1 from public.timesheets family_row
      where family_row.timesheet_id=any(v_family)
      order by family_row.timesheet_id
      for update;
      v_family_after_lock:=private.weekly_source_invoice_family_timesheet_ids_v1(
        v_receipt.root_timesheet_id
      );
      if v_family_after_lock is null
         or pg_catalog.cardinality(v_family_after_lock)=0
         or not (v_family_after_lock @> v_family and v_family @> v_family_after_lock)
      then
        raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
          using errcode='40001';
      end if;
      v_family:=v_family_after_lock;
    end if;
    if exists(
      select 1 from public.weekly_exceptional_pay_target_families family
      where family.root_timesheet_id=any(v_family)
        and family.ownership_state='TARGET_MANAGED'
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PROTECTED_TARGET_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.invoice_lines invoice_line
      where invoice_line.timesheet_id=any(v_family)
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.timesheets timesheet_row
      where timesheet_row.timesheet_id=v_receipt.root_timesheet_id
        and timesheet_row.active_document_operation_id is not null
    ) or exists(
      select 1 from public.invoice_operations operation
      where operation.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and operation.entity_type='TIMESHEET'
        and operation.entity_id=v_receipt.root_timesheet_id
    ) or exists(
      select 1 from public.invoice_operation_chunks chunk
      where chunk.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and chunk.entity_type='TIMESHEET'
        and chunk.entity_id=v_receipt.root_timesheet_id
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_INVOICE_OPERATION'
        using errcode='55000';
    end if;

    v_preflight:=public.import_timesheet_financial_preflight_v1(
      array[v_receipt.root_timesheet_id],
      'WEEKLY_SOURCE_CORRECT_FINAL_SOURCE',p_actor_user_id,'{}'::jsonb,
      coalesce(p_lock_roots,true),1
    );
    if coalesce((v_preflight->>'blocking_batch_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_PAY_DRAFT'
        using errcode='55000',detail=v_preflight::text;
    elsif coalesce((v_preflight->>'paid_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_PAID'
        using errcode='55000',detail=v_preflight::text;
    elsif coalesce((v_preflight->>'invoice_lined_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000',detail=v_preflight::text;
    elsif coalesce((v_preflight->>'allowed')::boolean,false) is not true
       or v_preflight->>'required_path' not in (
         -- Gate 2 / XSG-032.  UNAUTHORISE_AMEND_RECALCULATE_REAUTHORISE is
         -- deliberately NOT admitted: Correct Final Source stays the narrow
         -- same-cycle correction for a root that is not yet authorised.  An
         -- already-authorised root always goes to proposal and Office decision.
         'DIRECT_AMEND_RECALCULATE'
       ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_NOT_MUTABLE'
        using errcode='55000',detail=v_preflight::text;
    end if;
  end loop;

  if v_current_lock_operation is not null then
    perform private.bpay_next_source_current_lock_release_v1(v_current_lock_operation);
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'root_timesheet_id',receipt.root_timesheet_id,
    'prior_projection_receipt_id',receipt.id,
    'client_id',receipt.client_id,
    'source_profile_kind',receipt.source_profile_kind,
    'source_mode',receipt.source_mode,
    'root_after_hash',pg_catalog.encode(receipt.root_after_hash,'hex')
  ) order by receipt.root_timesheet_id),'[]'::jsonb)
  into v_roots
  from public.weekly_source_ordinary_pay_projection_receipts receipt
  where receipt.final_revision_id=v_revision.id
    and receipt.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED');

  return pg_catalog.jsonb_build_object(
    'prior_final_revision_id',v_revision.id,
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'authority_scope_kind',v_revision.authority_scope_kind,
    'report_scope_id',v_revision.report_scope_id,
    'client_id',v_manifest.client_id,
    'source_profile_kind',v_profile.final_authority_kind,
    'source_mode',case when v_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT'
      then 'NHSP_WEEKLY' else 'HEALTHROSTER_WEEKLY' end,
    'final_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex'),
    'affected_roots',v_roots
  );
end;
$function$;

create or replace function public.weekly_source_correct_final_open_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','authority_scope_kind','expected_current_final_revision_id',
    'expected_final_manifest_hash','idempotency_key','reason','report_scope_id',
    'schema_version','source_cycle_id'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_cycle_id uuid;
  v_scope_kind text;
  v_report_scope_id uuid;
  v_revision_id uuid;
  v_expected_manifest bytea;
  v_idempotency_key text;
  v_reason text;
  v_request_hash bytea;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_revision public.weekly_source_final_revisions%rowtype;
  v_existing public.weekly_final_source_correction_sessions%rowtype;
  v_existing_by_key public.weekly_final_source_correction_sessions%rowtype;
  v_existing_by_hash public.weekly_final_source_correction_sessions%rowtype;
  v_existing_key_count bigint;
  v_existing_hash_count bigint;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_guard jsonb;
  v_group_id uuid;
  v_client_id uuid;
  v_guard_fingerprint bytea;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_OPEN_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_scope_kind:=pg_catalog.upper(pg_catalog.btrim(p_request->>'authority_scope_kind'));
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_revision_id:=(p_request->>'expected_current_final_revision_id')::uuid;
    v_expected_manifest:=pg_catalog.decode(p_request->>'expected_final_manifest_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_actor is null or v_cycle_id is null or v_revision_id is null
     or v_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE')
     or (v_scope_kind='NHSP_REPORT_SCOPE') is distinct from (v_report_scope_id is not null)
     or pg_catalog.octet_length(v_expected_manifest)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_OPEN_V1',p_request-'idempotency_key'
  );
  -- WP-59.  Two defects lived in this one replay lookup.
  --
  -- (1) It chose between an idempotency-key match and a request-hash match with
  --     `order by ... limit 1`.  That is a safety decision taken by an
  --     ordering, which this programme forbids.  Both candidates are now read
  --     explicitly, each with its own cardinality check, and a disagreement
  --     between them fails closed instead of being silently ranked away.
  --
  -- (2) It matched a session in ANY state.  Before WP-59 that was harmless
  --     because no session could ever leave the live set.  Now that
  --     public.weekly_source_correct_final_cancel_atomic_v1 exists, re-sending
  --     the request that opened a since-cancelled session would have returned
  --     that cancelled session as an idempotent replay -- telling Office it
  --     still has a correction session when it has none.  A terminal session is
  --     never replayed as if it were live; the caller is told so in a typed
  --     refusal and must open the new correction with its own key.
  select pg_catalog.count(*) into v_existing_key_count
  from public.weekly_final_source_correction_sessions correction
  where correction.actor_user_id=v_actor
    and correction.idempotency_key=v_idempotency_key;
  select pg_catalog.count(*) into v_existing_hash_count
  from public.weekly_final_source_correction_sessions correction
  where correction.request_hash=v_request_hash;
  if v_existing_key_count>1 or v_existing_hash_count>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_AMBIGUOUS'
      using errcode='55000',
        detail='key_matches='||v_existing_key_count::text
               ||' request_hash_matches='||v_existing_hash_count::text;
  end if;
  if v_existing_key_count=1 then
    select * into v_existing_by_key
    from public.weekly_final_source_correction_sessions correction
    where correction.actor_user_id=v_actor
      and correction.idempotency_key=v_idempotency_key;
  end if;
  if v_existing_hash_count=1 then
    select * into v_existing_by_hash
    from public.weekly_final_source_correction_sessions correction
    where correction.request_hash=v_request_hash;
  end if;
  if v_existing_key_count=1 and v_existing_hash_count=1
     and v_existing_by_key.id is distinct from v_existing_by_hash.id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_COLLISION'
      using errcode='22023';
  end if;
  if v_existing_key_count=1 then
    v_existing:=v_existing_by_key;
  elsif v_existing_hash_count=1 then
    v_existing:=v_existing_by_hash;
  end if;
  if v_existing_key_count=1 or v_existing_hash_count=1 then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    if v_existing.state in ('CANCELLED','FAILED') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_SESSION_TERMINAL'
        using errcode='22023',
          detail='correction session '||v_existing.id::text||' is '
                 ||v_existing.state||'. Open the new correction with its own '
                 'idempotency key and its own reason; a terminal session is '
                 'never replayed as a live one.';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',v_existing.state,'correction_session_id',v_existing.id,
      'version',v_existing.version,'idempotent_replay',true
    );
  end if;

  select * into v_cycle from public.weekly_source_cycles
  where id=v_cycle_id for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select source_group_id into v_group_id
  from public.weekly_source_cycles where id=v_cycle.id;
  if v_scope_kind='NHSP_REPORT_SCOPE' then
    select * into v_scope from public.weekly_source_report_scopes
    where id=v_report_scope_id for update;
    if not found or v_scope.source_cycle_id is distinct from v_cycle.id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SCOPE_INVALID' using errcode='22023';
    end if;
    v_client_id:=v_scope.client_id;
    if v_scope.current_final_revision_id is distinct from v_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
    end if;
  elsif v_cycle.current_final_revision_id is distinct from v_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;
  select * into v_revision from public.weekly_source_final_revisions
  where id=v_revision_id for update;
  if not found or v_revision.state<>'CURRENT'
     or v_revision.source_cycle_id is distinct from v_cycle.id
     or v_revision.authority_scope_kind is distinct from v_scope_kind
     or v_revision.report_scope_id is distinct from v_report_scope_id
     or v_revision.manifest_hash is distinct from v_expected_manifest then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;
  if v_client_id is null then
    select client_id into strict v_client_id
    from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_revision.id;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group_id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_revision.id,v_actor,null::uuid,false
  );
  v_guard_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  insert into public.weekly_final_source_correction_sessions(
    source_cycle_id,authority_scope_kind,report_scope_id,
    expected_current_final_revision_id,expected_final_manifest_hash,state,version,
    actor_user_id,reason,idempotency_key,request_hash,guard_fingerprint
  ) values (
    v_cycle.id,v_scope_kind,v_report_scope_id,v_revision.id,v_revision.manifest_hash,
    'DRAFT',1,v_actor,v_reason,v_idempotency_key,v_request_hash,v_guard_fingerprint
  ) returning * into v_session;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_OPENED',
         pg_catalog.jsonb_build_object(
           'current_final_revision_id',v_revision.id,
           'current_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex')
         ),
         pg_catalog.jsonb_build_object(
           'state','DRAFT','source_cycle_id',v_cycle.id,
           'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_guard->'affected_roots'),
           'guard_fingerprint',pg_catalog.encode(v_guard_fingerprint,'hex')
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','DRAFT','correction_session_id',v_session.id,
    'version',v_session.version,'affected_root_count',
      pg_catalog.jsonb_array_length(v_guard->'affected_roots'),
    'guard_fingerprint',pg_catalog.encode(v_guard_fingerprint,'hex'),
    'idempotent_replay',false
  );
end;
$function$;

create or replace function public.weekly_source_correct_final_review_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_row_manifest_hash','expected_session_version','idempotency_key',
    'replacement_projection_publication_id','replacement_upload_id','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_idempotency_key text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_client_id uuid;
  v_office_preview jsonb;
  v_result jsonb;
  v_result_hash bytea;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_V1',p_request-'idempotency_key'
  );

  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.review_idempotency_key=v_idempotency_key then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.review_request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.review_result_json||pg_catalog.jsonb_build_object(
      'idempotent_replay',true
    );
  end if;
  if v_session.state not in ('READY','REVIEWED') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state not in ('READY','REVIEWED')
     or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for share;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,
                    v_cycle.current_projection_publication_id)
  for share;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for share;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for share;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
      or v_replacement_publication.authority_scope_version<>v_scope_version
      or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
      or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;
  select client_id into strict v_client_id
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,false
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  v_result:=pg_catalog.jsonb_build_object(
    'ok',true,
    'status',case when pg_catalog.jsonb_array_length(v_office_preview->'blockers')>0
      then 'BLOCKED' else 'READY_FOR_CONFIRMATION' end,
    'correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'upload_id',v_replacement_upload.id,
    'version',v_expected_session_version+1,
    'office_preview',v_office_preview,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='REVIEWED',review_idempotency_key=v_idempotency_key,
      review_request_hash=v_request_hash,review_result_json=v_result,
      review_result_hash=v_result_hash,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state in ('READY','REVIEWED')
    and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_REVIEWED',
         pg_catalog.jsonb_build_object('state',v_session.state,'version',v_expected_session_version),
         pg_catalog.jsonb_build_object(
           'state','REVIEWED','version',v_expected_session_version+1,
           'status',v_result->>'status',
           'change_count',pg_catalog.jsonb_array_length(v_office_preview->'changes'),
           'blocker_count',pg_catalog.jsonb_array_length(v_office_preview->'blockers'),
           'review_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_session.reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function public.weekly_source_correct_final_prepare_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_preview_hash','expected_row_manifest_hash','expected_session_version',
    'idempotency_key','reason','confirmation_text',
    'replacement_projection_publication_id','replacement_upload_id','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_expected_preview_hash bytea;
  v_idempotency_key text;
  v_reason text;
  v_confirmation_text text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_client_id uuid;
  v_core_result jsonb;
  v_context jsonb;
  v_result jsonb;
  v_result_hash bytea;
  v_prepared_revision_id uuid;
  v_prepared_session_version bigint;
  v_office_preview jsonb;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
    v_expected_preview_hash:=pg_catalog.decode(p_request->>'expected_preview_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_confirmation_text:=pg_catalog.btrim(coalesce(p_request->>'confirmation_text',''));
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.octet_length(v_expected_preview_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_confirmation_text) not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_V1',p_request-'idempotency_key'
  );
  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.state in ('PREPARED','COMMITTING','APPLIED') then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.prepare_idempotency_key is distinct from v_idempotency_key
       or v_session.prepare_request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.prepare_result_json||pg_catalog.jsonb_build_object(
      'status','PREPARED','idempotent_replay',true
    );
  end if;

  -- Exact retained PREPARE replay above remains exempt. Fresh correction
  -- admission precedes the outer cycle lock and the nested Final engine.
  perform private.weekly_source_pay_query_admit_v2();

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state<>'REVIEWED' or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or v_session.review_result_json is null
     or v_session.review_result_hash is distinct from private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_RESULT_V1',v_session.review_result_json
        )
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for share;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,
                    v_cycle.current_projection_publication_id)
  for share;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for update;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for update;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_publication.authority_scope_version<>v_scope_version
     or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
     or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;
  select client_id into strict v_client_id
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,true
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  if v_session.review_result_json->'office_preview' is distinct from v_office_preview
     or private.weekly_source_finalisation_hex32_v1(
          v_office_preview->>'preview_hash','WEEKLY_SOURCE_CORRECTION_PREVIEW_HASH_INVALID'
        ) is distinct from v_expected_preview_hash
     or v_confirmation_text is distinct from v_office_preview->>'confirmation_text'
     or pg_catalog.jsonb_array_length(v_office_preview->'blockers')<>0 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREVIEW_STALE' using errcode='40001';
  end if;
  update public.weekly_final_source_correction_sessions
  set state='PREPARING',prepare_idempotency_key=v_idempotency_key,
      prepare_request_hash=v_request_hash,reason=v_reason,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='REVIEWED' and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;

  v_core_result:=private.weekly_source_finalise_engine_v1(
    pg_catalog.jsonb_build_object(
      'actor_user_id',v_actor,'source_cycle_id',v_cycle.id,
      'authority_scope_kind',v_session.authority_scope_kind,
      'report_scope_id',v_session.report_scope_id,
      'upload_id',v_replacement_upload.id,
      'projection_publication_id',v_replacement_publication.id,
      'expected_authority_scope_version',v_scope_version,
      'expected_row_manifest_hash',pg_catalog.encode(v_expected_row_hash,'hex'),
      'expected_comparison_manifest_hash',pg_catalog.encode(v_expected_comparison_hash,'hex'),
      'expected_issue_set_hash',pg_catalog.encode(v_expected_issue_hash,'hex')
    ),v_session.id,true
  );
  if coalesce((v_core_result->>'ok')::boolean,false) is not true
     or v_core_result->>'status'<>'PREPARED' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_FAILED'
      using errcode='55000',detail=v_core_result::text;
  end if;
  v_prepared_revision_id:=(v_core_result->>'final_revision_id')::uuid;
  update public.weekly_final_source_correction_sessions
  set prepared_final_revision_id=v_prepared_revision_id
  where id=v_session.id and state='PREPARING'
    and prepare_request_hash=v_request_hash;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  v_context:=private.weekly_source_correct_final_prepared_context_v1(v_session.id);
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  v_prepared_session_version:=v_expected_session_version+2;
  v_result:=v_core_result||pg_catalog.jsonb_build_object(
    'correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'root_contexts',v_context->'root_contexts',
    'office_preview',v_office_preview,
    'version',v_prepared_session_version,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='PREPARED',prepare_result_json=v_result,prepare_result_hash=v_result_hash,
      version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='PREPARING'
    and prepared_final_revision_id=v_prepared_revision_id
    and prepare_request_hash=v_request_hash;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_PREPARED',
         pg_catalog.jsonb_build_object(
           'state','READY','current_final_revision_id',v_prior_revision.id
         ),
         pg_catalog.jsonb_build_object(
           'state','PREPARED','prepared_final_revision_id',v_prepared_revision_id,
           'replacement_upload_id',v_replacement_upload.id,
           'replacement_projection_publication_id',v_replacement_publication.id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_context->'root_contexts'),
           'prepare_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_session.reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function public.weekly_source_correct_final_apply_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_preview_hash','expected_row_manifest_hash','expected_session_version',
    'idempotency_key','reason','confirmation_text',
    'replacement_projection_publication_id','replacement_upload_id',
    'root_service_snapshots','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_expected_preview_hash bytea;
  v_idempotency_key text;
  v_reason text;
  v_confirmation_text text;
  v_apply_request_hash bytea;
  v_root_snapshots jsonb;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_prepared_revision public.weekly_source_final_revisions%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_prepared_context jsonb;
  v_live_preview jsonb;
  v_server_roots jsonb;
  v_client_id uuid;
  v_new_revision_id uuid;
  v_root record;
  v_snapshot jsonb;
  v_prior_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  v_projection_result jsonb;
  v_root_preflight jsonb;
  v_impact_hash bytea;
  v_result jsonb;
  v_result_hash bytea;
  v_completion_generation integer;
  v_completion_hash bytea;
  v_voided_count integer;
  v_old_movement_count integer;
  v_cas_count integer;
  v_family uuid[];
  v_family_after_lock uuid[];
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_APPLY_V1'
     or pg_catalog.jsonb_typeof(p_request->'root_service_snapshots')<>'array' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
    v_expected_preview_hash:=pg_catalog.decode(p_request->>'expected_preview_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_confirmation_text:=pg_catalog.btrim(coalesce(p_request->>'confirmation_text',''));
  v_root_snapshots:=p_request->'root_service_snapshots';
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.octet_length(v_expected_preview_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_confirmation_text) not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_VALUE_INVALID' using errcode='22023';
  end if;
  v_apply_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_APPLY_V1',p_request-'idempotency_key'
  );

  select * into v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.state='APPLIED' then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.apply_idempotency_key is distinct from v_idempotency_key
       or v_session.apply_request_hash is distinct from v_apply_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.result_json||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;

  -- Exact retained APPLIED replay above remains exempt. Fresh correction
  -- admission precedes cycle/session locks and the CURRENT authority CAS.
  perform private.weekly_source_pay_query_admit_v2();

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state<>'PREPARED' or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for update;
  select * into strict v_prepared_revision from public.weekly_source_final_revisions
  where id=v_session.prepared_final_revision_id for update;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for update;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,v_cycle.current_projection_publication_id)
  for update;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for update;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for update;

  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prepared_revision.state<>'PREPARED'
     or v_prepared_revision.reason<>'CORRECT_FINAL_SOURCE'
     or v_prepared_revision.predecessor_revision_id is distinct from v_prior_revision.id
     or v_prepared_revision.source_cycle_id is distinct from v_cycle.id
     or v_prepared_revision.upload_id is distinct from v_replacement_upload.id
     or v_session.prepare_result_json->>'final_revision_id'
          is distinct from v_prepared_revision.id::text
     or v_session.prepare_result_hash is distinct from private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_RESULT_V1',v_session.prepare_result_json
        )
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_publication.authority_scope_version<>v_scope_version
     or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
     or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;

  select client_id into strict v_client_id
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,true
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_prepared_context:=private.weekly_source_correct_final_prepared_context_v1(v_session.id);
  v_server_roots:=v_prepared_context->'root_contexts';
  if v_server_roots is distinct from v_session.prepare_result_json->'root_contexts' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_CONTEXT_STALE'
      using errcode='40001';
  end if;
  v_live_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  if v_session.prepare_result_json->'office_preview' is distinct from v_live_preview
     or private.weekly_source_finalisation_hex32_v1(
          v_live_preview->>'preview_hash','WEEKLY_SOURCE_CORRECTION_PREVIEW_HASH_INVALID'
        ) is distinct from v_expected_preview_hash
     or v_confirmation_text is distinct from v_live_preview->>'confirmation_text'
     or pg_catalog.jsonb_array_length(v_live_preview->'blockers')<>0 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREVIEW_STALE' using errcode='40001';
  end if;

  if exists(
    select 1 from pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
    where pg_catalog.jsonb_typeof(supplied.value)<>'object'
       or not (supplied.value ? 'root_timesheet_id'
               and supplied.value ? 'prepared_context_hash'
               and supplied.value ? 'service_snapshot')
       or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(supplied.value))<>3
       or coalesce(supplied.value->>'root_timesheet_id','')
            !~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(supplied.value->>'prepared_context_hash','') !~*'^[0-9a-f]{64}$'
       or pg_catalog.jsonb_typeof(supplied.value->'service_snapshot')<>'object'
  ) or (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_root_snapshots))
       <>pg_catalog.jsonb_array_length(v_server_roots)
     or exists(
       select 1
       from pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
       group by supplied.value->>'root_timesheet_id'
       having pg_catalog.count(*)<>1
     ) or exists(
       select 1 from pg_catalog.jsonb_array_elements(v_server_roots) server_root(value)
       where not exists(
         select 1 from pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
         where supplied.value->>'root_timesheet_id'=server_root.value->>'root_timesheet_id'
           and supplied.value->>'prepared_context_hash'=
                 server_root.value->>'prepared_context_hash'
       )
     ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_SNAPSHOT_SET_MISMATCH'
      using errcode='40001';
  end if;

  -- PREPARE can create a replacement-only root that did not exist when OPEN
  -- froze the prior-root guard.  Apply the same invoice/Banking/Draft
  -- preconditions to every sealed union root immediately before COMMITTING so
  -- a newly created root cannot enter another owner between PREPARE and APPLY.
  for v_root in
    select (server_root.value->>'root_timesheet_id')::uuid as root_timesheet_id
    from pg_catalog.jsonb_array_elements(v_server_roots) server_root(value)
    order by server_root.value->>'root_timesheet_id'
  loop
    -- Gate 13 hostile review F5 / standing rule 3, at COMMITTING time.  Same
    -- family keying and same lock-before-read order as the OPEN-time
    -- preconditions above: name the family, lock its rows in a deterministic
    -- order, re-resolve, require the membership to be unchanged, and only then
    -- read the protected-family and invoice-line state that is being guarded.
    v_family:=private.weekly_source_invoice_family_timesheet_ids_v1(
      v_root.root_timesheet_id
    );
    if v_family is null or pg_catalog.cardinality(v_family)=0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
        using errcode='55000';
    end if;
    perform 1 from public.timesheets family_row
    where family_row.timesheet_id=any(v_family)
    order by family_row.timesheet_id
    for update;
    v_family_after_lock:=private.weekly_source_invoice_family_timesheet_ids_v1(
      v_root.root_timesheet_id
    );
    if v_family_after_lock is null
       or pg_catalog.cardinality(v_family_after_lock)=0
       or not (v_family_after_lock @> v_family and v_family @> v_family_after_lock)
    then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
        using errcode='40001';
    end if;
    v_family:=v_family_after_lock;
    if exists(
      select 1 from public.weekly_exceptional_pay_target_families family
      where family.root_timesheet_id=any(v_family)
        and family.ownership_state='TARGET_MANAGED'
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PROTECTED_TARGET_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.invoice_lines invoice_line
      where invoice_line.timesheet_id=any(v_family)
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.timesheets timesheet_row
      where timesheet_row.timesheet_id=v_root.root_timesheet_id
        and timesheet_row.active_document_operation_id is not null
    ) or exists(
      select 1 from public.invoice_operations operation
      where operation.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and operation.entity_type='TIMESHEET'
        and operation.entity_id=v_root.root_timesheet_id
    ) or exists(
      select 1 from public.invoice_operation_chunks chunk
      where chunk.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and chunk.entity_type='TIMESHEET'
        and chunk.entity_id=v_root.root_timesheet_id
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_INVOICE_OPERATION'
        using errcode='55000';
    end if;
    v_root_preflight:=public.import_timesheet_financial_preflight_v1(
      array[v_root.root_timesheet_id],
      'WEEKLY_SOURCE_CORRECT_FINAL_SOURCE',v_actor,'{}'::jsonb,true,1
    );
    if coalesce((v_root_preflight->>'blocking_batch_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_PAY_DRAFT'
        using errcode='55000',detail=v_root_preflight::text;
    elsif coalesce((v_root_preflight->>'paid_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_PAID'
        using errcode='55000',detail=v_root_preflight::text;
    elsif coalesce((v_root_preflight->>'invoice_lined_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000',detail=v_root_preflight::text;
    elsif coalesce((v_root_preflight->>'allowed')::boolean,false) is not true
       or v_root_preflight->>'required_path' not in (
         -- Gate 2 / XSG-032, the same rule at COMMITTING time.
         'DIRECT_AMEND_RECALCULATE'
       ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_NOT_MUTABLE'
        using errcode='55000',detail=v_root_preflight::text;
    end if;
  end loop;

  update public.weekly_final_source_correction_sessions
  set state='COMMITTING',apply_idempotency_key=v_idempotency_key,
      apply_request_hash=v_apply_request_hash,reason=v_reason,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='PREPARED' and version=v_expected_session_version
    and prepared_final_revision_id=v_prepared_revision.id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;

  update public.weekly_source_expense_materialisations materialisation
  set state='SUPERSEDED'
  where materialisation.state='MATERIALISED'
    and materialisation.expense_authority_generation_id in (
      select expense.id from public.weekly_expense_authority_generations expense
      where expense.final_revision_id=v_prior_revision.id and expense.state='CURRENT'
    );

  -- Expense authority is activated in the same CAS as source authority.  The
  -- prepared generation wins where one exists; otherwise correcting away an
  -- erroneous same-cycle generation restores its exact predecessor (or zero
  -- when there was no predecessor).
  update public.weekly_expense_authority_generations current_expense
  set state='SUPERSEDED'
  where current_expense.state='CURRENT'
    and current_expense.work_event_id in (
      select old_expense.work_event_id
      from public.weekly_expense_authority_generations old_expense
      where old_expense.final_revision_id=v_prior_revision.id
      union
      select prepared_expense.work_event_id
      from public.weekly_expense_authority_generations prepared_expense
      where prepared_expense.final_revision_id=v_prepared_revision.id
        and prepared_expense.state='PREPARED'
    );
  update public.weekly_expense_authority_generations prepared_expense
  set state='CURRENT'
  where prepared_expense.final_revision_id=v_prepared_revision.id
    and prepared_expense.state='PREPARED';
  update public.weekly_expense_authority_generations baseline_expense
  set state='CURRENT'
  where baseline_expense.state='SUPERSEDED'
    and baseline_expense.id in (
      select old_expense.prior_expense_authority_generation_id
      from public.weekly_expense_authority_generations old_expense
      where old_expense.final_revision_id=v_prior_revision.id
        and old_expense.prior_expense_authority_generation_id is not null
        and not exists(
          select 1
          from public.weekly_expense_authority_generations prepared_expense
          where prepared_expense.final_revision_id=v_prepared_revision.id
            and prepared_expense.work_event_id=old_expense.work_event_id
            and prepared_expense.state='CURRENT'
        )
    );

  perform pg_catalog.set_config(
    'cloudtms.weekly_source_correction_owner',
    'weekly_source_correct_final_apply_atomic_v1',true
  );
  select pg_catalog.count(*)::integer into v_old_movement_count
  from public.weekly_source_billing_movements
  where final_revision_id=v_prior_revision.id;
  if exists(
    select 1 from public.weekly_source_billing_movements
    where final_revision_id=v_prior_revision.id and placement_state<>'UNPLACED'
  ) or exists(
    select 1 from public.weekly_source_billing_movements
    where final_revision_id=v_prepared_revision.id and placement_state<>'UNPLACED'
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_MOVEMENT_STATE_STALE' using errcode='40001';
  end if;
  update public.weekly_source_billing_movements
  set placement_state='VOIDED_BY_CORRECT_FINAL'
  where final_revision_id=v_prior_revision.id and placement_state='UNPLACED';
  get diagnostics v_voided_count=row_count;
  if v_voided_count<>v_old_movement_count then
    raise exception 'WEEKLY_SOURCE_CORRECTION_MOVEMENT_CAS_LOST' using errcode='40001';
  end if;
  update public.weekly_source_final_revisions
  set state='SUPERSEDED' where id=v_prior_revision.id and state='CURRENT';
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_CAS_LOST' using errcode='40001';
  end if;
  update public.weekly_source_final_revisions
  set state='CURRENT' where id=v_prepared_revision.id and state='PREPARED';
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_REVISION_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_uploads set state='SUPERSEDED'
  where id=v_prior_upload.id and state='CURRENT';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PRIOR_UPLOAD_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_projection_publications
  set state='STALE',failure_code='SUPERSEDED_BY_CORRECT_FINAL_SOURCE'
  where id=v_prior_publication.id and state='CURRENT';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PRIOR_PUBLICATION_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_uploads set state='CURRENT'
  where id=v_replacement_upload.id and state='CORRECTION_READY';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_UPLOAD_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_projection_publications set state='CURRENT'
  where id=v_replacement_publication.id and state='CORRECTION_READY';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_PUBLICATION_CAS_LOST'
      using errcode='40001';
  end if;

  if v_session.authority_scope_kind='CYCLE' then
    update public.weekly_source_cycles
    set current_complete_upload_id=v_replacement_upload.id,
        current_projection_publication_id=v_replacement_publication.id,
        current_final_revision_id=v_prepared_revision.id,projection_state='CURRENT',
        state='FINALISED',finalised_at_utc=pg_catalog.transaction_timestamp(),
        finalised_by_user_id=v_actor
    where id=v_cycle.id
      and current_complete_upload_id=v_prior_upload.id
      and current_projection_publication_id=v_prior_publication.id
      and current_final_revision_id=v_prior_revision.id
      and version=v_scope_version;
  else
    update public.weekly_source_report_scopes
    set current_complete_upload_id=v_replacement_upload.id,
        current_projection_publication_id=v_replacement_publication.id,
        current_final_revision_id=v_prepared_revision.id,projection_state='CURRENT',
        state='FINALISED',updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_scope.id
      and current_complete_upload_id=v_prior_upload.id
      and current_projection_publication_id=v_prior_publication.id
      and current_final_revision_id=v_prior_revision.id
      and version=v_scope_version;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_AUTHORITY_CAS_LOST' using errcode='40001';
  end if;
  v_new_revision_id:=v_prepared_revision.id;

  -- APPLIED replay returned earlier; only the successful new CURRENT CAS
  -- resolves report-contained manual queries before the existing selector.
  -- Keep the completion receipt below that selector in its original order.
  perform private.weekly_source_manual_reviews_finalised_v1(v_new_revision_id,v_actor);

  -- Source old/new and cycle/report CURRENT CAS succeeded. Retract only the
  -- exact old captured revision, publish genuine new origins, and retain an
  -- explicit new observation even for an empty correction. Outside readers
  -- cannot observe this intermediate state: it is the same owner transaction.
  if (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    perform private.bpay_next_source_current_apply_correction_v1(v_session.id);
  end if;

  update public.weekly_source_client_cycle_completions completion
  set state='SUPERSEDED',superseded_at_utc=pg_catalog.transaction_timestamp()
  where completion.source_cycle_id=v_cycle.id
    and completion.client_id=v_client_id and completion.state='CURRENT';
  select coalesce(pg_catalog.max(completion.completion_generation),0)+1
  into v_completion_generation
  from public.weekly_source_client_cycle_completions completion
  where completion.source_cycle_id=v_cycle.id and completion.client_id=v_client_id;
  v_completion_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CLIENT_CYCLE_COMPLETION_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
      'client_id',v_client_id,'completion_generation',v_completion_generation,
      'completion_kind','FINAL_SOURCE','final_revision_id',v_new_revision_id,
      'actor_user_id',v_actor
    )
  );
  insert into public.weekly_source_client_cycle_completions(
    source_cycle_id,source_group_id,client_id,completion_generation,
    completion_kind,final_revision_id,attested_by_user_id,attested_at_utc,
    attestation_text,completion_hash,state
  ) values (
    v_cycle.id,v_group.id,v_client_id,v_completion_generation,
    'FINAL_SOURCE',v_new_revision_id,v_actor,pg_catalog.transaction_timestamp(),
    null,v_completion_hash,'CURRENT'
  );
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    if not exists(
      select 1
      from public.weekly_source_group_clients membership
      where membership.source_group_id=v_group.id
        and v_cycle.finalisation_week_ending between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
        and not exists(
          select 1
          from public.weekly_source_client_cycle_completions completion
          where completion.source_cycle_id=v_cycle.id
            and completion.client_id=membership.client_id
            and completion.state='CURRENT'
        )
    ) then
      update public.weekly_source_cycles
      set state='FINALISED',finalised_at_utc=pg_catalog.transaction_timestamp(),
          finalised_by_user_id=v_actor
      where id=v_cycle.id;
    else
      update public.weekly_source_cycles set state='FINALISABLE'
      where id=v_cycle.id;
    end if;
  end if;

  for v_root in
    select (server_root.value->>'root_timesheet_id')::uuid as root_timesheet_id,
           (server_root.value->>'prior_projection_receipt_id')::uuid as prior_receipt_id,
           server_root.value->>'source_profile_kind' as source_profile_kind,
           server_root.value->>'source_mode' as source_mode,
           supplied.value->'service_snapshot' as service_snapshot
    from pg_catalog.jsonb_array_elements(v_server_roots) server_root(value)
    join pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
      on supplied.value->>'root_timesheet_id'=server_root.value->>'root_timesheet_id'
    order by server_root.value->>'root_timesheet_id'
  loop
    v_prior_receipt:=null;
    if v_root.prior_receipt_id is not null then
      select * into strict v_prior_receipt
      from public.weekly_source_ordinary_pay_projection_receipts
      where id=v_root.prior_receipt_id;
      if v_prior_receipt.final_revision_id is distinct from v_prior_revision.id
         or v_prior_receipt.root_timesheet_id is distinct from v_root.root_timesheet_id
         or v_prior_receipt.outcome not in ('PREPARED_FOR_AUTHORISATION','PROPOSED') then
        raise exception 'WEEKLY_SOURCE_CORRECTION_PRIOR_ROOT_RECEIPT_STALE'
          using errcode='40001';
      end if;
    end if;
    v_impact_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CORRECT_FINAL_ROOT_IMPACT_V1',
      pg_catalog.jsonb_build_object(
        'correction_session_id',v_session.id,
        'prior_final_revision_id',v_prior_revision.id,
        'replacement_final_revision_id',v_new_revision_id,
        'root_timesheet_id',v_root.root_timesheet_id,
        'prior_projection_receipt_id',v_root.prior_receipt_id,
        'client_id',v_client_id,
        'source_profile_kind',v_root.source_profile_kind,
        'source_mode',v_root.source_mode,
        'submitted_service_snapshot_hash',pg_catalog.encode(
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_ORDINARY_SERVICE_SNAPSHOT_V1',v_root.service_snapshot
          ),'hex'
        )
      )
    );
    insert into public.weekly_final_source_correction_root_impacts(
      correction_session_id,prior_final_revision_id,replacement_final_revision_id,
      root_timesheet_id,prior_projection_receipt_id,client_id,source_profile_kind,
      source_mode,impact_kind,submitted_service_snapshot_hash,impact_hash
    ) values (
      v_session.id,v_prior_revision.id,v_new_revision_id,v_root.root_timesheet_id,
      v_root.prior_receipt_id,v_client_id,v_root.source_profile_kind,v_root.source_mode,
      case when v_root.prior_receipt_id is null
        then 'PUBLISHED_REPLACEMENT_ONLY_ROOT'
        when exists(
        select 1 from public.weekly_source_billing_movements movement
        where movement.final_revision_id=v_new_revision_id
          and movement.invoice_timesheet_id=v_root.root_timesheet_id
      ) then 'REPROJECTED_WITH_CURRENT_REVISION_MOVEMENTS'
        else 'REPROJECTED_WITHOUT_CURRENT_REVISION_MOVEMENTS' end,
      private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_ORDINARY_SERVICE_SNAPSHOT_V1',v_root.service_snapshot
      ),v_impact_hash
    );
    v_projection_result:=public.weekly_source_ordinary_pay_projection_apply_atomic_v1(
      pg_catalog.jsonb_build_object(
        'schema_version','WEEKLY_SOURCE_ORDINARY_PAY_PROJECTION_REQUEST_V1',
        'actor_user_id',v_actor,'final_revision_id',v_new_revision_id,
        'root_timesheet_id',v_root.root_timesheet_id,
        'idempotency_key','correct-final:'||v_session.id::text||':'||v_root.root_timesheet_id::text,
        'service_snapshot',v_root.service_snapshot
      )
    );
    -- Gate 2: the projection no longer publishes.  The only outcome reachable
    -- from here is PREPARED_FOR_AUTHORISATION, because the gates above now
    -- admit DIRECT_AMEND_RECALCULATE only, i.e. a root that is not yet
    -- authorised.  Anything else means the root moved under us.
    if v_projection_result->>'outcome'<>'PREPARED_FOR_AUTHORISATION' then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_REPROJECT_FAILED'
        using errcode='55000',detail=v_projection_result::text;
    end if;
  end loop;

  v_result:=(v_session.prepare_result_json-'root_contexts')||pg_catalog.jsonb_build_object(
    'status','CORRECTED','correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'affected_root_count',pg_catalog.jsonb_array_length(v_server_roots),
    'version',v_expected_session_version+2,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='APPLIED',applied_final_revision_id=v_new_revision_id,
      result_json=v_result,result_hash=v_result_hash,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp(),
      completed_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='COMMITTING';
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_APPLIED',
         pg_catalog.jsonb_build_object(
           'state','CURRENT','final_revision_id',v_prior_revision.id,
           'upload_id',v_prior_upload.id,'projection_publication_id',v_prior_publication.id
         ),
         pg_catalog.jsonb_build_object(
           'state','APPLIED','final_revision_id',v_new_revision_id,
           'upload_id',v_replacement_upload.id,
           'projection_publication_id',v_replacement_publication.id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_server_roots),
           'voided_prior_movement_count',v_voided_count,
           'result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function private.weekly_source_office_query_groups_v1(
  p_source_cycle_id uuid,
  p_projection_publication_id uuid,
  p_filters jsonb default '{}'::jsonb
) returns table(
  group_key text,
  candidate_id uuid,
  client_id uuid,
  manager_recipient_route_key bytea,
  candidate_name text,
  client_name text,
  incident_ids uuid[],
  accept_incident_ids uuid[],
  missing_scopes jsonb,
  children jsonb,
  issue_count integer,
  candidate_asked boolean,
  manager_informed boolean,
  outreach_eligible boolean,
  manager_eligible boolean,
  candidate_app_available boolean,
  first_seen_at_utc timestamptz,
  status_text text,
  status_tone text,
  issue_summary text
)
language sql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
  with cycle_context as (
    select cycle.id,cycle.source_group_id,cycle.finalisation_week_ending,
      source_group.environment,source_group.agency_id,source_group.source_family,
      publication.upload_id,
      current_upload.source_format_profile_id,
      current_profile.profile_code
    from public.weekly_source_cycles cycle
    join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
    join public.weekly_source_projection_publications publication
      on publication.id=p_projection_publication_id
     and publication.source_cycle_id=cycle.id
     and publication.state='CURRENT'
    join public.weekly_source_uploads current_upload
      on current_upload.id=publication.upload_id
    join public.weekly_source_format_profiles current_profile
      on current_profile.id=current_upload.source_format_profile_id
    where cycle.id=p_source_cycle_id
  ), incident_facts as (
    select incident.id incident_id,incident.candidate_id,incident.client_id,
      incident.work_event_id,cycle_context.source_group_id,
      incident.candidate_action_state,incident.manager_action_state,
      incident.manager_potential_state,incident.created_at_utc,
      comparison.issue_family,comparison.contract_id,
      comparison.candidate_timesheet_id,comparison.source_presence,comparison.source_row_id,
      comparison.candidate_start_at_local,comparison.candidate_end_at_local,
      comparison.candidate_break_minutes,comparison.system_start_at_local,
      comparison.system_end_at_local,comparison.system_break_minutes,
      work_event.work_date,contract.role job_role,route_context.value route_context,
      candidate_reply.bounded_payload_json->>'choice' candidate_reply_choice,
      candidate_reply.occurred_at_utc candidate_replied_at,
      candidate_delivery.contacted_at_utc candidate_contacted_at,
      manager_reply.bounded_payload_json->>'response_kind' manager_reply_kind,
      manager_reply.occurred_at_utc manager_replied_at,
      manager_delivery.contacted_at_utc manager_contacted_at,
      manager_item.intended_start_at_local,manager_item.intended_end_at_local,
      manager_item.intended_break_minutes
    from cycle_context
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cycle_context.id and incident.state='OPEN'
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
    join public.weekly_source_uploads comparison_upload
      on comparison_upload.id=comparison.comparison_upload_id
    join public.weekly_work_events work_event on work_event.id=incident.work_event_id
    left join public.contracts contract on contract.id=comparison.contract_id
    -- Replies belong to the current incident episode. A prior question's answer
    -- must never be presented as the answer to materially changed hours.
    left join lateral (
      select event.bounded_payload_json,event.occurred_at_utc
      from public.weekly_discrepancy_events event
      where event.incident_id=incident.id and event.issue_episode=incident.episode_number
        and event.event_kind='CANDIDATE_RESPONDED'
        and incident.candidate_action_state='RESPONDED'
      order by event.occurred_at_utc desc,event.id desc limit 1
    ) candidate_reply on true
    left join lateral (
      select min(command.provider_accepted_at_utc) contacted_at_utc
      from public.weekly_candidate_outreach_memberships membership
      join public.weekly_message_dispatch_commands command
        on command.candidate_generation_id=membership.candidate_generation_id
        and command.state='ACCEPTED'
      where membership.incident_id=incident.id
        and membership.comparison_revision_id=incident.current_comparison_revision_id
    ) candidate_delivery on true
    left join lateral (
      select event.bounded_payload_json,event.occurred_at_utc
      from public.weekly_discrepancy_events event
      where event.incident_id=incident.id and event.issue_episode=incident.episode_number
        and event.event_kind='MANAGER_RESPONDED'
        and incident.manager_action_state='RESPONDED'
      order by event.occurred_at_utc desc,event.id desc limit 1
    ) manager_reply on true
    left join lateral (
      select min(command.provider_accepted_at_utc) contacted_at_utc
      from public.weekly_manager_review_items review_item
      join public.weekly_manager_review_batches review_batch on review_batch.id=review_item.review_batch_id
      join public.weekly_message_dispatch_commands command
        on command.message_render_id=review_batch.message_render_id
        and command.state='ACCEPTED'
      where review_item.incident_id=incident.id
        and review_item.incident_episode=incident.episode_number
    ) manager_delivery on true
    left join public.weekly_manager_review_items manager_item
      on manager_item.id=nullif(manager_reply.bounded_payload_json->>'review_item_id','')::uuid
      and manager_item.incident_id=incident.id
      and manager_item.incident_episode=incident.episode_number
    cross join lateral (
      select private.weekly_source_office_route_key_v1(
        incident.source_cycle_id,incident.candidate_id,incident.client_id,
        comparison.contract_id,work_event.work_date
      ) value
    ) route_context
    -- A provisional comparison can remain byte-for-byte unchanged when a new
    -- file covers its date. Its immutable revision still names the prior
    -- publication; visibility is based on the OPEN incident, not a rewrite of
    -- that revision or a second notification clock.
    where comparison.issue_family<>'CANDIDATE_TIMESHEET_MISSING'
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and (comparison.projection_publication_id=p_projection_publication_id
        or (cycle_context.profile_code='NHSP_PREFINAL_RELEASED_V1'
          and comparison_upload.source_cycle_id=cycle_context.id
          and comparison_upload.source_format_profile_id=cycle_context.source_format_profile_id))
  ), manual_facts as (
    select review.*,current_row.id current_source_row_id,
      current_row.normalised_row_hash current_source_row_hash,
      current_row.start_at_local,current_row.end_at_local,
      current_row.break_minutes,contract.role job_role,
      coalesce(nullif(office_user.display_name,''),'Office user') opened_by_name,
      route_context.value route_context
    from cycle_context
    join private.weekly_source_manual_reviews review
      on review.source_cycle_id=cycle_context.id and review.state='OPEN'
    join public.weekly_source_upload_rows source_row on source_row.id=review.upload_row_id
    join public.contracts contract on contract.id=review.contract_id
    left join public.tms_users office_user on office_user.id=review.opened_by_user_id
    left join lateral (
      select candidate_row.*
      from public.weekly_source_upload_rows candidate_row
      join public.weekly_source_uploads candidate_upload on candidate_upload.id=candidate_row.upload_id
      join lateral (
        select mapping.work_event_id,mapping.mapping_state
        from public.weekly_source_row_resolutions mapping
        where mapping.upload_row_id=candidate_row.id
        order by mapping.generation desc,mapping.id desc limit 1
      ) current_mapping on current_mapping.work_event_id=review.work_event_id
        and current_mapping.mapping_state='RESOLVED'
      where candidate_upload.source_cycle_id=review.source_cycle_id
        and candidate_row.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED')
        and (
          exists(select 1 from public.weekly_source_client_manifests manifest
            join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
            where manifest.source_cycle_id=review.source_cycle_id
              and manifest.client_id=review.client_id
              and revision.state='CURRENT' and revision.upload_id=candidate_upload.id)
          or (not exists(select 1 from public.weekly_source_client_manifests manifest
              join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
              where manifest.source_cycle_id=review.source_cycle_id
                and manifest.client_id=review.client_id and revision.state='CURRENT')
            and exists(select 1 from public.weekly_source_projection_publications publication
              where publication.source_cycle_id=review.source_cycle_id
                and publication.upload_id=candidate_upload.id and publication.state='CURRENT'))
        )
      order by candidate_row.created_at_utc desc,candidate_row.id desc limit 1
    ) current_row on true
    cross join lateral (select private.weekly_source_office_route_key_v1(
      review.source_cycle_id,review.candidate_id,review.client_id,
      review.contract_id,review.work_date) value) route_context
  ), missing_rows as (
    select cycle_context.id source_cycle_id,
      resolution.candidate_id,resolution.client_id,resolution.contract_id,
      row.id source_row_id,row.normalised_row_hash,row.work_date,
      row.start_at_local,row.end_at_local,row.break_minutes,row.actual_net_minutes,
      row.row_finalisation_state,row.created_at_utc,resolution.id row_resolution_id,
      resolution.work_event_id,resolution.source_row_fingerprint,
      resolution.contract_and_rate_fingerprint,resolution.effective_policy_fingerprint,
      (date_trunc('week',row.work_date)::date+6) week_ending,
      coalesce(lineage.timesheet_id,root_contract_week.timesheet_id) timesheet_id,
      route_context.value route_context
    from cycle_context
    join public.weekly_source_upload_rows row on row.upload_id=cycle_context.upload_id
    join lateral (
      select candidate.* from public.weekly_source_row_resolutions candidate
      where candidate.upload_row_id=row.id
      order by candidate.generation desc,candidate.id desc limit 1
    ) resolution on resolution.mapping_state='RESOLVED'
    left join public.weekly_source_row_timesheet_lineages lineage
      on lineage.row_resolution_id=resolution.id
    left join lateral (
      select contract_week.timesheet_id
      from public.contract_weeks contract_week
      where contract_week.contract_id=resolution.contract_id
        and contract_week.week_ending_date=(date_trunc('week',row.work_date)::date+6)
        and contract_week.additional_seq=0
        and not contract_week.is_adjustment
        and contract_week.status<>'CANCELLED'::public.contract_week_status_enum
      order by contract_week.created_at desc,contract_week.id desc
      limit 1
    ) root_contract_week on true
    left join public.timesheets timesheet
      on timesheet.timesheet_id=coalesce(lineage.timesheet_id,root_contract_week.timesheet_id)
     and timesheet.is_current and timesheet.revoked_at is null
     and timesheet.archived_at_utc is null
     and timesheet.sheet_scope='WEEKLY' and timesheet.line_type='HOURS'
    cross join lateral (
      select private.weekly_source_office_route_key_v1(
        cycle_context.id,resolution.candidate_id,resolution.client_id,
        resolution.contract_id,row.work_date
      ) value
    ) route_context
    where row.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED')
      and row.actual_net_minutes>0
      and not exists (
        select 1 from public.weekly_source_client_manifests manifest
        join public.weekly_source_final_revisions final_revision
          on final_revision.id=manifest.final_revision_id
        where manifest.source_cycle_id=cycle_context.id
          and manifest.client_id=resolution.client_id
          and final_revision.state='CURRENT'
      )
      and route_context.value->>'authority_mode'='SOURCE_AUTHORITY'
      and route_context.value->>'document_mode'='CHECK_ONLY'
      and (timesheet.timesheet_id is null
        or timesheet.r2_nurse_key is null or timesheet.img_sha256_nurse is null)
  ), missing_scopes as (
    select missing_rows.source_cycle_id,missing_rows.candidate_id,
      missing_rows.client_id,missing_rows.contract_id,missing_rows.week_ending,
      min(missing_rows.work_date) first_work_date,
      (pg_catalog.array_agg(missing_rows.source_row_id order by
        missing_rows.work_date,missing_rows.start_at_local,
        missing_rows.end_at_local,missing_rows.source_row_id))[1] first_source_row_id,
      min(missing_rows.created_at_utc) first_seen_at_utc,
      (min(missing_rows.route_context->>'route_key'))::text route_key_hex,
      bool_and(coalesce((missing_rows.route_context->>'candidate_queries_enabled')::boolean,false))
        candidate_queries_enabled,
      private.weekly_source_office_missing_scope_fingerprint_v1(
        p_projection_publication_id,missing_rows.candidate_id,missing_rows.client_id,
        missing_rows.contract_id,missing_rows.week_ending
      ) expected_source_fingerprint,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'incident_id',null,'row_key','missing-'||missing_rows.source_row_id::text,
        'day_date',to_char(missing_rows.work_date,'Dy FMDD Mon YYYY'),
        'job_role',coalesce(contract.role,''),
        'candidate_hours','Timesheet not submitted',
        'system_hours',case when missing_rows.start_at_local is null then pg_catalog.chr(8212)
          else to_char(missing_rows.start_at_local,'HH24:MI')||'-'||to_char(missing_rows.end_at_local,'HH24:MI') end,
        'issue','Timesheet missing',
        'status',pg_catalog.jsonb_build_object('text','Waiting for Timesheet','tone','warning'),
        'accept_eligible',false,'actions',pg_catalog.jsonb_build_array('View details')
      ) order by missing_rows.work_date,missing_rows.start_at_local,
        missing_rows.end_at_local,missing_rows.source_row_id) children
    from missing_rows
    join public.contracts contract on contract.id=missing_rows.contract_id
    group by missing_rows.source_cycle_id,missing_rows.candidate_id,
      missing_rows.client_id,missing_rows.contract_id,missing_rows.week_ending
  ), incident_grouped as (
    select (incident_facts.route_context->>'group_key')::text group_key,
      incident_facts.candidate_id,incident_facts.client_id,
      pg_catalog.decode(incident_facts.route_context->>'route_key','hex') manager_recipient_route_key,
      pg_catalog.array_agg(incident_facts.incident_id order by incident_facts.incident_id) incident_ids,
      coalesce(pg_catalog.array_agg(incident_facts.incident_id order by incident_facts.incident_id)
        filter (where incident_facts.route_context->>'authority_mode'='SOURCE_AUTHORITY'),'{}'::uuid[])
        accept_incident_ids,
      min(incident_facts.created_at_utc) first_seen_at_utc,
      bool_or(incident_facts.candidate_action_state in ('ASKED','RESPONDED')) candidate_asked,
      bool_or(incident_facts.manager_action_state in ('SENT','RESPONDED')) manager_informed,
      bool_and(coalesce((incident_facts.route_context->>'candidate_queries_enabled')::boolean,false))
        candidate_queries_enabled,
      bool_and(coalesce((incident_facts.route_context->>'manager_queries_enabled')::boolean,false)
        and coalesce((incident_facts.route_context->>'manager_recipient_present')::boolean,false))
        manager_queries_enabled,
      bool_and(incident_facts.candidate_timesheet_id is not null
        and incident_facts.manager_potential_state='AVAILABLE'
        and incident_facts.manager_action_state not in ('RESPONDED','NOT_REQUIRED')) manager_eligible,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'incident_id',incident_facts.incident_id,
        'candidate_shift_absent_from_import',incident_facts.issue_family='SOURCE_MISSING_OR_NOT_AUTHORISED'
          and incident_facts.source_presence='ABSENT' and incident_facts.source_row_id is null
          and incident_facts.candidate_timesheet_id is not null
          and incident_facts.candidate_start_at_local is not null
          and incident_facts.candidate_end_at_local>incident_facts.candidate_start_at_local,
        'candidate_response',case incident_facts.candidate_reply_choice
          when 'CANDIDATE_CORRECT' then 'My hours are correct'
          when 'CANDIDATE_WRONG' then 'Accepted system hours'
          when 'NEITHER_CORRECT' then 'Submitted corrected hours'
          else null end,
        'candidate_responded_at',to_char(incident_facts.candidate_replied_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'candidate_contacted_at',to_char(incident_facts.candidate_contacted_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'manager_response',case incident_facts.manager_reply_kind
          when 'SYSTEM_CORRECT' then 'System hours are correct'
          when 'CANDIDATE_DID_NOT_WORK' then 'Candidate did not work'
          when 'MANAGER_CORRECTED_SOURCE' then 'Reported a source correction'
          else null end,
        'manager_responded_at',to_char(incident_facts.manager_replied_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'manager_contacted_at',to_char(incident_facts.manager_contacted_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
        'manager_intended_hours',case when incident_facts.manager_reply_kind='MANAGER_CORRECTED_SOURCE'
          then to_char(incident_facts.intended_start_at_local,'HH24:MI')||'-'||to_char(incident_facts.intended_end_at_local,'HH24:MI')
            ||' ('||incident_facts.intended_break_minutes||' min break)' else null end,
        'protected_pay_seed',case when incident_facts.route_context->>'authority_mode'='SOURCE_AUTHORITY'
          then pg_catalog.jsonb_build_object('source_group_id',incident_facts.source_group_id,
            'client_id',incident_facts.client_id,'candidate_id',incident_facts.candidate_id,
            'work_event_id',incident_facts.work_event_id,'contract_id',incident_facts.contract_id,
            'work_date',incident_facts.work_date,
            'start',to_char(coalesce(incident_facts.candidate_start_at_local,incident_facts.system_start_at_local),'HH24:MI'),
            'end',to_char(coalesce(incident_facts.candidate_end_at_local,incident_facts.system_end_at_local),'HH24:MI'),
            'break_minutes',coalesce(incident_facts.candidate_break_minutes,incident_facts.system_break_minutes)) end,
        'row_key','incident-'||incident_facts.incident_id::text,
        'day_date',to_char(incident_facts.work_date,'Dy FMDD Mon YYYY'),
        'job_role',coalesce(incident_facts.job_role,''),
        'candidate_hours',case when incident_facts.candidate_start_at_local is null then 'Timesheet not submitted'
          else to_char(incident_facts.candidate_start_at_local,'HH24:MI')||'-'||to_char(incident_facts.candidate_end_at_local,'HH24:MI')
            ||case when incident_facts.candidate_break_minutes is null then '' else ' ('||incident_facts.candidate_break_minutes||' min break)' end end,
        'system_hours',case when incident_facts.source_presence<>'PRESENT' then 'Not included'
          else to_char(incident_facts.system_start_at_local,'HH24:MI')||'-'||to_char(incident_facts.system_end_at_local,'HH24:MI')
            ||case when incident_facts.system_break_minutes is null then '' else ' ('||incident_facts.system_break_minutes||' min break)' end end,
        'issue',case incident_facts.issue_family
          when 'SOURCE_HOURS_DIFFER' then 'Hours differ'
          when 'SOURCE_MISSING_OR_NOT_AUTHORISED' then 'Missing or not yet authorised'
          when 'REFERENCE_MISSING' then 'Reference missing'
          when 'HEALTHROSTER_NOT_FINALISED' then 'Not finalised'
          else 'Needs review' end,
        'status',pg_catalog.jsonb_build_object(
          'text',case when incident_facts.manager_action_state='RESPONDED' then 'Manager responded'
            when incident_facts.manager_action_state='SENT' then 'Manager informed'
            when incident_facts.candidate_action_state='RESPONDED' then 'Candidate responded'
            when incident_facts.candidate_action_state='ASKED' then 'Candidate asked' else 'Needs action' end,
          'tone',case when incident_facts.candidate_action_state='NOT_ASKED' then 'warning' else 'info' end
        ),'accept_eligible',incident_facts.route_context->>'authority_mode'='SOURCE_AUTHORITY',
        'actions',pg_catalog.jsonb_build_array('View details')
      ) order by incident_facts.work_date,
        coalesce(incident_facts.system_start_at_local,incident_facts.candidate_start_at_local),
        incident_facts.incident_id) children,
      pg_catalog.string_agg(distinct case incident_facts.issue_family
        when 'SOURCE_HOURS_DIFFER' then 'Hours differ'
        when 'SOURCE_MISSING_OR_NOT_AUTHORISED' then 'Missing or not yet authorised'
        when 'REFERENCE_MISSING' then 'Reference missing'
        when 'HEALTHROSTER_NOT_FINALISED' then 'Not finalised'
        else 'Needs review' end,', ' order by case incident_facts.issue_family
        when 'SOURCE_HOURS_DIFFER' then 'Hours differ'
        when 'SOURCE_MISSING_OR_NOT_AUTHORISED' then 'Missing or not yet authorised'
        when 'REFERENCE_MISSING' then 'Reference missing'
        when 'HEALTHROSTER_NOT_FINALISED' then 'Not finalised'
        else 'Needs review' end) issue_summary
    from incident_facts
    group by incident_facts.route_context->>'group_key',incident_facts.candidate_id,
      incident_facts.client_id,incident_facts.route_context->>'route_key'
  ), manual_grouped as (
    select (manual.route_context->>'group_key')::text group_key,
      manual.candidate_id,manual.client_id,
      pg_catalog.decode(manual.route_context->>'route_key','hex') manager_recipient_route_key,
      count(*)::integer review_count,min(manual.opened_at_utc) first_seen_at_utc,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'manual_review_id',manual.id,'incident_id',null,
        'source_row_id',manual.current_source_row_id,
        'current_source_row_hash',pg_catalog.encode(manual.current_source_row_hash,'hex'),
        'row_key','manual-'||manual.id::text,
        'day_date',to_char(manual.work_date,'Dy FMDD Mon YYYY'),
        'job_role',manual.job_role,
        'candidate_hours','See candidate Timesheet',
        'system_hours',case when manual.current_source_row_id is null then 'Not in current import'
          else to_char(manual.start_at_local,'HH24:MI')||'-'||
            to_char(manual.end_at_local,'HH24:MI')||' ('||manual.break_minutes||' min break)' end,
        'issue','Manually queried',
        'manual_query',pg_catalog.jsonb_build_object(
          'opened_by',manual.opened_by_name,
          'opened_at_uk',to_char(manual.opened_at_utc at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
          'reason',manual.office_reason),
        'status',pg_catalog.jsonb_build_object('text','Office review','tone','danger'),
        'accept_eligible',false,
        'protected_pay_seed',pg_catalog.jsonb_build_object(
          'source_group_id',manual.source_group_id,
          'client_id',manual.client_id,'candidate_id',manual.candidate_id,
          'work_event_id',manual.work_event_id,'contract_id',manual.contract_id,
          'manual_review_id',manual.id,
          'work_date',manual.work_date,'start',to_char(manual.start_at_local,'HH24:MI'),
          'end',to_char(manual.end_at_local,'HH24:MI'),
          'break_minutes',manual.break_minutes),
        'actions','[]'::jsonb
      ) order by manual.work_date,manual.start_at_local,manual.id) children
    from manual_facts manual
    group by manual.route_context->>'group_key',manual.candidate_id,
      manual.client_id,manual.route_context->>'route_key'
  ), missing_grouped as (
    select private.weekly_source_office_group_key_v1(
        scope.source_cycle_id,scope.candidate_id,scope.client_id,
        pg_catalog.decode(scope.route_key_hex,'hex')
      ) group_key,
      scope.candidate_id,scope.client_id,
      pg_catalog.decode(scope.route_key_hex,'hex') manager_recipient_route_key,
      pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'week_ending',scope.week_ending,'client_id',scope.client_id,
        'contract_id',scope.contract_id,
        'expected_source_fingerprint',pg_catalog.encode(scope.expected_source_fingerprint,'hex')
      ) order by scope.week_ending,scope.client_id,scope.contract_id) scopes,
      min(scope.first_seen_at_utc) first_seen_at_utc,
      bool_and(scope.candidate_queries_enabled) candidate_queries_enabled,
      pg_catalog.jsonb_agg(child.value order by scope.week_ending,scope.contract_id,child.ordinality) children
    from missing_scopes scope
    cross join lateral pg_catalog.jsonb_array_elements(scope.children) with ordinality child(value,ordinality)
    group by scope.source_cycle_id,scope.candidate_id,scope.client_id,scope.route_key_hex
  ), combined as (
    select coalesce(incident.group_key,missing.group_key,manual.group_key) group_key,
      coalesce(incident.candidate_id,missing.candidate_id,manual.candidate_id) candidate_id,
      coalesce(incident.client_id,missing.client_id,manual.client_id) client_id,
      coalesce(incident.manager_recipient_route_key,missing.manager_recipient_route_key,
        manual.manager_recipient_route_key)
        manager_recipient_route_key,
      coalesce(incident.incident_ids,'{}'::uuid[]) incident_ids,
      coalesce(incident.accept_incident_ids,'{}'::uuid[]) accept_incident_ids,
      coalesce(missing.scopes,'[]'::jsonb) missing_scopes,
      coalesce(incident.children,'[]'::jsonb)||coalesce(missing.children,'[]'::jsonb)
        ||coalesce(manual.children,'[]'::jsonb) children,
      coalesce(pg_catalog.array_length(incident.incident_ids,1),0)
        +coalesce(pg_catalog.jsonb_array_length(missing.scopes),0)
        +coalesce(manual.review_count,0) issue_count,
      coalesce(incident.candidate_asked,false) candidate_asked,
      coalesce(incident.manager_informed,false) manager_informed,
      coalesce(incident.candidate_queries_enabled,true)
        and coalesce(missing.candidate_queries_enabled,true) candidate_queries_enabled,
      coalesce(incident.manager_eligible,false)
        and pg_catalog.jsonb_array_length(coalesce(missing.scopes,'[]'::jsonb))=0 manager_eligible,
      least(incident.first_seen_at_utc,missing.first_seen_at_utc,
        manual.first_seen_at_utc) first_seen_at_utc,
      case when manual.review_count>0 and (incident.group_key is not null or missing.group_key is not null)
        then 'Multiple' when manual.review_count>0 then 'Manually queried'
        else coalesce(incident.issue_summary,'Timesheet missing') end issue_summary
    from incident_grouped incident
    full join missing_grouped missing on missing.group_key=incident.group_key
    full join manual_grouped manual on manual.group_key=coalesce(incident.group_key,missing.group_key)
  ), named as (
    select combined.*,coalesce(nullif(candidate.display_name,''),
        nullif(pg_catalog.concat_ws(' ',candidate.first_name,candidate.last_name),''),
        candidate.tms_ref,'Candidate') candidate_name,
      client.name client_name,context.environment,
      (select count(*)=1
       from public.candidate_app_global_membership_links membership
       join public.candidate_app_accounts account on account.id=membership.account_id
       where membership.candidate_id=combined.candidate_id
         and membership.state='ACTIVE' and account.status='ACTIVE') candidate_app_available
    from combined
    join public.candidates candidate on candidate.id=combined.candidate_id
    join public.clients client on client.id=combined.client_id
    cross join cycle_context context
  )
  select named.group_key,named.candidate_id,named.client_id,
    named.manager_recipient_route_key,named.candidate_name,named.client_name,
    named.incident_ids,named.accept_incident_ids,named.missing_scopes,named.children,named.issue_count,
    named.candidate_asked,named.manager_informed,
    named.candidate_queries_enabled and named.candidate_app_available
      and (pg_catalog.cardinality(named.incident_ids)>0
        or pg_catalog.jsonb_array_length(named.missing_scopes)>0) outreach_eligible,
    named.manager_eligible,named.candidate_app_available,named.first_seen_at_utc,
    case when not named.candidate_app_available then 'Candidate app unavailable'
      when pg_catalog.jsonb_array_length(named.missing_scopes)>0 then 'Waiting for Timesheet'
      when named.manager_informed then 'Manager informed'
      when named.candidate_asked then 'Candidate asked' else 'Needs action' end status_text,
    case when not named.candidate_app_available then 'warning'
      when named.manager_informed or named.candidate_asked then 'info' else 'warning' end status_tone,
    named.issue_summary
  from named
  where coalesce(p_filters->>'status','UNRESOLVED') in ('UNRESOLVED','ALL')
    and (nullif(pg_catalog.btrim(coalesce(p_filters->>'candidate','')),'') is null
      or private.weekly_source_query_ascii_fold_v1(named.candidate_name)
        like '%'||private.weekly_source_query_ascii_fold_v1(p_filters->>'candidate')||'%')
    and (coalesce(p_filters->>'issue','ALL')='ALL'
      or (p_filters->>'issue'='TIMESHEET_MISSING' and pg_catalog.jsonb_array_length(named.missing_scopes)>0)
      or (p_filters->>'issue'='HOURS_DIFFER' and named.issue_summary like '%Hours differ%')
      or (p_filters->>'issue'='MISSING_SHIFT' and named.issue_summary like '%Missing%'));
$function$;

create or replace function public.weekly_source_correct_final_cancel_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_session_version',
    'idempotency_key','reason','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_expected_session_version bigint;
  v_idempotency_key text;
  v_reason text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_locked public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_client_id uuid;
  v_manifest_count bigint;
  v_state_before text;
  v_upload record;
  v_publication record;
  v_rejected_uploads integer:=0;
  v_superseded_uploads integer:=0;
  v_staled_publications integer:=0;
  v_live_uploads_before bigint;
  v_live_publications_before bigint;
  v_live_uploads_after bigint;
  v_live_publications_after bigint;
  v_rows integer;
  v_result jsonb;
  v_result_hash bytea;
begin
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_CANCEL_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_actor is null or v_session_id is null
     or v_expected_session_version is null or v_expected_session_version<1
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_CANCEL_V1',p_request-'idempotency_key'
  );

  -- Unlocked pre-read.  Its ONLY uses are (a) to answer an exact idempotent
  -- replay, which writes nothing, and (b) to learn which cycle row to lock
  -- first.  Every value this owner gates on is read again under the locks
  -- below, and the session's own scope identity is re-proved after the lock.
  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.state='CANCELLED'
     and v_session.result_json->>'cancel_idempotency_key'=v_idempotency_key then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.result_json->>'cancel_request_hash'
            is distinct from pg_catalog.encode(v_request_hash,'hex') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.result_json||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;

  -- Lock order, taken BEFORE any state this owner gates on is read.  It is the
  -- order the four installed lifecycle owners already use -- cycle, then report
  -- scope, then correction session, then the revision -- so a cancel racing a
  -- review, a prepare or an apply queues behind the same first lock instead of
  -- deadlocking against it.  WP-54 section 6.2's precondition list named only
  -- the session lock; that is not enough to be deadlock-compatible with the
  -- owners it has to race, and this owner follows the installed order instead.
  select * into v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
    if not found then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SCOPE_INVALID' using errcode='22023';
    end if;
  end if;
  select * into v_locked from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  v_session:=v_locked;

  -- The scope identity the locks were chosen from must still be the session's
  -- own.  If it moved across the lock the locks are the wrong ones and nothing
  -- read after them can be trusted, so fail closed rather than continue.
  if v_session.source_cycle_id is distinct from v_cycle.id
     or v_session.report_scope_id is distinct from v_scope.id
     or (v_session.authority_scope_kind='NHSP_REPORT_SCOPE')
          is distinct from (v_session.report_scope_id is not null) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  if v_session.version<>v_expected_session_version then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;

  -- Authority before disposition.  03 section 21 gives Correct final source the
  -- "same active administrator predicate" with "no invented high-risk
  -- permission", so cancel re-uses the CORRECT_FINAL_SOURCE verb through the
  -- installed evaluator and adds no new operation key.  An actor who fails here
  -- is told only that, and never learns the session's internal state.
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    v_client_id:=v_scope.client_id;
  else
    select pg_catalog.count(*) into v_manifest_count
    from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_session.expected_current_final_revision_id;
    if v_manifest_count<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CLIENT_SCOPE_INVALID' using errcode='55000';
    end if;
    select client_id into v_client_id
    from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_session.expected_current_final_revision_id;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  -- WHO MAY CANCEL -- owner decision D-WP59-1, taken conservatively.
  -- WP-54 section 6.2 offered three candidate policies and recommended the
  -- third (the opening actor always; another holder of the authority only after
  -- a stated idle interval) while refusing to invent the interval, because the
  -- pack does not state one.  It is still not stated anywhere in the pack, so
  -- this owner ships the policy that cannot be wrong: the opening actor only.
  -- That is also the policy every other stage of this lifecycle already
  -- enforces -- review, prepare and apply each require
  -- v_session.actor_user_id = the calling actor.  Widening it to a second
  -- holder of the authority is an owner decision and an additive change to this
  -- one test; it is NOT taken here.
  if v_session.actor_user_id is distinct from v_actor then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_ACTOR_NOT_OPENER'
      using errcode='42501',
        detail='Only the actor who opened this correction session may cancel it. '
               'A second holder of CORRECT_FINAL_SOURCE may not, because the idle '
               'interval that would make that claim auditable is not stated in the '
               'pack and has not been ruled.';
  end if;

  -- WHAT THE SESSION HAS ALREADY COMMITTED.  Establish it before releasing
  -- anything, and refuse rather than guess.  These six limbs are exhaustive
  -- over the ten declared states, and the last one is the fail-closed branch
  -- for a state this owner does not recognise.
  v_state_before:=v_session.state;
  if v_state_before='APPLIED' or v_session.applied_final_revision_id is not null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_APPLIED'
      using errcode='55000',
        detail='This correction has already replaced the final source authority. '
               'Cancelling it would claim to undo an applied correction.';
  end if;
  if v_state_before='COMMITTING' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_COMMIT_IN_FLIGHT'
      using errcode='55000',
        detail='A correction transaction is in flight. Cancelling it is how a '
               'half-applied correction is produced; this is a case for the '
               'existing failure path, not for cancel.';
  end if;
  if v_state_before='PREPARING' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_IN_FLIGHT'
      using errcode='55000',
        detail='PREPARE is in flight. Whether a replacement revision has been '
               'materialised cannot be established from this state, so cancel '
               'refuses rather than guess.';
  end if;
  if v_state_before='PREPARED' or v_session.prepared_final_revision_id is not null then
    -- Owner decision D-WP59-2, and a correction to WP-54 section 6.2.  That
    -- specification permits cancel from PREPARING and PREPARED and states that
    -- "then the active_uq index frees the scope and the next correction opens
    -- normally".  Executed, that is false.  PREPARE materialises an inactive
    -- replacement revision whose predecessor_revision_id is the prior CURRENT
    -- revision, and private.weekly_source_correct_final_preconditions_v1
    -- refuses any later correction while a descendant of that prior revision
    -- exists, whatever the descendant's own state and whatever happened to the
    -- session that made it.  Cancelling a PREPARED session would therefore
    -- release the session row and leave the Trust and cutoff blocked anyway --
    -- a cancel that promises a release it cannot deliver.
    -- Releasing it needs the descendant refusal to stop counting a cancelled
    -- session's superseded descendant, and the pack states that refusal without
    -- any such exception (03 section 17: "It refuses ... if a correction
    -- descendant exists"; 05 CFS-008 and CFS-021).  The pack outranks this
    -- package's judgement, so the exception is not invented here.
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_REVISION_EXISTS'
      using errcode='55000',
        detail='A replacement final revision has already been materialised for '
               'this session. It is a correction descendant of the prior '
               'authority, so cancelling the session would not release the Trust '
               'and cutoff. Releasing a prepared correction is an unruled owner '
               'decision (WP-59 D-WP59-2).';
  end if;
  if v_state_before='CANCELLED' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_CANCELLED'
      using errcode='55000',
        detail='This correction session is already cancelled. Re-send the exact '
               'cancel request with its original idempotency key for the '
               'idempotent replay.';
  end if;
  if v_state_before='FAILED' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_TERMINAL'
      using errcode='55000',
        detail='This correction session is already terminal.';
  end if;
  if v_state_before not in ('DRAFT','STAGING','READY','REVIEWED') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_STATE_UNKNOWN'
      using errcode='55000',detail='state='||v_state_before;
  end if;

  -- THE PRIOR AUTHORITY MUST NOT HAVE MOVED.  A cancel releases a scope on the
  -- understanding that the authority it was opened against is still the live
  -- one.  If it is not, the world changed under this session and the honest
  -- answer is a stale refusal, not a release.
  select * into v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  if not found
     or v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_revision.source_cycle_id is distinct from v_cycle.id
     or v_prior_revision.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_prior_revision.report_scope_id is distinct from v_session.report_scope_id
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;

  -- A cancel must not promise a release it cannot deliver.  If a correction
  -- descendant of the prior authority already exists, the scope stays blocked
  -- by weekly_source_correct_final_preconditions_v1 whatever this owner does,
  -- so say so instead of releasing the session row and leaving the caller to
  -- discover it.  In a session this owner will cancel there is none, because
  -- the only routine that makes one is PREPARE and a prepared session is
  -- refused above.
  if exists(
    select 1 from public.weekly_source_final_revisions descendant
    where descendant.predecessor_revision_id=v_prior_revision.id
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_DESCENDANT_EXISTS'
      using errcode='55000',
        detail='A correction descendant of the prior final revision exists, so '
               'cancelling this session would not release the Trust and cutoff.';
  end if;

  -- The session's staged artefacts.  A session can carry more than one upload
  -- and more than one projection publication: the seal-failure and abort paths
  -- return the session to DRAFT and null the pointer while leaving the rejected
  -- upload row behind, and the rebuild path replaces
  -- replacement_projection_publication_id with a newer publication.  Every row
  -- bound to this session is therefore locked and disposed of, not only the two
  -- the session currently points at.  The ORDER BY exists solely to make lock
  -- acquisition deterministic; no decision below is taken by it.
  for v_upload in
    select id,state from public.weekly_source_uploads
    where correction_session_id=v_session.id
    order by id
    for update
  loop
    if v_upload.state not in ('STAGING','CORRECTION_READY','REJECTED','SUPERSEDED') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
        using errcode='40001',
          detail='correction upload '||v_upload.id::text||' is '||v_upload.state
                 ||'; it has been promoted beyond this session and cancel will not '
                 'discard accepted work.';
    end if;
  end loop;
  for v_publication in
    select id,state from public.weekly_source_projection_publications
    where correction_session_id=v_session.id
    order by id
    for update
  loop
    if v_publication.state not in ('BUILDING','CORRECTION_READY','STALE','FAILED') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
        using errcode='40001',
          detail='correction publication '||v_publication.id::text||' is '
                 ||v_publication.state||'; it has been promoted beyond this session '
                 'and cancel will not discard accepted work.';
    end if;
  end loop;

  -- A cancel must never SILENTLY succeed.  Removing nothing where something was
  -- expected is a refusal, not a success -- which is exactly the shape of the
  -- defect next door, `public.invoice_remove_nhsp_shifts`, a routine that
  -- returns cleanly and does nothing (WP-54 handoff N3).  Two guards make that
  -- impossible here.
  --
  -- FIRST: a pointer the session still holds must resolve to a row that is
  -- actually bound back to this session.  The disposal loops key on
  -- correction_session_id, so a pointer at a row that is NOT bound would be
  -- left live while the cancel reported success.
  if v_session.replacement_correction_upload_id is not null
     and not exists(
       select 1 from public.weekly_source_uploads bound_upload
       where bound_upload.id=v_session.replacement_correction_upload_id
         and bound_upload.correction_session_id=v_session.id
     ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
      using errcode='40001',
        detail='replacement_correction_upload_id '
               ||v_session.replacement_correction_upload_id::text
               ||' is not bound back to this correction session; cancel will not '
               'report success over work it cannot account for.';
  end if;
  if v_session.replacement_projection_publication_id is not null
     and not exists(
       select 1 from public.weekly_source_projection_publications bound_publication
       where bound_publication.id=v_session.replacement_projection_publication_id
         and bound_publication.correction_session_id=v_session.id
     ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
      using errcode='40001',
        detail='replacement_projection_publication_id '
               ||v_session.replacement_projection_publication_id::text
               ||' is not bound back to this correction session; cancel will not '
               'report success over work it cannot account for.';
  end if;

  -- SECOND: count what is live before the effects, so the effects can be
  -- required to account for exactly that much afterwards.
  select pg_catalog.count(*) into v_live_uploads_before
  from public.weekly_source_uploads
  where correction_session_id=v_session.id
    and state in ('STAGING','CORRECTION_READY');
  select pg_catalog.count(*) into v_live_publications_before
  from public.weekly_source_projection_publications
  where correction_session_id=v_session.id
    and state in ('BUILDING','CORRECTION_READY');

  -- Effects.  One transaction, prior authority untouched.
  --
  -- WP-54 section 6.2 said to "move that upload to REJECTED".  Executed, that
  -- is only possible for an upload that is still STAGING.  The table's
  -- weekly_source_uploads_check3 is
  --   (state in ('SEALED','CURRENT','SUPERSEDED','CORRECTION_READY'))
  --     = (row_manifest_hash is not null)
  -- so moving a sealed CORRECTION_READY upload to REJECTED raises 23514 unless
  -- its row_manifest_hash is erased first -- which would destroy the very
  -- evidence 05 CFS-015 says must remain ("Staged upload and preview remain
  -- audit history only").  A sealed replacement therefore goes to SUPERSEDED,
  -- the state the pack already uses for an upload that stays audit-only and
  -- "cannot be promoted by the correction route" (05 CFS-011).  Both carry the
  -- same typed attempt, so the Blocked/attempt history reads the same either way.
  for v_upload in
    select id from public.weekly_source_uploads
    where correction_session_id=v_session.id
      and state='STAGING'
    order by id
  loop
    update public.weekly_source_uploads set state='REJECTED' where id=v_upload.id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
        using errcode='55000',
          detail='correction upload '||v_upload.id::text||' did not move to REJECTED '
                 '(rows='||v_rows::text||').';
    end if;
    perform private.weekly_source_upload_attempt_append_v1(
      v_upload.id,v_actor,'REJECTED','CORRECTION_SESSION_CANCELLED'
    );
    v_rejected_uploads:=v_rejected_uploads+1;
  end loop;
  for v_upload in
    select id from public.weekly_source_uploads
    where correction_session_id=v_session.id
      and state='CORRECTION_READY'
    order by id
  loop
    update public.weekly_source_uploads set state='SUPERSEDED' where id=v_upload.id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
        using errcode='55000',
          detail='correction upload '||v_upload.id::text||' did not move to SUPERSEDED '
                 '(rows='||v_rows::text||').';
    end if;
    perform private.weekly_source_upload_attempt_append_v1(
      v_upload.id,v_actor,'REJECTED','CORRECTION_SESSION_CANCELLED'
    );
    v_superseded_uploads:=v_superseded_uploads+1;
  end loop;
  for v_publication in
    select id from public.weekly_source_projection_publications
    where correction_session_id=v_session.id
      and state in ('BUILDING','CORRECTION_READY')
    order by id
  loop
    update public.weekly_source_projection_publications
    set state='STALE',failure_code='CORRECTION_SESSION_CANCELLED'
    where id=v_publication.id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
        using errcode='55000',
          detail='correction publication '||v_publication.id::text||' did not move to '
                 'STALE (rows='||v_rows::text||').';
    end if;
    v_staled_publications:=v_staled_publications+1;
  end loop;

  -- The effects must account for exactly what was live before them, and
  -- nothing bound to this session may still be live after them.  Either
  -- mismatch means the cancel did less than it is about to report, and a cancel
  -- that removed nothing where something was expected is a refusal, not a
  -- success.
  if (v_rejected_uploads+v_superseded_uploads)<>v_live_uploads_before
     or v_staled_publications<>v_live_publications_before then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
      using errcode='55000',
        detail='expected to dispose '||v_live_uploads_before::text||' upload(s) and '
               ||v_live_publications_before::text||' publication(s); disposed '
               ||(v_rejected_uploads+v_superseded_uploads)::text||' and '
               ||v_staled_publications::text||'.';
  end if;
  select pg_catalog.count(*) into v_live_uploads_after
  from public.weekly_source_uploads
  where correction_session_id=v_session.id
    and state in ('STAGING','CORRECTION_READY');
  select pg_catalog.count(*) into v_live_publications_after
  from public.weekly_source_projection_publications
  where correction_session_id=v_session.id
    and state in ('BUILDING','CORRECTION_READY');
  if v_live_uploads_after<>0 or v_live_publications_after<>0 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
      using errcode='55000',
        detail=v_live_uploads_after::text||' upload(s) and '
               ||v_live_publications_after::text||' publication(s) bound to this '
               'correction session are still live after the cancel.';
  end if;

  v_result:=pg_catalog.jsonb_build_object(
    'ok',true,'status','CANCELLED',
    'correction_session_id',v_session.id,
    'cancelled_from_state',v_state_before,
    'version',v_expected_session_version+1,
    'prior_final_revision_id',v_prior_revision.id,
    'rejected_upload_count',v_rejected_uploads,
    'superseded_upload_count',v_superseded_uploads,
    'staled_publication_count',v_staled_publications,
    'cancel_reason',v_reason,
    'cancel_idempotency_key',v_idempotency_key,
    'cancel_request_hash',pg_catalog.encode(v_request_hash,'hex')
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_CANCEL_RESULT_V1',v_result
  );

  -- state and completed_at_utc move in the SAME statement: the table's own
  -- check ((state in ('APPLIED','CANCELLED','FAILED')) = (completed_at_utc is
  -- not null)) refuses anything else, including a bare UPDATE.
  -- The session's `reason` column is deliberately NOT overwritten: it holds the
  -- reason the correction was opened for, which is audit history.  The cancel's
  -- own reason is carried in result_json and in the audit event, which is what
  -- 24 section 18 asks for ("actor, reason, decision time").
  update public.weekly_final_source_correction_sessions
  set state='CANCELLED',completed_at_utc=pg_catalog.transaction_timestamp(),
      result_json=v_result,result_hash=v_result_hash,
      version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state=v_state_before
    and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_CANCELLED',
         pg_catalog.jsonb_build_object(
           'state',v_state_before,'version',v_expected_session_version,
           'expected_current_final_revision_id',v_prior_revision.id,
           'replacement_correction_upload_id',v_session.replacement_correction_upload_id,
           'replacement_projection_publication_id',
             v_session.replacement_projection_publication_id
         ),
         pg_catalog.jsonb_build_object(
           'state','CANCELLED','version',v_expected_session_version+1,
           'rejected_upload_count',v_rejected_uploads,
           'superseded_upload_count',v_superseded_uploads,
           'staled_publication_count',v_staled_publications,
           'prior_final_revision_state',v_prior_revision.state,
           'cancel_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;

  return v_result||pg_catalog.jsonb_build_object('idempotent_replay',false);
end;
$function$;

create or replace function public.weekly_source_invoice_report_rows_v1(
  p_request jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_invoice_ids uuid[];
  v_rows jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
               where key not in ('invoice_ids'))
     or pg_catalog.jsonb_typeof(p_request->'invoice_ids') is distinct from 'array'
     or pg_catalog.jsonb_array_length(p_request->'invoice_ids') not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_INVOICE_REPORT_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    select pg_catalog.array_agg(value::uuid order by ordinality)
      into v_invoice_ids
    from pg_catalog.jsonb_array_elements_text(p_request->'invoice_ids')
      with ordinality item(value,ordinality);
  exception when others then
    raise exception 'WEEKLY_SOURCE_INVOICE_REPORT_REQUEST_INVALID' using errcode='22023';
  end;
  if v_invoice_ids is null
     or pg_catalog.cardinality(v_invoice_ids)<>pg_catalog.jsonb_array_length(p_request->'invoice_ids')
     or pg_catalog.cardinality(v_invoice_ids)<>pg_catalog.cardinality(
       (select pg_catalog.array_agg(distinct invoice_id) from pg_catalog.unnest(v_invoice_ids) invoice_id)) then
    raise exception 'WEEKLY_SOURCE_INVOICE_REPORT_REQUEST_INVALID' using errcode='22023';
  end if;

  with movement_rows as materialized (
    select binding.invoice_id,
           movement.id movement_id,
           movement.movement_role,
           movement.invoice_timesheet_id,
           movement.finalisation_cycle_id source_cycle_id,
           movement.invoice_presentation_charge_pence,
           manifest.backing_report_number
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    join public.weekly_source_client_manifests manifest
      on manifest.id=presentation.client_manifest_id
    where binding.state='CURRENT'
      and binding.invoice_id=any(v_invoice_ids)
  ), per_invoice as (
    select invoice_id,
           pg_catalog.count(*)::integer movement_count,
           (pg_catalog.sum(invoice_presentation_charge_pence)::numeric/100.0)::numeric(12,2)
             source_movement_ex_vat,
           pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
             'movement_id',movement_id,
             'movement_role',movement_role,
             'timesheet_id',invoice_timesheet_id,
             'source_cycle_id',source_cycle_id,
             'charge_ex_vat',(invoice_presentation_charge_pence::numeric/100.0)::numeric(12,2)
           ) order by movement_id) movements,
           coalesce((select pg_catalog.jsonb_agg(cycle_id order by cycle_id)
                     from (select distinct source_cycle_id cycle_id
                           from movement_rows member
                           where member.invoice_id=movement_rows.invoice_id) cycles),'[]'::jsonb)
             source_cycle_ids,
           coalesce((select pg_catalog.jsonb_agg(report_number order by report_number)
                     from (select distinct backing_report_number report_number
                           from movement_rows member
                           where member.invoice_id=movement_rows.invoice_id
                             and backing_report_number is not null) reports),'[]'::jsonb)
             backing_report_numbers
    from movement_rows
    group by invoice_id
  )
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
           'invoice_id',invoice_id,
           'weekly_source',true,
           'movement_count',movement_count,
           'source_movement_ex_vat',source_movement_ex_vat,
           'source_cycle_ids',source_cycle_ids,
           'backing_report_numbers',backing_report_numbers,
           'movements',movements
         ) order by invoice_id),'[]'::jsonb)
    into v_rows
  from per_invoice;

  return pg_catalog.jsonb_build_object(
    'ok',true,
    'invoice_count',pg_catalog.jsonb_array_length(v_rows),
    'rows',v_rows);
end;
$function$;

create or replace function public.weekly_source_invoice_evidence_v1(p_request jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_invoice_id uuid;
  v_invoice public.invoices%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_binding_count bigint;
  v_joined_count bigint;
  v_rows jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or exists (select 1 from pg_catalog.jsonb_object_keys(p_request) key
                where key not in ('actor_user_id','invoice_id'))
     or not pg_catalog.pg_input_is_valid(coalesce(p_request->>'actor_user_id',''),'uuid')
     or not pg_catalog.pg_input_is_valid(coalesce(p_request->>'invoice_id',''),'uuid') then
    raise exception 'WEEKLY_SOURCE_INVOICE_EVIDENCE_INVALID' using errcode='22023';
  end if;
  v_actor := (p_request->>'actor_user_id')::uuid;
  v_invoice_id := (p_request->>'invoice_id')::uuid;

  select * into v_invoice from public.invoices where id=v_invoice_id;
  if not found or v_invoice.header_snapshot_json->>'schema_version'<>'WEEKLY_SOURCE_SELF_BILL_INVOICE_V1' then
    return pg_catalog.jsonb_build_object('is_weekly_source_invoice',false,'evidence','[]'::jsonb);
  end if;
  if not pg_catalog.pg_input_is_valid(
      coalesce(v_invoice.header_snapshot_json#>>'{meta,client_manifest_id}',''),'uuid') then
    raise exception 'WEEKLY_SOURCE_INVOICE_EVIDENCE_LINEAGE_INCOMPLETE' using errcode='P0001';
  end if;
  select * into strict v_manifest from public.weekly_source_client_manifests
    where id=(v_invoice.header_snapshot_json#>>'{meta,client_manifest_id}')::uuid;
  perform private.weekly_source_office_authority_v1(
    v_actor,'VIEW_SOURCE_PROGRESS',v_manifest.source_group_id,
    v_manifest.client_id,v_manifest.finalisation_week_ending
  );

  select pg_catalog.count(*) into v_binding_count
    from public.weekly_source_invoice_line_bindings binding
    where binding.invoice_id=v_invoice_id and binding.state='CURRENT';
  if v_binding_count>10000 then
    raise exception 'WEEKLY_SOURCE_INVOICE_EVIDENCE_CENSUS_LIMIT' using errcode='54000';
  end if;
  select pg_catalog.count(*) into v_joined_count
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    join public.weekly_source_final_revisions revision
      on revision.id=presentation.final_revision_id
    join public.weekly_source_uploads upload on upload.id=revision.upload_id
    where binding.invoice_id=v_invoice_id and binding.state='CURRENT';
  if v_binding_count<>v_joined_count then
    raise exception 'WEEKLY_SOURCE_INVOICE_EVIDENCE_LINEAGE_INCOMPLETE' using errcode='P0001';
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'upload_id',source.id,
    'filename',source.original_filename,
    'uploaded_at_utc',source.uploaded_at_utc,
    'byte_count',source.byte_count,
    'content_sha256',pg_catalog.encode(source.content_sha256,'hex'),
    'source_file_r2_key',source.file_metadata_json->>'source_file_r2_key'
  ) order by source.uploaded_at_utc,source.id),'[]'::jsonb) into v_rows
  from (
    select distinct upload.id,upload.original_filename,upload.uploaded_at_utc,
      upload.byte_count,upload.content_sha256,upload.file_metadata_json
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_invoice_presentation_lines presentation
      on presentation.id=binding.presentation_line_id
    join public.weekly_source_final_revisions revision
      on revision.id=presentation.final_revision_id
    join public.weekly_source_uploads upload on upload.id=revision.upload_id
    where binding.invoice_id=v_invoice_id and binding.state='CURRENT'
  ) source;
  return pg_catalog.jsonb_build_object('is_weekly_source_invoice',true,'evidence',v_rows);
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function public.weekly_source_protected_editor_context_v1(p_request jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_client uuid;
  v_candidate uuid;
  v_date date;
  v_group_id uuid;
  v_groups integer;
  v_cycle uuid;
  v_contracts jsonb;
  v_client_name text;
  v_candidate_name text;
  v_events jsonb;
  v_event jsonb;
  v_event_id uuid;
  v_signed jsonb;
  v_final_source jsonb;
  v_history jsonb:='[]'::jsonb;
  v_pending boolean:=false;
  v_resume jsonb;
  v_original jsonb;
  v_original_hash bytea;
  v_approval public.weekly_exceptional_payment_approvals%rowtype;
  v_run public.weekly_exceptional_orchestration_runs%rowtype;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','client_id','candidate_id','work_date','source_group_id','work_event_id'],
    'WEEKLY_PROTECTED_EDITOR_REQUEST_INVALID');
  v_actor:=(p_request->>'actor_user_id')::uuid;
  v_client:=(p_request->>'client_id')::uuid;
  v_candidate:=(p_request->>'candidate_id')::uuid;
  v_date:=(p_request->>'work_date')::date;
  v_event_id:=nullif(p_request->>'work_event_id','')::uuid;
  if v_client is null or v_candidate is null or v_date is null then
    raise exception 'WEEKLY_PROTECTED_EDITOR_SELECTION_REQUIRED' using errcode='22023';
  end if;
  perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY');
  select count(distinct source_group.id),min(source_group.id::text)::uuid
    into v_groups,v_group_id
  from public.weekly_source_groups source_group
  join public.weekly_source_group_clients membership on membership.source_group_id=source_group.id
  join public.weekly_source_client_policies policy on policy.source_group_id=source_group.id
    and policy.client_id=membership.client_id
  where source_group.active and membership.client_id=v_client
    and v_date between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
    and v_date between policy.effective_from and coalesce(policy.effective_to,'infinity'::date)
    and policy.authority_mode='SOURCE_AUTHORITY'
    and (nullif(p_request->>'source_group_id','') is null
      or source_group.id=(p_request->>'source_group_id')::uuid);
  if v_groups<>1 then
    raise exception 'WEEKLY_PROTECTED_EDITOR_SOURCE_SCOPE_REQUIRED' using errcode='22023';
  end if;
  perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY',v_group_id,v_client,v_date);
  select client.name into strict v_client_name from public.clients client where client.id=v_client;
  select coalesce(nullif(candidate.display_name,''),
    nullif(concat_ws(' ',candidate.first_name,candidate.last_name),''),candidate.tms_ref,'Candidate')
    into strict v_candidate_name from public.candidates candidate where candidate.id=v_candidate;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id',contract.id,
      'label',concat_ws(' · ',nullif(contract.role,''),nullif(contract.band,''),nullif(contract.display_site,''),
        nullif(contract.ward_hint,''),to_char(contract.start_date,'DD Mon YYYY')||' – '||to_char(contract.end_date,'DD Mon YYYY')),
      'week_ending_date',v_date+((contract.week_ending_weekday_snapshot-extract(dow from v_date)::integer+7)%7)
    ) order by contract.role,contract.start_date,contract.id),'[]'::jsonb)
    into v_contracts
  from public.contracts contract
  cross join lateral (select private._weekly_source_effective_policy_v1(v_client,contract.id,v_date) value) effective
  join public.weekly_source_groups source_group on source_group.id=v_group_id
  where contract.client_id=v_client and contract.candidate_id=v_candidate
    and v_date between contract.start_date and contract.end_date
    and contract.week_ending_weekday_snapshot between 0 and 6
    and effective.value->>'authority_mode'='SOURCE_AUTHORITY'
    and coalesce((effective.value->>'self_bill_enabled')::boolean,false)
    and effective.value->>'c1_source_mode' in ('NHSP_WEEKLY','HEALTHROSTER_WEEKLY')
    and (source_group.source_family='NHSP')=(effective.value->>'c1_source_mode'='NHSP_WEEKLY');
  select cycle.id into v_cycle from public.weekly_source_cycles cycle
    where cycle.source_group_id=v_group_id
      and (cycle.scope_client_id is null or cycle.scope_client_id=v_client)
    order by (cycle.state<>'FINALISED') desc,cycle.finalisation_week_ending desc,cycle.scope_client_id nulls last,cycle.id limit 1;
  -- Read each distinct work identity, not one arbitrary same-day shift. The
  -- Office must choose the existing identity before changing its protected pay.
  select coalesce(jsonb_agg(jsonb_build_object(
    'work_event_id',event.id,'identity_kind',event.identity_kind,
    'source_hours',case when source_row.id is not null then
      to_char(source_row.start_at_local,'HH24:MI')||'–'||to_char(source_row.end_at_local,'HH24:MI')
        ||' · '||source_row.break_minutes::text||' min break' end,
    'candidate_hours',case when comparison.candidate_start_at_local is not null then
      to_char(comparison.candidate_start_at_local,'HH24:MI')||'–'||to_char(comparison.candidate_end_at_local,'HH24:MI')
        ||' · '||comparison.candidate_break_minutes::text||' min break' end,
    'candidate_timesheet_id',comparison.candidate_timesheet_id,
    'booking_reference',source_row.external_source_key,
    'candidate_sort',(select coalesce(nullif(candidate.last_name,''),candidate.display_name)
      from public.candidates candidate where candidate.id=v_candidate),
    'pay_query_open',query_location.source_cycle_id is not null,
    'query_source_group_id',case when query_location.source_cycle_id is not null then v_group_id end,
    'query_week_ending',query_cycle.finalisation_week_ending,
    'final_report_key',case when final_report.manifest_id is not null then 'FINAL:'||final_report.manifest_id::text end,
    'final_report_week_ending',final_report.week_ending,
    'finalise_source_cycle_id',case when source_row.id is not null
      and (source_profile.profile_code='NHSP_FINAL_BACKING_V1'
        or source_upload.file_metadata_json->>'import_use'='PREPARE_FINALISATION')
      then source_upload.source_cycle_id end,
    'finalise_report_scope_id',case when source_row.id is not null
      and (source_profile.profile_code='NHSP_FINAL_BACKING_V1'
        or source_upload.file_metadata_json->>'import_use'='PREPARE_FINALISATION')
      then source_upload.report_scope_id end,
    'finalise_week_ending',case when source_row.id is not null
      and (source_profile.profile_code='NHSP_FINAL_BACKING_V1'
        or source_upload.file_metadata_json->>'import_use'='PREPARE_FINALISATION')
      then source_cycle.finalisation_week_ending end,
    'family_id',family.id,'contract_id',coalesce(family.contract_id,resolution.contract_id,comparison.contract_id),
    'expected_family_bound_version',family.bound_version::text,
    'protected_state',protected.state,
    'start',to_char(coalesce(protected.start_at_local,comparison.candidate_start_at_local,source_row.start_at_local),'HH24:MI'),
    'end',to_char(coalesce(protected.end_at_local,comparison.candidate_end_at_local,source_row.end_at_local),'HH24:MI'),
    'source_start',to_char(source_row.start_at_local,'HH24:MI'),
    'source_end',to_char(source_row.end_at_local,'HH24:MI'),
    'candidate_start',to_char(comparison.candidate_start_at_local,'HH24:MI'),
    'candidate_end',to_char(comparison.candidate_end_at_local,'HH24:MI'),
    'protected_start',to_char(protected.start_at_local,'HH24:MI'),
    'protected_end',to_char(protected.end_at_local,'HH24:MI'),
    'break_minutes',coalesce(protected.break_minutes,comparison.candidate_break_minutes,source_row.break_minutes)
  ) order by event.id),'[]'::jsonb) into v_events
  from public.weekly_work_events event
  left join lateral (
    select item.* from public.weekly_work_event_source_links item
    join public.weekly_source_row_resolutions resolved on resolved.id=item.row_resolution_id
    join public.weekly_source_upload_rows linked_row on linked_row.id=item.upload_row_id
    join public.weekly_source_projection_publications publication on publication.upload_id=linked_row.upload_id
      and coalesce(publication.projection_generation,publication.authority_scope_version::integer)=resolved.generation
    where item.work_event_id=event.id and publication.state='CURRENT'
      and (exists(select 1 from public.weekly_source_cycles cycle
        where cycle.current_projection_publication_id=publication.id)
        or exists(select 1 from public.weekly_source_report_scopes scope
          where scope.current_projection_publication_id=publication.id))
    order by item.created_at_utc desc,item.id desc limit 1
  ) link on true
  left join public.weekly_source_upload_rows source_row on source_row.id=link.upload_row_id
  left join public.weekly_source_uploads source_upload on source_upload.id=source_row.upload_id
  left join public.weekly_source_cycles source_cycle on source_cycle.id=source_upload.source_cycle_id
  left join public.weekly_source_format_profiles source_profile on source_profile.id=source_upload.source_format_profile_id
  left join public.weekly_source_row_resolutions resolution on resolution.id=link.row_resolution_id
  left join lateral (
    select coalesce(
      (select review.source_cycle_id from private.weekly_source_manual_reviews review
        where review.source_group_id=v_group_id and review.work_event_id=event.id and review.state='OPEN'
        order by review.opened_at_utc desc,review.id desc limit 1),
      (select incident.source_cycle_id from public.weekly_discrepancy_incidents incident
        join public.weekly_source_cycles incident_cycle on incident_cycle.id=incident.source_cycle_id
        where incident_cycle.source_group_id=v_group_id and incident.work_event_id=event.id
          and incident.state='OPEN'
        order by incident.created_at_utc desc,incident.id desc limit 1)) source_cycle_id
  ) query_location on true
  left join public.weekly_source_cycles query_cycle on query_cycle.id=query_location.source_cycle_id
  left join lateral (
    select manifest.id manifest_id,manifest.finalisation_week_ending week_ending
    from public.weekly_source_client_manifests manifest
    join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
    where manifest.source_group_id=v_group_id and manifest.client_id=v_client
      and revision.state='CURRENT'
      and (exists(select 1 from public.weekly_source_final_snapshot_lines snapshot
            where snapshot.final_revision_id=revision.id and snapshot.work_event_id=event.id)
        or exists(select 1 from public.weekly_source_billing_movements movement
            where movement.final_revision_id=revision.id and movement.work_event_id=event.id))
    order by revision.finalised_at_utc desc,manifest.id desc limit 1
  ) final_report on true
  left join lateral (
    select revision.* from public.weekly_discrepancy_incidents incident
    join public.weekly_issue_comparison_revisions revision on revision.id=incident.current_comparison_revision_id
    where incident.work_event_id=event.id
    order by revision.created_at_utc desc,revision.id desc limit 1
  ) comparison on true
  left join lateral (
    select item.* from public.weekly_exceptional_pay_family_events item
    where item.durable_work_event_id=event.id
    order by item.occurred_at_utc desc,item.event_sequence desc,item.id desc limit 1
  ) protected on true
  left join public.weekly_exceptional_pay_target_families family on family.id=protected.family_id
  where event.candidate_id=v_candidate and event.client_id=v_client and event.work_date=v_date
    and event.first_source_group_id=v_group_id;
  if v_event_id is not null then
    select item into v_event from jsonb_array_elements(v_events) item where item->>'work_event_id'=v_event_id::text;
    if v_event is null then
      raise exception 'WEEKLY_PROTECTED_EDITOR_SHIFT_STALE' using errcode='PT409';
    end if;
    select family.current_generation_id is null
      and family.c1_publication_state in ('PENDING','PUBLISHING') into v_pending
    from public.weekly_exceptional_pay_target_families family
    where family.id=(v_event->>'family_id')::uuid;
    if v_pending then
      -- Resume only a retained first approval, never a guessed amendment or
      -- reconstructed financial target. The original actor and exact request
      -- fingerprint remain the existing preparation owner's authority.
      select approval.* into v_approval
      from public.weekly_exceptional_payment_approvals approval
      join public.weekly_exceptional_pay_family_events recorded
        on recorded.evidence_approval_id=approval.id
      where recorded.family_id=(v_event->>'family_id')::uuid
        and recorded.durable_work_event_id=v_event_id
        and recorded.event_sequence=1 and approval.withdrawn_at_utc is null;
      if found then
        select run.* into v_run from public.weekly_exceptional_orchestration_runs run
        where run.id=v_approval.creation_orchestration_run_id
          and run.family_id=(v_event->>'family_id')::uuid
          and run.request_kind='APPROVE' and run.state='RUNNING'
          and run.requested_by_user_id=v_actor
          and v_approval.approved_by_user_id=v_actor
          and v_approval.candidate_id=v_candidate and v_approval.client_id=v_client
          and v_approval.protected_work_date=v_date
          and exists(select 1 from public.weekly_source_cycles original_cycle
            where original_cycle.id=v_approval.source_cycle_id
              and original_cycle.source_group_id=v_group_id)
          and 1=(select count(*) from public.weekly_exceptional_c1_publication_requests publication
            where publication.orchestration_run_id=run.id and publication.family_id=run.family_id
              and publication.state='READY');
        if found then
          v_original:=jsonb_build_object('actor_user_id',v_actor,
            'source_cycle_id',v_approval.source_cycle_id,'candidate_id',v_candidate,
            'client_id',v_client,'contract_id',v_approval.contract_id,
            'week_ending_date',v_approval.week_ending::text,'work_event_id',v_event_id,
            'work_date',v_date::text,
            'start_at_local',to_char(v_approval.protected_start_at_local,'YYYY-MM-DD HH24:MI:SS'),
            'end_at_local',to_char(v_approval.protected_end_at_local,'YYYY-MM-DD HH24:MI:SS'),
            'break_minutes',v_approval.protected_break_minutes,
            'evidence_timesheet_id',v_approval.evidence_timesheet_id,
            'reason',v_approval.approval_reason,'idempotency_key',v_run.idempotency_key);
          v_original_hash:=private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1',v_original);
          if v_original_hash is distinct from v_run.request_fingerprint then
            -- A source-absent first approval originally requested creation of
            -- its work identity. Only an exact hash permits this null variant.
            v_original:=v_original||jsonb_build_object('work_event_id',null);
            v_original_hash:=private.weekly_source_sha256_jsonb_v1(
              'WEEKLY_PROTECTED_PREPARE_FAMILY_REQUEST_V1',v_original);
          end if;
          if v_original_hash=v_run.request_fingerprint then
            perform private.weekly_source_office_authority_v1(v_actor,'APPROVE_PROTECTED_PAY',
              v_group_id,v_client,(select finalisation_week_ending from public.weekly_source_cycles
                where id=v_approval.source_cycle_id));
            v_resume:=(v_original-array['actor_user_id','start_at_local','end_at_local'])
              ||jsonb_build_object('start',to_char(v_approval.protected_start_at_local,'HH24:MI'),
                'end',to_char(v_approval.protected_end_at_local,'HH24:MI'));
          end if;
        end if;
      end if;
    end if;
    if nullif(v_event->>'family_id','') is not null and v_cycle is not null then
      v_final_source:=private.weekly_source_protected_final_source_context_v1(
        (v_event->>'family_id')::uuid,v_cycle,v_event_id);
    end if;
    -- Immutable approvals only: never reconstruct an Office action from an
    -- imported row or a candidate's unsigned schedule.
    select coalesce(jsonb_agg(jsonb_build_object(
      'event_id',history.id,'sequence',history.event_sequence,
      'at',history.occurred_at_utc,
      'by',coalesce(nullif(actor.display_name,''),'Office user'),
      'reason',history.office_reason,'state',history.state,
      'before',history.previous_schedule,
      'after',jsonb_build_object('start',to_char(history.start_at_local,'HH24:MI'),
        'end',to_char(history.end_at_local,'HH24:MI'),'break_minutes',history.break_minutes)
      ) order by history.event_sequence desc),'[]'::jsonb) into v_history
    from (
      select entry.*,lag(jsonb_build_object('start',to_char(entry.start_at_local,'HH24:MI'),
        'end',to_char(entry.end_at_local,'HH24:MI'),'break_minutes',entry.break_minutes))
        over(order by entry.event_sequence) previous_schedule
      from public.weekly_exceptional_pay_family_events entry
      where entry.family_id=(v_event->>'family_id')::uuid
        and entry.durable_work_event_id=v_event_id
    ) history
    left join public.tms_users actor on actor.id=history.office_actor_user_id;
    if nullif(v_event->>'candidate_timesheet_id','') is not null then
      begin
        v_signed:=private.weekly_exceptional_candidate_signed_evidence_v1((v_event->>'candidate_timesheet_id')::uuid);
      exception when sqlstate '55000' then v_signed:=null; end;
    end if;
  end if;
  return jsonb_build_object('ok',true,'contract','WEEKLY_PROTECTED_EDITOR_V1',
    'allowed',true,'source_group_id',v_group_id,'source_cycle_id',v_cycle,
    'source_family',(select source_family from public.weekly_source_groups where id=v_group_id),
    'client_id',v_client,'candidate_id',v_candidate,'work_date',v_date,
    'client',v_client_name,'candidate',v_candidate_name,'contracts',v_contracts,
    'events',v_events,'work_event_id',v_event_id,
    'family_id',v_event->>'family_id','expected_family_bound_version',v_event->>'expected_family_bound_version',
    'protected_state',v_event->>'protected_state','shift_contract_id',v_event->>'contract_id',
    'pending_approval',coalesce(v_pending,false),'resume_request',v_resume,
    'can_reconcile',coalesce((v_final_source->>'source_observed')::boolean,false),
    'final_source_proposal',v_final_source->'source_proposal',
    'history',v_history,
    'candidate_hours',coalesce(v_event->>'candidate_hours',case when v_event_id is null and jsonb_array_length(v_events)>0 then 'Choose a shift to inspect its submission' else 'No candidate hours recorded for this shift' end),
    'source_hours',coalesce(v_event->>'source_hours',case when v_event_id is null and jsonb_array_length(v_events)>0 then 'Choose a shift to inspect its source' else 'Not present in the current import' end),
    'evidence_timesheet_id',v_signed->>'timesheet_id','signed_evidence_available',v_signed is not null,
    'current_schedule',jsonb_build_object('start',v_event->>'start','end',v_event->>'end','break_minutes',v_event->'break_minutes'),
    'create_contract_seed',jsonb_build_object('client_id',v_client,'candidate_id',v_candidate));
end;
$function$;

create or replace function public.weekly_source_workspace_scopes_v1(p_request jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_group uuid;
  v_client uuid;
  v_week date;
  v_limit integer:=100;
  v_offset integer:=0;
  v_cursor jsonb;
  v_rows jsonb;
  v_version text;
  v_total integer;
  v_missing integer;
  v_pending integer;
  v_cutoffs jsonb;
  v_monday date:=(date_trunc('week',statement_timestamp() at time zone 'Europe/London'))::date;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','source_group_id','client_id','week_ending','cursor','limit'],
    'WEEKLY_SOURCE_SCOPE_REQUEST_INVALID');
  v_actor:=(p_request->>'actor_user_id')::uuid;
  v_group:=nullif(p_request->>'source_group_id','')::uuid;
  v_client:=nullif(p_request->>'client_id','')::uuid;
  v_week:=nullif(p_request->>'week_ending','')::date;
  v_limit:=coalesce((p_request->>'limit')::integer,100);
  if v_limit not between 1 and 100 then
    raise exception 'WEEKLY_SOURCE_SCOPE_REQUEST_INVALID' using errcode='22023';
  end if;
  perform private.weekly_source_office_authority_v1(v_actor,'VIEW_SOURCE_PROGRESS',v_group);
  if nullif(p_request->>'cursor','') is not null then
    begin
      v_cursor:=convert_from(decode(p_request->>'cursor','base64'),'UTF8')::jsonb;
      v_offset:=(v_cursor->>'offset')::integer;
      if v_offset is null or v_offset<0 then raise exception 'invalid offset'; end if;
    exception when others then
      raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001';
    end;
  end if;
  with candidates as (
    select distinct on (source_group.id,membership.client_id,cycle.finalisation_week_ending)
      source_group.id group_id,source_group.display_name source_name,source_group.source_family,
      membership.client_id,client.name client_name,cycle.id cycle_id,
      cycle.scope_client_id,
      cycle.finalisation_week_ending,cycle.cutoff_at_utc,cycle.version cycle_version,
      cycle.current_complete_upload_id,cycle.current_projection_publication_id
    from public.weekly_source_groups source_group
    join public.weekly_source_cycles cycle on cycle.source_group_id=source_group.id
    join public.weekly_source_group_clients membership on membership.source_group_id=source_group.id
      and cycle.finalisation_week_ending between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
      and (cycle.scope_client_id is null or cycle.scope_client_id=membership.client_id)
    join public.clients client on client.id=membership.client_id
    where source_group.active and (v_group is null or source_group.id=v_group)
      and (v_client is null or membership.client_id=v_client)
      and (v_week is null or cycle.finalisation_week_ending=v_week)
      and exists(select 1 from public.weekly_source_client_policies policy
        where policy.source_group_id=source_group.id and policy.client_id=membership.client_id
          and policy.authority_mode='SOURCE_AUTHORITY'
          and cycle.finalisation_week_ending between policy.effective_from and coalesce(policy.effective_to,'infinity'::date))
    order by source_group.id,membership.client_id,cycle.finalisation_week_ending,
      (cycle.scope_client_id is not null) desc,cycle.id
  ), scopes as (
    select candidate.*,report.id report_scope_id,report.version report_version,
      case when candidate.source_family='NHSP' then report.current_complete_upload_id
        when candidate.scope_client_id=candidate.client_id then candidate.current_complete_upload_id end upload_id,
      case when candidate.source_family='NHSP' then report.current_projection_publication_id
        when candidate.scope_client_id=candidate.client_id then candidate.current_projection_publication_id end publication_id,
      coalesce(final_report.id,completion.id) completion_id,
      case when final_report.id is not null then 'FINAL_SOURCE' else completion.completion_kind end completion_kind,
      coalesce(final_report.finalised_at_utc,completion.attested_at_utc) completed_at,
      encode(coalesce(final_report.manifest_hash,completion.completion_hash),'hex') completion_hash,
      coalesce(report.cutoff_at_utc,candidate.cutoff_at_utc) actual_cutoff
    from candidates candidate
    left join public.weekly_source_report_scopes report on report.source_cycle_id=candidate.cycle_id
      and report.client_id=candidate.client_id and candidate.source_family='NHSP'
    left join public.weekly_source_client_cycle_completions completion
      on completion.source_cycle_id=candidate.cycle_id and completion.client_id=candidate.client_id
      and completion.state='CURRENT' and completion.completion_kind='NO_SHIFTS_TO_IMPORT'
    -- Completion belongs to this exact client/report. A completed sibling
    -- report for the same client/week must not hide another pending report.
    left join lateral (
      select revision.id,revision.finalised_at_utc,revision.manifest_hash
      from public.weekly_source_final_revisions revision
      join public.weekly_source_client_manifests manifest on coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)=manifest.source_cycle_id and manifest.final_revision_id=revision.id
        and manifest.client_id=candidate.client_id
      where revision.source_cycle_id=candidate.cycle_id and revision.state='CURRENT'
        and revision.report_scope_id is not distinct from report.id
      order by revision.revision_number desc,revision.id limit 1
    ) final_report on true
  ), facts as (
    select scopes.*,private.weekly_source_import_is_prepared_v1(scopes.upload_id) prepared
    from scopes
  ), ordered as (
    select facts.*,bool_or(prepared) over(partition by cycle_id,client_id) client_has_prepared,
      row_number() over(order by private.weekly_source_query_ascii_fold_v1(client_name) collate "C",
      client_id,finalisation_week_ending desc,group_id,report_scope_id nulls first) ordinal
    from facts
  )
  select count(*)::integer,
    count(distinct (cycle_id,client_id)) filter(where completion_id is null and not client_has_prepared
      and actual_cutoff<(v_monday::timestamp at time zone 'Europe/London'))::integer,
    count(distinct (cycle_id,client_id)) filter(where completion_id is null and prepared)::integer,
    encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_WORKSPACE_SCOPES_V1',
      jsonb_build_object('filter',p_request-'cursor'-'limit','rows',coalesce(jsonb_agg(jsonb_build_array(
        cycle_id,client_id,cycle_version,report_scope_id,report_version,upload_id,publication_id,completion_hash,prepared)
        order by ordinal),'[]'::jsonb))),'hex'),
    coalesce(jsonb_agg(jsonb_build_object(
      'key',cycle_id::text||':'||client_id::text||':'||coalesce(report_scope_id::text,'CYCLE'),
      'source_group_id',group_id,'source_cycle_id',cycle_id,'report_scope_id',report_scope_id,
      'client_id',client_id,'client',client_name,'source',source_name,'source_family',source_family,
      'week_ending',finalisation_week_ending,'period',to_char(finalisation_week_ending,'FMDD Mon YYYY'),
      'cutoff',actual_cutoff,'upload_id',upload_id,'projection_publication_id',publication_id,
      'prepared',prepared,'completed',completion_id is not null,'completion_kind',completion_kind,
      'completed_at',completed_at,
      'missing_previous_report',completion_id is null and not client_has_prepared
        and actual_cutoff<(v_monday::timestamp at time zone 'Europe/London')
      ) order by ordinal) filter(where ordinal>v_offset and ordinal<=v_offset+v_limit),'[]'::jsonb)
    into v_total,v_missing,v_pending,v_version,v_rows from ordered;
  if v_cursor is not null and v_cursor->>'version' is distinct from v_version then
    raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('source_group_id',source_group.id,
    'source',source_group.display_name,'cutoff',deadline.value,
    'passed',statement_timestamp()>=deadline.value) order by source_group.display_name,source_group.id),'[]'::jsonb)
  into v_cutoffs from public.weekly_source_groups source_group
  cross join lateral(select ((v_monday+((source_group.cutoff_weekday+6)%7))
    +source_group.cutoff_local_time) at time zone source_group.timezone value) deadline
  where source_group.active and (v_group is null or source_group.id=v_group)
    and exists(select 1 from public.weekly_source_group_clients membership
      join public.weekly_source_client_policies policy on policy.source_group_id=source_group.id
        and policy.client_id=membership.client_id and policy.authority_mode='SOURCE_AUTHORITY'
      where membership.source_group_id=source_group.id and (v_client is null or membership.client_id=v_client)
        and (statement_timestamp() at time zone source_group.timezone)::date between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
        and (statement_timestamp() at time zone source_group.timezone)::date between policy.effective_from and coalesce(policy.effective_to,'infinity'::date));
  return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_WORKSPACE_SCOPES_V1',
    'rows',v_rows,'total_count',v_total,'version',v_version,
    'missing_previous_reports',v_missing,'reports_awaiting_finalisation',v_pending,
    'this_week_cutoffs',v_cutoffs,'has_more',v_offset+v_limit<v_total,
    'next_cursor',case when v_offset+v_limit<v_total then
      encode(convert_to(jsonb_build_object('offset',v_offset+v_limit,'version',v_version)::text,'UTF8'),'base64') else '' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.weekly_source_combined_review_workspace_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_request jsonb; v_scope_page jsonb; v_scopes jsonb:='[]'; v_scope jsonb;
  v_workspace jsonb; v_owner_request jsonb; v_rows jsonb:='[]'; v_item jsonb;
  v_manual_children jsonb; v_question_children jsonb; v_child jsonb;
  v_follow_workspace jsonb; v_follow_up jsonb;
  v_versions jsonb:='[]'; v_owners jsonb:='[]'; v_summary jsonb;
  v_tab text:=coalesce(nullif(p_request->>'tab',''),'queries');
  v_section text:=coalesce(nullif(p_request->>'section',''),'questions');
  v_sort text:=coalesce(nullif(p_request->>'sort_key',''),case when nullif(p_request->>'client_id','') is null then 'client' else 'candidate' end);
  v_direction text:=coalesce(nullif(p_request->>'sort_direction',''),'asc');
  v_seek text:=private.weekly_source_query_ascii_fold_v1(coalesce(p_request->>'seek',''));
  v_limit integer:=coalesce((p_request->>'limit')::integer,50);
  v_offset integer:=0; v_base integer:=0; v_total integer; v_page jsonb; v_counts jsonb;
  v_version text; v_cursor jsonb; v_client uuid; v_seen text[]:='{}'; v_key text; v_owner_key text;
  v_attention jsonb; v_attention_first boolean:=coalesce((p_request->>'attention_first')::boolean,false);
  v_attention_kind text:=coalesce(p_request->>'attention_kind','');
  v_released_scope record;
  v_pending record; v_pending_checks jsonb:='[]'::jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','source_group_id','client_id','week_ending','tab','section',
      'sort_key','sort_direction','seek','cursor','limit','report_key','attention_first','attention_kind'],'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID');
  if v_tab='history' then
    return public.weekly_source_report_history_v1(p_request-'tab'-'section');
  end if;
  if p_request ? 'report_key' then
    raise exception 'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID' using errcode='22023';
  end if;
  if v_tab not in ('imports','queries') or v_section not in ('questions','checks','protected','current','archive')
    or v_sort not in ('client','candidate','day_date','status','file','uploaded')
    or v_direction not in ('asc','desc') or v_limit not between 1 and 100 or length(v_seek)>100
    or v_attention_kind not in ('','missing_source','questions','checks','protected')
    or (p_request ? 'attention_first' and jsonb_typeof(p_request->'attention_first')<>'boolean') then
    raise exception 'WEEKLY_SOURCE_COMBINED_REQUEST_INVALID' using errcode='22023';
  end if;
  v_client:=nullif(p_request->>'client_id','')::uuid;
  v_request:=p_request-'tab'-'section'-'sort_key'-'sort_direction'-'seek'-'cursor'-'limit'-'attention_first'-'attention_kind';
  loop
    v_scope_page:=public.weekly_source_workspace_scopes_v1(v_request);
    v_summary:=v_scope_page-'rows'-'next_cursor'-'has_more';
    v_scopes:=v_scopes||(v_scope_page->'rows');
    exit when not (v_scope_page->>'has_more')::boolean;
    v_request:=v_request||jsonb_build_object('cursor',v_scope_page->>'next_cursor');
  end loop;

  -- Checking-only released NHSP files have row-wise client authority. These
  -- review scopes are not report obligations and must never feed Finalise.
  -- Keep contract, charge and Hours questions visible for eligible row clients
  -- even when they are outside the final backing report's source membership.
  if v_tab='queries' then
    for v_released_scope in
      select distinct cycle.id cycle_id,cycle.source_group_id,
        cycle.finalisation_week_ending,cycle.cutoff_at_utc,
        source_group.display_name source_name,resolution.client_id,client.name client_name,
        upload.id upload_id,publication.id publication_id
      from public.weekly_source_cycles cycle
      join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
      join public.weekly_source_uploads upload on upload.id=cycle.current_complete_upload_id
        and upload.source_cycle_id=cycle.id and upload.state='CURRENT' and upload.report_scope_id is null
      join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
      join public.weekly_source_projection_publications publication on publication.upload_id=upload.id
        and publication.source_cycle_id=cycle.id and publication.authority_scope_kind='CYCLE'
        and publication.report_scope_id is null and publication.authority_scope_version=cycle.version
      left join private.weekly_source_office_rechecks recheck on recheck.publication_id=publication.id
      left join public.weekly_source_projection_publications prior_publication on prior_publication.id=recheck.prior_publication_id
      join public.weekly_source_upload_rows source_row on source_row.upload_id=upload.id
      join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source_row.id
        and resolution.generation=case when publication.state='CURRENT'
          then coalesce(publication.projection_generation,publication.authority_scope_version)
          else coalesce(prior_publication.projection_generation,prior_publication.authority_scope_version) end
      join public.clients client on client.id=resolution.client_id
      where source_group.active and source_group.source_family='NHSP'
        and profile.profile_code='NHSP_PREFINAL_RELEASED_V1'
        and profile.row_finalisation_capability='CHECKING_ONLY' and not profile.single_client_required
        and ((publication.state='CURRENT' and cycle.current_projection_publication_id=publication.id)
          or (publication.state='BUILDING' and recheck.upload_id=upload.id))
        and (nullif(p_request->>'source_group_id','') is null or cycle.source_group_id=(p_request->>'source_group_id')::uuid)
        and (v_client is null or resolution.client_id=v_client)
        and (nullif(p_request->>'week_ending','') is null or cycle.finalisation_week_ending=(p_request->>'week_ending')::date)
        and private.weekly_source_upload_client_eligible_v1(upload.id,resolution.client_id,source_row.work_date)
        and not exists(select 1 from jsonb_array_elements(v_scopes) existing
          where existing->>'source_cycle_id'=cycle.id::text and existing->>'client_id'=resolution.client_id::text)
      order by cycle.id,resolution.client_id,publication.id
    loop
      perform private.weekly_source_office_authority_v1((p_request->>'actor_user_id')::uuid,
        'VIEW_SOURCE_PROGRESS',v_released_scope.source_group_id);
      v_scopes:=v_scopes||jsonb_build_array(jsonb_build_object(
        'key',v_released_scope.cycle_id::text||':'||v_released_scope.client_id::text||':RELEASED_REVIEW',
        'source_group_id',v_released_scope.source_group_id,'source_cycle_id',v_released_scope.cycle_id,
        'report_scope_id',null,'client_id',v_released_scope.client_id,'client',v_released_scope.client_name,
        'source',v_released_scope.source_name,'source_family','NHSP',
        'week_ending',v_released_scope.finalisation_week_ending,
        'period',to_char(v_released_scope.finalisation_week_ending,'FMDD Mon YYYY'),
        'cutoff',v_released_scope.cutoff_at_utc,'upload_id',v_released_scope.upload_id,
        'projection_publication_id',v_released_scope.publication_id,
        'review_only',true,'prepared',false,'completed',false,'completion_kind',null,
        'missing_previous_report',false));
    end loop;
  end if;

  -- A cycle publication is shared across its client scopes. If it has no
  -- cycle publication, each NHSP client's current report scope can instead
  -- own distinct query work. Visit each such scope exactly once.
  for v_scope in select distinct on (item->>'source_cycle_id',
      case when v_tab='queries' and cycle.current_projection_publication_id is null then item->>'client_id' else '' end)
      item||jsonb_build_object('cycle_publication_id',cycle.current_projection_publication_id)
    from jsonb_array_elements(v_scopes) item
    join public.weekly_source_cycles cycle on cycle.id=(item->>'source_cycle_id')::uuid
    order by item->>'source_cycle_id',
      case when v_tab='queries' and cycle.current_projection_publication_id is null then item->>'client_id' else '' end,
      case when item->>'report_scope_id' is null then 1 else 0 end,
      item->>'cutoff' desc nulls last,item->>'key'
  loop
    v_owner_request:=jsonb_build_object('actor_user_id',p_request->>'actor_user_id',
      'tab',v_tab,'source_group_id',v_scope->>'source_group_id',
      'source_cycle_id',v_scope->>'source_cycle_id','limit',100);
    if v_scope->>'source_family'='ROSTER' or
      (v_tab='queries' and v_scope->>'source_family'='NHSP' and v_scope->>'cycle_publication_id' is null
        and v_scope->>'report_scope_id' is not null) then
      v_owner_request:=v_owner_request||jsonb_build_object('client_id',v_scope->>'client_id');
    end if;
    if v_tab='queries' and v_scope->>'source_family'='NHSP' and v_scope->>'cycle_publication_id' is null
      and v_scope->>'report_scope_id' is not null then
      v_owner_request:=v_owner_request||jsonb_build_object('report_scope_id',v_scope->>'report_scope_id');
    end if;
    loop
      v_workspace:=public.weekly_source_office_workspace_v1(v_owner_request);
      v_owner_key:=case when v_tab='imports' then v_scope->>'source_cycle_id'
        else (v_scope->>'source_cycle_id')||':'||
          coalesce(v_workspace#>>'{selected,projection_publication_id}','none') end;
      v_versions:=v_versions||jsonb_build_array(jsonb_build_array(v_scope->>'source_cycle_id',v_workspace->>'workspace_version'));
      if not (v_owner_request ? 'cursor') then
        v_owners:=v_owners||jsonb_build_array(jsonb_build_object('key',v_owner_key,
          'source',v_scope->>'source','period',v_scope->>'period','scope',v_workspace->'selected',
          'bulk_actions',v_workspace#>'{queries,bulk_actions}',
          'protected_pay_enabled',v_workspace#>'{queries,protected_pay_enabled}'));
      end if;
      for v_item in select item from jsonb_array_elements(coalesce(v_workspace#>array[v_tab,'rows'],'[]')) item
      loop
        v_key:=v_tab||':'||v_owner_key;
        v_key:=v_key||':'||(v_item->>'row_key');
        if v_key=any(v_seen) then continue; end if;
        v_seen:=array_append(v_seen,v_key);
        if nullif(v_item->>'client_id','') is not null and not exists(select 1
          from jsonb_array_elements(v_scopes) permitted where permitted->>'source_cycle_id'=v_scope->>'source_cycle_id'
            and permitted->>'client_id'=v_item->>'client_id') then continue; end if;
        if v_client is not null and nullif(v_item->>'client_id','') is not null
          and (v_item->>'client_id')::uuid<>v_client then continue; end if;
        if v_tab='imports' then
          -- Upload errors remain in their immediate review receipt, not an
          -- ever-growing archive. Retain only accepted current work here.
          if v_item->>'state' is distinct from 'CURRENT' then continue; end if;
          if exists(select 1 from public.weekly_source_final_revisions revision
            join public.weekly_source_client_manifests manifest on coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)=manifest.source_cycle_id and manifest.final_revision_id=revision.id
            where revision.upload_id=(v_item->>'row_key')::uuid
              and revision.state in ('CURRENT','SUPERSEDED')
              and (nullif(v_item->>'client_id','') is null
                or manifest.client_id=(v_item->>'client_id')::uuid))
            and not exists(select 1 from jsonb_array_elements(v_scopes) sibling
              where sibling->>'upload_id'=v_item->>'row_key'
                and not coalesce((sibling->>'completed')::boolean,false)) then continue; end if;
        end if;
        if v_tab='queries' then
          -- An Office-created pay review is an Office check, not a request for
          -- candidate/manager hours evidence. Split only those children so a
          -- mixed group can retain its genuine Hours questions independently.
          select coalesce(jsonb_agg(child.value order by child.ordinality)
              filter(where child.value ? 'manual_review_id'),'[]'::jsonb),
            coalesce(jsonb_agg(child.value order by child.ordinality)
              filter(where not (child.value ? 'manual_review_id')),'[]'::jsonb)
            into v_manual_children,v_question_children
          from jsonb_array_elements(coalesce(v_item->'children','[]'::jsonb))
            with ordinality child(value,ordinality);
          for v_child in select value from jsonb_array_elements(v_manual_children)
          loop
            v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
              'combined_key','manual-check:'||(v_child->>'manual_review_id'),
              'row_key',v_child->>'row_key','section','checks',
              'scope_key',v_owner_key,
              'source',v_scope->>'source','source_family',v_scope->>'source_family',
              'period',v_scope->>'period',
              'client',v_item->>'client','client_id',v_item->>'client_id',
              'candidate',v_item->>'candidate','candidate_id',v_item->>'candidate_id',
              'day_date',v_child->>'day_date','system_hours',v_child->>'system_hours',
              'status',v_child->'status','manual_query',v_child->'manual_query',
              'problem','Accept current source hours or protect pay.',
              'pay_blocking',true,'actions',v_child->'actions'));
          end loop;
          if jsonb_array_length(v_question_children)=0 then continue; end if;
          if jsonb_array_length(v_manual_children)>0 then
            v_item:=jsonb_set(v_item,'{actions,0,payload,detail,shifts}',v_question_children,false)
              ||jsonb_build_object('children',v_question_children,
                'issues',greatest(0,coalesce((v_item->>'issues')::integer,0)
                  -jsonb_array_length(v_manual_children)));
          end if;
        end if;
        v_rows:=v_rows||jsonb_build_array(v_item||jsonb_build_object(
          'combined_key',v_key,'scope_key',v_owner_key,'source',v_scope->>'source',
          'source_family',v_scope->>'source_family',
          'period',v_scope->>'period','section',case when v_tab='queries' then 'questions' else 'current' end,
          'client',coalesce(nullif(v_item->>'client',''),(select name from public.clients
            where id=nullif(v_item->>'client_id','')::uuid),'Source-wide file')));
      end loop;
      if v_tab='queries' and not (v_owner_request ? 'cursor') then
        for v_item in
          select item||jsonb_build_object('section','checks') from jsonb_array_elements(coalesce(v_workspace#>'{queries,office_checks,rows}','[]')) item
          union all
          select item||jsonb_build_object('section','protected') from jsonb_array_elements(coalesce(v_workspace#>'{queries,protected_shifts,rows}','[]')) item
        loop
          v_key:=case when v_item->>'section'='protected' then
            'protected:'||(v_item->>'family_id')||':'||(v_item->>'work_event_id')
            else (v_item->>'section')||':'||v_owner_key||':'||(v_item->>'row_key') end;
          if v_key=any(v_seen) then continue; end if;
          v_seen:=array_append(v_seen,v_key);
          if nullif(v_item->>'client_id','') is not null and not exists(select 1
            from jsonb_array_elements(v_scopes) permitted where permitted->>'source_group_id'=v_scope->>'source_group_id'
              and permitted->>'client_id'=v_item->>'client_id') then continue; end if;
          if v_client is not null and nullif(v_item->>'client_id','') is not null
            and (v_item->>'client_id')::uuid<>v_client then continue; end if;
          v_rows:=v_rows||jsonb_build_array(v_item||jsonb_build_object('combined_key',v_key,
            'scope_key',v_owner_key,'source',v_scope->>'source','period',
              case when v_item->>'section'='protected' then 'Awaiting source period' else v_scope->>'period' end));
        end loop;
      end if;
      exit when not coalesce((v_workspace#>>array[v_tab,'has_more'])::boolean,false);
      v_owner_request:=v_owner_request||jsonb_build_object('cursor',v_workspace#>>array[v_tab,'next_cursor']);
    end loop;
  end loop;
  -- Finalisation does not complete its separately tracked approved-hours work.
  -- Keep that exact owner/action reachable from outstanding Office checks.
  if v_tab='queries' then
    for v_scope in select item from jsonb_array_elements(v_scopes) item
      where item->>'completion_kind'='FINAL_SOURCE'
    loop
      v_follow_workspace:=public.weekly_source_office_workspace_v1(jsonb_build_object(
        'actor_user_id',p_request->>'actor_user_id','tab','finalise',
        'source_group_id',v_scope->>'source_group_id','source_cycle_id',v_scope->>'source_cycle_id',
        'client_id',v_scope->>'client_id','report_scope_id',v_scope->>'report_scope_id'));
      v_follow_up:=v_follow_workspace#>'{finalise,approved_hours_follow_up}';
      if nullif(v_follow_up->>'title','') is null then continue; end if;
      v_key:='approved-hours:'||(v_scope->>'key');
      v_versions:=v_versions||jsonb_build_array(jsonb_build_array(v_key,v_follow_workspace->>'workspace_version',v_follow_up));
      v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
        'combined_key',v_key,'row_key',v_key,'section','checks',
        'client',v_scope->>'client','client_id',v_scope->>'client_id',
        'source',v_scope->>'source','period',v_scope->>'period',
        'candidate','Report follow-up','requires_attention',
          v_follow_up->>'state' in ('ACTION_REQUIRED','RECOVERY_REQUIRED')
          or jsonb_typeof(v_follow_up->'action')='object',
        'status',jsonb_build_object('text',v_follow_up->>'title'),
        'problem',v_follow_up->>'body','follow_up_scope',v_follow_workspace->'selected','actions','[]'::jsonb));
    end loop;
  end if;
  -- Rechecks invalidate the old authority before the replacement is ready.
  -- Retain old unresolved rows as explicitly non-actionable history, with only
  -- the exact saved recheck available. Never treat a missing CURRENT pointer
  -- as proof that Office has no work remaining.
  if v_tab='queries' then
    for v_pending in
      select recheck.request_id,recheck.actor_user_id,recheck.request_json,
        recheck.upload_id,recheck.publication_id,source_row.id as upload_row_id,
        source_row.work_date,source_row.source_client_identity,source_row.source_candidate_identity,
        source_row.external_source_key,source_row.start_at_local,source_row.end_at_local,source_row.break_minutes,
        coalesce(candidate.display_name,source_row.bounded_raw_columns_json->>'worker_name',
          source_row.bounded_raw_columns_json->>'candidate',source_row.source_candidate_identity) as candidate_name,
        resolution.mapping_state,charge.phase_severity,cycle.source_group_id,cycle.finalisation_week_ending,
        (select item->>'source' from jsonb_array_elements(v_scopes) item
          where item->>'source_cycle_id'=cycle.id::text limit 1) as source_name
      from private.weekly_source_office_rechecks recheck
      join public.weekly_source_projection_publications publication on publication.id=recheck.publication_id
      join public.weekly_source_projection_publications prior_publication on prior_publication.id=recheck.prior_publication_id
      join public.weekly_source_uploads upload on upload.id=recheck.upload_id
      join public.weekly_source_cycles cycle on cycle.id=upload.source_cycle_id
      left join public.weekly_source_report_scopes scope on scope.id=upload.report_scope_id
      join public.weekly_source_upload_rows source_row on source_row.upload_id=upload.id
      join public.weekly_source_row_resolutions resolution on resolution.upload_row_id=source_row.id
        and resolution.generation=coalesce(prior_publication.projection_generation,prior_publication.authority_scope_version)
      left join public.weekly_source_charge_checks charge on charge.upload_row_id=source_row.id
        and charge.generation=resolution.generation
      left join public.candidates candidate on candidate.id=coalesce(
        (select choice.candidate_id from private.weekly_source_office_row_choices choice
          where choice.upload_row_id=source_row.id order by choice.id desc limit 1),resolution.candidate_id)
      where publication.state='BUILDING' and upload.state='CURRENT'
        and publication.authority_scope_version=case when upload.report_scope_id is null then cycle.version else scope.version end
        and upload.id=case when upload.report_scope_id is null then cycle.current_complete_upload_id else scope.current_complete_upload_id end
        and exists(select 1 from jsonb_array_elements(v_scopes) item where item->>'source_cycle_id'=cycle.id::text)
        and (v_client is null or resolution.client_id=v_client or scope.client_id=v_client)
      order by recheck.request_id,source_row.source_row_ordinal
    loop
      v_key:='recheck:'||v_pending.request_id::text||':'||v_pending.upload_row_id::text;
      v_pending_checks:=v_pending_checks||jsonb_build_array(jsonb_build_object(
        'combined_key',v_key,'row_key',v_key,'section','checks','recheck_pending',true,
        'client',v_pending.source_client_identity,'candidate',v_pending.candidate_name,
        'source_reference',v_pending.source_candidate_identity,'booking_reference',v_pending.external_source_key,
        'source',v_pending.source_name,'period',to_char(v_pending.finalisation_week_ending,'FMDD Mon YYYY'),
        'work_date',v_pending.work_date,'day_date',to_char(v_pending.work_date,'FMDD Mon YYYY'),
        'system_hours',to_char(v_pending.start_at_local,'HH24:MI')||'–'||to_char(v_pending.end_at_local,'HH24:MI')
          ||' · '||v_pending.break_minutes::text||' min break',
        'pay_blocking',v_pending.mapping_state<>'RESOLVED',
        'status',jsonb_build_object('text','Recheck incomplete'),
        'problem',case when v_pending.mapping_state<>'RESOLVED' then 'Previous linking check — selection saved; replacement check incomplete.'
          when v_pending.phase_severity in ('PROVISIONAL_WARNING','FINALISATION_BLOCKER') then 'Previous contract charge warning — replacement check incomplete.'
          else 'Previous check — replacement check incomplete.' end,
        'actions',jsonb_build_array(jsonb_build_object('label','Retry recheck',
          'enabled',v_pending.actor_user_id=(p_request->>'actor_user_id')::uuid,
          'command','RECHECK_SOURCE','payload',v_pending.request_json-'actor_user_id'))));
    end loop;
    v_rows:=v_rows||v_pending_checks;
    v_summary:=v_summary||jsonb_build_object('recheck_pending_count',jsonb_array_length(v_pending_checks));
  end if;
  -- Classify the complete permitted collection before counting or paging.
  -- A waiting signature alone is informational; red unresolved work and green
  -- charge/reconciliation decisions remain visible and count as Office work.
  select coalesce(jsonb_agg(item||jsonb_build_object(
    'attention_missing_source_count',case when item->>'section'='questions' then
      (select count(*) from jsonb_array_elements(coalesce(item->'children','[]')) child
        where child->'candidate_shift_absent_from_import'='true'::jsonb) else 0 end,
    'attention_question_count',case when item->>'section'='questions' then
      (select count(*) from jsonb_array_elements(coalesce(item->'children','[]')) child
        where child->>'issue' is distinct from 'Timesheet missing'
          and child->'candidate_shift_absent_from_import' is distinct from 'true'::jsonb) else 0 end,
    'requires_attention',case
    when item->>'section'='questions' then exists(select 1
      from jsonb_array_elements(coalesce(item->'children','[]')) child
      where child->>'issue' is distinct from 'Timesheet missing')
    when item->>'section'='checks' then case when item ? 'follow_up_scope'
      then coalesce((item->>'requires_attention')::boolean,false) else true end
    when item->>'section'='protected' then coalesce((item->>'requires_attention')::boolean,false)
    else false end)),'[]') into v_rows from jsonb_array_elements(v_rows) item;
  select jsonb_build_object('missing_source',coalesce(sum((item->>'attention_missing_source_count')::integer),0),
    'questions',coalesce(sum((item->>'attention_question_count')::integer),0),
    'checks',count(*) filter(where item->>'section'='checks'),
    'protected',count(*) filter(where item->>'section'='protected'),
    'total',coalesce(sum((item->>'attention_missing_source_count')::integer
      +(item->>'attention_question_count')::integer),0)
      +count(*) filter(where item->>'section' in ('checks','protected')),'complete',true) into v_attention
  from jsonb_array_elements(v_rows) item where item->'requires_attention'='true'::jsonb;
  select jsonb_build_object('questions',count(*) filter(where item->>'section'='questions'),
    'checks',count(*) filter(where item->>'section'='checks'),'protected',count(*) filter(where item->>'section'='protected'),
    'current',count(*) filter(where item->>'section'='current'),'archive',count(*) filter(where item->>'section'='archive'))
    into v_counts from jsonb_array_elements(v_rows) item;
  v_version:=encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_COMBINED_REVIEW_V1',
    jsonb_build_object('scopes',v_summary->>'version','owners',v_versions,'attention_rows',v_rows,
      'filters',p_request-'cursor'-'limit')),'hex');
  -- Attention is an exact view filter, not a tab-total alias. The full census
  -- above stays intact; only this page collection is narrowed. Never rewrite
  -- server-owned action selections or comparison/financial proof payloads.
  if v_attention_kind<>'' then
    select coalesce(jsonb_agg(item),'[]') into v_rows from jsonb_array_elements(v_rows) item
    where item->'requires_attention'='true'::jsonb and case v_attention_kind
      when 'missing_source' then item->>'section'='questions' and (item->>'attention_missing_source_count')::integer>0
      when 'questions' then item->>'section'='questions' and (item->>'attention_question_count')::integer>0
      when 'checks' then item->>'section'='checks'
      when 'protected' then item->>'section'='protected'
      else false end;
    if v_attention_kind in ('missing_source','questions') then
      for v_item in select item from jsonb_array_elements(v_rows) item
      loop
        select coalesce(jsonb_agg(child.value order by child.ordinality),'[]') into v_question_children
          from jsonb_array_elements(v_item->'children') with ordinality child(value,ordinality)
          where child.value->>'issue' is distinct from 'Timesheet missing' and case v_attention_kind
            when 'missing_source' then child.value->'candidate_shift_absent_from_import'='true'::jsonb
            else child.value->'candidate_shift_absent_from_import' is distinct from 'true'::jsonb end;
        v_item:=v_item||jsonb_build_object('children',v_question_children,'issues',jsonb_array_length(v_question_children),
          'actions',(select coalesce(jsonb_agg(case when action->>'label'='Open'
            then jsonb_set(action,'{payload,detail,shifts}',v_question_children,false) else action end),'[]')
            from jsonb_array_elements(coalesce(v_item->'actions','[]')) action));
        select coalesce(jsonb_agg(case when item->>'combined_key'=v_item->>'combined_key' then v_item else item end),'[]')
          into v_rows from jsonb_array_elements(v_rows) item;
      end loop;
    end if;
  end if;
  if nullif(p_request->>'cursor','') is not null then
    begin
      v_cursor:=convert_from(decode(p_request->>'cursor','base64'),'UTF8')::jsonb;
      v_offset:=(v_cursor->>'offset')::integer;
      if v_offset is null or v_offset<0 or v_cursor->>'version' is distinct from v_version then raise exception 'stale'; end if;
    exception when others then raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001'; end;
  end if;
  with keyed as (
    select item,private.weekly_source_query_ascii_fold_v1(coalesce(case v_sort
      when 'candidate' then coalesce(item->>'candidate_sort',item->>'candidate') when 'client' then item->>'client'
      when 'day_date' then item->>'work_date' when 'file' then item->>'file' when 'uploaded' then item->>'uploaded_at'
      when 'status' then item#>>'{status,text}' end,'')) sort_value
    from jsonb_array_elements(v_rows) item where item->>'section'=v_section
  ), ordered as (
    select *,row_number() over(order by case when v_attention_first and v_seek='' then
      case v_attention_kind when 'missing_source' then ((item->>'attention_missing_source_count')::integer>0)::integer
        when 'questions' then ((item->>'attention_question_count')::integer>0)::integer
        else 0 end else 0 end desc,
      case when v_attention_first and v_seek=''
      then coalesce((item->>'requires_attention')::boolean,false)::integer else 0 end desc,
      case when v_direction='asc' then sort_value end collate "C" asc,
      case when v_direction='desc' then sort_value end collate "C" desc,
      private.weekly_source_query_ascii_fold_v1(item->>'client') collate "C",
      private.weekly_source_query_ascii_fold_v1(coalesce(item->>'candidate_sort',item->>'candidate')) collate "C",
      item->>'work_date',item->>'combined_key') ordinal from keyed
  ), origin as (select coalesce(min(ordinal) filter(where v_seek<>'' and starts_with(sort_value,v_seek)),1)-1 base from ordered)
  select count(*)::integer,coalesce(max(origin.base),0)::integer,coalesce(jsonb_agg(item order by ordinal)
    filter(where ordinal>origin.base+v_offset and ordinal<=origin.base+v_offset+v_limit),'[]')
    into v_total,v_base,v_page from ordered cross join origin;
  return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_COMBINED_REVIEW_V1','tab',v_tab,'section',v_section,
    'version',v_version,'rows',v_page,'total_count',v_total,'owners',v_owners,'scope_options',v_scopes,
    'summary',v_summary,'counts',v_counts,'attention',v_attention,
    'attention_kind',v_attention_kind,
    'sort_key',v_sort,'sort_direction',v_direction,
    'has_more',v_base+v_offset+v_limit<v_total,'next_cursor',case when v_base+v_offset+v_limit<v_total
      then encode(convert_to(jsonb_build_object('version',v_version,'offset',v_offset+v_limit)::text,'UTF8'),'base64') else '' end);
end;
$function$;

create or replace function public.weekly_source_report_history_v1(p_request jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid; v_group uuid; v_client uuid; v_week date;
  v_date_from date; v_date_to date;
  v_limit integer; v_offset integer:=0; v_cursor jsonb; v_version text;
  v_sort text; v_direction text; v_seek text;
  v_reports jsonb; v_options jsonb; v_page jsonb; v_report jsonb;
  v_total integer; v_base integer:=0; v_key text;
  v_revision uuid; v_shifts jsonb; v_movements jsonb;
  v_shift_count integer; v_movement_count integer;
  v_invoice_total bigint;
  v_final public.weekly_source_final_revisions%rowtype;
  v_profile text; v_actions jsonb:='[]'::jsonb;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','source_group_id','client_id','week_ending','date_from','date_to','report_key',
      'sort_key','sort_direction','seek','cursor','limit'],'WEEKLY_SOURCE_HISTORY_REQUEST_INVALID');
  v_actor:=(p_request->>'actor_user_id')::uuid;
  v_group:=nullif(p_request->>'source_group_id','')::uuid;
  v_client:=nullif(p_request->>'client_id','')::uuid;
  v_week:=nullif(p_request->>'week_ending','')::date;
  v_date_from:=nullif(p_request->>'date_from','')::date;
  v_date_to:=nullif(p_request->>'date_to','')::date;
  v_key:=nullif(p_request->>'report_key','');
  v_limit:=coalesce((p_request->>'limit')::integer,50);
  v_sort:=coalesce(nullif(p_request->>'sort_key',''),'finalised_at');
  v_direction:=coalesce(nullif(p_request->>'sort_direction',''),'desc');
  v_seek:=private.weekly_source_query_ascii_fold_v1(coalesce(p_request->>'seek',''));
  if v_date_from>v_date_to or v_limit not between 1 and 100 or v_sort not in ('client','source','period','report','finalised_at')
    or v_direction not in ('asc','desc') or length(v_seek)>100 then
    raise exception 'WEEKLY_SOURCE_HISTORY_REQUEST_INVALID' using errcode='22023';
  end if;
  -- History includes retired source groups; the existing global Office read
  -- authority still requires an active administrator. No new financial right.
  perform private.weekly_source_office_authority_v1(v_actor,'VIEW_SOURCE_PROGRESS');
  with completed as (
    select 'FINAL:'||manifest.id::text report_key,manifest.source_group_id,
      manifest.source_cycle_id,manifest.client_id,manifest.finalisation_week_ending,
      manifest.final_revision_id,manifest.backing_report_number,
      revision.finalised_at_utc completed_at,revision.finalised_by_user_id actor_id,
      revision.revision_number,revision.state revision_state,revision.reason,
      encode(revision.manifest_hash,'hex') evidence_hash,'FINAL_SOURCE' completion_kind,
      null::text attestation
    from public.weekly_source_client_manifests manifest
    join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
    where revision.state in ('CURRENT','SUPERSEDED')
    union all
    select 'ZERO:'||completion.id::text,completion.source_group_id,completion.source_cycle_id,
      completion.client_id,cycle.finalisation_week_ending,null::uuid,null::text,
      completion.attested_at_utc,completion.attested_by_user_id,completion.completion_generation,
      completion.state,'NO_SHIFTS_TO_IMPORT',encode(completion.completion_hash,'hex'),
      completion.completion_kind,completion.attestation_text
    from public.weekly_source_client_cycle_completions completion
    join public.weekly_source_cycles cycle on cycle.id=completion.source_cycle_id
    where completion.completion_kind='NO_SHIFTS_TO_IMPORT'
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'report_key',completed.report_key,'source_group_id',completed.source_group_id,
    'source_cycle_id',completed.source_cycle_id,'client_id',completed.client_id,
    'client',client.name,'source',source_group.display_name,'source_family',source_group.source_family,
    'week_ending',completed.finalisation_week_ending,'period',to_char(completed.finalisation_week_ending,'FMDD Mon YYYY'),
    'final_revision_id',completed.final_revision_id,'revision_number',completed.revision_number,
    'revision_state',completed.revision_state,'reason',completed.reason,
    'report',coalesce(completed.backing_report_number,case when completed.completion_kind='NO_SHIFTS_TO_IMPORT'
      then 'No shifts to import' else 'Weekly finalisation' end),
    'finalised_at',to_char(completed.completed_at at time zone 'Europe/London','FMDD Mon YYYY, HH24:MI'),
    'finalised_at_utc',completed.completed_at,'finalised_by',coalesce(office_user.display_name,'Office'),
    'completion_kind',completed.completion_kind,'attestation',completed.attestation,
    'evidence_hash',completed.evidence_hash
  ) order by completed.completed_at desc,completed.report_key),'[]'::jsonb)
  into v_reports from completed
  join public.clients client on client.id=completed.client_id
  join public.weekly_source_groups source_group on source_group.id=completed.source_group_id
  left join public.tms_users office_user on office_user.id=completed.actor_id
  where (v_group is null or completed.source_group_id=v_group)
    and (v_client is null or completed.client_id=v_client)
    and (v_date_from is null or (completed.completed_at at time zone 'Europe/London')::date>=v_date_from)
    and (v_date_to is null or (completed.completed_at at time zone 'Europe/London')::date<=v_date_to);
  select coalesce(jsonb_agg(distinct jsonb_build_object('source_group_id',item->>'source_group_id',
    'source',item->>'source','client_id',item->>'client_id','client',item->>'client',
    'week_ending',item->>'week_ending','period',item->>'period')),'[]'::jsonb)
    into v_options from jsonb_array_elements(v_reports) item;
  v_version:=encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_REPORT_HISTORY_V1',
    jsonb_build_object('reports',v_reports,'filter',p_request-'cursor'-'limit')),'hex');
  if nullif(p_request->>'cursor','') is not null then
    begin
      v_cursor:=convert_from(decode(p_request->>'cursor','base64'),'UTF8')::jsonb;
      v_offset:=(v_cursor->>'offset')::integer;
      if v_offset is null or v_offset<0 or v_cursor->>'version' is distinct from v_version then raise exception 'stale'; end if;
    exception when others then raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001'; end;
  end if;
  if v_key is not null then
    select item into v_report from jsonb_array_elements(v_reports) item where item->>'report_key'=v_key;
    if v_report is null then raise exception 'WEEKLY_SOURCE_COMPLETED_REPORT_NOT_FOUND' using errcode='22023'; end if;
    v_revision:=nullif(v_report->>'final_revision_id','')::uuid;
    v_client:=(v_report->>'client_id')::uuid;
    select revision.* into v_final from public.weekly_source_final_revisions revision where revision.id=v_revision;
    if v_final.state='CURRENT' and exists(select 1 from public.weekly_source_groups source_group
      join public.weekly_source_group_clients membership on membership.source_group_id=source_group.id
      where source_group.id=(v_report->>'source_group_id')::uuid and source_group.active
        and membership.client_id=v_client and (v_report->>'week_ending')::date
          between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)) then
      perform private.weekly_source_office_authority_v1(v_actor,'CORRECT_FINAL_SOURCE',
        (v_report->>'source_group_id')::uuid,v_client,(v_report->>'week_ending')::date);
      select profile.profile_code into v_profile from public.weekly_source_uploads upload
        join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
        where upload.id=v_final.upload_id;
      v_actions:=jsonb_build_array(jsonb_build_object('label','Correct final source','enabled',true,
        'payload',jsonb_build_object('scope_label',v_report->>'client','current_label',v_report->>'report',
          'correction_payload',jsonb_build_object('source_cycle_id',v_final.source_cycle_id,
            'authority_scope_kind',v_final.authority_scope_kind,'report_scope_id',v_final.report_scope_id,
            'expected_current_final_revision_id',v_final.id,
            'expected_final_manifest_hash',encode(v_final.manifest_hash,'hex'),
            'idempotency_key','history-correction:'||gen_random_uuid()::text),
          'replacement_context',jsonb_build_object('source_group_id',v_report->>'source_group_id',
            'client_id',v_client,'profile_id',v_profile))));
    end if;
    with shifts as (
      select snapshot.id::text row_key,snapshot.upload_row_id source_row_id,
        snapshot.work_event_id,snapshot.candidate_id,snapshot.work_date,
        snapshot.start_at_local,snapshot.end_at_local,snapshot.break_minutes,snapshot.actual_net_minutes,
        snapshot.external_event_identity booking_reference,
        source_row.source_total_cost_pence,source_row.source_commission_pence,
        source_row.source_shift_charge_pence
      from public.weekly_source_final_snapshot_lines snapshot
      left join public.weekly_source_upload_rows source_row on source_row.id=snapshot.upload_row_id
      where snapshot.final_revision_id=v_revision and snapshot.client_id=v_client
      union all
      select source_row.id::text,source_row.id,movement.work_event_id,
        movement.candidate_id,source_row.work_date,source_row.start_at_local,
        source_row.end_at_local,source_row.break_minutes,source_row.actual_net_minutes,
        source_row.external_source_key,source_row.source_total_cost_pence,
        source_row.source_commission_pence,source_row.source_shift_charge_pence
      from public.weekly_source_billing_movements movement
      join public.weekly_source_upload_rows source_row on source_row.id=movement.nhsp_upload_row_id
      where movement.final_revision_id=v_revision and movement.actual_client_id=v_client
    ), ordered as (
      select shifts.*,coalesce(candidate.display_name,concat_ws(' ',candidate.first_name,candidate.last_name)) candidate_name,
        row_number() over(order by private.weekly_source_query_ascii_fold_v1(candidate.last_name),
          candidate.id,shifts.work_date,shifts.start_at_local,shifts.row_key) ordinal
      from shifts join public.candidates candidate on candidate.id=shifts.candidate_id
    )
    select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('row_key',row_key,
      'source_row_id',case when v_final.state='CURRENT' then source_row_id end,
      'pay_query_open',exists(select 1 from private.weekly_source_manual_reviews review
        where review.source_group_id=(v_report->>'source_group_id')::uuid
          and review.work_event_id=ordered.work_event_id and review.state='OPEN')
        or exists(select 1 from public.weekly_discrepancy_incidents incident
          join public.weekly_source_cycles incident_cycle on incident_cycle.id=incident.source_cycle_id
          where incident_cycle.source_group_id=(v_report->>'source_group_id')::uuid
            and incident.work_event_id=ordered.work_event_id and incident.state='OPEN'),
      'work_event_id',work_event_id,'candidate',candidate_name,
      'day_date',to_char(work_date,'Dy FMDD Mon YYYY'),'start',to_char(start_at_local,'HH24:MI'),
      'end',to_char(end_at_local,'HH24:MI'),'break_minutes',break_minutes,'net_minutes',actual_net_minutes,
      'booking_reference',booking_reference,
      'source_total_cost_pence',source_total_cost_pence,
      'source_commission_pence',source_commission_pence,
      'source_shift_charge_pence',source_shift_charge_pence) order by ordinal)
      filter(where ordinal>v_offset and ordinal<=v_offset+v_limit),'[]'::jsonb)
      into v_shift_count,v_shifts from ordered;
    with ordered as (
      select movement.*,coalesce(candidate.display_name,concat_ws(' ',candidate.first_name,candidate.last_name)) candidate_name,
        event.work_date,row_number() over(order by event.work_date,candidate.last_name,candidate.id,movement.id) ordinal
      from public.weekly_source_billing_movements movement
      join public.candidates candidate on candidate.id=movement.candidate_id
      join public.weekly_work_events event on event.id=movement.work_event_id
      where movement.final_revision_id=v_revision and movement.actual_client_id=v_client
    )
    select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('row_key',id,'candidate',candidate_name,
      'day_date',to_char(work_date,'Dy FMDD Mon YYYY'),'movement',initcap(replace(movement_role,'_',' ')),
      'source_line_kind',source_line_kind,'booking_reference',source_facts_json->>'booking_reference',
      'pay_ex_vat_pence',round(total_pay_ex_vat*100)::bigint,
      'invoice_charge_pence',invoice_presentation_charge_pence,
      'vat_pence',round(vat_amount*100)::bigint,
      'total_inc_vat_pence',round(total_inc_vat*100)::bigint) order by ordinal)
      filter(where ordinal>v_offset and ordinal<=v_offset+v_limit),'[]'::jsonb)
      into v_movement_count,v_movements from ordered;
    select coalesce(sum(invoice_presentation_charge_pence),0) into v_invoice_total
      from public.weekly_source_billing_movements where final_revision_id=v_revision and actual_client_id=v_client;
    return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_COMPLETED_REPORT_V1','report',v_report,
      'shifts',v_shifts,'shift_count',v_shift_count,'movements',v_movements,'movement_count',v_movement_count,'actions',v_actions,
      'invoice_charge_pence',v_invoice_total,'has_more',v_offset+v_limit<greatest(v_shift_count,v_movement_count),
      'next_cursor',case when v_offset+v_limit<greatest(v_shift_count,v_movement_count) then
        encode(convert_to(jsonb_build_object('version',v_version,'offset',v_offset+v_limit)::text,'UTF8'),'base64') else '' end);
  end if;
  with filtered as (
    select item,private.weekly_source_query_ascii_fold_v1(case v_sort when 'period' then item->>'week_ending'
      when 'finalised_at' then item->>'finalised_at_utc' else item->>v_sort end) sort_value
    from jsonb_array_elements(v_reports) item where v_week is null or (item->>'week_ending')::date=v_week
  ), ordered as (
    select item,sort_value,row_number() over(order by case when v_direction='asc' then sort_value end collate "C" asc,
      case when v_direction='desc' then sort_value end collate "C" desc,item->>'report_key') ordinal from filtered
  ), origin as (select coalesce(min(ordinal) filter(where v_seek<>'' and starts_with(sort_value,v_seek)),1)-1 base from ordered)
  select count(*)::integer,coalesce(max(origin.base),0)::integer,coalesce(jsonb_agg(item order by ordinal)
    filter(where ordinal>origin.base+v_offset and ordinal<=origin.base+v_offset+v_limit),'[]'::jsonb)
    into v_total,v_base,v_page from ordered cross join origin;
  return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_REPORT_HISTORY_V1','rows',v_page,
    'scope_options',v_options,'sort_key',v_sort,'sort_direction',v_direction,'total_count',v_total,
    'has_more',v_base+v_offset+v_limit<v_total,'next_cursor',case when v_base+v_offset+v_limit<v_total then
      encode(convert_to(jsonb_build_object('version',v_version,'offset',v_offset+v_limit)::text,'UTF8'),'base64') else '' end);
end;
$function$;

create or replace function public.weekly_source_manual_review_open_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid; v_row_id uuid; v_reason text;
  v_row public.weekly_source_upload_rows%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_resolution public.weekly_source_row_resolutions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_route jsonb; v_existing uuid; v_review uuid;
  v_week date;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
    or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
      where key not in ('actor_user_id','source_row_id','reason')) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_row_id:=(p_request->>'source_row_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023';
  end;
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_actor is null or v_row_id is null or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  select * into v_row from public.weekly_source_upload_rows where id=v_row_id;
  if not found then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_ROW_NOT_FOUND' using errcode='22023'; end if;
  select * into strict v_upload from public.weekly_source_uploads where id=v_row.upload_id;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_upload.source_cycle_id;
  select * into v_resolution from public.weekly_source_row_resolutions
    where upload_row_id=v_row.id order by generation desc,id desc limit 1;
  if not found or v_resolution.mapping_state<>'RESOLVED' or v_resolution.work_event_id is null
    or v_row.row_finalisation_state not in ('NOT_APPLICABLE','SOURCE_WORKED')
    or v_upload.state not in ('CURRENT','SUPERSEDED')
    or not (
      exists(select 1 from public.weekly_source_client_manifests manifest
        join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
        where manifest.source_cycle_id=v_cycle.id and manifest.client_id=v_resolution.client_id
          and revision.upload_id=v_upload.id and revision.state='CURRENT')
      or (not exists(select 1 from public.weekly_source_client_manifests manifest
            join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
            where manifest.source_cycle_id=v_cycle.id and manifest.client_id=v_resolution.client_id
              and revision.state='CURRENT')
        and exists(select 1 from public.weekly_source_projection_publications publication
          where publication.source_cycle_id=v_cycle.id and publication.upload_id=v_upload.id
            and publication.state='CURRENT'))
    ) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_SOURCE_STALE' using errcode='40001';
  end if;
  v_route:=private.weekly_source_office_route_key_v1(v_cycle.id,v_resolution.candidate_id,
    v_resolution.client_id,v_resolution.contract_id,v_row.work_date);
  if v_route->>'authority_mode'<>'SOURCE_AUTHORITY' then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_AUTHORITY_INVALID' using errcode='22023';
  end if;
  perform private.weekly_source_office_authority_v1(v_actor,'RECHECK_SOURCE',
    v_cycle.source_group_id,v_resolution.client_id,v_cycle.finalisation_week_ending);
  v_week:=(date_trunc('week',v_row.work_date)::date+6);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_QUERY_FAMILY:'||v_resolution.contract_id::text||':'||v_week::text,0));
  if exists(select 1 from public.timesheets timesheet
      where timesheet.contract_id=v_resolution.contract_id
        and timesheet.week_ending_date=v_week and timesheet.is_current
        and timesheet.authorised_at_server is not null) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_ALREADY_AUTHORISED' using errcode='55000';
  end if;
  select id into v_existing from private.weekly_source_manual_reviews
    where source_group_id=v_cycle.source_group_id and work_event_id=v_resolution.work_event_id
      and state='OPEN' for update;
  if v_existing is not null then
    return pg_catalog.jsonb_build_object('ok',true,'review_id',v_existing,
      'already_open',true,'problem','Manually queried');
  end if;
  insert into private.weekly_source_manual_reviews(
    source_group_id,source_cycle_id,upload_row_id,row_resolution_id,source_row_hash,
    work_event_id,candidate_id,client_id,contract_id,work_date,state,
    office_reason,opened_by_user_id)
  values(v_cycle.source_group_id,v_cycle.id,v_row.id,v_resolution.id,v_row.normalised_row_hash,
    v_resolution.work_event_id,v_resolution.candidate_id,v_resolution.client_id,
    v_resolution.contract_id,v_row.work_date,'OPEN',v_reason,v_actor)
  returning id into v_review;
  perform public._audit_insert('weekly_source_manual_review',v_review::text,
    'WEEKLY_SOURCE_MANUAL_REVIEW_OPENED',null,
    pg_catalog.jsonb_build_object('source_row_id',v_row.id,'work_event_id',v_resolution.work_event_id,
      'reason',v_reason),'Office sent imported shift back to Queries',v_actor);
  return pg_catalog.jsonb_build_object('ok',true,'review_id',v_review,
    'already_open',false,'problem','Manually queried');
end;
$function$;

create or replace function public.weekly_source_manual_review_resolve_v1(p_request jsonb)
returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid; v_review_id uuid; v_kind text;
  v_review private.weekly_source_manual_reviews%rowtype;
  v_current_row public.weekly_source_upload_rows%rowtype;
  v_expected_hash text;
  v_week date; v_scope_date date;
begin
  perform private.weekly_source_query_require_service_v1();
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
    or exists(select 1 from pg_catalog.jsonb_object_keys(p_request) key
      where key not in ('actor_user_id','review_id','resolution_kind','expected_current_row_hash')) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_review_id:=(p_request->>'review_id')::uuid;
  exception when others then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023';
  end;
  v_kind:=p_request->>'resolution_kind';
  if v_actor is null or v_review_id is null or v_kind not in ('OFFICE_ACCEPTED_SOURCE','PROTECTED_PAY') then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  select * into v_review from private.weekly_source_manual_reviews where id=v_review_id;
  if found and v_review.state='RESOLVED' and v_review.resolution_kind=v_kind
     and v_review.resolved_by_user_id=v_actor then
    -- Exact retry after the atomic protected Save or a lost response. No
    -- second resolution, new audit row or current-source reinterpretation.
    perform private.weekly_source_office_authority_v1(v_actor,
      case when v_kind='PROTECTED_PAY' then 'APPROVE_PROTECTED_PAY' else 'ACCEPT_SYSTEM_HOURS' end,
      v_review.source_group_id,v_review.client_id,v_review.work_date);
    return jsonb_build_object('ok',true,'review_id',v_review.id,
      'resolution_kind',v_kind,'idempotent_replay',true);
  end if;
  if not found or v_review.state<>'OPEN' then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_NOT_OPEN' using errcode='40001';
  end if;
  select finalisation_week_ending into strict v_scope_date
  from public.weekly_source_cycles where id=v_review.source_cycle_id;
  perform private.weekly_source_office_authority_v1(v_actor,
    case when v_kind='PROTECTED_PAY' then 'APPROVE_PROTECTED_PAY' else 'ACCEPT_SYSTEM_HOURS' end,
    v_review.source_group_id,v_review.client_id,v_scope_date);
  v_week:=(date_trunc('week',v_review.work_date)::date+6);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'WEEKLY_SOURCE_QUERY_FAMILY:'||v_review.contract_id::text||':'||v_week::text,0));
  select * into strict v_review from private.weekly_source_manual_reviews
    where id=v_review_id and state='OPEN' for update;
  if v_kind='OFFICE_ACCEPTED_SOURCE' then
    v_expected_hash:=p_request->>'expected_current_row_hash';
    if v_expected_hash is null or v_expected_hash!~'^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_CURRENT_SOURCE_REQUIRED' using errcode='22023';
    end if;
    -- A later import may replace the original row's hours. Accept only the
    -- currently displayed source tuple for the same durable work identity.
    select candidate_row.* into v_current_row
    from public.weekly_source_upload_rows candidate_row
    join public.weekly_source_uploads candidate_upload on candidate_upload.id=candidate_row.upload_id
    join lateral (
      select mapping.work_event_id,mapping.mapping_state
      from public.weekly_source_row_resolutions mapping
      where mapping.upload_row_id=candidate_row.id
      order by mapping.generation desc,mapping.id desc limit 1
    ) current_mapping on current_mapping.work_event_id=v_review.work_event_id
      and current_mapping.mapping_state='RESOLVED'
    where candidate_upload.source_cycle_id=v_review.source_cycle_id
      and candidate_row.row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED')
      and (
        exists(select 1 from public.weekly_source_client_manifests manifest
          join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
          where manifest.source_cycle_id=v_review.source_cycle_id
            and manifest.client_id=v_review.client_id
            and revision.state='CURRENT' and revision.upload_id=candidate_upload.id)
        or (not exists(select 1 from public.weekly_source_client_manifests manifest
            join public.weekly_source_final_revisions revision on revision.id=manifest.final_revision_id
            where manifest.source_cycle_id=v_review.source_cycle_id
              and manifest.client_id=v_review.client_id and revision.state='CURRENT')
          and exists(select 1 from public.weekly_source_projection_publications publication
            where publication.source_cycle_id=v_review.source_cycle_id
              and publication.upload_id=candidate_upload.id and publication.state='CURRENT'))
      )
    order by candidate_row.created_at_utc desc,candidate_row.id desc limit 1;
    if not found or pg_catalog.encode(v_current_row.normalised_row_hash,'hex')<>v_expected_hash then
      raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_SOURCE_STALE' using errcode='40001';
    end if;
  elsif not exists (
    select 1 from public.weekly_exceptional_pay_family_events protected_event
    join public.weekly_exceptional_pay_target_families family
      on family.id=protected_event.family_id
    where family.contract_id=v_review.contract_id
      and family.candidate_id=v_review.candidate_id
      and family.week_ending_date=v_week
      and protected_event.durable_work_event_id=v_review.work_event_id
      and protected_event.state='WAIT'
      and exists(select 1 from public.weekly_exceptional_payment_approvals approved
        join public.weekly_exceptional_c1_publication_requests request
          on request.orchestration_run_id=approved.creation_orchestration_run_id
        where approved.id=protected_event.evidence_approval_id
          and (request.state='PUBLISHED' or exists(
            select 1 from private.weekly_source_local_protected_decision_receipts receipt
            where receipt.publication_request_id=request.id
              and receipt.state in ('COMPLETE','PENDING_FREEZE'))))
      and protected_event.event_sequence=(select max(latest.event_sequence)
        from public.weekly_exceptional_pay_family_events latest
        where latest.family_id=protected_event.family_id
          and latest.durable_work_event_id=protected_event.durable_work_event_id)
  ) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_PROTECTED_PAY_REQUIRED' using errcode='55000';
  end if;
  update private.weekly_source_manual_reviews
    set state='RESOLVED',resolved_by_user_id=v_actor,
      resolved_at_utc=pg_catalog.transaction_timestamp(),resolution_kind=v_kind
    where id=v_review.id;
  perform public._audit_insert('weekly_source_manual_review',v_review.id::text,
    'WEEKLY_SOURCE_MANUAL_REVIEW_RESOLVED',null,
    pg_catalog.jsonb_build_object('resolution_kind',v_kind,'work_event_id',v_review.work_event_id,
      'accepted_source_row_id',v_current_row.id),
    'Office resolved imported-shift review',v_actor);
  return pg_catalog.jsonb_build_object('ok',true,'review_id',v_review.id,
    'resolution_kind',v_kind);
end;
$function$;

create or replace function private.weekly_source_accepted_publication_context_v1(
  p_canonical jsonb
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_canonical jsonb;
  v_origin jsonb;
  v_bundle public.weekly_source_entitlement_decision_bundles%rowtype;
  v_root public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_final public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_inventory jsonb;
  v_basis jsonb;
  v_before_ids jsonb;
  v_control jsonb;
begin
  v_canonical:=private.weekly_source_publication_request_canonical_v1(
    p_canonical,'IMMEDIATE',null::uuid);
  v_origin:=v_canonical#>'{financial_request,source_revision}';
  if v_origin->>'origin_kind' is distinct from 'CURRENT_FINAL_SOURCE_V1'
     or jsonb_array_length(v_canonical->'member_root_ids')<>1
     or v_canonical#>>'{financial_request,member_entitlements,0,authority_kind}'
          is distinct from 'LOCKED_FINAL_SOURCE' then
    raise exception 'WEEKLY_SOURCE_ACCEPTED_ACTION_INVALID' using errcode='22023';
  end if;
  select * into v_bundle from public.weekly_source_entitlement_decision_bundles b
    where b.decision_bundle_id=(v_canonical->>'decision_bundle_id')::uuid
      and b.bundle_revision=(v_canonical->>'bundle_revision')::bigint;
  if not found or v_bundle.state not in ('PROPOSED','COMMITTED')
     or v_bundle.bundle_kind<>'SINGLE_ROOT'
     or v_bundle.publication_mode<>'IMMEDIATE'
     or v_bundle.target_root_timesheet_id is not null
     or v_bundle.whole_root_review_required
     or cardinality(v_bundle.proposed_head_ids)<>1
     or to_jsonb(v_bundle.proposed_head_ids) is distinct from v_canonical->'head_ids'
     or v_bundle.decision_id is distinct from (v_canonical->>'decision_id')::uuid
     or v_bundle.candidate_id is distinct from (v_canonical->>'candidate_id')::uuid
     or v_bundle.source_root_timesheet_id is distinct from
          (v_canonical#>>'{member_root_ids,0}')::uuid
     or v_bundle.source_root_family_booking_id is distinct from
          v_canonical#>>'{member_family_booking_ids,0}'
     or v_bundle.request_digest is distinct from
          private.weekly_source_publication_request_digest_v1(v_canonical)
     or v_bundle.source_revision_digest is distinct from
          private.weekly_source_publication_request_digest_v1(v_origin)
     or v_bundle.contract_choice_digest is distinct from
          private.weekly_source_publication_request_digest_v1(
            v_canonical#>'{financial_request,contract_choices}')
     then
    return null;
  end if;
  select * into v_root from public.timesheets t where t.timesheet_id=v_bundle.source_root_timesheet_id;
  if not found or not v_root.is_current
     or v_root.version is distinct from (v_canonical#>>'{member_root_versions,0}')::bigint
     or v_root.booking_id is distinct from v_bundle.source_root_family_booking_id
     or v_root.contract_id is distinct from v_bundle.source_contract_id
     or v_root.week_ending_date is distinct from v_bundle.week_ending_date then return null; end if;
  select * into v_contract from public.contracts c where c.id=v_root.contract_id;
  if not found or v_contract.candidate_id is distinct from v_bundle.candidate_id
     or v_contract.id is distinct from (v_canonical#>>'{financial_request,contract_choices,0,contract_id}')::uuid
     or v_root.week_ending_date is distinct from
          (v_canonical#>>'{financial_request,contract_choices,0,week_ending_date}')::date then return null; end if;
  select * into v_final from public.weekly_source_final_revisions f
    where f.id=(v_origin->>'final_revision_id')::uuid;
  if not found or v_final.state<>'CURRENT'
     or v_final.source_cycle_id is distinct from (v_origin->>'source_cycle_id')::uuid
     or v_final.revision_number is distinct from (v_origin->>'revision_number')::integer
     or encode(v_final.manifest_hash,'hex') is distinct from v_origin->>'manifest_hash'
     or encode(v_final.policy_fingerprint,'hex') is distinct from v_origin->>'policy_fingerprint' then return null; end if;
  select * into strict v_cycle from public.weekly_source_cycles where id=v_final.source_cycle_id;
  select * into strict v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  if v_group.agency_id is distinct from v_bundle.agency_id then return null; end if;
  -- Final scope remains report/cutoff based, never substituted by workweek.
  if not exists(select 1 from public.weekly_source_client_manifests m where coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=v_final.id and m.source_cycle_id=v_cycle.id
        and m.client_id=v_contract.client_id) then return null; end if;
  v_inventory:=private.weekly_source_effective_inventory_v1(v_root.timesheet_id);
  v_basis:=v_inventory->'approval_basis';
  if (v_inventory->>'ok') is distinct from 'true'
     or (v_basis->>'coverage_complete') is distinct from 'true'
     or v_basis#>>'{origin,kind}' not in ('INITIAL_AUTHORISED_TSFIN_V1','COMMITTED_SOURCE_HEAD_V1')
     or v_basis#>>'{scope,root_timesheet_id}' is distinct from v_root.timesheet_id::text then return null; end if;
  select coalesce(jsonb_agg(c.value->'component_id' order by c.value->>'component_id'),'[]'::jsonb)
    into v_before_ids from jsonb_array_elements(v_inventory->'components') c(value);
  v_control:=jsonb_build_object('bundle_kind','SINGLE_ROOT','reason','WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION',
    'expected_current_head_ids',jsonb_build_array(coalesce(v_inventory->'head_id','null'::jsonb)),
    'before_positions',jsonb_build_array(jsonb_build_object('root_ordinal',1,
      'component_ids',v_before_ids,'inventory_digest',v_basis->>'inventory_digest')),
    'moved_component_ids','[]'::jsonb,'target_root_authorisation',null,'whole_root_office_review',null);
  if v_bundle.before_inventory_digest is distinct from private.weekly_source_publication_request_digest_v1(
      private.weekly_source_publication_before_inventory_v1(v_control,1)) then return null; end if;
  -- The existing eleven-field canonical encoder excludes control. Do not
  -- change its receipt hash domain. The complete before-origin/content digest
  -- is stored separately, and the live publisher compares its own controls.
  -- At first acceptance we also require the actual constructor's controls.
  if p_canonical ? 'control' and p_canonical->'control' is distinct from v_control then return null; end if;
  perform private.weekly_source_office_authority_v1(v_bundle.decided_by_user_id,
    'APPROVE_PROTECTED_PAY',v_group.id,v_contract.client_id,v_cycle.finalisation_week_ending);
  return jsonb_build_object('canonical',v_canonical,'basis',v_basis,
    'actor_user_id',v_bundle.decided_by_user_id,'agency_id',v_bundle.agency_id,
    'finalisation_week_ending',v_cycle.finalisation_week_ending);
end;
$function$;

create or replace function private.weekly_source_manual_review_source_v2(p_source_row_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_row public.weekly_source_upload_rows%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_report_scope public.weekly_source_report_scopes%rowtype;
  v_final public.weekly_source_final_revisions%rowtype;
  v_projection public.weekly_source_projection_publications%rowtype;
  v_mapping public.weekly_source_row_resolutions%rowtype;
  v_contract public.contracts%rowtype;
  v_count integer; v_resolution_id uuid; v_week date; v_generation integer;
begin
  select r.* into v_row from public.weekly_source_upload_rows r where r.id=p_source_row_id;
  if not found or v_row.row_finalisation_state not in ('NOT_APPLICABLE','SOURCE_WORKED') then return null; end if;
  select u.* into strict v_upload from public.weekly_source_uploads u where u.id=v_row.upload_id;
  select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_upload.source_cycle_id;
  if v_upload.report_scope_id is not null then
    select s.* into v_report_scope from public.weekly_source_report_scopes s
      where s.id=v_upload.report_scope_id and s.source_cycle_id=v_cycle.id
        and s.source_group_id=v_cycle.source_group_id and s.cutoff_at_utc=v_cycle.cutoff_at_utc;
    if not found then return null; end if;
  end if;
  select count(*) into v_count from public.weekly_source_final_revisions f
    where f.source_cycle_id=v_cycle.id and f.report_scope_id is not distinct from v_upload.report_scope_id
      and f.state='CURRENT';
  if v_count>1 then raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_AUTHORITY_AMBIGUOUS' using errcode='55000'; end if;
  if v_count=1 then
    select f.* into strict v_final from public.weekly_source_final_revisions f
      where f.source_cycle_id=v_cycle.id and f.report_scope_id is not distinct from v_upload.report_scope_id
        and f.state='CURRENT';
    if v_final.upload_id is distinct from v_upload.id or v_final.finalised_at_utc is null
       or not isfinite(v_final.finalised_at_utc) then return null; end if;
    if (v_final.authority_scope_kind='CYCLE' and (v_final.report_scope_id is not null
          or v_cycle.current_final_revision_id is distinct from v_final.id))
      or (v_final.authority_scope_kind='NHSP_REPORT_SCOPE' and (v_report_scope.id is null
          or v_report_scope.current_final_revision_id is distinct from v_final.id))
      or v_final.authority_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE') then return null; end if;
    select count(*),(array_agg(s.row_resolution_id))[1] into v_count,v_resolution_id
      from private.weekly_source_manual_review_final_rows_v2(v_final.id) s
      where s.upload_row_id=v_row.id;
    if v_count<>1 then return null; end if;
    select r.* into strict v_mapping from public.weekly_source_row_resolutions r where r.id=v_resolution_id;
  else
    if (v_upload.report_scope_id is null and v_cycle.current_final_revision_id is not null)
      or (v_upload.report_scope_id is not null and v_report_scope.current_final_revision_id is not null) then
      return null; end if;
    select count(*) into v_count from public.weekly_source_projection_publications p
      where p.source_cycle_id=v_cycle.id and p.report_scope_id is not distinct from v_upload.report_scope_id
        and p.upload_id=v_upload.id and p.state='CURRENT';
    if v_count<>1 then return null; end if;
    select p.* into strict v_projection from public.weekly_source_projection_publications p
      where p.source_cycle_id=v_cycle.id and p.report_scope_id is not distinct from v_upload.report_scope_id
        and p.upload_id=v_upload.id and p.state='CURRENT';
    if v_upload.state is distinct from 'CURRENT'
      or (v_projection.authority_scope_kind='CYCLE' and (v_projection.report_scope_id is not null
        or v_cycle.current_complete_upload_id is distinct from v_upload.id
        or v_cycle.current_projection_publication_id is distinct from v_projection.id
        or v_cycle.version is distinct from v_projection.authority_scope_version
        or v_cycle.projection_state is distinct from 'CURRENT'))
      or (v_projection.authority_scope_kind='NHSP_REPORT_SCOPE' and (v_report_scope.id is null
        or v_report_scope.current_complete_upload_id is distinct from v_upload.id
        or v_report_scope.current_projection_publication_id is distinct from v_projection.id
        or v_report_scope.version is distinct from v_projection.authority_scope_version
        or v_report_scope.projection_state is distinct from 'CURRENT'))
      or v_projection.authority_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE') then return null; end if;
    if v_projection.authority_scope_version>2147483647
       or coalesce(v_projection.projection_generation,0)>2147483647 then
      raise exception 'WEEKLY_SOURCE_PROJECTION_GENERATION_OVERFLOW' using errcode='22003'; end if;
    v_generation:=coalesce(v_projection.projection_generation,v_projection.authority_scope_version::integer);
    if v_generation is null or v_projection.published_at_utc is null
       or not isfinite(v_projection.published_at_utc) then return null; end if;
    select r.* into v_mapping from public.weekly_source_row_resolutions r
      where r.upload_row_id=v_row.id and r.generation=v_generation;
    if not found then return null; end if;
  end if;
  if v_mapping.mapping_state is distinct from 'RESOLVED'
     or v_mapping.upload_row_id is distinct from v_row.id then return null; end if;
  select c.* into strict v_contract from public.contracts c where c.id=v_mapping.contract_id;
  if v_contract.candidate_id is distinct from v_mapping.candidate_id
     or v_contract.client_id is distinct from v_mapping.client_id
     or v_contract.week_ending_weekday_snapshot is null
     or v_contract.week_ending_weekday_snapshot not between 0 and 6 then return null; end if;
  v_week:=v_row.work_date+((v_contract.week_ending_weekday_snapshot-extract(dow from v_row.work_date)::integer+7)%7);
  if not exists(select 1 from public.weekly_work_events e where e.id=v_mapping.work_event_id
    and e.candidate_id=v_mapping.candidate_id and e.client_id=v_mapping.client_id and e.work_date=v_row.work_date)
    or (v_final.id is not null and not exists(select 1 from public.weekly_source_client_manifests m where coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=v_final.id and m.client_id=v_mapping.client_id
        and m.source_group_id=v_cycle.source_group_id and m.source_cycle_id=v_cycle.id)) then return null; end if;
  return jsonb_build_object('source_group_id',v_cycle.source_group_id,'source_cycle_id',v_cycle.id,
    'upload_row_id',v_row.id,'row_resolution_id',v_mapping.id,'source_row_hash',encode(v_row.normalised_row_hash,'hex'),
    'work_event_id',v_mapping.work_event_id,'candidate_id',v_mapping.candidate_id,
    'client_id',v_mapping.client_id,'contract_id',v_mapping.contract_id,
    'work_date',to_char(v_row.work_date,'YYYY-MM-DD'),'week_ending_date',to_char(v_week,'YYYY-MM-DD'),
    'final_revision_id',v_final.id,'projection_publication_id',v_projection.id);
end;
$function$;

create or replace function private.weekly_source_manual_reviews_finalised_v1(p_final_revision_id uuid,p_actor_user_id uuid)
returns integer language plpgsql volatile security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_final public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_review private.weekly_source_manual_reviews%rowtype;
  v_anchor private.weekly_source_manual_review_commands%rowtype;
  v_opening_upload_id uuid;
  v_count integer:=0;
begin
  perform private.weekly_source_query_require_service_v1();
  select f.* into strict v_final from public.weekly_source_final_revisions f where f.id=p_final_revision_id;
  select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_final.source_cycle_id;
  if p_actor_user_id is null or v_final.state is distinct from 'CURRENT' or v_final.finalised_by_user_id is distinct from p_actor_user_id
     or v_final.finalised_at_utc is null or not isfinite(v_final.finalised_at_utc) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_FINAL_AUTHORITY_INVALID' using errcode='55000'; end if;
  perform private.weekly_source_pay_query_admit_v2();
  -- The sole reviewed Final/Correct mutation callers invoke this private hook
  -- after their successful CURRENT CAS, never on preparation or replay. Do not
  -- compare preparation timestamps, nor xmin to the top xid: the real owner
  -- may write in a PL/pgSQL exception subtransaction. Validate its actual CAS
  -- result here; caller closure and genuine-owner native proof are mandatory.
  if (v_final.authority_scope_kind='CYCLE' and v_cycle.current_final_revision_id is distinct from v_final.id)
    or (v_final.authority_scope_kind='NHSP_REPORT_SCOPE' and not exists(
      select 1 from public.weekly_source_report_scopes s where s.id=v_final.report_scope_id
        and s.source_cycle_id=v_cycle.id and s.current_final_revision_id=v_final.id)) then
    raise exception 'WEEKLY_SOURCE_MANUAL_REVIEW_FINAL_AUTHORITY_INVALID' using errcode='55000'; end if;
  for v_review in
    with contained as materialized (
      select distinct s.work_event_id,s.candidate_id,s.client_id,s.contract_id,s.work_date
      from private.weekly_source_manual_review_final_rows_v2(v_final.id) s
    )
    select r.* from contained s join private.weekly_source_manual_reviews r
      on r.source_group_id=v_cycle.source_group_id and r.work_event_id=s.work_event_id and r.state='OPEN'
      and r.candidate_id=s.candidate_id and r.client_id=s.client_id
      and r.contract_id=s.contract_id and r.work_date=s.work_date
    order by r.id for update of r
  loop
    select c.* into v_anchor from private.weekly_source_manual_review_commands c where c.review_id=v_review.id
      and (c.opening_final_revision_id is not null or c.opening_projection_publication_id is not null);
    -- A legacy review without captured opening provenance needs an explicit
    -- Office remedy. Never manufacture an anchor using today's report.
    if not found or v_anchor.opening_final_revision_id=p_final_revision_id
       or not exists(select 1 from public.weekly_source_client_manifests m where coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=v_final.id
         and m.source_group_id=v_cycle.source_group_id and m.source_cycle_id=v_cycle.id and m.client_id=v_review.client_id) then continue; end if;
    -- A new Final for the report already queried is not a new imported report.
    -- Resolve the immutable opening authority, not preparation timestamps or
    -- the currently displayed row; rebuilt projections of that upload also
    -- remain the same report. Missing opening evidence is never a remedy.
    if v_anchor.opening_final_revision_id is not null then
      select f.upload_id into v_opening_upload_id from public.weekly_source_final_revisions f
        where f.id=v_anchor.opening_final_revision_id;
    else
      select p.upload_id into v_opening_upload_id from public.weekly_source_projection_publications p
        where p.id=v_anchor.opening_projection_publication_id;
    end if;
    if v_opening_upload_id is null or v_opening_upload_id=v_final.upload_id then continue; end if;
    perform private.weekly_source_office_authority_v1(p_actor_user_id,'ACCEPT_SYSTEM_HOURS',
      v_cycle.source_group_id,v_review.client_id,v_cycle.finalisation_week_ending);
    update private.weekly_source_manual_reviews set state='RESOLVED',resolved_by_user_id=p_actor_user_id,
      resolved_at_utc=statement_timestamp(),resolution_kind='OFFICE_ACCEPTED_SOURCE' where id=v_review.id;
    perform public._audit_insert('weekly_source_manual_review',v_review.id::text,'WEEKLY_SOURCE_MANUAL_REVIEW_RESOLVED',null,
      jsonb_build_object('resolution_kind','OFFICE_ACCEPTED_SOURCE','work_event_id',v_review.work_event_id,
        'final_revision_id',v_final.id,'reason','A later finalised report contains this shift'),
      'Later finalised source report resolved imported-shift review',p_actor_user_id);
    v_count:=v_count+1;
  end loop;
  return v_count;
end;
$function$;

create or replace function private.weekly_source_invoice_duty_v1(p_root_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_root public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_scope jsonb; v_ids uuid[]; v_groups uuid[]; v_invoices uuid[];
  v_movement public.weekly_source_billing_movements%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_row public.weekly_source_upload_rows%rowtype;
  v_resolution public.weekly_source_row_resolutions%rowtype;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_operation public.invoice_operations%rowtype;
  v_chunk public.invoice_operation_chunks%rowtype;
  v_member jsonb; v_members jsonb; v_context jsonb; v_guard jsonb; v_policy jsonb;
  v_basis jsonb:='[]'::jsonb; v_observation boolean;
  v_present boolean:=false; v_unknown boolean:=false;
  v_generation integer; v_count integer; v_invoice_id uuid; v_member_id uuid;
  v_linked_root uuid; v_text text; v_week date; v_relevant boolean;
  v_prior record;
begin
  select * into v_root from public.timesheets where timesheet_id=p_root_timesheet_id;
  if not found then return null; end if;
  select * into strict v_contract from public.contracts where id=v_root.contract_id;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  v_ids:=private.weekly_source_invoice_family_timesheet_ids_v1(p_root_timesheet_id);
  if v_scope is null or cardinality(v_ids) is null or cardinality(v_ids)=0 then return null; end if;
  select array_agg(distinct source_group_id) filter(where source_group_id is not null) into v_groups from (
    select c.source_group_id from public.weekly_source_row_timesheet_lineages l
      join public.weekly_source_cycles c on c.id=l.source_cycle_id where l.timesheet_id=any(v_ids)
    union select e.first_source_group_id from public.weekly_exceptional_pay_family_events fe
      join public.weekly_work_events e on e.id=fe.durable_work_event_id
      where fe.family_id=(v_scope->>'target_family_id')::uuid
    union select membership.source_group_id from public.weekly_source_group_clients membership
      where membership.client_id=v_contract.client_id
        and membership.valid_from<=v_root.week_ending_date
        and coalesce(membership.valid_to,'infinity'::date)>=v_root.week_ending_date-6
  ) groups;
  if cardinality(v_groups) is null or cardinality(v_groups)=0 then return null; end if;
  v_basis:=jsonb_build_array(jsonb_build_object('lane','DISCOVERY','groups',to_jsonb(v_groups),
    'scope',v_scope,'family_timesheet_ids',to_jsonb(v_ids)));
  select coalesce(array_agg(distinct l.invoice_id),'{}'::uuid[]) into v_invoices
    from public.invoice_lines l where l.timesheet_id=any(v_ids);

  -- Incomplete publication is not an empty invoice census. Discover across
  -- all cutoffs using client/group and actual work-date coverage, not the
  -- report's week. Nullable/unparsed date coverage remains relevant unknown.
  for v_upload in select u.* from public.weekly_source_uploads u
    join public.weekly_source_cycles c on c.id=u.source_cycle_id
    left join public.weekly_source_report_scopes s on s.id=u.report_scope_id
    where c.source_group_id=any(v_groups) and u.state not in ('CURRENT','SUPERSEDED','REJECTED')
      and (c.scope_client_id is null or c.scope_client_id=v_contract.client_id)
      and (s.client_id is null or s.client_id=v_contract.client_id)
      and (u.confirmed_coverage_start_local_date is null or u.confirmed_coverage_end_local_date is null
        or daterange(u.confirmed_coverage_start_local_date,u.confirmed_coverage_end_local_date+1,'[)')
          && daterange(v_root.week_ending_date-6,v_root.week_ending_date+1,'[)')
        or exists(select 1 from public.weekly_source_upload_rows r where r.upload_id=u.id
          and (r.work_date is null or r.work_date between v_root.week_ending_date-6 and v_root.week_ending_date)))
    order by u.id loop
    -- Prepared corrections have their complete old/new census below; they
    -- must not be permanently made unknown by their own CORRECTION_READY row.
    if v_upload.state='CORRECTION_READY' and exists(select 1 from public.weekly_final_source_correction_sessions s
      where s.id=v_upload.correction_session_id and s.replacement_correction_upload_id=v_upload.id
        and s.state in ('PREPARING','PREPARED','COMMITTING')) then continue; end if;
    v_unknown:=true;
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','INCOMPLETE_IMPORT',
      'upload',to_jsonb(v_upload),'present',null));
  end loop;

  -- Placement remains a duty across report cutoffs. A historical issued
  -- document alone is not work waiting to be invoiced again.
  for v_movement in select * from public.weekly_source_billing_movements where invoice_timesheet_id=any(v_ids)
    order by id loop
    v_observation:=null;
    if v_movement.candidate_id=v_contract.candidate_id and v_movement.contract_id=v_contract.id
       and v_movement.actual_client_id=v_contract.client_id then
      if v_movement.placement_state in ('UNPLACED','PLACED') then
        -- Prepared replacements are not yet admitted invoice movements. Their
        -- complete union and current seals are qualified in CORRECTION below.
        if exists(select 1 from public.weekly_source_final_revisions f
          where f.id=v_movement.final_revision_id and f.state='PREPARED') then
          if exists(select 1 from public.weekly_final_source_correction_sessions s
            where s.prepared_final_revision_id=v_movement.final_revision_id
              and s.state in ('PREPARING','PREPARED','COMMITTING')) then continue; end if;
        end if;
        if exists(select 1 from public.weekly_source_final_revisions f
          where f.id=v_movement.final_revision_id and f.state='CURRENT'
            and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)) then v_observation:=true; end if;
      elsif v_movement.placement_state='VOIDED_BY_CORRECT_FINAL' then
        if not exists(select 1 from public.weekly_source_invoice_line_bindings b
          where b.billing_movement_id=v_movement.id and b.state='CURRENT') then v_observation:=false; end if;
      elsif v_movement.placement_state='ISSUED' and exists(
        select 1 from public.weekly_source_invoice_line_bindings b
        join public.invoice_lines l on l.id=b.invoice_line_id and l.invoice_id=b.invoice_id
        join public.invoices i on i.id=b.invoice_id
        where b.billing_movement_id=v_movement.id and b.state='CURRENT'
          and b.client_id=v_movement.actual_client_id and i.client_id=v_movement.actual_client_id
          and l.timesheet_id=v_movement.invoice_timesheet_id
          and (i.status::text='ISSUED' or i.issue_state='ISSUED')) then v_observation:=false; end if;
    end if;
    v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','MOVEMENT','id',v_movement.id,
      'hash',encode(v_movement.movement_economic_hash,'hex'),'placement',v_movement.placement_state,'present',v_observation));
  end loop;

  -- Actual current imports, independent of their report/cutoff week. A
  -- checking-only NHSP import is positively excluded, not invoice authority.
  for v_upload in select u.* from public.weekly_source_uploads u
    join public.weekly_source_cycles c on c.id=u.source_cycle_id
    left join public.weekly_source_report_scopes s on s.id=u.report_scope_id
    where c.source_group_id=any(v_groups) and u.state='CURRENT'
      and (c.scope_client_id is null or c.scope_client_id=v_contract.client_id)
      and (s.client_id is null or s.client_id=v_contract.client_id) order by u.id
  loop
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CURRENT_IMPORT',
      'upload',to_jsonb(v_upload),'cycle',(select to_jsonb(c) from public.weekly_source_cycles c where c.id=v_upload.source_cycle_id),
      'report_scope',(select to_jsonb(s) from public.weekly_source_report_scopes s where s.id=v_upload.report_scope_id)));
    select * into strict v_profile from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
    if v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1' or v_profile.profile_json->>'purpose'='PREFINAL_CHECKING'
       or v_profile.row_finalisation_capability='CHECKING_ONLY' then continue; end if;
    -- A genuinely consumed Final already has its placement census above.
    if exists(select 1 from public.weekly_source_final_revisions f
      join public.weekly_source_cycles c on c.id=f.source_cycle_id
      left join public.weekly_source_report_scopes s on s.id=f.report_scope_id
      where f.upload_id=v_upload.id and f.source_cycle_id=v_upload.source_cycle_id
        and f.report_scope_id is not distinct from v_upload.report_scope_id
        and f.state='CURRENT' and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)
        and ((f.authority_scope_kind='CYCLE' and s.id is null and c.current_final_revision_id=f.id)
          or (f.authority_scope_kind='NHSP_REPORT_SCOPE' and s.current_final_revision_id=f.id))) then continue; end if;
    select count(*) into v_count from public.weekly_source_projection_publications p
      where p.upload_id=v_upload.id and p.source_cycle_id=v_upload.source_cycle_id
        and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT';
    if v_count<>1 then v_unknown:=true; continue; end if;
    select * into strict v_publication from public.weekly_source_projection_publications p
      where p.upload_id=v_upload.id and p.source_cycle_id=v_upload.source_cycle_id
        and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT';
    begin
      v_guard:=private.weekly_source_current_publication_guard_v1(v_upload.source_cycle_id,
        v_publication.authority_scope_kind,v_upload.report_scope_id,v_upload.id,v_publication.id,v_publication.authority_scope_version);
    exception when sqlstate '55000' or sqlstate '22023' then v_unknown:=true; continue; end;
    if v_publication.authority_scope_version>2147483647 or coalesce(v_publication.projection_generation,0)>2147483647
       or v_publication.published_at_utc is null or not isfinite(v_publication.published_at_utc) then
      v_unknown:=true; continue; end if;
    v_generation:=coalesce(v_publication.projection_generation,v_publication.authority_scope_version::integer);
    -- Match the genuine roster Final owner's complete prior/current union.
    -- A prior root may own a reversal when its event is omitted inside coverage
    -- OR retained by a current row that moves it to another root/work week.
    -- NHSP NO_INFERENCE does not use roster omission authority.
    if v_profile.final_authority_kind in ('GENERIC_COMPLETE_SNAPSHOT','HEALTHROSTER_ACTUAL_ROWS')
       and v_profile.omission_meaning='CANCEL_INSIDE_CONFIRMED_COVERAGE' then
      for v_prior in
        with prior_states as (
          select distinct on(t.work_event_id) t.new_snapshot_line_id,t.id as transition_id
          from public.weekly_source_state_transitions t
          join public.weekly_source_final_revisions f on f.id=t.final_revision_id and f.state='CURRENT'
          join public.weekly_source_cycles c on c.id=t.finalisation_cycle_id
          join public.weekly_source_client_manifests m on coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=f.id and m.client_id=v_contract.client_id
          where t.source_profile_kind=v_profile.final_authority_kind
            and c.source_group_id=(select source_group_id from public.weekly_source_cycles where id=v_upload.source_cycle_id)
            and c.finalisation_week_ending<(select finalisation_week_ending from public.weekly_source_cycles where id=v_upload.source_cycle_id)
          order by t.work_event_id,c.finalisation_week_ending desc,f.finalised_at_utc desc,
            f.revision_number desc,t.created_at_utc desc,t.id desc
        ) select line.*,s.transition_id,
            exists(select 1 from public.weekly_source_row_resolutions r
              join public.weekly_source_upload_rows current_row on current_row.id=r.upload_row_id
              where current_row.upload_id=v_upload.id and r.generation=v_generation
                and r.work_event_id=line.work_event_id) as has_current_replacement
          from prior_states s
          join public.weekly_source_final_snapshot_lines line on line.id=s.new_snapshot_line_id
          where line.candidate_id=v_contract.candidate_id and line.contract_id=v_contract.id
            and line.client_id=v_contract.client_id
            and line.work_date between v_root.week_ending_date-6 and v_root.week_ending_date
          order by line.id
      loop
        v_observation:=null;
        if v_upload.coverage_state='COMPLETE' and v_upload.coverage_confirmed_by_user_id is not null
           and v_upload.coverage_confirmed_at_utc is not null and isfinite(v_upload.coverage_confirmed_at_utc)
           and v_upload.coverage_timezone='Europe/London'
           and v_upload.confirmed_coverage_start_local_date is not null
           and v_upload.confirmed_coverage_end_local_date is not null
           and (v_prior.work_date between v_upload.confirmed_coverage_start_local_date and v_upload.confirmed_coverage_end_local_date
             or v_prior.has_current_replacement) then
          begin
            v_policy:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,v_prior.work_date);
            v_linked_root:=private.weekly_source_finalisation_lineage_assert_v1(v_prior.row_resolution_id,
              (select source_cycle_id from public.weekly_source_final_revisions where id=v_prior.final_revision_id));
            if v_linked_root=p_root_timesheet_id and v_policy->>'authority_mode'='SOURCE_AUTHORITY'
               and v_policy->>'self_bill_enabled'='true'
               and v_policy->>'source_group_id'=(select source_group_id::text from public.weekly_source_cycles where id=v_upload.source_cycle_id)
              then v_observation:=true; end if;
          exception when sqlstate '55000' or sqlstate '40001' or sqlstate '22023' then null; end;
        elsif v_upload.coverage_state='COMPLETE'
           and v_upload.confirmed_coverage_start_local_date is not null
           and v_upload.confirmed_coverage_end_local_date is not null
           and not v_prior.has_current_replacement
           and v_prior.work_date not between v_upload.confirmed_coverage_start_local_date and v_upload.confirmed_coverage_end_local_date
          then v_observation:=false;
        end if;
        v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
        v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','PREFINAL_ROSTER_PRIOR_CURRENT_UNION',
          'prior_snapshot',to_jsonb(v_prior),'publication',to_jsonb(v_publication),'present',v_observation));
      end loop;
    end if;
    for v_row in select * from public.weekly_source_upload_rows where upload_id=v_upload.id
      and (work_date is null or work_date between v_root.week_ending_date-6 and v_root.week_ending_date) order by id loop
      select * into v_resolution from public.weekly_source_row_resolutions
        where upload_row_id=v_row.id and generation=v_generation;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CURRENT_ROW_DISCOVERY',
        'row_id',v_row.id,'row_hash',encode(v_row.normalised_row_hash,'hex'),
        'resolution',to_jsonb(v_resolution),'publication',to_jsonb(v_publication)));
      if not found then v_unknown:=true; continue; end if;
      if v_resolution.candidate_id is not null and v_resolution.candidate_id<>v_contract.candidate_id
         or v_resolution.client_id is not null and v_resolution.client_id<>v_contract.client_id
         or v_resolution.contract_id is not null and v_resolution.contract_id<>v_contract.id then continue; end if;
      if v_resolution.mapping_state<>'RESOLVED' or v_row.work_date is null
         or v_contract.week_ending_weekday_snapshot is null
         or v_contract.week_ending_weekday_snapshot not between 0 and 6
         or v_row.work_date<v_contract.start_date
         or (v_contract.end_date is not null and v_row.work_date>v_contract.end_date)
         or v_root.submission_mode is distinct from 'MANUAL' then v_unknown:=true; continue; end if;
      begin
        v_policy:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,v_row.work_date);
      exception when sqlstate '55000' or sqlstate '22023' then v_unknown:=true; continue; end;
      if v_policy->>'authority_mode' is distinct from 'SOURCE_AUTHORITY'
         or v_policy->>'self_bill_enabled' is distinct from 'true'
         or v_policy->>'source_group_id' is distinct from (
           select c.source_group_id::text from public.weekly_source_cycles c where c.id=v_upload.source_cycle_id)
         or encode(v_resolution.effective_policy_fingerprint,'hex') is distinct from v_policy->>'policy_sha256'
         then v_unknown:=true; continue; end if;
      v_week:=v_row.work_date+((v_contract.week_ending_weekday_snapshot-extract(dow from v_row.work_date)::integer+7)%7);
      if v_week<>v_root.week_ending_date then continue; end if;
      v_linked_root:=null;
      if exists(select 1 from public.weekly_source_row_timesheet_lineages where row_resolution_id=v_resolution.id) then
        begin
          v_linked_root:=private.weekly_source_finalisation_lineage_assert_v1(v_resolution.id,v_upload.source_cycle_id);
        exception when sqlstate '55000' or sqlstate '40001' then v_unknown:=true; continue; end;
      else
        select cw.timesheet_id into v_linked_root from public.contract_weeks cw
          where cw.contract_id=v_contract.id and cw.week_ending_date=v_week and cw.additional_seq=0
            and not cw.is_adjustment and cw.status<>'CANCELLED'
            and cw.submission_mode_snapshot='MANUAL';
      end if;
      if v_linked_root is distinct from p_root_timesheet_id
         or not v_root.is_current or v_root.is_adjustment or v_root.revoked_at is not null
         or v_root.archived_at_utc is not null or v_root.sheet_scope<>'WEEKLY' or v_root.line_type<>'HOURS' then
        v_unknown:=true; continue; end if;
      v_present:=true;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','PREFINAL','row_id',v_row.id,
        'resolution_id',v_resolution.id,'generation',v_generation,'publication_guard',v_guard));
    end loop;
  end loop;

  -- Correct Final's full old/new union includes removal of its last movement.
  -- Unprepared or stale relevant replacements stay unknown, not empty.
  for v_session in select s.* from public.weekly_final_source_correction_sessions s
    join public.weekly_source_cycles c on c.id=s.source_cycle_id
    where c.source_group_id=any(v_groups) and s.state in ('DRAFT','STAGING','READY','REVIEWED','PREPARING','PREPARED','COMMITTING')
      and exists(select 1 from public.weekly_source_client_manifests m where coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=s.expected_current_final_revision_id and m.client_id=v_contract.client_id) order by s.id
  loop
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CORRECTION_DISCOVERY','session',to_jsonb(v_session)));
    if exists(select 1 from public.weekly_source_ordinary_pay_projection_receipts r
      where r.final_revision_id=v_session.expected_current_final_revision_id and r.root_timesheet_id=any(v_ids)
        and r.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED')) then
      if v_session.prepared_final_revision_id is null then v_unknown:=true; continue; end if;
    elsif v_session.prepared_final_revision_id is null then v_unknown:=true; continue; end if;
    begin v_context:=private.weekly_source_correct_final_prepared_context_v1(v_session.id);
    exception when sqlstate '55000' then v_unknown:=true; continue; end;
    if v_session.prepare_result_hash is distinct from private.weekly_source_sha256_jsonb_v1(
         'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_RESULT_V1',v_session.prepare_result_json)
       or v_context->'root_contexts' is distinct from v_session.prepare_result_json->'root_contexts'
       or not exists(select 1 from public.weekly_source_final_revisions f
         join public.weekly_source_cycles c on c.id=f.source_cycle_id
         left join public.weekly_source_report_scopes s on s.id=f.report_scope_id
         where f.id=v_session.expected_current_final_revision_id and f.state='CURRENT'
           and f.manifest_hash=v_session.expected_final_manifest_hash
           and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)
           and f.source_cycle_id=v_session.source_cycle_id and f.report_scope_id is not distinct from v_session.report_scope_id
           and ((f.authority_scope_kind='CYCLE' and c.current_final_revision_id=f.id)
             or (f.authority_scope_kind='NHSP_REPORT_SCOPE' and s.current_final_revision_id=f.id)))
       or not exists(select 1 from public.weekly_source_projection_publications p
         join public.weekly_source_uploads u on u.id=p.upload_id
         join public.weekly_source_final_revisions f on f.id=v_session.prepared_final_revision_id
         join public.weekly_source_format_profiles profile on profile.id=u.source_format_profile_id
         join public.weekly_source_final_revisions prior on prior.id=v_session.expected_current_final_revision_id
         join public.weekly_source_uploads prior_upload on prior_upload.id=prior.upload_id
         join public.weekly_source_format_profiles prior_profile on prior_profile.id=prior_upload.source_format_profile_id
         join public.weekly_source_cycles cycle on cycle.id=v_session.source_cycle_id
         join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
         left join public.weekly_source_report_scopes report_scope on report_scope.id=v_session.report_scope_id
         where p.id=v_session.replacement_projection_publication_id and u.id=v_session.replacement_correction_upload_id
           and p.state='CORRECTION_READY' and u.state='CORRECTION_READY'
           and p.correction_session_id=v_session.id and u.correction_session_id=v_session.id
           and p.source_cycle_id=v_session.source_cycle_id and u.source_cycle_id=v_session.source_cycle_id
           and p.report_scope_id is not distinct from v_session.report_scope_id
           and u.report_scope_id is not distinct from v_session.report_scope_id
           and u.purpose='FINAL_SOURCE_CORRECTION'
           and p.authority_scope_kind=v_session.authority_scope_kind
           and u.row_manifest_hash is not null and p.comparison_manifest_hash is not null and p.issue_set_hash is not null
           and p.authority_scope_version=case when v_session.authority_scope_kind='NHSP_REPORT_SCOPE'
             then report_scope.version else cycle.version end
           and prior_upload.state='CURRENT'
           and exists(select 1 from public.weekly_source_projection_publications current_publication
             where current_publication.id=case when v_session.authority_scope_kind='NHSP_REPORT_SCOPE'
               then report_scope.current_projection_publication_id else cycle.current_projection_publication_id end
               and current_publication.state='CURRENT' and current_publication.upload_id=prior_upload.id)
           and profile.final_authority_kind=prior_profile.final_authority_kind
           and (profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')=(source_group.source_family='NHSP')
           and f.state='PREPARED' and f.reason='CORRECT_FINAL_SOURCE'
           and f.upload_id=u.id and f.source_cycle_id=cycle.id
           and f.report_scope_id is not distinct from v_session.report_scope_id
           and f.predecessor_revision_id=prior.id
           and v_session.prepare_result_json->>'final_revision_id'=f.id::text
           and f.manifest_hash=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_FINAL_REVISION_MANIFEST_V1',
             jsonb_build_object('source_cycle_id',cycle.id,'authority_scope_kind',v_session.authority_scope_kind,
               'report_scope_id',v_session.report_scope_id,'revision_number',f.revision_number,'upload_id',u.id,
               'authority_scope_version',p.authority_scope_version,'row_manifest_hash',encode(u.row_manifest_hash,'hex'),
               'comparison_manifest_hash',encode(p.comparison_manifest_hash,'hex'),'issue_set_hash',encode(p.issue_set_hash,'hex'),
               'profile_code',profile.profile_code,'profile_version',profile.version,
               'coverage_start_local_date',f.coverage_start_local_date,'coverage_end_local_date',f.coverage_end_local_date,
               'reason',f.reason,'predecessor_revision_id',f.predecessor_revision_id,
               'prior_state_cutoff_revision_id',f.prior_state_cutoff_revision_id,
               'policy_fingerprint',encode(f.policy_fingerprint,'hex')))) then
      v_unknown:=true; continue; end if;
    v_guard:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
    if v_session.prepare_result_json->'office_preview' is distinct from v_guard
       or v_session.review_result_json->'office_preview' is distinct from v_guard
       or jsonb_array_length(v_guard->'blockers')<>0 then v_unknown:=true; continue; end if;
    if not exists(select 1 from jsonb_array_elements(v_context->'root_contexts') r
      where (r->>'root_timesheet_id')::uuid=any(v_ids)) then continue; end if;
    v_present:=true;
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CORRECTION','session_id',v_session.id,
      'prepared_context',v_context,'prepare_result_hash',encode(v_session.prepare_result_hash,'hex')));
  end loop;

  -- Use actual committed member chunks, not a client-wide fence. Ordinary
  -- selection expanders already exclude Source-owned roots in their owner.
  for v_chunk in select c.* from public.invoice_operation_chunks c
    join public.invoice_operations o on o.id=c.operation_id
    where o.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and c.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and (not c.is_manifest_member or c.manifest_committed)
      and coalesce(c.payload_json->>'is_selection_expander','false')<>'true'
      and (not c.is_manifest_member or coalesce(c.entity_type,'')<>'OPERATION') order by c.id
  loop
    select * into strict v_operation from public.invoice_operations where id=v_chunk.operation_id;
    v_observation:=false;
    v_relevant:=(v_chunk.entity_type='TIMESHEET' and v_chunk.entity_id=any(v_ids))
      or (v_chunk.entity_type='INVOICE' and v_chunk.entity_id=any(v_invoices))
      or (v_operation.entity_type='TIMESHEET' and v_operation.entity_id=any(v_ids))
      or (v_operation.entity_type='INVOICE' and v_operation.entity_id=any(v_invoices));
    if v_chunk.entity_type='TIMESHEET' and v_chunk.entity_id=any(v_ids) then
      if v_operation.operation_type in ('GENERATE_INVOICES','ISSUE_INVOICES','RECONCILE_INVOICE_WORK') then v_observation:=true;
      elsif v_operation.operation_type='BUILD_DOCUMENT' then v_observation:=null; end if;
    end if;
    if v_chunk.payload_json->>'command_type'='GENERATE_CREDIT_NOTE' then
      v_text:=coalesce(v_chunk.payload_json->>'source_invoice_id',v_chunk.entity_id::text);
      if coalesce(v_text,'')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        if v_relevant then v_observation:=null; end if;
      else
        v_invoice_id:=v_text::uuid;
        if (v_chunk.entity_type='INVOICE' and v_chunk.entity_id=any(v_invoices)
          and v_chunk.entity_id is distinct from v_invoice_id) then
          v_observation:=null;
        elsif v_invoice_id=any(v_invoices) then
          v_relevant:=true;
          if v_chunk.entity_id is not null and v_chunk.entity_id<>v_invoice_id then v_observation:=null;
          else v_observation:=true; end if;
        end if;
      end if;
    elsif v_operation.operation_type='GENERATE_INVOICES' then
      v_members:=v_chunk.payload_json->'canonical_source_members';
      if v_chunk.payload_json ? 'canonical_source_members' and jsonb_typeof(v_members) is distinct from 'array' then
        -- A malformed primary manifest must not be replaced by fallback IDs.
        -- Fallback membership is discovery only, to qualify the relevant NULL.
        v_members:=coalesce(v_chunk.payload_json->'canonical_source_ids',v_chunk.payload_json->'source_ids','[]'::jsonb);
        if jsonb_typeof(v_members)='array' and exists(select 1 from jsonb_array_elements_text(v_members) s(value)
          where lower(s.value)=any(select id::text from unnest(v_ids) id)) then v_relevant:=true; end if;
        if v_relevant then v_observation:=null; end if;
        v_members:='[]'::jsonb;
      elsif v_members is null or jsonb_array_length(v_members)=0 then
        v_members:=coalesce(v_chunk.payload_json->'canonical_source_ids',v_chunk.payload_json->'source_ids','[]'::jsonb);
        if jsonb_typeof(v_members) is distinct from 'array' then
          if v_relevant then v_observation:=null; end if;
          v_members:='[]'::jsonb;
        else
          select coalesce(jsonb_agg(jsonb_build_object('source_type','TIMESHEET','source_id',s.value,
            'related_timesheet_id',s.value) order by s.ordinality),'[]'::jsonb) into v_members
            from jsonb_array_elements_text(v_members) with ordinality s(value,ordinality);
        end if;
      end if;
      -- Discover actual membership before validating ANY member, so malformed
      -- earlier evidence cannot disappear merely because the owned root is last.
      if exists(select 1 from jsonb_array_elements(v_members) m(value)
        where lower(m.value->>'related_timesheet_id')=any(select id::text from unnest(v_ids) id)
          or lower(m.value->>'source_id')=any(select id::text from unnest(v_ids) id)) then v_relevant:=true; end if;
      for v_member in select value from jsonb_array_elements(v_members) loop
        -- Canonical TIMESHEET members carry both independently valid identities.
        -- COALESCE cannot let a valid related ID conceal a malformed source ID.
        if upper(coalesce(v_member->>'source_type','TIMESHEET'))='TIMESHEET' then
          if coalesce(v_member->>'source_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             or coalesce(v_member->>'related_timesheet_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
            if v_relevant then v_observation:=null; end if;
            continue;
          end if;
          if (v_member->>'source_id')::uuid is distinct from (v_member->>'related_timesheet_id')::uuid then
            if v_relevant then v_observation:=null; end if;
            continue;
          end if;
        end if;
        v_text:=coalesce(v_member->>'related_timesheet_id',v_member->>'source_id');
        if coalesce(v_text,'')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          if v_relevant then v_observation:=null; end if;
          continue; end if;
        v_member_id:=v_text::uuid;
        if v_member_id=any(v_ids) then
          v_relevant:=true;
          if upper(coalesce(v_member->>'source_type','TIMESHEET'))='TIMESHEET' then
            if v_observation is not null then v_observation:=true; end if;
          else v_observation:=null; end if;
        end if;
      end loop;
    else
      v_text:=coalesce(v_chunk.payload_json->>'invoice_id',case when v_chunk.entity_type='INVOICE' then v_chunk.entity_id::text end);
      if v_chunk.entity_type='INVOICE' and v_chunk.entity_id=any(v_invoices)
         and v_text is distinct from v_chunk.entity_id::text then v_observation:=null;
      elsif v_text ~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and v_text::uuid=any(v_invoices) then
        v_relevant:=true;
        if v_operation.operation_type='ISSUE_INVOICES' then v_observation:=true;
        elsif v_operation.operation_type='BUILD_DOCUMENT' then v_observation:=null; end if;
      end if;
    end if;
    if v_relevant then
      v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','OPERATION_CHUNK',
        'operation',to_jsonb(v_operation),'chunk',to_jsonb(v_chunk),'present',v_observation));
    end if;
  end loop;
  -- ISSUE can be queued before its exact invoice chunks have been expanded.
  for v_operation in select * from public.invoice_operations where operation_type='ISSUE_INVOICES'
    and status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED') order by id loop
    v_relevant:=v_operation.entity_type='INVOICE' and v_operation.entity_id=any(v_invoices);
    v_observation:=case when v_relevant then true else false end;
    if v_operation.input_json ? 'invoice_ids' then
      if jsonb_typeof(v_operation.input_json->'invoice_ids') is distinct from 'array' then
        if v_relevant then v_observation:=null; end if;
      else
        v_members:=v_operation.input_json->'invoice_ids';
        if exists(select 1 from jsonb_array_elements_text(v_members) s(value)
          where lower(s.value)=any(select id::text from unnest(v_invoices) id)) then v_relevant:=true; end if;
        if v_relevant then
          if exists(select 1 from jsonb_array_elements_text(v_members) s(value)
            where coalesce(s.value,'')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
            then v_observation:=null; else v_observation:=true; end if;
        end if;
      end if;
    end if;
    if v_relevant then
      v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','QUEUED_ISSUE',
        'operation',to_jsonb(v_operation),'present',v_observation));
    end if;
  end loop;
  return jsonb_build_object('scope',v_scope,'present',case when v_present then true when v_unknown then null else false end,
    'discovery_complete',not v_unknown,'basis',v_basis);
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function public.weekly_source_correct_final_open_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','authority_scope_kind','expected_current_final_revision_id',
    'expected_final_manifest_hash','idempotency_key','reason','report_scope_id',
    'schema_version','source_cycle_id'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_cycle_id uuid;
  v_scope_kind text;
  v_report_scope_id uuid;
  v_revision_id uuid;
  v_expected_manifest bytea;
  v_idempotency_key text;
  v_reason text;
  v_request_hash bytea;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_revision public.weekly_source_final_revisions%rowtype;
  v_existing public.weekly_final_source_correction_sessions%rowtype;
  v_existing_by_key public.weekly_final_source_correction_sessions%rowtype;
  v_existing_by_hash public.weekly_final_source_correction_sessions%rowtype;
  v_existing_key_count bigint;
  v_existing_hash_count bigint;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_guard jsonb;
  v_group_id uuid;
  v_client_id uuid;
  v_guard_fingerprint bytea;
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_OPEN_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_cycle_id:=(p_request->>'source_cycle_id')::uuid;
    v_scope_kind:=pg_catalog.upper(pg_catalog.btrim(p_request->>'authority_scope_kind'));
    v_report_scope_id:=nullif(p_request->>'report_scope_id','')::uuid;
    v_revision_id:=(p_request->>'expected_current_final_revision_id')::uuid;
    v_expected_manifest:=pg_catalog.decode(p_request->>'expected_final_manifest_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_actor is null or v_cycle_id is null or v_revision_id is null
     or v_scope_kind not in ('CYCLE','NHSP_REPORT_SCOPE')
     or (v_scope_kind='NHSP_REPORT_SCOPE') is distinct from (v_report_scope_id is not null)
     or pg_catalog.octet_length(v_expected_manifest)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_OPEN_V1',p_request-'idempotency_key'
  );
  -- WP-59.  Two defects lived in this one replay lookup.
  --
  -- (1) It chose between an idempotency-key match and a request-hash match with
  --     `order by ... limit 1`.  That is a safety decision taken by an
  --     ordering, which this programme forbids.  Both candidates are now read
  --     explicitly, each with its own cardinality check, and a disagreement
  --     between them fails closed instead of being silently ranked away.
  --
  -- (2) It matched a session in ANY state.  Before WP-59 that was harmless
  --     because no session could ever leave the live set.  Now that
  --     public.weekly_source_correct_final_cancel_atomic_v1 exists, re-sending
  --     the request that opened a since-cancelled session would have returned
  --     that cancelled session as an idempotent replay -- telling Office it
  --     still has a correction session when it has none.  A terminal session is
  --     never replayed as if it were live; the caller is told so in a typed
  --     refusal and must open the new correction with its own key.
  select pg_catalog.count(*) into v_existing_key_count
  from public.weekly_final_source_correction_sessions correction
  where correction.actor_user_id=v_actor
    and correction.idempotency_key=v_idempotency_key;
  select pg_catalog.count(*) into v_existing_hash_count
  from public.weekly_final_source_correction_sessions correction
  where correction.request_hash=v_request_hash;
  if v_existing_key_count>1 or v_existing_hash_count>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_AMBIGUOUS'
      using errcode='55000',
        detail='key_matches='||v_existing_key_count::text
               ||' request_hash_matches='||v_existing_hash_count::text;
  end if;
  if v_existing_key_count=1 then
    select * into v_existing_by_key
    from public.weekly_final_source_correction_sessions correction
    where correction.actor_user_id=v_actor
      and correction.idempotency_key=v_idempotency_key;
  end if;
  if v_existing_hash_count=1 then
    select * into v_existing_by_hash
    from public.weekly_final_source_correction_sessions correction
    where correction.request_hash=v_request_hash;
  end if;
  if v_existing_key_count=1 and v_existing_hash_count=1
     and v_existing_by_key.id is distinct from v_existing_by_hash.id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_COLLISION'
      using errcode='22023';
  end if;
  if v_existing_key_count=1 then
    v_existing:=v_existing_by_key;
  elsif v_existing_hash_count=1 then
    v_existing:=v_existing_by_hash;
  end if;
  if v_existing_key_count=1 or v_existing_hash_count=1 then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    if v_existing.state in ('CANCELLED','FAILED') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_OPEN_SESSION_TERMINAL'
        using errcode='22023',
          detail='correction session '||v_existing.id::text||' is '
                 ||v_existing.state||'. Open the new correction with its own '
                 'idempotency key and its own reason; a terminal session is '
                 'never replayed as a live one.';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'status',v_existing.state,'correction_session_id',v_existing.id,
      'version',v_existing.version,'idempotent_replay',true
    );
  end if;

  select * into v_cycle from public.weekly_source_cycles
  where id=v_cycle_id for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select source_group_id into v_group_id
  from public.weekly_source_cycles where id=v_cycle.id;
  if v_scope_kind='NHSP_REPORT_SCOPE' then
    select * into v_scope from public.weekly_source_report_scopes
    where id=v_report_scope_id for update;
    if not found or v_scope.source_cycle_id is distinct from v_cycle.id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SCOPE_INVALID' using errcode='22023';
    end if;
    v_client_id:=v_scope.client_id;
    if v_scope.current_final_revision_id is distinct from v_revision_id then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
    end if;
  elsif v_cycle.current_final_revision_id is distinct from v_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;
  select * into v_revision from public.weekly_source_final_revisions
  where id=v_revision_id for update;
  if not found or v_revision.state<>'CURRENT'
     or v_revision.source_cycle_id is distinct from v_cycle.id
     or v_revision.authority_scope_kind is distinct from v_scope_kind
     or v_revision.report_scope_id is distinct from v_report_scope_id
     or v_revision.manifest_hash is distinct from v_expected_manifest then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;
  if v_client_id is null then
    select client_id into strict v_client_id
    from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_revision.id;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group_id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_revision.id,v_actor,null::uuid,false
  );
  v_guard_fingerprint:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  insert into public.weekly_final_source_correction_sessions(
    source_cycle_id,authority_scope_kind,report_scope_id,
    expected_current_final_revision_id,expected_final_manifest_hash,state,version,
    actor_user_id,reason,idempotency_key,request_hash,guard_fingerprint
  ) values (
    v_cycle.id,v_scope_kind,v_report_scope_id,v_revision.id,v_revision.manifest_hash,
    'DRAFT',1,v_actor,v_reason,v_idempotency_key,v_request_hash,v_guard_fingerprint
  ) returning * into v_session;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_OPENED',
         pg_catalog.jsonb_build_object(
           'current_final_revision_id',v_revision.id,
           'current_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex')
         ),
         pg_catalog.jsonb_build_object(
           'state','DRAFT','source_cycle_id',v_cycle.id,
           'authority_scope_kind',v_scope_kind,'report_scope_id',v_report_scope_id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_guard->'affected_roots'),
           'guard_fingerprint',pg_catalog.encode(v_guard_fingerprint,'hex')
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'status','DRAFT','correction_session_id',v_session.id,
    'version',v_session.version,'affected_root_count',
      pg_catalog.jsonb_array_length(v_guard->'affected_roots'),
    'guard_fingerprint',pg_catalog.encode(v_guard_fingerprint,'hex'),
    'idempotent_replay',false
  );
end;
$function$;

create or replace function public.weekly_source_correct_final_review_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_row_manifest_hash','expected_session_version','idempotency_key',
    'replacement_projection_publication_id','replacement_upload_id','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_idempotency_key text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_client_id uuid;
  v_office_preview jsonb;
  v_result jsonb;
  v_result_hash bytea;
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_V1',p_request-'idempotency_key'
  );

  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.review_idempotency_key=v_idempotency_key then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.review_request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REVIEW_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.review_result_json||pg_catalog.jsonb_build_object(
      'idempotent_replay',true
    );
  end if;
  if v_session.state not in ('READY','REVIEWED') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state not in ('READY','REVIEWED')
     or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for share;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,
                    v_cycle.current_projection_publication_id)
  for share;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for share;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for share;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
      or v_replacement_publication.authority_scope_version<>v_scope_version
      or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
      or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;
  select client_id into strict v_client_id
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,false
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  v_result:=pg_catalog.jsonb_build_object(
    'ok',true,
    'status',case when pg_catalog.jsonb_array_length(v_office_preview->'blockers')>0
      then 'BLOCKED' else 'READY_FOR_CONFIRMATION' end,
    'correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'upload_id',v_replacement_upload.id,
    'version',v_expected_session_version+1,
    'office_preview',v_office_preview,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='REVIEWED',review_idempotency_key=v_idempotency_key,
      review_request_hash=v_request_hash,review_result_json=v_result,
      review_result_hash=v_result_hash,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state in ('READY','REVIEWED')
    and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_REVIEWED',
         pg_catalog.jsonb_build_object('state',v_session.state,'version',v_expected_session_version),
         pg_catalog.jsonb_build_object(
           'state','REVIEWED','version',v_expected_session_version+1,
           'status',v_result->>'status',
           'change_count',pg_catalog.jsonb_array_length(v_office_preview->'changes'),
           'blocker_count',pg_catalog.jsonb_array_length(v_office_preview->'blockers'),
           'review_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_session.reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function public.weekly_source_correct_final_prepare_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_preview_hash','expected_row_manifest_hash','expected_session_version',
    'idempotency_key','reason','confirmation_text',
    'replacement_projection_publication_id','replacement_upload_id','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_expected_preview_hash bytea;
  v_idempotency_key text;
  v_reason text;
  v_confirmation_text text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_client_id uuid;
  v_core_result jsonb;
  v_context jsonb;
  v_result jsonb;
  v_result_hash bytea;
  v_prepared_revision_id uuid;
  v_prepared_session_version bigint;
  v_office_preview jsonb;
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
    v_expected_preview_hash:=pg_catalog.decode(p_request->>'expected_preview_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_confirmation_text:=pg_catalog.btrim(coalesce(p_request->>'confirmation_text',''));
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.octet_length(v_expected_preview_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_confirmation_text) not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_V1',p_request-'idempotency_key'
  );
  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.state in ('PREPARED','COMMITTING','APPLIED') then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.prepare_idempotency_key is distinct from v_idempotency_key
       or v_session.prepare_request_hash is distinct from v_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.prepare_result_json||pg_catalog.jsonb_build_object(
      'status','PREPARED','idempotent_replay',true
    );
  end if;

  -- Exact retained PREPARE replay above remains exempt. Fresh correction
  -- admission precedes the outer cycle lock and the nested Final engine.
  perform private.weekly_source_pay_query_admit_v2();

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state<>'REVIEWED' or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or v_session.review_result_json is null
     or v_session.review_result_hash is distinct from private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_CORRECT_FINAL_REVIEW_RESULT_V1',v_session.review_result_json
        )
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for share;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,
                    v_cycle.current_projection_publication_id)
  for share;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for update;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for update;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_publication.authority_scope_version<>v_scope_version
     or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
     or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;
  select client_id into strict v_client_id
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,true
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  if v_session.review_result_json->'office_preview' is distinct from v_office_preview
     or private.weekly_source_finalisation_hex32_v1(
          v_office_preview->>'preview_hash','WEEKLY_SOURCE_CORRECTION_PREVIEW_HASH_INVALID'
        ) is distinct from v_expected_preview_hash
     or v_confirmation_text is distinct from v_office_preview->>'confirmation_text'
     or pg_catalog.jsonb_array_length(v_office_preview->'blockers')<>0 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREVIEW_STALE' using errcode='40001';
  end if;
  update public.weekly_final_source_correction_sessions
  set state='PREPARING',prepare_idempotency_key=v_idempotency_key,
      prepare_request_hash=v_request_hash,reason=v_reason,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='REVIEWED' and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;

  v_core_result:=private.weekly_source_finalise_engine_v1(
    pg_catalog.jsonb_build_object(
      'actor_user_id',v_actor,'source_cycle_id',v_cycle.id,
      'authority_scope_kind',v_session.authority_scope_kind,
      'report_scope_id',v_session.report_scope_id,
      'upload_id',v_replacement_upload.id,
      'projection_publication_id',v_replacement_publication.id,
      'expected_authority_scope_version',v_scope_version,
      'expected_row_manifest_hash',pg_catalog.encode(v_expected_row_hash,'hex'),
      'expected_comparison_manifest_hash',pg_catalog.encode(v_expected_comparison_hash,'hex'),
      'expected_issue_set_hash',pg_catalog.encode(v_expected_issue_hash,'hex')
    ),v_session.id,true
  );
  if coalesce((v_core_result->>'ok')::boolean,false) is not true
     or v_core_result->>'status'<>'PREPARED' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_FAILED'
      using errcode='55000',detail=v_core_result::text;
  end if;
  v_prepared_revision_id:=(v_core_result->>'final_revision_id')::uuid;
  update public.weekly_final_source_correction_sessions
  set prepared_final_revision_id=v_prepared_revision_id
  where id=v_session.id and state='PREPARING'
    and prepare_request_hash=v_request_hash;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  v_context:=private.weekly_source_correct_final_prepared_context_v1(v_session.id);
  v_office_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  v_prepared_session_version:=v_expected_session_version+2;
  v_result:=v_core_result||pg_catalog.jsonb_build_object(
    'correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'root_contexts',v_context->'root_contexts',
    'office_preview',v_office_preview,
    'version',v_prepared_session_version,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='PREPARED',prepare_result_json=v_result,prepare_result_hash=v_result_hash,
      version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='PREPARING'
    and prepared_final_revision_id=v_prepared_revision_id
    and prepare_request_hash=v_request_hash;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_PREPARED',
         pg_catalog.jsonb_build_object(
           'state','READY','current_final_revision_id',v_prior_revision.id
         ),
         pg_catalog.jsonb_build_object(
           'state','PREPARED','prepared_final_revision_id',v_prepared_revision_id,
           'replacement_upload_id',v_replacement_upload.id,
           'replacement_projection_publication_id',v_replacement_publication.id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_context->'root_contexts'),
           'prepare_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_session.reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function public.weekly_source_correct_final_apply_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','extensions','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_authority_scope_version',
    'expected_comparison_manifest_hash','expected_issue_set_hash',
    'expected_preview_hash','expected_row_manifest_hash','expected_session_version',
    'idempotency_key','reason','confirmation_text',
    'replacement_projection_publication_id','replacement_upload_id',
    'root_service_snapshots','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_upload_id uuid;
  v_publication_id uuid;
  v_expected_session_version bigint;
  v_scope_version bigint;
  v_expected_row_hash bytea;
  v_expected_comparison_hash bytea;
  v_expected_issue_hash bytea;
  v_expected_preview_hash bytea;
  v_idempotency_key text;
  v_reason text;
  v_confirmation_text text;
  v_apply_request_hash bytea;
  v_root_snapshots jsonb;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_upload public.weekly_source_uploads%rowtype;
  v_prior_publication public.weekly_source_projection_publications%rowtype;
  v_replacement_upload public.weekly_source_uploads%rowtype;
  v_replacement_publication public.weekly_source_projection_publications%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_replacement_profile public.weekly_source_format_profiles%rowtype;
  v_prepared_revision public.weekly_source_final_revisions%rowtype;
  v_guard jsonb;
  v_guard_hash bytea;
  v_prepared_context jsonb;
  v_live_preview jsonb;
  v_server_roots jsonb;
  v_client_id uuid;
  v_new_revision_id uuid;
  v_root record;
  v_snapshot jsonb;
  v_prior_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  v_projection_result jsonb;
  v_root_preflight jsonb;
  v_impact_hash bytea;
  v_result jsonb;
  v_result_hash bytea;
  v_completion_generation integer;
  v_completion_hash bytea;
  v_voided_count integer;
  v_old_movement_count integer;
  v_cas_count integer;
  v_family uuid[];
  v_family_after_lock uuid[];
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_APPLY_V1'
     or pg_catalog.jsonb_typeof(p_request->'root_service_snapshots')<>'array' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_upload_id:=(p_request->>'replacement_upload_id')::uuid;
    v_publication_id:=(p_request->>'replacement_projection_publication_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
    v_scope_version:=(p_request->>'expected_authority_scope_version')::bigint;
    v_expected_row_hash:=pg_catalog.decode(p_request->>'expected_row_manifest_hash','hex');
    v_expected_comparison_hash:=pg_catalog.decode(p_request->>'expected_comparison_manifest_hash','hex');
    v_expected_issue_hash:=pg_catalog.decode(p_request->>'expected_issue_set_hash','hex');
    v_expected_preview_hash:=pg_catalog.decode(p_request->>'expected_preview_hash','hex');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  v_confirmation_text:=pg_catalog.btrim(coalesce(p_request->>'confirmation_text',''));
  v_root_snapshots:=p_request->'root_service_snapshots';
  if v_actor is null or v_session_id is null or v_upload_id is null
     or v_publication_id is null or v_expected_session_version is null
     or v_scope_version is null or v_scope_version<1
     or pg_catalog.octet_length(v_expected_row_hash)<>32
     or pg_catalog.octet_length(v_expected_comparison_hash)<>32
     or pg_catalog.octet_length(v_expected_issue_hash)<>32
     or pg_catalog.octet_length(v_expected_preview_hash)<>32
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000
     or pg_catalog.char_length(v_confirmation_text) not between 1 and 500 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_VALUE_INVALID' using errcode='22023';
  end if;
  v_apply_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_APPLY_V1',p_request-'idempotency_key'
  );

  select * into v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.state='APPLIED' then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.apply_idempotency_key is distinct from v_idempotency_key
       or v_session.apply_request_hash is distinct from v_apply_request_hash then
      raise exception 'WEEKLY_SOURCE_CORRECTION_APPLY_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.result_json||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;

  -- Exact retained APPLIED replay above remains exempt. Fresh correction
  -- admission precedes cycle/session locks and the CURRENT authority CAS.
  perform private.weekly_source_pay_query_admit_v2();

  select * into strict v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into strict v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
  end if;
  select * into strict v_session from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if v_session.state<>'PREPARED' or v_session.actor_user_id is distinct from v_actor
     or v_session.version<>v_expected_session_version
     or v_session.replacement_correction_upload_id is distinct from v_upload_id
     or v_session.replacement_projection_publication_id is distinct from v_publication_id
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  select * into strict v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for update;
  select * into strict v_prepared_revision from public.weekly_source_final_revisions
  where id=v_session.prepared_final_revision_id for update;
  select * into strict v_prior_upload from public.weekly_source_uploads
  where id=v_prior_revision.upload_id for update;
  select * into strict v_prior_profile from public.weekly_source_format_profiles
  where id=v_prior_upload.source_format_profile_id;
  select * into strict v_prior_publication
  from public.weekly_source_projection_publications
  where id=coalesce(v_scope.current_projection_publication_id,v_cycle.current_projection_publication_id)
  for update;
  select * into strict v_replacement_upload from public.weekly_source_uploads
  where id=v_upload_id for update;
  select * into strict v_replacement_publication
  from public.weekly_source_projection_publications where id=v_publication_id for update;

  if v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prepared_revision.state<>'PREPARED'
     or v_prepared_revision.reason<>'CORRECT_FINAL_SOURCE'
     or v_prepared_revision.predecessor_revision_id is distinct from v_prior_revision.id
     or v_prepared_revision.source_cycle_id is distinct from v_cycle.id
     or v_prepared_revision.upload_id is distinct from v_replacement_upload.id
     or v_session.prepare_result_json->>'final_revision_id'
          is distinct from v_prepared_revision.id::text
     or v_session.prepare_result_hash is distinct from private.weekly_source_sha256_jsonb_v1(
          'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_RESULT_V1',v_session.prepare_result_json
        )
     or v_prior_upload.state<>'CURRENT'
     or v_prior_publication.state<>'CURRENT'
     or v_replacement_upload.state<>'CORRECTION_READY'
     or v_replacement_upload.purpose<>'FINAL_SOURCE_CORRECTION'
     or v_replacement_upload.correction_session_id is distinct from v_session.id
     or v_replacement_upload.source_cycle_id is distinct from v_cycle.id
     or v_replacement_upload.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_upload.row_manifest_hash is distinct from v_expected_row_hash
     or v_replacement_publication.state<>'CORRECTION_READY'
     or v_replacement_publication.correction_session_id is distinct from v_session.id
     or v_replacement_publication.upload_id is distinct from v_replacement_upload.id
     or v_replacement_publication.source_cycle_id is distinct from v_cycle.id
     or v_replacement_publication.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_replacement_publication.report_scope_id is distinct from v_session.report_scope_id
     or v_replacement_publication.authority_scope_version<>v_scope_version
     or v_replacement_publication.comparison_manifest_hash is distinct from v_expected_comparison_hash
     or v_replacement_publication.issue_set_hash is distinct from v_expected_issue_hash then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE' using errcode='40001';
  end if;
  select * into strict v_replacement_profile from public.weekly_source_format_profiles
  where id=v_replacement_upload.source_format_profile_id;
  if v_replacement_profile.final_authority_kind is distinct from v_prior_profile.final_authority_kind
     or (v_replacement_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')
          is distinct from (v_group.source_family='NHSP') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SOURCE_FAMILY_MISMATCH'
      using errcode='55000';
  end if;

  select client_id into strict v_client_id
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_prior_revision.id;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );
  v_guard:=private.weekly_source_correct_final_preconditions_v1(
    v_prior_revision.id,v_actor,v_session.id,true
  );
  v_guard_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_GUARD_V1',v_guard
  );
  if v_guard_hash is distinct from v_session.guard_fingerprint then
    raise exception 'WEEKLY_SOURCE_CORRECTION_GUARD_STALE' using errcode='40001';
  end if;
  v_prepared_context:=private.weekly_source_correct_final_prepared_context_v1(v_session.id);
  v_server_roots:=v_prepared_context->'root_contexts';
  if v_server_roots is distinct from v_session.prepare_result_json->'root_contexts' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_CONTEXT_STALE'
      using errcode='40001';
  end if;
  v_live_preview:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
  if v_session.prepare_result_json->'office_preview' is distinct from v_live_preview
     or private.weekly_source_finalisation_hex32_v1(
          v_live_preview->>'preview_hash','WEEKLY_SOURCE_CORRECTION_PREVIEW_HASH_INVALID'
        ) is distinct from v_expected_preview_hash
     or v_confirmation_text is distinct from v_live_preview->>'confirmation_text'
     or pg_catalog.jsonb_array_length(v_live_preview->'blockers')<>0 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREVIEW_STALE' using errcode='40001';
  end if;

  if exists(
    select 1 from pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
    where pg_catalog.jsonb_typeof(supplied.value)<>'object'
       or not (supplied.value ? 'root_timesheet_id'
               and supplied.value ? 'prepared_context_hash'
               and supplied.value ? 'service_snapshot')
       or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(supplied.value))<>3
       or coalesce(supplied.value->>'root_timesheet_id','')
            !~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(supplied.value->>'prepared_context_hash','') !~*'^[0-9a-f]{64}$'
       or pg_catalog.jsonb_typeof(supplied.value->'service_snapshot')<>'object'
  ) or (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_root_snapshots))
       <>pg_catalog.jsonb_array_length(v_server_roots)
     or exists(
       select 1
       from pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
       group by supplied.value->>'root_timesheet_id'
       having pg_catalog.count(*)<>1
     ) or exists(
       select 1 from pg_catalog.jsonb_array_elements(v_server_roots) server_root(value)
       where not exists(
         select 1 from pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
         where supplied.value->>'root_timesheet_id'=server_root.value->>'root_timesheet_id'
           and supplied.value->>'prepared_context_hash'=
                 server_root.value->>'prepared_context_hash'
       )
     ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_SNAPSHOT_SET_MISMATCH'
      using errcode='40001';
  end if;

  -- PREPARE can create a replacement-only root that did not exist when OPEN
  -- froze the prior-root guard.  Apply the same invoice/Banking/Draft
  -- preconditions to every sealed union root immediately before COMMITTING so
  -- a newly created root cannot enter another owner between PREPARE and APPLY.
  for v_root in
    select (server_root.value->>'root_timesheet_id')::uuid as root_timesheet_id
    from pg_catalog.jsonb_array_elements(v_server_roots) server_root(value)
    order by server_root.value->>'root_timesheet_id'
  loop
    -- Gate 13 hostile review F5 / standing rule 3, at COMMITTING time.  Same
    -- family keying and same lock-before-read order as the OPEN-time
    -- preconditions above: name the family, lock its rows in a deterministic
    -- order, re-resolve, require the membership to be unchanged, and only then
    -- read the protected-family and invoice-line state that is being guarded.
    v_family:=private.weekly_source_invoice_family_timesheet_ids_v1(
      v_root.root_timesheet_id
    );
    if v_family is null or pg_catalog.cardinality(v_family)=0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
        using errcode='55000';
    end if;
    perform 1 from public.timesheets family_row
    where family_row.timesheet_id=any(v_family)
    order by family_row.timesheet_id
    for update;
    v_family_after_lock:=private.weekly_source_invoice_family_timesheet_ids_v1(
      v_root.root_timesheet_id
    );
    if v_family_after_lock is null
       or pg_catalog.cardinality(v_family_after_lock)=0
       or not (v_family_after_lock @> v_family and v_family @> v_family_after_lock)
    then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
        using errcode='40001';
    end if;
    v_family:=v_family_after_lock;
    if exists(
      select 1 from public.weekly_exceptional_pay_target_families family
      where family.root_timesheet_id=any(v_family)
        and family.ownership_state='TARGET_MANAGED'
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PROTECTED_TARGET_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.invoice_lines invoice_line
      where invoice_line.timesheet_id=any(v_family)
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.timesheets timesheet_row
      where timesheet_row.timesheet_id=v_root.root_timesheet_id
        and timesheet_row.active_document_operation_id is not null
    ) or exists(
      select 1 from public.invoice_operations operation
      where operation.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and operation.entity_type='TIMESHEET'
        and operation.entity_id=v_root.root_timesheet_id
    ) or exists(
      select 1 from public.invoice_operation_chunks chunk
      where chunk.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and chunk.entity_type='TIMESHEET'
        and chunk.entity_id=v_root.root_timesheet_id
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_INVOICE_OPERATION'
        using errcode='55000';
    end if;
    v_root_preflight:=public.import_timesheet_financial_preflight_v1(
      array[v_root.root_timesheet_id],
      'WEEKLY_SOURCE_CORRECT_FINAL_SOURCE',v_actor,'{}'::jsonb,true,1
    );
    if coalesce((v_root_preflight->>'blocking_batch_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_PAY_DRAFT'
        using errcode='55000',detail=v_root_preflight::text;
    elsif coalesce((v_root_preflight->>'paid_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_PAID'
        using errcode='55000',detail=v_root_preflight::text;
    elsif coalesce((v_root_preflight->>'invoice_lined_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000',detail=v_root_preflight::text;
    elsif coalesce((v_root_preflight->>'allowed')::boolean,false) is not true
       or v_root_preflight->>'required_path' not in (
         -- Gate 2 / XSG-032, the same rule at COMMITTING time.
         'DIRECT_AMEND_RECALCULATE'
       ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_NOT_MUTABLE'
        using errcode='55000',detail=v_root_preflight::text;
    end if;
  end loop;

  update public.weekly_final_source_correction_sessions
  set state='COMMITTING',apply_idempotency_key=v_idempotency_key,
      apply_request_hash=v_apply_request_hash,reason=v_reason,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='PREPARED' and version=v_expected_session_version
    and prepared_final_revision_id=v_prepared_revision.id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;

  update public.weekly_source_expense_materialisations materialisation
  set state='SUPERSEDED'
  where materialisation.state='MATERIALISED'
    and materialisation.expense_authority_generation_id in (
      select expense.id from public.weekly_expense_authority_generations expense
      where expense.final_revision_id=v_prior_revision.id and expense.state='CURRENT'
    );

  -- Expense authority is activated in the same CAS as source authority.  The
  -- prepared generation wins where one exists; otherwise correcting away an
  -- erroneous same-cycle generation restores its exact predecessor (or zero
  -- when there was no predecessor).
  update public.weekly_expense_authority_generations current_expense
  set state='SUPERSEDED'
  where current_expense.state='CURRENT'
    and current_expense.work_event_id in (
      select old_expense.work_event_id
      from public.weekly_expense_authority_generations old_expense
      where old_expense.final_revision_id=v_prior_revision.id
      union
      select prepared_expense.work_event_id
      from public.weekly_expense_authority_generations prepared_expense
      where prepared_expense.final_revision_id=v_prepared_revision.id
        and prepared_expense.state='PREPARED'
    );
  update public.weekly_expense_authority_generations prepared_expense
  set state='CURRENT'
  where prepared_expense.final_revision_id=v_prepared_revision.id
    and prepared_expense.state='PREPARED';
  update public.weekly_expense_authority_generations baseline_expense
  set state='CURRENT'
  where baseline_expense.state='SUPERSEDED'
    and baseline_expense.id in (
      select old_expense.prior_expense_authority_generation_id
      from public.weekly_expense_authority_generations old_expense
      where old_expense.final_revision_id=v_prior_revision.id
        and old_expense.prior_expense_authority_generation_id is not null
        and not exists(
          select 1
          from public.weekly_expense_authority_generations prepared_expense
          where prepared_expense.final_revision_id=v_prepared_revision.id
            and prepared_expense.work_event_id=old_expense.work_event_id
            and prepared_expense.state='CURRENT'
        )
    );

  perform pg_catalog.set_config(
    'cloudtms.weekly_source_correction_owner',
    'weekly_source_correct_final_apply_atomic_v1',true
  );
  select pg_catalog.count(*)::integer into v_old_movement_count
  from public.weekly_source_billing_movements
  where final_revision_id=v_prior_revision.id;
  if exists(
    select 1 from public.weekly_source_billing_movements
    where final_revision_id=v_prior_revision.id and placement_state<>'UNPLACED'
  ) or exists(
    select 1 from public.weekly_source_billing_movements
    where final_revision_id=v_prepared_revision.id and placement_state<>'UNPLACED'
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_MOVEMENT_STATE_STALE' using errcode='40001';
  end if;
  update public.weekly_source_billing_movements
  set placement_state='VOIDED_BY_CORRECT_FINAL'
  where final_revision_id=v_prior_revision.id and placement_state='UNPLACED';
  get diagnostics v_voided_count=row_count;
  if v_voided_count<>v_old_movement_count then
    raise exception 'WEEKLY_SOURCE_CORRECTION_MOVEMENT_CAS_LOST' using errcode='40001';
  end if;
  update public.weekly_source_final_revisions
  set state='SUPERSEDED' where id=v_prior_revision.id and state='CURRENT';
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_CAS_LOST' using errcode='40001';
  end if;
  update public.weekly_source_final_revisions
  set state='CURRENT' where id=v_prepared_revision.id and state='PREPARED';
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_REVISION_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_uploads set state='SUPERSEDED'
  where id=v_prior_upload.id and state='CURRENT';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PRIOR_UPLOAD_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_projection_publications
  set state='STALE',failure_code='SUPERSEDED_BY_CORRECT_FINAL_SOURCE'
  where id=v_prior_publication.id and state='CURRENT';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PRIOR_PUBLICATION_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_uploads set state='CURRENT'
  where id=v_replacement_upload.id and state='CORRECTION_READY';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_UPLOAD_CAS_LOST'
      using errcode='40001';
  end if;
  update public.weekly_source_projection_publications set state='CURRENT'
  where id=v_replacement_publication.id and state='CORRECTION_READY';
  get diagnostics v_cas_count=row_count;
  if v_cas_count<>1 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_PUBLICATION_CAS_LOST'
      using errcode='40001';
  end if;

  if v_session.authority_scope_kind='CYCLE' then
    update public.weekly_source_cycles
    set current_complete_upload_id=v_replacement_upload.id,
        current_projection_publication_id=v_replacement_publication.id,
        current_final_revision_id=v_prepared_revision.id,projection_state='CURRENT',
        state='FINALISED',finalised_at_utc=pg_catalog.transaction_timestamp(),
        finalised_by_user_id=v_actor
    where id=v_cycle.id
      and current_complete_upload_id=v_prior_upload.id
      and current_projection_publication_id=v_prior_publication.id
      and current_final_revision_id=v_prior_revision.id
      and version=v_scope_version;
  else
    update public.weekly_source_report_scopes
    set current_complete_upload_id=v_replacement_upload.id,
        current_projection_publication_id=v_replacement_publication.id,
        current_final_revision_id=v_prepared_revision.id,projection_state='CURRENT',
        state='FINALISED',updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_scope.id
      and current_complete_upload_id=v_prior_upload.id
      and current_projection_publication_id=v_prior_publication.id
      and current_final_revision_id=v_prior_revision.id
      and version=v_scope_version;
  end if;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_AUTHORITY_CAS_LOST' using errcode='40001';
  end if;
  v_new_revision_id:=v_prepared_revision.id;

  -- APPLIED replay returned earlier; only the successful new CURRENT CAS
  -- resolves report-contained manual queries before the existing selector.
  -- Keep the completion receipt below that selector in its original order.
  perform private.weekly_source_manual_reviews_finalised_v1(v_new_revision_id,v_actor);

  -- Source old/new and cycle/report CURRENT CAS succeeded. Retract only the
  -- exact old captured revision, publish genuine new origins, and retain an
  -- explicit new observation even for an empty correction. Outside readers
  -- cannot observe this intermediate state: it is the same owner transaction.
  if (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    perform private.bpay_next_source_current_apply_correction_v1(v_session.id);
  end if;

  update public.weekly_source_client_cycle_completions completion
  set state='SUPERSEDED',superseded_at_utc=pg_catalog.transaction_timestamp()
  where completion.source_cycle_id=v_cycle.id
    and completion.client_id=v_client_id and completion.state='CURRENT';
  select coalesce(pg_catalog.max(completion.completion_generation),0)+1
  into v_completion_generation
  from public.weekly_source_client_cycle_completions completion
  where completion.source_cycle_id=v_cycle.id and completion.client_id=v_client_id;
  v_completion_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CLIENT_CYCLE_COMPLETION_V1',
    pg_catalog.jsonb_build_object(
      'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
      'client_id',v_client_id,'completion_generation',v_completion_generation,
      'completion_kind','FINAL_SOURCE','final_revision_id',v_new_revision_id,
      'actor_user_id',v_actor
    )
  );
  insert into public.weekly_source_client_cycle_completions(
    source_cycle_id,source_group_id,client_id,completion_generation,
    completion_kind,final_revision_id,attested_by_user_id,attested_at_utc,
    attestation_text,completion_hash,state
  ) values (
    v_cycle.id,v_group.id,v_client_id,v_completion_generation,
    'FINAL_SOURCE',v_new_revision_id,v_actor,pg_catalog.transaction_timestamp(),
    null,v_completion_hash,'CURRENT'
  );
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    if not exists(
      select 1
      from public.weekly_source_group_clients membership
      where membership.source_group_id=v_group.id
        and v_cycle.finalisation_week_ending between membership.valid_from
          and coalesce(membership.valid_to,'infinity'::date)
        and not exists(
          select 1
          from public.weekly_source_client_cycle_completions completion
          where completion.source_cycle_id=v_cycle.id
            and completion.client_id=membership.client_id
            and completion.state='CURRENT'
        )
    ) then
      update public.weekly_source_cycles
      set state='FINALISED',finalised_at_utc=pg_catalog.transaction_timestamp(),
          finalised_by_user_id=v_actor
      where id=v_cycle.id;
    else
      update public.weekly_source_cycles set state='FINALISABLE'
      where id=v_cycle.id;
    end if;
  end if;

  for v_root in
    select (server_root.value->>'root_timesheet_id')::uuid as root_timesheet_id,
           (server_root.value->>'prior_projection_receipt_id')::uuid as prior_receipt_id,
           server_root.value->>'source_profile_kind' as source_profile_kind,
           server_root.value->>'source_mode' as source_mode,
           supplied.value->'service_snapshot' as service_snapshot
    from pg_catalog.jsonb_array_elements(v_server_roots) server_root(value)
    join pg_catalog.jsonb_array_elements(v_root_snapshots) supplied(value)
      on supplied.value->>'root_timesheet_id'=server_root.value->>'root_timesheet_id'
    order by server_root.value->>'root_timesheet_id'
  loop
    v_prior_receipt:=null;
    if v_root.prior_receipt_id is not null then
      select * into strict v_prior_receipt
      from public.weekly_source_ordinary_pay_projection_receipts
      where id=v_root.prior_receipt_id;
      if v_prior_receipt.final_revision_id is distinct from v_prior_revision.id
         or v_prior_receipt.root_timesheet_id is distinct from v_root.root_timesheet_id
         or v_prior_receipt.outcome not in ('PREPARED_FOR_AUTHORISATION','PROPOSED') then
        raise exception 'WEEKLY_SOURCE_CORRECTION_PRIOR_ROOT_RECEIPT_STALE'
          using errcode='40001';
      end if;
    end if;
    v_impact_hash:=private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CORRECT_FINAL_ROOT_IMPACT_V1',
      pg_catalog.jsonb_build_object(
        'correction_session_id',v_session.id,
        'prior_final_revision_id',v_prior_revision.id,
        'replacement_final_revision_id',v_new_revision_id,
        'root_timesheet_id',v_root.root_timesheet_id,
        'prior_projection_receipt_id',v_root.prior_receipt_id,
        'client_id',v_client_id,
        'source_profile_kind',v_root.source_profile_kind,
        'source_mode',v_root.source_mode,
        'submitted_service_snapshot_hash',pg_catalog.encode(
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_ORDINARY_SERVICE_SNAPSHOT_V1',v_root.service_snapshot
          ),'hex'
        )
      )
    );
    insert into public.weekly_final_source_correction_root_impacts(
      correction_session_id,prior_final_revision_id,replacement_final_revision_id,
      root_timesheet_id,prior_projection_receipt_id,client_id,source_profile_kind,
      source_mode,impact_kind,submitted_service_snapshot_hash,impact_hash
    ) values (
      v_session.id,v_prior_revision.id,v_new_revision_id,v_root.root_timesheet_id,
      v_root.prior_receipt_id,v_client_id,v_root.source_profile_kind,v_root.source_mode,
      case when v_root.prior_receipt_id is null
        then 'PUBLISHED_REPLACEMENT_ONLY_ROOT'
        when exists(
        select 1 from public.weekly_source_billing_movements movement
        where movement.final_revision_id=v_new_revision_id
          and movement.invoice_timesheet_id=v_root.root_timesheet_id
      ) then 'REPROJECTED_WITH_CURRENT_REVISION_MOVEMENTS'
        else 'REPROJECTED_WITHOUT_CURRENT_REVISION_MOVEMENTS' end,
      private.weekly_source_sha256_jsonb_v1(
        'WEEKLY_SOURCE_ORDINARY_SERVICE_SNAPSHOT_V1',v_root.service_snapshot
      ),v_impact_hash
    );
    v_projection_result:=public.weekly_source_ordinary_pay_projection_apply_atomic_v1(
      pg_catalog.jsonb_build_object(
        'schema_version','WEEKLY_SOURCE_ORDINARY_PAY_PROJECTION_REQUEST_V1',
        'actor_user_id',v_actor,'final_revision_id',v_new_revision_id,
        'root_timesheet_id',v_root.root_timesheet_id,
        'idempotency_key','correct-final:'||v_session.id::text||':'||v_root.root_timesheet_id::text,
        'service_snapshot',v_root.service_snapshot
      )
    );
    -- Gate 2: the projection no longer publishes.  The only outcome reachable
    -- from here is PREPARED_FOR_AUTHORISATION, because the gates above now
    -- admit DIRECT_AMEND_RECALCULATE only, i.e. a root that is not yet
    -- authorised.  Anything else means the root moved under us.
    if v_projection_result->>'outcome'<>'PREPARED_FOR_AUTHORISATION' then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_REPROJECT_FAILED'
        using errcode='55000',detail=v_projection_result::text;
    end if;
  end loop;

  v_result:=(v_session.prepare_result_json-'root_contexts')||pg_catalog.jsonb_build_object(
    'status','CORRECTED','correction_session_id',v_session.id,
    'prior_final_revision_id',v_prior_revision.id,
    'affected_root_count',pg_catalog.jsonb_array_length(v_server_roots),
    'version',v_expected_session_version+2,
    'idempotent_replay',false
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_RESULT_V1',v_result
  );
  update public.weekly_final_source_correction_sessions
  set state='APPLIED',applied_final_revision_id=v_new_revision_id,
      result_json=v_result,result_hash=v_result_hash,version=version+1,
      updated_at_utc=pg_catalog.transaction_timestamp(),
      completed_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state='COMMITTING';
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;
  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_APPLIED',
         pg_catalog.jsonb_build_object(
           'state','CURRENT','final_revision_id',v_prior_revision.id,
           'upload_id',v_prior_upload.id,'projection_publication_id',v_prior_publication.id
         ),
         pg_catalog.jsonb_build_object(
           'state','APPLIED','final_revision_id',v_new_revision_id,
           'upload_id',v_replacement_upload.id,
           'projection_publication_id',v_replacement_publication.id,
           'affected_root_count',pg_catalog.jsonb_array_length(v_server_roots),
           'voided_prior_movement_count',v_voided_count,
           'result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;
  return v_result;
end;
$function$;

create or replace function public.weekly_source_correct_final_cancel_atomic_v1(
  p_request jsonb
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_expected_keys text[]:=array[
    'actor_user_id','correction_session_id','expected_session_version',
    'idempotency_key','reason','schema_version'
  ];
  v_actual_keys text[];
  v_actor uuid;
  v_session_id uuid;
  v_expected_session_version bigint;
  v_idempotency_key text;
  v_reason text;
  v_request_hash bytea;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_locked public.weekly_final_source_correction_sessions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_scope public.weekly_source_report_scopes%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_client_id uuid;
  v_manifest_count bigint;
  v_state_before text;
  v_upload record;
  v_publication record;
  v_rejected_uploads integer:=0;
  v_superseded_uploads integer:=0;
  v_staled_publications integer:=0;
  v_live_uploads_before bigint;
  v_live_publications_before bigint;
  v_live_uploads_after bigint;
  v_live_publications_after bigint;
  v_rows integer;
  v_result jsonb;
  v_result_hash bytea;
begin
  if p_request->>'authority_scope_kind'='SELF_BILL_REPORT_SCOPE'
    or exists(select 1 from public.weekly_source_report_scopes s where s.id=nullif(p_request->>'report_scope_id','')::uuid and s.self_bill_report_id is not null)
    or exists(select 1 from public.weekly_source_final_revisions r where r.id=nullif(p_request->>'expected_current_final_revision_id','')::uuid and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE')
    or exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=nullif(p_request->>'correction_session_id','')::uuid and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  perform pg_catalog.set_config('lock_timeout','5s',true);
  if coalesce(current_setting('request.jwt.claim.role',true),
       nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  if pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_REQUEST_INVALID' using errcode='22023';
  end if;
  select pg_catalog.array_agg(key order by key) into v_actual_keys
  from pg_catalog.jsonb_object_keys(p_request) key;
  select pg_catalog.array_agg(key order by key) into v_expected_keys
  from pg_catalog.unnest(v_expected_keys) key;
  if v_actual_keys is distinct from v_expected_keys
     or p_request->>'schema_version'<>'WEEKLY_SOURCE_CORRECT_FINAL_CANCEL_V1' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_REQUEST_INVALID' using errcode='22023';
  end if;
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_session_id:=(p_request->>'correction_session_id')::uuid;
    v_expected_session_version:=(p_request->>'expected_session_version')::bigint;
  exception when others then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_VALUE_INVALID' using errcode='22023';
  end;
  v_idempotency_key:=pg_catalog.btrim(coalesce(p_request->>'idempotency_key',''));
  v_reason:=pg_catalog.btrim(coalesce(p_request->>'reason',''));
  if v_actor is null or v_session_id is null
     or v_expected_session_version is null or v_expected_session_version<1
     or pg_catalog.char_length(v_idempotency_key) not between 1 and 200
     or pg_catalog.char_length(v_reason) not between 1 and 1000 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_VALUE_INVALID' using errcode='22023';
  end if;
  v_request_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_CANCEL_V1',p_request-'idempotency_key'
  );

  -- Unlocked pre-read.  Its ONLY uses are (a) to answer an exact idempotent
  -- replay, which writes nothing, and (b) to learn which cycle row to lock
  -- first.  Every value this owner gates on is read again under the locks
  -- below, and the session's own scope identity is re-proved after the lock.
  select * into v_session
  from public.weekly_final_source_correction_sessions where id=v_session_id;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  if v_session.state='CANCELLED'
     and v_session.result_json->>'cancel_idempotency_key'=v_idempotency_key then
    if v_session.actor_user_id is distinct from v_actor
       or v_session.result_json->>'cancel_request_hash'
            is distinct from pg_catalog.encode(v_request_hash,'hex') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_IDEMPOTENCY_COLLISION'
        using errcode='22023';
    end if;
    return v_session.result_json||pg_catalog.jsonb_build_object('idempotent_replay',true);
  end if;

  -- Lock order, taken BEFORE any state this owner gates on is read.  It is the
  -- order the four installed lifecycle owners already use -- cycle, then report
  -- scope, then correction session, then the revision -- so a cancel racing a
  -- review, a prepare or an apply queues behind the same first lock instead of
  -- deadlocking against it.  WP-54 section 6.2's precondition list named only
  -- the session lock; that is not enough to be deadlock-compatible with the
  -- owners it has to race, and this owner follows the installed order instead.
  select * into v_cycle from public.weekly_source_cycles
  where id=v_session.source_cycle_id for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_CYCLE_NOT_FOUND' using errcode='22023';
  end if;
  select * into strict v_group from public.weekly_source_groups
  where id=v_cycle.source_group_id;
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select * into v_scope from public.weekly_source_report_scopes
    where id=v_session.report_scope_id for update;
    if not found then
      raise exception 'WEEKLY_SOURCE_CORRECTION_SCOPE_INVALID' using errcode='22023';
    end if;
  end if;
  select * into v_locked from public.weekly_final_source_correction_sessions
  where id=v_session_id for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_NOT_FOUND' using errcode='22023';
  end if;
  v_session:=v_locked;

  -- The scope identity the locks were chosen from must still be the session's
  -- own.  If it moved across the lock the locks are the wrong ones and nothing
  -- read after them can be trusted, so fail closed rather than continue.
  if v_session.source_cycle_id is distinct from v_cycle.id
     or v_session.report_scope_id is distinct from v_scope.id
     or (v_session.authority_scope_kind='NHSP_REPORT_SCOPE')
          is distinct from (v_session.report_scope_id is not null) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;
  if v_session.version<>v_expected_session_version then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_STALE' using errcode='40001';
  end if;

  -- Authority before disposition.  03 section 21 gives Correct final source the
  -- "same active administrator predicate" with "no invented high-risk
  -- permission", so cancel re-uses the CORRECT_FINAL_SOURCE verb through the
  -- installed evaluator and adds no new operation key.  An actor who fails here
  -- is told only that, and never learns the session's internal state.
  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    v_client_id:=v_scope.client_id;
  else
    select pg_catalog.count(*) into v_manifest_count
    from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_session.expected_current_final_revision_id;
    if v_manifest_count<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CLIENT_SCOPE_INVALID' using errcode='55000';
    end if;
    select client_id into v_client_id
    from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_session.expected_current_final_revision_id;
  end if;
  perform private.weekly_source_office_authority_v1(
    v_actor,'CORRECT_FINAL_SOURCE',v_group.id,v_client_id,v_cycle.finalisation_week_ending
  );

  -- WHO MAY CANCEL -- owner decision D-WP59-1, taken conservatively.
  -- WP-54 section 6.2 offered three candidate policies and recommended the
  -- third (the opening actor always; another holder of the authority only after
  -- a stated idle interval) while refusing to invent the interval, because the
  -- pack does not state one.  It is still not stated anywhere in the pack, so
  -- this owner ships the policy that cannot be wrong: the opening actor only.
  -- That is also the policy every other stage of this lifecycle already
  -- enforces -- review, prepare and apply each require
  -- v_session.actor_user_id = the calling actor.  Widening it to a second
  -- holder of the authority is an owner decision and an additive change to this
  -- one test; it is NOT taken here.
  if v_session.actor_user_id is distinct from v_actor then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_ACTOR_NOT_OPENER'
      using errcode='42501',
        detail='Only the actor who opened this correction session may cancel it. '
               'A second holder of CORRECT_FINAL_SOURCE may not, because the idle '
               'interval that would make that claim auditable is not stated in the '
               'pack and has not been ruled.';
  end if;

  -- WHAT THE SESSION HAS ALREADY COMMITTED.  Establish it before releasing
  -- anything, and refuse rather than guess.  These six limbs are exhaustive
  -- over the ten declared states, and the last one is the fail-closed branch
  -- for a state this owner does not recognise.
  v_state_before:=v_session.state;
  if v_state_before='APPLIED' or v_session.applied_final_revision_id is not null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_APPLIED'
      using errcode='55000',
        detail='This correction has already replaced the final source authority. '
               'Cancelling it would claim to undo an applied correction.';
  end if;
  if v_state_before='COMMITTING' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_COMMIT_IN_FLIGHT'
      using errcode='55000',
        detail='A correction transaction is in flight. Cancelling it is how a '
               'half-applied correction is produced; this is a case for the '
               'existing failure path, not for cancel.';
  end if;
  if v_state_before='PREPARING' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARE_IN_FLIGHT'
      using errcode='55000',
        detail='PREPARE is in flight. Whether a replacement revision has been '
               'materialised cannot be established from this state, so cancel '
               'refuses rather than guess.';
  end if;
  if v_state_before='PREPARED' or v_session.prepared_final_revision_id is not null then
    -- Owner decision D-WP59-2, and a correction to WP-54 section 6.2.  That
    -- specification permits cancel from PREPARING and PREPARED and states that
    -- "then the active_uq index frees the scope and the next correction opens
    -- normally".  Executed, that is false.  PREPARE materialises an inactive
    -- replacement revision whose predecessor_revision_id is the prior CURRENT
    -- revision, and private.weekly_source_correct_final_preconditions_v1
    -- refuses any later correction while a descendant of that prior revision
    -- exists, whatever the descendant's own state and whatever happened to the
    -- session that made it.  Cancelling a PREPARED session would therefore
    -- release the session row and leave the Trust and cutoff blocked anyway --
    -- a cancel that promises a release it cannot deliver.
    -- Releasing it needs the descendant refusal to stop counting a cancelled
    -- session's superseded descendant, and the pack states that refusal without
    -- any such exception (03 section 17: "It refuses ... if a correction
    -- descendant exists"; 05 CFS-008 and CFS-021).  The pack outranks this
    -- package's judgement, so the exception is not invented here.
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREPARED_REVISION_EXISTS'
      using errcode='55000',
        detail='A replacement final revision has already been materialised for '
               'this session. It is a correction descendant of the prior '
               'authority, so cancelling the session would not release the Trust '
               'and cutoff. Releasing a prepared correction is an unruled owner '
               'decision (WP-59 D-WP59-2).';
  end if;
  if v_state_before='CANCELLED' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_CANCELLED'
      using errcode='55000',
        detail='This correction session is already cancelled. Re-send the exact '
               'cancel request with its original idempotency key for the '
               'idempotent replay.';
  end if;
  if v_state_before='FAILED' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_TERMINAL'
      using errcode='55000',
        detail='This correction session is already terminal.';
  end if;
  if v_state_before not in ('DRAFT','STAGING','READY','REVIEWED') then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_STATE_UNKNOWN'
      using errcode='55000',detail='state='||v_state_before;
  end if;

  -- THE PRIOR AUTHORITY MUST NOT HAVE MOVED.  A cancel releases a scope on the
  -- understanding that the authority it was opened against is still the live
  -- one.  If it is not, the world changed under this session and the honest
  -- answer is a stale refusal, not a release.
  select * into v_prior_revision from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id for share;
  if not found
     or v_prior_revision.state<>'CURRENT'
     or v_prior_revision.manifest_hash is distinct from v_session.expected_final_manifest_hash
     or v_prior_revision.source_cycle_id is distinct from v_cycle.id
     or v_prior_revision.authority_scope_kind is distinct from v_session.authority_scope_kind
     or v_prior_revision.report_scope_id is distinct from v_session.report_scope_id
     or coalesce(v_scope.current_final_revision_id,v_cycle.current_final_revision_id)
          is distinct from v_session.expected_current_final_revision_id then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE' using errcode='40001';
  end if;

  -- A cancel must not promise a release it cannot deliver.  If a correction
  -- descendant of the prior authority already exists, the scope stays blocked
  -- by weekly_source_correct_final_preconditions_v1 whatever this owner does,
  -- so say so instead of releasing the session row and leaving the caller to
  -- discover it.  In a session this owner will cancel there is none, because
  -- the only routine that makes one is PREPARE and a prepared session is
  -- refused above.
  if exists(
    select 1 from public.weekly_source_final_revisions descendant
    where descendant.predecessor_revision_id=v_prior_revision.id
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_DESCENDANT_EXISTS'
      using errcode='55000',
        detail='A correction descendant of the prior final revision exists, so '
               'cancelling this session would not release the Trust and cutoff.';
  end if;

  -- The session's staged artefacts.  A session can carry more than one upload
  -- and more than one projection publication: the seal-failure and abort paths
  -- return the session to DRAFT and null the pointer while leaving the rejected
  -- upload row behind, and the rebuild path replaces
  -- replacement_projection_publication_id with a newer publication.  Every row
  -- bound to this session is therefore locked and disposed of, not only the two
  -- the session currently points at.  The ORDER BY exists solely to make lock
  -- acquisition deterministic; no decision below is taken by it.
  for v_upload in
    select id,state from public.weekly_source_uploads
    where correction_session_id=v_session.id
    order by id
    for update
  loop
    if v_upload.state not in ('STAGING','CORRECTION_READY','REJECTED','SUPERSEDED') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
        using errcode='40001',
          detail='correction upload '||v_upload.id::text||' is '||v_upload.state
                 ||'; it has been promoted beyond this session and cancel will not '
                 'discard accepted work.';
    end if;
  end loop;
  for v_publication in
    select id,state from public.weekly_source_projection_publications
    where correction_session_id=v_session.id
    order by id
    for update
  loop
    if v_publication.state not in ('BUILDING','CORRECTION_READY','STALE','FAILED') then
      raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
        using errcode='40001',
          detail='correction publication '||v_publication.id::text||' is '
                 ||v_publication.state||'; it has been promoted beyond this session '
                 'and cancel will not discard accepted work.';
    end if;
  end loop;

  -- A cancel must never SILENTLY succeed.  Removing nothing where something was
  -- expected is a refusal, not a success -- which is exactly the shape of the
  -- defect next door, `public.invoice_remove_nhsp_shifts`, a routine that
  -- returns cleanly and does nothing (WP-54 handoff N3).  Two guards make that
  -- impossible here.
  --
  -- FIRST: a pointer the session still holds must resolve to a row that is
  -- actually bound back to this session.  The disposal loops key on
  -- correction_session_id, so a pointer at a row that is NOT bound would be
  -- left live while the cancel reported success.
  if v_session.replacement_correction_upload_id is not null
     and not exists(
       select 1 from public.weekly_source_uploads bound_upload
       where bound_upload.id=v_session.replacement_correction_upload_id
         and bound_upload.correction_session_id=v_session.id
     ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
      using errcode='40001',
        detail='replacement_correction_upload_id '
               ||v_session.replacement_correction_upload_id::text
               ||' is not bound back to this correction session; cancel will not '
               'report success over work it cannot account for.';
  end if;
  if v_session.replacement_projection_publication_id is not null
     and not exists(
       select 1 from public.weekly_source_projection_publications bound_publication
       where bound_publication.id=v_session.replacement_projection_publication_id
         and bound_publication.correction_session_id=v_session.id
     ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_REPLACEMENT_STALE'
      using errcode='40001',
        detail='replacement_projection_publication_id '
               ||v_session.replacement_projection_publication_id::text
               ||' is not bound back to this correction session; cancel will not '
               'report success over work it cannot account for.';
  end if;

  -- SECOND: count what is live before the effects, so the effects can be
  -- required to account for exactly that much afterwards.
  select pg_catalog.count(*) into v_live_uploads_before
  from public.weekly_source_uploads
  where correction_session_id=v_session.id
    and state in ('STAGING','CORRECTION_READY');
  select pg_catalog.count(*) into v_live_publications_before
  from public.weekly_source_projection_publications
  where correction_session_id=v_session.id
    and state in ('BUILDING','CORRECTION_READY');

  -- Effects.  One transaction, prior authority untouched.
  --
  -- WP-54 section 6.2 said to "move that upload to REJECTED".  Executed, that
  -- is only possible for an upload that is still STAGING.  The table's
  -- weekly_source_uploads_check3 is
  --   (state in ('SEALED','CURRENT','SUPERSEDED','CORRECTION_READY'))
  --     = (row_manifest_hash is not null)
  -- so moving a sealed CORRECTION_READY upload to REJECTED raises 23514 unless
  -- its row_manifest_hash is erased first -- which would destroy the very
  -- evidence 05 CFS-015 says must remain ("Staged upload and preview remain
  -- audit history only").  A sealed replacement therefore goes to SUPERSEDED,
  -- the state the pack already uses for an upload that stays audit-only and
  -- "cannot be promoted by the correction route" (05 CFS-011).  Both carry the
  -- same typed attempt, so the Blocked/attempt history reads the same either way.
  for v_upload in
    select id from public.weekly_source_uploads
    where correction_session_id=v_session.id
      and state='STAGING'
    order by id
  loop
    update public.weekly_source_uploads set state='REJECTED' where id=v_upload.id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
        using errcode='55000',
          detail='correction upload '||v_upload.id::text||' did not move to REJECTED '
                 '(rows='||v_rows::text||').';
    end if;
    perform private.weekly_source_upload_attempt_append_v1(
      v_upload.id,v_actor,'REJECTED','CORRECTION_SESSION_CANCELLED'
    );
    v_rejected_uploads:=v_rejected_uploads+1;
  end loop;
  for v_upload in
    select id from public.weekly_source_uploads
    where correction_session_id=v_session.id
      and state='CORRECTION_READY'
    order by id
  loop
    update public.weekly_source_uploads set state='SUPERSEDED' where id=v_upload.id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
        using errcode='55000',
          detail='correction upload '||v_upload.id::text||' did not move to SUPERSEDED '
                 '(rows='||v_rows::text||').';
    end if;
    perform private.weekly_source_upload_attempt_append_v1(
      v_upload.id,v_actor,'REJECTED','CORRECTION_SESSION_CANCELLED'
    );
    v_superseded_uploads:=v_superseded_uploads+1;
  end loop;
  for v_publication in
    select id from public.weekly_source_projection_publications
    where correction_session_id=v_session.id
      and state in ('BUILDING','CORRECTION_READY')
    order by id
  loop
    update public.weekly_source_projection_publications
    set state='STALE',failure_code='CORRECTION_SESSION_CANCELLED'
    where id=v_publication.id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
        using errcode='55000',
          detail='correction publication '||v_publication.id::text||' did not move to '
                 'STALE (rows='||v_rows::text||').';
    end if;
    v_staled_publications:=v_staled_publications+1;
  end loop;

  -- The effects must account for exactly what was live before them, and
  -- nothing bound to this session may still be live after them.  Either
  -- mismatch means the cancel did less than it is about to report, and a cancel
  -- that removed nothing where something was expected is a refusal, not a
  -- success.
  if (v_rejected_uploads+v_superseded_uploads)<>v_live_uploads_before
     or v_staled_publications<>v_live_publications_before then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
      using errcode='55000',
        detail='expected to dispose '||v_live_uploads_before::text||' upload(s) and '
               ||v_live_publications_before::text||' publication(s); disposed '
               ||(v_rejected_uploads+v_superseded_uploads)::text||' and '
               ||v_staled_publications::text||'.';
  end if;
  select pg_catalog.count(*) into v_live_uploads_after
  from public.weekly_source_uploads
  where correction_session_id=v_session.id
    and state in ('STAGING','CORRECTION_READY');
  select pg_catalog.count(*) into v_live_publications_after
  from public.weekly_source_projection_publications
  where correction_session_id=v_session.id
    and state in ('BUILDING','CORRECTION_READY');
  if v_live_uploads_after<>0 or v_live_publications_after<>0 then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CANCEL_INCOMPLETE'
      using errcode='55000',
        detail=v_live_uploads_after::text||' upload(s) and '
               ||v_live_publications_after::text||' publication(s) bound to this '
               'correction session are still live after the cancel.';
  end if;

  v_result:=pg_catalog.jsonb_build_object(
    'ok',true,'status','CANCELLED',
    'correction_session_id',v_session.id,
    'cancelled_from_state',v_state_before,
    'version',v_expected_session_version+1,
    'prior_final_revision_id',v_prior_revision.id,
    'rejected_upload_count',v_rejected_uploads,
    'superseded_upload_count',v_superseded_uploads,
    'staled_publication_count',v_staled_publications,
    'cancel_reason',v_reason,
    'cancel_idempotency_key',v_idempotency_key,
    'cancel_request_hash',pg_catalog.encode(v_request_hash,'hex')
  );
  v_result_hash:=private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_CORRECT_FINAL_CANCEL_RESULT_V1',v_result
  );

  -- state and completed_at_utc move in the SAME statement: the table's own
  -- check ((state in ('APPLIED','CANCELLED','FAILED')) = (completed_at_utc is
  -- not null)) refuses anything else, including a bare UPDATE.
  -- The session's `reason` column is deliberately NOT overwritten: it holds the
  -- reason the correction was opened for, which is audit history.  The cancel's
  -- own reason is carried in result_json and in the audit event, which is what
  -- 24 section 18 asks for ("actor, reason, decision time").
  update public.weekly_final_source_correction_sessions
  set state='CANCELLED',completed_at_utc=pg_catalog.transaction_timestamp(),
      result_json=v_result,result_hash=v_result_hash,
      version=version+1,updated_at_utc=pg_catalog.transaction_timestamp()
  where id=v_session.id and state=v_state_before
    and version=v_expected_session_version;
  if not found then
    raise exception 'WEEKLY_SOURCE_CORRECTION_SESSION_CAS_LOST' using errcode='40001';
  end if;

  insert into public.audit_events(
    ts_utc,actor_user_id,actor_display,actor_role_at_time,object_type,
    object_id_text,action,before_json,after_json,reason
  )
  select pg_catalog.statement_timestamp(),v_actor,actor.display_name,actor.role,
         'weekly_final_source_correction_sessions',v_session.id::text,
         'WEEKLY_SOURCE_CORRECT_FINAL_CANCELLED',
         pg_catalog.jsonb_build_object(
           'state',v_state_before,'version',v_expected_session_version,
           'expected_current_final_revision_id',v_prior_revision.id,
           'replacement_correction_upload_id',v_session.replacement_correction_upload_id,
           'replacement_projection_publication_id',
             v_session.replacement_projection_publication_id
         ),
         pg_catalog.jsonb_build_object(
           'state','CANCELLED','version',v_expected_session_version+1,
           'rejected_upload_count',v_rejected_uploads,
           'superseded_upload_count',v_superseded_uploads,
           'staled_publication_count',v_staled_publications,
           'prior_final_revision_state',v_prior_revision.state,
           'cancel_result_hash',pg_catalog.encode(v_result_hash,'hex')
         ),v_reason
  from public.tms_users actor where actor.id=v_actor;
  if not found then
    raise exception 'WEEKLY_SOURCE_ACTOR_NOT_FOUND' using errcode='55000';
  end if;

  return v_result||pg_catalog.jsonb_build_object('idempotent_replay',false);
end;
$function$;

create or replace function private.weekly_source_correct_final_preconditions_v1(
  p_prior_final_revision_id uuid,
  p_actor_user_id uuid,
  p_excluding_correction_session_id uuid,
  p_lock_roots boolean
) returns jsonb
language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_revision public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype;
  v_group public.weekly_source_groups%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_manifest public.weekly_source_client_manifests%rowtype;
  v_receipt public.weekly_source_ordinary_pay_projection_receipts%rowtype;
  v_root record;
  v_preflight jsonb;
  v_roots jsonb;
  v_family uuid[];
  v_family_after_lock uuid[];
  v_current_lock_upload public.weekly_source_uploads%rowtype;
  v_current_lock_publication public.weekly_source_projection_publications%rowtype;
  v_current_lock_generation integer;
  v_current_lock_operation uuid;
begin
  if exists(select 1 from public.weekly_source_final_revisions r where r.id=p_prior_final_revision_id and r.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  if p_prior_final_revision_id is null or p_actor_user_id is null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PRECONDITION_INPUT_INVALID'
      using errcode='22023';
  end if;

  select * into v_revision
  from public.weekly_source_final_revisions
  where id=p_prior_final_revision_id;
  if not found or v_revision.state<>'CURRENT' then
    raise exception 'WEEKLY_SOURCE_CORRECTION_FINAL_REVISION_STALE'
      using errcode='40001';
  end if;
  select * into strict v_cycle
  from public.weekly_source_cycles where id=v_revision.source_cycle_id;
  select * into strict v_group
  from public.weekly_source_groups where id=v_cycle.source_group_id;
  select * into strict v_upload
  from public.weekly_source_uploads where id=v_revision.upload_id;
  select * into strict v_profile
  from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;

  select * into v_manifest
  from public.weekly_source_client_manifests where coalesce(invoice_window_cycle_id,source_cycle_id)=source_cycle_id and final_revision_id=v_revision.id;
  if not found or exists(
    select 1 from public.weekly_source_client_manifests other_manifest
    where coalesce(other_manifest.invoice_window_cycle_id,other_manifest.source_cycle_id)=other_manifest.source_cycle_id and other_manifest.final_revision_id=v_revision.id
      and other_manifest.id<>v_manifest.id
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_CLIENT_SCOPE_INVALID'
      using errcode='55000';
  end if;

  if exists(
    select 1
    from public.weekly_source_final_revisions later_revision
    join public.weekly_source_cycles later_cycle
      on later_cycle.id=later_revision.source_cycle_id
    join public.weekly_source_client_manifests later_manifest on coalesce(later_manifest.invoice_window_cycle_id,later_manifest.source_cycle_id)=later_manifest.source_cycle_id and later_manifest.final_revision_id=later_revision.id
     and later_manifest.client_id=v_manifest.client_id
    join public.weekly_source_uploads later_upload on later_upload.id=later_revision.upload_id
    join public.weekly_source_format_profiles later_profile
      on later_profile.id=later_upload.source_format_profile_id
    where later_revision.state='CURRENT'
      and later_cycle.source_group_id=v_group.id
      and later_cycle.finalisation_week_ending>v_cycle.finalisation_week_ending
      and later_profile.final_authority_kind=v_profile.final_authority_kind
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_LATER_FINAL_CYCLE_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1 from public.weekly_source_final_revisions descendant
    where descendant.predecessor_revision_id=v_revision.id
      and not exists(
        select 1
        from public.weekly_final_source_correction_sessions own_correction
        where own_correction.id=p_excluding_correction_session_id
          and own_correction.expected_current_final_revision_id=v_revision.id
          and own_correction.prepared_final_revision_id=descendant.id
          and descendant.state='PREPARED'
      )
  ) or exists(
    select 1 from public.weekly_final_source_correction_sessions correction
    where correction.expected_current_final_revision_id=v_revision.id
      and correction.id is distinct from p_excluding_correction_session_id
      and correction.state not in ('CANCELLED','FAILED')
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_DESCENDANT_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1
    from public.weekly_exceptional_pay_target_events target_event
    where target_event.triggering_final_revision_id=v_revision.id
  ) or exists(
    select 1
    from public.weekly_exceptional_pending_reconciliation_targets pending_target
    where pending_target.current_final_revision_id=v_revision.id
      and pending_target.state='ACTIVE'
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_DESCENDANT_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1
    from public.weekly_source_invoice_line_bindings binding
    join public.weekly_source_billing_movements movement
      on movement.id=binding.billing_movement_id
    where movement.final_revision_id=v_revision.id
  ) or exists(
    select 1
    from public.weekly_source_invoice_placements placement
    join public.weekly_source_billing_movements movement
      on movement.id=placement.billing_movement_id
    where movement.final_revision_id=v_revision.id
      and placement.placement_state='PLACED'
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
      using errcode='55000';
  end if;

  if exists(
    select 1 from public.invoice_operations operation
    where operation.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and operation.operation_type in ('GENERATE_INVOICES','BUILD_DOCUMENT','ISSUE_INVOICES')
      and (
        (operation.entity_type='CLIENT' and operation.entity_id=v_manifest.client_id)
        or operation.input_json->>'client_id'=v_manifest.client_id::text
        or operation.input_json->'client_ids' @> pg_catalog.jsonb_build_array(v_manifest.client_id::text)
      )
  ) then
    raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_INVOICE_OPERATION'
      using errcode='55000';
  end if;

  -- Establish the complete sorted booking inventory BEFORE this owner's
  -- first old-family row lock. PREPARE/APPLY also include actual replacement
  -- upload roots and maintained prior-only CURRENT HR/expense coverage roots;
  -- OPEN has no replacement and locks only genuine exact prior membership.
  if coalesce(p_lock_roots,true) and (select active_owner from private.bpay_next_module_control where id=1)='NEXT' then
    if p_excluding_correction_session_id is not null then
      select u.* into v_current_lock_upload from public.weekly_final_source_correction_sessions s
        join public.weekly_source_uploads u on u.id=s.replacement_correction_upload_id
        where s.id=p_excluding_correction_session_id;
      if found then
        select p.* into strict v_current_lock_publication from public.weekly_final_source_correction_sessions s
          join public.weekly_source_projection_publications p on p.id=s.replacement_projection_publication_id
          where s.id=p_excluding_correction_session_id and p.upload_id=v_current_lock_upload.id;
        if v_current_lock_publication.authority_scope_version>2147483647 then
          raise exception 'WEEKLY_SOURCE_GENERATION_OVERFLOW' using errcode='22003';end if;
        v_current_lock_generation:=coalesce(v_current_lock_publication.projection_generation,v_current_lock_publication.authority_scope_version::integer);
      end if;
    end if;
    v_current_lock_operation:=private.bpay_next_source_current_lock_inventory_v1(
      v_current_lock_upload.id,v_current_lock_generation,v_revision.id,v_group.id,v_manifest.client_id,
      v_current_lock_upload.confirmed_coverage_start_local_date,v_current_lock_upload.confirmed_coverage_end_local_date
    );
  end if;

  for v_receipt in
    select receipt.*
    from public.weekly_source_ordinary_pay_projection_receipts receipt
    where receipt.final_revision_id=v_revision.id
      and receipt.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED')
    order by receipt.root_timesheet_id
  loop
    -- Gate 13 hostile review F5 / standing rule 3.  These preconditions guard
    -- one ordinary Weekly root against protected-pay ownership and against an
    -- existing invoice line.  After S8 the physical root id is not a family
    -- identity, so a protected family or an invoice line recorded against a
    -- rotated sibling was invisible here and the correction proceeded.
    --
    -- The lock is taken BEFORE the guarded state is read.  The family has to be
    -- named before its rows can be locked, so the identity is resolved, its
    -- rows are locked in a deterministic order, and the identity is then
    -- re-resolved and required to be unchanged (the same shape as the
    -- lock-and-resolve helper's post-lock re-read).  A membership change across
    -- the lock fails closed.
    v_family:=private.weekly_source_invoice_family_timesheet_ids_v1(
      v_receipt.root_timesheet_id
    );
    if v_family is null or pg_catalog.cardinality(v_family)=0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
        using errcode='55000';
    end if;
    if coalesce(p_lock_roots,true) then
      perform 1 from public.timesheets family_row
      where family_row.timesheet_id=any(v_family)
      order by family_row.timesheet_id
      for update;
      v_family_after_lock:=private.weekly_source_invoice_family_timesheet_ids_v1(
        v_receipt.root_timesheet_id
      );
      if v_family_after_lock is null
         or pg_catalog.cardinality(v_family_after_lock)=0
         or not (v_family_after_lock @> v_family and v_family @> v_family_after_lock)
      then
        raise exception 'WEEKLY_SOURCE_CORRECTION_FAMILY_UNRESOLVED'
          using errcode='40001';
      end if;
      v_family:=v_family_after_lock;
    end if;
    if exists(
      select 1 from public.weekly_exceptional_pay_target_families family
      where family.root_timesheet_id=any(v_family)
        and family.ownership_state='TARGET_MANAGED'
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_PROTECTED_TARGET_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.invoice_lines invoice_line
      where invoice_line.timesheet_id=any(v_family)
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000';
    end if;
    if exists(
      select 1 from public.timesheets timesheet_row
      where timesheet_row.timesheet_id=v_receipt.root_timesheet_id
        and timesheet_row.active_document_operation_id is not null
    ) or exists(
      select 1 from public.invoice_operations operation
      where operation.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and operation.entity_type='TIMESHEET'
        and operation.entity_id=v_receipt.root_timesheet_id
    ) or exists(
      select 1 from public.invoice_operation_chunks chunk
      where chunk.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
        and chunk.entity_type='TIMESHEET'
        and chunk.entity_id=v_receipt.root_timesheet_id
    ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_INVOICE_OPERATION'
        using errcode='55000';
    end if;

    v_preflight:=public.import_timesheet_financial_preflight_v1(
      array[v_receipt.root_timesheet_id],
      'WEEKLY_SOURCE_CORRECT_FINAL_SOURCE',p_actor_user_id,'{}'::jsonb,
      coalesce(p_lock_roots,true),1
    );
    if coalesce((v_preflight->>'blocking_batch_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ACTIVE_PAY_DRAFT'
        using errcode='55000',detail=v_preflight::text;
    elsif coalesce((v_preflight->>'paid_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ALREADY_PAID'
        using errcode='55000',detail=v_preflight::text;
    elsif coalesce((v_preflight->>'invoice_lined_count')::integer,0)>0 then
      raise exception 'WEEKLY_SOURCE_CORRECTION_INVOICE_LINE_EXISTS'
        using errcode='55000',detail=v_preflight::text;
    elsif coalesce((v_preflight->>'allowed')::boolean,false) is not true
       or v_preflight->>'required_path' not in (
         -- Gate 2 / XSG-032.  UNAUTHORISE_AMEND_RECALCULATE_REAUTHORISE is
         -- deliberately NOT admitted: Correct Final Source stays the narrow
         -- same-cycle correction for a root that is not yet authorised.  An
         -- already-authorised root always goes to proposal and Office decision.
         'DIRECT_AMEND_RECALCULATE'
       ) then
      raise exception 'WEEKLY_SOURCE_CORRECTION_ROOT_NOT_MUTABLE'
        using errcode='55000',detail=v_preflight::text;
    end if;
  end loop;

  if v_current_lock_operation is not null then
    perform private.bpay_next_source_current_lock_release_v1(v_current_lock_operation);
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'root_timesheet_id',receipt.root_timesheet_id,
    'prior_projection_receipt_id',receipt.id,
    'client_id',receipt.client_id,
    'source_profile_kind',receipt.source_profile_kind,
    'source_mode',receipt.source_mode,
    'root_after_hash',pg_catalog.encode(receipt.root_after_hash,'hex')
  ) order by receipt.root_timesheet_id),'[]'::jsonb)
  into v_roots
  from public.weekly_source_ordinary_pay_projection_receipts receipt
  where receipt.final_revision_id=v_revision.id
    and receipt.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED');

  return pg_catalog.jsonb_build_object(
    'prior_final_revision_id',v_revision.id,
    'source_cycle_id',v_cycle.id,'source_group_id',v_group.id,
    'authority_scope_kind',v_revision.authority_scope_kind,
    'report_scope_id',v_revision.report_scope_id,
    'client_id',v_manifest.client_id,
    'source_profile_kind',v_profile.final_authority_kind,
    'source_mode',case when v_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT'
      then 'NHSP_WEEKLY' else 'HEALTHROSTER_WEEKLY' end,
    'final_manifest_hash',pg_catalog.encode(v_revision.manifest_hash,'hex'),
    'affected_roots',v_roots
  );
end;
$function$;

create or replace function private.weekly_source_correct_final_office_preview_v1(
  p_correction_session_id uuid
) returns jsonb
language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_prior_revision public.weekly_source_final_revisions%rowtype;
  v_prior_profile public.weekly_source_format_profiles%rowtype;
  v_changes jsonb:='[]'::jsonb;
  v_blockers jsonb:='[]'::jsonb;
  v_confirmation text;
  v_old_report text;
  v_preview jsonb;
begin
  if exists(select 1 from public.weekly_final_source_correction_sessions c where c.id=p_correction_session_id and c.authority_scope_kind='SELF_BILL_REPORT_SCOPE') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_CORRECT_FINAL_UNSUPPORTED' using errcode='55000';
  end if;
  select * into v_session
  from public.weekly_final_source_correction_sessions
  where id=p_correction_session_id;
  if not found or v_session.state not in ('READY','REVIEWED','PREPARING','PREPARED','COMMITTING','APPLIED')
     or v_session.replacement_correction_upload_id is null
     or v_session.replacement_projection_publication_id is null then
    raise exception 'WEEKLY_SOURCE_CORRECTION_PREVIEW_NOT_READY' using errcode='55000';
  end if;
  select * into strict v_publication
  from public.weekly_source_projection_publications
  where id=v_session.replacement_projection_publication_id;
  select * into strict v_prior_revision
  from public.weekly_source_final_revisions
  where id=v_session.expected_current_final_revision_id;
  select profile.* into strict v_prior_profile
  from public.weekly_source_uploads upload_row
  join public.weekly_source_format_profiles profile
    on profile.id=upload_row.source_format_profile_id
  where upload_row.id=v_prior_revision.upload_id;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'candidate',coalesce(candidate.display_name,source_row.source_candidate_identity,'Candidate'),
    'day_date',to_char(source_row.work_date,'Dy FMDD Mon YYYY'),
    'problem',case
      when resolution.id is null then 'This row has not been linked yet'
      when resolution.mapping_state='CANDIDATE_NOT_FOUND' then 'Candidate could not be found'
      when resolution.mapping_state='CLIENT_NOT_FOUND' then 'Client could not be found'
      when resolution.mapping_state='NO_ELIGIBLE_CONTRACT' then 'No matching contract'
      when resolution.mapping_state in ('AMBIGUOUS_CONTRACT','CONTRACT_SELECTION_REQUIRED')
        then 'More than one contract matches'
      when source_row.row_finalisation_state='SOURCE_UNFINALISED' then 'This shift is not finalised'
      when charge.phase_severity='FINALISATION_BLOCKER' then 'Check the charge for this shift'
      else 'Check the hours for this shift' end,
    'action',case
      when resolution.mapping_state='CANDIDATE_NOT_FOUND' then 'Link candidate'
      when resolution.mapping_state='CLIENT_NOT_FOUND' then 'Link client'
      when resolution.mapping_state in ('NO_ELIGIBLE_CONTRACT','AMBIGUOUS_CONTRACT','CONTRACT_SELECTION_REQUIRED')
        then 'Choose contract'
      when charge.phase_severity='FINALISATION_BLOCKER' then 'Open charge details'
      else 'View details' end
  ) order by source_row.work_date,source_row.source_candidate_identity,source_row.source_row_ordinal),'[]'::jsonb)
  into v_blockers
  from public.weekly_source_upload_rows source_row
  left join public.weekly_source_row_resolutions resolution
    on resolution.upload_row_id=source_row.id
   and resolution.generation=coalesce(
     v_publication.projection_generation,
     v_publication.authority_scope_version::integer
   )
  left join public.candidates candidate on candidate.id=resolution.candidate_id
  left join public.weekly_source_charge_checks charge
    on charge.upload_row_id=source_row.id
   and charge.row_resolution_id=resolution.id
   and charge.generation=coalesce(
     v_publication.projection_generation,
     v_publication.authority_scope_version::integer
   )
  where source_row.upload_id=v_session.replacement_correction_upload_id
    and (
      resolution.id is null or resolution.mapping_state<>'RESOLVED'
      or source_row.row_finalisation_state in (
        'SOURCE_UNFINALISED','BLOCK_FINALISATION_DISAGREEMENT','BLOCK_ACTUAL_TUPLE'
      )
      or charge.phase_severity='FINALISATION_BLOCKER'
    );

  if pg_catalog.jsonb_array_length(v_blockers)=0 then
    if v_prior_profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT' then
      with prior_rows as (
        select movement.work_event_id,movement.source_line_kind,movement.candidate_id,
               movement.source_facts_json prior_facts,
               -- WP-54.  The money this line currently puts on the self-bill.
               -- Pack 14 section 4.3.1: for NHSP "The validated source total is
               -- the invoice value", and that is what this column holds.
               movement.invoice_presentation_charge_pence prior_charge_pence,
               pg_catalog.row_number() over(
                 partition by movement.work_event_id,movement.source_line_kind
                 order by source_row.source_row_ordinal,movement.id
               ) as row_number
        from public.weekly_source_billing_movements movement
        join public.weekly_source_upload_rows source_row
          on source_row.id=movement.nhsp_upload_row_id
        where movement.final_revision_id=v_session.expected_current_final_revision_id
      ), replacement_rows as (
        select resolution.work_event_id,
               case when economic.row_sign=1 then 'NHSP_PHYSICAL_POSITIVE'
                    else 'NHSP_PHYSICAL_FULL_NEGATIVE' end source_line_kind,
               resolution.candidate_id,
               pg_catalog.jsonb_build_object(
                 'work_date',source_row.work_date,
                 'start_at_local',source_row.start_at_local,
                 'end_at_local',source_row.end_at_local,
                 'break_minutes',source_row.break_minutes
               ) replacement_facts,
               -- WP-54.  The money the replacement line would put on the
               -- self-bill: the signed Commission + Total Cost the replacement
               -- report supplies, which pack 14 section 4.3.1 makes the invoice
               -- value once the server's own comparison has passed.
               source_row.source_shift_charge_pence replacement_charge_pence,
               pg_catalog.row_number() over(
                 partition by resolution.work_event_id,
                   case when economic.row_sign=1 then 'NHSP_PHYSICAL_POSITIVE'
                        else 'NHSP_PHYSICAL_FULL_NEGATIVE' end
                 order by source_row.source_row_ordinal,resolution.id
               ) as row_number
        from public.weekly_source_upload_rows source_row
        join public.weekly_source_row_resolutions resolution
          on resolution.upload_row_id=source_row.id
         and resolution.generation=coalesce(
           v_publication.projection_generation,
           v_publication.authority_scope_version::integer
         )
         and resolution.mapping_state='RESOLVED'
        join public.weekly_source_row_economic_snapshots economic
          on economic.row_resolution_id=resolution.id
        where source_row.upload_id=v_session.replacement_correction_upload_id
      ), paired as (
        select coalesce(replacement.work_event_id,prior.work_event_id) work_event_id,
               coalesce(replacement.source_line_kind,prior.source_line_kind) source_line_kind,
               coalesce(replacement.candidate_id,prior.candidate_id) candidate_id,
               prior.prior_facts,replacement.replacement_facts,
               prior.prior_charge_pence,replacement.replacement_charge_pence
        from prior_rows prior
        full join replacement_rows replacement
          on replacement.work_event_id=prior.work_event_id
         and replacement.source_line_kind=prior.source_line_kind
         and replacement.row_number=prior.row_number
      ), presented as (
        select paired.*,candidate.display_name,
          coalesce(replacement_facts->>'work_date',prior_facts->>'work_date') work_date,
          case when prior_facts is null then 'Not present' else
            to_char((prior_facts->>'start_at_local')::timestamp,'HH24:MI')||'-'||
            to_char((prior_facts->>'end_at_local')::timestamp,'HH24:MI')||' ('||
            coalesce(prior_facts->>'break_minutes','0')||' min break)' end current_final,
          case when replacement_facts is null then 'Not present' else
            to_char((replacement_facts->>'start_at_local')::timestamp,'HH24:MI')||'-'||
            to_char((replacement_facts->>'end_at_local')::timestamp,'HH24:MI')||' ('||
            coalesce(replacement_facts->>'break_minutes','0')||' min break)' end replacement,
          -- WP-54.  The same two lines expressed as money.  The preview
          -- compared the formatted TIME only, so a report that repriced every
          -- line produced changes=[] and the confirmation the Office signed --
          -- and the preview_hash that binds it -- covered an empty list.
          -- Pack 24 section 7 requires Office to see the exact consequence it
          -- is confirming; pack 14 section 4.3.1 makes this figure the invoice
          -- value.  The DECISION below compares exact signed pence; only the
          -- display is formatted.
          case when paired.prior_charge_pence is null then 'Not present'
               else private.weekly_source_office_money_text_v1(paired.prior_charge_pence::numeric/100)
          end current_final_amount,
          case when paired.replacement_charge_pence is null then 'Not present'
               else private.weekly_source_office_money_text_v1(paired.replacement_charge_pence::numeric/100)
          end replacement_amount,
          case when prior_facts is null then 'Added'
               when replacement_facts is null then 'Removed'
               else 'Changed' end result
        from paired
        left join public.candidates candidate on candidate.id=paired.candidate_id
      )
      select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'candidate',coalesce(display_name,'Candidate'),
        'day_date',to_char(work_date::date,'Dy FMDD Mon YYYY'),
        'current_final',current_final,'replacement',replacement,
        'current_final_amount',current_final_amount,
        'replacement_amount',replacement_amount,
        'amount_changed',prior_charge_pence is distinct from replacement_charge_pence,
        'result',result
      ) order by work_date,coalesce(display_name,''),work_event_id),'[]'::jsonb)
      into v_changes
      from presented
      where current_final is distinct from replacement
         or prior_charge_pence is distinct from replacement_charge_pence;
    else
      with prior_rows as (
        select snapshot.work_event_id,snapshot.candidate_id,snapshot.work_date,
               snapshot.start_at_local,snapshot.end_at_local,snapshot.break_minutes,
               -- WP-54.  The same blindness the NHSP branch had: this preview
               -- compared work date, times and break only.  On this route the
               -- money is the server's own calculation, so it moves when the
               -- Contract or the rate policy behind the row moves even though
               -- every displayed time is identical.  LEFT join: a row with no
               -- economic snapshot keeps its place in the pairing and simply
               -- carries no amount.
               prior_economic.calculated_charge_pence prior_charge_pence
        from public.weekly_source_final_snapshot_lines snapshot
        left join public.weekly_source_row_economic_snapshots prior_economic
          on prior_economic.row_resolution_id=snapshot.row_resolution_id
        where snapshot.final_revision_id=v_session.expected_current_final_revision_id
      ), replacement_rows as (
        select resolution.work_event_id,resolution.candidate_id,source_row.work_date,
               source_row.start_at_local,source_row.end_at_local,source_row.break_minutes,
               replacement_economic.calculated_charge_pence replacement_charge_pence
        from public.weekly_source_upload_rows source_row
        join public.weekly_source_row_resolutions resolution
          on resolution.upload_row_id=source_row.id
         and resolution.generation=coalesce(
           v_publication.projection_generation,
           v_publication.authority_scope_version::integer
         )
         and resolution.mapping_state='RESOLVED'
        left join public.weekly_source_row_economic_snapshots replacement_economic
          on replacement_economic.row_resolution_id=resolution.id
        where source_row.upload_id=v_session.replacement_correction_upload_id
          and (
            source_row.row_finalisation_state='SOURCE_WORKED'
            or (v_prior_profile.final_authority_kind='GENERIC_COMPLETE_SNAPSHOT'
                and source_row.row_finalisation_state='NOT_APPLICABLE')
          )
      ), paired as (
        select coalesce(replacement.work_event_id,prior.work_event_id) work_event_id,
               coalesce(replacement.candidate_id,prior.candidate_id) candidate_id,
               prior.work_date prior_date,prior.start_at_local prior_start,
               prior.end_at_local prior_end,prior.break_minutes prior_break,
               prior.prior_charge_pence,
               replacement.work_date replacement_date,
               replacement.start_at_local replacement_start,
               replacement.end_at_local replacement_end,
               replacement.break_minutes replacement_break,
               replacement.replacement_charge_pence
        from prior_rows prior
        full join replacement_rows replacement using(work_event_id)
      )
      select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'candidate',coalesce(candidate.display_name,'Candidate'),
        'day_date',to_char(coalesce(paired.replacement_date,paired.prior_date),'Dy FMDD Mon YYYY'),
        'current_final',case when paired.prior_date is null then 'Not present' else
          to_char(paired.prior_start,'HH24:MI')||'-'||to_char(paired.prior_end,'HH24:MI')||
          ' ('||paired.prior_break||' min break)' end,
        'replacement',case when paired.replacement_date is null then 'Not present' else
          to_char(paired.replacement_start,'HH24:MI')||'-'||to_char(paired.replacement_end,'HH24:MI')||
          ' ('||paired.replacement_break||' min break)' end,
        'current_final_amount',case when paired.prior_charge_pence is null then 'Not present'
          else private.weekly_source_office_money_text_v1(
            paired.prior_charge_pence::numeric/100) end,
        'replacement_amount',case when paired.replacement_charge_pence is null then 'Not present'
          else private.weekly_source_office_money_text_v1(
            paired.replacement_charge_pence::numeric/100) end,
        'amount_changed',paired.prior_charge_pence is distinct from paired.replacement_charge_pence,
        'result',case when paired.prior_date is null then 'Added'
          when paired.replacement_date is null then 'Removed' else 'Changed' end
      ) order by coalesce(paired.replacement_date,paired.prior_date),
        coalesce(candidate.display_name,''),paired.work_event_id),'[]'::jsonb)
      into v_changes
      from paired
      left join public.candidates candidate on candidate.id=paired.candidate_id
      -- WP-54: money joins date, times and break in the comparison, so a
      -- correction that moves only the figure can no longer present the Office
      -- with an empty change list.
      where pg_catalog.jsonb_build_array(
              paired.prior_date,paired.prior_start,paired.prior_end,paired.prior_break
            ) is distinct from pg_catalog.jsonb_build_array(
              paired.replacement_date,paired.replacement_start,
              paired.replacement_end,paired.replacement_break
            )
         or paired.prior_charge_pence is distinct from paired.replacement_charge_pence;
    end if;
  end if;

  if v_session.authority_scope_kind='NHSP_REPORT_SCOPE' then
    select backing.backing_report_number into strict v_old_report
    from public.weekly_source_nhsp_backing_reports backing
    where backing.final_revision_id=v_session.expected_current_final_revision_id;
    v_confirmation:='I understand this will replace report '||v_old_report||
      ' as the final report for this Trust and cutoff.';
  else
    v_confirmation:='I understand this will replace the final version for this group and week.';
  end if;
  v_preview:=pg_catalog.jsonb_build_object(
    'changes',v_changes,'blockers',v_blockers,'confirmation_text',v_confirmation
  );
  return v_preview||pg_catalog.jsonb_build_object(
    'preview_hash',pg_catalog.encode(private.weekly_source_sha256_jsonb_v1(
      'WEEKLY_SOURCE_CORRECT_FINAL_OFFICE_PREVIEW_V1',v_preview
    ),'hex')
  );
end;
$function$;

create or replace function private.weekly_source_invoice_duty_v1(p_root_timesheet_id uuid)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_root public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_scope jsonb; v_ids uuid[]; v_groups uuid[]; v_invoices uuid[];
  v_movement public.weekly_source_billing_movements%rowtype;
  v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype;
  v_profile public.weekly_source_format_profiles%rowtype;
  v_row public.weekly_source_upload_rows%rowtype;
  v_resolution public.weekly_source_row_resolutions%rowtype;
  v_session public.weekly_final_source_correction_sessions%rowtype;
  v_operation public.invoice_operations%rowtype;
  v_chunk public.invoice_operation_chunks%rowtype;
  v_member jsonb; v_members jsonb; v_context jsonb; v_guard jsonb; v_policy jsonb;
  v_basis jsonb:='[]'::jsonb; v_observation boolean;
  v_present boolean:=false; v_unknown boolean:=false;
  v_generation integer; v_count integer; v_invoice_id uuid; v_member_id uuid;
  v_linked_root uuid; v_text text; v_week date; v_relevant boolean;
  v_prior record;
begin
  select * into v_root from public.timesheets where timesheet_id=p_root_timesheet_id;
  if not found then return null; end if;
  select * into strict v_contract from public.contracts where id=v_root.contract_id;
  v_scope:=private.weekly_source_pay_query_scope_v1(p_root_timesheet_id);
  v_ids:=private.weekly_source_invoice_family_timesheet_ids_v1(p_root_timesheet_id);
  if v_scope is null or cardinality(v_ids) is null or cardinality(v_ids)=0 then return null; end if;
  select array_agg(distinct source_group_id) filter(where source_group_id is not null) into v_groups from (
    select c.source_group_id from public.weekly_source_row_timesheet_lineages l
      join public.weekly_source_cycles c on c.id=l.source_cycle_id where l.timesheet_id=any(v_ids)
    union select e.first_source_group_id from public.weekly_exceptional_pay_family_events fe
      join public.weekly_work_events e on e.id=fe.durable_work_event_id
      where fe.family_id=(v_scope->>'target_family_id')::uuid
    union select membership.source_group_id from public.weekly_source_group_clients membership
      where membership.client_id=v_contract.client_id
        and membership.valid_from<=v_root.week_ending_date
        and coalesce(membership.valid_to,'infinity'::date)>=v_root.week_ending_date-6
  ) groups;
  if cardinality(v_groups) is null or cardinality(v_groups)=0 then return null; end if;
  v_basis:=jsonb_build_array(jsonb_build_object('lane','DISCOVERY','groups',to_jsonb(v_groups),
    'scope',v_scope,'family_timesheet_ids',to_jsonb(v_ids)));
  select coalesce(array_agg(distinct l.invoice_id),'{}'::uuid[]) into v_invoices
    from public.invoice_lines l where l.timesheet_id=any(v_ids);

  -- Incomplete publication is not an empty invoice census. Discover across
  -- all cutoffs using client/group and actual work-date coverage, not the
  -- report's week. Nullable/unparsed date coverage remains relevant unknown.
  for v_upload in select u.* from public.weekly_source_uploads u
    join public.weekly_source_cycles c on c.id=u.source_cycle_id
    left join public.weekly_source_report_scopes s on s.id=u.report_scope_id
    where c.source_group_id=any(v_groups) and u.state not in ('CURRENT','SUPERSEDED','REJECTED')
      and (c.scope_client_id is null or c.scope_client_id=v_contract.client_id)
      and (s.client_id is null or s.client_id=v_contract.client_id)
      and (u.confirmed_coverage_start_local_date is null or u.confirmed_coverage_end_local_date is null
        or daterange(u.confirmed_coverage_start_local_date,u.confirmed_coverage_end_local_date+1,'[)')
          && daterange(v_root.week_ending_date-6,v_root.week_ending_date+1,'[)')
        or exists(select 1 from public.weekly_source_upload_rows r where r.upload_id=u.id
          and (r.work_date is null or r.work_date between v_root.week_ending_date-6 and v_root.week_ending_date)))
    order by u.id loop
    -- Prepared corrections have their complete old/new census below; they
    -- must not be permanently made unknown by their own CORRECTION_READY row.
    if v_upload.state='CORRECTION_READY' and exists(select 1 from public.weekly_final_source_correction_sessions s
      where s.id=v_upload.correction_session_id and s.replacement_correction_upload_id=v_upload.id
        and s.state in ('PREPARING','PREPARED','COMMITTING')) then continue; end if;
    v_unknown:=true;
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','INCOMPLETE_IMPORT',
      'upload',to_jsonb(v_upload),'present',null));
  end loop;

  -- Placement remains a duty across report cutoffs. A historical issued
  -- document alone is not work waiting to be invoiced again.
  for v_movement in select * from public.weekly_source_billing_movements where invoice_timesheet_id=any(v_ids)
    order by id loop
    v_observation:=null;
    if v_movement.candidate_id=v_contract.candidate_id and v_movement.contract_id=v_contract.id
       and v_movement.actual_client_id=v_contract.client_id then
      if v_movement.placement_state in ('UNPLACED','PLACED') then
        -- Prepared replacements are not yet admitted invoice movements. Their
        -- complete union and current seals are qualified in CORRECTION below.
        if exists(select 1 from public.weekly_source_final_revisions f
          where f.id=v_movement.final_revision_id and f.state='PREPARED') then
          if exists(select 1 from public.weekly_final_source_correction_sessions s
            where s.prepared_final_revision_id=v_movement.final_revision_id
              and s.state in ('PREPARING','PREPARED','COMMITTING')) then continue; end if;
        end if;
        if exists(select 1 from public.weekly_source_final_revisions f
          where f.id=v_movement.final_revision_id and f.state='CURRENT'
            and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)) then v_observation:=true; end if;
      elsif v_movement.placement_state='VOIDED_BY_CORRECT_FINAL' then
        if not exists(select 1 from public.weekly_source_invoice_line_bindings b
          where b.billing_movement_id=v_movement.id and b.state='CURRENT') then v_observation:=false; end if;
      elsif v_movement.placement_state='ISSUED' and exists(
        select 1 from public.weekly_source_invoice_line_bindings b
        join public.invoice_lines l on l.id=b.invoice_line_id and l.invoice_id=b.invoice_id
        join public.invoices i on i.id=b.invoice_id
        where b.billing_movement_id=v_movement.id and b.state='CURRENT'
          and b.client_id=v_movement.actual_client_id and i.client_id=v_movement.actual_client_id
          and l.timesheet_id=v_movement.invoice_timesheet_id
          and (i.status::text='ISSUED' or i.issue_state='ISSUED')) then v_observation:=false; end if;
    end if;
    v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','MOVEMENT','id',v_movement.id,
      'hash',encode(v_movement.movement_economic_hash,'hex'),'placement',v_movement.placement_state,'present',v_observation));
  end loop;

  -- Actual current imports, independent of their report/cutoff week. A
  -- checking-only NHSP import is positively excluded, not invoice authority.
  for v_upload in select u.* from public.weekly_source_uploads u
    join public.weekly_source_cycles c on c.id=u.source_cycle_id
    left join public.weekly_source_report_scopes s on s.id=u.report_scope_id
    where c.source_group_id=any(v_groups) and u.state='CURRENT'
      and (c.scope_client_id is null or c.scope_client_id=v_contract.client_id)
      and (s.client_id is null or s.client_id=v_contract.client_id) order by u.id
  loop
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CURRENT_IMPORT',
      'upload',to_jsonb(v_upload),'cycle',(select to_jsonb(c) from public.weekly_source_cycles c where c.id=v_upload.source_cycle_id),
      'report_scope',(select to_jsonb(s) from public.weekly_source_report_scopes s where s.id=v_upload.report_scope_id)));
    select * into strict v_profile from public.weekly_source_format_profiles where id=v_upload.source_format_profile_id;
    if v_profile.profile_code='NHSP_PREFINAL_RELEASED_V1' or v_profile.profile_json->>'purpose'='PREFINAL_CHECKING'
       or v_profile.row_finalisation_capability='CHECKING_ONLY' then continue; end if;
    -- A genuinely consumed Final already has its placement census above.
    if exists(select 1 from public.weekly_source_final_revisions f
      join public.weekly_source_cycles c on c.id=f.source_cycle_id
      left join public.weekly_source_report_scopes s on s.id=f.report_scope_id
      where f.upload_id=v_upload.id and f.source_cycle_id=v_upload.source_cycle_id
        and f.report_scope_id is not distinct from v_upload.report_scope_id
        and f.state='CURRENT' and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)
        and ((f.authority_scope_kind='CYCLE' and s.id is null and c.current_final_revision_id=f.id)
          or (f.authority_scope_kind in ('NHSP_REPORT_SCOPE','SELF_BILL_REPORT_SCOPE') and s.current_final_revision_id=f.id))) then continue; end if;
    select count(*) into v_count from public.weekly_source_projection_publications p
      where p.upload_id=v_upload.id and p.source_cycle_id=v_upload.source_cycle_id
        and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT';
    if v_count<>1 then v_unknown:=true; continue; end if;
    select * into strict v_publication from public.weekly_source_projection_publications p
      where p.upload_id=v_upload.id and p.source_cycle_id=v_upload.source_cycle_id
        and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT';
    begin
      v_guard:=private.weekly_source_current_publication_guard_v1(v_upload.source_cycle_id,
        v_publication.authority_scope_kind,v_upload.report_scope_id,v_upload.id,v_publication.id,v_publication.authority_scope_version);
    exception when sqlstate '55000' or sqlstate '22023' then v_unknown:=true; continue; end;
    if v_publication.authority_scope_version>2147483647 or coalesce(v_publication.projection_generation,0)>2147483647
       or v_publication.published_at_utc is null or not isfinite(v_publication.published_at_utc) then
      v_unknown:=true; continue; end if;
    v_generation:=coalesce(v_publication.projection_generation,v_publication.authority_scope_version::integer);
    -- Match the genuine roster Final owner's complete prior/current union.
    -- A prior root may own a reversal when its event is omitted inside coverage
    -- OR retained by a current row that moves it to another root/work week.
    -- NHSP NO_INFERENCE does not use roster omission authority.
    if v_profile.final_authority_kind in ('GENERIC_COMPLETE_SNAPSHOT','HEALTHROSTER_ACTUAL_ROWS')
       and v_profile.omission_meaning='CANCEL_INSIDE_CONFIRMED_COVERAGE' then
      for v_prior in
        with prior_states as (
          select distinct on(t.work_event_id) t.new_snapshot_line_id,t.id as transition_id
          from public.weekly_source_state_transitions t
          join public.weekly_source_final_revisions f on f.id=t.final_revision_id and f.state='CURRENT'
          join public.weekly_source_cycles c on c.id=t.finalisation_cycle_id
          join public.weekly_source_client_manifests m on coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=f.id and m.client_id=v_contract.client_id
          where t.source_profile_kind=v_profile.final_authority_kind
            and c.source_group_id=(select source_group_id from public.weekly_source_cycles where id=v_upload.source_cycle_id)
            and c.finalisation_week_ending<(select finalisation_week_ending from public.weekly_source_cycles where id=v_upload.source_cycle_id)
          order by t.work_event_id,c.finalisation_week_ending desc,f.finalised_at_utc desc,
            f.revision_number desc,t.created_at_utc desc,t.id desc
        ) select line.*,s.transition_id,
            exists(select 1 from public.weekly_source_row_resolutions r
              join public.weekly_source_upload_rows current_row on current_row.id=r.upload_row_id
              where current_row.upload_id=v_upload.id and r.generation=v_generation
                and r.work_event_id=line.work_event_id) as has_current_replacement
          from prior_states s
          join public.weekly_source_final_snapshot_lines line on line.id=s.new_snapshot_line_id
          where line.candidate_id=v_contract.candidate_id and line.contract_id=v_contract.id
            and line.client_id=v_contract.client_id
            and line.work_date between v_root.week_ending_date-6 and v_root.week_ending_date
          order by line.id
      loop
        v_observation:=null;
        if v_upload.coverage_state='COMPLETE' and v_upload.coverage_confirmed_by_user_id is not null
           and v_upload.coverage_confirmed_at_utc is not null and isfinite(v_upload.coverage_confirmed_at_utc)
           and v_upload.coverage_timezone='Europe/London'
           and v_upload.confirmed_coverage_start_local_date is not null
           and v_upload.confirmed_coverage_end_local_date is not null
           and (v_prior.work_date between v_upload.confirmed_coverage_start_local_date and v_upload.confirmed_coverage_end_local_date
             or v_prior.has_current_replacement) then
          begin
            v_policy:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,v_prior.work_date);
            v_linked_root:=private.weekly_source_finalisation_lineage_assert_v1(v_prior.row_resolution_id,
              (select source_cycle_id from public.weekly_source_final_revisions where id=v_prior.final_revision_id));
            if v_linked_root=p_root_timesheet_id and v_policy->>'authority_mode'='SOURCE_AUTHORITY'
               and v_policy->>'self_bill_enabled'='true'
               and v_policy->>'source_group_id'=(select source_group_id::text from public.weekly_source_cycles where id=v_upload.source_cycle_id)
              then v_observation:=true; end if;
          exception when sqlstate '55000' or sqlstate '40001' or sqlstate '22023' then null; end;
        elsif v_upload.coverage_state='COMPLETE'
           and v_upload.confirmed_coverage_start_local_date is not null
           and v_upload.confirmed_coverage_end_local_date is not null
           and not v_prior.has_current_replacement
           and v_prior.work_date not between v_upload.confirmed_coverage_start_local_date and v_upload.confirmed_coverage_end_local_date
          then v_observation:=false;
        end if;
        v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
        v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','PREFINAL_ROSTER_PRIOR_CURRENT_UNION',
          'prior_snapshot',to_jsonb(v_prior),'publication',to_jsonb(v_publication),'present',v_observation));
      end loop;
    end if;
    for v_row in select * from public.weekly_source_upload_rows where upload_id=v_upload.id
      and (work_date is null or work_date between v_root.week_ending_date-6 and v_root.week_ending_date) order by id loop
      if v_row.row_finalisation_state='SOURCE_REPORT_LINE' then
        select rr.* into v_resolution from public.weekly_source_self_bill_report_line_bindings b
          join public.weekly_source_row_resolutions rr on rr.id=b.bound_row_resolution_id
          where b.report_row_id=v_row.id and b.state='CURRENT';
        if not found then
          -- A never-bound line may be this root's mapped Request. Its report
          -- obligation is unknown, never a fabricated Withdrawn/no-duty state.
          if exists(select 1 from public.weekly_work_events e where e.first_source_group_id=any(v_groups)
            and e.client_id=v_contract.client_id and e.candidate_id=v_contract.candidate_id
            and e.work_date=v_row.work_date and e.profile_external_key=v_row.external_source_key) then v_unknown:=true; end if;
        elsif v_resolution.candidate_id=v_contract.candidate_id and v_resolution.client_id=v_contract.client_id
          and v_resolution.contract_id=v_contract.id then
          v_present:=true;
          v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','ACCEPTED_REPORT_ROW','report_row_id',v_row.id,
            'report_row_hash',encode(v_row.normalised_row_hash,'hex'),'bound_row_resolution_id',v_resolution.id,
            'publication',to_jsonb(v_publication),'present',true));
        end if;
        continue;
      end if;
      select * into v_resolution from public.weekly_source_row_resolutions
        where upload_row_id=v_row.id and generation=v_generation;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CURRENT_ROW_DISCOVERY',
        'row_id',v_row.id,'row_hash',encode(v_row.normalised_row_hash,'hex'),
        'resolution',to_jsonb(v_resolution),'publication',to_jsonb(v_publication)));
      if not found then v_unknown:=true; continue; end if;
      if v_resolution.candidate_id is not null and v_resolution.candidate_id<>v_contract.candidate_id
         or v_resolution.client_id is not null and v_resolution.client_id<>v_contract.client_id
         or v_resolution.contract_id is not null and v_resolution.contract_id<>v_contract.id then continue; end if;
      if v_resolution.mapping_state<>'RESOLVED' or v_row.work_date is null
         or v_contract.week_ending_weekday_snapshot is null
         or v_contract.week_ending_weekday_snapshot not between 0 and 6
         or v_row.work_date<v_contract.start_date
         or (v_contract.end_date is not null and v_row.work_date>v_contract.end_date)
         or v_root.submission_mode is distinct from 'MANUAL' then v_unknown:=true; continue; end if;
      begin
        v_policy:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,v_row.work_date);
      exception when sqlstate '55000' or sqlstate '22023' then v_unknown:=true; continue; end;
      if v_policy->>'authority_mode' is distinct from 'SOURCE_AUTHORITY'
         or v_policy->>'self_bill_enabled' is distinct from 'true'
         or v_policy->>'source_group_id' is distinct from (
           select c.source_group_id::text from public.weekly_source_cycles c where c.id=v_upload.source_cycle_id)
         or encode(v_resolution.effective_policy_fingerprint,'hex') is distinct from v_policy->>'policy_sha256'
         then v_unknown:=true; continue; end if;
      v_week:=v_row.work_date+((v_contract.week_ending_weekday_snapshot-extract(dow from v_row.work_date)::integer+7)%7);
      if v_week<>v_root.week_ending_date then continue; end if;
      v_linked_root:=null;
      if exists(select 1 from public.weekly_source_row_timesheet_lineages where row_resolution_id=v_resolution.id) then
        begin
          v_linked_root:=private.weekly_source_finalisation_lineage_assert_v1(v_resolution.id,v_upload.source_cycle_id);
        exception when sqlstate '55000' or sqlstate '40001' then v_unknown:=true; continue; end;
      else
        select cw.timesheet_id into v_linked_root from public.contract_weeks cw
          where cw.contract_id=v_contract.id and cw.week_ending_date=v_week and cw.additional_seq=0
            and not cw.is_adjustment and cw.status<>'CANCELLED'
            and cw.submission_mode_snapshot='MANUAL';
      end if;
      if v_linked_root is distinct from p_root_timesheet_id
         or not v_root.is_current or v_root.is_adjustment or v_root.revoked_at is not null
         or v_root.archived_at_utc is not null or v_root.sheet_scope<>'WEEKLY' or v_root.line_type<>'HOURS' then
        v_unknown:=true; continue; end if;
      v_present:=true;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','PREFINAL','row_id',v_row.id,
        'resolution_id',v_resolution.id,'generation',v_generation,'publication_guard',v_guard));
    end loop;
  end loop;

  -- Correct Final's full old/new union includes removal of its last movement.
  -- Unprepared or stale relevant replacements stay unknown, not empty.
  for v_session in select s.* from public.weekly_final_source_correction_sessions s
    join public.weekly_source_cycles c on c.id=s.source_cycle_id
    where c.source_group_id=any(v_groups) and s.state in ('DRAFT','STAGING','READY','REVIEWED','PREPARING','PREPARED','COMMITTING')
      and exists(select 1 from public.weekly_source_client_manifests m where coalesce(m.invoice_window_cycle_id,m.source_cycle_id)=m.source_cycle_id and m.final_revision_id=s.expected_current_final_revision_id and m.client_id=v_contract.client_id) order by s.id
  loop
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CORRECTION_DISCOVERY','session',to_jsonb(v_session)));
    if exists(select 1 from public.weekly_source_ordinary_pay_projection_receipts r
      where r.final_revision_id=v_session.expected_current_final_revision_id and r.root_timesheet_id=any(v_ids)
        and r.outcome in ('PREPARED_FOR_AUTHORISATION','PROPOSED')) then
      if v_session.prepared_final_revision_id is null then v_unknown:=true; continue; end if;
    elsif v_session.prepared_final_revision_id is null then v_unknown:=true; continue; end if;
    begin v_context:=private.weekly_source_correct_final_prepared_context_v1(v_session.id);
    exception when sqlstate '55000' then v_unknown:=true; continue; end;
    if v_session.prepare_result_hash is distinct from private.weekly_source_sha256_jsonb_v1(
         'WEEKLY_SOURCE_CORRECT_FINAL_PREPARE_RESULT_V1',v_session.prepare_result_json)
       or v_context->'root_contexts' is distinct from v_session.prepare_result_json->'root_contexts'
       or not exists(select 1 from public.weekly_source_final_revisions f
         join public.weekly_source_cycles c on c.id=f.source_cycle_id
         left join public.weekly_source_report_scopes s on s.id=f.report_scope_id
         where f.id=v_session.expected_current_final_revision_id and f.state='CURRENT'
           and f.manifest_hash=v_session.expected_final_manifest_hash
           and f.finalised_at_utc is not null and isfinite(f.finalised_at_utc)
           and f.source_cycle_id=v_session.source_cycle_id and f.report_scope_id is not distinct from v_session.report_scope_id
           and ((f.authority_scope_kind='CYCLE' and c.current_final_revision_id=f.id)
             or (f.authority_scope_kind in ('NHSP_REPORT_SCOPE','SELF_BILL_REPORT_SCOPE') and s.current_final_revision_id=f.id)))
       or not exists(select 1 from public.weekly_source_projection_publications p
         join public.weekly_source_uploads u on u.id=p.upload_id
         join public.weekly_source_final_revisions f on f.id=v_session.prepared_final_revision_id
         join public.weekly_source_format_profiles profile on profile.id=u.source_format_profile_id
         join public.weekly_source_final_revisions prior on prior.id=v_session.expected_current_final_revision_id
         join public.weekly_source_uploads prior_upload on prior_upload.id=prior.upload_id
         join public.weekly_source_format_profiles prior_profile on prior_profile.id=prior_upload.source_format_profile_id
         join public.weekly_source_cycles cycle on cycle.id=v_session.source_cycle_id
         join public.weekly_source_groups source_group on source_group.id=cycle.source_group_id
         left join public.weekly_source_report_scopes report_scope on report_scope.id=v_session.report_scope_id
         where p.id=v_session.replacement_projection_publication_id and u.id=v_session.replacement_correction_upload_id
           and p.state='CORRECTION_READY' and u.state='CORRECTION_READY'
           and p.correction_session_id=v_session.id and u.correction_session_id=v_session.id
           and p.source_cycle_id=v_session.source_cycle_id and u.source_cycle_id=v_session.source_cycle_id
           and p.report_scope_id is not distinct from v_session.report_scope_id
           and u.report_scope_id is not distinct from v_session.report_scope_id
           and u.purpose='FINAL_SOURCE_CORRECTION'
           and p.authority_scope_kind=v_session.authority_scope_kind
           and u.row_manifest_hash is not null and p.comparison_manifest_hash is not null and p.issue_set_hash is not null
           and p.authority_scope_version=case when v_session.authority_scope_kind='NHSP_REPORT_SCOPE'
             then report_scope.version else cycle.version end
           and prior_upload.state='CURRENT'
           and exists(select 1 from public.weekly_source_projection_publications current_publication
             where current_publication.id=case when v_session.authority_scope_kind='NHSP_REPORT_SCOPE'
               then report_scope.current_projection_publication_id else cycle.current_projection_publication_id end
               and current_publication.state='CURRENT' and current_publication.upload_id=prior_upload.id)
           and profile.final_authority_kind=prior_profile.final_authority_kind
           and (profile.final_authority_kind='NHSP_TRUST_BACKING_REPORT')=(source_group.source_family='NHSP')
           and f.state='PREPARED' and f.reason='CORRECT_FINAL_SOURCE'
           and f.upload_id=u.id and f.source_cycle_id=cycle.id
           and f.report_scope_id is not distinct from v_session.report_scope_id
           and f.predecessor_revision_id=prior.id
           and v_session.prepare_result_json->>'final_revision_id'=f.id::text
           and f.manifest_hash=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_FINAL_REVISION_MANIFEST_V1',
             jsonb_build_object('source_cycle_id',cycle.id,'authority_scope_kind',v_session.authority_scope_kind,
               'report_scope_id',v_session.report_scope_id,'revision_number',f.revision_number,'upload_id',u.id,
               'authority_scope_version',p.authority_scope_version,'row_manifest_hash',encode(u.row_manifest_hash,'hex'),
               'comparison_manifest_hash',encode(p.comparison_manifest_hash,'hex'),'issue_set_hash',encode(p.issue_set_hash,'hex'),
               'profile_code',profile.profile_code,'profile_version',profile.version,
               'coverage_start_local_date',f.coverage_start_local_date,'coverage_end_local_date',f.coverage_end_local_date,
               'reason',f.reason,'predecessor_revision_id',f.predecessor_revision_id,
               'prior_state_cutoff_revision_id',f.prior_state_cutoff_revision_id,
               'policy_fingerprint',encode(f.policy_fingerprint,'hex')))) then
      v_unknown:=true; continue; end if;
    v_guard:=private.weekly_source_correct_final_office_preview_v1(v_session.id);
    if v_session.prepare_result_json->'office_preview' is distinct from v_guard
       or v_session.review_result_json->'office_preview' is distinct from v_guard
       or jsonb_array_length(v_guard->'blockers')<>0 then v_unknown:=true; continue; end if;
    if not exists(select 1 from jsonb_array_elements(v_context->'root_contexts') r
      where (r->>'root_timesheet_id')::uuid=any(v_ids)) then continue; end if;
    v_present:=true;
    v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','CORRECTION','session_id',v_session.id,
      'prepared_context',v_context,'prepare_result_hash',encode(v_session.prepare_result_hash,'hex')));
  end loop;

  -- Use actual committed member chunks, not a client-wide fence. Ordinary
  -- selection expanders already exclude Source-owned roots in their owner.
  for v_chunk in select c.* from public.invoice_operation_chunks c
    join public.invoice_operations o on o.id=c.operation_id
    where o.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and c.status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED')
      and (not c.is_manifest_member or c.manifest_committed)
      and coalesce(c.payload_json->>'is_selection_expander','false')<>'true'
      and (not c.is_manifest_member or coalesce(c.entity_type,'')<>'OPERATION') order by c.id
  loop
    select * into strict v_operation from public.invoice_operations where id=v_chunk.operation_id;
    v_observation:=false;
    v_relevant:=(v_chunk.entity_type='TIMESHEET' and v_chunk.entity_id=any(v_ids))
      or (v_chunk.entity_type='INVOICE' and v_chunk.entity_id=any(v_invoices))
      or (v_operation.entity_type='TIMESHEET' and v_operation.entity_id=any(v_ids))
      or (v_operation.entity_type='INVOICE' and v_operation.entity_id=any(v_invoices));
    if v_chunk.entity_type='TIMESHEET' and v_chunk.entity_id=any(v_ids) then
      if v_operation.operation_type in ('GENERATE_INVOICES','ISSUE_INVOICES','RECONCILE_INVOICE_WORK') then v_observation:=true;
      elsif v_operation.operation_type='BUILD_DOCUMENT' then v_observation:=null; end if;
    end if;
    if v_chunk.payload_json->>'command_type'='GENERATE_CREDIT_NOTE' then
      v_text:=coalesce(v_chunk.payload_json->>'source_invoice_id',v_chunk.entity_id::text);
      if coalesce(v_text,'')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        if v_relevant then v_observation:=null; end if;
      else
        v_invoice_id:=v_text::uuid;
        if (v_chunk.entity_type='INVOICE' and v_chunk.entity_id=any(v_invoices)
          and v_chunk.entity_id is distinct from v_invoice_id) then
          v_observation:=null;
        elsif v_invoice_id=any(v_invoices) then
          v_relevant:=true;
          if v_chunk.entity_id is not null and v_chunk.entity_id<>v_invoice_id then v_observation:=null;
          else v_observation:=true; end if;
        end if;
      end if;
    elsif v_operation.operation_type='GENERATE_INVOICES' then
      v_members:=v_chunk.payload_json->'canonical_source_members';
      if v_chunk.payload_json ? 'canonical_source_members' and jsonb_typeof(v_members) is distinct from 'array' then
        -- A malformed primary manifest must not be replaced by fallback IDs.
        -- Fallback membership is discovery only, to qualify the relevant NULL.
        v_members:=coalesce(v_chunk.payload_json->'canonical_source_ids',v_chunk.payload_json->'source_ids','[]'::jsonb);
        if jsonb_typeof(v_members)='array' and exists(select 1 from jsonb_array_elements_text(v_members) s(value)
          where lower(s.value)=any(select id::text from unnest(v_ids) id)) then v_relevant:=true; end if;
        if v_relevant then v_observation:=null; end if;
        v_members:='[]'::jsonb;
      elsif v_members is null or jsonb_array_length(v_members)=0 then
        v_members:=coalesce(v_chunk.payload_json->'canonical_source_ids',v_chunk.payload_json->'source_ids','[]'::jsonb);
        if jsonb_typeof(v_members) is distinct from 'array' then
          if v_relevant then v_observation:=null; end if;
          v_members:='[]'::jsonb;
        else
          select coalesce(jsonb_agg(jsonb_build_object('source_type','TIMESHEET','source_id',s.value,
            'related_timesheet_id',s.value) order by s.ordinality),'[]'::jsonb) into v_members
            from jsonb_array_elements_text(v_members) with ordinality s(value,ordinality);
        end if;
      end if;
      -- Discover actual membership before validating ANY member, so malformed
      -- earlier evidence cannot disappear merely because the owned root is last.
      if exists(select 1 from jsonb_array_elements(v_members) m(value)
        where lower(m.value->>'related_timesheet_id')=any(select id::text from unnest(v_ids) id)
          or lower(m.value->>'source_id')=any(select id::text from unnest(v_ids) id)) then v_relevant:=true; end if;
      for v_member in select value from jsonb_array_elements(v_members) loop
        -- Canonical TIMESHEET members carry both independently valid identities.
        -- COALESCE cannot let a valid related ID conceal a malformed source ID.
        if upper(coalesce(v_member->>'source_type','TIMESHEET'))='TIMESHEET' then
          if coalesce(v_member->>'source_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             or coalesce(v_member->>'related_timesheet_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
            if v_relevant then v_observation:=null; end if;
            continue;
          end if;
          if (v_member->>'source_id')::uuid is distinct from (v_member->>'related_timesheet_id')::uuid then
            if v_relevant then v_observation:=null; end if;
            continue;
          end if;
        end if;
        v_text:=coalesce(v_member->>'related_timesheet_id',v_member->>'source_id');
        if coalesce(v_text,'')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          if v_relevant then v_observation:=null; end if;
          continue; end if;
        v_member_id:=v_text::uuid;
        if v_member_id=any(v_ids) then
          v_relevant:=true;
          if upper(coalesce(v_member->>'source_type','TIMESHEET'))='TIMESHEET' then
            if v_observation is not null then v_observation:=true; end if;
          else v_observation:=null; end if;
        end if;
      end loop;
    else
      v_text:=coalesce(v_chunk.payload_json->>'invoice_id',case when v_chunk.entity_type='INVOICE' then v_chunk.entity_id::text end);
      if v_chunk.entity_type='INVOICE' and v_chunk.entity_id=any(v_invoices)
         and v_text is distinct from v_chunk.entity_id::text then v_observation:=null;
      elsif v_text ~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and v_text::uuid=any(v_invoices) then
        v_relevant:=true;
        if v_operation.operation_type='ISSUE_INVOICES' then v_observation:=true;
        elsif v_operation.operation_type='BUILD_DOCUMENT' then v_observation:=null; end if;
      end if;
    end if;
    if v_relevant then
      v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','OPERATION_CHUNK',
        'operation',to_jsonb(v_operation),'chunk',to_jsonb(v_chunk),'present',v_observation));
    end if;
  end loop;
  -- ISSUE can be queued before its exact invoice chunks have been expanded.
  for v_operation in select * from public.invoice_operations where operation_type='ISSUE_INVOICES'
    and status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT','BLOCKED') order by id loop
    v_relevant:=v_operation.entity_type='INVOICE' and v_operation.entity_id=any(v_invoices);
    v_observation:=case when v_relevant then true else false end;
    if v_operation.input_json ? 'invoice_ids' then
      if jsonb_typeof(v_operation.input_json->'invoice_ids') is distinct from 'array' then
        if v_relevant then v_observation:=null; end if;
      else
        v_members:=v_operation.input_json->'invoice_ids';
        if exists(select 1 from jsonb_array_elements_text(v_members) s(value)
          where lower(s.value)=any(select id::text from unnest(v_invoices) id)) then v_relevant:=true; end if;
        if v_relevant then
          if exists(select 1 from jsonb_array_elements_text(v_members) s(value)
            where coalesce(s.value,'')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
            then v_observation:=null; else v_observation:=true; end if;
        end if;
      end if;
    end if;
    if v_relevant then
      v_present:=v_present or v_observation is true; v_unknown:=v_unknown or v_observation is null;
      v_basis:=v_basis||jsonb_build_array(jsonb_build_object('lane','QUEUED_ISSUE',
        'operation',to_jsonb(v_operation),'present',v_observation));
    end if;
  end loop;
  return jsonb_build_object('scope',v_scope,'present',case when v_present then true when v_unknown then null else false end,
    'discovery_complete',not v_unknown,'basis',v_basis);
end;
$function$;

create or replace function public.weekly_source_workspace_scopes_v1(p_request jsonb)
returns jsonb language plpgsql stable security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_actor uuid;
  v_group uuid;
  v_client uuid;
  v_week date;
  v_limit integer:=100;
  v_offset integer:=0;
  v_cursor jsonb;
  v_rows jsonb;
  v_version text;
  v_total integer;
  v_missing integer;
  v_pending integer;
  v_cutoffs jsonb;
  v_monday date:=(date_trunc('week',statement_timestamp() at time zone 'Europe/London'))::date;
begin
  perform private.weekly_source_query_require_service_v1();
  perform private._weekly_source_settings_assert_request_v1(p_request,
    array['actor_user_id','source_group_id','client_id','week_ending','cursor','limit'],
    'WEEKLY_SOURCE_SCOPE_REQUEST_INVALID');
  v_actor:=(p_request->>'actor_user_id')::uuid;
  v_group:=nullif(p_request->>'source_group_id','')::uuid;
  v_client:=nullif(p_request->>'client_id','')::uuid;
  v_week:=nullif(p_request->>'week_ending','')::date;
  v_limit:=coalesce((p_request->>'limit')::integer,100);
  if v_limit not between 1 and 100 then
    raise exception 'WEEKLY_SOURCE_SCOPE_REQUEST_INVALID' using errcode='22023';
  end if;
  perform private.weekly_source_office_authority_v1(v_actor,case when exists(select 1 from public.tms_users actor where actor.id=v_actor
    and lower(btrim(coalesce(actor.role,'')))='admin') then 'VIEW_SOURCE_PROGRESS' else 'VIEW_PAY_WORK' end,v_group);
  if nullif(p_request->>'cursor','') is not null then
    begin
      v_cursor:=convert_from(decode(p_request->>'cursor','base64'),'UTF8')::jsonb;
      v_offset:=(v_cursor->>'offset')::integer;
      if v_offset is null or v_offset<0 then raise exception 'invalid offset'; end if;
    exception when others then
      raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001';
    end;
  end if;
  with candidates as (
    select distinct on (source_group.id,membership.client_id,cycle.finalisation_week_ending)
      source_group.id group_id,source_group.display_name source_name,source_group.source_family,
      membership.client_id,client.name client_name,cycle.id cycle_id,
      cycle.scope_client_id,
      cycle.finalisation_week_ending,cycle.cutoff_at_utc,cycle.version cycle_version,
      cycle.current_complete_upload_id,cycle.current_projection_publication_id
    from public.weekly_source_groups source_group
    join public.weekly_source_cycles cycle on cycle.source_group_id=source_group.id
    join public.weekly_source_group_clients membership on membership.source_group_id=source_group.id
      and cycle.finalisation_week_ending between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
      and (cycle.scope_client_id is null or cycle.scope_client_id=membership.client_id)
    join public.clients client on client.id=membership.client_id
    where source_group.active and (v_group is null or source_group.id=v_group)
      and (v_client is null or membership.client_id=v_client)
      and (v_week is null or cycle.finalisation_week_ending=v_week)
      and exists(select 1 from public.weekly_source_client_policies policy
        where policy.source_group_id=source_group.id and policy.client_id=membership.client_id
          and policy.authority_mode='SOURCE_AUTHORITY'
          and cycle.finalisation_week_ending between policy.effective_from and coalesce(policy.effective_to,'infinity'::date))
    order by source_group.id,membership.client_id,cycle.finalisation_week_ending,
      (cycle.scope_client_id is not null) desc,cycle.id
  ), scopes as (
    select candidate.*,report.id report_scope_id,report.version report_version,
      case when candidate.source_family='NHSP' then report.current_complete_upload_id
        when candidate.scope_client_id=candidate.client_id then candidate.current_complete_upload_id end upload_id,
      case when candidate.source_family='NHSP' then report.current_projection_publication_id
        when candidate.scope_client_id=candidate.client_id then candidate.current_projection_publication_id end publication_id,
      coalesce(final_report.id,completion.id) completion_id,
      case when final_report.id is not null then 'FINAL_SOURCE' else completion.completion_kind end completion_kind,
      coalesce(final_report.finalised_at_utc,completion.attested_at_utc) completed_at,
      encode(coalesce(final_report.manifest_hash,completion.completion_hash),'hex') completion_hash,
      coalesce(report.cutoff_at_utc,candidate.cutoff_at_utc) actual_cutoff
    from candidates candidate
    left join public.weekly_source_report_scopes report on report.source_cycle_id=candidate.cycle_id
      and report.client_id=candidate.client_id and candidate.source_family='NHSP'
    left join public.weekly_source_client_cycle_completions completion
      on completion.source_cycle_id=candidate.cycle_id and completion.client_id=candidate.client_id
      and completion.state='CURRENT' and completion.completion_kind='NO_SHIFTS_TO_IMPORT'
    -- Completion belongs to this exact client/report. A completed sibling
    -- report for the same client/week must not hide another pending report.
    left join lateral (
      select revision.id,revision.finalised_at_utc,revision.manifest_hash
      from public.weekly_source_final_revisions revision
      join public.weekly_source_client_manifests manifest on coalesce(manifest.invoice_window_cycle_id,manifest.source_cycle_id)=manifest.source_cycle_id and manifest.final_revision_id=revision.id
        and manifest.client_id=candidate.client_id
      where revision.source_cycle_id=candidate.cycle_id and revision.state='CURRENT'
        and revision.report_scope_id is not distinct from report.id
      order by revision.revision_number desc,revision.id limit 1
    ) final_report on true
    union all
    select g.id,g.display_name,g.source_family,rs.client_id,cl.name,rc.id,rc.scope_client_id,
      rc.finalisation_week_ending,rc.cutoff_at_utc,rc.version,rc.current_complete_upload_id,rc.current_projection_publication_id,
      rs.id,rs.version,rs.current_complete_upload_id,rs.current_projection_publication_id,
      fr.id,case when fr.id is not null then 'FINAL_SOURCE' end,fr.finalised_at_utc,encode(fr.manifest_hash,'hex'),rs.cutoff_at_utc
    from public.weekly_source_report_scopes rs join public.weekly_source_self_bill_reports sr on sr.id=rs.self_bill_report_id
    join public.weekly_source_cycles rc on rc.id=rs.source_cycle_id
    join public.weekly_source_groups g on g.id=rs.source_group_id and g.active and g.source_family='ROSTER'
    join public.clients cl on cl.id=rs.client_id
    left join public.weekly_source_final_revisions fr on fr.id=rs.current_final_revision_id
      and fr.report_scope_id=rs.id and fr.authority_scope_kind='SELF_BILL_REPORT_SCOPE' and fr.state='CURRENT'
    -- Invoice-only report scopes are hidden from the reduced pay workspace.
    where exists(select 1 from public.tms_users actor where actor.id=v_actor and actor.is_active
      and lower(btrim(coalesce(actor.role,'')))='admin')
      and (v_group is null or rs.source_group_id=v_group) and (v_client is null or rs.client_id=v_client)
      and (v_week is null or rc.finalisation_week_ending=v_week)
      and exists(select 1 from public.weekly_source_group_clients gc where gc.source_group_id=rs.source_group_id
        and gc.client_id=rs.client_id and rc.finalisation_week_ending between gc.valid_from and coalesce(gc.valid_to,'infinity'::date))
  ), facts as (
    select scopes.*,private.weekly_source_import_is_prepared_v1(scopes.upload_id) prepared
    from scopes
  ), ordered as (
    select facts.*,bool_or(prepared) over(partition by cycle_id,client_id,
      case when exists(select 1 from public.weekly_source_report_scopes rs where rs.id=facts.report_scope_id and rs.self_bill_report_id is not null)
        then report_scope_id end) client_has_prepared,
      row_number() over(order by private.weekly_source_query_ascii_fold_v1(client_name) collate "C",
      client_id,finalisation_week_ending desc,group_id,report_scope_id nulls first) ordinal
    from facts
  )
  select count(*)::integer,
    count(distinct (cycle_id,client_id)) filter(where completion_id is null and not client_has_prepared
      and actual_cutoff<(v_monday::timestamp at time zone 'Europe/London'))::integer,
    count(distinct (cycle_id,client_id)) filter(where completion_id is null and prepared)::integer,
    encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_WORKSPACE_SCOPES_V1',
      jsonb_build_object('filter',p_request-'cursor'-'limit','rows',coalesce(jsonb_agg(jsonb_build_array(
        cycle_id,client_id,cycle_version,report_scope_id,report_version,upload_id,publication_id,completion_hash,prepared)
        order by ordinal),'[]'::jsonb))),'hex'),
    coalesce(jsonb_agg(jsonb_build_object(
      'key',cycle_id::text||':'||client_id::text||':'||coalesce(report_scope_id::text,'CYCLE'),
      'source_group_id',group_id,'source_cycle_id',cycle_id,'report_scope_id',report_scope_id,
      'client_id',client_id,'client',client_name,'source',source_name,'source_family',source_family,
      'week_ending',finalisation_week_ending,'period',to_char(finalisation_week_ending,'FMDD Mon YYYY'),
      'cutoff',actual_cutoff,'upload_id',upload_id,'projection_publication_id',publication_id,
      'prepared',prepared,'completed',completion_id is not null,'completion_kind',completion_kind,
      'completed_at',completed_at,
      'missing_previous_report',completion_id is null and not client_has_prepared
        and actual_cutoff<(v_monday::timestamp at time zone 'Europe/London')
      ) order by ordinal) filter(where ordinal>v_offset and ordinal<=v_offset+v_limit),'[]'::jsonb)
    into v_total,v_missing,v_pending,v_version,v_rows from ordered;
  if v_cursor is not null and v_cursor->>'version' is distinct from v_version then
    raise exception 'WEEKLY_SOURCE_WORKSPACE_CURSOR_STALE' using errcode='40001';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('source_group_id',source_group.id,
    'source',source_group.display_name,'cutoff',deadline.value,
    'passed',statement_timestamp()>=deadline.value) order by source_group.display_name,source_group.id),'[]'::jsonb)
  into v_cutoffs from public.weekly_source_groups source_group
  cross join lateral(select ((v_monday+((source_group.cutoff_weekday+6)%7))
    +source_group.cutoff_local_time) at time zone source_group.timezone value) deadline
  where source_group.active and (v_group is null or source_group.id=v_group)
    and exists(select 1 from public.weekly_source_group_clients membership
      join public.weekly_source_client_policies policy on policy.source_group_id=source_group.id
        and policy.client_id=membership.client_id and policy.authority_mode='SOURCE_AUTHORITY'
      where membership.source_group_id=source_group.id and (v_client is null or membership.client_id=v_client)
        and (statement_timestamp() at time zone source_group.timezone)::date between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
        and (statement_timestamp() at time zone source_group.timezone)::date between policy.effective_from and coalesce(policy.effective_to,'infinity'::date));
  return jsonb_build_object('ok',true,'contract','WEEKLY_SOURCE_WORKSPACE_SCOPES_V1',
    'rows',v_rows,'total_count',v_total,'version',v_version,
    'missing_previous_reports',v_missing,'reports_awaiting_finalisation',v_pending,
    'this_week_cutoffs',v_cutoffs,'has_more',v_offset+v_limit<v_total,
    'next_cursor',case when v_offset+v_limit<v_total then
      encode(convert_to(jsonb_build_object('offset',v_offset+v_limit,'version',v_version)::text,'UTF8'),'base64') else '' end);
end;
$function$;

-- Isolated complete source proposal. No installation/runtime acceptance.
create or replace function private.weekly_source_self_bill_report_finalise_v1(p_request jsonb,p_vat_rounding_variant text)
returns jsonb language plpgsql volatile security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_actor uuid; v_cycle public.weekly_source_cycles%rowtype; v_scope public.weekly_source_report_scopes%rowtype;
  v_report public.weekly_source_self_bill_reports%rowtype; v_upload public.weekly_source_uploads%rowtype;
  v_publication public.weekly_source_projection_publications%rowtype; v_rules jsonb; v_revision uuid; v_manifest uuid;
  v_policy bytea; v_hash bytea; v_row uuid; v_movement uuid; v_rounding uuid; v_count integer; v_client_hash bytea;
  v_rounding_pence bigint;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_vat_rounding_variant is null or p_vat_rounding_variant not in ('A','B') then
    raise exception 'WEEKLY_SOURCE_VAT_ROUNDING_COMPOSITION_UNPROVED' using errcode='55000'; end if;
  if jsonb_typeof(p_request) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_request) k where k not in (
    'actor_user_id','source_cycle_id','authority_scope_kind','report_scope_id','upload_id','projection_publication_id',
    'expected_authority_scope_version','expected_row_manifest_hash','expected_comparison_manifest_hash','expected_issue_set_hash','exclude_unfinalised_acknowledged'))
    or p_request->>'authority_scope_kind' is distinct from 'SELF_BILL_REPORT_SCOPE' then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_FINALISE_REQUEST_INVALID' using errcode='22023'; end if;
  v_actor:=(p_request->>'actor_user_id')::uuid;
  if v_actor is null then raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_ACTOR_REQUIRED' using errcode='22023'; end if;
  perform 1 from public.weekly_source_groups where id=(select source_group_id from public.weekly_source_cycles where id=(p_request->>'source_cycle_id')::uuid) for update;
  select * into strict v_cycle from public.weekly_source_cycles where id=(p_request->>'source_cycle_id')::uuid for update;
  select * into strict v_scope from public.weekly_source_report_scopes where id=(p_request->>'report_scope_id')::uuid for update;
  select * into strict v_report from public.weekly_source_self_bill_reports where id=v_scope.self_bill_report_id;
  select * into strict v_upload from public.weekly_source_uploads where id=(p_request->>'upload_id')::uuid for share;
  select * into strict v_publication from public.weekly_source_projection_publications where id=(p_request->>'projection_publication_id')::uuid for share;
  perform private.weekly_source_office_authority_v1(v_actor,'FINALISE_WEEK',v_cycle.source_group_id,v_scope.client_id,v_cycle.finalisation_week_ending);
  v_rules:=private.weekly_source_self_bill_report_rules_assert_v1(v_scope.client_id,v_cycle.id);
  if v_scope.source_cycle_id<>v_cycle.id or v_scope.source_group_id<>v_cycle.source_group_id
    or v_scope.cutoff_at_utc<>v_cycle.cutoff_at_utc or v_report.source_cycle_id<>v_cycle.id
    or v_report.client_id<>v_scope.client_id or v_scope.version is distinct from (p_request->>'expected_authority_scope_version')::bigint
    or v_scope.current_complete_upload_id is distinct from v_upload.id or v_scope.current_projection_publication_id is distinct from v_publication.id
    or v_scope.projection_state<>'CURRENT' or v_upload.state<>'CURRENT' or v_upload.report_scope_id<>v_scope.id
    or v_publication.state<>'CURRENT' or v_publication.authority_scope_kind<>'SELF_BILL_REPORT_SCOPE'
    or v_publication.upload_id<>v_upload.id or v_publication.report_scope_id<>v_scope.id or v_publication.authority_scope_version<>v_scope.version
    or v_upload.row_manifest_hash is distinct from private.weekly_source_hex32_v1(p_request->>'expected_row_manifest_hash','WEEKLY_SOURCE_ROW_MANIFEST_HASH_INVALID')
    or v_publication.comparison_manifest_hash is distinct from private.weekly_source_hex32_v1(p_request->>'expected_comparison_manifest_hash','WEEKLY_SOURCE_COMPARISON_MANIFEST_HASH_INVALID')
    or v_publication.issue_set_hash is distinct from private.weekly_source_hex32_v1(p_request->>'expected_issue_set_hash','WEEKLY_SOURCE_ISSUE_SET_HASH_INVALID') then
    raise exception 'WEEKLY_SOURCE_SELF_BILL_REPORT_FINALISE_CAS_STALE' using errcode='40001'; end if;
  if v_scope.current_final_revision_id is not null then
    if not exists(select 1 from public.weekly_source_final_revisions fr where fr.id=v_scope.current_final_revision_id
      and fr.authority_scope_kind='SELF_BILL_REPORT_SCOPE' and fr.report_scope_id=v_scope.id and fr.upload_id=v_upload.id and fr.state='CURRENT') then
      raise exception 'WEEKLY_SOURCE_REPORT_FINAL_POINTER_CORRUPT' using errcode='55000'; end if;
    return jsonb_build_object('ok',true,'status','FINALISED','final_revision_id',v_scope.current_final_revision_id,
      'source_cycle_id',v_cycle.id,'report_scope_id',v_scope.id,'invoice_only',true,'idempotent',true);
  end if;
  if v_scope.state not in ('OPEN','FINALISABLE') then raise exception 'WEEKLY_SOURCE_REPORT_SCOPE_NOT_OPEN' using errcode='55000'; end if;
  perform private.weekly_source_self_bill_report_seal_assert_v1(v_upload.id);
  perform private.weekly_source_final_upload_assert_v1(v_upload.id);
  if not private.weekly_source_import_is_prepared_v1(v_upload.id) then
    raise exception 'WEEKLY_SOURCE_REPORT_IMPORT_NOT_PREPARED' using errcode='55000'; end if;
  if exists(select 1 from public.weekly_source_upload_rows r where r.upload_id=v_upload.id
    and r.source_shift_charge_pence::numeric+r.source_vat_pence::numeric is distinct from r.source_gross_pence::numeric) then
    raise exception 'WEEKLY_SOURCE_REPORT_LITERAL_GROSS_MISMATCH' using errcode='55000'; end if;
  v_policy:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_REPORT_FINAL_POLICY_V1',v_rules);
  v_hash:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_REPORT_FINAL_MANIFEST_V1',jsonb_build_object(
    'source_cycle_id',v_cycle.id,'report_scope_id',v_scope.id,'self_bill_report_id',v_report.id,'upload_id',v_upload.id,
    'publication_id',v_publication.id,'authority_scope_version',v_scope.version,'row_manifest_hash',encode(v_upload.row_manifest_hash,'hex'),
    'report_row_manifest_hash',encode(v_report.row_manifest_hash,'hex'),'policy_fingerprint',encode(v_policy,'hex')));
  insert into public.weekly_source_final_revisions(source_cycle_id,authority_scope_kind,report_scope_id,revision_number,upload_id,
    reason,finalised_by_user_id,manifest_hash,policy_fingerprint,state,rule_set_version_id)
    values(v_cycle.id,'SELF_BILL_REPORT_SCOPE',v_scope.id,1,v_upload.id,'INITIAL_FINALISATION',v_actor,v_hash,v_policy,'CURRENT',
      (v_rules->>'rule_set_version_id')::uuid) returning id into v_revision;
  for v_row in select id from public.weekly_source_upload_rows where upload_id=v_upload.id order by source_row_ordinal loop
    v_movement:=private.weekly_source_self_bill_report_movement_insert_v1(v_row,v_revision);
  end loop;
  select count(*) into v_count from public.weekly_source_billing_movements where final_revision_id=v_revision and source_line_kind='SELF_BILL_REPORT_LINE';
  if v_count<>v_report.line_count or not exists(select 1 from public.weekly_source_billing_movements where final_revision_id=v_revision
    having sum(invoice_presentation_charge_pence)=v_report.net_pence and sum(vat_amount*100)=v_report.vat_pence and sum(total_inc_vat*100)=v_report.gross_pence) then
    raise exception 'WEEKLY_SOURCE_REPORT_MOVEMENT_TOTALS_MISMATCH' using errcode='55000'; end if;
  -- A/B is selected solely by the root integration after real proof. No default.
  v_rounding:=private.weekly_source_vat_rounding_movement_insert_v1(v_revision,v_scope.client_id,
    case when p_vat_rounding_variant='B' then v_movement else null end);
  select coalesce(sum(vat_amount*100),0)::bigint into v_rounding_pence from public.weekly_source_billing_movements
    where id=v_rounding and vat_rounding_revision_id=v_revision and actual_client_id=v_scope.client_id and source_line_kind='INVOICE_VAT_ROUNDING';
  if not exists(select 1 from public.weekly_source_billing_movements where final_revision_id=v_revision
    having sum(invoice_presentation_charge_pence)=v_report.net_pence
      and sum(vat_amount*100)=v_report.vat_pence::numeric+v_rounding_pence
      and sum(total_inc_vat*100)=v_report.net_pence::numeric+v_report.vat_pence::numeric+v_rounding_pence) then
    raise exception 'WEEKLY_SOURCE_REPORT_INVOICE_TARGET_TOTALS_MISMATCH' using errcode='55000'; end if;
  select private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_CLIENT_MANIFEST_V1',jsonb_build_object(
    'final_revision_id',v_revision,'source_group_id',v_cycle.source_group_id,'source_cycle_id',v_cycle.id,'client_id',v_scope.client_id,
    'finalisation_week_ending',v_cycle.finalisation_week_ending,'backing_report_number',v_report.report_number,
    'movements',jsonb_agg(jsonb_build_object('movement_id',id,'movement_economic_hash',encode(movement_economic_hash,'hex')) order by encode(movement_economic_hash,'hex')),
    'expense_authorities','[]'::jsonb)) into v_client_hash from public.weekly_source_billing_movements where final_revision_id=v_revision;
  insert into public.weekly_source_client_manifests(final_revision_id,source_group_id,source_cycle_id,client_id,finalisation_week_ending,
    backing_report_number,manifest_hash,movement_count,unchanged_snapshot_count,expense_line_count,invoice_state)
    values(v_revision,v_cycle.source_group_id,v_cycle.id,v_scope.client_id,v_cycle.finalisation_week_ending,v_report.report_number,v_client_hash,
      v_count+(v_rounding is not null)::integer,0,0,'READY') returning id into v_manifest;
  insert into public.weekly_source_manifest_movements(client_manifest_id,billing_movement_id,manifest_ordinal,movement_hash)
    select v_manifest,id,row_number() over(order by encode(movement_economic_hash,'hex'))::integer,movement_economic_hash
    from public.weekly_source_billing_movements where final_revision_id=v_revision;
  update public.weekly_source_report_scopes set current_final_revision_id=v_revision,state='FINALISED',updated_at_utc=transaction_timestamp()
    where id=v_scope.id and current_final_revision_id is null and version=v_scope.version
      and current_complete_upload_id=v_upload.id and current_projection_publication_id=v_publication.id;
  if not found then raise exception 'WEEKLY_SOURCE_REPORT_FINALISE_CAS_LOST' using errcode='40001'; end if;
  return jsonb_build_object('ok',true,'status','FINALISED','idempotent',false,'final_revision_id',v_revision,
    'source_cycle_id',v_cycle.id,'authority_scope_kind','SELF_BILL_REPORT_SCOPE','report_scope_id',v_scope.id,
    'self_bill_report_id',v_report.id,'invoice_date',v_report.invoice_date,'movement_count',v_count+(v_rounding is not null)::integer,
    'snapshot_count',0,'transition_count',0,'expense_generation_count',0,'invoice_only',true);
end;
$function$;

create or replace function private.weekly_source_rule_coverage_floor_v1(p_client_id uuid,p_cycle_id uuid)
returns date language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_cycle public.weekly_source_cycles%rowtype; v_floor date;
begin
  select * into strict v_cycle from public.weekly_source_cycles where id=p_cycle_id;
  if private.weekly_source_effective_rule_set_v1(p_client_id,p_cycle_id) is null then return null; end if;
  -- F1's only feature writer refuses false->false. A RULE_SET purpose and
  -- complete receipt remain after disable; a never-enabled draft has neither.
  -- Refuse malformed activated history rather than advancing a client's floor.
  if exists(select 1 from public.weekly_source_group_rule_assignments a
    join public.weekly_source_group_clients gc on gc.source_group_id=a.source_group_id and gc.client_id=p_client_id
      and daterange(gc.valid_from,coalesce(gc.valid_to,'infinity'::date),'[]')
        && daterange(a.effective_from_week_ending,coalesce(a.effective_to_week_ending,'infinity'::date),'[]')
    where a.source_group_id=v_cycle.source_group_id and a.feature_purpose='RULE_SET'
      and a.effective_from_week_ending<=v_cycle.finalisation_week_ending and (
        a.rule_set_version_id is null or a.feature_release_id is null or a.feature_changed_at_utc is null
        or a.feature_changed_by_user_id is null or a.feature_request_id is null or a.feature_request_sha256 is null
        or a.feature_receipt_json->>'contract' is distinct from 'WEEKLY_SOURCE_RULE_FEATURE_RECEIPT_V1'
        or a.feature_receipt_json->>'assignment_id' is distinct from a.id::text
        or a.feature_receipt_json->>'source_group_id' is distinct from a.source_group_id::text
        or a.feature_receipt_json->>'rule_set_version_id' is distinct from a.rule_set_version_id::text
        or a.feature_receipt_json->>'effective_from_week_ending' is distinct from a.effective_from_week_ending::text
        or a.feature_receipt_json->>'release_id' is distinct from a.feature_release_id
        or a.feature_receipt_json->>'actor_user_id' is distinct from a.feature_changed_by_user_id::text
        or a.feature_receipt_json->>'request_id' is distinct from a.feature_request_id::text
        or (a.feature_receipt_json->>'changed_at_utc')::timestamptz is distinct from a.feature_changed_at_utc
        or a.feature_receipt_json->>'feature_purpose' is distinct from 'RULE_SET'
        or a.feature_receipt_json->'feature_enabled' is distinct from to_jsonb(a.feature_enabled)
      )) then
    raise exception 'WEEKLY_SOURCE_RULE_COVERAGE_HISTORY_UNPROVABLE' using errcode='55000';
  end if;
  with applicable_assignments as (
    select greatest(a.effective_from_week_ending+((7-extract(dow from a.effective_from_week_ending)::integer)%7),
      gc.valid_from+((7-extract(dow from gc.valid_from)::integer)%7)) first_week,
      least(coalesce(a.effective_to_week_ending,'infinity'::date),coalesce(gc.valid_to,'infinity'::date),
        v_cycle.finalisation_week_ending) last_week
    from public.weekly_source_group_rule_assignments a
    join public.weekly_source_group_clients gc on gc.source_group_id=a.source_group_id and gc.client_id=p_client_id
    join public.weekly_source_rule_set_versions version on version.id=a.rule_set_version_id
    join public.weekly_source_rule_sets rules on rules.id=version.rule_set_id
    join public.weekly_source_groups source_group on source_group.id=a.source_group_id
      and source_group.agency_id=rules.agency_id and source_group.environment=rules.environment
    where a.source_group_id=v_cycle.source_group_id and a.feature_purpose='RULE_SET'
      and a.feature_release_id is not null and a.feature_changed_at_utc is not null
  ), frozen_use as (
    select source_cycle.finalisation_week_ending first_week
    from public.weekly_source_final_revisions final
    join public.weekly_source_cycles source_cycle on source_cycle.id=final.source_cycle_id
      and source_cycle.source_group_id=v_cycle.source_group_id
    join public.weekly_source_group_clients gc on gc.source_group_id=source_cycle.source_group_id
      and gc.client_id=p_client_id and source_cycle.finalisation_week_ending
        between gc.valid_from and coalesce(gc.valid_to,'infinity'::date)
    join public.weekly_source_rule_set_versions version on version.id=final.rule_set_version_id
    join public.weekly_source_rule_sets rules on rules.id=version.rule_set_id
    join public.weekly_source_groups source_group on source_group.id=source_cycle.source_group_id
      and source_group.agency_id=rules.agency_id and source_group.environment=rules.environment
    where source_cycle.finalisation_week_ending<=v_cycle.finalisation_week_ending
      and (source_cycle.scope_client_id=p_client_id or exists(
        select 1 from public.weekly_source_client_manifests manifest
        where manifest.final_revision_id=final.id and manifest.client_id=p_client_id)
        or exists(select 1 from public.weekly_source_report_scopes report
          where report.id=final.report_scope_id and report.source_cycle_id=source_cycle.id and report.client_id=p_client_id))
  ) select min(first_week)-6 into v_floor from (
    select first_week from applicable_assignments where first_week<=last_week
    union all select first_week from frozen_use
  ) history;
  if v_floor is null then raise exception 'WEEKLY_SOURCE_RULE_COVERAGE_HISTORY_UNPROVABLE' using errcode='55000'; end if;
  return v_floor;
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
  raise exception 'WEEKLY_SOURCE_RULE_COVERAGE_HISTORY_UNPROVABLE' using errcode='55000';
end;
$function$;

create or replace function private.weekly_source_upload_coverage_context_v1(p_client_id uuid,p_cycle_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'pg_catalog','pg_temp'
as $function$
declare v_cycle public.weekly_source_cycles%rowtype; v_rules jsonb; v_floor date;
  v_oldest date; v_completed date; v_has_final boolean;
begin
  select * into strict v_cycle from public.weekly_source_cycles where id=p_cycle_id;
  v_rules:=private.weekly_source_effective_rule_set_v1(p_client_id,p_cycle_id);
  if v_rules is null then return null; end if;
  v_floor:=private.weekly_source_rule_coverage_floor_v1(p_client_id,p_cycle_id);
  select min(event.work_date) into v_oldest
  from public.weekly_exceptional_pay_family_events event
  join public.weekly_exceptional_payment_approvals approval on approval.id=event.evidence_approval_id
    and approval.client_id=p_client_id and approval.withdrawn_at_utc is null
  join public.weekly_source_cycles origin on origin.id=approval.source_cycle_id
    and origin.source_group_id=v_cycle.source_group_id
  where event.state='WAIT' and event.work_date>=v_floor
    and event.event_sequence=(select max(latest.event_sequence)
      from public.weekly_exceptional_pay_family_events latest
      where latest.family_id=event.family_id and latest.durable_work_event_id=event.durable_work_event_id);
  -- A completed Contract week has ended in UK local time; planned future weeks
  -- and cancelled weeks are not evidence of a completed period.
  select max(week.week_ending_date) into v_completed
  from public.contract_weeks week join public.contracts contract on contract.id=week.contract_id
  where contract.client_id=p_client_id and week.status::text<>'CANCELLED'
    and week.week_ending_date<(statement_timestamp() at time zone 'Europe/London')::date;
  select exists(select 1 from public.weekly_source_final_revisions final
    join public.weekly_source_cycles cycle on cycle.id=final.source_cycle_id
      and cycle.source_group_id=v_cycle.source_group_id
    join public.weekly_source_client_manifests manifest on manifest.final_revision_id=final.id
      and manifest.client_id=p_client_id
    where final.state='CURRENT' and final.authority_scope_kind='CYCLE') into v_has_final;
  return jsonb_build_object('contract','WEEKLY_SOURCE_UPLOAD_COVERAGE_CONTEXT_V1',
    'coverage_floor_local_date',v_floor,'oldest_protected_work_date',v_oldest,
    'last_completed_contract_week',v_completed,'has_current_final_source',v_has_final,
    'lookback_warning_enabled',v_rules#>>'{values,lookback_warning}'='WARN_IF_AFTER_OLDEST_PROTECTED');
end;
$function$;

CREATE OR REPLACE FUNCTION public.weekly_source_client_settings_save_atomic_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_agency uuid;
  v_environment text;
  v_client uuid;
  v_expected text;
  v_input jsonb;
  v_effective_from date;
  v_current_shape jsonb;
  v_group_id uuid;
  v_group public.weekly_source_groups%rowtype;
  v_old_group_id uuid;
  v_locked_old_group_id uuid;
  v_membership public.weekly_source_group_clients%rowtype;
  v_policy public.weekly_source_client_policies%rowtype;
  v_policy_found boolean:=false;
  v_contract_count integer;
  v_client_nhsp_basis boolean:=false;
  v_client_agency_basis boolean:=false;
  v_family_count integer;
  v_mode_count integer;
  v_self_bill_count integer;
  v_family text;
  v_authority text;
  v_document text;
  v_self_bill boolean;
  v_correction text;
  v_source_expenses boolean;
  v_source_expense_vat boolean;
  v_rate_method text;
  v_tie_rule text;
  v_candidate_queries boolean;
  v_manager_queries boolean;
  v_manager_recipient text;
  v_completed_copy boolean;
  v_completed_recipient text;
  v_expense_supported boolean;
  v_prior_end date;
  v_nhsp_group_count integer;
  v_membership_history_count integer;
  v_policy_history_count integer;
  v_membership_effective_from date;
  v_policy_effective_from date;
begin
  perform private._weekly_source_settings_assert_request_v1(
    p_request,array[
      'actor_user_id','agency_id','environment','client_id',
      'expected_settings_version','settings'
    ],'WEEKLY_SOURCE_CLIENT_SETTINGS_SAVE_REQUEST_INVALID'
  );
  v_input:=p_request->'settings';
  perform private._weekly_source_settings_assert_request_v1(
    v_input,array[
      'source_group_id','effective_from','authority_mode','document_mode','self_bill_enabled',
      'self_bill_correction_presentation','source_fixed_expenses_enabled','source_expense_vat_enabled',
      'weekly_rate_classification_method','duration_break_tie_rule',
      'candidate_queries_enabled','manager_queries_enabled','manager_query_recipient',
      'completed_pack_copy_enabled','completed_pack_recipient'
    ],'WEEKLY_SOURCE_CLIENT_SETTINGS_VALUES_INVALID'
  );
  begin
    v_actor:=(p_request->>'actor_user_id')::uuid;
    v_agency:=(p_request->>'agency_id')::uuid;
    v_client:=(p_request->>'client_id')::uuid;
    v_expected:=pg_catalog.btrim(p_request->>'expected_settings_version');
    v_effective_from:=coalesce(nullif(v_input->>'effective_from','')::date,current_date);
    v_group_id:=nullif(v_input->>'source_group_id','')::uuid;
    v_correction:=nullif(pg_catalog.upper(pg_catalog.btrim(v_input->>'self_bill_correction_presentation')),'');
    v_source_expenses:=(v_input->>'source_fixed_expenses_enabled')::boolean;
    v_source_expense_vat:=(v_input->>'source_expense_vat_enabled')::boolean;
    v_rate_method:=pg_catalog.upper(pg_catalog.btrim(v_input->>'weekly_rate_classification_method'));
    v_tie_rule:=nullif(pg_catalog.upper(pg_catalog.btrim(v_input->>'duration_break_tie_rule')),'');
    v_candidate_queries:=(v_input->>'candidate_queries_enabled')::boolean;
    v_manager_queries:=(v_input->>'manager_queries_enabled')::boolean;
    v_manager_recipient:=nullif(pg_catalog.btrim(v_input->>'manager_query_recipient'),'');
    v_completed_copy:=(v_input->>'completed_pack_copy_enabled')::boolean;
    v_completed_recipient:=nullif(pg_catalog.btrim(v_input->>'completed_pack_recipient'),'');
  exception when others then
    raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_SAVE_REQUEST_INVALID' using errcode='22023';
  end;
  perform private._weekly_source_settings_require_admin_v1(v_actor);
  v_environment:=private._weekly_source_settings_deployment_v1(v_agency,p_request->>'environment');
  if v_effective_from<current_date or nullif(v_expected,'') is null then
    raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_SAVE_REQUEST_INVALID' using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'weekly-source-settings-client:'||v_client::text,0
  ));
  v_current_shape:=private._weekly_source_settings_client_shape_v1(
    v_agency,v_environment,v_client,v_effective_from
  );
  if v_current_shape->>'settings_version'<>v_expected then
    raise exception 'WEEKLY_SOURCE_SETTINGS_STALE' using errcode='40001';
  end if;
  if not (v_current_shape->>'eligible')::boolean then
    raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_NOT_APPLICABLE' using errcode='22023';
  end if;

  select pg_catalog.count(*),
         pg_catalog.count(distinct case
           when contract.weekly_timesheet_source::text='NHSP' then 'NHSP'
           when contract.weekly_timesheet_source::text='HEALTHROSTER' then 'ROSTER'
         end),
         pg_catalog.count(distinct case
           when contract.weekly_timesheet_source::text='NHSP'
             or coalesce(contract.no_timesheet_required,false) then 'SOURCE_AUTHORITY'
           else 'TIMESHEET_AUTHORITY'
         end),
         pg_catalog.count(distinct contract.self_bill),
         pg_catalog.min(case
           when contract.weekly_timesheet_source::text='NHSP' then 'NHSP'
           when contract.weekly_timesheet_source::text='HEALTHROSTER' then 'ROSTER'
         end),
         pg_catalog.min(case
           when contract.weekly_timesheet_source::text='NHSP'
             or coalesce(contract.no_timesheet_required,false) then 'SOURCE_AUTHORITY'
           else 'TIMESHEET_AUTHORITY'
         end),
         pg_catalog.bool_and(contract.self_bill)
  into v_contract_count,v_family_count,v_mode_count,v_self_bill_count,
       v_family,v_authority,v_self_bill
  from public.contracts contract
  where contract.client_id=v_client
    and contract.weekly_timesheet_source::text<>'NONE'
    and contract.end_date>=v_effective_from;

  -- Client setup precedes contracts. Only the currently effective dedicated
  -- NHSP client mode may supply this pre-contract configuration basis.
  -- Existing source contracts (including conflicting ones) remain authoritative.
  if v_contract_count=0 and coalesce((
    select settings.is_nhsp
      and not coalesce(settings.requires_hr,false)
      and not coalesce(settings.autoprocess_hr,false)
      and not coalesce(settings.no_timesheet_required,false)
    from public.client_settings settings
    where settings.client_id=v_client
      and (settings.effective_from is null or settings.effective_from<=v_effective_from)
    order by settings.effective_from desc nulls last,settings.updated_at desc,settings.id desc
    limit 1
  ),false) then
    v_family:='NHSP';
    v_authority:='SOURCE_AUTHORITY';
    v_self_bill:=true;
    v_family_count:=1;
    v_mode_count:=1;
    v_self_bill_count:=1;
    v_client_nhsp_basis:=true;
  end if;

  -- F1: derive the SOURCE/CHECK_ONLY exception only from an exact saved
  -- dated agency assignment and actual unsigned Client/Contract settings.
  v_client_agency_basis:=private.weekly_source_configured_agency_invoice_v1(
    v_client,v_group_id,v_agency,v_environment,v_effective_from);
  if v_client_agency_basis then
    v_authority:='SOURCE_AUTHORITY';
    v_self_bill:=false;
  end if;
  if (v_contract_count=0 and not v_client_nhsp_basis) or v_family_count<>1 or v_mode_count<>1 or v_self_bill_count<>1
     or (v_authority='SOURCE_AUTHORITY' and not v_self_bill and not v_client_agency_basis)
     or (v_authority='TIMESHEET_AUTHORITY' and v_self_bill) then
    raise exception 'WEEKLY_SOURCE_CLIENT_CONTRACT_POLICY_INCONSISTENT' using errcode='55000';
  end if;
  v_document:=case v_authority when 'SOURCE_AUTHORITY' then 'CHECK_ONLY'
    else 'INVOICE_EVIDENCE_REQUIRED' end;
  if (v_input ? 'authority_mode' and v_input->>'authority_mode'<>v_authority)
     or (v_input ? 'document_mode' and v_input->>'document_mode'<>v_document)
     or (v_input ? 'self_bill_enabled' and (v_input->>'self_bill_enabled')::boolean<>v_self_bill) then
    raise exception 'WEEKLY_SOURCE_CLIENT_READ_ONLY_POLICY_MISMATCH' using errcode='22023';
  end if;

  if v_family='NHSP' then
    select pg_catalog.count(*) into v_nhsp_group_count
    from public.weekly_source_groups source_group
    where source_group.agency_id=v_agency
      and source_group.environment=v_environment
      and source_group.source_family='NHSP'
      and source_group.active;
    if v_nhsp_group_count<>1 then
      raise exception 'WEEKLY_SOURCE_NHSP_GROUP_REQUIRED' using errcode='55000';
    end if;
    select source_group.id into strict v_group_id
    from public.weekly_source_groups source_group
    where source_group.agency_id=v_agency
      and source_group.environment=v_environment
      and source_group.source_family='NHSP'
      and source_group.active;
  end if;

  -- F8/G1: all finalisers lock their group row before cycle/revision writes.
  -- Preserve client-advisory-first; acquire both groups in the same UUID order
  -- before the established target-group lock and before any membership write.
  select membership.source_group_id into v_locked_old_group_id
  from public.weekly_source_group_clients membership
  join public.weekly_source_groups source_group on source_group.id=membership.source_group_id
  where membership.client_id=v_client and source_group.agency_id=v_agency
    and source_group.environment=v_environment
    and v_effective_from between membership.valid_from and coalesce(membership.valid_to,'infinity'::date);
  perform 1 from public.weekly_source_groups source_group
  where source_group.id=v_group_id or source_group.id=v_locked_old_group_id
  order by source_group.id for update;

  select * into v_group from public.weekly_source_groups source_group
  where source_group.id=v_group_id for update;
  if not found or v_group.agency_id<>v_agency or v_group.environment<>v_environment
     or not v_group.active or v_group.source_family<>v_family then
    raise exception 'WEEKLY_SOURCE_CLIENT_GROUP_NOT_APPLICABLE' using errcode='22023';
  end if;
  if v_rate_method not in ('SPLIT_RATE_WINDOWS','WHOLE_SHIFT_START_DAY')
     or (v_rate_method='SPLIT_RATE_WINDOWS' and v_tie_rule not in ('EARLIEST_LONGEST_PORTION','LATEST_LONGEST_PORTION')) then
    raise exception 'WEEKLY_SOURCE_CLIENT_RATE_SETTINGS_INVALID' using errcode='22023';
  end if;
  if v_rate_method<>'SPLIT_RATE_WINDOWS' then v_tie_rule:=null; end if;

  if v_self_bill and v_family='ROSTER' then
    if v_correction not in ('FULL_REVERSAL_REPLACEMENT','NET_DIFFERENCE_PRESENTATION') then
      raise exception 'WEEKLY_SOURCE_CLIENT_CORRECTION_SETTING_REQUIRED' using errcode='22023';
    end if;
  elsif v_correction is not null then
    raise exception 'WEEKLY_SOURCE_CLIENT_CORRECTION_SETTING_NOT_APPLICABLE' using errcode='22023';
  end if;

  select exists(
    select 1
    from public.weekly_source_uploads upload
    join public.weekly_source_cycles cycle on cycle.id=upload.source_cycle_id
    join public.weekly_source_format_profiles profile on profile.id=upload.source_format_profile_id
    where cycle.source_group_id=v_group_id
      and profile.profile_json ? 'expense_column'
      and upload.state in ('SEALED','CURRENT','SUPERSEDED','CORRECTION_READY')
  ) or coalesce((v_current_shape->'settings'->>'source_fixed_expenses_enabled')::boolean,false)
  into v_expense_supported;
  if v_client_agency_basis and (v_source_expenses or v_source_expense_vat) then
    raise exception 'WEEKLY_SOURCE_RULE_R13' using errcode='22023';
  end if;
  if v_source_expenses and not v_expense_supported then
    raise exception 'WEEKLY_SOURCE_CLIENT_SOURCE_EXPENSES_NOT_APPLICABLE' using errcode='22023';
  end if;
  if not v_source_expenses then v_source_expense_vat:=false; end if;

  if v_authority<>'SOURCE_AUTHORITY' then
    if v_candidate_queries or v_manager_queries or v_manager_recipient is not null
       or v_completed_copy or v_completed_recipient is not null then
      raise exception 'WEEKLY_SOURCE_CLIENT_QUERY_SETTINGS_NOT_APPLICABLE' using errcode='22023';
    end if;
  else
    if not v_manager_queries then v_manager_recipient:=null; end if;
    if v_manager_queries and v_manager_recipient is null then
      select nullif(pg_catalog.btrim(client.ts_queries_email),'') into v_manager_recipient
      from public.clients client where client.id=v_client;
    end if;
    if v_manager_queries and v_manager_recipient is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_QUERY_RECIPIENT_REQUIRED' using errcode='22023';
    end if;
    if not v_completed_copy then v_completed_recipient:=null; end if;
    if v_completed_copy and v_completed_recipient is null then
      select coalesce(
        v_manager_recipient,
        nullif(pg_catalog.btrim(client.ts_queries_email),'')
      ) into v_completed_recipient
      from public.clients client where client.id=v_client;
    end if;
    if v_completed_copy and v_completed_recipient is null then
      raise exception 'WEEKLY_SOURCE_COMPLETED_PACK_RECIPIENT_REQUIRED' using errcode='22023';
    end if;
  end if;

  select membership.* into v_membership
  from public.weekly_source_group_clients membership
  join public.weekly_source_groups source_group on source_group.id=membership.source_group_id
  where membership.client_id=v_client
    and source_group.agency_id=v_agency and source_group.environment=v_environment
    and v_effective_from between membership.valid_from and coalesce(membership.valid_to,'infinity'::date)
  for update of membership;
  if found then v_old_group_id:=v_membership.source_group_id; end if;
  if v_old_group_id is distinct from v_locked_old_group_id then
    raise exception 'WEEKLY_SOURCE_SETTINGS_STALE' using errcode='40001';
  end if;
  if v_old_group_id is not null and v_old_group_id<>v_group_id and exists(
    select 1 from public.weekly_source_final_revisions final
    join public.weekly_source_cycles cycle on cycle.id=final.source_cycle_id
      and cycle.source_group_id=v_old_group_id
    where final.state='CURRENT' and (
      cycle.scope_client_id=v_client
      or exists(select 1 from public.weekly_source_client_manifests manifest
        where manifest.final_revision_id=final.id and manifest.client_id=v_client)
      or exists(select 1 from public.weekly_source_report_scopes report
        where report.id=final.report_scope_id and report.client_id=v_client
          and report.source_cycle_id=cycle.id and report.source_group_id=v_old_group_id)
    )
  ) then
    raise exception 'WEEKLY_SOURCE_CLIENT_GROUP_HAS_CURRENT_FINAL_REVISION' using errcode='55000',
      detail='This client has a finalised report in its current group and cannot be moved.';
  end if;


  select pg_catalog.count(*) into v_membership_history_count
  from public.weekly_source_group_clients membership
  join public.weekly_source_groups source_group on source_group.id=membership.source_group_id
  where membership.client_id=v_client
    and source_group.agency_id=v_agency and source_group.environment=v_environment;
  v_membership_effective_from:=case when v_membership_history_count=0
    then date '1900-01-01' else v_effective_from end;

  if v_old_group_id is null then
    insert into public.weekly_source_group_clients(
      source_group_id,client_id,valid_from,created_by_user_id
    ) values (v_group_id,v_client,v_membership_effective_from,v_actor)
    returning * into v_membership;
  elsif v_old_group_id<>v_group_id then
    if v_membership.valid_from=v_effective_from then
      update public.weekly_source_group_clients
      set source_group_id=v_group_id
      where id=v_membership.id returning * into v_membership;
    else
      v_prior_end:=v_membership.valid_to;
      update public.weekly_source_group_clients set valid_to=v_effective_from-1
      where id=v_membership.id;
      insert into public.weekly_source_group_clients(
        source_group_id,client_id,valid_from,valid_to,created_by_user_id
      ) values (v_group_id,v_client,v_effective_from,v_prior_end,v_actor)
      returning * into v_membership;
    end if;
  end if;

  if v_old_group_id is not null then
    select * into v_policy
    from public.weekly_source_client_policies policy
    where policy.source_group_id=v_old_group_id and policy.client_id=v_client
      and v_effective_from between policy.effective_from and coalesce(policy.effective_to,'infinity'::date)
    for update;
    v_policy_found:=found;
  end if;
  select pg_catalog.count(*) into v_policy_history_count
  from public.weekly_source_client_policies policy
  join public.weekly_source_groups source_group on source_group.id=policy.source_group_id
  where policy.client_id=v_client
    and source_group.agency_id=v_agency and source_group.environment=v_environment;
  v_policy_effective_from:=case when v_policy_history_count=0
    then date '1900-01-01' else v_effective_from end;
  if v_policy_found and v_policy.effective_from=v_effective_from then
    update public.weekly_source_client_policies
    set source_group_id=v_group_id,authority_mode=v_authority,document_mode=v_document,
        self_bill_enabled=v_self_bill,self_bill_correction_presentation=v_correction,
        source_fixed_expenses_enabled=v_source_expenses,
        source_expense_vat_enabled=v_source_expense_vat,
        weekly_rate_classification_method=v_rate_method,duration_break_tie_rule=v_tie_rule,
        candidate_queries_enabled=v_candidate_queries,manager_queries_enabled=v_manager_queries,
        manager_query_recipient=v_manager_recipient,
        completed_pack_copy_enabled=v_completed_copy,completed_pack_recipient=v_completed_recipient,
        created_by_user_id=v_actor,created_at_utc=pg_catalog.transaction_timestamp()
    where id=v_policy.id;
  else
    if v_policy_found then
      v_prior_end:=v_policy.effective_to;
      update public.weekly_source_client_policies set effective_to=v_effective_from-1
      where id=v_policy.id;
    else
      v_prior_end:=null;
    end if;
    insert into public.weekly_source_client_policies(
      source_group_id,client_id,effective_from,effective_to,
      authority_mode,document_mode,self_bill_enabled,self_bill_correction_presentation,
      source_fixed_expenses_enabled,source_expense_vat_enabled,
      weekly_rate_classification_method,duration_break_tie_rule,
      candidate_queries_enabled,manager_queries_enabled,manager_query_recipient,
      completed_pack_copy_enabled,completed_pack_recipient,created_by_user_id
    ) values (
      v_group_id,v_client,v_policy_effective_from,v_prior_end,
      v_authority,v_document,v_self_bill,v_correction,
      v_source_expenses,v_source_expense_vat,v_rate_method,v_tie_rule,
      v_candidate_queries,v_manager_queries,v_manager_recipient,
      v_completed_copy,v_completed_recipient,v_actor
    );
  end if;

  if v_old_group_id is not null and v_old_group_id<>v_group_id then
    perform private._weekly_source_settings_stale_open_v1(v_old_group_id,v_client);
  end if;
  perform private._weekly_source_settings_stale_open_v1(v_group_id,v_client);
  return private._weekly_source_settings_client_shape_v1(
    v_agency,v_environment,v_client,v_effective_from
  );
exception when exclusion_violation then
  raise exception 'WEEKLY_SOURCE_CLIENT_SETTINGS_EFFECTIVE_RANGE_CONFLICT' using errcode='23P01';
end;
$function$;



do $active_work_guard$ begin
  if exists (
  select 1
  from public.invoice_operation_chunks
  where status in ('QUEUED','RUNNING','WAITING','RETRY_WAIT')
    and (
      (chunk_type='DOCUMENT_PLAN' and phase='BUILD_MANIFEST')
      or (chunk_type='ISSUE_INVOICE' and phase='FREEZE')
    )
) then raise exception 'INVOICE_PRESENTATION_SNAPSHOT_ACTIVE_WORK'; end if;
end; $active_work_guard$;


create or replace function private._invoice_presentation_snapshot_batch(
    p_requests jsonb,
    p_now_utc timestamptz default null
)
returns table (
    request_key text,
    snapshot_schema_version text,
    presentation_model jsonb,
    timesheet_sources jsonb,
    supporting_sources jsonb,
    higher_rate_support jsonb,
    snapshot_json jsonb,
    snapshot_hash text,
    valid boolean,
    error_code text,
    error_detail jsonb
)
language plpgsql
security definer
set search_path to 'public','private','extensions','pg_temp'
as $function$
#variable_conflict use_column
declare
  v_now timestamptz := coalesce(p_now_utc, now());
begin
  if p_requests is null or jsonb_typeof(p_requests) is distinct from 'array' then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  if jsonb_array_length(p_requests) < 1
     or jsonb_array_length(p_requests) > 100 then
    raise exception using errcode='22023',
      message='p_requests must be a JSON array containing 1..100 requests';
  end if;

  return query
  with recursive raw_requests as materialized (
    select x.ordinality::integer request_no,
           x.value raw_request,
           nullif(btrim(coalesce(x.value->>'request_key','')),'') req_key,
           upper(nullif(btrim(coalesce(x.value->>'entity_type','')),'')) entity_type,
           case when coalesce(x.value->>'entity_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             then (x.value->>'entity_id')::uuid end entity_id,
           upper(nullif(btrim(coalesce(x.value->>'purpose','')),'')) purpose,
           coalesce(nullif(btrim(x.value->>'template_version'),''),'invoice-professional-v2') template_version,
           case when pg_input_is_valid(nullif(x.value->>'issue_at_utc',''),'timestamptz') then (x.value->>'issue_at_utc')::timestamptz end issue_at_utc,
           case when pg_input_is_valid(nullif(x.value->>'tax_point_utc',''),'timestamptz') then (x.value->>'tax_point_utc')::timestamptz end tax_point_utc,
           case when pg_input_is_valid(nullif(x.value->>'due_at_utc',''),'timestamptz') then (x.value->>'due_at_utc')::timestamptz end due_at_utc
    from jsonb_array_elements(p_requests) with ordinality x(value,ordinality)
  ),
  key_stats as materialized (
    select req_key,count(*)::integer key_count,min(request_no) first_request_no
    from raw_requests
    where req_key is not null
    group by req_key
  ),
  duplicate_key_results as materialized (
    select r.request_no,
           r.req_key request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',r.request_no,'request_key',r.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           'DUPLICATE_REQUEST_KEY'::text error_code,
           jsonb_build_object('request_no',r.request_no,'request_key',r.req_key,'duplicate_count',ks.key_count,'first_request_no',ks.first_request_no) error_detail
    from raw_requests r
    join key_stats ks on ks.req_key=r.req_key
    where ks.key_count > 1
  ),
  processable as materialized (
    select r.*
    from raw_requests r
    left join key_stats ks on ks.req_key=r.req_key
    where coalesce(ks.key_count,0) <= 1
  ),
  invalid_request_results as materialized (
    select p.request_no,
           coalesce(p.req_key,'__request_'||p.request_no::text) request_key,
           'INVALID_PRESENTATION_REQUEST'::text snapshot_schema_version,
           '{}'::jsonb presentation_model,
           '[]'::jsonb timesheet_sources,
           '[]'::jsonb supporting_sources,
           jsonb_build_object('schema_version','HIGHER_RATE_PRESENTATION_V1','rows','[]'::jsonb) higher_rate_support,
           jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key) snapshot_json,
           encode(digest(jsonb_build_object('snapshot_schema_version','INVALID_PRESENTATION_REQUEST','request_no',p.request_no,'request_key',p.req_key)::text,'sha256'),'hex') snapshot_hash,
           false valid,
           case
             when p.req_key is null then 'REQUEST_KEY_REQUIRED'
             when length(p.req_key) > 256 then 'REQUEST_KEY_TOO_LONG'
             when p.entity_type not in('INVOICE','TIMESHEET') then 'ENTITY_TYPE_UNSUPPORTED'
             when p.entity_id is null then 'ENTITY_ID_INVALID'
             when p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET') then 'PURPOSE_UNSUPPORTED'
             when p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null) then 'FINAL_ISSUE_DATES_REQUIRED'
             else 'PRESENTATION_REQUEST_INVALID' end error_code,
           jsonb_build_object('request_no',p.request_no,'entity_type',p.entity_type,'purpose',p.purpose) error_detail
    from processable p
    where p.req_key is null
       or length(p.req_key) > 256
       or p.entity_type not in('INVOICE','TIMESHEET')
       or p.entity_id is null
       or p.purpose not in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
       or (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  valid_requests as materialized (
    select p.*
    from processable p
    where p.req_key is not null and length(p.req_key) <= 256
      and p.entity_type in('INVOICE','TIMESHEET')
      and p.entity_id is not null
      and p.purpose in('DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
      and not (p.purpose='FINAL_ISSUE' and (p.issue_at_utc is null or p.tax_point_utc is null or p.due_at_utc is null))
  ),
  requested_invoices as materialized (
    select entity_id invoice_id from valid_requests where entity_type='INVOICE'
  ),
  reference_scope as materialized (
    select r.*
    from private._invoice_reference_rows_batch(
      coalesce((select array_agg(distinct invoice_id) from requested_invoices), array[]::uuid[])
    ) r
  ),
  source_rounding_suppression as materialized (
    select il.invoice_id,il.id invoice_line_id,
      private.weekly_source_invoice_rounding_suppression_witness_v1(il.id) witness
    from public.invoice_lines il where il.invoice_id in(select invoice_id from requested_invoices)
      and il.meta_json->>'presentation_disposition'='SUPPRESS_ZERO_ROUNDING_AUTHORITY'
  ),
  source_rounding_suppression_agg as materialized (
    select invoice_id,jsonb_agg(witness order by invoice_line_id) witnesses
    from source_rounding_suppression group by invoice_id
  ),
  source_receipt_support as materialized (
    select ri.invoice_id,private.weekly_source_invoice_receipt_support_v1(ri.invoice_id) witness from requested_invoices ri
  ),
  invoice_line_base as materialized (
    select il.*,
           coalesce(nullif(btrim(vs.candidate_name),''),nullif(btrim(t.occupant_key_norm),'')) worker_name,
           coalesce(t.week_ending_date,
             case when pg_input_is_valid(nullif(il.meta_json->>'week_ending_date',''),'date')
               then (il.meta_json->>'week_ending_date')::date end)
             timesheet_week_ending_date,
           row_number() over(partition by il.invoice_id order by il.created_at,il.id)::integer base_display_order,
           case when pg_input_is_valid(nullif(il.meta_json->>'quantity',''),'numeric') then nullif(il.meta_json->>'quantity','')::numeric end meta_quantity,
           case when pg_input_is_valid(nullif(il.meta_json->>'units',''),'numeric') then nullif(il.meta_json->>'units','')::numeric end meta_units,
           case when il.timesheet_id is null
             then coalesce(nullif(btrim(il.meta_json->>'reference'),''),
               nullif(btrim(il.meta_json->>'po_number'),''))
             else refs.reference end canonical_reference,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_source,'NONE') end reference_source,
           case when il.timesheet_id is null then 'CUSTOM_LINE'
             else coalesce(refs.reference_scope,'TIMESHEET') end reference_scope,
           coalesce(refs.reference_source_row_keys,'[]'::jsonb)
             reference_source_row_keys,
           coalesce(refs.reference_required,false) reference_required
    from public.invoice_lines il
    left join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=il.timesheet_id
    left join lateral (
      select
        string_agg(x.current_reference,', ' order by x.first_row_key) reference,
        case when count(*)=1 then min(x.reference_source)
          else 'AGGREGATED_CANONICAL' end reference_source,
        case when count(*)=1 then min(x.reference_scope)
          else 'AGGREGATED_TIMESHEET' end reference_scope,
        jsonb_agg(x.row_key order by x.first_row_key) reference_source_row_keys,
        bool_or(x.is_required) reference_required
      from (
        select r.current_reference,min(r.row_key) first_row_key,
          min(r.row_key) row_key,
          min(case
            when r.ref_target='SEGMENT' then 'SEGMENT'
            when r.day_ymd is not null then 'DAY'
            else 'TIMESHEET' end) reference_source,
          min(case
            when r.ref_target='SEGMENT' then 'EXACT_SEGMENT'
            when r.day_ymd is not null then 'EXACT_DAY'
            else 'WHOLE_TIMESHEET' end) reference_scope,
          bool_or(r.is_required) is_required
        from reference_scope r
        where r.invoice_id=il.invoice_id and r.timesheet_id=il.timesheet_id
          and nullif(btrim(r.current_reference),'') is not null
        group by r.current_reference
      ) x
    ) refs on true
    where il.invoice_id in(select invoice_id from requested_invoices)
      and not exists(select 1 from source_rounding_suppression suppressed where suppressed.invoice_line_id=il.id and suppressed.witness is not null)
  ),
  invoice_line_component_raw as materialized (
    select b.invoice_id,b.id,b.created_at,
           (b.base_display_order*100+v.display_suffix)::integer base_display_order,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||v.bucket row_key,
           v.label description,
           b.canonical_reference reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           'hours'::text unit,
           round(coalesce(v.hours,0),4) quantity_raw,
           round(coalesce(v.hours,0)*coalesce(v.rate,0),4) net_raw,
           round(coalesce(b.total_charge_ex_vat,0),2) line_net,
           round(coalesce(b.vat_amount,0),2) line_vat,
           coalesce(b.vat_rate_pct,0) vat_rate,
           b.source_key,b.id source_invoice_line_id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    cross join lateral (values
      ('DAY','Day',1,coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
      ('NIGHT','Night',2,coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
      ('SATURDAY','Saturday',3,coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
      ('SUNDAY','Sunday',4,coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
      ('BANK_HOLIDAY','Bank holiday',5,coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
    ) v(bucket,label,display_suffix,hours,rate)
    where coalesce(v.hours,0)<>0
    union all
    select b.invoice_id,b.id,b.created_at,(b.base_display_order*100+90)::integer,
           coalesce(nullif(b.source_key,''),b.id::text)||':'||lower(coalesce(nullif(b.meta_json->>'line_type',''),'residual')),
           case
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'Mileage'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%TRAVEL%' then 'Travel'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ACCOMMODATION%' then 'Accommodation'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%HIGHER%' then 'Higher rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADDITIONAL%' then 'Additional rate'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%REVERS%' then 'Reversal'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%CREDIT%' then 'Credit'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%ADJUST%' then 'Adjustment'
             when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%EXPENSE%' then 'Other expenses'
             else coalesce(nullif(b.description,''),'Invoice line') end,
           b.canonical_reference,b.reference_required,b.reference_scope,
           b.reference_source,b.reference_source_row_keys,
           case when upper(coalesce(b.meta_json->>'line_type',b.source_key,'')) like '%MILEAGE%' then 'miles' else 'item' end,
           round(coalesce(b.meta_quantity,b.meta_units,1),4),
           round(coalesce(b.total_charge_ex_vat,0) - (
             coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
             + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
             + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
             + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
             + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
           ),4),
           round(coalesce(b.total_charge_ex_vat,0),2),round(coalesce(b.vat_amount,0),2),coalesce(b.vat_rate_pct,0),b.source_key,b.id,b.worker_name,
           b.timesheet_week_ending_date
    from invoice_line_base b
    where abs(coalesce(b.total_charge_ex_vat,0) - (
      coalesce(b.hours_day,0)*coalesce(b.charge_day,0)
      + coalesce(b.hours_night,0)*coalesce(b.charge_night,0)
      + coalesce(b.hours_sat,0)*coalesce(b.charge_sat,0)
      + coalesce(b.hours_sun,0)*coalesce(b.charge_sun,0)
      + coalesce(b.hours_bh,0)*coalesce(b.charge_bh,0)
    )) > 0.004
       or not exists (
         select 1 from (values
           (coalesce(b.hours_day,0),coalesce(b.charge_day,0)),
           (coalesce(b.hours_night,0),coalesce(b.charge_night,0)),
           (coalesce(b.hours_sat,0),coalesce(b.charge_sat,0)),
           (coalesce(b.hours_sun,0),coalesce(b.charge_sun,0)),
           (coalesce(b.hours_bh,0),coalesce(b.charge_bh,0))
         ) nonzero(h,a) where coalesce(h,0)<>0 or coalesce(a,0)<>0)
  ),
  invoice_line_component_ranked as materialized (
    select r.*,
      row_number() over(partition by r.id order by r.base_display_order,r.row_key)::integer component_no,
      count(*) over(partition by r.id)::integer component_count,
      case when coalesce(r.line_net,0)<>0 then r.line_vat * r.net_raw / r.line_net
           else r.line_vat / nullif(count(*) over(partition by r.id),0) end raw_vat
    from invoice_line_component_raw r
  ),
  invoice_line_components as materialized (
    select q.invoice_id,q.id,q.created_at,q.base_display_order,q.row_key,q.description,
           q.reference,q.reference_required,q.reference_scope,q.reference_source,
           q.reference_source_row_keys,q.unit,
           q.quantity_raw quantity,
           case when q.quantity_raw<>0 then round(q.net_amount/q.quantity_raw,4) else q.net_amount end unit_price,
           q.net_amount,q.vat_rate,q.vat_amount,round(q.net_amount+q.vat_amount,2) gross_amount,
           q.source_key,q.source_invoice_line_id,q.worker_name,
           q.timesheet_week_ending_date
    from (
      select r.*,
        case when r.component_no=r.component_count
          then round(r.line_net - coalesce(sum(round(r.net_raw,2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(r.net_raw,2) end net_amount,
        case when r.component_no=r.component_count
          then round(r.line_vat - coalesce(sum(round(coalesce(r.raw_vat,0),2)) over(partition by r.id order by r.component_no rows between unbounded preceding and 1 preceding),0),2)
          else round(coalesce(r.raw_vat,0),2) end vat_amount
      from invoice_line_component_ranked r
    ) q
  ),
  invoice_line_rows as materialized (
    select c.invoice_id,
           jsonb_agg(jsonb_build_object(
             'row_key',c.row_key,
             'source_invoice_line_id',c.source_invoice_line_id,
             'source_key',coalesce(c.source_key,c.source_invoice_line_id::text),
             'description',c.description,
             'worker',c.worker_name,
             'week_ending_date',c.timesheet_week_ending_date,
             'reference',c.reference,
             'reference_required',c.reference_required,
             'reference_scope',c.reference_scope,
             'reference_source',c.reference_source,
             'reference_source_row_keys',c.reference_source_row_keys,
             'unit',c.unit,
             'quantity',c.quantity::text,
             'unit_price',c.unit_price::text,
             'net_amount',c.net_amount::text,
             'vat_rate',c.vat_rate::text,
             'vat_amount',c.vat_amount::text,
             'gross_amount',c.gross_amount::text,
             'display_order',c.base_display_order
           ) order by c.created_at,c.id,c.base_display_order) lines,
           round(sum(c.net_amount),2) line_net,
           round(sum(c.vat_amount),2) line_vat,
           round(sum(c.gross_amount),2) line_gross
    from invoice_line_components c
    group by c.invoice_id
  ),
  timesheet_targets as materialized (
    select distinct il.invoice_id,t.timesheet_id
    from requested_invoices ri
    join public.invoice_lines il on il.invoice_id=ri.invoice_id
      and il.timesheet_id is not null
    join public.timesheets t on t.timesheet_id=il.timesheet_id and t.is_current
    union
    select null::uuid,vr.entity_id
    from valid_requests vr
    where vr.entity_type='TIMESHEET'
  ),
  timesheet_base as materialized (
    select target.invoice_id,t.timesheet_id,t.document_revision,
      upper(coalesce(t.sheet_scope::text,'')) sheet_scope,
      upper(coalesce(t.submission_mode::text,'')) submission_mode,
      t.contract_id,t.week_ending_date,
      t.worked_start_iso,t.worked_end_iso,t.break_start_iso,t.break_end_iso,
      coalesce(t.break_minutes,0) break_minutes,t.actual_schedule_json,
      t.day_references_json,t.reference_number,t.additional_units_week,
      t.additional_units_per_day,t.authorised_at_server,t.auth_name,
      t.auth_job_title,t.r2_nurse_key,t.r2_auth_key,t.img_sha256_nurse,
      t.img_sha256_auth,t.qr_status::text qr_status,t.qr_token,
      t.qr_payload_json,t.qr_signed_hash,t.qr_signed_at_utc,
      coalesce(vs.candidate_id,tf.candidate_id,ct.candidate_id) candidate_id,
      coalesce(vs.client_id,tf.client_id,ct.client_id) client_id,
      coalesce(nullif(btrim(cand.first_name),''),
        split_part(coalesce(vs.candidate_name,t.occupant_key_norm,''),' ',1))
        candidate_first_name,
      coalesce(nullif(btrim(cand.last_name),''),
        nullif(btrim(regexp_replace(
          coalesce(vs.candidate_name,t.occupant_key_norm,''),
          '^[^ ]+[ ]*','','g')),'')) candidate_surname,
      coalesce(nullif(btrim(tf.role),''),nullif(btrim(t.job_title_norm),''),
        nullif(btrim(ct.role),'')) job_profile_title,
      coalesce(nullif(btrim(cl.name),''),nullif(btrim(vs.client_name),''),
        nullif(btrim(t.hospital_norm),'')) client_name,
      nullif(lower(btrim(t.hospital_norm)),'') hospital_norm,
      nullif(lower(btrim(t.ward_norm)),'') ward_norm,
      coalesce(
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        nullif(btrim(cl.name),''),
        nullif(btrim(vs.client_name),'')) hospital,
      regexp_replace(
        regexp_replace(
          initcap(lower(nullif(btrim(t.ward_norm),''))),
          '\mNhs\M','NHS','g'),
        '\mIcu\M','ICU','g') ward_display,
      concat_ws(' - ',
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.hospital_norm),''))),
            '\mSt Richards\M','St Richard''s','g'),
          '\mNhs\M','NHS','g'),
        regexp_replace(
          regexp_replace(
            initcap(lower(nullif(btrim(t.ward_norm),''))),
            '\mNhs\M','NHS','g'),
          '\mIcu\M','ICU','g')) site_ward,
      coalesce(nullif(btrim(tf.band),''),nullif(btrim(t.band),'')) band,
      coalesce(tf.invoice_breakdown_json,'{}'::jsonb) invoice_breakdown_json,
      coalesce(tf.additional_units_json,
        tf.invoice_breakdown_json#>'{additional,units}',
        '{}'::jsonb) additional_units_json,
      coalesce((authority.settings_json#>>'{values,week_ending_weekday}')::integer,0)
        configured_week_ending_weekday,
      coalesce(pc.require_reference_to_invoice,false)
        or coalesce(pc.reference_number_required_to_issue_invoice,false)
        reference_required,
      sd.agency_name,
      case
        when nullif(coalesce(
          sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
          sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),'') is null
          then '{}'::jsonb
        else jsonb_build_object(
          'r2_key',coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,r2_key}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,r2_key}'),
          'sha256',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,sha256}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,sha256}')),
          'size_bytes',case when coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}',
            '')~'^[1-9][0-9]{0,18}$' then coalesce(
              sd.invoice_document_presentation_json#>>'{branding,logo,size_bytes}',
              sd.import_config_json#>>'{invoice_document_presentation,branding,logo,size_bytes}')::bigint end,
          'media_type',lower(coalesce(
            sd.invoice_document_presentation_json#>>'{branding,logo,media_type}',
            sd.import_config_json#>>'{invoice_document_presentation,branding,logo,media_type}')))
      end logo_identity,
      coalesce(sd.timesheet_header_json,'{}'::jsonb) header_wording,
      coalesce(sd.timesheet_footer_json,'{}'::jsonb) footer_wording,
      coalesce(sd.temporary_worker_declaration_json,'{}'::jsonb)
        temporary_worker_declaration,
      coalesce(sd.client_declaration_json,'{}'::jsonb) client_declaration
    from timesheet_targets target
    join public.timesheets t on t.timesheet_id=target.timesheet_id and t.is_current
    left join public.v_timesheets_summary_base vs on vs.timesheet_id=t.timesheet_id
    left join public.contracts ct on ct.id=t.contract_id
    left join public.candidates cand on cand.id=coalesce(vs.candidate_id,ct.candidate_id)
    left join public.clients cl on cl.id=coalesce(vs.client_id,ct.client_id)
    left join public.v_ts_invoice_precheck pc on pc.timesheet_id=t.timesheet_id
    left join lateral (
      select tf0.*
      from public.timesheets_financials tf0
      where tf0.timesheet_id=t.timesheet_id and tf0.is_current
      order by tf0.computed_at_utc desc nulls last,tf0.created_at desc nulls last,
        tf0.updated_at desc nulls last,tf0.id desc
      limit 1
    ) tf on true
    cross join lateral (
      select private._timesheet_settings_authority_frozen_v1(t.timesheet_id)
        as settings_json
    ) authority
    cross join public.settings_defaults sd
    where sd.id=1
  ),
  timesheet_number_fnv(
    invoice_id,timesheet_id,source_text,character_no,fnv_hash
  ) as (
    select b.invoice_id,b.timesheet_id,b.timesheet_id::text,1::integer,
      2166136261::bigint
    from timesheet_base b
    union all
    select h.invoice_id,h.timesheet_id,h.source_text,h.character_no+1,
      mod(
        ((h.fnv_hash # ascii(substr(
          h.source_text,h.character_no,1))::bigint)*16777619::bigint),
        4294967296::bigint)
    from timesheet_number_fnv h
    where h.character_no<=length(h.source_text)
  ),
  timesheet_week_context as materialized (
    select b.*,
      coalesce(b.week_ending_date,
        (b.worked_start_iso at time zone 'Europe/London')::date+
          ((b.configured_week_ending_weekday-
            extract(dow from (b.worked_start_iso at time zone
              'Europe/London')::date)::integer+7)%7)) resolved_week_ending_date
    from timesheet_base b
  ),
  timesheet_schedule_source as materialized (
    select b.invoice_id,b.timesheet_id,s.ordinality::integer source_order,s.value row_json
    from timesheet_week_context b
    cross join lateral jsonb_array_elements(
      case
        when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
          then b.invoice_breakdown_json->'segments'
        when jsonb_typeof(b.actual_schedule_json)='array'
          then b.actual_schedule_json
        else '[]'::jsonb
      end) with ordinality s(value,ordinality)
    union all
    select b.invoice_id,b.timesheet_id,1,jsonb_build_object(
      'date',(b.worked_start_iso at time zone 'Europe/London')::date,
      'start_utc',b.worked_start_iso,'end_utc',b.worked_end_iso,
      'break_start',case when b.break_start_iso is not null
        then to_char(b.break_start_iso at time zone 'Europe/London','HH24:MI') end,
      'break_end',case when b.break_end_iso is not null
        then to_char(b.break_end_iso at time zone 'Europe/London','HH24:MI') end,
      'break_minutes',b.break_minutes,'ref_num',b.reference_number)
    from timesheet_week_context b
    where b.sheet_scope='DAILY'
      and not exists(
        select 1 from jsonb_array_elements(
          case
            when upper(coalesce(b.invoice_breakdown_json->>'mode',''))='SEGMENTS'
              and jsonb_typeof(b.invoice_breakdown_json->'segments')='array'
              then b.invoice_breakdown_json->'segments'
            when jsonb_typeof(b.actual_schedule_json)='array'
              then b.actual_schedule_json
            else '[]'::jsonb
          end) existing)
  ),
  timesheet_schedule_normalised as materialized (
    select s.*,b.resolved_week_ending_date,b.reference_required,
      coalesce(nullif(btrim(s.row_json->>'segment_id'),''),
        case when nullif(btrim(s.row_json->>'start_utc'),'') is not null
          and nullif(btrim(s.row_json->>'end_utc'),'') is not null
          then 'SE:'||(s.row_json->>'start_utc')||'|'||
            (s.row_json->>'end_utc') end,
        'ts:'||s.timesheet_id::text||':'||(s.source_order-1)::text) segment_id,
      coalesce(nullif(btrim(s.row_json->>'date'),''),
        nullif(btrim(s.row_json->>'day'),''),
        case when pg_input_is_valid(nullif(coalesce(
            s.row_json->>'worked_start',s.row_json->>'start_utc'),''),
            'timestamptz')
          then (coalesce(s.row_json->>'worked_start',
            s.row_json->>'start_utc')::timestamptz at time zone
              'Europe/London')::date::text end,
        case when b.sheet_scope='DAILY'
          then (b.worked_start_iso at time zone 'Europe/London')::date::text end)
        work_date,
      coalesce(nullif(btrim(s.row_json->>'worked_start'),''),
        nullif(btrim(s.row_json->>'start_utc'),''),
        nullif(btrim(s.row_json->>'start'),'')) worked_start,
      coalesce(nullif(btrim(s.row_json->>'worked_end'),''),
        nullif(btrim(s.row_json->>'end_utc'),''),
        nullif(btrim(s.row_json->>'end'),'')) worked_end,
      case
        when nullif(btrim(s.row_json->>'break_start'),'') is not null
          and nullif(btrim(s.row_json->>'break_end'),'') is not null
          then 'EXPLICIT_INTERVAL'
        when coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
          and coalesce(s.row_json->>'break_minutes',
            s.row_json->>'break_mins')::integer>0
          then 'MINUTES_ONLY'
        else 'NONE' end break_display_mode,
      case when coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins','')~'^[0-9]{1,5}$'
        then coalesce(s.row_json->>'break_minutes',
          s.row_json->>'break_mins')::integer else 0 end break_minutes,
      coalesce(nullif(btrim(s.row_json->>'ref_num'),''),
        nullif(btrim(s.row_json->>'reference'),'')) source_reference
    from timesheet_schedule_source s
    join timesheet_week_context b
      on b.invoice_id is not distinct from s.invoice_id
     and b.timesheet_id=s.timesheet_id
  ),
  timesheet_schedule_rows as materialized (
    select s.invoice_id,s.timesheet_id,s.source_order,s.segment_id,s.work_date,
      jsonb_build_object(
        'row_key',s.timesheet_id::text||'|SEGMENT|'||s.segment_id||'|'||
          coalesce(s.work_date,''),
        'display_order',row_number() over(
          partition by s.invoice_id,s.timesheet_id,s.work_date
          order by
            case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              then s.worked_start::timestamptz end nulls last,
            s.worked_start,s.segment_id,s.source_order),
        'segment_id',s.segment_id,
        'date',s.work_date,
        'worked_start_utc',case when pg_input_is_valid(
          nullif(s.worked_start,''),'timestamptz')
          then s.worked_start::timestamptz end,
        'worked_end_utc',case when pg_input_is_valid(
          nullif(s.worked_end,''),'timestamptz')
          then s.worked_end::timestamptz end,
        'display_start_local',case
          when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
            then to_char(s.worked_start::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_start~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_start,5)
          end,
        'display_end_local',case
          when pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then to_char(s.worked_end::timestamptz at time zone
              'Europe/London','HH24:MI')
          when s.worked_end~'^[0-2][0-9]:[0-5][0-9]' then left(s.worked_end,5)
          end,
        'break_start_local',nullif(btrim(s.row_json->>'break_start'),''),
        'break_end_local',nullif(btrim(s.row_json->>'break_end'),''),
        'break_minutes',s.break_minutes,
        'break_display_mode',s.break_display_mode,
        'bucket_hours',jsonb_build_object(
          'DAY',coalesce(s.row_json->'hours_day','0'::jsonb),
          'NIGHT',coalesce(s.row_json->'hours_night','0'::jsonb),
          'SATURDAY',coalesce(s.row_json->'hours_sat','0'::jsonb),
          'SUNDAY',coalesce(s.row_json->'hours_sun','0'::jsonb),
          'BANK_HOLIDAY',coalesce(s.row_json->'hours_bh','0'::jsonb)),
        'paid_minutes',coalesce(
          case when (select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
            from(values(s.row_json->>'hours_day'),
              (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
              (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v))>0
            then round(60*(select sum(case when coalesce(v,'')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
              then v::numeric else 0 end)
              from(values(s.row_json->>'hours_day'),
                (s.row_json->>'hours_night'),(s.row_json->>'hours_sat'),
                (s.row_json->>'hours_sun'),(s.row_json->>'hours_bh')) h(v)))::integer
          end,
          case when pg_input_is_valid(nullif(s.worked_start,''),'timestamptz')
              and pg_input_is_valid(nullif(s.worked_end,''),'timestamptz')
            then greatest(0,round(extract(epoch from(
              s.worked_end::timestamptz-s.worked_start::timestamptz))/60)
                -s.break_minutes)::integer end,
          case when coalesce(s.row_json->>'hours',
              s.row_json->>'units','')~
                '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
            then round(coalesce(s.row_json->>'hours',
              s.row_json->>'units')::numeric*60)::integer end),
        'band',b.band,
        'booking_reference',coalesce(
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          s.source_reference,
          (select rs.current_reference from reference_scope rs
            where rs.invoice_id=s.invoice_id
              and rs.timesheet_id=s.timesheet_id
              and rs.day_ymd=s.work_date
              and nullif(rs.current_reference,'') is not null
            order by rs.row_key limit 1),
          case when jsonb_typeof(b.day_references_json)='object'
            then coalesce(
              b.day_references_json#>>array[s.work_date,'reference'],
              b.day_references_json#>>array[s.work_date,'ref_num'],
              b.day_references_json->>s.work_date) end,
          nullif(b.reference_number,'')),
        'reference_required',b.reference_required,
        'reference_source',case
          when exists(select 1 from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id
              and nullif(rs.current_reference,'') is not null) then 'SEGMENT'
          when nullif(s.source_reference,'') is not null then 'SEGMENT_SOURCE'
          when exists(select 1 from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.day_ymd=s.work_date
              and nullif(rs.current_reference,'') is not null) then 'DAY'
          when nullif(b.reference_number,'') is not null then 'TIMESHEET'
          else 'NONE' end,
        'reference_row_key',coalesce(
          (select rs.row_key from reference_scope rs
            where rs.invoice_id=s.invoice_id and rs.timesheet_id=s.timesheet_id
              and rs.segment_id=s.segment_id order by rs.row_key limit 1),
          s.timesheet_id::text||'|SEGMENT|'||s.segment_id||'|'||
            coalesce(s.work_date,'')))
        shift_model
    from timesheet_schedule_normalised s
    join timesheet_week_context b
      on b.invoice_id is not distinct from s.invoice_id
     and b.timesheet_id=s.timesheet_id
  ),
  timesheet_current_additional_rows as materialized (
    select b.invoice_id,b.timesheet_id,d.code,d.unit_date,d.quantity
    from timesheet_week_context b
    cross join lateral (
      select upper(day_unit.key) code,day_value.key unit_date,
        (day_value.value#>>'{}')::numeric quantity
      from jsonb_each(case
        when jsonb_typeof(b.additional_units_per_day)='object'
          then b.additional_units_per_day else '{}'::jsonb end) day_unit(key,value)
      cross join lateral jsonb_each(case
        when jsonb_typeof(day_unit.value)='object'
          then day_unit.value else '{}'::jsonb end) day_value(key,value)
      where coalesce(day_value.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
        and (day_value.value#>>'{}')::numeric<>0
      union all
      select upper(week_unit.key),null::text,
        (week_unit.value#>>'{}')::numeric
      from jsonb_each(case
        when jsonb_typeof(b.additional_units_week)='object'
          then b.additional_units_week else '{}'::jsonb end) week_unit(key,value)
      where coalesce(week_unit.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
        and (week_unit.value#>>'{}')::numeric<>0
        and not exists(
          select 1
          from jsonb_each(case
            when jsonb_typeof(b.additional_units_per_day)='object'
              then b.additional_units_per_day else '{}'::jsonb end) per_day(code,value)
          cross join lateral jsonb_each(case
            when jsonb_typeof(per_day.value)='object'
              then per_day.value else '{}'::jsonb end) per_value(day,value)
          where upper(per_day.code)=upper(week_unit.key)
            and coalesce(per_value.value#>>'{}','')~
              '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
            and (per_value.value#>>'{}')::numeric<>0)
    ) d
  ),
  timesheet_additional_rows as materialized (
    select b.invoice_id,b.timesheet_id,a.key code,
      coalesce(nullif(a.value->>'bucket_name',''),a.key) rate_type,
      nullif(d.key,'') unit_date,
      case
        when d.key is not null and coalesce(d.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(d.value#>>'{}')::numeric
        when d.key is null and coalesce(a.value->>'unit_count','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(a.value->>'unit_count')::numeric
      end quantity,
      coalesce(nullif(a.value->>'unit_name',''),'unit') unit_name,
      case when d.key is null then 'WEEKLY' else 'PER_DAY' end frequency,
      case when coalesce(a.value->>'configured_display_order',
          a.value->>'display_order','')~'^[0-9]{1,9}$'
        then coalesce(a.value->>'configured_display_order',
          a.value->>'display_order')::integer else 2147483647 end configured_order
    from timesheet_week_context b
    cross join lateral jsonb_each(case
      when jsonb_typeof(b.additional_units_json)='object'
        then b.additional_units_json else '{}'::jsonb end) a(key,value)
    left join lateral jsonb_each(case
      when jsonb_typeof(a.value->'days')='object' and a.value->'days'<>'{}'::jsonb
        then a.value->'days' else '{}'::jsonb end) d(key,value) on true
    where jsonb_typeof(a.value)='object'
      and case
        when d.key is not null and coalesce(d.value#>>'{}','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(d.value#>>'{}')::numeric<>0
        when d.key is null and coalesce(a.value->>'unit_count','')~
          '^[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)$'
          then(a.value->>'unit_count')::numeric<>0
        else false end
  ),
  timesheet_additional_staleness as materialized (
    select b.invoice_id,b.timesheet_id,
      exists(
        (select upper(c.code),c.unit_date,trim_scale(c.quantity)
         from timesheet_current_additional_rows c
         where c.invoice_id is not distinct from b.invoice_id
           and c.timesheet_id=b.timesheet_id
         except
         select upper(a.code),a.unit_date,trim_scale(a.quantity)
         from timesheet_additional_rows a
         where a.invoice_id is not distinct from b.invoice_id
           and a.timesheet_id=b.timesheet_id)
        union all
        (select upper(a.code),a.unit_date,trim_scale(a.quantity)
         from timesheet_additional_rows a
         where a.invoice_id is not distinct from b.invoice_id
           and a.timesheet_id=b.timesheet_id
         except
         select upper(c.code),c.unit_date,trim_scale(c.quantity)
         from timesheet_current_additional_rows c
         where c.invoice_id is not distinct from b.invoice_id
           and c.timesheet_id=b.timesheet_id)
      ) snapshot_stale
    from timesheet_week_context b
  ),
  timesheet_v2_models as materialized (
    select b.invoice_id,b.timesheet_id,
      jsonb_build_object(
        'schema_version','TIMESHEET_RENDER_MODEL_V2',
        'template_version','timesheet-professional-v2',
        'layout_contract_version','TIMESHEET_ONE_PAGE_LANDSCAPE_V2',
        'timesheet_id',b.timesheet_id,
        'document_revision',b.document_revision,
        'timesheet_number',coalesce((
          select lpad((h.fnv_hash%100000000)::text,8,'0')
          from timesheet_number_fnv h
          where h.invoice_id is not distinct from b.invoice_id
            and h.timesheet_id=b.timesheet_id
            and h.character_no=length(h.source_text)+1
          limit 1),'00000000'),
        'sheet_scope',b.sheet_scope,
        'form_variant',case
          when b.submission_mode='MANUAL' and upper(coalesce(b.qr_status,''))='PENDING'
            then 'QR_UNSIGNED'
          when b.submission_mode='ELECTRONIC'
            and b.authorised_at_server is not null
            and nullif(b.r2_nurse_key,'') is not null
            and nullif(b.r2_auth_key,'') is not null
            then 'ELECTRONIC_SIGNED'
          else 'ELECTRONIC_UNSIGNED' end,
        'submission_mode',b.submission_mode,
        'locale','en-GB','time_zone','Europe/London',
        'week_period',jsonb_build_object(
