  if private._expense_approval_policy_v1(v_client,v_contract,current_date,'CONTRACT_EXPENSE')->>'paper_submission_enabled' is distinct from 'true'
     or private._expense_approval_policy_v1(v_client,v_contract,current_date,'CONTRACT_HOURS')->>'paper_submission_enabled' is distinct from 'false'
     or private._expense_approval_policy_v1(v_client,v_contract,current_date,'CONTRACT_COMBINED')->>'paper_submission_enabled' is distinct from 'false' then
    raise exception 'IMPORT_PURPOSE_PERMISSION_INCORRECT';
