  if private._expense_approval_policy_v1(v_client,v_contract,current_date,'CONTRACT_EXPENSE')->>'paper_submission_enabled' is distinct from 'false' then raise exception 'CLIENT_DENY_IGNORED'; end if;
  update public.contracts set candidate_paper_submission_enabled_override=true where id=v_contract;
  if private._expense_approval_policy_v1(v_client,v_contract,current_date,'CONTRACT_EXPENSE')->>'paper_submission_enabled' is distinct from 'true' then raise exception 'CONTRACT_ALLOW_IGNORED'; end if;
  update public.contracts set candidate_paper_submission_enabled_override=null where id=v_contract;
  update public.client_settings set candidate_paper_submission_enabled=true where client_id=v_client;

  -- Deliberately make the worked anchor an already-used, signed, approved row.
  -- The pre-fix PAPER adapter rejected this exact authority state.
  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
