do $released_review$
declare
  request jsonb:=jsonb_build_object('actor_user_id','d1000000-0000-4000-8000-000000000001',
    'source_group_id','d5000000-0000-4000-8000-000000000003',
    'client_id','d2000000-0000-4000-8000-000000000004','tab','queries','section','checks');
  value jsonb; single jsonb; final_before jsonb; scopes_before jsonb;
begin
  final_before:=public.weekly_source_combined_finalise_workspace_v1(request-'tab'-'section');
  scopes_before:=public.weekly_source_workspace_scopes_v1(request-'tab'-'section');
  insert into public.weekly_source_row_resolutions
  select (jsonb_populate_record(null::public.weekly_source_row_resolutions,to_jsonb(r)||jsonb_build_object(
    'id','de000000-0000-4000-8000-000000000002','generation',2,
    'mapping_state','NO_ELIGIBLE_CONTRACT','blocker_code','NO_ELIGIBLE_CONTRACT',
    'contract_id',null,'qualifying_contract_count',0,'contract_selection_method',null,
    'work_event_id',null,'work_event_match_kind',null,'work_event_match_fingerprint',null))).*
  from public.weekly_source_row_resolutions r where id='de000000-0000-4000-8000-000000000001';
  value:=public.weekly_source_combined_review_workspace_v1(request);
  perform pg_temp.assert_true(value#>>'{rows,0,actions,0,label}'='Choose contract',
    'released outside-group missing contract disappeared from Office checks');
  perform pg_temp.assert_true(value->>'total_count'='1',
    'released outside-group contract check duplicated');
  perform pg_temp.assert_true((value#>>'{scope_options,0,review_only}')::boolean,
    'released review scope was represented as a report obligation');
  single:=public.weekly_source_combined_review_workspace_v1(request||jsonb_build_object('section','questions'));
  perform pg_temp.assert_true(single->>'total_count'='0',
    'unresolved contract incorrectly created an Hours question');

  perform pg_temp.assert_true(public.weekly_source_workspace_scopes_v1(request-'tab'-'section')=scopes_before,
    'review reads changed final-report obligations');
  perform pg_temp.assert_true(public.weekly_source_combined_finalise_workspace_v1(request-'tab'-'section')=final_before,
    'released review scope changed finalisation availability');
  update public.client_settings set is_nhsp=false
  where id='d2100000-0000-4000-8000-000000000004';
  value:=public.weekly_source_combined_review_workspace_v1(request);
  perform pg_temp.assert_true(value->>'total_count'='0',
    'non-NHSP outside-group client acquired released review authority');
  update public.client_settings set is_nhsp=true
  where id='d2100000-0000-4000-8000-000000000004';

  -- Once Office separately configures a valid source policy and contract,
  -- the existing hours and charge owners must surface the next checks. The
  -- review function itself must NOT add membership or manufacture a policy.
  insert into public.weekly_source_group_clients(source_group_id,client_id,valid_from,created_by_user_id)
  values('d5000000-0000-4000-8000-000000000003','d2000000-0000-4000-8000-000000000004',
    '2026-09-07','d1000000-0000-4000-8000-000000000001');
  insert into public.weekly_source_row_resolutions
  select (jsonb_populate_record(null::public.weekly_source_row_resolutions,to_jsonb(r)||jsonb_build_object(
    'id','de000000-0000-4000-8000-000000000003','generation',3))).*
  from public.weekly_source_row_resolutions r where id='de000000-0000-4000-8000-000000000001';
  update public.timesheets set r2_nurse_key=null,img_sha256_nurse=null
  where timesheet_id='da000000-0000-4000-8000-000000000003';
  value:=public.weekly_source_combined_review_workspace_v1(request||jsonb_build_object('section','questions'));
  perform pg_temp.assert_true(value->>'total_count'='1'
    and value#>>'{rows,0,children,0,issue}'='Timesheet missing',
    'eligible resolved contract did not expose missing candidate hours');

  insert into public.weekly_source_charge_checks(
    id,upload_row_id,row_resolution_id,generation,row_sign_kind,
    source_commission_pence,source_total_cost_pence,source_shift_charge_pence,
    calculated_segment_charge_pence,source_charge_difference_pence,
    comparison_profile_version,comparison_result,comparison_reason_code,phase_severity,
    charge_calculation_fingerprint
  ) values ('df000000-0000-4000-8000-000000000002','dd000000-0000-4000-8000-000000000001',
    'de000000-0000-4000-8000-000000000003',3,'POSITIVE',1000,9000,10000,12000,-2000,
    'NHSP_TWO_COMPONENT_PENCE_V1','MISMATCH','MISMATCH','PROVISIONAL_WARNING',decode(repeat('9d',32),'hex'));
  value:=public.weekly_source_combined_review_workspace_v1(request);
  perform pg_temp.assert_true(value->>'total_count'='1'
    and value#>>'{rows,0,actions,0,label}'='Open charge details',
    'resolved charge mismatch disappeared from Office checks');
  single:=public.weekly_source_combined_review_workspace_v1(request||jsonb_build_object('section','questions'));
  perform pg_temp.assert_true(single->>'total_count'='1',
    'charge warning hid the independent missing-timesheet question');

  update public.timesheets set r2_nurse_key='verify/taylor.png',img_sha256_nurse=repeat('c',64)
  where timesheet_id='da000000-0000-4000-8000-000000000003';
  value:=public.weekly_source_combined_review_workspace_v1(request||jsonb_build_object('section','questions'));
  perform pg_temp.assert_true(value->>'total_count'='0',
    'signed candidate hours created a false missing-timesheet question');
  value:=public.weekly_source_combined_review_workspace_v1(request);
  perform pg_temp.assert_true(value->>'total_count'='1',
    'signed matching hours incorrectly cleared a charge warning');

  perform pg_temp.assert_true(not has_function_privilege('authenticated',
    'public.weekly_source_combined_review_workspace_v1(jsonb)','EXECUTE'),
    'released review is exposed as a browser RPC');
end $released_review$;

-- Rollback-contained full Master roster / callable DNA / effect replay proof.
-- Includes stale, ambiguous and caller-supplied subject negative cases.




do $verification$
declare
  v_candidate_id uuid:=gen_random_uuid();
  v_generation_id uuid:=gen_random_uuid();
  v_batch_id uuid:=gen_random_uuid();
  v_link_group_id uuid:=gen_random_uuid();
  v_today date:='2026-08-30'::date;
  v_shift_start timestamptz:='2026-08-30 07:30:00+01'::timestamptz;
  v_shift_end timestamptz:='2026-08-30 20:00:00+01'::timestamptz;
  v_source_hash text:=repeat('a',64);
  v_token text;
  v_result jsonb;
  v_definition text;
  v_day integer;
  v_subject jsonb;
  v_context jsonb;
  v_input jsonb;
  v_claim jsonb;
  v_roster jsonb;
  v_bad jsonb;
  v_case integer;
begin
  select pg_get_functiondef(
    'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)'::regprocedure
  ) into v_definition;
  if position('select d.* into v_day' in lower(v_definition))=0
     or lower(v_definition) ~ 'select[[:space:]]+d[[:space:]]+into[[:space:]]+v_day'
     or v_definition~*'pg_catalog\.(coalesce|nullif|least|greatest)[[:space:]]*\('
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: row assignment is unsafe';
  end if;
  if not exists(
    select 1 from pg_proc p
    where p.oid='private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)'::regprocedure
      and p.prosecdef and p.provolatile='s'
      and p.proconfig @> array['search_path=""']::text[]
  ) then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: function security changed';
  end if;
  if has_function_privilege(
       'service_role',
       'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)',
       'EXECUTE'
     )
     or has_function_privilege(
       'anon',
       'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)',
       'EXECUTE'
     )
     or has_function_privilege(
       'authenticated',
       'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)',
       'EXECUTE'
     )
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: private ACL opened';
  end if;

  update public.settings_defaults
  set candidate_app_feature_flags_json=
    candidate_app_feature_flags_json||'{"candidate_daily_enabled":true}'::jsonb
  where id=1;

  insert into public.candidates(id,email,display_name,phone,active)
  values(
    v_candidate_id,
    'emergency-window-'||v_candidate_id::text||'@example.invalid',
    'Emergency window proof','07000000000',true
  );
  insert into private.candidate_daily_authority_scopes(
    environment,candidate_id,authority_mode,canonical_version,transition_in_progress
  ) values('TEST',v_candidate_id,'SUPABASE_PRIMARY',1,false);
  insert into private.candidate_daily_entitlements(
    environment,candidate_id,enabled,reason,evidence_sha256
  ) values('TEST',v_candidate_id,true,'Emergency window proof',repeat('1',64));
  insert into private.candidate_daily_source_links(
    environment,candidate_id,source_system,canonicalization_version,
    link_group_id,identifier_hmac,hmac_key_version,state,evidence_sha256
  ) values(
    'TEST',v_candidate_id,'GOOGLE_CREDENTIALLY_PUBLIC_ID','SOURCE_IDENTITY_V1',
    v_link_group_id,repeat('2',64),1,'PRIMARY',repeat('3',64)
  );
  insert into private.candidate_daily_batch_receipts(
    batch_receipt_id,environment,actor_class,operation_class,idempotency_key,
    request_hash,item_keys_json,item_count,state,terminal_http_status,
    terminal_response_body,terminal_response_sha256,correlation_id,completed_at_utc
  ) values(
    v_batch_id,'TEST','SIGNED_SYSTEM','ROTA_GENERATION_PUBLISH',
    'emergency-window-'||v_batch_id::text,repeat('4',64),
    jsonb_build_array(v_candidate_id::text),1,'COMPLETED',200,'{}'::jsonb,
    repeat('5',64),'01M18D00000000000000000000',clock_timestamp()
  );
  insert into public.candidate_daily_rota_generations(
    generation_id,environment,candidate_id,generation_version,window_start,
    window_end,state,expected_day_count,actual_day_count,source_system,
    source_event_id,source_revision,source_event_time,item_key,source_hash,
    generation_row_hash,batch_receipt_id,correlation_id,activated_at_utc,
    published_at_utc
  ) values(
    v_generation_id,'TEST',v_candidate_id,1,v_today,v_today+13,'ACTIVE',14,14,
    'MASTER_ROTA','emergency-window-source-'||v_generation_id::text,
    'emergency-window-v1',clock_timestamp()-interval '1 day',
    'emergency-window-item-'||v_generation_id::text,repeat('6',64),repeat('7',64),
    v_batch_id,'01M18D00000000000000000000',clock_timestamp()-interval '1 day',
    clock_timestamp()-interval '1 day'
  );
  for v_day in 0..13 loop
    insert into public.candidate_daily_rota_days(
      generation_id,environment,candidate_id,rota_date,booked,system_blocked,
      booking_id,shift_starts_at,shift_ends_at,shift_info,hospital,ward,
      job_title,booking_ref,shift_type,timesheet_authorised,timesheet_eligible,
      source_row_hash
    ) values(
      v_generation_id,'TEST',v_candidate_id,v_today+v_day,v_day=0,false,
      case when v_day=0 then 'emergency-window-booking' else null end,
      case when v_day=0 then v_shift_start else null end,
      case when v_day=0 then v_shift_end else null end,
      case when v_day=0 then 'Long Day 0730-2000hrs' else null end,
      case when v_day=0 then 'North General Hospital' else null end,
      case when v_day=0 then 'Ward 1' else null end,
      case when v_day=0 then 'Registered Nurse' else null end,
      case when v_day=0 then 'TEST-BOOKING' else null end,
      case when v_day=0 then 'Long Day' else null end,
      false,false,
      case when v_day=0 then v_source_hash
        else repeat(substr(md5(v_candidate_id::text||v_day::text),1,1),64) end
    );
  end loop;
  update private.candidate_daily_authority_scopes
  set active_generation_id=v_generation_id
  where environment='TEST' and candidate_id=v_candidate_id;

  v_token:=private._candidate_daily_emergency_token_v1(
    'TEST',v_candidate_id,v_generation_id,v_today,v_source_hash
  );
  -- Complete Master contacts are a separate signed-source projection, not
  -- dependent on the colleague being enrolled in MyTMS.
  v_result:=public.candidate_daily_specialist_read_v1(
    jsonb_build_object('policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate_id),
    'EMERGENCY_ROSTER_PUBLISH',jsonb_build_object('emergency_shift_token',v_token,'roster',jsonb_build_object(
      'emergency_shift_token',v_token,'captured_at',clock_timestamp(),'groups',jsonb_build_object(
        'current',jsonb_build_array(jsonb_build_object('display_name','Unenrolled colleague','role','RMN','callable_mobile','447111111111')),
        'previous','[]'::jsonb,'next','[]'::jsonb))),v_shift_start,'01M18D00000000000000000000');
  if v_result->>'accepted' is distinct from 'true' then raise exception 'Emergency roster publication failed'; end if;
  v_result:=private._candidate_daily_specialist_shift_v1(
    jsonb_build_object(
      'policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate_id
    ),v_token,v_shift_start
  );
  if v_result->>'date' is distinct from v_today::text
     or (v_result->>'starts_at')::timestamptz is distinct from v_shift_start
     or (v_result->>'ends_at')::timestamptz is distinct from v_shift_end
     or not (v_result->'allowed_issues' ? 'RUNNING_LATE')
     or not (v_result->'allowed_issues' ? 'LEAVE_EARLY')
     or not (v_result->'allowed_issues' ? 'DNA')
     or v_result#>>'{dna_subjects,0,callable_mobile}' is distinct from '447111111111'
     or coalesce(v_result#>>'{dna_subjects,0,subject_token}','') !~ '^[a-f0-9]{64}$'
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: private first use is wrong: %',
      v_result;
  end if;

  v_result:=public.candidate_daily_specialist_read_v1(
    jsonb_build_object(
      'policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate_id
    ),'EMERGENCY_WINDOW','{}'::jsonb,v_shift_start,
    '01M18D00000000000000000000'
  );
  if v_result->>'eligible' is distinct from 'true'
     or jsonb_array_length(v_result->'shifts')<>1
     or v_result#>>'{shifts,0,date}' is distinct from v_today::text
     or v_result#>>'{shifts,0,display_label}' not like '%North General Hospital%'
     or (v_result#>'{shifts,0}') ? '_agency_payload'
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: public first use is wrong: %',
      v_result;
  end if;
  -- Service-only projection ACL and no enrolment requirement for DNA subject.
  if has_table_privilege('service_role','private.candidate_daily_emergency_roster_snapshots','SELECT,INSERT,UPDATE,DELETE')
    or has_table_privilege('anon','private.candidate_daily_emergency_roster_snapshots','SELECT,INSERT,UPDATE,DELETE')
    or has_table_privilege('authenticated','private.candidate_daily_emergency_roster_snapshots','SELECT,INSERT,UPDATE,DELETE') then
    raise exception 'Emergency roster direct table ACL opened';
  end if;
  v_subject:=v_result#>'{shifts,0,dna_subjects,0}';
  v_context:=jsonb_build_object('policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate_id);
  v_input:=jsonb_build_object('type','DNA','emergency_shift_token',v_token,
    'subject_token',v_subject->>'subject_token','tried_calling',false);
  begin
    perform public.candidate_daily_effect_claim_candidate_v1(v_context,'DNA',v_input,
      'emergency-roster-proof','emergency-dna-'||v_candidate_id::text,120,v_shift_start,'01M18D00000000000000000000');
    raise exception 'DNA accepted without tried calling';
  exception when sqlstate '22023' then
    if sqlerrm<>'SEMANTIC_REJECTION' then raise; end if;
  end;
  v_input:=v_input||'{"tried_calling":true}'::jsonb;
  v_claim:=public.candidate_daily_effect_claim_candidate_v1(v_context,'DNA',v_input,
    'emergency-roster-proof','emergency-dna-'||v_candidate_id::text,120,v_shift_start,'01M18D00000000000000000000');
  if v_claim->>'state' is distinct from 'CLAIMED'
    or v_claim#>>'{effect_payload,dna_subject,callable_mobile}' is distinct from '447111111111'
    or v_claim#>>'{effect_payload,dna_subject,display_name}' is distinct from 'Unenrolled colleague' then
    raise exception 'DNA exact callable identity not preserved';
  end if;
  -- A lost HTTP response must recover its exact key while the original executor
  -- is still running or its lease has expired, without another claim or send.
  v_result:=public.candidate_daily_specialist_read_v1(v_context,'EFFECT_REPLAY',
    jsonb_build_object('operation','DNA','input',v_input,'idempotency_key','emergency-dna-'||v_candidate_id::text),
    v_shift_start+interval '1 second','01M18D00000000000000000000');
  if v_result->>'state' is distinct from 'IN_PROGRESS'
    or v_result#>>'{safe_result,effect_key}' is distinct from v_claim->>'effect_key'
    or v_result#>>'{safe_result,status}' is distinct from 'IN_PROGRESS' then
    raise exception 'In-progress replay did not recover the original safe status';
  end if;
  v_result:=public.candidate_daily_specialist_read_v1(v_context,'EFFECT_REPLAY',
    jsonb_build_object('operation','DNA','input',v_input,'idempotency_key','emergency-dna-'||v_candidate_id::text),
    v_shift_start+interval '121 seconds','01M18D00000000000000000000');
  if v_result#>>'{safe_result,effect_key}' is distinct from v_claim->>'effect_key'
    or (select attempt_count from private.candidate_daily_external_effect_receipts
      where effect_receipt_id=(v_claim->>'effect_receipt_id')::uuid)<>1 then
    raise exception 'Expired pending replay replaced/reclaimed the original attempt';
  end if;
  -- No external executor is invoked. Complete the test-only receipt UNKNOWN.
  perform public.candidate_daily_effect_complete_candidate_v1(v_context,
    (v_claim->>'effect_receipt_id')::uuid,v_claim->>'lease_token','UNKNOWN',null,
    'Fixture only; no messages sent',v_shift_start+interval '1 second','01M18D00000000000000000000');
  delete from private.candidate_daily_emergency_roster_snapshots where environment='TEST' and candidate_id=v_candidate_id;
  v_result:=public.candidate_daily_specialist_read_v1(v_context,'EFFECT_REPLAY',
    jsonb_build_object('operation','DNA','input',v_input,'idempotency_key','emergency-dna-'||v_candidate_id::text),
    v_shift_end+interval '1 day','01M18D00000000000000000000');
  if v_result->>'state' is distinct from 'UNKNOWN' then raise exception 'Uncertain replay requires source/resend'; end if;
  begin
    perform public.candidate_daily_specialist_read_v1(v_context,'EFFECT_REPLAY',
      jsonb_build_object('operation','DNA','input',v_input||'{"reason_text":"different"}'::jsonb,
        'idempotency_key','emergency-dna-'||v_candidate_id::text),v_shift_start,'01M18D00000000000000000000');
    raise exception 'Changed payload accepted under existing request key';
  exception when sqlstate '23505' then if sqlerrm<>'SOURCE_EVENT_CONFLICT' then raise; end if; end;
  begin
    perform public.candidate_daily_specialist_read_v1(v_context,'EMERGENCY_WINDOW','{}',v_shift_start,'01M18D00000000000000000000');
    raise exception 'Missing roster treated as zero colleagues';
  exception when sqlstate '55000' then if sqlerrm<>'DEPENDENCY_UNAVAILABLE' then raise; end if; end;
  v_roster:=jsonb_build_object('emergency_shift_token',v_token,'captured_at',clock_timestamp(),'groups',
    jsonb_build_object('current',jsonb_build_array(jsonb_build_object(
      'display_name','Unenrolled colleague','role','RMN','callable_mobile','447111111111')),'previous','[]'::jsonb,'next','[]'::jsonb));
  for v_case in 1..8 loop
    v_bad:=v_roster;
    if v_case=1 then v_bad:=jsonb_set(v_bad,'{groups,current,0,callable_mobile}','"07111111111"'); end if;
    if v_case=2 then v_bad:=jsonb_set(v_bad,'{groups,current,0,callable_mobile}','"447000000000"'); end if;
    if v_case=3 then v_bad:=jsonb_set(v_bad,'{groups,current}',(v_roster#>'{groups,current}')||(v_roster#>'{groups,current}')); end if;
    if v_case=4 then v_bad:=v_bad-'groups'; end if;
    if v_case=5 then v_bad:=v_bad||jsonb_build_object('captured_at',clock_timestamp()-interval '2 minutes'); end if;
    if v_case=6 then v_bad:=v_bad||jsonb_build_object('captured_at',clock_timestamp()+interval '1 minute'); end if;
    if v_case=7 then v_bad:=v_bad||jsonb_build_object('emergency_shift_token',repeat('f',64)); end if;
    if v_case=8 then v_bad:=jsonb_set(v_bad,'{groups,current,0,subject_token}',to_jsonb(repeat('f',64)),true); end if;
    begin
      perform public.candidate_daily_specialist_read_v1(v_context,'EMERGENCY_ROSTER_PUBLISH',
        jsonb_build_object('emergency_shift_token',v_token,'roster',v_bad),v_shift_start,'01M18D00000000000000000000');
      raise exception 'Invalid roster case % accepted',v_case;
    exception when sqlstate '22023' or sqlstate '55000' then
      if sqlerrm not in ('VALIDATION_FAILED','DEPENDENCY_UNAVAILABLE') then raise; end if;
    end;
  end loop;
  perform public.candidate_daily_specialist_read_v1(v_context,'EMERGENCY_ROSTER_PUBLISH',
    jsonb_build_object('emergency_shift_token',v_token,'roster',v_roster),v_shift_start,'01M18D00000000000000000000');
  update private.candidate_daily_emergency_roster_snapshots set
    observed_at_utc=p.instant-interval '6 minutes',expires_at_utc=p.instant-interval '1 minute'
    from (select clock_timestamp() as instant) p where environment='TEST' and candidate_id=v_candidate_id;
  begin
    perform public.candidate_daily_specialist_read_v1(v_context,'EMERGENCY_WINDOW','{}',v_shift_start,'01M18D00000000000000000000');
    raise exception 'Expired roster accepted';
  exception when sqlstate '55000' then if sqlerrm<>'DEPENDENCY_UNAVAILABLE' then raise; end if; end;
  update public.candidate_daily_rota_days set source_row_hash=repeat('b',64)
    where generation_id=v_generation_id and rota_date=v_today;
  begin
    perform public.candidate_daily_specialist_read_v1(v_context,'EMERGENCY_ROSTER_PUBLISH',
      jsonb_build_object('emergency_shift_token',v_token,'roster',v_roster),v_shift_start,'01M18D00000000000000000000');
    raise exception 'Changed booking accepted the old shift token';
  exception when sqlstate '02000' then if sqlerrm<>'NOT_FOUND' then raise; end if; end;

end;
$verification$;

-- Portable NEW/UPGRADE check, read-only except transaction-local request role.
-- This proves relation/routine isolation, not native APP/publication/J13.
do $verify$
declare
  v_table oid:=to_regclass('private.weekly_source_accepted_publication_actions_v1');
  v_routine record;
  v_signature text;
  v_result jsonb;
begin
  if v_table is null or exists(select 1 from pg_class c where c.oid=v_table
      and c.relowner<>(select oid from pg_roles where rolname=current_user))
     or exists(select 1 from (values('anon'),('authenticated'),('service_role')) r(name)
      where has_table_privilege(r.name,v_table,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) then
    raise exception 'WEEKLY_SOURCE_ACCEPTED_ACTION_TABLE_ACL_INVALID'; end if;
  foreach v_signature in array array[
    'private.weekly_source_accepted_publication_context_v1(jsonb)',
    'private.weekly_source_accepted_publication_action_record_v1(jsonb,jsonb,jsonb)',
    'private.weekly_source_accepted_publication_action_verify_v1(uuid,uuid,bigint,bytea,uuid)'] loop
    select * into v_routine from pg_proc where oid=to_regprocedure(v_signature);
    if not found or not v_routine.prosecdef
       or v_routine.proowner<>(select oid from pg_roles where rolname=current_user)
       or not ('search_path=public, private, pg_catalog, pg_temp'=any(v_routine.proconfig))
       or has_function_privilege('anon',v_routine.oid,'EXECUTE')
       or has_function_privilege('authenticated',v_routine.oid,'EXECUTE')
       or has_function_privilege('service_role',v_routine.oid,'EXECUTE') then
      raise exception 'WEEKLY_SOURCE_ACCEPTED_ACTION_ROUTINE_ACL_INVALID:%',v_signature; end if;
  end loop;
  if (select count(*) from pg_trigger t where t.tgrelid=v_table and not t.tgisinternal
       and t.tgenabled='O' and t.tgfoid=
         'private.weekly_source_accepted_publication_action_immutable_v1()'::regprocedure)<>2
     or exists(select 1 from (values('anon'),('authenticated'),('service_role')) r(name)
       where has_function_privilege(r.name,
         'private.weekly_source_accepted_publication_action_immutable_v1()','EXECUTE')) then
    raise exception 'WEEKLY_SOURCE_ACCEPTED_ACTION_IMMUTABILITY_INVALID'; end if;
  if not exists(select 1 from pg_constraint c where c.conrelid=v_table and c.contype='f'
      and c.confrelid='public.weekly_source_entitlement_decision_bundles'::regclass
      and array_length(c.conkey,1)=2 and c.confdeltype='r') then
    raise exception 'WEEKLY_SOURCE_ACCEPTED_ACTION_BUNDLE_REVISION_FK_INVALID'; end if;
  perform set_config('request.jwt.claim.role','authenticated',true);
  begin
    perform private.weekly_source_accepted_publication_action_record_v1('{}','{}','{}');
    raise exception 'WEEKLY_SOURCE_ACCEPTED_ACTION_UNTRUSTED_ROLE_ACCEPTED';
  exception when insufficient_privilege then
    if sqlerrm<>'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' then raise; end if;
  end;
  perform set_config('request.jwt.claim.role','service_role',true);
  begin
    perform private.weekly_source_accepted_publication_action_verify_v1(null,null,null,null,null);
    raise exception 'WEEKLY_SOURCE_ACCEPTED_ACTION_NULL_CERTIFICATE_ACCEPTED';
  exception when invalid_parameter_value then
    if sqlerrm<>'WEEKLY_SOURCE_ACCEPTED_ACTION_INVALID' then raise; end if;
  end;
end; $verify$;

-- Portable NEW and UPGRADE security/ownership checks. No business rows changed.
do $verify$
declare
  routine record;
  receipt_table oid:=to_regclass('private.weekly_source_local_protected_decision_receipts');
  definition text;
begin
  if receipt_table is null or exists(select 1 from pg_class where oid=receipt_table
      and relowner<>(select oid from pg_roles where rolname=current_user))
    or exists(select 1 from (values('anon'),('authenticated'),('service_role')) role(name)
      where has_table_privilege(role.name,receipt_table,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) then
    raise exception 'WEEKLY_PROTECTED_LOCAL_RECEIPT_ACL_INVALID';
  end if;
  for routine in select expected.signature,expected.service_execute,p.* from (values
    ('public.weekly_exceptional_pay_complete_local_v1(jsonb)',true),
    ('private.weekly_source_local_preauthorisation_write_allowed_v1(uuid,jsonb)',true),
    ('private.weekly_source_local_protected_pending_released_v1()',false)
  ) expected(signature,service_execute) left join pg_proc p on p.oid=to_regprocedure(expected.signature)
  loop
    if routine.oid is null or not routine.prosecdef
      or routine.proowner<>(select oid from pg_roles where rolname=current_user)
      or not exists(select 1 from unnest(routine.proconfig) config where config like 'search_path=%')
      or has_function_privilege('anon',routine.oid,'EXECUTE')
      or has_function_privilege('authenticated',routine.oid,'EXECUTE')
      or has_function_privilege('service_role',routine.oid,'EXECUTE') is distinct from routine.service_execute then
      raise exception 'WEEKLY_PROTECTED_LOCAL_ROUTINE_ACL_INVALID:%',routine.signature;
    end if;
  end loop;
  if not exists(select 1 from pg_trigger where tgrelid='public.weekly_source_pending_entitlement_bundles'::regclass
    and tgname='weekly_source_local_protected_pending_released' and tgenabled='O'
    and tgfoid='private.weekly_source_local_protected_pending_released_v1()'::regprocedure) then
    raise exception 'WEEKLY_PROTECTED_LOCAL_RELEASE_HOOK_MISSING';
  end if;
  definition:=pg_get_functiondef('public.weekly_exceptional_pay_complete_local_v1(jsonb)'::regprocedure);
  if position('private.weekly_source_entitlement_publish_immediate_v1' in definition)=0
    or position('public.tsfin_write_current_snapshot_single_bounded' in definition)=0
    or position('prior_effective_inventory' in definition)=0
    or position('public.weekly_source_manual_review_resolve_v1' in definition)=0
    or definition ~ '(weekly_source_start_c1|weekly_source_publish_c1|weekly_source_status_c1)' then
    raise exception 'WEEKLY_PROTECTED_LOCAL_AUTHORITY_BOUNDARY_INVALID';
  end if;
  perform set_config('request.jwt.claim.role','authenticated',true);
  begin
    perform public.weekly_exceptional_pay_complete_local_v1('{}'::jsonb);
    raise exception 'WEEKLY_PROTECTED_LOCAL_BROWSER_CALL_ACCEPTED';
  exception when insufficient_privilege then
    if sqlerrm<>'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' then raise; end if;
  end;
  perform set_config('request.jwt.claim.role','service_role',true);
  begin
    perform public.weekly_exceptional_pay_complete_local_v1('{}'::jsonb);
    raise exception 'WEEKLY_PROTECTED_LOCAL_INVALID_REQUEST_ACCEPTED';
  exception when invalid_parameter_value then
    if sqlerrm<>'WEEKLY_PROTECTED_LOCAL_COMPLETE_INVALID' then raise; end if;
  end;
end
$verify$;

-- Rollback-contained first-use proof for the weekly PAPER/QR adapter.  A
-- submitted Candidate workflow may have no Timesheet after withdrawal.  The
-- adapter must create exactly one unapproved current Timesheet/TSFIN through
-- the existing weekly canonical writer, link the workflow, replay safely, and
-- remain inaccessible to browser roles.


do $candidate_weekly_paper_target_prepare_verification$
declare
  v_now timestamptz := '2026-08-30 06:05:00+00';
  v_week_ending_date date := ('2026-08-30 06:05:00+00'::timestamptz at time zone 'UTC')::date;
  v_work_date date := (('2026-08-30 06:05:00+00'::timestamptz at time zone 'UTC')::date-6);
  v_client uuid := gen_random_uuid();
  v_candidate uuid := gen_random_uuid();
  v_contract uuid := gen_random_uuid();
  v_week uuid := gen_random_uuid();
  v_account uuid := gen_random_uuid();
  v_session uuid := gen_random_uuid();
  v_workflow uuid := gen_random_uuid();
  v_timesheet uuid := gen_random_uuid();
  v_email text;
  v_schedule jsonb;
  v_create jsonb;
  v_patch jsonb;
  v_week_patch jsonb;
  v_snapshot jsonb;
  v_submission jsonb;
  v_first jsonb;
  v_replay jsonb;
  v_paper jsonb;
  v_paper_replay jsonb;
  v_promote jsonb;
  v_manifest jsonb;
  v_manifest_hex text;
  v_page jsonb;
  v_qr jsonb;
  v_proof jsonb;
  v_prepare jsonb;
  v_pack jsonb;
  v_pack_replay jsonb;
  v_verified_pages jsonb;
  v_component uuid;
  v_component_key uuid := gen_random_uuid();
  v_pack_key uuid := gen_random_uuid();
  v_bad_pack_key uuid := gen_random_uuid();
  v_content_hash text;
  v_bad_proof_failed boolean := false;
  v_mileage_source_component uuid := gen_random_uuid();
  v_mileage_component_no integer;
  v_mileage_source_hash text;
  v_mileage_manifest jsonb;
  v_mileage_manifest_hex text;
  v_mileage_page jsonb;
  v_hours_page jsonb;
  v_mileage_qr jsonb;
  v_pack_qr jsonb;
  v_mileage_proof jsonb;
  v_pack_proof jsonb;
  v_wrong_mileage_failed boolean := false;
  v_mileage_on_hours_failed boolean := false;
  v_plan_chunk uuid;
  v_plan_document_version uuid;
  v_plan_result jsonb;
  v_manual_operation uuid := gen_random_uuid();
  v_manual_document_version uuid := gen_random_uuid();
  v_manual_plan_chunk uuid := gen_random_uuid();
  v_manual_revision bigint;
  v_manual_result jsonb;
  v_stale_failed boolean := false;
begin
  v_email := 'paper-target-'||replace(v_candidate::text,'-','')||'@example.test';
  v_schedule := jsonb_build_array(jsonb_build_object(
    'date',v_work_date,'day','MON','start','09:00','end','17:00',
    'break_minutes',0,'hours',8
  ));
  v_create := jsonb_build_object(
    'timesheet_id',v_timesheet,
    'booking_id','CANDIDATE-WEEKLY-'||replace(v_week::text,'-',''),
    'contract_id',v_contract,
    'week_ending_date',v_week_ending_date,
    'occupant_key_norm','PAPER-TARGET-'||replace(v_candidate::text,'-',''),
    'hospital_norm','Paper target verification client',
    'ward_norm','',
    'job_title_norm','RMN',
    'shift_label_norm','weekly',
    'status','RECEIVED',
    'submission_mode','MANUAL',
    'line_type','HOURS',
    'sheet_scope','WEEKLY',
    'actual_schedule_json',v_schedule,
    'additional_units_week','{}'::jsonb,
    'additional_units_per_day','{}'::jsonb,
    'candidate_hint_text',jsonb_build_object('display_name','Paper Target Candidate')
  );
  v_patch := jsonb_build_object(
    'actual_schedule_json',v_schedule,
    'additional_units_week','{}'::jsonb,
    'additional_units_per_day','{}'::jsonb
  );
  v_week_patch := jsonb_build_object(
    'totals_json',jsonb_build_object('total_hours',8,'actual_schedule_json',v_schedule),
    'planned_schedule_json',v_schedule
  );
  v_snapshot := jsonb_build_object(
    'timesheet_id',v_timesheet,
    'timesheet_version',1,
    'candidate_id',v_candidate,
    'client_id',v_client,
    'basis','SELF_REPORTED',
    'candidate_assignment','ASSIGNED',
    'processing_status','PENDING_AUTH',
    'total_hours',8,
    'hours_day',8,
    'hours_night',0,
    'hours_sat',0,
    'hours_sun',0,
    'hours_bh',0,
    'invoice_breakdown_json','{}'::jsonb,
    'additional_units_json','{}'::jsonb,
    'mileage_units',0,
    'mileage_pay_ex_vat',0,
    'mileage_charge_ex_vat',0,
    'expenses_pay_ex_vat',0,
    'expenses_charge_ex_vat',0,
    'travel_pay_ex_vat',0,
    'travel_charge_ex_vat',0,
    'accommodation_pay_ex_vat',0,
    'accommodation_charge_ex_vat',0,
    'other_pay_ex_vat',0,
    'other_charge_ex_vat',0
  );
  v_submission := jsonb_build_object(
    'contract_version','CANDIDATE_WEEKLY_CANONICAL_AUTHORITY_V1',
    'timesheet_create_json',v_create,
    'timesheet_patch_json',v_patch,
    'contract_week_patch_json',v_week_patch,
    'canonical_tsfin_snapshot',v_snapshot
  );

  update public.settings_defaults
  set candidate_app_feature_flags_json=candidate_app_feature_flags_json||jsonb_build_object(
    'candidate_app_reads',true,
    'candidate_app_writes',true,
    'candidate_record_role_capabilities',true,
    'candidate_paper_qr',true
  )
  where id=1;

  insert into public.clients(id,name)
  values(v_client,'Paper target verification client');
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday
  ) values(
    gen_random_uuid(),v_client,v_week_ending_date-30,'ELECTRONIC',
    extract(dow from v_week_ending_date)::integer
  );
  insert into public.candidates(id,email,display_name,active,key_norm,opt_in_email)
  values(v_candidate,v_email,'Paper Target Candidate',true,
    'PAPER-TARGET-'||replace(v_candidate::text,'-',''),true);
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,week_ending_weekday_snapshot,
    default_submission_mode,pay_method_snapshot,role,
    candidate_paper_submission_enabled_override
  ) values(
    v_contract,v_candidate,v_client,v_week_ending_date-30,v_week_ending_date+30,
    extract(dow from v_week_ending_date)::integer,
    'ELECTRONIC','PAYE','RMN',true
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot,timesheet_id,
    day_entries_json,totals_json
  ) values(
    v_week,v_contract,v_week_ending_date,'SUBMITTED','ELECTRONIC',null,
    v_schedule,jsonb_build_object('total_hours',8,'actual_schedule_json',v_schedule)
  );
  insert into public.candidate_app_accounts(
    id,environment,email_normalized,status,password_scheme,password_scheme_version,
    password_salt,password_digest,password_changed_at_utc
  ) values(
    v_account,'TEST',v_email,'ACTIVE','PBKDF2-HMAC-SHA256',1,
    decode(repeat('41',16),'hex'),decode(repeat('42',32),'hex'),v_now
  );
  insert into public.candidate_app_sessions(
    id,account_id,environment,selected_candidate_id,status,refresh_token_hash,
    expires_at_utc,absolute_expires_at_utc
  ) values(
    v_session,v_account,'TEST',v_candidate,'ACTIVE',
    extensions.digest(v_session::text,'sha256'),v_now+interval '1 hour',v_now+interval '2 hours'
  );
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,
    generation,contract_id,contract_week_id,anchor_timesheet_id,target_timesheet_id,
    week_ending_date,idempotency_key,review_manifest_sha256,
    immutable_submission_json,immutable_submission_sha256
  ) values(
    v_workflow,'TEST',v_account,v_candidate,'CONTRACT_HOURS','WEEKLY','ELECTRONIC',
    'READY_FOR_MANAGER_APPROVAL',1,v_contract,v_week,null,null,v_week_ending_date,
    'paper-target-verification-'||v_workflow::text,
    extensions.digest('paper-target-verification-'||v_workflow::text,'sha256'),
    v_submission,private._candidate_sha256_jsonb_v1(v_submission)
  );
  insert into public.candidate_submission_components(
    workflow_id,workflow_generation,component_no,component_kind,document_role,state,
    required,review_ordinal,review_render_state,final_signed_render_state
  ) values(
    v_workflow,1,1,'HOURS_TIMESHEET','ELECTRONIC_TIMESHEET_MANAGER_REVIEW','PENDING',
    true,1,'PENDING','PENDING'
  );

  v_first:=public.candidate_weekly_paper_target_prepare_v1(
    v_session,'TEST',v_workflow,1,v_now
  );
  v_replay:=public.candidate_weekly_paper_target_prepare_v1(
    v_session,'TEST',v_workflow,1,v_now+interval '1 second'
  );

  if v_first->>'timesheet_id' is distinct from v_timesheet::text
     or v_first->>'created' is distinct from 'true'
     or v_replay->>'timesheet_id' is distinct from v_timesheet::text
     or v_replay->>'idempotent_replay' is distinct from 'true'
     or (select timesheet_id from public.contract_weeks where id=v_week) is distinct from v_timesheet
     or (select target_timesheet_id from public.candidate_submission_workflows where id=v_workflow) is distinct from v_timesheet
     or (select timesheet_id from public.candidate_submission_components where workflow_id=v_workflow and component_no=1) is distinct from v_timesheet
     or (select count(*) from public.timesheets where contract_id=v_contract and week_ending_date=v_week_ending_date and is_current)<>1
     or not exists(
       select 1 from public.timesheets
       where timesheet_id=v_timesheet and is_current and archived_at_utc is null
         and sheet_scope='WEEKLY' and submission_mode='MANUAL'
         and authorised_at_server is null
     )
     or (select count(*) from public.timesheets_financials where timesheet_id=v_timesheet and is_current)<>1
     or not exists(
       select 1 from public.timesheets_financials
       where timesheet_id=v_timesheet and is_current
         and authorised_at_utc is null and paid_at_utc is null
         and locked_by_invoice_id is null
     ) then
    raise exception 'CANDIDATE_WEEKLY_PAPER_TARGET_FIRST_USE_FAILED: %, %',v_first,v_replay;
  end if;

  begin
    perform public.candidate_weekly_paper_target_prepare_v1(
      v_session,'TEST',v_workflow,2,v_now+interval '2 seconds'
    );
  exception when sqlstate '40001' then
    v_stale_failed:=true;
  end;
  if not v_stale_failed then
    raise exception 'CANDIDATE_WEEKLY_PAPER_TARGET_STALE_GENERATION_ACCEPTED';
  end if;

  -- The real app offers Printed Documents after the electronic review pack is
  -- ready.  Target preparation above must preserve that state, then the atomic
  -- adapter enters the existing PAPER authority without creating another
  -- Timesheet, workflow or outbox item.
  if (select state from public.candidate_submission_workflows where id=v_workflow)
       is distinct from 'READY_FOR_MANAGER_APPROVAL'
     or (select route from public.candidate_submission_workflows where id=v_workflow)
       is distinct from 'ELECTRONIC' then
    raise exception 'CANDIDATE_WEEKLY_PAPER_TARGET_READY_STATE_NOT_PRESERVED';
  end if;
  v_paper:=public.candidate_weekly_paper_prepare_atomic_v1(
    v_session,'TEST',v_workflow,'PAPER_PREPARE',1,'{}'::jsonb,
    'paper-ready-verification-'||v_workflow::text,v_now+interval '3 seconds'
  );
  v_paper_replay:=public.candidate_weekly_paper_prepare_atomic_v1(
    v_session,'TEST',v_workflow,'PAPER_PREPARE',1,'{}'::jsonb,
    'paper-ready-verification-'||v_workflow::text,v_now+interval '4 seconds'
  );
  if v_paper->>'state' is distinct from 'AWAITING_PAPER_RETURN'
     or v_paper_replay->>'state' is distinct from 'AWAITING_PAPER_RETURN'
     or (select state from public.candidate_submission_workflows where id=v_workflow)
          is distinct from 'AWAITING_PAPER_RETURN'
     or (select route from public.candidate_submission_workflows where id=v_workflow)
          is distinct from 'PAPER'
     or (select count(*) from public.timesheets where contract_id=v_contract and week_ending_date=v_week_ending_date and is_current)<>1
     or (select count(*) from public.mail_outbox
         where type='TIMESHEET_QR'
           and payment_scope_json->>'candidate_workflow_id'=v_workflow::text)<>1
     or (select processing_status::text
         from public.timesheets_financials
         where timesheet_id=v_timesheet and is_current)
          is distinct from 'AWAITING_MANUAL_SIGNATURE'
     or not exists(
       select 1
       from public.timesheets current_timesheet
       join public.invoice_document_versions current_document
         on current_document.id=current_timesheet.current_document_version_id
       where current_timesheet.timesheet_id=v_timesheet
         and current_timesheet.is_current
         and current_timesheet.document_state='QUEUED'
         and current_document.source_revision=current_timesheet.document_revision::text
         and current_document.entity_id=current_timesheet.timesheet_id
     ) then
    raise exception 'CANDIDATE_WEEKLY_PAPER_READY_FIRST_USE_FAILED: %, %',v_paper,v_paper_replay;
  end if;

  -- The Candidate PAPER route stores the Timesheet as MANUAL so the eventual
  -- returned page is handled by the established signed-asset authority.  Its
  -- initial frozen QR_UNSIGNED pack is nevertheless a server-rendered official
  -- form and must not be rejected as a missing uploaded manual asset.
  if (select count(*)
      from public.invoice_operation_chunks c
      where c.entity_type='TIMESHEET'
        and c.entity_id=v_timesheet
        and c.chunk_type='DOCUMENT_PLAN'
        and c.phase='BUILD_MANIFEST')<>1 then
    raise exception 'CANDIDATE_WEEKLY_PAPER_DOCUMENT_PLAN_MULTIPLICITY_INVALID';
  end if;
  select c.id,c.document_version_id
    into v_plan_chunk,v_plan_document_version
  from public.invoice_operation_chunks c
  where c.entity_type='TIMESHEET'
    and c.entity_id=v_timesheet
    and c.chunk_type='DOCUMENT_PLAN'
    and c.phase='BUILD_MANIFEST';

  v_plan_result:=private._invoice_document_advance_batch(
    jsonb_build_array(jsonb_build_object(
      'chunk_id',v_plan_chunk,'phase','BUILD_MANIFEST')),
    v_now+interval '5 seconds'
  );
  if v_plan_result->0->>'status' is distinct from 'QUEUED'
     or v_plan_result->0->>'phase' is distinct from 'WAIT_FOR_INPUTS'
     or (select status::text from public.invoice_operation_chunks
         where id=v_plan_chunk) is distinct from 'QUEUED'
     or (select phase from public.invoice_operation_chunks
         where id=v_plan_chunk) is distinct from 'WAIT_FOR_INPUTS'
     or (select status::text from public.invoice_document_versions
         where id=v_plan_document_version) is distinct from 'WAITING_FOR_INPUTS'
     or (select jsonb_array_length(manifest_json)
         from public.invoice_document_versions
         where id=v_plan_document_version)<>1
     or (select manifest_json->0->>'input_type'
         from public.invoice_document_versions
         where id=v_plan_document_version) is distinct from 'ELECTRONIC_TIMESHEET'
     or (select count(*) from public.invoice_operation_chunks
         where operation_id=(select operation_id from public.invoice_operation_chunks
                             where id=v_plan_chunk)
           and chunk_type='SOURCE_RENDER' and phase='RENDER' and status='QUEUED')<>1
     or exists(
       select 1 from public.invoice_operation_chunks
       where operation_id=(select operation_id from public.invoice_operation_chunks
                           where id=v_plan_chunk)
         and error_json->>'code'='MANUAL_TIMESHEET_ASSET_REQUIRED'
     ) then
    raise exception 'CANDIDATE_WEEKLY_QR_UNSIGNED_DOCUMENT_PLAN_FAILED: %',v_plan_result;
  end if;

  -- New packs are promoted while the email is still held.  The returned
  -- physical JPEG is first staged outside PostgreSQL, but no returned page is
  -- accepted here until the exact full manifest is supplied in one call.
  v_promote:=public.candidate_paper_manifest_v2_promote_v1(
    v_session,'TEST',v_workflow,1,
    v_paper->>'paper_return_manifest_sha256',v_now+interval '6 seconds'
  );
  select paper_return_manifest_json,
         encode(paper_return_manifest_sha256,'hex')
    into v_manifest,v_manifest_hex
  from public.candidate_submission_workflows
  where id=v_workflow;
  if v_promote->>'manifest_version' is distinct from '2'
     or v_manifest->>'qr_contract_version' is distinct from
       'CANDIDATE_PAPER_PAGE_QR_V2'
     or jsonb_array_length(v_manifest->'pages')<>1 then
    raise exception 'CANDIDATE_PAPER_MANIFEST_V2_PROMOTION_FAILED: %',v_promote;
  end if;

  v_page:=v_manifest->'pages'->0;
  v_qr:=jsonb_build_object(
    'v',2,
    'w',v_workflow::text,
    't',v_timesheet::text,
    'g',1,
    'm',v_manifest_hex,
    'o',(v_page->>'ordinal')::integer,
    'p',v_page->>'page_key_sha256_16',
    'k',v_page->>'page_kind_code',
    'c',coalesce(v_page->>'category_code',''),
    'n',(v_page->>'category_occurrence')::integer
  );
  v_proof:=public.candidate_paper_return_proof_validate_v2(
    v_session,'TEST',v_workflow,1,v_manifest_hex,v_page->>'page_key',v_qr,
    v_now+interval '7 seconds'
  );
  v_content_hash:=encode(extensions.digest(
    'candidate-paper-pack-v2-first-use','sha256'
  ),'hex');
  v_prepare:=public.candidate_component_prepare_atomic_v1(
    v_session,'TEST',v_workflow,1,jsonb_build_object(
      'component_kind','SIGNED_RETURN',
      'document_role','SIGNED_RETURN',
      'paper_return_page_key',v_page->>'page_key',
      'storage_key','candidate-paper-pack-v2/verification.jpg',
      'media_type','image/jpeg',
      'byte_size',4096
    ),v_component_key::text,v_now+interval '8 seconds'
  );
  v_component:=(v_prepare->>'component_id')::uuid;
  v_verified_pages:=jsonb_build_array(jsonb_build_object(
    'ordinal',(v_page->>'ordinal')::integer,
    'page_key',v_page->>'page_key',
    'component_id',v_component,
    'source_content_sha256',v_content_hash,
    'byte_size',4096,
    'media_type','image/jpeg',
    'image_width',1600,
    'image_height',1200,
    'manifest_sha256',v_manifest_hex,
    'qr_payload',v_qr,
    'proof_receipt_sha256',v_proof->>'proof_receipt_sha256',
    'qr_payload_sha256',v_proof->>'qr_payload_sha256'
  ));

  -- A syntactically valid but false proof must roll back the component
  -- completion performed earlier in the same function invocation.
  begin
    perform public.candidate_paper_return_pack_complete_v2(
      v_session,'TEST',v_workflow,1,
      jsonb_set(v_verified_pages,'{0,proof_receipt_sha256}',
        to_jsonb(repeat('0',64)),false),
      v_bad_pack_key::text,v_now+interval '9 seconds'
    );
  exception when sqlstate '40001' then
    v_bad_proof_failed:=true;
  end;
  if not v_bad_proof_failed
     or (select state from public.candidate_submission_components
         where id=v_component) is distinct from 'PENDING'
     or (select state from public.candidate_submission_workflows
         where id=v_workflow) is distinct from 'AWAITING_PAPER_RETURN' then
    raise exception 'CANDIDATE_PAPER_PACK_PARTIAL_ACCEPTANCE_NOT_ROLLED_BACK';
  end if;

  v_pack:=public.candidate_paper_return_pack_complete_v2(
    v_session,'TEST',v_workflow,1,v_verified_pages,
    v_pack_key::text,v_now+interval '10 seconds'
  );
  if v_pack->>'state' is distinct from 'RECEIVED'
     or v_pack->>'paper_return_pack_verified' is distinct from 'true'
     or v_pack->>'paper_return_page_count' is distinct from '1'
     or (select state from public.candidate_submission_components
         where id=v_component) is distinct from 'IMMUTABLE'
     or (select paper_return_proof_receipt_sha256 is not null
         from public.candidate_submission_components
         where id=v_component) is distinct from true
     or (select state from public.candidate_submission_workflows
         where id=v_workflow) is distinct from 'RECEIVED' then
    raise exception 'CANDIDATE_PAPER_PACK_ATOMIC_FIRST_USE_FAILED: %',v_pack;
  end if;

  v_pack_replay:=public.candidate_paper_return_pack_complete_v2(
    v_session,'TEST',v_workflow,1,v_verified_pages,
    v_pack_key::text,v_now+interval '11 seconds'
  );
  if v_pack_replay->>'state' is distinct from 'RECEIVED'
     or v_pack_replay->>'idempotent_replay' is distinct from 'true'
     or v_pack_replay->>'paper_return_pack_verified' is distinct from 'true'
     or v_pack_replay->>'paper_return_page_count' is distinct from '1'
     or (select count(*) from public.candidate_submission_components
         where workflow_id=v_workflow and component_kind='SIGNED_RETURN')<>1
     or (select count(*) from public.audit_events
         where object_type='candidate_workflow_mutation_receipt'
           and object_id_text=v_workflow::text
           and correlation_id=v_pack_key::text)<>1 then
    raise exception 'CANDIDATE_PAPER_PACK_IDEMPOTENT_REPLAY_FAILED: %',v_pack_replay;
  end if;

  -- Mileage is photographed as unsigned evidence before the worker chooses a
  -- manager route.  PAPER then carries each photograph into its own current
  -- pack page and gives that page the same unique return-QR contract as every
  -- other page.  Prove the exact Mileage pack-page QR is accepted, a stale
  -- manifest is rejected, and a Mileage page identity cannot satisfy Hours.
  v_mileage_source_hash:=encode(extensions.digest(
    'candidate-paper-mileage-source-first-use','sha256'
  ),'hex');
  select coalesce(max(component_no),0)+1 into v_mileage_component_no
  from public.candidate_submission_components
  where workflow_id=v_workflow and workflow_generation=1;
  insert into public.candidate_submission_components(
    id,workflow_id,workflow_generation,component_no,timesheet_id,
    component_kind,expense_category,document_role,state,required,
    storage_key,media_type,byte_size,source_content_sha256,immutable_at_utc
  ) values(
    v_mileage_source_component,v_workflow,1,v_mileage_component_no,v_timesheet,
    'MILEAGE_FORM','MILEAGE','MILEAGE_CLAIM_FORM','IMMUTABLE',false,
    'candidate-paper-mileage-source/verification.jpg','image/jpeg',4096,
    decode(v_mileage_source_hash,'hex'),v_now+interval '12 seconds'
  );
  v_mileage_page:=jsonb_build_object(
    'ordinal',1,
    'page_key','paper-v2:2:mileage-source',
    'page_key_sha256_16',substring(encode(extensions.digest(
      'paper-v2:2:mileage-source','sha256'
    ),'hex') from 1 for 16),
    'page_kind_code','M',
    'category_code','M',
    'category_occurrence',1,
    'component_kind','MILEAGE_FORM',
    'expense_category','MILEAGE',
    'source_component_id',v_mileage_source_component,
    'source_content_sha256',v_mileage_source_hash
  );
  v_hours_page:=jsonb_build_object(
    'ordinal',2,
    'page_key','paper-v2:2:hours',
    'page_key_sha256_16',substring(encode(extensions.digest(
      'paper-v2:2:hours','sha256'
    ),'hex') from 1 for 16),
    'page_kind_code','T',
    'category_code','',
    'category_occurrence',1,
    'component_kind','HOURS_TIMESHEET',
    'expense_category',null
  );
  v_mileage_manifest:=jsonb_build_object(
    'manifest_version',2,
    'qr_contract_version','CANDIDATE_PAPER_PAGE_QR_V2',
    'workflow_id',v_workflow,
    'generation',2,
    'pages',jsonb_build_array(v_mileage_page,v_hours_page)
  );
  v_mileage_manifest_hex:=encode(
    private._candidate_sha256_jsonb_v1(v_mileage_manifest),'hex'
  );
  update public.candidate_submission_workflows
     set generation=2,
         route='PAPER',
         state='AWAITING_PAPER_RETURN',
         paper_return_manifest_json=v_mileage_manifest,
         paper_return_manifest_sha256=decode(v_mileage_manifest_hex,'hex')
   where id=v_workflow;

  v_mileage_qr:=jsonb_build_object(
    'v',2,
    'w',v_workflow::text,
    't',v_timesheet::text,
    'g',2,
    'm',v_mileage_manifest_hex,
    'o',1,
    'p',v_mileage_page->>'page_key_sha256_16',
    'k','M',
    'c','M',
    'n',1
  );
  v_mileage_proof:=public.candidate_paper_return_proof_validate_v2(
    v_session,'TEST',v_workflow,2,v_mileage_manifest_hex,
    v_mileage_page->>'page_key',v_mileage_qr,v_now+interval '13 seconds'
  );
  if v_mileage_proof->>'ok' is distinct from 'true'
     or v_mileage_proof->>'qr_identity_kind' is distinct from 'PACK_PAGE'
     or v_mileage_proof->>'page_component_kind' is distinct from 'MILEAGE_FORM' then
    raise exception 'CANDIDATE_PAPER_MILEAGE_PACK_QR_FIRST_USE_FAILED: %',
      v_mileage_proof;
  end if;

  begin
    perform public.candidate_paper_return_proof_validate_v2(
      v_session,'TEST',v_workflow,2,v_mileage_manifest_hex,
      v_mileage_page->>'page_key',
      jsonb_set(v_mileage_qr,'{m}',to_jsonb(repeat('f',64)),false),
      v_now+interval '14 seconds'
    );
  exception when sqlstate '28000' then
    v_wrong_mileage_failed:=true;
  end;
  if not v_wrong_mileage_failed then
    raise exception 'CANDIDATE_PAPER_STALE_MILEAGE_PACK_QR_ACCEPTED';
  end if;

  begin
    perform public.candidate_paper_return_proof_validate_v2(
      v_session,'TEST',v_workflow,2,v_mileage_manifest_hex,
      v_hours_page->>'page_key',v_mileage_qr,v_now+interval '15 seconds'
    );
  exception when sqlstate '28000' then
    v_mileage_on_hours_failed:=true;
  end;
  if not v_mileage_on_hours_failed then
    raise exception 'CANDIDATE_PAPER_MILEAGE_PACK_QR_ACCEPTED_FOR_HOURS';
  end if;

  v_pack_qr:=jsonb_build_object(
    'v',2,
    'w',v_workflow::text,
    't',v_timesheet::text,
    'g',2,
    'm',v_mileage_manifest_hex,
    'o',2,
    'p',v_hours_page->>'page_key_sha256_16',
    'k','T',
    'c','',
    'n',1
  );
  v_pack_proof:=public.candidate_paper_return_proof_validate_v2(
    v_session,'TEST',v_workflow,2,v_mileage_manifest_hex,
    v_hours_page->>'page_key',v_pack_qr,v_now+interval '16 seconds'
  );
  if v_pack_proof->>'ok' is distinct from 'true'
     or v_pack_proof->>'qr_identity_kind' is distinct from 'PACK_PAGE'
     or v_pack_proof->>'page_component_kind' is distinct from 'HOURS_TIMESHEET' then
    raise exception 'CANDIDATE_PAPER_CURRENT_PACK_QR_REGRESSION: %',v_pack_proof;
  end if;

  -- Preserve the opposite fail-closed rule: an ordinary MANUAL Timesheet with
  -- no registered source asset is still blocked.  This second planner is a
  -- rollback-only synthetic operation over the same fixture after QR has been
  -- cancelled, so it cannot be mistaken for the approved QR_UNSIGNED form.
  update public.timesheets
     set qr_status='CANCELLED',qr_token=null,qr_payload_json='{}'::jsonb,
         current_document_version_id=null,active_document_operation_id=null,
         document_state='STALE',document_revision=document_revision+1,
         updated_at=v_now+interval '6 seconds'
   where timesheet_id=v_timesheet and is_current
   returning document_revision into v_manual_revision;

  insert into public.invoice_operations(
    id,operation_type,entity_type,entity_id,idempotency_key,status,phase,
    priority,source_revision,template_version,input_json,config_json,
    progress_json,total_units,chunk_count,control_version,change_seq,
    created_at_utc,updated_at_utc
  ) values(
    v_manual_operation,'BUILD_DOCUMENT','TIMESHEET',v_timesheet,
    'paper-manual-negative-'||v_manual_operation::text,'QUEUED','BUILD_MANIFEST',
    550,v_manual_revision::text,'timesheet-professional-v2','{}'::jsonb,
    jsonb_build_object('processor_policy',private._invoice_processor_limits()),
    '{}'::jsonb,1,1,1,nextval('public.invoice_operation_change_seq'),
    v_now+interval '6 seconds',v_now+interval '6 seconds'
  );
  insert into public.invoice_document_versions(
    id,entity_type,entity_id,purpose,operation_id,source_revision,
    template_version,status,snapshot_json,snapshot_hash,manifest_json,
    manifest_hash,created_at_utc
  ) values(
    v_manual_document_version,'TIMESHEET',v_timesheet,'TIMESHEET',
    v_manual_operation,v_manual_revision::text,'timesheet-professional-v2',
    'PLANNING','{}'::jsonb,encode(extensions.digest('{}','sha256'),'hex'),
    '[]'::jsonb,encode(extensions.digest('[]','sha256'),'hex'),
    v_now+interval '6 seconds'
  );
  insert into public.invoice_operation_chunks(
    id,operation_id,chunk_type,phase,work_key,sequence_no,entity_type,
    entity_id,document_version_id,status,priority,run_after_utc,payload_json,
    operation_control_version,created_at_utc,updated_at_utc
  ) values(
    v_manual_plan_chunk,v_manual_operation,'DOCUMENT_PLAN','BUILD_MANIFEST',
    encode(extensions.digest('paper-manual-negative-'||v_manual_operation::text,
      'sha256'),'hex'),0,'TIMESHEET',v_timesheet,v_manual_document_version,
    'QUEUED',550,v_now+interval '6 seconds','{}'::jsonb,1,
    v_now+interval '6 seconds',v_now+interval '6 seconds'
  );
  v_manual_result:=private._invoice_document_advance_batch(
    jsonb_build_array(jsonb_build_object(
      'chunk_id',v_manual_plan_chunk,'phase','BUILD_MANIFEST')),
    v_now+interval '7 seconds'
  );
  if v_manual_result->0->>'status' is distinct from 'BLOCKED'
     or v_manual_result->0#>>'{error,code}' is distinct from
       'MANUAL_TIMESHEET_ASSET_REQUIRED'
     or (select status::text from public.invoice_operation_chunks
         where id=v_manual_plan_chunk) is distinct from 'BLOCKED' then
    raise exception 'ORDINARY_MANUAL_MISSING_ASSET_NOT_BLOCKED: %',v_manual_result;
  end if;

  if pg_catalog.has_function_privilege('anon',
       'public.candidate_weekly_paper_target_prepare_v1(uuid,text,uuid,integer,timestamp with time zone)',
       'EXECUTE')
     or pg_catalog.has_function_privilege('authenticated',
       'public.candidate_weekly_paper_target_prepare_v1(uuid,text,uuid,integer,timestamp with time zone)',
       'EXECUTE')
     or not pg_catalog.has_function_privilege('service_role',
       'public.candidate_weekly_paper_target_prepare_v1(uuid,text,uuid,integer,timestamp with time zone)',
       'EXECUTE') then
    raise exception 'CANDIDATE_WEEKLY_PAPER_TARGET_ACL_INVALID';
  end if;
  if pg_catalog.has_function_privilege('anon',
       'public.candidate_weekly_paper_prepare_atomic_v1(uuid,text,uuid,text,integer,jsonb,text,timestamp with time zone)',
       'EXECUTE')
     or pg_catalog.has_function_privilege('authenticated',
       'public.candidate_weekly_paper_prepare_atomic_v1(uuid,text,uuid,text,integer,jsonb,text,timestamp with time zone)',
       'EXECUTE')
     or not pg_catalog.has_function_privilege('service_role',
       'public.candidate_weekly_paper_prepare_atomic_v1(uuid,text,uuid,text,integer,jsonb,text,timestamp with time zone)',
       'EXECUTE') then
    raise exception 'CANDIDATE_WEEKLY_PAPER_READY_ACL_INVALID';
  end if;
  if pg_catalog.has_function_privilege('anon',
       'public.candidate_paper_return_pack_complete_v2(uuid,text,uuid,integer,jsonb,text,timestamp with time zone)',
       'EXECUTE')
     or pg_catalog.has_function_privilege('authenticated',
       'public.candidate_paper_return_pack_complete_v2(uuid,text,uuid,integer,jsonb,text,timestamp with time zone)',
       'EXECUTE')
     or not pg_catalog.has_function_privilege('service_role',
       'public.candidate_paper_return_pack_complete_v2(uuid,text,uuid,integer,jsonb,text,timestamp with time zone)',
       'EXECUTE') then
    raise exception 'CANDIDATE_PAPER_PACK_ACL_INVALID';
  end if;
end;
$candidate_weekly_paper_target_prepare_verification$;

do $verification$
declare
  v_name text;
  v_oid oid;
  v_rls boolean;
  v_view_options text[];
  v_failed text[] := array[]::text[];
begin
  foreach v_name in array array[
    'candidate_job_titles','candidates','client_settings','clients',
    'contract_weeks','contracts','mail_outbox','settings_defaults',
    'timesheet_evidence','timesheets','timesheets_financials'
  ] loop
    select c.oid,c.relrowsecurity into v_oid,v_rls
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relname=v_name and c.relkind='r';
    if v_oid is null or v_rls is not true
       or pg_catalog.has_table_privilege('anon',v_oid,'SELECT,INSERT,UPDATE,DELETE')
       or pg_catalog.has_table_privilege('authenticated',v_oid,'SELECT,INSERT,UPDATE,DELETE')
       or not pg_catalog.has_table_privilege('service_role',v_oid,'SELECT,INSERT,UPDATE,DELETE') then
      v_failed := pg_catalog.array_append(v_failed,v_name);
    end if;
  end loop;

  select c.oid,c.reloptions into v_oid,v_view_options
  from pg_catalog.pg_class c
  join pg_catalog.pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public' and c.relname='candidate_activity_rollup' and c.relkind='v';
  if v_oid is null
     or not ('security_invoker=true'=any(coalesce(v_view_options,array[]::text[])))
     or pg_catalog.has_table_privilege('anon',v_oid,'SELECT')
     or pg_catalog.has_table_privilege('authenticated',v_oid,'SELECT')
     or not pg_catalog.has_table_privilege('service_role',v_oid,'SELECT') then
    v_failed := pg_catalog.array_append(v_failed,'candidate_activity_rollup');
  end if;

  if pg_catalog.array_length(v_failed,1) is not null then
    raise exception 'CANDIDATE_MYTMS_RELATION_ISOLATION_FAILED:%',
      pg_catalog.array_to_string(v_failed,',');
  end if;
end
$verification$;

do $function_verification$
declare
