-- Rollback-contained first-use proof for the Candidate-driven Timesheet Summary refresh cursor.


do $candidate_timesheet_summary_refresh_verification$
declare
  v_timesheet_id uuid:=gen_random_uuid();
  v_contract_week_id uuid:=gen_random_uuid();
  v_workflow_id uuid:=gen_random_uuid();
  v_cursor_before bigint;
  v_cursor_after bigint;
  v_ping jsonb;
begin
  if has_table_privilege('anon','private.candidate_timesheet_summary_revisions','select')
     or has_table_privilege('authenticated','private.candidate_timesheet_summary_revisions','select')
     or has_table_privilege('service_role','private.candidate_timesheet_summary_revisions','select') then
    raise exception 'CANDIDATE_TIMESHEET_SUMMARY_PRIVATE_TABLE_EXPOSED';
  end if;
  if has_sequence_privilege('anon','private.candidate_timesheet_summary_revision_seq','usage')
     or has_sequence_privilege('authenticated','private.candidate_timesheet_summary_revision_seq','usage')
     or has_sequence_privilege('service_role','private.candidate_timesheet_summary_revision_seq','usage') then
    raise exception 'CANDIDATE_TIMESHEET_SUMMARY_PRIVATE_SEQUENCE_EXPOSED';
  end if;
  if has_function_privilege('anon','public.candidate_timesheet_summary_cursor_v1()','execute')
     or has_function_privilege('authenticated','public.candidate_timesheet_summary_cursor_v1()','execute')
     or not has_function_privilege('service_role','public.candidate_timesheet_summary_cursor_v1()','execute') then
    raise exception 'CANDIDATE_TIMESHEET_SUMMARY_CURSOR_ACL_INVALID';
  end if;

  v_cursor_before:=coalesce((public.candidate_timesheet_summary_cursor_v1()->>'cursor')::bigint,0);
  perform private._candidate_timesheet_summary_revision_upsert_v1(
    'TIMESHEET',v_timesheet_id,v_timesheet_id,v_contract_week_id
  );
  v_cursor_after:=coalesce((public.candidate_timesheet_summary_cursor_v1()->>'cursor')::bigint,0);
  if v_cursor_after<=v_cursor_before then
    raise exception 'CANDIDATE_TIMESHEET_SUMMARY_CURSOR_DID_NOT_ADVANCE';
  end if;

  perform set_config('request.jwt.claim.role','service_role',true);
  v_ping:=public.rpc_changes_ping(jsonb_build_object(
    '__candidate_timesheet_summary_watch',true,
    '__candidate_timesheet_summary_cursor',v_cursor_before
  ));
  if coalesce((v_ping->>'candidate_timesheet_summary_cursor')::bigint,0)<>v_cursor_after
     or jsonb_array_length(coalesce(v_ping->'candidate_timesheet_summary_changed_identities','[]'::jsonb))<>1
     or v_ping#>>'{candidate_timesheet_summary,changed_identities,0,identity_id}'<>v_timesheet_id::text
     or coalesce((v_ping->>'candidate_timesheet_summary_overflow')::boolean,true) then
    raise exception 'CANDIDATE_TIMESHEET_SUMMARY_HEARTBEAT_FIRST_USE_FAILED: %',v_ping;
  end if;

  create temporary table candidate_summary_workflow_trigger_fixture(
    anchor_timesheet_id uuid,
    target_timesheet_id uuid,
    contract_week_id uuid
  ) on commit drop;
  create trigger candidate_summary_workflow_trigger_fixture_trg
  after insert or update or delete on candidate_summary_workflow_trigger_fixture
  for each row execute function private._candidate_timesheet_summary_workflow_revision_trg_v1();
  insert into candidate_summary_workflow_trigger_fixture(
    anchor_timesheet_id,target_timesheet_id,contract_week_id
  ) values(v_timesheet_id,v_timesheet_id,v_contract_week_id);
  update candidate_summary_workflow_trigger_fixture
  set target_timesheet_id=gen_random_uuid();
  delete from candidate_summary_workflow_trigger_fixture;

  create temporary table candidate_summary_approval_trigger_fixture(workflow_id uuid) on commit drop;
  create trigger candidate_summary_approval_trigger_fixture_trg
  after insert or update or delete on candidate_summary_approval_trigger_fixture
  for each row execute function private._candidate_timesheet_summary_approval_revision_trg_v1();
  insert into candidate_summary_approval_trigger_fixture(workflow_id) values(v_workflow_id);
  update candidate_summary_approval_trigger_fixture set workflow_id=gen_random_uuid();
  delete from candidate_summary_approval_trigger_fixture;

  create temporary table candidate_summary_mail_trigger_fixture(payment_scope_json jsonb) on commit drop;
  create trigger candidate_summary_mail_trigger_fixture_trg
  after insert or update or delete on candidate_summary_mail_trigger_fixture
  for each row execute function private._candidate_timesheet_summary_mail_revision_trg_v1();
  insert into candidate_summary_mail_trigger_fixture(payment_scope_json)
  values(jsonb_build_object('candidate_workflow_id',v_workflow_id));
  update candidate_summary_mail_trigger_fixture
  set payment_scope_json=jsonb_build_object('candidate_manager_workflow_id',v_workflow_id);
  delete from candidate_summary_mail_trigger_fixture;

  if not exists(
    select 1 from private.candidate_timesheet_summary_revisions
    where identity_kind='TIMESHEET' and identity_id=v_timesheet_id
  ) or not exists(
    select 1 from private.candidate_timesheet_summary_revisions
    where identity_kind='CONTRACT_WEEK' and identity_id=v_contract_week_id
  ) then
    raise exception 'CANDIDATE_TIMESHEET_SUMMARY_TRIGGER_FIRST_USE_FAILED';
  end if;
end;
$candidate_timesheet_summary_refresh_verification$;

do $verification$
declare
  v_definition text;
  v_field text;
begin
  select pg_get_functiondef(p.oid)
  into v_definition
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public'
    and p.proname='candidate_app_timesheet_page_v1'
    and pg_get_function_identity_arguments(p.oid)=
      'p_session_id uuid, p_environment text, p_view text, p_cursor text, p_limit integer, p_now_utc timestamp with time zone';

  if v_definition is null then
    raise exception 'CANDIDATE_TIMESHEET_PAGE_FUNCTION_MISSING';
  end if;

  foreach v_field in array array[
    'expenses_pay_ex_vat',
    'mileage_pay_ex_vat',
    'travel_pay_ex_vat',
    'accommodation_pay_ex_vat',
    'other_pay_ex_vat'
  ] loop
    if position(
      format('COALESCE(totals.%1$s, base.%1$s, 0::numeric)',v_field)
      in v_definition
    )=0 and position(
      format('coalesce(totals.%1$s,base.%1$s,0)',v_field)
      in lower(v_definition)
    )=0 then
      raise exception 'CANDIDATE_TIMESHEET_CARD_BASE_EXPENSE_FALLBACK_MISSING:%',v_field;
    end if;
  end loop;

  if has_function_privilege(
       'anon',
       'public.candidate_app_timesheet_page_v1(uuid,text,text,text,integer,timestamp with time zone)',
       'EXECUTE'
     ) or has_function_privilege(
       'authenticated',
       'public.candidate_app_timesheet_page_v1(uuid,text,text,text,integer,timestamp with time zone)',
       'EXECUTE'
     ) then
    raise exception 'CANDIDATE_TIMESHEET_PAGE_BROWSER_EXECUTE_EXPOSED';
  end if;
  if not has_function_privilege(
       'service_role',
       'public.candidate_app_timesheet_page_v1(uuid,text,text,text,integer,timestamp with time zone)',
       'EXECUTE'
     ) then
    raise exception 'CANDIDATE_TIMESHEET_PAGE_SERVICE_EXECUTE_MISSING';
  end if;
end;
$verification$;

do $verification$
declare
  v_transition_definition text;
  v_replacement_definition text;
  v_read_definition text;
begin
  select pg_get_functiondef(
    'public.candidate_workflow_transition_atomic_v1(uuid,text,uuid,text,integer,jsonb,text,timestamptz)'::regprocedure
  ) into v_transition_definition;

  if position(
       'v_source_workflow.state not in (''REJECTED'',''REFUSED'')'
       in v_transition_definition
     )=0 then
    raise exception 'Candidate manager-refused resubmission authority is not installed';
  end if;

  if position(
       'current_week.id=v_source_workflow.contract_week_id'
       in v_transition_definition
     )=0
     or position(
       'current_week.contract_id is not distinct from v_source_workflow.contract_id'
       in v_transition_definition
     )=0
     or position(
       'current_week.week_ending_date is not distinct from v_source_workflow.week_ending_date'
       in v_transition_definition
     )=0
     or position(
       'v_source_workflow.creation_identity_json#>>''{derived,daily_booking_id}'''
       in v_transition_definition
     )=0 then
    raise exception 'Candidate manager-refused resubmission does not resolve the current weekly/Daily authority';
  end if;

  if position(
       'from public.contract_weeks current_week'
       in v_transition_definition
     )=0
     or position(
       'if v_week.timesheet_id is not null then'
       in v_transition_definition
     )=0
     or position(
       'current_timesheet.timesheet_id=v_week.timesheet_id'
       in v_transition_definition
     )=0
     or position(
       '''anchor_timesheet_id'',case when v_workflow_kind=''CONTRACT_EXPENSE'''
       in v_transition_definition
     )=0
     or position(
       'then v_source_workflow.anchor_timesheet_id else v_week.timesheet_id end'
       in v_transition_definition
     )=0 then
    raise exception 'Candidate manager-refused weekly resubmission is not bound to the exact editable Contract Week';
  end if;

  if position(
       'CANDIDATE_WORKFLOW_ANCHOR_MISMATCH'' using errcode=''55000'''
       in v_transition_definition
     )=0 then
    raise exception 'Candidate manager-refused anchor mismatch remains a retryable serialization failure';
  end if;

  select pg_get_functiondef(
    'private._candidate_rejection_replaced_v1(uuid)'::regprocedure
  ) into v_replacement_definition;

  if position(
       'v_rejected.state not in (''REJECTED'',''REFUSED'')'
       in v_replacement_definition
     )=0 then
    raise exception 'Candidate manager-refused replacement guard is not installed';
  end if;

  select pg_get_functiondef(
    'private._candidate_timesheet_primary_action_v1(text,jsonb,jsonb,uuid,uuid)'::regprocedure
  ) into v_read_definition;

  if position(
       'item->>''state''<>''REFUSED'''
       in v_read_definition
     )=0
     or position(
       'not private._candidate_rejection_replaced_v1('
       in v_read_definition
     )=0 then
    raise exception 'Candidate refused-card recovery still offers a second impossible direct replacement';
  end if;

  if v_transition_definition~*'pg_catalog\.(coalesce|nullif|least|greatest)\s*\('
     or v_replacement_definition~*'pg_catalog\.(coalesce|nullif|least|greatest)\s*\('
     or v_read_definition~*'pg_catalog\.(coalesce|nullif|least|greatest)\s*\(' then
    raise exception 'Candidate manager-refused resubmission authority contains an illegal conditional-expression prefix';
  end if;
end;
$verification$;

-- First-use proof of booked/blocked availability clearing and exact replay.
-- All synthetic Candidate, generation, availability and outbox rows roll back.


do $verification$
declare
  v_candidate uuid := '00000000-0000-4000-8000-00000000e956';
  v_source text := repeat('9',64);
  v_key text := 'CID1-956ABCDEFGHJKMNPQRS';
  v_today date := (clock_timestamp() at time zone 'Europe/London')::date;
  v_context jsonb := jsonb_build_object(
    'policy','SIGNED_SYSTEM_SYNC','environment','TEST','system_auth_verified',true,
    'nonce_consumed',true,'environment_trusted',true,'stable_operation_identity',true,
    'approved_source_mapping',true,'source_scope_ready',true,'authority_mode_compatible',true,
    'transition_ready',true);
  v_days jsonb; v_item jsonb; v_missing jsonb; v_result jsonb; v_replay jsonb;
  v_generation uuid; v_batch uuid := '00000000-0000-4000-8000-00000000e957';
  v_command uuid; v_version bigint; v_count integer;
begin
  insert into public.candidates(id,email,display_name,first_name,last_name,active,key_norm)
  values(v_candidate,'rota-clear-proof@example.invalid','Rota Clear Proof','Rota','Clear Proof',true,lower(v_key));
  select jsonb_agg(jsonb_build_object('date',(v_today+n)::text,'booked',false,
    'system_blocked',false,'source_row_hash',lpad(to_hex(n+1),64,'0')) order by n)
  into v_days from generate_series(0,13)n;
  v_item := jsonb_build_object('candidate_global_key',v_key,'candidate_source_hmac',v_source,
    'source_hmac_key_version',1,'source_event_id','rota-clear-proof-first-0001',
    'source_revision','rota-clear-proof-1','source_hash',repeat('a',64),
    'window_start',v_today::text,'days',v_days,'source_event_time',clock_timestamp()::text,
    'item_key','rota-clear-item-first-0001');
  v_result := public.candidate_daily_rota_generation_publish_atomic_v1(v_context,
    '00000000-0000-4000-8000-00000000e958','rota-clear-proof-initial-0001',
    jsonb_build_array(v_item),'01K2ABCDEFGHJKMNPQRSTVWXYZ');
  if v_result#>>'{outcomes,0,status}' is distinct from 'COMMITTED' then
    raise exception 'ROTA_CLEAR_PROOF: initial blank generation failed';
  end if;

  -- The old app's accepted preference is cleared only for booked/blocked dates.
  v_result := public.candidate_daily_legacy_availability_apply_atomic_v1(
    v_context||jsonb_build_object('policy','LEGACY_COMPAT','candidate_source_hmac',v_source),
    v_source,'00000000-0000-4000-8000-00000000e959','rota-clear-proof-availability-0001',
    jsonb_build_array(jsonb_build_object('date',v_today::text,'availability','LD'),
      jsonb_build_object('date',(v_today+1)::text,'availability','N'),
      jsonb_build_object('date',(v_today+2)::text,'availability','LD')),
    '01K2ABCDEFGHJKMNPQRSTVWXYZ');
  select canonical_version into v_version from private.candidate_daily_authority_scopes
    where environment='TEST' and candidate_id=v_candidate;
  if (select count(*) from public.candidate_daily_availability_days where environment='TEST'
      and candidate_id=v_candidate and preference<>'PENDING')<>3 then
    raise exception 'ROTA_CLEAR_PROOF: availability fixture did not seed three preferences';
  end if;
