    raise exception 'anon can execute Candidate workflow transition';
  end if;
  if exists(select 1 from pg_roles where rolname='authenticated')
     and has_function_privilege('authenticated',v_oid,'EXECUTE') then
    raise exception 'authenticated can execute Candidate workflow transition';
  end if;
  if exists(select 1 from pg_roles where rolname='service_role')
     and not has_function_privilege('service_role',v_oid,'EXECUTE') then
    raise exception 'service_role cannot execute Candidate workflow transition';
  end if;
end;
$verification$;

-- First-use proof for the mobile sequence that allocates a separate expense
-- carrier before it creates the Candidate workflow.  The carrier is MANUAL
-- storage, while the original worked Timesheet supplies eligibility only: a
-- later separate expense keeps the Candidate's chosen approval route.  Every
-- fixture write is rolled back.



update public.settings_defaults
set candidate_app_feature_flags_json=coalesce(candidate_app_feature_flags_json,'{}'::jsonb)
  || jsonb_build_object(
    'candidate_app_reads',true,
    'candidate_app_writes',true,
    'candidate_record_role_capabilities',true,
    'candidate_expense_atomic_placement',true,
    'candidate_manager_approval',true,
    'candidate_paper_qr',true
  )
where id=1;

do $verification$
declare
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_anchor_week uuid:=gen_random_uuid();
  v_anchor_timesheet uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_session uuid:=gen_random_uuid();
  v_workflow uuid:=gen_random_uuid();
  v_qr_anchor_week uuid:=gen_random_uuid();
  v_qr_anchor_timesheet uuid:=gen_random_uuid();
  v_qr_workflow uuid:=gen_random_uuid();
  v_carrier_week uuid;
  v_qr_carrier_week uuid;
  v_email text:='carrier-route-'||gen_random_uuid()::text||'@example.test';
  v_carrier jsonb;
  v_qr_carrier jsonb;
  v_created jsonb;
  v_replayed jsonb;
  v_qr_created jsonb;
  v_qr_replayed jsonb;
  v_before_timesheet jsonb;
  v_after_timesheet jsonb;
  v_before_financial jsonb;
  v_after_financial jsonb;
  v_qr_before_timesheet jsonb;
  v_qr_after_timesheet jsonb;
  v_qr_before_financial jsonb;
  v_qr_after_financial jsonb;
  v_definition text;
  v_compact_definition text;
begin
  select lower(pg_get_functiondef(to_regprocedure(
    'public.candidate_workflow_transition_atomic_v1(uuid,text,uuid,text,integer,jsonb,text,timestamptz)'
  ))) into v_definition;
  v_compact_definition:=regexp_replace(v_definition,'\s+','','g');
  if position(
       'case when v_workflow_kind=''contract_expense'' then v_anchor_week.timesheet_id else v_week.timesheet_id end'
       in v_definition
     )=0
     or position(
       'case when v_workflow_kind=''contract_expense'' then v_anchor_week.id else v_week.id end'
       in v_definition
     )=0
     or position(
       'if v_workflow_kind=''contract_expense'' and v_route_authority->>''route_family''=''qr'' then v_route:=''paper'''
       in regexp_replace(v_definition,'\s+',' ','g')
     )<>0 then
    raise exception 'Candidate expense creation no longer preserves anchor eligibility and independent route choice';
  end if;
  if v_definition~'pg_catalog\.(coalesce|nullif|least|greatest)\s*\(' then
    raise exception 'Candidate workflow transition contains illegal qualified conditional syntax';
  end if;
  if (select count(*) from regexp_matches(v_compact_definition,'selectdistincton\(','g'))<4
     or position(
       'coalesce(source_component.source_component_id,source_component.id)'
       in v_compact_definition
     )=0
     or position(
       'coalesce(component.source_component_id,component.id)'
       in v_compact_definition
     )=0
     or position(
       'source_component.source_content_sha256'
       in v_compact_definition
     )=0
     or position(
       'component.source_content_sha256'
       in v_compact_definition
     )=0 then
    raise exception 'Candidate expense carry/printed manifest no longer canonicalises one page per durable source identity';
  end if;

  insert into public.clients(id,name) values(v_client,'Carrier Route Verification Client');
  insert into public.candidates(id,email,active,key_norm)
  values(v_candidate,v_email,true,'GCK-CARRIER-'||replace(v_candidate::text,'-',''));
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,
    candidate_expenses_require_separate_timesheet,
    candidate_paper_submission_enabled,candidate_expense_invoice_email
  ) values(
    gen_random_uuid(),v_client,current_date-1,'ELECTRONIC',true,true,
    'expenses@example.test'
  );
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,
    pay_method_snapshot,week_ending_weekday_snapshot,default_submission_mode
  ) values(
    v_contract,v_candidate,v_client,current_date-30,current_date+30,
    'PAYE',extract(dow from current_date)::integer,'ELECTRONIC'
  );
  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    contract_id,week_ending_date,sheet_scope,line_type,submission_mode,
    r2_nurse_key,r2_auth_key
  ) values(
    v_anchor_timesheet,'CARRIER_ROUTE_'||replace(v_anchor_timesheet::text,'-',''),
    'GCK-CARRIER-'||replace(v_candidate::text,'-',''),
    'CARRIER HOSPITAL','CARRIER WARD','NURSE',
    v_contract,current_date,'WEEKLY','HOURS','ELECTRONIC',
    'carrier-route/candidate-signature','carrier-route/manager-signature'
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot,timesheet_id
  ) values(
    v_anchor_week,v_contract,current_date,'OPEN','ELECTRONIC',v_anchor_timesheet
  );
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,processing_status
  ) values(
    v_anchor_timesheet,1,v_candidate,v_client,8,'UNPROCESSED'
  );
  insert into public.candidate_app_accounts(
    id,environment,email_normalized,status
  ) values(v_account,'TEST',lower(v_email),'ACTIVE');
  insert into public.candidate_app_sessions(
    id,account_id,environment,selected_candidate_id,status,refresh_token_hash,
    expires_at_utc,absolute_expires_at_utc
  ) values(
    v_session,v_account,'TEST',v_candidate,'ACTIVE',decode(repeat('a7',32),'hex'),
    now()+interval '30 days',now()+interval '90 days'
  );

  select to_jsonb(t) into v_before_timesheet
  from public.timesheets t where t.timesheet_id=v_anchor_timesheet;
  select to_jsonb(tf) into v_before_financial
  from public.timesheets_financials tf
  where tf.timesheet_id=v_anchor_timesheet and tf.is_current=true;

  v_carrier:=public.expense_carrier_resolve_or_create_atomic_v1(
    v_candidate,'TEST',v_anchor_timesheet,null,
    'carrier-route:create-carrier',now()
  );
  if v_carrier->>'placement'<>'CREATE_CARRIER'
     or nullif(v_carrier->>'target_contract_week_id','') is null
     or nullif(v_carrier->>'target_timesheet_id','') is not null then
    raise exception 'Separate expense carrier was not created safely: %',v_carrier;
  end if;
  v_carrier_week:=(v_carrier->>'target_contract_week_id')::uuid;
  if not exists(
    select 1 from public.contract_weeks
    where id=v_carrier_week
      and contract_id=v_contract
      and week_ending_date=current_date
      and submission_mode_snapshot='MANUAL'
      and timesheet_id is null
  ) then
    raise exception 'Expense carrier no longer has the expected empty MANUAL storage shape';
  end if;

  v_created:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE',
      'scope','WEEKLY',
      'route','ELECTRONIC',
      'contract_id',v_contract,
      'contract_week_id',v_carrier_week,
      'anchor_timesheet_id',v_anchor_timesheet,
      'week_ending_date',current_date
    ),
    'carrier-route:create-workflow',now()
  );
  if coalesce((v_created->>'ok')::boolean,false)=false
     or v_created->>'state'<>'WORKER_DRAFT'
     or (v_created->>'workflow_id')::uuid is distinct from v_workflow then
    raise exception 'First expense-workflow creation was not accepted: %',v_created;
  end if;
  if not exists(
    select 1 from public.candidate_submission_workflows
    where id=v_workflow
      and workflow_kind='CONTRACT_EXPENSE'
      and route='ELECTRONIC'
      and contract_week_id=v_carrier_week
      and anchor_timesheet_id=v_anchor_timesheet
      and target_timesheet_id is null
  ) then
    raise exception 'Created expense workflow lost its carrier/anchor boundary';
  end if;

  v_replayed:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE',
      'scope','WEEKLY',
      'route','ELECTRONIC',
      'contract_id',v_contract,
      'contract_week_id',v_carrier_week,
      'anchor_timesheet_id',v_anchor_timesheet,
      'week_ending_date',current_date
    ),
    'carrier-route:create-workflow',now()+interval '1 second'
  );
  if coalesce((v_replayed->>'idempotent_replay')::boolean,false)=false
     or (v_replayed->>'workflow_id')::uuid is distinct from v_workflow
     or (select count(*) from public.candidate_submission_workflows
         where candidate_id=v_candidate)<>1
     or (select count(*) from public.contract_weeks
         where contract_id=v_contract and week_ending_date=current_date)<>2 then
    raise exception 'Expense workflow replay created duplicate state: %',v_replayed;
  end if;

  select to_jsonb(t) into v_after_timesheet
  from public.timesheets t where t.timesheet_id=v_anchor_timesheet;
  select to_jsonb(tf) into v_after_financial
  from public.timesheets_financials tf
  where tf.timesheet_id=v_anchor_timesheet and tf.is_current=true;
  if v_after_timesheet is distinct from v_before_timesheet
     or v_after_financial is distinct from v_before_financial
     or (select count(*) from public.timesheets_financials
         where candidate_id=v_candidate)<>1 then
    raise exception 'Expense workflow creation changed Timesheet financial authority';
  end if;

  -- A later expense may begin from a worked Timesheet whose QR pack is already
  -- pending, but it is a new claim and may use a different approval route.  An
  -- ELECTRONIC request therefore remains ELECTRONIC instead of being forced
  -- back to the earlier QR/PAPER route.
  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    contract_id,week_ending_date,sheet_scope,line_type,submission_mode,
    r2_nurse_key,r2_auth_key,qr_status,qr_token
  ) values(
    v_qr_anchor_timesheet,'CARRIER_QR_ROUTE_'||replace(v_qr_anchor_timesheet::text,'-',''),
    'GCK-CARRIER-'||replace(v_candidate::text,'-',''),
    'CARRIER QR HOSPITAL','CARRIER QR WARD','NURSE',
    v_contract,current_date-7,'WEEKLY','HOURS','ELECTRONIC',
    'carrier-qr-route/candidate-signature','carrier-qr-route/manager-signature',
    'PENDING','carrier-qr-route-token'
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot,timesheet_id
  ) values(
    v_qr_anchor_week,v_contract,current_date-7,'OPEN','ELECTRONIC',v_qr_anchor_timesheet
  );
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,processing_status
  ) values(
    v_qr_anchor_timesheet,1,v_candidate,v_client,8,'UNPROCESSED'
  );

  select to_jsonb(t) into v_qr_before_timesheet
  from public.timesheets t where t.timesheet_id=v_qr_anchor_timesheet;
  select to_jsonb(tf) into v_qr_before_financial
  from public.timesheets_financials tf
  where tf.timesheet_id=v_qr_anchor_timesheet and tf.is_current=true;

  v_qr_carrier:=public.expense_carrier_resolve_or_create_atomic_v1(
    v_candidate,'TEST',v_qr_anchor_timesheet,null,
    'carrier-qr-route:create-carrier',now()
  );
  if v_qr_carrier->>'placement'<>'CREATE_CARRIER'
     or nullif(v_qr_carrier->>'target_contract_week_id','') is null
     or nullif(v_qr_carrier->>'target_timesheet_id','') is not null then
    raise exception 'QR-backed separate expense carrier was not created safely: %',v_qr_carrier;
  end if;
  v_qr_carrier_week:=(v_qr_carrier->>'target_contract_week_id')::uuid;

  v_qr_created:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_qr_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE',
      'scope','WEEKLY',
      'route','ELECTRONIC',
      'contract_id',v_contract,
      'contract_week_id',v_qr_carrier_week,
      'anchor_timesheet_id',v_qr_anchor_timesheet,
      'week_ending_date',current_date-7
    ),
    'carrier-qr-route:create-workflow',now()
  );
  if coalesce((v_qr_created->>'ok')::boolean,false)=false
     or v_qr_created->>'state'<>'WORKER_DRAFT'
     or (v_qr_created->>'workflow_id')::uuid is distinct from v_qr_workflow then
    raise exception 'QR-backed expense-workflow creation was not accepted: %',v_qr_created;
  end if;
  if not exists(
    select 1 from public.candidate_submission_workflows
    where id=v_qr_workflow
      and workflow_kind='CONTRACT_EXPENSE'
      and route='ELECTRONIC'
      and contract_week_id=v_qr_carrier_week
      and anchor_timesheet_id=v_qr_anchor_timesheet
      and target_timesheet_id is null
      and creation_identity_json#>>'{request,initial_route}'='ELECTRONIC'
      and creation_identity_json#>>'{derived,initial_route}'='ELECTRONIC'
  ) then
    raise exception 'QR-backed expense workflow lost request/derived route authority';
  end if;

  v_qr_replayed:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_qr_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE',
      'scope','WEEKLY',
      'route','ELECTRONIC',
      'contract_id',v_contract,
      'contract_week_id',v_qr_carrier_week,
      'anchor_timesheet_id',v_qr_anchor_timesheet,
      'week_ending_date',current_date-7
    ),
    'carrier-qr-route:create-workflow',now()+interval '1 second'
  );
  if coalesce((v_qr_replayed->>'idempotent_replay')::boolean,false)=false
     or (v_qr_replayed->>'workflow_id')::uuid is distinct from v_qr_workflow
     or (select count(*) from public.candidate_submission_workflows
         where candidate_id=v_candidate)<>2
     or (select count(*) from public.contract_weeks
         where contract_id=v_contract and week_ending_date=current_date-7)<>2 then
    raise exception 'QR-backed expense replay created duplicate state: %',v_qr_replayed;
  end if;

  select to_jsonb(t) into v_qr_after_timesheet
  from public.timesheets t where t.timesheet_id=v_qr_anchor_timesheet;
  select to_jsonb(tf) into v_qr_after_financial
  from public.timesheets_financials tf
  where tf.timesheet_id=v_qr_anchor_timesheet and tf.is_current=true;
  if v_qr_after_timesheet is distinct from v_qr_before_timesheet
     or v_qr_after_financial is distinct from v_qr_before_financial
     or (select count(*) from public.timesheets_financials
         where candidate_id=v_candidate)<>2 then
    raise exception 'QR-backed expense creation changed Timesheet financial authority';
  end if;

  -- Once the electronic workflow is manager-approved, finalisation must reuse
  -- the exact carrier it reserved before approval. This remains true after the
  -- Client becomes import-authoritative; no extra empty carrier may be created.
  update public.client_settings set is_nhsp=true where client_id=v_client;
  update public.candidate_submission_workflows
  set state='READY_TO_FINALISE',manager_approved_at_utc=now(),updated_at_utc=now()
  where id=v_workflow;
  v_replayed:=public.expense_carrier_resolve_or_create_atomic_v1(
    v_candidate,'TEST',v_anchor_timesheet,null,
    'carrier-route:finalise-reserved-carrier',now()
  );
  if v_replayed->>'placement'<>'REUSE_CARRIER'
     or v_replayed->>'reason_code'<>'WORKFLOW_CARRIER_RESERVED'
     or (v_replayed->>'target_contract_week_id')::uuid is distinct from v_carrier_week
     or nullif(v_replayed->>'target_timesheet_id','') is not null
     or (select count(*) from public.contract_weeks
         where contract_id=v_contract and week_ending_date=current_date)<>2 then
    raise exception 'Finalisation did not reuse its reserved import expense carrier: %',v_replayed;
  end if;
end;
$verification$;

-- Rollback-contained first-use proof for the two candidate-source terminal
-- failures observed in the real TEST Banking Pay refresh. Withdrawn history
-- is not a current booking-family member, while every non-withdrawn identity
-- still needs the existing financial owner. A genuinely empty, fully sealed
-- candidate build can advance to the existing zero-line publication stage
-- without any Draft, provider or payment mutation.

SET LOCAL statement_timeout='30s';

DO $verification$
DECLARE
  v_snapshot_id uuid:=gen_random_uuid();
  v_actor_id uuid:=gen_random_uuid();
  v_session_id uuid:=gen_random_uuid();
  v_dependency_candidate_id uuid:=gen_random_uuid();
  v_empty_candidate_id uuid:=gen_random_uuid();
  v_dependency_job_id uuid:=gen_random_uuid();
  v_empty_job_id uuid:=gen_random_uuid();
  v_dependency_build_id uuid:=gen_random_uuid();
  v_empty_build_id uuid:=gen_random_uuid();
  v_empty_attempt_id uuid:=gen_random_uuid();
  v_empty_attempt_nonce uuid:=gen_random_uuid();
  v_dependency_run_id uuid:=gen_random_uuid();
  v_empty_run_id uuid:=gen_random_uuid();
  v_root_timesheet_id uuid:=gen_random_uuid();
  v_revoked_timesheet_id uuid:=gen_random_uuid();
  v_active_unowned_timesheet_id uuid:=gen_random_uuid();
  v_booking_id text:='BPAY-REFRESH-VERIFY-'||gen_random_uuid()::text;
  v_prefix text:='BANKING_PAY_SOURCE_REFRESH_VERIFY:'||gen_random_uuid()::text;
  v_result jsonb;
  v_capture_result jsonb;
  v_definition text;
  v_row record;
  v_case_count_before bigint;
  v_now timestamptz:=clock_timestamp();
BEGIN
  SELECT pg_get_functiondef(
    'private.pay_workbench_timesheet_dependency_closure_v2(uuid,jsonb,integer)'::regprocedure
  )||E'\n'||pg_get_functiondef(
    'private.pay_workbench_reconcile_empty_scope_v1(uuid,uuid,uuid,uuid)'::regprocedure
  )||E'\n'||pg_get_functiondef(
    'public.pay_sync_overpayments_from_preview(date,date,uuid,text,uuid[],jsonb,uuid,uuid[],uuid[])'::regprocedure
  ) INTO STRICT v_definition;
  IF v_definition ~* 'pg_catalog\.(coalesce|nullif|least|greatest)\s*\(' THEN
    RAISE EXCEPTION 'BANKING_PAY_SOURCE_REFRESH_ILLEGAL_CONDITIONAL_PREFIX';
  END IF;

  IF has_function_privilege('anon',
       'private.pay_workbench_reconcile_empty_scope_v1(uuid,uuid,uuid,uuid)','EXECUTE')
     OR has_function_privilege('authenticated',
       'private.pay_workbench_reconcile_empty_scope_v1(uuid,uuid,uuid,uuid)','EXECUTE')
     OR has_function_privilege('service_role',
       'private.pay_workbench_reconcile_empty_scope_v1(uuid,uuid,uuid,uuid)','EXECUTE')
     OR NOT has_function_privilege('service_role',
       'public.pay_sync_overpayments_from_preview(date,date,uuid,text,uuid[],jsonb,uuid,uuid[],uuid[])',
       'EXECUTE') THEN
    RAISE EXCEPTION 'BANKING_PAY_SOURCE_REFRESH_ACL_INVALID';
  END IF;

  INSERT INTO public.banking_pay_snapshot_runs(
    id,pay_date,week_ending_cutoff,pay_week_start,eligibility_from_date,
    eligibility_to_date,status,is_active
  ) VALUES (
    v_snapshot_id,DATE '2099-03-06',DATE '2099-03-01',DATE '2099-02-23',
    DATE '2099-01-01',DATE '2099-03-01','OPEN',false
  );

  INSERT INTO public.tms_users(id,email,password_hash,role,is_active)
  VALUES (v_actor_id,
    'bpay-source-refresh-'||replace(v_actor_id::text,'-','')||'@example.invalid',
    'UNUSABLE_ROLLBACK_VERIFIER','admin',true);

  INSERT INTO public.candidates(id,display_name,tms_ref,pay_method) VALUES
    (v_dependency_candidate_id,v_prefix||':DEPENDENCY',v_prefix||':DEPENDENCY','PAYE'),
    (v_empty_candidate_id,v_prefix||':EMPTY',v_prefix||':EMPTY','PAYE');

  INSERT INTO public.app_change_counters(entity_key,seq) VALUES
    ('pay_candidate:'||v_dependency_candidate_id::text,1),
    ('pay_candidate:'||v_empty_candidate_id::text,1)
  ON CONFLICT(entity_key) DO UPDATE SET seq=EXCLUDED.seq;

  INSERT INTO public.banking_pay_workbench_sessions(
    id,actor_user_id,pay_date,week_ending_cutoff,session_signature,
    source_snapshot_run_id,status,version
  ) VALUES (
    v_session_id,v_actor_id,DATE '2099-03-06',DATE '2099-03-01',
    v_prefix||':SESSION',v_snapshot_id,'OPEN',1
  );

  INSERT INTO private.banking_pay_workbench_candidate_scope_registry AS registry(
    candidate_id,initialisation_status,dirty_generation,evaluated_generation,
    current_source_change_seq,last_dirty_reason,last_evaluated_at_utc,
    initialised_at_utc,last_dirtied_at_utc,created_at_utc,updated_at_utc
  ) VALUES
    (v_dependency_candidate_id,'READY',1,1,1,'ROLLBACK_VERIFICATION',
      v_now,v_now,v_now,v_now,v_now),
    (v_empty_candidate_id,'READY',1,1,1,'ROLLBACK_VERIFICATION',
      v_now,v_now,v_now,v_now,v_now)
  ON CONFLICT(candidate_id) DO UPDATE SET
    initialisation_status='READY',dirty_generation=1,evaluated_generation=1,
    current_source_change_seq=1,current_build_id=NULL,
    last_dirty_reason='ROLLBACK_VERIFICATION',last_evaluated_at_utc=clock_timestamp(),
    initialised_at_utc=COALESCE(
      registry.initialised_at_utc,
      clock_timestamp()),failure_json='{}'::jsonb,updated_at_utc=clock_timestamp();

  INSERT INTO public.banking_pay_workbench_jobs(
    id,job_type,status,priority,run_at_utc,attempt_count,max_attempts,dedupe_key,
    snapshot_run_id,session_id,candidate_id,payload_json,economic_build_id,
    private_stage,private_cursor_kind,private_cursor_json,private_stage_version,
    created_at_utc,updated_at_utc
  ) VALUES
    (v_dependency_job_id,'WORKBENCH_CANDIDATE_SOURCE_BUILD','QUEUED',40,
      clock_timestamp(),0,8,v_prefix||':DEPENDENCY_JOB',v_snapshot_id,
      v_session_id,v_dependency_candidate_id,jsonb_build_object(
        'session_id',v_session_id,'session_version',1,'source_change_seq',1,
        'source_build_run_id',v_dependency_run_id
      ),NULL,'BUILD_INITIALISE','BUILD_INITIALISE','{}'::jsonb,1,
      clock_timestamp(),clock_timestamp()),
    (v_empty_job_id,'WORKBENCH_CANDIDATE_SOURCE_BUILD','QUEUED',40,
      clock_timestamp(),0,8,v_prefix||':EMPTY_JOB',v_snapshot_id,
      v_session_id,v_empty_candidate_id,jsonb_build_object(
        'session_id',v_session_id,'session_version',1,'source_change_seq',1,
        'source_build_run_id',v_empty_run_id
      ),NULL,'BUILD_INITIALISE','BUILD_INITIALISE','{}'::jsonb,1,
      clock_timestamp(),clock_timestamp());

  INSERT INTO public.banking_pay_workbench_session_scope(
    session_id,candidate_id,scope_ordinal,status,seeded,dirty,pending_job_id
  ) VALUES (
    v_session_id,v_empty_candidate_id,1,'SOURCE_BUILD_PENDING',true,true,v_empty_job_id
  );

  INSERT INTO private.banking_pay_workbench_economic_builds(
    id,candidate_id,session_id,session_version,source_snapshot_run_id,
    source_build_run_id,source_job_id,captured_candidate_generation,
    source_change_seq,status,private_stage,stage_version,
    seed_scope_count,seed_scope_digest,seed_scope_sealed_at_utc,
    scope_count,scope_cursor_json,created_at_utc,updated_at_utc
  ) VALUES (
    v_dependency_build_id,v_dependency_candidate_id,v_session_id,1,v_snapshot_id,
    v_dependency_run_id,v_dependency_job_id,1,1,'COLLECTING','DEPENDENCY_CLOSURE',1,
    1,md5(v_root_timesheet_id::text),v_now,1,
    '{"terminal":true}'::jsonb,v_now,v_now
  );

  UPDATE private.banking_pay_workbench_candidate_scope_registry
  SET current_build_id=v_dependency_build_id,updated_at_utc=clock_timestamp()
  WHERE candidate_id=v_dependency_candidate_id;

  INSERT INTO public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,week_ending_date,status,is_current,version
  ) VALUES
    (v_root_timesheet_id,v_booking_id,v_prefix,'VERIFY','VERIFY','VERIFY',
      DATE '2099-03-01','RECEIVED',true,3),
    (v_revoked_timesheet_id,v_booking_id,v_prefix,'VERIFY','VERIFY','VERIFY',
      DATE '2099-03-01','REVOKED',false,1);

  INSERT INTO private.banking_pay_workbench_economic_build_scope(
    build_id,timesheet_id,candidate_id,root_timesheet_id,seed_reasons,
    dependency_reasons,captured_dirty_generation,closure_status,
    required_fact_families,completed_fact_families
  ) VALUES (
    v_dependency_build_id,v_root_timesheet_id,v_dependency_candidate_id,
    v_root_timesheet_id,ARRAY['ROLLBACK_VERIFICATION'],ARRAY[]::text[],1,
    'PENDING',ARRAY[]::text[],ARRAY[]::text[]
  );

  v_result:=private.pay_workbench_timesheet_dependency_closure_v2(
    v_dependency_build_id,
    jsonb_build_object(
      'cursor_kind','DEPENDENCY_CLOSURE','cursor_version',1,
      'build_id',v_dependency_build_id,'candidate_id',v_dependency_candidate_id,
      'frontier_timesheet_id',v_root_timesheet_id,'dependency_family_ordinal',5,
      'processed_edge_count',0,'processed_emission_count',0,'page_number',1
    ),25
  );
  IF EXISTS(
       SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
       WHERE build_id=v_dependency_build_id AND timesheet_id=v_revoked_timesheet_id
     ) OR COALESCE((v_result->>'inserted_scope_count')::integer,0)<>0 THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_REVOKED_HISTORY_ENTERED_CURRENT_SCOPE',
      DETAIL=v_result::text;
  END IF;

  INSERT INTO public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,week_ending_date,status,is_current,version
  ) VALUES (
    v_active_unowned_timesheet_id,v_booking_id,v_prefix,'VERIFY','VERIFY','VERIFY',
    DATE '2099-03-01','RECEIVED',false,2
  );
  UPDATE private.banking_pay_workbench_economic_build_scope
  SET closure_status='PENDING',closure_family_ordinal=1,closure_last_edge_key=NULL,
      updated_at_utc=clock_timestamp()
  WHERE build_id=v_dependency_build_id AND timesheet_id=v_root_timesheet_id;

  BEGIN
    PERFORM private.pay_workbench_timesheet_dependency_closure_v2(
      v_dependency_build_id,
      jsonb_build_object(
        'cursor_kind','DEPENDENCY_CLOSURE','cursor_version',1,
        'build_id',v_dependency_build_id,'candidate_id',v_dependency_candidate_id,
        'frontier_timesheet_id',v_root_timesheet_id,'dependency_family_ordinal',5,
        'processed_edge_count',0,'processed_emission_count',0,'page_number',1
      ),25
    );
    RAISE EXCEPTION 'BANKING_PAY_ACTIVE_UNOWNED_DEPENDENCY_WAS_ACCEPTED';
  EXCEPTION WHEN SQLSTATE '23514' THEN
    IF SQLERRM IS DISTINCT FROM 'PAY_WORKBENCH_DEPENDENCY_IDENTITY_CONFLICT' THEN
      RAISE;
    END IF;
  END;

  INSERT INTO private.banking_pay_workbench_economic_builds(
    id,candidate_id,session_id,session_version,source_snapshot_run_id,
    source_build_run_id,source_job_id,captured_candidate_generation,
    source_change_seq,status,private_stage,stage_version,
    seed_scope_count,seed_scope_digest,seed_scope_sealed_at_utc,
    scope_count,dependency_node_count,dependency_edge_count,tagged_edge_count,
    row_seal_count,last_stable_ordinal,scope_cursor_json,closure_cursor_json,
    dependency_edge_stream_complete,dependency_edge_stream_digest,
    edge_tag_stream_complete,edge_tag_digest,unit_digest,scope_digest,
    dependency_digest,sealed_fingerprint_digest,dependency_closure_sealed_at_utc,
    attestation_json,ready_at_utc,created_at_utc,updated_at_utc
  ) VALUES (
    v_empty_build_id,v_empty_candidate_id,v_session_id,1,v_snapshot_id,
    v_empty_run_id,v_empty_job_id,1,1,'RECONCILING','RECONCILE_EXECUTE',1,
    0,md5(''),v_now,0,0,0,0,0,0,'{"terminal":true}'::jsonb,
    '{"terminal":true,"seal_phase":"COMPLETE"}'::jsonb,true,md5(''),
    true,md5(''),md5(''),md5(''),md5(''),md5(''),v_now,
    jsonb_build_object(
      'execution_profile_version',1,'reconciliation_optimization_version',0,
      'effect_plan_sealed',true,'effect_plan_count',0,
      'effect_plan_digest',md5('[]'),'effect_plan_created_at_utc',clock_timestamp()
    ),v_now,v_now,v_now
  );

  UPDATE private.banking_pay_workbench_candidate_scope_registry
  SET current_build_id=v_empty_build_id,updated_at_utc=clock_timestamp()
  WHERE candidate_id=v_empty_candidate_id;

  UPDATE public.banking_pay_workbench_jobs
  SET status='RUNNING',attempt_count=1,economic_build_id=v_empty_build_id,
    private_stage='RECONCILE_EXECUTE',private_cursor_kind='RECONCILE_EXECUTE',
    private_cursor_json=jsonb_build_object(
      'cursor_kind','RECONCILE_EXECUTE','cursor_version',1,
      'build_id',v_empty_build_id,'candidate_id',v_empty_candidate_id,
      'effect_plan_digest',md5('[]')
    ),private_stage_version=1,started_at_utc=clock_timestamp(),
    updated_at_utc=clock_timestamp()
  WHERE id=v_empty_job_id;

  INSERT INTO private.banking_pay_workbench_stage_attempts(
    id,job_id,build_id,candidate_id,private_stage,attempt_number,attempt_nonce,
    worker_id,lane_identity,captured_candidate_generation,
    captured_source_change_seq,execution_profile_version,attempt_status,
    started_at_utc,lease_expires_at_utc,created_at_utc,updated_at_utc
  ) VALUES (
    v_empty_attempt_id,v_empty_job_id,v_empty_build_id,v_empty_candidate_id,
    'RECONCILE_EXECUTE',1,v_empty_attempt_nonce,'ROLLBACK_VERIFIER',
    'ROLLBACK_VERIFIER_LANE',1,1,1,'STARTED',v_now,
    v_now+interval '10 minutes',v_now,v_now
  );

  CREATE TEMP TABLE pg_temp._bpay_wb_sync_context_v1(
    job_id uuid NOT NULL,build_id uuid NOT NULL,attempt_id uuid NOT NULL,
    attempt_nonce uuid NOT NULL,build_token uuid NOT NULL,candidate_id uuid NOT NULL,
    private_stage text NOT NULL,captured_generation bigint NOT NULL,
    source_change_seq bigint NOT NULL,created_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;
  INSERT INTO pg_temp._bpay_wb_sync_context_v1
  SELECT v_empty_job_id,v_empty_build_id,v_empty_attempt_id,v_empty_attempt_nonce,
    build_row.build_token,v_empty_candidate_id,'RECONCILE_EXECUTE',1,1,v_now
  FROM private.banking_pay_workbench_economic_builds AS build_row
  WHERE build_row.id=v_empty_build_id;
  PERFORM pg_catalog.set_config(
    'cloudtms.pay_workbench_execution_profile_version','1',true
  );

  -- Match the controller's rollback-contained capture protocol exactly. The
  -- public wrapper must expose an empty effect array instead of rejecting the
  -- legacy authoritative-empty result shape.
  BEGIN
    PERFORM pg_catalog.set_config(
      'cloudtms.pay_workbench_effect_capture_mode','capture',true
    );
    v_capture_result:=public.pay_sync_overpayments_from_preview(
      DATE '2099-03-06',DATE '2099-03-01',v_actor_id,'PAYE',
      ARRAY[v_empty_candidate_id],'{}'::jsonb,NULL,NULL,NULL
    );
    IF COALESCE((v_capture_result->>'effect_plan_capture')::boolean,false) IS NOT TRUE
       OR v_capture_result->'captured_effects' IS DISTINCT FROM '[]'::jsonb
       OR COALESCE((v_capture_result->>'explicit_empty_timesheet_scope')::boolean,false)
          IS NOT TRUE THEN
      RAISE EXCEPTION USING MESSAGE='BANKING_PAY_EMPTY_SCOPE_CAPTURE_INVALID',
        DETAIL=v_capture_result::text;
    END IF;
    RAISE EXCEPTION 'BANKING_PAY_EMPTY_SCOPE_CAPTURE_ROLLBACK' USING ERRCODE='PZ001';
  EXCEPTION WHEN SQLSTATE 'PZ001' THEN
    NULL;
  END;

  SELECT count(*) INTO v_case_count_before
  FROM public.pay_advances WHERE candidate_id=v_empty_candidate_id;

  v_result:=public.pay_sync_overpayments_from_preview(
    DATE '2099-03-06',DATE '2099-03-01',v_actor_id,'PAYE',
    ARRAY[v_empty_candidate_id],'{}'::jsonb,NULL,NULL,NULL
  );
  SELECT status,private_stage,scope_count,canonical_count,canonical_digest,
    attestation_json->>'policy_x_authority_scope' AS policy_scope,
    attestation_json->>'empty_scope_reconciliation_version' AS empty_version
  INTO STRICT v_row
  FROM private.banking_pay_workbench_economic_builds
  WHERE id=v_empty_build_id;
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'explicit_empty_timesheet_scope')::boolean,false)
        IS NOT TRUE
     OR v_row.status IS DISTINCT FROM 'RECONCILED'
     OR v_row.private_stage IS DISTINCT FROM 'SOURCE_PUBLISH'
     OR v_row.scope_count<>0 OR v_row.canonical_count<>0
     OR v_row.canonical_digest IS DISTINCT FROM md5('')
     OR v_row.policy_scope IS DISTINCT FROM 'PRE_DRAFT_LIVE_TRUTH'
     OR v_row.empty_version IS DISTINCT FROM '1'
     OR EXISTS(
       SELECT 1 FROM private.banking_pay_workbench_canonical_stage_lines
       WHERE build_id=v_empty_build_id
     )
     OR (SELECT count(*) FROM public.pay_advances
         WHERE candidate_id=v_empty_candidate_id) IS DISTINCT FROM v_case_count_before THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_EMPTY_SCOPE_RECONCILIATION_INVALID',
      DETAIL=jsonb_build_object('result',v_result,'build',to_jsonb(v_row))::text;
  END IF;

  RAISE NOTICE 'PASS: revoked booking history is excluded; active unowned identities fail closed; zero-scope reconciliation reaches SOURCE_PUBLISH without finance mutation.';
END;
$verification$;

-- Rollback-contained first-use proof for historical queued source-build jobs
-- which predate the current authority-fingerprint contract.  These rows are
-- refresh instructions only.  The verifier proves that they fail the current
-- claim, are terminalised under Candidate serial authority, are replaced only
-- through the canonical enqueue owner, cannot remain current, and do not touch
-- Draft, batch, provider, payment, settlement or remittance authority.

SET LOCAL statement_timeout='30s';

DO $verification$
DECLARE
  v_snapshot_id uuid:=gen_random_uuid();
  v_actor_id uuid:=gen_random_uuid();
  v_session_id uuid:=gen_random_uuid();
  v_candidate_repair uuid:=gen_random_uuid();
  v_candidate_preserve uuid:=gen_random_uuid();
  v_invalid_job_one uuid:=gen_random_uuid();
  v_invalid_job_two uuid:=gen_random_uuid();
  v_invalid_stray_job uuid:=gen_random_uuid();
  v_preserved_owner_id uuid:=NULL::uuid;
  v_repaired_owner_id uuid:=NULL::uuid;
  v_prefix text:='BANKING_PAY_INVALID_SOURCE_AUTHORITY_VERIFY:' || gen_random_uuid()::text;
  v_result jsonb:='{}'::jsonb;
  v_replay_result jsonb:='{}'::jsonb;
  v_claim_error text:=NULL::text;
  v_owner record;
  v_terminal record;
  v_operations_before bigint:=0;
  v_batches_before bigint:=0;
  v_provider_before bigint:=0;
  v_settlement_before bigint:=0;
  v_remittance_before bigint:=0;
BEGIN
  UPDATE public.settings_defaults
  SET banking_pay_same_authority_build_election_v1_enabled=true
  WHERE id=1;

  INSERT INTO public.banking_pay_snapshot_runs(
    id,pay_date,week_ending_cutoff,pay_week_start,eligibility_from_date,
    eligibility_to_date,status,is_active
  ) VALUES (
    v_snapshot_id,DATE '2099-01-09',DATE '2099-01-04',DATE '2098-12-29',
    DATE '2098-12-01',DATE '2099-01-04','OPEN',false
  );

  INSERT INTO public.tms_users(id,email,password_hash,role,is_active)
  VALUES (
    v_actor_id,
    'bpay-invalid-authority-' || replace(v_actor_id::text,'-','') || '@example.invalid',
    'UNUSABLE_ROLLBACK_VERIFIER','admin',true
  );

  INSERT INTO public.candidates(id,display_name,tms_ref) VALUES
    (v_candidate_repair,v_prefix || ':REPAIR',v_prefix || ':REPAIR'),
    (v_candidate_preserve,v_prefix || ':PRESERVE',v_prefix || ':PRESERVE');

  INSERT INTO public.banking_pay_workbench_sessions(
    id,actor_user_id,pay_date,week_ending_cutoff,session_signature,
    source_snapshot_run_id,status,version,discarded_at_utc
  ) VALUES (
    v_session_id,v_actor_id,DATE '2099-01-09',DATE '2099-01-04',
    v_prefix || ':SESSION',v_snapshot_id,'OPEN',7,NULL
  );

  INSERT INTO public.app_change_counters(entity_key,seq) VALUES
    ('pay_candidate:' || v_candidate_repair::text,31),
    ('pay_candidate:' || v_candidate_preserve::text,41)
  ON CONFLICT(entity_key) DO UPDATE SET seq=EXCLUDED.seq;

  UPDATE private.banking_pay_workbench_candidate_scope_registry AS registry_row
  SET initialisation_status='READY',
      dirty_generation=CASE
        WHEN registry_row.candidate_id=v_candidate_repair THEN 3 ELSE 4 END,
      evaluated_generation=CASE
        WHEN registry_row.candidate_id=v_candidate_repair THEN 2 ELSE 3 END,
      current_source_change_seq=CASE
        WHEN registry_row.candidate_id=v_candidate_repair THEN 31 ELSE 41 END,
      last_dirty_reason='VERIFICATION_DIRTY',
      last_dirtied_at_utc=clock_timestamp(),
      last_evaluated_at_utc=clock_timestamp(),
      initialised_at_utc=clock_timestamp(),
      failure_json='{}'::jsonb,
      updated_at_utc=clock_timestamp()
  WHERE registry_row.candidate_id IN (v_candidate_repair,v_candidate_preserve);

  INSERT INTO public.banking_pay_workbench_jobs(
    id,job_type,status,priority,run_at_utc,attempt_count,max_attempts,dedupe_key,
    snapshot_run_id,session_id,candidate_id,payload_json,economic_build_id,
    private_stage,private_cursor_kind,private_cursor_json,private_stage_version
  ) VALUES
    (v_invalid_job_one,'WORKBENCH_CANDIDATE_SOURCE_BUILD','QUEUED',10,
      clock_timestamp(),0,8,v_prefix || ':INVALID_ONE',v_snapshot_id,
      v_session_id,v_candidate_repair,pg_catalog.jsonb_build_object(
        'session_id',v_session_id::text,'session_version',7,
        'source_change_seq',31,'scope_change_generation',3,
        'source_build_run_id','10000000-0000-4000-8000-000000001301',
        'refresh_scope_kind','CANDIDATE_FULL_LIVE','pay_channel_scope','ALL',
        'reason','DIRTY_TRIGGER:CONTRACTS:UPDATE'
      ),NULL,'BUILD_INITIALISE','BUILD_INITIALISE','{}'::jsonb,1),
    (v_invalid_job_two,'WORKBENCH_CANDIDATE_SOURCE_BUILD','QUEUED',20,
      clock_timestamp(),0,8,v_prefix || ':INVALID_TWO',v_snapshot_id,
      v_session_id,v_candidate_repair,pg_catalog.jsonb_build_object(
        'session_id',v_session_id::text,'session_version',7,
        'source_change_seq',31,'scope_change_generation',3,
        'source_build_run_id','10000000-0000-4000-8000-000000001302',
        'authority_fingerprint_version',3,
        'authority_fingerprint',repeat('a',64),
        'required_physical_publication_contract_version','not-a-version',
        'refresh_scope_kind','CANDIDATE_FULL_LIVE','pay_channel_scope','ALL',
        'reason','DIRTY_TRIGGER:CLIENT_SETTINGS:UPDATE'
      ),NULL,'BUILD_INITIALISE','BUILD_INITIALISE','{}'::jsonb,1);

  INSERT INTO public.banking_pay_workbench_session_scope(
    session_id,candidate_id,scope_ordinal,status,seeded,dirty,pending_job_id,error_json
  ) VALUES
    (v_session_id,v_candidate_repair,1,'SOURCE_BUILD_PENDING',true,true,v_invalid_job_one,NULL),
    (v_session_id,v_candidate_preserve,2,'READY',true,false,NULL,NULL);

  INSERT INTO public.banking_pay_workbench_session_candidate_state(
    session_id,candidate_id,status,source_change_seq,session_version,pending_job_id,last_error_json
  ) VALUES
    (v_session_id,v_candidate_repair,'PENDING',31,7,v_invalid_job_one,NULL),
    (v_session_id,v_candidate_preserve,'READY',41,7,NULL,NULL);

  v_result:=public.pay_workbench_enqueue_candidate_refresh(
    p_snapshot_run_id=>v_snapshot_id,
    p_candidate_id=>v_candidate_preserve,
    p_reason=>'VERIFICATION_CURRENT_CANONICAL_OWNER',
    p_actor_user_id=>v_actor_id,
    p_payload_json=>pg_catalog.jsonb_build_object(
      'session_id',v_session_id::text,
      'source_session_id',v_session_id::text,
      'candidate_id',v_candidate_preserve::text,
      'session_version',7,
      'source_change_seq',41,
      'refresh_scope_kind','CANDIDATE_FULL_LIVE',
      'pay_channel_scope','ALL',
      'force_legacy',true,
      'force_broad_legacy',true
    )
  );
  IF COALESCE(v_result->>'job_id','') !~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_INVALID_AUTHORITY_CANONICAL_FIXTURE_NOT_CREATED',
      DETAIL=v_result::text;
  END IF;
  v_preserved_owner_id:=(v_result->>'job_id')::uuid;

  INSERT INTO public.banking_pay_workbench_jobs(
    id,job_type,status,priority,run_at_utc,attempt_count,max_attempts,dedupe_key,
    snapshot_run_id,session_id,candidate_id,payload_json,economic_build_id,
    private_stage,private_cursor_kind,private_cursor_json,private_stage_version
  ) VALUES (
    v_invalid_stray_job,'WORKBENCH_CANDIDATE_SOURCE_BUILD','QUEUED',30,
    clock_timestamp(),0,8,v_prefix || ':INVALID_STRAY',v_snapshot_id,
    v_session_id,v_candidate_preserve,pg_catalog.jsonb_build_object(
      'session_id',v_session_id::text,'session_version',7,
      'source_change_seq',41,'scope_change_generation',4,
      'source_build_run_id','10000000-0000-4000-8000-000000001303',
      'refresh_scope_kind','CANDIDATE_FULL_LIVE','pay_channel_scope','ALL',
      'reason','DIRTY_TRIGGER:CONTRACTS:UPDATE'
    ),NULL,'BUILD_INITIALISE','BUILD_INITIALISE','{}'::jsonb,1
  );

  SELECT COUNT(*) INTO v_operations_before FROM public.banking_pay_operations;
  SELECT COUNT(*) INTO v_batches_before FROM public.pay_batches;
  SELECT COUNT(*) INTO v_provider_before FROM public.banking_pay_operation_provider_attempts;
  SELECT COUNT(*) INTO v_settlement_before FROM public.banking_pay_operation_settlement_scope;
  SELECT COUNT(*) INTO v_remittance_before FROM public.banking_pay_operation_remittance_scope;

  BEGIN
    PERFORM public.pay_workbench_source_build_attempt_claim_start_v1(
      'invalid-authority-verifier','invalid-authority-verifier:lane:0',25,
      clock_timestamp(),v_session_id,v_candidate_repair
    );
    RAISE EXCEPTION 'BANKING_PAY_INVALID_AUTHORITY_OLD_FAILURE_NOT_REPRODUCED';
  EXCEPTION WHEN SQLSTATE '22023' THEN
    GET STACKED DIAGNOSTICS v_claim_error=MESSAGE_TEXT;
    IF v_claim_error IS DISTINCT FROM 'PAY_WORKBENCH_SOURCE_BUILD_AUTHORITY_FINGERPRINT_REQUIRED' THEN
      RAISE EXCEPTION USING MESSAGE='BANKING_PAY_INVALID_AUTHORITY_WRONG_OLD_FAILURE',
        DETAIL=COALESCE(v_claim_error,'NULL');
    END IF;
  END;

  v_result:=public.pay_workbench_repair_invalid_source_authority_jobs_v1(
    v_session_id,NULL::uuid,10,'VERIFICATION_INVALID_SOURCE_AUTHORITY_REPAIR'
  );
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'examined_candidate_count')::integer,-1)<>2
     OR COALESCE((v_result->>'repaired_candidate_count')::integer,-1)<>2
     OR COALESCE((v_result->>'terminalised_job_count')::integer,-1)<>3
     OR COALESCE((v_result->>'failed_count')::integer,-1)<>0
     OR COALESCE((v_result->>'remaining_invalid_active_count')::integer,-1)<>0
     OR COALESCE((v_result->>'all_state_transitions_proven')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_INVALID_AUTHORITY_REPAIR_RESULT_INVALID',
      DETAIL=v_result::text;
  END IF;

  FOR v_terminal IN
    SELECT status,completed_at_utc,failed_at_utc,economic_build_id,private_stage,
      private_cursor_kind,private_cursor_json,private_stage_version,
      last_error_json->>'code' AS error_code,
      payload_json->>'invalid_source_authority_terminalised' AS terminalised
    FROM public.banking_pay_workbench_jobs
    WHERE id IN (v_invalid_job_one,v_invalid_job_two,v_invalid_stray_job)
  LOOP
    IF v_terminal.status IS DISTINCT FROM 'DEAD'
       OR v_terminal.completed_at_utc IS NOT NULL
       OR v_terminal.failed_at_utc IS NULL
       OR v_terminal.economic_build_id IS NOT NULL
       OR v_terminal.private_stage IS NOT NULL
       OR v_terminal.private_cursor_kind IS NOT NULL
       OR v_terminal.private_cursor_json IS DISTINCT FROM '{}'::jsonb
       OR v_terminal.private_stage_version IS NOT NULL
       OR v_terminal.error_code IS DISTINCT FROM
          'SOURCE_BUILD_AUTHORITY_PAYLOAD_INVALID_TERMINALISED'
       OR LOWER(COALESCE(v_terminal.terminalised,'false'))<>'true' THEN
      RAISE EXCEPTION USING MESSAGE='BANKING_PAY_INVALID_AUTHORITY_TERMINAL_SHAPE_INVALID',
        DETAIL=pg_catalog.to_jsonb(v_terminal)::text;
    END IF;
  END LOOP;

  SELECT scope_row.pending_job_id,scope_row.status AS scope_status,scope_row.dirty,
    scope_row.error_json,owner_job.status AS owner_status,
    owner_job.payload_json->>'created_by_helper' AS created_by_helper,
    owner_job.payload_json->>'session_version' AS session_version,
    owner_job.payload_json->>'source_change_seq' AS source_change_seq,
    owner_job.payload_json->>'source_build_run_id' AS source_build_run_id,
    owner_job.payload_json->>'authority_fingerprint_version' AS fingerprint_version,
    owner_job.payload_json->>'authority_fingerprint' AS fingerprint,
    state_row.status AS state_status,state_row.pending_job_id AS state_pending_job_id,
    state_row.session_version AS state_session_version,
    state_row.source_change_seq AS state_source_change_seq
  INTO STRICT v_owner
  FROM public.banking_pay_workbench_session_scope AS scope_row
  JOIN public.banking_pay_workbench_jobs AS owner_job ON owner_job.id=scope_row.pending_job_id
  JOIN public.banking_pay_workbench_session_candidate_state AS state_row
    ON state_row.session_id=scope_row.session_id
   AND state_row.candidate_id=scope_row.candidate_id
  WHERE scope_row.session_id=v_session_id
    AND scope_row.candidate_id=v_candidate_repair;
  v_repaired_owner_id:=v_owner.pending_job_id;

  IF v_repaired_owner_id IN (v_invalid_job_one,v_invalid_job_two)
     OR v_owner.scope_status IS DISTINCT FROM 'SOURCE_BUILD_PENDING'
     OR v_owner.dirty IS NOT TRUE
     OR v_owner.error_json IS NOT NULL
     OR v_owner.owner_status NOT IN ('QUEUED','RUNNING')
     OR v_owner.created_by_helper IS DISTINCT FROM 'pay_workbench_enqueue_candidate_refresh'
     OR v_owner.session_version IS DISTINCT FROM '7'
     OR v_owner.source_change_seq::bigint<31
     OR v_owner.source_build_run_id !~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_owner.fingerprint_version NOT IN ('2','3')
     OR v_owner.fingerprint !~ '^[0-9a-f]{64}$'
     OR v_owner.state_status IS DISTINCT FROM 'PENDING'
     OR v_owner.state_pending_job_id IS DISTINCT FROM v_repaired_owner_id
     OR v_owner.state_session_version IS DISTINCT FROM 7
     OR v_owner.state_source_change_seq<31 THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_INVALID_AUTHORITY_REPLACEMENT_OWNER_INVALID',
      DETAIL=pg_catalog.to_jsonb(v_owner)::text;
  END IF;

  SELECT scope_row.pending_job_id,owner_job.payload_json->>'created_by_helper' AS created_by_helper,
    owner_job.payload_json->>'authority_fingerprint' AS fingerprint
  INTO STRICT v_owner
  FROM public.banking_pay_workbench_session_scope AS scope_row
  JOIN public.banking_pay_workbench_jobs AS owner_job ON owner_job.id=scope_row.pending_job_id
  WHERE scope_row.session_id=v_session_id
    AND scope_row.candidate_id=v_candidate_preserve;
  IF v_owner.pending_job_id IS DISTINCT FROM v_preserved_owner_id
     OR v_owner.created_by_helper IS DISTINCT FROM 'pay_workbench_enqueue_candidate_refresh'
     OR v_owner.fingerprint !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_INVALID_AUTHORITY_CURRENT_OWNER_NOT_PRESERVED',
      DETAIL=pg_catalog.to_jsonb(v_owner)::text;
  END IF;

  IF EXISTS(
    SELECT 1 FROM public.banking_pay_workbench_session_scope AS current_scope
    WHERE current_scope.session_id=v_session_id
      AND current_scope.pending_job_id IN (
        v_invalid_job_one,v_invalid_job_two,v_invalid_stray_job
      )
  ) OR EXISTS(
    SELECT 1 FROM public.banking_pay_workbench_session_candidate_state AS current_state
    WHERE current_state.session_id=v_session_id
      AND current_state.pending_job_id IN (
        v_invalid_job_one,v_invalid_job_two,v_invalid_stray_job
      )
  ) THEN
    RAISE EXCEPTION 'BANKING_PAY_INVALID_AUTHORITY_DEAD_JOB_REMAINS_CURRENT';
  END IF;

  v_replay_result:=public.pay_workbench_repair_invalid_source_authority_jobs_v1(
    v_session_id,NULL::uuid,10,'VERIFICATION_INVALID_SOURCE_AUTHORITY_REPAIR_REPLAY'
  );
  IF COALESCE((v_replay_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_replay_result->>'examined_candidate_count')::integer,-1)<>0
     OR COALESCE((v_replay_result->>'repaired_candidate_count')::integer,-1)<>0
     OR COALESCE((v_replay_result->>'terminalised_job_count')::integer,-1)<>0
     OR COALESCE((v_replay_result->>'remaining_invalid_active_count')::integer,-1)<>0 THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_INVALID_AUTHORITY_REPAIR_NOT_IDEMPOTENT',
      DETAIL=v_replay_result::text;
  END IF;

  IF (SELECT pending_job_id FROM public.banking_pay_workbench_session_scope
      WHERE session_id=v_session_id AND candidate_id=v_candidate_repair)
        IS DISTINCT FROM v_repaired_owner_id
     OR (SELECT pending_job_id FROM public.banking_pay_workbench_session_scope
      WHERE session_id=v_session_id AND candidate_id=v_candidate_preserve)
        IS DISTINCT FROM v_preserved_owner_id THEN
    RAISE EXCEPTION 'BANKING_PAY_INVALID_AUTHORITY_REPLAY_CHANGED_CURRENT_OWNER';
  END IF;

  IF (SELECT COUNT(*) FROM public.banking_pay_operations)<>v_operations_before
     OR (SELECT COUNT(*) FROM public.pay_batches)<>v_batches_before
     OR (SELECT COUNT(*) FROM public.banking_pay_operation_provider_attempts)<>v_provider_before
     OR (SELECT COUNT(*) FROM public.banking_pay_operation_settlement_scope)<>v_settlement_before
     OR (SELECT COUNT(*) FROM public.banking_pay_operation_remittance_scope)<>v_remittance_before THEN
    RAISE EXCEPTION 'BANKING_PAY_INVALID_AUTHORITY_FINANCIAL_LIFECYCLE_CHANGED';
  END IF;

  IF pg_catalog.has_function_privilege(
       'anon','public.pay_workbench_repair_invalid_source_authority_jobs_v1(uuid,uuid,integer,text)','EXECUTE'
     )
     OR pg_catalog.has_function_privilege(
       'authenticated','public.pay_workbench_repair_invalid_source_authority_jobs_v1(uuid,uuid,integer,text)','EXECUTE'
     )
     OR NOT pg_catalog.has_function_privilege(
       'service_role','public.pay_workbench_repair_invalid_source_authority_jobs_v1(uuid,uuid,integer,text)','EXECUTE'
     ) THEN
    RAISE EXCEPTION 'BANKING_PAY_INVALID_AUTHORITY_REPAIR_ACL_INVALID';
  END IF;
END;
$verification$;

