            'affected_display_amount', v_item->>'affected_display_amount',
            'linked_timesheet_id_matches', (v_item->>'linked_timesheet_id' is not distinct from v_timesheet::text),
            'affected_candidate_count', v_item->>'affected_candidate_count',
            'affected_payment_count', v_item->>'affected_payment_count'
          );
      end if;
    end loop;
  end loop;

  begin
    perform public.pay_workbench_session_get_action_required_page_v1(
      v_session,v_options,v_actor,'GROSS','ASC',null,100,'','ACTION_REQUIRED');
    raise exception 'BANKING_PAY_ACTION_AMOUNT_VERIFY: unapproved sort accepted';
  exception when invalid_parameter_value then
    if sqlerrm is distinct from 'BANKING_PAY_V2_INVALID_INPUT' then raise; end if;
  end;

  select md5(to_jsonb(r)::text) into strict v_after
  from public.banking_pay_workbench_preview_rows r where r.id=v_row;
  if v_after is distinct from v_before then
    raise exception 'BANKING_PAY_ACTION_AMOUNT_VERIFY: read changed a payment row';
  end if;
end;
$verify$;

do $verification$
declare
  v_definition text;
  v_state text;
begin
  select pg_get_functiondef(p.oid)
  into v_definition
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public'
    and p.proname='candidate_app_timesheet_page_v1'
    and pg_get_function_identity_arguments(p.oid)=
      'p_session_id uuid, p_environment text, p_view text, p_cursor text, p_limit integer, p_now_utc timestamp with time zone';

  if v_definition is null then
    raise exception 'CANDIDATE_SUBMITTED_WEEKLY_CARD_FUNCTION_MISSING';
  end if;

  foreach v_state in array array[
    'CREATED','WORKER_DRAFT','WORKER_SUBMITTED',
    'WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT','READY_FOR_MANAGER_APPROVAL',
    'AWAITING_MANAGER_APPROVAL','MANAGER_APPROVED',
    'MANAGER_APPROVED_PENDING_FINAL_DOCUMENT','READY_TO_FINALISE',
    'AWAITING_PAPER_RETURN','RECEIVED','REFUSED'
  ] loop
    if position(quote_literal(v_state) in v_definition)=0 then
      raise exception 'CANDIDATE_SUBMITTED_WEEKLY_CARD_STATE_MISSING:%',v_state;
    end if;
  end loop;

  if position('classified.target_timesheet_id is null' in lower(v_definition))=0
     or position('classified.anchor_timesheet_id is null' in lower(v_definition))=0
     or position('draft_week.id=classified.contract_week_id' in lower(v_definition))=0 then
    raise exception 'CANDIDATE_SUBMITTED_WEEKLY_CARD_EXACT_WEEK_LINK_MISSING';
  end if;

  if position('{hours_submission,canonical_tsfin_snapshot,total_hours}' in lower(v_definition))=0
     or position('{expense_submission,canonical_tsfin_snapshot,expenses_pay_ex_vat}' in lower(v_definition))=0
     or position('coalesce(nullif(base.total_hours,0),workflows.submitted_total_hours,base.total_hours,0)' in lower(v_definition))=0
     or position('overlay_total_hours' in lower(v_definition))=0 then
    raise exception 'CANDIDATE_SUBMITTED_WEEKLY_CARD_FACTUAL_OVERLAY_MISSING';
  end if;

  if position('draft_has_content' in lower(v_definition))=0
     or position('component.workflow_id=resolved.id' in lower(v_definition))=0
     or position('component.workflow_generation=resolved.generation' in lower(v_definition))=0
     or position('component.superseded_at_utc is null' in lower(v_definition))=0 then
    raise exception 'CANDIDATE_MUTABLE_DRAFT_CONTENT_TRUTH_MISSING';
  end if;

  if position('workflow.target_timesheet_id=carrier.timesheet_id' in lower(v_definition))=0
     or position('workflow.target_timesheet_id is null' in lower(v_definition))=0
     or position('from public.candidate_submission_workflows exact_owner' in lower(v_definition))=0
     or position('exact_owner.target_timesheet_id=carrier.timesheet_id' in lower(v_definition))=0
     or position('workflow.target_timesheet_id=carrier.timesheet_id or workflow.contract_week_id=carrier.id' in lower(v_definition))<>0 then
    raise exception 'CANDIDATE_MULTI_EXPENSE_EXACT_OWNER_PRECEDENCE_MISSING';
  end if;

  if has_function_privilege('anon',
       'public.candidate_app_timesheet_page_v1(uuid,text,text,text,integer,timestamp with time zone)',
       'EXECUTE')
     or has_function_privilege('authenticated',
       'public.candidate_app_timesheet_page_v1(uuid,text,text,text,integer,timestamp with time zone)',
       'EXECUTE') then
    raise exception 'CANDIDATE_SUBMITTED_WEEKLY_CARD_BROWSER_EXECUTE_EXPOSED';
  end if;
  if not has_function_privilege('service_role',
       'public.candidate_app_timesheet_page_v1(uuid,text,text,text,integer,timestamp with time zone)',
       'EXECUTE') then
    raise exception 'CANDIDATE_SUBMITTED_WEEKLY_CARD_SERVICE_EXECUTE_MISSING';
  end if;
end;
$verification$;

do $verification$
declare
  v_candidate uuid:=gen_random_uuid();
  v_context jsonb;
  v_current jsonb;
  v_saved jsonb;
  v_replay jsonb;
  v_candidate_read jsonb;
  v_version bigint;
  v_idempotency text:=gen_random_uuid()::text;
  v_actor_hmac text:=pg_catalog.encode(extensions.gen_random_bytes(32),'hex');
  v_home_version_before bigint;
  v_home_version_after bigint;
  v_hash text:=pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(gen_random_uuid()::text,'UTF8'),'sha256'),
    'hex'
  );
begin
  if pg_catalog.has_table_privilege('anon','public.candidate_daily_information_settings','SELECT')
     or pg_catalog.has_table_privilege('authenticated','public.candidate_daily_information_settings','SELECT')
     or pg_catalog.has_table_privilege('service_role','public.candidate_daily_information_settings','SELECT')
     or pg_catalog.has_table_privilege('anon','public.candidate_daily_information_versions','SELECT')
     or pg_catalog.has_table_privilege('authenticated','public.candidate_daily_information_versions','SELECT')
     or pg_catalog.has_table_privilege('service_role','public.candidate_daily_information_versions','SELECT')
  then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: direct table access is open';
  end if;
  if pg_catalog.has_function_privilege(
       'anon','public.candidate_daily_information_settings_get_v1()','EXECUTE'
     )
     or pg_catalog.has_function_privilege(
       'authenticated','public.candidate_daily_information_settings_get_v1()','EXECUTE'
     )
     or pg_catalog.has_function_privilege(
       'anon',
       'public.candidate_daily_information_candidate_v1(jsonb,text,timestamptz,text)',
       'EXECUTE'
     )
     or not pg_catalog.has_function_privilege(
       'service_role','public.candidate_daily_information_settings_get_v1()','EXECUTE'
     )
     or not pg_catalog.has_function_privilege(
       'service_role',
       'public.candidate_daily_information_candidate_v1(jsonb,text,timestamptz,text)',
       'EXECUTE'
     )
  then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: function ACL is wrong';
  end if;

  select candidate_home_announcement_version into v_home_version_before
  from public.settings_defaults where id=1;
  v_current:=public.candidate_daily_information_settings_get_v1();
  v_version:=(v_current->>'version')::bigint;
  if v_current->>'ok' is distinct from 'true'
     or pg_catalog.jsonb_typeof(v_current->'hospital_addresses') is distinct from 'array'
     or pg_catalog.jsonb_typeof(v_current->'accommodation_contacts') is distinct from 'array'
  then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: initial settings read is invalid';
  end if;

  v_saved:=public.candidate_daily_information_settings_set_v1(
    v_version,
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'hospital_name','  North General Hospital  ',
      'address',E'1 Health Street\r\nLondon\r\nN1 1AA',
      'telephone',' 020 7123 4567 ',
      'map_query',' North General Hospital, N1 1AA '
    )),
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'hospital_name','North General Hospital',
      'office_name',' Staff accommodation office ',
      'address','Residences Building, 2 Health Street',
      'telephone','020 7987 6543',
      'email',' HOUSING@EXAMPLE.INVALID ',
      'working_hours',E'Monday to Friday\r\n09:00–17:00'
    )),
    v_actor_hmac,v_idempotency,
    '2026-08-30 03:16:00+00'::timestamptz
  );
  if v_saved->>'ok' is distinct from 'true'
     or (v_saved->>'version')::bigint is distinct from v_version+1
     or v_saved#>>'{hospital_addresses,0,hospital_name}'
       is distinct from 'North General Hospital'
     or v_saved#>>'{hospital_addresses,0,address}'
       is distinct from E'1 Health Street\nLondon\nN1 1AA'
     or v_saved#>>'{accommodation_contacts,0,email}'
       is distinct from 'housing@example.invalid'
     or v_saved#>>'{accommodation_contacts,0,working_hours}'
       is distinct from E'Monday to Friday\n09:00–17:00'
  then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: normalized save is wrong: %',v_saved;
  end if;

  v_replay:=public.candidate_daily_information_settings_set_v1(
    v_version,
    v_saved->'hospital_addresses',v_saved->'accommodation_contacts',
    v_actor_hmac,v_idempotency,
    '2026-08-30 03:17:00+00'::timestamptz
  );
  if v_replay->>'idempotent_replay' is distinct from 'true'
     or v_replay->>'version' is distinct from v_saved->>'version'
     or (select pg_catalog.count(*) from public.candidate_daily_information_versions
         where idempotency_key=v_idempotency)<>1
  then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: idempotent replay is wrong';
  end if;

  begin
    perform public.candidate_daily_information_settings_set_v1(
      v_version,v_saved->'hospital_addresses',v_saved->'accommodation_contacts',
      pg_catalog.encode(extensions.gen_random_bytes(32),'hex'),v_idempotency,
      '2026-08-30 03:17:30+00'::timestamptz
    );
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: cross-actor replay was accepted';
  exception when sqlstate 'PT409' then
    null;
  end;

  begin
    perform public.candidate_daily_information_settings_set_v1(
      (v_saved->>'version')::bigint,
      pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'hospital_name','North General Hospital','address','1 Health Street'
        ),
        pg_catalog.jsonb_build_object(
          'hospital_name',' north general hospital ','address','Different address'
        )
      ),
      '[]'::jsonb,pg_catalog.encode(extensions.gen_random_bytes(32),'hex'),
      gen_random_uuid()::text,'2026-08-30 03:18:00+00'::timestamptz
    );
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: duplicate normalization was accepted';
  exception when sqlstate '22023' then
    null;
  end;

  begin
    perform public.candidate_daily_information_settings_set_v1(
      v_version,v_saved->'hospital_addresses',v_saved->'accommodation_contacts',
      pg_catalog.encode(extensions.gen_random_bytes(32),'hex'),gen_random_uuid()::text,
      '2026-08-30 03:18:00+00'::timestamptz
    );
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: stale version was accepted';
  exception when sqlstate 'PT409' then
    null;
  end;

  insert into public.candidates(id,email,display_name,active)
  values(
    v_candidate,
    'daily-information-'||v_candidate::text||'@example.invalid',
    'Daily information proof',true
  );
  insert into private.candidate_daily_entitlements(
    environment,candidate_id,enabled,reason,evidence_sha256
  ) values('TEST',v_candidate,true,'Daily information proof',v_hash);
  insert into private.candidate_daily_source_links(
    environment,candidate_id,source_system,canonicalization_version,link_group_id,
    identifier_hmac,hmac_key_version,state,evidence_sha256
  ) values(
    'TEST',v_candidate,'GOOGLE_CREDENTIALLY_PUBLIC_ID','SOURCE_IDENTITY_V1',
    gen_random_uuid(),v_hash,1,'PRIMARY',v_hash
  );
  insert into private.candidate_daily_authority_scopes(
    environment,candidate_id,authority_mode,canonical_version,transition_in_progress
  ) values('TEST',v_candidate,'SUPABASE_PRIMARY',1,false);
  update public.settings_defaults
  set candidate_app_feature_flags_json=candidate_app_feature_flags_json
    ||pg_catalog.jsonb_build_object('candidate_daily_enabled',true)
  where id=1;
  v_context:=pg_catalog.jsonb_build_object(
    'policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate
  );

  v_candidate_read:=public.candidate_daily_information_candidate_v1(
    v_context,'hospital-addresses','2026-08-30 03:19:00+00'::timestamptz,
    '01K2ABCDEFGHJKMNPQRSTVWXYZ'
  );
  if v_candidate_read->>'kind' is distinct from 'hospital-addresses'
     or v_candidate_read->>'title' is distinct from 'Hospital addresses'
     or v_candidate_read->>'schema_version' is distinct from '1'
     or v_candidate_read#>>'{entries,0,hospital_name}'
       is distinct from 'North General Hospital'
     or v_candidate_read#>>'{appInfo,version}'
       is distinct from 'CLOUDTMS_DIRECTORY_V1'
  then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: Candidate projection is wrong: %',
      v_candidate_read;
  end if;
  v_candidate_read:=public.candidate_daily_information_candidate_v1(
    v_context,'accommodation-contacts','2026-08-30 03:19:00+00'::timestamptz,
    '01K2ABCDEFGHJKMNPQRSTVWXYZ'
  );
  if v_candidate_read->>'kind' is distinct from 'accommodation-contacts'
     or v_candidate_read#>>'{entries,0,office_name}'
       is distinct from 'Staff accommodation office'
  then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: accommodation projection is wrong';
  end if;

  select candidate_home_announcement_version into v_home_version_after
  from public.settings_defaults where id=1;
  if v_home_version_after is distinct from v_home_version_before then
    raise exception 'CANDIDATE_DAILY_INFORMATION_PROOF: unrelated MyTMS setting changed';
  end if;
end;
$verification$;

-- Rollback-contained first-use proof for the Candidate Daily emergency window.
-- The regression was a composite-row assignment (`select d into %rowtype`) that
-- compiled successfully but failed on its first real booked shift.




do $verification$
declare
  v_candidate_id uuid:=gen_random_uuid();
  v_generation_id uuid:=gen_random_uuid();
  v_batch_id uuid:=gen_random_uuid();
  v_link_group_id uuid:=gen_random_uuid();
  v_today date:='2026-08-30'::date;
  v_shift_start timestamptz:='2026-08-30 07:30:00+01'::timestamptz;
  v_shift_end timestamptz:='2026-08-30 20:00:00+01'::timestamptz;
  v_source_hash text:=repeat('a',64);
  v_token text;
  v_result jsonb;
  v_definition text;
  v_day integer;
begin
  select pg_get_functiondef(
    'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)'::regprocedure
  ) into v_definition;
  if position('select d.* into v_day' in lower(v_definition))=0
     or lower(v_definition) ~ 'select[[:space:]]+d[[:space:]]+into[[:space:]]+v_day'
     or v_definition~*'pg_catalog\.(coalesce|nullif|least|greatest)[[:space:]]*\('
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: row assignment is unsafe';
  end if;
  if not exists(
    select 1 from pg_proc p
    where p.oid='private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)'::regprocedure
      and p.prosecdef and p.provolatile='s'
      and p.proconfig @> array['search_path=""']::text[]
  ) then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: function security changed';
  end if;
  if has_function_privilege(
       'service_role',
       'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)',
       'EXECUTE'
     )
     or has_function_privilege(
       'anon',
       'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)',
       'EXECUTE'
     )
     or has_function_privilege(
       'authenticated',
       'private._candidate_daily_specialist_shift_v1(jsonb,text,timestamptz)',
       'EXECUTE'
     )
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: private ACL opened';
  end if;

  update public.settings_defaults
  set candidate_app_feature_flags_json=
    candidate_app_feature_flags_json||'{"candidate_daily_enabled":true}'::jsonb
  where id=1;

  insert into public.candidates(id,email,display_name,phone,active)
  values(
    v_candidate_id,
    'emergency-window-'||v_candidate_id::text||'@example.invalid',
    'Emergency window proof','07000000000',true
  );
  insert into private.candidate_daily_authority_scopes(
    environment,candidate_id,authority_mode,canonical_version,transition_in_progress
  ) values('TEST',v_candidate_id,'SUPABASE_PRIMARY',1,false);
  insert into private.candidate_daily_entitlements(
    environment,candidate_id,enabled,reason,evidence_sha256
  ) values('TEST',v_candidate_id,true,'Emergency window proof',repeat('1',64));
  insert into private.candidate_daily_source_links(
    environment,candidate_id,source_system,canonicalization_version,
    link_group_id,identifier_hmac,hmac_key_version,state,evidence_sha256
  ) values(
    'TEST',v_candidate_id,'GOOGLE_CREDENTIALLY_PUBLIC_ID','SOURCE_IDENTITY_V1',
    v_link_group_id,repeat('2',64),1,'PRIMARY',repeat('3',64)
  );
  insert into private.candidate_daily_batch_receipts(
    batch_receipt_id,environment,actor_class,operation_class,idempotency_key,
    request_hash,item_keys_json,item_count,state,terminal_http_status,
    terminal_response_body,terminal_response_sha256,correlation_id,completed_at_utc
  ) values(
    v_batch_id,'TEST','SIGNED_SYSTEM','ROTA_GENERATION_PUBLISH',
    'emergency-window-'||v_batch_id::text,repeat('4',64),
    jsonb_build_array(v_candidate_id::text),1,'COMPLETED',200,'{}'::jsonb,
    repeat('5',64),'01M18D00000000000000000000',clock_timestamp()
  );
  insert into public.candidate_daily_rota_generations(
    generation_id,environment,candidate_id,generation_version,window_start,
    window_end,state,expected_day_count,actual_day_count,source_system,
    source_event_id,source_revision,source_event_time,item_key,source_hash,
    generation_row_hash,batch_receipt_id,correlation_id,activated_at_utc,
    published_at_utc
  ) values(
    v_generation_id,'TEST',v_candidate_id,1,v_today,v_today+13,'ACTIVE',14,14,
    'MASTER_ROTA','emergency-window-source-'||v_generation_id::text,
    'emergency-window-v1',clock_timestamp()-interval '1 day',
    'emergency-window-item-'||v_generation_id::text,repeat('6',64),repeat('7',64),
    v_batch_id,'01M18D00000000000000000000',clock_timestamp()-interval '1 day',
    clock_timestamp()-interval '1 day'
  );
  for v_day in 0..13 loop
    insert into public.candidate_daily_rota_days(
      generation_id,environment,candidate_id,rota_date,booked,system_blocked,
      booking_id,shift_starts_at,shift_ends_at,shift_info,hospital,ward,
      job_title,booking_ref,shift_type,timesheet_authorised,timesheet_eligible,
      source_row_hash
    ) values(
      v_generation_id,'TEST',v_candidate_id,v_today+v_day,v_day=0,false,
      case when v_day=0 then 'emergency-window-booking' else null end,
      case when v_day=0 then v_shift_start else null end,
      case when v_day=0 then v_shift_end else null end,
      case when v_day=0 then 'Long Day 0730-2000hrs' else null end,
      case when v_day=0 then 'North General Hospital' else null end,
      case when v_day=0 then 'Ward 1' else null end,
      case when v_day=0 then 'Registered Nurse' else null end,
      case when v_day=0 then 'TEST-BOOKING' else null end,
      case when v_day=0 then 'Long Day' else null end,
      false,false,
      case when v_day=0 then v_source_hash
        else repeat(substr(md5(v_candidate_id::text||v_day::text),1,1),64) end
    );
  end loop;
  update private.candidate_daily_authority_scopes
  set active_generation_id=v_generation_id
  where environment='TEST' and candidate_id=v_candidate_id;

  v_token:=private._candidate_daily_emergency_token_v1(
    'TEST',v_candidate_id,v_generation_id,v_today,v_source_hash
  );
  -- Complete Master contacts are a separate signed-source projection, not
  -- dependent on the colleague being enrolled in MyTMS.
  v_result:=public.candidate_daily_specialist_read_v1(
    jsonb_build_object('policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate_id),
    'EMERGENCY_ROSTER_PUBLISH',jsonb_build_object('emergency_shift_token',v_token,'roster',jsonb_build_object(
      'emergency_shift_token',v_token,'captured_at',clock_timestamp(),'groups',jsonb_build_object(
        'current',jsonb_build_array(jsonb_build_object('display_name','Unenrolled colleague','role','RMN','callable_mobile','447111111111')),
        'previous','[]'::jsonb,'next','[]'::jsonb))),v_shift_start,'01M18D00000000000000000000');
  if v_result->>'accepted' is distinct from 'true' then raise exception 'Emergency roster publication failed'; end if;
  v_result:=private._candidate_daily_specialist_shift_v1(
    jsonb_build_object(
      'policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate_id
    ),v_token,v_shift_start
  );
  if v_result->>'date' is distinct from v_today::text
     or (v_result->>'starts_at')::timestamptz is distinct from v_shift_start
     or (v_result->>'ends_at')::timestamptz is distinct from v_shift_end
     or not (v_result->'allowed_issues' ? 'RUNNING_LATE')
     or not (v_result->'allowed_issues' ? 'LEAVE_EARLY')
     or not (v_result->'allowed_issues' ? 'DNA')
     or v_result#>>'{dna_subjects,0,callable_mobile}' is distinct from '447111111111'
     or coalesce(v_result#>>'{dna_subjects,0,subject_token}','') !~ '^[a-f0-9]{64}$'
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: private first use is wrong: %',
      v_result;
  end if;

  v_result:=public.candidate_daily_specialist_read_v1(
    jsonb_build_object(
      'policy','CANDIDATE_SURFACE','environment','TEST','candidate_id',v_candidate_id
    ),'EMERGENCY_WINDOW','{}'::jsonb,v_shift_start,
    '01M18D00000000000000000000'
  );
  if v_result->>'eligible' is distinct from 'true'
     or jsonb_array_length(v_result->'shifts')<>1
     or v_result#>>'{shifts,0,date}' is distinct from v_today::text
     or v_result#>>'{shifts,0,display_label}' not like '%North General Hospital%'
     or (v_result#>'{shifts,0}') ? '_agency_payload'
  then
    raise exception 'CANDIDATE_DAILY_EMERGENCY_WINDOW_ROW_PROOF: public first use is wrong: %',
      v_result;
  end if;
end;
$verification$;

-- Installed transaction and ACL authority for returned-paper QR proof.

do $candidate_paper_return_proof_transaction_boundary_verification$
declare
  v_oid oid;
  v_security_definer boolean;
  v_volatility "char";
  v_config text[];
  v_owner text;
  v_definition text;
begin
  select p.oid,p.prosecdef,p.provolatile,p.proconfig,owner_role.rolname
    into v_oid,v_security_definer,v_volatility,v_config,v_owner
  from pg_catalog.pg_proc p
  join pg_catalog.pg_roles owner_role on owner_role.oid=p.proowner
  where p.oid=pg_catalog.to_regprocedure(
    'public.candidate_paper_return_proof_validate_v1(uuid,text,uuid,integer,text,text,text,text,timestamp with time zone)'
  );

  if not found
     or not v_security_definer
     or v_volatility<>'v'
     or v_owner<>current_user
     or v_config is distinct from
        array['search_path=pg_catalog, public, private, extensions, pg_temp']::text[]
     or not pg_catalog.has_function_privilege('service_role',v_oid,'EXECUTE')
     or pg_catalog.has_function_privilege('anon',v_oid,'EXECUTE')
     or pg_catalog.has_function_privilege('authenticated',v_oid,'EXECUTE') then
    raise exception 'CANDIDATE_PAPER_RETURN_PROOF_TRANSACTION_BOUNDARY_INVALID';
  end if;

  v_definition:=pg_catalog.pg_get_functiondef(v_oid);
  if v_definition not like '%_candidate_session_context_v1(%true%'
     or v_definition not like '%CANDIDATE_PAPER_QR_PROOF_MISMATCH%'
     or v_definition not like '%CANDIDATE_PAPER_QR_PROOF_FORBIDDEN%' then
    raise exception 'CANDIDATE_PAPER_RETURN_PROOF_LOCK_OR_FAIL_CLOSED_AUTHORITY_MISSING';
  end if;
end
