  v_workflow uuid:='a2000000-0000-0000-0000-000000000009';
  v_document_operation uuid:='a2000000-0000-0000-0000-000000000010';
  v_source_component uuid;
  v_unsafe_component uuid;
  v_return_component uuid;
  v_response jsonb;
  v_page jsonb;
  v_manifest jsonb;
  v_manifest_hash text;
  v_service jsonb;
  v_mail uuid;
  v_row_signature text;
  v_failed boolean:=false;
  v_counter integer:=0;
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema='public' and table_name='tms_users' and column_name='password_hash'
  ) then
    execute $sql$
      insert into public.tms_users(id,email,password_hash,role,is_active)
      values($1,'qr-evidence-label-runtime@example.invalid','UNUSABLE_VERIFICATION_ONLY','admin',true)
    $sql$ using v_actor;
  else
    insert into public.tms_users(id,email,is_active)
    values(v_actor,'qr-evidence-label-runtime@example.invalid',true);
  end if;
  update public.settings_defaults set candidate_app_system_actor_user_id=v_actor where id=1;
  insert into public.clients(id,name) values(v_client,'Paper complete-pack runtime client');
  insert into public.candidates(id,email,active,key_norm)
  values(v_candidate,'paper-runtime@example.test',true,'GCK-PAPER-RUNTIME');
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,
    candidate_expenses_require_separate_timesheet,candidate_paper_submission_enabled
  ) values(gen_random_uuid(),v_client,current_date-1,'ELECTRONIC',false,true);
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,week_ending_weekday_snapshot,
    pay_method_snapshot,default_submission_mode
  ) values(v_contract,v_candidate,v_client,current_date-60,current_date+60,
    extract(dow from current_date)::integer,'PAYE','ELECTRONIC');
  insert into public.timesheets(
    timesheet_id,contract_id,booking_id,occupant_key_norm,hospital_norm,
    ward_norm,job_title_norm,week_ending_date,line_type,sheet_scope,
    submission_mode,qr_status,qr_token,actual_schedule_json
  ) values(
    v_timesheet,v_contract,'PAPER-COMPLETE-PACK-RUNTIME','GCK-PAPER-RUNTIME',
    'PAPER-COMPLETE-PACK-RUNTIME-CLIENT','PAPER-COMPLETE-PACK-RUNTIME-WARD',
    'PAPER-COMPLETE-PACK-RUNTIME-ROLE',current_date,'HOURS','WEEKLY','MANUAL',
    'PENDING','paper-complete-pack-runtime-token',
    jsonb_build_array(jsonb_build_object(
      'date',current_date,'start','09:00','end','17:30','break_minutes',30
    ))
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot,timesheet_id
  ) values(v_week,v_contract,current_date,'OPEN','ELECTRONIC',v_timesheet);
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,processing_status
  ) values(v_timesheet,1,v_candidate,v_client,8,'UNPROCESSED');
  insert into public.invoice_operations(
    id,operation_type,entity_type,entity_id,actor_user_id,idempotency_key,
    status,phase,priority,source_revision,template_version,input_json,config_json,
    progress_json,total_units,chunk_count,control_version,change_seq,
    created_at_utc,updated_at_utc
  ) values(
    v_document_operation,'BUILD_DOCUMENT','TIMESHEET',v_timesheet,v_actor,
    'paper-complete-pack-runtime-'||v_document_operation::text,
    'COMPLETE','VERIFYING',550,'1','timesheet-professional-v2','{}'::jsonb,
    jsonb_build_object('processor_policy',private._invoice_processor_limits()),
    '{}'::jsonb,1,1,1,nextval('public.invoice_operation_change_seq'),now(),now()
  );
  insert into public.invoice_document_versions(
    entity_type,entity_id,purpose,operation_id,source_revision,template_version,status,
    snapshot_json,snapshot_hash,manifest_json,manifest_hash,
    r2_key,sha256,size_bytes,page_count,ready_at_utc,verified_at_utc
  ) values(
    'TIMESHEET',v_timesheet,'TIMESHEET',v_document_operation,'1',
    'timesheet-professional-v2','READY','{}'::jsonb,
    encode(extensions.digest('{}','sha256'),'hex'),'[]'::jsonb,
    encode(extensions.digest('[]','sha256'),'hex'),
    'candidate-app/test/paper-base.pdf',repeat('f',64),1024,1,now(),now()
  );
  insert into public.candidate_app_accounts(id,environment,email_normalized,status)
  values(v_account,'TEST','paper-runtime@example.test','ACTIVE');
  insert into public.candidate_app_sessions(
    id,account_id,environment,selected_candidate_id,status,refresh_token_hash,
    expires_at_utc,absolute_expires_at_utc
  ) values(v_session,v_account,'TEST',v_candidate,'ACTIVE',decode(repeat('a2',32),'hex'),
    now()+interval '30 days',now()+interval '90 days');

  perform public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'CREATE',1,jsonb_build_object(
      'workflow_kind','CONTRACT_COMBINED','scope','WEEKLY','route','PAPER',
      'contract_id',v_contract,'contract_week_id',v_week,
      'anchor_timesheet_id',v_timesheet,'target_timesheet_id',v_timesheet,
      'week_ending_date',current_date
    ),'paper:create',now());
  v_response:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'COMPONENT_PREPARE',1,jsonb_build_object(
      'component_kind','EXPENSE_EVIDENCE','expense_category','OTHER',
      'document_role','SOURCE_EVIDENCE','storage_key','paper/source/other.png',
      'media_type','image/png','byte_size',1024
    ),'paper:evidence:prepare',now());
  v_source_component:=(v_response->>'component_id')::uuid;
  perform public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'COMPONENT_COMPLETE',1,jsonb_build_object(
      'component_id',v_source_component,'source_content_sha256_hex',repeat('a3',32),
      'verified_byte_size',1024,'verified_media_type','image/png'
    ),'paper:evidence:complete',now());
  v_response:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'COMPONENT_PREPARE',1,jsonb_build_object(
      'component_kind','EXPENSE_EVIDENCE','expense_category','TRAVEL',
      'document_role','SOURCE_EVIDENCE','storage_key','paper/source/unsafe.png',
      'media_type','image/png','byte_size',128
    ),'paper:unsafe:prepare',now());
  v_unsafe_component:=(v_response->>'component_id')::uuid;
  update public.candidate_submission_components
  set state='SUPERSEDED',superseded_at_utc=now()
  where id=v_unsafe_component;
  v_response:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'COMPONENT_PREPARE',1,jsonb_build_object(
      'component_kind','EXPENSE_EVIDENCE','expense_category','TRAVEL',
      'document_role','SOURCE_EVIDENCE','storage_key','paper/source/unsafe.png',
      'media_type','image/png','byte_size',128
    ),'paper:unsafe:prepare',now());
  if not coalesce((v_response->>'idempotent_replay')::boolean,false)
     or (v_response->>'component_id')::uuid<>v_unsafe_component then
    raise exception 'superseded component exact replay did not preserve its durable receipt: %',v_response;
  end if;
  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'COMPONENT_COMPLETE',1,jsonb_build_object(
        'component_id',v_unsafe_component,'source_content_sha256_hex',repeat('a5',32),
        'verified_byte_size',128,'verified_media_type','image/png'
      ),'paper:unsafe:complete',now());
    raise exception 'superseded component was revived by completion';
  exception when sqlstate '55000' then
    if sqlerrm<>'CANDIDATE_COMPONENT_COMPLETE_STATE_CONFLICT' then raise; end if;
  end;
  v_response:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'WORKER_SUBMIT',1,jsonb_build_object(
      'approval_route','PAPER',
      'immutable_submission',jsonb_build_object(
        'hours_submission',jsonb_build_object(
          'canonical_tsfin_snapshot',jsonb_build_object(
            'candidate_id',v_candidate,'client_id',v_client,'total_hours',8,
            'hours_day',8,'total_pay_ex_vat',80,'total_charge_ex_vat',100,'margin_ex_vat',20
          ),
          'timesheet_patch_json',jsonb_build_object(
            'actual_schedule_json',jsonb_build_array(jsonb_build_object(
              'date',current_date,'start','09:00','end','17:30','break_minutes',30
            ))
          ),
          'contract_week_patch_json','{}'::jsonb
        ),
        'expense_submission',jsonb_build_object(
          'canonical_tsfin_snapshot',jsonb_build_object(
            'candidate_id',v_candidate,'client_id',v_client,
            'other_pay_ex_vat',10,'other_charge_ex_vat',12,
            'total_pay_ex_vat',90,'total_charge_ex_vat',112,'margin_ex_vat',22
          ),
          'timesheet_patch_json','{}'::jsonb,'contract_week_patch_json','{}'::jsonb,
          'evidence_display_name','Returned paper expense page'
        )
      )
    ),'paper:submit',now());
  if v_response->>'state'<>'WORKER_SUBMITTED' or v_response->>'generation'<>'2' then
    raise exception 'paper worker submission did not freeze generation two: %',v_response;
  end if;
  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'COMPONENT_PREPARE',2,jsonb_build_object(
        'component_kind','EXPENSE_EVIDENCE','expense_category','OTHER',
        'document_role','SOURCE_EVIDENCE','storage_key','paper/source/other.png',
        'media_type','image/png','byte_size',1024
      ),'paper:evidence:prepare',now());
    raise exception 'cross-generation mutation key reuse unexpectedly issued a contract';
  exception when sqlstate '40001' then
    if sqlerrm<>'CANDIDATE_IDEMPOTENCY_CONFLICT' then raise; end if;
  end;

  update public.timesheets set actual_schedule_json='[]'::jsonb where timesheet_id=v_timesheet;
  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'PAPER_PREPARE',2,'{}'::jsonb,
      'paper:prepare:queue-failure',now());
    raise exception 'paper preparation was accepted when the canonical QR queue rejected the timesheet';
  exception when sqlstate '55000' then
    if sqlerrm<>'CANDIDATE_PAPER_PACK_QUEUE_FAILED' then raise; end if;
  end;
  if (select state from public.candidate_submission_workflows where id=v_workflow)<>'WORKER_SUBMITTED'
     or exists(
       select 1 from public.mail_outbox
       where payment_scope_json->>'candidate_workflow_id'=v_workflow::text
     ) then
    raise exception 'canonical QR queue failure did not roll back PAPER preparation atomically';
  end if;
  update public.timesheets
  set actual_schedule_json=jsonb_build_array(jsonb_build_object(
    'date',current_date,'start','09:00','end','17:30','break_minutes',30
  ))
  where timesheet_id=v_timesheet;

  update public.candidates set email=null where id=v_candidate;
  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'PAPER_PREPARE',2,'{}'::jsonb,
      'paper:prepare:missing-email',now());
    raise exception 'paper preparation was accepted without a candidate email';
  exception
    when sqlstate '28000' then
      if sqlerrm<>'CANDIDATE_ACCOUNT_NOT_ELIGIBLE' then raise; end if;
    when sqlstate '55000' then
      if sqlerrm<>'CANDIDATE_PAPER_EMAIL_NOT_AVAILABLE' then raise; end if;
  end;
  if (select state from public.candidate_submission_workflows where id=v_workflow)<>'WORKER_SUBMITTED'
     or exists(
       select 1 from public.mail_outbox
       where payment_scope_json->>'candidate_workflow_id'=v_workflow::text
     ) then
    raise exception 'missing-email PAPER preparation did not roll back atomically';
  end if;

  update public.candidates
  set email='paper-runtime@example.test',opt_in_email=false
  where id=v_candidate;
  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'PAPER_PREPARE',2,'{}'::jsonb,
      'paper:prepare:email-opted-out',now());
    raise exception 'paper preparation was accepted after email opt-out';
  exception when sqlstate '55000' then
    if sqlerrm<>'CANDIDATE_PAPER_EMAIL_NOT_AVAILABLE' then raise; end if;
  end;
  if (select state from public.candidate_submission_workflows where id=v_workflow)<>'WORKER_SUBMITTED'
     or exists(
       select 1 from public.mail_outbox
       where payment_scope_json->>'candidate_workflow_id'=v_workflow::text
     ) then
    raise exception 'email-opt-out PAPER preparation did not roll back atomically';
  end if;
  update public.candidates set opt_in_email=true where id=v_candidate;

  v_response:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'PAPER_PREPARE',2,'{}'::jsonb,'paper:prepare',now());
  perform public.candidate_paper_manifest_v2_promote_v1(
    v_session,'TEST',v_workflow,2,
    v_response->>'paper_return_manifest_sha256',now()
  );
  select paper_return_manifest_json into v_manifest
  from public.candidate_submission_workflows where id=v_workflow;
  v_mail:=(v_response->'paper_pack'->>'mail_outbox_id')::uuid;
  select encode(paper_return_manifest_sha256,'hex') into v_manifest_hash
  from public.candidate_submission_workflows where id=v_workflow;
  if v_response->>'state'<>'AWAITING_PAPER_RETURN'
     or jsonb_array_length(v_manifest->'pages')<>2
     or v_manifest->>'manifest_version'<>'2'
     or v_manifest->>'qr_contract_version'<>'CANDIDATE_PAPER_PAGE_QR_V2'
     or v_manifest#>>'{pages,0,display_name}'<>'Timesheet'
     or v_manifest#>>'{pages,1,display_name}'<>'Other 1'
     or exists(
       select 1 from jsonb_array_elements(v_manifest->'pages') manifest_page
       where upper(coalesce(manifest_page->>'component_kind',''))='EXPENSE_SUMMARY'
     )
     or not coalesce((v_response->'paper_pack'->>'queued')::boolean,false)
     or not coalesce((v_response->'paper_pack'->>'recipient_available')::boolean,false)
     or nullif(v_response->'paper_pack'->>'mail_outbox_id','') is null then
    raise exception 'paper manifest was not the complete two-page unsigned-summary pack: %',v_response;
  end if;
  if not exists(
    select 1 from public.mail_outbox mail
    where mail.id=v_mail and mail.type='TIMESHEET_QR'
      and mail.context_kind='timesheets' and mail.context_id=v_timesheet
      and mail.payment_scope_json->>'candidate_mail_authority'='CANDIDATE_PAPER_V1'
      and mail.payment_scope_json->>'candidate_workflow_id'=v_workflow::text
      and mail.payment_scope_json->>'candidate_workflow_generation'='2'
      and mail.payment_scope_json->>'paper_return_manifest_sha256'=v_manifest_hash
  ) then
    raise exception 'canonical PAPER enqueue omitted the closed Office/Candidate authority identity';
  end if;
  v_response:=public.candidate_workflow_transition_atomic_v1(
    null,'TEST',v_workflow,'PAPER_PACK_MARK_FAILURE',2,jsonb_build_object(
      'service_paper_pack_failure',true,
      'mail_outbox_id',v_mail,
      'paper_return_manifest_sha256',v_manifest_hash,
      'error_code','CANDIDATE_PAPER_PACK_ASSEMBLY_TRANSIENT'
    ),'paper:pack:failure:retryable',now()
  );
  if v_response->>'paper_pack_state'<>'FAILED_RETRYABLE'
     or not coalesce((v_response->>'retryable')::boolean,false)
     or not exists(
       select 1 from public.mail_outbox mail where mail.id=v_mail
         and lower(coalesce(mail.payment_scope_json->>'candidate_paper_pack_retryable','false'))
           in ('true','t','1','yes')
     ) then
    raise exception 'production PAPER failure owner did not create a retryable receipt: %',v_response;
  end if;

  v_page:=(v_manifest->'pages')->0;
  v_response:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'COMPONENT_PREPARE',2,jsonb_build_object(
      'component_kind','SIGNED_RETURN','document_role','SIGNED_RETURN',
      'paper_return_page_key',v_page->>'page_key',
      'storage_key','paper/returned/first.pdf','media_type','application/pdf','byte_size',512
    ),'paper:return:first:prepare',now());
  v_return_component:=(v_response->>'component_id')::uuid;
  perform public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'COMPONENT_COMPLETE',2,jsonb_build_object(
      'component_id',v_return_component,'source_content_sha256_hex',repeat('a4',32),
      'verified_byte_size',512,'verified_media_type','application/pdf'
    ),'paper:return:first:complete',now());
  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'PAPER_RETURN',2,'{}'::jsonb,'paper:return:incomplete',now());
    raise exception 'one returned page was accepted as a complete paper pack';
  exception when sqlstate '22023' then
    if sqlerrm<>'CANDIDATE_PAPER_RETURN_INCOMPLETE' then raise; end if;
  end;
  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'COMPONENT_PREPARE',2,jsonb_build_object(
        'component_kind','SIGNED_RETURN','document_role','SIGNED_RETURN',
        'paper_return_page_key',v_page->>'page_key',
        'storage_key','paper/returned/duplicate.pdf','media_type','application/pdf','byte_size',512
      ),'paper:return:duplicate:prepare',now());
    raise exception 'duplicate returned paper page was accepted';
  exception when sqlstate '23505' then
    if sqlerrm<>'CANDIDATE_PAPER_RETURN_PAGE_DUPLICATE' then raise; end if;
  end;

  for v_page in select value from jsonb_array_elements(v_manifest->'pages') with ordinality p(value,ordinality)
    where ordinality>1 order by ordinality
  loop
    v_counter:=v_counter+1;
    v_response:=public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'COMPONENT_PREPARE',2,jsonb_build_object(
        'component_kind','SIGNED_RETURN','document_role','SIGNED_RETURN',
        'paper_return_page_key',v_page->>'page_key',
        'storage_key','paper/returned/'||v_counter::text||'.pdf',
        'media_type','application/pdf','byte_size',512
      ),'paper:return:'||v_counter::text||':prepare',now());
    v_return_component:=(v_response->>'component_id')::uuid;
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_workflow,'COMPONENT_COMPLETE',2,jsonb_build_object(
        'component_id',v_return_component,
        'source_content_sha256_hex',encode(extensions.digest(
          convert_to('paper-return-'||v_counter::text,'UTF8'),'sha256'),'hex'),
        'verified_byte_size',512,'verified_media_type','application/pdf'
      ),'paper:return:'||v_counter::text||':complete',now());
  end loop;
  v_response:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'PAPER_RETURN',2,'{}'::jsonb,'paper:return:complete',now());
  if v_response->>'state'<>'RECEIVED' then
    raise exception 'complete paper pack did not become received: %',v_response;
  end if;

  v_row_signature:=public.timesheet_lifecycle_guard_signature_v1(v_timesheet,v_week,false)->>'row_signature';
  v_service:=jsonb_build_object(
    'contract_version','CANDIDATE_MANAGER_FINALISATION_V1',
    'workflow_generation',2,
    'approval_method','PAPER',
    'approval_request_id',null,
    'approval_request_generation',null,
    'review_manifest_sha256_hex','',
    'paper_return_manifest_sha256_hex',v_manifest_hash,
    'finalisation_identity',jsonb_build_object(
      'contract_version','CANDIDATE_FINALISATION_IDENTITY_V1',
      'workflow_id',v_workflow,
      'workflow_generation',2,
      'approval_method','PAPER',
      'approval_request_id',null,
      'approval_request_generation',null,
      'review_manifest_sha256_hex',null,
      'paper_return_manifest_sha256_hex',v_manifest_hash
    )
  );
  begin
    perform public.cloudtms_office_candidate_adapter_v1(
      'FINALISE_EXECUTE',v_actor,'TEST',jsonb_build_object(
        'workflow_id',v_workflow,
        'generation',2,
        'expected_row_signature',repeat('0',64),
        'idempotency_key','paper:finalise:initial',
        'daily_materialisation_json',jsonb_build_object('service_finalisation',v_service)
      ),now()
    );
    raise exception 'stale initial PAPER finalisation unexpectedly succeeded';
  exception when others then
    if sqlerrm='ROW_SIGNATURE_MISMATCH' then
      v_failed:=true;
    else
      raise;
    end if;
  end;
  if not v_failed
     or (select state from public.candidate_submission_workflows where id=v_workflow)<>'RECEIVED'
     or exists(
       select 1 from public.audit_events ae
       where ae.object_type='candidate_workflow_finalisation_completion'
         and ae.object_id_text=v_workflow::text
     ) then
    raise exception 'failed initial PAPER finalisation left lifecycle or completion residue';
  end if;
  v_response:=public.cloudtms_office_candidate_adapter_v1(
    'FINALISE_EXECUTE',v_actor,'TEST',jsonb_build_object(
      'workflow_id',v_workflow,
      'generation',2,
      'expected_row_signature',v_row_signature,
      'idempotency_key','paper:finalise:retry',
      'daily_materialisation_json',jsonb_build_object('service_finalisation',v_service)
    ),now()
  );
  if v_response->>'state'<>'FINALISED' then
    raise exception 'complete paper pack did not finalise: %',v_response;
  end if;
  if not exists(select 1 from public.timesheets
    where timesheet_id=v_timesheet and submission_mode='MANUAL'
      and r2_nurse_key is null and r2_auth_key is null) then
    raise exception 'PAPER finalisation did not preserve the expected unsigned MANUAL Timesheet';
  end if;
  if (select count(*) from public.timesheet_evidence where timesheet_id=v_timesheet)<>2 then
    raise exception 'PAPER finalisation did not attach exactly two returned evidence rows: %',
      (select jsonb_agg(jsonb_build_object(
        'kind',kind,'document_role',document_role,'display_name',display_name,
        'candidate_component_id',candidate_component_id
      ) order by created_at_utc,id) from public.timesheet_evidence where timesheet_id=v_timesheet);
  end if;
  if not exists(select 1 from public.timesheet_evidence
    where timesheet_id=v_timesheet and kind='TIMESHEET' and document_role='SIGNED_TIMESHEET') then
    raise exception 'PAPER finalisation did not attach the signed Timesheet evidence';
  end if;
  if exists(
       select 1
       from public.timesheet_evidence evidence
       join public.candidate_submission_components component
         on component.id=evidence.candidate_component_id
       where evidence.timesheet_id=v_timesheet
         and component.component_kind='EXPENSE_SUMMARY'
     ) then
    raise exception 'PAPER finalisation attached the internal Expense summary as a returned page: %',
      (select jsonb_agg(jsonb_build_object(
        'display_name',evidence.display_name,
        'candidate_component_id',evidence.candidate_component_id,
        'component_kind',component.component_kind,
        'paper_return_page_key',component.paper_return_page_key
      ))
       from public.timesheet_evidence evidence
       left join public.candidate_submission_components component
         on component.id=evidence.candidate_component_id
       where evidence.timesheet_id=v_timesheet);
  end if;
  if not exists(
       select 1
       from public.timesheet_evidence evidence
       join public.candidate_submission_components component
         on component.id=evidence.candidate_component_id
       join lateral jsonb_array_elements(v_manifest->'pages') manifest_page
         on manifest_page->>'page_key'=component.paper_return_page_key
       where evidence.timesheet_id=v_timesheet
         and manifest_page->>'component_kind'='EXPENSE_EVIDENCE'
         and manifest_page->>'display_name'='Other 1'
         and evidence.display_name=manifest_page->>'display_name'
     ) then
    raise exception 'PAPER finalisation did not attach the Other 1 manifest label: %',
      (select jsonb_agg(jsonb_build_object('display_name',display_name,'candidate_component_id',candidate_component_id))
       from public.timesheet_evidence where timesheet_id=v_timesheet);
  end if;
  v_response:=public.cloudtms_office_candidate_adapter_v1(
    'FINALISE_REPLAY_LOOKUP',v_actor,'TEST',jsonb_build_object(
      'workflow_id',v_workflow,
      'generation',2,
      'expected_row_signature',repeat('0',64),
      'idempotency_key','paper:finalise:initial',
      'daily_materialisation_json',jsonb_build_object('service_finalisation',v_service)
    ),now()
  );
  if v_response->>'state'<>'FINALISED'
     or v_response->>'generation'<>'3'
     or not coalesce((v_response->>'idempotent_replay')::boolean,false) then
    raise exception 'failed trigger key did not find the later canonical PAPER completion: %',v_response;
  end if;
end;
$paper_complete_pack$;
select 'PASS'::text as candidate_paper_evidence_manifest_label_runtime_verification;

-- Rollback-contained first-use proof for Banking Pay DIRTY_APPLY family
-- authority. A trigger may initially invalidate one Timesheet, while the
-- bounded dependency/rotation closure later proves a wider version family.
-- The processor must establish one current authority for the final family
-- before scanning sessions. Historical terminal jobs for the two proven
-- authority errors remain immutable audit evidence and receive one canonical,
-- idempotent full-Candidate successor while an open session is still stuck.

SET LOCAL statement_timeout='30s';

DO $verification$
DECLARE
  v_snapshot_id uuid:=gen_random_uuid();
  v_actor_id uuid:=gen_random_uuid();
  v_family_candidate_id uuid:=gen_random_uuid();
  v_repair_candidate_id uuid:=gen_random_uuid();
  v_current_timesheet_id uuid:=gen_random_uuid();
  v_history_timesheet_id uuid:=gen_random_uuid();
  v_family_job_id uuid;
  v_dead_job_id uuid:=gen_random_uuid();
  v_repair_session_id uuid:=gen_random_uuid();
  v_booking_id text:='BPAY-FAMILY-VERIFY-'||gen_random_uuid()::text;
  v_prefix text:='BANKING_PAY_DIRTY_FAMILY_VERIFY:'||gen_random_uuid()::text;
  v_seed_result jsonb:='{}'::jsonb;
  v_stage_result jsonb:='{}'::jsonb;
  v_process_result jsonb:='{}'::jsonb;
  v_repair_result jsonb:='{}'::jsonb;
  v_replay_result jsonb:='{}'::jsonb;
  v_pre_repair jsonb:='{}'::jsonb;
  v_old_generation bigint:=0;
  v_new_generation bigint:=0;
  v_dead_before jsonb:='{}'::jsonb;
  v_dead_after jsonb:='{}'::jsonb;
  v_successor_id uuid;
  v_definition text;
  v_authority_contract_mismatch jsonb:='[]'::jsonb;
  v_pre record;
  v_operations_before bigint;
  v_batches_before bigint;
  v_provider_before bigint;
  v_settlement_before bigint;
  v_remittance_before bigint;
BEGIN
  WITH expected(identity,definition_sha256,expected_config) AS (
    VALUES
      ('public._pay_active_settled_components(uuid[])'::regprocedure,NULL::text,NULL::text[]),
      ('public.bulk_authorise_dataset_v1(jsonb)'::regprocedure,
       '88880fc433528df687f6eb83983679ad0afc0cc8e6913971de7848874e3a4e71'::text,
       ARRAY['search_path=public']::text[]),
      ('public.bulk_authorise_row_context_v1(jsonb)'::regprocedure,NULL::text,NULL::text[]),
      ('public.bulk_process_dataset_v1(jsonb)'::regprocedure,NULL::text,NULL::text[]),
      ('public.bulk_process_row_context_v1(jsonb)'::regprocedure,NULL::text,NULL::text[]),
      ('public.bulk_timesheet_row_patch_v1(jsonb)'::regprocedure,NULL::text,NULL::text[]),
      -- MOVED at the Plan 6.2 final seals pass (WP-15d), 18 September 2026,
      -- under HANDOVER 2 round-5 Part C.  This is the second of the two pins on
      -- the same identity; both move together to the same value.  Previous pin
      -- ac3a122f00af03e35bb2c40e82ddb114571f7252a6ac31d9bfec23d7cb3afc19.
      -- This file hashes the raw definition while 29082026_0336 normalises CRLF
      -- to LF first; the installed definition contains zero CR bytes, so both
      -- forms yield the same value and both pins carry it.  The expected
      -- proconfig below is deliberately unchanged: only the definition moved.
      ('public.contract_week_manual_upsert_atomic(uuid,uuid,jsonb,jsonb,jsonb,jsonb,jsonb,uuid,boolean,timestamptz,text,jsonb)'::regprocedure,
       'd05fe8c683bfe6dc5a850d57360a2d1ef303fd184773cafb2a8a6ebbf018f21f'::text,
       ARRAY['search_path=public']::text[]),
      ('public.pay_preview_candidate_build_canonical_lines(jsonb,uuid)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_preview_candidate_build_finance_case_baseline(jsonb,uuid)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_timesheet_summary_pay_state_refresh_trigger()'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_contract_client_dirty_fanout_chunk(uuid,jsonb,integer)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_dirty_apply_jobs_chunk(integer,timestamptz,uuid,uuid,text,integer)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_enqueue_candidate_refresh(uuid,uuid,text,uuid,jsonb)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_enqueue_stage_continuation(uuid,uuid,text,jsonb,uuid,jsonb,uuid,text,integer,integer)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_repair_invalid_source_build_poison(uuid,uuid,integer,timestamptz,text)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_session_clear_case_resolution(uuid,uuid,jsonb)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_session_clone_eligibility_v1(uuid,uuid,uuid,jsonb)'::regprocedure,NULL::text,NULL::text[]),
      ('public.pay_workbench_session_replay_replaced_queue_v1(uuid,uuid,text,jsonb)'::regprocedure,
       '363aeab20aed70b8396793808f9a2263766e984d66914317bdf0a767e6e0f360'::text,
       ARRAY['search_path=""']::text[]),
      ('public.pay_workbench_session_set_selected_rows(uuid,jsonb,uuid)'::regprocedure,
       '7d622194f7bca877bf8420cb6f10f9ad46a69bad118c5f8fb9ed16810492d98c'::text,
       ARRAY['search_path=public']::text[]),
      ('public.pay_workbench_worker_drain_chunk(integer,timestamptz,uuid,uuid,text[],text,integer)'::regprocedure,NULL::text,NULL::text[]),
      ('public.timesheet_authorise_bulk_atomic(jsonb,uuid,timestamptz)'::regprocedure,NULL::text,NULL::text[]),
      ('public.timesheet_authorise_generic_atomic(uuid,uuid,uuid,timestamptz,text)'::regprocedure,NULL::text,NULL::text[]),
      ('public.timesheet_daily_manual_process_atomic(uuid,uuid,uuid,jsonb,jsonb,timestamptz,text)'::regprocedure,NULL::text,NULL::text[]),
      ('public.timesheet_lifecycle_guard_signature_v1(uuid,uuid,boolean)'::regprocedure,NULL::text,NULL::text[]),
      ('public.timesheet_qr_send_enqueue_v1(uuid,uuid,uuid,text,timestamptz)'::regprocedure,
       '090fcbd7a66ade81f107635c360a038a514a5c26358c0b4aa716bdea91245347'::text,
       ARRAY['search_path=public']::text[])
  ), actual AS (
    SELECT
      expected.identity,
      expected.definition_sha256,
      expected.expected_config,
      pg_catalog.encode(extensions.digest(
        pg_catalog.convert_to(pg_catalog.pg_get_functiondef(expected.identity::oid),'UTF8'),
        'sha256'
      ),'hex') AS actual_definition_sha256,
      pg_catalog.pg_get_userbyid(proc.proowner) AS owner_name,
      proc.proconfig AS actual_config,
      COALESCE((
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'grantee',normalised_acl.grantee,
          'privilege',normalised_acl.privilege,
          'grantable',normalised_acl.grantable
        ) ORDER BY
          normalised_acl.grantee COLLATE "C",
          normalised_acl.privilege COLLATE "C",
          normalised_acl.grantable)
        FROM (
          SELECT DISTINCT
            CASE
              WHEN function_acl.grantee=proc.proowner
                OR pg_catalog.pg_get_userbyid(function_acl.grantee)='postgres'
                THEN 'OWNER'
              WHEN function_acl.grantee=0 THEN 'PUBLIC'
              ELSE pg_catalog.pg_get_userbyid(function_acl.grantee)
            END AS grantee,
            function_acl.privilege_type AS privilege,
            function_acl.is_grantable AS grantable
          FROM pg_catalog.aclexplode(COALESCE(
            proc.proacl,pg_catalog.acldefault('f'::"char",proc.proowner)
          )) AS function_acl
        ) AS normalised_acl
      ),'[]'::jsonb) AS actual_acl,
      pg_catalog.has_function_privilege('service_role',expected.identity::oid,'EXECUTE') AS service_execute,
      pg_catalog.has_function_privilege('anon',expected.identity::oid,'EXECUTE') AS anon_execute,
      pg_catalog.has_function_privilege('authenticated',expected.identity::oid,'EXECUTE') AS authenticated_execute
    FROM expected
    JOIN pg_catalog.pg_proc AS proc ON proc.oid=expected.identity::oid
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'identity',identity::text,
    'expected_definition_sha256',definition_sha256,
    'actual_definition_sha256',actual_definition_sha256,
    'owner_name',owner_name,
    'expected_config',expected_config,
    'actual_config',actual_config,
    'actual_acl',actual_acl,
    'service_execute',service_execute,
    'anon_execute',anon_execute,
    'authenticated_execute',authenticated_execute
  ) ORDER BY identity::text),'[]'::jsonb)
  INTO v_authority_contract_mismatch
  FROM actual
  WHERE (definition_sha256 IS NOT NULL AND actual_definition_sha256 IS DISTINCT FROM definition_sha256)
     OR (expected_config IS NOT NULL AND actual_config IS DISTINCT FROM expected_config)
     OR owner_name IS DISTINCT FROM current_user
     OR actual_acl IS DISTINCT FROM pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object(
            'grantee','OWNER','privilege','EXECUTE','grantable',false
          ),
          pg_catalog.jsonb_build_object(
            'grantee','service_role','privilege','EXECUTE','grantable',false
          )
        )
     OR service_execute IS NOT TRUE
     OR anon_execute IS TRUE
     OR authenticated_execute IS TRUE;

  IF pg_catalog.jsonb_array_length(v_authority_contract_mismatch)<>0 THEN
    RAISE EXCEPTION USING
      MESSAGE='BANKING_PAY_FINAL_AUTHORITY_CLOSURE_MISMATCH',
      DETAIL=v_authority_contract_mismatch::text;
  END IF;

  SELECT pg_get_functiondef(
    'public.pay_workbench_candidate_dirty_apply_job_process(uuid,integer)'::regprocedure
  )||E'\n'||pg_get_functiondef(
    'public.pay_workbench_repair_invalid_dirty_apply_jobs_v1(uuid,uuid,integer,text)'::regprocedure
  ) INTO STRICT v_definition;
  IF v_definition ~* 'pg_catalog\.(coalesce|nullif|least|greatest)\s*\(' THEN
    RAISE EXCEPTION 'BANKING_PAY_DIRTY_FAMILY_ILLEGAL_CONDITIONAL_PREFIX';
  END IF;

  IF has_function_privilege(
       'anon','public.pay_workbench_repair_invalid_dirty_apply_jobs_v1(uuid,uuid,integer,text)','EXECUTE'
     )
     OR has_function_privilege(
       'authenticated','public.pay_workbench_repair_invalid_dirty_apply_jobs_v1(uuid,uuid,integer,text)','EXECUTE'
     )
     OR NOT has_function_privilege(
       'service_role','public.pay_workbench_repair_invalid_dirty_apply_jobs_v1(uuid,uuid,integer,text)','EXECUTE'
     )
     OR has_function_privilege(
       'anon','public.pay_workbench_candidate_dirty_apply_job_process(uuid,integer)','EXECUTE'
     )
     OR has_function_privilege(
       'authenticated','public.pay_workbench_candidate_dirty_apply_job_process(uuid,integer)','EXECUTE'
     )
     OR NOT has_function_privilege(
       'service_role','public.pay_workbench_candidate_dirty_apply_job_process(uuid,integer)','EXECUTE'
     ) THEN
    RAISE EXCEPTION 'BANKING_PAY_DIRTY_FAMILY_ACL_INVALID';
  END IF;

  SELECT count(*) INTO v_operations_before FROM public.banking_pay_operations;
  SELECT count(*) INTO v_batches_before FROM public.pay_batches;
  SELECT count(*) INTO v_provider_before
  FROM public.banking_pay_operation_provider_attempts;
  SELECT count(*) INTO v_settlement_before
  FROM public.banking_pay_operation_settlement_scope;
  SELECT count(*) INTO v_remittance_before
  FROM public.banking_pay_operation_remittance_scope;

  INSERT INTO public.banking_pay_snapshot_runs(
    id,pay_date,week_ending_cutoff,pay_week_start,eligibility_from_date,
    eligibility_to_date,status,is_active
  ) VALUES (
    v_snapshot_id,DATE '2099-04-10',DATE '2099-04-05',DATE '2099-03-30',
    DATE '2099-03-01',DATE '2099-04-05','OPEN',false
  );

  INSERT INTO public.tms_users(id,email,password_hash,role,is_active)
  VALUES (
    v_actor_id,
    'bpay-dirty-family-'||replace(v_actor_id::text,'-','')||'@example.invalid',
    'UNUSABLE_ROLLBACK_VERIFIER','admin',true
  );

  INSERT INTO public.candidates(id,display_name,tms_ref,pay_method) VALUES
    (v_family_candidate_id,v_prefix||':FAMILY',v_prefix||':FAMILY','PAYE'),
    (v_repair_candidate_id,v_prefix||':REPAIR',v_prefix||':REPAIR','PAYE');

  INSERT INTO public.app_change_counters(entity_key,seq,scope_change_generation)
  VALUES
    ('pay_candidate:'||v_family_candidate_id::text,7,0),
    ('pay_candidate:'||v_repair_candidate_id::text,11,0)
  ON CONFLICT(entity_key) DO UPDATE SET
    seq=EXCLUDED.seq,scope_change_generation=EXCLUDED.scope_change_generation;

  INSERT INTO public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,week_ending_date,status,is_current,version,revoked_at,
    revoked_reason
  ) VALUES
    (v_history_timesheet_id,v_booking_id,v_prefix,'VERIFY','VERIFY','VERIFY',
      DATE '2099-04-05','REVOKED',false,1,clock_timestamp(),'VERSION_REPLACED'),
    (v_current_timesheet_id,v_booking_id,v_prefix,'VERIFY','VERIFY','VERIFY',
      DATE '2099-04-05','RECEIVED',true,2,NULL,NULL);

  INSERT INTO public.timesheets_financials(
    timesheet_id,timesheet_version,is_current,candidate_id,
    candidate_assignment,processing_status
  ) VALUES (
    v_current_timesheet_id,2,true,v_family_candidate_id,'ASSIGNED','READY_FOR_HR'
  );

  -- Reproduce the original one-row trigger knowledge. The invalidator creates
  -- the ordinary canonical DIRTY_APPLY owner and finalises its authority.
  v_seed_result:=private.pay_workbench_scope_invalidate_v1(
    ARRAY[v_family_candidate_id],ARRAY[v_current_timesheet_id],
    'VERIFICATION_ONE_ROW_TRIGGER',NULL::uuid,
    jsonb_build_object(
      'source_change_seq',7,
      'latest_source_change_seq',7,
      'trigger_source','ROLLBACK_VERIFICATION',
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
      'economic_truth_mutation_allowed',false
    )
  );

  -- The real trigger request commits before the worker claims its job. Force
  -- only this rollback verifier's deferred constraint at the same boundary.
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 IMMEDIATE';
  PERFORM set_config('cloudtms.scope_generation_finalising','false',true);
  PERFORM set_config('cloudtms.banking_pay_scope_tx_token','',true);
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 DEFERRED';

  SELECT job.id,job.scope_change_generation
  INTO STRICT v_family_job_id,v_old_generation
  FROM public.banking_pay_workbench_jobs AS job
  WHERE job.candidate_id=v_family_candidate_id
    AND job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
    AND job.status='QUEUED'
  ORDER BY job.created_at_utc DESC,job.id DESC
  LIMIT 1;

  IF COALESCE((v_seed_result->>'ok')::boolean,false) IS NOT TRUE
     OR v_old_generation<1
     OR jsonb_array_length(
       (SELECT payload_json->'targeted_timesheet_ids'
        FROM public.banking_pay_workbench_jobs WHERE id=v_family_job_id)
     )<>1 THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_DIRTY_FAMILY_SEED_INVALID',
      DETAIL=v_seed_result::text;
  END IF;

  UPDATE public.banking_pay_workbench_jobs
  SET status='RUNNING',attempt_count=1,started_at_utc=clock_timestamp(),
      updated_at_utc=clock_timestamp()
  WHERE id=v_family_job_id;

  v_stage_result:=public.pay_workbench_candidate_dirty_apply_job_process(
    v_family_job_id,100
  );

  IF COALESCE((v_stage_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_stage_result->>'preinvalidated_scope_reissued')::boolean,false)
          IS NOT TRUE
     OR COALESCE((v_stage_result->>'preinvalidated_scope_reissue_pending_finalization')::boolean,false)
          IS NOT TRUE
     OR COALESCE((v_stage_result->>'family_timesheet_count')::integer,-1)<>2
     OR (SELECT status FROM public.banking_pay_workbench_jobs
         WHERE id=v_family_job_id) IS DISTINCT FROM 'QUEUED' THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_DIRTY_FAMILY_REISSUE_NOT_STAGED',
      DETAIL=v_stage_result::text;
  END IF;

  -- The real RPC now commits, the canonical deferred finaliser assigns one
  -- generation, and the worker later claims the same durable job again.
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 IMMEDIATE';
  PERFORM set_config('cloudtms.scope_generation_finalising','false',true);
  PERFORM set_config('cloudtms.banking_pay_scope_tx_token','',true);
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 DEFERRED';
  SELECT job.payload_json,job.scope_change_generation,
    tx.state AS tx_state,tx.allocated_generation AS tx_generation,
    registry.dirty_generation AS registry_generation,
    counter.scope_change_generation AS live_generation,
    (SELECT count(*) FROM private.banking_pay_workbench_timesheet_scope_state state
      WHERE state.candidate_id=v_family_candidate_id
        AND state.timesheet_id IN (v_history_timesheet_id,v_current_timesheet_id)
        AND state.dirty_generation=job.scope_change_generation) AS matched_count
  INTO STRICT v_pre
  FROM public.banking_pay_workbench_jobs job
  LEFT JOIN public.banking_pay_scope_change_transactions tx
    ON tx.tx_token=(job.payload_json->>'scope_change_tx_token')::uuid
  JOIN private.banking_pay_workbench_candidate_scope_registry registry
    ON registry.candidate_id=job.candidate_id
  LEFT JOIN public.app_change_counters counter
    ON counter.entity_key='pay_candidate:'||job.candidate_id::text
  WHERE job.id=v_family_job_id;
  IF v_pre.tx_state IS DISTINCT FROM 'FINALIZED'
     OR v_pre.tx_generation IS DISTINCT FROM v_pre.scope_change_generation
     OR v_pre.registry_generation IS DISTINCT FROM v_pre.scope_change_generation
     OR v_pre.live_generation IS DISTINCT FROM v_pre.scope_change_generation
     OR v_pre.matched_count<>2
     OR lower(COALESCE(v_pre.payload_json->>'bounded_scope_state_precedes_job','false'))<>'true' THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_DIRTY_FAMILY_STAGED_AUTHORITY_NOT_FINAL',
      DETAIL=to_jsonb(v_pre)::text;
  END IF;
  UPDATE public.banking_pay_workbench_jobs
  SET status='RUNNING',attempt_count=attempt_count+1,
      started_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp()
  WHERE id=v_family_job_id;

  v_process_result:=public.pay_workbench_candidate_dirty_apply_job_process(
    v_family_job_id,100
  );
  v_new_generation:=(v_process_result->>'effective_scope_change_generation')::bigint;

  IF COALESCE((v_process_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_process_result->>'preinvalidated_scope_reissued')::boolean,false)
          IS NOT TRUE
     OR COALESCE((v_process_result->>'family_timesheet_count')::integer,-1)<>2
     OR v_new_generation<=v_old_generation
     OR (SELECT scope_change_generation
         FROM public.banking_pay_workbench_jobs WHERE id=v_family_job_id)
          IS DISTINCT FROM v_new_generation
     OR (SELECT count(*)
         FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
         WHERE scope_state.candidate_id=v_family_candidate_id
           AND scope_state.timesheet_id IN (
             v_history_timesheet_id,v_current_timesheet_id
           )
           AND scope_state.dirty_generation=v_new_generation)<>2
     OR (SELECT status FROM public.timesheets
         WHERE timesheet_id=v_history_timesheet_id) IS DISTINCT FROM 'REVOKED'
     OR (SELECT is_current FROM public.timesheets
         WHERE timesheet_id=v_history_timesheet_id) IS NOT FALSE THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_DIRTY_FAMILY_FINAL_AUTHORITY_INVALID',
      DETAIL=jsonb_build_object(
        'seed',v_seed_result,'stage',v_stage_result,'process',v_process_result,
        'old_generation',v_old_generation,'new_generation',v_new_generation
      )::text;
  END IF;

  -- Build the historical failure shape independently. The repair needs an
  -- open still-dirty session, but it must never alter the DEAD source row.
  INSERT INTO public.banking_pay_workbench_sessions(
    id,actor_user_id,pay_date,week_ending_cutoff,session_signature,
    source_snapshot_run_id,status,version,scope_change_generation_target,
    scope_change_generation_applied
  ) VALUES (
    v_repair_session_id,v_actor_id,DATE '2099-04-10',DATE '2099-04-05',
    v_prefix||':REPAIR_SESSION',v_snapshot_id,'OPEN',4,2,1
  );

  INSERT INTO public.banking_pay_workbench_session_scope(
    session_id,candidate_id,scope_ordinal,status,seeded,dirty,error_json
  ) VALUES (
    v_repair_session_id,v_repair_candidate_id,1,'FAILED',true,true,
    jsonb_build_object('code','VERIFICATION_STUCK_SCOPE')
  );

  -- Candidate creation itself legitimately emits an ordinary dirty event.
  -- Close only that rollback-fixture owner before constructing the later DEAD
  -- authority failure, so the repair is tested against its real eligibility
  -- rule: no currently active DIRTY_APPLY already owns the Candidate.
  UPDATE public.banking_pay_workbench_jobs
  SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),
      updated_at_utc=clock_timestamp()
  WHERE candidate_id=v_repair_candidate_id
    AND job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
    AND status IN ('QUEUED','RUNNING');

  INSERT INTO public.banking_pay_workbench_jobs(
    id,job_type,status,priority,run_at_utc,attempt_count,max_attempts,dedupe_key,
    snapshot_run_id,session_id,candidate_id,payload_json,failed_at_utc,
    last_error_json,created_at_utc,updated_at_utc
  ) VALUES (
    v_dead_job_id,'WORKBENCH_CANDIDATE_DIRTY_APPLY','DEAD',-1000,
    clock_timestamp(),8,8,v_prefix||':DEAD',v_snapshot_id,
    v_repair_session_id,v_repair_candidate_id,
    jsonb_build_object('source_change_seq',11,'targeted_timesheet_ids','[]'::jsonb),
    clock_timestamp(),
    jsonb_build_object(
      'message','PAY_WORKBENCH_PRECEDING_SCOPE_INVALIDATION_UNPROVED',
      'code','PAY_WORKBENCH_PRECEDING_SCOPE_INVALIDATION_UNPROVED'
    ),clock_timestamp(),clock_timestamp()
  );

  -- A directly inserted fixture job passes through the normal job-stage
  -- trigger. Finish that historical row's own transaction before capturing
  -- its immutable terminal shape, as would already be true in production.
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 IMMEDIATE';
  PERFORM set_config('cloudtms.scope_generation_finalising','false',true);
  PERFORM set_config('cloudtms.banking_pay_scope_tx_token','',true);
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 DEFERRED';

  SELECT to_jsonb(job) INTO STRICT v_dead_before
  FROM public.banking_pay_workbench_jobs AS job WHERE job.id=v_dead_job_id;

  SELECT jsonb_build_object(
    'dead_matches',(SELECT count(*) FROM public.banking_pay_workbench_jobs job
      WHERE job.id=v_dead_job_id AND job.status='DEAD'
        AND job.last_error_json->>'message' IN (
          'PAY_WORKBENCH_PRECEDING_SCOPE_INVALIDATION_UNPROVED',
          'PAY_WORKBENCH_STALE_PREINVALIDATED_AUTHORITY_NOT_CURRENT')),
    'open_stuck_scope',(SELECT count(*)
      FROM public.banking_pay_workbench_sessions session_row
      JOIN public.banking_pay_workbench_session_scope scope_row
        ON scope_row.session_id=session_row.id
       AND scope_row.candidate_id=v_repair_candidate_id
      WHERE session_row.id=v_repair_session_id
        AND session_row.status='OPEN' AND session_row.discarded_at_utc IS NULL
        AND (scope_row.dirty OR scope_row.error_json IS NOT NULL
          OR session_row.scope_change_generation_applied
             <session_row.scope_change_generation_target)),
    'active_dirty',(SELECT count(*) FROM public.banking_pay_workbench_jobs job
      WHERE job.candidate_id=v_repair_candidate_id
        AND job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND job.status IN ('QUEUED','RUNNING')),
    'later_success',(SELECT count(*) FROM public.banking_pay_workbench_jobs job
      WHERE job.candidate_id=v_repair_candidate_id
        AND job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND job.status='SUCCEEDED'
        AND (job.updated_at_utc,job.id)>
            ((v_dead_before->>'updated_at_utc')::timestamptz,v_dead_job_id))
  ) INTO v_pre_repair;
  IF (v_pre_repair->>'dead_matches')::integer<>1
     OR (v_pre_repair->>'open_stuck_scope')::integer<>1
     OR (v_pre_repair->>'active_dirty')::integer<>0
     OR (v_pre_repair->>'later_success')::integer<>0 THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_DIRTY_FAMILY_REPAIR_FIXTURE_INVALID',
      DETAIL=v_pre_repair::text;
  END IF;

  v_repair_result:=public.pay_workbench_repair_invalid_dirty_apply_jobs_v1(
    v_repair_session_id,v_repair_candidate_id,1,'ROLLBACK_VERIFICATION'
  );
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 IMMEDIATE';
  PERFORM set_config('cloudtms.scope_generation_finalising','false',true);
  PERFORM set_config('cloudtms.banking_pay_scope_tx_token','',true);
  EXECUTE 'SET CONSTRAINTS trg_pay_workbench_scope_change_finalize_v1 DEFERRED';

  SELECT to_jsonb(job) INTO STRICT v_dead_after
  FROM public.banking_pay_workbench_jobs AS job WHERE job.id=v_dead_job_id;
  SELECT job.id INTO v_successor_id
  FROM public.banking_pay_workbench_jobs AS job
  WHERE job.candidate_id=v_repair_candidate_id
    AND job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
    AND job.status IN ('QUEUED','RUNNING')
    AND job.payload_json->>'invalid_dirty_apply_repair_source_job_id'
        =v_dead_job_id::text
  ORDER BY job.created_at_utc DESC,job.id DESC LIMIT 1;

  IF COALESCE((v_repair_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_repair_result->>'repaired_candidate_count')::integer,-1)<>1
     OR COALESCE((v_repair_result->>'successor_job_count')::integer,-1)<>1
     OR COALESCE((v_repair_result->>'failed_count')::integer,-1)<>0
     OR v_dead_after IS DISTINCT FROM v_dead_before
     OR v_successor_id IS NULL
     OR COALESCE((SELECT scope_change_generation
         FROM public.banking_pay_workbench_jobs WHERE id=v_successor_id),0)<1
     OR (SELECT dirty_generation
         FROM private.banking_pay_workbench_candidate_scope_registry
         WHERE candidate_id=v_repair_candidate_id)
          IS DISTINCT FROM (SELECT scope_change_generation
            FROM public.banking_pay_workbench_jobs WHERE id=v_successor_id)
     OR (SELECT scope_change_generation FROM public.app_change_counters
         WHERE entity_key='pay_candidate:'||v_repair_candidate_id::text)
          IS DISTINCT FROM (SELECT scope_change_generation
            FROM public.banking_pay_workbench_jobs WHERE id=v_successor_id)
     OR jsonb_array_length(
       (SELECT payload_json->'targeted_timesheet_ids'
        FROM public.banking_pay_workbench_jobs WHERE id=v_successor_id)
     )<>0
     OR (SELECT status FROM public.banking_pay_workbench_jobs
         WHERE id=v_dead_job_id) IS DISTINCT FROM 'DEAD' THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_DIRTY_FAMILY_REPAIR_INVALID',
      DETAIL=jsonb_build_object(
        'result',v_repair_result,'dead_unchanged',v_dead_after=v_dead_before,
        'successor_id',v_successor_id,'dead_before',v_dead_before,
        'dead_after',v_dead_after
      )::text;
  END IF;

  v_replay_result:=public.pay_workbench_repair_invalid_dirty_apply_jobs_v1(
    v_repair_session_id,v_repair_candidate_id,1,'ROLLBACK_VERIFICATION_REPLAY'
  );
  IF COALESCE((v_replay_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_replay_result->>'examined_candidate_count')::integer,-1)<>0
     OR COALESCE((v_replay_result->>'repaired_candidate_count')::integer,-1)<>0
     OR (SELECT count(*) FROM public.banking_pay_workbench_jobs
         WHERE candidate_id=v_repair_candidate_id
           AND job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
           AND payload_json->>'invalid_dirty_apply_repair_source_job_id'
               =v_dead_job_id::text)<>1 THEN
    RAISE EXCEPTION USING MESSAGE='BANKING_PAY_DIRTY_FAMILY_REPAIR_NOT_IDEMPOTENT',
      DETAIL=v_replay_result::text;
  END IF;

  IF (SELECT count(*) FROM public.banking_pay_operations)<>v_operations_before
     OR (SELECT count(*) FROM public.pay_batches)<>v_batches_before
     OR (SELECT count(*) FROM public.banking_pay_operation_provider_attempts)
          <>v_provider_before
     OR (SELECT count(*) FROM public.banking_pay_operation_settlement_scope)
          <>v_settlement_before
     OR (SELECT count(*) FROM public.banking_pay_operation_remittance_scope)
          <>v_remittance_before THEN
    RAISE EXCEPTION 'BANKING_PAY_DIRTY_FAMILY_FINANCIAL_LIFECYCLE_CHANGED';
  END IF;

  RAISE NOTICE 'PASS: final Timesheet-family authority is reissued once; DEAD audit history is immutable; canonical repair is idempotent and does not touch financial lifecycle authority.';
END;
$verification$;

-- Rollback-contained first-use proof for the shared Daily/Weekly overlap guard.
-- Real table triggers remain enabled.  The proof exercises Candidate workflow
-- admission and Office authorisation without retaining any fixture data.


do $timesheet_cross_record_overlap_guard_verification$
declare
  v_now timestamptz:='2026-08-31 03:22:00+00';
  v_week date:='2026-08-30';
  v_candidate uuid:=gen_random_uuid();
  v_client_one uuid:=gen_random_uuid();
  v_client_two uuid:=gen_random_uuid();
  v_contract_one uuid:=gen_random_uuid();
  v_contract_two uuid:=gen_random_uuid();
  v_week_one uuid:=gen_random_uuid();
  v_week_two uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_timesheet_one uuid:=gen_random_uuid();
  v_timesheet_two uuid:=gen_random_uuid();
  v_timesheet_same_family uuid:=gen_random_uuid();
  v_timesheet_office uuid:=gen_random_uuid();
  v_daily_one uuid:=gen_random_uuid();
  v_daily_two uuid:=gen_random_uuid();
  v_workflow_one uuid:=gen_random_uuid();
  v_workflow_two uuid:=gen_random_uuid();
  v_workflow_same_family uuid:=gen_random_uuid();
  v_daily_workflow_one uuid:=gen_random_uuid();
  v_daily_workflow_two uuid:=gen_random_uuid();
  v_schedule_morning jsonb;
  v_schedule_overlap jsonb;
  v_schedule_touching jsonb;
  v_schedule_late jsonb;
  v_payload_morning jsonb;
  v_payload_overlap jsonb;
  v_payload_touching jsonb;
  v_failed boolean:=false;
  v_family text;
begin
  v_family:='OVERLAP-'||replace(v_candidate::text,'-','');
  v_schedule_morning:=jsonb_build_array(jsonb_build_object(
    'date','2026-08-24','start','09:00','end','17:00','break_minutes',30));
  v_schedule_overlap:=jsonb_build_array(jsonb_build_object(
    'date','2026-08-24','start','16:00','end','18:00','break_minutes',0));
  v_schedule_touching:=jsonb_build_array(jsonb_build_object(
    'date','2026-08-24','start','17:00','end','20:00','break_minutes',0));
  v_schedule_late:=jsonb_build_array(jsonb_build_object(
    'date','2026-08-24','start','20:00','end','22:00','break_minutes',0));
  v_payload_morning:=jsonb_build_object('hours_submission',jsonb_build_object(
    'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_morning)));
  v_payload_overlap:=jsonb_build_object('hours_submission',jsonb_build_object(
    'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_overlap)));
  v_payload_touching:=jsonb_build_object('hours_submission',jsonb_build_object(
    'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_touching)));

  insert into public.clients(id,name) values
    (v_client_one,'Overlap guard client one'),
    (v_client_two,'Overlap guard client two');
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday
  ) values
    (gen_random_uuid(),v_client_one,v_week-30,'ELECTRONIC',0),
    (gen_random_uuid(),v_client_two,v_week-30,'ELECTRONIC',0);
  insert into public.candidates(id,email,display_name,active,key_norm,opt_in_email)
  values(v_candidate,'overlap-'||replace(v_candidate::text,'-','')||'@example.test',
    'Overlap Guard Candidate',true,v_family,true);
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,week_ending_weekday_snapshot,
    default_submission_mode,pay_method_snapshot,role
  ) values
    (v_contract_one,v_candidate,v_client_one,v_week-30,v_week+30,0,'ELECTRONIC','PAYE','RMN'),
    (v_contract_two,v_candidate,v_client_two,v_week-30,v_week+30,0,'ELECTRONIC','PAYE','RMN');
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot,day_entries_json,totals_json
  ) values
    (v_week_one,v_contract_one,v_week,'SUBMITTED','ELECTRONIC',v_schedule_morning,
      jsonb_build_object('total_hours',7.5,'actual_schedule_json',v_schedule_morning)),
    (v_week_two,v_contract_two,v_week,'SUBMITTED','ELECTRONIC',v_schedule_touching,
      jsonb_build_object('total_hours',3,'actual_schedule_json',v_schedule_touching));
  insert into public.candidate_app_accounts(id,environment,email_normalized,status)
  values(v_account,'TEST','overlap-'||replace(v_candidate::text,'-','')||'@example.test','ACTIVE');

  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    contract_id,week_ending_date,line_type,submission_mode,
    sheet_scope,actual_schedule_json
  ) values
    (v_timesheet_one,v_family||'-ONE',v_family,'HOSPITAL-ONE','WARD-ONE','RMN',v_contract_one,v_week,'HOURS','MANUAL','WEEKLY',v_schedule_morning),
    (v_timesheet_two,v_family||'-TWO',v_family,'HOSPITAL-TWO','WARD-TWO','RMN',v_contract_two,v_week,'HOURS','MANUAL','WEEKLY',v_schedule_touching);
  update public.contract_weeks set timesheet_id=v_timesheet_one where id=v_week_one;
  update public.contract_weeks set timesheet_id=v_timesheet_two where id=v_week_two;

  -- First accepted Weekly submission establishes 09:00-17:00.
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    contract_id,contract_week_id,anchor_timesheet_id,target_timesheet_id,week_ending_date,
    idempotency_key,worker_submitted_at_utc,immutable_submission_json,immutable_submission_sha256
  ) values(
    v_workflow_one,'TEST',v_account,v_candidate,'CONTRACT_HOURS','WEEKLY','ELECTRONIC',
    'WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',2,v_contract_one,v_week_one,
    v_timesheet_one,v_timesheet_one,v_week,'overlap-workflow-one-'||v_workflow_one::text,
    v_now,v_payload_morning,private._candidate_sha256_jsonb_v1(v_payload_morning)
  );

  -- A separate Weekly Timesheet for another Client overlaps 16:00-18:00.
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    contract_id,contract_week_id,anchor_timesheet_id,target_timesheet_id,week_ending_date,
    idempotency_key
  ) values(
    v_workflow_two,'TEST',v_account,v_candidate,'CONTRACT_HOURS','WEEKLY','ELECTRONIC',
    'CREATED',1,v_contract_two,v_week_two,v_timesheet_two,v_timesheet_two,v_week,
    'overlap-workflow-two-'||v_workflow_two::text
  );
  begin
    update public.candidate_submission_workflows set
      state='WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',generation=2,
      worker_submitted_at_utc=v_now,immutable_submission_json=v_payload_overlap,
      immutable_submission_sha256=private._candidate_sha256_jsonb_v1(v_payload_overlap)
    where id=v_workflow_two;
    raise exception 'OVERLAPPING_WEEKLY_SUBMISSION_WAS_ACCEPTED';
  exception when sqlstate 'PT409' then
    if sqlerrm<>'TIMESHEET_WORK_INTERVAL_OVERLAP' then raise; end if;
    v_failed:=true;
  end;
  if not v_failed or (select state from public.candidate_submission_workflows where id=v_workflow_two)<>'CREATED' then
    raise exception 'OVERLAPPING_WEEKLY_ROLLBACK_NOT_PROVEN';
  end if;

  -- Boundary-touching 17:00 start is valid.
  update public.candidate_submission_workflows set
    state='WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',generation=2,
    worker_submitted_at_utc=v_now,immutable_submission_json=v_payload_touching,
    immutable_submission_sha256=private._candidate_sha256_jsonb_v1(v_payload_touching)
  where id=v_workflow_two;

  -- A replacement version in the same booking family is not a second logical
  -- Timesheet and therefore must not conflict with itself.
  update public.timesheets set is_current=false where timesheet_id=v_timesheet_one;
  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    contract_id,week_ending_date,line_type,submission_mode,
    sheet_scope,actual_schedule_json,version,is_current
  ) values(
    v_timesheet_same_family,v_family||'-ONE',v_family,'HOSPITAL-ONE','WARD-ONE','RMN',v_contract_one,v_week,'HOURS','MANUAL',
    'WEEKLY',v_schedule_morning,2,true
  );
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    contract_id,contract_week_id,anchor_timesheet_id,target_timesheet_id,week_ending_date,
    idempotency_key,worker_submitted_at_utc,immutable_submission_json,immutable_submission_sha256,
    replacement_of_workflow_id
  ) values(
    v_workflow_same_family,'TEST',v_account,v_candidate,'CONTRACT_HOURS','WEEKLY','ELECTRONIC',
    'WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',3,v_contract_one,v_week_one,
    v_timesheet_same_family,v_timesheet_same_family,v_week,
    'overlap-same-family-'||v_workflow_same_family::text,v_now,v_payload_morning,
    private._candidate_sha256_jsonb_v1(v_payload_morning),v_workflow_one
  );

  -- Office authorisation is independently guarded.  A 16:00-18:00 row is
  -- rejected; a 20:00-22:00 boundary-touching row is accepted.
  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    contract_id,week_ending_date,line_type,submission_mode,
    sheet_scope,actual_schedule_json
  ) values(v_timesheet_office,v_family||'-OFFICE',v_family,'HOSPITAL-TWO','WARD-TWO','RMN',v_contract_two,v_week,
    'HOURS','MANUAL','WEEKLY',v_schedule_overlap);
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,processing_status,actual_schedule_json
  ) values(v_timesheet_office,1,v_candidate,v_client_two,2,'UNPROCESSED',v_schedule_overlap);
  v_failed:=false;
  begin
    update public.timesheets set authorised_at_server=v_now where timesheet_id=v_timesheet_office;
    raise exception 'OVERLAPPING_OFFICE_AUTHORISATION_WAS_ACCEPTED';
  exception when sqlstate 'PT409' then
    if sqlerrm<>'TIMESHEET_WORK_INTERVAL_OVERLAP' then raise; end if;
    v_failed:=true;
  end;
  if not v_failed or (select authorised_at_server from public.timesheets where timesheet_id=v_timesheet_office) is not null then
    raise exception 'OVERLAPPING_OFFICE_AUTHORISATION_ROLLBACK_NOT_PROVEN';
  end if;
  update public.timesheets set actual_schedule_json=v_schedule_late where timesheet_id=v_timesheet_office;
  update public.timesheets_financials set actual_schedule_json=v_schedule_late where timesheet_id=v_timesheet_office;
  update public.timesheets set authorised_at_server=v_now where timesheet_id=v_timesheet_office;

  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    week_ending_date,line_type,submission_mode,sheet_scope,
    actual_schedule_json
  ) values(
    v_daily_one,v_family||'-DAILY-ONE',v_family,'HOSPITAL-DAILY','WARD-DAILY','RMN',v_week,'HOURS','MANUAL','DAILY',v_schedule_morning
  );
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    anchor_timesheet_id,target_timesheet_id,work_date,idempotency_key
  ) values(
    v_daily_workflow_one,'TEST',v_account,v_candidate,'DAILY','DAILY','PHONE',
    'CREATED',1,v_daily_one,v_daily_one,'2026-08-24',
    'overlap-daily-one-'||v_daily_workflow_one::text
  );
  update public.timesheets set candidate_workflow_id=v_daily_workflow_one,
    candidate_workflow_generation=1 where timesheet_id=v_daily_one;

  -- The same check spans record types: a Daily shift cannot overlap a Weekly
  -- submission for the same Candidate.
  v_failed:=false;
  begin
    update public.candidate_submission_workflows set
      state='WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',generation=2,
      worker_submitted_at_utc=v_now,
      immutable_submission_json=jsonb_build_object(
        'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_morning)),
      immutable_submission_sha256=private._candidate_sha256_jsonb_v1(jsonb_build_object(
        'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_morning)))
    where id=v_daily_workflow_one;
    raise exception 'OVERLAPPING_WEEKLY_DAILY_SUBMISSION_WAS_ACCEPTED';
  exception when sqlstate 'PT409' then
    if sqlerrm<>'TIMESHEET_WORK_INTERVAL_OVERLAP' then raise; end if;
    v_failed:=true;
  end;
  if not v_failed or (select state from public.candidate_submission_workflows where id=v_daily_workflow_one)<>'CREATED' then
    raise exception 'OVERLAPPING_WEEKLY_DAILY_ROLLBACK_NOT_PROVEN';
  end if;

  -- Retire the Weekly submissions.  Refused history must not block the same
  -- valid Daily submission, which now becomes the active 09:00-17:00 record.
  update public.candidate_submission_workflows set state='REFUSED',updated_at_utc=v_now
  where id in (v_workflow_one,v_workflow_two,v_workflow_same_family);
  update public.candidate_submission_workflows set
    state='WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',generation=2,
    worker_submitted_at_utc=v_now,
    immutable_submission_json=jsonb_build_object(
      'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_morning)),
    immutable_submission_sha256=private._candidate_sha256_jsonb_v1(jsonb_build_object(
      'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_morning)))
  where id=v_daily_workflow_one;
  update public.timesheets set candidate_workflow_generation=2 where timesheet_id=v_daily_one;

  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    week_ending_date,line_type,submission_mode,sheet_scope,
    actual_schedule_json
  ) values(
    v_daily_two,v_family||'-DAILY-TWO',v_family,'HOSPITAL-DAILY','WARD-DAILY','RMN',v_week,'HOURS','MANUAL','DAILY',v_schedule_overlap
  );
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    anchor_timesheet_id,target_timesheet_id,work_date,idempotency_key
  ) values(
    v_daily_workflow_two,'TEST',v_account,v_candidate,'DAILY','DAILY','PHONE','CREATED',1,
    v_daily_two,v_daily_two,'2026-08-24','overlap-daily-two-'||v_daily_workflow_two::text
  );
  update public.timesheets set candidate_workflow_id=v_daily_workflow_two,
    candidate_workflow_generation=1 where timesheet_id=v_daily_two;
  v_failed:=false;
  begin
    update public.candidate_submission_workflows set
      state='WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',generation=2,
      worker_submitted_at_utc=v_now,
      immutable_submission_json=jsonb_build_object(
        'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_overlap)),
      immutable_submission_sha256=private._candidate_sha256_jsonb_v1(jsonb_build_object(
        'timesheet_patch_json',jsonb_build_object('actual_schedule_json',v_schedule_overlap)))
    where id=v_daily_workflow_two;
    raise exception 'OVERLAPPING_DAILY_SUBMISSION_WAS_ACCEPTED';
  exception when sqlstate 'PT409' then
    if sqlerrm<>'TIMESHEET_WORK_INTERVAL_OVERLAP' then raise; end if;
    v_failed:=true;
  end;
  if not v_failed or (select state from public.candidate_submission_workflows where id=v_daily_workflow_two)<>'CREATED' then
    raise exception 'OVERLAPPING_DAILY_ROLLBACK_NOT_PROVEN';
  end if;

  -- Browser roles cannot invoke the private parser/assertion/trigger helpers.
  if exists(
    select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and p.proname in (
      '_timesheet_work_intervals_v1','_timesheet_cross_record_overlap_assert_v1',
      '_timesheet_submission_workflow_overlap_trg_v1','_timesheet_authorisation_overlap_trg_v1'
    ) and (
      pg_catalog.has_function_privilege('public',p.oid,'EXECUTE')
      or (pg_catalog.to_regrole('anon') is not null and pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE'))
      or (pg_catalog.to_regrole('authenticated') is not null and pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE'))
    )
  ) then raise exception 'TIMESHEET_OVERLAP_PRIVATE_HELPER_BROWSER_EXECUTABLE'; end if;

  if not exists(select 1 from pg_catalog.pg_trigger where tgname='trg_timesheet_submission_workflow_overlap_biu' and tgenabled='O')
     or not exists(select 1 from pg_catalog.pg_trigger where tgname='trg_timesheet_authorisation_overlap_biu' and tgenabled='O') then
    raise exception 'TIMESHEET_OVERLAP_TRIGGER_NOT_ENABLED';
  end if;
end;$timesheet_cross_record_overlap_guard_verification$;

-- Rollback-contained first-use proof for an Office-created empty expense-only
-- carrier.  The Candidate must add the first expense to the existing workflow;
-- the read path must not call it a saved claim or create a second workflow.



do $verification$
declare
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_week uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_workflow uuid:=gen_random_uuid();
  v_workflows jsonb;
  v_action jsonb;
  v_invocation jsonb;
  v_definition text;
begin
  select lower(pg_get_functiondef(to_regprocedure(
    'private._candidate_timesheet_primary_action_v1(text,jsonb,jsonb,uuid,uuid)'
  ))) into v_definition;
  if position('and not v_draft_has_content then ''add_expenses''' in v_definition)=0
     or position('v_workflow:=null' in replace(v_definition,' ',''))=0
     or v_definition~'pg_catalog\.(coalesce|nullif|least|greatest)\s*\(' then
    raise exception 'Empty expense-carrier primary-action authority is not installed safely';
  end if;

  select lower(pg_get_functiondef(to_regprocedure(
    'private._candidate_action_invocation_v1(jsonb)'
  ))) into v_definition;
  if position(
       'v_code=''add_expenses'' and nullif(p_action->>''workflow_id'','''') is not null'
       in v_definition
     )=0
     or position('''expense_claim_editor''' in v_definition)=0
     or v_definition~'pg_catalog\.(coalesce|nullif|least|greatest)\s*\(' then
    raise exception 'Existing-workflow expense editor invocation is not installed safely';
  end if;

  insert into public.clients(id,name)
  values(v_client,'Empty Expense Carrier Verification Client');
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday
  ) values(
    gen_random_uuid(),v_client,current_date-7,'ELECTRONIC',
    extract(dow from current_date)::integer
  );
  insert into public.candidates(id,email,active)
  values(v_candidate,'empty-expense-'||v_candidate::text||'@example.test',true);
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,
    pay_method_snapshot,week_ending_weekday_snapshot,default_submission_mode
  ) values(
    v_contract,v_candidate,v_client,current_date-7,current_date+7,
    'PAYE',extract(dow from current_date)::integer,'ELECTRONIC'
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id
  ) values(v_week,v_contract,current_date,1,'OPEN','MANUAL',null);
  insert into public.candidate_app_accounts(
    id,environment,email_normalized,status
  ) values(
    v_account,'TEST','empty-expense-'||v_candidate::text||'@example.test','SETUP_REQUIRED'
  );
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    contract_id,contract_week_id,week_ending_date,
    policy_snapshot_json,input_snapshot_json,idempotency_key
  ) values(
    v_workflow,'TEST',v_account,v_candidate,'CONTRACT_EXPENSE','WEEKLY','ELECTRONIC',
    'WORKER_DRAFT',1,v_contract,v_week,current_date,'{}','{}',
    'empty-expense-carrier-verification'
  );

  v_workflows:=jsonb_build_array(jsonb_build_object(
    'workflow_id',v_workflow,'workflow_kind','CONTRACT_EXPENSE',
    'state','WORKER_DRAFT','generation',1,'detail_action_owner',true,
    'updated_at_utc',now()
  ));
  v_action:=private._candidate_timesheet_primary_action_v1(
    'WORKER_DRAFT',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    null,v_week
  );
  if v_action->>'code'<>'ADD_EXPENSES'
     or v_action->>'label'<>'Add Expenses'
     or (v_action->>'workflow_id')::uuid is distinct from v_workflow
     or (v_action->>'workflow_generation')::integer<>1 then
    raise exception 'Empty expense carrier was not presented as Add Expenses: %',v_action;
  end if;
  v_invocation:=private._candidate_action_invocation_v1(v_action);
  if v_invocation#>>'{invocation,kind}'<>'CLIENT_DESTINATION'
     or v_invocation#>>'{invocation,destination}'<>'EXPENSE_CLAIM_EDITOR'
     or (v_invocation#>>'{invocation,context,workflow_id}')::uuid is distinct from v_workflow
     or v_invocation ? 'method' and v_invocation->>'method' is not null
     or v_invocation ? 'path' and v_invocation->>'path' is not null then
    raise exception 'Empty expense carrier did not reuse its existing editor workflow: %',v_invocation;
  end if;

  v_action:=private._candidate_timesheet_primary_action_v1(
    'WORKER_DRAFT',v_workflows,
    jsonb_build_object('can_edit_hours',true,'can_edit_expenses',true),
    null,v_week
  );
  if v_action->>'code'<>'ENTER_TIMESHEET'
     or v_action->>'label'<>'Enter Timesheet'
     or (v_action->>'contract_week_id')::uuid is distinct from v_week
     or v_action ? 'workflow_id' then
    raise exception 'Empty expense shell hid the FLEXIBLE hours journey: %',v_action;
  end if;

  insert into public.candidate_submission_components(
    workflow_id,workflow_generation,component_no,component_kind,expense_category,
    document_role,state,created_at_utc
  ) values(
    v_workflow,1,1,'EXPENSE_EVIDENCE','OTHER','SOURCE_EVIDENCE','PENDING',now()
  );
  v_action:=private._candidate_timesheet_primary_action_v1(
    'WORKER_DRAFT',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    null,v_week
  );
  if v_action->>'code'<>'CONTINUE_EXPENSE_CLAIM'
     or v_action->>'label'<>'Continue Expense Claim'
     or (v_action->>'workflow_id')::uuid is distinct from v_workflow then
    raise exception 'A genuine expense draft no longer continues normally: %',v_action;
  end if;

  if (select count(*) from public.candidate_submission_workflows where id=v_workflow)<>1
     or (select count(*) from public.contract_weeks where id=v_week)<>1 then
    raise exception 'Read-only action projection duplicated the expense claim';
  end if;
end;
$verification$;

do $verification$
declare
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_root uuid:=gen_random_uuid();
  v_carrier uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_session uuid:=gen_random_uuid();
  v_workflow uuid:=gen_random_uuid();
  v_hours_workflow uuid:=gen_random_uuid();
  v_result jsonb;
  v_contract_before jsonb;
  v_actor uuid;
  v_office_actor uuid;
  v_anchor_timesheet uuid:=gen_random_uuid();
  v_evidence uuid:=gen_random_uuid();
  v_approval uuid;
  v_signature uuid:=gen_random_uuid();
  v_policy jsonb;
  v_submission jsonb;
  v_expense_timesheet uuid;
begin
  insert into public.settings_defaults(id,candidate_manager_email_templates_sha256,candidate_home_announcement_sha256)
  values(1,decode(repeat('01',32),'hex'),decode(repeat('02',32),'hex')) on conflict(id) do nothing;
  update public.settings_defaults set candidate_app_feature_flags_json=
    coalesce(candidate_app_feature_flags_json,'{}'::jsonb)||
    '{"candidate_app_reads":true,"candidate_app_writes":true,"candidate_expense_atomic_placement":true,"candidate_record_role_capabilities":true}'::jsonb where id=1;
  if (select candidate_app_system_actor_user_id from public.settings_defaults where id=1) is null then
    insert into public.tms_users(email,role,is_active,password_hash,display_name,payment_authoriser,payment_golden_key)
    values('carrier-regression-'||v_workflow::text||'@example.test','user',false,
      '!no-login!','Carrier regression system',false,false) returning id into v_actor;
    update public.settings_defaults set candidate_app_system_actor_user_id=v_actor where id=1;
  end if;
  insert into public.clients(id,name) values(v_client,'Expense carrier regression');
  insert into public.client_settings(id,client_id,effective_from,default_submission_mode,week_ending_weekday)
  values(gen_random_uuid(),v_client,'1900-01-01','ELECTRONIC',extract(dow from current_date)::integer);
  insert into public.candidates(id,email,active)
  values(v_candidate,'carrier-'||v_candidate::text||'@example.test',true);
  insert into public.contracts(id,candidate_id,client_id,start_date,end_date,pay_method_snapshot,
    week_ending_weekday_snapshot,default_submission_mode)
  values(v_contract,v_candidate,v_client,current_date-7,current_date+7,'PAYE',
    extract(dow from current_date)::integer,'ELECTRONIC');
  insert into public.contract_weeks(id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,day_entries_json,planned_schedule_json,totals_json,is_adjustment)
  values(v_root,v_contract,current_date,0,'OPEN','ELECTRONIC','[]','[]','{}',false),
    (v_carrier,v_contract,current_date,1,'OPEN','MANUAL','[]','[]','{}',true);
  if private._candidate_provisional_expense_carrier_v1(v_carrier) then
    raise exception 'Unproven additional row classified as expense';
  end if;
  perform private._candidate_audit_v1('contract_week',v_carrier::text,'CANDIDATE_EXPENSE_CARRIER_CREATED',null,
    jsonb_build_object('contract_id',v_contract,'week_ending_date',current_date,'additional_seq',1));
  update public.client_settings set is_nhsp=true,
    send_manual_invoices_to_different_email=true,
    candidate_expense_invoice_email='expenses@example.test',
    manual_invoices_alt_email_address='expenses@example.test'
  where client_id=v_client;
  v_result:=private._candidate_record_capabilities_v1(null,v_carrier,'{}');
  if v_result->>'record_role' is distinct from 'FLEXIBLE'
     or v_result->>'import_authoritative' is distinct from 'false'
     or v_result->>'can_edit_hours' is distinct from 'false'
     or v_result->>'can_edit_expenses' is distinct from 'true' then
    raise exception 'Expense reservation capabilities incorrect: %',v_result;
  end if;
  v_result:=private._candidate_record_capabilities_v1(null,v_root,'{}');
  if v_result->>'record_role' is distinct from 'IMPORT_HOURS'
     or v_result->>'import_authoritative' is distinct from 'true' then
    raise exception 'Source root lost import authority: %',v_result;
  end if;
  if private._candidate_provisional_expense_carrier_v1(v_carrier) is distinct from true
     or private._candidate_provisional_expense_carrier_v1(v_root) is distinct from false then
    raise exception 'Provisional carrier/root classification failed';
  end if;
  update public.contract_weeks set totals_json='{"hours":{"day":1,"night":-1}}' where id=v_carrier;
  if private._candidate_provisional_expense_carrier_v1(v_carrier) then
    raise exception 'Offsetting hours bypassed carrier classification';
  end if;
  update public.contract_weeks set totals_json='{}' where id=v_carrier;
  insert into public.candidate_app_accounts(id,environment,email_normalized,status)
  values(v_account,'TEST','carrier-'||v_candidate::text||'@example.test','ACTIVE');
  insert into public.candidate_app_sessions(id,account_id,environment,selected_candidate_id,status,
    refresh_token_hash,expires_at_utc,absolute_expires_at_utc)
  values(v_session,v_account,'TEST',v_candidate,'ACTIVE',decode(repeat('d7',32),'hex'),
    now()+interval '1 day',now()+interval '2 days');
  insert into public.candidate_submission_workflows(id,environment,account_id,candidate_id,
    workflow_kind,scope,route,state,generation,contract_id,contract_week_id,week_ending_date,
    policy_snapshot_json,input_snapshot_json,idempotency_key)
  values(v_workflow,'TEST',v_account,v_candidate,'CONTRACT_EXPENSE','WEEKLY','EMAIL',
    'WORKER_DRAFT',1,v_contract,v_carrier,current_date,'{}','{}','carrier-regression-'||v_workflow::text);
  v_result:=public.expense_placement_resolve_v1(v_candidate,'TEST',null,v_root);
  if v_result->>'placement' is distinct from 'BLOCKED'
     or v_result->>'reason_code' is distinct from 'CANDIDATE_RECORD_VIEW_ONLY' then
    raise exception 'A week without worked evidence was admitted: %',v_result;
  end if;
  insert into public.candidate_submission_workflows(id,environment,account_id,candidate_id,
    workflow_kind,scope,route,state,generation,contract_id,contract_week_id,week_ending_date,
    policy_snapshot_json,input_snapshot_json,idempotency_key)
  values(v_hours_workflow,'TEST',v_account,v_candidate,'CONTRACT_HOURS','WEEKLY','ELECTRONIC',
    'WORKER_SUBMITTED',1,v_contract,v_root,current_date,'{}',
    '{"hours_submission":{"timesheet_patch_json":{"actual_schedule_json":[{"start_time":"09:00","end_time":"17:00"}]}}}',
    'carrier-hours-regression-'||v_hours_workflow::text);
  -- Match the actual pre-final source state: a manual-storage hours root holds
  -- candidate clock evidence but has no final source financial snapshot yet.
  insert into public.timesheets(timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,contract_id,week_ending_date,sheet_scope,line_type,submission_mode,actual_schedule_json)
  values(v_anchor_timesheet,'SOURCE_EXPENSE_'||v_anchor_timesheet::text,'SOURCE_EXPENSE_CANDIDATE',
    'REGRESSION HOSPITAL','REGRESSION WARD','NURSE',v_contract,current_date,'WEEKLY','HOURS','MANUAL',
    '[{"start_time":"09:00","end_time":"17:00"}]');
  update public.contract_weeks set timesheet_id=v_anchor_timesheet where id=v_root;
  update public.candidate_submission_workflows set anchor_timesheet_id=v_anchor_timesheet where id=v_workflow;
  v_result:=public.expense_placement_resolve_v1(v_candidate,'TEST',null,v_root);
  if v_result->>'placement' is distinct from 'REUSE_CARRIER'
     or v_result->>'target_contract_week_id' is distinct from v_carrier::text then
    raise exception 'Submitted source-week evidence did not reuse its expense reservation: %',v_result;
  end if;
  v_result:=public.candidate_app_timesheet_page_v1(v_session,'TEST','CURRENT',null,100,now());
  if not exists(select 1 from jsonb_array_elements(v_result->'items') card
      where card->>'contract_week_id'=v_root::text)
     or exists(select 1 from jsonb_array_elements(v_result->'items') card
      where card->>'contract_week_id'=v_carrier::text) then
    raise exception 'MyTMS did not retain root and hide its expense reservation: %',v_result;
  end if;
  v_result:=private._candidate_empty_provisional_expense_cleanup_v1('TEST',v_carrier);
  if v_result->>'deleted' is distinct from 'false' then
    raise exception 'Active draft was deleted';
  end if;
  insert into public.tms_users(email,role,is_active,password_hash,display_name,payment_authoriser,payment_golden_key)
  values('carrier-office-'||v_workflow::text||'@example.test','user',true,
    '!no-login!','Carrier regression Office',false,false) returning id into v_office_actor;
  v_result:=public.candidate_office_expense_reservations_v1('TEST',v_office_actor,array[v_root,v_carrier]);
  if jsonb_array_length(v_result->'rows') is distinct from 1
     or v_result#>>'{rows,0,contract_week_id}' is distinct from v_carrier::text
     or v_result#>>'{rows,0,state}' is distinct from 'WORKER_DRAFT' then
    raise exception 'Office reservation projection lost exact claim/root scope: %',v_result;
  end if;
  begin
    perform public.candidate_office_expense_reservations_v1('TEST',gen_random_uuid(),array[v_carrier]);
    raise exception 'Unknown Office actor accepted';
  exception when sqlstate '28000' then null;
  end;
  if has_function_privilege('anon','public.candidate_office_expense_reservations_v1(text,uuid,uuid[])','EXECUTE')
     or has_function_privilege('authenticated','public.candidate_office_expense_reservations_v1(text,uuid,uuid[])','EXECUTE')
     or not has_function_privilege('service_role','public.candidate_office_expense_reservations_v1(text,uuid,uuid[])','EXECUTE') then
    raise exception 'Office reservation RPC role boundary incorrect';
  end if;
  -- Exercise the real finaliser's source-work gate, while deliberately missing
  -- signed documents: eligibility must not bypass the next approval/evidence gate.
  begin
    update public.candidate_submission_workflows set anchor_timesheet_id=v_anchor_timesheet,
      state='READY_TO_FINALISE',review_manifest_sha256=decode(repeat('a1',32),'hex') where id=v_workflow;
    insert into public.candidate_submission_components(id,workflow_id,workflow_generation,component_no,
      component_kind,expense_category,document_role,state,storage_key,media_type,byte_size,
