    v_contract,v_candidate,v_client,v_as_of-30,v_as_of+30,0,'ELECTRONIC','PAYE','RMN'
  );

  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot
  ) values(v_week,v_contract,v_as_of,'OPEN','ELECTRONIC');

  v_pre_route:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_as_of,
    jsonb_build_object('can_edit_hours',true,'import_authoritative',false)
  );
  if v_pre_route#>>'{applicable}' is distinct from 'true'
     or v_pre_route#>>'{mode}' is distinct from 'DURATION_MINUTES'
     or v_pre_route#>>'{source}' is distinct from 'CLIENT_SETTINGS'
     or v_pre_route#>>'{reason}' is distinct from 'CANDIDATE_EDITABLE_ELECTRONIC'
     or v_pre_route#>>'{context_token}' !~ '^[a-f0-9]{64}$' then
    raise exception 'CANDIDATE_PRE_ROUTE_BREAK_ENTRY_NOT_EXPOSED:%',v_pre_route;
  end if;

  -- candidate_app_timesheet_detail_v1 currently projects the editable,
  -- not-yet-selected Weekly route as MANUAL_NON_QR. This exact shape must be
  -- covered because it is what the physical app receives.
  v_projected_pre_route:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_as_of,
    jsonb_build_object(
      'can_edit_hours',true,
      'import_authoritative',false,
      'route_family','MANUAL_NON_QR'
    )
  );
  if v_projected_pre_route#>>'{applicable}' is distinct from 'true'
     or v_projected_pre_route#>>'{mode}' is distinct from 'DURATION_MINUTES'
     or v_projected_pre_route#>>'{source}' is distinct from 'CLIENT_SETTINGS'
     or v_projected_pre_route#>>'{reason}' is distinct from 'CANDIDATE_EDITABLE_ELECTRONIC'
     or v_projected_pre_route#>>'{context_token}' is distinct from v_pre_route#>>'{context_token}' then
    raise exception 'CANDIDATE_PROJECTED_PRE_ROUTE_BREAK_ENTRY_NOT_EXPOSED:%',
      v_projected_pre_route;
  end if;

  foreach v_route in array array['ELECTRONIC','PAPER','QR']
  loop
    v_selected:=private._candidate_break_entry_context_core_v1(
      null,v_week,v_as_of,
      jsonb_build_object(
        'can_edit_hours',true,
        'import_authoritative',false,
        'route_family',v_route
      )
    );
    if v_selected#>>'{applicable}' is distinct from 'true'
       or v_selected#>>'{mode}' is distinct from 'DURATION_MINUTES'
       or v_selected#>>'{context_token}' is distinct from v_pre_route#>>'{context_token}' then
      raise exception 'CANDIDATE_SELECTED_ROUTE_BREAK_ENTRY_DRIFT:%:%',v_route,v_selected;
    end if;
  end loop;

  update public.client_settings
  set is_nhsp=true
  where client_id=v_client;
  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_as_of,
    jsonb_build_object(
      'can_edit_hours',true,
      'import_authoritative',false,
      'route_family','ELECTRONIC'
    )
  );
  if v_result#>>'{applicable}' is distinct from 'false'
     or v_result#>'{mode}' is distinct from 'null'::jsonb
     or v_result#>>'{source}' is distinct from 'NOT_APPLICABLE'
     or v_result#>>'{reason}' is distinct from 'IMPORT_AUTHORITATIVE' then
    raise exception 'CANDIDATE_DEDICATED_NHSP_WEEKLY_BREAK_ENTRY_EXPOSED:%',v_result;
  end if;

  update public.client_settings
  set is_nhsp=false
  where client_id=v_client;

  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_as_of,
    jsonb_build_object(
      'can_edit_hours',true,
      'import_authoritative',true,
      'route_family','ELECTRONIC'
    )
  );
  if v_result#>>'{applicable}' is distinct from 'false'
     or v_result#>>'{reason}' is distinct from 'IMPORT_AUTHORITATIVE' then
    raise exception 'CANDIDATE_IMPORT_BREAK_ENTRY_BROADENED:%',v_result;
  end if;

  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_as_of,
    jsonb_build_object(
      'can_edit_hours',true,
      'import_authoritative',false,
      'route_family','PHONE'
    )
  );
  if v_result#>>'{applicable}' is distinct from 'false'
     or v_result#>>'{reason}' is distinct from 'NON_ELECTRONIC_ROUTE' then
    raise exception 'CANDIDATE_UNRELATED_ROUTE_BREAK_ENTRY_BROADENED:%',v_result;
  end if;

  update public.client_settings
  set autoprocess_hr=true,requires_hr=false,no_timesheet_required=true
  where client_id=v_client;
  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_as_of,
    jsonb_build_object(
      'can_edit_hours',true,
      'import_authoritative',false,
      'route_family','ELECTRONIC'
    )
  );
  if v_result#>>'{applicable}' is distinct from 'false'
     or v_result#>>'{reason}' is distinct from 'IMPORT_AUTHORITATIVE' then
    raise exception 'CANDIDATE_AUTHORITATIVE_ROSTER_BREAK_ENTRY_BROADENED:%',v_result;
  end if;
end
$candidate_weekly_preroute_break_entry_verification$;



select 'PASS'::text as candidate_weekly_preroute_break_entry_verification;

-- Portable, rollback-contained first-use proof. Candidate-reported breaks are
-- evidence on source-authoritative weeks; they do not alter source authority.


do $candidate_source_break_verification$
declare
  v_date date := '2026-09-27';
  v_candidate uuid := gen_random_uuid();
  v_client uuid := gen_random_uuid();
  v_contract uuid := gen_random_uuid();
  v_week uuid := gen_random_uuid();
  v_result jsonb;
  v_capabilities jsonb := jsonb_build_object(
    'candidate_source_self_entry_allowed',true,
    'import_authoritative',true,
    'route_family','IMPORT_AUTHORITATIVE',
    'protected',false,
    'candidate_mutation_locked',false,
    'can_edit_hours',false
  );
begin
  insert into public.clients(id,name)
  values(v_client,'Candidate source break verification Client');

  insert into public.candidates(id,email,display_name,active,key_norm)
  values(v_candidate,
    'source-break-'||replace(v_candidate::text,'-','')||'@example.test',
    'Candidate Source Break Verification',true,
    'SOURCE-BREAK-'||replace(v_candidate::text,'-',''));

  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday,
    is_nhsp,timesheet_break_entry_mode
  ) values(gen_random_uuid(),v_client,v_date-30,'ELECTRONIC',0,
    true,'START_END_TIMES');

  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,week_ending_weekday_snapshot,
    default_submission_mode,pay_method_snapshot,role
  ) values(v_contract,v_candidate,v_client,v_date-30,v_date+30,0,
    'ELECTRONIC','PAYE','RMN');

  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot
  ) values(v_week,v_contract,v_date,'OPEN','ELECTRONIC');

  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_date,v_capabilities);
  if v_result#>>'{applicable}' is distinct from 'true'
     or v_result#>>'{mode}' is distinct from 'START_END_TIMES'
     or v_result#>>'{source}' is distinct from 'CLIENT_SETTINGS'
     or v_result#>>'{reason}' is distinct from 'CANDIDATE_SOURCE_SELF_ENTRY'
     or v_result#>>'{context_token}' !~ '^[a-f0-9]{64}$' then
    raise exception 'SOURCE_BREAK_SELF_ENTRY_NOT_EXPOSED:%',v_result;
  end if;

  update public.client_settings set timesheet_break_entry_mode='DURATION_MINUTES'
  where client_id=v_client;
  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_date,v_capabilities);
  if v_result#>>'{applicable}' is distinct from 'true'
     or v_result#>>'{mode}' is distinct from 'DURATION_MINUTES'
     or v_result#>>'{source}' is distinct from 'CLIENT_SETTINGS' then
    raise exception 'SOURCE_BREAK_DURATION_MODE_LOST:%',v_result;
  end if;

  update public.contracts
  set overrideclientsettings=true,timesheet_break_entry_mode='START_END_TIMES'
  where id=v_contract;
  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_date,v_capabilities);
  if v_result#>>'{applicable}' is distinct from 'true'
     or v_result#>>'{mode}' is distinct from 'START_END_TIMES'
     or v_result#>>'{source}' is distinct from 'CONTRACT_OVERRIDE' then
    raise exception 'SOURCE_BREAK_CONTRACT_OVERRIDE_LOST:%',v_result;
  end if;

  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_date,v_capabilities||'{"candidate_source_self_entry_allowed":false}'::jsonb);
  if v_result#>>'{applicable}' is distinct from 'false'
     or v_result#>'{mode}' is distinct from 'null'::jsonb then
    raise exception 'SOURCE_BREAK_UNADMITTED_EXPOSED:%',v_result;
  end if;

  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_date,v_capabilities||'{"protected":true}'::jsonb);
  if v_result#>>'{applicable}' is distinct from 'false' then
    raise exception 'SOURCE_BREAK_PROTECTED_EXPOSED:%',v_result;
  end if;

  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_date,v_capabilities||'{"candidate_mutation_locked":true}'::jsonb);
  if v_result#>>'{applicable}' is distinct from 'false' then
    raise exception 'SOURCE_BREAK_LOCKED_EXPOSED:%',v_result;
  end if;

  v_result:=private._candidate_break_entry_context_core_v1(
    null,v_week,v_date,v_capabilities||'{"route_family":"ELECTRONIC"}'::jsonb);
  if v_result#>>'{applicable}' is distinct from 'false' then
    raise exception 'SOURCE_BREAK_OTHER_ROUTE_EXPOSED:%',v_result;
  end if;
end
$candidate_source_break_verification$;



select 'PASS'::text as candidate_source_self_entry_break_context_verification;

do $verify$
declare
  v_config text[];
begin
  select p.proconfig into strict v_config
  from pg_catalog.pg_proc p
  where p.oid='public.candidate_submission_finalize_atomic_v1(uuid,text,uuid,integer,text,text,timestamp with time zone,jsonb)'::regprocedure;

  if not ('lock_timeout=5s'=any(coalesce(v_config,array[]::text[]))) then
    raise exception 'CANDIDATE_FINALISATION_LOCK_TIMEOUT_NOT_INSTALLED';
  end if;
  if not ('statement_timeout=120s'=any(coalesce(v_config,array[]::text[]))) then
    raise exception 'CANDIDATE_FINALISATION_STATEMENT_TIMEOUT_NOT_INSTALLED';
  end if;
end;
$verify$;

-- A reusable empty expense carrier can still be typed EXPENSES. A pure-mileage
-- final claim must atomically retype it to MILEAGE. All fixture work rolls back.


update public.settings_defaults
set candidate_app_feature_flags_json=coalesce(candidate_app_feature_flags_json,'{}'::jsonb)
  ||jsonb_build_object(
    'candidate_app_writes',true,
    'candidate_record_role_capabilities',true,
    'candidate_expense_atomic_placement',true
  ),
  candidate_app_environment='TEST';

do $verification$
declare
  v_actor uuid:=gen_random_uuid();
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_week uuid:=gen_random_uuid();
  v_new_carrier_week uuid:=gen_random_uuid();
  v_import_week uuid:=gen_random_uuid();
  v_timesheet uuid:=gen_random_uuid();
  v_import_timesheet uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_workflow uuid:=gen_random_uuid();
  v_new_carrier_workflow uuid:=gen_random_uuid();
  v_component uuid:=gen_random_uuid();
  v_new_carrier_component uuid:=gen_random_uuid();
  v_manager_component uuid:=gen_random_uuid();
  v_new_manager_component uuid:=gen_random_uuid();
  v_approval_request uuid:=gen_random_uuid();
  v_new_approval_request uuid:=gen_random_uuid();
  v_claim jsonb;
  v_response jsonb;
  v_signature text;
  v_line_type text;
  v_new_target uuid;
begin
  -- The focused Candidate runtime fixture intentionally carries only the
  -- shared tms_users columns, while a complete database also requires the
  -- non-login password sentinel and role. Keep one rollback verifier valid
  -- against both shapes without weakening either schema.
  if exists(
    select 1 from information_schema.columns
    where table_schema='public' and table_name='tms_users' and column_name='password_hash'
  ) then
    execute 'insert into public.tms_users(id,email,password_hash,role,is_active)
      values($1,$2,$3,$4,$5)'
    using v_actor,
      'mileage-line-type-actor-'||replace(v_actor::text,'-','')||'@example.test',
      'UNUSABLE_VERIFICATION_ONLY','admin',true;
  else
    execute 'insert into public.tms_users(id,email,is_active) values($1,$2,$3)'
    using v_actor,
      'mileage-line-type-actor-'||replace(v_actor::text,'-','')||'@example.test',true;
  end if;
  update public.settings_defaults set candidate_app_system_actor_user_id=v_actor where id=1;

  insert into public.clients(id,name)
  values(v_client,'Mileage line type verification client');
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday,
    candidate_expenses_require_separate_timesheet,candidate_expense_invoice_email
  ) values(
    gen_random_uuid(),v_client,current_date-30,'ELECTRONIC',
    extract(dow from current_date)::integer,true,'expenses@example.test'
  );
  insert into public.candidates(id,email,active)
  values(v_candidate,'mileage-line-type-'||replace(v_candidate::text,'-','')||'@example.test',true);
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,
    week_ending_weekday_snapshot,default_submission_mode,pay_method_snapshot
  ) values(
    v_contract,v_candidate,v_client,current_date-7,current_date+7,
    extract(dow from current_date)::integer,'ELECTRONIC','PAYE'
  );
  insert into public.timesheets(
    timesheet_id,booking_id,contract_id,week_ending_date,
    occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    line_type,submission_mode,sheet_scope
  ) values(
    v_timesheet,'MILEAGE-LINE-TYPE-'||replace(v_timesheet::text,'-',''),
    v_contract,current_date,'candidate','test hospital','test ward','test role',
    'EXPENSES','MANUAL','WEEKLY'
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id
  ) values(v_week,v_contract,current_date,1,'OPEN','MANUAL',v_timesheet);
  insert into public.candidate_app_accounts(
    id,environment,email_normalized,status
  ) values(
    v_account,'TEST','mileage-line-type-'||replace(v_candidate::text,'-','')||'@example.test','SETUP_REQUIRED'
  );

  v_claim:=jsonb_build_object(
    'contract_week_id',v_week,
    'canonical_tsfin_snapshot',jsonb_build_object(
      'candidate_id',v_candidate,'client_id',v_client,
      'total_hours',0,'mileage_units',25,
      'mileage_pay_ex_vat',0,'mileage_charge_ex_vat',0,
      'expenses_pay_ex_vat',0,'expenses_charge_ex_vat',0,
      'travel_pay_ex_vat',0,'travel_charge_ex_vat',0,
      'accommodation_pay_ex_vat',0,'accommodation_charge_ex_vat',0,
      'other_pay_ex_vat',0,'other_charge_ex_vat',0
    ),
    'timesheet_patch_json',jsonb_build_object('line_type','EXPENSES'),
    'contract_week_patch_json','{}'::jsonb,
    'evidence_display_name','Mileage Claim Form'
  );

  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    contract_id,contract_week_id,anchor_timesheet_id,target_timesheet_id,week_ending_date,
    policy_snapshot_json,input_snapshot_json,idempotency_key,manager_approved_at_utc,
    immutable_submission_json,immutable_submission_sha256
  ) values(
    v_workflow,'TEST',v_account,v_candidate,'CONTRACT_EXPENSE','WEEKLY','PHONE',
    'READY_TO_FINALISE',1,v_contract,v_week,v_timesheet,v_timesheet,current_date,
    '{}'::jsonb,'{}'::jsonb,'mileage-line-type-workflow-'||v_workflow::text,now(),
    v_claim,private._candidate_sha256_jsonb_v1(v_claim)
  );
  insert into public.candidate_submission_components(
    id,workflow_id,workflow_generation,component_no,review_ordinal,timesheet_id,component_kind,
    expense_category,document_role,required,state,storage_key,media_type,byte_size,
    source_content_sha256,immutable_at_utc,
    review_render_state,review_storage_key,review_content_sha256,review_media_type,
    review_byte_size,review_page_count,review_render_input_sha256,
    review_renderer_contract_version,review_renderer_receipt_json,review_generated_at_utc,
    final_signed_render_state,final_signed_storage_key,final_signed_content_sha256,
    final_signed_media_type,final_signed_byte_size,final_signed_page_count,
    final_signed_render_input_sha256,final_signed_renderer_contract_version,
    final_signed_renderer_receipt_json,final_signed_generated_at_utc
  ) values(
    v_component,v_workflow,1,1,1,v_timesheet,'MILEAGE_FORM','MILEAGE','MILEAGE_CLAIM_FORM',
    true,'IMMUTABLE','expense/mileage-source.jpg','image/jpeg',100,
    decode(repeat('cc',32),'hex'),now(),
    'READY','expense/mileage-review.pdf',decode(repeat('ab',32),'hex'),'application/pdf',
    200,1,decode(repeat('ef',32),'hex'),'MILEAGE_REVIEW_TEST_V1','{}'::jsonb,now(),
    'READY','expense/mileage-final.pdf',decode(repeat('dd',32),'hex'),'application/pdf',
    220,1,decode(repeat('ef',32),'hex'),'MILEAGE_FINAL_TEST_V1','{}'::jsonb,now()
  );
  insert into public.candidate_approval_requests(
    id,workflow_id,workflow_generation,request_generation,method,state,
    review_manifest_sha256,required_component_ids,required_component_manifest_json,
    manager_review_timesheet_sha256,approved_at_utc
  ) values(
    v_approval_request,v_workflow,1,1,'PHONE','APPROVED',decode(repeat('ab',32),'hex'),
    array[v_component],jsonb_build_array(jsonb_build_object('component_id',v_component)),
    decode(repeat('ab',32),'hex'),now()
  );
  insert into public.candidate_submission_components(
    id,workflow_id,workflow_generation,component_no,component_kind,document_role,state,
    approval_request_id,storage_key,media_type,byte_size,source_content_sha256,immutable_at_utc,
    required,review_render_state,final_signed_render_state
  ) values(
    v_manager_component,v_workflow,1,2,'MANAGER_SIGNATURE','MANAGER_SIGNATURE','IMMUTABLE',
    v_approval_request,'expense/manager-signature.png','image/png',100,
    decode(repeat('bc',32),'hex'),now(),false,'NOT_REQUIRED','NOT_REQUIRED'
  );
  update public.candidate_submission_workflows set
    manager_name='Mileage Test Manager',manager_position='Service Manager',
    manager_signature_component_id=v_manager_component,
    manager_signature_sha256=decode(repeat('bc',32),'hex')
  where id=v_workflow;

  perform set_config('cloudtms.candidate_finalize_workflow',v_workflow::text||':1',true);
  perform set_config('cloudtms.candidate_electronic_finalise',v_workflow::text||':1',true);
  v_signature:=public.timesheet_lifecycle_guard_signature_v1(v_timesheet,v_week,false)->>'row_signature';
  v_response:=public.timesheet_expense_apply_atomic_v1(
    v_candidate,'TEST',v_timesheet,v_workflow,1,v_signature,
    v_claim,array[v_component],'mileage-line-type-apply-'||v_workflow::text,now()
  );
  select line_type::text into v_line_type
  from public.timesheets where timesheet_id=v_timesheet and is_current=true;
  if not coalesce((v_response->>'ok')::boolean,false) or v_line_type<>'MILEAGE' then
    raise exception 'pure mileage carrier line type verification failed';
  end if;

  -- Close the first fixture workflow before proving a later claim for the same
  -- Candidate, Contract and week. Production permits one active claim at a
  -- time; the later carrier is valid only after the earlier claim is terminal.
  update public.candidate_submission_workflows
  set state='FINALISED',finalised_at_utc=now(),updated_at_utc=now()
  where id=v_workflow;

  -- The second carrier deliberately inherits an NHSP/import-authoritative
  -- Client. The separate zero-hour Mileage row must still materialise, while
  -- the source imported-hours row remains protected by the exact workflow
  -- and line-type boundary in the final-state guard.
  update public.client_settings
  set is_nhsp=true,
      candidate_expense_invoice_email='expenses@example.test'
  where client_id=v_client;

  -- The real Candidate route begins with an authoritative worked Timesheet and
  -- a reserved additional Contract week that has no Timesheet yet. Exercise
  -- that first-use materialisation so an invalid Contract-week status cannot
  -- be passed into the Timesheet enum, and ensure an inherited import route
  -- cannot misclassify the explicit zero-hour Mileage carrier as mixed data.
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,submission_mode_snapshot
  ) values(v_new_carrier_week,v_contract,current_date,2,'OPEN','MANUAL');

  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
    contract_id,contract_week_id,anchor_timesheet_id,target_timesheet_id,week_ending_date,
    policy_snapshot_json,input_snapshot_json,idempotency_key,manager_approved_at_utc,
    immutable_submission_json,immutable_submission_sha256
  ) values(
    v_new_carrier_workflow,'TEST',v_account,v_candidate,'CONTRACT_EXPENSE','WEEKLY','PHONE',
    'READY_TO_FINALISE',1,v_contract,v_new_carrier_week,v_timesheet,null,current_date,
    '{}'::jsonb,'{}'::jsonb,'mileage-new-carrier-workflow-'||v_new_carrier_workflow::text,now(),
    v_claim,private._candidate_sha256_jsonb_v1(v_claim)
  );
  insert into public.candidate_submission_components(
    id,workflow_id,workflow_generation,component_no,review_ordinal,timesheet_id,component_kind,
    expense_category,document_role,required,state,storage_key,media_type,byte_size,
    source_content_sha256,immutable_at_utc,
    review_render_state,review_storage_key,review_content_sha256,review_media_type,
    review_byte_size,review_page_count,review_render_input_sha256,
    review_renderer_contract_version,review_renderer_receipt_json,review_generated_at_utc,
    final_signed_render_state,final_signed_storage_key,final_signed_content_sha256,
    final_signed_media_type,final_signed_byte_size,final_signed_page_count,
    final_signed_render_input_sha256,final_signed_renderer_contract_version,
    final_signed_renderer_receipt_json,final_signed_generated_at_utc
  ) values(
    v_new_carrier_component,v_new_carrier_workflow,1,1,1,v_timesheet,
    'MILEAGE_FORM','MILEAGE','MILEAGE_CLAIM_FORM',true,'IMMUTABLE',
    'expense/new-mileage-source.jpg','image/jpeg',100,decode(repeat('ac',32),'hex'),now(),
    'READY','expense/new-mileage-review.pdf',decode(repeat('ad',32),'hex'),'application/pdf',
    200,1,decode(repeat('ae',32),'hex'),'MILEAGE_REVIEW_TEST_V1','{}'::jsonb,now(),
    'READY','expense/new-mileage-final.pdf',decode(repeat('af',32),'hex'),'application/pdf',
    220,1,decode(repeat('ae',32),'hex'),'MILEAGE_FINAL_TEST_V1','{}'::jsonb,now()
  );
  insert into public.candidate_approval_requests(
    id,workflow_id,workflow_generation,request_generation,method,state,
    review_manifest_sha256,required_component_ids,required_component_manifest_json,
    manager_review_timesheet_sha256,approved_at_utc
  ) values(
    v_new_approval_request,v_new_carrier_workflow,1,1,'PHONE','APPROVED',decode(repeat('ad',32),'hex'),
    array[v_new_carrier_component],jsonb_build_array(jsonb_build_object('component_id',v_new_carrier_component)),
    decode(repeat('ad',32),'hex'),now()
  );
  insert into public.candidate_submission_components(
    id,workflow_id,workflow_generation,component_no,component_kind,document_role,state,
    approval_request_id,storage_key,media_type,byte_size,source_content_sha256,immutable_at_utc,
    required,review_render_state,final_signed_render_state
  ) values(
    v_new_manager_component,v_new_carrier_workflow,1,2,'MANAGER_SIGNATURE','MANAGER_SIGNATURE','IMMUTABLE',
    v_new_approval_request,'expense/new-manager-signature.png','image/png',100,
    decode(repeat('bd',32),'hex'),now(),false,'NOT_REQUIRED','NOT_REQUIRED'
  );
  update public.candidate_submission_workflows set
    manager_name='Import Mileage Manager',manager_position='Service Manager',
    manager_signature_component_id=v_new_manager_component,
    manager_signature_sha256=decode(repeat('bd',32),'hex')
  where id=v_new_carrier_workflow;

  perform set_config('cloudtms.candidate_finalize_workflow',v_new_carrier_workflow::text||':1',true);
  perform set_config('cloudtms.candidate_electronic_finalise',v_new_carrier_workflow::text||':1',true);
  if coalesce((private._candidate_import_authoritative_v1(
       v_client,v_contract,null,v_claim->'canonical_tsfin_snapshot',current_date
     )->>'is_import_authoritative')::boolean,false)=false then
    raise exception 'Mileage carrier fixture is not import-authoritative';
  end if;
  insert into public.timesheets(
    timesheet_id,booking_id,contract_id,week_ending_date,
    occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    line_type,submission_mode,sheet_scope
  ) values(
    v_import_timesheet,'MILEAGE-IMPORT-HOURS-'||replace(v_import_timesheet::text,'-',''),
    v_contract,current_date,'candidate','test hospital','test ward','test role',
    'HOURS','MANUAL','WEEKLY'
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id
  ) values(v_import_week,v_contract,current_date,3,'AUTHORISED','MANUAL',v_import_timesheet);
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,basis,total_hours,processing_status
  ) values(v_import_timesheet,1,v_candidate,v_client,'NHSP',8,'READY_FOR_INVOICE');
  begin
    v_response:=private._candidate_weekly_final_state_guard_v1(
      v_import_week,v_import_timesheet,null,jsonb_build_object('line_type','MILEAGE'),
      v_claim->'canonical_tsfin_snapshot'
    );
    raise exception 'Import hours accepted expense economics: %',v_response;
  exception when sqlstate '22023' then
    if sqlerrm<>'HOURS_AND_EXPENSES_REQUIRE_SEPARATE_TIMESHEETS' then
      raise;
    end if;
  end;
  v_signature:=public.timesheet_lifecycle_guard_signature_v1(null,v_new_carrier_week,false)->>'row_signature';
  v_response:=public.timesheet_expense_apply_atomic_v1(
    v_candidate,'TEST',null,v_new_carrier_workflow,1,v_signature,
    v_claim,array[v_new_carrier_component],
    'mileage-new-carrier-apply-'||v_new_carrier_workflow::text,now()
  );
  v_new_target:=nullif(v_response->>'target_timesheet_id','')::uuid;
  if not coalesce((v_response->>'ok')::boolean,false)
     or v_new_target is null or v_new_target=v_timesheet
     or v_response#>>'{capabilities,record_role}'<>'EXPENSE_ONLY'
     or not exists(
       select 1 from public.timesheets target
       where target.timesheet_id=v_new_target
         and target.line_type='MILEAGE' and target.status='RECEIVED'
         and target.submission_mode='MANUAL'
         and target.auth_name='Import Mileage Manager'
         and target.auth_job_title='Service Manager'
         and target.r2_auth_key='expense/new-manager-signature.png'
         and target.img_sha256_auth=encode(decode(repeat('bd',32),'hex'),'hex')
         and target.candidate_workflow_id=v_new_carrier_workflow
         and target.candidate_workflow_generation=1
         and target.candidate_manager_approved_at_utc is not null
         and target.is_current=true
     )
     or (select timesheet_id from public.contract_weeks where id=v_new_carrier_week)
       is distinct from v_new_target then
    raise exception 'new Mileage carrier materialisation verification failed: %',v_response;
  end if;
end;
$verification$;

do $verify$
declare
  v_definition text;
begin
  select pg_catalog.pg_get_functiondef(
    'public.candidate_submission_finalize_single_flight_v1(uuid,text,uuid,integer,text,text,timestamp with time zone,jsonb)'::regprocedure
  ) into strict v_definition;

  if v_definition not like '%pg_try_advisory_xact_lock%' then
    raise exception 'CANDIDATE_FINALISATION_SINGLE_FLIGHT_LOCK_MISSING';
  end if;
  if v_definition not like '%CANDIDATE_FINALISATION_GLOBAL%'
     or v_definition not like '%FINALISATION_CAPACITY_BUSY%' then
    raise exception 'CANDIDATE_FINALISATION_GLOBAL_CAPACITY_GATE_MISSING';
  end if;
  if v_definition not like '%candidate_submission_finalize_atomic_v1%' then
    raise exception 'CANDIDATE_FINALISATION_ATOMIC_DELEGATE_MISSING';
  end if;
  if v_definition not like '%single_flight_deferred%' then
    raise exception 'CANDIDATE_FINALISATION_DEFERRED_RECEIPT_MISSING';
  end if;
  if pg_catalog.has_function_privilege(
       'anon',
       'public.candidate_submission_finalize_single_flight_v1(uuid,text,uuid,integer,text,text,timestamp with time zone,jsonb)',
       'execute'
     )
     or pg_catalog.has_function_privilege(
       'authenticated',
       'public.candidate_submission_finalize_single_flight_v1(uuid,text,uuid,integer,text,text,timestamp with time zone,jsonb)',
       'execute'
     )
     or not pg_catalog.has_function_privilege(
       'service_role',
       'public.candidate_submission_finalize_single_flight_v1(uuid,text,uuid,integer,text,text,timestamp with time zone,jsonb)',
       'execute'
     ) then
    raise exception 'CANDIDATE_FINALISATION_SINGLE_FLIGHT_ACL_INVALID';
  end if;
end;
$verify$;

-- Rollback-contained first-use proof for the single dated Client/Contract
-- settings authority.  It proves precedence, planned-only refresh, real-row
-- freezing, Dedicated NHSP and HealthRoster classification, expense separation,
-- invoice VAT stability, Global-only ERNI/holiday dates and browser isolation.


do $contract_settings_effective_authority_verification$
declare
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_week_one uuid:=gen_random_uuid();
  v_week_two uuid:=gen_random_uuid();
  v_adjustment_week uuid:=gen_random_uuid();
  v_weekly_timesheet uuid:=gen_random_uuid();
  v_daily_timesheet uuid:=gen_random_uuid();
  v_authority jsonb;
  v_frozen jsonb;
  v_fingerprint text;
  v_import jsonb;
  v_vat jsonb;
  v_review record;
  v_finance_erni numeric;
  v_policy jsonb;
  v_flags jsonb;
  v_pay_impact jsonb;
  v_definition text;
  v_previous_finalise_context text;
begin
  update public.settings_defaults
  set bh_list='["2026-12-28"]'::jsonb,
      bh_feed_list='["2026-12-25","2026-12-28"]'::jsonb
  where id=1;

  insert into public.clients(
    id,name,primary_invoice_email,vat_chargeable,payment_terms_days
  ) values(
    v_client,'Settings authority verification Client',
    'settings-authority@example.test',true,30
  );
  insert into public.candidates(id,email,display_name,active,key_norm)
  values(
    v_candidate,
    'settings-authority-'||replace(v_candidate::text,'-','')||'@example.test',
    'Settings Authority Candidate',true,
    'SETTINGS-AUTHORITY-'||replace(v_candidate::text,'-','')
  );
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday,
    is_nhsp,autoprocess_hr,requires_hr,no_timesheet_required,
    vat_rate_pct,erni_pct,bh_list,timesheet_break_entry_mode,
    candidate_expenses_require_separate_timesheet
  ) values(
    gen_random_uuid(),v_client,'2026-06-01','ELECTRONIC',0,
    false,false,false,false,
    20,99,'["2099-01-01"]'::jsonb,'DURATION_MINUTES',false
  );
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,week_ending_weekday_snapshot,
    default_submission_mode,pay_method_snapshot,role,overrideclientsettings,
    is_nhsp,autoprocess_hr,requires_hr,no_timesheet_required
  ) values(
    v_contract,v_candidate,v_client,'2026-01-01','2026-12-31',0,
    'ELECTRONIC','PAYE','RMN',false,false,false,false,false
  );

  if (select effective_from from public.client_settings where client_id=v_client)
       is distinct from date '2026-01-01' then
    raise exception 'CLIENT_SETTINGS_ORIGIN_NOT_ALIGNED_TO_EARLIEST_CONTRACT';
  end if;

  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,is_adjustment
  ) values
    (v_week_one,v_contract,'2026-05-31',0,'OPEN','ELECTRONIC',false),
    (v_week_two,v_contract,'2026-06-07',0,'OPEN','ELECTRONIC',false),
    (v_adjustment_week,v_contract,'2026-06-07',1,'OPEN','MANUAL',true);

  if (select submission_mode_snapshot from public.contract_weeks
      where id=v_adjustment_week)<>'MANUAL'::public.submission_mode_enum then
    raise exception 'PLANNED_ADJUSTMENT_MANUAL_ROUTE_NOT_PRESERVED_ON_INSERT';
  end if;

  select settings_authority_json into v_authority
  from public.contract_weeks where id=v_week_one;
  select erni_pct into v_finance_erni
  from public.settings_finance_pick(date '2026-05-31') limit 1;
  if v_authority->>'authority_version'<>'CONTRACT_SETTINGS_AUTHORITY_V1'
     or v_authority->>'configured_route'<>'STANDARD_WEEKLY'
     or v_authority#>>'{sources,contract_governed_settings}'<>'CLIENT_SETTINGS'
     or coalesce((v_authority#>>'{values,erni_pct}')::numeric,-1)
        is distinct from coalesce(v_finance_erni,13.8)
     or not (v_authority#>'{values,bh_list}' ? '2026-12-25')
     or not (v_authority#>'{values,bh_list}' ? '2026-12-28')
     or (v_authority#>'{values,bh_list}' ? '2099-01-01') then
    raise exception 'GLOBAL_CLIENT_AUTHORITY_RESOLUTION_INVALID:%',v_authority;
  end if;

  -- Self-billing mandates separate Candidate expense carriers without turning
  -- ordinary hour entry into import-controlled work. Both Client inheritance
  -- and explicit Contract override are checked with the expense preference off.
  v_policy:=private._candidate_policy_resolve_v1(v_client,v_contract,'2026-05-31');
  if v_policy->>'expenses_require_separate_timesheet' is distinct from 'false'
     or v_policy->>'import_expense_separation_mandatory' is distinct from 'false' then
    raise exception 'ORDINARY_NON_SELF_BILL_COMBINED_POLICY_CHANGED';
  end if;
  update public.client_settings set self_bill_no_invoices_sent=true
  where client_id=v_client;
  v_policy:=private._candidate_policy_resolve_v1(v_client,v_contract,'2026-05-31');
  v_authority:=private._contract_settings_effective_core_v1(
    v_client,v_contract,'2026-05-31','WEEKLY',null
  );
  if v_policy->>'expenses_require_separate_timesheet' is distinct from 'true'
     or v_policy->>'expenses_require_separate_timesheet_source' is distinct from 'SELF_BILL_MANDATORY'
     or v_policy->>'import_expense_separation_mandatory' is distinct from 'false'
     or v_authority->>'configured_route' is distinct from 'STANDARD_WEEKLY'
     or v_authority#>>'{applicability,candidate_hours_view_only}' is distinct from 'false'
     or v_authority#>>'{applicability,import_authoritative}' is distinct from 'false' then
    raise exception 'ORDINARY_SELF_BILL_CLIENT_EXPENSE_SEPARATION_INVALID';
  end if;
  v_authority:=private._contract_settings_effective_core_v1(
    v_client,v_contract,'2026-05-31','DAILY',null
  );
  if v_authority#>>'{values,candidate_expenses_require_separate_timesheet}' is distinct from 'true'
     or v_authority#>>'{applicability,candidate_hours_view_only}' is distinct from 'false'
     or v_authority#>>'{applicability,import_authoritative}' is distinct from 'false' then
    raise exception 'ORDINARY_SELF_BILL_DAILY_EXPENSE_SEPARATION_INVALID';
  end if;

  -- A true Contract override controls self-billing independently from the
  -- Client. A false expense-separation preference cannot bypass self-billing.
  update public.contracts set overrideclientsettings=true,self_bill=false,
    candidate_expenses_require_separate_timesheet_override=false
  where id=v_contract;
  v_policy:=private._candidate_policy_resolve_v1(v_client,v_contract,'2026-05-31');
  if v_policy->>'expenses_require_separate_timesheet' is distinct from 'false' then
    raise exception 'SELF_BILL_CONTRACT_FALSE_OVERRIDE_IGNORED';
  end if;
  update public.client_settings set self_bill_no_invoices_sent=false
  where client_id=v_client;
  update public.contracts set self_bill=true where id=v_contract;
  v_policy:=private._candidate_policy_resolve_v1(v_client,v_contract,'2026-05-31');
  if v_policy->>'expenses_require_separate_timesheet' is distinct from 'true'
     or v_policy->>'expenses_require_separate_timesheet_source' is distinct from 'SELF_BILL_MANDATORY'
     or v_policy->>'import_expense_separation_mandatory' is distinct from 'false' then
    raise exception 'SELF_BILL_CONTRACT_TRUE_OVERRIDE_NOT_ENFORCED';
  end if;

  -- First-use final-state admission rejects a stale combined caller but keeps
  -- an hours-only submission and a separate expense-only submission valid.
  v_previous_finalise_context:=current_setting('cloudtms.candidate_electronic_finalise',true);
  perform set_config('cloudtms.candidate_electronic_finalise','self-bill-verification',true);
  begin
    perform private._candidate_weekly_final_state_guard_v1(
      v_week_one,null,'{"line_type":"HOURS"}'::jsonb,'{}'::jsonb,
      '{"total_hours":8,"accommodation_pay_ex_vat":25}'::jsonb
    );
    raise exception 'SELF_BILL_COMBINED_SUBMISSION_ADMITTED';
  exception when sqlstate '22023' then
    if sqlerrm is distinct from 'HOURS_AND_EXPENSES_REQUIRE_SEPARATE_TIMESHEETS' then
      raise;
    end if;
  end;
  v_flags:=private._candidate_weekly_final_state_guard_v1(
    v_week_one,null,'{"line_type":"HOURS"}'::jsonb,'{}'::jsonb,
    '{"total_hours":8}'::jsonb
  );
  if v_flags->>'record_role' is distinct from 'HOURS_ONLY' then
    raise exception 'SELF_BILL_ORDINARY_HOUR_ENTRY_BLOCKED';
  end if;
  v_flags:=private._candidate_weekly_final_state_guard_v1(
    v_adjustment_week,null,'{"line_type":"EXPENSES"}'::jsonb,'{}'::jsonb,
    '{"total_hours":0,"accommodation_pay_ex_vat":25}'::jsonb
  );
  if v_flags->>'record_role' is distinct from 'EXPENSE_ONLY' then
    raise exception 'SELF_BILL_SEPARATE_EXPENSE_ENTRY_BLOCKED';
  end if;
  perform set_config('cloudtms.candidate_electronic_finalise',coalesce(v_previous_finalise_context,''),true);
  update public.contracts set overrideclientsettings=false,self_bill=false,
    candidate_expenses_require_separate_timesheet_override=null
  where id=v_contract;

  -- A Client change refreshes both remaining planned weeks while Contract
  -- override is off. Dedicated NHSP Weekly is always authoritative.
  update public.client_settings set is_nhsp=true,nhsp_import_auto_authorise=true
  where client_id=v_client;
  if (select submission_mode_snapshot from public.contract_weeks
      where id=v_adjustment_week)<>'MANUAL'::public.submission_mode_enum then
    raise exception 'PLANNED_ADJUSTMENT_MANUAL_ROUTE_REWRITTEN_BY_CLIENT_REFRESH';
  end if;
  select settings_authority_json into v_authority
  from public.contract_weeks where id=v_week_one;
  if v_authority->>'configured_route'<>'DEDICATED_NHSP_WEEKLY'
     or v_authority#>>'{applicability,import_authoritative}'<>'true'
     or v_authority#>>'{applicability,candidate_hours_view_only}'<>'true'
     or v_authority#>>'{values,candidate_expenses_require_separate_timesheet}'<>'true'
     or v_authority#>>'{values,candidate_paper_submission_enabled}'<>'false' then
    raise exception 'DEDICATED_NHSP_WEEKLY_NOT_AUTHORITATIVE:%',v_authority;
  end if;

  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,contract_id,week_ending_date,line_type,submission_mode,
    sheet_scope
  ) values(
    v_weekly_timesheet,'SETTINGS-AUTH-WEEKLY-'||v_weekly_timesheet::text,
    lower(v_candidate::text),'settings authority hospital','ward','rmn',
    v_contract,'2026-05-31','HOURS','MANUAL','WEEKLY'
  );
  update public.contract_weeks set timesheet_id=v_weekly_timesheet
  where id=v_week_one;
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,
    processing_status
  ) values(v_weekly_timesheet,1,v_candidate,v_client,8,'UNPROCESSED');

  select settings_authority_json,settings_authority_fingerprint
  into v_frozen,v_fingerprint
  from public.timesheets where timesheet_id=v_weekly_timesheet;
  if v_frozen#>>'{applicability,import_authoritative}'<>'true'
     or private._timesheet_settings_authority_frozen_v1(v_weekly_timesheet)
        is distinct from v_frozen then
    raise exception 'WEEKLY_REAL_TIMESHEET_NOT_FROZEN:%',v_frozen;
  end if;
  update public.timesheets set
    settings_authority_json=jsonb_set(settings_authority_json,'{values,is_nhsp}','false'::jsonb),
    settings_authority_fingerprint=repeat('0',64)
  where timesheet_id=v_weekly_timesheet;
  if (select settings_authority_json from public.timesheets
      where timesheet_id=v_weekly_timesheet) is distinct from v_frozen
     or (select settings_authority_fingerprint from public.timesheets
         where timesheet_id=v_weekly_timesheet) is distinct from v_fingerprint then
    raise exception 'REAL_TIMESHEET_AUTHORITY_DIRECT_UPDATE_NOT_BLOCKED';
  end if;
  update public.contract_weeks set
    settings_authority_json='{}'::jsonb,
    settings_authority_version=null,
    settings_authority_fingerprint=null,
    settings_authority_resolved_at=null
  where id=v_week_one;
  if (select settings_authority_fingerprint from public.contract_weeks
      where id=v_week_one) is distinct from v_fingerprint then
    raise exception 'LINKED_WEEK_AUTHORITY_DIRECT_UPDATE_NOT_BLOCKED';
  end if;
  update public.contract_weeks set
    settings_authority_json='{}'::jsonb,
    settings_authority_version=null,
    settings_authority_fingerprint=null,
    settings_authority_resolved_at=null
  where id=v_week_two;
  if (select settings_authority_json from public.contract_weeks where id=v_week_two)='{}'::jsonb then
    raise exception 'PLANNED_WEEK_AUTHORITY_DIRECT_UPDATE_NOT_RECALCULATED';
  end if;
  if private._candidate_submission_mode_v1(v_client,v_contract,'2026-05-31')
       <>'ELECTRONIC'::public.submission_mode_enum then
    raise exception 'CANDIDATE_SUBMISSION_MODE_BYPASSED_AUTHORITY';
  end if;
  v_policy:=private._candidate_policy_resolve_v1(v_client,v_contract,'2026-05-31');
  if v_policy->>'import_expense_separation_mandatory'<>'true'
     or v_policy->>'paper_submission_enabled'<>'false'
     or v_policy->>'authority_fingerprint' is distinct from v_fingerprint then
    raise exception 'CANDIDATE_POLICY_BYPASSED_AUTHORITY:%',v_policy;
  end if;
  v_policy:=public.import_auto_authorise_policy_resolve_v2(
    'NHSP'::public.hr_source_enum,v_client,v_contract,v_weekly_timesheet,
    '2026-05-31',false
  );
  if v_policy->>'effective_value'<>'true'
     or v_policy->>'authority_version'<>'CONTRACT_SETTINGS_AUTHORITY_V1'
     or v_policy->>'relevant_date'<>'2026-05-31'
     or v_policy->>'authority_fingerprint' is distinct from v_fingerprint then
    raise exception 'IMPORT_AUTO_AUTHORISE_BYPASSED_AUTHORITY:%',v_policy;
  end if;

  -- The stale caller shape says editable; server authority must still suppress
  -- the NHSP hours/break editor and preserve separate Candidate expenses.
  v_import:=private._candidate_import_authoritative_v1(
    v_client,v_contract,v_weekly_timesheet,null,'2026-05-31'
  );
  if v_import->>'is_import_authoritative'<>'true'
     or v_import->>'candidate_hours_view_only'<>'true'
     or v_import->>'mandatory_expense_separation'<>'true' then
    raise exception 'CANDIDATE_NHSP_READ_AUTHORITY_INVALID:%',v_import;
  end if;
  v_import:=private._candidate_break_entry_context_core_v1(
    v_weekly_timesheet,v_week_one,'2026-05-31',
    jsonb_build_object(
      'can_edit_hours',true,'import_authoritative',false,
      'route_family','ELECTRONIC'
    )
  );
  if v_import->>'applicable'<>'false'
     or v_import->>'reason'<>'IMPORT_AUTHORITATIVE' then
    raise exception 'CANDIDATE_NHSP_BREAK_EDITOR_EXPOSED:%',v_import;
  end if;

  -- Later Client settings refresh only the still-planned week. They cannot
  -- rewrite the real Weekly Timesheet or its invoicing authority.
  update public.client_settings set
    is_nhsp=false,autoprocess_hr=true,requires_hr=true,
    no_timesheet_required=false,vat_rate_pct=5,
    pay_reference_required=true
  where client_id=v_client;
  if (select settings_authority_fingerprint from public.timesheets
     where timesheet_id=v_weekly_timesheet) is distinct from v_fingerprint
     or (select (settings_authority_json#>>'{values,vat_rate_pct}')::numeric
         from public.timesheets where timesheet_id=v_weekly_timesheet)<>20 then
    raise exception 'REAL_WEEKLY_TIMESHEET_REWRITTEN_BY_CLIENT_CHANGE: expected %, actual %, vat %',
      v_fingerprint,
      (select settings_authority_fingerprint from public.timesheets
       where timesheet_id=v_weekly_timesheet),
      (select settings_authority_json#>>'{values,vat_rate_pct}'
       from public.timesheets where timesheet_id=v_weekly_timesheet);
  end if;
  select x.out_policy,x.out_effective_flags into v_policy,v_flags
  from public.tsfin_load_context_batch(array[v_weekly_timesheet]) x;
  if (v_policy->>'vat_rate_pct')::numeric<>20
     or v_policy->>'settings_authority_fingerprint' is distinct from v_fingerprint
     or v_flags->>'client_is_nhsp'<>'true' then
    raise exception 'TSFIN_PROCESSING_DID_NOT_USE_FROZEN_AUTHORITY:%:%',v_policy,v_flags;
  end if;
  v_pay_impact:=public.pay_timesheet_impact_preview(v_weekly_timesheet);
  if v_pay_impact->>'require_reference_to_pay'<>'false' then
    raise exception 'BANKING_PAY_IMPACT_DID_NOT_USE_FROZEN_AUTHORITY:%',v_pay_impact;
  end if;
  select settings_authority_json into v_authority
  from public.contract_weeks where id=v_week_two;
  if v_authority->>'configured_route'<>'HEALTHROSTER_WEEKLY_VALIDATION'
     or v_authority#>>'{applicability,import_authoritative}'<>'false' then
    raise exception 'HEALTHROSTER_VALIDATION_CLASSIFICATION_INVALID:%',v_authority;
  end if;
  select * into v_review
  from public._import_review_effective_authority_core_v1(
    'HR_WEEKLY',v_contract,v_client,'2026-06-07'
  );
  if not v_review.route_eligible or not v_review.validation_eligible
     or v_review.import_authoritative then
    raise exception 'HEALTHROSTER_VALIDATION_REVIEW_AUTHORITY_INVALID';
  end if;

  select to_jsonb(v) into v_vat
  from private._invoice_generation_vat_policy_batch(jsonb_build_array(
    jsonb_build_object(
      'source_member_key','settings-authority-vat',
      'source_type','TIMESHEET','source_id',v_weekly_timesheet,
      'timesheet_id',v_weekly_timesheet,'effective_date','2026-05-31'
    )
  )) v limit 1;
  if v_vat->>'valid'<>'true' or (v_vat->>'vat_rate')::numeric<>20 then
    raise exception 'INVOICE_VAT_DID_NOT_USE_FROZEN_TIMESHEET_AUTHORITY:%',v_vat;
  end if;

  -- A Contract override retains its governed values, while a subsequent
  -- Client change still refreshes Client-owned values on the remaining
  -- planned week.
  update public.contracts set
    overrideclientsettings=true,is_nhsp=false,autoprocess_hr=false,
    requires_hr=false,no_timesheet_required=false
  where id=v_contract;
  update public.client_settings set is_nhsp=true,autoprocess_hr=false,
    requires_hr=false,no_timesheet_required=false,vat_rate_pct=7
  where client_id=v_client;
  select settings_authority_json into v_authority
  from public.contract_weeks where id=v_week_two;
  if v_authority->>'configured_route'<>'STANDARD_WEEKLY'
     or v_authority#>>'{sources,contract_governed_settings}'<>'CONTRACT_OVERRIDE'
     or coalesce((v_authority#>>'{values,vat_rate_pct}')::numeric,-1)<>7 then
    raise exception 'CONTRACT_OVERRIDE_PRECEDENCE_INVALID:%',v_authority;
  end if;
  update public.contracts set is_nhsp=true where id=v_contract;
  if (select settings_authority_json#>>'{applicability,import_authoritative}'
      from public.contract_weeks where id=v_week_two)<>'true' then
    raise exception 'CONTRACT_OVERRIDE_PLANNED_REFRESH_MISSING';
  end if;

  -- HealthRoster authoritative is the exact autoprocess + no-timesheet route;
  -- it does not require or permit the validation-only flag simultaneously.
  update public.contracts set overrideclientsettings=false where id=v_contract;
  update public.client_settings set
    is_nhsp=false,autoprocess_hr=true,requires_hr=false,
    no_timesheet_required=true
  where client_id=v_client;
  select settings_authority_json into v_authority
  from public.contract_weeks where id=v_week_two;
  if v_authority->>'configured_route'<>'HEALTHROSTER_WEEKLY_AUTHORITATIVE'
     or v_authority#>>'{applicability,import_authoritative}'<>'true' then
    raise exception 'HEALTHROSTER_AUTHORITATIVE_CLASSIFICATION_INVALID:%',v_authority;
  end if;
  select * into v_review
  from public._import_review_effective_authority_core_v1(
    'HR_WEEKLY',v_contract,v_client,'2026-06-07'
  );
  if not v_review.route_eligible or v_review.validation_eligible
     or not v_review.import_authoritative then
    raise exception 'HEALTHROSTER_AUTHORITATIVE_REVIEW_AUTHORITY_INVALID';
  end if;

  -- Daily is not real at row creation. It freezes only when Office processing
  -- supplies processed_at_utc, then later settings edits cannot rewrite it.
  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,contract_id,week_ending_date,line_type,submission_mode,
    sheet_scope,settings_authority_json,settings_authority_version,
    settings_authority_fingerprint,settings_authority_resolved_at
  ) values(
    v_daily_timesheet,'SETTINGS-AUTH-DAILY-'||v_daily_timesheet::text,
    lower(v_candidate::text),'settings authority hospital','ward','rmn',
    v_contract,'2026-06-07','HOURS','MANUAL','DAILY',
    v_frozen,'CONTRACT_SETTINGS_AUTHORITY_V1',v_fingerprint,
    (v_frozen->>'resolved_at_utc')::timestamptz
  );
  if (select settings_authority_json from public.timesheets
      where timesheet_id=v_daily_timesheet)<>'{}'::jsonb then
    raise exception 'DAILY_TIMESHEET_CALLER_SNAPSHOT_NOT_CLEARED_ON_INSERT';
  end if;
  update public.timesheets set
    settings_authority_json=v_frozen,
    settings_authority_version='CONTRACT_SETTINGS_AUTHORITY_V1',
    settings_authority_fingerprint=v_fingerprint,
    settings_authority_resolved_at=(v_frozen->>'resolved_at_utc')::timestamptz
  where timesheet_id=v_daily_timesheet;
  if (select settings_authority_json from public.timesheets
      where timesheet_id=v_daily_timesheet)<>'{}'::jsonb then
    raise exception 'UNPROCESSED_DAILY_TIMESHEET_CALLER_SNAPSHOT_NOT_CLEARED';
  end if;
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,
    processing_status,processed_at_utc
  ) values(
    v_daily_timesheet,1,v_candidate,v_client,8,'READY_FOR_INVOICE',
    '2026-06-08 09:00:00+00'
  );
  select settings_authority_json,settings_authority_fingerprint
  into v_frozen,v_fingerprint
  from public.timesheets where timesheet_id=v_daily_timesheet;
  if v_frozen->>'configured_route'<>'HEALTHROSTER_DAILY_AUTHORITATIVE'
     or v_frozen#>>'{applicability,import_authoritative}'<>'true' then
    raise exception 'DAILY_PROCESSED_TIMESHEET_NOT_FROZEN:%',v_frozen;
  end if;
  update public.client_settings set
    autoprocess_hr=false,requires_hr=false,no_timesheet_required=false
  where client_id=v_client;
  if (select settings_authority_fingerprint from public.timesheets
      where timesheet_id=v_daily_timesheet) is distinct from v_fingerprint then
    raise exception 'REAL_DAILY_TIMESHEET_REWRITTEN_BY_CLIENT_CHANGE';
  end if;

  if not exists(
       select 1 from pg_catalog.pg_trigger
       where tgname='contract_week_settings_authority_before_v1' and tgenabled='O'
     )
     or not exists(
       select 1 from pg_catalog.pg_trigger
       where tgname='daily_timesheet_settings_authority_after_fin_v1' and tgenabled='O'
     ) then
    raise exception 'CONTRACT_SETTINGS_FREEZE_TRIGGERS_NOT_ENABLED';
  end if;
  select pg_catalog.pg_get_functiondef(
    pg_catalog.to_regprocedure(
      'public.pay_preview_candidate_collect_scope(jsonb,uuid,jsonb,integer)'
    )
  ) into v_definition;
  if (length(v_definition)-length(replace(
       v_definition,'private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)',''
     ))) / length('private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)')<>2
     or v_definition like '%con.overrideclientsettings%require_reference_to_pay%'
     or v_definition like '%cs.pay_reference_required%as require_reference_to_pay%' then
    raise exception 'BANKING_PAY_COLLECT_SCOPE_NOT_FROZEN';
  end if;
  select pg_catalog.pg_get_functiondef(
    pg_catalog.to_regprocedure('private._invoice_correction_validate_batch(jsonb,date)')
  ) into v_definition;
  if v_definition not like '%_timesheet_settings_authority_frozen_v1%'
     or v_definition like '%from public.client_settings%' then
    raise exception 'INVOICE_CORRECTION_VALIDATION_NOT_FROZEN';
  end if;
  select pg_catalog.pg_get_functiondef(
    pg_catalog.to_regprocedure(
      'private._invoice_presentation_snapshot_batch(jsonb,timestamp with time zone)'
    )
  ) into v_definition;
  if v_definition not like '%_timesheet_settings_authority_frozen_v1%'
     or v_definition like '%from public.client_settings%' then
    raise exception 'INVOICE_PRESENTATION_NOT_FROZEN';
  end if;
  select pg_catalog.pg_get_functiondef(
    pg_catalog.to_regprocedure('public.timesheet_summary_lightweight_rows_v1(jsonb)')
  ) into v_definition;
  if v_definition like '%BOOL_OR(client_setting.reference_number_required_to_issue_invoice)%'
     or v_definition like '%client_reference_settings%' then
    raise exception 'OFFICE_TIMESHEET_SUMMARY_STILL_READS_CLIENT_HISTORY';
  end if;
  if pg_catalog.has_function_privilege(
       'anon','public.contract_settings_effective_get_v1(uuid,uuid,date,text,uuid)','EXECUTE'
     )
     or pg_catalog.has_function_privilege(
       'authenticated','public.contract_settings_effective_get_v1(uuid,uuid,date,text,uuid)','EXECUTE'
     )
     or not pg_catalog.has_function_privilege(
       'service_role','public.contract_settings_effective_get_v1(uuid,uuid,date,text,uuid)','EXECUTE'
     ) then
    raise exception 'CONTRACT_SETTINGS_RESOLVER_ACL_INVALID';
  end if;
end
$contract_settings_effective_authority_verification$;



