do $history_anchor$
declare
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_anchor_one_week uuid:=gen_random_uuid();
  v_anchor_two_week uuid:=gen_random_uuid();
  v_anchor_one_timesheet uuid:=gen_random_uuid();
  v_anchor_two_timesheet uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_session uuid:=gen_random_uuid();
  v_first_workflow uuid:=gen_random_uuid();
  v_recovered_workflow uuid:=gen_random_uuid();
  v_conflicting_workflow uuid:=gen_random_uuid();
  v_refused_workflow uuid:=gen_random_uuid();
  v_carrier_week uuid;
  v_email text:='history-anchor-'||gen_random_uuid()::text||'@example.test';
  v_carrier jsonb;
  v_result jsonb;
begin
  insert into public.clients(id,name)
  values(v_client,'Candidate history anchor runtime client');

  insert into public.candidates(id,email,active,key_norm)
  values(v_candidate,v_email,true,'GCK-HISTORY-'||replace(v_candidate::text,'-',''));

  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,
    candidate_expenses_require_separate_timesheet,
    candidate_paper_submission_enabled,candidate_expense_invoice_email
  ) values(
    gen_random_uuid(),v_client,current_date-1,'ELECTRONIC',true,true,
    'expenses@example.test'
  );

  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,
    pay_method_snapshot,week_ending_weekday_snapshot,default_submission_mode
  ) values(
    v_contract,v_candidate,v_client,current_date-30,current_date+30,
    'PAYE',extract(dow from current_date)::integer,'ELECTRONIC'
  );

  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    contract_id,week_ending_date,sheet_scope,line_type,submission_mode,
    r2_nurse_key,r2_auth_key
  ) values
  (
    v_anchor_one_timesheet,'HISTORY_ANCHOR_ONE_'||replace(v_anchor_one_timesheet::text,'-',''),
    'GCK-HISTORY-'||replace(v_candidate::text,'-',''),
    'HISTORY HOSPITAL','HISTORY WARD ONE','NURSE',
    v_contract,current_date,'WEEKLY','HOURS','ELECTRONIC',
    'history-anchor/one/candidate','history-anchor/one/manager'
  ),
  (
    v_anchor_two_timesheet,'HISTORY_ANCHOR_TWO_'||replace(v_anchor_two_timesheet::text,'-',''),
    'GCK-HISTORY-'||replace(v_candidate::text,'-',''),
    'HISTORY HOSPITAL','HISTORY WARD TWO','NURSE',
    v_contract,current_date,'WEEKLY','HOURS','ELECTRONIC',
    'history-anchor/two/candidate','history-anchor/two/manager'
  );

  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id
  ) values
    (v_anchor_one_week,v_contract,current_date,0,'OPEN','ELECTRONIC',v_anchor_one_timesheet),
    (v_anchor_two_week,v_contract,current_date,1,'OPEN','ELECTRONIC',v_anchor_two_timesheet);

  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,processing_status
  ) values
    (v_anchor_one_timesheet,1,v_candidate,v_client,8,'UNPROCESSED'),
    (v_anchor_two_timesheet,1,v_candidate,v_client,4,'UNPROCESSED');

  insert into public.candidate_app_accounts(id,environment,email_normalized,status)
  values(v_account,'TEST',lower(v_email),'ACTIVE');

  insert into public.candidate_app_sessions(
    id,account_id,environment,selected_candidate_id,status,refresh_token_hash,
    expires_at_utc,absolute_expires_at_utc
  ) values(
    v_session,v_account,'TEST',v_candidate,'ACTIVE',decode(repeat('d4',32),'hex'),
    now()+interval '30 days',now()+interval '90 days'
  );

  v_carrier:=public.expense_carrier_resolve_or_create_atomic_v1(
    v_candidate,'TEST',v_anchor_one_timesheet,null,
    'history-anchor:create-carrier',now()
  );
  if v_carrier->>'placement'<>'CREATE_CARRIER'
     or nullif(v_carrier->>'target_contract_week_id','') is null then
    raise exception 'history-anchor carrier was not created: %',v_carrier;
  end if;
  v_carrier_week:=(v_carrier->>'target_contract_week_id')::uuid;

  v_result:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_first_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
      'contract_id',v_contract,'contract_week_id',v_carrier_week,
      'anchor_timesheet_id',v_anchor_one_timesheet,
      'week_ending_date',current_date
    ),
    'history-anchor:first-workflow',now()
  );
  if coalesce((v_result->>'ok')::boolean,false)=false then
    raise exception 'first history-anchor workflow was not created: %',v_result;
  end if;
  update public.candidate_submission_workflows
  set state='CANCELLED',updated_at_utc=now()
  where id=v_first_workflow;

  -- No anchor is supplied. Although two worked Timesheets exist, this exact
  -- carrier has one durable historical anchor and must recover it.
  v_result:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_recovered_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
      'contract_id',v_contract,'contract_week_id',v_carrier_week,
      'week_ending_date',current_date
    ),
    'history-anchor:recovered-workflow',now()+interval '1 second'
  );
  if coalesce((v_result->>'ok')::boolean,false)=false
     or not exists(
       select 1 from public.candidate_submission_workflows
       where id=v_recovered_workflow
         and contract_week_id=v_carrier_week
         and anchor_timesheet_id=v_anchor_one_timesheet
         and target_timesheet_id is null
     ) then
    raise exception 'unique historical carrier anchor was not recovered: %',v_result;
  end if;
  update public.candidate_submission_workflows
  set state='CANCELLED',updated_at_utc=now()
  where id=v_recovered_workflow;

  -- An explicit, valid but different anchor creates contradictory carrier
  -- history. A later anchorless request must fail closed instead of guessing.
  v_result:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_conflicting_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
      'contract_id',v_contract,'contract_week_id',v_carrier_week,
      'anchor_timesheet_id',v_anchor_two_timesheet,
      'week_ending_date',current_date
    ),
    'history-anchor:conflicting-workflow',now()+interval '2 seconds'
  );
  if coalesce((v_result->>'ok')::boolean,false)=false then
    raise exception 'conflicting history fixture workflow was not created: %',v_result;
  end if;
  update public.candidate_submission_workflows
  set state='CANCELLED',updated_at_utc=now()
  where id=v_conflicting_workflow;

  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_refused_workflow,'CREATE',1,
      jsonb_build_object(
        'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
        'contract_id',v_contract,'contract_week_id',v_carrier_week,
        'week_ending_date',current_date
      ),
      'history-anchor:must-refuse',now()+interval '3 seconds'
    );
    raise exception 'contradictory historical carrier anchors were accepted';
  exception
    when sqlstate '55000' then
      if sqlerrm<>'EXPENSE_WORKED_ANCHOR_HISTORY_AMBIGUOUS' then
        raise exception 'wrong contradictory-history failure: %',sqlerrm;
      end if;
  end;

  if exists(select 1 from public.candidate_submission_workflows where id=v_refused_workflow) then
    raise exception 'refused contradictory-history request created a workflow';
  end if;
end;
$history_anchor$;

-- Read-only installed-definition proof for the failed-payment/no-money result
-- envelope. Runtime authority is Miget TEST; the `supabase` directory name is
-- historical. This verifier performs no business or financial mutation.
DO $verification$
DECLARE
  v_oid oid := pg_catalog.to_regprocedure(
    'public.pay_no_money_unwind_apply_work_item(uuid,uuid)'
  );
  v_owner text;
  v_security_definer boolean;
  v_volatility "char";
  v_parallel "char";
  v_config text[];
  v_public_execute boolean;
  v_definition text;
  v_result_section text;
  v_result_start integer;
  v_result_end integer;
  v_result_join_count integer;
  v_required_field text;
BEGIN
  IF v_oid IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_NO_MONEY_UNWIND_OWNER_MISSING';
  END IF;

  SELECT
    pg_catalog.pg_get_userbyid(proc.proowner),
    proc.prosecdef,
    proc.provolatile,
    proc.proparallel,
    proc.proconfig,
    EXISTS (
      SELECT 1
      FROM pg_catalog.aclexplode(
        coalesce(proc.proacl, pg_catalog.acldefault('f', proc.proowner))
      ) AS acl_row
      WHERE acl_row.grantee = 0
        AND acl_row.privilege_type = 'EXECUTE'
    ),
    pg_catalog.pg_get_functiondef(proc.oid)
  INTO STRICT
    v_owner,
    v_security_definer,
    v_volatility,
    v_parallel,
    v_config,
    v_public_execute,
    v_definition
  FROM pg_catalog.pg_proc AS proc
  WHERE proc.oid = v_oid;

  IF v_owner NOT IN (CURRENT_USER, 'postgres')
     OR v_security_definer IS DISTINCT FROM true
     OR v_volatility <> 'v'
     OR v_parallel <> 'u'
     OR v_config IS DISTINCT FROM ARRAY[
          'search_path=pg_catalog, private, extensions, pg_temp',
          'statement_timeout=6000ms',
          'lock_timeout=1000ms'
        ]::text[]
     OR v_public_execute
     OR pg_catalog.has_function_privilege('anon', v_oid, 'EXECUTE')
     OR pg_catalog.has_function_privilege('authenticated', v_oid, 'EXECUTE')
     OR NOT pg_catalog.has_function_privilege('service_role', v_oid, 'EXECUTE') THEN
    RAISE EXCEPTION 'BANKING_PAY_NO_MONEY_UNWIND_METADATA_OR_ACL_DRIFT';
  END IF;

  v_result_start := pg_catalog.strpos(v_definition, 'v_result := jsonb_build_object(');
  v_result_end := v_result_start - 1 + pg_catalog.strpos(
    pg_catalog.substr(v_definition, v_result_start),
    'UPDATE public.pay_payment_correction_work_items'
  );

  IF v_result_start = 0 OR v_result_end <= v_result_start THEN
    RAISE EXCEPTION 'BANKING_PAY_NO_MONEY_UNWIND_RESULT_ENVELOPE_MISSING';
  END IF;

  v_result_section := pg_catalog.substr(
    v_definition,
    v_result_start,
    v_result_end - v_result_start
  );
  v_result_join_count := (
    pg_catalog.length(v_result_section)
    - pg_catalog.length(pg_catalog.replace(v_result_section, ') || jsonb_build_object(', ''))
  ) / pg_catalog.length(') || jsonb_build_object(');

  IF v_result_section IS NULL
     OR v_result_join_count <> 3
     OR pg_catalog.strpos(
          v_result_section,
          '''communication_cleanup_contract_version'', CASE' || chr(10)
            || '      WHEN v_candidate_scope_contract_version = 2 THEN v_communication_cleanup_contract_version ELSE NULL::integer END'
            || chr(10) || '  ) || jsonb_build_object(' || chr(10)
            || '    ''matching_queued_count'', v_matching_queued_count'
        ) = 0
     OR pg_catalog.strpos(
          v_result_section,
          '''blockers'', ''[]''::jsonb' || chr(10) || '  ) || jsonb_build_object(' || chr(10)
            || '    ''manual_adjustment_support_details_json'', COALESCE(v_manual_adjustment_result, ''{}''::jsonb)'
        ) = 0
     OR pg_catalog.strpos(
          v_result_section,
          '''rail_state_summary'', COALESCE(v_rail_state_summary_json, ''{}''::jsonb)' || chr(10)
            || '  ) || jsonb_build_object(' || chr(10)
            || '    ''workbench_refresh_status'', COALESCE(v_workbench_refresh_status, ''NOT_REQUIRED'')'
        ) = 0 THEN
    RAISE EXCEPTION 'BANKING_PAY_NO_MONEY_UNWIND_RESULT_ENVELOPE_NOT_BOUNDED';
  END IF;

  FOREACH v_required_field IN ARRAY ARRAY[
    'selected_candidate_count',
    'voided_item_count',
    'released_reservation_count',
    'restored_component_count',
    'active_batch_amount_inc_vat_after',
    'classification_result',
    'provider_evidence_result',
    'rail_state_summary',
    'workbench_refresh'
  ] LOOP
    IF pg_catalog.strpos(v_result_section, quote_literal(v_required_field)) = 0 THEN
      RAISE EXCEPTION 'BANKING_PAY_NO_MONEY_UNWIND_RESULT_FIELD_MISSING: %', v_required_field;
    END IF;
  END LOOP;
END;
$verification$;

-- A manager-approved Candidate submission remains immutable while it awaits
-- Office authorisation, but a later claim may use a separate expense-only
-- carrier immediately after the approved submission safely finalises.
-- Before manager approval, the active claim must still be withdrawn and
-- restarted rather than accepting another expense in parallel.


do $verification$
declare
  v_timesheet uuid:=gen_random_uuid();
  v_week uuid:=gen_random_uuid();
  v_workflow uuid:=gen_random_uuid();
  v_action jsonb;
  v_action_contract jsonb;
  v_workflows jsonb;
  v_definition text;
  v_status text;
begin
  select lower(pg_get_functiondef(to_regprocedure(
    'private._candidate_timesheet_primary_action_v1(text,jsonb,jsonb,uuid,uuid)'
  ))) into v_definition;
  if position('v_has_finalised_hours' in v_definition)=0
     or position('v_hours_office_protected' in v_definition)<>0
     or v_definition~'pg_catalog\.(coalesce|nullif|least|greatest)\s*\(' then
    raise exception 'Manager-approved additional-expense action authority is not installed safely';
  end if;

  v_workflows:=jsonb_build_array(jsonb_build_object(
    'workflow_id',v_workflow,'workflow_kind','CONTRACT_COMBINED',
    'state','FINALISED','generation',2,'detail_action_owner',true,
    'updated_at_utc',now()
  ));

  v_action:=private._candidate_timesheet_primary_action_v1(
    'PENDING_AUTH',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_timesheet,v_week
  );
  if v_action->>'code'<>'ADD_EXPENSES'
     or v_action->>'label'<>'Add Expenses' then
    raise exception 'Manager-approved combined claim did not expose a separate expense claim: %',v_action;
  end if;
  v_action_contract:=private._candidate_timesheet_action_contract_v1(
    'PENDING_AUTH',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_timesheet,v_week,now()
  );
  if v_action_contract#>>'{primary_action,code}'<>'ADD_EXPENSES'
     or not exists(
       select 1
       from jsonb_array_elements(v_action_contract->'available_actions') item
       where item->>'code'='ADD_EXPENSES'
     ) then
    raise exception 'Manager-approved combined claim lost its separate expense action: %',
      v_action_contract;
  end if;

  foreach v_status in array array['AUTHORISED','INVOICED_NOT_PAID','PAID'] loop
    v_action:=private._candidate_timesheet_primary_action_v1(
      v_status,v_workflows,
      jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
      v_timesheet,v_week
    );
    if v_action->>'code'<>'ADD_EXPENSES'
       or v_action->>'label'<>'Add Expenses' then
      raise exception 'Later status % did not retain the separate expense action: %',
        v_status,v_action;
    end if;
  end loop;

  v_action_contract:=private._candidate_timesheet_action_contract_v1(
    'AUTHORISED',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_timesheet,v_week,now()
  );
  if v_action_contract#>>'{primary_action,code}'<>'ADD_EXPENSES'
     or not exists(
       select 1
       from jsonb_array_elements(v_action_contract->'available_actions') item
       where item->>'code'='ADD_EXPENSES'
     ) then
    raise exception 'Authorised claim lost its separate expense action: %',
      v_action_contract;
  end if;

  v_workflows:=jsonb_build_array(jsonb_build_object(
    'workflow_id',v_workflow,'workflow_kind','CONTRACT_HOURS',
    'state','FINALISED','generation',2,'detail_action_owner',true,
    'updated_at_utc',now()
  ));
  v_action:=private._candidate_timesheet_primary_action_v1(
    'PENDING_AUTH',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_timesheet,v_week
  );
  if v_action->>'code'<>'ADD_EXPENSES' then
    raise exception 'Manager-approved hours did not expose a separate expense claim: %',v_action;
  end if;

  v_workflows:=jsonb_build_array(jsonb_build_object(
    'workflow_id',v_workflow,'workflow_kind','CONTRACT_EXPENSE',
    'state','FINALISED','generation',2,'detail_action_owner',true,
    'updated_at_utc',now()
  ));
  v_action:=private._candidate_timesheet_primary_action_v1(
    'PENDING_AUTH',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_timesheet,v_week
  );
  if v_action->>'code'<>'ADD_EXPENSES' then
    raise exception 'Manager-approved expense still blocked the next claim: %',v_action;
  end if;

  v_workflows:=jsonb_build_array(jsonb_build_object(
    'workflow_id',v_workflow,'workflow_kind','CONTRACT_COMBINED',
    'state','AWAITING_MANAGER_APPROVAL','generation',2,'detail_action_owner',true,
    'updated_at_utc',now()
  ));
  v_action:=private._candidate_timesheet_primary_action_v1(
    'AWAITING_MANAGER_APPROVAL',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_timesheet,v_week
  );
  if v_action->>'code'<>'CONTINUE_TIMESHEET' then
    raise exception 'Pre-approval submission did not remain on its existing claim: %',v_action;
  end if;
  v_action_contract:=private._candidate_timesheet_action_contract_v1(
    'AWAITING_MANAGER_APPROVAL',v_workflows,
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_timesheet,v_week,now()
  );
  if exists(
    select 1
    from jsonb_array_elements(v_action_contract->'available_actions') item
    where item->>'code'='ADD_EXPENSES'
  ) then
    raise exception 'Pre-approval submission exposed a parallel expense claim: %',
      v_action_contract;
  end if;

  -- Source-authority hours are Candidate-signed evidence only. They never own
  -- Candidate expenses, so a separate expense carrier remains available while
  -- those hours wait for Office/source finalisation.
  v_workflows:=jsonb_build_array(jsonb_build_object(
    'workflow_id',v_workflow,'workflow_kind','CONTRACT_HOURS',
    'state','WORKER_SUBMITTED','generation',2,'detail_action_owner',true,
    'updated_at_utc',now()
  ));
  v_action_contract:=private._candidate_timesheet_action_contract_v1(
    'RECEIVED',v_workflows,
    jsonb_build_object(
      'can_edit_hours',false,
      'can_edit_expenses',true,
      'route_family','IMPORT_AUTHORITATIVE',
      'record_role','IMPORT_HOURS',
      'effective_separation',true
    ),
    v_timesheet,v_week,now()
  );
  if not exists(
    select 1
    from jsonb_array_elements(v_action_contract->'available_actions') item
    where item->>'code'='ADD_EXPENSES'
  ) then
    raise exception 'Source-authority submitted hours lost the separate expense carrier action: %',
      v_action_contract;
  end if;

  -- Once that separate claim exists, the Candidate must continue it rather
  -- than opening a second carrier in parallel.
  v_workflows:=v_workflows||jsonb_build_array(jsonb_build_object(
    'workflow_id',gen_random_uuid(),'workflow_kind','CONTRACT_EXPENSE',
    'state','WORKER_DRAFT','generation',1,'detail_action_owner',false,
    'updated_at_utc',now()-interval '1 second'
  ));
  v_action_contract:=private._candidate_timesheet_action_contract_v1(
    'RECEIVED',v_workflows,
    jsonb_build_object(
      'can_edit_hours',false,
      'can_edit_expenses',true,
      'route_family','IMPORT_AUTHORITATIVE',
      'record_role','IMPORT_HOURS',
      'effective_separation',true
    ),
    v_timesheet,v_week,now()
  );
  if exists(
    select 1
    from jsonb_array_elements(v_action_contract->'available_actions') item
    where item->>'code'='ADD_EXPENSES'
  ) then
    raise exception 'Source-authority hours exposed a second parallel expense carrier: %',
      v_action_contract;
  end if;
end;
$verification$;

-- Rollback-contained first-use proof for sequential Candidate expenses. A
-- finalised manager-approved expense remains awaiting agency authorisation,
-- but it must no longer block the next claim. The newly opened claim must then
-- block a third parallel claim until it is completed or cancelled.



update public.settings_defaults
set candidate_app_feature_flags_json=coalesce(candidate_app_feature_flags_json,'{}'::jsonb)
  || jsonb_build_object(
    'candidate_app_reads',true,
    'candidate_app_writes',true,
    'candidate_record_role_capabilities',true,
    'candidate_expense_atomic_placement',true,
    'candidate_manager_approval',true
  )
where id=1;

do $sequential_expense$
declare
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_anchor_week uuid:=gen_random_uuid();
  v_anchor_timesheet uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_session uuid:=gen_random_uuid();
  v_first_carrier_week uuid;
  v_first_expense_timesheet uuid:=gen_random_uuid();
  v_first_workflow uuid:=gen_random_uuid();
  v_second_carrier_week uuid;
  v_second_workflow uuid:=gen_random_uuid();
  v_third_workflow uuid:=gen_random_uuid();
  v_email text:='sequential-expense-'||gen_random_uuid()::text||'@example.test';
  v_result jsonb;
  v_action jsonb;
begin
  insert into public.clients(id,name)
  values(v_client,'Candidate sequential expense verification client');

  insert into public.candidates(id,email,active,key_norm)
  values(v_candidate,v_email,true,
    'GCK-SEQUENTIAL-'||replace(v_candidate::text,'-',''));

  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,
    candidate_expenses_require_separate_timesheet,
    candidate_paper_submission_enabled,candidate_expense_invoice_email
  ) values(
    gen_random_uuid(),v_client,current_date-1,'ELECTRONIC',true,true,
    'expenses@example.test'
  );

  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,
    pay_method_snapshot,week_ending_weekday_snapshot,default_submission_mode
  ) values(
    v_contract,v_candidate,v_client,current_date-30,current_date+30,
    'PAYE',extract(dow from current_date)::integer,'ELECTRONIC'
  );

  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,contract_id,week_ending_date,sheet_scope,line_type,
    submission_mode,r2_nurse_key,r2_auth_key
  ) values(
    v_anchor_timesheet,
    'SEQUENTIAL_ANCHOR_'||replace(v_anchor_timesheet::text,'-',''),
    'GCK-SEQUENTIAL-'||replace(v_candidate::text,'-',''),
    'SEQUENTIAL HOSPITAL','SEQUENTIAL WARD','NURSE',
    v_contract,current_date,'WEEKLY','HOURS','ELECTRONIC',
    'sequential/anchor/candidate','sequential/anchor/manager'
  );

  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id
  ) values(
    v_anchor_week,v_contract,current_date,0,'OPEN','ELECTRONIC',
    v_anchor_timesheet
  );

  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,
    processing_status
  ) values(
    v_anchor_timesheet,1,v_candidate,v_client,8,'UNPROCESSED'
  );

  insert into public.candidate_app_accounts(
    id,environment,email_normalized,status
  ) values(v_account,'TEST',lower(v_email),'ACTIVE');

  insert into public.candidate_app_sessions(
    id,account_id,environment,selected_candidate_id,status,refresh_token_hash,
    expires_at_utc,absolute_expires_at_utc
  ) values(
    v_session,v_account,'TEST',v_candidate,'ACTIVE',
    decode(repeat('e4',32),'hex'),now()+interval '30 days',
    now()+interval '90 days'
  );

  v_result:=public.expense_carrier_resolve_or_create_atomic_v1(
    v_candidate,'TEST',v_anchor_timesheet,null,
    'sequential-expense:first-carrier',now()
  );
  if v_result->>'placement'<>'CREATE_CARRIER' then
    raise exception 'First sequential expense carrier was not created: %',v_result;
  end if;
  v_first_carrier_week:=(v_result->>'target_contract_week_id')::uuid;

  v_result:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_first_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
      'contract_id',v_contract,'contract_week_id',v_first_carrier_week,
      'anchor_timesheet_id',v_anchor_timesheet,
      'week_ending_date',current_date
    ),
    'sequential-expense:first-workflow',now()
  );
  if coalesce((v_result->>'ok')::boolean,false)=false then
    raise exception 'First sequential expense workflow was not created: %',v_result;
  end if;

  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,contract_id,week_ending_date,sheet_scope,line_type,
    submission_mode,candidate_workflow_id,candidate_workflow_generation,
    candidate_manager_approved_at_utc,r2_nurse_key,r2_auth_key
  ) values(
    v_first_expense_timesheet,
    'SEQUENTIAL_EXPENSE_'||replace(v_first_expense_timesheet::text,'-',''),
    'GCK-SEQUENTIAL-'||replace(v_candidate::text,'-',''),
    'SEQUENTIAL HOSPITAL','SEQUENTIAL WARD','NURSE',
    v_contract,current_date,'WEEKLY','EXPENSES','ELECTRONIC',
    v_first_workflow,2,now(),
    'sequential/expense/candidate','sequential/expense/manager'
  );

  update public.contract_weeks
  set timesheet_id=v_first_expense_timesheet,updated_at=now()
  where id=v_first_carrier_week;

  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,
    expenses_pay_ex_vat,processing_status
  ) values(
    v_first_expense_timesheet,1,v_candidate,v_client,0,12.50,'PENDING_AUTH'
  );

  update public.candidate_submission_workflows
  set state='FINALISED',generation=2,
    target_timesheet_id=v_first_expense_timesheet,
    manager_approved_at_utc=now(),finalised_at_utc=now(),updated_at_utc=now()
  where id=v_first_workflow;

  v_action:=private._candidate_timesheet_primary_action_v1(
    'PENDING_AUTH',
    jsonb_build_array(jsonb_build_object(
      'workflow_id',v_first_workflow,'workflow_kind','CONTRACT_EXPENSE',
      'state','FINALISED','generation',2,'detail_action_owner',true,
      'target_timesheet_id',v_first_expense_timesheet,
      'updated_at_utc',now()
    )),
    jsonb_build_object('can_edit_hours',false,'can_edit_expenses',true),
    v_anchor_timesheet,v_anchor_week
  );
  if v_action->>'code'<>'ADD_EXPENSES' then
    raise exception 'Finalised expense did not offer Add Expenses: %',v_action;
  end if;

  v_result:=public.expense_carrier_resolve_or_create_atomic_v1(
    v_candidate,'TEST',v_anchor_timesheet,null,
    'sequential-expense:second-carrier',now()+interval '1 second'
  );
  if v_result->>'placement'<>'CREATE_CARRIER' then
    raise exception 'Second sequential expense carrier was not created: %',v_result;
  end if;
  v_second_carrier_week:=(v_result->>'target_contract_week_id')::uuid;

  v_result:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_second_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
      'contract_id',v_contract,'contract_week_id',v_second_carrier_week,
      'anchor_timesheet_id',v_anchor_timesheet,
      'week_ending_date',current_date
    ),
    'sequential-expense:second-workflow',now()+interval '1 second'
  );
  if coalesce((v_result->>'ok')::boolean,false)=false
     or not exists(
       select 1
       from public.candidate_submission_workflows
       where id=v_second_workflow and state='WORKER_DRAFT'
     ) then
    raise exception 'Second sequential expense workflow was not opened: %',v_result;
  end if;

  begin
    perform public.candidate_workflow_transition_atomic_v1(
      v_session,'TEST',v_third_workflow,'CREATE',1,
      jsonb_build_object(
        'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
        'contract_id',v_contract,'contract_week_id',v_second_carrier_week,
        'anchor_timesheet_id',v_anchor_timesheet,
        'week_ending_date',current_date
      ),
      'sequential-expense:parallel-workflow',now()+interval '2 seconds'
    );
    raise exception 'Parallel unfinished expense claim was accepted';
  exception
    when sqlstate '55000' then
      if sqlerrm<>'CANDIDATE_EXPENSE_CLAIM_ALREADY_ACTIVE' then
        raise exception 'Wrong parallel-claim failure: %',sqlerrm;
      end if;
  end;

  if exists(
    select 1 from public.candidate_submission_workflows
    where id=v_third_workflow
  ) then
    raise exception 'Rejected parallel expense claim created a workflow';
  end if;
end;
$sequential_expense$;

-- Rollback-contained first-use proof for a later standalone PAPER expense.
-- The worked Timesheet is already manager-approved and signed. It is only the
-- Candidate ownership/display anchor: PAPER preparation must not change it or
-- create the separate expense Timesheet before the returned pack is accepted.



update public.settings_defaults
set candidate_app_feature_flags_json=coalesce(candidate_app_feature_flags_json,'{}'::jsonb)
  ||jsonb_build_object(
    'candidate_app_reads',true,
    'candidate_app_writes',true,
    'candidate_record_role_capabilities',true,
    'candidate_expense_atomic_placement',true,
    'candidate_manager_approval',true,
    'candidate_paper_qr',true
  )
where id=1;

do $targetless_expense_paper$
declare
  v_now timestamptz:='2026-09-06 06:00:00+00';
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_anchor_week uuid:=gen_random_uuid();
  v_anchor_timesheet uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_session uuid:=gen_random_uuid();
  v_carrier_week uuid;
  v_workflow uuid:=gen_random_uuid();
  v_component_one uuid:=gen_random_uuid();
  v_component_two uuid:=gen_random_uuid();
  v_component_three uuid:=gen_random_uuid();
  v_email text:='targetless-paper-'||gen_random_uuid()::text||'@example.test';
  v_submission jsonb;
  v_placement jsonb;
  v_create jsonb;
  v_prepare jsonb;
  v_replay jsonb;
  v_promote jsonb;
  v_old_manifest_sha256 text;
  v_new_manifest_sha256 text;
  v_anchor_before jsonb;
  v_anchor_after jsonb;
  v_financial_before jsonb;
  v_financial_after jsonb;
  v_anchor_week_before jsonb;
  v_anchor_week_after jsonb;
  v_mail_id uuid;
  v_mail_count integer;
begin
  insert into public.clients(id,name)
  values(v_client,'Targetless PAPER expense verification client');

  insert into public.candidates(id,email,display_name,active,key_norm,opt_in_email)
  values(
    v_candidate,v_email,'Targetless PAPER Candidate',true,
    'TARGETLESS-PAPER-'||replace(v_candidate::text,'-',''),true
  );

  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,
    candidate_expenses_require_separate_timesheet,
    candidate_paper_submission_enabled,candidate_expense_invoice_email
  ) values(
    gen_random_uuid(),v_client,current_date-1,'ELECTRONIC',true,true,
    'expenses@example.test'
  );

  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,
    pay_method_snapshot,week_ending_weekday_snapshot,default_submission_mode,
    candidate_paper_submission_enabled_override
  ) values(
    v_contract,v_candidate,v_client,current_date-30,current_date+30,
    'PAYE',extract(dow from current_date)::integer,'ELECTRONIC',true
  );

  -- Deliberately make the worked anchor an already-used, signed, approved row.
  -- The pre-fix PAPER adapter rejected this exact authority state.
  insert into public.timesheets(
    timesheet_id,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,contract_id,week_ending_date,sheet_scope,line_type,
    submission_mode,qr_status,qr_token,qr_generated_at,qr_scanned_at,
    qr_signed_hash,qr_signed_at_utc,candidate_manager_approved_at_utc,
    auth_name,auth_job_title,r2_nurse_key,r2_auth_key
  ) values(
    v_anchor_timesheet,
    'TARGETLESS_PAPER_ANCHOR_'||replace(v_anchor_timesheet::text,'-',''),
    'TARGETLESS-PAPER-'||replace(v_candidate::text,'-',''),
    'TARGETLESS PAPER HOSPITAL','TARGETLESS PAPER WARD','NURSE',
    v_contract,current_date,'WEEKLY','HOURS','ELECTRONIC',
    'USED','used-anchor-token',v_now-interval '2 days',v_now-interval '1 day',
    repeat('a',64),v_now-interval '1 day',v_now-interval '1 day',
    'Approved Manager','Ward Manager',
    'targetless-paper/anchor/candidate','targetless-paper/anchor/manager'
  );

  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,
    submission_mode_snapshot,timesheet_id
  ) values(
    v_anchor_week,v_contract,current_date,0,'SUBMITTED','ELECTRONIC',
    v_anchor_timesheet
  );

  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,total_hours,
    processing_status
  ) values(
    v_anchor_timesheet,1,v_candidate,v_client,8,'PENDING_AUTH'
  );

  insert into public.candidate_app_accounts(
    id,environment,email_normalized,status
  ) values(v_account,'TEST',lower(v_email),'ACTIVE');

  insert into public.candidate_app_sessions(
    id,account_id,environment,selected_candidate_id,status,refresh_token_hash,
    expires_at_utc,absolute_expires_at_utc
  ) values(
    v_session,v_account,'TEST',v_candidate,'ACTIVE',
    extensions.digest(v_session::text,'sha256'),
    v_now+interval '1 day',v_now+interval '7 days'
  );

  v_placement:=public.expense_carrier_resolve_or_create_atomic_v1(
    v_candidate,'TEST',v_anchor_timesheet,null,
    'targetless-paper:carrier',v_now
  );
  if v_placement->>'placement'<>'CREATE_CARRIER'
     or nullif(v_placement->>'target_timesheet_id','') is not null then
    raise exception 'TARGETLESS_PAPER_CARRIER_NOT_RESERVED: %',v_placement;
  end if;
  v_carrier_week:=(v_placement->>'target_contract_week_id')::uuid;

  v_create:=public.candidate_workflow_transition_atomic_v1(
    v_session,'TEST',v_workflow,'CREATE',1,
    jsonb_build_object(
      'workflow_kind','CONTRACT_EXPENSE','scope','WEEKLY','route','ELECTRONIC',
      'contract_id',v_contract,'contract_week_id',v_carrier_week,
      'anchor_timesheet_id',v_anchor_timesheet,
      'week_ending_date',current_date
    ),
    'targetless-paper:create',v_now
  );
  if not coalesce((v_create->>'ok')::boolean,false) then
    raise exception 'TARGETLESS_PAPER_WORKFLOW_NOT_CREATED: %',v_create;
  end if;

  v_submission:=jsonb_build_object(
    'contract_week_id',v_carrier_week,
    'canonical_tsfin_snapshot',jsonb_build_object(
      'candidate_id',v_candidate,'client_id',v_client,
      'total_hours',0,'mileage_units',25,
      'mileage_pay_ex_vat',11.25,'mileage_charge_ex_vat',11.25,
      'expenses_pay_ex_vat',0,'expenses_charge_ex_vat',0,
      'travel_pay_ex_vat',0,'travel_charge_ex_vat',0,
      'accommodation_pay_ex_vat',0,'accommodation_charge_ex_vat',0,
      'other_pay_ex_vat',0,'other_charge_ex_vat',0
    ),
    'timesheet_patch_json',jsonb_build_object('line_type','MILEAGE'),
    'contract_week_patch_json','{}'::jsonb,
    'official_presentation',jsonb_build_object(
      'renderer_contract_version','CANDIDATE_REVIEW_DOCUMENTS_V1',
      'branding',jsonb_build_object(
        'branding_contract_sha256',repeat('b',64)
      )
    )
  );

  update public.candidate_submission_workflows
  set state='READY_FOR_MANAGER_APPROVAL',
      immutable_submission_json=v_submission,
      immutable_submission_sha256=private._candidate_sha256_jsonb_v1(v_submission),
      review_manifest_sha256=extensions.digest('targetless-paper-review','sha256'),
      renderer_contract_version='CANDIDATE_REVIEW_DOCUMENTS_V1',
      updated_at_utc=v_now
  where id=v_workflow;

  insert into public.candidate_submission_components(
    id,workflow_id,workflow_generation,component_no,review_ordinal,timesheet_id,
    component_kind,expense_category,document_role,required,state,storage_key,
    media_type,byte_size,source_content_sha256,immutable_at_utc,
    review_render_state,final_signed_render_state
  ) values
  (
    v_component_one,v_workflow,1,1,1,v_anchor_timesheet,
    'MILEAGE_FORM','MILEAGE','MILEAGE_CLAIM_FORM',true,'IMMUTABLE',
    'targetless-paper/mileage-page-1.jpg','image/jpeg',100,
    decode(repeat('c1',32),'hex'),v_now,'PENDING','PENDING'
  ),
  (
    v_component_two,v_workflow,1,2,2,v_anchor_timesheet,
    'MILEAGE_FORM','MILEAGE','MILEAGE_CLAIM_FORM',true,'IMMUTABLE',
    'targetless-paper/mileage-page-2.jpg','image/jpeg',100,
    decode(repeat('c2',32),'hex'),v_now,'PENDING','PENDING'
  ),
  (
    v_component_three,v_workflow,1,3,3,v_anchor_timesheet,
    'MILEAGE_FORM','MILEAGE','MILEAGE_CLAIM_FORM',true,'IMMUTABLE',
    'targetless-paper/mileage-page-3.jpg','image/jpeg',100,
    decode(repeat('c3',32),'hex'),v_now,'PENDING','PENDING'
  );

  select to_jsonb(anchor_row.*) into v_anchor_before
  from public.timesheets anchor_row
  where anchor_row.timesheet_id=v_anchor_timesheet and anchor_row.is_current;
  select to_jsonb(fin_row.*) into v_financial_before
  from public.timesheets_financials fin_row
  where fin_row.timesheet_id=v_anchor_timesheet and fin_row.is_current;
  select to_jsonb(week_row.*) into v_anchor_week_before
  from public.contract_weeks week_row where week_row.id=v_anchor_week;

  v_prepare:=public.candidate_weekly_paper_prepare_atomic_v1(
    v_session,'TEST',v_workflow,'PAPER_PREPARE',1,'{}'::jsonb,
    'targetless-paper:prepare',v_now+interval '1 second'
  );
  v_replay:=public.candidate_weekly_paper_prepare_atomic_v1(
    v_session,'TEST',v_workflow,'PAPER_PREPARE',1,'{}'::jsonb,
    'targetless-paper:prepare',v_now+interval '2 seconds'
  );

  select to_jsonb(anchor_row.*) into v_anchor_after
  from public.timesheets anchor_row
  where anchor_row.timesheet_id=v_anchor_timesheet and anchor_row.is_current;
  select to_jsonb(fin_row.*) into v_financial_after
  from public.timesheets_financials fin_row
  where fin_row.timesheet_id=v_anchor_timesheet and fin_row.is_current;
  select to_jsonb(week_row.*) into v_anchor_week_after
  from public.contract_weeks week_row where week_row.id=v_anchor_week;

  if v_prepare->>'state' is distinct from 'AWAITING_PAPER_RETURN'
     or v_prepare->>'paper_return_page_count' is distinct from '3'
     or v_replay->>'state' is distinct from 'AWAITING_PAPER_RETURN'
     or (select count(*)
         from jsonb_array_elements((select paper_return_manifest_json
           from public.candidate_submission_workflows where id=v_workflow)->'pages'))<>3
     or exists(
       select 1
       from jsonb_array_elements((select paper_return_manifest_json
         from public.candidate_submission_workflows where id=v_workflow)->'pages') page_row
       where page_row->>'component_kind'<>'MILEAGE_FORM'
          or page_row->>'expense_category'<>'MILEAGE'
     )
     or v_anchor_after is distinct from v_anchor_before
     or v_financial_after is distinct from v_financial_before
     or v_anchor_week_after is distinct from v_anchor_week_before
     or (select target_timesheet_id from public.candidate_submission_workflows
         where id=v_workflow) is not null
     or (select timesheet_id from public.contract_weeks where id=v_carrier_week)
          is not null
     or (select count(*) from public.timesheets
         where contract_id=v_contract and week_ending_date=current_date
           and is_current)<>1 then
    raise exception 'TARGETLESS_PAPER_PREPARE_CHANGED_APPROVED_AUTHORITY: %, %',
      v_prepare,v_replay;
  end if;

  v_mail_id:=(v_prepare#>>'{paper_pack,mail_outbox_id}')::uuid;
  select count(*)::integer into v_mail_count
  from public.mail_outbox mail_row
  where mail_row.id=v_mail_id
    and mail_row.type='TIMESHEET_QR'
    and mail_row.context_kind='timesheets'
    and mail_row.context_id=v_anchor_timesheet
    and mail_row.status='QUEUED'
    and mail_row.attempt_lease_token is null
    and mail_row.payment_scope_json->>'candidate_mail_authority'='CANDIDATE_PAPER_V1'
    and mail_row.payment_scope_json->>'candidate_workflow_id'=v_workflow::text
    and mail_row.payment_scope_json->>'source_authority'='WORKFLOW_IMMUTABLE_SUBMISSION'
    and mail_row.payment_scope_json->>'source_authority_sha256'=
      encode(private._candidate_sha256_jsonb_v1(v_submission),'hex')
    and lower(coalesce(mail_row.payment_scope_json->>'candidate_paper_pack_ready','false'))
      in ('false','f','0','no')
    and lower(coalesce(mail_row.payment_scope_json->>'mail_held_until_pdf_rendered','false'))
      in ('true','t','1','yes')
    and jsonb_typeof(mail_row.attachments)='array'
    and jsonb_array_length(mail_row.attachments)=0;
  if v_mail_count<>1 then
    raise exception 'TARGETLESS_PAPER_HELD_MAIL_AUTHORITY_INVALID: %',v_prepare;
  end if;

  v_old_manifest_sha256:=v_prepare->>'paper_return_manifest_sha256';
  v_promote:=public.candidate_paper_manifest_v2_promote_v1(
    v_session,'TEST',v_workflow,1,v_old_manifest_sha256,
    v_now+interval '3 seconds'
  );
  v_new_manifest_sha256:=v_promote->>'paper_return_manifest_sha256';
  if v_promote->>'manifest_version' is distinct from '2'
     or v_promote->>'qr_contract_version'
          is distinct from 'CANDIDATE_PAPER_PAGE_QR_V2'
     or v_promote->>'paper_return_page_count' is distinct from '3'
     or v_new_manifest_sha256 is null
     or v_new_manifest_sha256=v_old_manifest_sha256
     or (select payment_scope_json->>'paper_return_manifest_sha256'
         from public.mail_outbox where id=v_mail_id)
          is distinct from v_new_manifest_sha256
     or (select payment_scope_json->>'candidate_paper_manifest_version'
         from public.mail_outbox where id=v_mail_id)
          is distinct from '2'
     or (select target_timesheet_id from public.candidate_submission_workflows
         where id=v_workflow) is not null
     or (select timesheet_id from public.contract_weeks where id=v_carrier_week)
          is not null then
    raise exception 'TARGETLESS_PAPER_MANIFEST_PROMOTION_INVALID: %',v_promote;
  end if;

  if pg_catalog.has_function_privilege(
       'anon',
       'public.candidate_targetless_expense_paper_pack_enqueue_v1(text,uuid,integer,text,timestamp with time zone)',
       'EXECUTE'
     )
     or pg_catalog.has_function_privilege(
       'authenticated',
       'public.candidate_targetless_expense_paper_pack_enqueue_v1(text,uuid,integer,text,timestamp with time zone)',
       'EXECUTE'
     )
     or not pg_catalog.has_function_privilege(
       'service_role',
       'public.candidate_targetless_expense_paper_pack_enqueue_v1(text,uuid,integer,text,timestamp with time zone)',
       'EXECUTE'
     ) then
    raise exception 'TARGETLESS_PAPER_HELPER_ACL_INVALID';
  end if;
end;
$targetless_expense_paper$;

-- Verify the route/capability fast path remains private, retains the complete
-- response contract and evaluates representative installed data without
-- recursively querying the full Office Timesheet Summary view.

set local statement_timeout='120s';

do $verification$
declare
  v_signature regprocedure:=to_regprocedure(
    'private._candidate_route_family_v1(uuid,uuid)'
  );
  v_definition text;
  v_config text[];
  v_record record;
  v_route jsonb;
begin
  if v_signature is null then
    raise exception 'Candidate route fast path is missing';
  end if;

  select lower(pg_get_functiondef(v_signature)),p.proconfig
  into v_definition,v_config
  from pg_proc p
  where p.oid=v_signature;

  if position('security definer' in v_definition)=0
     or not coalesce(
       v_config @> array['search_path=pg_catalog, public, private, pg_temp']::text[],
       false
     ) then
    raise exception 'Candidate route fast path security contract drifted';
  end if;

  if position('private._contract_settings_effective_core_v1' in v_definition)=0
     or position('private._candidate_import_authoritative_v1' in v_definition)=0
     or position('public.v_timesheets_summary' in v_definition)>0 then
    raise exception 'Candidate route fast path dependency contract drifted';
  end if;

  if has_function_privilege('anon',v_signature,'EXECUTE')
     or has_function_privilege('authenticated',v_signature,'EXECUTE')
     or has_function_privilege('service_role',v_signature,'EXECUTE') then
    raise exception 'Candidate route fast path escaped its private boundary';
  end if;

  for v_record in
    select cw.id,cw.timesheet_id
    from public.contract_weeks cw
    order by cw.updated_at desc nulls last,cw.id
    limit 500
  loop
    v_route:=private._candidate_route_family_v1(
      v_record.timesheet_id,v_record.id
    );
    if jsonb_typeof(v_route)<>'object'
       or not v_route ?& array[
         'route_family','effective_submission_mode','pending_route_intent',
         'import_authoritative','import_source_family','qr_backed',
         'electronic_paper_fallback_enabled',
         'candidate_hours_submission_allowed','candidate_expenses_allowed',
         'candidate_paper_submission_allowed','candidate_no_work_allowed','policy'
       ]
       or v_route->>'route_family' not in (
         'IMPORT_AUTHORITATIVE','QR','ELECTRONIC','MANUAL_NON_QR'
       )
       or jsonb_typeof(v_route->'policy')<>'object'
       or coalesce(v_route#>>'{policy,policy_fingerprint}','')
          !~ '^[0-9a-f]{64}$'
       or coalesce(v_route#>>'{policy,authority_fingerprint}','')
          !~ '^[0-9a-f]{64}$' then
      raise exception 'Candidate route fast path returned an invalid contract: %',
        v_route;
    end if;
  end loop;
end;
$verification$;

-- Read-only installed-definition and bounded runtime proof for the unified
-- Office Outbox projection. This verifier does not alter application data.

set local statement_timeout = '120s';

do $verification$
declare
  v_signature regprocedure := pg_catalog.to_regprocedure(
    'public.outbox_unified_list_v2(text,text,text,text,text,uuid,boolean,integer,integer,text,text,timestamp with time zone)'
  );
  v_owner text;
  v_security_definer boolean;
  v_volatility "char";
  v_config text[];
  v_public_execute boolean;
  v_definition text;
  v_snapshot_at_utc timestamptz := pg_catalog.clock_timestamp();
  v_payload jsonb;
  v_items jsonb;
  v_legacy_total bigint;
  v_invoice_total bigint;
  v_expected_total bigint;
  v_actual_total bigint;
  v_duplicate_count bigint;
  v_violation_count bigint;
  v_sort_by text;
  v_sort_dir text;
begin
  if v_signature is null then
    raise exception 'UNIFIED_OUTBOX_LIST_V2_FUNCTION_MISSING';
  end if;

  select
    pg_catalog.pg_get_userbyid(proc.proowner),
    proc.prosecdef,
    proc.provolatile,
    proc.proconfig,
    exists (
      select 1
      from pg_catalog.aclexplode(
        coalesce(proc.proacl, pg_catalog.acldefault('f', proc.proowner))
      ) as acl
      where acl.grantee = 0
        and acl.privilege_type = 'EXECUTE'
    ),
    pg_catalog.pg_get_functiondef(proc.oid)
  into strict
    v_owner,
    v_security_definer,
    v_volatility,
    v_config,
    v_public_execute,
    v_definition
  from pg_catalog.pg_proc as proc
  where proc.oid = v_signature;

  if v_owner not in (current_user, 'postgres')
     or not v_security_definer
     or v_volatility <> 's'
     or not (
       'search_path=pg_catalog, public, pg_temp'
       = any(coalesce(v_config, array[]::text[]))
     )
     or v_public_execute
     or (
       pg_catalog.to_regrole('anon') is not null
       and pg_catalog.has_function_privilege('anon', v_signature, 'EXECUTE')
     )
     or (
       pg_catalog.to_regrole('authenticated') is not null
       and pg_catalog.has_function_privilege('authenticated', v_signature, 'EXECUTE')
     )
     or pg_catalog.to_regrole('service_role') is null
     or not pg_catalog.has_function_privilege('service_role', v_signature, 'EXECUTE') then
    raise exception 'UNIFIED_OUTBOX_LIST_V2_SECURITY_INVALID';
  end if;

  if v_definition !~ 'public\.v_outbox_unified'
     or v_definition !~ 'public\.invoice_operations'
     or v_definition !~ 'OPERATION_CONTROL_REQUEST'
     or v_definition !~ 'pg_input_is_valid'
     or v_definition ~* 'SET[[:space:]]+(LOCAL[[:space:]]+)?(statement_timeout|lock_timeout|idle_in_transaction_session_timeout)' then
    raise exception 'UNIFIED_OUTBOX_LIST_V2_DEFINITION_INVALID';
  end if;

  select pg_catalog.count(*)::bigint
  into v_legacy_total
  from public.v_outbox_unified as unified_row
  where unified_row.created_at_utc <= v_snapshot_at_utc;

  select pg_catalog.count(*)::bigint
  into v_invoice_total
  from public.invoice_operations as operation_row
  where operation_row.created_at_utc <= v_snapshot_at_utc
    and operation_row.operation_type <> 'OPERATION_CONTROL_REQUEST';

  v_expected_total := v_legacy_total + v_invoice_total;
  v_payload := public.outbox_unified_list_v2(
    p_limit => 500,
    p_offset => 0,
    p_sort_by => 'created_at_utc',
    p_sort_dir => 'desc',
    p_snapshot_at_utc => v_snapshot_at_utc
  );
  v_items := coalesce(v_payload -> 'items', '[]'::jsonb);
  v_actual_total := coalesce((v_payload ->> 'total_count')::bigint, -1);

  if pg_catalog.jsonb_typeof(v_payload) <> 'object'
     or pg_catalog.jsonb_typeof(v_items) <> 'array'
     or coalesce((v_payload ->> 'ok')::boolean, false) is not true
     or v_actual_total <> v_expected_total
     or coalesce((v_payload #>> '{source_totals,legacy}')::bigint, -1) <> v_legacy_total
     or coalesce((v_payload #>> '{source_totals,invoice}')::bigint, -1) <> v_invoice_total
     or pg_catalog.jsonb_array_length(v_items) <> least(v_expected_total, 500)::integer
     or coalesce((v_payload ->> 'returned_count')::integer, -1)
        <> pg_catalog.jsonb_array_length(v_items)
     or coalesce((v_payload ->> 'has_more')::boolean, false)
        <> (v_expected_total > 500) then
    raise exception 'UNIFIED_OUTBOX_LIST_V2_COUNT_CONTRACT_INVALID';
  end if;

  select pg_catalog.count(*) - pg_catalog.count(distinct (
    upper(coalesce(item ->> 'channel', '')) || '::' || coalesce(item ->> 'outbox_id', '')
  ))
  into v_duplicate_count
  from pg_catalog.jsonb_array_elements(v_items) as item;

  if v_duplicate_count <> 0
     or exists (
       select 1
       from pg_catalog.jsonb_array_elements(v_items) as item
       where coalesce(item ->> 'channel', '') = ''
          or coalesce(item ->> 'outbox_id', '') = ''
          or coalesce(item ->> 'created_at_utc', '') = ''
     ) then
    raise exception 'UNIFIED_OUTBOX_LIST_V2_ROW_IDENTITY_INVALID';
  end if;

  foreach v_sort_by in array array[
    'created_at_utc',
    'scheduled_for_utc',
    'effective_ready_at_utc',
    'status',
    'channel'
  ] loop
    foreach v_sort_dir in array array['asc', 'desc'] loop
      v_payload := public.outbox_unified_list_v2(
        p_limit => 500,
        p_offset => 0,
        p_sort_by => v_sort_by,
        p_sort_dir => v_sort_dir,
        p_snapshot_at_utc => v_snapshot_at_utc
      );

      if coalesce((v_payload ->> 'total_count')::bigint, -1) <> v_expected_total
         or coalesce(v_payload #>> '{sort,sort_by}', '') <> v_sort_by
         or coalesce(v_payload #>> '{sort,sort_dir}', '') <> v_sort_dir then
        raise exception 'UNIFIED_OUTBOX_LIST_V2_SORT_METADATA_INVALID: % %',
          v_sort_by,
          v_sort_dir;
      end if;

      if v_sort_by in ('created_at_utc', 'scheduled_for_utc', 'effective_ready_at_utc') then
        with ordered as (
          select
            ordinality,
            case
              when coalesce(item ->> v_sort_by, '') = '' then null::timestamptz
              else (item ->> v_sort_by)::timestamptz
            end as sort_value
          from pg_catalog.jsonb_array_elements(v_payload -> 'items')
            with ordinality as page_item(item, ordinality)
        ),
        compared as (
          select
            ordinality,
            sort_value,
            pg_catalog.lag(sort_value) over (order by ordinality) as previous_value
          from ordered
        )
        select pg_catalog.count(*)::bigint
        into v_violation_count
        from compared
        where ordinality > 1
          and (
            (previous_value is null and sort_value is not null)
            or (
              previous_value is not null
              and sort_value is not null
              and (
                (v_sort_dir = 'asc' and previous_value > sort_value)
                or (v_sort_dir = 'desc' and previous_value < sort_value)
              )
            )
          );
      else
        with ordered as (
          select
            ordinality,
            nullif(upper(coalesce(item ->> v_sort_by, '')), '') as sort_value
          from pg_catalog.jsonb_array_elements(v_payload -> 'items')
            with ordinality as page_item(item, ordinality)
        ),
        compared as (
          select
            ordinality,
            sort_value,
            pg_catalog.lag(sort_value) over (order by ordinality) as previous_value
          from ordered
        )
        select pg_catalog.count(*)::bigint
        into v_violation_count
        from compared
        where ordinality > 1
          and (
            (previous_value is null and sort_value is not null)
            or (
              previous_value is not null
              and sort_value is not null
              and (
                (v_sort_dir = 'asc' and previous_value > sort_value)
                or (v_sort_dir = 'desc' and previous_value < sort_value)
              )
            )
          );
      end if;

      if v_violation_count <> 0 then
        raise exception 'UNIFIED_OUTBOX_LIST_V2_SORT_ORDER_INVALID: % %',
          v_sort_by,
          v_sort_dir;
      end if;
    end loop;
  end loop;

  begin
    perform public.outbox_unified_list_v2(
      p_sort_by => 'not_a_visible_column',
      p_snapshot_at_utc => v_snapshot_at_utc
    );
    raise exception 'UNIFIED_OUTBOX_LIST_V2_INVALID_SORT_ACCEPTED';
  exception
    when sqlstate '22023' then
      null;
  end;
end;
$verification$;

-- Rollback-contained first-use proof for the Office reject-before-delete rule.
-- A submitted/manager-approved Electronic or QR Candidate workflow prevents
-- deletion.  A target-less pending expense follows the same worked Timesheet
-- across Timesheet ID rotation and is rejected in the same transaction.


update public.settings_defaults
set candidate_app_feature_flags_json=candidate_app_feature_flags_json
  ||'{"candidate_app_reads":true,"candidate_app_writes":true,"candidate_notifications":true}'::jsonb,
    candidate_app_environment='TEST'
where id=1;

do $verification$
declare
  v_actor uuid:=gen_random_uuid();
  v_client uuid:=gen_random_uuid();
  v_candidate uuid:=gen_random_uuid();
  v_contract uuid:=gen_random_uuid();
  v_old_timesheet uuid:=gen_random_uuid();
  v_timesheet uuid:=gen_random_uuid();
  v_week uuid:=gen_random_uuid();
  v_account uuid:=gen_random_uuid();
  v_hours_workflow uuid:=gen_random_uuid();
  v_expense_workflow uuid:=gen_random_uuid();
  v_hours_component uuid:=gen_random_uuid();
  v_approval_request uuid:=gen_random_uuid();
  v_guard jsonb;
  v_preview jsonb;
  v_signature text;
  v_result jsonb;
  v_new_timesheet uuid;
  v_delete_timesheet_ids uuid[];
  v_delete_contract_week_ids uuid[];
  v_delete_nhsp_shift_ids uuid[];
begin
  insert into public.tms_users(id,email,password_hash,role,is_active)
  values(
    v_actor,'candidate-delete-reject-'||v_actor::text||'@example.test',
    'UNUSABLE_VERIFICATION_ONLY','admin',true
  );
  update public.settings_defaults
  set candidate_app_system_actor_user_id=v_actor
  where id=1;

  insert into public.clients(id,name)
  values(v_client,'Candidate Delete Reject Verification Client');
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday
  ) values(
    gen_random_uuid(),v_client,current_date-7,'ELECTRONIC',
    extract(dow from current_date)::integer
  );
  insert into public.candidates(id,email,active)
  values(
    v_candidate,'candidate-delete-reject-'||v_candidate::text||'@example.test',true
  );
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,pay_method_snapshot,
    week_ending_weekday_snapshot,default_submission_mode
  ) values(
    v_contract,v_candidate,v_client,current_date-14,current_date+14,'PAYE',
    extract(dow from current_date)::integer,'ELECTRONIC'
  );

  -- The expense deliberately points to the previous Timesheet ID.  The
  -- current row retains the same stable work identity.
  insert into public.timesheets(
    timesheet_id,contract_id,week_ending_date,line_type,submission_mode,
    sheet_scope,booking_id,occupant_key_norm,hospital_norm,ward_norm,
    job_title_norm,r2_nurse_key,r2_auth_key,version,is_current
  ) values(
    v_old_timesheet,v_contract,current_date,'HOURS','ELECTRONIC','WEEKLY',
    'CANDIDATE-DELETE-REJECT-'||v_contract::text,v_candidate::text,
    'VERIFICATION HOSPITAL','VERIFICATION WARD','VERIFICATION ROLE',
    'verification/old/candidate-signature','verification/old/manager-signature',1,false
  ),(
    v_timesheet,v_contract,current_date,'HOURS','ELECTRONIC','WEEKLY',
    'CANDIDATE-DELETE-REJECT-'||v_contract::text,v_candidate::text,
    'VERIFICATION HOSPITAL','VERIFICATION WARD','VERIFICATION ROLE',
    'verification/current/candidate-signature','verification/current/manager-signature',2,true
  );
  insert into public.contract_weeks(
    id,contract_id,week_ending_date,status,submission_mode_snapshot,timesheet_id
  ) values(v_week,v_contract,current_date,'SUBMITTED','ELECTRONIC',v_timesheet);
  insert into public.timesheets_financials(
    timesheet_id,timesheet_version,candidate_id,client_id,is_current,
    processing_status,total_hours
  ) values(v_timesheet,2,v_candidate,v_client,true,'UNPROCESSED',8);
  insert into public.candidate_app_accounts(
    id,environment,email_normalized,status,notification_preferences_json
  ) values(
    v_account,'TEST','candidate-delete-reject-'||v_candidate::text||'@example.test',
    'ACTIVE','{}'::jsonb
  );
  insert into public.candidate_submission_workflows(
    id,environment,account_id,candidate_id,workflow_kind,scope,route,state,
    generation,contract_id,contract_week_id,anchor_timesheet_id,
    target_timesheet_id,week_ending_date,policy_snapshot_json,input_snapshot_json,
    idempotency_key
  ) values(
    v_hours_workflow,'TEST',v_account,v_candidate,'CONTRACT_HOURS','WEEKLY',
    'ELECTRONIC','MANAGER_APPROVED',1,v_contract,v_week,v_timesheet,
    v_timesheet,current_date,'{}','{}','candidate-delete-reject-hours'
  ),(
    v_expense_workflow,'TEST',v_account,v_candidate,'CONTRACT_EXPENSE','WEEKLY',
    'ELECTRONIC','READY_FOR_MANAGER_APPROVAL',1,v_contract,v_week,v_old_timesheet,
    null,current_date,'{}','{}','candidate-delete-reject-expense'
  );
  insert into public.candidate_submission_components(
    id,workflow_id,workflow_generation,component_no,timesheet_id,
    component_kind,document_role,state,immutable_at_utc,required,review_ordinal,
    review_render_state,final_signed_render_state
  ) values(
    v_hours_component,v_hours_workflow,1,1,v_timesheet,
    'HOURS_TIMESHEET','ELECTRONIC_TIMESHEET_MANAGER_REVIEW','IMMUTABLE',now(),
    true,1,'PENDING','PENDING'
  );
  insert into public.candidate_approval_requests(
    id,workflow_id,workflow_generation,method,state,approved_at_utc,
    review_manifest_sha256,required_component_ids,
    required_component_manifest_json,manager_review_timesheet_component_id
  ) values(
    v_approval_request,v_hours_workflow,1,'PHONE','APPROVED',now(),
    decode(repeat('11',32),'hex'),array[v_hours_component],
    jsonb_build_array(jsonb_build_object('component_id',v_hours_component)),
    v_hours_component
  );

  v_guard:=public.timesheet_candidate_submission_delete_guard_preview_v1(
    'TEST',array[v_timesheet]
  );
  if v_guard->>'contract_version'<>'TIMESHEET_CANDIDATE_SUBMISSION_DELETE_GUARD_V1'
     or coalesce((v_guard->>'candidate_submission_rejection_required')::boolean,false) is not true
     or v_guard->>'candidate_submission_stage'<>'MANAGER_APPROVED'
     or coalesce((v_guard->>'guarded_workflow_count')::integer,0)<>2
     or coalesce((v_guard->>'linked_pending_expense_claim_count')::integer,0)<>1
     or not exists(
       select 1 from jsonb_array_elements(v_guard->'guarded_workflows') item
       where item->>'workflow_id'=v_expense_workflow::text
         and item->>'link_kind'='ROTATED_ANCHOR'
         and coalesce((item->>'linked_pending_expense')::boolean,false)
     ) then
    raise exception 'Candidate delete guard did not include the rotated linked expense: %',v_guard;
  end if;

  -- Weekly parent deletion supplies every Timesheet version in the booking
  -- chain.  The historical version has no Contract Week of its own; it must
  -- inherit the current Electronic route without losing or duplicating either
  -- protected workflow.
  v_guard:=public.timesheet_candidate_submission_delete_guard_preview_v1(
    'TEST',array[v_old_timesheet,v_timesheet]
  );
  if coalesce((v_guard->>'candidate_submission_rejection_required')::boolean,false) is not true
     or v_guard->>'candidate_submission_stage'<>'MANAGER_APPROVED'
     or coalesce((v_guard->>'guarded_workflow_count')::integer,0)<>2
     or coalesce((v_guard->>'linked_pending_expense_claim_count')::integer,0)<>1
     or (select count(*) from jsonb_array_elements(v_guard->'guarded_workflows') item
         where item->>'workflow_id'=v_expense_workflow::text)<>1 then
    raise exception 'Candidate delete guard did not resolve the full rotated Timesheet chain: %',v_guard;
  end if;

  update public.candidate_submission_workflows
  set state='WORKER_DRAFT'
  where id=v_expense_workflow;
  v_guard:=public.timesheet_candidate_submission_delete_guard_preview_v1(
    'TEST',array[v_timesheet]
  );
  if coalesce((v_guard->>'candidate_submission_rejection_required')::boolean,false) is not true
     or coalesce((v_guard->>'guarded_workflow_count')::integer,0)<>1
     or coalesce((v_guard->>'linked_pending_expense_claim_count')::integer,0)<>1 then
    raise exception 'Draft linked expense was omitted from the delete warning: %',v_guard;
  end if;
  update public.candidate_submission_workflows
  set state='READY_FOR_MANAGER_APPROVAL'
  where id=v_expense_workflow;

  begin
    perform public.timesheet_delete_with_candidate_submission_guard_apply_v1(
      'TEST','STANDARD_DELETE',v_timesheet,v_actor,v_timesheet,repeat('0',64),
      array[v_timesheet],array[v_week],array[]::uuid[],array[]::uuid[],
      array[]::uuid[],repeat('0',64),gen_random_uuid(),now()
    );
    raise exception 'Delete unexpectedly passed a Candidate submission';
  exception
    when sqlstate '55000' then
      if sqlerrm not like '%CANDIDATE_SUBMISSION_REJECTION_REQUIRED%' then
        raise;
      end if;
  end;
  if not exists(select 1 from public.timesheets where timesheet_id=v_timesheet)
     or (select state from public.candidate_submission_workflows
         where id=v_expense_workflow)<>'READY_FOR_MANAGER_APPROVAL' then
    raise exception 'Delete refusal changed the Timesheet or pending expense';
  end if;

  v_preview:=private._candidate_office_reject_preview_v1(
    'TEST',v_timesheet,v_actor,now()
  );
  if coalesce((v_preview->>'permitted')::boolean,false) is not true
     or coalesce((v_preview->>'linked_pending_expense_claim_count')::integer,0)<>1
     or jsonb_array_length(v_preview->'target_workflows')<>2 then
    raise exception 'Reject preview did not warn about the linked expense: %',v_preview;
  end if;

  v_signature:=public.timesheet_lifecycle_guard_signature_v1(
    v_timesheet,v_week,false
  )->>'row_signature';
  v_result:=public.candidate_submission_reject_atomic_v1(
    v_actor,'TEST',v_timesheet,v_timesheet,v_signature,
    'Verification rejection with linked pending expense',
    'candidate-delete-reject:reject',now()
  );
  v_new_timesheet:=nullif(v_result->>'timesheet_id','')::uuid;
  if v_new_timesheet is null or v_new_timesheet=v_timesheet
     or coalesce((v_result->>'linked_pending_expense_claim_count')::integer,0)<>1
     or (select state from public.candidate_submission_workflows
         where id=v_hours_workflow)<>'REJECTED'
     or (select state from public.candidate_submission_workflows
         where id=v_expense_workflow)<>'REJECTED'
     or (select rejection_scope from public.candidate_submission_workflows
         where id=v_expense_workflow)<>'COMPLETE_EXPENSE_CLAIM'
     or (select count(*) from public.candidate_notifications
         where workflow_id=v_hours_workflow
           and event_type='OFFICE_REJECTED'
           and template_key='candidate-office-rejected-v1'
           and timesheet_id=v_new_timesheet)<>1
     or (select count(*) from public.candidate_notifications
         where workflow_id=v_expense_workflow
           and event_type='EXPENSE_CLAIM_CANCELLED'
           and preference_category='timesheet_expense_attention'
           and template_key='candidate-expense-claim-cancelled-timesheet-rejection-v1'
           and template_params->>'reason_code'='LINKED_TIMESHEET_REJECTED_FOR_DELETE'
           and deep_link_json->>'type'='workflow'
           and deep_link_json->>'workflow_id'=v_expense_workflow::text
           and timesheet_id is null)<>1 then
    raise exception 'Atomic rejection did not reject both workflows exactly: %',v_result;
  end if;

  v_guard:=public.timesheet_candidate_submission_delete_guard_preview_v1(
    'TEST',array[v_new_timesheet]
  );
  if coalesce((v_guard->>'candidate_submission_rejection_required')::boolean,true)
     or coalesce((v_guard->>'guarded_workflow_count')::integer,-1)<>0 then
    raise exception 'Rejected workflows still prevented deletion: %',v_guard;
  end if;

  -- The rejected replacement must now be genuinely deletable. Candidate
  -- workflow and notification history is retained as a terminal tombstone,
  -- but no retained row may keep a restrictive foreign key to the deleted
  -- Timesheet or Contract Week.
  v_preview:=public.timesheet_weekly_chain_delete_preview(v_new_timesheet,v_actor);
  select coalesce(array_agg(value::uuid order by value),array[]::uuid[])
  into v_delete_timesheet_ids
  from jsonb_array_elements_text(coalesce(v_preview->'timesheet_ids','[]'::jsonb)) ids(value);
  select coalesce(array_agg(value::uuid order by value),array[]::uuid[])
  into v_delete_contract_week_ids
  from jsonb_array_elements_text(coalesce(v_preview->'contract_week_ids','[]'::jsonb)) ids(value);
  select coalesce(array_agg(value::uuid order by value),array[]::uuid[])
  into v_delete_nhsp_shift_ids
  from jsonb_array_elements_text(coalesce(v_preview->'nhsp_shift_ids','[]'::jsonb)) ids(value);
  v_signature:=public.timesheet_lifecycle_guard_signature_v1(
    v_new_timesheet,v_week,false
  )->>'row_signature';
  v_result:=public.timesheet_delete_with_candidate_submission_guard_apply_v1(
    'TEST','WEEKLY_CHAIN_DELETE_PARENT',v_new_timesheet,v_actor,
    v_new_timesheet,v_signature,v_delete_timesheet_ids,
    v_delete_contract_week_ids,v_delete_nhsp_shift_ids,array[]::uuid[],
    array[]::uuid[],
    public.timesheet_pending_expense_delete_preview_v1(
      'TEST',v_delete_timesheet_ids
    )->>'context_sha256',gen_random_uuid(),now()
  );
  if coalesce((v_result->>'apply_performed')::boolean,false) is not true
     or coalesce((v_result->>'decision'),'')<>'PERMANENT_DELETE'
     or coalesce((v_result->>'cancelled_pending_expense_claim_count')::integer,-1)<>0
     or exists(
       select 1 from public.timesheets
       where timesheet_id=any(v_delete_timesheet_ids)
     )
     or exists(
       select 1 from public.contract_weeks
       where id=any(v_delete_contract_week_ids)
     )
     or (select count(*) from public.candidate_submission_workflows
         where id in (v_hours_workflow,v_expense_workflow)
           and state='REJECTED'
           and target_timesheet_id is null
           and anchor_timesheet_id is null
           and contract_week_id is null
           and issue_codes @> '["OFFICE_PERMANENTLY_DELETED_TIMESHEET"]'::jsonb)<>2
     or (select count(*) from public.candidate_submission_components
         where id=v_hours_component
           and workflow_id=v_hours_workflow
           and timesheet_id is null
           and state='REJECTED')<>1
     or (select count(*) from public.candidate_approval_requests
         where id=v_approval_request
           and workflow_id=v_hours_workflow
           and state='SUPERSEDED')<>1
     or (select count(*) from public.candidate_notifications
         where workflow_id=v_hours_workflow
           and event_type='OFFICE_REJECTED'
           and timesheet_id is null
           and deep_link_json->>'type'='workflow'
           and deep_link_json->>'workflow_id'=v_hours_workflow::text)<>1
     or (select count(*) from public.candidate_notifications
         where workflow_id=v_expense_workflow
           and event_type='EXPENSE_CLAIM_CANCELLED'
           and timesheet_id is null
           and deep_link_json->>'type'='workflow'
           and deep_link_json->>'workflow_id'=v_expense_workflow::text)<>1 then
    raise exception 'Rejected replacement did not complete one safe permanent delete: %',v_result;
  end if;
end;
