create or replace function private._candidate_office_service_context_valid_v1(
  p_environment text,p_actor_user_id uuid,p_action text
) returns boolean
language plpgsql
stable
security definer
set search_path=pg_catalog,public,private,pg_temp
as $context$
declare
  v_context jsonb;
begin
