select pg_temp.assert_refused(
  pg_catalog.format(
    'select private.weekly_source_finalisation_lineage_assert_v1(%L,%L)',
    (select row_resolution_id from wp03_root),
    'a3000000-0000-4000-8000-000000000008'),
