do $mode_a_verification$
declare
  v_actor constant uuid:='73000000-0000-4000-8000-000000000001';
  v_clean jsonb;
  v_held jsonb;
  v_unsigned jsonb;
  v_dispatch jsonb;
  v_apply jsonb;
  v_count integer;
  v_state text;
begin
  -- ── 1. Complete exact coverage ───────────────────────────────────────────
  v_clean:=pg_temp.mode_a_scope('CLEAN',time '17:00',true);
  v_dispatch:=public.weekly_source_mode_a_dispatch_atomic_v1(pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor,'publication_id',(v_clean->>'publication_id')::uuid
  ));
  if coalesce((v_dispatch->>'dispatched')::boolean,false) is not true
     or (v_dispatch->>'timesheet_authority_rows')::integer<>2 then
    raise exception 'MODE_A_CLEAN_DISPATCH_DID_NOT_RUN: %',v_dispatch::text;
  end if;
  -- The established owner's comparison, recorded by production code.  Both
  -- days match on times and on equal break duration, so both are EXACT_MATCH
  -- and both carry the source reference.
  select count(*)::integer into v_count
  from public.weekly_timesheet_source_comparisons comparison
  where comparison.projection_publication_id=(v_clean->>'publication_id')::uuid
    and comparison.comparison_state='EXACT_MATCH'
    and comparison.source_reference_number is not null
    and comparison.total_break_minutes_match;
  if v_count<>2 then
    raise exception 'MODE_A_CLEAN_EXACT_MATCH_COMPARISONS_NOT_WRITTEN: %',v_count;
  end if;
  if exists(
    select 1 from public.weekly_timesheet_source_comparisons comparison
    where comparison.projection_publication_id=(v_clean->>'publication_id')::uuid
      and comparison.comparison_state<>'EXACT_MATCH'
  ) then
    raise exception 'MODE_A_CLEAN_UNEXPECTED_COMPARISON_STATE';
  end if;

  v_apply:=public.weekly_source_mode_a_reference_apply_atomic_v1(pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor,'publication_id',(v_clean->>'publication_id')::uuid
  ));
  select operation.state into v_state
  from public.weekly_timesheet_reference_apply_operations operation
  where operation.projection_publication_id=(v_clean->>'publication_id')::uuid;
  if v_state is distinct from 'APPLIED' then
    raise exception 'MODE_A_CLEAN_REFERENCE_APPLY_DID_NOT_APPLY: % / %',v_state,v_apply::text;
  end if;
  -- `25 §9`: "A matching source row writes the reference".  The established
  -- owner writes it; this verifier only proves the result.
  select count(*)::integer into v_count
  from public.nhsp_shifts shift
  where shift.timesheet_id=(v_clean->>'timesheet_id')::uuid
    and nullif(pg_catalog.btrim(coalesce(shift.ref_num,'')),'') is not null;
  if v_count<>2 then
    raise exception 'MODE_A_CLEAN_REFERENCE_NOT_WRITTEN_BY_ESTABLISHED_OWNER: %',v_count;
  end if;
  if not exists(
    select 1 from public.weekly_timesheet_reference_apply_items item
    join public.weekly_timesheet_reference_apply_operations operation
      on operation.id=item.operation_id
    where operation.projection_publication_id=(v_clean->>'publication_id')::uuid
      and item.applied_at_utc is not null
  ) then
    raise exception 'MODE_A_CLEAN_REFERENCE_APPLY_ITEMS_NOT_RECORDED';
  end if;
  -- `25 §9`: complete coverage may auto-authorise only through the existing
  -- setting.  The decision is the established resolver's and is recorded, not
  -- taken here.
  if not exists(
    select 1 from public.weekly_timesheet_reference_apply_operations operation
    where operation.projection_publication_id=(v_clean->>'publication_id')::uuid
      and operation.auto_authorise_requested
      and operation.auto_authorise_applied
  ) then
    raise exception 'MODE_A_CLEAN_AUTO_AUTHORISATION_NOT_RECORDED';
  end if;

  -- ── 2. One mismatched day holds the week ─────────────────────────────────
  v_held:=pg_temp.mode_a_scope('HELD',time '18:00',true);
  v_dispatch:=public.weekly_source_mode_a_dispatch_atomic_v1(pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor,'publication_id',(v_held->>'publication_id')::uuid
  ));
  if coalesce((v_dispatch->>'dispatched')::boolean,false) is not true then
    raise exception 'MODE_A_HELD_DISPATCH_DID_NOT_RUN';
  end if;
  if not exists(
    select 1 from public.weekly_timesheet_source_comparisons comparison
    where comparison.projection_publication_id=(v_held->>'publication_id')::uuid
      and comparison.comparison_state='HOURS_MISMATCH' and comparison.work_date='2026-09-08'
  ) or not exists(
    select 1 from public.weekly_timesheet_source_comparisons comparison
    where comparison.projection_publication_id=(v_held->>'publication_id')::uuid
      and comparison.comparison_state='EXACT_MATCH' and comparison.work_date='2026-09-07'
  ) then
    raise exception 'MODE_A_HELD_COMPARISON_STATES_INVALID';
  end if;
  -- `24 §14`: "a mismatch uses the existing manager correction email journey".
  -- The established catalogue raises its own EMAIL_ISSUE action; Weekly Source
  -- creates no route of its own.
  if not exists(
    select 1 from public.import_review_decisions decision
    join public.hr_imports import_row on import_row.id=decision.import_id
    where import_row.client_id=(v_held->>'client_id')::uuid
      and decision.is_current and decision.action_kind in ('EMAIL_ISSUE','EMAIL_REMINDER')
  ) then
    raise exception 'MODE_A_HELD_MANAGER_CORRECTION_EMAIL_ACTION_ABSENT';
  end if;
  v_apply:=public.weekly_source_mode_a_reference_apply_atomic_v1(pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor,'publication_id',(v_held->>'publication_id')::uuid
  ));
  select operation.state into v_state
  from public.weekly_timesheet_reference_apply_operations operation
  where operation.projection_publication_id=(v_held->>'publication_id')::uuid;
  if v_state is distinct from 'REFUSED' then
    raise exception 'MODE_A_HELD_REFERENCE_APPLY_WAS_NOT_REFUSED: % / %',v_state,v_apply::text;
  end if;
  if exists(
    select 1 from public.nhsp_shifts shift
    where shift.timesheet_id=(v_held->>'timesheet_id')::uuid
      and nullif(pg_catalog.btrim(coalesce(shift.ref_num,'')),'') is not null
  ) then
    raise exception 'MODE_A_HELD_REFERENCE_WAS_WRITTEN_DESPITE_A_MISMATCH';
  end if;

  -- ── 3. Unsigned / unsubmitted evidence does not participate ──────────────
  v_unsigned:=pg_temp.mode_a_scope('UNSIGNED',time '17:00',false);
  v_dispatch:=public.weekly_source_mode_a_dispatch_atomic_v1(pg_catalog.jsonb_build_object(
    'actor_user_id',v_actor,'publication_id',(v_unsigned->>'publication_id')::uuid
  ));
  if exists(
    select 1 from public.weekly_timesheet_source_comparisons comparison
    where comparison.projection_publication_id=(v_unsigned->>'publication_id')::uuid
  ) then
    raise exception 'MODE_A_UNSIGNED_EVIDENCE_PRODUCED_A_COMPARISON';
  end if;
  if not exists(
    select 1 from public.import_review_decisions decision
    join public.hr_imports import_row on import_row.id=decision.import_id
    where import_row.client_id=(v_unsigned->>'client_id')::uuid
      and decision.is_current and decision.blocking
      and decision.summary_json->>'reason_code'='WEEKLY_TIMESHEET_NOT_SUBMITTED'
  ) then
    raise exception 'MODE_A_UNSIGNED_EVIDENCE_WAS_NOT_HELD_BY_THE_ESTABLISHED_OWNER';
  end if;

  -- ── 4. Boundaries ────────────────────────────────────────────────────────
  -- No source-authority artefact anywhere on the Mode A route.
  if (pg_temp.ws_verify_writes('public.weekly_source_billing_movements'::regclass)>0)
     or (pg_temp.ws_verify_writes('public.weekly_source_final_revisions'::regclass)>0)
     or (pg_temp.ws_verify_writes('public.weekly_source_charge_checks'::regclass)>0)
     or (pg_temp.ws_verify_writes('public.weekly_source_row_economic_snapshots'::regclass)>0)
     or (pg_temp.ws_verify_writes('public.weekly_exceptional_pay_target_families'::regclass)>0) then
    raise exception 'MODE_A_CROSSED_INTO_THE_SOURCE_AUTHORITY_ROUTE';
  end if;
  -- The Candidate is never queried, and no secure manager link is created.
  if (pg_temp.ws_verify_writes('public.weekly_discrepancy_incidents'::regclass)>0)
     or (pg_temp.ws_verify_writes('public.weekly_discrepancy_events'::regclass)>0)
     or (pg_temp.ws_verify_writes('public.weekly_message_delivery_failures'::regclass)>0) then
    raise exception 'MODE_A_CREATED_A_CANDIDATE_OR_SECURE_QUERY';
  end if;
  -- Daily is untouched: every import this route created is HR_WEEKLY.
  if exists(
    select 1 from public.hr_imports import_row
    where import_row.parser_version='WEEKLY_SOURCE_MODE_A_BRIDGE_V1'
      -- scoped to fixture rows: hosted TEST holds real rows
      and import_row.client_id in ((v_clean->>'client_id')::uuid,(v_held->>'client_id')::uuid,(v_unsigned->>'client_id')::uuid)
      and (import_row.import_scope is distinct from 'HR_WEEKLY'
        or import_row.source_system<>'HEALTHROSTER'::public.hr_source_enum)
  ) then
    raise exception 'MODE_A_BRIDGE_CREATED_A_NON_WEEKLY_IMPORT';
  end if;
  if exists(
    select 1 from public.import_review_decisions decision
    join public.hr_imports import_row on import_row.id=decision.import_id
    where import_row.parser_version='WEEKLY_SOURCE_MODE_A_BRIDGE_V1'
      and import_row.client_id in ((v_clean->>'client_id')::uuid,(v_held->>'client_id')::uuid,(v_unsigned->>'client_id')::uuid)
      and decision.summary_json->>'source_route' like '%DAILY%'
  ) then
    raise exception 'MODE_A_BRIDGE_PRODUCED_A_DAILY_ACTION';
  end if;
  -- Every Mode A authority resolution defaults `Reference required before pay`
  -- to false and is client-level (`25 §9`).
  if exists(
    select 1 from public.weekly_timesheet_authority_resolutions authority
    where authority.require_reference_to_pay is not false
      and authority.client_id in ((v_clean->>'client_id')::uuid,(v_held->>'client_id')::uuid,(v_unsigned->>'client_id')::uuid)
  ) then
    raise exception 'MODE_A_REFERENCE_REQUIRED_BEFORE_PAY_DID_NOT_DEFAULT_FALSE';
  end if;
end;
$mode_a_verification$;

select pg_catalog.jsonb_build_object(
  'ok',true,'verification','weekly_source_mode_a_dispatch_v1',
  'comparisons',pg_temp.ws_verify_count('public.weekly_timesheet_source_comparisons'::regclass),
  'authority_resolutions',pg_temp.ws_verify_count('public.weekly_timesheet_authority_resolutions'::regclass),
  'reference_apply_operations',(
    select pg_catalog.jsonb_object_agg(state,count)
    from (
      select state,count(*)::integer count
      from public.weekly_timesheet_reference_apply_operations group by state
    ) states
  ),
  'reference_apply_items',pg_temp.ws_verify_count('public.weekly_timesheet_reference_apply_items'::regclass),
  'bridged_imports',(
    select count(*) from public.hr_imports
    where parser_version='WEEKLY_SOURCE_MODE_A_BRIDGE_V1'
  ),
  'financial_writes',pg_temp.ws_verify_count('public.weekly_source_billing_movements'::regclass)
);

-- Rollback-only proof for weekly_source_invoice_issue_validator_v1 (Gate 7, G7-3).
--
-- Every row of P:\annexes\invoice-issue-real-route-matrix.csv (ISS-001..ISS-014)
-- is exercised through the REAL issue entry points:
--
--   * private._invoice_issue_validate_batch - the single hard-blocker gate of
--     the asynchronous route, consumed unchanged by
--     private._invoice_issue_advance_core_v8 and by
--     private._invoice_batch_issue_classification_v2;
--   * private._invoice_batch_issue_classification_v2 - the batch issue
--     classifier the Office list is built from;
--   * public.invoice_issue_one and public.invoice_unissue_one - the real direct
--     owners that perform the transition.
--
-- 25 section 4 Removed, bullet 1: nothing here writes public.invoices.status
-- directly to prove an issue.  Every write is rolled back.



\set weekly_source_verification_outer_transaction true
\set weekly_source_ordinary_verification_outer_transaction true
\set weekly_source_verification_correction_presentation 'FULL_REVERSAL_REPLACEMENT'
\set weekly_source_verification_expense_vat_enabled false

-- scoped to fixture rows: hosted TEST holds real manifests, invoices and bindings
-- Include only inside a rollback-contained verifier, before fixture INSERTs.
-- Records keys and counters for this transaction, never reads business history.
-- Any UPDATE/DELETE of a row not inserted by this fixture is rejected outright.
create temporary table if not exists ws_verify_relations(
  rel oid primary key, key_expression text not null,
  inserts bigint not null default 0, updates bigint not null default 0,
  deletes bigint not null default 0
) on commit drop;
create temporary table if not exists ws_verify_keys(
  rel oid not null, key jsonb not null, primary key(rel,key)
) on commit drop;

create or replace function pg_temp.ws_verify_capture() returns trigger language plpgsql
set search_path='' as $f$
declare expr text; old_key jsonb; new_key jsonb;
begin
  if tg_op='TRUNCATE' then raise exception 'WS_VERIFY_TRUNCATE_FORBIDDEN'; end if;
  select key_expression into strict expr from pg_temp.ws_verify_relations where rel=tg_relid;
  if tg_op in ('UPDATE','DELETE') then
    execute 'select pg_catalog.jsonb_build_array('||expr||')' into old_key using old;
    if not exists(select 1 from pg_temp.ws_verify_keys where rel=tg_relid and key=old_key) then
      raise exception 'WS_VERIFY_EXISTING_ROW_MUTATION: %.% %',tg_table_schema,tg_table_name,tg_op;
    end if;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    execute 'select pg_catalog.jsonb_build_array('||expr||')' into new_key using new;
    if pg_catalog.octet_length(new_key::text)>2048 then raise exception 'WS_VERIFY_KEY_TOO_LARGE'; end if;
  end if;
  if tg_op in ('UPDATE','DELETE') then
    delete from pg_temp.ws_verify_keys where rel=tg_relid and key=old_key;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    insert into pg_temp.ws_verify_keys values(tg_relid,new_key);
  end if;
  update pg_temp.ws_verify_relations set
    inserts=inserts+case when tg_op='INSERT' then 1 else 0 end,
    updates=updates+case when tg_op='UPDATE' then 1 else 0 end,
    deletes=deletes+case when tg_op='DELETE' then 1 else 0 end
  where rel=tg_relid;
  if (select inserts+updates+deletes from pg_temp.ws_verify_relations where rel=tg_relid)>100000 then
    raise exception 'WS_VERIFY_FIXTURE_WORK_LIMIT';
  end if;
  return null;
end $f$;

create or replace function pg_temp.ws_verify_watch(p_rel regclass) returns void language plpgsql
set search_path='' as $f$
declare expr text; target text;
begin
  if exists(select 1 from pg_temp.ws_verify_relations where rel=p_rel) then return; end if;
  select pg_catalog.string_agg(pg_catalog.format('($1).%I',a.attname),',' order by k.ord)
  into expr from pg_catalog.pg_index i
  cross join lateral pg_catalog.unnest(i.indkey) with ordinality k(attnum,ord)
  join pg_catalog.pg_attribute a on a.attrelid=i.indrelid and a.attnum=k.attnum
  where i.indrelid=p_rel and i.indisprimary and k.ord<=i.indnkeyatts;
  if expr is null then raise exception 'WS_VERIFY_PRIMARY_KEY_REQUIRED: %',p_rel; end if;
  select pg_catalog.format('%I.%I',n.nspname,c.relname) into strict target
  from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
  where c.oid=p_rel;
  insert into pg_temp.ws_verify_relations(rel,key_expression) values(p_rel,expr);
  execute pg_catalog.format('create trigger ws_verify_capture after insert or update or delete on %s for each row execute function pg_temp.ws_verify_capture()',target);
  execute pg_catalog.format('create trigger ws_verify_no_truncate before truncate on %s for each statement execute function pg_temp.ws_verify_capture()',target);
end $f$;

create or replace function pg_temp.ws_verify_count(p_rel regclass) returns bigint language plpgsql
set search_path='' as $f$
declare n bigint;
begin
  select inserts-deletes into strict n from pg_temp.ws_verify_relations where rel=p_rel;
  return n;
end $f$;
create or replace function pg_temp.ws_verify_writes(p_rel regclass) returns bigint language plpgsql
set search_path='' as $f$
declare n bigint;
begin
  select inserts+updates+deletes into strict n from pg_temp.ws_verify_relations where rel=p_rel;
  return n;
end $f$;

