-- Rollback-only PostgreSQL 17 proof for the Plan 6.2 Gate 11 audit, export and
-- notification owners (`17092026_1200_weekly_source_audit_and_export_v1.sql`).
--
-- Covers, in order:
--   1. structure, ownership, security, volatility and privileges of every
--      function and every trigger this package adds;
--   2. the static money and evidence contract: the export owner performs no
--      currency-to-hours arithmetic, never reads the timesheet_pay_state
--      last-settled cache, and reaches paid hours only through the Gate 9
--      settlement-allocation reader; no safety decision rests on LIMIT or sort
--      order;
--   3. the Candidate payload scanner over COMPLETE serialised payloads, with
--      positive and negative controls at depth and a nested-key control;
--   4. first authorisation driven through the REAL owner
--      `public.weekly_source_first_authorise_v1`, its audit event, its plain
--      English, and the chronology that renders it;
--   5. withdrawal through the REAL owner, proving this package adds no second
--      `WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWN` row (UNA-001 stays true)
--      and that the chronology renders WP-07's row in plain English;
--   6. head publication IMMEDIATE and DEFERRED, supersession, and the four
--      pending-bundle states, each from a database state that genuinely
--      produces it;
--   7. the export differentials: submitted, source, approved and paid kept
--      apart; a rotated family whose physical Timesheet changed; an
--      `UNAVAILABLE` settlement; and an ordinary Timesheet whose export member
--      is byte-identically empty;
--   8. the Candidate hours-only push through the existing boundary: the whole
--      serialised payload carries no forbidden field and no forbidden word, a
--      forbidden payload fails closed and pushes nothing, the same approved
--      hours never push twice, and a push failure never rolls back a
--      publication;
--   9. the notification routes: the grouped manager email and its secure
--      response exist only on the source-authority route, and Office Weekly
--      source notices never enter the Banking alert store.
--
-- Prerequisites: the Weekly Source schema migration, the ACL contract, the
-- rotation authority (WP-03), the freeze census (WP-08a), first authorisation
-- (WP-07), pending release (WP-08b), the settlement allocation reader and the
-- Candidate view producer (WP-11a), and this package's repeatable.
--
-- Nothing here defines, wraps or re-creates a Banking Pay, Draft, execution,
-- cancellation, settlement, provider, recovery or remittance owner. No message
-- of any kind leaves the database: the Candidate push boundary writes an
-- in-database `public.candidate_notifications` row with `push_state='PENDING'`
-- and the delivery worker that would claim it is never run. Everything written
-- is rolled back.


\pset pager off


-- Verification only: one transaction snapshot for complete-row comparisons.
-- Otherwise an unrelated committed background update can be mistaken for a
-- write by this rollback fixture. Every field and every original guard remains
-- included; this transaction still sees ALL of its own writes. A write conflict
-- still fails closed. This changes no application isolation or Banking policy.
-- Included callers must establish their outer isolation BEFORE their first read.
do $source_verifier_snapshot_guard$
begin
  if pg_catalog.current_setting('transaction_isolation')<>'repeatable read' then
    raise exception using errcode='P0001',
      message='SOURCE_VERIFIER_TRANSACTION_SNAPSHOT_REQUIRED';
  end if;
end $source_verifier_snapshot_guard$;

-- Rollback-contained verification support only. Never install as a repeatable.
-- Existing rows are not an empty-database precondition and may not be mutated.
-- Use the established key/counter capture, not a replacement Banking owner.
-- Include only inside a rollback-contained verifier, before fixture INSERTs.
-- Records keys and counters for this transaction, never reads business history.
-- Any UPDATE/DELETE of a row not inserted by this fixture is rejected outright.
create temporary table if not exists ws_verify_relations(
  rel oid primary key, key_expression text not null,
  inserts bigint not null default 0, updates bigint not null default 0,
  deletes bigint not null default 0
) on commit drop;
create temporary table if not exists ws_verify_keys(
  rel oid not null, key jsonb not null, primary key(rel,key)
) on commit drop;

create or replace function pg_temp.ws_verify_capture() returns trigger language plpgsql
set search_path='' as $f$
declare expr text; old_key jsonb; new_key jsonb;
begin
  if tg_op='TRUNCATE' then raise exception 'WS_VERIFY_TRUNCATE_FORBIDDEN'; end if;
  select key_expression into strict expr from pg_temp.ws_verify_relations where rel=tg_relid;
  if tg_op in ('UPDATE','DELETE') then
    execute 'select pg_catalog.jsonb_build_array('||expr||')' into old_key using old;
    if not exists(select 1 from pg_temp.ws_verify_keys where rel=tg_relid and key=old_key) then
      raise exception 'WS_VERIFY_EXISTING_ROW_MUTATION: %.% %',tg_table_schema,tg_table_name,tg_op;
    end if;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    execute 'select pg_catalog.jsonb_build_array('||expr||')' into new_key using new;
    if pg_catalog.octet_length(new_key::text)>2048 then raise exception 'WS_VERIFY_KEY_TOO_LARGE'; end if;
  end if;
  if tg_op in ('UPDATE','DELETE') then
    delete from pg_temp.ws_verify_keys where rel=tg_relid and key=old_key;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    insert into pg_temp.ws_verify_keys values(tg_relid,new_key);
  end if;
  update pg_temp.ws_verify_relations set
    inserts=inserts+case when tg_op='INSERT' then 1 else 0 end,
    updates=updates+case when tg_op='UPDATE' then 1 else 0 end,
    deletes=deletes+case when tg_op='DELETE' then 1 else 0 end
  where rel=tg_relid;
  if (select inserts+updates+deletes from pg_temp.ws_verify_relations where rel=tg_relid)>100000 then
    raise exception 'WS_VERIFY_FIXTURE_WORK_LIMIT';
  end if;
  return null;
end $f$;

create or replace function pg_temp.ws_verify_watch(p_rel regclass) returns void language plpgsql
set search_path='' as $f$
declare expr text; target text;
begin
  if exists(select 1 from pg_temp.ws_verify_relations where rel=p_rel) then return; end if;
  select pg_catalog.string_agg(pg_catalog.format('($1).%I',a.attname),',' order by k.ord)
  into expr from pg_catalog.pg_index i
  cross join lateral pg_catalog.unnest(i.indkey) with ordinality k(attnum,ord)
  join pg_catalog.pg_attribute a on a.attrelid=i.indrelid and a.attnum=k.attnum
  where i.indrelid=p_rel and i.indisprimary and k.ord<=i.indnkeyatts;
  if expr is null then raise exception 'WS_VERIFY_PRIMARY_KEY_REQUIRED: %',p_rel; end if;
  select pg_catalog.format('%I.%I',n.nspname,c.relname) into strict target
  from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
  where c.oid=p_rel;
  insert into pg_temp.ws_verify_relations(rel,key_expression) values(p_rel,expr);
  execute pg_catalog.format('create trigger ws_verify_capture after insert or update or delete on %s for each row execute function pg_temp.ws_verify_capture()',target);
  execute pg_catalog.format('create trigger ws_verify_no_truncate before truncate on %s for each statement execute function pg_temp.ws_verify_capture()',target);
end $f$;

create or replace function pg_temp.ws_verify_count(p_rel regclass) returns bigint language plpgsql
set search_path='' as $f$
declare n bigint;
begin
  select inserts-deletes into strict n from pg_temp.ws_verify_relations where rel=p_rel;
  return n;
end $f$;
create or replace function pg_temp.ws_verify_writes(p_rel regclass) returns bigint language plpgsql
set search_path='' as $f$
declare n bigint;
begin
  select inserts+updates+deletes into strict n from pg_temp.ws_verify_relations where rel=p_rel;
  return n;
end $f$;

