-- Hash each complete row first; aggregate only fixed-size digests, not customer
-- payloads. Include count and multiplicity. No row contents leave this session.
create or replace function pg_temp.ws_verify_workbench_fingerprint()
returns jsonb language plpgsql set search_path='' as $f$
declare v_relation text; v_result jsonb := '{}'::jsonb; v_fingerprint jsonb;
begin
  foreach v_relation in array array[
    'public.banking_pay_workbench_candidate_delta_projection_runs',
    'public.banking_pay_workbench_candidate_line_work',
    'public.banking_pay_workbench_candidate_source_lines',
    'public.banking_pay_workbench_case_resolution_carry_registrations',
    'public.banking_pay_workbench_preview_rows',
    'public.banking_pay_workbench_selection_carry_registrations',
    'public.banking_pay_workbench_session_candidate_state',
    'public.banking_pay_workbench_session_case_resolutions',
    'public.banking_pay_workbench_session_overrides',
    'public.banking_pay_workbench_session_scope',
    'public.banking_pay_workbench_sessions'
  ] loop
    execute pg_catalog.format($q$
      select pg_catalog.jsonb_build_object('count',pg_catalog.count(*),'sha256',
        pg_catalog.encode(extensions.digest(coalesce(
          pg_catalog.string_agg(row_digest,'' order by row_digest),''),'sha256'),'hex'))
      from (select pg_catalog.encode(extensions.digest(
        pg_catalog.to_jsonb(x)::text,'sha256'),'hex') as row_digest from %s x) rows
    $q$,v_relation) into v_fingerprint;
    v_result := v_result || pg_catalog.jsonb_build_object(v_relation,v_fingerprint);
  end loop;
  return v_result;
end $f$;

create or replace function pg_temp.ws_verify_other_jobs_fingerprint(p_owned uuid[])
returns jsonb language sql set search_path='' as $f$
  select pg_catalog.jsonb_build_object('count',pg_catalog.count(*),'sha256',
    pg_catalog.encode(extensions.digest(coalesce(
      pg_catalog.string_agg(row_digest,'' order by row_digest),''),'sha256'),'hex'))
  from (select pg_catalog.encode(extensions.digest(
    pg_catalog.to_jsonb(j)::text,'sha256'),'hex') as row_digest
    from public.banking_pay_workbench_jobs j
    where not(j.id=any(p_owned))) rows;
$f$;

-- Rollback-contained verification support only; never a runtime definition.
-- Compare complete rows, including multiplicity, without constructing one JSON
-- array containing the populated database's complete financial payloads. That
-- array can exceed PostgreSQL's 268435455-byte JSONB element limit. Aggregate
-- only fixed-size full-row SHA256 digests; no data is omitted or returned.
create or replace function pg_temp.ws_verify_full_relation_fingerprint(p_relation regclass)
returns text language plpgsql set search_path='' as $fingerprint$
declare v_fingerprint text;
begin
  execute pg_catalog.format($query$
    select pg_catalog.jsonb_build_object('count',pg_catalog.count(*),'sha256',
      pg_catalog.encode(extensions.digest(coalesce(
        pg_catalog.string_agg(row_digest,'' order by row_digest),''),'sha256'),'hex'))::text
    from (select pg_catalog.encode(extensions.digest(
      pg_catalog.to_jsonb(row_value)::text,'sha256'),'hex') as row_digest
      from %s row_value) complete_rows
  $query$,p_relation) into v_fingerprint;
  return v_fingerprint;
end;
$fingerprint$;


-- Rollback-only failure diagnostics. No runtime owner or financial policy.
-- Retain only primary-key, complete-row and per-field SHA256 digests. Never
-- retain/return customer values, identifiers, monetary values or payloads.
create temporary table ws_verify_financial_drift_rows(
  phase text not null check(phase in ('BEFORE','AFTER')),
  relation_oid oid not null,
  key_sha256 text not null,
  row_sha256 text not null,
  field_sha256 jsonb not null,
  primary key(phase,relation_oid,key_sha256)
) on commit drop;

create function pg_temp.ws_verify_financial_drift_capture(p_relation regclass,p_phase text)
returns text language plpgsql set search_path='' as $capture$
declare v_keys text;v_fingerprint text;
begin
  if p_phase not in ('BEFORE','AFTER') or p_phase is null then
    raise exception 'WS_VERIFY_DRIFT_PHASE_INVALID';
  end if;
  select pg_catalog.string_agg(pg_catalog.format('j->%L',a.attname),',' order by k.ord)
    into v_keys
    from pg_catalog.pg_index i
    cross join lateral pg_catalog.unnest(i.indkey) with ordinality k(attnum,ord)
    join pg_catalog.pg_attribute a on a.attrelid=i.indrelid and a.attnum=k.attnum
   where i.indrelid=p_relation and i.indisprimary and k.ord<=i.indnkeyatts;
  if v_keys is null then raise exception 'WS_VERIFY_DRIFT_PRIMARY_KEY_REQUIRED'; end if;
  delete from pg_temp.ws_verify_financial_drift_rows
   where relation_oid=p_relation::oid and phase=p_phase;
  execute pg_catalog.format($query$
    insert into pg_temp.ws_verify_financial_drift_rows
      (phase,relation_oid,key_sha256,row_sha256,field_sha256)
    select $1,$2,
      pg_catalog.encode(extensions.digest(pg_catalog.jsonb_build_array(%s)::text,'sha256'),'hex'),
      pg_catalog.encode(extensions.digest(j::text,'sha256'),'hex'),
      (select pg_catalog.jsonb_object_agg(f.key,
        pg_catalog.encode(extensions.digest(f.value::text,'sha256'),'hex'))
         from pg_catalog.jsonb_each(j) f)
    from (select pg_catalog.to_jsonb(t) as j from %s t) complete_rows
  $query$,v_keys,p_relation) using p_phase,p_relation::oid;
  -- Identical count/multiplicity/full-row digest algorithm to the original
  -- fingerprint guard. This additional capture does not replace that guard.
  select pg_catalog.jsonb_build_object('count',pg_catalog.count(*),'sha256',
    pg_catalog.encode(extensions.digest(coalesce(
      pg_catalog.string_agg(row_sha256,'' order by row_sha256),''),'sha256'),'hex'))::text
    into v_fingerprint
    from pg_temp.ws_verify_financial_drift_rows
   where relation_oid=p_relation::oid and phase=p_phase;
  return v_fingerprint;
end $capture$;

create function pg_temp.ws_verify_financial_drift_detail(p_before jsonb,p_after jsonb,p_worker_call integer)
returns text language plpgsql set search_path='' as $detail$
declare v_relation text;v_oid oid;v_before_hash text;v_after_hash text;
  v_added bigint;v_removed bigint;v_changed bigint;v_fields jsonb;
  v_relations jsonb:='[]'::jsonb;
begin
  for v_relation in select k from pg_catalog.jsonb_object_keys(p_before||p_after) k
    where p_before->k is distinct from p_after->k order by k
  loop
    v_oid:=v_relation::regclass::oid;
    v_after_hash:=pg_temp.ws_verify_financial_drift_capture(v_relation::regclass,'AFTER');
    select pg_catalog.jsonb_build_object('count',pg_catalog.count(*),'sha256',
      pg_catalog.encode(extensions.digest(coalesce(
        pg_catalog.string_agg(row_sha256,'' order by row_sha256),''),'sha256'),'hex'))::text
      into v_before_hash
      from pg_temp.ws_verify_financial_drift_rows
     where relation_oid=v_oid and phase='BEFORE';
    select pg_catalog.count(*) filter(where b.key_sha256 is null),
           pg_catalog.count(*) filter(where a.key_sha256 is null),
           pg_catalog.count(*) filter(where b.key_sha256 is not null
             and a.key_sha256 is not null and b.row_sha256 is distinct from a.row_sha256)
      into v_added,v_removed,v_changed
      from (select * from pg_temp.ws_verify_financial_drift_rows
        where relation_oid=v_oid and phase='BEFORE') b
      full join (select * from pg_temp.ws_verify_financial_drift_rows
        where relation_oid=v_oid and phase='AFTER') a using(key_sha256);
    select coalesce(pg_catalog.jsonb_object_agg(changed.field,changed.rows),'{}'::jsonb)
      into v_fields from (
      select f.key as field,pg_catalog.count(*) as rows
        from pg_temp.ws_verify_financial_drift_rows b
        join pg_temp.ws_verify_financial_drift_rows a
          on a.phase='AFTER' and a.relation_oid=b.relation_oid and a.key_sha256=b.key_sha256
        cross join lateral pg_catalog.jsonb_each(b.field_sha256) f
       where b.phase='BEFORE' and b.relation_oid=v_oid
         and f.value is distinct from a.field_sha256->f.key
       group by f.key
    ) changed;
    v_relations:=v_relations||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'relation',v_relation,'added_rows',v_added,'removed_rows',v_removed,
      'changed_rows',v_changed,'changed_fields_row_counts',v_fields,
      'before_matches_guard',v_before_hash is not distinct from p_before->>v_relation,
      'after_matches_guard',v_after_hash is not distinct from p_after->>v_relation));
  end loop;
  return pg_catalog.jsonb_build_object('worker_call',p_worker_call,'relations',v_relations)::text;
end $detail$;

-- Rollback-only first-use controls for privacy-safe financial failure details.
create temporary table ws_verify_drift_control(id integer primary key, label text, amount numeric, payload jsonb) on commit drop;
insert into ws_verify_drift_control values(1,'SENSITIVE_BASELINE',12.5,'{"private":"DO_NOT_RETURN"}'),(2,null,0,null);
do $control$
declare b jsonb;a jsonb;d jsonb;r jsonb;name text:=('pg_temp.ws_verify_drift_control'::regclass)::text;
begin
 b:=jsonb_build_object(name,pg_temp.ws_verify_full_relation_fingerprint('pg_temp.ws_verify_drift_control'::regclass));
 if pg_temp.ws_verify_financial_drift_capture('pg_temp.ws_verify_drift_control'::regclass,'BEFORE') is distinct from b->>name then
   raise exception 'CONTROL_COMPLETE_ROW_HASH_MISMATCH';
 end if;
 d:=pg_temp.ws_verify_financial_drift_detail(b,b,1)::jsonb;
 if d->'relations' is distinct from '[]'::jsonb then raise exception 'CONTROL_UNCHANGED_NOT_EMPTY';end if;
 update pg_temp.ws_verify_drift_control set amount=13.5,label='SENSITIVE_NEW' where id=1;
 delete from pg_temp.ws_verify_drift_control where id=2;
 insert into pg_temp.ws_verify_drift_control values(3,'SENSITIVE_INSERT',25,'{"private":"NEW_PRIVATE"}');
 a:=jsonb_build_object(name,pg_temp.ws_verify_full_relation_fingerprint('pg_temp.ws_verify_drift_control'::regclass));
 d:=pg_temp.ws_verify_financial_drift_detail(b,a,2)::jsonb;r:=d->'relations'->0;
 if jsonb_array_length(d->'relations')<>1 or d->>'worker_call'<>'2'
    or r->>'added_rows'<>'1' or r->>'removed_rows'<>'1' or r->>'changed_rows'<>'1'
    or r->'changed_fields_row_counts' is distinct from '{"amount":1,"label":1}'::jsonb
    or r->>'before_matches_guard'<>'true' or r->>'after_matches_guard'<>'true'
    or d::text like '%SENSITIVE%' or d::text like '%PRIVATE%' or d::text like '%13.5%' then
   raise exception 'CONTROL_DETAIL_COUNTS_OR_PRIVACY_FAILED';
 end if;
 -- A changed read-back is flagged, never misrepresented as the original guard.
 update pg_temp.ws_verify_drift_control set payload='{"private":"SECOND_PRIVATE"}' where id=1;
 d:=pg_temp.ws_verify_financial_drift_detail(b,a,2)::jsonb;
 if d->'relations'->0->>'after_matches_guard'<>'false' then
   raise exception 'CONTROL_LATER_SNAPSHOT_MISMATCH_NOT_REPORTED';
 end if;
 -- Composite keys, NULL and row-associated value swaps all remain visible.
 create temporary table ws_verify_drift_composite(a int,b int,val text,primary key(a,b)) on commit drop;
 insert into pg_temp.ws_verify_drift_composite values(1,1,null),(1,2,'');
 name:=('pg_temp.ws_verify_drift_composite'::regclass)::text;
 b:=jsonb_build_object(name,pg_temp.ws_verify_financial_drift_capture('pg_temp.ws_verify_drift_composite'::regclass,'BEFORE'));
 update pg_temp.ws_verify_drift_composite t set val=case t.b when 1 then '' else null end;
 a:=jsonb_build_object(name,pg_temp.ws_verify_full_relation_fingerprint('pg_temp.ws_verify_drift_composite'::regclass));
 d:=pg_temp.ws_verify_financial_drift_detail(b,a,3)::jsonb;r:=d->'relations'->0;
 if r->>'changed_rows'<>'2' or r->'changed_fields_row_counts' is distinct from '{"val":2}'::jsonb
    or r->>'added_rows'<>'0' or r->>'removed_rows'<>'0' then
   raise exception 'CONTROL_COMPOSITE_NULL_SWAP_NOT_EXACT';
 end if;
end $control$;

-- Transaction-local fixture accounting; existing customer rows are not an empty-table precondition.
-- Include only inside a rollback-contained verifier, before fixture INSERTs.
-- Records keys and counters for this transaction, never reads business history.
-- Any UPDATE/DELETE of a row not inserted by this fixture is rejected outright.
create temporary table if not exists ws_verify_relations(
  rel oid primary key, key_expression text not null,
  inserts bigint not null default 0, updates bigint not null default 0,
  deletes bigint not null default 0
) on commit drop;
create temporary table if not exists ws_verify_keys(
  rel oid not null, key jsonb not null, primary key(rel,key)
) on commit drop;

create or replace function pg_temp.ws_verify_capture() returns trigger language plpgsql
set search_path='' as $f$
declare expr text; old_key jsonb; new_key jsonb;
begin
  if tg_op='TRUNCATE' then raise exception 'WS_VERIFY_TRUNCATE_FORBIDDEN'; end if;
  select key_expression into strict expr from pg_temp.ws_verify_relations where rel=tg_relid;
  if tg_op in ('UPDATE','DELETE') then
    execute 'select pg_catalog.jsonb_build_array('||expr||')' into old_key using old;
    if not exists(select 1 from pg_temp.ws_verify_keys where rel=tg_relid and key=old_key) then
      raise exception 'WS_VERIFY_EXISTING_ROW_MUTATION: %.% %',tg_table_schema,tg_table_name,tg_op;
    end if;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    execute 'select pg_catalog.jsonb_build_array('||expr||')' into new_key using new;
    if pg_catalog.octet_length(new_key::text)>2048 then raise exception 'WS_VERIFY_KEY_TOO_LARGE'; end if;
  end if;
  if tg_op in ('UPDATE','DELETE') then
    delete from pg_temp.ws_verify_keys where rel=tg_relid and key=old_key;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    insert into pg_temp.ws_verify_keys values(tg_relid,new_key);
  end if;
  update pg_temp.ws_verify_relations set
    inserts=inserts+case when tg_op='INSERT' then 1 else 0 end,
    updates=updates+case when tg_op='UPDATE' then 1 else 0 end,
    deletes=deletes+case when tg_op='DELETE' then 1 else 0 end
  where rel=tg_relid;
  if (select inserts+updates+deletes from pg_temp.ws_verify_relations where rel=tg_relid)>100000 then
    raise exception 'WS_VERIFY_FIXTURE_WORK_LIMIT';
  end if;
  return null;
end $f$;

create or replace function pg_temp.ws_verify_watch(p_rel regclass) returns void language plpgsql
set search_path='' as $f$
declare expr text; target text;
begin
  if exists(select 1 from pg_temp.ws_verify_relations where rel=p_rel) then return; end if;
  select pg_catalog.string_agg(pg_catalog.format('($1).%I',a.attname),',' order by k.ord)
  into expr from pg_catalog.pg_index i
  cross join lateral pg_catalog.unnest(i.indkey) with ordinality k(attnum,ord)
  join pg_catalog.pg_attribute a on a.attrelid=i.indrelid and a.attnum=k.attnum
  where i.indrelid=p_rel and i.indisprimary and k.ord<=i.indnkeyatts;
  if expr is null then raise exception 'WS_VERIFY_PRIMARY_KEY_REQUIRED: %',p_rel; end if;
  select pg_catalog.format('%I.%I',n.nspname,c.relname) into strict target
  from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
  where c.oid=p_rel;
  insert into pg_temp.ws_verify_relations(rel,key_expression) values(p_rel,expr);
  execute pg_catalog.format('create trigger ws_verify_capture after insert or update or delete on %s for each row execute function pg_temp.ws_verify_capture()',target);
  execute pg_catalog.format('create trigger ws_verify_no_truncate before truncate on %s for each statement execute function pg_temp.ws_verify_capture()',target);
end $f$;

create or replace function pg_temp.ws_verify_count(p_rel regclass) returns bigint language plpgsql
set search_path='' as $f$
declare n bigint;
begin
  select inserts-deletes into strict n from pg_temp.ws_verify_relations where rel=p_rel;
  return n;
end $f$;
create or replace function pg_temp.ws_verify_writes(p_rel regclass) returns bigint language plpgsql
set search_path='' as $f$
declare n bigint;
begin
  select inserts+updates+deletes into strict n from pg_temp.ws_verify_relations where rel=p_rel;
  return n;
end $f$;

