do $row_admission_guards$
declare
  v_result jsonb;
  v_raised text;
  v_upload uuid;
begin
  -- =======================================================================
  -- Part 1: the guards themselves, called directly.
  -- =======================================================================

  -- An empty upload breaches neither rule.
  v_result:=pg_temp.guard_seal('BRG-001',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T17:00:00',30,450,500,15500)));
  perform pg_temp.assert_true(v_result->>'status'='CURRENT',
    'a compliant NHSP backing report must still seal');
  v_upload:=(v_result->>'probe_upload_id')::uuid;

  -- Directly: the same rows against a cutoff BEFORE their finish.
  begin
    perform private.weekly_source_cutoff_admission_assert_v1(
      v_upload,'NHSP_FINAL_BACKING_V1','2026-09-14 15:00:00+00');
    v_raised:='NONE';
  exception when others then
    v_raised:=sqlerrm;
  end;
  perform pg_temp.assert_true(v_raised='WEEKLY_SOURCE_NHSP_CUTOFF_BEFORE_ACTUAL_FINISH',
    'the cutoff guard must refuse a cutoff earlier than a row Actual finish, got '||v_raised);

  -- Directly: EXACTLY equal is admitted -- the cutoff is not EARLIER.
  -- 2026-09-14 17:00 Europe/London is 16:00:00+00 (British Summer Time).
  begin
    perform private.weekly_source_cutoff_admission_assert_v1(
      v_upload,'NHSP_FINAL_BACKING_V1','2026-09-14 16:00:00+00');
    v_raised:='NONE';
  exception when others then
    v_raised:=sqlerrm;
  end;
  perform pg_temp.assert_true(v_raised='NONE',
    'a cutoff exactly equal to the Actual finish must be admitted, got '||v_raised);

  -- Directly: one second earlier refuses.  This is the British Summer Time
  -- boundary case as well: read as a naive UTC instant the row would finish at
  -- 17:00Z and pass, so a guard that skipped the zone conversion would not
  -- refuse here.
  begin
    perform private.weekly_source_cutoff_admission_assert_v1(
      v_upload,'NHSP_FINAL_BACKING_V1','2026-09-14 15:59:59+00');
    v_raised:='NONE';
  exception when others then
    v_raised:=sqlerrm;
  end;
  perform pg_temp.assert_true(v_raised='WEEKLY_SOURCE_NHSP_CUTOFF_BEFORE_ACTUAL_FINISH',
    'one second before the Actual finish must refuse, got '||v_raised);

  -- Directly: the rule is NHSP final only; another profile returns.
  begin
    perform private.weekly_source_cutoff_admission_assert_v1(
      v_upload,'HEALTHROSTER_WEEKLY_EXPLICIT_ACTUAL_V1','2026-09-01 00:00:00+00');
    v_raised:='NONE';
  exception when others then
    v_raised:=sqlerrm;
  end;
  perform pg_temp.assert_true(v_raised='NONE',
    'the cutoff rule must not fire outside NHSP_FINAL_BACKING_V1, got '||v_raised);

  -- Directly: fail closed on a missing cutoff occurrence.
  begin
    perform private.weekly_source_cutoff_admission_assert_v1(
      v_upload,'NHSP_FINAL_BACKING_V1',null);
    v_raised:='NONE';
  exception when others then
    v_raised:=sqlerrm;
  end;
  perform pg_temp.assert_true(v_raised='WEEKLY_SOURCE_NHSP_CUTOFF_OCCURRENCE_REQUIRED',
    'a missing cutoff occurrence must fail closed, got '||v_raised);

  -- Directly: a null upload id is a caller error, not a silent pass.
  begin
    perform private.weekly_source_overlap_admission_assert_v1(null);
    v_raised:='NONE';
  exception when others then
    v_raised:=sqlerrm;
  end;
  perform pg_temp.assert_true(v_raised='WEEKLY_SOURCE_OVERLAP_ASSERT_INPUT_INVALID',
    'the overlap guard must refuse a null upload id, got '||v_raised);

  -- Directly: the sealed single-row report has no overlap.
  begin
    perform private.weekly_source_overlap_admission_assert_v1(v_upload);
    v_raised:='NONE';
  exception when others then
    v_raised:=sqlerrm;
  end;
  perform pg_temp.assert_true(v_raised='NONE',
    'a one-row report must not be reported as overlapping, got '||v_raised);

  -- =======================================================================
  -- Part 2: end to end through the real seal.
  -- =======================================================================

  -- NHSP-BR-006: a row worked two days AFTER the confirmed cutoff.  Before this
  -- package this report sealed CURRENT.
  v_result:=pg_temp.guard_seal('BRG-002',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-18',
      '2026-09-18T09:00:00','2026-09-18T17:00:00',30,450,500,15500)));
  perform pg_temp.assert_true(
    v_result->>'status'='REJECTED'
    and v_result->>'reason_code'='WEEKLY_SOURCE_NHSP_CUTOFF_BEFORE_ACTUAL_FINISH',
    'the seal must refuse a row finishing after the cutoff, got '
    ||coalesce(v_result->>'status','?')||'/'||coalesce(v_result->>'reason_code','?'));
  perform pg_temp.assert_true(
    (select state from public.weekly_source_uploads
     where id=(v_result->>'probe_upload_id')::uuid)='REJECTED',
    'a refused report must not remain staging or become current');

  -- "including an overnight finish": 15 September 22:00 to 16 September 15:00
  -- Europe/London finishes at exactly 14:00:00+00, the cutoff instant itself,
  -- so it is admitted.
  v_result:=pg_temp.guard_seal('BRG-003',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-15',
      '2026-09-15T22:00:00','2026-09-16T15:00:00',60,960,500,15500)));
  perform pg_temp.assert_true(v_result->>'status'='CURRENT',
    'an overnight shift finishing exactly at the cutoff must seal, got '
    ||coalesce(v_result->>'status','?'));

  -- The same overnight shift one minute later must refuse.  These two cases
  -- differ by one minute and nothing else.
  v_result:=pg_temp.guard_seal('BRG-004',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-15',
      '2026-09-15T22:00:00','2026-09-16T15:01:00',60,961,500,15500)));
  perform pg_temp.assert_true(
    v_result->>'status'='REJECTED'
    and v_result->>'reason_code'='WEEKLY_SOURCE_NHSP_CUTOFF_BEFORE_ACTUAL_FINISH',
    'an overnight shift finishing one minute after the cutoff must refuse, got '
    ||coalesce(v_result->>'status','?')||'/'||coalesce(v_result->>'reason_code','?'));

  -- 03 section 7: two POSITIVE lines, one Candidate, one date, overlapping.
  -- Before this package this report sealed and carried GBP 340.00 of invoice
  -- authority for one shift.
  v_result:=pg_temp.guard_seal('BRG-005',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T17:00:00',0,480,500,15500),
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T18:00:00',0,540,500,17500)));
  perform pg_temp.assert_true(
    v_result->>'status'='REJECTED'
    and v_result->>'reason_code'='WEEKLY_SOURCE_OVERLAPPING_WORKED_ROWS',
    'the seal must refuse two overlapping positive lines for one person, got '
    ||coalesce(v_result->>'status','?')||'/'||coalesce(v_result->>'reason_code','?'));

  -- A £0 source charge does not mean no work.  It is the explicit rate-card
  -- warning journey and must still participate in duplicate/overlap admission.
  v_result:=pg_temp.guard_seal('BRG-011',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate Zero','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T17:00:00',0,480,0,0),
    pg_temp.guard_row('Guard Candidate Zero','2026-09-14',
      '2026-09-14T12:00:00','2026-09-14T18:00:00',0,360,0,0)));
  perform pg_temp.assert_true(
    v_result->>'status'='REJECTED'
    and v_result->>'reason_code'='WEEKLY_SOURCE_OVERLAPPING_WORKED_ROWS',
    'two overlapping £0 worked rows must refuse before Office rate acceptance, got '
    ||coalesce(v_result->>'status','?')||'/'||coalesce(v_result->>'reason_code','?'));

  -- Must still seal: an abutting split shift.  Half-open intervals.
  v_result:=pg_temp.guard_seal('BRG-006',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T13:00:00',0,240,250,7750),
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T13:00:00','2026-09-14T18:00:00',0,300,250,9750)));
  perform pg_temp.assert_true(v_result->>'status'='CURRENT',
    'an abutting split shift must still seal, got '||coalesce(v_result->>'status','?'));

  -- Must still seal: 14 section 4.2.4 -- a full reversal and the re-issue it
  -- overlaps.  This is the ordinary NHSP correction shape and the single most
  -- important thing this guard must NOT break.
  v_result:=pg_temp.guard_seal('BRG-007',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T17:00:00',0,480,-500,-15500),
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T18:00:00',0,540,500,17500)));
  perform pg_temp.assert_true(v_result->>'status'='CURRENT',
    'a full reversal and its overlapping re-issue must still seal, got '
    ||coalesce(v_result->>'status','?'));

  -- Must still seal: two DIFFERENT people on the same interval.
  v_result:=pg_temp.guard_seal('BRG-008',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T17:00:00',0,480,500,15500),
    pg_temp.guard_row('Guard Candidate Two','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T17:00:00',0,480,500,15500)));
  perform pg_temp.assert_true(v_result->>'status'='CURRENT',
    'two different people on one interval must still seal, got '
    ||coalesce(v_result->>'status','?'));

  -- Must refuse: an overlap of one minute, and an overlap that spans midnight
  -- into the next calendar date, so the rule is not secretly keyed on
  -- work_date.
  v_result:=pg_temp.guard_seal('BRG-009',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T09:00:00','2026-09-14T13:01:00',0,241,250,7750),
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T13:00:00','2026-09-14T18:00:00',0,300,250,9750)));
  perform pg_temp.assert_true(
    v_result->>'status'='REJECTED'
    and v_result->>'reason_code'='WEEKLY_SOURCE_OVERLAPPING_WORKED_ROWS',
    'a one-minute overlap must refuse, got '||coalesce(v_result->>'status','?'));

  v_result:=pg_temp.guard_seal('BRG-010',pg_catalog.jsonb_build_array(
    pg_temp.guard_row('Guard Candidate','2026-09-13',
      '2026-09-13T20:00:00','2026-09-14T04:00:00',0,480,250,7750),
    pg_temp.guard_row('Guard Candidate','2026-09-14',
      '2026-09-14T03:00:00','2026-09-14T11:00:00',0,480,250,9750)));
  perform pg_temp.assert_true(
    v_result->>'status'='REJECTED'
    and v_result->>'reason_code'='WEEKLY_SOURCE_OVERLAPPING_WORKED_ROWS',
    'an overlap across two calendar dates must refuse, got '
    ||coalesce(v_result->>'status','?')||'/'||coalesce(v_result->>'reason_code','?'));

  -- The guards decide nothing else: no Timesheet, financial, invoice or
  -- Banking Pay row exists after all of the above.
  perform pg_temp.assert_true(
    pg_temp.ws_verify_writes('public.weekly_source_billing_movements'::regclass)=0
    and pg_temp.ws_verify_writes('public.weekly_source_final_revisions'::regclass)=0,
    'the admission guards must create no financial record');
end;
$row_admission_guards$;

select pg_catalog.jsonb_build_object(
  'ok',true,
  'verification','weekly_source_row_admission_guards_v1',
  'rules',pg_catalog.jsonb_build_array('NHSP-BR-006','03 section 7 / 14 section 4.2.8'),
  'sealed_reports',(select pg_catalog.count(*) from public.weekly_source_uploads
                    where state='CURRENT' or state='SUPERSEDED'),
  'refused_reports',(select pg_catalog.count(*) from public.weekly_source_uploads
                     where state='REJECTED'),
  'financial_records',pg_temp.ws_verify_count('public.weekly_source_billing_movements'::regclass)
);

-- PHD-022 / PROT-UNAUTH-001 / PROT-ROTATION-001.
-- PostgreSQL 17.11 rollback-contained proof that both ordinary unauthorise
-- owners refuse before mutation when any physical member of a rotated
-- Timesheet family carries an invoice line, a TSFIN invoice id, or a segment
-- invoice lock. No Banking Pay or Workbench owner is defined or changed here.




set local request.jwt.claim.role='service_role';

create temporary table phd022_results(
  ordinal serial primary key,
  proof_id text not null,
  result text not null,
  detail text not null
) on commit drop;

create function pg_temp.record_result(p_proof_id text,p_ok boolean,p_detail text)
returns void language sql as $function$
  insert into phd022_results(proof_id,result,detail)
  values(p_proof_id,case when p_ok then 'PASS' else 'FAIL' end,
         pg_catalog.left(pg_catalog.replace(p_detail,'|','/'),500));
$function$;

create function pg_temp.seed_family(p_case integer,p_lock_kind text)
returns uuid language plpgsql as $function$
declare
  v_actor uuid:=md5('phd022-actor')::uuid;
  v_client uuid:=md5('phd022-client')::uuid;
  v_candidate uuid:=md5('phd022-candidate-'||p_case)::uuid;
  v_contract uuid:=md5('phd022-contract-'||p_case)::uuid;
  v_old uuid:=('70000000-0000-4000-8000-'||pg_catalog.lpad((p_case*2-1)::text,12,'0'))::uuid;
  v_current uuid:=('70000000-0000-4000-8000-'||pg_catalog.lpad((p_case*2)::text,12,'0'))::uuid;
  v_week uuid:=md5('phd022-week-'||p_case)::uuid;
  v_old_tf uuid:=md5('phd022-old-tf-'||p_case)::uuid;
  v_current_tf uuid:=md5('phd022-current-tf-'||p_case)::uuid;
  v_invoice uuid:=md5('phd022-invoice-'||p_case)::uuid;
  v_line uuid:=md5('phd022-line-'||p_case)::uuid;
  v_booking text:='PHD022-BK-'||pg_catalog.lpad(p_case::text,2,'0');
begin
  insert into public.tms_users(id,email,role,is_active,password_hash)
  values(v_actor,'phd022-office@example.test','admin',true,'not-a-login')
  on conflict(id) do nothing;
  insert into public.clients(id,name)
  values(v_client,'PHD-022 ordinary Client')
  on conflict(id) do nothing;
  insert into public.client_settings(
    id,client_id,effective_from,default_submission_mode,week_ending_weekday
  )
  select md5('phd022-client-settings')::uuid,v_client,'2026-01-01','MANUAL',0
  where not exists(
    select 1 from public.client_settings cs where cs.client_id=v_client
  );
  insert into public.candidates(id,display_name)
  values(v_candidate,'PHD-022 Candidate '||p_case);
  insert into public.contracts(
    id,candidate_id,client_id,start_date,end_date,pay_method_snapshot,rates_json,
    weekly_timesheet_source,self_bill,no_timesheet_required,requires_hr,autoprocess_hr
  ) values (
    v_contract,v_candidate,v_client,'2026-01-01','2026-12-31','PAYE','{}'::jsonb,
    'HEALTHROSTER',false,false,false,false
  );

  insert into public.timesheets(
    timesheet_id,booking_id,version,is_current,status,sheet_scope,submission_mode,
    line_type,occupant_key_norm,hospital_norm,ward_norm,job_title_norm,
    shift_label_norm,week_ending_date,contract_id,actual_schedule_json,
    qr_payload_json,is_adjustment,authorised_at_server,created_at,updated_at
  ) values
  (v_old,v_booking,1,false,'RECEIVED'::public.timesheet_status_enum,
   'WEEKLY'::public.timesheet_scope_enum,'MANUAL'::public.submission_mode_enum,
   'HOURS'::public.timesheet_line_type_enum,'phd022-'||p_case,'phd022-hospital',
   'phd022-ward','phd022-role','weekly-0','2026-09-13',v_contract,'[]'::jsonb,
   '{}'::jsonb,false,null,pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()),
  (v_current,v_booking,2,true,'RECEIVED'::public.timesheet_status_enum,
   'WEEKLY'::public.timesheet_scope_enum,'MANUAL'::public.submission_mode_enum,
   'HOURS'::public.timesheet_line_type_enum,'phd022-'||p_case,'phd022-hospital',
   'phd022-ward','phd022-role','weekly-0','2026-09-13',v_contract,'[]'::jsonb,
   '{}'::jsonb,false,pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp());

  insert into public.contract_weeks(
    id,contract_id,week_ending_date,additional_seq,status,submission_mode_snapshot,
    timesheet_id,is_adjustment
  ) values (
    v_week,v_contract,'2026-09-13',0,'AUTHORISED'::public.contract_week_status_enum,
    'MANUAL'::public.submission_mode_enum,v_current,false
  );

  insert into public.timesheets_financials(
    id,timesheet_id,timesheet_version,is_current,candidate_id,client_id,
    processing_status,total_hours,total_pay_ex_vat,total_charge_ex_vat,authorised_at_utc
  ) values
  (v_old_tf,v_old,1,false,v_candidate,v_client,
   'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum,8,100,200,
   pg_catalog.statement_timestamp()),
  (v_current_tf,v_current,2,true,v_candidate,v_client,
   'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum,8,100,200,
   pg_catalog.statement_timestamp());

  insert into public.invoices(id,client_id,status,invoice_no)
  values(v_invoice,v_client,'DRAFT'::public.invoice_status_enum,'PHD022-'||p_case);

  if p_lock_kind='LINE' then
    insert into public.invoice_lines(id,invoice_id,timesheet_id,booking_id,description)
    values(v_line,v_invoice,v_old,v_booking,'PHD-022 historical family line');
  elsif p_lock_kind='TSFIN' then
    update public.timesheets_financials
       set locked_by_invoice_id=v_invoice,
           locked_at_utc=pg_catalog.statement_timestamp()
     where id=v_old_tf;
  elsif p_lock_kind='SEGMENT' then
    update public.timesheets_financials
       set invoice_breakdown_json=pg_catalog.jsonb_build_array(
         pg_catalog.jsonb_build_object('invoice_locked_invoice_id',v_invoice::text))
     where id=v_old_tf;
  else
    raise exception 'PHD022_UNKNOWN_LOCK_KIND';
  end if;
  return v_current;
end
$function$;

create function pg_temp.prove_single(p_case integer,p_lock_kind text)
returns void language plpgsql as $function$
declare
  v_current uuid:=pg_temp.seed_family(p_case,p_lock_kind);
  v_actor uuid:=md5('phd022-actor')::uuid;
  v_refused boolean:=false;
  v_authorised timestamptz;
  v_financial_authorised timestamptz;
  v_week_status text;
begin
  begin
    perform public.timesheet_unauthorise_atomic(v_current,v_current,v_actor);
  exception when others then
    v_refused:=sqlerrm='TIMESHEET_LOCKED_BY_INVOICE';
  end;
  select ts.authorised_at_server,tf.authorised_at_utc,cw.status::text
    into v_authorised,v_financial_authorised,v_week_status
  from public.timesheets ts
  join public.timesheets_financials tf
    on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
  join public.contract_weeks cw on cw.timesheet_id=ts.timesheet_id
  where ts.timesheet_id=v_current;
  perform pg_temp.record_result(
    'PHD-022-SINGLE-'||p_lock_kind,
    v_refused and v_authorised is not null and v_financial_authorised is not null
      and v_week_status='AUTHORISED',
    'single owner refused historical '||p_lock_kind||' evidence before changing the current Timesheet, TSFIN or contract week'
  );
end
$function$;

create function pg_temp.prove_bulk(p_case integer,p_lock_kind text)
returns void language plpgsql as $function$
declare
  v_current uuid:=pg_temp.seed_family(p_case,p_lock_kind);
  v_actor uuid:=md5('phd022-actor')::uuid;
  v_result jsonb;
  v_authorised timestamptz;
  v_financial_authorised timestamptz;
  v_week_status text;
  v_ok boolean;
begin
  v_result:=public.timesheet_unauthorise_bulk_atomic(
    pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'timesheet_id',v_current,
      'expected_timesheet_id',v_current
    )),
    v_actor
  );
  select ts.authorised_at_server,tf.authorised_at_utc,cw.status::text
    into v_authorised,v_financial_authorised,v_week_status
  from public.timesheets ts
  join public.timesheets_financials tf
    on tf.timesheet_id=ts.timesheet_id and tf.is_current=true
  join public.contract_weeks cw on cw.timesheet_id=ts.timesheet_id
  where ts.timesheet_id=v_current;
  v_ok:=coalesce(v_result#>>'{results,0,error_code}','')='TIMESHEET_LOCKED_BY_INVOICE'
      and coalesce((v_result->>'success_count')::integer,-1)=0
      and coalesce((v_result->>'failure_count')::integer,-1)=1
      and v_authorised is not null and v_financial_authorised is not null
      and v_week_status='AUTHORISED';
  perform pg_temp.record_result(
    'PHD-022-BULK-'||p_lock_kind,
    v_ok,
    'bulk owner refused historical '||p_lock_kind||' evidence before changing the current Timesheet, TSFIN or contract week'
      ||case when v_ok then '' else '; result='||v_result::text end
  );
end
$function$;

select pg_temp.prove_single(1,'LINE');
select pg_temp.prove_single(2,'TSFIN');
select pg_temp.prove_single(3,'SEGMENT');
select pg_temp.prove_bulk(4,'LINE');
select pg_temp.prove_bulk(5,'TSFIN');
select pg_temp.prove_bulk(6,'SEGMENT');

do $assertions$
declare
  v_failures text;
begin
  select pg_catalog.string_agg(proof_id||':'||detail,'; ' order by ordinal)
    into v_failures
  from phd022_results
  where result<>'PASS';
  if v_failures is not null then
    raise exception 'PHD022_ORDINARY_UNAUTHORISE_FAMILY_CENSUS_FAILED: %',v_failures using errcode='55000';
  end if;
  if (select count(*) from phd022_results)<>6 then
    raise exception 'PHD022_ORDINARY_UNAUTHORISE_FAMILY_CENSUS_INCOMPLETE' using errcode='55000';
  end if;
end
$assertions$;

select 'PHD022_PROOF|'||proof_id||'|'||result||'|'||detail as line
from phd022_results
order by ordinal;

-- Read-only installed-definition/ACL check. This does not replace native journeys.

begin read only;
do $check$
declare r record; role_name text; actual integer;
begin
  for r in select p.oid,p.proname,p.prosecdef,p.proconfig,n.nspname
    from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and p.proname in (
      'weekly_source_observation_storage_v1','weekly_source_observation_begin_v1',
      'weekly_source_observation_seal_v1','weekly_source_observation_end_v1',
      'weekly_source_observe_effect_v1','weekly_source_inventory_changed_v1')
  loop
    if not r.prosecdef or not ('search_path=pg_catalog, pg_temp'=any(r.proconfig)) then
      raise exception 'SB02_HELPER_SECURITY_INVALID: %',r.proname;
    end if;
    foreach role_name in array array['anon','authenticated','service_role'] loop
      if pg_catalog.has_function_privilege(role_name,r.oid,'EXECUTE') then
        raise exception 'SB02_HELPER_CALLABLE: %, %',role_name,r.proname;
      end if;
    end loop;
    if exists(select 1 from pg_catalog.pg_proc p,
      lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a
      where p.oid=r.oid and a.grantee=0 and a.privilege_type='EXECUTE') then
      raise exception 'SB02_HELPER_PUBLIC_EXECUTE: %',r.proname;
    end if;
  end loop;
  select count(*) into actual from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and p.proname in (
      'weekly_source_observation_storage_v1','weekly_source_observation_begin_v1',
      'weekly_source_observation_seal_v1','weekly_source_observation_end_v1',
      'weekly_source_observe_effect_v1','weekly_source_inventory_changed_v1');
  if actual<>6 then raise exception 'SB02_HELPER_COUNT: %',actual; end if;
  select count(*) into actual from pg_catalog.pg_trigger t
   where (t.tgname='ws_operation_effect_capture_v1' and t.tgrelid in (
     'public.banking_pay_workbench_jobs'::regclass,'public.banking_pay_scope_change_transactions'::regclass,
     'private.banking_pay_workbench_timesheet_scope_state'::regclass,
     'private.banking_pay_workbench_candidate_scope_registry'::regclass))
     or (t.tgname='ws_inventory_changed_v1' and t.tgrelid in (
       'public.weekly_source_entitlement_heads'::regclass,'public.weekly_source_entitlement_head_components'::regclass));
  if actual<>6 then raise exception 'SB02_TRIGGER_COUNT: %',actual; end if;
  -- A name count cannot prove execution order or an enabled capture boundary.
  for r in select * from (values
    ('public.banking_pay_workbench_jobs','ws_operation_effect_capture_v1',29,'private.weekly_source_observe_effect_v1()'),
    ('public.banking_pay_scope_change_transactions','ws_operation_effect_capture_v1',29,'private.weekly_source_observe_effect_v1()'),
    ('private.banking_pay_workbench_timesheet_scope_state','ws_operation_effect_capture_v1',29,'private.weekly_source_observe_effect_v1()'),
    ('private.banking_pay_workbench_candidate_scope_registry','ws_operation_effect_capture_v1',29,'private.weekly_source_observe_effect_v1()'),
    ('public.weekly_source_entitlement_heads','ws_inventory_changed_v1',31,'private.weekly_source_inventory_changed_v1()'),
    ('public.weekly_source_entitlement_head_components','ws_inventory_changed_v1',31,'private.weekly_source_inventory_changed_v1()')
  ) expected(relation_name,trigger_name,event_bits,function_identity) loop
    if not exists(select 1 from pg_catalog.pg_trigger t
      where t.tgrelid=pg_catalog.to_regclass(r.relation_name) and t.tgname=r.trigger_name
        and t.tgfoid=pg_catalog.to_regprocedure(r.function_identity)
        and t.tgtype=r.event_bits and t.tgenabled='O'
        and not t.tgisinternal and not t.tgdeferrable and not t.tginitdeferred
        and t.tgnargs=0 and t.tgqual is null) then
      raise exception 'SB02_TRIGGER_BINDING_INVALID: %.%',r.relation_name,r.trigger_name;
    end if;
  end loop;
end;
$check$;

set local statement_timeout='15s';
do $inventory_release$
declare v_role text; v_function text; v_relation text;
begin
  if not exists(select 1 from private.weekly_source_workbench_inventory_install_v1 where singleton and complete) then
    raise exception 'SOURCE_READER_INSTALLATION_INCOMPLETE';
  end if;
  foreach v_relation in array array['weekly_source_workbench_inventory_v1','weekly_source_workbench_inventory_install_v1'] loop
    if not exists(select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
      where n.nspname='private' and c.relname=v_relation and c.relrowsecurity and c.relforcerowsecurity
      and c.relowner=(select oid from pg_catalog.pg_roles where rolname=current_user)) then
      raise exception 'SOURCE_READER_METADATA_OWNER_OR_RLS_INVALID: %',v_relation;
    end if;
    foreach v_role in array array['anon','authenticated','service_role'] loop
      if has_table_privilege(v_role,'private.'||v_relation,'SELECT,INSERT,UPDATE,DELETE') then
        raise exception 'SOURCE_READER_METADATA_DIRECT_GRANT: % %',v_relation,v_role;
